def t_write_lf_roundtrip():
    import subprocess
    proj = Path(tempfile.mkdtemp(prefix="gctl-lf-"))
    (proj / "Systems").mkdir(parents=True); (proj / "MOC").mkdir()
    (proj / "MOC" / "idx.md").write_bytes(b"---\ntype: moc\n---\n# idx\n")
