def t_help_when_no_duplicate_keys():
    """說明對照表不准有重複鍵:Python 字典後寫的會蓋掉先寫的,`lumos loop list --help` 曾印成 guard list 的說明。
    2026-10-11 世界解重新註解核對抓到;重名的子指令一律用「上層 子指令」當鍵。"""
    import ast as _ast, collections as _c
    tree = _ast.parse(Path(GRAPHCTL).read_text(encoding="utf-8"))
    dup = {}
    for n in _ast.walk(tree):
        if isinstance(n, _ast.Assign) and any(getattr(t, "id", "") == "HELP_WHEN" for t in n.targets):
            keys = [k.value for k in n.value.keys if isinstance(k, _ast.Constant)]
            dup = {k: v for k, v in _c.Counter(keys).items() if v > 1}
    check("說明表沒有重複鍵", dup == {}, str(dup))
    r = subprocess.run([sys.executable, GRAPHCTL, "loop", "list", "--help"], capture_output=True, text=True)
    check("loop list 的說明講審查編號,不是合約綁測試", "審查編號" in r.stdout and "合約綁測試" not in r.stdout, r.stdout[:300])


def t_about_code_to_rater_format():
    """★about_code 預標 → refresh_labels merge 吃的格式★(工具清單 #8)。

    merge 吃 {題:{候選:0|1|2}};about_code 預標是 {節點:[檔清單]}——r3 實測字面呼叫直接
    AttributeError。轉換:節點當「題」、檔當「候選」、列了=1、沒列=0。
    ★關鍵:候選集要是兩席的聯集★——A 列了 B 沒列的檔,B 那邊要填 0(明確判「不關於」),
    不能留空(留空 merge 會當 B 沒意見 → 進 disputed 桶當人裁,而那其實是 B 的反對票)。
    翻紅釘:候選集改成只用 A 席的 → 第 3 條翻紅(B 獨有的檔消失)。"""
    import importlib.util
    from importlib.machinery import SourceFileLoader
    spec = importlib.util.spec_from_file_location("lumos_ac", GRAPHCTL, loader=SourceFileLoader("lumos_ac", GRAPHCTL))
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    A = {"Systems/X.md": ["a.py", "b.py"], "Systems/Y.md": [], "Systems/Z.md": ["c.py"]}
    B = {"Systems/X.md": ["a.py", "d.py"], "Systems/Y.md": ["e.py"]}   # Z 沒標
    ra, rb = m.about_code_to_rater(A, B)
    check("X:A 列 a,b → a=1 b=1;B 列 a,d → d 在 A 側=0", ra["Systems/X.md"] == {"a.py": 1, "b.py": 1, "d.py": 0}, str(ra["Systems/X.md"]))
    check("X:B 側 b=0 d=1", rb["Systems/X.md"] == {"a.py": 1, "b.py": 0, "d.py": 1}, str(rb["Systems/X.md"]))
    check("★B 獨有的 d 出現在兩席(聯集)★", "d.py" in ra["Systems/X.md"] and "d.py" in rb["Systems/X.md"])
    check("Y:A 空清單、B 列 e → A 側 e=0", ra["Systems/Y.md"] == {"e.py": 0} and rb["Systems/Y.md"] == {"e.py": 1}, str(ra["Systems/Y.md"]))
    check("★Z 只有 A 標過 → B 側不出現(真的沒意見,讓 merge 判 degraded/disputed)★", "Systems/Z.md" in ra and "Systems/Z.md" not in rb, str(list(rb)))
    # 餵進真的 merge 跑一次,確認格式相容
    import json as _json, tempfile as _tf, subprocess as _sp
    from pathlib import Path as _P
    d = _P(_tf.mkdtemp(prefix="acr-"))
    (d / "a.json").write_text(_json.dumps(ra), encoding="utf-8"); (d / "b.json").write_text(_json.dumps(rb), encoding="utf-8")
    repo = _P(GRAPHCTL).resolve().parent.parent
    r = _sp.run([sys.executable, str(repo / "governance" / "eval" / "refresh_labels.py"), "merge",
                 "--a", str(d / "a.json"), "--b", str(d / "b.json"), "--json"], capture_output=True, text=True)
    check("★餵進 refresh_labels merge 不炸★", r.returncode == 0, r.stderr[-200:])
    res = _json.loads(r.stdout.strip().splitlines()[-1])
    check("merge 結果:a.py 兩席一致 → agreed", res["agreed"].get("Systems/X.md", {}).get("a.py") == 1, str(res["agreed"]))
    check("merge 結果:b.py/d.py 不一致 → disputed", set(res["disputed"].get("Systems/X.md", {})) == {"b.py", "d.py"}, str(res["disputed"]))


def t_about_code_revert_batch():
    """★整批撤銷某天的 about_code 預標★(工具清單 #7)。

    計劃的回滾路徑:批次寫入時 stamp 第一段固定 `batch-<日期>`;撤=找 stamp 第一段等於它的節點,
    逐值拿掉 about_code、整欄拿掉 stamp。★最怕誤撤人工修正過的★——那些 stamp 第一段會變成
    `claude/…`,不在 batch 範圍。r3 抓到原本寫的 `query --field` 根本不存在,所以這是新子命令。
    翻紅釘:把比對改成「stamp 含日期字串」(非第一段精確比對)→ 第 3 條翻紅(人工修正的被誤撤)。"""
    import json as _json
    v = mkvault()
    # 三篇:批次標的 / 人工修正過的(同日期但第一段不同) / 別天批次的
    write(v, "Systems/B1.md", "type: system\nstatus: done\nabout_code:\n  - scripts/lumos\n  - scripts/hooks/pre-push\nabout_code_stamp: batch-2026-08-23/2026-08-23")
    write(v, "Systems/M1.md", "type: system\nstatus: done\nabout_code:\n  - scripts/lumos\nabout_code_stamp: claude/2026-08-23")
    write(v, "Systems/B2.md", "type: system\nstatus: done\nabout_code:\n  - scripts/lumos\nabout_code_stamp: batch-2026-08-20/2026-08-20")
    write(v, "Systems/N0.md", "type: system\nstatus: done")   # 沒欄位的,不該被碰

    r = run(v, "about-code", "revert", "--batch", "2026-08-23", "--dry-run")
    check("dry-run rc0 且列出會撤的", r.returncode == 0 and "B1" in r.stdout and "M1" not in r.stdout, r.stdout[:300] + r.stderr[-200:])
    b1_before = (v / "Systems" / "B1.md").read_text(encoding="utf-8")
    check("dry-run 沒動檔案", "about_code_stamp" in b1_before)

    r2 = run(v, "about-code", "revert", "--batch", "2026-08-23")
    check("真撤 rc0", r2.returncode == 0, r2.stderr[-200:])
    b1 = (v / "Systems" / "B1.md").read_text(encoding="utf-8")
    check("★B1:about_code 與 stamp 都拿掉★", "about_code" not in b1, b1[:200])
    m1 = (v / "Systems" / "M1.md").read_text(encoding="utf-8")
    check("★M1 人工修正過的(claude/…)原封不動★", "about_code_stamp: claude/2026-08-23" in m1 and "scripts/lumos" in m1, m1[:200])
    b2 = (v / "Systems" / "B2.md").read_text(encoding="utf-8")
    check("B2 別天批次的原封不動", "batch-2026-08-20" in b2, b2[:200])
    n0 = (v / "Systems" / "N0.md").read_text(encoding="utf-8")
    check("N0 沒欄位的沒被動", n0.count("\n") <= 5, n0)
    check("輸出講了撤幾篇", "1 篇" in r2.stdout or "1 個" in r2.stdout, r2.stdout[:200])
    r3 = run(v, "about-code", "revert", "--batch", "2026-01-01")
    check("沒有該批次 → rc2 講清楚,不是靜默成功", r3.returncode == 2, f"rc={r3.returncode} {r3.stderr[-150:]}")

    # 工具清單 #2:範本加 about_code 空欄——只在 system/issue(固定席會碰的兩類,同 aliases 範圍)
    # 2026-09-10 起 append about_code 會檢查路徑要真的存在於 repo(代碼審 r1),先把那支檔放好
    _repo = Path(v).resolve().parent
    (_repo / "scripts").mkdir(exist_ok=True)
    (_repo / "scripts" / "lumos").write_text("# lumos\n", encoding="utf-8")
    for kind, sub in (("system", "Systems"), ("issue", "Issues")):
        run(v, "new", kind, f"範本{kind}")
        txt = (v / sub / f"範本{kind}.md").read_text(encoding="utf-8")
        check(f"★{kind} 範本有 about_code: []★", "about_code: []" in txt, txt[:300])
        ra = run(v, "append", f"{sub}/範本{kind}", "about_code", "scripts/lumos")
        check(f"{kind} 範本建的節點 append about_code rc0(靠 [] 修法)", ra.returncode == 0, ra.stderr[-150:])
    for kind, sub in (("project", "Projects"), ("verification", "Verification")):
        run(v, "new", kind, f"範本{kind}")
        txt = (v / sub / f"範本{kind}.md").read_text(encoding="utf-8")
        check(f"{kind} 範本★不加★about_code(範圍刀:固定席只碰 system/issue)", "about_code" not in txt, txt[:200])
    rn = run(v, "new", "system", "提示測試")
    check("NEW_HINT 提到 about_code 怎麼填", "about_code" in rn.stdout, rn.stdout[:400])


def t_about_code_revert_partial_fail():
    """★revert 單篇部分失敗不准刪 stamp、不准算成功★(about-code-impl-std r1 s3f8)。

    審查員抓到:某篇有一個值拿不掉,原碼照樣刪 stamp、照樣 done+=1——下次 revert 找不到這篇,
    殘值永遠留著,而且回報「撤成功」是假的。重現時還發現更糟:清單重複值會讓第一次 remove
    把兩個都拿掉、第二次拋 ValueError 沒人接,整個指令崩潰。
    修法:值先去重;單篇任一值失敗(含例外)→ 跳過刪 stamp、不計 done、rc 非 0、其餘篇繼續。
    翻紅釘:把「失敗就跳過刪 stamp」拿掉 → 第 2 條翻紅。"""
    v = mkvault()
    # 重複值:修前直接崩潰
    write(v, "Systems/D1.md", "type: system\nstatus: done\nabout_code:\n  - scripts/lumos\n  - scripts/lumos\nabout_code_stamp: batch-2026-08-23/2026-08-23")
    r = run(v, "about-code", "revert", "--batch", "2026-08-23")
    d1 = (v / "Systems" / "D1.md").read_text(encoding="utf-8")
    check("重複值:rc0 且欄位與 stamp 都拿掉(不崩潰)", r.returncode == 0 and "about_code" not in d1, f"rc={r.returncode} {r.stderr[-200:]}")

    # 部分失敗:直呼函式、把 cmd_remove 換成對第二個值必敗的假貨
    m = _load_lumos_module()
    write(v, "Systems/P1.md", "type: system\nstatus: done\nabout_code:\n  - a.py\n  - b.py\nabout_code_stamp: batch-2026-08-24/2026-08-24")
    write(v, "Systems/P2.md", "type: system\nstatus: done\nabout_code:\n  - c.py\nabout_code_stamp: batch-2026-08-24/2026-08-24")
    real = m.cmd_remove
    def fake(env, rel, key, value=None):
        if value == "b.py":
            raise ValueError("假裝拿不掉")
        return real(env, rel, key, value)
    m.cmd_remove = fake
    import io, contextlib
    buf, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(err):
        rc = m.cmd_about_code_revert(m.Env(v), "2026-08-24")
    m.cmd_remove = real
    p1 = (v / "Systems" / "P1.md").read_text(encoding="utf-8")
    p2 = (v / "Systems" / "P2.md").read_text(encoding="utf-8")
    check("★部分失敗那篇:stamp 留著(下次還找得到)★", "about_code_stamp: batch-2026-08-24" in p1, p1[:200])
    check("部分失敗那篇:不崩潰,rc 非 0", rc != 0, f"rc={rc} {err.getvalue()[-200:]}")
    check("其餘篇照撤", "about_code" not in p2, p2[:200])
    check("輸出講清楚撤了 1 篇、1 篇失敗", "1 篇" in buf.getvalue() and ("失敗" in buf.getvalue() or "失敗" in err.getvalue()), buf.getvalue()[-200:] + err.getvalue()[-200:])


def t_note_body_hash_and_restamp():
    """★正文雜湊過期守衛 + restamp 語意★(about-code-impl-std r2/r3 折入:工具清單 #11)。

    三輪設計審的結論:過期判準用日期/commit 數表達不了「標記在同日序列的哪一格」(83 篇首日就誤判 2 篇),
    改記正文 sha256 前 12 碼當 stamp 第三段。restamp = 「人核過標籤仍對」→ 三段全換 claude/<今天>/<雜湊>,
    離開 batch- 後 revert --batch 不再撤它(合約候選 #4);沒有批次模式(Codex r3:一口氣洗白=橡皮章)。
    翻紅釘:①把 utf-8-sig 改回 utf-8 → BOM 條翻紅 ②restamp 不換第一段 → revert 條翻紅。"""
    m = _load_lumos_module()
    v = mkvault()
    write(v, "Systems/H1.md", "type: system\nstatus: done\nabout_code:\n  - scripts/lumos\nabout_code_stamp: batch-2026-08-23/2026-08-23", body="# H1\n\n正文。\n")
    h1 = m.note_body_hash(v, "Systems/H1.md")
    check("雜湊 12 碼 hex", isinstance(h1, str) and len(h1) == 12 and all(c in "0123456789abcdef" for c in h1), repr(h1))
    run(v, "set", "Systems/H1", "updated", "2026-08-24"); run(v, "append", "Systems/H1", "about_code", "scripts/x.py")
    check("★只改 frontmatter 雜湊不變★", m.note_body_hash(v, "Systems/H1.md") == h1)
    (v / "Systems" / "H1.md").write_text((v / "Systems" / "H1.md").read_text(encoding="utf-8") + "多一行\n", encoding="utf-8")
    check("正文改一字雜湊變", m.note_body_hash(v, "Systems/H1.md") != h1)
    # BOM 檔:必須用 utf-8-sig 讀,否則 frontmatter 切不出、整檔算進雜湊
    bom_body = "# B\n\n內容\n"
    (v / "Systems" / "B1.md").write_bytes(("\ufeff---\ntype: system\nstatus: done\n---\n" + bom_body).encode("utf-8"))
    (v / "Systems" / "B2.md").write_text("---\ntype: system\nstatus: done\nupdated: 2026-01-01\n---\n" + bom_body, encoding="utf-8")
    check("★BOM 檔與無 BOM 檔同正文 → 同雜湊(utf-8-sig)★", m.note_body_hash(v, "Systems/B1.md") == m.note_body_hash(v, "Systems/B2.md"))
    check("無 frontmatter 檔也能算(防呆分支,不崩)", isinstance(m.note_body_hash(v, "Systems/B1.md"), str))
    check("檔不存在 → None 不崩", m.note_body_hash(v, "Systems/nope.md") is None)

    # restamp:三段全換、第一段離開 batch-
    write(v, "Systems/R1.md", "type: system\nstatus: done\nabout_code:\n  - scripts/lumos\nabout_code_stamp: batch-2026-08-23/2026-08-23", body="# R1\n正文\n")
    r = run(v, "about-code", "restamp", "Systems/R1")
    check("restamp rc0", r.returncode == 0, r.stderr[-200:])
    st = m.Env(v).notes["Systems/R1.md"].fields.get("about_code_stamp")
    parts = str(st).split("/")
    check("★三段式、第一段 claude、第三段=現在正文雜湊★", len(parts) == 3 and parts[0] == "claude" and parts[2] == m.note_body_hash(v, "Systems/R1.md"), str(st))
    r2 = run(v, "about-code", "restamp", "Systems/R1", "--by", "enzo")
    check("--by 改第一段", "enzo/" in (v / "Systems" / "R1.md").read_text(encoding="utf-8"), r2.stderr[-100:])
    rv = run(v, "about-code", "revert", "--batch", "2026-08-23")
    check("★restamp 過的不被 revert --batch 撤(合約候選 #4)★", "scripts/lumos" in (v / "Systems" / "R1.md").read_text(encoding="utf-8"), rv.stdout[-200:] + rv.stderr[-200:])
    # 沒有 stamp 的新節點第一次也用同一指令
    write(v, "Systems/N1.md", "type: system\nstatus: done\nabout_code:\n  - a.py", body="# N1\n")
    r3 = run(v, "about-code", "restamp", "Systems/N1")
    check("無 stamp 節點 restamp 建三段", r3.returncode == 0 and "claude/" in (v / "Systems" / "N1.md").read_text(encoding="utf-8"), r3.stderr[-150:])
    write(v, "Systems/N2.md", "type: system\nstatus: done", body="# N2\n")
    r4 = run(v, "about-code", "restamp", "Systems/N2")
    check("沒有 about_code 的節點 restamp 擋下 rc2(沒東西可核)", r4.returncode == 2, f"rc={r4.returncode} {r4.stderr[-150:]}")
    r5 = run(v, "about-code", "restamp", "--expired")
    check("★沒有 --expired 批次模式(橡皮章)★", r5.returncode != 0, r5.stderr[-150:])
    # code-loop r1 s1f2:--by 不准以 batch- 開頭,否則重標完又回到 revert --batch 的命名空間、之後被整批撤
    r6 = run(v, "about-code", "restamp", "Systems/R1", "--by", "batch-2026-08-23")
    check("★--by batch-* 擋下 rc2(會被 revert 誤撤)★", r6.returncode == 2 and "batch-" in r6.stderr, f"rc={r6.returncode} {r6.stderr[-150:]}")
    r7 = run(v, "about-code", "restamp", "Systems/不存在")
    check("找不到節點:訊息回顯使用者打的名字,不印 None", r7.returncode == 2 and "不存在" in r7.stderr and "None" not in r7.stderr, r7.stderr[-150:])


def t_about_code_migrate_stamp():
    """★83 篇存量遷移:用標註當時 commit 的正文算雜湊,不用現在的★(Codex r3 f2 blocker:現在正文=橡皮章)。

    migrate-stamp --at <commit>:對 batch-* 兩段式節點,git show <commit>:<path> 取當時正文算第三段,
    第一、二段不動。標完之後改過正文的,寫入後自然跟現在雜湊對不上 → doctor 列給人核。
    翻紅釘:把 git show 換成讀現在的檔 → 「改過的那篇第三段≠現在雜湊」翻紅。"""
    import subprocess as _sp, tempfile as _tf, os as _os
    from pathlib import Path as _P
    m = _load_lumos_module()
    root = _P(_tf.mkdtemp(prefix="mig-")); _sp.run(["git", "init", "-q", str(root)], check=True)
    kg = root / "docs" / "k" / "Systems"; kg.mkdir(parents=True)
    genv = {**_os.environ, "GIT_COMMITTER_DATE": "2026-08-23T22:00:00", "GIT_AUTHOR_DATE": "2026-08-23T22:00:00"}
    def commit(msg):
        _sp.run(["git", "add", "-A"], cwd=str(root), check=True)
        _sp.run(["git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", msg, "--no-verify"], cwd=str(root), check=True, env=genv)
    fm = "---\ntype: system\nstatus: done\nabout_code:\n  - scripts/lumos\nabout_code_stamp: batch-2026-08-23/2026-08-23\n---\n"
    (kg / "未改.md").write_text(fm + "# 未改\n舊正文\n", encoding="utf-8")
    (kg / "有改.md").write_text(fm + "# 有改\n舊正文\n", encoding="utf-8")
    (kg / "人工.md").write_text(fm.replace("batch-2026-08-23", "claude") + "# 人工\n", encoding="utf-8")
    commit("label time")
    at = _sp.run(["git", "rev-parse", "HEAD"], cwd=str(root), capture_output=True, text=True).stdout.strip()
    old_hash_changed = m.note_body_hash(root / "docs" / "k", "Systems/有改.md")
    (kg / "有改.md").write_text(fm + "# 有改\n新正文\n", encoding="utf-8")   # 標完之後改了(未 commit)
    r = _sp.run([sys.executable, GRAPHCTL, "--vault", str(root / "docs" / "k"), "about-code", "migrate-stamp", "--at", at, "--repo", str(root)], capture_output=True, text=True)
    check("migrate rc0", r.returncode == 0, r.stderr[-300:])
    env = m.Env(root / "docs" / "k")
    s_un = str(env.notes["Systems/未改.md"].fields.get("about_code_stamp")).split("/")
    s_ch = str(env.notes["Systems/有改.md"].fields.get("about_code_stamp")).split("/")
    check("未改:第三段=現在雜湊", len(s_un) == 3 and s_un[2] == m.note_body_hash(root / "docs" / "k", "Systems/未改.md"), "/".join(s_un))
    check("★有改:第三段=標註當時雜湊,≠現在雜湊(之後 doctor 會列它)★", len(s_ch) == 3 and s_ch[2] == old_hash_changed and s_ch[2] != m.note_body_hash(root / "docs" / "k", "Systems/有改.md"), "/".join(s_ch))
    check("第一、二段不動(仍是 batch)", s_un[0] == "batch-2026-08-23" and s_un[1] == "2026-08-23", "/".join(s_un))
    check("人工修正過的(claude/)不動", str(env.notes["Systems/人工.md"].fields.get("about_code_stamp")) == "claude/2026-08-23", str(env.notes["Systems/人工.md"].fields.get("about_code_stamp")))
    r2 = _sp.run([sys.executable, GRAPHCTL, "--vault", str(root / "docs" / "k"), "about-code", "migrate-stamp", "--at", at, "--repo", str(root)], capture_output=True, text=True)
    check("再跑一次:已三段式的跳過,rc0 冪等", r2.returncode == 0 and "0 篇" in r2.stdout, r2.stdout[-200:])


def _about_impact_fixture(prefix="gctl-about-"):
    """#4 專用 fixture:git repo + 三篇 pinned(兩合約 direct + 一事故)+ 一篇 free(indirect)+ 一篇有 about 欄不含目標。
    ★cmd_impact 不吃 --vault,靠 --repo/cwd 找 vault★(std-r3 s2f1)——一律 cwd=root 跑。"""
    import subprocess as sp
    root = Path(tempfile.mkdtemp(prefix=prefix))
    def g(*a): sp.run(["git", "-C", str(root), *a], capture_output=True, text=True)
    g("init", "-q"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
    v = root / "docs" / "z-knowledge"
    for d in ("Systems", "Issues", "MOC"): (v / d).mkdir(parents=True)
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    def note(rel, fm, body):
        (v / rel).write_text("---\n" + fm + "\n---\n" + body, encoding="utf-8")
    # 兩篇含合約 direct:A 有 about 命中,B 沒 about 欄;名字讓 B 原序在前(A 要靠 about 才排前)
    note("Systems/A-about.md", "type: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ A [test:X]\nabout_code:\n  - src/svc.py\nabout_code_stamp: claude/2026-08-24/PLACEHOLDER", "# A\n實作在 `src/svc.py`。\n")
    note("Systems/0-B-plain.md", "type: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ B [test:Y]", "# B\n`src/svc.py` 也在這。\n")
    # 有欄但不含目標(事故類,靠事故路徑保送)
    note("Issues/SQL注入.md", "type: issue\nstatus: open\npitfall_when:\n  - \"content:SELECT.*FROM\"\nabout_code:\n  - src/other.py\nabout_code_stamp: claude/2026-08-24/PLACEHOLDER\nsummary: |-\n  FLAG:TECHNICAL", "# SQL\n坑。\n")
    # free(無合約 direct):about 命中也不該升固定席
    note("Systems/Free.md", "type: system\nstatus: done\nsummary: |-\n  KEY:普通\nabout_code:\n  - src/svc.py\nabout_code_stamp: claude/2026-08-24/PLACEHOLDER", "# Free\n提到 `src/svc.py`。\n")
    (root / "src").mkdir(); (root / "src" / "svc.py").write_text("def save(x):\n    pass\n", encoding="utf-8")
    # 把 PLACEHOLDER 換成真雜湊
    m = _load_lumos_module()
    for rel in ("Systems/A-about.md", "Issues/SQL注入.md", "Systems/Free.md"):
        pth = v / rel; txt = pth.read_text(encoding="utf-8")
        pth.write_text(txt.replace("PLACEHOLDER", m.note_body_hash(v, rel)), encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "init")
    return root, v


def t_impact_about_hit():
    """★#4:impact 讀 about_code——只加分不降級、排前排、事故永遠最前、過期不信、總開關、巨檔門檻★
    (about-code-impl-std 三輪折入版;計劃 Projects/固定席扇出降權_計劃)。
    翻紅釘:拿掉 stable sort → ①「排在非事故 pins 首位」翻紅。
    ★2026-09-12 起這一段只驗「家那條旋鈕關掉」時的舊行為★(推筆記認家 [S2][S7][S9]):
    旋鈕開著時舊的「關於命中」整段不跑,改由「確認過的家」保送——旋鈕開著的行為在本函式尾段另外驗。"""
    import subprocess as sp, json, os as _os
    root, v = _about_impact_fixture()
    def lum(*a, env_extra=None, stdin=None):
        e = {**_os.environ, "LUMOS_IMPACT_HOME": "0", **(env_extra or {})}
        r = sp.run([sys.executable, GRAPHCTL, *a], capture_output=True, text=True, cwd=root, input=stdin, env=e)
        return r, (json.loads(r.stdout.strip().splitlines()[-1]) if r.returncode == 0 and r.stdout.strip() else None)
    payload = json.dumps({"query": "def save(x): q='SELECT id FROM t'", "prospective": {"src/svc.py": "def save(x):\n    q='SELECT id FROM t'\n"}})
    r, d = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload)
    check("rc0", r.returncode == 0, r.stderr[-300:])
    pins = [x for x in d["results"] if x.get("pinned")]
    names = [x["node"] for x in pins]
    a = next((x for x in pins if "A-about" in x["node"]), None)
    check("①A(合約 direct,about 命中)仍 pinned 且 about_hit", a is not None and a.get("about_hit") is True, str(pins)[:300])
    inc_idx = [i for i, x in enumerate(pins) if x["kind"] == "incident"]
    non_inc = [x for x in pins if x["kind"] != "incident"]
    check("★⑩事故 pin 永遠在最前(即使不帶 about)★", inc_idx == list(range(len(inc_idx))), str(names))
    check("★①A 排在非事故 pins 首位(B 原序在前但沒 about)★", non_inc and "A-about" in non_inc[0]["node"], str(names))
    check("⑦direct 候選既有 hit 欄沒被蓋掉", a.get("hit") in ("body-inline-code", "basename-match"), str(a))
    sql = next((x for x in pins if "SQL" in x["node"]), None)
    check("有欄不含目標(事故)→ 仍 pinned、無 about_hit 鍵", sql is not None and "about_hit" not in sql, str(sql))
    free = next((x for x in d["results"] if "Free" in x["node"]), None)
    check("★⑨free 候選 about 命中 → 仍 free(不是第四條入口)★", free is not None and not free.get("pinned"), str(free))
    # ②③⑧ knob=0:無 about_hit 鍵,pinned 判定逐 byte 相同,pins 序列=原序(B 在 A 前)
    r0, d0 = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload, env_extra={"LUMOS_IMPACT_ABOUT": "0"})
    check("⑧knob=0 → 任一項無 about_hit 鍵", all("about_hit" not in x for x in d0["results"]), str(d0["results"])[:200])
    strip = lambda rs: [{k: v for k, v in x.items() if k != "about_hit"} for x in rs]
    check("★②pinned 判定與 knob=0 逐 byte 相同(只差排序與鍵)★", sorted(json.dumps(x, sort_keys=True) for x in strip(d["results"])) == sorted(json.dumps(x, sort_keys=True) for x in d0["results"]), "")
    p0 = [x["node"] for x in d0["results"] if x.get("pinned") and x["kind"] != "incident"]
    check("⑧knob=0 pins 序列=三軸原序(B 在 A 前)", p0 and "0-B-plain" in p0[0], str(p0))
    # ④過期:正文改一字(不 commit)→ 視同無欄
    pa = v / "Systems" / "A-about.md"; pa.write_text(pa.read_text(encoding="utf-8") + "改了\n", encoding="utf-8")
    r4, d4 = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload)
    a4 = next(x for x in d4["results"] if "A-about" in x["node"])
    check("★④正文改一字(未 commit)→ 過期,無 about_hit、仍 pinned★", "about_hit" not in a4 and a4.get("pinned"), str(a4))
    # ⑬ 只改 frontmatter → 不過期(先把正文還原)
    pa.write_text(pa.read_text(encoding="utf-8").replace("改了\n", ""), encoding="utf-8")
    sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "set", "Systems/A-about", "updated", "2026-08-24"], capture_output=True)
    r13, d13 = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload)
    check("⑬只改 frontmatter → 仍 about_hit", next(x for x in d13["results"] if "A-about" in x["node"]).get("about_hit") is True, "")
    # ★旋鈕開著(預設)★:換成家那條——兩篇的正文都用反引號寫了 src/svc.py,都是確認過的家
    rh, dh = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload,
                 env_extra={"LUMOS_IMPACT_HOME": "1"})
    byh = {x["node"]: x for x in dh["results"]}
    free_h = next(x for k, x in byh.items() if "Free" in k)
    check("★旋鈕開著:確認過的家升成必推(這正是舊制刻意不做、本案翻案的那條)★",
          free_h.get("pinned") and free_h.get("home"), str(free_h))
    check("旋鈕開著:舊的 about 命中鍵整段不出現", all("about_hit" not in x for x in dh["results"]), str(dh["results"])[:200])
    pins_h = [x for x in dh["results"] if x["pinned"]]
    inc_h = [i for i, x in enumerate(pins_h) if x["kind"] == "incident"]
    check("旋鈕開著:事故仍永遠最前", inc_h == list(range(len(inc_h))), str([x["node"] for x in pins_h]))
    non_inc_h = [x for x in pins_h if x["kind"] != "incident"]
    check("旋鈕開著:家排在非事故必推項的最前面", non_inc_h and non_inc_h[0].get("home"), str([x["node"] for x in non_inc_h]))
    # ④b 舊格式(兩段)→ 視同無欄
    sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "set", "Systems/A-about", "about_code_stamp", "batch-2026-08-23/2026-08-23"], capture_output=True)
    _, d4b = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload)
    check("④b stamp 無第三段 → 無 about_hit", "about_hit" not in next(x for x in d4b["results"] if "A-about" in x["node"]), "")
    sp.run([sys.executable, GRAPHCTL, "about-code", "restamp", "Systems/A-about", "--repo", str(root)], capture_output=True, cwd=root)
    sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "about-code", "restamp", "Systems/A-about"], capture_output=True)
    # ⑫ --incidents-only → 無 about_hit 鍵
    _, d12 = lum("impact", "--file", "src/svc.py", "--ranked", "--incidents-only", "--stdin-payload", "--json", stdin=payload)
    check("⑫--incidents-only → 任一項無 about_hit 鍵", d12 is not None and all("about_hit" not in x for x in d12["results"]), str(d12)[:200])
    # ⑪ about_code 存成純量字串 → 仍命中
    pa.write_text(pa.read_text(encoding="utf-8").replace("about_code:\n  - src/svc.py", "about_code: src/svc.py"), encoding="utf-8")
    sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "about-code", "restamp", "Systems/A-about"], capture_output=True)
    _, d11 = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload)
    check("★⑪about_code 純量字串 → 仍命中(as_list)★", next(x for x in d11["results"] if "A-about" in x["node"]).get("about_hit") is True, str(d11["results"])[:300])
    # code-loop r1 s1f3:值寫成 ./src/svc.py 也要對得上
    pa.write_text(pa.read_text(encoding="utf-8").replace("about_code: src/svc.py", "about_code: ./src/svc.py"), encoding="utf-8")
    sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "about-code", "restamp", "Systems/A-about"], capture_output=True)
    _, d14 = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload)
    check("⑭about_code 值帶 ./ 前綴 → 仍命中", next(x for x in d14["results"] if "A-about" in x["node"]).get("about_hit") is True, "")
    # ⑮ 值寫成 src/../src/svc.py 也要對得上:排序這一側跟寫入側用同一個路徑正規化(2026-09-10 代碼審 r3 整合席)
    pa.write_text(pa.read_text(encoding="utf-8").replace("about_code: ./src/svc.py", "about_code: src/../src/svc.py"), encoding="utf-8")
    sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "about-code", "restamp", "Systems/A-about"], capture_output=True)
    _, d15 = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload)
    check("⑮about_code 值帶 ../ 繞一圈 → 仍命中", next(x for x in d15["results"] if "A-about" in x["node"]).get("about_hit") is True, "")


def t_impact_about_giant_file():
    """★⑤巨檔門檻:目標檔被 ≥ LUMOS_IMPACT_ABOUT_MAX(預設 8)篇 about 命中 → 本次關閉 about 加分★(獨立 vault,s2 要求)。"""
    import subprocess as sp, json, os as _os
    root, v = _about_impact_fixture(prefix="gctl-giant-")
    m = _load_lumos_module()
    for i in range(8):
        rel = f"Systems/G{i}.md"
        (v / rel).write_text(f"---\ntype: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ G{i} [test:G]\nabout_code:\n  - src/svc.py\nabout_code_stamp: claude/2026-08-24/x\n---\n# G{i}\n`src/svc.py`。\n", encoding="utf-8")
        txt = (v / rel).read_text(encoding="utf-8"); (v / rel).write_text(txt.replace("/x\n", "/" + m.note_body_hash(v, rel) + "\n"), encoding="utf-8")
    def lum(env=None):
        # 舊制的「about 只加分不當入口」由旋鈕關掉家之後才看得到(推筆記認家 [S9]:旋鈕開著時舊那條整段不跑)
        e = {"LUMOS_IMPACT_HOME": "0", **(env or {})}
        r = sp.run([sys.executable, GRAPHCTL, "impact", "--file", "src/svc.py", "--ranked", "--json"], capture_output=True, text=True, cwd=root, env={**_os.environ, **e})
        return json.loads(r.stdout.strip().splitlines()[-1])
    d = lum()
    check("★⑤≥8 篇命中 → 全部無 about_hit(門檻關閉)★", all("about_hit" not in x for x in d["results"]), str([x["node"] for x in d["results"] if x.get("about_hit")]))
    d2 = lum({"LUMOS_IMPACT_ABOUT_MAX": "100"})
    check("門檻調高 → 有 about_hit", any(x.get("about_hit") for x in d2["results"]), "")
    d3 = lum({"LUMOS_IMPACT_HOME": "1"})
    check("★旋鈕開著時同一道大檔門檻照樣擋:8 篇家一篇都不當入口★",
          all(x.get("kind") != "home" for x in d3["results"]),
          str([x["node"] for x in d3["results"] if x.get("kind") == "home"]))


def t_doctor_about_code_expiry():
    """★#6:doctor 另開迴圈(Check S2)列「about_code 標了之後正文又改過」的節點★——全 type、跳過作廢、
    舊格式另列、受總開關;warn_soft 不擋、不計 issues;訊息先叫人看標籤對不對,不把 restamp 當萬靈丹。
    翻紅釘:把雜湊比對改成恆 False → ①翻紅。"""
    import os as _os
    m = _load_lumos_module(); v = mkvault()
    def mk(rel, extra_fm, body, stamp_hash=True):
        write(v, rel, "type: " + ("issue" if rel.startswith("Issues") else "system") + "\nstatus: done\nabout_code:\n  - scripts/lumos\n" + extra_fm, body=body)
        if stamp_hash:
            h = m.note_body_hash(v, rel)
            run(v, "set", rel[:-3], "about_code_stamp", f"claude/2026-08-24/{h}")
    mk("Issues/改過.md", "", "# 改過\n舊\n"); (v / "Issues" / "改過.md").write_text((v / "Issues" / "改過.md").read_text(encoding="utf-8") + "新\n", encoding="utf-8")
    mk("Systems/沒改.md", "", "# 沒改\n")
    mk("Systems/只改欄位.md", "", "# 欄位\n"); run(v, "set", "Systems/只改欄位", "updated", "2026-08-25")
    mk("Systems/舊格式.md", "about_code_stamp: batch-2026-08-23/2026-08-23", "# 舊\n", stamp_hash=False)
    mk("Systems/壞雜湊.md", "about_code_stamp: claude/2026-08-24/notahexvalue", "# 壞\n", stamp_hash=False)
    mk("Systems/作廢.md", "", "# 作廢\n舊\n"); run(v, "set", "Systems/作廢", "status", "superseded"); (v / "Systems" / "作廢.md").write_text((v / "Systems" / "作廢.md").read_text(encoding="utf-8") + "新\n", encoding="utf-8")
    write(v, "Systems/無stamp.md", "type: system\nstatus: done", body="# 無\n")
    r = run(v, "doctor")
    def s2(txt):
        i = txt.find("語意「關於」標籤"); j = txt.find("\n\n", i)
        return txt[i:j if j > 0 else None]
    out = s2(r.stdout)
    check("①issue 類正文改了 → 列", "改過" in out and "標了之後正文又改過" in out, out[-800:])
    check("②沒改不列", "沒改.md" not in out, "")
    check("③無 stamp 不列", "無stamp" not in out, "")
    check("④⑦舊格式/壞雜湊 → 列為舊格式", "舊格式.md" in out and "壞雜湊.md" in out and "舊格式" in out, out[-600:])
    check("⑤只改 frontmatter → 不列", "只改欄位" not in out, "")
    check("⑨作廢節點不列", "作廢.md" not in out, "")
    check("訊息先叫人看標籤、提 restamp", "還對不對" in out and "restamp" in out, out[-600:])
    check("不計 issues(doctor rc0)", r.returncode == 0, f"rc={r.returncode}")
    import subprocess as _sp
    r0 = _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "doctor"], capture_output=True, text=True, env={**_os.environ, "LUMOS_IMPACT_ABOUT": "0"})
    check("⑥knob=0 → 整段略過、不列", "改過.md" not in s2(r0.stdout) and "總開關" in s2(r0.stdout), s2(r0.stdout)[-400:])


def t_loop_disposal_zero_findings():
    """★零發現的乾淨輪,處置閘要能過★(2026-08-24 code-out-top3 實踩:record 說「沒發現別帶處置選項」、
    disposal 閘又要求「無處置帳 ✗」——兩邊打架,乾淨輪永遠過不了。手冊語意=「每個發現都有去向即過」,
    零發現視同全處置(vacuous),這是閘漏了 findings=0 分支的 bug 不是語意變更。
    翻紅釘:把空輪分支拿掉 → 第 2 條翻紅。
    編號帶 code- 前綴(2026-09-09):條款綁定閘當日生效後,設計審拿 .patch 當審材會被那一步擋(這裡審的是空輪語意不是條款),code 迴圈那一步跳過。"""
    import subprocess as sp, hashlib, tempfile
    v = mkvault()
    spec = Path(tempfile.mkdtemp(prefix="zf-")) / "spec.patch"
    spec.write_text("diff --git a/x b/x\n+clean\n", encoding="utf-8")
    rpt = spec.parent / "r1-s1.md"; rpt.write_text("severity: clean\n# clean\n已讀,無 finding\n", encoding="utf-8")
    sha = hashlib.sha256(spec.read_bytes()).hexdigest()
    r = run(v, "canary", "record", "none", "--loop", "code-zf-loop", "--round", "r1", "--auditor", "s1",
            "--severity", "clean", "--findings", "0", "--report", str(rpt), "--snapshot", str(spec),
            "--spec", str(spec), "--reviewed", sha, "--scope-lines", "2", "--tier", "standard")
    check("clean 輪記帳 rc0", r.returncode == 0, r.stderr[-200:])
    g = run(v, "loop", "status", "code-zf-loop", "--disposal", "--spec", str(spec), "--repo", str(v))
    check("★零發現輪處置閘 PASS(vacuous:沒有發現=每個發現都有去向)★", g.returncode == 0 and "PASS" in g.stdout, g.stdout[-300:] + g.stderr[-200:])
    check("訊息講明是零發現空輪", "0 條發現" in g.stdout or "零發現" in g.stdout or "無發現" in g.stdout, g.stdout[-300:])
    # r1 blocker 折入:空輪不准跳過留痕重驗;橫幅不准宣稱沒做的「引句全錨定」
    check("★空輪仍跑全席留痕重驗★", "留痕: ✓" in g.stdout, g.stdout[-400:])
    check("★空輪橫幅不宣稱引句全錨定(沒驗的不寫)★", "引句全錨定" not in g.stdout and ("引句" in g.stdout), g.stdout[-300:])
    import shutil as _sh
    hid = spec.parent / "hidden"; _sh.move(str(rpt), str(hid))
    g3 = run(v, "loop", "status", "code-zf-loop", "--disposal", "--spec", str(spec), "--repo", str(v))
    _sh.move(str(hid), str(rpt))
    check("★空輪留痕檔被刪 → FAIL(不是免驗通行證)★", g3.returncode != 0 and "留痕" in g3.stdout, g3.stdout[-300:])
    # r1 f2:帳上 findings 手改成壞值 → fail-closed rc2,不 traceback
    lp = v.parent / ".canary-log.jsonl"
    check("前置:找得到帳本", lp.exists(), str(lp))
    orig = lp.read_text(encoding="utf-8")
    lp.write_text(orig.replace('"findings": 0', '"findings": "x"', 1), encoding="utf-8")
    g4 = run(v, "loop", "status", "code-zf-loop", "--disposal", "--spec", str(spec), "--repo", str(v))
    lp.write_text(orig, encoding="utf-8")
    check("★findings 壞值 → rc2 擋下、不 traceback★", g4.returncode == 2 and "Traceback" not in g4.stderr and ("壞" in g4.stderr or "手改" in g4.stderr or "格式" in g4.stderr), f"rc={g4.returncode} {g4.stderr[-250:]}")
    # 反向:有發現卻沒處置帳,仍要 FAIL(不能被空輪分支放水)
    rpt2 = spec.parent / "r1-s1b.md"; rpt2.write_text("severity: major\nseverity: major\n甲\nseverity: major\n乙\n", encoding="utf-8")
    r2 = run(v, "canary", "record", "none", "--loop", "code-zf-loop2", "--round", "r1", "--auditor", "s1",
             "--severity", "major", "--findings", "2", "--report", str(rpt2), "--snapshot", str(spec),
             "--spec", str(spec), "--reviewed", sha, "--scope-lines", "2", "--tier", "standard")
    g2 = run(v, "loop", "status", "code-zf-loop2", "--disposal", "--spec", str(spec), "--repo", str(v))
    check("★有發現沒處置帳 → 照樣 FAIL★", g2.returncode != 0 and "FAIL" in g2.stdout, g2.stdout[-200:])


def _hardpin_fixture(prefix="gctl-hp-"):
    """pin-denoise-a-v4 fixture:目標檔 src/svc.py;三種 indirect 鄰居(INVARIANT/RISK·守衛面/無合約)
    +一個 direct 合約+一個事故。indirect 靠「hub 筆記提到檔案、鄰居 wikilink hub」構圖(hop1)。"""
    import subprocess as sp
    root = Path(tempfile.mkdtemp(prefix=prefix))
    def g(*a): sp.run(["git", "-C", str(root), *a], capture_output=True, text=True)
    g("init", "-q"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
    v = root / "docs" / "z-knowledge"
    for d in ("Systems", "Issues", "MOC"): (v / d).mkdir(parents=True)
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    def note(rel, fm, body):
        (v / rel).write_text("---\n" + fm + "\n---\n" + body, encoding="utf-8")
    note("Systems/Hub.md", "type: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ hub [test:X]", "# Hub\n實作在 `src/svc.py`。\n")
    note("Systems/Inv1.md", "type: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ inv [test:Y]", "# Inv1\n[[Systems/Hub]]\n")
    note("Systems/Irr1.md", "type: system\nstatus: done\nsummary: |-\n  KEY:★IRREVERSIBLE★ irr [test:Z]", "# Irr1\n[[Systems/Hub]]\n")
    note("Systems/Risk1.md", "type: system\nstatus: done\ntags:\n  - risk/守衛面\nsummary: |-\n  KEY:守衛", "# Risk1\n[[Systems/Hub]]\n")
    note("Systems/Risk2.md", "type: system\nstatus: done\ntags:\n  - risk/守衛面\nsummary: |-\n  KEY:守衛二", "# Risk2\n[[Systems/Hub]]\n")
    note("Systems/Plain.md", "type: system\nstatus: done\nsummary: |-\n  KEY:普通", "# Plain\n[[Systems/Hub]]\n")
    note("Issues/事故.md", "type: issue\nstatus: open\npitfall_when:\n  - \"content:DANGER\"\nsummary: |-\n  FLAG:TECHNICAL", "# 事故\n坑。\n")
    (root / "src").mkdir(); (root / "src" / "svc.py").write_text("def save(x):\n    pass\n", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "init")
    return root, v


def t_impact_hard_pin_lane():
    """★pin-denoise-a-v4:硬合約保送+參考道★(計劃 Projects/固定席降噪A層_計劃,四輪設計審收斂版)。
    預設(2026-08-24 考卷轉正=1):indirect hop≤1 只有 INVARIANT/IRREVERSIBLE 保送;RISK 類降入 JSON 獨立頂層鍵 lane
    (不進 results),score=R 公式、cap LUMOS_IMPACT_LANE_N、meta lane/lane_truncated。knob=0 逃生:輸出與舊制逐 byte 同、無 lane 鍵。
    翻紅釘:拿掉 lane 收集 → ③翻紅。"""
    import subprocess as sp, json, os as _os
    root, v = _hardpin_fixture()
    def lum(env_extra=None, *extra):
        r = sp.run([sys.executable, GRAPHCTL, "impact", "--file", "src/svc.py", "--ranked", "--json", *extra],
                   capture_output=True, text=True, cwd=root, env={**_os.environ, **(env_extra or {})})
        return r, json.loads(r.stdout.strip().splitlines()[-1])
    r0, d0 = lum({"LUMOS_IMPACT_HARD_PIN": "0"})   # 逃生臂(2026-08-24 轉正後預設=1)
    check("①knob=0 逃生:無 lane 鍵(條件鍵兩態)、行為=舊制", "lane" not in d0, str(list(d0)))
    risk_pinned0 = [x for x in d0["results"] if "Risk" in x["node"] and x.get("pinned")]
    check("前置:舊制 RISK indirect 是固定席", len(risk_pinned0) == 2, str(d0["results"])[:300])
    r1, d1 = lum()   # 預設臂=硬合約保送開
    check("②knob=1:RISK 類不再 pinned、不在 results", all("Risk" not in x["node"] for x in d1["results"] if x.get("pinned")) and all("Risk" not in x["node"] for x in d1["results"]), str([x["node"] for x in d1["results"]]))
    check("③★被降者在 JSON 頂層 lane 鍵★", "lane" in d1 and {x["node"] for x in d1["lane"]} == {"Systems/Risk1.md", "Systems/Risk2.md"}, str(d1.get("lane")))
    check("④INVARIANT+IRREVERSIBLE indirect 仍保送;事故不受影響", any("Inv1" in x["node"] and x.get("pinned") for x in d1["results"]) and any("Irr1" in x["node"] and x.get("pinned") for x in d1["results"]), str([x["node"] for x in d1["results"] if x.get("pinned")]))
    check("lane 項欄位:lane 標記/pinned False/kind 保留 indirect/score 是 R 公式非 0.70", all(x.get("lane") == "soft-guard" and x.get("pinned") is False and x.get("kind") == "indirect" and x.get("score") != 0.7 for x in d1["lane"]), str(d1["lane"]))
    check("meta 計數", d1["meta"].get("lane") == 2 and d1["meta"].get("lane_truncated") == 0, str(d1["meta"]))
    # free 集不動:knob=0/1 的 results 逐 byte 同(除 RISK pinned 項移除外——直接比 free 部分)
    free0 = [x for x in d0["results"] if not x.get("pinned")]
    free1 = [x for x in d1["results"] if not x.get("pinned")]
    check("⑤free 集合與排序完全不動(逐 byte)", json.dumps(free0, sort_keys=True) == json.dumps(free1, sort_keys=True), "")
    # cap
    r2, d2 = lum({"LUMOS_IMPACT_HARD_PIN": "1", "LUMOS_IMPACT_LANE_N": "1"})
    check("⑥cap=1:lane 1 條、lane_truncated=1;JSON=同一份(無另一口徑)", len(d2["lane"]) == 1 and d2["meta"]["lane_truncated"] == 1, str(d2["meta"]))
    # ⑭ lane 集 ⊆ 改前 pinned 集(降級不生新候選——消融閘安全論證的機械釘)
    pinned0 = {x["node"] for x in d0["results"] if x.get("pinned")}
    check("★⑭lane ⊆ 改前 pinned(不生新未標候選)★", {x["node"] for x in d1["lane"]} <= pinned0, str(pinned0))
    # 人讀分支不炸
    r3 = sp.run([sys.executable, GRAPHCTL, "impact", "--file", "src/svc.py", "--ranked"], capture_output=True, text=True, cwd=root, env={**_os.environ, "LUMOS_IMPACT_HARD_PIN": "1"})
    check("⑦人讀分支不 KeyError 且有守衛面參考小節", r3.returncode == 0 and "守衛面參考" in r3.stdout, r3.stdout[-300:] + r3.stderr[-200:])
    # diff 聚合不含 lane(code-r1 s1f3:工作樹要真的髒,否則 files=[] 空集恆真=假綠)
    (root / "src" / "svc.py").write_text("def save(x):\n    return x\n", encoding="utf-8")
    r4 = sp.run([sys.executable, GRAPHCTL, "impact", "--diff", "HEAD", "--json"], capture_output=True, text=True, cwd=root, env={**_os.environ, "LUMOS_IMPACT_HARD_PIN": "1"})
    d4 = json.loads(r4.stdout.strip().splitlines()[-1])
    check("⑧前置:diff 非空(防空集恆真)", d4.get("files"), str(d4)[:150])
    check("⑧--diff 聚合不含 lane 節點", d4["results"] and all("Risk" not in x.get("node", "") for x in d4["results"]), str(d4)[:200])


def t_git_last_change_dates_batch():
    """★一次 git log 拿全庫每個檔的最後改動日期★(工具清單 #5;★原為 about_code 過期判準的材料,2026-08-24 該判準改記正文雜湊後本函式暫無呼叫者,保留★)。

    design-loop about-code-field r3 實測:逐篇 `git log -1 -- <檔>` 83 次 5.3s,批次 0.22s,
    差 18 倍;且 vault 檔名幾乎全中文,不加 `-c core.quotepath=false` 輸出是八進位跳脫、對不回路徑。
    翻紅釘:①拿掉 quotepath 旗標 → 第 2 條翻紅 ②改成逐檔呼叫 → 第 4 條(呼叫次數)翻紅。"""
    import subprocess as _sp, tempfile as _tf
    from pathlib import Path as _P
    import importlib.util
    from importlib.machinery import SourceFileLoader
    spec = importlib.util.spec_from_file_location("lumos_gd", GRAPHCTL, loader=SourceFileLoader("lumos_gd", GRAPHCTL))
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)

    root = _P(_tf.mkdtemp(prefix="gd-"))
    _sp.run(["git", "init", "-q", str(root)], check=True)
    kg = root / "docs" / "x-knowledge" / "Systems"; kg.mkdir(parents=True)
    def commit(name, date):
        (kg / name).write_text(f"# {name}\n{date}\n", encoding="utf-8")   # 內容帶日期,每次 commit 都有 diff
        _sp.run(["git", "add", "-A"], cwd=str(root), check=True)
        _sp.run(["git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", name, "--no-verify"],
                cwd=str(root), check=True, env={**__import__("os").environ, "GIT_COMMITTER_DATE": f"{date}T12:00:00", "GIT_AUTHOR_DATE": f"{date}T12:00:00"})
    commit("英文.md", "2026-08-01")
    commit("中文檔名測試.md", "2026-08-10")
    commit("英文.md", "2026-08-20")          # 再改一次,日期要是最新的

    dates = m.git_last_change_dates(root, root / "docs" / "x-knowledge")
    check("回 dict", isinstance(dates, dict), type(dates).__name__)
    check("★中文檔名對得回(quotepath 旗標)★", "Systems/中文檔名測試.md" in dates, str(list(dates)[:4]))
    check("英文檔取最新一次改動日期", dates.get("Systems/英文.md") == "2026-08-20", str(dates.get("Systems/英文.md")))
    check("中文檔日期正確", dates.get("Systems/中文檔名測試.md") == "2026-08-10", str(dates.get("Systems/中文檔名測試.md")))
    # 只准呼叫 git 一次:用 PATH 上的假 git 計數
    import os as _os
    shim = _P(_tf.mkdtemp(prefix="gitshim-")); cnt = shim / "count"
    (shim / "git").write_text(f"#!/bin/sh\necho x >> {cnt}\nexec /usr/bin/git \"$@\"\n", encoding="utf-8"); (shim / "git").chmod(0o755)
    real_git = _sp.run(["which", "git"], capture_output=True, text=True).stdout.strip()
    (shim / "git").write_text(f"#!/bin/sh\necho x >> {cnt}\nexec {real_git} \"$@\"\n", encoding="utf-8")
    old = _os.environ.get("PATH", ""); _os.environ["PATH"] = f"{shim}:{old}"
    m._GIT_DATES_CACHE.clear()     # 第一次呼叫已快取;要數的是「冷呼叫幾次 git」
    try:
        m.git_last_change_dates(root, root / "docs" / "x-knowledge")
    finally:
        _os.environ["PATH"] = old
    n = len(cnt.read_text().splitlines()) if cnt.exists() else 0
    check("★整個 vault 只呼叫 git 一次(不是逐檔)★", n == 1, f"呼叫了 {n} 次")
    # git 缺席/失敗 → 回空 dict 不炸(fail-open,呼叫端退回 updated 欄位)
    nogit = _P(_tf.mkdtemp(prefix="nogit-")) / "docs" / "y-knowledge"; nogit.mkdir(parents=True)
    check("不是 git repo → 回空 dict 不炸", m.git_last_change_dates(nogit.parent.parent, nogit) == {}, "")


def t_remove_scalar_field():
    """★純量欄位可以整個拿掉★:`lumos remove <節點> <key>`(不帶 value)。

    2026-08-23 design-loop about-code-field r3 抓到:回滾要「刪 stamp」,但 cmd_set 只能覆寫、
    edit_fm_remove 對非 list 直接 raise——純量欄位沒有刪除原語,回滾最後一步是空的。
    設計:不加新子命令,remove 對純量=省略 value 即整欄拿掉(一個指令學一次)。
    ★守衛★:type/status/created 是筆記骨架,刪了 lint/doctor 全炸——硬擋 rc2。
    翻紅釘:把 cmd_remove 的純量分支拿掉 → 第 1、2 條翻紅。"""
    v = mkvault()
    write(v, "Systems/S.md", "type: system\nstatus: done\nself_audit: sonnet/2026-08-23\nregen: yes")
    r = run(v, "remove", "Systems/S", "self_audit")
    check("★純量欄省略 value → 整欄拿掉,rc0★", r.returncode == 0, r.stderr[-200:])
    txt = (v / "Systems" / "S.md").read_text(encoding="utf-8")
    check("檔案裡 self_audit 那行消失", "self_audit" not in txt, txt[:200])
    check("其他欄位原封不動", "regen: yes" in txt and "status: done" in txt, txt[:200])
    # 守衛:骨架欄位不准刪
    r2 = run(v, "remove", "Systems/S", "type")
    check("★type 不准刪,rc2★", r2.returncode == 2 and "骨架" in r2.stderr, f"rc={r2.returncode} {r2.stderr[-150:]}")
    check("擋下時檔案沒動", "type: system" in (v / "Systems" / "S.md").read_text(encoding="utf-8"))
    # 不存在的欄位
    r3 = run(v, "remove", "Systems/S", "self_audit")
    check("欄位已不在 → rc2 講清楚", r3.returncode == 2, r3.stderr[-150:])
    # list 欄位省略 value 不准(避免誤刪整個 verified_by)
    write(v, "Systems/T.md", "type: system\nstatus: done\nverified_by:\n  - \"[[Verification/x]]\"")
    r4 = run(v, "remove", "Systems/T", "verified_by")
    check("★清單欄位省略 value 不准整欄刪(要逐值),rc2★", r4.returncode == 2, r4.stderr[-150:])

    # 工具清單 #1:about_code / about_code_stamp 進白名單——append/set/remove 三條路都要通
    write(v, "Systems/A.md", "type: system\nstatus: done")
    # 2026-09-10 起 append about_code 會檢查路徑要真的存在於 repo(代碼審 r1),先把那支檔放好
    _repo = Path(v).resolve().parent
    (_repo / "scripts").mkdir(exist_ok=True)
    (_repo / "scripts" / "lumos").write_text("# lumos\n", encoding="utf-8")
    ra = run(v, "append", "Systems/A", "about_code", "scripts/lumos")
    check("about_code 進 LIST_KEYS:append rc0", ra.returncode == 0, ra.stderr[-150:])
    rs = run(v, "set", "Systems/A", "about_code_stamp", "codex/2026-08-23")
    check("about_code_stamp 進 SCALAR_KEYS:set rc0", rs.returncode == 0, rs.stderr[-150:])
    rr = run(v, "remove", "Systems/A", "about_code_stamp")
    check("about_code_stamp 可整欄拿掉(回滾路徑):rc0", rr.returncode == 0, rr.stderr[-150:])
    txt = (v / "Systems" / "A.md").read_text(encoding="utf-8")
    check("三步後:about_code 在、stamp 不在", "scripts/lumos" in txt and "about_code_stamp" not in txt, txt[:200])


def t_empty_list_bracket_is_list():
    """★`aliases: []` 必須被認成清單,不是純量★。

    2026-08-23 design-loop r3 席一順手抓到:範本寫 `aliases: []`(YAML 合法空清單),
    但 fm_structure 判 list 的規則是「冒號後是空字串」——`[]` 不是空字串 → 判 scalar →
    從範本建的節點第一次 `lumos append aliases` 必敗。全庫 15 篇在這狀態。
    翻紅釘:把 fm_structure 的 `[]` 分支拿掉 → 第 1、2 條翻紅。"""
    import importlib.util
    from importlib.machinery import SourceFileLoader
    spec = importlib.util.spec_from_file_location("lumos_el", GRAPHCTL, loader=SourceFileLoader("lumos_el", GRAPHCTL))
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    fm = ["type: system", "aliases: []", "tags:", "  - type/system"]
    kinds = {k: kind for k, s, e, kind in m.fm_structure(fm)}
    check("`aliases: []` 判成 list", kinds.get("aliases") == "list", str(kinds))
    out = m.edit_fm_append(fm, "aliases", "新別名")
    check("append 進 `[]` 成功且變成多行清單", "  - 新別名" in out and "aliases: []" not in out, str(out))
    # 反例:真的純量不能被誤判
    fm2 = ["type: system", "status: done", "self_audit: sonnet/2026-08-23"]
    k2 = {k: kind for k, s, e, kind in m.fm_structure(fm2)}
    check("★純量不受影響★", k2.get("status") == "scalar" and k2.get("self_audit") == "scalar", str(k2))
    # 非空 inline list 不在本次範圍——明確標「仍判 scalar」,免得有人以為也修了
    fm3 = ["aliases: [a, b]"]
    k3 = {k: kind for k, s, e, kind in m.fm_structure(fm3)}
    check("非空 inline list `[a, b]` 本次不處理(仍 scalar,append 會擋不會壞)", k3.get("aliases") == "scalar", str(k3))
    # 真檔 e2e:從範本建節點 → append aliases 要成功
    v = mkvault()
    r0 = run(v, "new", "system", "範本節點")
    r1 = run(v, "append", "Systems/範本節點", "aliases", "別名一")
    check("★e2e:範本建的節點 append aliases rc0★", r1.returncode == 0, r1.stderr[-200:])
    txt = (v / "Systems" / "範本節點.md").read_text(encoding="utf-8")
    check("e2e:檔案裡 aliases 變成多行清單含別名", "  - 別名一" in txt, txt[:300])


def t_per_test_timeout():
    """per-test 超時:卡住的測試要被打斷、判紅、印出名字,不能拖垮整輪。
    翻紅釘:把 run_with_timeout 改成直接 fn() → 第 2 條永遠等不到 TestTimeout。"""
    import time
    check("超時 helper: 正常跑完照回傳值", run_with_timeout(lambda: 42, 5) == 42)
    t0 = time.time()
    try:
        run_with_timeout(lambda: time.sleep(30), 1)
        check("超時 helper: 卡住的要拋 TestTimeout", False, "沒拋,等於沒有超時保護")
    except TestTimeout:
        dt = time.time() - t0
        pass   # 這條分支在這台跑不到;不印綠(印綠等於宣稱驗過)
        check("超時 helper: 真的在時限附近打斷(不是等它跑完)", dt < 5, f"實際等了 {dt:.1f}s")
    check("超時 helper: seconds<=0 = 不設限(平台退路)", run_with_timeout(lambda: 7, 0) == 7)


def t_timeout_override_names_exist():
    """★覆寫表的名字必須真的存在★:改名後覆寫靜默失效,那支回到全域上限被誤殺,
    而誤殺長得跟「真的卡死」一模一樣——是最難查的一種紅。
    翻紅釘:把 TIMEOUT_OVERRIDE 的鍵改成不存在的名字 → 這條翻紅。"""
    names = {k for k in globals() if k.startswith("t_")}
    for k in TIMEOUT_OVERRIDE:
        check(f"超時覆寫: {k} 真的是一支測試(沒被改名)", k in names,
              f"覆寫表有 {k} 但 t_ 名單裡沒有——覆寫已靜默失效")


def t_stale_status_table():
    """★狀態表過期偵測★:表格說某件事還沒做,但它指的節點已 done → context 頭部要喊。

    真實案例(2026-08-22):某調研的候選表寫「建議升優先」,它指的計劃同一天就 done 了,
    照表回報進度講反。★判準要窄★——全 vault 實測「同行有待辦詞」28 處、三分之一誤報;
    收成「表格行 + 待辦詞獨佔一格」剩 1 處真陽性。誤報的代價是變背景噪音。
    翻紅釘:把判準放寬回「同一行含待辦詞」→ 第 3、4 條反例會翻紅。"""
    v = mkvault()
    write(v, "Projects/已完成.md", "type: project\nstatus: done")
    write(v, "Projects/進行中.md", "type: project\nstatus: doing")
    write(v, "Projects/表.md", "type: project\nstatus: doing",
          "# 表\n\n"
          "| # | 狀態 | 說明 |\n|---|---|---|\n"
          "| A | 待放行 | 見 [[Projects/已完成]] |\n"
          "| B | 待裁 | 見 [[Projects/進行中]] |\n"
          "| C | 這條講的是 B 可機械未做的那型 | 見 [[Projects/已完成]] |\n\n"
          "- 散文行:某某還沒做,見 [[Projects/已完成]]\n")
    r = run(v, "context", "Projects/表")
    o = r.stdout
    check("表格說待放行、指的那篇已 done → 有喊", "已經做完了" in o, o[:400])
    check("喊的是對的那一篇", "Projects/已完成" in o, o[:400])
    check("★指向未完成的那格不喊★", o.count("已經做完了") == 1,
          f"喊了 {o.count('已經做完了')} 次,應該只有 1 次\n{o[:400]}")
    check("★待辦詞夾在長句裡不算(否則長 KEY 行全中)★", "| C |" not in o, o[:400])
    check("★散文行不算(只看表格)★", "散文行" not in o, o[:400])


def t_hooks_python_fallback():
    import pathlib
    repo = pathlib.Path(GRAPHCTL).resolve().parent.parent
    # 2026-09-29 最低 Python 3.14:不再寫死 python3||python,改內嵌「找任何版本的 python」段(先試 python3.14…、
