    r = run(v, "decision-add", "X", '含冒號: 又有 "雙引號"', "--decided", "2026-06-13")
    check("S7 決策內容含「: 」又有雙引號 → 改單引號寫得進去",
          r.returncode == 0 and "- content: '含冒號: 又有 \"雙引號\"'" in read(p), r.stderr + read(p))


