def t_guard_audit():
    # guard audit:把 [audit:模型/日期] 留痕寫回 KEY 行,保留 [test:],重審覆蓋舊留痕
    v = mkvault()
    p = write(v, "Systems/S.md",
              "type: system\nstatus: done\nsummary: |-\n"
              "  KEY:★INVARIANT★ 點數不足必須擋 [test:SomeGuard]",
              body="# S\n")
    r = run(v, "guard", "audit", "Systems/S", "點數不足", "--date", "2026-06-18")
    txt = read(p)
    check("guard audit: [audit:] 寫回 KEY 行", "[audit:sonnet/2026-06-18]" in txt, r.stdout + r.stderr)
    check("guard audit: [test:] 綁定不受影響", "[test:SomeGuard]" in txt, txt)
    # 重審(換模型/日期)→ 覆蓋,不重複留痕
    run(v, "guard", "audit", "Systems/S", "點數不足", "--date", "2026-07-01", "--model", "opus")
    txt2 = read(p)
    check("guard audit: 重審覆蓋舊留痕(新日期生效)",
          "[audit:opus/2026-07-01]" in txt2 and "2026-06-18" not in txt2, txt2)
    check("guard audit: 不累積(只一個 audit 標記)", txt2.count("[audit:") == 1, txt2)
    # 找不到子字串 → rc2
    r3 = run(v, "guard", "audit", "Systems/S", "不存在的合約")
    check("guard audit: 子字串找不到 KEY 行 → rc2", r3.returncode == 2, r3.stdout + r3.stderr)


# ── 審查收斂規則(Projects/審查收斂規則_計劃):殘留標記、第二個代理的問答留痕、索引與風險分級 ──
# 判準來源:計劃〈做法〉2–6 與驗收條款 S1–S9;預期值是手寫的固定例子(決策 d12 有 checker 行、d13 已翻案、d14 沒 checker、d15 內容空白),
# 不呼叫被測函式產生 expected。
_RC_CONTRACT = "下單不得超賣"
# 合約行的 [audit:] 日期要不早於那筆 untestable 問答的日期(代碼審 r2 G8:手冊的順序是先問答、再審計);問答日期是跑測試當天,
# 固定例子的審計日期寫在很遠的將來,保證「已照順序」;要測順序被擋的另外用 guard audit --date 改成較早的日期。
_RC_AUDIT = "sonnet/2099-01-01"
_RC_UNAUDITED = "未審的另一條規則"
_RC_PLAN_DECISIONS = (
    "decisions:\n"
    "  - content: 殘留:多節點程式內互斥屬繞過設計(反例 c1、c3);第 3 輪審計收斂 checker:sonnet/2026-10-14\n"
    "    id: d12\n    decided: 2026-10-14\n"
    "  - content: 已被翻案的殘留 checker:sonnet/2026-10-14\n"
    "    id: d13\n    decided: 2026-10-14\n    valid: false\n    superseded_by: Projects/a_計劃#d12\n    ended: 2026-10-14\n"
    "  - content: 沒寫第二個代理是誰的殘留\n"
    "    id: d14\n    decided: 2026-10-14\n"
    "  - content: \"\"\n"
    "    id: d15\n    decided: 2026-10-14\n")


_RC_GIT_ENV_DROP = ("GIT_NO_REPLACE_OBJECTS", "GIT_GRAFT_FILE", "GIT_DIFF_OPTS", "GIT_EXTERNAL_DIFF")


def _rc_git_env():
    """測試自己叫 git 用的乾淨環境:拿掉 lumos 入口會設的那幾個變數(代碼審 r5 G5)。測試經 lumos 跑時(fix-check、bound-tests)
    會繼承入口設的值,證明「替身、grafts、差異選項會生效」的前置檢查就不成立;被測的 lumos 端照樣走入口。"""
    import os as _os
    return {k: x for k, x in _os.environ.items() if k not in _RC_GIT_ENV_DROP}


def _rc_repo(tag="rc", residual_line=None, commit=True, vault="kg"):
    """git 專案(.git 在 root)+ docs/<vault> 圖譜;Systems/S 兩條合約(一條已審、一條未審),about_code=src/a.py;
    Projects/a_計劃 帶 d12 到 d15;tests/test_a.py 有 test_rc_guard。residual_line 給了就直接寫在已審那條行尾(不經指令)。
    派工鏡頭只認 docs/*-knowledge,測鏡頭的傳 vault="rc-knowledge"。"""
    import subprocess as _sp, json as _j
    root = Path(tempfile.mkdtemp(prefix=f"gctl-{tag}-"))
    g = lambda *a: _sp.run(["git", "-C", str(root), *a], capture_output=True, text=True, env=_rc_git_env())
    g("init", "-q", "-b", "main"); g("config", "user.email", "t@t"); g("config", "user.name", "t")
    (root / ".lumos").mkdir()
    (root / ".lumos" / "config.json").write_text(_j.dumps({"test_profile": "python"}), encoding="utf-8")
    (root / "src").mkdir()
    (root / "src" / "a.py").write_text("def a():\n    return 1\n", encoding="utf-8")
    (root / "src" / "b.py").write_text("def b():\n    return 2\n", encoding="utf-8")
    (root / "tests").mkdir()
    (root / "tests" / "test_a.py").write_text("def test_rc_guard():\n    assert True\n", encoding="utf-8")
    v = root / "docs" / vault
    for sub in ("Systems", "Verification", "Projects", "MOC"):
        (v / sub).mkdir(parents=True)
    (v / "MOC" / "idx.md").write_text("---\ntype: moc\n---\n# idx\n", encoding="utf-8")
    tail = f" {residual_line}" if residual_line else ""
    (v / "Systems" / "S.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n"
        f"  KEY:★INVARIANT★ {_RC_CONTRACT} [test:test_rc_guard] [audit:{_RC_AUDIT}]{tail}\n"
        f"  KEY:★INVARIANT★ {_RC_UNAUDITED} [test:test_rc_guard]\n"
        "about_code:\n  - src/a.py\n---\n# S\n", encoding="utf-8")
    (v / "Projects" / "a_計劃.md").write_text(
        "---\ntype: project\nstatus: doing\n" + _RC_PLAN_DECISIONS + "---\n# a\n", encoding="utf-8")
    if commit:
        g("add", "-A"); g("commit", "-qm", "init")
    return root, v, g


def _rc_gov(root, gate="residual-ask"):
    import json as _j
    p = root / "docs" / ".governance-log.jsonl"
    if not p.is_file():
        return []
    out = []
    for ln in p.read_text(encoding="utf-8").splitlines():
        try:
            d = _j.loads(ln)
        except ValueError:
            continue
        if isinstance(d, dict) and d.get("gate") == gate:
            out.append(d)
    return out


def _rc_ask(v, case, verdict="untestable", checker="sonnet/2026-10-14", substr=_RC_CONTRACT, reaudit=True):
    """記一筆 residual-ask;reaudit(預設)時問答成功後照手冊順序重審那條合約(guard audit,戳記照舊是 _RC_AUDIT),
    --add 才驗得過「最近一次 guard audit 事件晚於問答」(代碼審 r3 G5)。未審那條(_RC_UNAUDITED)不重審,它要維持沒有 [audit:]。
    要測順序被擋的傳 reaudit=False。"""
    r = run(v, "guard", "residual-ask", "Systems/S", substr, "--case", case, "--checker", checker, "--verdict", verdict)
    if r.returncode == 0 and reaudit and substr != _RC_UNAUDITED:
        model, date = _RC_AUDIT.split("/")
        run(v, "guard", "audit", "Systems/S", substr, "--model", model, "--date", date, expect_rc=0)
    return r


def t_guard_residual_write():
    """[審查收斂規則 S1] guard residual --add 寫標記並更新索引;每一種不合格各自回 2 不寫(理由對得上);同一個標記再寫回 0 不重複。"""
    import json as _j, shutil as _sh
    root, v, g = _rc_repo("rc-s1")
    s = v / "Systems" / "S.md"
    try:
        check("★前置★ c1 問過且判 untestable", _rc_ask(v, "c1").returncode == 0, "")
        check("★前置★ c3 問過但判 testable", _rc_ask(v, "c3", verdict="testable").returncode == 0, "")
        check("★前置★ 未審那條也問過 c1(只剩沒 [audit:] 一個理由)", _rc_ask(v, "c1", substr=_RC_UNAUDITED).returncode == 0, "")
        before = s.read_text(encoding="utf-8")
        bad = (("決策找不到", [_RC_CONTRACT, "--add", "Projects/a_計劃#d99", "--case", "c1"], "找不到"),
               ("決策已被翻案", [_RC_CONTRACT, "--add", "Projects/a_計劃#d13", "--case", "c1"], "翻案"),
               ("決策內容空白", [_RC_CONTRACT, "--add", "Projects/a_計劃#d15", "--case", "c1"], "內容是空的"),
               ("c2 沒有問過", [_RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c2"], "沒有 residual-ask"),
               ("c3 問過但判測得到", [_RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c3"], "testable"),
               ("決策內容沒有那一筆的 checker:", [_RC_CONTRACT, "--add", "Projects/a_計劃#d14", "--case", "c1"], "checker:sonnet/2026-10-14"),
               ("指標是短名", [_RC_CONTRACT, "--add", "a_計劃#d12", "--case", "c1"], "全名"),
               ("合約行還沒有 [audit:]", [_RC_UNAUDITED, "--add", "Projects/a_計劃#d12", "--case", "c1"], "[audit:]"),
               ("--add 沒帶 --case", [_RC_CONTRACT, "--add", "Projects/a_計劃#d12"], "--case"))
        for name, args, why in bad:
            r = run(v, "guard", "residual", "Systems/S", *args)
            check(f"S1 {name} → 回 2 且說明理由", r.returncode == 2 and why in r.stderr, f"rc={r.returncode} {r.stderr[-300:]}")
            check(f"S1 {name} → 筆記沒動", s.read_text(encoding="utf-8") == before, "")
        check("S1 不合格的都沒有產生索引", not (root / "governance" / "residual-index.json").exists(), "")
        r = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1")
        txt = s.read_text(encoding="utf-8")
        line = next(l for l in txt.splitlines() if _RC_CONTRACT in l)
        check("S1 合格 → 回 0、標記加在那條合約行尾", r.returncode == 0 and line.endswith(f"[audit:{_RC_AUDIT}] [residual:Projects/a_計劃#d12]"),
              f"rc={r.returncode} {r.stderr[-300:]}\n{line}")
        check("S1 另一條合約沒被動到", f"{_RC_UNAUDITED} [test:test_rc_guard]\n" in txt, txt)
        idx = _j.loads((root / "governance" / "residual-index.json").read_text(encoding="utf-8"))
        ent = idx.get("entries") or []
        check("S1 索引一筆:節點、殘留決策、about_code、測試所在的檔",
              len(ent) == 1 and ent[0].get("node") == "Systems/S" and ent[0].get("residuals") == ["Projects/a_計劃#d12"]
              and ent[0].get("about_code") == ["src/a.py"] and ent[0].get("test_files") == ["tests/test_a.py"] and ent[0].get("fp"),
              repr(idx))
        r2 = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1")
        txt2 = s.read_text(encoding="utf-8")
        check("S1 同一個標記再寫 → 回 0、說已經有了、不重複加", r2.returncode == 0 and "已經有了" in r2.stdout and txt2.count("[residual:") == 1,
              f"rc={r2.returncode} {r2.stdout[-200:]}")
        r3 = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--remove", "Projects/a_計劃#d99")
        check("S1 --remove 找不到那個標記 → 回 2", r3.returncode == 2 and s.read_text(encoding="utf-8") == txt2, r3.stderr[-200:])
        r4 = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--remove", "Projects/a_計劃#d12")
        idx2 = _j.loads((root / "governance" / "residual-index.json").read_text(encoding="utf-8"))
        check("S1 --remove → 標記拿掉、[audit:] 照留、索引清空",
              r4.returncode == 0 and "[residual:" not in s.read_text(encoding="utf-8")
              and f"[audit:{_RC_AUDIT}]" in s.read_text(encoding="utf-8") and idx2.get("entries") == [], f"{r4.stderr[-200:]} {idx2}")
        r5 = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1", "--remove", "Projects/a_計劃#d12")
        check("S1 --add 與 --remove 一起給 → 回 2", r5.returncode == 2, r5.stderr[-200:])
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_guard_audit_keeps_residual():
    """[審查收斂規則 S2] 對帶 [residual:] 的合約重跑 guard audit:只換 [audit:] 那一段,[residual:] 與其餘原文不變。"""
    import shutil as _sh
    root, v, g = _rc_repo("rc-s2", residual_line="[residual:Projects/a_計劃#d12] [residual:Projects/a_計劃#d13]")
    s = v / "Systems" / "S.md"
    try:
        old = next(l for l in s.read_text(encoding="utf-8").splitlines() if _RC_CONTRACT in l)
        check("★前置★ 現場有兩個殘留標記", old.count("[residual:") == 2, old)
        r = run(v, "guard", "audit", "Systems/S", _RC_CONTRACT, "--model", "opus", "--date", "2026-10-20")
        new = next(l for l in s.read_text(encoding="utf-8").splitlines() if _RC_CONTRACT in l)
        check("S2 重審成功、新戳記生效", r.returncode == 0 and "[audit:opus/2026-10-20]" in new and _RC_AUDIT not in new, f"{r.stderr[-200:]}\n{new}")
        check("S2 [residual:] 原樣保留(位置與內容都不變)",
              new == old.replace(f"[audit:{_RC_AUDIT}]", "[audit:opus/2026-10-20]"), f"\n舊:{old}\n新:{new}")
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_doctor_checks_residual_ref():
    """[審查收斂規則 S3] [residual:] 指到的決策事後被翻案或被刪:doctor 報錯、指出去哪一篇補或用 --remove 拿掉。"""
    import shutil as _sh
    root, v, g = _rc_repo("rc-s3", residual_line="[residual:Projects/a_計劃#d12]")
    p = v / "Projects" / "a_計劃.md"
    try:
        _rc_ask(v, "c1")   # 手寫的標記要有第二個代理的問答才合格(r1 G3:doctor 跟 --add 同一套驗法),前置才是「決策好好的」
        run(v, "guard", "residual", "--reindex", expect_rc=0)
        r0 = run(v, "doctor")
        check("★前置★ 決策好好的 → doctor 不報殘留", "[residual:Projects/a_計劃#d12]" not in r0.stdout, r0.stdout[-600:])
        p.write_text(p.read_text(encoding="utf-8").replace("    id: d12\n    decided: 2026-10-14\n",
                                                           "    id: d12\n    decided: 2026-10-14\n    valid: false\n    superseded_by: Projects/a_計劃#d14\n    ended: 2026-10-15\n"),
                     encoding="utf-8")
        r1 = run(v, "doctor")
        check("S3 被翻案 → doctor 報錯並指路", "[residual:Projects/a_計劃#d12]" in r1.stdout and "已被翻案" in r1.stdout
              and "去 Projects/a_計劃 補回那筆決策" in r1.stdout and "guard residual" in r1.stdout and "--remove" in r1.stdout, r1.stdout[-1200:])
        txt = p.read_text(encoding="utf-8")
        start = txt.index("  - content: 殘留:")
        end = txt.index("  - content: 已被翻案")
        p.write_text(txt[:start] + txt[end:], encoding="utf-8")
        r2 = run(v, "doctor")
        check("S3 被刪 → doctor 報找不到", "[residual:Projects/a_計劃#d12]" in r2.stdout and "找不到" in r2.stdout, r2.stdout[-1200:])
        check("S3 有問題時 doctor --strict 不是 0", run(v, "doctor", "--strict").returncode != 0, "")
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_inv_tag_strips_residual():
    """[審查收斂規則 S4] 帶 [residual:] 的合約行:乾淨宣稱文字、合約定位、家筆記正式行比對、guard list 都跟沒有標記時一樣。"""
    import shutil as _sh
    m = _load_lumos()
    base = f"KEY:★INVARIANT★ {_RC_CONTRACT} [test:test_rc_guard] [audit:{_RC_AUDIT}]"
    withr = base + " [residual:Projects/a_計劃#d12]"
    body = lambda l: m.INVARIANT_RE.match(l).group(1)
    check("S4 乾淨宣稱文字相同", m.strip_test_refs(body(withr))[0] == m.strip_test_refs(body(base))[0] == _RC_CONTRACT,
          repr(m.strip_test_refs(body(withr))))
    lines = ["---", "type: system", "summary: |-", "  " + withr, "---", "# S"]
    check("S4 合約定位:標記裡的字不算宣稱文字(對不到)", m._kill_find_contract(lines, 1, 4, "a_計劃#d12") == (None, "none"),
          repr(m._kill_find_contract(lines, 1, 4, "a_計劃#d12")))
    check("S4 合約定位:宣稱文字照樣對得到", m._kill_find_contract(lines, 1, 4, _RC_CONTRACT) == (3, None), "")
    check("S4 家筆記正式行比對:跟沒有標記的原句相等", m._guard_formal_line(lines, 4, _RC_CONTRACT) == 3,
          repr(m._guard_formal_line(lines, 4, _RC_CONTRACT)))
    root, v, g = _rc_repo("rc-s4", residual_line="[residual:Projects/a_計劃#d12]")
    try:
        r = run(v, "guard", "list")
        shown = [l.strip() for l in r.stdout.splitlines() if _RC_CONTRACT in l]
        check("S4 guard list 的乾淨文字跟沒有標記時一樣", shown == [_RC_CONTRACT], repr(shown))
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_dispatch_lens_badge_shows_residual():
    """[審查收斂規則 S5] 派工鏡頭:帶 [residual:] 的合約行徽章標「⚠帶殘留 N 筆」(N=不同決策數);超過 200 字、平台設定讀不到時也一樣。"""
    import json as _json, shutil as _sh
    for multi in (False, True):
        d, v = _mk_lens_bound_repo(multi=multi, residual=True)
        try:
            r = run(v, "dispatch-lens", "main..HEAD", "--repo", str(d), "--json", "--no-cache")
            data = _json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {}
            text = data.get("text", "")
            tag = "平台設定讀不到" if multi else "平台設定正常"
            eta = [l for l in text.splitlines() if "★ eta 規則" in l]   # 「beta 規則」也含 eta 規則,要帶前面的 ★
            check(f"S5 {tag}:重複的同一筆只算一次 → 帶殘留 2 筆", len(eta) == 1 and eta[0].endswith("⚠帶殘留 2 筆"), repr(eta) + text[:600])
            lng = [l for l in text.splitlines() if "omega" in l]
            check(f"S5 {tag}:超過 200 字、標記在第 200 字之後也標出來", len(lng) == 1 and lng[0].endswith("⚠帶殘留 1 筆") and "[residual:" not in lng[0],
                  repr(lng)[:400])
            plain = [l for l in text.splitlines() if "alpha 不得回傳負數" in l]
            check(f"S5 {tag}:沒標記的合約行不加殘留徽章", len(plain) == 1 and "帶殘留" not in plain[0], repr(plain))
        finally:
            _sh.rmtree(d, ignore_errors=True)


def t_pitfalls_tier_high_on_residual_index():
    """[審查收斂規則 S6] 推送範圍改到殘留索引(起點或頂端版本)列的檔 → high;同一提交拿掉標記、改名也 high;沒有索引 → 分級照舊。"""
    import json as _j, shutil as _sh
    def tier(v, root):
        r = run(v, "pitfalls", "--diff", "main..HEAD", "--no-lint", "--json", "--repo", str(root))
        try:
            return _j.loads(r.stdout)
        except ValueError:
            return {"tier": None, "tier_reason": r.stdout[-200:] + r.stderr[-200:]}
    idx = {"version": 1, "entries": [{"node": "Systems/S", "fp": "x", "residuals": ["Projects/a_計劃#d12"],
                                      "about_code": ["src/a.py"], "test_files": ["tests/test_a.py"]}]}
    roots = []
    try:
        # 沒有索引:分級照舊(改程式檔、沒命中型樣 → standard,理由不提殘留)
        root, v, g = _rc_repo("rc-s6-none"); roots.append(root)
        g("checkout", "-qb", "feat"); (root / "src" / "a.py").write_text("def a():\n    return 3\n", encoding="utf-8"); g("commit", "-qam", "x")
        d0 = tier(v, root)
        check("S6 沒有索引 → 跟現在一樣(standard、不提殘留)", d0["tier"] == "standard" and "殘留" not in d0.get("tier_reason", ""), repr(d0)[:300])

        def with_index(tag):
            root, v, g = _rc_repo(tag); roots.append(root)
            (root / "governance").mkdir()
            (root / "governance" / "residual-index.json").write_text(_j.dumps(idx, ensure_ascii=False), encoding="utf-8")
            g("add", "-A"); g("commit", "-qm", "index"); g("checkout", "-qb", "feat")
            return root, v, g
        root, v, g = with_index("rc-s6-hit")
        (root / "src" / "a.py").write_text("def a():\n    return 3\n", encoding="utf-8"); g("commit", "-qam", "x")
        d1 = tier(v, root)
        check("S6 改到 about_code 的檔 → high、理由說帶殘留", d1["tier"] == "high" and "改到帶殘留合約守的程式" in d1.get("tier_reason", ""), repr(d1)[:300])
        root, v, g = with_index("rc-s6-test")
        (root / "tests" / "test_a.py").write_text("def test_rc_guard():\n    assert 1\n", encoding="utf-8"); g("commit", "-qam", "x")
        check("S6 改到合約綁定測試所在的檔 → high", tier(v, root)["tier"] == "high", "")
        root, v, g = with_index("rc-s6-miss")
        (root / "src" / "b.py").write_text("def b():\n    return 5\n", encoding="utf-8"); g("commit", "-qam", "x")
        d2 = tier(v, root)
        check("S6 改到索引外的檔 → 不升 high", d2["tier"] == "standard", repr(d2)[:300])
        root, v, g = with_index("rc-s6-drop")
        (root / "governance" / "residual-index.json").write_text(_j.dumps({"version": 1, "entries": []}), encoding="utf-8")
        (root / "src" / "a.py").write_text("def a():\n    return 3\n", encoding="utf-8"); g("commit", "-qam", "drop + change")
        check("S6 同一提交拿掉索引裡那筆又改程式 → 起點版本照算 high", tier(v, root)["tier"] == "high", "")
        root, v, g = with_index("rc-s6-mv")
        g("mv", "src/a.py", "src/c.py"); g("commit", "-qm", "rename")
        check("S6 把那支檔改名 → high(舊路徑算改到)", tier(v, root)["tier"] == "high", "")
        root, v, g = _rc_repo("rc-s6-head"); roots.append(root)
        g("checkout", "-qb", "feat")
        (root / "governance").mkdir()
        hidx = {"version": 1, "entries": [dict(idx["entries"][0], about_code=["src/b.py"], test_files=[])]}
        (root / "governance" / "residual-index.json").write_text(_j.dumps(hidx), encoding="utf-8")
        (root / "src" / "b.py").write_text("def b():\n    return 5\n", encoding="utf-8"); g("add", "-A"); g("commit", "-qm", "add index + change")
        check("S6 這次推送才加的殘留(頂端版本)也算 → high", tier(v, root)["tier"] == "high", "")
        root, v, g = _rc_repo("rc-s6-bad"); roots.append(root)
        (root / "governance").mkdir(); (root / "governance" / "residual-index.json").write_text("{壞掉", encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "bad"); g("checkout", "-qb", "feat")
        (root / "src" / "a.py").write_text("def a():\n    return 3\n", encoding="utf-8"); g("commit", "-qam", "x")
        check("S6 索引讀不出 → 什麼都不做(standard)", tier(v, root)["tier"] == "standard", "")
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_loop_escape_residual_ref():
    """[審查收斂規則 S7] loop escape --residual-ref:記進 residual_ref;找不到/短名回 2;跟 --list、撤回、--auto 一起用回 2;escape-stats 印筆數。"""
    import json as _j
    v = _mk_escape_fixture(review=[("甲", "standard")], converged=["甲"], escapes=[_esc_row("甲", token="ESC-A", sha="s1")])
    (v / "Projects" / "a_計劃.md").write_text("---\ntype: project\nstatus: doing\n" + _RC_PLAN_DECISIONS + "---\n# a\n", encoding="utf-8")
    log = v.parent / ".escape-log.jsonl"
    base = ["loop", "escape", "甲", "--stage", "CI", "--severity", "major", "--desc", "多節點下超賣", "--sha", "abc1234"]
    before = log.read_text(encoding="utf-8")
    for name, ref in (("找不到", "Projects/a_計劃#d99"), ("已翻案", "Projects/a_計劃#d13"), ("短名", "a_計劃#d12")):
        r = run(v, *base, "--residual-ref", ref)
        check(f"S7 指到{name}的決策 → 回 2、帳不變", r.returncode == 2 and log.read_text(encoding="utf-8") == before, r.stderr[-200:])
    for name, args in (("--list", ["loop", "escape", "--list"]),
                       ("撤回", ["loop", "escape", "--withdraw", "ESC-A", "--reason", "理由夠長了", "--withdrawn-by", "t"]),
                       ("--auto", ["loop", "escape", "--auto", "--range", "a..b", "--stage", "CI", "--severity", "major", "--desc", "d"])):
        r = run(v, *args, "--residual-ref", "Projects/a_計劃#d12")
        check(f"S7 跟 {name} 一起用 → 回 2", r.returncode == 2 and log.read_text(encoding="utf-8") == before, r.stderr[-200:])
    r = run(v, *base, "--residual-ref", "Projects/a_計劃#d12")
    rec = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()][-1]
    check("S7 合格 → 回 0、residual_ref 記進帳", r.returncode == 0 and rec.get("residual_ref") == "Projects/a_計劃#d12", f"{r.stderr[-200:]} {rec}")
    st = _esc_stats(v)
    check("S7 escape-stats --json 數到 1 筆帶 residual_ref", st["totals"].get("residual_ref") == 1, repr(st["totals"]))
    r2 = run(v, "loop", "escape-stats")
    check("S7 escape-stats 印帶殘留歸因的筆數", "歸因到殘留 1 列" in r2.stdout, r2.stdout[-400:])


def t_reference_audit_q3_rules():
    """[審查收斂規則 S8] lumos-project-notes 審計五問段寫著:三種去向、分不清先當殺得掉的局部退化、第二個獨立代理與 checker:、三輪上限;不要求逐字貼。"""
    _need_src("skills/lumos-project-notes/reference.md")
    import re as _re
    ref = (Path(GRAPHCTL).resolve().parent.parent / "skills" / "lumos-project-notes" / "reference.md").read_text(encoding="utf-8")
    i = ref.index("### ★INVARIANT★ → `[audit:]` 獨立合法性審計")
    sec = ref[i:ref.index("\n### ", i + 10)]
    for k in ("局部退化,殺得掉", "局部退化,殺不掉", "繞過設計"):
        check(f"S8 寫著去向「{k}」", k in sec, "")
    check("S8 寫著分不清先當殺得掉的局部退化", _re.search(r"分不清[^。\n]{0,20}殺得掉", sec) is not None, "")
    check("S8 寫著第二個獨立代理", "第二個獨立代理" in sec and "residual-ask" in sec, "")
    check("S8 寫著 checker: 行", "checker:<" in sec or "checker:" in sec, "")
    check("S8 寫著三輪上限", _re.search(r"三輪[^。\n]{0,6}上限|上限[^。\n]{0,6}三輪", sec) is not None, "")
    check("S8 寫著編排者只能往嚴改", "往嚴" in sec, "")
    bad = [m.start() for m in _re.finditer("逐字貼", sec) if not _re.search(r"(勿|不要|別|不|不准|不必)[^。\n]{0,4}$", sec[max(0, m.start() - 8):m.start()])]
    check("S8 沒有要求派工時逐字貼(出現「逐字貼」都是否定說法)", not bad, repr([sec[max(0, b - 20):b + 10] for b in bad]))
    # r1 G5(代碼審合約席 major):第 3 問的放行條件不能寫成「已記成殘留」——記殘留要先有 [audit:],兩句互卡;
    # 放行改成「每個反例都殺掉,或經第二個代理確認測不到」,並寫明順序 問答 → 蓋 [audit:] → 記殘留決策 → guard residual --add。
    # 判準來源:r1-合約-sonnet.md Finding 1;同一句在方法論與計劃也要一致(散落同句一起改)。
    def _order_ok(text):
        for ln in text.splitlines():
            if "順序" not in ln:
                continue
            pos = [ln.find(k) for k in ("residual-ask", "guard audit", "decision-add", "guard residual <")]
            if all(p >= 0 for p in pos) and pos == sorted(pos):
                return True
        return False
    q3 = next((l for l in sec.splitlines() if "③" in l and "測試夠格" in l), "")
    check("G5 第 3 問的放行條件是「每個反例都殺掉,或經第二個代理確認測不到」", "每個反例都殺掉" in q3 and "第二個獨立代理確認測不到" in q3, q3[:300])
    check("G5 第 3 問不再要求「已記成殘留才放行」", "記成殘留(`[residual:]`)的才放行" not in q3, q3[:300])
    check("G5 手冊寫明順序:問答 → guard audit → decision-add → guard residual --add", _order_ok(sec), "")
    root_ = Path(GRAPHCTL).resolve().parent.parent
    for rel_ in ("docs/methodology/圖譜即合約.md", "docs/lumos-toolchain-knowledge/Projects/審查收斂規則_計劃.md",
                 "skills/lumos-project-notes/commands/06-代碼審與推送.md"):
        txt_ = (root_ / rel_).read_text(encoding="utf-8")
        check(f"G5 {rel_} 也寫同一個順序", _order_ok(txt_), "")
    # r2 G8(代碼審合約席):06 手冊與 design-loop 講第 3 問的 KEY 行也要同一個順序;手冊說寫入時驗的是 [audit:] 日期不早於問答,不是只驗存在
    dl_ = (root_ / "docs/lumos-toolchain-knowledge/Systems/design-loop.md").read_text(encoding="utf-8")
    kl_ = "\n".join(l for l in dl_.splitlines() if l.strip().startswith("KEY:") and "第 3 問" in l)
    check("G8 design-loop 講第 3 問的 KEY 行寫同一個順序", _order_ok(kl_), kl_[:300])
    ord_ = next((l for l in sec.splitlines() if "**記殘留**" in l), "")
    check("G8 手冊說第 ④ 步驗最近一次 guard audit 晚於問答(r3 G5:比治理帳事件、不比戳記日期)",
          "最近一次 `guard audit` 晚於" in ord_ and "找不到審計紀錄" in ord_ and "不早於" not in ord_ and "驗前三步都做了" not in ord_, ord_[:300])
    # r3 G1:「只准問一次」是方便不是保證,把關在新增殘留的推送要過高風險代碼審——手冊、06、方法論、計劃都要這樣講
    for rel_ in ("skills/lumos-project-notes/reference.md", "skills/lumos-project-notes/commands/06-代碼審與推送.md",
                 "docs/methodology/圖譜即合約.md", "docs/lumos-toolchain-knowledge/Projects/審查收斂規則_計劃.md"):
        txt_ = (root_ / rel_).read_text(encoding="utf-8")
        check(f"r3 G1 {rel_} 寫明只准問一次是方便、把關在新增殘留的推送過高風險代碼審",
              _re.search(r"只准問一次[^。\n]{0,20}方便", txt_) is not None and "新增殘留的推送要過高風險代碼審" in txt_, "")
    # r4 G5(合約席 F4):講到這件事的每一個檔都要照實講,而且逐行看——原本只在四個檔各找「整檔任一處」符合,
    # 同檔另一行寫回「只准問一次=保證」照綠,design-loop、guard-kill、pitfalls-code-loop 與 lumos 的提示文字也沒涵蓋。
    # 規則一條:凡是提到「只准問一次」的那一行都要同時說是方便;「擋得住重問」的舊說法一處都不准留;每個檔都寫明把關在高風險代碼審。
    for rel_ in ("skills/lumos-project-notes/reference.md", "skills/lumos-project-notes/commands/06-代碼審與推送.md",
                 "docs/methodology/圖譜即合約.md", "docs/lumos-toolchain-knowledge/Projects/審查收斂規則_計劃.md",
                 "docs/lumos-toolchain-knowledge/Systems/design-loop.md", "docs/lumos-toolchain-knowledge/Systems/guard-kill.md",
                 "docs/lumos-toolchain-knowledge/Systems/pitfalls-code-loop.md", "scripts/lumos"):
        txt_ = (root_ / rel_).read_text(encoding="utf-8")
        bare_ = [ln.strip()[:80] for ln in txt_.splitlines() if "只准問一次" in ln and "方便" not in ln]
        check(f"r4 G5 {rel_} 提到只准問一次的每一行都說是方便", not bare_, repr(bare_[:3]))
        old_ = [k for k in ("不能換代理重問", "不准換人重問", "不准換代理重問") if k in txt_]
        check(f"r4 G5 {rel_} 沒有「擋得住重問」的舊說法", not old_, repr(old_))
        check(f"r4 G5 {rel_} 寫明把關在高風險代碼審", "高風險代碼審" in txt_, "")


def t_guard_residual_ask_once():
    """[審查收斂規則 S9] 同一條合約同一個反例只准問一次;問答記治理帳(residual-ask);doctor 在索引跟圖譜不一致時報錯並給 --reindex。"""
    import json as _j, shutil as _sh
    m = _load_lumos()
    check("S9 閘名 residual-ask 在 _KNOWN_GATES", "residual-ask" in m._KNOWN_GATES, "")
    root, v, g = _rc_repo("rc-s9")
    try:
        r = _rc_ask(v, "c1")
        ev = _rc_gov(root)
        check("S9 第一次問 → 回 0、記一筆帶節點、指紋、反例、checker、結論",
              r.returncode == 0 and len(ev) == 1 and ev[0].get("node") == "Systems/S" and ev[0].get("case") == "c1"
              and ev[0].get("checker") == "sonnet/2026-10-14" and ev[0].get("verdict") == "untestable" and ev[0].get("fp"), f"{r.stderr[-200:]} {ev}")
        r2 = _rc_ask(v, "c1", verdict="testable", checker="opus/2026-10-15")
        check("S9 同一反例換代理重問 → 回 2、帳上仍只有一筆", r2.returncode == 2 and "已經問過" in r2.stderr and len(_rc_gov(root)) == 1, r2.stderr[-200:])
        check("S9 別的反例照樣能問", _rc_ask(v, "c2", verdict="testable").returncode == 0 and len(_rc_gov(root)) == 2, "")
        check("S9 別條合約的同一個反例編號是另一件事", _rc_ask(v, "c1", substr=_RC_UNAUDITED).returncode == 0, "")
        check("S9 --checker 格式不對 → 回 2", _rc_ask(v, "c9", checker="sonnet").returncode == 2, "")
        run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1", expect_rc=0)
        r0 = run(v, "doctor")
        check("★前置★ 剛寫完索引 → doctor 不報索引不一致", "殘留索引" not in r0.stdout, r0.stdout[-800:])
        ip = root / "governance" / "residual-index.json"
        ip.write_text(_j.dumps({"version": 1, "entries": []}), encoding="utf-8")
        r1 = run(v, "doctor")
        check("S9 索引少了圖譜裡的殘留 → doctor 報錯並給 --reindex", "殘留索引" in r1.stdout and "guard residual --reindex" in r1.stdout, r1.stdout[-1200:])
        run(v, "guard", "residual", "--reindex", expect_rc=0)
        check("S9 --reindex 之後一致", "殘留索引" not in run(v, "doctor").stdout, "")
        d = _j.loads(ip.read_text(encoding="utf-8"))
        d["entries"][0]["about_code"] = ["src/zzz.py"]
        ip.write_text(_j.dumps(d), encoding="utf-8")
        check("S9 about_code 清單對不上 → doctor 報錯", "殘留索引" in run(v, "doctor").stdout, "")
        ip.unlink()
        check("S9 圖譜有殘留卻沒有索引 → doctor 報錯", "殘留索引" in run(v, "doctor").stdout, "")
    finally:
        _sh.rmtree(root, ignore_errors=True)


# ── 代碼審 code-審查收斂規則 r1 的修正(九組;r1-intake.md〈根因分組與處置〉)──
# 預期值都是手寫的固定例子:同一個反例的寫法變體、同一筆決策的大小寫變體、加一個句號的宣稱、索引寫不進去的現場,
# 不呼叫被測函式產生 expected。

def t_residual_identity_normalized():
    """[r1 G1] 反例編號、殘留指標、宣稱指紋各有正規形:c1/C1/c1./c-1 是同一個反例;projects/A_計劃#d12 是同一筆決策;
    宣稱加句號或空白不換合約、改了字詞就是另一條;--checker 只收半形真日期;已有同一個指標時換 --case 照驗問答。"""
    import shutil as _sh
    m = _load_lumos()
    fp = m._residual_claim_fp
    check("G1 指紋:句尾加句號、頭尾加空白、標記增減都是同一句",
          fp("下單不得超賣") == fp("下單不得超賣。") == fp(" 下單不得超賣 ") == fp("下單不得超賣 [audit:x/2026-01-01] [residual:P/a#d1]"),
          repr([fp("下單不得超賣"), fp("下單不得超賣。")]))
    check("G1 指紋:全形英數跟半形同一句(NFKC)", fp("Ａ值不得為負") == fp("A值不得為負"), "")
    check("G1 指紋:改了字詞是另一條合約(要重審)", fp("下單不得超賣") != fp("下單不得超量"), "")
    check("G1 反例編號正規形:c1、C1、c1. 同一個;c1 與 c2、c11 不同",
          len({m._residual_case_key(x) for x in ("c1", "C1", "c1.")}) == 1
          and len({m._residual_case_key(x) for x in ("c1", "c2", "c11")}) == 3, "")
    root, v, g = _rc_repo("rc-g1")
    s = v / "Systems" / "S.md"
    try:
        check("★前置★ c1 第一次問(判 testable)", _rc_ask(v, "c1", verdict="testable").returncode == 0, "")
        for var in ("C1", "c1."):
            r = _rc_ask(v, var)
            check(f"G1 同一個反例換寫法 {var} 重問 → 回 2、帳上仍只有一筆 c1", r.returncode == 2 and "已經問過" in r.stderr
                  and len(_rc_gov(root)) == 1, f"rc={r.returncode} {r.stderr[-200:]}")
        txt = s.read_text(encoding="utf-8")
        s.write_text(txt.replace(f"{_RC_CONTRACT} [test:", f"{_RC_CONTRACT}。 [test:"), encoding="utf-8")
        r = _rc_ask(v, "c1")
        check("G1 宣稱尾端加句號 → 還是同一條合約,c1 不准再問", r.returncode == 2 and "已經問過" in r.stderr, r.stderr[-200:])
        s.write_text(txt.replace(f"{_RC_CONTRACT} [test:", f"{_RC_CONTRACT}且不得負庫存 [test:"), encoding="utf-8")
        r = _rc_ask(v, "c1", verdict="untestable")
        check("G1 宣稱改了字詞 → 另一條合約,c1 問得到(改字重問交給推送分級的「新增了殘留」,r3 G1;t_pitfalls_residual_added_needs_review)",
              r.returncode == 0, r.stderr[-200:])
        check("G1 宣稱改了字詞 → 另一條合約,沒判過 testable 的 c5 可以問", _rc_ask(v, "c5", verdict="untestable").returncode == 0, "")
        s.write_text(txt, encoding="utf-8")
        for bad in ("x/２０２６-１０-１４", "sonnet/9999-99-99", "sonnet/2026-02-30", "sonnet/2026-1-4"):
            r = _rc_ask(v, "c7", checker=bad)
            check(f"G1 --checker {bad} → 回 2", r.returncode == 2 and "--checker" in r.stderr, f"rc={r.returncode} {r.stderr[-200:]}")
        check("★前置★ c2 問過判 untestable", _rc_ask(v, "c2").returncode == 0, "")
        r = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "projects/A_計劃#d12", "--case", "C2")
        line = next(l for l in s.read_text(encoding="utf-8").splitlines() if _RC_CONTRACT in l)
        check("G1 大小寫變體的指標與反例 → 寫成正式路徑", r.returncode == 0 and line.endswith("[residual:Projects/a_計劃#d12]"),
              f"rc={r.returncode} {r.stderr[-300:]}\n{line}")
        r = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c2")
        check("G1 同一筆決策換寫法再加 → 已經有了、只有一個標記",
              r.returncode == 0 and "已經有了" in r.stdout and s.read_text(encoding="utf-8").count("[residual:") == 1, r.stdout[-200:] + r.stderr[-200:])
        r = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c9")
        check("G1 已有同一個指標、這次 --case 沒問過 → 照驗、回 2(不早退)", r.returncode == 2 and "沒有 residual-ask" in r.stderr,
              f"rc={r.returncode} {r.stdout[-200:]} {r.stderr[-200:]}")
        r = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1")
        check("G1 已有同一個指標、這次 --case 判的是 testable → 回 2", r.returncode == 2 and "testable" in r.stderr, r.stderr[-200:])
        r = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--remove", "PROJECTS/a_計劃#d12")
        check("G1 --remove 用大小寫變體也拿得掉", r.returncode == 0 and "[residual:" not in s.read_text(encoding="utf-8"), r.stderr[-200:])
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_guard_residual_index_write_failure():
    """[r1 G2] 合約行寫了、索引寫不進去:講實話(合約行已寫/已拿掉、索引沒更新、跑 --reindex)、回 1、不噴堆疊;
    「已經有了」「沒有這個標記」兩條路也重建索引,所以照提示重跑就補好。"""
    import json as _j, shutil as _sh
    root, v, g = _rc_repo("rc-g2")
    s = v / "Systems" / "S.md"
    ip = root / "governance" / "residual-index.json"
    add = ("guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1")
    rm = ("guard", "residual", "Systems/S", _RC_CONTRACT, "--remove", "Projects/a_計劃#d12")
    try:
        check("★前置★ c1 判 untestable", _rc_ask(v, "c1").returncode == 0, "")
        ip.mkdir(parents=True)   # 索引位置被一個資料夾佔住
        r = run(v, *add)
        check("G2 --add 索引寫不進去 → 回 1、說合約行已寫、索引沒更新、給 --reindex",
              r.returncode == 1 and "合約行已寫" in r.stderr and "索引沒更新" in r.stderr and "guard residual --reindex" in r.stderr
              and "Traceback" not in r.stderr, f"rc={r.returncode} {r.stderr[-400:]}")
        check("★前置★ 合約行真的已經有標記", s.read_text(encoding="utf-8").count("[residual:") == 1, "")
        r = run(v, *add)
        check("G2 照樣佔住時重跑 → 已經有了、但索引還是沒更新 → 回 1", r.returncode == 1 and "索引沒更新" in r.stderr, f"rc={r.returncode} {r.stderr[-300:]}")
        ip.rmdir()
        r = run(v, *add)
        idx = _j.loads(ip.read_text(encoding="utf-8")) if ip.is_file() else {}
        check("G2 修好再跑 → 已經有了、回 0、索引補上那一筆", r.returncode == 0 and "已經有了" in r.stdout and len(idx.get("entries") or []) == 1,
              f"rc={r.returncode} {r.stderr[-300:]} {idx}")
        ip.unlink(); ip.mkdir()
        r = run(v, *rm)
        check("G2 --remove 索引寫不進去 → 回 1、說合約行已拿掉、索引沒更新", r.returncode == 1 and "合約行已拿掉" in r.stderr and "索引沒更新" in r.stderr
              and "[residual:" not in s.read_text(encoding="utf-8"), f"rc={r.returncode} {r.stderr[-300:]}")
        ip.rmdir()
        r = run(v, *rm)
        idx = _j.loads(ip.read_text(encoding="utf-8")) if ip.is_file() else None
        check("G2 修好再跑 --remove → 沒有這個標記(回 2);圖譜沒有殘留、索引也不在,本來就一致 → 不建索引檔(r2 G6)",
              r.returncode == 2 and "沒有" in r.stderr and idx is None, f"rc={r.returncode} {r.stderr[-300:]} {idx}")
        _sh.rmtree(root / "governance"); (root / "governance").write_text("佔住", encoding="utf-8")   # mkdir 丟 OSError 那一種
        r = run(v, *add)
        check("G2 governance 是一般檔(建資料夾丟 OSError)→ 回 1、不噴堆疊、說索引沒更新",
              r.returncode == 1 and "索引沒更新" in r.stderr and "Traceback" not in r.stderr, f"rc={r.returncode} {r.stderr[-400:]}")
        r = run(v, "guard", "residual", "--reindex")
        check("G2 --reindex 寫不進去 → 回 1、不噴堆疊", r.returncode == 1 and "Traceback" not in r.stderr, f"rc={r.returncode} {r.stderr[-300:]}")
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_residual_check_shared():
    """[r1 G3] --reindex、doctor 跟 --add 同一套驗法:手寫的 [residual:] 沒有問答、決策沒 checker:、合約沒 [audit:]、
    同一反例另有 testable 都要講;--reindex 照樣寫索引但回 1;doctor 也比 test_files。"""
    import json as _j, shutil as _sh
    root, v, g = _rc_repo("rc-g3", residual_line="[residual:Projects/a_計劃#d12]")
    s = v / "Systems" / "S.md"
    ip = root / "governance" / "residual-index.json"
    try:
        r = run(v, "guard", "residual", "--reindex")
        idx = _j.loads(ip.read_text(encoding="utf-8")) if ip.is_file() else {}
        check("G3 手寫的殘留沒有問答 → --reindex 回 1、說沒有判 untestable 的 residual-ask",
              r.returncode == 1 and "untestable" in (r.stdout + r.stderr) and "residual-ask" in (r.stdout + r.stderr), f"rc={r.returncode} {r.stdout[-300:]} {r.stderr[-300:]}")
        check("G3 不合格也照樣寫進索引(寧可多升 high)", len(idx.get("entries") or []) == 1, repr(idx))
        r = run(v, "doctor")
        check("G3 doctor 報那條殘留不合格", "residual-ask" in r.stdout and "Systems/S" in r.stdout and "不合格" in r.stdout, r.stdout[-1500:])
        check("★前置★ 補問 c1 判 untestable", _rc_ask(v, "c1").returncode == 0, "")
        r = run(v, "guard", "residual", "--reindex")
        check("G3 補問之後 --reindex 回 0", r.returncode == 0, f"{r.stdout[-300:]} {r.stderr[-300:]}")
        out = run(v, "doctor").stdout
        check("G3 補問之後 doctor 不報不合格", not any("殘留" in l and "不合格" in l for l in out.splitlines()), out[-1200:])
        # 舊帳裡同一反例另有 testable(正規化前寫進去的 C1)→ 不合格
        gp = root / "docs" / ".governance-log.jsonl"
        ev = [ln for ln in gp.read_text(encoding="utf-8").splitlines() if '"residual-ask"' in ln][-1]
        d = _j.loads(ev); d["case"] = "C1"; d["verdict"] = "testable"
        with gp.open("a", encoding="utf-8") as fh:
            fh.write(_j.dumps(d, ensure_ascii=False) + "\n")
        r = run(v, "guard", "residual", "--reindex")
        check("G3 同一反例另有判 testable 的問答 → 回 1", r.returncode == 1 and "testable" in r.stderr, f"rc={r.returncode} {r.stderr[-300:]}")
        gp.write_text("".join(l + "\n" for l in gp.read_text(encoding="utf-8").splitlines() if '"C1"' not in l), encoding="utf-8")
        # 決策沒有 checker:、合約沒有 [audit:]
        txt = s.read_text(encoding="utf-8")
        s.write_text(txt.replace("[residual:Projects/a_計劃#d12]", "[residual:Projects/a_計劃#d14]"), encoding="utf-8")
        r = run(v, "guard", "residual", "--reindex")
        check("G3 決策內容沒有 checker: → 回 1、說 checker:", r.returncode == 1 and "checker:" in r.stderr, f"rc={r.returncode} {r.stderr[-300:]}")
        s.write_text(txt.replace(f"{_RC_UNAUDITED} [test:test_rc_guard]", f"{_RC_UNAUDITED} [test:test_rc_guard] [residual:Projects/a_計劃#d12]"), encoding="utf-8")
        r = run(v, "guard", "residual", "--reindex")
        check("G3 合約行沒有 [audit:] → 回 1、說 [audit:]", r.returncode == 1 and "[audit:]" in r.stderr, f"rc={r.returncode} {r.stderr[-300:]}")
        s.write_text(txt, encoding="utf-8")
        check("★前置★ 回到合格", run(v, "guard", "residual", "--reindex").returncode == 0, "")
        # doctor 比 test_files:綁定測試搬到別支檔
        (root / "tests" / "test_a.py").write_text("def test_other():\n    assert True\n", encoding="utf-8")
        (root / "tests" / "test_b.py").write_text("def test_rc_guard():\n    assert True\n", encoding="utf-8")
        r = run(v, "doctor")
        check("G3 綁定測試搬到別支檔、索引沒重建 → doctor 報索引對不上", "殘留索引" in r.stdout and "guard residual --reindex" in r.stdout, r.stdout[-1200:])
        run(v, "guard", "residual", "--reindex", expect_rc=0)
        check("G3 重建後索引列的是新檔", _j.loads(ip.read_text(encoding="utf-8"))["entries"][0].get("test_files") == ["tests/test_b.py"], ip.read_text(encoding="utf-8"))
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_residual_test_files_skip_comments():
    """[r1 G3] 找綁定測試所在的檔先剝註解(跟測試方法掃描同一套):被註解掉的測試宣告不算那支檔有這個測試。"""
    import json as _j, shutil as _sh
    m = _load_lumos()
    root = Path(tempfile.mkdtemp(prefix="gctl-rc-g3c-"))
    try:
        (root / ".lumos").mkdir()
        (root / ".lumos" / "config.json").write_text(_j.dumps({"test_profile": "node-jest"}), encoding="utf-8")
        (root / "test").mkdir()
        (root / "test" / "a.test.js").write_text("test('rc_guard', () => { expect(1).toBe(1) })\n", encoding="utf-8")
        (root / "test" / "b.test.js").write_text("// test('rc_guard', () => {})\n/* test('rc_guard', () => {}) */\n", encoding="utf-8")
        body = "下單不得超賣 [test:rc_guard]"
        got = m._residual_test_files(root, [body]).get(body)
        files = got["files"] if isinstance(got, dict) else got
        check("G3 只列真的宣告了測試的那支檔(註解掉的不算)", files == ["test/a.test.js"], repr(got))
    finally:
        _sh.rmtree(root, ignore_errors=True)


def _rc_run(v, *args):
    """跑 lumos,但環境拿掉入口會設的那幾個 git 變數(_rc_git_env):攻擊測試證明的是「入口自己會設」,不靠父行程剛好帶著。"""
    return subprocess.run([sys.executable, GRAPHCTL, "--vault", str(v), *args], capture_output=True, text=True, env=_rc_git_env(), check=False)


def _rc_pitfalls_tier(v, root, rng="main..HEAD"):
    import json as _j
    r = _rc_run(v, "pitfalls", "--diff", rng, "--no-lint", "--json", "--repo", str(root))
    try:
        return _j.loads(r.stdout)
    except ValueError:
        return {"tier": None, "tier_reason": r.stdout[-200:] + r.stderr[-200:]}


def _rc_with_index(tag, idx, roots):
    import json as _j
    root, v, g = _rc_repo(tag); roots.append(root)
    (root / "governance").mkdir()
    (root / "governance" / "residual-index.json").write_text(_j.dumps(idx, ensure_ascii=False), encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "index"); g("checkout", "-qb", "feat")
    return root, v, g


def t_pitfalls_tier_high_on_residual_removed():
    """[r1 G4] 推送範圍裡拿掉殘留(起點索引有、頂端沒有)本身升 high;頂端索引讀不出而起點有殘留也升 high;理由分得出來;
    --remove 提示拿掉殘留的推送會被判高風險。"""
    import json as _j, shutil as _sh
    idx = {"version": 1, "entries": [{"node": "Systems/S", "fp": "x", "residuals": ["Projects/a_計劃#d12"],
                                      "about_code": ["src/a.py"], "test_files": [], "tests": []}]}
    roots = []
    try:
        root, v, g = _rc_with_index("rc-g4-drop", idx, roots)
        (root / "governance" / "residual-index.json").write_text(_j.dumps({"version": 1, "entries": []}), encoding="utf-8")
        g("commit", "-qam", "只拿掉殘留")
        d = _rc_pitfalls_tier(v, root)
        check("G4 只拿掉殘留、沒改程式 → high、理由說拿掉殘留", d["tier"] == "high" and "拿掉殘留" in d.get("tier_reason", ""), repr(d)[:400])
        root, v, g = _rc_with_index("rc-g4-del", idx, roots)
        g("rm", "-q", "governance/residual-index.json"); g("commit", "-qm", "刪掉索引")
        d = _rc_pitfalls_tier(v, root)
        check("G4 刪掉索引 → high、理由說拿掉殘留", d["tier"] == "high" and "拿掉殘留" in d.get("tier_reason", ""), repr(d)[:400])
        root, v, g = _rc_with_index("rc-g4-bad", idx, roots)
        (root / "governance" / "residual-index.json").write_text("{壞掉", encoding="utf-8"); g("commit", "-qam", "弄壞索引")
        d = _rc_pitfalls_tier(v, root)
        check("G4 頂端索引讀不出、起點有殘留 → high、理由說讀不出", d["tier"] == "high" and "讀不出" in d.get("tier_reason", ""), repr(d)[:400])
        root, v, g = _rc_with_index("rc-g4-shape", idx, roots)
        (root / "governance" / "residual-index.json").write_text(_j.dumps({"version": 1, "entries": {"x": 1}}), encoding="utf-8"); g("commit", "-qam", "形狀不對")
        d = _rc_pitfalls_tier(v, root)
        check("G4 頂端索引形狀不對、起點有殘留 → high", d["tier"] == "high" and "讀不出" in d.get("tier_reason", ""), repr(d)[:400])
        root, v, g = _rc_with_index("rc-g4-keep", idx, roots)
        (root / "README.md").write_text("x\n", encoding="utf-8"); g("add", "-A"); g("commit", "-qm", "doc")
        d = _rc_pitfalls_tier(v, root)
        check("G4 殘留沒動、沒改它守的檔 → 不升 high", d["tier"] != "high", repr(d)[:400])
        root, v, g = _rc_repo("rc-g4-msg"); roots.append(root)
        _rc_ask(v, "c1")
        run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1", expect_rc=0)
        r = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--remove", "Projects/a_計劃#d12")
        check("G4 --remove 提示拿掉殘留的推送會被判高風險、要過代碼審", r.returncode == 0 and "拿掉殘留的推送會被判高風險" in r.stdout
              and "代碼審" in r.stdout, r.stdout[-300:])
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_pitfalls_residual_test_file_whole():
    """[r2 G1] 綁定測試所在的檔整檔算命中(拿掉上一輪「diff 碰到綁定測試名才算」的收窄):縮排在 class 裡的測試方法
    (Kotlin、class 式 pytest)只改方法本體、或只改它呼叫的輔助函式,都要升 high;改索引外的檔照舊不升。
    判準來源:r2 正確性、邊界、通才、資安四席實測——git 的 hunk 標頭只帶頂格的那一行(class 名),增刪行不含測試名,
    收窄判成沒碰到;索引裡仍帶 tests 欄的舊索引也照整檔讀。"""
    import json as _j
    import shutil as _sh
    kt = ("class FooTest {\n    @Test\n    fun guardWorks() {\n        assertEquals(1, check())\n    }\n\n"
          "    private fun check(): Int {\n        return 1\n    }\n}\n")
    py = ("def helper_assert(x):\n    assert x == 1\n\n\nclass TestFoo:\n    def test_guard(self):\n        helper_assert(1)\n")
    idx = {"version": 1, "entries": [{"node": "Systems/S", "fp": "x", "residuals": ["Projects/a_計劃#d12"], "about_code": ["src/a.py"],
                                      "test_files": ["tests/FooTest.kt", "tests/test_c.py"], "tests": ["guardWorks", "test_guard"]}]}
    roots = []
    def prep(tag, ix):
        root, v, g = _rc_repo(tag, commit=False); roots.append(root)
        (root / "tests" / "FooTest.kt").write_text(kt, encoding="utf-8")
        (root / "tests" / "test_c.py").write_text(py, encoding="utf-8")
        (root / "governance").mkdir()
        (root / "governance" / "residual-index.json").write_text(_j.dumps(ix, ensure_ascii=False), encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "init"); g("checkout", "-qb", "feat")
        return root, v, g
    try:
        cases = (("Kotlin 只改縮排測試方法的本體", "tests/FooTest.kt", kt, "assertEquals(1, check())", "assertEquals(9, check())"),
                 ("Kotlin 只改它呼叫的輔助函式", "tests/FooTest.kt", kt, "return 1", "return 2"),
                 ("class 式 pytest 只改縮排測試方法的本體", "tests/test_c.py", py, "helper_assert(1)", "helper_assert(1) or True"),
                 ("class 式 pytest 只改它呼叫的輔助函式", "tests/test_c.py", py, "assert x == 1", "assert True"))
        for i, (name, rel, src, old, new_) in enumerate(cases):
            root, v, g = prep(f"rc-r2g1-{i}", idx)
            (root / rel).write_text(src.replace(old, new_), encoding="utf-8"); g("commit", "-qam", "weaken")
            hd = subprocess.run(["git", "-C", str(root), "diff", "-U0", "main..HEAD", "--", rel], capture_output=True, text=True, check=False).stdout
            check(f"★前置★ {name}:diff 的增刪行與 hunk 標頭都不含測試名(情境成立)", "guardWorks" not in hd and "test_guard" not in hd, hd[-300:])
            d = _rc_pitfalls_tier(v, root)
            check(f"G1 {name} → high、理由說改到帶殘留合約守的程式", d["tier"] == "high" and "改到帶殘留合約守的程式" in d.get("tier_reason", ""), repr(d)[:400])
        root, v, g = prep("rc-r2g1-miss", idx)
        (root / "src" / "b.py").write_text("def b():\n    return 5\n", encoding="utf-8"); g("commit", "-qam", "x")
        check("G1 改索引外的檔 → 不升 high(整檔算只擴到索引列的檔)", _rc_pitfalls_tier(v, root)["tier"] != "high", "")
        root, v, g = prep("rc-r2g1-del", idx)
        g("rm", "-q", "tests/test_c.py"); g("commit", "-qm", "x")
        check("G1 刪掉那支測試檔 → high", _rc_pitfalls_tier(v, root)["tier"] == "high", "")
        old_ix = {"version": 1, "entries": [{k: x for k, x in idx["entries"][0].items() if k != "tests"}]}
        root, v, g = prep("rc-r2g1-old", old_ix)
        (root / "tests" / "test_c.py").write_text(py.replace("assert x == 1", "assert True"), encoding="utf-8"); g("commit", "-qam", "x")
        check("G1 沒有 tests 欄的索引也整檔命中(high)", _rc_pitfalls_tier(v, root)["tier"] == "high", "")
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_contracts_shows_residual():
    """[r1 G7] lumos contracts 對帶殘留的合約印「⚠帶殘留 N 筆」(跟 guard list 同一個寫法);沒帶的不印。"""
    import shutil as _sh
    root, v, _g = _rc_repo("rc-g7", residual_line="[residual:Projects/a_計劃#d12] [residual:Projects/a_計劃#d13]")
    try:
        r = run(v, "contracts", "Systems/S")
        blk = r.stdout.split("★INVARIANT★")
        mine = [b for b in blk if _RC_CONTRACT in b]
        other = [b for b in blk if _RC_UNAUDITED in b]
        check("G7 帶殘留的合約印 ⚠帶殘留 2 筆", len(mine) == 1 and "⚠帶殘留 2 筆" in mine[0], r.stdout[-600:])
        check("G7 沒帶殘留的合約不印", len(other) == 1 and "帶殘留" not in other[0], r.stdout[-600:])
        gl = run(v, "guard", "list").stdout
        check("G7 跟 guard list 的寫法一樣", "⚠帶殘留 2 筆" in gl, gl[-400:])
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_residual_decision_shared_resolve():
    """[r1 G9] 殘留決策的節點解析跟 _pq_decision_state 同一份:只差大小寫的兩篇並存、指標又兩篇都不完全相符 → 判不出(不取第一篇)。"""
    import shutil as _sh
    m = _load_lumos()
    root, v, g = _rc_repo("rc-g9", commit=False)
    try:
        env = m.Env(v)
        env.notes["projects/A_計劃.md"] = env.notes["Projects/a_計劃.md"]   # 模擬只差大小寫的第二篇(檔案系統可能不分大小寫,直接塞進記憶體)
        check("★前置★ _pq_decision_state 判撞名", m._pq_decision_state(env, "Systems/S.md", "PROJECTS/a_計劃#d12") == "bad", "")
        check("G9 _residual_decision 撞名時也判不出(回 None)", m._residual_decision(env, "PROJECTS/a_計劃#d12") is None,
              repr(m._residual_decision(env, "PROJECTS/a_計劃#d12")))
        check("G9 完全相符那篇照樣拿得到決策", (m._residual_decision(env, "Projects/a_計劃#d12") or {}).get("id") == "d12", "")
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_guard_audit_and_kill_add_share_contract_locate():
    """[r1 G9] 結構:guard audit、kill-add、guard residual 的「節點 → 讀檔 → 定位合約行」走同一支 _contract_locate,不各寫一份樣板
    (守的是三個指令的擋下訊息與定位規則不分岔;行為由 t_guard_audit*、t_kill_add*、t_guard_residual_write 各自驗)。"""
    import inspect as _in
    m = _load_lumos()
    for fn in ("_cmd_guard_audit_locked", "_guard_kill_add_locked", "_cmd_guard_residual_locked", "cmd_guard_residual_ask"):
        src = _in.getsource(getattr(m, fn))
        check(f"G9 {fn} 用 _contract_locate、不自己呼叫 _kill_find_contract", "_contract_locate(" in src and "_kill_find_contract(" not in src, "")
    import shutil as _sh
    root, v, g = _rc_repo("rc-g9b")
    try:
        for args in (("guard", "audit", "Systems/S", "不存在的合約"),
                     ("guard", "residual-ask", "Systems/S", "不存在的合約", "--case", "c1", "--checker", "sonnet/2026-10-14", "--verdict", "untestable")):
            r = run(v, *args)
            check(f"G9 {args[1]} 找不到合約行 → 回 2、同一句擋下訊息", r.returncode == 2 and "找不到內容含『不存在的合約』的合約 KEY 行" in r.stderr, r.stderr[-200:])
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_residual_graph_key_lines():
    """[r1 G6] 圖譜 KEY 行跟上:pitfalls-code-loop 講分級的那條 KEY 行寫到殘留升 high;design-loop 講五問、講防應試化的兩條 KEY 行寫到第 3 問的殘留。"""
    kg = Path(GRAPHCTL).resolve().parent.parent / "docs" / "lumos-toolchain-knowledge" / "Systems"
    pc = (kg / "pitfalls-code-loop.md").read_text(encoding="utf-8").splitlines()
    tier = [l for l in pc if l.strip().startswith("KEY:") and "_pitfall_tier" in l]
    check("G6 pitfalls-code-loop 分級 KEY 行寫到殘留升 high", len(tier) == 1 and "殘留" in tier[0] and "拿掉殘留" in tier[0], repr(tier)[:300])
    dl = (kg / "design-loop.md").read_text(encoding="utf-8").splitlines()
    five = [l for l in dl if l.strip().startswith("KEY:") and "五問 rubric" in l]
    anti = [l for l in dl if l.strip().startswith("KEY:") and "防應試化" in l]
    check("G6 design-loop 五問 KEY 行寫到第 3 問三種去向與殘留", len(five) == 1 and "殘留" in five[0] and "第 3 問" in five[0], repr(five)[:300])
    check("G6 design-loop 防應試化 KEY 行寫到抽考把帶殘留通過當不合格", len(anti) == 1 and "帶殘留通過" in anti[0], repr(anti)[:300])


# ── 代碼審 code-審查收斂規則 r2 的修正(九組;r2-intake.md〈根因分組與處置〉)──
# 預期值都是手寫的固定例子(席報告實測的撞例、手寫的索引與治理帳列),不呼叫被測函式產生 expected。

def t_residual_identity_keeps_meaningful_punct():
    """[r2 G2] 正規化只抹掉不帶意思的差異:反例編號連續的非字母數字合成一個 -(c1.1 = c1-1 ≠ c11、a-bc ≠ ab-c);
    宣稱指紋只壓空白、去頭尾空白與句尾標點,句中的小數點、負號、斜線、括號照留(1.5 倍 ≠ 15 倍、-1 ≠ 1、a/b ≠ ab、v1.2 ≠ v12、(a) ≠ a)。
    判準來源:r2 正確性、邊界兩席列的撞例。"""
    import shutil as _sh
    m = _load_lumos()
    ck, fp = m._residual_case_key, m._residual_claim_fp
    for a, b in (("c1", "C1"), ("c1", "c1."), ("c1.1", "c1-1"), ("c1.1", "c1..1"), ("Ｃ１", "c1"), ("-c1-", "c1")):
        check(f"G2 反例編號 {a} 與 {b} 是同一個", ck(a) == ck(b), f"{ck(a)!r} {ck(b)!r}")
    for a, b in (("c1.1", "c11"), ("a-bc", "ab-c"), ("c1", "c11"), ("c1-2", "c12")):
        check(f"G2 反例編號 {a} 與 {b} 不同", ck(a) != ck(b), f"{ck(a)!r} {ck(b)!r}")
    for a, b in (("上限 1.5 倍", "上限 1.5 倍。"), ("上限 1.5 倍", " 上限 1.5 倍 "), ("上限 1.5 倍", "上限  1.5 倍"),
                 ("回傳 -1", "回傳 -1;"), ("回傳 -1", "回傳 -1；"), ("回傳 -1", "回傳 -1!?"), ("回傳 -1", "回傳 -1,。")):
        check(f"G2 宣稱「{a}」與「{b}」是同一句", fp(a) == fp(b), "")
    for a, b in (("上限 1.5 倍", "上限 15 倍"), ("回傳 -1", "回傳 1"), ("a/b 不得為空", "ab 不得為空"), ("v1.2", "v12"),
                 ("(a)", "a"), ("(a 或 b) 且 c", "a 或 (b 且 c)"), ("rc 0.5", "rc 05")):
        check(f"G2 宣稱「{a}」與「{b}」是不同的合約", fp(a) != fp(b), "")
    root, v, _g = _rc_repo("rc-r2g2")
    s = v / "Systems" / "S.md"
    try:
        check("★前置★ c1.1 問過判 untestable", _rc_ask(v, "c1.1").returncode == 0, "")
        r = _rc_ask(v, "c1-1")
        check("G2 c1-1 跟 c1.1 是同一個反例 → 不准再問", r.returncode == 2 and "已經問過" in r.stderr, r.stderr[-200:])
        r = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c11")
        check("G2 c11 沒問過 → --add 回 2(不借 c1.1 的問答)", r.returncode == 2 and "沒有 residual-ask" in r.stderr and "[residual:" not in s.read_text(encoding="utf-8"),
              f"rc={r.returncode} {r.stderr[-300:]}")
        check("G2 c11 是另一個反例 → 照樣能問", _rc_ask(v, "c11").returncode == 0, "")
        # 同一節點兩條只差小數點的合約:問過 1.5 倍那條的 c1,不能拿去替 15 倍那條記殘留
        txt = s.read_text(encoding="utf-8")
        s.write_text(txt.replace(f"{_RC_CONTRACT} [test:", "重試上限 1.5 倍 [test:")
                        .replace(f"{_RC_UNAUDITED} [test:test_rc_guard]", f"重試上限 15 倍 [test:test_rc_guard] [audit:{_RC_AUDIT}]"), encoding="utf-8")
        check("★前置★ 1.5 倍那條問過 c1 判 untestable", _rc_ask(v, "c1", substr="重試上限 1.5 倍").returncode == 0, "")
        r = run(v, "guard", "residual", "Systems/S", "重試上限 15 倍", "--add", "Projects/a_計劃#d12", "--case", "c1")
        check("G2 15 倍那條沒問過 c1 → --add 回 2", r.returncode == 2 and "沒有 residual-ask" in r.stderr, f"rc={r.returncode} {r.stderr[-300:]}")
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_residual_testable_sticks_to_case():
    """[r2 G3 → r3 G1] 判過 testable 的反例記在(節點、合約指紋、反例編號)上:同一條合約不准改判 untestable、不准記殘留
    (寫法變體與手寫進帳的 untestable 都一樣);同節點別條合約的同名反例不受牽連;合約改字換指紋後問得到,
    但記成殘留的那次推送升 high(外層看門)。判準來源:r2 資安席 F3、r3 合約席與通才席(同節點別條合約的 c1 被牽連)。"""
    import json as _j
    import shutil as _sh
    root, v, g = _rc_repo("rc-r2g3")
    s = v / "Systems" / "S.md"
    gp = root / "docs" / ".governance-log.jsonl"
    try:
        check("★前置★ c9 判 testable", _rc_ask(v, "c9", verdict="testable").returncode == 0, "")
        for var in ("c9", "C9.", "c-9"):
            r = _rc_ask(v, var)
            check(f"G3 同一條合約的 {var} 改判 untestable → 回 2、說判過 testable", r.returncode == 2 and "testable" in r.stderr
                  and len(_rc_gov(root)) == 1, f"rc={r.returncode} {r.stderr[-300:]}")
        row = dict(_rc_gov(root)[-1], verdict="untestable", case="C9")
        with gp.open("a", encoding="utf-8") as fh:
            fh.write(_j.dumps(row, ensure_ascii=False) + "\n")   # 繞過指令直接進帳的一筆
        r = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c9")
        check("G3 手寫的 untestable → --add 回 2、說判過 testable", r.returncode == 2 and "testable" in r.stderr
              and "[residual:" not in s.read_text(encoding="utf-8"), f"rc={r.returncode} {r.stderr[-300:]}")
        txt = s.read_text(encoding="utf-8")
        s.write_text(txt.replace(f"{_RC_UNAUDITED} [test:test_rc_guard]", f"{_RC_UNAUDITED} [test:test_rc_guard] [audit:{_RC_AUDIT}]"), encoding="utf-8")
        r = _rc_ask(v, "c9", substr=_RC_UNAUDITED, reaudit=False)
        check("G3 同節點別條合約的 c9 不受牽連 → 問得到", r.returncode == 0, r.stderr[-300:])
        s.write_text(txt, encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "c9 testable"); g("checkout", "-qb", "feat")
        s.write_text(txt.replace(f"{_RC_CONTRACT} [test:", f"{_RC_CONTRACT}且目前不得負庫存 [test:"), encoding="utf-8")
        r = _rc_ask(v, "c9")
        check("G3 合約改字換指紋 → 另一條合約,c9 問得到(只准問一次是方便不是保證)", r.returncode == 0, r.stderr[-300:])
        r = run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c9")
        check("★前置★ 新句子的 c9 記成殘留", r.returncode == 0, r.stderr[-300:])
        g("add", "-A"); g("commit", "-qm", "改字重問後記殘留")
        d = _rc_pitfalls_tier(v, root)
        check("G3 改字重問後記殘留的推送 → high、理由說新增了殘留要過高風險代碼審", d["tier"] == "high" and "新增了殘留" in d.get("tier_reason", ""), repr(d)[:400])
    finally:
        _sh.rmtree(root, ignore_errors=True)


def t_pitfalls_residual_ask_rows_dropped():
    """[r2 G3] 推送範圍刪掉或改掉治理帳裡 residual-ask 的列 → high(刪帳列重問躲不掉);新增問答、刪別的閘的列不升。
    判準來源:r2 資安席 F3 步驟 b(刪掉 testable 那列再問 untestable)。只讀 git diff,不載圖譜。"""
    import json as _j
    import shutil as _sh
    ask = {"ts": "2026-10-14T10:00:00+08:00", "gate": "residual-ask", "kind": "asked", "node": "Systems/S", "fp": "abc",
           "case": "c9", "verdict": "testable", "checker": "sonnet/2026-10-14"}
    other = {"ts": "2026-10-14T10:00:00+08:00", "gate": "code-loop", "kind": "passed", "note": "x"}
    roots = []
    def prep(tag):
        root, v, g = _rc_repo(tag, commit=False); roots.append(root)
        (root / "docs" / ".governance-log.jsonl").write_text(_j.dumps(other) + "\n" + _j.dumps(ask) + "\n", encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "init"); g("checkout", "-qb", "feat")
        return root, v, g
    try:
        for name, body, want in (("刪掉 residual-ask 那列", _j.dumps(other) + "\n", True),
                                 ("把那列的判定改掉", _j.dumps(other) + "\n" + _j.dumps(dict(ask, verdict="untestable")) + "\n", True),
                                 ("新增一筆問答", _j.dumps(other) + "\n" + _j.dumps(ask) + "\n" + _j.dumps(dict(ask, case="c10")) + "\n", False),
                                 ("刪掉別的閘的列", _j.dumps(ask) + "\n", False)):
            root, v, g = prep(f"rc-r2g3d-{len(roots)}")
            (root / "docs" / ".governance-log.jsonl").write_text(body, encoding="utf-8"); g("commit", "-qam", name)
            d = _rc_pitfalls_tier(v, root)
            if want:
                check(f"G3 {name} → high、理由說刪改了治理帳的問答", d["tier"] == "high" and "residual-ask" in d.get("tier_reason", ""), repr(d)[:400])
            else:
                check(f"G3 {name} → 不升 high", d["tier"] != "high", repr(d)[:400])
        root, v, g = prep("rc-r2g3d-rm")
        g("rm", "-q", "docs/.governance-log.jsonl"); g("commit", "-qm", "rm")
        check("G3 整本治理帳刪掉 → high", _rc_pitfalls_tier(v, root)["tier"] == "high", "")
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_pitfalls_residual_guard_shrunk():
    """[r2 G4] 同一筆殘留(節點、殘留指標)起點有、頂端沒有的 about_code 或測試檔 → 算拿掉殘留、high(分兩次推送先縮守備範圍躲不掉);
    守備範圍變大、只換指紋不升。判準來源:r2 資安席 F1 的函式層實驗(推送 1 只清空 about_code 與測試檔)。"""
    import json as _j
    import shutil as _sh
    ent = {"node": "Systems/S", "fp": "x", "residuals": ["Projects/a_計劃#d12"], "about_code": ["src/a.py"], "test_files": ["tests/test_a.py"]}
    roots = []
    try:
        for name, head, want in (("about_code 清空", dict(ent, about_code=[]), True),
                                 ("測試檔清空", dict(ent, test_files=[]), True),
                                 ("about_code 換成別支檔", dict(ent, about_code=["src/c.py"]), True),
                                 ("守備範圍變大", dict(ent, about_code=["src/a.py", "src/b.py"]), False)):
            root, v, g = _rc_with_index(f"rc-r2g4-{len(roots)}", {"version": 1, "entries": [ent]}, roots)
            (root / "governance" / "residual-index.json").write_text(_j.dumps({"version": 1, "entries": [head]}, ensure_ascii=False), encoding="utf-8")
            g("commit", "-qam", name)
            d = _rc_pitfalls_tier(v, root)
            if want:
                check(f"G4 {name} → high、理由說縮小殘留守的範圍", d["tier"] == "high" and "守的範圍" in d.get("tier_reason", ""), repr(d)[:400])
            else:
                check(f"G4 {name} → 不升 high", d["tier"] != "high", repr(d)[:400])
        # 代碼審 r3 G3:殘留身分帶合約指紋——合約改字只換指紋,升 high(原本判成不升);
        # r4 G5(通才席):理由照實講「合約句子改了(舊的拿掉、新的加入)」,不再寫成拿掉殘留加新增殘留
        root, v, g = _rc_with_index(f"rc-r2g4-{len(roots)}", {"version": 1, "entries": [ent]}, roots)
        (root / "governance" / "residual-index.json").write_text(_j.dumps({"version": 1, "entries": [dict(ent, fp="y")]}), encoding="utf-8")
        g("commit", "-qam", "改字換指紋")
        d = _rc_pitfalls_tier(v, root)
        why = d.get("tier_reason", "")
        check("G4 合約改字只換指紋 → high、理由說合約句子改了(舊的拿掉、新的加入),不說拿掉殘留(r3 G3、r4 G5)",
              d["tier"] == "high" and "合約句子改了(舊的拿掉、新的加入),要過代碼審" in why and "推送範圍裡拿掉殘留" not in why
              and "新增了殘留" not in why, repr(d)[:400])
        # 同節點同指標另有一條合約照舊、只多一條新句子:那是新增,不是改字
        root, v, g = _rc_with_index(f"rc-r2g4-{len(roots)}", {"version": 1, "entries": [ent]}, roots)
        (root / "governance" / "residual-index.json").write_text(_j.dumps({"version": 1, "entries": [ent, dict(ent, fp="y")]}), encoding="utf-8")
        g("commit", "-qam", "多一條")
        d = _rc_pitfalls_tier(v, root)
        check("G4 舊句子還在、多一條新句子 → 理由說新增了殘留、不說改字", d["tier"] == "high" and "新增了殘留" in d.get("tier_reason", "")
              and "合約句子改了" not in d.get("tier_reason", ""), repr(d)[:400])
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_pitfalls_residual_git_failures():
    """[r2 G5] git 出錯一律往多升 high 的方向:起點索引讀不出(物件遺失,不是路徑不存在)→ high;
    檔名清單的 git diff 失敗而索引有殘留 → high;沒有任何殘留時檔名清單失敗照舊不升。判準來源:r2 併發席。"""
    import json as _j
    import shutil as _sh
    import types as _ty
    m = _load_lumos()
    ent = {"node": "Systems/S", "fp": "x", "residuals": ["Projects/a_計劃#d12"], "about_code": ["src/a.py"], "test_files": []}
    roots = []
    real = m.subprocess
    try:
        root, v, g = _rc_with_index("rc-r2g5-base", {"version": 1, "entries": [ent]}, roots)
        (root / "governance" / "residual-index.json").write_text(_j.dumps({"version": 1, "entries": [ent]}, indent=2), encoding="utf-8")
        (root / "src" / "b.py").write_text("def b():\n    return 5\n", encoding="utf-8"); g("commit", "-qam", "x")
        blob = g("rev-parse", "main:governance/residual-index.json").stdout.strip()
        obj = root / ".git" / "objects" / blob[:2] / blob[2:]
        check("★前置★ 起點索引是鬆散物件", obj.is_file(), str(obj))
        obj.unlink()
        check("★前置★ git show 讀不出、ls-tree 還列得到(不是路徑不存在)",
              g("show", "main:governance/residual-index.json").returncode != 0 and "residual-index.json" in g("ls-tree", "main", "--", "governance/residual-index.json").stdout, "")
        res = m._residual_tier_hits(root, "main..HEAD")
        check("G5 起點索引讀不出 → 記成讀不出", res.get("base_bad") is True, repr(res))
        tier, why = m._pitfall_tier([], ["src/b.py"], root, "main..HEAD")
        check("G5 起點索引讀不出 → high、理由說起點版本的索引讀不出", tier == "high" and "起點版本的殘留索引讀不出" in why, f"{tier} {why}")
        root, _v, g = _rc_repo("rc-r2g5-new"); roots.append(root)
        g("checkout", "-qb", "feat"); (root / "governance").mkdir()
        (root / "governance" / "residual-index.json").write_text(_j.dumps({"version": 1, "entries": [ent]}), encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "index")
        check("G5 起點沒有索引檔(路徑不存在)→ 不算讀不出", "base_bad" not in m._residual_tier_hits(root, "main..HEAD"), "")

        def fake(args, *a, **kw):
            if "--name-only" in args:
                return real.CompletedProcess(args, 128, "", "fatal: 模擬失敗")
            return real.run(args, *a, **kw)
        root, _v, g = _rc_with_index("rc-r2g5-names", {"version": 1, "entries": [ent]}, roots)
        (root / "src" / "b.py").write_text("def b():\n    return 5\n", encoding="utf-8"); g("commit", "-qam", "x")
        root0, _v0, g0 = _rc_repo("rc-r2g5-none"); roots.append(root0)
        g0("checkout", "-qb", "feat"); (root0 / "src" / "b.py").write_text("x = 1\n", encoding="utf-8"); g0("commit", "-qam", "x")
        m.subprocess = _ty.SimpleNamespace(run=fake, TimeoutExpired=real.TimeoutExpired, CompletedProcess=real.CompletedProcess, PIPE=real.PIPE)
        try:
            res = m._residual_tier_hits(root, "main..HEAD")
            tier, why = m._pitfall_tier([], ["src/b.py"], root, "main..HEAD")
            res0 = m._residual_tier_hits(root0, "main..HEAD")
        finally:
            m.subprocess = real
        check("G5 檔名清單失敗、索引有殘留 → 記成判不出改了哪些檔", res.get("files_unknown") is True, repr(res))
        check("G5 檔名清單失敗、索引有殘留 → high、理由說列不出改了哪些檔", tier == "high" and "列不出這次改了哪些檔" in why, f"{tier} {why}")
        check("G5 沒有任何殘留時檔名清單失敗 → 不升(跟沒有殘留機制時一樣)", res0 == {}, repr(res0))
    finally:
        m.subprocess = real
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_guard_residual_noop_keeps_index():
    """[r2 G6] 「已經有了」「沒有這個標記」兩條沒事可做的路:索引跟重算結果相同就不碰檔案(打錯字的指令不在工作樹留改動);
    不同才寫,寫了印「索引原本沒跟上,已補好」。判準來源:r2 併發、通才兩席。"""
    import json as _j
    import shutil as _sh
    root, v, _g = _rc_repo("rc-r2g6")
    ip = root / "governance" / "residual-index.json"
    add = ("guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1")
    typo = ("guard", "residual", "Systems/S", _RC_CONTRACT, "--remove", "Projects/a_計劃#d99")
    try:
        r = run(v, *typo)
        check("G6 沒有殘留、沒有索引時 --remove 打錯 → 回 2、不建索引檔", r.returncode == 2 and not ip.exists(), f"rc={r.returncode} exists={ip.exists()}")
        check("★前置★ c1 判 untestable、--add 寫好索引", _rc_ask(v, "c1").returncode == 0 and run(v, *add).returncode == 0 and ip.is_file(), "")
        st = lambda: (ip.stat().st_ino, ip.stat().st_mtime_ns, ip.read_bytes())
        before = st()
        for name, args, rc in (("已經有了", add, 0), ("沒有這個標記", typo, 2)):
            r = run(v, *args)
            check(f"G6 {name}、索引本來就對 → 回 {rc}、索引檔沒被碰、不說補好", r.returncode == rc and st() == before and "已補好" not in r.stdout + r.stderr,
                  f"rc={r.returncode} {r.stdout[-200:]} {r.stderr[-200:]}")
        for name, args, rc in (("已經有了", add, 0), ("沒有這個標記", typo, 2)):
            ip.write_text(_j.dumps({"version": 1, "entries": []}), encoding="utf-8")
            r = run(v, *args)
            ents = _j.loads(ip.read_text(encoding="utf-8")).get("entries")
            check(f"G6 {name}、索引沒跟上 → 回 {rc}、補好並說「索引原本沒跟上,已補好」", r.returncode == rc and len(ents) == 1
                  and "索引原本沒跟上,已補好" in r.stdout + r.stderr, f"rc={r.returncode} {r.stdout[-200:]} {r.stderr[-200:]} {ents}")
    finally:
        _sh.rmtree(root, ignore_errors=True)


