def t_pitfalls_residual_ask_unreadable_reason():
    """[r5 G2] 分級把「治理帳讀不出」跟「刪掉或改掉問答」分成兩種理由句:①起點帳沒有任何 residual-ask 列、頂端(工作目錄)那份是捷徑讀不出
    → high,理由說讀不出、不說刪掉;②起點有一列、頂端真的少了那列 → 理由說刪掉或改掉、不說讀不出。
    判準來源:r5 通才席(起點沒問答、頂端讀不出時理由寫成「刪掉或改掉」,與事實不符)。"""
    import json as _j
    import os as _os
    import shutil as _sh
    import tempfile as _tf
    m = _load_lumos()
    other = {"ts": "2026-10-14T10:00:00+08:00", "gate": "code-loop", "kind": "passed", "note": "x"}
    ask = {"ts": "2026-10-14T10:00:00+08:00", "gate": "residual-ask", "kind": "asked", "node": "Systems/S", "fp": "abc",
           "case": "c9", "verdict": "testable", "checker": "sonnet/2026-10-14"}
    L = lambda *ds: "".join(_j.dumps(d, ensure_ascii=False) + "\n" for d in ds)
    roots = []
    try:
        root, _v, g = _rc_repo("rc-r5g2-why", commit=False)
        roots.append(root)
        gp = root / "docs" / ".governance-log.jsonl"
        gp.write_text(L(other), encoding="utf-8")
        g("add", "-A")
        g("commit", "-qm", "init")
        outside = Path(_tf.mkdtemp(prefix="gctl-rc-r5g2-out-"))
        roots.append(outside)
        (outside / "real.jsonl").write_text(L(other, dict(ask, verdict="untestable")), encoding="utf-8")
        gp.unlink()
        _os.symlink(outside / "real.jsonl", gp)
        why = ";".join(m._residual_tier_reasons(m._residual_tier_hits(root, "main")))
        check("G2 ①起點沒有問答、頂端帳是捷徑讀不出 → 有理由(升 high)、說讀不出、不說刪掉", why and "讀不出" in why and "刪掉" not in why, why)
        root, _v, g = _rc_repo("rc-r5g2-drop", commit=False)
        roots.append(root)
        gp = root / "docs" / ".governance-log.jsonl"
        gp.write_text(L(other, ask), encoding="utf-8")
        g("add", "-A")
        g("commit", "-qm", "init")
        g("checkout", "-qb", "feat")
        gp.write_text(L(other), encoding="utf-8")
        g("commit", "-qam", "刪問答")
        why = ";".join(m._residual_tier_reasons(m._residual_tier_hits(root, "main..HEAD")))
        check("G2 ②頂端真的少了一列 → 理由說刪掉或改掉、不說讀不出", "刪掉或改掉" in why and "讀不出" not in why, why)
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_dispatch_lens_residual_new_rows_first():
    """[r5 G3] 鏡頭排序:問答列這次新增的先列、其餘照 _gov_ts 排(讀不出的排最後);合約清單真的殘留索引變化排最前,
    問答指到的節點不在殘留索引的標「節點不在殘留索引」排後面。①邊界席:同一條合約主線已有 12 筆正常 ts 的問答,
    分支手寫 3 筆 ts 偽造成「0000-x」的 untestable 新增列 → 3 筆新增都列出;②資安席 F3:分支手寫 5 筆指到假節點 A0–A4 的 untestable 問答,
    同時真的新增一筆殘留 → 真殘留列出、假節點標「節點不在殘留索引」。應抓到的錯:照 ts 原始字串排、取最後 12 筆 → ①紅;合約照節點名排、取前 5 條 → ②紅。"""
    import shutil as _sh
    roots = []
    try:
        root, v, g = _rc_r4_main_with_residual("rc-r5g3-ts", roots, vault="rc-knowledge")
        base_row = [x for x in _rc_gov(root) if x.get("verdict") == "untestable"][-1]
        _rc_r5_rebase_main(g, lambda: _rc_r4_append(root, *[dict(base_row, case=f"c{20 + i}", ts=f"2026-10-{i + 1:02d}T10:00:00+08:00") for i in range(12)]))
        _rc_r4_append(root, *[dict(base_row, case=f"n{i}", ts="0000-x") for i in (1, 2, 3)])
        g("commit", "-qam", "三筆偽造 ts 的新增列")
        t = _rc_r5_section(root)
        shown = [c for c in ("n1", "n2", "n3") if any(f"問答 {c} " in ln and "這次新增" in ln for ln in t.splitlines())]
        check("G3 ①12 筆正常列 + 3 筆偽造 ts 的新增列 → 3 筆新增都列出、標這次新增", shown == ["n1", "n2", "n3"], t[-2000:])
        root, v, g = _rc_repo("rc-r5g3-fake", vault="rc-knowledge")
        roots.append(root)
        g("checkout", "-qb", "feat")
        check("★前置★ c1 判 untestable", _rc_ask(v, "c1").returncode == 0, "")
        run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1", expect_rc=0)
        row = [x for x in _rc_gov(root) if x.get("verdict") == "untestable"][-1]
        _rc_r4_append(root, *[dict(row, node=f"A/A{i}", fp=f"f{i}", case="c1") for i in range(5)])
        g("add", "-A")
        g("commit", "-qm", "真殘留 + 五筆假節點問答")
        t = _rc_r5_section(root)
        fake = [ln for ln in t.splitlines() if ln.startswith("- A/A")]
        check("G3 ②五筆假節點問答 + 一條真殘留 → 真殘留列出", "[residual:Projects/a_計劃#d12]" in t, t[-2000:])
        check("G3 ②假節點標「節點不在殘留索引」、排在真殘留後面", fake and all("節點不在殘留索引" in ln for ln in fake)
              and t.find("[residual:Projects/a_計劃#d12]") < t.find("- A/A"), t[-2000:])
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


