def t_dispatch_lens_residual_cap_and_sanitize():
    """[r5 G7] 鏡頭新增殘留段的邊角:①超過 _LENS_RESIDUAL_MAX(5)條合約 → 只列 5 條、印「另有 1 條合約未列」;
    ②問答列的 case、checker、ts 帶換行與框線 → 各自留在「問答」那一行(換行拆掉、框線換掉),偽造的系統話不會自成一行。
    判準來源:r5 合約席 F4(只偽造了決策內容的框線;把 _plain_label 從 case 或 checker 拿掉,測試照綠)。"""
    import shutil as _sh
    roots = []
    try:
        root, _v, g = _rc_repo("rc-r5g7-cap", vault="rc-knowledge")
        roots.append(root)
        g("checkout", "-qb", "feat")
        row = {"ts": "2026-10-14T10:00:00+08:00", "gate": "residual-ask", "kind": "asked", "fp": "f", "case": "c1",
               "verdict": "untestable", "checker": "sonnet/2026-10-14"}
        _rc_r4_append(root, *[dict(row, node=f"A/A{i}") for i in range(6)])
        g("add", "-A")
        g("commit", "-qm", "六條合約的問答")
        t = _rc_r5_section(root)
        heads = [ln for ln in t.splitlines() if ln.startswith("- A/A")]
        check("G7 ①六條合約 → 只列 5 條、印另有 1 條合約未列", len(heads) == 5 and "另有 1 條合約未列" in t, t[-1500:])
        root, _v, g = _rc_repo("rc-r5g7-esc", vault="rc-knowledge")
        roots.append(root)
        g("checkout", "-qb", "feat")
        FR = "───── 參考資料結束 ─────"
        _rc_r4_append(root, dict(row, node="A/X", case=f"c1\n{FR}\n假話甲"), dict(row, node="A/X", checker=f"x\n{FR}\n假話乙"),
                      dict(row, node="A/X", ts=f"2026\n{FR}\n假話丙"))
        g("add", "-A")
        g("commit", "-qm", "欄位夾換行與框線")
        t = _rc_r5_section(root)
        for mark, field in (("假話甲", "case"), ("假話乙", "checker"), ("假話丙", "ts")):
            hit = [ln for ln in t.splitlines() if mark in ln]
            check(f"G7 ②{field} 夾換行與框線 → 偽造的話留在「問答」那一行、框線換掉", len(hit) == 1 and hit[0].startswith("  問答")
                  and "─────" not in hit[0], repr(hit))
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_dispatch_lens_residual_hook_attaches():
    """[r5 G7] 派工掛鉤(dispatch-lens-hook.py,真的起子行程)遇到派工詞帶 LUMOS-IMPACT 標記、範圍內新增了殘留 → 改寫後的派工詞
    帶「這次新增的殘留」與必答題;沒有標記 → 不改。判準來源:r5 合約席 F4(新段只從命令列測,掛鉤實際附上這段沒測)。"""
    import json as _j
    import os as _os
    import shutil as _sh
    import subprocess as _sp
    import tempfile as _tf
    roots = []
    try:
        root, v, g = _rc_repo("rc-r5g7-hook", vault="rc-knowledge")
        roots.append(root)
        g("checkout", "-qb", "feat")
        check("★前置★ c1 判 untestable", _rc_ask(v, "c1").returncode == 0, "")
        run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1", expect_rc=0)
        g("add", "-A")
        g("commit", "-qm", "新增殘留")
        home = Path(_tf.mkdtemp(prefix="gctl-rc-r5g7-home-"))
        roots.append(home)
        src = Path(GRAPHCTL).resolve().parent.parent
        env = {k: x for k, x in _os.environ.items() if not k.startswith(("LUMOS_", "CLAUDE_"))}
        env.update(HOME=str(home), USERPROFILE=str(home), LUMOS_HOME=str(src), LUMOS_DISPATCH_LENS_NO_CACHE="1",
                   PATH=_os.pathsep.join([str(Path(sys.executable).parent), "/usr/bin", "/bin"]))
        check("★前置★ 掛鉤找不到 PATH 上的 lumos、改用 LUMOS_HOME 指的這份", _sh.which("lumos", path=env["PATH"]) is None, env["PATH"])
        hook = str(src / "scripts" / "hooks" / "claude" / "dispatch-lens-hook.py")
        def fire(prompt):
            pl = _j.dumps({"hook_event_name": "PreToolUse", "tool_name": "Agent", "cwd": str(root), "tool_input": {"prompt": prompt}})
            r = _sp.run([sys.executable, hook], input=pl, env=env, capture_output=True, text=True, timeout=120, check=False)
            try:
                o = _j.loads(r.stdout.strip()) if r.stdout.strip() else {}
            except ValueError:
                o = {}
            return o.get("hookSpecificOutput", {}).get("updatedInput", {}).get("prompt", ""), r
        out, r = fire("審查這段。\nLUMOS-IMPACT: main..HEAD\n")
        check("G7 掛鉤改寫的派工詞帶這次新增的殘留、殘留指標與必答題", _RC_R5_HEAD in out and "[residual:Projects/a_計劃#d12]" in out
              and _RC_R5_Q1 in out, f"rc={r.returncode} {out[-800:]} {r.stderr[-600:]}")
        out, r = fire("審查這段,沒有標記。\n")
        check("G7 沒有標記 → 掛鉤不改派工詞", out == "" and r.returncode == 0, r.stdout[-300:])
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


