def t_pitfalls_residual_ignores_git_grafts():
    """[r5 G5] 主程式入口關掉 grafts(GIT_GRAFT_FILE 指到不存在的路徑):主線多一個提交 M2,分支新增殘留;再寫 .git/info/grafts
    把 M2 的父提交改成分支頂端 → git merge-base 變成頂端本身、main...HEAD 看起來是空範圍。走入口的 pitfalls --diff main...HEAD
    照樣看到真歷史:high、理由說新增了殘留。判準來源:協調者轉述另一分支資安席實測(git 2.39 在 GIT_NO_REPLACE_OBJECTS=1 下仍讀 grafts)。
    應抓到的錯:入口不設 GIT_GRAFT_FILE → 紅。"""
    import shutil as _sh
    roots = []
    try:
        root, v, g = _rc_repo("rc-r5g5-graft", vault="rc-knowledge")
        roots.append(root)
        g("checkout", "-qb", "feat")
        check("★前置★ c1 判 untestable", _rc_ask(v, "c1").returncode == 0, "")
        run(v, "guard", "residual", "Systems/S", _RC_CONTRACT, "--add", "Projects/a_計劃#d12", "--case", "c1", expect_rc=0)
        g("add", "-A")
        g("commit", "-qm", "新增殘留")
        head = _rc_r5_rev(root, "HEAD")
        g("checkout", "-q", "main")
        (root / "src" / "b.py").write_text("def b():\n    return 3\n", encoding="utf-8")
        g("commit", "-qam", "主線另一個提交")
        m2 = _rc_r5_rev(root, "HEAD")
        g("checkout", "-q", "feat")
        d = _rc_pitfalls_tier(v, root, "main...HEAD")
        check("★前置★ 沒有 grafts 時 main...HEAD → high、新增了殘留", d["tier"] == "high" and "新增了殘留" in d.get("tier_reason", ""), repr(d)[:400])
        (root / ".git" / "info").mkdir(exist_ok=True)
        (root / ".git" / "info" / "grafts").write_text(f"{m2} {head}\n", encoding="utf-8")
        check("★前置★ grafts 生效:git merge-base main HEAD 變成頂端本身", g("merge-base", "main", "HEAD").stdout.strip() == head, "")
        d = _rc_pitfalls_tier(v, root, "main...HEAD")
        check("G5 grafts 改寫祖先關係 → 照樣 high、理由說新增了殘留", d["tier"] == "high" and "新增了殘留" in d.get("tier_reason", ""), repr(d)[:400])
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_pitfalls_ignores_git_diff_opts_env():
    """[r5 G5] 主程式入口拿掉 GIT_DIFF_OPTS(它會蓋掉程式裡明寫的 -U0/-U3):環境帶 GIT_DIFF_OPTS=-u0 或 -u40 跑 pitfalls --diff,
    結果(分級、挑出的測試關鍵字)跟沒帶時相同。固定例子:src/a.py 前面一個 30 多行的 first()、後面 second() 裡改一行 →
    關鍵字是 second(-u40 時 git 的區塊標頭會變成 first)。判準來源:協調者轉述另一分支資安席實測。應抓到的錯:入口不拿掉 GIT_DIFF_OPTS → 紅。"""
    import json as _j
    import shutil as _sh
    import subprocess as _sp
    roots = []
    try:
        root, v, g = _rc_repo("rc-r5g5-dopts")
        roots.append(root)
        body = "def first():\n" + "".join(f"    x{i} = {i}\n" for i in range(30)) + "    return 0\n\n\ndef second():\n    y = 1\n    return y\n"
        (root / "src" / "b.py").write_text(body, encoding="utf-8")
        g("commit", "-qam", "b.py 兩個函式")
        g("checkout", "-qb", "feat")
        (root / "src" / "b.py").write_text(body.replace("    y = 1", "    y = 2"), encoding="utf-8")
        g("commit", "-qam", "改 second")
        env0 = _rc_git_env()
        def tier(extra):
            env = dict(env0, **extra)
            r = _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "pitfalls", "--diff", "main..HEAD", "--no-lint", "--json", "--repo", str(root)],
                        capture_output=True, text=True, env=env, check=False)
            try:
                d = _j.loads(r.stdout)
            except ValueError:
                return ("?", r.stdout[-200:] + r.stderr[-200:])
            return (d.get("tier"), d.get("affected_keys"))
        base = tier({})
        check("★前置★ 沒帶 GIT_DIFF_OPTS → 關鍵字是 second", base[1] and "second" in base[1] and "first" not in base[1], repr(base))
        hdr = _sp.run(["git", "-C", str(root), "diff", "-U0", "main..HEAD"], capture_output=True, text=True, env=dict(env0, GIT_DIFF_OPTS="-u40"), check=False).stdout
        check("★前置★ GIT_DIFF_OPTS=-u40 蓋得掉明寫的 -U0(情境成立)", "@@ -1," in hdr, hdr[:200])
        for val in ("-u0", "-u40"):
            got = tier({"GIT_DIFF_OPTS": val})
            check(f"G5 環境帶 GIT_DIFF_OPTS={val} → 結果跟沒帶時相同", got == base, f"{got!r} vs {base!r}")
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_reference_residual_lens_docs():
    """[r5 G6] 手冊照實寫新增殘留段(結構檢查,守的是說法不跟程式打架):①templates §3 與 06 那列講「內容從 base 讀」的地方寫明例外
    ——新增殘留段從頂端讀推送者寫的字,防護是注入框、字數上限、消毒;②code-loop SKILL.md 不再說「沒答的席照漏答固定席處理」
    (沒有對應機制),照實寫把關是推送升 high、要過一輪高風險代碼審,審查席有沒有答沒有機械核對,並列鏡頭附段的前提
    (LUMOS-IMPACT 標記、base 在主線、沒逾時、已提交);③reference.md、06、圖譜即合約.md 寫明新增判 untestable 的問答也升 high,
    改到存著已登記殘留決策的筆記也升 high;④(r6 合約席)reference.md、圖譜即合約.md、templates §3、計劃 WHY 照實寫
    「只保證跑一輪高風險代碼審,審查席有沒有答沒有機械核對」,圖譜即合約.md 與 06 寫粗粒度的代價,templates §3 寫只改筆記也附段。判準來源:r5 合約席 F1–F3、r6 合約席。"""
    import re as _re
    root = Path(GRAPHCTL).resolve().parent.parent
    rd = lambda rel: (root / rel).read_text(encoding="utf-8")
    tpl = rd("skills/lumos-design-loop/templates.md")
    s3 = tpl[tpl.find("### §3 編排者派工前須知"):]
    s3 = s3[:s3.find("\n### ", 10)] if "\n### " in s3[10:] else s3
    six = rd("skills/lumos-project-notes/commands/06-代碼審與推送.md")
    row = next((ln for ln in six.splitlines() if "固定席節點自動附進派工詞了嗎" in ln), "")
    for name, txt in (("templates §3", s3), ("06 固定席那列", row)):
        check(f"G6 {name} 寫明新增殘留段是從頂端讀的例外、附防護(注入框、字數上限、消毒)",
              _re.search(r"這次新增的殘留[^\n]{0,80}頂端", txt) is not None and "注入框" in txt and "字數上限" in txt and "消毒" in txt, txt[:300])
    sk = rd("skills/lumos-code-loop/SKILL.md")
    check("G6 code-loop SKILL.md 不再說沒答的席照漏答固定席處理", "漏答固定席處理" not in sk, "")
    ln = next((x for x in sk.splitlines() if "這次新增的殘留" in x), "")
    check("G6 code-loop SKILL.md 照實寫把關強度(推送升 high、審查席有沒有答沒有機械核對)與附段前提",
          "沒有機械核對" in ln and "LUMOS-IMPACT" in ln and "base 在主線" in ln and "逾時" in ln and "已提交" in ln, ln[:400])
    for rel in ("skills/lumos-project-notes/reference.md", "skills/lumos-project-notes/commands/06-代碼審與推送.md", "docs/methodology/圖譜即合約.md"):
        t = rd(rel)
        check(f"G6 {rel} 寫明新增判 untestable 的問答也升 high", _re.search(r"新增[^。\n]{0,12}判[^。\n]{0,6}(untestable|測不到)[^。\n]{0,8}問答[^。\n]{0,30}(升 high|高風險)", t) is not None, "")
        check(f"G6 {rel} 寫明改到存著已登記殘留決策的筆記也升 high", "存著已登記殘留" in t, "")
    # r6 G6(合約席):把關強度在各處照實寫,不只 SKILL.md;粗粒度的代價與「只改筆記也附段」寫進使用者面的手冊
    plan = rd("docs/lumos-toolchain-knowledge/Projects/審查收斂規則_計劃.md")
    why = next((x for x in plan.splitlines() if x.startswith("WHY:「同一反例只准問一次」")), "")
    honest = "只保證跑一輪高風險代碼審,審查席有沒有答沒有機械核對"
    gm = rd("docs/methodology/圖譜即合約.md").replace("，", ",")
    for name, txt in (("reference.md", rd("skills/lumos-project-notes/reference.md")), ("圖譜即合約.md", gm), ("templates §3", s3), ("計劃 WHY", why)):
        check(f"G6 {name} 照實寫把關強度:{honest}", honest in txt, txt[:200] if name == "計劃 WHY" else "")
    for name, txt in (("圖譜即合約.md", gm), ("06", six)):
        check(f"G6 {name} 寫明改到存著殘留決策的筆記是刻意的粗粒度、只改錯字也要過一輪高風險代碼審", "只改錯字也要過一輪高風險代碼審" in txt, "")
    check("G6 templates §3 寫明只改存著已登記殘留決策的筆記也會附這一段", "只改了存著已登記殘留決策的筆記" in s3 and "也會附這一段" in s3, s3[:300])


# ── 代碼審 code-審查收斂規則 r6 的修正(六組;r6-intake.md〈根因分組與處置〉)──
# 預期值都是手寫的固定例子(50 筆舊格式殘留、搬走的決策筆記、三種寫錯的 notes 值、docs/knowledge 圖譜、會改輸出的外部差異工具),
# 不呼叫被測函式產生 expected。

def _rc_r6_set_notes(root, value):
    """改工作目錄那份殘留索引:每筆的 notes 換成 value(None = 整欄拿掉,當舊格式)。"""
    import json as _j
    idx = root / "governance" / "residual-index.json"
    doc = _j.loads(idx.read_text(encoding="utf-8"))
    for e in doc["entries"]:
        if value is None:
            e.pop("notes", None)
        else:
            e["notes"] = {r: value for r in e["residuals"]}
    idx.write_text(_j.dumps(doc, ensure_ascii=False, indent=2), encoding="utf-8")


def t_dispatch_lens_residual_new_not_crowded():
    """[r6 G1] 鏡頭排序分級:這次新增的殘留排最前,位置未知的舊殘留不逐條展開、彙總成一行。情境照 r6 併發席(縮成 50 筆):
    主線索引 50 筆舊格式殘留(Systems/n0..n49,沒有 notes 欄),分支新增 Systems/n50 一筆、同時改一篇圖譜筆記 →
    n50 一定列出(照節點名排它在 n0、n1、n10… 之後,舊寫法只取前 5 條就擠掉它);50 筆位置未知的彙總成一行(講幾筆、改了哪篇),不逐條列。
    應抓到的錯:位置未知跟新增同排級 0 → n50 不出現、n0 逐條出現 → 紅。"""
    import json as _j
    import shutil as _sh
    roots = []
    m = _load_lumos()
    try:
        root, v, g = _rc_repo("rc-r6g1", vault="rc-knowledge")
        roots.append(root)
        ref = "Projects/a_計劃#d12"
        ents = [{"node": f"Systems/n{i}", "fp": f"f{i}", "residuals": [ref], "about_code": [], "test_files": []} for i in range(50)]
        (root / "governance").mkdir()
        idx = root / "governance" / "residual-index.json"
        idx.write_text(_j.dumps({"version": 1, "entries": ents}, ensure_ascii=False), encoding="utf-8")
        g("add", "-A")
        g("commit", "-qm", "主線 50 筆舊格式殘留")
        g("checkout", "-qb", "feat")
        new = {"node": "Systems/n50", "fp": "f50", "residuals": [ref], "about_code": [], "test_files": [],
               "notes": {ref: "docs/rc-knowledge/Projects/a_計劃.md"}}
        idx.write_text(_j.dumps({"version": 1, "entries": ents + [new]}, ensure_ascii=False), encoding="utf-8")
        (v / "MOC" / "idx.md").write_text("---\ntype: moc\n---\n# idx\n\n多一行\n", encoding="utf-8")
        g("add", "-A")
        g("commit", "-qm", "新增 n50、改一篇圖譜筆記")
        hits = m._residual_tier_hits(root, "main..HEAD")
        check("★前置★ 分級看到 1 筆新增、50 筆位置未知", hits.get("added") == [f"Systems/n50 [residual:{ref}]"]
              and len(hits.get("notes_unknown") or []) == 50, repr(hits)[:400])
        t = _rc_r5_section(root)
        heads = [ln for ln in t.splitlines() if ln.startswith("- Systems/n")]
        check("G1 新增的 Systems/n50 一定列出", any(ln.startswith("- Systems/n50(") for ln in heads), t[-1500:])
        check("G1 位置未知的 50 筆不逐條展開(n0 不自成一條合約)", not any(ln.startswith("- Systems/n0(") for ln in heads), t[-1500:])
        summ = [ln for ln in t.splitlines() if "另有 50 筆殘留" in ln]
        check("G1 位置未知的彙總成一行:講 50 筆、講改了哪篇", len(summ) == 1 and "docs/rc-knowledge/MOC/idx.md" in summ[0], t[-1500:])
        check("G1 照附必答題", _RC_R5_Q1 in t, t[-400:])
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_pitfalls_residual_note_unresolved_reason():
    """[r6 G2] --reindex 解不出殘留決策所在筆記時,索引記明確的「解不出」與原因({"unresolved": 原因}),不是靜默不記;
    之後改到圖譜檔照樣升 high,理由照實講解不出與原因、不叫人跑 --reindex(跑了也修不好)。
    固定例子:主線把存著 d12 的 Projects/a_計劃.md 搬成 b_計劃.md 後重建索引(指標 Projects/a_計劃#d12 指到找不到的筆記)。
    判準來源:r6 正確性席(理由叫人跑 --reindex,照做索引不變、下次照升)。"""
    import json as _j
    import shutil as _sh
    roots = []
    try:
        root, v, g = _rc_r4_main_with_residual("rc-r6g2-unres", roots, vault="rc-knowledge")
        def move_note():
            (v / "Projects" / "a_計劃.md").rename(v / "Projects" / "b_計劃.md")
            run(v, "guard", "residual", "--reindex")
        _rc_r5_rebase_main(g, move_note)
        ents = _j.loads((root / "governance" / "residual-index.json").read_text(encoding="utf-8"))["entries"]
        nv = (ents[0].get("notes") or {}).get("Projects/a_計劃#d12") if ents else None
        check("G2 --reindex 解不出時索引記明確的解不出與原因", isinstance(nv, dict) and isinstance(nv.get("unresolved"), str)
              and nv["unresolved"].strip(), repr(ents)[:400])
        (v / "MOC" / "idx.md").write_text("---\ntype: moc\n---\n# idx\n\n多一行\n", encoding="utf-8")
        g("commit", "-qam", "改別篇圖譜筆記")
        d = _rc_pitfalls_tier(v, root)
        why = d.get("tier_reason", "")
        check("G2 解不出決策所在筆記、改到圖譜檔 → 照樣 high", d["tier"] == "high" and "Projects/a_計劃#d12" in why, repr(d)[:500])
        check("G2 理由照實講解不出與原因、不叫人跑 --reindex", "解不出" in why and "找不到" in why and "--reindex" not in why, why)
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_pitfalls_residual_note_path_checked():
    """[r6 G2] 分級讀起點索引的 notes 時確認那條路徑在起點的樹裡(照 git 的路徑字串比,大小寫不同算不在):
    notes 寫成 ../x.md、指到不存在的檔、大小寫跟 git 不同(A_計劃.md)三種,只改真正的 a_計劃.md → 都不准靜默 light,
    當成位置未知升 high,理由講起點版本裡沒有那支檔。判準來源:r6 邊界席 F1(三種都得到 light、沒有任何提示)。"""
    import shutil as _sh
    roots = []
    try:
        for i, bad in enumerate(("../x.md", "docs/rc-knowledge/Projects/none.md", "docs/rc-knowledge/Projects/A_計劃.md")):
            root, v, g = _rc_r4_main_with_residual(f"rc-r6g2-path{i}", roots, vault="rc-knowledge")
            _rc_r5_rebase_main(g, lambda r=root, b=bad: _rc_r6_set_notes(r, b))
            p = v / "Projects" / "a_計劃.md"
            p.write_text(p.read_text(encoding="utf-8").replace("第 3 輪審計收斂 checker:", "第 3 輪審計收斂;另 c2 checker:"), encoding="utf-8")
            g("commit", "-qam", "只改 d12 內容")
            d = _rc_pitfalls_tier(v, root)
            why = d.get("tier_reason", "")
            check(f"G2 notes 寫成 {bad} 而只改真正那篇 → 不靜默 light、升 high、理由講起點版本裡沒有那支檔",
                  d["tier"] == "high" and "起點版本裡沒有" in why, repr(d)[:500])
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


def t_pitfalls_residual_note_nfd_path():
    """[r6 G6] 索引 notes 寫成 NFD(macOS 檔案系統常見的分解形)、改動清單的檔名是 git 存的 NFC → 照樣認得是那篇:
    只改那篇 → high、理由說改到存著已登記殘留的筆記(不是位置未知)。固定例子:決策筆記 Projects/café_計劃.md(é 有分解形)。判準來源:r6 邊界席(把比對的 nfc 拿掉,測試照綠)。
    應抓到的錯:比對前不正規化 → 對不上、判 light → 紅。"""
    import shutil as _sh
    import unicodedata as _ud
    roots = []
    try:
        root, v, g = _rc_r4_main_with_residual("rc-r6g6-nfd", roots, vault="rc-knowledge")
        name = _ud.normalize("NFC", "Projects/café_計劃.md")
        nfd = _ud.normalize("NFD", "docs/rc-knowledge/" + name)
        def setup():
            (v / name).write_text("---\ntype: project\nstatus: doing\n---\n# café\n", encoding="utf-8")
            _rc_r6_set_notes(root, nfd)
        _rc_r5_rebase_main(g, setup)
        tracked = [n for n in g("-c", "core.quotePath=false", "ls-files", "docs/rc-knowledge/Projects").stdout.split("\n") if "caf" in n]
        check("★前置★ 主線索引的 notes 是 NFD、git 存的檔名是 NFC,兩種寫法不同", nfd != _ud.normalize("NFC", nfd)
              and nfd in (root / "governance" / "residual-index.json").read_text(encoding="utf-8")
              and tracked == [_ud.normalize("NFC", nfd)], repr(tracked))
        p = v / name
        p.write_text(p.read_text(encoding="utf-8") + "\n多一行\n", encoding="utf-8")
        g("commit", "-qam", "只改那篇")
        d = _rc_pitfalls_tier(v, root)
        why = d.get("tier_reason", "")
        check("G6 notes 是 NFD、改動檔名是 NFC → high、理由說改到存著已登記殘留的筆記", d["tier"] == "high"
              and "改到存著已登記殘留的筆記" in why and "不知道" not in why, repr(d)[:500])
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


