def t_pitfalls_residual_graph_file_any_vault():
    """[r6 G3] 舊索引(不知道決策在哪篇)那條「改到圖譜的檔」只認圖譜資料夾底下的 .md,圖譜資料夾用 _vault_slug_of 那一套
    (docs/<名>-knowledge/,加認 docs/knowledge/)。固定例子:圖譜在 docs/knowledge/(不叫 rc-knowledge),主線索引是舊格式:
    ①改圖譜裡的 .md → high;②殘留指標在圖譜根目錄(Home#d1)、改 docs/knowledge/Home.md → high;
    ③改圖譜資料夾底下的非 .md(data.json)→ 不因這條升;④改圖譜外、路徑段剛好叫 Projects 的 src/Projects/api/notes.md → 不因這條升。
    判準來源:r6 正確性席、架構對齊席、邊界席。應抓到的錯:判定改成 return False → ①②紅;認資料夾不看副檔名 → ③紅;認任何層級的 Projects → ④紅。"""
    import json as _j
    import shutil as _sh
    roots = []
    m = _load_lumos()
    WHY = "不知道這筆殘留的決策在哪篇"
    try:
        root, v, g = _rc_r4_main_with_residual("rc-r6g3", roots, vault="knowledge")
        def legacy():
            _rc_r6_set_notes(root, None)
            idx = root / "governance" / "residual-index.json"
            doc = _j.loads(idx.read_text(encoding="utf-8"))
            doc["entries"].append({"node": "Systems/T", "fp": "t1", "residuals": ["Home#d1"], "about_code": [], "test_files": []})
            idx.write_text(_j.dumps(doc, ensure_ascii=False, indent=2), encoding="utf-8")
            (v / "Home.md").write_text("---\ntype: moc\n---\n# Home\n", encoding="utf-8")
            (v / "data.json").write_text("{}\n", encoding="utf-8")
            (root / "src" / "Projects" / "api").mkdir(parents=True)
            (root / "src" / "Projects" / "api" / "notes.md").write_text("# notes\n", encoding="utf-8")
        _rc_r5_rebase_main(g, legacy)
        check("★前置★ 圖譜在 docs/knowledge/", (root / "docs" / "knowledge" / "Projects" / "a_計劃.md").is_file(), "")
        cases = (("①圖譜裡的 .md", "docs/knowledge/MOC/idx.md", True), ("②圖譜根目錄 Home.md(指標 Home#d1)", "docs/knowledge/Home.md", True),
                 ("③圖譜資料夾底下的非 .md", "docs/knowledge/data.json", False), ("④圖譜外的 src/Projects/api/notes.md", "src/Projects/api/notes.md", False))
        for label, rel, high in cases:
            g("reset", "-q", "--hard", "main")
            (root / rel).write_text((root / rel).read_text(encoding="utf-8") + "\n多一行\n", encoding="utf-8")
            g("commit", "-qam", f"改 {rel}")
            d = _rc_pitfalls_tier(v, root)
            hits = m._residual_tier_hits(root, "main..HEAD")
            hit = bool(hits.get("notes_unknown"))
            ok = (d["tier"] == "high" and WHY in d.get("tier_reason", "")) if high else True
            check(f"G3 {label} → " + ("high、理由說不知道決策在哪篇" if high else "不因這條升"), hit == high and ok, f"{hits!r} {d!r}"[:500])
    finally:
        for r_ in roots:
            _sh.rmtree(r_, ignore_errors=True)


