def t_lint_aligned():
    import subprocess as sp
    import importlib.util as U
    from importlib.machinery import SourceFileLoader
    root = Path(tempfile.mkdtemp(prefix="gctl-la-"))
    def git(*a): sp.run(["git",*a],cwd=root,capture_output=True)
    git("init"); git("config","user.email","t@t"); git("config","user.name","t")
    (root/"a.kt").write_text("l1\n",encoding="utf-8")
    git("add","-A"); git("-c","user.email=t@t","-c","user.name=t","commit","-m","c1")
    (root/"a.kt").write_text("l1\nl2\n",encoding="utf-8")
    git("add","-A"); git("-c","user.email=t@t","-c","user.name=t","commit","-m","c2")
    # lumos 無 .py 副檔名 → spec_from_file_location 推不出 loader,顯式給 SourceFileLoader
    spec=U.spec_from_file_location("lm",GRAPHCTL,loader=SourceFileLoader("lm",GRAPHCTL))
    m=U.module_from_spec(spec); spec.loader.exec_module(m)
    # added 集合:c2 的 +l2 在第 2 行
    diff=sp.run(["git","diff","-U3","HEAD~1..HEAD"],cwd=root,capture_output=True,text=True).stdout
    added=m._diff_added_lines(diff)
    check("added: a.kt 第2行", added.get("a.kt")=={2}, str(added))
    # 對齊:乾淨 ..HEAD → True
    check("aligned: 乾淨 ..HEAD True", m._lint_aligned("HEAD~1..HEAD", root) is True, "")
    # 對齊:... symmetric split 不炸(右端 rsplit)
    check("aligned: ...HEAD 不炸", isinstance(m._lint_aligned("HEAD~1...HEAD", root), bool), "")
    # dirty tree → False
    (root/"a.kt").write_text("l1\nl2\nDIRTY\n",encoding="utf-8")
    check("aligned: dirty False", m._lint_aligned("HEAD~1..HEAD", root) is False, "")


def t_lint_config():
    import importlib.util as U
    from importlib.machinery import SourceFileLoader
    # lumos 無 .py 副檔名 → 顯式給 SourceFileLoader
    spec = U.spec_from_file_location("lm2", GRAPHCTL, loader=SourceFileLoader("lm2", GRAPHCTL))
    m = U.module_from_spec(spec); spec.loader.exec_module(m)

    root = Path(tempfile.mkdtemp(prefix="gctl-lc-"))
    lumos_dir = root / ".lumos"
    lumos_dir.mkdir()

    # Case 1: .kt 命中 → ["cmd1"]
    lint_json = lumos_dir / "lint.json"
    lint_json.write_text('{"kt":["cmd1"],"py":["cmd2"]}', encoding="utf-8")
    config = m._lint_load_config(root)
    check("lint_config: 讀取 .lumos/lint.json 回 dict", isinstance(config, dict), str(config))
    # added: a.kt 第 1 行
    added = {"a.kt": {1}}
    cmds = m._lint_stacks_for_diff(added, config)
    # ★2026-09-16 起回的是「命令 → 這次改到的哪幾支檔」★:只迭代它的呼叫端拿到的仍是
    # 命令清單(行為不變),而算風險那條路需要檔清單才能把真檔名送進 linter。
    check("lint_config: .kt 命中 → 只有 cmd1", list(cmds) == ["cmd1"], str(cmds))
    check("lint_config: .kt 命中 → cmd1 要檢查 a.kt", cmds["cmd1"] == ["a.kt"], str(cmds))

    # Case 2: 無宣告副檔名 .vue → []
    added_vue = {"a.vue": {1}}
    cmds_vue = m._lint_stacks_for_diff(added_vue, config)
    check("lint_config: .vue 無宣告 → 一條都不跑", not cmds_vue, str(cmds_vue))

    # Case 3: 無 .lumos/lint.json → _lint_load_config 回 None
    root2 = Path(tempfile.mkdtemp(prefix="gctl-lc2-"))
    result = m._lint_load_config(root2)
    check("lint_config: 無 lint.json → None", result is None, str(result))

    # Case 4: 多檔共享 stack → 去重,不重複 cmd
    added_multi = {"a.kt": {1}, "b.kt": {2}}
    cmds_multi = m._lint_stacks_for_diff(added_multi, config)
    check("lint_config: 多 .kt 共享 stack → 命令去重成一條", list(cmds_multi) == ["cmd1"], str(cmds_multi))
    check("★但兩支檔都要送進那條命令★(去重的是命令,不是要檢查的檔)",
          sorted(cmds_multi["cmd1"]) == ["a.kt", "b.kt"], str(cmds_multi))

    # ★把「直接迭代它拿到的是命令、而且照 first-seen 順序」釘成明文合約★
    # (r1 架構席):這支的回傳型別 2026-09-16 從清單改成對應表,有一個呼叫端
    # 沒被改到、★只是剛好因為迭代 dict 拿到的是鍵才還能動★。這種「靠語言特性剛好
    # 相容」的東西沒有測試釘住,以後動到內部就會無聲壞掉。
    config2 = {"kt": ["cmdA", "cmdB"], "py": ["cmdB", "cmdC"]}
    ordered = m._lint_stacks_for_diff({"z.kt": {1}, "a.py": {1}}, config2)
    check("★直接迭代它拿到的是命令本身★(有呼叫端就是這樣用的)",
          all(isinstance(x, str) for x in ordered), str(list(ordered)))
    check("★而且照 first-seen 順序,同一條命令只出現一次★",
          list(ordered) == ["cmdA", "cmdB", "cmdC"], str(list(ordered)))
    check("被兩個副檔名共用的那條命令,兩邊的檔都要在",
          sorted(ordered["cmdB"]) == ["a.py", "z.kt"], str(ordered))

    # Case 5: 壞 JSON → None
    lint_json.write_text("{bad json}", encoding="utf-8")
    result_bad = m._lint_load_config(root)
    check("lint_config: 壞 JSON → None", result_bad is None, str(result_bad))


def t_lint_sarif():
    import importlib.util as U, json as J
    from importlib.machinery import SourceFileLoader
    spec=U.spec_from_file_location("lm",GRAPHCTL,loader=SourceFileLoader("lm",GRAPHCTL)); m=U.module_from_spec(spec); spec.loader.exec_module(m)
    root=Path(tempfile.mkdtemp(prefix="gctl-ls-"))
    # 假 SARIF:絕對 file:// uri + per-run driver + 一筆 location-less
    sarif={"runs":[{"tool":{"driver":{"name":"detekt"}},"results":[
        {"ruleId":"R1","message":{"text":"m1"},"locations":[{"physicalLocation":{
            "artifactLocation":{"uri":f"file://{root}/app/X.kt"},"region":{"startLine":5}}}]},
        {"ruleId":"R2","message":{"text":"no-loc"}}  # location-less → 跳該筆不連坐
    ]}]}
    sf=root/"fake.sarif"; sf.write_text(J.dumps(sarif),encoding="utf-8")
    cmd=f"cp {sf} {{LINT_SARIF_OUT}}"   # 假 linter=把預存 SARIF 複製到注入路徑
    claims, ok = m._lint_run_and_parse(cmd, root)
    check("sarif ok", ok is True, "")
    check("sarif: 1 claim(location-less 跳)", len(claims)==1, str(claims))
    c=claims[0]
    check("sarif: uri 正規化 repo 相對", c["file"]=="app/X.kt", c["file"])
    check("sarif: source per-run", c["source"]=="lint:detekt", c["source"])
    check("sarif: line/rule/message", c["line"]==5 and c["rule"]=="R1" and c["message"]=="m1", str(c))
    # 指令失敗無 SARIF → ok False
    claims2, ok2 = m._lint_run_and_parse("false", root)
    check("sarif: 失敗 ok False", ok2 is False and claims2==[], "")


def t_lint_sarif_malformed_run():
    """Finding 1: 含壞 run(無 tool key)的 SARIF — 壞 run 跳過,好 run claim 仍回傳,不 crash。"""
    import importlib.util as U, json as J
    from importlib.machinery import SourceFileLoader
    spec=U.spec_from_file_location("lm2",GRAPHCTL,loader=SourceFileLoader("lm2",GRAPHCTL)); m=U.module_from_spec(spec); spec.loader.exec_module(m)
    root=Path(tempfile.mkdtemp(prefix="gctl-lsm-"))
    sarif={"runs":[
        # 壞 run:完全沒有 tool 鍵 → 應 skip 而不 crash
        {"results":[{"ruleId":"BAD","message":{"text":"bad"},"locations":[{"physicalLocation":{
            "artifactLocation":{"uri":f"file://{root}/bad.kt"},"region":{"startLine":1}}}]}]},
        # 好 run:正常 driver
        {"tool":{"driver":{"name":"detekt"}},"results":[
            {"ruleId":"R1","message":{"text":"good"},"locations":[{"physicalLocation":{
                "artifactLocation":{"uri":f"file://{root}/app/Good.kt"},"region":{"startLine":7}}}]}
        ]},
    ]}
    sf=root/"mixed.sarif"; sf.write_text(J.dumps(sarif),encoding="utf-8")
    cmd=f"cp {sf} {{LINT_SARIF_OUT}}"
    claims, ok = m._lint_run_and_parse(cmd, root)
    check("sarif malformed run: ok True(有好 run)", ok is True, "")
    check("sarif malformed run: 僅好 run 的 claim 回傳(=1)", len(claims)==1, str(claims))
    check("sarif malformed run: claim 來自好 run", claims[0]["source"]=="lint:detekt" and claims[0]["file"]=="app/Good.kt", str(claims))


def t_lint_sarif_relative_uri():
    """Finding 2: SARIF uri 已是 repo-relative(無 file://) → file 直接用,不產 ../.. 遍歷路徑。"""
    import importlib.util as U, json as J
    from importlib.machinery import SourceFileLoader
    spec=U.spec_from_file_location("lm3",GRAPHCTL,loader=SourceFileLoader("lm3",GRAPHCTL)); m=U.module_from_spec(spec); spec.loader.exec_module(m)
    root=Path(tempfile.mkdtemp(prefix="gctl-lsr-"))
    # uri 是 repo-relative(沒有 file:// 也沒有絕對路徑前綴)
    sarif={"runs":[{"tool":{"driver":{"name":"ktlint"}},"results":[
        {"ruleId":"R9","message":{"text":"rel"},"locations":[{"physicalLocation":{
            "artifactLocation":{"uri":"app/Y.kt"},"region":{"startLine":3}}}]}
    ]}]}
    sf=root/"rel.sarif"; sf.write_text(J.dumps(sarif),encoding="utf-8")
    cmd=f"cp {sf} {{LINT_SARIF_OUT}}"
    claims, ok = m._lint_run_and_parse(cmd, root)
    check("sarif relative uri: ok True", ok is True, "")
    check("sarif relative uri: 1 claim", len(claims)==1, str(claims))
    check("sarif relative uri: file=app/Y.kt(非 ../.. 遍歷)", claims[0]["file"]=="app/Y.kt", claims[0].get("file",""))
    check("sarif relative uri: 無 ../.. 前綴", not claims[0]["file"].startswith(".."), claims[0].get("file",""))


def t_pitfalls_diff():
    import json as _json, subprocess as sp
    root = Path(tempfile.mkdtemp(prefix="gctl-pfd-"))
    def git(*a): sp.run(["git", *a], cwd=root, capture_output=True)
    git("init"); git("config", "user.email", "t@t"); git("config", "user.name", "t")
    (root / "app.py").write_text("x = 1\n", encoding="utf-8")
    git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "init")
    # 新增:無 timeout 的 requests.post(資源類)+ 迴圈內 query(效能類)
    (root / "app.py").write_text(
        "import requests\n"
        "def f(ids):\n"
        "    requests.post('http://x')\n"
        "    for i in ids:\n"
        "        db.execute('SELECT 1')\n", encoding="utf-8")
    git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "c2")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    check("pitfalls --diff: rc 0(提示器)", r.returncode == 0, f"rc={r.returncode}\n{r.stderr}")
    data = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    tokens = " ".join(f"{c['pattern']}|{c['class']}" for c in data["claims"])
    check("pitfalls --diff: 命中無 timeout requests(資源)", "資源" in tokens, r.stdout)
    check("pitfalls --diff: 命中迴圈內 query(效能)", "效能" in tokens, r.stdout)
    check("pitfalls --diff: tier high", data["tier"] == "high", r.stdout)
    check("pitfalls --diff: class 用形態軸非四業務類",
          all(c["class"] in ("併發", "效能", "資源") for c in data["claims"]), r.stdout)
    check("pitfalls --diff: 每條有 line", all(isinstance(c["line"], int) for c in data["claims"]), r.stdout)
    check("pitfalls --diff: requests.post 在第 3 行", any(c["line"] == 3 for c in data["claims"]), r.stdout)
    check("pitfalls --diff: SELECT 在第 5 行", any(c["line"] == 5 for c in data["claims"]), r.stdout)
    # 純文檔 diff → tier standard
    (root / "readme.md").write_text("hello\n", encoding="utf-8")
    git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "doc")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    data = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("pitfalls --diff: .md skip → 沒程式檔 → tier light(2026-09-18 起 light 有機械來源)", data["tier"] == "light", r.stdout)
    # 測試檔內的 requests.post 不觸發(過濾繼承 _TEST_PAT)
    (root / "test_app.py").write_text("import requests\nrequests.post('http://y')\n", encoding="utf-8")
    git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "t")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    data = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("pitfalls --diff: 測試檔 skip → 沒程式檔(測試檔不需要家)→ tier light", data["tier"] == "light", r.stdout)
    # 併發寫入案: INSERT → class=併發(證第 6 條不再是死碼)
    (root / "write_op.py").write_text(
        "def store(val):\n"
        "    db.execute('INSERT INTO t VALUES(1)')\n", encoding="utf-8")
    git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "insert")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    data = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("pitfalls --diff: INSERT → class=併發(第 6 條不死碼)", any(c["class"] == "併發" for c in data["claims"]), r.stdout)
    # CJK 檔名(core.quotePath 預設 true 會八進位轉義,"+++ b/" 前綴比對全失效,
    # r2 panel major:_pitfall_diff_collect 漏帶 core.quotePath=false)
    (root / "訂單頁.py").write_text(
        "def f():\n"
        "    fh = open('x.txt')\n", encoding="utf-8")
    git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "cjk")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    data = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("pitfalls --diff: CJK 檔名命中且檔名不轉義",
          any(c["file"] == "訂單頁.py" for c in data["claims"]), r.stdout)


def t_pitfalls_diff_ignores_vendored_toolchain():
    """★消費專案的第一次提交,風險分級不得被「工具鏈自己的檔」撐成 high★。

    2026-09-10 在一個小 Vue 專案上實撞:init 會把 CLI、五支 hook 一起複製進 scripts/,
    第一次提交自然把它們一起帶進去;pitfalls 掃 diff 時逐檔命中那些檔裡的 open( 之類,
    ★整份報告 30 條沒有一條在專案自己的程式碼裡★,tier 卻被撐成 high,推送被擋,
    要求對一份不是自己寫的程式做代碼審。愈是剛接入的專案愈會撞到。

    ★但工具鏈自己的 repo 不能跳過★——在那裡 scripts/lumos 就是產品本體,
    跳過等於把這個閘整個關掉。判別鍵沿用既有慣例(skills/lumos-project-notes/SKILL.md
    只存在於來源 repo,永不複製進消費專案)。
    翻紅釘:拿掉跳過 → ②翻紅;跳過時不看是不是工具鏈本體 → ④翻紅。"""
    import json as _json, subprocess as sp
    m = _load_lumos_inproc()
    root = Path(tempfile.mkdtemp(prefix="gctl-pfvendor-"))
    def git(*a): sp.run(["git", *a], cwd=root, capture_output=True)
    def commit(m): git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", m)
    git("init")
    (root / "app.js").write_text("export const x = 1\n", encoding="utf-8")
    commit("init")

    # ① 基準線:專案自己的檔命中,照樣要報
    (root / "src").mkdir(exist_ok=True)
    (root / "src" / "mine.py").write_text("def f():\n    fh = open('x.txt')\n", encoding="utf-8")
    commit("mine")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("①專案自己的檔照樣要報", any(c["file"] == "src/mine.py" for c in d["claims"]), r.stdout)

    # ② 工具鏈自己安裝進來的檔:同樣的寫法,不得算在這個專案頭上
    (root / "scripts" / "hooks" / "claude").mkdir(parents=True, exist_ok=True)
    for rel in ("scripts/lumos", "scripts/test_lumos.py", "scripts/hooks/claude/impact-hook.py"):
        (root / rel).write_text("def f():\n    fh = open('x.txt')\n", encoding="utf-8")
    m._vendored_manifest_write(root)   # 安裝時會記下內容指紋(r3:只比檔名會被「改了工具檔」繞過)
    commit("vendored")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("②工具鏈自己安裝的檔不算這個專案的風險(沒別的程式檔 → light)",
          not d["claims"] and d["tier"] in ("standard", "light"),
          str(d.get("tier")) + " / " + str(d["claims"])[:400])

    # ③ 同一次提交裡混著兩種:只留專案自己的那條
    (root / "src" / "two.py").write_text("def g():\n    fh = open('y.txt')\n", encoding="utf-8")
    (root / "scripts" / "lumos").write_text("def f():\n    fh = open('z.txt')\n    q = open('w.txt')\n", encoding="utf-8")
    m._vendored_manifest_write(root)   # 工具更新:工具檔跟指紋清單一起換
    commit("mixed")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    files = {c["file"] for c in d["claims"]}
    check("③混著提交時只留專案自己的", files == {"src/two.py"}, str(files))

    # ③b ★專案自己改了工具裝進來的檔(指紋清單沒跟著換)→ 照樣要掃★(2026-09-10 代碼審 r3 併發資源席:
    #    只比檔名的話,把風險程式碼放進那 15 個路徑就能讓風險掃描完全看不到)
    (root / "scripts" / "hooks" / "claude" / "impact-hook.py").write_text("def f():\n    fh = open('edited.txt')\n", encoding="utf-8")
    commit("edit-vendored")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("③b 改過的工具檔(內容跟安裝時不同)照樣要掃",
          any(c["file"] == "scripts/hooks/claude/impact-hook.py" for c in d["claims"]), str(d["claims"])[:400])

    # ③c 沒有指紋清單(舊版安裝)→ 一支都不跳,寧可多掃
    rootn = Path(tempfile.mkdtemp(prefix="gctl-pfvendorn-"))
    def gitn(*a): sp.run(["git", *a], cwd=rootn, capture_output=True)
    def commitn(msg): gitn("add", "-A"); gitn("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", msg)
    gitn("init"); (rootn / "app.js").write_text("x\n", encoding="utf-8"); commitn("init")
    (rootn / "scripts").mkdir()
    (rootn / "scripts" / "lumos").write_text("def f():\n    fh = open('x.txt')\n", encoding="utf-8")
    commitn("vendored-no-manifest")
    r = run(rootn, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(rootn), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("③c 沒有指紋清單 → 工具檔照樣掃(寧可多掃)",
          any(c["file"] == "scripts/lumos" for c in d["claims"]), str(d["claims"])[:400])

    # ④ 工具鏈本體的 repo 不得跳過(那裡 scripts/lumos 就是產品)
    (root / "skills" / "lumos-project-notes").mkdir(parents=True, exist_ok=True)
    (root / "skills" / "lumos-project-notes" / "SKILL.md").write_text("# skill\n", encoding="utf-8")
    (root / "scripts" / "lumos").write_text("def f():\n    fh = open('again.txt')\n", encoding="utf-8")
    commit("selfrepo")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("④在工具鏈自己的 repo 裡,scripts/lumos 照樣要掃",
          any(c["file"] == "scripts/lumos" for c in d["claims"]), str(d["claims"])[:400])

    # ⑤ ★消費專案自己放在 scripts/hooks 底下的程式照樣要掃★(r1 四席獨立抓到的 blocker):
    # 原本照目錄前綴跳過,專案自己的 hook/樣板程式會被當成工具的檔,推送閘的風險分級被降、逃過代碼審。
    # 改成只跳過「工具確實會安裝的那幾支檔」(精確檔名清單)。
    root2 = Path(tempfile.mkdtemp(prefix="gctl-pfvendor2-"))
    def git2(*a): sp.run(["git", *a], cwd=root2, capture_output=True)
    def commit2(m): git2("add", "-A"); git2("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", m)
    git2("init"); (root2 / "app.js").write_text("x\n", encoding="utf-8"); commit2("init")
    (root2 / "scripts" / "hooks" / "claude").mkdir(parents=True)
    (root2 / "scripts" / "hooks" / "my_own_deploy.py").write_text("def f():\n    fh = open('k')\n", encoding="utf-8")
    (root2 / "scripts" / "templates").mkdir(parents=True)
    (root2 / "scripts" / "templates" / "render.py").write_text("def g():\n    fh = open('t')\n", encoding="utf-8")
    (root2 / "scripts" / "hooks" / "claude" / "impact-hook.py").write_text("def h():\n    fh = open('v')\n", encoding="utf-8")
    m._vendored_manifest_write(root2)
    commit2("own-hooks")
    r = run(root2, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root2), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    files = {c["file"] for c in d["claims"]}
    check("⑤專案自己放在 scripts/hooks、scripts/templates 的程式照樣要掃,分級照樣會變 high",
          {"scripts/hooks/my_own_deploy.py", "scripts/templates/render.py"} <= files and d["tier"] == "high",
          str(files) + " / " + str(d["tier"]))
    check("⑤工具確實安裝的那支檔(同名同路徑)才跳過",
          "scripts/hooks/claude/impact-hook.py" not in files, str(files))

    # ⑥ ★刪除行那一條路也要跳過★(r1 整合席 F2 / 正確性席 F3):工具自己的檔只有刪行時,
    # 不得觸發棧別效能題(借一支 .vue 讓題表認得;路徑用工具確實安裝的檔名才算數)
    m = _load_lumos_inproc()
    # 工具真正安裝的檔都是 .py/shell/.md,沒有一支會觸發棧別題——那樣這條就驗不到東西。
    # 所以臨時把一支 .vue 登記成「工具的檔」當替身,只為了讓刪除行那條路有東西可咬。
    # 每次動它都跟著換指紋清單(=工具自己的更新)。
    vend = "scripts/hooks/claude/h1.vue"
    saved_all = m._VENDORED_ALL
    m._VENDORED_ALL = frozenset(saved_all | {vend})
    root3 = Path(tempfile.mkdtemp(prefix="gctl-pfvendor3-"))
    def git3(*a): sp.run(["git", *a], cwd=root3, capture_output=True)
    def commit3(msg): git3("add", "-A"); git3("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", msg)
    git3("init"); (root3 / "a.txt").write_text("x\n", encoding="utf-8"); commit3("init")
    (root3 / "scripts" / "hooks" / "claude").mkdir(parents=True)
    (root3 / vend).write_text("const s = reactive({a: 1})\nconst t = 1\n", encoding="utf-8"); m._vendored_manifest_write(root3); commit3("v1")
    (root3 / vend).write_text("const t = 1\n", encoding="utf-8"); m._vendored_manifest_write(root3); commit3("v2-delete-only")
    dd = m._pitfall_diff_collect("HEAD~1..HEAD", root3, no_lint=True)
    check("⑥工具自己的檔只有刪行時,不觸發任何棧別效能題", not dd.get("stack_questions_applicable"),
          str(dd.get("stack_questions_applicable")))

    # ⑦ ★lint 那一層也要跳過★(r1 整合席 F1 / 外家找洞席 F2):宣告了 lint 的消費專案,
    # 工具自己那幾支檔的 lint 命中照樣會把分級撐成 high。對齊與不對齊兩條路都要濾。
    (root3 / "src").mkdir()
    (root3 / "src" / "mine.py").write_text("x = 1\n", encoding="utf-8")
    (root3 / vend).write_text("const t = 1\nconst z = 2\n", encoding="utf-8"); m._vendored_manifest_write(root3); commit3("v3")
    saved = {k: getattr(m, k) for k in ("_lint_load_config", "_lint_stacks_for_diff", "_lint_aligned", "_lint_run_and_parse")}
    try:
        m._lint_load_config = lambda root: {"py": ["fakelint"]}
        m._lint_stacks_for_diff = lambda added, cfg, repo_root=None: {"fakelint": []}
        m._lint_run_and_parse = lambda cmd, root: ([
            {"file": vend, "line": 2, "source": "lint:fake", "class": "lint", "question": "q"},
            {"file": "src/mine.py", "line": 1, "source": "lint:fake", "class": "lint", "question": "q"}], True)
        for aligned in (True, False):
            m._lint_aligned = lambda *a, _al=aligned: _al
            dl = m._pitfall_diff_collect("HEAD~1..HEAD", root3)
            lf = {c["file"] for c in dl["claims"] if str(c.get("source", "")).startswith("lint:")}
            check(f"⑦lint 命中:工具自己的檔要濾掉、專案自己的留著(對齊={aligned})",
                  vend not in lf and "src/mine.py" in lf, str(lf))
        # ⑧ 整支拆掉(deinit):終點上檔不在了,但起點時是原封不動的工具檔 → 刪掉的行也不觸發棧別題
        (root3 / vend).write_text("const s = reactive({a: 1})\n", encoding="utf-8"); m._vendored_manifest_write(root3); commit3("v4")
        (root3 / vend).unlink(); m._vendored_manifest_write(root3); commit3("v5-removed")
        d8 = m._pitfall_diff_collect("HEAD~1..HEAD", root3, no_lint=True)
        check("⑧拆掉原封不動的工具檔,刪掉的行不觸發棧別題", not d8.get("stack_questions_applicable"),
              str(d8.get("stack_questions_applicable")))
        # ⑨ 工具檔內容不是 UTF-8(或二進位)也要讀得動、算得出指紋(第四輪:改用既有的 git show 讀法後,
        #    文字模式解碼不了就會噴錯;現在用位元組讀)
        #    (直接驗指紋判斷那一步:整份差異裡有非 UTF-8 內容時,風險掃描讀差異那段本身就會中斷——那是另一個既有問題,
        #     見 Issues/風險掃描遇到非UTF-8內容整支中斷)
        (root3 / vend).write_bytes(b"\xff\xfe const t = 1\n"); m._vendored_manifest_write(root3); commit3("v6-bytes")
        try:
            in9, pr9 = m._vendored_state(root3, "HEAD")
            ok9 = True
        except (ValueError, OSError):
            in9, pr9, ok9 = frozenset(), frozenset(), False
        check("⑨版本裡的工具檔不是 UTF-8 也不崩潰、照樣認得是原封不動", ok9 and vend in in9, str(in9))
    finally:
        for k, v in saved.items():
            setattr(m, k, v)
        m._VENDORED_ALL = saved_all


def t_diff_readers_survive_non_utf8_content():
    """提交裡有一支內容不是 UTF-8 的檔(git 沒把它當二進位),讀 git 差異的指令都不能中斷。
    2026-09-10 代碼審第四輪撞到、2026-09-11 查清範圍:風險掃描、波及計算、派工鏡頭都用文字模式讀差異,
    解碼一丟錯就整支停——★推送檢查那邊更糟:風險掃描壞掉時是放行(fail-open),分級變成 unknown,
    「高風險要先審查」這道要求整個消失★。照刪除守衛讀差異的先例,解不了的字元換成替代字元。
    見 Issues/風險掃描遇到非UTF-8內容整支中斷。"""
    import subprocess as sp, json as _json
    root = Path(tempfile.mkdtemp(prefix="gctl-nonutf8-"))
    def git(*a): sp.run(["git", *a], cwd=root, capture_output=True)
    def commit(msg): git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", msg)
    git("init")
    (root / "src").mkdir()
    (root / "src" / "a.py").write_text("x = 1\n", encoding="utf-8")
    kb = root / "docs" / "t-knowledge" / "Systems"
    kb.mkdir(parents=True)
    (kb / "A.md").write_text("---\ntype: system\nstatus: doing\n---\n# A\n講 `src/a.py`\n", encoding="utf-8")
    commit("init")
    (root / "src" / "a.py").write_bytes(b'x = "\xff\xfe caf\xe9"\nfh = open("f")\n'
                                        b'requests.post("u")  # \xe9\n'
                                        b'deleteMe()  # caf\xe9\n')
    commit("bytes")
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, *a], capture_output=True, text=True, cwd=root)
    r = lum("pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    ok = r.returncode == 0 and "UnicodeDecodeError" not in r.stderr
    check("風險掃描不中斷", ok, r.stderr[-300:])
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0]) if ok else {}
    check("風險掃描照樣看得到那支檔的風險寫法(開檔沒關)", any(c.get("file") == "src/a.py" for c in d.get("claims", [])), str(d)[:300])
    r = lum("code-loop", "check", "--diff", "HEAD~1..HEAD", "--repo", str(root))
    out = r.stdout + r.stderr
    check("★推送檢查不再因為風險掃描壞掉而放行(fail-open)★", "fail-open" not in out and "tier=unknown" not in out, out[-300:])
    # 共用的 git 包裝(派工鏡頭讀 base 版內容、逐檔 diff 都走它)也要讀得動非 UTF-8 內容
    m = _load_lumos_inproc()
    try:
        rg = m._lens_git(root, "show", "HEAD:src/a.py")
        ok_g = rg is not None and rg.returncode == 0 and "\ufffd" in rg.stdout
    except UnicodeDecodeError:
        ok_g = False
    check("共用 git 包裝讀非 UTF-8 內容不丟錯(解不了的字元換成替代字元)", ok_g, "")
    for args in (("impact", "--diff", "HEAD~1..HEAD", "--repo", str(root)),
                 ("dispatch-lens", "HEAD~1..HEAD", "--repo", str(root), "--no-cache"),
                 ("test-layers", "--diff", "HEAD~1..HEAD", "--repo", str(root))):
        r = lum(*args)
        check(f"{args[0]} 不中斷", "UnicodeDecodeError" not in r.stderr and "Traceback" not in r.stderr, r.stderr[-300:])
    # 2026-09-11 代碼審 r1:下面兩條原本漏掉——拿掉修法測試照樣綠,等於沒有證據
    try:
        hits = m._scan_diff_for_irreversible_hints(str(root))
        ok_h = any("requests.post" in str(h) for h in hits)
    except UnicodeDecodeError:
        hits, ok_h = [], False
    check("不可逆寫法掃描讀得動非 UTF-8 內容,照樣抓到那行對外呼叫", ok_h, str(hits)[:200])
    try:
        conf = m._delguard_confidence(["deleteMe"], str(root), "docs/t-knowledge")
    except UnicodeDecodeError:
        conf = None
    check("刪除守衛的全域搜尋讀得動非 UTF-8 內容(那個名字還在用,判 low)", conf == {"deleteMe": "low"}, str(conf))
    try:
        txt = m._sp_run_text(["git", "-C", str(root), "show", "HEAD:src/a.py"])
        ok_t = "\ufffd" in txt and "deleteMe" in txt
    except UnicodeDecodeError:
        ok_t = False
    check("泛用的讀文字包裝讀得動非 UTF-8 內容(第二輪兩席抓到的漏網)", ok_t, "")


def t_git_readers_survive_non_utf8_filenames():
    """提交裡有一支檔名不是 UTF-8 的檔(例如 Big5 檔名),要 git 印原始檔名的指令都不能中斷、也不能悄悄跳過。
    2026-09-11 代碼審 r1 F1 追出來的:有好幾處刻意叫 git 不要轉義檔名(為了中文檔名),
    這時非 UTF-8 的檔名位元組會原樣吐出來,文字模式解碼一丟錯——有的整支停、有的被外層接住變成「跳過提醒」。
    這台 Mac 的檔案系統不收非 UTF-8 檔名,所以用 git 底層指令直接把檔名寫進提交,不經過磁碟。"""
    import subprocess as sp, json as _json
    root = Path(tempfile.mkdtemp(prefix="gctl-nonutf8-name-"))
    def git(*a, **kw): return sp.run(["git", *a], cwd=root, capture_output=True, **kw)
    ident = ("-c", "user.email=t@t", "-c", "user.name=t")
    git("init")
    (root / "src").mkdir()
    (root / "src" / "a.py").write_text("x = 1\n", encoding="utf-8")
    kb = root / "docs" / "t-knowledge" / "Systems"
    kb.mkdir(parents=True)
    (kb / "A.md").write_text("---\ntype: system\nstatus: doing\n---\n# A\n講 `src/a.py`\n", encoding="utf-8")
    git("add", "-A"); git(*ident, "commit", "-m", "init")
    name = b"src/\xa4\xa4\xa4\xe5.py"   # Big5 的「中文」
    def put(content):
        blob = git("hash-object", "-w", "--stdin", input=content).stdout.strip()
        sp.run([b"git", b"update-index", b"--add", b"--cacheinfo", b"100644," + blob + b"," + name],
               cwd=root, capture_output=True)
    put(b"y = 1\n"); git(*ident, "commit", "-m", "big5 name")
    (root / "src" / "a.py").write_text("x = 2\n", encoding="utf-8")
    git("add", "src/a.py")
    put(b"y = 2\n"); git(*ident, "commit", "-m", "touch both")
    raw = git("-c", "core.quotePath=false", "diff", "--name-only", "HEAD~1..HEAD").stdout
    check("基準線:差異裡真的有一支非 UTF-8 檔名", name in raw, repr(raw))
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, *a], capture_output=True, text=True, cwd=root)
    (root / ".lumos").mkdir()
    (root / ".lumos" / "test-layers.json").write_text('{"py": {"layer": "unit"}}', encoding="utf-8")
    r = lum("test-layers", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    js = [l for l in r.stdout.splitlines() if l.strip().startswith("{")]
    hits = _json.loads(js[0]).get("hits", []) if js else []
    check("test-layers 照樣給提醒(不是讀差異失敗就跳過)", bool(hits) and "失敗" not in r.stderr, r.stderr[-300:])
    r = lum("impact", "--diff", "HEAD~1..HEAD", "--repo", str(root))
    check("impact 不中斷", r.returncode == 0 and "Traceback" not in r.stderr, r.stderr[-300:])
    r = lum("cochange", "check", "--diff", "HEAD~1..HEAD", "--repo", str(root))
    check("共改檢查(挖歷史＋讀差異)跑得完(rc0,不是 git 失敗的 rc2、也不是中斷)",
          r.returncode == 0 and "Traceback" not in r.stderr, f"rc={r.returncode} {r.stderr[-300:]}")
    m = _load_lumos_inproc()
    rt = m._testmap_git(root, ["diff", "--name-only", "HEAD~1..HEAD"])
    check("測試對照表的 git 包裝讀得動(解不了的換成替代字元)", "\ufffd" in rt.stdout, repr(rt.stdout))
    # 使用者自己把 core.quotePath 關掉(中文檔名的常見設定)時,沒特別指定的呼叫也會吐原始位元組
    git("config", "core.quotePath", "false")
    a = git("rev-parse", "HEAD~1", text=True).stdout.strip()
    b = git("rev-parse", "HEAD", text=True).stdout.strip()
    try:
        ok_v, why = m._codeloop_record_valid(root, a, b)
        ok = ok_v is False and "動了代碼" in why
    except UnicodeDecodeError:
        ok, why = False, "UnicodeDecodeError"
    check("推送檢查判審查留痕還算不算數時不中斷(那段改了代碼 → 不算數)", ok, why)


def t_deinit_refuses_non_utf8_root_instead_of_guessing():
    """專案路徑不是 UTF-8 時,deinit 必須擋下,不能把路徑換成替代字元再去刪。
    2026-09-11 代碼審第三輪外家席(Codex)抓到:全面加 errors="replace" 之後,找專案根目錄那一行也被換字元,
    旁邊剛好有一個名字只差那一個字、已經裝好 Lumos 的專案,deinit --yes 就會刪掉★它的★圖譜。
    改之前這裡是解碼失敗 → 擋下,不刪任何東西;修法是恢復成嚴格解碼、並講清楚為什麼擋。
    這台 Mac 的檔案系統不收非 UTF-8 檔名,所以用假的 git 輸出模擬「專案路徑的位元組不是 UTF-8」。"""
    import subprocess as _subp, shutil as _sh, os, io, contextlib
    from unittest import mock
    m = _load_lumos_inproc()
    with tempfile.TemporaryDirectory() as d:
        base = Path(d)
        decoy = base / "p-\ufffd"          # 名字只差那一個字、已經裝好的另一個專案
        vault = decoy / "docs" / "decoy-knowledge"
        vault.mkdir(parents=True)
        (vault / "keep.md").write_text("別人的圖譜\n", encoding="utf-8")
        raw = os.fsencode(str(base)) + b"/p-\xff\n"
        def fake_check_output(*a, **k):
            return raw.decode("utf-8", k.get("errors") or "strict") if k.get("text") else raw
        removed = []
        with mock.patch.object(_subp, "check_output", side_effect=fake_check_output), \
             mock.patch.object(_sh, "rmtree", side_effect=lambda p, *a, **k: removed.append(str(p))), \
             mock.patch.object(m, "_deinit_unbar_gate", lambda *a, **k: None), \
             mock.patch.object(m, "_deinit_strip_claude", lambda *a, **k: None), \
             mock.patch.object(m, "_deinit_remove_vendored", lambda *a, **k: None):
            buf = io.StringIO()
            with contextlib.redirect_stderr(buf), contextlib.redirect_stdout(io.StringIO()):
                rc = m.cmd_deinit(yes=True)
        check("非 UTF-8 的專案路徑:deinit 擋下(rc2)", rc == 2, f"rc={rc} {buf.getvalue()[-200:]}")
        check("★旁邊那個名字只差一個字的專案,圖譜一個檔都沒被刪★", removed == [] and (vault / "keep.md").exists(), str(removed))
        check("擋下的原因講的是路徑編碼,不是「這裡不是 git 專案」", "UTF-8" in buf.getvalue(), buf.getvalue()[-200:])


def _text_git_calls_missing_errors(src):
    """回傳原始碼裡「文字模式、沒帶 errors=、而且跑的是 git 或看不出跑什麼」的子程序呼叫行號。
    看得出跑什麼=命令是字面清單(或以字面清單開頭的串接),或是同一個函式裡由這種清單指定的變數:
    第一個元素是 "git" → 要帶;是別的程式(抓網址、查 GitHub、呼叫自己)→ 不管。
    ★看不出來(命令從參數傳進來、或由函式算出來)→ 當成可能是 git,一樣要帶★——
    2026-09-11 代碼審第二輪兩席都指出:泛用包裝 _sp_run_text(cmd) 的 git 字樣只在呼叫端,
    原本「所在函式裡有沒有 git 字樣」的判法看不到它。寧可多抓,加了 errors= 對 UTF-8 正常的輸出沒有影響。"""
    import ast
    tree = ast.parse(src)
    parents = {c: n for n in ast.walk(tree) for c in ast.iter_child_nodes(n)}
    def func_of(n):
        while n in parents:
            n = parents[n]
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
                return n
        return tree
    def name_of(first, fn, depth):
        """命令清單第一個元素是哪支程式:字串照字面;變數往回找同一函式裡的字串指定;
        sys.executable 是 python / 工具自己;其他看不出來(第三輪外家席:exe = "git" 原本被當成別的程式)。"""
        if isinstance(first, ast.Constant) and isinstance(first.value, str):
            return "git" if first.value == "git" else "other"
        if isinstance(first, ast.Attribute) and first.attr == "executable":
            return "other"
        if isinstance(first, ast.Name) and depth <= 5:
            vals = [n.value for n in ast.walk(fn) if isinstance(n, ast.Assign)
                    and any(isinstance(t, ast.Name) and t.id == first.id for t in n.targets)]
            kinds = [name_of(v, fn, depth + 1) for v in vals]
            if kinds and all(k == "other" for k in kinds):
                return "other"
            return "git" if "git" in kinds else None
        return None
    def program(expr, fn, depth=0):
        """回 "git" / "other" / None(看不出來)。"""
        if depth > 5:
            return None
        if isinstance(expr, (ast.List, ast.Tuple)):
            if not expr.elts or isinstance(expr.elts[0], ast.Starred):
                return None
            return name_of(expr.elts[0], fn, depth + 1)
        if isinstance(expr, ast.BinOp) and isinstance(expr.op, ast.Add):
            return program(expr.left, fn, depth + 1)
        if isinstance(expr, ast.Name):
            found = []
            for n in ast.walk(fn):
                if isinstance(n, ast.Assign) and any(isinstance(t, ast.Name) and t.id == expr.id for t in n.targets):
                    found.append(program(n.value, fn, depth + 1))
                elif isinstance(n, (ast.For, ast.comprehension)) and isinstance(n.target, ast.Name) \
                        and n.target.id == expr.id:
                    it = n.iter
                    found.extend([program(e, fn, depth + 1) for e in it.elts]
                                 if isinstance(it, (ast.List, ast.Tuple)) else [None])
            if "git" in found:
                return "git"
            if not found or None in found:
                return None   # 參數、外層變數、算出來的:看不出來
            return "other"
        return None
    bad = []
    for n in ast.walk(tree):
        if not isinstance(n, ast.Call):
            continue
        f = n.func
        fname = f.attr if isinstance(f, ast.Attribute) else (f.id if isinstance(f, ast.Name) else None)
        if fname not in ("run", "check_output", "Popen", "call", "check_call") or not n.args:
            continue
        kw = {k.arg: k.value for k in n.keywords if k.arg}
        text = kw.get("text") or kw.get("universal_newlines")
        textish = "encoding" in kw or (text is not None and not (isinstance(text, ast.Constant) and text.value is False))
        if not textish or "errors" in kw:
            continue
        if program(n.args[0], func_of(n)) != "other":
            bad.append(n.lineno)
    return sorted(bad)


def t_every_text_mode_git_call_tolerates_undecodable_output():
    """★守衛★:工具裡每一個用文字模式讀 git 輸出的呼叫都要帶 errors=(解不了的字元換成替代字元)。
    git 的輸出會帶非 UTF-8 位元組的地方很多:檔案內容、沒轉義的檔名、舊專案的 Big5 提交訊息;
    嚴格解碼一丟錯,輕則整支停,重則被外層接住變成悄悄放行(2026-09-11 風險掃描就是這樣讓推送檢查失效)。
    逐處補、逐處找,代碼審第一輪就證明會漏(九處只釘到三處、另外漏了刪除守衛那一處),所以改成機器掃全部。
    UTF-8 正常的輸出加了 errors= 結果一模一樣,所以不設例外清單。見 Issues/風險掃描遇到非UTF-8內容整支中斷。"""
    bad = _text_git_calls_missing_errors(Path(GRAPHCTL).read_text(encoding="utf-8"))
    check("每個文字模式、跑 git 或看不出跑什麼的呼叫都帶 errors=", bad == [], f"缺的行號:{bad[:20]}")
    # 守衛自己要會翻紅:餵壞的、好的、看不出跑什麼的包裝、明確是別的程式的
    sample_bad = 'import subprocess\ndef f():\n    cmd = ["git", "log"]\n    return subprocess.run(cmd, capture_output=True, text=True)\n'
    sample_good = sample_bad.replace("text=True)", 'text=True, errors="replace")')
    check("守衛抓得到變數形式的 git 呼叫", _text_git_calls_missing_errors(sample_bad) == [4], "")
    check("帶了 errors= 就放過", _text_git_calls_missing_errors(sample_good) == [], "")
    sample_wrapper = ('import subprocess as _sp\ndef run_text(cmd):\n'
                      '    return _sp.run(cmd, capture_output=True, text=True).stdout\n'
                      'def g():\n    return run_text(["git", "show", "HEAD:x"])\n')
    check("★命令從參數傳進來的泛用包裝也抓得到★(第二輪兩席抓到的漏洞型)",
          _text_git_calls_missing_errors(sample_wrapper) == [3], str(_text_git_calls_missing_errors(sample_wrapper)))
    sample_other = ('import subprocess, sys\ndef h(args):\n'
                    '    subprocess.run(["curl", "-s", "u"], capture_output=True, text=True)\n'
                    '    subprocess.run(["gh"] + args, capture_output=True, text=True)\n'
                    '    subprocess.run([sys.executable, "x"], capture_output=True, text=True)\n')
    check("明確跑別的程式的不算", _text_git_calls_missing_errors(sample_other) == [], str(_text_git_calls_missing_errors(sample_other)))
    # 第三輪外家席:程式名稱放在變數裡(exe = "git")也要認得,不能因為開頭不是字串就當成別的程式
    sample_var_exe = ('import subprocess\ndef f():\n    exe = "git"\n    cmd = [exe, "show", "HEAD:x"]\n'
                      '    return subprocess.run(cmd, capture_output=True, text=True)\n')
    check("程式名稱放在變數裡的 git 呼叫也抓得到", _text_git_calls_missing_errors(sample_var_exe) == [5],
          str(_text_git_calls_missing_errors(sample_var_exe)))
    # ★找專案根目錄的那一行必須嚴格解碼★:那個路徑會拿去寫檔、刪檔,換成替代字元等於猜路徑
    # (第三輪外家席:換字元後可能剛好指到旁邊名字只差一個字的專案,deinit 就刪錯人的圖譜)
    # ★只看語法樹裡的字串常數,不要對每個呼叫切原始碼★:ast.get_source_segment 每次都把整份檔切一次行,
    # 對兩萬多行的工具逐個呼叫做,本機 130 秒、CI 直接超時(2026-09-11 推上去當場 CI 紅)
    import ast as _ast
    src = Path(GRAPHCTL).read_text(encoding="utf-8")
    loose = []
    for n in _ast.walk(_ast.parse(src)):
        if isinstance(n, _ast.Call) and n.args and any(
                isinstance(c, _ast.Constant) and c.value == "--show-toplevel" for c in _ast.walk(n.args[0])):
            kw = {k.arg: k.value for k in n.keywords if k.arg}
            if "text" in kw and not (isinstance(kw.get("errors"), _ast.Constant) and kw["errors"].value == "strict"):
                loose.append(n.lineno)
    check("★找專案根目錄的每一行都是嚴格解碼(解不了就擋,不換字元)★", loose == [], f"不是 strict 的行號:{loose}")


def t_vendored_state_survives_unreadable_file():
    """工具檔讀不到(權限、被鎖)時,健檢與風險掃描不能直接噴錯中斷——那支檔當成「不是原封不動」照樣掃。
    2026-09-10 代碼審 r4 邊界席(blocker):逐檔讀內容沒包例外,權限錯直接變成 Python 錯誤、推送前的檢查整支停掉。"""
    import os as _os
    m = _load_lumos_inproc()
    with tempfile.TemporaryDirectory() as d:
        root = Path(d)
        (root / "scripts").mkdir()
        f = root / "scripts" / "lumos"
        f.write_text("x\n", encoding="utf-8")
        m._vendored_manifest_write(root)
        check("基準線:讀得到時認得是原封不動", "scripts/lumos" in m._vendored_state(root)[0], "")
        _os.chmod(f, 0)
        try:
            try:
                open(f, "rb").close()
                readable = True
            except OSError:
                readable = False
            if readable:   # 以 root 身分跑時權限擋不住,後面驗不了(基準線那條照樣算數)
                return
            try:
                intact, present = m._vendored_state(root)
                ok = True
            except OSError:
                ok = False
            check("讀不到的工具檔不讓整支中斷", ok, "")
            check("讀不到的工具檔不算原封不動(照樣掃),但算存在", ok and "scripts/lumos" not in intact and "scripts/lumos" in present, "")
            r = run(root, "doctor")
            check("健檢照樣跑得完(沒有 Python 錯誤)", "Traceback" not in r.stderr, r.stderr[-300:])
        finally:
            _os.chmod(f, 0o644)


def t_vendored_file_list_matches_what_install_ships():
    """跳過清單★必須跟工具確實安裝的檔一模一樣★(r1 整合席 F5:原本另寫了一份目錄清單)。
    清單少一支 → 那支檔又會被當成專案程式掃、撐高分級;多一支 → 專案同名的檔會被靜默跳過。
    翻紅釘:在 scripts/hooks 底下多加一支受版控的檔卻不登記 → 翻紅。"""
    import subprocess as sp
    # 比的是工具鏈 repo 自己受版控的檔——在消費專案裡跑沒有意義,而且專案自己在 scripts/hooks 放檔就會假紅
    # (第三輪外家找洞席;同類事故 [[Issues/vendored自測3紅_來源repo專用測試漏標skip]])
    _need_src("skills/lumos-project-notes/SKILL.md")
    m = _load_lumos_inproc()
    repo = Path(GRAPHCTL).resolve().parent.parent
    tracked = sp.run(["git", "ls-files", *m._VENDORED_TREE_DIRS], cwd=repo,
                     capture_output=True, text=True).stdout.split()
    tracked = {t for t in tracked if "__pycache__" not in t}
    check("跳過清單 = 工具鏈 repo 裡那兩個目錄底下受版控的每一支檔",
          set(m._VENDORED_TREE_FILES) == tracked,
          f"少登記:{sorted(tracked - set(m._VENDORED_TREE_FILES))} 多登記:{sorted(set(m._VENDORED_TREE_FILES) - tracked)}")
    check("工具鏈根目錄那幾支也在清單裡", set(m._VENDORED_TOOLKIT) <= m._VENDORED_ALL, "")
    # 路徑正規化:./ 開頭、反斜線都要認得;★只比對整條路徑★,不是字首
    iv = lambda x: m._posix_norm(x) in m._VENDORED_ALL
    check("./ 開頭、反斜線寫法都認得", iv("./scripts/hooks/pre-push") and iv("scripts\\hooks\\pre-push"), "")
    check("目錄本身、同目錄的其他檔都不算", not iv("scripts/hooks") and not iv("scripts/hooks/my_own.py")
          and not iv(".scripts/hooks/pre-push"), "")
    # 指紋:換行統一後再算(Windows 換行轉換不該讓指紋對不上)
    check("指紋不受 CRLF/LF 影響", m._vendored_digest(b"a\r\nb\n") == m._vendored_digest(b"a\nb\n"), "")


def t_pitfalls_diff_ignores_data_files_and_string_literals():
    """工具鏈補強十件 #7:資料檔(.json/.jsonl…)與字串字面裡的 open(/UPDATE 不算代碼風險——
    2026-08-22 三批推送被探針結果 JSON 和 print 文字連判 high,閘被訓練成「先想怎麼 skip」。"""
    import json as _json, subprocess as sp
    root = Path(tempfile.mkdtemp(prefix="gctl-pfd7-"))
    def git(*a): sp.run(["git", *a], cwd=root, capture_output=True)
    def commit(m): git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", m)
    git("init"); (root / "app.py").write_text("x = 1\n", encoding="utf-8"); commit("init")
    # ① 資料檔帶 open( / UPDATE → 不算
    (root / "run.json").write_text('{"calls": ["open(path)", "UPDATE t SET a=1"]}\n', encoding="utf-8")
    (root / "log.jsonl").write_text('{"cmd": "requests.post(url)"}\n', encoding="utf-8")
    commit("data")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("★資料檔(.json/.jsonl)不掃 → 沒程式檔 → light★", d["tier"] == "light" and not d["claims"], r.stdout)
    # ② 字串字面裡的關鍵字 → 不算;真的 open( → 算
    (root / "app.py").write_text(
        "def f():\n"
        "    print(\"擋下:檔案 handle 有沒有 with/確定 close? open(\")\n"
        "    msg = 'UPDATE 失敗'\n", encoding="utf-8")
    commit("strings")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("★字串字面裡的 open(/UPDATE 不算★", d["tier"] == "standard" and not d["claims"], r.stdout)
    (root / "app.py").write_text("def g(p):\n    fh = open(p)\n    return fh.read()\n", encoding="utf-8")
    commit("real")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    check("真的 open( 照樣 high(反誤傷)", d["tier"] == "high" and any(c["line"] == 2 for c in d["claims"]), r.stdout)
    # 外審 major(2026-08-22):收緊後漏掃 COUNT(*) / 別名欄位 / 跨行 UPDATE → 回歸釘
    (root / "sql.py").write_text(
        "cur.execute(\"SELECT COUNT(*) FROM orders WHERE status='open'\")\n"
        "conn.execute(\"\"\"\n    UPDATE users\n    SET status = 'active'\n\"\"\")\n"
        "q = 'SELECT u.id, u.name FROM users u'\n", encoding="utf-8")
    commit("sql")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    kinds = {c["class"] for c in d["claims"]}
    check("★COUNT(*) FROM / 別名欄位 / 跨行 UPDATE 照樣抓到(反漏掃)★", d["tier"] == "high" and {"效能", "併發"} <= kinds, r.stdout[:400])
    print("  ✓ t_pitfalls_diff_ignores_data_files_and_string_literals")


def t_pitfalls_diff_arch_alignment_hints():
    """架構對齊鏡頭(2026-08-22,Enzo:自動開發不得產出跟既有不一樣或不入流的寫法):
    pitfalls --diff 對每支改動 code 檔列同層最像的既有檔當對照組+三問+慣例 skill;沒有鄰居就不印。"""
    import json as _json, subprocess as sp
    root = Path(tempfile.mkdtemp(prefix="gctl-arch-"))
    def git(*a): sp.run(["git", *a], cwd=root, capture_output=True)
    def commit(m): git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", m)
    git("init")
    svc = root / "app" / "services"; svc.mkdir(parents=True)
    (svc / "OrderService.kt").write_text("class OrderService\n", encoding="utf-8")
    (svc / "PaymentService.kt").write_text("class PaymentService\n", encoding="utf-8")
    (svc / "OrderServiceTest.kt").write_text("class OrderServiceTest\n", encoding="utf-8")
    (root / "lonely").mkdir(); (root / "lonely" / "x.py").write_text("x = 1\n", encoding="utf-8")
    commit("init")
    (svc / "RefundService.kt").write_text("class RefundService\n", encoding="utf-8")
    (root / "lonely" / "x.py").write_text("x = 2\n", encoding="utf-8")
    commit("add")
    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d = _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
    arch = d.get("arch_alignment") or {}
    sibs = arch.get("files", {}).get("app/services/RefundService.kt", [])
    check("★新 Service 的對照組=同層既有 Service(排除測試檔)★",
          "app/services/OrderService.kt" in sibs and "app/services/PaymentService.kt" in sibs
          and not any("Test" in x for x in sibs), str(arch)[:300])
    check("沒鄰居的檔不列對照", "lonely/x.py" not in arch.get("files", {}), str(arch)[:300])
    check("依副檔名附慣例 skill", "kotlin-idioms" in arch.get("idiom_skills", []), str(arch)[:300])
    r2 = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root))
    check("人讀輸出有[架構對齊]三問", "[架構對齊]" in r2.stdout and "第二種做法" in r2.stdout, r2.stdout[-500:])
    print("  ✓ t_pitfalls_diff_arch_alignment_hints")


_ARCH_NODE = "Systems/DDD目標"


def _arch_node_text(n_rules=2, superseded=True):
    rules = ["  RULE:Domain 層不依賴框架與資料庫型別,違反長怎樣是實體裡出現 ORM [依據:人] [since:2026-10-09] [retire:人裁] [until:2099-10-09]"]
    rules += [f"  RULE:第{i}條目標規則寫在這裡 [依據:人] [since:2026-10-09] [retire:人裁] [until:2099-10-09]" for i in range(2, n_rules + 1)]
    if superseded:
        rules.append("  RULE:舊規則已經作廢不准再附 [依據:人] [since:2026-01-01] [retire:人裁] [until:2099-12-31] [status:superseded] [被取代:Systems/DDD目標]")
    return ("---\ntype: system\nstatus: doing\nresponsibility: 目標架構\nsummary: |-\n" + "\n".join(rules)
            + "\n---\n# DDD目標\n")


def _arch_target_repo(cfg_text=None, node_text=None, extra=None):
    """main 上:Billing 兩支舊檔、Domain/Legacy 兩支舊檔、Domain/Order 一支舊檔、圖譜(api 節點+可選的目標節點)、可選的設定;切到 feat。
    cfg_text 是原樣寫進 .lumos/config.json 的字串(壞 JSON 也照寫)。回 (d, g, w, c, base)。"""
    d, g, w, c = _role_git_repo()
    w("app/Billing/OldBilling.py", "def old():\n    return 1\n")
    w("app/Billing/Invoice.py", "def inv():\n    return 1\n")
    w("app/Domain/Legacy/OldHelper.py", "def helper():\n    return 1\n")
    w("app/Domain/Legacy/Other.py", "def other():\n    return 1\n")
    w("app/Domain/Order/OrderOld.py", "def order_old():\n    return 1\n")
    w("docs/t-knowledge/Systems/api.md", "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:api\n---\n\n管 api。\n")
    if node_text is not None:
        w(f"docs/t-knowledge/{_ARCH_NODE}.md", node_text)
    if cfg_text is not None:
        w(".lumos/config.json", cfg_text)
    for rel, txt in (extra or {}).items():
        w(rel, txt)
    base = c("base")
    g("checkout", "-qb", "feat")
    return d, g, w, c, base


def _arch_pitfalls(d, rng, human=False):
    import json as _j
    r = run(d, "pitfalls", "--diff", rng, "--repo", str(d), *([] if human else ["--json"]))
    if human:
        return r
    lines = [l for l in r.stdout.splitlines() if l.strip().startswith("{")]
    return _j.loads(lines[0]).get("arch_alignment") or {} if lines else {"_raw": r.stdout + r.stderr}


def _arch_cfg(*items):
    import json as _j
    return _j.dumps({"arch_targets": [dict(path=p, node=n) for p, n in items]}, ensure_ascii=False)


_DDD_TEMPLATE = "skills/lumos-project-notes/commands/target-arch-ddd-template.md"


def _ddd_template_block():
    """使用說明裡 DDD 目標架構範本的節點區塊:「## 範本」那一節裡的 markdown 圍欄內容(照小節標題切,同其他讀說明檔的測試)。"""
    _need_src(_DDD_TEMPLATE)
    text = (Path(GRAPHCTL).resolve().parent.parent / _DDD_TEMPLATE).read_text(encoding="utf-8")
    section = text.split("\n## 範本\n", 1)[1].split("\n## ", 1)[0] if "\n## 範本\n" in text else ""
    body = section.split("```markdown\n", 1)[1].split("\n```", 1)[0] if "```markdown\n" in section else ""
    check("前置:「## 範本」那一節有一個 markdown 圍欄", bool(body), section[:200])
    return body


def _ddd_template_lint(text):
    v = mkvault()
    (v / "Systems" / "DDD目標架構.md").write_text(text, encoding="utf-8")
    return run(v, "lint", "Systems/DDD目標架構")


def t_arch_target_ddd_template_valid():
    """[Projects/DDD目標架構範本_計劃 S1] 範本日期佔位換成實際日期後存成節點:lint 0 問題、目標架構規則讀法讀到九條有效規則。
    翻紅釘:範本裡任一條 RULE 少了必有鍵、或規則讀法改了寫法而範本沒跟上 → 翻紅。"""
    import datetime as _dt
    block = _ddd_template_block()
    today = _dt.datetime.now(_dt.timezone.utc).astimezone().date()   # 本機日期,同 RULE 生命週期提醒的取法
    filled = block.replace("<採用日>", today.isoformat()).replace("<回頭日>", (today + _dt.timedelta(days=365)).isoformat())
    r = _ddd_template_lint(filled)
    check("S1: 換好日期後 lint 0 問題", r.returncode == 0 and "0 問題" in r.stdout, r.stdout[-500:])
    m = _load_lumos_inproc()
    rules = m._arch_target_note_rules(m._note_from_text("Systems/DDD目標架構.md", filled))
    check("S1: 讀到九條有效規則、沒有一條算過期", len(rules) == 9 and not any(e for _t, e in rules), str(rules)[:300])
    print("  ✓ t_arch_target_ddd_template_valid")


def t_arch_target_ddd_template_placeholder_warns():
    """[Projects/DDD目標架構範本_計劃 S2] 沒換日期佔位就照抄時,lint 對佔位的日期欄位印格式警告(筆記格子目前只提醒不擋)。
    翻紅釘:範本改成寫死實際日期 → 前置斷言翻紅(沒有佔位,採用的人不會被提醒換日期)。"""
    block = _ddd_template_block()
    r = _ddd_template_lint(block)
    check("前置:範本用佔位字而不是寫死日期", "<採用日>" in block and "<回頭日>" in block, block[:200])
    check("S2: lint 對佔位日期印格式警告",
          "[since:<採用日>] 日期要寫成 YYYY-MM-DD" in r.stdout and "[until:<回頭日>] 日期要寫成 YYYY-MM-DD" in r.stdout, r.stdout[-500:])
    print("  ✓ t_arch_target_ddd_template_placeholder_warns")


def t_arch_target_ddd_template_linked_from_usage():
    """[Projects/DDD目標架構範本_計劃 S3] 使用說明 06 的 arch_targets 那一列指到範本檔,找 arch_targets 用法的人看得到範本。"""
