def t_arch_target_rules_shared_parser():
    """[代碼審 r1 ARC-1] 目標規則走專案共用的摘要條目與 RULE 欄位讀法:[status:SUPERSEDED] 大寫也算作廢;
    單行寫法的 summary 也認得;until 已過的照附並加註。翻紅釘:作廢判斷不轉小寫 → ①翻紅;手拼開頭欄位、漏單行退路 → ②翻紅。"""
    node = ("---\ntype: system\nstatus: doing\nsummary: |-\n"
            "  RULE:有效規則照常附上給審查席看 [依據:人] [since:2026-10-09] [retire:人裁] [until:2099-10-09]\n"
            "  RULE:大寫作廢的規則不准附上 [依據:人] [since:2026-01-01] [retire:人裁] [until:2099-12-31] [status:SUPERSEDED] [被取代:Systems/DDD目標]\n"
            "  RULE:到期日已過的規則要加註 [依據:人] [since:2020-01-01] [retire:人裁] [until:2020-12-31]\n"
            "---\n# DDD目標\n")
    single = "---\ntype: system\nstatus: doing\nsummary: \"RULE:單行摘要寫法的規則也要認得 [依據:人] [since:2026-10-09] [retire:人裁] [until:2099-10-09]\"\n---\n# 單行\n"
    d, g, w, c, base = _arch_target_repo(_arch_cfg(("app/Domain/One/**", "Systems/單行"), ("app/Domain/**", _ARCH_NODE)), node,
                                         extra={"docs/t-knowledge/Systems/單行.md": single})
    w("app/Domain/Payment/Payment.py", "def pay():\n    return 1\n")
    w("app/Domain/One/one.py", "def one():\n    return 1\n")
    c("x")
    r, data = _arch_lens(d, "main..HEAD", "--arch-target")
    t = data.get("arch_text", "")
    check("①大寫 SUPERSEDED 也算作廢", "有效規則照常附上" in t and "大寫作廢的規則" not in t, t[:600])
    check("①until 已過的照附並加註", any("到期日已過的規則" in ln and "已過 until" in ln for ln in t.splitlines()), t[:600])
    check("②單行 summary 的規則認得", "單行摘要寫法的規則也要認得" in t, t[:600])
    rd = run(d / "docs" / "t-knowledge", "doctor")
    check("②doctor 不把單行 summary 的節點誤判成沒有規則",
          not any("Systems/單行" in ln and "沒有有效 RULE" in ln for ln in rd.stdout.splitlines()), rd.stdout[-800:])
    print("  ✓ t_arch_target_rules_shared_parser")


def t_arch_target_config_reader_cases():
    """[代碼審 r1 ARC-2/COR-8] 設定讀取走共用讀法:沒宣告 arch_targets 的專案設定檔壞掉,架構對齊段不多任何東西(逐字不變);
    宣告了但檔案不是 UTF-8 → 整份不用加警告。翻紅釘:讀不懂一律警告 → ①翻紅;用寬鬆解碼 → ②翻紅。"""
    def mk(raw_bytes):
        d, g, w, c = _role_git_repo()
        w("app/Billing/OldBilling.py", "def old():\n    return 1\n")
        (d / ".lumos").mkdir(exist_ok=True)
        (d / ".lumos" / "config.json").write_bytes(raw_bytes)
        base = c("base")
        w("app/Billing/Refund.py", "def refund():\n    return 1\n")
        c("x")
        return _arch_pitfalls(d, f"{base}..HEAD")
    plain = mk(b'{"test_profile": "python"}')
    broken = mk(b'{"test_profile": "python",}')
    check("①沒宣告、設定壞掉 → 架構對齊段跟設定正常時一樣", broken == plain, f"{broken} vs {plain}")
    latin = mk('{"arch_targets": [{"path": "app/Domain/**", "node": "Systems/DDD目標"}], "x": "é"}'.encode("utf-8").replace("é".encode("utf-8"), b"\xe9"))
    check("②宣告了但不是 UTF-8 → 警告", bool(latin.get("warnings")) and not latin.get("targets"), str(latin)[:300])
    print("  ✓ t_arch_target_config_reader_cases")


def t_arch_target_failure_not_silent():
    """[代碼審 r1 COR-7] 讀設定時 git 失敗、或目標段計算出例外,派工鏡頭要附一行固定說明,不只寫錯誤輸出(掛鉤會丟掉)。
    翻紅釘:失敗回空字串 → 兩條都翻紅。"""
    from unittest.mock import patch
    m = _load_lumos_inproc()
    d, g, w, c, base = _arch_target_repo(_arch_cfg(("app/Domain/**", _ARCH_NODE)), _arch_node_text())
    w("app/Domain/Payment/Payment.py", "def pay():\n    return 1\n")
    head = c("x")
    real = m._lens_git
    def flaky(root, *a, **k):
        return None if a and a[0] == "show" else real(root, *a, **k)
    with patch.object(m, "_lens_git", flaky):
        rules, warns = m._arch_targets_at(d, base)
    check("①git 讀不到起點版設定 → 回警告而不是當沒宣告", not rules and bool(warns), str(warns))
    def boom(*a, **k):
        raise RuntimeError("x")
    with patch.object(m, "_arch_target_split", boom):
        t = m._dispatch_lens_arch_text(f"{base}..{head}", str(d))
    check("②目標段算到一半出例外 → 附固定說明", "算不出" in t, repr(t))
    def no_catfile(root, *a, **k):
        return None if a and a[0] in ("show", "cat-file") else real(root, *a, **k)
    with patch.object(m, "_lens_git", no_catfile):
        rules, warns = m._arch_targets_at(d, base)
    check("③git 連分辨檔在不在都做不到 → 也回警告(r2 COR2-5)", not rules and bool(warns), str(warns))
    with patch.object(m, "_arch_target_split", boom):
        t = m._dispatch_lens_spec_arch_text(d, "docs/t-knowledge/", "要新增 `app/Domain/Payment/Payment.py`")
    check("④設計審目標段出例外 → 附固定說明(r2 COR2-5)", "算不出" in t, repr(t))
    print("  ✓ t_arch_target_failure_not_silent")


def t_pitfalls_diff_node_flavor_by_package_json():
    """[iOS/Node 補棧 2026-09-08]同樣是 .ts 檔,後端專案(package.json 沒前端框架)附 node 效能追問
    + node-idioms;前端專案(依賴有 vue)維持舊行為:不附 node 追問、慣例 skill 仍是 vue-idioms;
    沒有 package.json 也維持舊行為。.swift 檔附 swift 追問 + swift-idioms。
    翻紅釘:把 _stack_key_for_file 的 package.json 分流拔掉 → ①或②翻紅。"""
    import json as _json, subprocess as sp

    def mkrepo(pkg_deps, ext="ts"):
        root = Path(tempfile.mkdtemp(prefix="gctl-nodeflv-"))
        def git(*a): sp.run(["git", *a], cwd=root, capture_output=True)
        def commit(msg): git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", msg)
        git("init")
        if pkg_deps is not None:
            (root / "package.json").write_text(_json.dumps({"name": "x", "dependencies": pkg_deps}), encoding="utf-8")
        svc = root / "src" / "services"; svc.mkdir(parents=True)
        (svc / f"OrderService.{ext}").write_text("export const a = 1;\n", encoding="utf-8")
        commit("init")
        (svc / f"RefundService.{ext}").write_text("export const b = 2;\n", encoding="utf-8")
        commit("add")
        r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
        return _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])

    d_node = mkrepo({"fastify": "^5"})
    check("①後端 .ts:附 node 效能追問 + node-idioms",
          "node" in (d_node.get("stack_questions") or {}) and "node-idioms" in (d_node.get("arch_alignment") or {}).get("idiom_skills", []),
          str(d_node.get("stack_questions", {}).keys()) + str(d_node.get("arch_alignment")))
    d_vue = mkrepo({"vue": "^3"})
    check("②前端 .ts(依賴有 vue):不附 node 追問、慣例仍 vue-idioms",
          "node" not in (d_vue.get("stack_questions") or {}) and "vue-idioms" in (d_vue.get("arch_alignment") or {}).get("idiom_skills", []),
          str(d_vue.get("stack_questions", {}).keys()) + str(d_vue.get("arch_alignment")))
    d_none = mkrepo(None)
    check("③沒 package.json:舊行為(不附 node 追問、vue-idioms)",
          "node" not in (d_none.get("stack_questions") or {}) and "vue-idioms" in (d_none.get("arch_alignment") or {}).get("idiom_skills", []),
          str(d_none.get("arch_alignment")))
    d_swift = mkrepo(None, ext="swift")
    check("④.swift:附 swift 效能追問 + swift-idioms",
          "swift" in (d_swift.get("stack_questions") or {}) and "swift-idioms" in (d_swift.get("arch_alignment") or {}).get("idiom_skills", []),
          str(d_swift.get("stack_questions", {}).keys()) + str(d_swift.get("arch_alignment")))
    print("  ✓ t_pitfalls_diff_node_flavor_by_package_json")


def t_pitfalls_diff_prints_impact_lens_hint_human_only():
    """★2026-08-02:code-loop 的「派 reviewer 前跑 impact --diff 附 manifest」原本
    純紀律層、沒有任何機械提醒——當天編排者自己就忘了跑,而事後補跑第一行就是後來
    被證實違反合約的那個節點。★本測試釘住那句提示存在,而且只存在於人可讀輸出。★

    兩個斷言方向缺一不可:
    ① 人可讀輸出要有提示,★且必須帶真實的 range★(印成寫死的佔位符等於沒用——
       使用者無法直接複製貼上,提示的價值就沒了)。
    ② `--json` ★絕不能★有這行。`--json` 是 pre-push 讀 verdict 的路徑
       (scripts/hooks/pre-push:98),混進非 JSON 文字會讓解析端直接壞掉。

    ★刻意不驗的事★:不驗「impact 真的被跑了」「manifest 真的餵進 reviewer」——
    那不可觀測(派工在模型腦內),見 Projects/送審前impact鏡頭機械化_計劃 的誠實天花板。
    這條只買「提示印得出來、且沒污染 JSON」。

    ★翻紅釘★:把那行 print 拿掉 → ①翻紅;把它從 else 分支移到 as_json 分支外
    (兩邊都印)→ ②翻紅。"""
    import json as _json, subprocess as sp
    root = Path(tempfile.mkdtemp(prefix="gctl-pflens-"))
    def git(*a): sp.run(["git", *a], cwd=root, capture_output=True)
    git("init"); git("config", "user.email", "t@t"); git("config", "user.name", "t")
    (root / "app.py").write_text("x = 1\n", encoding="utf-8")
    git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "init")
    (root / "app.py").write_text("x = 2\n", encoding="utf-8")
    git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "c2")

    rng = "HEAD~1..HEAD"
    r = run(root, "pitfalls", "--diff", rng, "--repo", str(root))
    check("★前置★ 現場成立:人可讀分支真的跑到了(印得出 tier 行)",
          any(l.startswith("tier: ") for l in r.stdout.splitlines()), r.stdout)
    check("★人可讀輸出要有送審前 impact 鏡頭提示★",
          "lumos impact --diff" in r.stdout, r.stdout)
    check("★提示必須帶真實 range,不能是寫死的佔位符(否則無法直接複製)★",
          f"lumos impact --diff {rng}" in r.stdout, r.stdout)
    check("★提示要接上最後一里(2026-08-30 爆炸半徑供糧案唯一交付):跑完要貼進派工詞★",
          "貼進每一席的派工詞" in r.stdout and "貼內容不貼路徑" in r.stdout, r.stdout)

    rj = run(root, "pitfalls", "--diff", rng, "--repo", str(root), "--json")
    check("★前置★ 現場成立:--json 這一跑確實產出了 JSON",
          any(l.strip().startswith("{") for l in rj.stdout.splitlines()), rj.stdout)
    check("★--json 絕不能混進提示文字(pre-push 讀它拿 verdict,混了就解析壞)★",
          "lumos impact --diff" not in rj.stdout, rj.stdout)
    body = [l for l in rj.stdout.splitlines() if l.strip()]
    ok = True
    for l in body:
        try:
            _json.loads(l)
        except Exception:
            ok = False
    check("★--json 的每一行都必須是合法 JSON(沒有夾雜任何散文)★", ok, rj.stdout)


def t_pitfalls_spec():
    root = Path(tempfile.mkdtemp(prefix="gctl-pf-"))
    (root / ".git").mkdir()
    # 命中 payment + external-send
    md_hit = root / "hit.md"
    md_hit.write_text("# s\n## 目標\n接 stripe 收款後寄送通知。\n## 組件\n扣款流程。\n", encoding="utf-8")
    r = run(root, "pitfalls", str(md_hit), "--repo", str(root))
    check("pitfalls spec: 印通用 3 問", "併發" in r.stdout and "效能" in r.stdout and "資源" in r.stdout, r.stdout)
    check("pitfalls spec: 命中 payment 追問", "冪等" in r.stdout, r.stdout)
    check("pitfalls spec: 命中 external-send 追問", "去重" in r.stdout or "重試" in r.stdout, r.stdout)
    # --check 命中且無節 → rc 1
    r = run(root, "pitfalls", str(md_hit), "--repo", str(root), "--check")
    check("pitfalls --check: 命中無節 rc 1", r.returncode == 1, f"rc={r.returncode}\n{r.stdout}")
    # 補節 → rc 0
    md_ok = root / "ok.md"
    md_ok.write_text("# s\n## 目標\n接 stripe 收款。\n## 實務隱患\n冪等鍵用訂單號。\n", encoding="utf-8")
    r = run(root, "pitfalls", str(md_ok), "--repo", str(root), "--check")
    check("pitfalls --check: 有節 rc 0", r.returncode == 0, f"rc={r.returncode}\n{r.stdout}")
    # 零命中 → rc 0(無節也不擋)
    md_clean = root / "clean.md"
    md_clean.write_text("# s\n## 目標\n重構內部排序,無外部行為。\n## 組件\n拆函數。\n", encoding="utf-8")
    r = run(root, "pitfalls", str(md_clean), "--repo", str(root), "--check")
    check("pitfalls --check: 零命中無節 rc 0", r.returncode == 0, f"rc={r.returncode}\n{r.stdout}")
    check("pitfalls spec: 零命中只印通用問", "冪等" not in r.stdout, r.stdout)
    # 剝除:風險詞只在黑名單樣板節 → 不觸發
    md_tmpl = root / "tmpl.md"
    md_tmpl.write_text("# s\n## 目標\n" + "純內部整理。" * 20 +
                       "\n## 組件\n" + "改函數命名。" * 20 +
                       "\n## 審計修正紀錄\nr1 canary 抓到金流 stripe 扣款壞 ref。\n", encoding="utf-8")
    r = run(root, "pitfalls", str(md_tmpl), "--repo", str(root), "--check")
    check("pitfalls 剝除: 風險詞只在審計紀錄節 → --check rc 0", r.returncode == 0, f"rc={r.returncode}\n{r.stdout}")
    # md 不存在 → rc 2
    r = run(root, "pitfalls", str(root / "ghost.md"), "--repo", str(root))
    check("pitfalls: md 不存在 rc 2", r.returncode == 2, f"rc={r.returncode}")


def t_pitfalls_ask_risk_classes():
    """[已知坑機械前置 S0]pitfalls spec 模式加「反問風險類」廣度問——在場 LLM 自我分類,
    補寫死 4 類太少。①反問行出現(子字串對齊實際問句)②固定 3 問仍在③--check rc 語意不變。
    翻紅釘:拔反問行 → ①翻紅。"""
    print("t_pitfalls_ask_risk_classes")
    v = mkvault()
    root = v.parent
    md = root / "feat.md"
    md.write_text("# s\n## 目標\n前端加 refresh token 靜默續期。\n## 實務隱患\n併發見下。\n",
                  encoding="utf-8")
    r = run(root, "pitfalls", str(md), "--repo", str(root))
    check("★反問行:列出此功能碰到的風險類★", "列出此功能碰到的風險類" in r.stdout, r.stdout[:500])
    check("固定 3 問仍在(併發/效能/資源)",
          all(w in r.stdout for w in ("併發", "效能", "資源")), r.stdout[:500])
    # --check rc 語意不變(有實務隱患節 → rc0)
    rc = run(root, "pitfalls", str(md), "--repo", str(root), "--check")
    check("--check rc 語意不變(有節 rc0)", rc.returncode == 0, f"rc={rc.returncode}")


def t_pitfalls_known_pitfall():
    """[已知坑策展庫 v2]pitfalls 接 known-pitfall 節點(有 pitfall_ask+content-trigger)。
    ①白名單擴充:append pitfall_when/set pitfall_ask/pitfall_source 可用 ②spec 文本命中 corpus
    →pitfall_ask+source 攤出 ③無 pitfall_ask 的事故節點不誤觸 ④無 vault 降級=現況 ⑤--check rc 不變。
    翻紅釘:拔 vault 掃描 → ②翻紅;拔白名單擴充 → ①翻紅。★正向案用 --repo str(v)★"""
    print("t_pitfalls_known_pitfall")
    import subprocess
    v = mkvault()
    # ① 白名單:建 known-pitfall 節點(走 lumos new/append/set)
    r = run(v, "new", "system", "known-pitfall-rt")
    node = "Systems/known-pitfall-rt.md"
    ra = run(v, "append", node, "pitfall_when", "content:refresh.?token|refreshToken")
    check("★白名單:append pitfall_when 可用(非 rc2)★", ra.returncode == 0, ra.stdout + ra.stderr)
    rs1 = run(v, "set", node, "pitfall_ask", "並發 refresh:single-flight?token 輪換?")
    rs2 = run(v, "set", node, "pitfall_source", "https://owasp.org/x")
    check("★白名單:set pitfall_ask/source 可用★",
          rs1.returncode == 0 and rs2.returncode == 0, rs1.stdout + rs2.stderr)
    check("known-pitfall 節點 lint 過(含 aliases)", run(v, "lint", "known-pitfall-rt").returncode == 0, "")
    # ② 正向命中:含 refresh token 的 spec,--repo str(v)(vault 本身當 root)
    md = v / "MOC" / "feat.md"  # 放 vault 內任一位置
    md.write_text("# s\n## 目標\n前端 refreshToken 靜默續期。\n## 實務隱患\n待答。\n", encoding="utf-8")
    r = run(v, "pitfalls", str(md), "--repo", str(v))
    check("★known-pitfall 命中:pitfall_ask 攤出★", "single-flight" in r.stdout, r.stdout[:600])
    check("known-pitfall 命中:來源 URL 印出", "owasp.org" in r.stdout, r.stdout[:600])
    # ③ 無 pitfall_ask 的事故節點不誤觸
    (v / "Issues").mkdir(exist_ok=True)
    (v / "Issues" / "incid.md").write_text(
        "---\ntype: issue\nstatus: open\ncreated: 2026-08-09\nupdated: 2026-08-09\n"
        "aliases: []\npitfall_when:\n  - \"content:refreshToken\"\n"
        "tags:\n  - type/issue\nsummary: |-\n  KEY:x\n---\n# incid\n", encoding="utf-8")
    r = run(v, "pitfalls", str(md), "--repo", str(v))
    check("★無 pitfall_ask 的事故節點不誤觸(不進 known-pitfall)★",
          r.stdout.count("incid") == 0, r.stdout[:600])
    # ④ 無 vault 降級:對純 .git repo(無 vault)跑 → 不炸、無 known-pitfall
    import tempfile as _tf
    nov = Path(_tf.mkdtemp(prefix="gctl-novault-"))
    (nov / ".git").mkdir()
    md2 = nov / "s.md"
    md2.write_text("# s\n## 目標\nrefreshToken 續期。\n## 實務隱患\n待答。\n", encoding="utf-8")
    r = run(nov, "pitfalls", str(md2), "--repo", str(nov))
    check("★無 vault 降級:不炸 rc0 且無 known-pitfall 段★",
          r.returncode == 0 and "single-flight" not in r.stdout, f"rc={r.returncode}\n{r.stdout[:300]}")
    # ⑤ --check rc 語意不變(known-pitfall 命中不改 rc)
    rc = run(v, "pitfalls", str(md), "--repo", str(v), "--check")
    check("--check rc 不變(known-pitfall advisory-only)", rc.returncode == 0, f"rc={rc.returncode}")


def t_pitfalls_lint_integration():
    """Task 4: _pitfall_diff_mode 尾段整合——lint claims 合併/過濾/tier/fallback。"""
    import json as _json
    import subprocess as sp
    import sys as _sys

    # ── 共用 git fixture 建立 helper ──────────────────────────────────────
    def make_repo():
        root = Path(tempfile.mkdtemp(prefix="gctl-pli-"))
        def git(*a):
            sp.run(["git", *a], cwd=root, capture_output=True)
        git("init")
        git("config", "user.email", "t@t")
        git("config", "user.name", "t")
        return root, git

    def commit_file(root, git, name, content):
        (root / name).write_text(content, encoding="utf-8")
        git("add", "-A")
        git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", f"add {name}")

    # 寫假 linter 腳本到臨時目錄,避免 shell 引號問題
    helper_dir = Path(tempfile.mkdtemp(prefix="gctl-pli-helper-"))

    def make_linter(name, sarif_dict):
        """生成 fake linter 腳本:把 sarif 寫到 argv[1]"""
        sarif_json = _json.dumps(sarif_dict)
        script_path = helper_dir / name
        script_path.write_text(
            "import sys, json\n"
            f"data = {repr(sarif_json)}\n"
            "open(sys.argv[1], 'w').write(data)\n",
            encoding="utf-8",
        )
        return f"{_sys.executable} {script_path} {{LINT_SARIF_OUT}}"

    # SARIF 含兩個 finding: line 2 (在 diff-added) + line 99 (不在 diff-added)
    sarif_multi_dict = {
        "runs": [{
            "tool": {"driver": {"name": "FakeLint"}},
            "originalUriBaseIds": {},
            "results": [
                {
                    "ruleId": "FAKE001",
                    "message": {"text": "fake warning line 2"},
                    "locations": [{"physicalLocation": {
                        "artifactLocation": {"uri": "base.kt"},
                        "region": {"startLine": 2},
                    }}]
                },
                {
                    "ruleId": "FAKE002",
                    "message": {"text": "fake warning line 99"},
                    "locations": [{"physicalLocation": {
                        "artifactLocation": {"uri": "base.kt"},
                        "region": {"startLine": 99},
                    }}]
                },
            ]
        }]
    }
    fake_cmd = make_linter("fakelint_multi.py", sarif_multi_dict)

    # ── Case 1+2: config 存在, aligned diff ──────────────────────────────
    # base.kt: 第 1 行舊, 第 2 行新增(含 requests.get(→regex 命中), 第 3 行新增
    # diff HEAD~1..HEAD 新增行 = {2, 3}
    # .lumos/lint.json 在 init commit 提交,保持 dirty tree 清空 → aligned=True
    root, git = make_repo()
    (root / ".lumos").mkdir()
    (root / ".lumos" / "lint.json").write_text(_json.dumps({"kt": [fake_cmd]}), encoding="utf-8")
    commit_file(root, git, "base.kt", "// base\n")  # 含 .lumos 一起提交
    (root / "base.kt").write_text(
        "// base\n"
        "    val r = requests.get('http://x')\n"
        "    val x = 1\n",
        encoding="utf-8",
    )
    git("add", "-A")
    git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "add kt code")

    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    check("pitfalls-lint: rc 0", r.returncode == 0, f"rc={r.returncode}\n{r.stderr}")
    data = _json.loads(next(ln for ln in r.stdout.splitlines() if ln.strip().startswith("{")))

    sources = [c.get("source", "") for c in data["claims"]]
    # Case 1: 兩種 source 都在
    check("pitfalls-lint: lint source 出現(lint:FakeLint)",
          any("lint:FakeLint" in s for s in sources), str(data))
    check("pitfalls-lint: regex source 出現(pitfalls-builtin)",
          any(s == "pitfalls-builtin" for s in sources), str(data))

    # Case 2: aligned → line 2 保留, line 99 過濾掉
    lint_lines = [c["line"] for c in data["claims"] if "lint:" in c.get("source", "")]
    check("pitfalls-lint: aligned 過濾 line 2 保留", 2 in lint_lines, f"lint_lines={lint_lines}")
    check("pitfalls-lint: aligned 過濾 line 99 剔除", 99 not in lint_lines, f"lint_lines={lint_lines}")

    # lint_ran 有記錄 cmd
    check("pitfalls-lint: lint_ran 非空", bool(data.get("lint_ran")), str(data))
    # tier high(有 claims)
    check("pitfalls-lint: tier high", data["tier"] == "high", str(data))

    # ── Case 3: dirty tree (unaligned) → 全收 + filtered:false ──────────
    root3, git3 = make_repo()
    commit_file(root3, git3, "base.kt", "// base\n")
    (root3 / "base.kt").write_text(
        "// base\n"
        "    val r = requests.get('http://x')\n",
        encoding="utf-8",
    )
    git3("add", "-A")
    git3("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "add kt")

    # 製造 dirty tree: 新增未 commit 的改動 → _lint_aligned 回 False
    (root3 / "dirty_untracked.kt").write_text("// dirty\n", encoding="utf-8")

    sarif_line99_dict = {
        "runs": [{
            "tool": {"driver": {"name": "FakeLint"}},
            "originalUriBaseIds": {},
            "results": [{
                "ruleId": "FAKE001",
                "message": {"text": "fake warning line 99"},
                "locations": [{"physicalLocation": {
                    "artifactLocation": {"uri": "base.kt"},
                    "region": {"startLine": 99},
                }}]
            }]
        }]
    }
    fake_dirty_cmd = make_linter("fakelint_dirty.py", sarif_line99_dict)
    (root3 / ".lumos").mkdir()
    (root3 / ".lumos" / "lint.json").write_text(
        _json.dumps({"kt": [fake_dirty_cmd]}), encoding="utf-8"
    )

    r3 = run(root3, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root3), "--json")
    data3 = _json.loads([l for l in r3.stdout.splitlines() if l.strip().startswith("{")][0])
    lint_lines3 = [c["line"] for c in data3["claims"] if "lint:" in c.get("source", "")]
    check("pitfalls-lint: unaligned line 99 保留(全收)",
          99 in lint_lines3, f"lint_lines3={lint_lines3} data3={data3}")
    check("pitfalls-lint: unaligned filtered:false 標記",
          data3.get("filtered") is False, str(data3))

    # ── Case 4: 無 .lumos/lint.json → regex-only, 無 lint_ran ───────────
    root4, git4 = make_repo()
    commit_file(root4, git4, "app.py", "x = 1\n")
    (root4 / "app.py").write_text(
        "import requests\n"
        "requests.post('http://x')\n",
        encoding="utf-8",
    )
    git4("add", "-A")
    git4("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "c2")

    r4 = run(root4, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root4), "--json")
    data4 = _json.loads([l for l in r4.stdout.splitlines() if l.strip().startswith("{")][0])
    check("pitfalls-lint: 無 config → 無 lint_ran key", "lint_ran" not in data4, str(data4))
    check("pitfalls-lint: 無 config → regex claims 存在", len(data4.get("claims", [])) > 0, str(data4))

    # ── Case 5: lint cmd 失敗 → lint_skipped 記錄, rc 0, regex claims 在 ─
    root5, git5 = make_repo()
    commit_file(root5, git5, "base.kt", "// base\n")
    (root5 / "base.kt").write_text(
        "// base\n"
        "    val r = requests.get('http://x')\n",
        encoding="utf-8",
    )
    git5("add", "-A")
    git5("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "add kt")

    fail_script = helper_dir / "fakelint_fail.py"
    fail_script.write_text("import sys\nsys.exit(1)\n", encoding="utf-8")
    fail_cmd = f"{_sys.executable} {fail_script} {{LINT_SARIF_OUT}}"
    (root5 / ".lumos").mkdir()
    (root5 / ".lumos" / "lint.json").write_text(
        _json.dumps({"kt": [fail_cmd]}), encoding="utf-8"
    )

    r5 = run(root5, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root5), "--json")
    check("pitfalls-lint: cmd 失敗 rc 0", r5.returncode == 0, f"rc={r5.returncode}\n{r5.stderr}")
    data5 = _json.loads([l for l in r5.stdout.splitlines() if l.strip().startswith("{")][0])
    check("pitfalls-lint: cmd 失敗 → lint_skipped 有記錄", bool(data5.get("lint_skipped")), str(data5))
    check("pitfalls-lint: cmd 失敗 → regex claims 仍在", len(data5.get("claims", [])) > 0, str(data5))

    # ── Case 6: diff 未碰宣告棧 → lint_ran 空 ────────────────────────────
    root6, git6 = make_repo()
    commit_file(root6, git6, "readme.txt", "hello\n")
    (root6 / "readme.txt").write_text("hello world\n", encoding="utf-8")
    git6("add", "-A")
    git6("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "update txt")

    # config 只宣告 kt,但 diff 是 txt
    (root6 / ".lumos").mkdir()
    (root6 / ".lumos" / "lint.json").write_text(_json.dumps({"kt": [fake_cmd]}), encoding="utf-8")

    r6 = run(root6, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root6), "--json")
    data6 = _json.loads(next(ln for ln in r6.stdout.splitlines() if ln.strip().startswith("{")))
    check("pitfalls-lint: 未碰宣告棧 → lint_ran 空", data6.get("lint_ran") == [], str(data6))


def t_pitfalls_lint_gets_the_changed_files():
    """★算風險時,宣告的 linter 指令要真的收到「這次改了哪些檔」★
    (Issues/風險掃描的linter那隻手沒送檔進去,2026-09-16)。

    出身:宣告檔裡的指令寫著兩個佔位符,一個是「結果寫到哪」、一個是「要檢查哪些檔」。
    ★只有前者被換掉★,後者原樣送給工具,工具當場回報「找不到這個檔」。兩個方向都傷到:
    ①真問題完全看不到(工具根本沒讀到任何一支檔)②那句「找不到檔」自己被當成一條發現、
    把風險分級撐成最高級,等於為了一個工具 bug 白跑一整輪多席審查。

    ★這個洞躲過既有測試的原因★:既有 fixture 的假 linter 不使用那個佔位符,
    所以它收到什麼檔都無所謂。這支測試的假 linter ★會把自己實際收到的參數寫出來★。

    四個呼叫端裡只有算風險這一條漏換;冒煙、規則索引、新增告警閘三條都有換。

    翻紅釘:把換佔位符那一步拿掉 → 第 2、3、4 條翻紅。"""
    import json as _json
    import subprocess as sp
    import sys as _sys

    root = Path(tempfile.mkdtemp(prefix="gctl-lintfiles-"))

    def git(*a):
        sp.run(["git", *a], cwd=root, capture_output=True)
    git("init")
    git("config", "user.email", "t@t")
    git("config", "user.name", "t")

    helper = Path(tempfile.mkdtemp(prefix="gctl-lintfiles-h-")) / "recorder.py"
    got = root / "收到的參數.txt"
    # 假 linter:argv[1]=SARIF 輸出路徑,argv[2:]=它實際收到的檔清單。
    # 把收到的檔原樣記下來,並且★針對真的收到的那支檔★報一條 finding(行號 2 = 這次新增的行)。
    helper.write_text(
        "import sys, json\n"
        "out, files = sys.argv[1], sys.argv[2:]\n"
        f"open({str(got)!r}, 'w').write(repr(files))\n"
        "res = [{'ruleId': 'REAL001', 'message': {'text': '真的讀到檔了'},\n"
        "        'locations': [{'physicalLocation': {\n"
        "            'artifactLocation': {'uri': f}, 'region': {'startLine': 2}}}]}\n"
        "       for f in files]\n"
        "json.dump({'runs': [{'tool': {'driver': {'name': 'RecLint'}},\n"
        "                     'originalUriBaseIds': {}, 'results': res}]}, open(out, 'w'))\n",
        encoding="utf-8")
    cmd = f"{_sys.executable} {helper} {{LINT_SARIF_OUT}} {{LINT_FILES}}"

    (root / ".lumos").mkdir()
    (root / ".lumos" / "lint.json").write_text(_json.dumps({"kt": [cmd]}), encoding="utf-8")
    (root / "base.kt").write_text("// base\n", encoding="utf-8")
    git("add", "-A")
    git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "init")
    (root / "base.kt").write_text("// base\n    val x = 1\n", encoding="utf-8")
    git("add", "-A")
    git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "change kt")

    r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    data = _json.loads(next(ln for ln in r.stdout.splitlines() if ln.strip().startswith("{")))

    check("★前置★ 現場成立:這條宣告的指令真的跑了",
          bool(data.get("lint_ran")), str(data)[:300])
    received = got.read_text(encoding="utf-8") if got.exists() else "(檔沒被寫出來=linter 沒跑)"
    check("★linter 要收到這次真的改到的那支檔★",
          "base.kt" in received, f"它實際收到的是:{received}")
    check("★不准把佔位符原樣送出去★(送出去等於一支檔都沒檢查)",
          "LINT_FILES" not in received, f"它實際收到的是:{received}")

    claims = data.get("claims", [])
    files = [c.get("file", "") for c in claims]
    check("★工具報的問題要進得來★(收得到檔才報得出真問題)",
          any(f.endswith("base.kt") for f in files), str(claims)[:400])
    check("★不准出現檔名是佔位符字串的假發現★(那是工具在喊找不到檔,不是真問題)",
          not any("LINT_FILES" in f for f in files), str(claims)[:400])

    # ── 對不齊座標時,linter 的發現不准自己把分級撐高 ──────────────────
    # ★量出來的事實★(2026-09-16):佔位符修好、linter 真的開始讀檔之後,對不齊那條路
    # (工作目錄不乾淨、或審的是比 HEAD 舊的範圍)會把★改到的檔裡所有舊有問題★全收進來——
    # 這個 repo 實測是 1446 條,分級必定最高級。對齊時只有 3 條,而且都落在新增的行上。
    # 這條路以前無害只是因為 linter 根本沒讀到檔,現在它會讓分級永遠喊最高級。
    # ★處置★:對不齊時 linter 的發現照樣列出來(資訊不丟),但不參與分級——
    # 分級的意思是「這次改動有多risky」,而對不齊時根本分不出哪條是這次帶進來的。
    # 真正擋「新帶進來的告警」的是推送前那道閘(它比對兩份快照,跟對齊無關),不是這裡。
    (root / "dirty.txt").write_text("讓工作目錄變髒\n", encoding="utf-8")
    r2 = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
    d2 = _json.loads(next(ln for ln in r2.stdout.splitlines() if ln.strip().startswith("{")))
    check("★前置★ 現場成立:這次真的是對不齊的那條路",
          d2.get("filtered") is False, str(d2)[:300])
    check("對不齊時 linter 的發現照樣列出來(資訊不丟)",
          any("lint:" in c.get("source", "") for c in d2.get("claims", [])), str(d2)[:400])
    check("★對不齊時 linter 的發現不准自己把分級撐高★(分不出是不是這次帶進來的)",
          d2["tier"] == "standard", f"tier={d2['tier']} claims={len(d2.get('claims', []))}")

    # ── 沒有副檔名的程式檔也要被認出來 ────────────────────────────────
    # ★這個 repo 最重要的那支檔就是這種★:主程式 scripts/lumos 是 python3 但沒有 .py。
    # 專案裡早就有一支「沒有副檔名就看第一行 shebang」的函式(2026-09-13 為了這件事寫的),
    # 但算風險這條路沒用它、自己用副檔名 → 主程式對整道 linter 檢查是隱形的。
    root7 = Path(tempfile.mkdtemp(prefix="gctl-lintfiles-noext-"))

    def git7(*a):
        sp.run(["git", *a], cwd=root7, capture_output=True)
    git7("init")
    git7("config", "user.email", "t@t")
    git7("config", "user.name", "t")
    got7 = root7 / "收到的參數.txt"
    helper7 = Path(tempfile.mkdtemp(prefix="gctl-lintfiles-h7-")) / "recorder.py"
    helper7.write_text(
        "import sys, json\n"
        "out, files = sys.argv[1], sys.argv[2:]\n"
        f"open({str(got7)!r}, 'w').write(repr(files))\n"
        "json.dump({'runs': [{'tool': {'driver': {'name': 'RecLint'}},\n"
        "                     'originalUriBaseIds': {}, 'results': []}]}, open(out, 'w'))\n",
        encoding="utf-8")
    cmd7 = f"{_sys.executable} {helper7} {{LINT_SARIF_OUT}} {{LINT_FILES}}"
    (root7 / ".lumos").mkdir()
    (root7 / ".lumos" / "lint.json").write_text(_json.dumps({"py": [cmd7]}), encoding="utf-8")
    (root7 / "主程式").write_text("#!/usr/bin/env python3\nx = 1\n", encoding="utf-8")
    git7("add", "-A")
    git7("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "init")
    (root7 / "主程式").write_text("#!/usr/bin/env python3\nx = 1\ny = 2\n", encoding="utf-8")
    git7("add", "-A")
    git7("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "change")

    r7 = run(root7, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root7), "--json")
    d7 = _json.loads(next(ln for ln in r7.stdout.splitlines() if ln.strip().startswith("{")))
    check("★沒有副檔名但第一行寫了語言的程式檔,也要跑它那個棧的檢查★",
          bool(d7.get("lint_ran")), str(d7)[:300])
    got7_txt = got7.read_text(encoding="utf-8") if got7.exists() else "(linter 根本沒跑)"
    check("★而且要真的把那支檔送進去★",
          "主程式" in got7_txt, f"它實際收到的是:{got7_txt}")

    # ── 對不齊的降級只准套用在「推送閘接得住」的那種宣告 ──────────────
    # ★r1 外家席打臉★:編排者原本的理由是「真正擋新帶進來的告警的是推送前那道閘」,
    # 但★那道閘對沒有帶檔清單佔位符的宣告根本不跑★(把它降級成只報不擋)。所以那種宣告
    # 會同時失去兩邊:分級不升、推送閘也不擋。降級只能套在推送閘真的涵蓋得到的那種。
    root8 = Path(tempfile.mkdtemp(prefix="gctl-lintfiles-noplace-"))

    def git8(*a):
        sp.run(["git", *a], cwd=root8, capture_output=True)
    git8("init")
    git8("config", "user.email", "t@t")
    git8("config", "user.name", "t")
    helper8 = Path(tempfile.mkdtemp(prefix="gctl-lintfiles-h8-")) / "always.py"
    helper8.write_text(
        "import sys, json\n"
        "json.dump({'runs': [{'tool': {'driver': {'name': 'NoPlaceLint'}},\n"
        "  'originalUriBaseIds': {}, 'results': [{'ruleId': 'NP001',\n"
        "    'message': {'text': '這條宣告沒有檔清單佔位,推送閘接不住'},\n"
        "    'locations': [{'physicalLocation': {\n"
        "      'artifactLocation': {'uri': 'a.kt'}, 'region': {'startLine': 2}}}]}]}]},\n"
        "  open(sys.argv[1], 'w'))\n",
        encoding="utf-8")
    # ★刻意不帶 {LINT_FILES}★:這是合法宣告(例如直接掃整個資料夾),但推送閘不跑它
    cmd8 = f"{_sys.executable} {helper8} {{LINT_SARIF_OUT}}"
    (root8 / ".lumos").mkdir()
    (root8 / ".lumos" / "lint.json").write_text(_json.dumps({"kt": [cmd8]}), encoding="utf-8")
    (root8 / "a.kt").write_text("// base\n", encoding="utf-8")
    git8("add", "-A")
    git8("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "init")
    (root8 / "a.kt").write_text("// base\n// 第二行\n", encoding="utf-8")
    git8("add", "-A")
    git8("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "change")
    (root8 / "dirty.txt").write_text("讓工作目錄變髒\n", encoding="utf-8")

    r8 = run(root8, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root8), "--json")
    d8 = _json.loads(next(ln for ln in r8.stdout.splitlines() if ln.strip().startswith("{")))
    check("★前置★ 現場成立:這次是對不齊的那條路,而且 linter 真的報了東西",
          d8.get("filtered") is False
          and any("lint:" in c.get("source", "") for c in d8.get("claims", [])), str(d8)[:400])
    check("★沒有檔清單佔位的宣告,對不齊時仍要把分級撐高★"
          "(推送閘不跑它,這裡再放掉就兩邊都漏)",
          d8["tier"] == "high", f"tier={d8['tier']}")

    print("  ✓ t_pitfalls_lint_gets_the_changed_files")


def t_never_create_dirs_under_an_untrusted_path():
    """★不可信的路徑上連一個空資料夾都不准建★(2026-09-16 收尾)。

    出身:家目錄底下那幾個寫入點(派工鏡頭快取、武裝目錄、綁定測試快取、筆記庫寫入鎖)
    都是「先 mkdir 出整條路徑,再檢查這條路徑可不可信」。★順序反了★:檢查不過的時候,
    連結指到的地方(可能是別人的目錄)已經被建出一層空資料夾了。真正危險的動作
    (寫檔、改權限、刪目錄)確實都在檢查之後,所以以前只當成殘留記在註解裡——
    但「在別人的目錄裡留東西」本來就不該做,而且這是這幾處★共用的★缺口。

    正解是從家目錄往下逐層建、逐層檢查:每建一層就確認它是真目錄、是自己的、
    別人不可寫;任何一層不過就停手,已經建的不回頭刪(那反而是在動別人的東西)。

    翻紅釘:把逐層檢查改回一次 mkdir 整條路徑 → 第 2 條翻紅。"""
    import os as _os
    m = _lm()
    home = Path(tempfile.mkdtemp(prefix="gctl-mkdir-home-"))
    victim = Path(tempfile.mkdtemp(prefix="gctl-mkdir-victim-"))
    (home / ".cache").mkdir()
    (home / ".cache" / "lumos").symlink_to(victim)     # 中間一層換成指向別人的連結

    old_home = _os.environ.get("HOME")
    _os.environ["HOME"] = str(home)
    try:
        before = sorted(q.name for q in victim.iterdir())
        check("★前置★ 現場成立:受害者的目錄本來是空的", before == [], str(before))
        ok = m._mkdir_trusted_under_home(".cache", "lumos", "dispatch-lens")
        check("★不可信就回報失敗★", not ok, "它說可以建")
        after = sorted(q.name for q in victim.iterdir())
        check("★而且不准在連結指到的地方留下任何東西(連空資料夾都不行)★",
              after == [], f"受害者目錄多了:{after}")

        # 對照:路徑正常時照樣建得起來、而且回報成功
        (home / ".cache" / "lumos").unlink()
        ok2 = m._mkdir_trusted_under_home(".cache", "lumos", "dispatch-lens")
        made = home / ".cache" / "lumos" / "dispatch-lens"
        check("路徑正常時照樣建得起來(別把功能一起關掉)",
              ok2 and made.is_dir(), f"ok={ok2} exists={made.exists()}")
    finally:
        if old_home is not None:
            _os.environ["HOME"] = old_home

    # ── 路徑段不准帶人跳出家目錄 ──────────────────────────────────────
    # ★外家備援席(gemini)抓到★:這支函式的名字就叫「留在家目錄底下」,但 Python 的路徑
    # 接合遇到絕對路徑會★整個重置★,`..` 也照走——實測絕對路徑段直接在別的地方建出資料夾,
    # 而且回報成功。目前所有呼叫端都是寫死的字面段、利用不到,但守衛沒做到它名字說的事。
    escape = Path(tempfile.mkdtemp(prefix="gctl-mkdir-escape-"))
    _os.environ["HOME"] = str(home)
    try:
        for name, segs in (("絕對路徑段", (str(escape / "壞"),)),
                           ("上層跳脫段", ("..", "壞")),
                           ("夾了路徑分隔符", ("a/b",)),
                           ("空字串段", ("", "壞")),
                           ("單點", (".", "壞"))):
            ok = m._mkdir_trusted_under_home(*segs)
            check(f"★{name}不准放行★(這支的職責就是留在家目錄底下)", not ok, f"它說可以建")
        left = sorted(q.name for q in escape.iterdir())
        check("★而且不准在家目錄外面留下任何東西★", left == [], f"外面多了:{left}")
    finally:
        if old_home is not None:
            _os.environ["HOME"] = old_home

    print("  ✓ t_never_create_dirs_under_an_untrusted_path")


def t_stop_block_dir_does_not_touch_someone_elses_dir():
    """★收工擋停的標記目錄也不准在別人的地方留東西★(2026-09-16 補審 delta 那一輪)。

    出身:那支 hook 的註解寫著「不在別人的目錄上寫標記」,實際卻是
    ★先一次 mkdir 出整條路徑、再檢查可不可信★——上層被換成指向別處的連結時,
    別人的目錄裡已經多出一個 stop-block 資料夾了,檢查才說「不碰它」。
    跟註解自己的承諾矛盾。

    ★同一個形狀今天第五次★:主程式那邊當天剛改成逐層建逐層檢查,這支 hook 沒跟上,
    兩份判準就此不一致——而這支 hook 的說明還寫著「跟主程式同一套威脅模型」。

    翻紅釘:把逐層那道拿掉、改回一次 mkdir 整條路徑 → 第 2 條翻紅。"""
    import os as _os
    import subprocess as _sp
    hook = Path(GRAPHCTL).resolve().parent / "hooks" / "claude" / "check-graph-sync.py"
    if not hook.is_file():
        raise _SrcOnly("找不到收工檢查那支 hook(非來源 repo),這段沒驗到")
    home = Path(tempfile.mkdtemp(prefix="gctl-stopdir-home-"))
    victim = Path(tempfile.mkdtemp(prefix="gctl-stopdir-victim-"))
    (home / ".cache").mkdir()
    (home / ".cache" / "lumos").symlink_to(victim)      # 上層換成指向別人目錄的連結

    code = ("import importlib.util as U;"
            f"spec=U.spec_from_file_location('cgs', {str(hook)!r});"
            "m=U.module_from_spec(spec);\n"
            "try: spec.loader.exec_module(m)\n"
            "except SystemExit: pass\n"
            "m._stop_block_dir()\n")
    r = _sp.run([sys.executable, "-c", code],
                env={**_os.environ, "HOME": str(home)}, capture_output=True, text=True)
    check("★前置★ 現場成立:那支 hook 真的跑得起來(不然這條等於沒在驗)",
          "Traceback" not in r.stderr or "SystemExit" in r.stderr, r.stderr[-300:])
    left = sorted(q.name for q in victim.rglob("*"))
    check("★不准在連結指到的地方留下任何東西★(那支 hook 的註解自己承諾過不碰別人的目錄)",
          left == [], f"別人的目錄裡多了:{left}")

    print("  ✓ t_stop_block_dir_does_not_touch_someone_elses_dir")


def t_arm_dir_chmod_must_not_follow_a_symlink():
    """★改權限不准跟著連結走★(2026-09-16 代碼審 資安席)。

    出身:武裝目錄那處,父層改成逐層建逐層檢查了,★但葉節點那一層還是舊寫法★——
    先 mkdir、先改權限、才驗。葉節點如果在檢查之後被換成指向別人目錄的連結,
    `os.chmod` 會跟著連結把★別人目錄的權限★改掉;最後那道驗證雖然會擋下寫入,
    但權限已經動過、回不去了。

    ★誠實前提★:要同一個 OS 帳號、而且要贏一個很窄的競速窗口;同帳號本來就能直接改
    自己任何目錄的權限,所以實際多拿到的東西趨近於零。這條的價值是★完整性★——
    新函式宣稱覆蓋四個寫入點的每一層,實際漏了這一層。

    翻紅釘:把 O_NOFOLLOW 那道拿掉、改回直接 os.chmod → 第 2 條翻紅。"""
    import os as _os
    m = _lm()
    armed = Path(tempfile.mkdtemp(prefix="gctl-chmod-armed-"))
    other = Path(tempfile.mkdtemp(prefix="gctl-chmod-other-"))
    _os.chmod(other, 0o755)
    d = armed / "指紋"
    d.symlink_to(other)
    before = oct(other.stat().st_mode & 0o777)
    check("★前置★ 現場成立:別人的目錄現在是 0o755", before == "0o755", before)
    ok = m._chmod_no_follow(d, 0o700)
    after = oct(other.stat().st_mode & 0o777)
    check("★連結指到的目錄權限不准被改★", after == before, f"{before} → {after}")
    check("而且要回報失敗,不能默默當成功", not ok, "它說改成功了")

    # 對照:真的是自己的目錄時照樣改得動
    real = armed / "真目錄"
    real.mkdir(mode=0o755)
    ok2 = m._chmod_no_follow(real, 0o700)
    check("真目錄照樣改得動(別把功能一起關掉)",
          ok2 and oct(real.stat().st_mode & 0o777) == "0o700",
          f"ok={ok2} mode={oct(real.stat().st_mode & 0o777)}")

    print("  ✓ t_arm_dir_chmod_must_not_follow_a_symlink")


def t_vault_lock_message_says_the_real_reason():
    """★鎖的位置不對勁時,訊息要講對是哪一種不對勁★(2026-09-16 代碼審 資安席)。

    出身:改用逐層建之後,「決定鎖放哪」那支★已經不可能再回報「資料夾建不起來」★
    (逐層那支回的是 True/False,不再拋例外),但呼叫端還留著一整段在處理那個情況——死碼。
    而且兩種原因被混成同一句話,使用者會被叫去檢查一條其實沒有連結問題的路徑。

    行為上沒有變得比較不安全(兩種都退到同一條退路),壞的是★診斷不準★。"""
    m = _lm()
    import inspect as _i
    src = _i.getsource(m._vault_lock_where)
    check("★決定位置那支不再產出「建不起來」這種原因★(不然下面的斷言等於沒在驗)",
          "no-dir" not in src, src[-400:])
    src2 = _i.getsource(m._vault_write_lock) + _i.getsource(m._vault_lock_say)
    check("★呼叫端也不准留著處理那個情況的死碼★", "no-dir" not in src2, "還留著 no-dir 分支")

    print("  ✓ t_vault_lock_message_says_the_real_reason")


def t_vault_lock_falls_back_instead_of_giving_up():
    """★鎖的地方不可信時要換個地方鎖,不是乾脆不鎖★
    (2026-09-16 代碼審 r1 外家席)。

    出身:同一天補了「鎖檔的資料夾也要過信任檢查」,不過關就直接放行不上鎖。
    ★那是把一個安全問題換成一個正確性問題★:修之前鎖檔雖然建在不可信的地方,
    ★鎖本身仍然有效★;修之後不可信就完全沒有鎖,兩個程序可以同時做讀—改—寫,
    後寫的蓋掉先寫的。而且觸發條件不需要攻擊者——把快取目錄搬到別的磁碟這種
    正常設定就會踩到。

    正解是換一個一定屬於使用者自己的地方鎖:★筆記庫自己★。要寫的就是它,
    使用者一定擁有它,而且兩個程序算出來的路徑一樣,互斥照樣成立。

    翻紅釘:把退路拿掉、改回「不可信就直接 yield」→ 第 3、4 條翻紅。"""
    import os as _os
    m = _lm()
    v = mkvault()
    home = Path(tempfile.mkdtemp(prefix="gctl-lock-home-"))
    victim = Path(tempfile.mkdtemp(prefix="gctl-lock-victim-"))
    (home / ".cache").mkdir()
    (home / ".cache" / "lumos").symlink_to(victim)      # 中間一層換成指向別處的連結

    old_home = _os.environ.get("HOME")
    _os.environ["HOME"] = str(home)
    try:
        check("★前置★ 現場成立:那條路徑的信任檢查真的不過",
              not m._trusted_private_dir(Path.home() / ".cache" / "lumos" / "vault-lock",
                                         ".cache", "lumos", "vault-lock"), "")
        seen = []
        with m._vault_write_lock(v):
            # 鎖拿著的時候,找找看鎖檔到底落在哪
            seen = [str(q) for q in Path(v).rglob("*.lock")] + \
                   [str(q) for q in victim.rglob("*.lock")]
        check("★不可信時不准把鎖檔寫進連結指到的地方★",
              not any(str(victim) in s for s in seen), str(seen))
        check("★但還是要有鎖★(沒有鎖=兩個程序互相蓋掉修改,比原本更糟)",
              any(str(v) in s for s in seen), f"一個鎖檔都沒有:{seen}")
        # ★真的巢狀,不是前後兩個區塊★(r2 修正差異席):上一版寫成兩個不重疊的 with,
        # 根本沒測到巢狀——而退路分支剛好把可重入的鍵算錯,真巢狀會卡滿 60 秒才拋
        # 「別的程序在寫」這句假訊息。用短逾時代替 60 秒,卡住就當場失敗而不是讓整套測試停擺。
        import signal as _sig

        def _boom(_s, _f):
            raise TimeoutError("巢狀拿同一把鎖卡住了(可重入判斷沒認出是自己)")
        _old = _sig.signal(_sig.SIGALRM, _boom)
        _sig.alarm(8)
        try:
            with m._vault_write_lock(v):
                with m._vault_write_lock(v):       # ← 外層還沒退出,內層再拿一次
                    pass
            check("★同一個程序真巢狀拿同一把鎖不會卡死自己★(退路換了位置,可重入的鍵要跟著換)",
                  True, "")
        except TimeoutError as e:
            check("★同一個程序真巢狀拿同一把鎖不會卡死自己★(退路換了位置,可重入的鍵要跟著換)",
                  False, str(e))
        except RuntimeError as e:
            check("★同一個程序真巢狀拿同一把鎖不會卡死自己★(退路換了位置,可重入的鍵要跟著換)",
                  False, f"拋了假訊息:{e}")
        finally:
            _sig.alarm(0)
            _sig.signal(_sig.SIGALRM, _old)
    finally:
        if old_home is not None:
            _os.environ["HOME"] = old_home

    print("  ✓ t_vault_lock_falls_back_instead_of_giving_up")


def t_smoke_says_no_files_instead_of_crying_broken():
    """★棧裡一支檔都沒有時,冒煙要說「沒檔可驗」,不准說「命令壞了」★
    (2026-09-16 代碼審 r1 單reviewer 席)。

    出身:同一天為了修「linter 從沒真的檢查過」,在執行入口加了一道 fail-closed
    ——命令裡還留著檔清單佔位符就不跑。對它要修的那條路(算風險)是對的,
    ★但冒煙驗收那條路原本就刻意設計成「這個棧一支檔都沒有時把命令原樣送出去,
    只驗命令本身跑不跑得動」★,於是變成保證失敗。

    ★而且假警報的內容還是錯的診斷★:回「task 不存在/工具沒裝?」,而工具完全正常,
    只是專案裡還沒有那個副檔名的檔。這正是「剛裝好宣告、還沒寫第一支檔」這個最常見的
    驗收時序,也跟這批改動要修的原始症狀同一族(明明是好的卻被判壞)。

    翻紅釘:把「沒檔可驗就別跑」那段拿掉 → 第 2、3 條翻紅。"""
    import json as _json
    import subprocess as sp
    import sys as _sys

    root = Path(tempfile.mkdtemp(prefix="gctl-smoke-nofiles-"))

    def git(*a):
        sp.run(["git", *a], cwd=root, capture_output=True)
    git("init")
    git("config", "user.email", "t@t")
    git("config", "user.name", "t")
    helper = Path(tempfile.mkdtemp(prefix="gctl-smoke-h-")) / "always_ok.py"
    helper.write_text(
        "import sys, json\n"
        "json.dump({'runs': [{'tool': {'driver': {'name': 'OkLint'}},\n"
        "                     'originalUriBaseIds': {}, 'results': []}]}, open(sys.argv[1], 'w'))\n",
        encoding="utf-8")
    cmd = f"{_sys.executable} {helper} {{LINT_SARIF_OUT}} {{LINT_FILES}}"
    (root / ".lumos").mkdir()
    (root / ".lumos" / "lint.json").write_text(_json.dumps({"kt": [cmd]}), encoding="utf-8")
    git("add", "-A")
    git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "init")

    # 現場:宣告好好的、工具好好的,就是還沒有任何一支 .kt
    r = run(root, "lint-check", "--smoke", "--repo", str(root), "--json")
    out = _json.loads(next(ln for ln in r.stdout.splitlines() if ln.strip().startswith("{")))
    probs = out.get("problems", [])
    check("★前置★ 現場成立:這個專案真的一支 kt 都沒有",
          not list(root.glob("*.kt")), str(list(root.glob("*.kt"))))
    check("★不准說命令壞了★(工具好好的,只是沒檔可驗)",
          not any("跑不出可解析" in pr.get("issue", "") for pr in probs), str(probs))
    check("★也不准假裝驗過了★:要講出「這個棧還沒有檔」",
          r.returncode == 0 or any("沒有" in pr.get("issue", "") for pr in probs),
          f"rc={r.returncode} problems={probs}")

    # 對照:有檔的時候照常真跑、照常通過
    (root / "a.kt").write_text("// x\n", encoding="utf-8")
    r2 = run(root, "lint-check", "--smoke", "--repo", str(root), "--json")
    out2 = _json.loads(next(ln for ln in r2.stdout.splitlines() if ln.strip().startswith("{")))
    check("有檔的時候照常驗、照常通過(別把冒煙整個關掉)",
          out2.get("problems") == [], str(out2))

    print("  ✓ t_smoke_says_no_files_instead_of_crying_broken")


def t_closing_fence_must_not_carry_a_language_tag():
    """★收尾圍欄不准帶語言標記★(2026-09-16 代碼審 r1 外家席)。

    出身:全檔唯一那支剝圍欄實作,判「這行關不關得掉圍欄」時只看「同一個字元、長度夠」,
    ★沒看後面還有沒有東西★。CommonMark 規定收尾圍欄不得帶語言標記,所以巢狀範例裡的
    `~~~python` 其實還在外層圍欄裡面,它卻拿來把圍欄關掉——結果貼在範例裡的樣板文字
    變成「看得見」,被下游當成真的宣告。

    ★改這支之前先量過影響面★:把判定改嚴之後對整個圖譜 537 篇逐篇比對「看得見哪些行」,
    只有 1 篇結果會變(一篇 markdown 範例裡包了 yaml 區塊的計劃筆記),而且那篇★改嚴才是對的★
    ——照 CommonMark,那個 yaml 區塊本來就算在外層範例裡面。

    翻紅釘:把「後面必須只有空白」那個條件拿掉 → 第 2、3 條翻紅。"""
    m = _lm()
    vis = m._visible_lines

    def seen(txt):
        return [ln for _no, ln in vis(txt.rstrip("\n").split("\n"))]

    plain = "一般散文\n```\n程式碼\n```\n後面的散文\n"
    check("★前置★ 現場成立:正常成對的圍欄照舊被剝掉,前後散文照舊看得見",
          seen(plain) == ["一般散文", "後面的散文"], str(seen(plain)))
    tagged_close = "~~~\n```\n~~~python\n藏在範例裡的字\n```\n~~~\n"
    check("★帶語言標記的那行不能把圍欄關掉★(它其實是範例內容)",
          "藏在範例裡的字" not in seen(tagged_close), str(seen(tagged_close)))
    check("整段範例都該被剝掉,一行都不該漏出來",
          seen(tagged_close) == [], str(seen(tagged_close)))
    open_tag = "```python\n程式碼\n```\n後面\n"
    check("開頭圍欄帶語言標記是合法的,別一起改壞",
          seen(open_tag) == ["後面"], str(seen(open_tag)))
    trailing_ws = "```\n程式碼\n```   \n後面\n"
    check("收尾圍欄後面只有空白照樣算收尾", seen(trailing_ws) == ["後面"], str(seen(trailing_ws)))

    # ★收緊之後不准讓打錯字變成災難★(r2 修正差異席):嚴格讀法(收尾不得帶任何東西)
    # 比題目寬——題目是「語言標記」,但打錯一個字、多敲一鍵也會變成「關不掉」,
    # 後面到檔尾所有內容★包含合約行★全部無聲隱形。這正是這支函式自己警告過的最危險模式,
    # 換個門重新長出來。做法:先照規格讀;規格讀出「有圍欄一直沒關到檔尾」才退回寬鬆讀法。
    typo = "前面\n```\n程式碼\n```x\n中間的真內容\n★INVARIANT★ 不能破壞的規則\n後面\n"
    got = seen(typo)
    check("★收尾打錯字不准讓後面整段消失★(合約行消失是這裡最嚴重的失敗模式)",
          "★INVARIANT★ 不能破壞的規則" in got, str(got))
    check("打錯字那種情況,前後的散文都要看得見",
          got == ["前面", "中間的真內容", "★INVARIANT★ 不能破壞的規則", "後面"], str(got))
    # 但退回寬鬆只在「規格讀法讀不完」時才發生:巢狀那題規格讀得完,照樣要擋得住偽造
    check("巢狀那題規格讀得完,不會因為有退路就被放水",
          seen(tagged_close) == [], str(seen(tagged_close)))

    print("  ✓ t_closing_fence_must_not_carry_a_language_tag")


def t_intake_declaration_uses_shared_fence_stripping():
    """★前掃留痕的宣告行判定要走全檔唯一那支剝圍欄實作★
    (2026-09-16 同族掃描 B 類)。

    出身:那支判定自己寫了一個 ````…```` 的正則,而專案裡早就有一支「全檔唯一的
    圍欄判定」——它的說明白紙黑字寫著「所有人都必須走這裡」,因為自己寫的正則有兩個
    致命假設(圍欄一定成對、標記一定在第 0 欄)。這處沒走,於是兩邊對同一段文字給出
    不同答案。

    ★後果★:這個宣告行是用來觀測「首輪前掃到底有沒有真的跑過」的(處置閘印它、
    體檢的滾動窗也數它,兩邊都只觀測不擋)。把樣板原樣貼進圍欄裡就算數的話,
    那個觀測數字就不再代表任何事——而那支判定的說明自己就寫著要防「模板照抄即偽造」。

    翻紅釘:改回自己寫的正則 → 第 2、3 條翻紅。"""
    m = _lm()
    decl, vis = m._intake_declared, m._visible_lines

    def visible(txt):
        return any("preflight-4:" in str(ln) for _no, ln in vis(txt.split("\n")))

    plain = "preflight-4: ran\n"
    check("★前置★ 現場成立:沒被圍欄包住時兩邊都算數",
          decl(plain) and visible(plain), "")
    nested = "````\n```\npreflight-4: ran\n````\n"
    check("★四個反引號外層、三個反引號內層:貼在裡面的樣板不算數★",
          not decl(nested), f"共用那支的答案是 {visible(nested)}")
    tilde = "~~~\npreflight-4: ran\n~~~\n"
    check("★波浪號也是圍欄:貼在裡面的樣板不算數★",
          not decl(tilde), f"共用那支的答案是 {visible(tilde)}")
    fenced = "```\npreflight-4: ran\n```\n"
    check("三個反引號包住的照樣不算數(原本就對,別改壞)", not decl(fenced), "")

    print("  ✓ t_intake_declaration_uses_shared_fence_stripping")


def t_lint_files_substitution_has_one_implementation():
    """★「要檢查哪些檔」的替換只准有一份實作★
    (Issues/風險掃描的linter那隻手沒送檔進去,2026-09-16)。

    出身:這件事原本在四個地方各寫一次,★算改動風險那一條漏了★,於是那條路等於從來
    沒檢查過任何一支檔。抽成共用函式之後我在註解裡寫了「唯一實作,不會再漏第四個地方」
    ——同族掃描當場打臉:另外兩處(冒煙、規則索引核對)還是各自手寫一份,那句話名不副實。

    ★這條測試就是那句話的機械保證★:除了共用函式自己那一行,整支程式不准再有別人
    直接對這個佔位符做替換。純字串檢查,便宜而且擋得住未來的分裂。"""
    # ★用語法樹找,不要用字串比對★(r1 架構席:字串比對版拆成多行、換個寫法、
    # 多一個空白就繞過去了,「機械保證」四個字名不副實)。這裡走 ast:找所有
    # 「拿那個佔位符去做替換」的呼叫,不管它寫成幾行、縮排怎麼排。
    import ast as _ast
    src = (Path(__file__).resolve().parent / "lumos").read_text(encoding="utf-8")
    tree = _ast.parse(src)

    def _mentions_token(node):
        for sub in _ast.walk(node):
            if isinstance(sub, _ast.Name) and sub.id == "_LINT_NEW_FILES_TOKEN":
                return True
            if isinstance(sub, _ast.Constant) and sub.value == "{LINT_FILES}":
                return True
        return False

    # ★改成白名單制★(r2 修正差異席):上一版只找「直接把佔位符當參數丟給 replace」的呼叫,
    # 而 r1 明明示範過「先賦值給變數再用」這招——實測它完全沒防住,我卻在註解裡寫了
    # 「拿變數繞也擋得住」。這是同一個毛病第三次:把守衛的能力講得比實際寬。
    # 白名單制不看你怎麼寫,只看★哪些函式碰得到這個佔位符★:名單外的函式只要提到它就紅,
    # 逼人當場說明為什麼要碰。
    ALLOWED = {
        "_lint_cmd_with_files",   # 唯一准做替換的那支
        "_lint_run_and_parse",    # 只做「還沒換掉就別跑」的檢查
        "_lintcheck_smoke_cmd",   # 只做「這條命令要不要換檔」的檢查
        "cmd_rule_check",         # 只做同樣的檢查
        "_lint_new_verdict",      # 只做同樣的檢查
        "_pitfall_diff_collect",  # 只做「這條命令推送閘接不接得住」的檢查
    }
    touchers = {}
    for fn in _ast.walk(tree):
        if not isinstance(fn, (_ast.FunctionDef, _ast.AsyncFunctionDef)):
            continue
        if _mentions_token(fn):
            touchers[fn.name] = True
    check("★前置★ 現場成立:白名單裡的函式真的都還在(名單過期了這條就等於沒在驗)",
          ALLOWED <= set(touchers), f"名單裡有幾支已經不碰它了:{sorted(ALLOWED - set(touchers))}")
    check("★名單外的函式不准碰這個佔位符★"
          "(要換檔就呼叫共用那支;真的需要碰,先把函式名加進這份名單並寫清楚為什麼)",
          set(touchers) <= ALLOWED, f"名單外碰到它的:{sorted(set(touchers) - ALLOWED)}")

    subs = []          # 名單內的那幾支裡面,真的做替換的有幾處
    for fn in _ast.walk(tree):
        if not isinstance(fn, (_ast.FunctionDef, _ast.AsyncFunctionDef)):
            continue
        for call in _ast.walk(fn):
            if not isinstance(call, _ast.Call):
                continue
            f = call.func
            name = f.attr if isinstance(f, _ast.Attribute) else getattr(f, "id", "")
            if name in ("replace", "sub") and any(_mentions_token(a) for a in call.args):
                subs.append((fn.name, call.lineno))
    check("★真的動手替換的只准有一處,而且在共用函式裡★",
          len(subs) == 1 and subs[0][0] == "_lint_cmd_with_files", str(subs))
    # ★這條買到什麼、沒買到什麼★:白名單擋得住「新開一支函式自己做替換」,不管它寫成幾行、
    # 用不用變數、用 replace 還是 re.sub。擋不住「在名單內的函式裡多做一次替換」
    # (第三條斷言接住直接寫的那種,但同樣用變數繞就看不到)、也擋不住 getattr 取方法。
    # 不宣稱密不透風——上一版就是因為宣稱過頭被抓。

    # 共用函式的行為本身也釘一下:沒有佔位符照原樣、檔清單空的照原樣、多檔各自跳脫
    m = _lm()
    f = m._lint_cmd_with_files
    check("沒有那個佔位符的指令原樣回傳(掃整個資料夾的宣告是合法的)",
          f("lint --all {LINT_SARIF_OUT}", ["a.py"]) == "lint --all {LINT_SARIF_OUT}", "")
    check("檔清單是空的就原樣回傳(塞空字串進去等於叫工具檢查空檔名)",
          f("lint {LINT_FILES}", []) == "lint {LINT_FILES}", "")
    check("★多支檔要各自跳脫再以空白相接★(整串一起跳脫會把好幾個路徑黏成一個參數)",
          f("lint {LINT_FILES}", ["a b.py", "c.py"]) == "lint 'a b.py' c.py",
          f("lint {LINT_FILES}", ["a b.py", "c.py"]))

    print("  ✓ t_lint_files_substitution_has_one_implementation")


def t_lint_watch_semver():
    import importlib.util as U
    from importlib.machinery import SourceFileLoader
    spec = U.spec_from_file_location("lm", GRAPHCTL, loader=SourceFileLoader("lm", GRAPHCTL))
    m = U.module_from_spec(spec); spec.loader.exec_module(m)
    # _semver_parse
    check("parse 1.23.7", m._semver_parse("1.23.7") == (1,23,7), str(m._semver_parse("1.23.7")))
    check("parse v 前綴剝除", m._semver_parse("v1.2.3") == (1,2,3), str(m._semver_parse("v1.2.3")))
    check("parse 非數字段→None", m._semver_parse("1.x.3") is None, str(m._semver_parse("1.x.3")))
    # _is_prerelease 正例
    for v in ["1.24.0-RC1","0.5.0b1","2.22.0.dev20260702"]:
        check(f"prerelease True {v}", m._is_prerelease(v) is True, v)
    # _is_prerelease 負例(不可假陽性)
    for v in ["1.24.0","5.0.2.4997","cobra"]:
        check(f"prerelease False {v}", m._is_prerelease(v) is False, v)
    # _compare_versions 三態
    check("behind", m._compare_versions("1.23.7","1.24.0") == ("behind",""), str(m._compare_versions("1.23.7","1.24.0")))
    check("current(反向)", m._compare_versions("1.24.0","1.23.7")[0] == "current", str(m._compare_versions("1.24.0","1.23.7")))
    check("current(相等)", m._compare_versions("1.2.3","1.2.3")[0] == "current", "")
    check("skip unparseable", m._compare_versions("1.x","1.2.3") == ("skip","unparseable"), str(m._compare_versions("1.x","1.2.3")))
    check("skip prerelease", m._compare_versions("1.0.0","1.1.0-RC1") == ("skip","prerelease"), str(m._compare_versions("1.0.0","1.1.0-RC1")))
    check("skip 段數不一(calendar)", m._compare_versions("1.23.7","2024.1") == ("skip","segment-count-mismatch"), str(m._compare_versions("1.23.7","2024.1")))
    check("skip 段數不一(4段maven)", m._compare_versions("5.0.1","5.0.1.3006") == ("skip","segment-count-mismatch"), "")
    # 數值排序見證(同段數,證非字串比較:字串 '1.9.0' > '1.20.0' 但數值應 behind)
    check("數值 behind 1.9.0→1.20.0", m._compare_versions("1.9.0","1.20.0") == ("behind",""), str(m._compare_versions("1.9.0","1.20.0")))


def t_lint_watch_registry():
    import importlib.util as U, json as J, os, tempfile
    from importlib.machinery import SourceFileLoader
    spec = U.spec_from_file_location("lm", GRAPHCTL, loader=SourceFileLoader("lm", GRAPHCTL))
    m = U.module_from_spec(spec); spec.loader.exec_module(m)
    # 四型 registry 的假 response,key = _registry_latest 內部組出的 url
    pypi_url = "https://pypi.org/pypi/ruff/json"
    npm_url  = "https://registry.npmjs.org/eslint/latest"
    gh_url   = "https://api.github.com/repos/detekt/detekt/releases/latest"
    import urllib.parse as UP
    mvn_url  = ("https://search.maven.org/solrsearch/select?q="
               + UP.quote('g:"org.sonarsource.scanner.cli" AND a:"sonar-scanner-cli"')
               + "&core=gav&sort=timestamp+desc&rows=20&wt=json")
    fixture = {
        pypi_url: {"info": {"version": "0.4.9"}},
        npm_url:  {"version": "9.0.0"},
        gh_url:   {"tag_name": "v1.24.0"},
        # maven docs 含 3.9 / 3.20.0 / 一個 RC → 過濾 RC、數值 max 應回 3.20.0
        mvn_url:  {"response": {"docs": [
            {"v": "3.9"}, {"v": "3.20.0"}, {"v": "3.21.0-RC1"}, {"v": "3.11"}]}},
    }
    fx = Path(tempfile.mkdtemp(prefix="gctl-lw-")) / "fx.json"
    fx.write_text(J.dumps(fixture), encoding="utf-8")
    os.environ["LUMOS_LINT_WATCH_FIXTURE"] = str(fx)
    try:
        check("pypi", m._registry_latest("pypi:ruff") == ("0.4.9", None), str(m._registry_latest("pypi:ruff")))
        check("npm", m._registry_latest("npm:eslint") == ("9.0.0", None), str(m._registry_latest("npm:eslint")))
        check("github 剝 v", m._registry_latest("github:detekt/detekt") == ("1.24.0", None), str(m._registry_latest("github:detekt/detekt")))
        check("maven 數值 max 過濾 RC",
              m._registry_latest("maven:org.sonarsource.scanner.cli:sonar-scanner-cli") == ("3.20.0", None),
              str(m._registry_latest("maven:org.sonarsource.scanner.cli:sonar-scanner-cli")))
        # pypi info.version 為 prerelease → (None, "latest is prerelease")
        fixture[pypi_url] = {"info": {"version": "0.4.3a1"}}
        fx.write_text(J.dumps(fixture), encoding="utf-8")
        check("pypi prerelease", m._registry_latest("pypi:ruff") == (None, "latest is prerelease"), str(m._registry_latest("pypi:ruff")))
        # 抓取回 None(fixture 無此 key)→ (None, "registry query failed: ...")
        latest, reason = m._registry_latest("npm:does-not-exist")
        check("抓取失敗", latest is None and reason.startswith("registry query failed"), f"{latest},{reason}")
    finally:
        os.environ.pop("LUMOS_LINT_WATCH_FIXTURE", None)


def t_lint_watch_cli():
    import subprocess as sp, json as J, os, tempfile
    root = Path(tempfile.mkdtemp(prefix="gctl-lwcli-"))
    (root / ".lumos").mkdir()
    watch = [
        {"name":"ruff","registry":"pypi:ruff","current":"0.4.2"},        # behind
        {"name":"eslint","registry":"npm:eslint","current":"9.0.0"},     # current(相等)
        {"name":"cal","registry":"npm:cal","current":"1.23.7"},          # skip(段數不一 2024.1)
        {"name":"down","registry":"npm:down","current":"0.0.0"},         # fetch 失敗→failed
    ]
    (root / ".lumos" / "lint-watch.json").write_text(J.dumps(watch), encoding="utf-8")
    fixture = {
        "https://pypi.org/pypi/ruff/json": {"info":{"version":"0.4.9"}},
        "https://registry.npmjs.org/eslint/latest": {"version":"9.0.0"},
        "https://registry.npmjs.org/cal/latest": {"version":"2024.1"},
        # down 無 fixture key → fetch None → failed
    }
    fx = root / "fx.json"; fx.write_text(J.dumps(fixture), encoding="utf-8")
    env = dict(os.environ, LUMOS_LINT_WATCH_FIXTURE=str(fx))
    r = sp.run([sys.executable, GRAPHCTL, "lint-watch", "--repo", str(root), "--json"],
               capture_output=True, text=True, env=env)
    check("rc 0", r.returncode == 0, r.stderr)
    d = J.loads(r.stdout)
    check("1 candidate(ruff)", len(d["candidates"]) == 1 and d["candidates"][0]["name"] == "ruff", str(d["candidates"]))
    check("candidate latest", d["candidates"][0]["latest"] == "0.4.9", str(d["candidates"][0]))
    check("checked = behind+current = 2", d["checked"] == 2, str(d["checked"]))
    failed_names = {f["name"] for f in d["failed"]}
    check("failed 含 cal(段數) + down(抓取)", failed_names == {"cal","down"}, str(d["failed"]))
    # 缺清單 → rc 0 空候選
    root2 = Path(tempfile.mkdtemp(prefix="gctl-lwcli2-"))
    r2 = sp.run([sys.executable, GRAPHCTL, "lint-watch", "--repo", str(root2), "--json"], capture_output=True, text=True, env=env)
    check("缺清單 rc0", r2.returncode == 0 and J.loads(r2.stdout)["candidates"] == [], r2.stdout)
    # 壞清單(非 list)→ rc 2
    (root2 / ".lumos").mkdir()
    (root2 / ".lumos" / "lint-watch.json").write_text('{"not":"a list"}', encoding="utf-8")
    r3 = sp.run([sys.executable, GRAPHCTL, "lint-watch", "--repo", str(root2), "--json"], capture_output=True, text=True, env=env)
    check("壞清單 rc2", r3.returncode == 2, f"rc={r3.returncode}")
    # 清單條目缺必填欄位(missing current)→ rc 2
    root3 = Path(tempfile.mkdtemp(prefix="gctl-lwcli3-"))
    (root3 / ".lumos").mkdir()
    (root3 / ".lumos" / "lint-watch.json").write_text(
        '[{"name":"x","registry":"npm:x"}]', encoding="utf-8"
    )
    r4 = sp.run([sys.executable, GRAPHCTL, "lint-watch", "--repo", str(root3), "--json"],
                capture_output=True, text=True, env=env)
    check("malformed entry rc2", r4.returncode == 2, f"rc={r4.returncode} stderr={r4.stderr}")


def t_lint_watch_google_maven():
    """google-maven: registry type — XML maven-metadata.xml; prerelease-in-<latest> 陷阱避開."""
    import importlib.util as U, json as J, os, tempfile
    from importlib.machinery import SourceFileLoader
    spec = U.spec_from_file_location("lm", GRAPHCTL, loader=SourceFileLoader("lm", GRAPHCTL))
    m = U.module_from_spec(spec); spec.loader.exec_module(m)

    agp_url = ("https://dl.google.com/dl/android/maven2/"
               "com/android/tools/build/gradle/maven-metadata.xml")
    only_pre_url = ("https://dl.google.com/dl/android/maven2/"
                    "com/example/only-pre/maven-metadata.xml")

    # Realistic AGP XML: <latest> is alpha (the known trap), stable max = 9.2.1
    agp_xml = (
        '<?xml version="1.0" encoding="UTF-8"?>'
        '<metadata>'
        '<versioning>'
        '<latest>9.4.0-alpha03</latest>'
        '<release>9.4.0-alpha03</release>'
        '<versions>'
        '<version>8.2.2</version>'
        '<version>9.0.0</version>'
        '<version>9.2.0</version>'
        '<version>9.2.1</version>'
        '<version>9.4.0-alpha03</version>'
        '<version>3.9</version>'
        '</versions>'
        '</versioning>'
        '</metadata>'
    )
    only_pre_xml = (
        '<?xml version="1.0" encoding="UTF-8"?>'
        '<metadata><versioning><latest>9.4.0-alpha03</latest>'
        '<versions><version>9.4.0-alpha03</version><version>9.3.0-beta01</version></versions>'
        '</versioning></metadata>'
    )

    fixture = {
        agp_url: agp_xml,
        only_pre_url: only_pre_xml,
        # missing_url not present → fetch None
    }
    fx_dir = tempfile.mkdtemp(prefix="gctl-gm-")
    fx = Path(fx_dir) / "fx.json"
    fx.write_text(J.dumps(fixture), encoding="utf-8")
    os.environ["LUMOS_LINT_WATCH_FIXTURE"] = str(fx)
    try:
        # 1. AGP: must NOT use <latest>=alpha03; stable numeric max = 9.2.1
        result = m._registry_latest("google-maven:com.android.tools.build:gradle")
        check("google-maven AGP stable max=9.2.1 (NOT alpha)",
              result == ("9.2.1", None), str(result))

        # 2. Only-prerelease XML → (None, "no stable version")
        result2 = m._registry_latest("google-maven:com.example:only-pre")
        check("google-maven only-prerelease → no stable version",
              result2 == (None, "no stable version"), str(result2))

        # 3. URL not in fixture (fetch returns None) → (None, "registry query failed: ...")
        latest3, reason3 = m._registry_latest("google-maven:com.example:missing")
        check("google-maven missing url → registry query failed",
              latest3 is None and reason3 is not None and "registry query failed" in reason3,
              f"{latest3},{reason3}")

        # 4. _http_get_text: returns XML string for known key, None for missing key
        text = m._http_get_text(agp_url)
        check("_http_get_text fixture returns XML string",
              isinstance(text, str) and "<metadata>" in text, repr(text)[:80])
        missing_text = m._http_get_text("https://dl.google.com/NOTHERE")
        check("_http_get_text missing key → None", missing_text is None, repr(missing_text))

    finally:
        os.environ.pop("LUMOS_LINT_WATCH_FIXTURE", None)
        import shutil; shutil.rmtree(fx_dir, ignore_errors=True)


def t_compose_parse():
    import importlib.util as U, json, tempfile
    from importlib.machinery import SourceFileLoader
    from pathlib import Path
    spec = U.spec_from_file_location("lm", GRAPHCTL, loader=SourceFileLoader("lm", GRAPHCTL))
    m = U.module_from_spec(spec); spec.loader.exec_module(m)
    d = Path(tempfile.mkdtemp(prefix="gctl-cm-"))
    md = d / "metrics"; rd = d / "reports"; md.mkdir(); rd.mkdir()
    (md / "app_release-module.json").write_text(json.dumps({
        "skippableComposables": 96, "restartableComposables": 229, "totalComposables": 233,
        "knownUnstableArguments": 100, "inferredUnstableClasses": 29}), encoding="utf-8")
    # csv: KdsScreen non-skippable(skippable=0,restartable=1); MainFeatureBtn skippable(1,1);
    #      ColZeroWidget non-skippable(0,1) — col-0 bare fun fixture
    (rd / "app_release-composables.csv").write_text(
        "package,name,composable,skippable,restartable,readonly,inline,isLambda,hasDefaults,defaultsGroup,groups,calls,\n"
        "com.citrus.KdsScreen,KdsScreen,1,0,1,0,0,0,0,0,2,15,\n"
        "com.citrus.MainFeatureBtn,MainFeatureBtn,1,1,1,0,0,0,0,0,1,1,\n"
        "com.citrus.GenScreen,GenScreen,1,0,1,0,0,0,0,0,1,1,\n"
        "com.citrus.ColZeroWidget,ColZeroWidget,1,0,1,0,0,0,0,0,1,1,\n", encoding="utf-8")
    # txt: KdsScreen 有 unstable viewModel;GenScreen 為泛型 fun GenScreen<T>(;含空行 default;裸 fun helper 無關鍵字;
    #      ColZeroWidget col-0 裸 fun 有 unstable param(M2 修正驗證)
    (rd / "app_release-composables.txt").write_text(
        'restartable scheme("[androidx.compose.ui.UiComposable]") fun KdsScreen(\n'
        '  unstable viewModel: CentralViewModel\n'
        '  stable askUpdate: Function0<Unit>\n'
        ')\n'
        'restartable skippable fun MainFeatureBtn(\n'
        '  stable status: String = @static {\n'
        '\n'                                # 空行(多行 default)不該斷區塊
        '  }\n'
        ')\n'
        'restartable fun GenScreen<T>(\n'   # 泛型
        '  unstable data: T\n'
        ')\n'
        'fun calculateYOffset(\n'           # 裸 fun 無關鍵字前綴(無 unstable)
        '  stable width: Int\n'
        '): Dp\n'
        'fun ColZeroWidget(\n'             # col-0 裸 fun WITH unstable(M2 核心案例)
        '  unstable data: Foo\n'
        ')\n', encoding="utf-8")
    # module
    mod = m._compose_read_module(str(md), "app_release")
    check("module skippable", mod["skippableComposables"] == 96, str(mod))
    check("module missing→None", m._compose_read_module(str(md), "nope") is None, "")
    # module corrupt JSON → None (M3: parse-error branch)
    (md / "app_release-corrupt.json").write_text("{not json", encoding="utf-8")
    check("module corrupt JSON→None", m._compose_read_module(str(md), "app_release-corrupt") is None, "")
    # composables
    non_sk, fqn2name, umap = m._compose_read_composables(str(rd), "app_release")
    check("non_skippable = KdsScreen+GenScreen+ColZeroWidget(FQN)",
          non_sk == {"com.citrus.KdsScreen", "com.citrus.GenScreen", "com.citrus.ColZeroWidget"}, str(non_sk))
    check("fqn2name", fqn2name["com.citrus.KdsScreen"] == "KdsScreen", str(fqn2name))
    check("unstable KdsScreen", umap.get("KdsScreen") == ["viewModel: CentralViewModel"], str(umap.get("KdsScreen")))
    check("unstable GenScreen(泛型名剝<T>)", umap.get("GenScreen") == ["data: T"], str(umap.get("GenScreen")))
    check("MainFeatureBtn 空行不斷→無 unstable", umap.get("MainFeatureBtn", []) == [], str(umap.get("MainFeatureBtn")))
    check("col-0 fun ColZeroWidget unstable captured(M2)",
          umap.get("ColZeroWidget") == ["data: Foo"], str(umap.get("ColZeroWidget")))
    # csv missing → early-return empty (M1)
    import tempfile as _tf
    empty_rd = Path(_tf.mkdtemp(prefix="gctl-cm-nocsv-"))
    (empty_rd / "x-composables.txt").write_text("fun Orphan(\n  unstable x: Y\n)\n", encoding="utf-8")
    ns2, fn2, um2 = m._compose_read_composables(str(empty_rd), "x")
    check("csv missing→early-return (set(),{},{})", (ns2, fn2, um2) == (set(), {}, {}),
          f"ns2={ns2} fn2={fn2} um2={um2}")


def t_compose_diff():
    import importlib.util as U
    from importlib.machinery import SourceFileLoader
    spec = U.spec_from_file_location("lm", GRAPHCTL, loader=SourceFileLoader("lm", GRAPHCTL))
    m = U.module_from_spec(spec); spec.loader.exec_module(m)
    baseline = {"aggregate": {"skippableComposables": 96, "restartableComposables": 229,
                              "totalComposables": 233, "knownUnstableArguments": 100, "inferredUnstableClasses": 29},
                "non_skippable": ["com.citrus.KdsScreen"]}
    cur_agg = {"skippableComposables": 96, "restartableComposables": 230, "totalComposables": 234,
               "knownUnstableArguments": 108, "inferredUnstableClasses": 29}
    cur_non = {"com.citrus.KdsScreen", "com.citrus.NewScreen"}   # NewScreen 新增
    fqn2name = {"com.citrus.NewScreen": "NewScreen", "com.citrus.KdsScreen": "KdsScreen"}
    umap = {"NewScreen": ["vm: CentralViewModel"]}
    regs = m._compose_diff("app", baseline, cur_agg, cur_non, fqn2name, umap)
    kinds = [(r["kind"], r.get("name") or r.get("metric")) for r in regs]
    check("new_non_skippable NewScreen",
          ("new_non_skippable", "com.citrus.NewScreen") in kinds, str(kinds))
    nn = [r for r in regs if r["kind"]=="new_non_skippable"][0]
    check("unstable_params 附上", nn["unstable_params"] == ["vm: CentralViewModel"], str(nn))
    check("knownUnstableArguments 上升報", ("aggregate", "knownUnstableArguments") in kinds, str(kinds))
    check("inferredUnstableClasses 未升→不報",
          ("aggregate", "inferredUnstableClasses") not in kinds, str(kinds))
    # skippable_ratio: baseline 96/233=.412, current 96/234=.410 → 差 .002 < EPS(.01) → 不報
    check("ratio 微幅<EPS 不報", ("aggregate", "skippable_ratio") not in kinds, str(kinds))
    # ratio 大跌:current skippable=80/234=.342 vs .412 差 .07>EPS → 報
    regs2 = m._compose_diff("app", baseline, dict(cur_agg, skippableComposables=80), cur_non, fqn2name, umap)
    check("ratio 大跌>EPS 報", any(r["kind"]=="aggregate" and r.get("metric")=="skippable_ratio" for r in regs2), str(regs2))
    # 移除的 composable 不報:baseline 有 X 現況無 → 無 regression
    regs3 = m._compose_diff("app", {"aggregate": baseline["aggregate"], "non_skippable": ["com.citrus.KdsScreen","com.citrus.Gone"]},
                            cur_agg, {"com.citrus.KdsScreen"}, {}, {})
    check("移除不報", not any(r["kind"]=="new_non_skippable" for r in regs3), str(regs3))


def t_compose_metrics_cli():
    import subprocess as sp, json, tempfile
    from pathlib import Path
    root = Path(tempfile.mkdtemp(prefix="gctl-cmcli-"))
    (root/".lumos").mkdir()
    md = root/"app"/"m"; rd = root/"app"/"r"; md.mkdir(parents=True); rd.mkdir(parents=True)
    (root/".lumos"/"compose-metrics.json").write_text(json.dumps(
        {"modules":[{"name":"app","metrics_dir":"app/m","reports_dir":"app/r"}]}), encoding="utf-8")
    def write_metrics(skippable, non_sk_rows):
        (md/"app_release-module.json").write_text(json.dumps(
            {"skippableComposables":skippable,"restartableComposables":10,"totalComposables":20,
             "knownUnstableArguments":5,"inferredUnstableClasses":2}), encoding="utf-8")
        rows = "package,name,composable,skippable,restartable,readonly,inline,isLambda,hasDefaults,defaultsGroup,groups,calls,\n"
        for fqn,name in non_sk_rows:
            rows += f"{fqn},{name},1,0,1,0,0,0,0,0,1,1,\n"
        (rd/"app_release-composables.csv").write_text(rows, encoding="utf-8")
        (rd/"app_release-composables.txt").write_text("", encoding="utf-8")
    write_metrics(10, [("com.a.Foo","Foo")])
    # baseline 缺 → baseline_missing、rc 0、無 regressions
    r0 = sp.run([sys.executable,GRAPHCTL,"compose-metrics","--repo",str(root),"--json"],capture_output=True,text=True)
    d0 = json.loads(r0.stdout)
    check("baseline_missing", r0.returncode==0 and d0["baseline_missing"] is True and d0["regressions"]==[], r0.stdout)
    # --update-baseline 立基準
    ru = sp.run([sys.executable,GRAPHCTL,"compose-metrics","--repo",str(root),"--update-baseline"],capture_output=True,text=True)
    check("update-baseline rc0", ru.returncode==0 and (root/".lumos"/"compose-baseline.json").exists(), ru.stderr)
    # 新增 non_skippable Bar → 報 new_non_skippable
    write_metrics(10, [("com.a.Foo","Foo"),("com.a.Bar","Bar")])
    r1 = sp.run([sys.executable,GRAPHCTL,"compose-metrics","--repo",str(root),"--json"],capture_output=True,text=True)
    d1 = json.loads(r1.stdout)
    names = [x.get("name") for x in d1["regressions"] if x["kind"]=="new_non_skippable"]
    check("new_non_skippable Bar", r1.returncode==0 and "com.a.Bar" in names, r1.stdout)
    check("checked_modules 1", d1["checked_modules"]==1, str(d1))
    # Fix #2: --update-baseline 當 0 模組解析時不能覆寫 baseline
    root2 = Path(tempfile.mkdtemp(prefix="gctl-cmcli-noparse-"))
    (root2/".lumos").mkdir()
    md2 = root2/"app"/"m"; rd2 = root2/"app"/"r"; md2.mkdir(parents=True); rd2.mkdir(parents=True)
    (root2/".lumos"/"compose-metrics.json").write_text(json.dumps(
        {"modules":[{"name":"app","metrics_dir":"app/m","reports_dir":"app/r"}]}), encoding="utf-8")
    sentinel = '{"sentinel":true}'
    (root2/".lumos"/"compose-baseline.json").write_text(sentinel, encoding="utf-8")
    # no metrics files → all modules fail to parse → parsed list is empty
    ru2 = sp.run([sys.executable,GRAPHCTL,"compose-metrics","--repo",str(root2),"--update-baseline"],capture_output=True,text=True)
    after = (root2/".lumos"/"compose-baseline.json").read_text(encoding="utf-8")
    check("0-parse baseline not overwritten", ru2.returncode==0 and after==sentinel, f"stdout={ru2.stdout!r} file={after!r}")
    # Fix #1: corrupt baseline → baseline_unreadable=True, baseline_missing=False, rc 0, file intact
    root3 = Path(tempfile.mkdtemp(prefix="gctl-cmcli-corrupt-"))
    (root3/".lumos").mkdir()
    md3 = root3/"app"/"m"; rd3 = root3/"app"/"r"; md3.mkdir(parents=True); rd3.mkdir(parents=True)
    (root3/".lumos"/"compose-metrics.json").write_text(json.dumps(
        {"modules":[{"name":"app","metrics_dir":"app/m","reports_dir":"app/r"}]}), encoding="utf-8")
    corrupt_content = b"not valid json!!!"
    (root3/".lumos"/"compose-baseline.json").write_bytes(corrupt_content)
    write_metrics_into = lambda md_,rd_,sk,rows: (
        (md_/("app_release-module.json")).write_text(json.dumps(
            {"skippableComposables":sk,"restartableComposables":10,"totalComposables":20,
             "knownUnstableArguments":5,"inferredUnstableClasses":2}), encoding="utf-8"),
        (rd_/("app_release-composables.csv")).write_text(
            "package,name,composable,skippable,restartable,readonly,inline,isLambda,hasDefaults,defaultsGroup,groups,calls,\n", encoding="utf-8"),
        (rd_/("app_release-composables.txt")).write_text("", encoding="utf-8"),
    )
    write_metrics_into(md3, rd3, 10, [])
    rc3 = sp.run([sys.executable,GRAPHCTL,"compose-metrics","--repo",str(root3),"--json"],capture_output=True,text=True)
    d3 = json.loads(rc3.stdout)
    after3 = (root3/".lumos"/"compose-baseline.json").read_bytes()
    check("corrupt-baseline rc0", rc3.returncode==0, f"rc={rc3.returncode} stderr={rc3.stderr!r}")
    check("corrupt-baseline unreadable true", d3.get("baseline_unreadable") is True, str(d3))
    check("corrupt-baseline missing false", d3.get("baseline_missing") is not True, str(d3))
    check("corrupt-baseline regressions empty", d3.get("regressions")==[], str(d3))
    check("corrupt-baseline file intact", after3==corrupt_content, f"file changed: {after3!r}")
    # 壞宣告 → rc 2
    (root/".lumos"/"compose-metrics.json").write_text('[]', encoding="utf-8")
    r2 = sp.run([sys.executable,GRAPHCTL,"compose-metrics","--repo",str(root),"--json"],capture_output=True,text=True)
    check("壞宣告 rc2", r2.returncode==2, f"rc={r2.returncode}")


def t_compose_metrics_audit():
    import subprocess as sp, json, tempfile
    from pathlib import Path
    root = Path(tempfile.mkdtemp(prefix="gctl-cmaudit-"))
    (root/".lumos").mkdir()
    md = root/"app"/"m"; rd = root/"app"/"r"; md.mkdir(parents=True); rd.mkdir(parents=True)
    (root/".lumos"/"compose-metrics.json").write_text(json.dumps(
        {"modules":[{"name":"app","metrics_dir":"app/m","reports_dir":"app/r"}]}), encoding="utf-8")
    (md/"app_release-module.json").write_text(json.dumps(
        {"skippableComposables":8,"restartableComposables":10,"totalComposables":20,
         "knownUnstableArguments":5,"inferredUnstableClasses":2}), encoding="utf-8")
    (rd/"app_release-composables.csv").write_text(
        "package,name,composable,skippable,restartable,readonly,inline,isLambda,hasDefaults,defaultsGroup,groups,calls,\n"
        "com.a.Foo,Foo,1,0,1,0,0,0,0,0,1,1,\n"
        "com.a.Bar,Bar,1,0,1,0,0,0,0,0,1,1,\n"
        "com.a.Ok,Ok,1,1,1,0,0,0,0,0,1,1,\n", encoding="utf-8")
    (rd/"app_release-composables.txt").write_text(
        "restartable fun Foo(\n  unstable vm: Baz\n)\nrestartable skippable fun Ok()\n", encoding="utf-8")
    # audit: 無視 baseline(不存在也照列)→ inventory 含全部 non-skippable(Foo+Bar,不含 Ok)
    r = sp.run([sys.executable,GRAPHCTL,"compose-metrics","--repo",str(root),"--audit","--json"],
               capture_output=True,text=True)
    check("audit rc0", r.returncode==0, r.stderr)
    d = json.loads(r.stdout)
    names = sorted(x["name"] for x in d["inventory"])
    check("audit inventory = 全部 non-skippable(無視 baseline)", names==["com.a.Bar","com.a.Foo"], str(names))
    foo = [x for x in d["inventory"] if x["name"]=="com.a.Foo"][0]
    check("audit unstable_params 附上", foo["unstable_params"]==["vm: Baz"], str(foo))
    check("audit aggregate", d["aggregate"]["app"]["skippableComposables"]==8, str(d.get("aggregate")))
    check("audit checked_modules/failed 欄位", d["checked_modules"]==1 and d["failed"]==[], str(d))
    # 缺 config + --audit → audit 形狀(有 inventory 鍵,非 delta 形狀)
    root2 = Path(tempfile.mkdtemp(prefix="gctl-cmaudit2-"))
    ra = sp.run([sys.executable,GRAPHCTL,"compose-metrics","--repo",str(root2),"--audit","--json"],
                capture_output=True,text=True)
    da = json.loads(ra.stdout)
    check("缺config+audit → audit 形狀(inventory 鍵)", ra.returncode==0 and "inventory" in da and "regressions" not in da, ra.stdout)


def _macrobench_mod():
    return _load_lumos_inproc()   # 只讀不改模組狀態,共用快取單例即可


_MB_CFG = {"tolerance_pct": 10.0, "abs_tolerance": 1.0, "higher_is_better": [], "ignore_metrics": ["frameCount"]}
_MB_DEV = {"model": "Pixel Tablet", "fingerprint": "google/tangorpro/tangorpro:14/X/1:user/release-keys"}


def _mb_entry(metrics=None, sampled=None, device=None):
    return {"device": dict(device or _MB_DEV), "metrics": metrics or {}, "sampled": sampled or {}}


def t_macrobench_regression_needs_both():
    """啟動類指標(有 median/min/max)要同時過兩道才算退步:中位數慢超過容差,而且比基準最大值還慢。
    預期值手算:基準中位數 1000、容差 10% → 門檻 1100。"""
    m = _macrobench_mod()
    k = "pkg.StartupBenchmark#coldStartup"
    base = {k: _mb_entry(metrics={"timeToInitialDisplayMs": {"median": 1000.0, "minimum": 950.0, "maximum": 1050.0}})}
    def run(cur_median, base_entries=base):
        cur = {k: _mb_entry(metrics={"timeToInitialDisplayMs": {"median": cur_median, "minimum": cur_median, "maximum": cur_median}})}
        return m._macrobench_compare(base_entries, cur, _MB_CFG)
    r = run(1120.0)
    regs = r["regressions"]
    check("1120 > 1100 且 > 最大值 1050 → 退步", len(regs) == 1 and regs[0]["metric"] == "timeToInitialDisplayMs", str(r))
    check("退步附基準值與現值", regs and regs[0]["baseline"] == 1000.0 and regs[0]["current"] == 1120.0, str(regs))
    check("變快 900 → 不算", run(900.0)["regressions"] == [], str(run(900.0)))


def t_macrobench_single_gate_not_enough():
    """只過其中一道不算退步。手算:基準中位數 1000、容差 10% → 門檻 1100。"""
    m = _macrobench_mod()
    k = "pkg.StartupBenchmark#coldStartup"
    def run(cur_median, lo, hi):
        b = {k: _mb_entry(metrics={"timeToInitialDisplayMs": {"median": 1000.0, "minimum": lo, "maximum": hi}})}
        c = {k: _mb_entry(metrics={"timeToInitialDisplayMs": {"median": cur_median, "minimum": cur_median, "maximum": cur_median}})}
        return m._macrobench_compare(b, c, _MB_CFG)["regressions"]
    check("前置:1120 對窄基準(最大 1050)是退步", len(run(1120.0, 950.0, 1050.0)) == 1, "")
    check("1080 超出最大值 1050 但沒過容差 1100 → 不算", run(1080.0, 950.0, 1050.0) == [], "")
    check("1200 過容差但仍在基準浮動範圍(最大 1300)內 → 不算", run(1200.0, 800.0, 1300.0) == [], "")


def t_macrobench_device_mismatch_skips():
    """換了裝置(型號或系統指紋不同)整項不比,只列出來。對照組:同裝置同數字一定是退步,證明情境成立。"""
    m = _macrobench_mod()
    k = "pkg.StartupBenchmark#coldStartup"
    base = {k: _mb_entry(metrics={"timeToInitialDisplayMs": {"median": 1000.0, "minimum": 950.0, "maximum": 1050.0}})}
    slow = {"timeToInitialDisplayMs": {"median": 3000.0, "minimum": 3000.0, "maximum": 3000.0}}
    same = m._macrobench_compare(base, {k: _mb_entry(metrics=slow)}, _MB_CFG)
    check("前置:同裝置慢三倍 → 退步", len(same["regressions"]) == 1, str(same))
    other_fp = dict(_MB_DEV, fingerprint="google/tangorpro/tangorpro:15/Y/2:user/release-keys")
    r = m._macrobench_compare(base, {k: _mb_entry(metrics=slow, device=other_fp)}, _MB_CFG)
    check("指紋不同 → 不比、不報退步", r["regressions"] == [], str(r))
    check("指紋不同 → 列在 device_changed", [d["key"] for d in r["device_changed"]] == [k], str(r))
    other_model = dict(_MB_DEV, model="SM-T220")
    r2 = m._macrobench_compare(base, {k: _mb_entry(metrics=slow, device=other_model)}, _MB_CFG)
    check("型號不同 → 列在 device_changed", r2["regressions"] == [] and len(r2["device_changed"]) == 1, str(r2))


def t_macrobench_higher_is_better():
    """設定為越大越好的指標反過來判:變小才是退步。對照組:同一組數字放在越小越好時,判斷要相反。"""
    m = _macrobench_mod()
    k = "pkg.X#y"
    base = {k: _mb_entry(metrics={"opsPerSec": {"median": 100.0, "minimum": 95.0, "maximum": 105.0}})}
    hib = dict(_MB_CFG, higher_is_better=["opsPerSec"])
    def cur(v):
        return {k: _mb_entry(metrics={"opsPerSec": {"median": v, "minimum": v, "maximum": v}})}
    check("越大越好:85(< 90 且 < 最小 95)→ 退步", len(m._macrobench_compare(base, cur(85.0), hib)["regressions"]) == 1, "")
    check("越大越好:120 → 不算", m._macrobench_compare(base, cur(120.0), hib)["regressions"] == [], "")
    check("對照:越小越好時 120 → 退步", len(m._macrobench_compare(base, cur(120.0), _MB_CFG)["regressions"]) == 1, "")
    check("對照:越小越好時 85 → 不算", m._macrobench_compare(base, cur(85.0), _MB_CFG)["regressions"] == [], "")


def t_macrobench_nonpositive_baseline():
    """基準是負數或零時不除以零、方向不反。每幀超時(frameOverrunMs)負的代表準時。
    手算:基準 P50 -10、容差 10% → 允許慢 1ms;基準 0 → 用絕對容差 1ms。"""
    m = _macrobench_mod()
    k = "pkg.Scroll#scroll"
    def cmp(base_p50, cur_p50, metric="frameOverrunMs"):
        b = {k: _mb_entry(sampled={metric: {"P50": base_p50, "P90": -50.0, "P95": -40.0, "P99": -30.0}})}
        c = {k: _mb_entry(sampled={metric: {"P50": cur_p50, "P90": -50.0, "P95": -40.0, "P99": -30.0}})}
        return [x for x in m._macrobench_compare(b, c, _MB_CFG)["regressions"] if x["stat"] == "P50"]
    check("-10 → -12 是變快 → 不算", cmp(-10.0, -12.0) == [], str(cmp(-10.0, -12.0)))
    check("-10 → -9.5 慢 0.5 < 1 → 不算", cmp(-10.0, -9.5) == [], str(cmp(-10.0, -9.5)))
    check("-10 → -8.5 慢 1.5 > 1 → 退步", len(cmp(-10.0, -8.5)) == 1, str(cmp(-10.0, -8.5)))
    check("基準 0 → 0.5 未過絕對容差 1 → 不算", cmp(0.0, 0.5, "frameDurationCpuMs") == [], "")
    check("基準 0 → 1.5 過絕對容差 → 退步", len(cmp(0.0, 1.5, "frameDurationCpuMs")) == 1, "")
    # 上面的 -10 剛好讓 10%×|基準| 等於絕對容差 1,分不出「負數用比例」與「負數誤用絕對容差」;下面兩組才分得出
    check("-100 → -95 慢 5 < 10%×100 → 不算", cmp(-100.0, -95.0) == [], str(cmp(-100.0, -95.0)))
    check("-100 → -85 慢 15 > 10%×100 → 退步", len(cmp(-100.0, -85.0)) == 1, str(cmp(-100.0, -85.0)))
    # 容差有下限:取「基準的 10%」與絕對容差兩者較大的那個(2026-10-23 實機:接近 0 的指標只靠比例會被正常抖動誤報)
    check("-0.5 → -0.2 慢 0.3 未過下限 1 → 不算", cmp(-0.5, -0.2) == [], str(cmp(-0.5, -0.2)))
    check("5 → 5.8 慢 0.8:比例只允許 0.5,但下限 1 → 不算", cmp(5.0, 5.8, "frameDurationCpuMs") == [], str(cmp(5.0, 5.8, "frameDurationCpuMs")))
    check("5 → 6.2 慢 1.2 > 下限 1 → 退步", len(cmp(5.0, 6.2, "frameDurationCpuMs")) == 1, str(cmp(5.0, 6.2, "frameDurationCpuMs")))
    cfg = dict(_MB_CFG, abs_tolerance=0.3)
    b0 = {k: _mb_entry(sampled={"frameDurationCpuMs": {"P50": 0.0, "P90": 5.0}})}
    c0 = {k: _mb_entry(sampled={"frameDurationCpuMs": {"P50": 0.5, "P90": 5.0}})}
    got = [x["stat"] for x in m._macrobench_compare(b0, c0, cfg)["regressions"]]
    check("基準 0、自訂絕對容差 0.3 → 0.5 算退步", got == ["P50"], str(got))
    b5 = {k: _mb_entry(sampled={"frameDurationCpuMs": {"P50": 5.0, "P90": 9.0}})}
    c5 = {k: _mb_entry(sampled={"frameDurationCpuMs": {"P50": 5.8, "P90": 9.0}})}
    got = [x["stat"] for x in m._macrobench_compare(b5, c5, cfg)["regressions"]]
    check("自訂下限 0.3:5 → 5.8 慢 0.8 > 比例 0.5 → 退步", got == ["P50"], str(got))


def t_macrobench_sampled_percentiles():
    """滑動類指標只有百分位:P50、P90 過容差算退步;P99 太吵只列出。手算:P90 基準 20 → 門檻 22。"""
    m = _macrobench_mod()
    k = "pkg.Scroll#scroll"
    base = {k: _mb_entry(sampled={"frameDurationCpuMs": {"P50": 10.0, "P90": 20.0, "P95": 30.0, "P99": 40.0}})}
    def cur(p50, p90, p99):
        return {k: _mb_entry(sampled={"frameDurationCpuMs": {"P50": p50, "P90": p90, "P95": 30.0, "P99": p99}})}
    r = m._macrobench_compare(base, cur(10.0, 20.0, 60.0), _MB_CFG)
    check("只有 P99 變慢 → 不算退步", r["regressions"] == [], str(r))
    check("只有 P99 變慢 → 列在 listed", [(x["stat"], x["current"]) for x in r["listed"]] == [("P99", 60.0)], str(r))
    r2 = m._macrobench_compare(base, cur(10.0, 23.0, 40.0), _MB_CFG)
    check("P90 23 > 22 → 退步", [(x["metric"], x["stat"]) for x in r2["regressions"]] == [("frameDurationCpuMs", "P90")], str(r2))
    r3 = m._macrobench_compare(base, cur(10.5, 20.0, 40.0), _MB_CFG)
    check("P50 10.5 < 11 → 不算", r3["regressions"] == [], str(r3))
    r4 = m._macrobench_compare(base, cur(11.5, 20.0, 40.0), _MB_CFG)
    check("P50 11.5 > 11 → 退步", [x["stat"] for x in r4["regressions"]] == ["P50"], str(r4))


def t_macrobench_overrun_crosses_zero():
    """每幀超時 P90 從不大於 0 變成大於 0(開始掉幀)不看差幅就算退步。
    選基準 0 → 0.5:差幅 0.5 沒過絕對容差 1,所以只有「跨零」這條會讓它成立。"""
    m = _macrobench_mod()
    k = "pkg.Scroll#scroll"
    def cmp(metric, base_p90, cur_p90):
        b = {k: _mb_entry(sampled={metric: {"P50": -20.0, "P90": base_p90, "P95": 5.0, "P99": 9.0}})}
        c = {k: _mb_entry(sampled={metric: {"P50": -20.0, "P90": cur_p90, "P95": 5.0, "P99": 9.0}})}
        return [x for x in m._macrobench_compare(b, c, _MB_CFG)["regressions"] if x["stat"] == "P90"]
    check("frameOverrunMs P90 0 → 0.5 跨零 → 退步", len(cmp("frameOverrunMs", 0.0, 0.5)) == 1, str(cmp("frameOverrunMs", 0.0, 0.5)))
    check("對照:別的指標 0 → 0.5 → 不算", cmp("frameDurationCpuMs", 0.0, 0.5) == [], "")
    check("frameOverrunMs P90 0.2 → 0.21 本來就正的、差 0.01 沒過容差 0.02 → 不算", cmp("frameOverrunMs", 0.2, 0.21) == [], "")


def _mb_result_json(benchmarks, model="Pixel Tablet", fingerprint="fp-1"):
    """照 2026-10-21 KDS 實跑結果檔的形狀造假檔(只放讀取器會用到的欄位)。"""
    import json
    return json.dumps({"context": {"build": {"brand": "google", "device": "d", "fingerprint": fingerprint,
                                             "model": model, "version": {"sdk": 34}}},
                       "benchmarks": benchmarks})


def _mb_startup(cls, median, lo, hi):
    return {"name": "coldStartup", "params": {}, "className": cls,
            "metrics": {"timeToInitialDisplayMs": {"minimum": lo, "maximum": hi, "median": median, "runs": [median]}},
            "sampledMetrics": {}}


def _mb_run(root, *args):
    import subprocess as sp
    return sp.run([sys.executable, GRAPHCTL, "macrobench", "--repo", str(root), *args], capture_output=True, text=True)


def t_macrobench_reads_real_kds_file():
    """拿 2026-10-21 Citrus_KDS 在模擬器上真跑出來的結果檔:檔名裡套件名的點變底線、放在子目錄。
    預期值是當天直接從該檔讀出來的數字(不是用讀取器算的)。"""
    import json, shutil, tempfile
    real = Path(GRAPHCTL).resolve().parent.parent / "governance" / "research" / "macrobench" / "2026-10-21-kds-emulator-benchmarkData.json"
    check("前置:真結果檔在 repo 裡", real.exists(), str(real))
    if not real.exists():
        return
    with tempfile.TemporaryDirectory(prefix="gctl-mbreal-") as td:
        root = Path(td)
        (root / ".lumos").mkdir()
        out = root / "app-bench" / "build" / "outputs" / "connected" / "emu"
        out.mkdir(parents=True)
        shutil.copy(real, out / "com_citrus_citruskds_macrobenchmark-benchmarkData.json")
        (root / ".lumos" / "macrobench.json").write_text(json.dumps({"results_dirs": ["app-bench/build/outputs"]}), encoding="utf-8")
        ru = _mb_run(root, "--update-baseline")
        check("真檔 update-baseline rc0", ru.returncode == 0, ru.stdout + ru.stderr)
        bp = root / ".lumos" / "macrobench-baseline.json"
        check("真檔 update-baseline 有寫出基準檔", bp.exists(), ru.stdout)
        bl = json.loads(bp.read_text(encoding="utf-8")).get("entries", {}) if bp.exists() else {}
        st = bl.get("com.citrus.citruskds.macrobenchmark.StartupBenchmark#coldStartup", {})
        check("啟動中位數照真檔", st.get("metrics", {}).get("timeToInitialDisplayMs", {}).get("median") == 2188.0938340000002, str(st)[:300])
        sc = bl.get("com.citrus.citruskds.macrobenchmark.OrderScrollBenchmark#scrollMainOrders", {})
        check("每幀超時 P90 照真檔", sc.get("sampled", {}).get("frameOverrunMs", {}).get("P90") == 213.84345389999996, str(sc)[:300])
        check("裝置型號照真檔", st.get("device", {}).get("model") == "sdk_gphone64_arm64", str(st.get("device")))
        r = _mb_run(root, "--json")
        d = json.loads(r.stdout) if r.stdout.strip().startswith("{") else {}
        check("同一份檔跟自己比 → 0 退步、2 項都比到", r.returncode == 0 and d.get("regressions") == [] and d.get("checked") == 2, r.stdout[:400])


def t_macrobench_update_baseline_skips_failed():
    """--update-baseline 只用解析成功的檔;壞檔不能把既有基準清掉。全部壞掉時基準檔一個位元組都不動。"""
    import json, tempfile
    with tempfile.TemporaryDirectory(prefix="gctl-mbupd-") as td:
        root = Path(td)
        (root / ".lumos").mkdir()
        res = root / "out"
        res.mkdir()
        (root / ".lumos" / "macrobench.json").write_text(json.dumps({"results_dirs": ["out"]}), encoding="utf-8")
        old = {"version": 1, "entries": {"pkg.Old#kept": {"device": {"model": "m", "fingerprint": "f"},
                                                           "metrics": {"timeToInitialDisplayMs": {"median": 1.0, "minimum": 1.0, "maximum": 1.0}},
                                                           "sampled": {}}}}
        bpath = root / ".lumos" / "macrobench-baseline.json"
        bpath.write_text(json.dumps(old), encoding="utf-8")
        (res / "a-benchmarkData.json").write_text(_mb_result_json([_mb_startup("pkg.New", 500.0, 480.0, 520.0)]), encoding="utf-8")
        (res / "b-benchmarkData.json").write_text("{ not json", encoding="utf-8")
        ru = _mb_run(root, "--update-baseline")
        check("部分壞檔 update rc0", ru.returncode == 0, ru.stdout + ru.stderr)
        entries = json.loads(bpath.read_text(encoding="utf-8")).get("entries", {})
        check("新檔的項目寫進基準", entries.get("pkg.New#coldStartup", {}).get("metrics", {}).get("timeToInitialDisplayMs", {}).get("median") == 500.0, str(entries))
        check("既有項目沒被清掉", "pkg.Old#kept" in entries, str(entries))
        check("壞檔有說出來", "b-benchmarkData.json" in ru.stdout, ru.stdout)
        (res / "a-benchmarkData.json").write_text("[]", encoding="utf-8")
        before = bpath.read_bytes()
        ru2 = _mb_run(root, "--update-baseline")
        check("全部壞掉 → rc0 且基準檔不動", ru2.returncode == 0 and bpath.read_bytes() == before, ru2.stdout)


def t_macrobench_exit_codes():
    """設定檔壞掉回 2;沒接(沒設定檔)與有退步都回 0(只提醒,不擋)。"""
    import json, tempfile
    with tempfile.TemporaryDirectory(prefix="gctl-mbrc-") as td:
        root = Path(td)
        r0 = _mb_run(root, "--json")
        d0 = json.loads(r0.stdout) if r0.stdout.strip().startswith("{") else {}
        check("沒設定檔 → rc0", r0.returncode == 0 and d0.get("regressions") == [], r0.stdout + r0.stderr)
        (root / ".lumos").mkdir()
        cfg = root / ".lumos" / "macrobench.json"
        for bad, why in (("[]", "最外層陣列"), ("{", "JSON 壞掉"), ('{"tolerance_pct": 10}', "缺 results_dirs"),
                         ('{"results_dirs": "out"}', "results_dirs 不是陣列"),
                         ('{"results_dirs": ["out"], "tolerance_pct": "ten"}', "容差不是數字"),
                         ('{"results_dirs": ["out"], "tolerance_pct": 0}', "容差不是正數")):
            cfg.write_text(bad, encoding="utf-8")
            r = _mb_run(root, "--json")
            check(f"壞設定({why}) → rc2 且說哪裡壞", r.returncode == 2 and "macrobench.json" in r.stderr, f"rc={r.returncode} err={r.stderr!r}")
        res = root / "out"
        res.mkdir()
        cfg.write_text(json.dumps({"results_dirs": ["out"]}), encoding="utf-8")
        f = res / "x-benchmarkData.json"
        f.write_text(_mb_result_json([_mb_startup("pkg.S", 1000.0, 950.0, 1050.0)]), encoding="utf-8")
        _mb_run(root, "--update-baseline")
        f.write_text(_mb_result_json([_mb_startup("pkg.S", 2000.0, 1900.0, 2100.0)]), encoding="utf-8")
        r = _mb_run(root, "--json")
        d = json.loads(r.stdout) if r.stdout.strip().startswith("{") else {}
        check("有退步 → rc0 且列出", r.returncode == 0 and len(d.get("regressions", [])) == 1, r.stdout)
        rt = _mb_run(root)
        check("文字輸出有寫退步的情境名", rt.returncode == 0 and "pkg.S#coldStartup" in rt.stdout, rt.stdout)


def t_macrobench_real_tablet_lab():
    """2026-10-23 實機(SM-X710、Android 16、benchmark-macro 1.4.1)跑小專案三次:正常、注入變慢(啟動多 300ms、
    每列多 8ms)、正常重跑。以正常那次當基準:變慢那次要剛好報出四項,正常重跑那次要一項都不報。
    預期值照三次實跑印出的數字手算(容差 = max(10%×|基準|, 1)):
      啟動中位數 216.1 → 571.1(差 355 > 21.6 且 > 基準最大 226.8);重跑 223.1(差 7 < 21.6)
      幀 CPU P90 4.7 → 10.2(差 5.5 > 1);重跑 4.7
      幀超時 P50 -3.6 → -1.0(差 2.6 > 1);重跑 -3.4(差 0.2)
      幀超時 P90 -1.7 → 3.6(跨零);重跑 -0.9(差 0.8 < 1,只靠比例 0.17 會誤報)
    結果檔名 1.4.1 保留套件名的點(1.2.4 會換成底線),兩種都要掃得到。"""
    import json, shutil, tempfile
    src = Path(GRAPHCTL).resolve().parent.parent / "governance" / "research" / "macrobench" / "2026-10-23-lab-tablet"
    with tempfile.TemporaryDirectory(prefix="gctl-mbtab-") as td:
        root = Path(td)
        (root / ".lumos").mkdir()
        (root / ".lumos" / "macrobench.json").write_text(json.dumps({"results_dirs": ["latest"]}), encoding="utf-8")
        (root / "latest").mkdir()
        dst = root / "latest" / "com.example.mblab.bench-benchmarkData.json"
        shutil.copy(src / "1-base-benchmarkData.json", dst)
        r = _mb_run(root, "--update-baseline")
        check("前置:實機正常版存成基準(檔名帶點也掃得到)", "寫入 2 個情境" in r.stdout, r.stdout + r.stderr)
        shutil.copy(src / "2-slow-benchmarkData.json", dst)
        d = json.loads(_mb_run(root, "--json").stdout)
        got = sorted((x["key"].split("#")[1], x["metric"], x["stat"]) for x in d["regressions"])
        want = sorted([("coldStartup", "timeToInitialDisplayMs", "median"), ("scrollList", "frameDurationCpuMs", "P90"),
                       ("scrollList", "frameOverrunMs", "P50"), ("scrollList", "frameOverrunMs", "P90")])
        check("注入變慢 → 剛好報出四項", got == want, str(got))
        cross = [x for x in d["regressions"] if x["metric"] == "frameOverrunMs" and x["stat"] == "P90"]
        check("注入變慢 → 幀超時 P90 標成跨零", bool(cross) and cross[0].get("zero_crossed") is True, str(cross))
        shutil.copy(src / "3-base-again-benchmarkData.json", dst)
        d = json.loads(_mb_run(root, "--json").stdout)
        check("正常重跑 → 一項都不報", d["regressions"] == [] and d["checked"] == 2, str(d["regressions"]))


def t_macrobench_corrupt_baseline_entry():
    """基準檔某一項缺欄(手改或寫壞)時,當成基準讀不了:rc0、說基準讀不了,不噴 traceback。"""
    import json, tempfile
    with tempfile.TemporaryDirectory(prefix="gctl-mbcb-") as td:
        root = Path(td)
        (root / ".lumos").mkdir()
        (root / ".lumos" / "macrobench.json").write_text(json.dumps({"results_dirs": ["out"]}), encoding="utf-8")
        (root / "out").mkdir()
        (root / "out" / "x-benchmarkData.json").write_text(
            _mb_result_json([_mb_startup("pkg.S", 1000.0, 950.0, 1050.0)]), encoding="utf-8")
        r = _mb_run(root, "--update-baseline")
        check("前置:基準建得起來", r.returncode == 0 and (root / ".lumos" / "macrobench-baseline.json").exists(), r.stdout + r.stderr)
        bp = root / ".lumos" / "macrobench-baseline.json"
        data = json.loads(bp.read_text(encoding="utf-8"))
        key = next(iter(data["entries"]))
        check("前置:基準裡有啟動指標", "timeToInitialDisplayMs" in data["entries"][key]["metrics"], str(data))
        good = json.loads(json.dumps(data))
        # 每一種壞法都要整份當讀不了;基準檔的形狀要跟讀結果檔產出的一樣(啟動類 median/minimum/maximum,
        # 滑動類 P50/P90 必有、P95/P99 有就要是數字,device 是物件)
        def bad_metrics_missing(e): e["metrics"]["timeToInitialDisplayMs"] = {"median": 1000.0}
        def bad_metrics_list(e): e["metrics"] = []
        def bad_device_str(e): e["device"] = "Pixel"
        def bad_entry_list(e): e.clear(); e["x"] = 1
        def bad_sampled_no_p90(e): e["sampled"] = {"frameDurationCpuMs": {"P50": 5.0}}
        def bad_sampled_p99_null(e): e["sampled"] = {"frameDurationCpuMs": {"P50": 5.0, "P90": 8.0, "P99": None}}
        def bad_sampled_p95_str(e): e["sampled"] = {"frameDurationCpuMs": {"P50": 5.0, "P90": 8.0, "P95": "9"}}
        def bad_sampled_list(e): e["sampled"] = [1]
        # 現況也要有滑動類指標,壞掉的基準欄位才會真的被拿來比(沒被比到就看不出會不會噴例外)
        (root / "out" / "x-benchmarkData.json").write_text(json.dumps({
            "context": {"build": {"model": "Pixel Tablet", "fingerprint": "fp-1"}},
            "benchmarks": [{"className": "pkg.S", "name": "coldStartup",
                            "metrics": {"timeToInitialDisplayMs": {"median": 1000.0, "minimum": 950.0, "maximum": 1050.0}},
                            "sampledMetrics": {"frameDurationCpuMs": {"P50": 5.0, "P90": 8.0, "P95": 9.0, "P99": 12.0}}}]}),
            encoding="utf-8")
        r = _mb_run(root, "--update-baseline")
        good = json.loads(bp.read_text(encoding="utf-8"))
        r = _mb_run(root)
        check("前置:形狀正確的基準照常比對", r.returncode == 0 and "比了 1 個情境" in r.stdout, r.stdout + r.stderr)
        for name, breaker in (("metrics 缺欄", bad_metrics_missing), ("metrics 是陣列", bad_metrics_list),
                              ("device 是字串", bad_device_str), ("項目少了 device", bad_entry_list),
                              ("sampled 缺 P90", bad_sampled_no_p90), ("sampled 的 P99 是 null", bad_sampled_p99_null),
                              ("sampled 的 P95 是字串", bad_sampled_p95_str), ("sampled 是陣列", bad_sampled_list)):
            data = json.loads(json.dumps(good))
            breaker(data["entries"][key])
            bp.write_text(json.dumps(data), encoding="utf-8")
            before = bp.read_text(encoding="utf-8")
            r = _mb_run(root)
            check(f"{name} → rc0、沒有 traceback", r.returncode == 0 and "Traceback" not in r.stderr, f"rc={r.returncode} err={r.stderr[-300:]!r}")
            check(f"{name} → 說基準讀不了", "基準檔讀不了" in r.stdout, r.stdout)
            r = _mb_run(root, "--update-baseline")
            check(f"{name} → 更新時不蓋掉它", r.returncode == 0 and bp.read_text(encoding="utf-8") == before, r.stdout + r.stderr)


def t_macrobench_duplicate_scenario():
    """同一個情境出現在兩個結果檔:兩份都不收,而且要說是重複,不能說成檔案讀不了。"""
    import json, tempfile
    with tempfile.TemporaryDirectory(prefix="gctl-mbdup-") as td:
        root = Path(td)
        (root / ".lumos").mkdir()
        (root / ".lumos" / "macrobench.json").write_text(json.dumps({"results_dirs": ["out"]}), encoding="utf-8")
        body = _mb_result_json([_mb_startup("pkg.S", 1000.0, 950.0, 1050.0)])
        for sub in ("a", "b"):
            (root / "out" / sub).mkdir(parents=True)
            (root / "out" / sub / "x-benchmarkData.json").write_text(body, encoding="utf-8")
        r = _mb_run(root, "--update-baseline")
        check("重複情境 → 不寫基準", not (root / ".lumos" / "macrobench-baseline.json").exists(), r.stdout)
        check("重複情境 → 說是重複出現", "重複" in r.stdout, r.stdout)
        check("重複情境 → 不說一個結果檔都沒讀成功", "一個結果檔都沒讀成功" not in r.stdout, r.stdout)
        r = _mb_run(root, "--json")
        d = json.loads(r.stdout) if r.stdout.strip().startswith("{") else {}
        dup = [f for f in d.get("failed", []) if "pkg.S#coldStartup" in f.get("reason", "")]
        check("重複情境 → --json 的 failed 有這個情境", len(dup) >= 1, r.stdout)
        r = _mb_run(root)
        check("重複情境 → 一般比對的文字輸出說重複", "重複" in r.stdout, r.stdout)
        check("重複情境 → 一般比對不說讀不了", "讀不了" not in r.stdout, r.stdout)


def t_android_evidence_rerun_refuses_empty():
    """逐層診斷收據的重跑腳本(scripts/templates/android-receipt-rerun.sh):收據本身寫錯時回 2 並說原因,不能空轉回 0。
    每個案例只踩一道檢查(其他條件都合格、查詢都帶 expect),拿掉任一道檢查,那個案例就會跑去叫分析工具、回 1 而不是 2。
    最後一個案例格式全對,用假的分析工具確認範本真的跑得通、比對相符時回 0。"""
    import json, os, subprocess as sp, tempfile
    tpl = Path(GRAPHCTL).resolve().parent / "templates" / "android-receipt-rerun.sh"
    check("前置:範本檔在 scripts/templates/", tpl.is_file(), str(tpl))
    if not tpl.is_file():
        return
    ok_q = "-- [Q1] session=a trace=t requires=- expect=a:n=1\nselect 'a' as k, 1 as n;\n"
    cases = (("標頭比解析到的多(最後一條漏分號)", ok_q + "-- [Q2] session=a trace=t requires=- expect=a:n=1\nselect 'a' as k, 1 as n\n", ["Q1"], 2, "標頭"),
             ("一條 expect 都沒有", "-- [Q1] session=a trace=t requires=- expect=-\ncreate perfetto table x as select 1;\n", [], 2, "expect"),
             ("manifest 列了不存在的 Q", ok_q, ["Q1", "Q9"], 2, "Q9"),
             ("查詢指到不存在的 Trace", ok_q.replace("trace=t", "trace=zzz"), ["Q1"], 2, "zzz"),
             ("requires 指到不存在的查詢", ok_q.replace("requires=-", "requires=Q7"), ["Q1"], 2, "Q7"),
             ("格式全對、比對相符", ok_q, ["Q1"], 0, "OK  Q1"))
    for why, sql, layer_qs, want_rc, want_text in cases:
        with tempfile.TemporaryDirectory(prefix="gctl-rerun-") as td:
            d = Path(td) / ".lumos" / "receipts" / "x"
            d.mkdir(parents=True)
            (d / "rerun.sh").write_bytes(tpl.read_bytes())
            (d / "queries.sql").write_text(sql, encoding="utf-8")
            (d / "manifest.json").write_text(json.dumps({"artifacts": [{"id": "t", "path": "trace.bin"}],
                                                         "layers": [{"layer": "L1", "queries": layer_qs}]}), encoding="utf-8")
            fake = Path(td) / "fake_tp"
            fake.write_text("#!/bin/sh\nprintf '\"k\",\"n\"\\n\"a\",\"1\"\\n'\n", encoding="utf-8")
            fake.chmod(0o755)
            r = sp.run(["sh", str(d / "rerun.sh")], capture_output=True, text=True, env=dict(os.environ, TP=str(fake)))
            said = r.stderr if want_rc == 2 else r.stdout   # 收據寫錯照 lumos 慣例印到 stderr、以「擋下:」開頭
            check(f"rerun.sh {why} → rc{want_rc} 並說明", r.returncode == want_rc and want_text in said
                  and (want_rc != 2 or said.startswith("擋下:")) and "Traceback" not in r.stderr,
                  f"rc={r.returncode} out={r.stdout[:300]} err={r.stderr[:200]}")


_UI_ATTR_TPL = "android-ui-attribution.sql"


def _ui_attr(frames, other_tracks=()):
    """拿 Python 內建的 sqlite3 建出 Perfetto 的四張表,跑工具鏈範本裡的歸因查詢(scripts/templates/android-ui-attribution.sql)。
    frames:每一幀是一棵樹 (名稱, 毫秒, [子區段…]),放在 com.lab 的主執行緒上;子區段從父區段的起點依序排、不交錯(Perfetto 同一條執行緒上的區段一定是巢狀)。
    other_tracks:(行程名, 是不是主執行緒, 樹) 放到別的執行緒,用來確認查詢只算這個 App 的主執行緒。
    回 {幀起點毫秒: {"xml", "compose", "pipeline", "other", "dur"(毫秒), "fn"(Compose 自身時間最多的函式區段名)}};範本不在回 None。"""
    import sqlite3
    tpl = Path(GRAPHCTL).resolve().parent / "templates" / _UI_ATTR_TPL
    if not tpl.is_file():
        return None
    ms = 1_000_000
    db = sqlite3.connect(":memory:")
    db.executescript("create table process(upid integer primary key, pid int, name text);"
                     "create table thread(utid integer primary key, tid int, name text, upid int);"
                     "create table thread_track(id integer primary key, utid int);"
                     "create table slice(id integer primary key, ts int, dur int, track_id int, name text, depth int, parent_id int);"
                     "insert into process values (1, 100, 'com.lab'), (2, 200, 'com.other');"
                     "insert into thread values (1, 100, 'com.lab', 1), (2, 101, 'RenderThread', 1), (3, 200, 'com.other', 2);"
                     "insert into thread_track values (1, 1), (2, 2), (3, 3);")
    nid = [0]

    def put(node, track, ts, depth, parent):
        name, dur, kids = node[0], node[1], (node[2] if len(node) > 2 else [])
        nid[0] += 1
        me = nid[0]
        db.execute("insert into slice values (?,?,?,?,?,?,?)", (me, ts * ms, dur * ms, track, name, depth, parent))
        at = ts
        for k in kids:
            put(k, track, at, depth + 1, me)
            at += k[1]
    start = 0
    for f in frames:
        put(f, 1, start, 0, None)
        start += 100
    for proc, main, tree in other_tracks:
        put(tree, 1 if proc == "com.lab" and main else 2 if proc == "com.lab" else 3, start, 0, None)
        start += 100
    cur = db.execute(tpl.read_text(encoding="utf-8").replace("__PROCESS__", "com.lab"))
    cols = [c[0] for c in cur.description]
    out = {}
    for row in cur.fetchall():
        r = dict(zip(cols, row))
        if cols[0] != "frame" or r["frame"] != f"f{r['frame_ts']}":
            raise AssertionError(f"第一欄要是字串鍵 frame='f<幀起點>'(重跑腳本拿第一欄當鍵):{cols[:2]} {row[:2]}")
        out[r["frame_ts"] // ms] = {"xml": r["xml_ns"] / ms, "compose": r["compose_ns"] / ms, "pipeline": r["pipeline_ns"] / ms,
                                    "other": r["other_ns"] / ms, "dur": r["frame_dur"] / ms, "fn": r["top_compose_fn"]}
    return out


def _ui_split(got, ts):
    """某一幀的 (xml, compose, pipeline, other) 毫秒;沒有那一幀回 None。"""
    f = (got or {}).get(ts)
    return None if f is None else (f["xml"], f["compose"], f["pipeline"], f["other"])


def t_android_ui_attribution_innermost():
    """外層包著 Compose 時,Compose 那段的自身時間算給 Compose,外層只算扣掉子區段後剩下的。兩種包法:
    畫面管線的 measure 包著 Compose 的排版(Compose 畫面或 XML 裡嵌 ComposeView 的排版階段);
    清單綁定列包著 Compose 重組(XML 清單每列是 ComposeView)。比外層總長的話,Compose 會被整段算給外層。"""
    got = _ui_attr([("Choreographer#doFrame 1", 16, [("traversal", 12, [("measure", 10, [("Compose:measure", 7)])])]),
                    ("Choreographer#doFrame 4", 10, [("animation", 6, [("compose:lazy:prefetch:compose", 5)])]),
                    ("Choreographer#doFrame 2", 10, [("RV onBindViewHolder type=0x0", 6, [("Compose:recompose", 4)])]),
                    ("Choreographer#doFrame 3", 10, [("animation", 6, [("Recomposer:recompose", 4)])])])
    check("前置:範本檔在 scripts/templates/", got is not None, _UI_ATTR_TPL)
    if got is None:
        return
    check("animation 階段包 Recomposer 的重組:Compose 4、管線 2、其他 4", _ui_split(got, 300) == (0.0, 4.0, 2.0, 4.0), str(got))
    # LazyColumn 的預先組合用小寫開頭(2026-10-23 實驗室 Compose 1.9 真實 Trace:每輪約 1 秒)
    check("小寫 compose:lazy:prefetch 也算 Compose:Compose 5、管線 1、其他 4", _ui_split(got, 100) == (0.0, 5.0, 1.0, 4.0), str(got))
    check("管線包 Compose:XML 0、Compose 7、管線 5(traversal 2 + measure 3)、其他 4(doFrame 自身)",
          _ui_split(got, 0) == (0.0, 7.0, 5.0, 4.0), str(got))
    check("清單綁定列包 Compose:XML 2、Compose 4、管線 0、其他 4", _ui_split(got, 200) == (2.0, 4.0, 0.0, 4.0), str(got))


def t_android_ui_attribution_inherit():
    """名稱分不出類的區段(App 自己打的、binder 等)跟著最近一個分得出類的祖先;一路上都分不出的算其他。"""
    got = _ui_attr([("Choreographer#doFrame 1", 30, [("RV onBindViewHolder type=0x0", 8, [("MyApp#bindRow", 5)]),
                                                     ("Compose:recompose", 6, [("RepoLoad", 2)]),
                                                     ("Record View#draw()", 7, [("binder transaction", 4)]),
                                                     ("MyApp#tick", 1)])])
    check("前置:範本檔在 scripts/templates/", got is not None, _UI_ATTR_TPL)
    if got is None:
        return
    xml, comp, pipe, other = _ui_split(got, 0) or (None,) * 4
    check("清單綁定列底下的 App 區段算 XML(3 + 5 = 8)", xml == 8.0, str(got))
    check("Compose 底下的 App 區段算 Compose(4 + 2 = 6)", comp == 6.0, str(got))
    check("繪製底下的 binder 算管線(3 + 4 = 7)", pipe == 7.0, str(got))
    check("直接掛在 doFrame 底下的 App 區段算其他(doFrame 自身 8 + 1 = 9)", other == 9.0, str(got))
    # 名稱是 NULL 的區段(track_event 沒給名稱)照「分不出類、跟祖先」,不能連子樹整段消失(2026-10-24 代碼審 r1 正確性席、邊界席)
    got2 = _ui_attr([("Choreographer#doFrame 1", 10, [(None, 6, [("measure", 3)])])])
    check("名稱 NULL 的區段跟祖先算其他、底下的 measure 照算管線,四類加總等於幀長",
          _ui_split(got2, 0) == (0.0, 0.0, 3.0, 7.0), str(got2))


def t_android_ui_attribution_rv_names():
    """只有 XML 寫法才有的元件區段:清單綁定的新舊名(官方文件寫 RV OnBindView,RecyclerView 主線已改成 RV onBindViewHolder type=0x…)、
    舊清單元件 ListView 的 obtainView 與 setupListItem(實驗室 App 的真實 Trace 裡就是這兩個)、inflate。"""
    names = ("RV OnBindView", "RV onBindViewHolder type=0x0", "obtainView", "setupListItem", "inflate")
    got = _ui_attr([("Choreographer#doFrame 1", 10, [(n, 3)]) for n in names] +
                   [("Choreographer#doFrame 9", 10, [("RVX", 2)])])
    check("前置:範本檔在 scripts/templates/", got is not None, _UI_ATTR_TPL)
    if got is None:
        return
    for i, n in enumerate(names):
        check(f"{n} 算 XML 元件", _ui_split(got, i * 100) == (3.0, 0.0, 0.0, 7.0), str(got.get(i * 100)))
    check("RV 後面沒有空白的不算(只比開頭「RV 」)", _ui_split(got, len(names) * 100) == (0.0, 0.0, 0.0, 10.0),
          str(got.get(len(names) * 100)))


def t_android_ui_attribution_pipeline():
    """兩種寫法共用的畫面管線(input、animation、traversal、measure、layout、draw、Record View#draw()、postAndWait)
    單獨一類、不算成 XML:Compose 畫面也掛在 View 系統上跑,Compose 的繪製沒有自己的區段。"""
    names = ("input", "animation", "traversal", "measure", "layout", "draw", "draw-VRI[MainActivity]@1", "Record View#draw()", "postAndWait")
    got = _ui_attr([("Choreographer#doFrame 1", 10, [(n, 3)]) for n in names])
    check("前置:範本檔在 scripts/templates/", got is not None, _UI_ATTR_TPL)
    if got is None:
        return
    for i, n in enumerate(names):
        check(f"{n} 算管線、不算 XML", _ui_split(got, i * 100) == (0.0, 0.0, 3.0, 7.0), str(got.get(i * 100)))
    # App 自己打的 draw 開頭區段不是框架的繪製,跟祖先(2026-10-24 代碼審 r1 邊界席:原本 draw* 全吸進管線)
    got2 = _ui_attr([("Choreographer#doFrame 1", 100, [("Compose:recompose", 60, [("drawChart", 50)])])])
    check("Compose 底下 App 的 drawChart 跟祖先算 Compose(60),不算管線", _ui_split(got2, 0) == (0.0, 60.0, 0.0, 40.0), str(got2))


def t_android_ui_attribution_compose_fn():
    """有開 composition tracing 時,輸出 Compose 自身時間最多的函式區段名(同名的加總後比,名稱帶檔名與行號);
    Compose: 開頭的框架區段不算函式。函式區段直接掛在 XML 元件底下(清單每列是 ComposeView)也算 Compose。"""
    got = _ui_attr([("Choreographer#doFrame 1", 20, [("Compose:recompose", 12, [("com.a.Row (Row.kt:12)", 2),
                                                                                ("com.a.Row (Row.kt:12)", 2),
                                                                                ("com.a.Header (Header.kt:5)", 3)])]),
                    ("Choreographer#doFrame 2", 10, [("RV onBindViewHolder type=0x0", 6, [("com.a.Card (Card.kt:3)", 4)])]),
                    ("Choreographer#doFrame 3", 5, [("Compose:recompose", 3)])])
    check("前置:範本檔在 scripts/templates/", got is not None, _UI_ATTR_TPL)
    if got is None:
        return
    check("同名加總後最多的是 Row(2+2 > Header 3),不是自身 5 的 Compose:recompose",
          (got.get(0) or {}).get("fn") == "com.a.Row (Row.kt:12)", str(got.get(0)))
    check("函式區段直接在 XML 元件底下 → XML 2、Compose 4", (_ui_split(got, 100) or ())[:2] == (2.0, 4.0), str(got.get(100)))
    check("沒有函式區段的幀不亂填", 200 in got and got[200]["fn"] is None, str(got.get(200)))
    # 同分時照名稱排、取第一個,Python 的 sqlite3 與 trace_processor 才挑得出同一個(2026-10-24 代碼審 r2 正確性席)
    got_tie = _ui_attr([("Choreographer#doFrame 1", 10, [("Compose:recompose", 8, [("a.B (B.kt:1)", 3), ("a.A (A.kt:1)", 3)])])])
    check("兩個函式自身時間同分 → 取名稱排在前面的 a.A", (got_tie.get(0) or {}).get("fn") == "a.A (A.kt:1)", str(got_tie))
    # ART 的鎖競爭區段也帶「(檔.kt:行號)」,但是一整句話;2026-10-23 實驗室真實 Trace 裡被誤算成 Compose 791 毫秒
    lock = ("monitor contention with owner lab-lock-holder (24615) at void com.example.mblab.MainActivity$Companion."
            "startLockHolder$lambda$0(long)(MainActivity.kt:65) waiters=0 blocking from android.view.View "
            "com.example.mblab.MainActivity$RowAdapter.getView(int, android.view.View, android.view.ViewGroup)(MainActivity.kt:44)")
    got2 = _ui_attr([("Choreographer#doFrame 1", 10, [("obtainView", 8, [(lock, 6)])])])
    check("鎖競爭區段不算 Compose 函式,跟著祖先算 XML 元件", _ui_split(got2, 0) == (8.0, 0.0, 0.0, 2.0) and got2[0]["fn"] is None,
          str(got2))


def t_android_ui_attribution_sums():
    """只有某一類的幀其他類是 0,四類加總等於幀長;只算這個 App 的主執行緒:
    別的 App 主執行緒、同一個 App 別的執行緒上的 doFrame(有自己 Choreographer 的背景執行緒)都不算;
    Trace 結束時還沒收尾的幀(Perfetto 記成長度 -1)不輸出;doFrame 掛在 Looper 訊息區段底下(開了訊息迴圈追蹤)照樣算。"""
    got = _ui_attr([("Choreographer#doFrame 1", 10, [("RV OnBindView", 9)]),
                    ("Choreographer#doFrame 2", 10, [("Compose:recompose", 6)]),
                    ("Looper.dispatch: android.view.Choreographer$FrameHandler", 12, [("Choreographer#doFrame 3", 10, [("layout", 4)])]),
                    ("Choreographer#doFrame 4", -1)],
                   other_tracks=(("com.lab", False, ("Choreographer#doFrame 5", 8, [("traversal", 5)])),
                                 ("com.other", True, ("Choreographer#doFrame 9", 30, [("traversal", 25)]))))
    check("前置:範本檔在 scripts/templates/", got is not None, _UI_ATTR_TPL)
    if got is None:
        return
    check("只算 com.lab 主執行緒的三個完整幀(不含別的執行緒、別的 App、沒收尾的)", sorted(got) == [0, 100, 200], str(got))
    check("掛在 Looper 訊息底下的幀:管線 4、其他 6", _ui_split(got, 200) == (0.0, 0.0, 4.0, 6.0), str(got.get(200)))
    check("只有 XML 元件的幀:XML 9、Compose 0、管線 0、其他 1", _ui_split(got, 0) == (9.0, 0.0, 0.0, 1.0), str(got))
    check("只有 Compose 的幀:XML 0、Compose 6、管線 0、其他 4", _ui_split(got, 100) == (0.0, 6.0, 0.0, 4.0), str(got))
    check("四類加總等於幀長", all(abs(sum(_ui_split(got, t)) - v["dur"]) < 1e-9 for t, v in got.items()), str(got))
    # 沒收尾(dur -1)的區段連同底下整棵子樹都不算,時間留給最近一個已收尾的祖先;結果不能隨「這個名稱在別處有沒有出現過」而變
    # (2026-10-24 代碼審 r2 邊界席:名稱只出現一次時子樹消失,名稱在別處出現過時子樹被算進去、祖先又沒扣,加總超過幀長)
    for extra in ([], [("Choreographer#doFrame 2", 10, [("measure", 2)])]):
        got4 = _ui_attr([("Choreographer#doFrame 1", 10, [("traversal", 5, [("measure", -1, [("Compose:a", 3)])])]), *extra])
        check(f"沒收尾的 measure 底下的 Compose 不算、時間留給 traversal(measure 在別處{'有' if extra else '沒有'}出現)",
              _ui_split(got4, 0) == (0.0, 0.0, 5.0, 5.0), str(got4.get(0)))
    # 子區段比父區段長(資料錯或時間重疊)時自身時間取 0,不輸出負數(2026-10-24 代碼審 r1 邊界席)
    got3 = _ui_attr([("Choreographer#doFrame 1", 100, [("Compose:recompose", 150)])])
    check("子區段比幀長時其他類是 0、不是負的", (_ui_split(got3, 0) or (None,) * 4)[3] == 0.0, str(got3))


