def t_android_ui_attribution_receipt_rerun():
    """範本整份(含檔頭註解)貼在收據標頭底下,收據的重跑腳本要把完整的查詢交給分析工具。
    重跑腳本拿「第一個以分號結尾的行」當查詢結尾;範本註解要是以分號結尾,查詢會被截在註解、本體整段丟掉,
    而且不會回 2(標頭數照樣對),只會在比對時報不符(2026-10-24 代碼審 code-android-ui-kind r1 整合席)。
    假的分析工具只在收到的查詢從 WITH RECURSIVE 到結尾 ORDER BY 都在時才印出一列,expect 才對得上。"""
    import json, os, subprocess as sp, tempfile
    here = Path(GRAPHCTL).resolve().parent / "templates"
    tpl, rerun = here / _UI_ATTR_TPL, here / "android-receipt-rerun.sh"
    check("前置:兩支範本都在", tpl.is_file() and rerun.is_file(), str(here))
    if not (tpl.is_file() and rerun.is_file()):
        return
    sql = "-- [Q1] session=c trace=t requires=- expect=f100:compose_ns=5\n" + tpl.read_text(encoding="utf-8").replace("__PROCESS__", "com.lab")
    with tempfile.TemporaryDirectory(prefix="gctl-uirerun-") as td:
        d = Path(td) / ".lumos" / "receipts" / "x"
        d.mkdir(parents=True)
        (d / "rerun.sh").write_bytes(rerun.read_bytes())
        (d / "queries.sql").write_text(sql, encoding="utf-8")
        (d / "manifest.json").write_text(json.dumps({"artifacts": [{"id": "t", "path": "trace.bin"}],
                                                     "layers": [{"layer": "L1", "queries": ["Q1"]}]}), encoding="utf-8")
        fake = Path(td) / "fake_tp"
        fake.write_text("#!/bin/sh\n# 用法跟 trace_processor 一樣:<trace> -q <查詢檔>\n"
                        "if grep -q 'WITH RECURSIVE' \"$3\" && grep -q 'ORDER BY f.ts;' \"$3\"; then\n"
                        "  printf '\"frame\",\"compose_ns\"\\n\"f100\",\"5\"\\n'\nfi\n", encoding="utf-8")
        fake.chmod(0o755)
        r = sp.run(["sh", str(d / "rerun.sh")], capture_output=True, text=True, env=dict(os.environ, TP=str(fake)))
        check("整份範本貼進收據 → 重跑腳本交出完整查詢、比對相符回 0", r.returncode == 0 and "OK  Q1" in r.stdout,
              f"rc={r.returncode} out={r.stdout[:300]} err={r.stderr[:200]}")
        # 非 UTF-8 的環境(LC_ALL=C)照樣跑通(2026-10-24 代碼審 r2 邊界席:範本帶中文註解,原本寫暫存檔時 UnicodeEncodeError)。
        # 重跑腳本四處讀寫都要碰到中文才驗得到:manifest 的路徑、分析工具的輸出、印出的比對值(stdout)、收據寫錯時的訊息(stderr)
        env_c = {k: v for k, v in os.environ.items() if not k.startswith(("LC_", "LANG", "PYTHONUTF8", "PYTHONIOENCODING"))}
        env_c.update(LC_ALL="C", PYTHONUTF8="0", PYTHONCOERCECLOCALE="0", TP=str(fake))
        d2 = Path(td) / ".lumos" / "receipts" / "y"
        d2.mkdir(parents=True)
        (d2 / "rerun.sh").write_bytes(rerun.read_bytes())
        (d2 / "queries.sql").write_text(sql.replace("expect=f100:compose_ns=5", "expect=f100:compose_ns=5,top_compose_fn=甲"), encoding="utf-8")
        (d2 / "manifest.json").write_text(json.dumps({"artifacts": [{"id": "t", "path": "trace-甲.bin"}],
                                                      "layers": [{"layer": "L1", "queries": ["Q1"]}]}, ensure_ascii=False), encoding="utf-8")
        fake.write_text("#!/bin/sh\n"
                        "if grep -q 'WITH RECURSIVE' \"$3\" && grep -q 'ORDER BY f.ts;' \"$3\"; then\n"
                        "  printf '\"frame\",\"compose_ns\",\"top_compose_fn\"\\n\"f100\",\"5\",\"甲\"\\n'\nfi\n", encoding="utf-8")
        r2 = sp.run(["sh", str(d2 / "rerun.sh")], capture_output=True, env=env_c)
        out2, err2 = r2.stdout.decode("utf-8", "replace"), r2.stderr.decode("utf-8", "replace")
        check("非 UTF-8 環境:中文路徑、中文輸出、中文比對值照樣比對相符回 0", r2.returncode == 0 and "OK  Q1" in out2 and "甲" in out2
              and "Traceback" not in err2, f"rc={r2.returncode} out={out2[:200]} err={err2[-300:]}")
        (d2 / "queries.sql").write_text(sql.replace("expect=f100:compose_ns=5", "expect=-"), encoding="utf-8")
        r3 = sp.run(["sh", str(d2 / "rerun.sh")], capture_output=True, env=env_c)
        err3 = r3.stderr.decode("utf-8", "replace")
        check("非 UTF-8 環境:收據寫錯照樣回 2 並印出中文原因", r3.returncode == 2 and err3.startswith("擋下:") and "Traceback" not in err3,
              f"rc={r3.returncode} err={err3[-300:]}")
        # 收據檔開頭帶 BOM(2026-10-24 代碼審 r3 邊界席):queries.sql 的 BOM 原本讓第一個標頭配不到、標頭數與條數一起少一,
        # 第一條比對不符也照樣回 0(假過);manifest.json 的 BOM 原本 Traceback
        bom = "\ufeff"
        two = (sql.replace("expect=f100:compose_ns=5", "expect=f100:compose_ns=999")
               + "\n" + sql.replace("-- [Q1]", "-- [Q2]"))
        (d2 / "queries.sql").write_text(bom + two, encoding="utf-8")
        (d2 / "manifest.json").write_text(bom + json.dumps({"artifacts": [{"id": "t", "path": "trace-甲.bin"}],
                                                            "layers": [{"layer": "L1", "queries": ["Q1", "Q2"]}]}, ensure_ascii=False),
                                          encoding="utf-8")
        r4 = sp.run(["sh", str(d2 / "rerun.sh")], capture_output=True, env=dict(os.environ, TP=str(fake)))
        out4, err4 = r4.stdout.decode("utf-8", "replace"), r4.stderr.decode("utf-8", "replace")
        check("queries.sql 與 manifest 帶 BOM:第一條照樣被讀到、比對不符回 1", r4.returncode == 1 and "BAD Q1" in out4 and "OK  Q2" in out4
              and "Traceback" not in err4, f"rc={r4.returncode} out={out4[:200]} err={err4[-300:]}")
        # 分析工具不存在:回 2 說原因,不留暫存查詢檔(2026-10-24 代碼審 r3 資源席:原本 Traceback 回 1、暫存檔留在系統暫存目錄)
        (d2 / "queries.sql").write_text(sql, encoding="utf-8")
        (d2 / "manifest.json").write_text(json.dumps({"artifacts": [{"id": "t", "path": "trace.bin"}],
                                                      "layers": [{"layer": "L1", "queries": ["Q1"]}]}), encoding="utf-8")
        tmp = Path(td) / "tmpdir"
        tmp.mkdir()
        r5 = sp.run(["sh", str(d2 / "rerun.sh")], capture_output=True,
                    env=dict(os.environ, TP=str(Path(td) / "沒有這支工具"), TMPDIR=str(tmp)))
        err5 = r5.stderr.decode("utf-8", "replace")
        check("分析工具不存在 → 回 2、說是找不到分析工具、不留暫存檔", r5.returncode == 2 and err5.startswith("擋下:") and "分析工具" in err5
              and "Traceback" not in err5 and not list(tmp.iterdir()), f"rc={r5.returncode} err={err5[-300:]} tmp={list(tmp.iterdir())}")


def t_macrobench_threshold_trace_section_count():
    """TraceSectionMetric 的次數指標(例 Compose:recompose 的 Count 模式,結果檔叫 Compose:recomposeCount)跟啟動時間一樣是單值指標,
    可以寫門檻:中位數超過上限列沒達、在上限內列達標。"""
    import tempfile

    def bench(med):
        return {"name": "scrollCompose", "params": {}, "className": "pkg.Flow",
                "metrics": {"Compose:recomposeCount": {"minimum": med - 2, "maximum": med + 2, "median": med, "runs": [med]}},
                "sampledMetrics": {}}
    for med, want_fail in ((55.0, True), (40.0, False)):
        with tempfile.TemporaryDirectory(prefix="gctl-mbthr-") as td:
            thr = _mb_thr(scenario="pkg.Flow#scrollCompose", metric="Compose:recomposeCount", stat="median", max=40)
            _, r, d, rt = _mb_thr_root(td, [bench(med)], [thr])
            got = (len(d.get("threshold_failures", [])), len(d.get("threshold_passed", [])))
            check(f"重組次數中位數 {med}、門檻 ≤ 40 → {'沒達' if want_fail else '達標'}",
                  got == ((1, 0) if want_fail else (0, 1)), r.stdout + r.stderr)
            if want_fail:
                check("文字輸出印出指標名與次數", "Compose:recomposeCount" in rt.stdout and "55" in rt.stdout, rt.stdout)


def _ms_result(**over):
    """收集腳本寫的 stability.json 的假檔:預設每個來源都 ok、什麼都沒漏。over 用 來源=dict 整段蓋掉。"""
    d = {"scenario": "pkg.Leak#cycle", "device_model": "SM-X710", "android_sdk": 36, "total_mem_mb": 7213,
         "category": "app", "warmup": 2, "cycles": 5,
         "driver": {"status": "ok", "warmup": {"rc": 0}, "cycles": {"rc": 0}},
         "pids": {"status": "ok", "values": [100, 100, 100]},
         "unreachable": {"status": "ok", "before": {"bytes": 0, "allocations": 0}, "after": {"bytes": 0, "allocations": 0}},
         "heap": {"status": "ok", "before": {"com.sdk.Player": 1}, "after": {"com.sdk.Player": 1}, "classes_seen": {"before": 9000, "after": 9000}},
         "native_heap_kb": {"status": "ok", "before": 7000, "after": 7100},
         "cycle_trace": {"status": "ok", "peak_anon_swap_kb": 200000, "frozen_frames": 0, "max_main_block_ms": 40, "frames": 600},
         "exits": {"status": "ok", "new": []},
         "strictmode": {"status": "ok", "violations": []}}
    d.update(over)
    return d


def _ms_thr(check, **over):
    t = {"scenario": "pkg.Leak#cycle", "check": check, "contract": "Systems/播放器 ★INVARIANT★ 關畫面釋放播放器",
         "decided_by": "Enzo", "decided_at": "2026-10-24"}
    t.update(over)
    return {k: v for k, v in t.items() if v is not None}


def _ms_root(td, thresholds, result, config=None, text=True):
    """暫存專案:門檻檔 + 一份 stability.json;config 給了才寫 .lumos/macrobench.json。
    回 (root, --json 那次, 解析後的 dict, 文字輸出那次)。"""
    import json
    root = Path(td)
    (root / ".lumos").mkdir(exist_ok=True)
    if config is not None:
        (root / ".lumos" / "macrobench.json").write_text(json.dumps(config), encoding="utf-8")
    (root / ".lumos" / "macrobench-thresholds.json").write_text(
        json.dumps({"version": 1, "thresholds": thresholds}, ensure_ascii=False), encoding="utf-8")
    sp = root / "stability.json"
    sp.write_text(result if isinstance(result, str) else json.dumps(result, ensure_ascii=False), encoding="utf-8")
    r = _mb_run(root, "--stability", str(sp), "--json")
    d = json.loads(r.stdout) if r.stdout.strip().startswith("{") else {}
    return root, r, d, (_mb_run(root, "--stability", str(sp)) if text else r)


def _ms_verdict(d):
    """--json 結果裡寫了 check 的那幾筆 → [(清單名, check, 那筆)]。"""
    return [(k, x.get("check"), x) for k in ("threshold_failures", "threshold_passed", "threshold_skipped")
            for x in d.get(k, []) if x.get("check")]


def t_android_memstab_native_unreachable():
    """S1:兩次掃描的沒人指著原生記憶體差值大於門檻 → 沒過並印差值;等於門檻 → 通過;只比差值不比絕對值。"""
    import tempfile
    cases = [((0, 0), (10485760, 5), None, "threshold_failures"),   # 實驗室實測:沒呼叫 release 5 輪漏 10 MB 5 塊
             ((4096, 1), (4096, 1), None, "threshold_passed"),       # 暖機後就有 4 KB 基線、量測後沒變 → 差值 0
             ((0, 0), (1024, 1), 1024, "threshold_passed"),          # 差值剛好等於門檻
             ((0, 0), (1025, 1), 1024, "threshold_failures")]
    for (b, ba), (a, aa), lim, want in cases:
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            res = _ms_result(unreachable={"status": "ok", "before": {"bytes": b, "allocations": ba},
                                          "after": {"bytes": a, "allocations": aa}})
            _, r, d, rt = _ms_root(td, [_ms_thr("native_unreachable", max_bytes=lim)], res)
            v = _ms_verdict(d)
            check(f"前 {b} 後 {a} 門檻 {lim} → {want}", [x[0] for x in v] == [want], r.stdout + r.stderr)
            if want == "threshold_failures":
                rec = v[0][2]
                check("沒過那筆附差值位元組與塊數", rec.get("delta_bytes") == a - b and rec.get("delta_allocations") == aa - ba, str(rec))
                check("文字輸出印出差值", str(a - b) in rt.stdout and "native_unreachable" in rt.stdout, rt.stdout)
            check("只提醒、回 0", r.returncode == 0 and rt.returncode == 0, r.stderr + rt.stderr)


def t_android_memstab_java_growth():
    """S2:不在排除清單的類別增加量至少 N × 每輪門檻 → 沒過並列出;少一個 → 通過;平台型別增加再多也不算。"""
    import tempfile
    def run(before, after, text=False, **thr):   # 文字輸出只在要看的案例才跑:每案多起一次 lumos(代碼審 r3 通才席)
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            res = _ms_result(heap={"status": "ok", "before": before, "after": after, "classes_seen": {"before": 9000, "after": 9000}})
            _, r, d, rt = _ms_root(td, [_ms_thr("java_growth", **thr)], res, text=text)
            return _ms_verdict(d), r, rt
    v, r, rt = run({"com.sdk.Player": 1, "java.lang.String": 900}, {"com.sdk.Player": 6, "java.lang.String": 5000}, text=True)
    check("SDK 類別 5 輪多 5 個 → 沒過", [x[0] for x in v] == ["threshold_failures"], r.stdout + r.stderr)
    grown = v[0][2].get("grown", []) if v else []
    check("列出增長的類別與增加量,不列平台型別", grown == [{"class": "com.sdk.Player", "delta": 5}], str(grown))
    check("文字輸出印出類別名", "com.sdk.Player" in rt.stdout, rt.stdout)
    v, r, _ = run({"com.sdk.Player": 1}, {"com.sdk.Player": 5})
    check("多 4 個(少一個)→ 通過", [x[0] for x in v] == ["threshold_passed"], r.stdout)
    v, r, _ = run({"byte[]": 10, "androidx.Foo": 1, "kotlin.Bar": 1}, {"byte[]": 99999, "androidx.Foo": 50, "kotlin.Bar": 50})
    check("基本型別陣列與 androidx.、kotlin. 開頭的增加再多也不算", [x[0] for x in v] == ["threshold_passed"], r.stdout)
    v, r, _ = run({"com.sdk.Player": 1}, {"com.sdk.Player": 11}, min_per_cycle=2)
    check("每輪門檻 2:多 10 個 = 5×2 → 沒過", [x[0] for x in v] == ["threshold_failures"], r.stdout)
    v, r, _ = run({"com.sdk.Player": 1}, {"com.sdk.Player": 11}, exclude_prefixes=["com.sdk."])
    check("自訂排除清單蓋掉預設:排除 com.sdk. 後通過", [x[0] for x in v] == ["threshold_passed"], r.stdout)
    v, r, _ = run({}, {"com.sdk.New": 5})
    check("第一份沒有、第二份有 5 個的類別算增加 5", [x[0] for x in v] == ["threshold_failures"], r.stdout)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        res = _ms_result(heap={"status": "ok", "before": {"a.b": 1}, "after": {"a.b": 6}, "classes_seen": {"before": 9, "after": 9}, "class_names": "raw"})
        _, r, _d, rt = _ms_root(td, [_ms_thr("java_growth")], res)
        check("類別名沒還原時文字輸出標明(沒給 R8 mapping)", "類別名未還原" in rt.stdout, rt.stdout)


def t_android_memstab_instance_limit():
    """S3:宣告類別在第二份快照超過上限 → 沒過並印類別名與實例數;只在第一份有 → 算 0;兩份都沒有 → 跳過並說可能拼錯或混淆。"""
    import tempfile
    def run(before, after, mx=1, text=False):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            res = _ms_result(heap={"status": "ok", "before": before, "after": after, "classes_seen": {"before": 9000, "after": 9000}})
            _, r, d, rt = _ms_root(td, [_ms_thr("instances", **{"class": "com.sdk.Player", "max": mx})], res, text=text)
            return _ms_verdict(d), r, rt
    v, r, rt = run({"com.sdk.Player": 1}, {"com.sdk.Player": 5}, text=True)
    check("5 個 > 上限 1 → 沒過", [x[0] for x in v] == ["threshold_failures"], r.stdout + r.stderr)
    check("沒過那筆附類別名與實例數", v and v[0][2].get("class") == "com.sdk.Player" and v[0][2].get("count") == 5, str(v))
    check("文字輸出印出類別名與實例數(實例數與上限沒印反)", "com.sdk.Player 有 5 個(上限 1)" in rt.stdout, rt.stdout)
    v, r, _ = run({"com.sdk.Player": 1}, {"com.sdk.Player": 1})
    check("1 個 = 上限 → 通過", [x[0] for x in v] == ["threshold_passed"], r.stdout)
    v, r, _ = run({"com.sdk.Player": 3}, {}, mx=0)
    check("只在第一份有 → 第二份算 0 個 → 通過", [x[0] for x in v] == ["threshold_passed"], r.stdout)
    v, r, _ = run({"com.other.X": 1}, {"com.other.X": 1})
    check("兩份都沒有實例、也沒有類別物件 → 跳過(不是通過)", [x[0] for x in v] == ["threshold_skipped"], r.stdout)
    check("跳過原因提到拼錯或混淆", v and ("拼錯" in v[0][2].get("reason", "") and "混淆" in v[0][2].get("reason", "")), str(v))
    cls = "java.lang.Class<com.sdk.Player>"
    v, r, _ = run({cls: 1}, {cls: 1}, mx=0)
    check("沒有實例但有類別物件(載入過、實例都釋放了)→ 算 0 個 → 通過(2026-10-24 實驗室正常版)", [x[0] for x in v] == ["threshold_passed"]
          and v[0][2].get("count") == 0, str(v))


def t_android_memstab_peak_vitals_floor():
    """S4:依 total_mem_mb 與 category 照官方區間(含下界不含上界)查前景上限;超過 → 沒過;區間外 → 跳過並說原因。"""
    import tempfile
    GB = 1024 * 1024   # KB
    cases = [(7213, "app", 2.25 * GB + 1, "threshold_failures"),    # SM-X710 實測 MemTotal 約 7213 MB → 6800到9216 級 2.25 GB
             (7213, "app", 2.25 * GB, "threshold_passed"),
             (6800, "app", 2.25 * GB + 1, "threshold_failures"),    # 下界含:6800 落 6800到9216 級
             (6799, "app", 2.25 * GB, "threshold_passed"),          # 6799 落 4800到6800 級(也是 2.25)
             (4799, "app", 2.0 * GB + 1, "threshold_failures"),     # 3200到4800 級 2.00 GB
             (4800, "game", 2.75 * GB, "threshold_passed"),         # 遊戲 4800到6800 級 2.75 GB
             (4800, "game", 2.75 * GB + 1, "threshold_failures"),
             (3199, "app", 99 * GB, "threshold_skipped"),           # 低於 3200 沒有官方數字
             (18432, "app", 99 * GB, "threshold_skipped")]          # 至少 18432 沒有官方數字
    for mem, cat, peak, want in cases:
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            ct = dict(_ms_result()["cycle_trace"], peak_anon_swap_kb=peak)
            res = _ms_result(total_mem_mb=mem, category=cat, cycle_trace=ct)
            _, r, d, _ = _ms_root(td, [_ms_thr("peak_vitals")], res, text=False)
            v = _ms_verdict(d)
            check(f"{mem} MB {cat} 峰值 {peak / GB:.4f} GB → {want}", [x[0] for x in v] == [want], r.stdout + r.stderr)
            if want == "threshold_skipped":
                check("跳過說沒有官方數字", "官方" in v[0][2].get("reason", ""), str(v))


def t_android_memstab_exits():
    """S5:新增紀錄裡有崩潰、原生崩潰、ANR、低記憶體被殺、記憶體上限,或三次 pid 不一樣 → 沒過並印種類;只有其他原因 → 通過並回報。"""
    import tempfile
    def run(new, pids=(100, 100, 100), text=False):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            res = _ms_result(exits={"status": "ok", "new": new}, pids={"status": "ok", "values": list(pids)})
            _, r, d, rt = _ms_root(td, [_ms_thr("exits")], res, text=text)
            return _ms_verdict(d), r, rt
    for typ in ("crash", "native_crash", "anr", "low_memory", "memory_limiter"):
        v, r, rt = run([{"type": typ, "reason": 4, "pid": 100, "timestamp": "2026-10-24 02:37:24.652", "desc": "x"}], text=True)
        check(f"新增一筆 {typ} → 沒過", [x[0] for x in v] == ["threshold_failures"], r.stdout + r.stderr)
        check(f"{typ} 印出種類", typ in rt.stdout, rt.stdout)
    v, r, rt = run([{"type": "other", "reason": 10, "pid": 100, "timestamp": "2026-10-24 02:37:24.652", "desc": "user"}], text=True)
    check("只有使用者要求那種 → 通過", [x[0] for x in v] == ["threshold_passed"], r.stdout)
    check("通過那筆仍回報其他原因的紀錄", v and v[0][2].get("other") == 1, str(v))
    check("文字輸出也逐條印達標那筆(S5 要回報其他原因的結束紀錄)", "[達標] pkg.Leak#cycle exits:只有 1 筆其他原因的結束紀錄" in rt.stdout, rt.stdout)
    v, r, _ = run([], pids=(100, 100, 222))
    check("三次 pid 不一樣 → 沒過", [x[0] for x in v] == ["threshold_failures"], r.stdout)


def t_android_memstab_strictmode():
    """S7:有違規 → 沒過;設定沒宣告 strictmode(收集腳本記 unsupported)或日誌串流中斷(failed)→ 跳過。"""
    import tempfile
    def run(sm):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            _, r, d, _ = _ms_root(td, [_ms_thr("strictmode")], _ms_result(strictmode=sm), text=False)
            return _ms_verdict(d), r
    v, r = run({"status": "ok", "violations": [{"type": "LeakedClosableViolation"}]})
    check("一筆違規 → 沒過", [x[0] for x in v] == ["threshold_failures"], r.stdout + r.stderr)
    v, r = run({"status": "ok", "violations": []})
    check("零筆且收得到 → 通過", [x[0] for x in v] == ["threshold_passed"], r.stdout)
    v, r = run({"status": "unsupported", "reason": "設定沒宣告 strictmode"})
    check("沒宣告 → 跳過", [x[0] for x in v] == ["threshold_skipped"], r.stdout)
    v, r = run({"status": "failed", "reason": "日誌串流中斷"})
    check("串流中斷 → 跳過(不是通過)", [x[0] for x in v] == ["threshold_skipped"], r.stdout)


def t_android_memstab_frozen_frame():
    """S8:凍結幀 > 0 → 沒過;設了 max_block_ms 而最長阻塞超過 → 沒過;沒設只回報;frames 欄位是 0 → 跳過。"""
    import tempfile
    def run(ct, **thr):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            full = dict(_ms_result()["cycle_trace"], **ct)
            _, r, d, _ = _ms_root(td, [_ms_thr("frozen", **thr)], _ms_result(cycle_trace=full), text=False)
            return _ms_verdict(d), r
    v, r = run({"frozen_frames": 1})
    check("一幀超過 700ms → 沒過", [x[0] for x in v] == ["threshold_failures"], r.stdout + r.stderr)
    v, r = run({"frozen_frames": 0, "max_main_block_ms": 650})
    check("沒設阻塞上限、最長 650ms → 通過並回報", [x[0] for x in v] == ["threshold_passed"] and v[0][2].get("max_main_block_ms") == 650, str(v))
    v, r = run({"frozen_frames": 0, "max_main_block_ms": 650}, max_block_ms=500)
    check("設了 500ms、最長 650ms → 沒過", [x[0] for x in v] == ["threshold_failures"], r.stdout)
    v, r = run({"frozen_frames": 0, "frames": 0})
    check("frames 是 0(沒錄到幀)→ 跳過", [x[0] for x in v] == ["threshold_skipped"], r.stdout)


def t_android_memstab_source_not_ok_skipped():
    """S11:來源 status 不是 ok、欄位缺、值是 -1 或不是有限數 → 跳過不通過;driver 不是 ok → 需要完整 N 輪的五種跳過,exits 與 strictmode 照判。"""
    import tempfile
    all_checks = [_ms_thr("native_unreachable"), _ms_thr("java_growth"), _ms_thr("instances", **{"class": "com.sdk.Player", "max": 9}),
                  _ms_thr("peak_vitals"), _ms_thr("exits"), _ms_thr("strictmode"), _ms_thr("frozen")]
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        res = _ms_result(driver={"status": "failed", "reason": "FAILURES!!!"},
                         exits={"status": "ok", "new": [{"type": "crash", "reason": 4, "pid": 100, "timestamp": "t", "desc": "x"}]})
        _, r, d, _ = _ms_root(td, all_checks, res, text=False)
        got = {c: k for k, c, _ in _ms_verdict(d)}
        check("前置:七條都有判定", len(got) == 7, str(got))
        check("driver 失敗:五種需要完整 N 輪的跳過",
              all(got.get(c) == "threshold_skipped" for c in ("native_unreachable", "java_growth", "instances", "peak_vitals", "frozen")), str(got))
        check("driver 失敗:exits 照判(量測輪崩潰 → 沒過)", got.get("exits") == "threshold_failures", str(got))
        check("driver 失敗:strictmode 照判", got.get("strictmode") == "threshold_passed", str(got))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        res = _ms_result(pids={"status": "ok", "values": [100, 100, 222]},
                         exits={"status": "ok", "new": [{"type": "crash", "reason": 4, "pid": 100, "timestamp": "t", "desc": "x"}]})
        _, r, d, _ = _ms_root(td, all_checks, res, text=False)
        got = {c: k for k, c, _ in _ms_verdict(d)}
        check("行程換過(中途崩潰後被重啟,2026-10-24 實驗室):五種需要完整 N 輪的跳過",
              all(got.get(c) == "threshold_skipped" for c in ("native_unreachable", "java_growth", "instances", "peak_vitals", "frozen")), str(got))
        check("行程換過:exits 照判沒過", got.get("exits") == "threshold_failures", str(got))
    bad = [("unreachable", {"status": "failed", "reason": "掃描逾時"}, "native_unreachable"),
           ("unreachable", {"status": "ok", "before": {"bytes": 0, "allocations": 0}, "after": {"bytes": float("nan"), "allocations": 0}}, "native_unreachable"),
           ("unreachable", {"status": "ok", "before": {"bytes": 0, "allocations": 0}, "after": {"bytes": True, "allocations": 0}}, "native_unreachable"),
           ("heap", {"status": "unsupported", "reason": "沒宣告測試資料"}, "java_growth"),
           ("cycle_trace", dict(_ms_result()["cycle_trace"], peak_anon_swap_kb=-1), "peak_vitals"),
           ("exits", {"status": "failed", "reason": "沒有全域標頭"}, "exits")]
    for src, val, chk in bad:
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            res = _ms_result(**{src: val})   # NaN 由 _ms_root 的 json.dumps 寫成 NaN 字面
            _, r, d, _ = _ms_root(td, [t for t in all_checks if t["check"] == chk], res, text=False)
            v = _ms_verdict(d)
            check(f"{src}={str(val)[:40]} → {chk} 跳過", [x[0] for x in v] == ["threshold_skipped"], r.stdout + r.stderr)
            check(f"{src} 跳過附原因", v and v[0][2].get("reason"), str(v))


def t_android_memstab_check_compat():
    """S13:沒寫 check 的條目照舊對 Macrobenchmark 結果檔判、結果不變;不認得的 check、缺欄位、門檻不是有限數 → 回 2;
    沒給 --stability 時 check 條目跳過;check 條目沒過時文字輸出不因缺 metric 出錯。"""
    import json, tempfile
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        root, r, d, rt = _mb_thr_root(td, [_mb_scroll("pkg.Flow", 3.6)], [_mb_thr(), _ms_thr("exits")])
        legacy = [x for x in d.get("threshold_failures", []) if not x.get("check")]
        check("舊條目照舊判沒達、附現值", len(legacy) == 1 and legacy[0].get("current") == 3.6, r.stdout + r.stderr)
        skipped = [x for x in d.get("threshold_skipped", []) if x.get("check") == "exits"]
        check("沒給 --stability:check 條目跳過並說原因", len(skipped) == 1 and "stability" in skipped[0].get("reason", ""), r.stdout)
        check("兩種條目並存時文字輸出回 0", rt.returncode == 0, rt.stderr)
    for bad, why in ((_ms_thr("leakz"), "不認得的 check"), (_ms_thr("instances", max=1), "instances 缺 class"),
                     (_ms_thr("instances", **{"class": "c"}), "instances 缺 max"),
                     (_ms_thr("native_unreachable", max_bytes=float("inf")), "門檻不是有限數"),
                     (_ms_thr("exits", decided_at="2026-13-40"), "日期不是真的日期"),
                     (_ms_thr("exits", contract=None), "缺 contract")):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            root = Path(td)
            (root / ".lumos").mkdir()
            (root / ".lumos" / "macrobench-thresholds.json").write_text(json.dumps({"version": 1, "thresholds": [bad]}), encoding="utf-8")
            (root / "s.json").write_text(json.dumps(_ms_result()), encoding="utf-8")
            r = _mb_run(root, "--stability", str(root / "s.json"))
            check(f"{why} → 回 2 並印擋下", r.returncode == 2 and "擋下" in r.stderr, r.stdout + r.stderr)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        _, r, d, rt = _ms_root(td, [_ms_thr("exits")], _ms_result(exits={"status": "ok", "new": [
            {"type": "anr", "reason": 6, "pid": 100, "timestamp": "t", "desc": "x"}]}))
        check("check 條目沒過時文字輸出回 0、印 check 名", rt.returncode == 0 and "exits" in rt.stdout and "Traceback" not in rt.stderr,
              rt.stdout + rt.stderr)


def t_android_memstab_stability_config():
    """S14:沒有 .lumos/macrobench.json、或只有 stability 段沒有 results_dirs 時照樣判 check 條目;
    只有 stability 段時 --update-baseline 說沒有結果目錄、回 0;結果檔讀不了或不是 JSON → 回 2 擋下。"""
    import json, tempfile
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        _, r, d, _ = _ms_root(td, [_ms_thr("exits")], _ms_result(), text=False)
        check("沒有 macrobench.json 也判", [x[0] for x in _ms_verdict(d)] == ["threshold_passed"], r.stdout + r.stderr)
    stab = {"stability": {"package": "com.example.mblab", "scenario": "pkg.Leak#cycle", "driver": "x {{CYCLES}}",
                          "warmup": 2, "cycles": 5}}
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        root, r, d, _ = _ms_root(td, [_ms_thr("exits")], _ms_result(), config=stab)
        check("只有 stability 段也判", [x[0] for x in _ms_verdict(d)] == ["threshold_passed"], r.stdout + r.stderr)
        u = _mb_run(root, "--update-baseline")
        check("只有 stability 段:--update-baseline 說沒有結果目錄、回 0", u.returncode == 0 and "results_dirs" in u.stdout, u.stdout + u.stderr)
        c = _mb_run(root, "--check-config")
        check("--check-config 設定合格 → 回 0", c.returncode == 0, c.stdout + c.stderr)
    for bad, why in (({"stability": dict(stab["stability"], cycles=0)}, "cycles 是 0"),
                     ({"stability": dict(stab["stability"], warmup=0)}, "warmup 是 0"),
                     ({"stability": dict(stab["stability"], package="com.x; rm -rf /")}, "套件名有怪字元"),
                     ({"stability": dict(stab["stability"], category="toy")}, "category 不是 app 或 game"),
                     ({"stability": dict(stab["stability"], test_data=True)}, "test_data 沒署名日期")):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            root = Path(td)
            (root / ".lumos").mkdir()
            (root / ".lumos" / "macrobench.json").write_text(json.dumps(bad), encoding="utf-8")
            c = _mb_run(root, "--check-config")
            check(f"--check-config:{why} → 回 2 擋下", c.returncode == 2 and "擋下" in c.stderr, c.stdout + c.stderr)
    for content, why in (("{not json", "不是 JSON"), (None, "檔案不存在"), ("[1, 2]", "最外層不是物件")):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            root = Path(td)
            (root / ".lumos").mkdir()
            (root / ".lumos" / "macrobench-thresholds.json").write_text(json.dumps({"version": 1, "thresholds": [_ms_thr("exits")]}), encoding="utf-8")
            if content is not None:
                (root / "s.json").write_text(content, encoding="utf-8")
            r = _mb_run(root, "--stability", str(root / "s.json"))
            check(f"結果檔{why} → 回 2 擋下", r.returncode == 2 and "擋下" in r.stderr, r.stdout + r.stderr)


def _ms_sql(name, setup):
    """拿 Python 內建 sqlite3 照 Perfetto 文件建同名的表,跑工具鏈範本裡的查詢;範本不在回 None。"""
    import sqlite3
    tpl = Path(GRAPHCTL).resolve().parent / "templates" / name
    if not tpl.is_file():
        return None
    db = sqlite3.connect(":memory:")
    db.executescript("create table process(upid integer primary key, pid int, name text);"
                     "create table thread(utid integer primary key, tid int, name text, upid int);"
                     "create table thread_track(id integer primary key, utid int);"
                     "create table slice(id integer primary key, ts int, dur int, track_id int, name text, depth int, parent_id int);"
                     "create table process_counter_track(id integer primary key, upid int, name text);"
                     "create table counter(id integer primary key, ts int, track_id int, value real);"
                     "create table actual_frame_timeline_slice(id integer primary key, ts int, dur int, upid int);"
                     "create table heap_graph_class(id integer primary key, name text);"
                     "create table heap_graph_object(id integer primary key, upid int, type_id int, reachable int);"
                     "insert into process values (1, 100, 'com.lab'), (2, 200, 'com.other');"
                     "insert into thread values (1, 100, 'com.lab', 1), (2, 101, 'RenderThread', 1), (3, 200, 'com.other', 2);"
                     "insert into thread_track values (1, 1), (2, 2), (3, 3);"
                     "insert into process_counter_track values (1, 1, 'mem.rss.anon'), (2, 1, 'mem.swap'), (3, 2, 'mem.rss.anon');")
    db.executescript(setup)
    sql = tpl.read_text(encoding="utf-8").replace("__PROCESS__", "com.lab")
    return db.execute(sql).fetchall()


def t_android_memstab_cycle_query():
    """S9:追蹤檔查詢一列:cycle、匿名常駐加 swap 最大值(swap 取之前最近一次)、凍結幀(有幀時間線用幀時間線)、主執行緒最長最上層區段、幀數;量不到 -1。"""
    MB, ms = 1024 * 1024, 1_000_000
    setup = (f"insert into counter(ts, track_id, value) values (0, 2, {10 * MB}), (100, 1, {100 * MB}), (200, 1, {150 * MB}),"
             f" (300, 2, {40 * MB}), (400, 1, {120 * MB}), (500, 3, {999 * MB});"   # 別的行程那筆 999 MB 不能算進來
             f"insert into actual_frame_timeline_slice(ts, dur, upid) values (0, {16 * ms}, 1), (100, {701 * ms}, 1), (200, {700 * ms}, 1),"
             f" (300, {900 * ms}, 2);"   # 別的行程的凍結幀不算;剛好 700ms 不算凍結
             f"insert into slice(ts, dur, track_id, name, depth) values (0, {650 * ms}, 1, 'activityStart', 0), (0, {600 * ms}, 1, 'inflate', 1),"
             f" (0, {2000 * ms}, 2, 'DrawFrame', 0), (0, {3000 * ms}, 3, 'other', 0);")
    rows = _ms_sql("android-stability-cycle.sql", setup)
    check("前置:範本在", rows is not None)
    if rows is None:
        return
    check("恰好一列、第一欄是字串 cycle", len(rows) == 1 and rows[0][0] == "cycle", str(rows))
    _key, peak, frozen, block, frames = rows[0]
    # 峰值:200 那點 anon 150 MB 配之前最近的 swap 10 MB = 160 MB;400 那點 120 + 40 = 160 MB;取最大 160 MB
    check("峰值 = anon 加之前最近一次 swap 的最大值,只算這個 App", peak == 160 * 1024, str(rows))
    check("凍結幀只算超過 700ms、只算這個 App", frozen == 1, str(rows))
    check("主執行緒最長最上層區段 650ms(RenderThread 與別的行程不算、子區段不算)", block == 650, str(rows))
    check("幀數 = 這個 App 的幀時間線筆數", frames == 3, str(rows))
    rows = _ms_sql("android-stability-cycle.sql",
                   f"insert into slice(ts, dur, track_id, name, depth) values (0, {800 * ms}, 1, 'Choreographer#doFrame 12345', 0),"
                   f" (900, {16 * ms}, 1, 'Choreographer#doFrame 12346', 0);")
    check("沒有幀時間線時用名稱以 Choreographer#doFrame 開頭的區段(帶幀號也認)", rows and rows[0][2] == 1 and rows[0][4] == 2, str(rows))
    check("沒有記憶體計數 → 峰值 -1", rows and rows[0][1] == -1, str(rows))
    rows = _ms_sql("android-stability-cycle.sql", "")
    check("什麼都沒有 → 峰值 -1、阻塞 -1、幀數 0", rows == [("cycle", -1, 0, -1, 0)], str(rows))


def t_android_memstab_heap_query():
    """S10:快照查詢每個類別一列、第一欄是類別名、只算還有人指著的物件、同名類別加總成一列、只算這個 App。"""
    setup = ("insert into heap_graph_class values (1, 'com.sdk.Player'), (2, 'com.sdk.Player'), (3, 'java.lang.String');"
             "insert into heap_graph_object(upid, type_id, reachable) values (1, 1, 1), (1, 1, 1), (1, 2, 1), (1, 1, 0),"
             " (1, 3, 1), (2, 1, 1), (2, 3, 1);")
    rows = _ms_sql("android-heap-classes.sql", setup)
    check("前置:範本在", rows is not None)
    if rows is None:
        return
    got = dict(rows)
    check("同名類別(兩個 classloader)加總、不算沒人指著的、不算別的行程", got.get("com.sdk.Player") == 3, str(rows))
    check("每個類別一列", got == {"com.sdk.Player": 3, "java.lang.String": 1}, str(rows))
    check("第一欄是類別名字串", all(isinstance(r[0], str) for r in rows), str(rows))


def t_android_memstab_templates_receipt_safe():
    """兩支新範本的註解沒有以分號結尾的行(收據重跑腳本拿第一個分號結尾的行當查詢結尾),整支只有最後一行以分號結尾。"""
    tdir = Path(GRAPHCTL).resolve().parent / "templates"
    for name in ("android-stability-cycle.sql", "android-heap-classes.sql"):
        f = tdir / name
        check(f"前置:{name} 在", f.is_file())
        if not f.is_file():
            continue
        lines = [x.rstrip() for x in f.read_text(encoding="utf-8").splitlines() if x.strip()]
        semi = [i for i, x in enumerate(lines) if x.endswith(";")]
        check(f"{name} 只有最後一行以分號結尾", semi == [len(lines) - 1], str([lines[i] for i in semi]))


_MS_FAKE_ADB = r"""#!/usr/bin/env python3
import os, sys, time
d = os.environ["FAKE_DIR"]
def nxt(name):
    # 依序回 name.0、name.1…;沒有下一份就一直回最後一份
    c = os.path.join(d, name + ".count")
    i = int(open(c).read()) if os.path.exists(c) else 0
    open(c, "w").write(str(i + 1))
    for k in (i, i - 1, 0):
        f = os.path.join(d, f"{name}.{k}")
        if k >= 0 and os.path.exists(f):
            return open(f).read()
    return ""
a = sys.argv[1:]
open(os.path.join(d, "adb.log"), "a").write(" ".join(a) + "\n")
if a[0] == "push":
    sys.exit(0)
if a[0] == "pull":
    open(a[2], "w").write("trace")
    sys.exit(0)
if a[0] == "logcat":
    if os.path.exists(os.path.join(d, "logcat_dies")):
        sys.exit(1)   # 裝置斷線、--pid 無效:串流一開就結束
    if "-T" not in a and os.path.exists(os.path.join(d, "logcat_before_t0.txt")):
        sys.stdout.write(open(os.path.join(d, "logcat_before_t0.txt")).read())   # 沒帶 -T 時會倒出量測開始前的舊日誌
    sys.stdout.write(open(os.path.join(d, "logcat.txt")).read() if os.path.exists(os.path.join(d, "logcat.txt")) else "")
    sys.stdout.flush()
    time.sleep(60)
    sys.exit(0)
c = a[1] if a[0] == "shell" else ""
if c.startswith("getprop ro.product.model"): print("SM-X710")
elif c.startswith("getprop ro.build.version.sdk"): print("36")
elif c.startswith("cat /proc/meminfo"): print("MemTotal:        7386728 kB")
elif c.startswith("dumpsys activity exit-info"): sys.stdout.write(nxt("exitinfo"))
elif c.startswith("pidof"): sys.stdout.write(nxt("pid"))
elif "--unreachable" in c:
    if os.path.exists(os.path.join(d, "unreach_offline")):
        sys.stderr.write("error: device offline\n")   # adb 自己的錯誤走標準錯誤
        sys.exit(1)
    sys.stdout.write(nxt("unreachable"))
elif c.startswith("dumpsys meminfo"): print(" Native Heap:     4816                           7208")
elif c.startswith("date"): print("10-24 03:00:00.000")
elif c.startswith("perfetto"):
    if os.path.exists(os.path.join(d, "perfetto_fails")): print("errno: 13, Permission denied"); sys.exit(1)
    if os.path.exists(os.path.join(d, "perfetto_slow")):
        time.sleep(5)   # 錄製已經在裝置上開起來、pid 還沒回來
    print("4321")
elif c.startswith("pkill"):
    open(os.path.join(d, "termed"), "w").write("1")
elif c.startswith("rm -f") and os.path.exists(os.path.join(d, "device_gone")):
    sys.stderr.write("error: device not found\n")   # 裝置沒回應:收尾刪不到暫存
    sys.exit(1)
elif c.startswith("kill -TERM"):
    if os.path.exists(os.path.join(d, "term_slow")):
        time.sleep(3)   # 裝置卡住:收尾的裝置呼叫要等很久
    if not os.path.exists(os.path.join(d, "ignores_term")): open(os.path.join(d, "termed"), "w").write("1")
elif c.startswith("kill -KILL"): open(os.path.join(d, "termed"), "w").write("1")
elif c.startswith("kill -0"): print("/system/bin/sh: kill: 4321: Permission denied"); sys.exit(1)   # 實機:shell 不准對 perfetto 送 kill -0
elif c.startswith("ps -A"):
    if os.path.exists(os.path.join(d, "ps_slow")):
        time.sleep(4)   # 慢機器:中斷會落在送出 kill -TERM 之前
    c_ps = os.path.join(d, "ps.count")
    n_ps = int(open(c_ps).read()) if os.path.exists(c_ps) else 0
    open(c_ps, "w").write(str(n_ps + 1))
    f_ps = os.path.join(d, "ps_fail_n")   # 前 N 次 ps 失敗(adb 偶發),失敗時留標記給前置斷言
    if os.path.exists(f_ps) and n_ps < int(open(f_ps).read()):
        open(os.path.join(d, "ps_failed"), "a").write(f"{n_ps}\n")
        sys.exit(255)
    # 別的行程:pid 開頭相同(43210)、名字含錄製 pid 的,都不能被當成錄製還活著
    lines = ["999 surfaceflinger", "43210 other", "555 perfetto4321"]
    if not (os.path.exists(os.path.join(d, "record_dies_early")) or os.path.exists(os.path.join(d, "termed"))):
        lines.append("4321 perfetto")
    print("\n".join(lines))   # 腳本不在裝置上 grep:全部行程照列,只靠腳本自己比對 pid
"""
