_MS_EXIT_HEAD = "ACTIVITY MANAGER PROCESS EXIT INFO (dumpsys activity exit-info)\nLast Timestamp of Persistence Into Persistent Storage: 2026-10-24 02:12:32.070\n"


def _ms_exit_rec(i, pid, ts, reason, name, desc="x"):
    return (f"        ApplicationExitInfo #{i}:\n"
            f"          timestamp={ts} pid={pid} realUid=10229 packageUid=10229 definingUid=10229 user=0\n"
            f"          process=com.lab reason={reason} ({name}) subreason=0 (UNKNOWN) status=0\n"
            f"          importance=100 pss=0.00 rss=0.00 description={desc} state=empty trace=null\n")


def _ms_collect_env(fake):
    """收集腳本用的假工具環境;LUMOS_STABILITY_SETTLE 把腳本裡等 App 起來、等日誌跟上的兩秒縮短(測試用,預設 2)。"""
    import os
    # 全域 git 設定隔離:使用者的全域 gitignore(~/.gitconfig 指的檔、或 $XDG_CONFIG_HOME/git/ignore)有 .lumos/ 時,
    # 「產物目錄沒被忽略」那幾條會誤紅(代碼審 r2、r3 通才席);XDG_CONFIG_HOME 指到不存在的目錄

    return dict(os.environ, ADB=str(fake / "adb"), TP=str(fake / "tp"), JAVA_HEAP_DUMP=str(fake / "jhd"), FAKE_DIR=str(fake),
                GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM="1", XDG_CONFIG_HOME=str(fake / "xdg-empty"),
                LUMOS_STABILITY_SETTLE="0.1", LUMOS_STABILITY_STOP_TIMEOUT="2")


def _ms_collect(td, **kw):
    """在暫存專案跑工具鏈的收集腳本,adb、trace_processor、java_heap_dump 與驅動都用假的。回 (CompletedProcess, 結果 dict, 假工具目錄)。"""
    import json, subprocess as sp
    root, fake, script = _ms_prepare(td, **kw)   # 參數與預設值只寫在 _ms_prepare 一處
    r = sp.run(["sh", str(script), "run1"], cwd=root, capture_output=True, text=True, env=_ms_collect_env(fake), timeout=120)
    out = root / ".lumos" / "artifacts" / "android" / "run1" / "stability.json"
    return r, (json.loads(out.read_text(encoding="utf-8")) if out.is_file() else {}), fake


def _ms_prepare(td, *, exit_before, exit_after, pids=("100", "100", "100"), unreachable=("0 bytes in 0 unreachable allocations",) * 2,
                driver_out="INSTRUMENTATION_CODE: -1", driver_rc=0, stability=None, heap=({"com.sdk.Player": 1}, {"com.sdk.Player": 6}),
                logcat="", thresholds=None):
    """備好暫存專案與假工具,不跑收集腳本。回 (專案根, 假工具目錄, 收集腳本路徑)。"""
    import json
    root, fake = Path(td) / "proj", Path(td) / "fake"
    (root / ".lumos").mkdir(parents=True, exist_ok=True)
    fake.mkdir(exist_ok=True)
    for name, body in (("adb", _MS_FAKE_ADB), ("tp", _MS_FAKE_TP), ("jhd", _MS_FAKE_JHD)):
        (fake / name).write_text(body, encoding="utf-8")
        (fake / name).chmod(0o755)
    (fake / "driver").write_text(f"#!/bin/sh\necho \"$@\" >> \"$FAKE_DIR/driver.log\"\n[ -f \"$FAKE_DIR/driver_sleeps\" ] && [ \"$1\" = 5 ] && \"$FAKE_DIR/sleeper\"\n"
                                 f"echo '{driver_out}'\nexit {driver_rc}\n", encoding="utf-8")
    (fake / "driver").chmod(0o755)
    # 驅動底下的子程序:自己睡、不另開 sleep,命令列一直帶假工具目錄,孤兒查得到(代碼審 r4 測試資安席)
    (fake / "sleeper").write_text("#!/usr/bin/env python3\nimport time\ntime.sleep(30)\n", encoding="utf-8")
    (fake / "sleeper").chmod(0o755)
    (fake / "exitinfo.0").write_text(exit_before, encoding="utf-8")
    (fake / "exitinfo.1").write_text(exit_after, encoding="utf-8")
    for i, v in enumerate(pids):
        (fake / f"pid.{i}").write_text(v + "\n", encoding="utf-8")
    for i, v in enumerate(unreachable):
        (fake / f"unreachable.{i}").write_text(f" Unreachable memory\n  {v}\n  ABI: 'arm64'\n", encoding="utf-8")
    for tag, counts in zip(("before", "after"), heap):
        (fake / f"heap.{tag}").write_text("".join(f'"{k}","{v}"\n' for k, v in counts.items()), encoding="utf-8")
    (fake / "logcat.txt").write_text(logcat, encoding="utf-8")
    st = {"package": "com.lab", "scenario": "pkg.Leak#cycle", "driver": f"{fake / 'driver'} {{{{CYCLES}}}}", "warmup": 2, "cycles": 5}
    st.update(stability or {})
    (root / ".lumos" / "macrobench.json").write_text(json.dumps({"stability": st}), encoding="utf-8")
    if thresholds is not None:
        (root / ".lumos" / "macrobench-thresholds.json").write_text(json.dumps({"version": 1, "thresholds": thresholds}), encoding="utf-8")
    return root, fake, Path(GRAPHCTL).resolve().parent / "templates" / "android-stability-collect.sh"


def t_android_memstab_exit_info_diff():
    """S6:只留後一份多出來的紀錄(pid 加 timestamp 比)並依 reason 與描述分類;只有全域標頭沒有套件區段是零筆 ok;沒有全域標頭是 failed。"""
    import tempfile
    pkg = "  package: com.lab\n    Historical Process Exit for uid=10229\n"
    old = _ms_exit_rec(0, 90, "2026-10-23 23:52:02.173", 10, "USER REQUESTED")
    new_recs = (_ms_exit_rec(0, 100, "2026-10-24 03:00:05.000", 4, "APP CRASH(EXCEPTION)") +
                _ms_exit_rec(1, 101, "2026-10-24 03:00:06.000", 5, "APP CRASH(NATIVE)") +
                _ms_exit_rec(2, 102, "2026-10-24 03:00:07.000", 6, "ANR") +
                _ms_exit_rec(3, 103, "2026-10-24 03:00:08.000", 3, "LOW MEMORY") +
                _ms_exit_rec(4, 104, "2026-10-24 03:00:09.000", 13, "OTHER KILLS BY SYSTEM", desc="MemoryLimiter:AnonSwap") +
                _ms_exit_rec(5, 105, "2026-10-24 03:00:10.000", 10, "USER REQUESTED"))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        r, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD + pkg + old, exit_after=_MS_EXIT_HEAD + pkg + new_recs + old)
        ex = d.get("exits", {})
        check("收集腳本回 0 並寫出結果檔", r.returncode == 0 and d, r.stdout + r.stderr)
        check("結束紀錄 status ok", ex.get("status") == "ok", str(ex))
        types = [e.get("type") for e in ex.get("new", [])]
        check("只留後一份多的 6 筆,舊的那筆不算", len(types) == 6, str(ex))
        check("依 reason 與描述分類", types == ["crash", "native_crash", "anr", "low_memory", "memory_limiter", "other"], str(types))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        _, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("只有全域標頭、沒有套件區段 → 零筆且 ok", d.get("exits") == {"status": "ok", "new": []}, str(d.get("exits")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        _, d, _ = _ms_collect(td, exit_before="Error: unknown command\n", exit_after=_MS_EXIT_HEAD)
        check("連全域標頭都沒有 → failed", d.get("exits", {}).get("status") == "failed", str(d.get("exits")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        other = "  package: com.other\n    Historical Process Exit for uid=1\n" + _ms_exit_rec(0, 7, "2026-10-24 03:00:01.000", 4, "APP CRASH")
        _, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD + other)
        check("別的套件的崩潰不算", d.get("exits") == {"status": "ok", "new": []}, str(d.get("exits")))


def t_android_memstab_collect_test_data_gate():
    """S15:沒宣告測試資料 → 不錄快照、heap 是 unsupported;開跑先刪產物目錄底下超過 7 天的 heap-*.pftrace,不刪別的檔;
    宣告了才錄快照,且結果檔只存有增減的類別與門檻檔宣告的類別。"""
    import os, tempfile, time
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        art = Path(td) / "proj" / ".lumos" / "artifacts" / "android" / "old"
        art.mkdir(parents=True)
        old_ts = time.time() - 8 * 86400
        for name in ("heap-before.pftrace", "cycle.pftrace", "heap-notes.txt"):
            (art / name).write_text("x", encoding="utf-8")
            os.utime(art / name, (old_ts, old_ts))
        (art / "heap-after.pftrace").write_text("x", encoding="utf-8")   # 新的(今天)不刪
        r, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("回 0", r.returncode == 0, r.stderr)
        check("沒宣告 → heap 是 unsupported", d.get("heap", {}).get("status") == "unsupported", str(d.get("heap")))
        check("沒宣告 → 沒有呼叫 java_heap_dump", not (fake / "jhd.log").exists())
        check("超過 7 天的 heap-*.pftrace 刪了", not (art / "heap-before.pftrace").exists())
        check("超過 7 天但不是快照樣式的檔沒刪", (art / "cycle.pftrace").exists() and (art / "heap-notes.txt").exists())
        check("今天的快照沒刪", (art / "heap-after.pftrace").exists())
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        elsewhere = Path(td) / "elsewhere"
        elsewhere.mkdir()
        (elsewhere / "heap-x.pftrace").write_text("x", encoding="utf-8")
        os.utime(elsewhere / "heap-x.pftrace", (time.time() - 9 * 86400,) * 2)
        base = Path(td) / "proj" / ".lumos" / "artifacts" / "android"
        base.mkdir(parents=True)
        (base / "linked").symlink_to(elsewhere, target_is_directory=True)
        _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("產物目錄底下的捷徑指到別處時,別處的舊快照不刪", (elsewhere / "heap-x.pftrace").exists())
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        td_decl = {"test_data": {"value": True, "decided_by": "Enzo", "decided_at": "2026-10-24"}}
        heap = ({"com.sdk.Player": 1, "com.app.Same": 3, "com.app.Declared": 2}, {"com.sdk.Player": 6, "com.app.Same": 3, "com.app.Declared": 2})
        thr = [{"scenario": "pkg.Leak#cycle", "check": "instances", "class": "com.app.Declared", "max": 5,
                "contract": "c", "decided_by": "Enzo", "decided_at": "2026-10-24"}]
        r, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability=td_decl, heap=heap, thresholds=thr)
        h = d.get("heap", {})
        check("宣告了 → heap ok 並錄兩份", h.get("status") == "ok" and (fake / "jhd.log").read_text().count("-n com.lab") == 2, str(h) + r.stderr)
        check("只存有增減的與宣告的類別", set(h.get("after", {})) == {"com.sdk.Player", "com.app.Declared"}, str(h))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        heap = ({"java.lang.Class<com.app.Declared>": 1, "com.app.Other": 1}, {"java.lang.Class<com.app.Declared>": 1, "com.app.Other": 1})
        r, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability=td_decl, heap=heap, thresholds=thr)
        check("宣告類別沒有實例時,它的類別物件照樣存進結果檔", d.get("heap", {}).get("after") == {"java.lang.Class<com.app.Declared>": 1}, str(d.get("heap")))
        log = (fake / "adb.log").read_text()
        check("錄製設定推到 /data/misc/perfetto-configs/(放 /data/local/tmp 時 perfetto 讀不到,2026-10-24 實機)",
              "/data/misc/perfetto-configs/" in log and "/data/local/tmp/lumos-stability" not in log, log[-400:])
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        import subprocess as sp
        root, fake0, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        r = sp.run(["sh", str(script), "mem java -1"], cwd=root, capture_output=True, text=True, env=_ms_collect_env(fake0), timeout=60)
        check("run-id 有空白(會壞掉裝置上的路徑)→ 回 2 擋下", r.returncode == 2 and "run-id" in r.stderr, r.stdout + r.stderr)
        check("run-id 有空白:擋在碰裝置之前(假 adb 一次都沒被叫)", not (fake0 / "adb.log").exists(), (fake0 / "adb.log").read_text()[-200:] if (fake0 / "adb.log").exists() else "")
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        bad = {"test_data": True}
        r, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability=bad)
        check("test_data 沒署名日期 → 回 2 擋下、不寫結果檔", r.returncode == 2 and "擋下" in r.stderr and not d, r.stdout + r.stderr)
        check("test_data 沒署名日期:擋在碰裝置之前(假 adb 一次都沒被叫)", not (fake / "adb.log").exists(), (fake / "adb.log").read_text()[-200:] if (fake / "adb.log").exists() else "")


def t_android_memstab_collect_record_alive():
    """查 ps 本身失敗(adb 偶發)時當成不知道、照樣送 TERM 等它停,不把好的追蹤檔當成提早結束丟掉(代碼審 r3 正確性席)。
    錄製還在跑時(ps 看得到)停止後 cycle_trace 是 ok;錄製在量測跑完前就結束(ps 看不到)→ failed 並說到了上限。
    不能用 kill -0 判斷:實機上 shell 對 perfetto 送 kill -0 回 Permission denied(2026-10-24 SM-X710)。"""
    import tempfile
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        r, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("錄製還在跑 → cycle_trace ok", d.get("cycle_trace", {}).get("status") == "ok", str(d.get("cycle_trace")) + r.stderr)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "record_dies_early").write_text("1", encoding="utf-8")
        r, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        ct = d.get("cycle_trace", {})
        check("錄製提早結束 → cycle_trace failed 並說到了上限", ct.get("status") == "failed" and "上限" in ct.get("reason", ""), str(ct) + r.stderr)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "ps_fail_n").write_text("1", encoding="utf-8")
        r, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("前置:第一次 ps 真的失敗了(假 adb 留了標記)", (fake / "ps_failed").exists())
        check("第一次 ps 失敗 → 再問一次就知道、cycle_trace ok", d.get("cycle_trace", {}).get("status") == "ok", str(d.get("cycle_trace")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 錄製已經到上限停了、ps 又一直失敗:判不出來就不採用(代碼審 r4 正確性席)
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "ps_fail_n").write_text("3", encoding="utf-8")
        (fake / "record_dies_early").write_text("1", encoding="utf-8")
        r, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        ct = d.get("cycle_trace", {})
        check("前置:前三次 ps 都失敗了", (fake / "ps_failed").read_text().count("\n") == 3 if (fake / "ps_failed").exists() else False)
        check("ps 連三次失敗 → cycle_trace failed 並說問不到,不把可能只錄一半的追蹤檔當完整", ct.get("status") == "failed" and "問不到" in ct.get("reason", ""), str(ct))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "perfetto_fails").write_text("1", encoding="utf-8")
        r, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        log = (fake / "adb.log").read_text()
        check("錄製開不起來 → cycle_trace failed", d.get("cycle_trace", {}).get("status") == "failed", str(d.get("cycle_trace")))
        check("錄製開不起來也刪掉推上裝置的設定檔(2026-10-24 實機留下殘檔)", "rm -f /data/misc/perfetto-configs/lumos-stability-run1.pbtxt" in log, log[-300:])
        check("錄製回報失敗也補送停止(回傳碼不是 0 也可能已經開起來;代碼審 r4 資源席)", "pkill -TERM -f /data/misc/perfetto-traces/lumos-stability-run1.pftrace" in log, log[-300:])


def t_android_memstab_collect_driver_status():
    """S16:驅動回傳碼不是 0、或 UI Automator 輸出沒有 INSTRUMENTATION_CODE: -1、或有 FAILURES!!! → driver failed;成功 → ok 並把輪數換進指令。"""
    import tempfile
    cases = (("INSTRUMENTATION_STATUS: ok\\nINSTRUMENTATION_CODE: -1", 0, "ok"),
             ("FAILURES!!!\\nINSTRUMENTATION_CODE: -1", 0, "failed"),
             ("INSTRUMENTATION_CODE: 0", 0, "failed"),
             ("maestro: flow passed", 0, "ok"),
             ("boom", 3, "failed"))
    for out, rc, want in cases:
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            r, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, driver_out=out, driver_rc=rc)
            check(f"驅動輸出 {out[:30]!r} rc{rc} → driver {want}", d.get("driver", {}).get("status") == want, str(d.get("driver")) + r.stderr)
            if want == "ok":
                calls = (fake / "driver.log").read_text().split()
                check("輪數換進指令:暖機 2、量測 5", calls == ["2", "5"], str(calls))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        r, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, pids=("100", "100", "222"),
                              unreachable=("0 bytes in 0 unreachable allocations", "10485760 bytes in 5 unreachable allocations"),
                              stability={"strictmode": True},
                              logcat="D/StrictMode( 100): StrictMode policy violation: android.os.strictmode.LeakedClosableViolation: x\nD/StrictMode( 100): \tat a.b\n")
        check("三次 pid 都記下", d.get("pids", {}).get("values") == [100, 100, 222], str(d.get("pids")))
        log = (Path(td) / "fake" / "adb.log").read_text().splitlines()
        fs = next((i for i, x in enumerate(log) if "am force-stop com.lab" in x), None)
        ex = next((i for i, x in enumerate(log) if "exit-info" in x), None)
        st = next((i for i, x in enumerate(log) if "monkey -p com.lab" in x), None)
        check("開跑先強制停止 App,而且在讀前一次結束紀錄與啟動之前(上一次的殘留不算進這一次)",
              None not in (fs, ex, st) and fs < ex < st, str(log[:8]))
        check("兩次原生掃描都記下總量", d.get("unreachable", {}).get("after") == {"bytes": 10485760, "allocations": 5}, str(d.get("unreachable")))
        sm = d.get("strictmode", {})
        check("StrictMode 一筆違規只算一次(堆疊行不算)", sm.get("status") == "ok" and sm.get("violations") == [{"type": "LeakedClosableViolation"}], str(sm))


def t_android_memstab_vendored():
    """S12:收集腳本、兩支查詢範本與錄製設定要帶 SPDX 檔頭、登記在工具組複製清單,才會跟其他範本一起進消費專案。"""
    m = _load_lumos_inproc()
    tdir = Path(GRAPHCTL).resolve().parent / "templates"
    for name in ("android-stability-collect.sh", "android-stability-cycle.sql", "android-heap-classes.sql", "android-stability-record.pbtxt"):
        rel = f"scripts/templates/{name}"
        check(f"{name} 登記在工具組複製清單", rel in m._VENDORED_TREE_FILES, "")
        f = tdir / name
        check(f"{name} 檔真的在", f.is_file(), "")
        head = f.read_text(encoding="utf-8")[:400] if f.is_file() else ""
        mark = "--" if name.endswith(".sql") else "#"
        check(f"{name} 檔頭有 {mark} 開頭的 SPDX 行", f"{mark} SPDX-License-Identifier: MIT" in head, head[:120])


def t_android_memstab_unreadable_never_passes():
    """代碼審 r1 甲組(讀不到不准當成沒事)的統一規則:每種檢查用到的欄位缺、型別錯、空的、量不到,一律列成跳過並說原因,不列通過、不噴例外;
    唯一例外是 exits:結束紀錄裡有崩潰類,就算 pid 讀不到也判沒過(崩潰後 App 沒被重啟時第三次讀不到 pid,這正是最該抓的情境)。"""
    import json, tempfile
    def verdict(thr, res):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            _, r, d, rt = _ms_root(td, [thr], res)
            v = _ms_verdict(d)
            return (v[0][0] if v else None), (v[0][2] if v else {}), r, rt
    crash = [{"type": "crash", "reason": 4, "pid": 100, "timestamp": "t", "desc": "x"}]
    k, rec, r, _ = verdict(_ms_thr("exits"), _ms_result(exits={"status": "ok", "new": crash},
                                                       pids={"status": "failed", "reason": "有一次讀不到 pid", "values": [100, 100, None]},
                                                       driver={"status": "failed", "reason": "FAILURES!!!"}))
    check("崩潰後沒被重啟(第三次讀不到 pid、驅動也失敗)→ exits 沒過", k == "threshold_failures" and rec.get("bad_types") == ["crash"], r.stdout + r.stderr)
    k, rec, r, _ = verdict(_ms_thr("exits"), _ms_result(exits={"status": "ok", "new": []},
                                                       pids={"status": "failed", "reason": "讀不到", "values": [100, None, None]}))
    check("沒有崩潰類紀錄、pid 又讀不到 → exits 跳過(判不出 pid 有沒有變)", k == "threshold_skipped", r.stdout)
    cases = [
        ("java_growth 兩份快照都是空的", _ms_thr("java_growth"), _ms_result(heap={"status": "ok", "before": {}, "after": {}})),
        ("frozen 設了阻塞上限但阻塞量不到(-1)", _ms_thr("frozen", max_block_ms=500), _ms_result(cycle_trace=dict(_ms_result()["cycle_trace"], max_main_block_ms=-1))),
        ("exits 缺 new 欄", _ms_thr("exits"), _ms_result(exits={"status": "ok"})),
        ("exits 的 new 是 null", _ms_thr("exits"), _ms_result(exits={"status": "ok", "new": None})),
        ("strictmode 缺 violations 欄", _ms_thr("strictmode"), _ms_result(strictmode={"status": "ok"})),
        ("pids 缺 values 欄", _ms_thr("exits"), _ms_result(pids={"status": "ok"})),
        ("pids 的 values 是巢狀清單", _ms_thr("exits"), _ms_result(pids={"status": "ok", "values": [[1], [2]]})),
        ("heap 的 before 是清單", _ms_thr("java_growth"), _ms_result(heap={"status": "ok", "before": [1], "after": {"a.B": 1}})),
        ("category 寫成清單", _ms_thr("peak_vitals"), _ms_result(category=["app"])),
        ("cycles 是字串", _ms_thr("java_growth"), _ms_result(cycles="5")),
        # 代碼審 r2 邊界席:同一條規則漏網的幾種
        ("unreachable 的 before 是清單", _ms_thr("native_unreachable"), _ms_result(unreachable={"status": "ok", "before": [1], "after": {"bytes": 0, "allocations": 0}})),
        ("strictmode 的 violations 元素不是物件", _ms_thr("strictmode"), _ms_result(strictmode={"status": "ok", "violations": ["DiskReadViolation"]})),
        ("strictmode 的 violations 的 type 不是字串", _ms_thr("strictmode"), _ms_result(strictmode={"status": "ok", "violations": [{"type": 5}]})),
        ("exits 的 new 元素不是物件", _ms_thr("exits"), _ms_result(exits={"status": "ok", "new": ["crash"]})),
        ("cycles 是超大整數", _ms_thr("java_growth"), _ms_result(cycles=10 ** 400)),
        # 代碼審 r3 邊界席:-1 以外的負數也是量不到
        ("凍結幀是 -5", _ms_thr("frozen"), _ms_result(cycle_trace=dict(_ms_result()["cycle_trace"], frozen_frames=-5))),
        ("unreachable 的位元組是負數", _ms_thr("native_unreachable"), _ms_result(unreachable={"status": "ok", "before": {"bytes": -9, "allocations": 0}, "after": {"bytes": 0, "allocations": 0}})),
    ]
    for why, thr, res in cases:
        k, rec, r, rt = verdict(thr, res)
        check(f"{why} → 跳過並附原因", k == "threshold_skipped" and rec.get("reason"), r.stdout + r.stderr)
        check(f"{why} → 不噴例外、回 0", r.returncode == 0 and rt.returncode == 0 and "Traceback" not in r.stderr + rt.stderr, r.stderr + rt.stderr)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 收集到的文字含換行時不能偽造出一行判定(代碼審 r2 資安席)
        res = _ms_result(strictmode={"status": "failed", "reason": "斷了\n  [達標] pkg.Leak#cycle exits:偽造的一行"})
        _, r, _, rt = _ms_root(td, [_ms_thr("strictmode")], res)
        lines = [x for x in rt.stdout.splitlines() if "偽造的一行" in x]
        check("原因裡的換行換成空白,不會多出一行 [達標]", len(lines) == 1 and lines[0].lstrip().startswith("[沒判]"), rt.stdout)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # U+2028 這類分行字元也一樣(代碼審 r4 資安席)
        res = _ms_result(driver={"status": "failed", "reason": "驅動回 1:x\u2028  [達標] pkg.Leak#cycle exits:偽造的一行"})
        _, r, d, rt = _ms_root(td, [_ms_thr("exits"), _ms_thr("java_growth")], res)
        check("原因含 U+2028 → 印出來切行後也不會多出一行 [達標]", not any(x.lstrip().startswith("[達標]") and "偽造" in x for x in rt.stdout.splitlines()), rt.stdout)
        check("有 check 條目時 --json 的 stability_unjudged 是 null(鍵固定)", "stability_unjudged" in d and d["stability_unjudged"] is None, str(d.get("stability_unjudged")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        res = _ms_result(cycle_trace=dict(_ms_result()["cycle_trace"], frozen_frames=-5))
        _, r, d, _ = _ms_root(td, [_ms_thr("frozen")], res, text=False)
        v = _ms_verdict(d)
        check("凍結幀 -5 → 跳過原因寫明負數(不是只寫 -1)", v and "負數" in v[0][2].get("reason", ""), str(v))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 類別名走 [沒達驗收門檻] 那條也一樣(代碼審 r3 測試資安席)
        evil = "a.B\n  [達標] pkg.Leak#cycle exits:偽造的一行"
        res = _ms_result(heap={"status": "ok", "before": {}, "after": {evil: 9}, "classes_seen": {"before": 3, "after": 3}, "class_names": "mapping"})
        _, r, _, rt = _ms_root(td, [_ms_thr("java_growth")], res)
        lines = [x for x in rt.stdout.splitlines() if "偽造的一行" in x]
        check("前置:類別名帶換行那筆判成沒過", "[沒達驗收門檻]" in rt.stdout, rt.stdout)
        check("類別名裡的換行換成空白,不會多出一行 [達標]", len(lines) == 1 and lines[0].lstrip().startswith("[沒達驗收門檻]"), rt.stdout)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 孤立代理字元:--json 印到 UTF-8 不能崩(代碼審 r3 邊界席)
        root = Path(td)
        (root / ".lumos").mkdir()
        (root / ".lumos" / "macrobench-thresholds.json").write_text(json.dumps({"version": 1, "thresholds": [_ms_thr("native_unreachable")]}), encoding="utf-8")
        body = json.dumps(_ms_result(unreachable={"status": "failed", "reason": "XSURX"})).replace("XSURX", "bad \\ud800 x")
        (root / "stability.json").write_text(body, encoding="utf-8")
        r = _mb_run(root, "--stability", str(root / "stability.json"), "--json")
        check("原因含孤立代理字元 → --json 照樣印出一份 JSON、回 0", r.returncode == 0 and r.stdout.strip().startswith("{") and "Traceback" not in r.stderr, r.stderr[-300:])
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 警語放在清單前面,類別一多也不被截掉(代碼審 r3 邊界席)
        after = {f"com.lib.C{i:02d}": 60 for i in range(40)}
        res = _ms_result(heap={"status": "ok", "before": {}, "after": after, "classes_seen": {"before": 40, "after": 40}, "class_names": "raw"})
        _, r, _, rt = _ms_root(td, [_ms_thr("java_growth")], res)
        check("40 個類別增長、沒給 mapping → 文字輸出仍看得到「類別名未還原」與類別數", "類別名未還原" in rt.stdout and "40 個類別增長" in rt.stdout, rt.stdout[-400:])
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 忘了寫門檻檔時不能看起來像全部通過(代碼審 r2 邊界席)
        root = Path(td)
        (root / ".lumos").mkdir()
        (root / "stability.json").write_text(json.dumps(_ms_result()), encoding="utf-8")
        r = _mb_run(root, "--stability", str(root / "stability.json"))
        check("給了 --stability 卻沒有 check 條目 → 印出沒有東西可判、回 0", r.returncode == 0 and "沒有東西可判" in r.stdout, r.stdout + r.stderr)
        r = _mb_run(root, "--stability", str(root / "stability.json"), "--json")
        dj = json.loads(r.stdout) if r.stdout.strip().startswith("{") else {}
        check("--json 也帶 stability_unjudged(skill 走 --json,三個清單全空會被記成 L0 通過;代碼審 r3 整合席)",
              "沒有東西可判" in str(dj.get("stability_unjudged")), r.stdout[:300])
        r = _mb_run(root, "--update-baseline", "--stability", str(root / "stability.json"))
        check("沒有 macrobench.json 時 --update-baseline 說沒有設定檔,不說成沒有 results_dirs", "沒有 .lumos/macrobench.json" in r.stdout, r.stdout)


def t_android_memstab_check_fields_strict():
    """代碼審 r1:check 條目寫了不認得的欄位(拼錯)→ 回 2,不准默默用預設值;stability 段的 category 不是字串 → 回 2 不噴例外;
    results_dirs 給空清單、只做穩定性也收;run-id 只有點、max_record_s 太大太小 → 擋下。"""
    import json, tempfile
    for bad, why in ((_ms_thr("native_unreachable", max_byte=999), "max_byte 拼錯"), (_ms_thr("frozen", max_block=5), "max_block 拼錯")):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            root = Path(td)
            (root / ".lumos").mkdir()
            (root / ".lumos" / "macrobench-thresholds.json").write_text(json.dumps({"version": 1, "thresholds": [bad]}), encoding="utf-8")
            r = _mb_run(root, "--check-config")
            check(f"{why} → 回 2 並說不認得的欄位", r.returncode == 2 and "擋下" in r.stderr and ("max_byte" in r.stderr or "max_block" in r.stderr), r.stdout + r.stderr)
    for bad, why in ((_ms_thr("exits", decided_by="<裁定的人>"), "check 條目"),
                     ({"scenario": "s", "metric": "m", "stat": "median", "max": 1, "contract": "c", "decided_by": " <裁定的人> ", "decided_at": "2026-10-24"}, "舊寫法條目")):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 照抄範例只改日期時不能當成有人裁過(代碼審 r3 文件資安席、整合席)
            root = Path(td)
            (root / ".lumos").mkdir()
            (root / ".lumos" / "macrobench-thresholds.json").write_text(json.dumps({"version": 1, "thresholds": [bad]}, ensure_ascii=False), encoding="utf-8")
            r = _mb_run(root, "--check-config")
            check(f"{why}的裁定人是佔位 → 回 2 並說 decided_by", r.returncode == 2 and "decided_by" in r.stderr, r.stdout + r.stderr)
    stab = {"package": "com.lab", "scenario": "s", "driver": "x {{CYCLES}}", "warmup": 2, "cycles": 5}
    for st, want, why in ((dict(stab, category=["app"]), 2, "category 是清單"), (dict(stab, category={}), 2, "category 是物件"),
                          (dict(stab, max_record_s=1e300), 2, "max_record_s 超大"), (dict(stab, max_record_s=0.0004), 2, "max_record_s 不到 1 秒"),
                          (dict(stab, cycles=10 ** 18), 2, "cycles 超大"), (dict(stab, warmup=10001), 2, "warmup 超過上限"),
                          (dict(stab, cycles=10000), 0, "cycles 剛好等於上限"),
                          (dict(stab, test_data={"value": True, "decided_by": "<裁定的人>", "decided_at": "2026-10-24"}), 2, "test_data 的裁定人是佔位"),
                          (dict(stab, test_data={"value": True, "decided_by": "某人", "decided_at": "2026-10-24"}), 0, "test_data 填了真的裁定人"),
                          (dict(stab, test_data={"value": True, "decided_by": "\uff1c裁定的人\uff1e", "decided_at": "2026-10-24"}), 2, "裁定人是全形角括號佔位"),
                          (dict(stab, test_data={"value": True, "decided_by": "<裁定\n的人>", "decided_at": "2026-10-24"}), 2, "裁定人佔位中間有換行"),
                          (dict(stab, test_data={"value": True, "decided_by": "Enzo <e@x.com>", "decided_at": "2026-10-24"}), 0, "裁定人名後面帶信箱")):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            root = Path(td)
            (root / ".lumos").mkdir()
            (root / ".lumos" / "macrobench.json").write_text(json.dumps({"stability": st}), encoding="utf-8")
            r = _mb_run(root, "--check-config")
            check(f"{why} → 回 {want} 擋下、不噴例外", r.returncode == want and "Traceback" not in r.stderr, r.stdout + r.stderr)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        root = Path(td)
        (root / ".lumos").mkdir()
        (root / ".lumos" / "macrobench.json").write_text(json.dumps({"results_dirs": [], "stability": stab}), encoding="utf-8")
        r = _mb_run(root, "--check-config")
        check("有 stability 段時 results_dirs 給空清單也收", r.returncode == 0, r.stdout + r.stderr)
    for rid in (".", ".."):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            import subprocess as sp
            root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
            r = sp.run(["sh", str(script), rid], cwd=root, capture_output=True, text=True, env=_ms_collect_env(fake), timeout=60)
            check(f"run-id {rid!r} → 回 2 擋下", r.returncode == 2 and "run-id" in r.stderr, r.stdout + r.stderr)
            check("run-id 只有點:擋在碰裝置之前(假 adb 一次都沒被叫)", not (fake / "adb.log").exists(), (fake / "adb.log").read_text()[-200:] if (fake / "adb.log").exists() else "")


def t_android_memstab_vitals_every_tier():
    """S4:官方表每一級都對一次「剛好等於 → 通過、多 1 KB → 沒過」,含每個分級的上界(上界不含)。
    40 個案例直接呼叫判定函式(每案經命令列要起兩次 lumos,40 案約 50 秒);命令列那條路徑由 t_android_memstab_peak_vitals_floor 走。"""
    m = _load_lumos_module()
    GB = 1024 * 1024
    app = ((3200, 2.00), (4800, 2.25), (6800, 2.25), (9216, 3.25), (14336, 4.25))
    game = ((3200, 2.25), (4800, 2.75), (6800, 3.50), (9216, 4.00), (14336, 5.00))
    for cat, table in (("app", app), ("game", game)):
        for i, (lo, gb) in enumerate(table):
            hi = table[i + 1][0] if i + 1 < len(table) else 18432
            for mem in (lo, hi - 1):
                for peak, want in ((gb * GB, "threshold_passed"), (gb * GB + 1, "threshold_failures")):
                    res = _ms_result(total_mem_mb=mem, category=cat, cycle_trace=dict(_ms_result()["cycle_trace"], peak_anon_swap_kb=peak))
                    v = _ms_verdict(m._macrobench_judge_stability([_ms_thr("peak_vitals")], res))
                    check(f"{cat} {mem} MB 峰值 {peak / GB:.6f} GB → {want}", [x[0] for x in v] == [want], str(v))


def t_android_memstab_collect_never_fakes_ok():
    """unreachable 讀不到總量那行時,失敗原因不帶裝置輸出(那是 App 原生記憶體的十六進位傾印,代碼審 r3 資安席)。
    代碼審 r1 甲、乙組在收集腳本這一側:讀不到就記 failed,不准記成 ok。
    驅動輸出任何 INSTRUMENTATION_ 開頭的行卻沒有 INSTRUMENTATION_CODE: -1 → failed;快照查詢回傳碼 0 但一列都沒有 → heap failed;
    日誌串流一開就斷 → strictmode failed;正常時 heap 帶 classes_seen 讓判定端分得出空快照。"""
    import tempfile
    td_decl = {"test_data": {"value": True, "decided_by": "Enzo", "decided_at": "2026-10-24"}}
    for out in ("INSTRUMENTATION_FAILED: com.lab.test/androidx.test.runner.AndroidJUnitRunner",
                "INSTRUMENTATION_RESULT: shortMsg=Process crashed.", "INSTRUMENTATION_ABORTED: System has crashed."):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            _, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, driver_out=out)
            check(f"驅動輸出 {out[:28]!r} 回 0 → driver failed", d.get("driver", {}).get("status") == "failed", str(d.get("driver")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "heap_empty").write_text("1", encoding="utf-8")
        _, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability=td_decl)
        check("快照查詢一列都沒有 → heap failed", d.get("heap", {}).get("status") == "failed", str(d.get("heap")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        heap = ({"com.sdk.Player": 1}, {"com.sdk.Player": 6, "com.sdk.Other": 2})   # 前後類別數不同,前後對調才抓得到(代碼審 r2 通才席)
        _, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability=td_decl, heap=heap)
        check("正常時 heap 帶兩份快照各自讀到的類別數", d.get("heap", {}).get("classes_seen") == {"before": 1, "after": 2}, str(d.get("heap")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "logcat_dies").write_text("1", encoding="utf-8")
        _, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability={"strictmode": True})
        check("日誌串流一開就斷 → strictmode failed", d.get("strictmode", {}).get("status") == "failed", str(d.get("strictmode")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        dump = ("0x7a23 42 65 61 72 65 72 20 65 |Bearer e|", "contents: |Authoriz| token")
        _r, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, unreachable=(dump[0], dump[1]))
        u = d.get("unreachable", {})
        check("前置:總量那行讀不到 → unreachable failed", u.get("status") == "failed", str(u))
        check("失敗原因不帶記憶體傾印的內容", "Bearer" not in str(u) and "Authoriz" not in str(u), str(u))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 離線、逾時這類原因要留(標準錯誤不是記憶體內容;代碼審 r4 正確性席)
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "unreach_offline").write_text("1", encoding="utf-8")
        _r, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        u = d.get("unreachable", {})
        check("裝置離線 → 失敗原因看得出是 device offline", u.get("status") == "failed" and "device offline" in u.get("reason", ""), str(u))


def t_android_memstab_collect_logcat_scope():
    """日誌只收量測開始之後、只收這個 pid、只在宣告了 strictmode 時才開;落地的只留違規那幾行(日誌常含帳號、權杖、網址)。"""
    import tempfile
    vio = "D/StrictMode( 100): StrictMode policy violation: android.os.strictmode.LeakedClosableViolation: x\n"
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "logcat_before_t0.txt").write_text(vio.replace("Closable", "Registration"), encoding="utf-8")
        _, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability={"strictmode": True},
                                 logcat=vio + "I/App( 100): token=SECRET123 user=alice@example.com\n")
        sm = d.get("strictmode", {})
        check("量測開始前的違規不算(有帶 -T)", sm.get("violations") == [{"type": "LeakedClosableViolation"}], str(sm))
        log = (fake / "adb.log").read_text()
        check("日誌串流帶 --pid 與 -T 量測開始時間", "logcat --pid=100 -T 10-24 03:00:00.000" in log, log[-300:])
        kept = (Path(td) / "proj" / ".lumos" / "artifacts" / "android" / "run1" / "logcat.txt")
        body = kept.read_text(encoding="utf-8") if kept.exists() else ""
        check("落地的日誌只留違規那幾行,不留其他內容", "SECRET123" not in body and "alice@example.com" not in body, body[:200])
        check("正常結束也刪掉原始日誌 logcat.raw(代碼審 r3 通才席)", not kept.with_name("logcat.raw").exists())
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 串流斷了也要刪原始日誌(代碼審 r2 五席)
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "logcat_dies").write_text("1", encoding="utf-8")
        _, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability={"strictmode": True})
        run = Path(td) / "proj" / ".lumos" / "artifacts" / "android" / "run1"
        check("前置:串流一開就斷 → strictmode failed", d.get("strictmode", {}).get("status") == "failed", str(d.get("strictmode")))
        check("串流斷了也不留原始日誌 logcat.raw", not (run / "logcat.raw").exists(), str(sorted(x.name for x in run.iterdir())))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        _, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, logcat="I/App( 100): token=SECRET123\n")
        log = (fake / "adb.log").read_text()
        check("沒宣告 strictmode → 不開日誌串流", " logcat " not in f" {log}" and "logcat --pid" not in log, log[-300:])
        check("沒宣告 strictmode → 不留日誌檔", not (Path(td) / "proj" / ".lumos" / "artifacts" / "android" / "run1" / "logcat.txt").exists())


def t_android_memstab_collect_edges():
    """exit-info 同一個 pid 先後兩筆用 timestamp 分開;ps 只認自己那個 pid;產物目錄本身是捷徑時不刪別處的舊快照;
    R8 mapping 會還原類別物件 java.lang.Class<混淆名> 尖括號裡的名字,沒給 mapping 時結果檔標明類別名未還原;
    專案是 git repo 而產物目錄沒被忽略時擋下(快照與結果檔不准進版控)。"""
    import os, subprocess as sp, tempfile, time
    pkg = "  package: com.lab\n    Historical Process Exit for uid=10229\n"
    old = _ms_exit_rec(0, 100, "2026-10-23 10:00:00.000", 10, "USER REQUESTED")
    new = _ms_exit_rec(0, 100, "2026-10-24 03:00:05.000", 4, "APP CRASH(EXCEPTION)")
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        _, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD + pkg + old, exit_after=_MS_EXIT_HEAD + pkg + new + old)
        check("同一個 pid、不同時間的新紀錄要算進去", [e.get("type") for e in d.get("exits", {}).get("new", [])] == ["crash"], str(d.get("exits")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        _, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("錄製還在跑(ps 列出 4321)→ cycle_trace ok", d.get("cycle_trace", {}).get("status") == "ok", str(d.get("cycle_trace")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 只剩別的行程(43210、perfetto4321):腳本自己比對 pid 那一道(代碼審 r2、r4 通才席)
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "record_dies_early").write_text("1", encoding="utf-8")
        _, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        log = (fake / "adb.log").read_text()
        check("前置:ps 有被問到", "ps -A" in log, log[-300:])
        ct = d.get("cycle_trace", {})   # 當成還在跑的話會變成「送了 TERM 停不下來」,一樣是 failed,要看原因才分得出來
        check("ps 只列 pid 開頭相同或名字含 pid 的別的行程(錄製早就停了)→ 判成錄製提早結束,不是停不下來", ct.get("status") == "failed" and "上限" in ct.get("reason", "")
              and "停不下來" not in ct.get("reason", ""), str(ct))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        elsewhere = Path(td) / "elsewhere"
        (elsewhere / "r").mkdir(parents=True)
        (elsewhere / "r" / "heap-x.pftrace").write_text("x", encoding="utf-8")
        os.utime(elsewhere / "r" / "heap-x.pftrace", (time.time() - 9 * 86400,) * 2)
        (Path(td) / "proj" / ".lumos" / "artifacts").mkdir(parents=True)
        (Path(td) / "proj" / ".lumos" / "artifacts" / "android").symlink_to(elsewhere, target_is_directory=True)
        _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("產物目錄本身是捷徑時,捷徑指去的舊快照不刪", (elsewhere / "r" / "heap-x.pftrace").exists())
    td_decl = {"test_data": {"value": True, "decided_by": "Enzo", "decided_at": "2026-10-24"}}
    thr = [{"scenario": "pkg.Leak#cycle", "check": "instances", "class": "com.sdk.Player", "max": 0,
            "contract": "c", "decided_by": "Enzo", "decided_at": "2026-10-24"}]
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        (Path(td) / "proj").mkdir()
        (Path(td) / "proj" / "mapping.txt").write_text("com.sdk.Player -> a.b:\ncom.sdk.Other -> a.c:\n", encoding="utf-8")
        heap = ({"java.lang.Class<a.b>": 1, "a.c": 1}, {"java.lang.Class<a.b>": 1, "a.c": 4})
        _, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, heap=heap, thresholds=thr,
                              stability=dict(td_decl, mapping="mapping.txt"))
        h = d.get("heap", {})
        check("類別物件尖括號裡的混淆名也還原", h.get("after", {}).get("java.lang.Class<com.sdk.Player>") == 1, str(h))
        check("一般類別名照樣還原", h.get("after", {}).get("com.sdk.Other") == 4, str(h))
        check("有 mapping → 標明類別名已還原", h.get("class_names") == "mapping", str(h))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        _, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability=td_decl)
        check("沒給 mapping → 結果檔標明類別名未還原", d.get("heap", {}).get("class_names") == "raw", str(d.get("heap")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        proj = Path(td) / "proj"
        proj.mkdir()
        sp.run(["git", "init", "-q", str(proj)], check=True, env=_ms_collect_env(proj))
        r, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("git repo 裡產物目錄沒被忽略 → 回 2 擋下、不寫結果檔", r.returncode == 2 and "gitignore" in r.stderr and not d, r.stdout + r.stderr)
        check("產物目錄沒被忽略:擋在碰裝置之前(假 adb 一次都沒被叫)", not (fake / "adb.log").exists(), (fake / "adb.log").read_text()[-200:] if (fake / "adb.log").exists() else "")
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        proj = Path(td) / "proj"
        proj.mkdir()
        sp.run(["git", "init", "-q", str(proj)], check=True, env=_ms_collect_env(proj))
        (proj / ".gitignore").write_text(".lumos/artifacts/\n", encoding="utf-8")
        r, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("git repo 裡產物目錄有被忽略 → 照常寫出結果檔", r.returncode == 0 and d, r.stdout + r.stderr)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 使用者的全域 ignore 放在 ~/.config/git/ignore 時,隔離得掉(代碼審 r4 通才席)
        proj, home = Path(td) / "proj", Path(td) / "home"
        proj.mkdir()
        (home / ".config" / "git").mkdir(parents=True)
        (home / ".config" / "git" / "ignore").write_text(".lumos/\n", encoding="utf-8")
        root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        env = dict(_ms_collect_env(fake), HOME=str(home))
        sp.run(["git", "init", "-q", str(proj)], check=True, env=env)
        pre = sp.run(["git", "-C", str(proj), "check-ignore", "-q", ".lumos/x"], env=dict(os.environ, HOME=str(home), XDG_CONFIG_HOME=""), capture_output=True)
        check("前置:不隔離的話,這個 HOME 的全域 ignore 會蓋掉 .lumos/", pre.returncode == 0, str(pre.returncode))
        r = sp.run(["sh", str(script), "run1"], cwd=root, capture_output=True, text=True, timeout=120, env=env)
        check("全域 ignore 有 .lumos/ 時照樣判成沒被忽略、回 2(測試不受使用者設定影響)", r.returncode == 2 and "沒被 git 忽略" in r.stderr, r.stdout + r.stderr)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # git 自己壞了(safe.directory 等)不能當成不是 repo(代碼審 r4 資安席)
        root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        gbin = Path(td) / "gbin"
        gbin.mkdir()
        (gbin / "git").write_text("#!/bin/sh\necho 'fatal: detected dubious ownership in repository' >&2\nexit 128\n", encoding="utf-8")
        (gbin / "git").chmod(0o755)
        r = sp.run(["sh", str(script), "run1"], cwd=root, capture_output=True, text=True, timeout=120,
                   env=dict(_ms_collect_env(fake), PATH=f"{gbin}:{os.environ['PATH']}"))
        check("git 回 128 而且不是「不是 repo」→ 回 2 擋下、不碰裝置", r.returncode == 2 and "git 判不了" in r.stderr and not (fake / "adb.log").exists(), r.stdout + r.stderr)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 只忽略 *.json:結果檔過了、快照與日誌沒被忽略(代碼審 r2 資安席)
        proj = Path(td) / "proj"
        proj.mkdir()
        sp.run(["git", "init", "-q", str(proj)], check=True, env=_ms_collect_env(proj))
        (proj / ".gitignore").write_text("*.json\n", encoding="utf-8")
        r, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check(".gitignore 只寫 *.json → 回 2 擋下並列出沒被忽略的檔", r.returncode == 2 and "heap-before.pftrace" in r.stderr and "logcat.raw" in r.stderr and not d,
              r.stdout + r.stderr)
        check("只忽略 *.json:擋在碰裝置之前(假 adb 一次都沒被叫)", not (fake / "adb.log").exists(), (fake / "adb.log").read_text()[-200:] if (fake / "adb.log").exists() else "")
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        proj = Path(td) / "proj"
        proj.mkdir()
        for mod in ("json", "re"):
            (proj / f"{mod}.py").write_text("raise SystemExit('專案目錄的同名模組被載入了')\n", encoding="utf-8")
        r, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("專案根目錄有同名的 json.py、re.py → 不載入它們,照常寫出結果檔", r.returncode == 0 and d and "同名模組" not in r.stderr, r.stdout + r.stderr)
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 殘留的 PYTHONPATH 也不載入(代碼審 r2 資安席)
        root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        bad = Path(td) / "pp"
        bad.mkdir()
        (bad / "shutil.py").write_text("raise SystemExit('PYTHONPATH 裡的同名模組被載入了')\n", encoding="utf-8")
        r = sp.run(["sh", str(script), "run1"], cwd=root, capture_output=True, text=True, timeout=120, env=dict(_ms_collect_env(fake), PYTHONPATH=str(bad)))
        check("PYTHONPATH 指到有 shutil.py 的目錄 → 不載入它,照常跑完", r.returncode == 0 and "同名模組" not in r.stderr, r.stdout + r.stderr)
        n_before = (fake / "adb.log").read_text().count("\n")
        r = sp.run(["sh", str(script), "run1"], cwd=root, capture_output=True, text=True, timeout=120, env=_ms_collect_env(fake))
        check("同一個 run-id 已經有結果檔 → 回 2 擋下(中斷時舊結果檔會被當成這次的)", r.returncode == 2 and "run-id" in r.stderr, r.stdout + r.stderr)
        check("同一個 run-id:擋在碰裝置之前(假 adb 沒有多被叫)", (fake / "adb.log").read_text().count("\n") == n_before)
    big5 = sp.run(["python3", "-I", "-c", "import sys; print(sys.stdout.encoding)"], capture_output=True, text=True,
                  env={"PATH": os.environ["PATH"], "LC_ALL": "zh_TW.BIG5"}).stdout.strip().lower()
    if big5 == "big5":   # 機器有 Big5 語系才驗得出來(Linux CI 多半沒有,這段不跑)
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
            root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
            r = sp.run(["sh", str(script), "壞 id"], cwd=root, capture_output=True, timeout=60, env=dict(_ms_collect_env(fake), LC_ALL="zh_TW.BIG5"))
            err = r.stderr.decode("utf-8", errors="replace")
            check("Big5 語系下擋下訊息照樣是 UTF-8(-I 會關掉 UTF-8 模式)", r.returncode == 2 and "擋下" in err and "run-id" in err, err)
    else:
        print("  (略過 Big5 語系那條:這台機器沒有 zh_TW.BIG5 語系,-P 與 UTF-8 輸出這條在這裡驗不到)")


def t_android_memstab_collect_cleanup():
    """收集腳本收到 SIGTERM(外層逾時、kill 的預設訊號)時,停掉裝置上的錄製、刪裝置暫存、收掉日誌串流與驅動整組子程序;
    錄製收到 TERM 不停時,等完就補 KILL 並記成 failed;驅動逾時時也整組殺掉。"""
    import json, signal, subprocess as sp, tempfile, time
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, pids=("100", "100", "100"),
                                         unreachable=("0 bytes in 0 unreachable allocations",) * 2, driver_out="INSTRUMENTATION_CODE: -1",
                                         driver_rc=0, stability={"strictmode": True}, heap=({}, {}), logcat="", thresholds=None)
        (fake / "driver_sleeps").write_text("1", encoding="utf-8")
        p = sp.Popen(["sh", str(script), "run2"], cwd=root, stdout=sp.PIPE, stderr=sp.PIPE, text=True, env=_ms_collect_env(fake))
        for _ in range(300):   # 等到量測輪的驅動開始(驅動被呼叫第二次)
            if (fake / "driver.log").exists() and (fake / "driver.log").read_text().count("\n") >= 2:
                break
            time.sleep(0.1)
        time.sleep(0.5)
        p.send_signal(signal.SIGTERM)
        p.wait(timeout=60)
        log = (fake / "adb.log").read_text()
        check("SIGTERM 時停掉裝置上的錄製", "kill -TERM 4321" in log, log[-500:])
        check("SIGTERM 時刪掉裝置上的錄製設定與追蹤檔", "rm -f /data/misc/perfetto-configs/lumos-stability-run2.pbtxt" in log, log[-500:])
        time.sleep(0.5)
        left_lc = _ms_orphans(fake, "adb logcat")   # 找到就收:紅的時候不留孤兒給別支測試(代碼審 r3、r4 通才席)
        check("SIGTERM 時日誌串流沒有變成孤兒", not left_lc, str(left_lc))
        left = _ms_orphans(fake, "driver|sleeper")
        check("SIGTERM 時驅動(連同它底下的 sleep)沒有變成孤兒", not left, str(left))
        check("SIGTERM 時原始日誌 logcat.raw 也刪掉", not (root / ".lumos" / "artifacts" / "android" / "run2" / "logcat.raw").exists())
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        fake = Path(td) / "fake"
        fake.mkdir()
        (fake / "ignores_term").write_text("1", encoding="utf-8")
        _r, d, fake = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        log = (fake / "adb.log").read_text()
        check("錄製收到 TERM 不停 → 等完補 KILL", "kill -KILL 4321" in log, log[-400:])
        check("錄製要靠 KILL 才停 → cycle_trace failed 並說停不下來", d.get("cycle_trace", {}).get("status") == "failed"
              and "停不下來" in d.get("cycle_trace", {}).get("reason", ""), str(d.get("cycle_trace")))
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        (fake / "driver_sleeps").write_text("1", encoding="utf-8")
        t0 = time.monotonic()
        r = sp.run(["sh", str(script), "run3"], cwd=root, capture_output=True, text=True, timeout=120,
                   env=dict(_ms_collect_env(fake), LUMOS_STABILITY_LONG_TIMEOUT="2"))
        took = time.monotonic() - t0
        out = root / ".lumos" / "artifacts" / "android" / "run3" / "stability.json"
        drv = json.loads(out.read_text(encoding="utf-8")).get("driver", {}) if out.is_file() else {}
        check("驅動逾時 → driver failed 並說逾時", drv.get("status") == "failed" and "逾時" in str(drv), r.stdout + r.stderr + str(drv))
        time.sleep(0.5)
        left = _ms_orphans(fake, "driver|sleeper")
        check("驅動逾時時整組殺掉,驅動底下的程序沒有變成孤兒", not left, str(left))
        check("驅動逾時後不等底下的程序自己跑完(它們握著輸出管線,只殺最外層會卡到它們結束)", took < 20, f"{took:.1f} 秒")


def t_android_memstab_collect_result_fields():
    """代碼審 r3 通才席:收集腳本寫出的數字欄位對得上假工具給的值(期望值從假工具的輸出另外算,不照抄實作)。
    假 /proc/meminfo 給 7386728 kB → 7213 MB;假 getprop 給 SM-X710、36;假 dumpsys meminfo 的 Native Heap 第一欄 4816;
    假 trace_processor 給 cycle 那列 200000,0,40,600(峰值、凍結幀、最長阻塞、幀數)。"""
    import tempfile
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        r, d, _ = _ms_collect(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        check("前置:收集跑完、寫出結果檔", r.returncode == 0 and d, r.stderr)
        check("total_mem_mb 是 MemTotal 換成 MB(7386728 // 1024)", d.get("total_mem_mb") == 7213, str(d.get("total_mem_mb")))
        check("device_model 與 android_sdk 照 getprop", d.get("device_model") == "SM-X710" and d.get("android_sdk") == 36, str(d))
        check("native_heap_kb 前後都是 Native Heap 第一欄", d.get("native_heap_kb") == {"status": "ok", "before": 4816, "after": 4816}, str(d.get("native_heap_kb")))
        ct = d.get("cycle_trace", {})
        check("cycle_trace 四個數字各在自己的欄位(峰值、凍結幀、最長阻塞、幀數沒有互換)",
              (ct.get("peak_anon_swap_kb"), ct.get("frozen_frames"), ct.get("max_main_block_ms"), ct.get("frames")) == (200000, 0, 40, 600), str(ct))
        check("warmup、cycles、category 照設定寫進結果檔", (d.get("warmup"), d.get("cycles"), d.get("category")) == (2, 5, "app"), str(d))


def _ms_wait_for(cond, tries=300, step=0.1):
    """等條件成立(最多 tries × step 秒);回最後一次的結果。"""
    import time
    for _ in range(tries):
        if cond():
            return True
        time.sleep(step)
    return cond()


def _ms_log(fake, name="adb.log"):
    return (fake / name).read_text() if (fake / name).exists() else ""


def _ms_orphans(fake, pattern):
    """找出還活著、命令列帶這個假工具目錄的程序,收掉並回它們的 pid(紅的時候不留孤兒給別支測試)。"""
    import subprocess as sp
    left = sp.run(["pgrep", "-f", f"{fake}/({pattern})"], capture_output=True, text=True).stdout.split()
    for pid in left:
        sp.run(["kill", pid], capture_output=True)
    return left


def t_android_memstab_collect_heap_timeout():
    """代碼審 r2:java_heap_dump 這類不是驅動的工具逾時也整組殺、不等它底下握著管線的程序。"""
    import json, subprocess as sp, tempfile, time
    td_decl = {"test_data": {"value": True, "decided_by": "Enzo", "decided_at": "2026-10-24"}}
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:
        root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability=td_decl)
        (fake / "jhd_hangs").write_text("1", encoding="utf-8")
        t0 = time.monotonic()
        r = sp.run(["sh", str(script), "run4"], cwd=root, capture_output=True, text=True, timeout=180,
                   env=dict(_ms_collect_env(fake), LUMOS_STABILITY_LONG_TIMEOUT="2"))
        took = time.monotonic() - t0
        out = root / ".lumos" / "artifacts" / "android" / "run4" / "stability.json"
        heap = json.loads(out.read_text(encoding="utf-8")).get("heap", {}) if out.is_file() else {}
        check("前置:快照工具真的逾時了(heap failed 並說逾時)", heap.get("status") == "failed" and "逾時" in str(heap), r.stderr + str(heap))
        check("快照工具逾時時整組殺,不等它底下握著管線的程序(兩次快照各卡 30 秒就會超過)", took < 20, f"{took:.1f} 秒")
        left = _ms_orphans(fake, "sleeper")
        check("快照工具逾時時底下的程序沒有變成孤兒", not left, str(left))


def t_android_memstab_collect_signals():
    """代碼審 r3:SIGHUP(關掉終端機分頁)、SIGQUIT(Ctrl-\\)跟 SIGTERM 一樣走收尾;收尾裡再來一次 SIGTERM 不打斷收尾。"""
    import signal, subprocess as sp, tempfile, time
    for sig, label in ((signal.SIGHUP, "SIGHUP(關掉終端機分頁)"), (signal.SIGQUIT, "SIGQUIT(Ctrl-\\)"), (signal.SIGINT, "SIGINT(Ctrl-C)")):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 只接 SIGTERM 時這兩種直接結束、什麼都不收(r3 資源席、資安席)
            root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability={"strictmode": True})
            (fake / "driver_sleeps").write_text("1", encoding="utf-8")
            p = sp.Popen(["sh", str(script), "run6"], cwd=root, stdout=sp.PIPE, stderr=sp.PIPE, text=True, env=_ms_collect_env(fake))
            check(f"前置:{label} 之前量測輪的驅動已經開始", _ms_wait_for(lambda f=fake: _ms_log(f, "driver.log").count("\n") >= 2))
            time.sleep(0.5)
            check(f"前置:{label} 送出時收集還在跑", p.poll() is None)
            p.send_signal(sig)
            p.wait(timeout=60)
            time.sleep(0.5)
            log = _ms_log(fake)
            left = _ms_orphans(fake, "driver|sleeper|adb logcat")
            check(f"{label}:回 2 擋下(走收尾,不是直接被殺)", p.returncode == 2, str(p.returncode))
            check(f"{label}:驅動與日誌串流沒有變成孤兒", not left, str(left))
            check(f"{label}:裝置上的錄製有送 kill -TERM、原始日誌刪掉", "kill -TERM 4321" in log
                  and not (root / ".lumos" / "artifacts" / "android" / "run6" / "logcat.raw").exists(), log[-300:])
    for sig, label in ((signal.SIGTERM, "SIGTERM"), (signal.SIGINT, "Ctrl-C")):
        with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 收尾裡再來一次中斷:不准打斷收尾(r3 正確性席、資源席;r4 通才席補 Ctrl-C)
            root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD, stability={"strictmode": True})
            for flag in ("driver_sleeps", "term_slow"):
                (fake / flag).write_text("1", encoding="utf-8")
            p = sp.Popen(["sh", str(script), "run7"], cwd=root, stdout=sp.PIPE, stderr=sp.PIPE, text=True, env=_ms_collect_env(fake))
            check(f"前置({label}):量測輪的驅動已經開始", _ms_wait_for(lambda f=fake: _ms_log(f, "driver.log").count("\n") >= 2))
            time.sleep(0.5)
            p.send_signal(sig)
            check(f"前置({label}):收尾走到卡住的 kill -TERM", _ms_wait_for(lambda f=fake: "kill -TERM" in _ms_log(f), tries=100, step=0.05))
            p.send_signal(sig)
            err = p.communicate(timeout=60)[1]
            log = _ms_log(fake)
            _ms_orphans(fake, "driver|sleeper|adb logcat")
            check(f"收尾中再按一次 {label}:照樣回 2,不噴例外", p.returncode == 2 and "Traceback" not in err, err[-300:])
            check(f"收尾中再按一次 {label}:裝置暫存照刪、原始日誌照刪", "rm -f /data/misc/perfetto-configs/lumos-stability-run7.pbtxt" in log
                  and not (root / ".lumos" / "artifacts" / "android" / "run7" / "logcat.raw").exists(), log[-300:])
            check(f"收尾中再按一次 {label}:收尾開始時印出「最久約 4 分鐘」的提示", "收尾中" in err and "4 分鐘" in err, err[-300:])
    with tempfile.TemporaryDirectory(prefix="gctl-ms-") as td:   # 裝置沒回應時,訊息不能說錄製已停、暫存已刪(代碼審 r4 資安席)
        root, fake, script = _ms_prepare(td, exit_before=_MS_EXIT_HEAD, exit_after=_MS_EXIT_HEAD)
        for flag in ("driver_sleeps", "device_gone"):
            (fake / flag).write_text("1", encoding="utf-8")
        p = sp.Popen(["sh", str(script), "run9"], cwd=root, stdout=sp.PIPE, stderr=sp.PIPE, text=True, env=_ms_collect_env(fake))
        check("前置:量測輪的驅動已經開始", _ms_wait_for(lambda: _ms_log(fake, "driver.log").count("\n") >= 2))
        time.sleep(0.5)
        p.send_signal(signal.SIGTERM)
        err = p.communicate(timeout=60)[1]
        _ms_orphans(fake, "driver|sleeper|adb logcat")
        check("裝置刪不到暫存 → 回 2,訊息說錄製與暫存可能還在,不說已刪", p.returncode == 2 and "可能還在" in err and "暫存已刪" not in err, err[-300:])


def t_android_memstab_collect_start_window():
    """代碼審 r3:錄製已經在裝置上開起來、pid 還沒回來就被中斷時,照追蹤檔名停掉錄製並刪裝置暫存。"""
