    result_backlink = _impact_via("S/F.md", "S/H.md", True, env)
    check("impact_via: backlink H→F 讀 dest(H.fields) 得 via=verified_by(不是讀 F)",
          result_backlink == "verified_by", f"got {result_backlink!r}")


