def t_loop_next_disposal_cmd_actually_runs():
    """[T5](plan:design-loop重設計_實作計畫 T5)loop next 的 disposal_cmd 模板★真跑 oracle★
    (沿 t_loop_next_legacy 教訓:工具吐的指令必須跑得動,字串斷言只證長得對)。
    record_cmd 原樣保留(code-loop 不受影響)。"""
    import json as _j
    v = mkvault()
    spec = v / "Projects" / "t5spec.md"
    spec.write_text("t5 spec\n規則甲:這是一段足夠長的內容當引句。\n", encoding="utf-8")
    h = _sha256_of(spec)
    rpt = v / "Projects" / "t5rpt.md"
    rpt.write_text("severity: minor\nseverity: minor\n引句：「規則甲:這是一段足夠長的內容當引句。」\n", encoding="utf-8")
    lid = f"t5-{_M1U}"
    d = _j.loads(run(v, "loop", "next", lid, "--tier", "standard", "--orchestrator", "claude", "--json").stdout)
    check("★前置★ 現場成立:panel tier 吐 disposal_cmd+disposal_gate",
          "disposal_cmd" in d and "disposal_gate" in d and "record_cmd" in d, str(d)[:200])
    filled = (d["disposal_cmd"].replace("caught|missed", "caught").replace("<席>", "s1")
              .replace("<s>", "minor").replace("<id串>", "F1", 1)          # findings-set
              .replace("--folded-set <id串>", "--folded-set F1")
              .replace(" --accepted-set <id串>", "")     # accepted 缺省=空集合(argv 手切,'' 會變字面引號)
              .replace(" --accept-reason <id=理由>", "")
              .replace("<席報告.md>", str(rpt)).replace("<這一席審的那份凍結材料(拆包審時填該席那一包)>", str(spec)).replace("<這一席那份的行數(拆包審時填該席那一包)>", "10")
              .replace("<計劃節點.md>", str(spec)).replace("<sha256>", h))
    argv = filled.split()
    check("★前置★ 填完無殘留佔位符", "<" not in filled and argv[0] == "lumos", filled)
    # cb3 s3-f1:record_cmd 同樣真跑——寫側新規曾讓它照跑必 rc2,模板已補 --report,這釘防回歸
    rec_filled = (d["record_cmd"].replace("caught|missed", "caught").replace("<席>", "s9")
                  .replace("<s>", "minor").replace("<M>", "0")
                  .replace("<席報告.md>", _sevrep(v.parent, "minor"))
                  .replace("<計劃節點.md>", str(spec)).replace("<sha256>", h)
                  .replace("<這一席審的那份凍結材料(拆包審時填該席那一包)>", str(spec)).replace("<這一席那份的行數(拆包審時填該席那一包)>", "10"))
    check("★前置★ record_cmd 填完無殘留佔位符", "<" not in rec_filled, rec_filled)
    rrec = run(v, *rec_filled.split()[1:])
    check("★record_cmd 模板真的跑得動(rc0)★", rrec.returncode == 0, f"rc={rrec.returncode} {rrec.stderr[:200]}")
    rr = run(v, *argv[1:])
    check("★disposal_cmd 模板真的跑得動(rc0)★", rr.returncode == 0,
          f"rc={rr.returncode} {rr.stderr[:200]}")
    g = (d["disposal_gate"].replace("<計劃節點.md>", str(spec)).replace("<root>", str(v.parent)))
    rg = run(v, *g.split()[1:])
    check("★disposal_gate 模板跑得動且對剛記的帳給出判定(rc0/1 非 rc2)★", rg.returncode in (0, 1),
          f"rc={rg.returncode} {rg.stderr[:200]}")


def t_loop_next_spec_uses_disposal_gate_for_new_loops():
    """loop next 帶 --spec 時代問的閘:2026-08-25 之後開的新編號問處置閘,不走已退役的 panel 閘
    (Issues/loop-next帶spec誤走退役panel閘:原本照 lumos-code-loop 手冊第 1 步帶 --spec 必被「panel 閘僅供舊迴圈回放」擋 rc2);
    舊編號(退役日之前定錨)照舊走 panel 閘回放。"""
    import json as _j
    import os as _os
    v = mkvault()
    spec = v / "Projects" / "nxspec.md"
    spec.write_text("nx spec\n規則甲:這是一段足夠長的內容當引句。\n", encoding="utf-8")
    h = _sha256_of(spec)
    rpt = v / "Projects" / "nxrpt.md"
    rpt.write_text("severity: minor\n## F1 甲\nseverity: minor\n引句：「規則甲:這是一段足夠長的內容當引句。」\n", encoding="utf-8")
    lid = f"nx-{_M1U}"
    run(v, "canary", "record", "none", "--loop", lid, "--round", "r1", "--auditor", "正確性-s", "--severity", "minor",
        "--findings", "1", "--findings-set", "F1", "--folded-set", "F1", "--refuted-set", "none",
        "--report", str(rpt), "--snapshot", str(spec), "--spec", str(spec), "--reviewed", h,
        "--tier", "standard", "--orchestrator", "claude", "--scope-lines", "10", expect_rc=0)
    # 測試總檔開頭把退役日凍在 9999(所有編號都算舊迴圈),這個 bug 因此一直沒被全套抓到;新迴圈要自己把退役日拉到過去
    env_new = dict(_os.environ, LUMOS_PANEL_RETIRE_CUTOFF="2000-01-01")
    r = subprocess.run([sys.executable, GRAPHCTL, "--vault", str(v), "loop", "next", lid, "--spec", str(spec),
                        "--repo", str(v.parent), "--json"], capture_output=True, text=True, env=env_new)
    check("★新編號帶 --spec 不被退役的 panel 閘擋(rc0、沒有 panel 閘字樣)★",
          r.returncode == 0 and "panel 閘" not in r.stderr, f"rc={r.returncode} {r.stderr[:300]} OUT={r.stdout[:300]}")
    d = _j.loads(r.stdout) if r.returncode == 0 else {}
    check("★處置閘判過 → phase=converged★", d.get("phase") == "converged", str(d)[:300])
    rpt.write_text("severity: major\n## F1 甲\nseverity: major\n引句：「規則甲:這是一段足夠長的內容當引句。」\n", encoding="utf-8")
    for _ in range(2):   # 報告改得比帳面高 → 處置閘會想記一筆席位異常;loop next 是唯讀指針,不准落檔
        subprocess.run([sys.executable, GRAPHCTL, "--vault", str(v), "loop", "next", lid, "--spec", str(spec),
                        "--repo", str(v.parent), "--json"], capture_output=True, text=True, env=env_new)
    logs = list(Path(v.parent).rglob("roster-alerts.log"))
    check("★loop next 代問處置閘是唯讀:跑兩次也不寫席位異常紀錄★", not logs, str(logs))
    r2 = run(v, "loop", "next", lid, "--spec", str(spec), "--repo", str(v.parent), "--json")   # 總檔預設:舊迴圈
    d2 = _j.loads(r2.stdout) if r2.stdout.strip().startswith("{") else {}
    check("舊編號(退役日之前)照舊走 panel 閘回放:不拿處置閘當收斂依據", r2.returncode != 2
          and d2.get("phase") != "converged", f"rc={r2.returncode} {str(d2)[:200]} {r2.stderr[:200]}")


def t_disposal_loop_requires_provenance():
    """[T6 收緊](plan:design-loop重設計_實作計畫 T6)

    定錨規則(同 M2 cluster 前例):loop ★首筆帶 findings_set 的記錄★定錨為 disposal loop;
    定錨後該 loop 後續 record ★必帶 --report+--snapshot★,缺=rc2(寫側擋)。
    ★舊 loop/未定錨 loop 完全不受影響★(相容鐵則)。
    翻紅釘:把強制檢查還原掉 → 「定錨後缺 report 必 rc2」翻紅。"""
    v = mkvault()
    d = v / "Projects"
    rpt = d / "t6r.md"; rpt.write_text("severity: clean\n引句：「這是一段足夠長的快照內容」\n", encoding="utf-8")
    snap = d / "t6s.md"; snap.write_text("這是一段足夠長的快照內容 後面還有\n", encoding="utf-8")
    lid = f"t6-{_M1U}"
    # 首筆帶 findings_set+留痕 → 定錨
    run(v, "canary", "record", "caught", "--round", "r1", "--loop", lid, "--auditor", "s1", "--severity", "minor",
        "--findings-set", "a", "--refuted-set", "none", "--folded-set", "a", "--report", str(rpt), "--snapshot", str(snap),
        expect_rc=0)
    # 定錨後缺留痕 → rc2
    rr = run(v, "canary", "record", "caught", "--loop", lid, "--round", "r1", "--auditor", "s2", "--severity", "minor")
    check("★定錨後缺 --report/--snapshot 必 rc2(留痕轉強制)★", rr.returncode == 2, f"rc={rr.returncode} {rr.stderr[:150]}")
    # 帶齊就過
    run(v, "canary", "record", "missed", "--loop", lid, "--round", "r1", "--auditor", "s3", "--severity", "major",
        "--report", str(rpt), "--snapshot", str(snap), expect_rc=0)
    # ★相容:未定錨 loop 照舊自由★
    run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", f"t6free-{_M1U}", "--auditor", "s1",
        "--severity", "minor", expect_rc=0)
    check("★前置★ 現場成立:定錨 loop 與自由 loop 同庫共存", True, "")


def t_code_loop_record_requires_provenance_from_first_row():
    """代碼審的每一筆記帳,從第一筆起就要帶 --report 與 --snapshot,缺了當場擋。

    出身:2026-09-22 rtb-production-agent-demo 回報。既有規則只在「這條迴圈已經有一筆帶發現清單」
    之後才強制留痕;而代碼審的慣例順序是先記非載體席、再記載體席,所以第一席記帳時還沒定錨,
    漏帶 --snapshot 會安靜通過,要到問處置閘才以「資安席留痕對不上」這種看不出原因的訊息爆出來,
    而帳本不能撤銷,只能整輪換編號重記。代碼審的手冊本來就要求每一席都帶這兩個,
    所以改成寫側當場擋,訊息直接講缺哪一個。
    設計審(散文)不動:那邊仍照原本的定錨規則,相容鐵則。
    翻紅釘:把代碼審的前置檢查拿掉 → ②紅。
    """
    v = mkvault()
    d = v / "Projects"
    rpt = d / "cr.md"; rpt.write_text("severity: clean\n引句：「這是一段足夠長的快照內容」\n", encoding="utf-8")
    snap = d / "cs.md"; snap.write_text("這是一段足夠長的快照內容 後面還有\n", encoding="utf-8")
    lid = f"code-留痕-{_M1U}"
    r = run(v, "canary", "record", "none", "--loop", lid, "--round", "r1", "--auditor", "架構對齊-sonnet",
            "--severity", "clean", "--findings", "0", "--report", str(rpt))
    check("① 現場成立:這是這條迴圈的第一筆,還沒有任何一筆帶發現清單(沒定錨)", True, "")
    check("② 代碼審第一筆就缺 --snapshot → 當場 rc2", r.returncode == 2, f"rc={r.returncode} {r.stderr[:200]}")
    check("② 訊息直接講缺的是凍結快照", "--snapshot" in r.stderr, r.stderr[:300])
    ok = run(v, "canary", "record", "none", "--loop", lid, "--round", "r1", "--auditor", "架構對齊-sonnet",
             "--severity", "clean", "--findings", "0", "--report", str(rpt), "--snapshot", str(snap))
    check("③ 兩個都帶齊就記得進去", ok.returncode == 0, f"rc={ok.returncode} {ok.stderr[:200]}")
    free = run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", f"design-自由-{_M1U}",
               "--auditor", "s1", "--severity", "minor")
    check("④ 相容:設計審(非代碼審)還沒定錨時照舊不強制", free.returncode == 0, f"rc={free.returncode} {free.stderr[:200]}")
    # ⑤ code 開頭沒連字號的(帳裡真的有 codestage):看不出是哪種審查,照 repo 既有慣例從嚴——
    #   代碼審 r2 架構席 blocker:從寬的話取個 codeX 的編號就能漏帶快照。但訊息不准硬說它是代碼審
    #   (r1 兩席抓到第一版講成「代碼審」,誤導人去找一份不存在的凍結 patch)。
    odd = run(v, "canary", "record", "none", "--loop", f"codeXreview-{_M1U}", "--round", "r1", "--auditor", "s1",
              "--severity", "clean", "--findings", "0", "--report", str(rpt))
    check("⑤ 看不出是哪種審查的也要擋(不能靠取編號繞過)", odd.returncode == 2, f"rc={odd.returncode} {odd.stderr[:200]}")
    check("⑤ 但訊息老實講「看不出是哪一種」,不硬說它是代碼審",
          "看不出是哪一種審查" in odd.stderr and "擋下:代碼審(" not in odd.stderr, odd.stderr[:300])
    # ⑥ 同輪通才席:只記結局的帳結構上就不帶報告與快照
    oc = run(v, "canary", "record", "none", "--loop", f"code-結局-{_M1U}", "--auditor", "orchestrator",
             "--outcome", "skipped")
    check("⑥ 只記結局的帳(--outcome)不被這道擋", oc.returncode == 0, f"rc={oc.returncode} {oc.stderr[:200]}")


def t_codeloop_record_invalid_after_squash_says_why():
    """壓過提交之後留痕失效時,訊息要講出「多半是壓過提交」和怎麼重來,不能只丟兩個 sha。

    出身:2026-09-22 rtb-production-agent-demo 回報。表態與審查留痕都綁在某個提交上,
    只認「同一個、或是它的祖先且中間只動簿記檔」。把幾個本機提交壓成一個之後,內容一模一樣,
    原本記的那個提交卻不再是祖先——推送被擋,而訊息只說「sha A 不是 sha B 的祖先」,
    看不出是自己剛做的壓提交造成的,也不知道要重跑哪兩個指令。
    翻紅釘:把訊息改回只有兩個 sha → ②紅。
    """
    import subprocess as _sp, tempfile
    m = _import_lumos()
    with tempfile.TemporaryDirectory() as d:
        g = lambda *a: _sp.run(["git", *a], cwd=d, capture_output=True, text=True)
        g("init", "-q", "-b", "main"); g("config", "user.email", "t@t"); g("config", "user.name", "t")
        Path(d, "a.py").write_text("x = 1\n", encoding="utf-8"); g("add", "-A"); g("commit", "-qm", "base")
        Path(d, "a.py").write_text("x = 2\n", encoding="utf-8"); g("add", "-A"); g("commit", "-qm", "wip1")
        recorded = g("rev-parse", "HEAD").stdout.strip()      # 表態/留痕記在這個提交上
        Path(d, "a.py").write_text("x = 3\n", encoding="utf-8"); g("add", "-A"); g("commit", "-qm", "wip2")
        g("reset", "--soft", "HEAD~2"); g("commit", "-qm", "squashed")   # 壓成一個
        head = g("rev-parse", "HEAD").stdout.strip()
        ok, why = m._codeloop_record_valid(Path(d), recorded, head)
        check("① 現場成立:壓過之後原本那個提交已經不是祖先", ok is False, why)
        check("② 訊息點出多半是壓過提交或改寫過歷史", "壓" in why and ("rebase" in why or "改寫" in why), why)
        check("② 訊息給得出重來的指令(表態與審查留痕各一條)",
              "--dispositions-template --carry" in why and "code-loop pass" in why, why)
        # ③ 代碼審 r1 通才席:提交根本找不到(寫錯、淺 clone、被清掉)時,不准講成「多半是壓過提交」
        ok2, why2 = m._codeloop_record_valid(Path(d), "0" * 39 + "1", head)
        check("③ 找不到的提交:講「找不到」,不講成壓過提交", ok2 is False and "找不到" in why2 and "壓過提交" not in why2, why2)


def t_codeloop_check_after_squash_says_why():
    """壓過提交之後,推送閘判審查留痕的那條路也要講出原因與怎麼重來。

    出身:代碼審 r1 架構席——第一版只改了判有效性那支函式的訊息,而推送閘判審查留痕的那條路
    在失效時完全不讀那個訊息,印的是固定的「非純簿記增量」(壓過提交時這句話根本是錯的)。
    ★這支直接看那條路的判定結果,不看整個 code-loop check 的輸出★:第二版看整段輸出,
    結果被「表態過期」那一行(它也講壓過提交、也給 code-loop pass 指令)滿足,
    把推送閘那條路改回固定字串照樣綠——是翻紅驗證抓到的假綠。
    翻紅釘:推送閘那條路改回印固定字串 → ②紅。
    """
    import subprocess as _sp, tempfile, os as _os
    m = _import_lumos()
    lumos_real = str(Path(__file__).resolve().parent / "lumos")
    with tempfile.TemporaryDirectory() as d:
        _make_high_tier_repo(d)
        env = dict(_os.environ); env["GIT_DIR"] = str(Path(d) / ".git")
        pr = _sp.run([sys.executable, lumos_real, "code-loop", "pass", "--note", "審過了", "--repo", d],
                     capture_output=True, text=True, env=env)
        check("① 現場成立:審查留痕記得進去", pr.returncode == 0, pr.stdout[-300:] + pr.stderr[-300:])
        _sp.run(["git", "commit", "--amend", "-q", "--no-edit", "--no-verify", "-m", "squashed"],
                cwd=d, capture_output=True, text=True)   # 內容不變,只改寫歷史
        # 照真實的重來順序:表態先在新提交上重答,才看得到審查留痕那一關(表態那關先擋會蓋掉它)
        _answer_stack_questions(d)
        v = m._codeloop_guard_verdict(Path(d))
        reason = str(v.get("reason", ""))
        check("① 現場成立:判的是審查留痕過時(不是別的原因)",
              v.get("blocked") and v.get("reason_kind") == "review" and "留痕" in reason and "過時" in reason, str(v)[:400])
        check("② 那一句就講得出多半是壓過提交,並給重來的指令",
              "壓過提交" in reason and "code-loop pass" in reason, reason[:400])


def t_loop_status_disposal_gate():
    """[T4 處置閘](spec:Projects/design-loop重設計 三;plan:同名_實作計畫 T4)

    `loop status <id> --disposal --spec <真檔> --repo <root>`:新閘走★獨立路徑★,
    四條合取全部讀側可重算:①G3 hash 鏈 ②處置集合(重算,不信寫側)③留痕讀側重驗
    (report/snapshot 存在且 sha256 與帳面一致——record 完刪檔照樣擋)④quote-check
    對帳面 snapshot 重跑全 ok。

    ★d4 合約★:canary kind=missed ★不進合取★——missed 席在場照樣可收斂(觀測非閘)。
    ★相容合約★:同一帳不帶 --disposal 走舊路徑,行為與改動前一致(舊閘一行不動)。
    取捨(plan〈實務隱患〉預告):舊路徑迴歸斷言採「rc+判定行子字串」而非逐字節相同——
    逐字節對提示文字換行過脆;rc+『輪有效』子串足以釘住「走的是舊 panel 判定」。
    翻紅釘:刪掉報告檔 → 條③翻紅(現場成立前置:record 當下檔案在)。"""
    import json as _j
    v = mkvault()
    d = v / "Projects"
    spec = d / "t4spec.md"
    spec.write_text("# spec\n規則甲：只在 0 命中時回退。\n", encoding="utf-8")
    h = _sha256_of(spec)
    snap = d / "t4snap.md"
    snap.write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    rpt = d / "t4rpt.md"
    rpt.write_text("severity: clean\n甲\n引句：「規則甲：只在 0 命中時回退。」\n", encoding="utf-8")
    lid = f"t4-{_M1U}"

    # 判定輪 r1 兩席:席1 帶處置帳+留痕+雙 hash;席2=★missed★(d4:不得影響閘)
    run(v, "canary", "record", "caught", "--loop", lid, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1,F2", "--refuted-set", "none", "--folded-set", "F1",
        "--accepted-set", "F2", "--accept-reason", "F2=精度級",
        "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    run(v, "canary", "record", "missed", "--loop", lid, "--round", "r1", "--auditor", "s2",
        "--severity", "major", "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)   # T6:定錨後每席都要留痕(d4 判定留痕)

    # 互斥
    for extra in (["--panel"], ["--light"], ["--need", "3"]):
        rr = run(v, "loop", "status", lid, "--disposal", "--spec", str(spec), "--repo", str(v.parent), *extra)
        check(f"--disposal 與 {extra[0]} 互斥 rc2", rr.returncode == 2, f"rc={rr.returncode} {rr.stderr[:100]}")
    check("--disposal 缺 --spec rc2(fail-closed,同 light 慣例)",
          run(v, "loop", "status", lid, "--disposal", "--repo", str(v.parent)).returncode == 2, "")

    r = run(v, "loop", "status", lid, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★四條合取全過→rc0;missed 席在場照樣收斂(d4:canary=觀測非閘)★",
          r.returncode == 0, f"rc={r.returncode}\n{r.stdout[:400]}{r.stderr[:200]}")

    # 舊路徑迴歸:同一帳不帶 --disposal 走舊 panel 閘(格式帶 round→須 --panel),行為不變
    r_old = run(v, "loop", "status", lid, "--gate", "--panel", "--spec", str(spec), "--repo", str(v.parent))
    check("★相容:同一帳走舊 panel 閘照舊 FAIL(1 caught+1 missed=輪無效)——舊閘一行不動★",
          r_old.returncode == 1 and "輪有效" in r_old.stdout, f"rc={r_old.returncode}\n{r_old.stdout[:200]}")

    # ③留痕讀側:record 完把報告檔改掉 → sha 不符 → FAIL
    check("★前置★ 現場成立:record 當下報告檔在且剛才 rc0", rpt.exists(), "")
    orig = rpt.read_text(encoding="utf-8")
    rpt.write_text(orig + "事後竄改\n", encoding="utf-8")
    r2 = run(v, "loop", "status", lid, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★留痕讀側重驗:報告被改(sha 不符)必 FAIL rc1★", r2.returncode == 1, f"rc={r2.returncode}\n{r2.stdout[:300]}")
    rpt.write_text(orig, encoding="utf-8")

    # ④quote-check 讀側:快照偷換成沒有該句的版本 → miss → FAIL
    snap2 = d / "t4snap2.md"
    snap2.write_text("# 別的內容\n", encoding="utf-8")
    lid2 = f"t4b-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid2, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--refuted-set", "none", "--folded-set", "F1",
        "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    # 記完再把帳裡的快照換成沒有該句的版本(寫側 2026-09-06 起會擋這種載體,見 _ledger_patch_last)
    _ledger_patch_last(v.parent / ".canary-log.jsonl", lid2, snapshot_path=snap2)
    r3 = run(v, "loop", "status", lid2, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★quote-check 讀側:引句錨不到快照必 FAIL rc1★", r3.returncode == 1, f"rc={r3.returncode}\n{r3.stdout[:300]}")

    # ②處置集合讀側+blocker 線:blocker 席在場且有 accepted → FAIL(即使寫側當時個別合法)
    lid3 = f"t4c-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid3, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--refuted-set", "none", "--folded-set", "",
        "--accepted-set", "F1", "--accept-reason", "F1=可放",
        "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    run(v, "canary", "record", "caught", "--loop", lid3, "--round", "r1", "--auditor", "s2",
        "--severity", "blocker", "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)   # T6 同上
    r4 = run(v, "loop", "status", lid3, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★blocker 在別席+本席 accepted:輪級重算必 FAIL(堵 Codex 的寫側盲區)★",
          r4.returncode == 1, f"rc={r4.returncode}\n{r4.stdout[:300]}")


def t_loop_status_disposal_panel_routing():
    """[修 Issues/設計迴圈問閘指令與panel記帳互斥 d1](2026-08-24 指路不代選)

    多席 panel 型記帳(一輪多筆帶處置)丟給 --disposal:照舊 rc2 擋下,
    但擋下訊息必須指路到 --gate --panel --min-seats(自主迴圈讀指路續跑;
    此前只擋不指,照 skill 字面走的人第一次必撞後自己猜閘)。
    翻紅釘:拿掉指路 print → 錨字串斷言翻紅。前置斷言:多席擋下本身成立。"""
    v = mkvault()
    d = v / "Projects"
    spec = d / "rt-spec.md"
    spec.write_text("# spec\n路由規則甲確實存在於本份文件之中。\n", encoding="utf-8")
    h = _sha256_of(spec)
    snap = d / "rt-snap.md"
    snap.write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    rpt = d / "rt-rpt.md"
    rpt.write_text("severity: clean\n甲\n引句：「路由規則甲確實存在於本份文件之中。」\n", encoding="utf-8")
    lid = f"rt-route-{_M1U}"
    for seat in ("s1", "s2"):
        run(v, "canary", "record", "caught", "--loop", lid, "--round", "r1", "--auditor", seat,
            "--severity", "minor", "--findings-set", "F1", "--refuted-set", "none", "--folded-set", "F1",
            "--report", str(rpt), "--snapshot", str(snap),
            "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r = run(v, "loop", "status", lid, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    err = (r.stderr or "") + (r.stdout or "")
    check("★前置★ 多席帶處置 → disposal rc2 擋下(現場成立)", r.returncode == 2 and "帶了處置結果" in err,
          f"rc={r.returncode}\n{err[:300]}")
    check("★擋下訊息指路到 panel 閘(--gate --panel --min-seats)★",
          "--gate --panel --min-seats" in err and "連續兩輪" in err,
          f"{err[:400]}")
    # 單席一筆:不觸發多席擋,也不該印指路(訊息只在撞牆時出現)
    lid2 = f"rt-single-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid2, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--refuted-set", "none", "--folded-set", "F1",
        "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r2 = run(v, "loop", "status", lid2, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    err2 = (r2.stderr or "") + (r2.stdout or "")
    check("單席一筆:不印指路(rc0 且無 panel 提示)", r2.returncode == 0 and "--gate --panel --min-seats" not in err2,
          f"rc={r2.returncode}\n{err2[:300]}")


def t_disposal_gate_r1_panel_hardening():
    """[T8 終審 r1 findings 修復](plan:design-loop重設計_實作計畫 T8;loop code-dloop-redesign r1)

    五組缺陷全部先機械 repro 證實(可執行 falsification)才修:
    ①壞行 fail-closed:.canary-log 有壞行 → disposal 閘 rc2(原:壞行靜默跳過,判錯 latest);
      T6 定錨掃描改逐行容錯(原:壞行在定錨行前→any() 短路前炸→整包 fail-open,強制被繞過)。
    ②判定輪守衛:round-id 非連續重現 rc2(reuse panel 守衛;原:OrderedDict 首現序拿錯輪,
      時序最後的遲到 r1 帶壞引句照樣 PASS)。
    ③留痕讀側涵蓋判定輪★全部★帶留痕欄的席(原只驗 carrier;竄改 missed 席報告照樣 PASS)。
    ④report/snapshot 以 repo root 相對路徑落帳與解析(原:相對 cwd;換目錄跑 gate 留痕假失蹤,
      合法 loop 永久 FAIL)。
    ⑤report/snapshot 非 UTF-8 → 讀側 FAIL/rc2,不得 traceback。
    翻紅釘:各條把修法還原必翻紅;各場景附「現場成立」前置斷言。"""
    import json as _j
    v = mkvault()
    d = v / "Projects"
    spec = d / "h8spec.md"
    spec.write_text("# spec\n規則『甲』其實存在,規則乙也在。\n", encoding="utf-8")
    h = _sha256_of(spec)
    snap = d / "h8snap.md"
    snap.write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    rptA = d / "h8a.md"
    rptA.write_text("severity: clean\n甲\n引句：「規則『甲』其實存在,規則乙也在。」\n", encoding="utf-8")
    rptB = d / "h8b.md"
    rptB.write_text("severity: clean\n乙\n引句：「規則『甲』其實存在,規則乙也在。」\n", encoding="utf-8")
    ledger = v.parent / ".canary-log.jsonl"

    # ── ① 讀側:壞行 → disposal rc2 ──
    lid1 = f"h8a-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid1, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--refuted-set", "none", "--folded-set", "F1",
        "--report", str(rptA), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r0 = run(v, "loop", "status", lid1, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★前置★ 現場成立:壞行注入前同帳 rc0", r0.returncode == 0, f"rc={r0.returncode}\n{r0.stdout[:200]}")
    good = ledger.read_text(encoding="utf-8")
    ledger.write_text(good + "{broken\n", encoding="utf-8")
    r1 = run(v, "loop", "status", lid1, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★壞行 fail-closed:帳含不可解析行 → disposal rc2★", r1.returncode == 2,
          f"rc={r1.returncode}\n{r1.stdout[:200]}{r1.stderr[:200]}")
    # ── ① 寫側:壞行在定錨行前,T6 強制不得被繞過 ──
    ledger.write_text("{broken\n" + good, encoding="utf-8")
    r2 = run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid1, "--auditor", "s9", "--severity", "minor")
    check("★T6 定錨掃描逐行容錯:壞行在定錨行前,缺留痕照樣 rc2(原 fail-open rc0)★",
          r2.returncode == 2, f"rc={r2.returncode} {r2.stderr[:150]}")
    ledger.write_text(good, encoding="utf-8")

    # ── ② round-id 非連續重現 → rc2 ──
    lid2 = f"h8b-{_M1U}"
    rptBad = d / "h8bad.md"
    rptBad.write_text("severity: clean\n引句：「這句話快照裡根本沒有喔喔喔」\n", encoding="utf-8")
    for rid in ("r1", "r2", "r1"):
        run(v, "canary", "record", "caught", "--loop", lid2, "--round", rid, "--auditor", "sx",
            "--severity", "minor", "--findings-set", "F1", "--refuted-set", "none", "--folded-set", "F1",
            "--report", str(rptA), "--snapshot", str(snap),
            "--spec", str(spec), "--reviewed", h, expect_rc=0)
    # 遲到那筆要「引句錨不到」。2026-09-06 起寫側會擋錨不到的載體,所以這種帳只可能來自
    # 舊版本或手改——直接把帳改成指向壞報告,比繞過寫側更貼近讀側真正要防的東西。
    _ledger_patch_last(ledger, lid2, report_path=rptBad)
    raw = [_j.loads(l) for l in ledger.read_text(encoding="utf-8").splitlines()
           if l.strip() and _j.loads(l).get("loop") == lid2]
    check("★前置★ 現場成立:帳面時序 r1,r2,r1(遲到筆引句錨不到)", [x.get("round") for x in raw] == ["r1", "r2", "r1"], str(raw)[:200])
    r3 = run(v, "loop", "status", lid2, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★round-id 非連續重現=帳次序損壞 rc2(原:拿 r2 當判定輪照樣 PASS)★",
          r3.returncode == 2, f"rc={r3.returncode}\n{r3.stdout[:200]}{r3.stderr[:150]}")

    # ── ③ 竄改非 carrier 席(missed)的報告 → FAIL ──
    lid3 = f"h8c-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid3, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--refuted-set", "none", "--folded-set", "F1",
        "--report", str(rptA), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    run(v, "canary", "record", "missed", "--loop", lid3, "--round", "r1", "--auditor", "s2",
        "--severity", "major", "--report", str(rptB), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r4 = run(v, "loop", "status", lid3, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★前置★ 現場成立:兩席各自留痕,未竄改時 rc0", r4.returncode == 0, f"rc={r4.returncode}\n{r4.stdout[:300]}")
    origB = rptB.read_text(encoding="utf-8")
    rptB.write_text(origB + "事後竄改 missed 席\n", encoding="utf-8")
