def t_quote_full_span_blocks_fabricated_suffix():
    """[引句錨定整段比對 S1]前綴照抄、接閉引號、再接編造文字與另一個閉引號(同行、換行後才補、另一型收尾引號、
    中間插一個後面不是開引號的「引句:」字樣、前文有沒閉合的開引號——r4 兩席實測全域堆疊會把收尾引號配給它):
    新判準判格式不合 kind=stray;舊判準照舊判錨定。"""
    m = _load_lumos_inproc()
    for label, fab in (("同行", "引句:「合法前綴文字至少十個字」編造後半根本不在審材裡」\n"),
                       ("換行後才補", "引句:「合法前綴文字至少十個字」\n編造後半根本不在審材裡」\n"),
                       ("另一型收尾引號", "引句:「合法前綴文字至少十個字」編造後半根本不在審材裡』\n"),
                       ("中間插非標籤字樣", "引句:「合法前綴文字至少十個字」這是引句:編造後半」\n"),
                       ("前文有沒閉合的開引號", "他提到「某規則 還沒結束\n引句:「合法前綴文字至少十個字」編造後半根本不在審材裡」\n")):
        old = _qfs_rows(m, fab, _QFS_OLD)
        new = _qfs_rows(m, fab, _QFS_V1)
        check("引句整段 S1 前置(%s):舊判準判錨定(漏洞存在)" % label, old and all(r["ok"] for r in old), old)
        check("引句整段 S1(%s):新判準判格式不合 kind=stray" % label,
              new and len(new) == 1 and not new[0]["ok"] and new[0].get("malformed") and new[0].get("kind") == "stray", new)
    real = "引句:「合法前綴文字至少十個字,後面接的是別的東西。」\n"
    check("引句整段 S1:原文整句照抄 → 新判準判錨定", all(r["ok"] for r in _qfs_rows(m, real, _QFS_V1)), "")
    print("  ✓ t_quote_full_span_blocks_fabricated_suffix")


def t_quote_full_span_nested_and_multiline():
    """[引句錨定整段比對 S2]同型巢狀、或引句內含另一個完整「引句:「…」」:抽整段、只產生一條結果;跨行照舊。"""
    m = _load_lumos_inproc()
    r1 = _qfs_rows(m, "引句:「規則「甲」其實存在,規則乙也在。」\n", _QFS_V1)
    check("引句整段 S2:同型巢狀抽整段(含內層引號)並判錨定",
          len(r1) == 1 and r1[0]["quote"] == "規則「甲」其實存在,規則乙也在。" and r1[0]["ok"], r1)
    r1o = _qfs_rows(m, "引句:「規則「甲」其實存在,規則乙也在。」\n", _QFS_OLD)
    check("引句整段 S2 前置:舊判準把同一句截在內層、判錨不到", r1o and not r1o[0]["ok"], r1o)
    r2 = _qfs_rows(m, "引句:「規則「甲」其實存在,但這半句是編的」\n", _QFS_V1)
    check("引句整段 S2:巢狀後半不在快照 → 錨不到", len(r2) == 1 and not r2[0]["ok"] and not r2[0].get("malformed"), r2)
    inner = _qfs_rows(m, "引句:「範本寫:引句:「原文要逐字抄十個字以上」,不要改字。」\n", _QFS_V1)
    check("引句整段 S2:引句內含完整「引句:「…」」→ 外層整段一條結果並錨定,不多出幽靈條目", len(inner) == 1 and inner[0]["ok"], inner)
    r3 = _qfs_rows(m, "引句:「第一行內容在這裡\n第二行內容接著寫」\n", _QFS_V1)
    check("引句整段 S2:跨行引句抽整段並判錨定(保留既有行為)", r3 and r3[0]["ok"] and "第二行" in r3[0]["quote"], r3)
    print("  ✓ t_quote_full_span_nested_and_multiline")


def t_quote_full_span_unclosed_and_trailing_note():
    """[引句錨定整段比對 S3]沒有配對閉引號只讓那一條判 kind=unclosed,後面的標籤照常;忘了閉合又被後面的落單收尾引號
    補閉合 → 整段錨不到(仍擋)、被包進去的標籤不另成一條;落單收尾引號只算給前面最近那一條;引句後接註記照常;
    兩型引號各自配對;5000 個未閉合標籤 1 秒內抽完(逐標籤往後掃的寫法是二次方,r3 實測)。"""
    import time as _t
    m = _load_lumos_inproc()
    rpt = "引句:「規則「甲」其實存在,規則乙也在。\n說明\n引句:「合法前綴文字至少十個字,後面接的是別的東西。」\n"
    r1 = _qfs_rows(m, rpt, _QFS_V1)
    check("引句整段 S3:第一條沒有配對閉引號 → kind=unclosed;第二條照常抽出並錨定",
          len(r1) == 2 and r1[0].get("kind") == "unclosed" and not r1[0]["ok"] and r1[1]["ok"], r1)
    check("引句整段 S3:unclosed 列的 quote 是開引號之後到那一行結尾", r1 and r1[0]["quote"] == "規則「甲」其實存在,規則乙也在。", r1[:1])
    cap = "引句:「忘了閉合的前半句\n引句:「合法前綴文字至少十個字,後面接的是別的東西。」\n」\n"
    rc = _qfs_rows(m, cap, _QFS_V1)
    check("引句整段 S3:忘了閉合的引句被後面落單收尾引號補閉合 → 只有一條、整段錨不到、不是格式不合",
          len(rc) == 1 and not rc[0]["ok"] and not rc[0].get("malformed") and "合法前綴" in rc[0]["quote"], rc)
    near = "引句:「合法前綴文字至少十個字,後面接的是別的東西。」\n引句:「第一行內容在這裡第二行」多一個」\n"
    rn = _qfs_rows(m, near, _QFS_V1)
    check("引句整段 S3:落單收尾引號只算給前面最近那一條,前一條照常錨定",
          len(rn) == 2 and rn[0]["ok"] and not rn[0].get("malformed") and rn[1].get("kind") == "stray", rn)
    r2 = _qfs_rows(m, "引句:「合法前綴文字至少十個字,後面接的是別的東西。」(第 2 行,這段是註記)\n", _QFS_V1)
    check("引句整段 S3:引句後接註記、沒有落單收尾引號 → 照常比對並判錨定", len(r2) == 1 and r2[0]["ok"], r2)
    r3 = _qfs_rows(m, "引句:「合法前綴文字至少十個字,後面接的是別的東西。」另見「說明『甲』」\n", _QFS_V1)
    check("引句整段 S3:尾段兩型引號都成對 → 不判落單", len(r3) == 1 and r3[0]["ok"], r3)
    r4 = _qfs_rows(m, "引句:「合法前綴文字至少十個字,後面接的是別的東西。」另見『甲」\n", _QFS_V1)
    check("引句整段 S3:尾段『未閉合又多一個落單」→ 兩型各自配對,判 stray", len(r4) == 1 and r4[0].get("kind") == "stray", r4)
    big = "引句:「甲甲甲甲甲甲甲甲甲甲\n" + "引句:「\n" * 5000
    t0 = _t.perf_counter()
    rb = _qfs_rows(m, big, _QFS_V1)
    dt = _t.perf_counter() - t0
    check("引句整段 S3:5000 個未閉合標籤 1 秒內抽完,每條 kind=unclosed",
          dt < 1.0 and len(rb) == 5001 and all(r.get("kind") == "unclosed" for r in rb), (round(dt, 3), len(rb)))
    print("  ✓ t_quote_full_span_unclosed_and_trailing_note")


def t_quote_full_span_no_masking():
    """[引句錨定整段比對 S4]反引號與圍欄裡的引句照舊抽取比對(r1 三席:遮蔽會讓包起來的造假整條消失);
    格式不合列帶 malformed 與 kind 且 quote 欄最多 200 字;錨定與錨不到的列保留完整 quote(seat-check 拿全文比材料)。"""
    m = _load_lumos_inproc()
    rpt = ("說明:`引句:「這句話快照裡根本沒有喔喔喔」`\n```\n引句:「圍欄裡也是編的不在快照裡」\n```\n"
           "引句:「合法前綴文字至少十個字,後面接的是別的東西。」\n")
    new = _qfs_rows(m, rpt, _QFS_V1)
    check("引句整段 S4:反引號與圍欄裡的引句照常抽出(3 個標籤 3 條結果),造假的判錨不到",
          len(new) == 3 and [r["ok"] for r in new] == [False, False, True], new)
    long = _qfs_rows(m, "引句:「" + "長" * 500 + "\n", _QFS_V1)
    check("引句整段 S4:格式不合列帶 malformed 與 kind,quote 欄最多 200 字加截斷標記",
          len(long) == 1 and long[0].get("malformed") and long[0].get("kind") == "unclosed"
          and len(long[0]["quote"]) <= 210 and "截斷" in long[0]["quote"], [len(long[0]["quote"])] if long else long)
    miss = _qfs_rows(m, "引句:「" + "編" * 300 + "」\n", _QFS_V1)
    check("引句整段 S4:錨不到的列保留完整 quote(300 字不截)",
          len(miss) == 1 and not miss[0]["ok"] and not miss[0].get("malformed") and miss[0]["quote"] == "編" * 300,
          [len(miss[0]["quote"])] if miss else miss)
    print("  ✓ t_quote_full_span_no_masking")


def _qfs_project(prefix):
    """專案根 + docs 帳 + git(治理帳落 root/docs);三份席報告:整句照抄、後半編造、同型巢狀。"""
    import subprocess as _sp
    root, v = _stats_fixture(prefix, [])
    _sp.run(["git", "-C", str(root), "init", "-q"], capture_output=True)
    d = root / "docs"
    spec = d / "spec.md"
    spec.write_text(_QFS_SNAP, encoding="utf-8")
    snap = d / "snap.md"
    snap.write_text(_QFS_SNAP, encoding="utf-8")
    head = "severity: minor\n1. 甲\nseverity: minor\nblocking: 否\n"
    files = {}
    for name, q in (("good", "引句:「合法前綴文字至少十個字,後面接的是別的東西。」\n"),
                    ("fab", "引句:「合法前綴文字至少十個字」編造後半根本不在審材裡」\n"),
                    ("nest", "引句:「規則「甲」其實存在,規則乙也在。」\n")):
        f = d / ("%s.md" % name)
        f.write_text(head + q, encoding="utf-8")
        files[name] = f
    return root, v, d, spec, snap, files


def _qfs_lumos(v, *args, rule=None, broken=None, exc="RuntimeError", consts=None):
    """在同一程序裡跑 lumos:rule 給了就把寫側常數 _QUOTE_WRITE_RULE 換成它;broken 給了就讓 _quote_rows 對那一版丟例外
    (產品碼不留切換判準的開關,subprocess 也注不進例外)。"""
    import subprocess as _sp, sys as _sys
    argv = ["lumos", "--vault", str(v), *args]
    code = ("import sys, importlib.machinery, importlib.util\n"
            "ld = importlib.machinery.SourceFileLoader('lm', %r)\n"
            "sp = importlib.util.spec_from_loader('lm', ld); m = importlib.util.module_from_spec(sp); ld.exec_module(m)\n"
            "rule, broken, exc, consts = %r, %r, %r, %r\n"
            "for _k, _v in (consts or {}).items(): setattr(m, _k, _v)\n"
            "if rule is not None: m._QUOTE_WRITE_RULE = rule\n"
            "if broken is not None:\n"
            "    orig = m._quote_rows\n"
            "    def _b(*a, **k):\n"
            "        if k.get('rule') == broken: raise __import__('builtins').__dict__[exc]('壞掉的判準')\n"
            "        return orig(*a, **k)\n"
            "    m._quote_rows = _b\n"
            "sys.argv = %r\n"
            "sys.exit(m._cli())\n") % (GRAPHCTL, rule, broken, exc, consts, argv)
    return _sp.run([_sys.executable, "-c", code], capture_output=True, text=True)


def _qfs_record(v, lid, rpt, snap, spec, auditor="正確性-sonnet", carrier=True, rule=_QFS_V1, broken=None, exc="RuntimeError"):
    args = ["canary", "record", "none", "--loop", lid, "--round", "r1", "--auditor", auditor, "--severity", "minor",
            "--findings", "1", "--report", str(rpt), "--snapshot", str(snap), "--spec", str(spec), "--reviewed", _sha256_of(spec)]
    if carrier:
        args += ["--findings-set", "F1", "--folded-set", "F1", "--refuted-set", "none"]
    return _qfs_lumos(v, *args, rule=rule, broken=broken, exc=exc)


def _qfs_rows_of(d, lid):
    import json as _j
    led = d / ".canary-log.jsonl"
    return [_j.loads(ln) for ln in (led.read_text(encoding="utf-8").splitlines() if led.exists() else []) if '"%s"' % lid in ln]


def _qfs_set_row(d, lid, row):
    """把該迴圈的載體列換成 row(其餘列不動);指紋照實重算由呼叫端負責。"""
    import json as _j
    led = d / ".canary-log.jsonl"
    lines = led.read_text(encoding="utf-8").splitlines()
    idx = [i for i, ln in enumerate(lines) if '"%s"' % lid in ln and '"findings_set"' in ln][-1]
    lines[idx] = _j.dumps(row, ensure_ascii=False)
    led.write_text("\n".join(lines) + "\n", encoding="utf-8")


def t_quote_full_span_rule_stamped_on_ledger():
    """[引句錨定整段比對 S5]寫側常數 full-span-v1:通過蓋章、被擋不寫帳;處置閘照載體列的章選判準(載體列之後另有無章
    非載體列也不影響)、無章用 legacy、章值不認得判失敗不 traceback;常數 legacy 時新帳蓋 legacy、舊 v1 帳照新判準;
    第一階段常數是 legacy;處置閘遇到判準丟例外判失敗、印型別、不 traceback;手動 quote-check 第一行印判準、--rule 覆蓋、--json 帶 rule。"""
    import json as _j, shutil as _sh
    m = _load_lumos_inproc()
    check("引句整段 S5:第一階段寫側常數是 legacy", m._QUOTE_WRITE_RULE == "legacy", m._QUOTE_WRITE_RULE)
    check("引句整段 S5:診斷指令的參數經 _drift_sh(node=True):開頭是 - 補成 ./、含空白加引號、一般路徑原樣",
          m._drift_sh("-x.md", node=True) == "./-x.md" and m._drift_sh("a b.md", node=True) == "'a b.md'"
          and m._drift_sh("docs/a.md", node=True) == "docs/a.md",
          (m._drift_sh("-x.md", node=True), m._drift_sh("a b.md", node=True)))
    root, v, d, spec, snap, f = _qfs_project("gctl-qrs-")
    try:
        r = _qfs_lumos(v, "quote-check", str(f["fab"]), "--spec", str(snap), rule=_QFS_V1)
        first = r.stdout.splitlines()[0] if r.stdout.strip() else ""
        check("引句整段 S5:手動 quote-check 預設跟寫側常數(新判準),後半編造 rc1,第一行印判準,人讀輸出標出格式不合與 kind",
              r.returncode == 1 and first == "引句判準:%s" % _QFS_V1 and "(格式不合:stray)" in r.stdout, (r.returncode, r.stdout[:300]))
        r2 = _qfs_lumos(v, "quote-check", str(f["fab"]), "--spec", str(snap), "--rule", "legacy", "--json", rule=_QFS_V1)
        js = _j.loads(r2.stdout) if r2.stdout.strip().startswith("{") else {}
        check("引句整段 S5:--rule legacy 覆蓋常數、照舊判準判錨定,--json 物件帶 rule 欄", r2.returncode == 0 and js.get("rule") == "legacy", r2.stdout[:200])
        lid = "qrs-%s" % _M1U
        rw = _qfs_record(v, lid, f["fab"], snap, spec)
        check("引句整段 S5:寫側用新判準擋下後半編造的載體,而且不寫帳", rw.returncode == 2 and not _qfs_rows_of(d, lid), (rw.returncode, rw.stderr[-200:]))
        ok = _qfs_record(v, lid, f["good"], snap, spec)
        _qfs_record(v, lid, f["good"], snap, spec, auditor="邊界-sonnet", carrier=False)
        rows = _qfs_rows_of(d, lid)
        car = [x for x in rows if "findings_set" in x]
        check("引句整段 S5:寫側通過的載體列蓋 quote_rule=full-span-v1(非載體列不蓋)",
              ok.returncode == 0 and car and car[-1].get("quote_rule") == _QFS_V1 and all("quote_rule" not in x for x in rows if "findings_set" not in x),
              [x.get("quote_rule") for x in rows])

        def gate(**kw):
            return _qfs_lumos(v, "loop", "status", lid, "--disposal", "--spec", str(snap), "--repo", str(root), **kw)
        base = car[-1]
        fab_row = dict(base, report_path=base["report_path"].replace("good.md", "fab.md"), report_sha256=_sha256_of(f["fab"]))
        _qfs_set_row(d, lid, fab_row)
        g1 = gate()
        check("引句整段 S5:載體列章 v1 + 報告後半編造 → 處置閘判不過並印判準(載體列之後的無章非載體列不影響)",
              g1.returncode == 1 and ("引句判準:%s" % _QFS_V1) in g1.stdout, g1.stdout[-300:])
        check("引句整段 S5:判不過時印診斷指令,帶處置閘共用的前綴與帳上的章",
              "[disposal]     診斷:lumos quote-check " in g1.stdout and "--rule %s" % _QFS_V1 in g1.stdout, g1.stdout[-300:])
        gm = gate(broken=_QFS_V1, exc="MemoryError")
        check("引句整段 S5:判準遇到記憶體不足 → 照常往外丟(非 0、stderr 有 MemoryError),不當成判準丟例外",
              gm.returncode != 0 and "MemoryError" in gm.stderr and "丟例外" not in gm.stdout, (gm.returncode, gm.stdout[-200:], gm.stderr[-200:]))
        gx = gate(broken=_QFS_V1)
        check("引句整段 S5:處置閘遇到判準丟例外 → 判失敗、印「丟例外」與型別、不 traceback",
              gx.returncode == 1 and "丟例外" in gx.stdout and "RuntimeError" in gx.stdout and "Traceback" not in gx.stderr, (gx.returncode, gx.stdout[-300:], gx.stderr[-200:]))
        _qfs_set_row(d, lid, {k: x for k, x in fab_row.items() if k != "quote_rule"})
        g0 = gate()
        check("引句整段 S5:載體列無章 → 照舊判準判過,並印「帳上無章」", g0.returncode == 0 and "帳上無章" in g0.stdout, g0.stdout[-300:])
        for bad in ("", None, 5, ["full-span-v1"], "future-v9"):
            _qfs_set_row(d, lid, dict(base, quote_rule=bad))
            gb = gate()
            check("引句整段 S5:章值 %r → 判失敗、印「引句判準欄不認得」、不 traceback" % (bad,),
                  gb.returncode == 1 and "引句判準欄不認得" in gb.stdout and "Traceback" not in gb.stderr, (gb.returncode, gb.stdout[-200:], gb.stderr[-200:]))
        zq = d / "零 引句.md"
        zq.write_text("severity: minor\n1. 甲\nseverity: minor\nblocking: 否\n沒有引句\n", encoding="utf-8")
        _qfs_set_row(d, lid, dict(base, report_path=base["report_path"].replace("good.md", "零 引句.md"), report_sha256=_sha256_of(zq)))
        gz = gate()
        check("引句整段 S5:零引句判失敗也印診斷指令,路徑照 --repo 解成實際路徑、含空白加了引號",
              gz.returncode == 1 and "零引句" in gz.stdout and ("診斷:lumos quote-check '%s" % Path(root).resolve()) in gz.stdout,
              [ln for ln in gz.stdout.splitlines() if "診斷" in ln or "零引句" in ln])
        tq = d / "tab\tname.md"
        tq.write_text(f["fab"].read_text(encoding="utf-8"), encoding="utf-8")
        _qfs_set_row(d, lid, dict(fab_row, report_path=str(tq), report_sha256=_sha256_of(tq)))
        gt = gate()
        check("引句整段 S5:報告路徑含控制字元 → 診斷行改印說明、不印可照貼的指令",
              gt.returncode == 1 and "不印可照貼的指令" in gt.stdout and "tab\tname" not in gt.stdout,
              (gt.returncode, [ln for ln in gt.stdout.splitlines() if "\t" in ln or "診斷" in ln or "quote" in ln]))
        _qfs_set_row(d, lid, fab_row)
        check("引句整段 S5:寫側常數是 legacy 時,已蓋 v1 的帳照新判準仍判不過", gate(rule="legacy").returncode == 1, "")
        lx = "qrs-leg-%s" % _M1U
        rr = _qfs_record(v, lx, f["fab"], snap, spec, rule="legacy")
        cr = [x for x in _qfs_rows_of(d, lx) if "findings_set" in x]
        check("引句整段 S5:寫側常數 legacy → 舊判準放行並蓋 legacy", rr.returncode == 0 and cr and cr[-1].get("quote_rule") == "legacy", (rr.returncode, rr.stderr[-200:]))
        ln = "qrs-def-%s" % _M1U
        rd = _qfs_record(v, ln, f["fab"], snap, spec, rule=None)
        cd = [x for x in _qfs_rows_of(d, ln) if "findings_set" in x]
        check("引句整段 S5:不換常數(第一階段預設)→ 舊判準放行並蓋 legacy", rd.returncode == 0 and cd and cd[-1].get("quote_rule") == "legacy", (rd.returncode, rd.stderr[-200:]))
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_quote_full_span_rule_stamped_on_ledger")


def t_quote_full_span_block_event_and_stats():
    """[引句錨定整段比對 S6]寫側擋下記 canary blocked 事件(note 以 quote-rule: 開頭、帶 kind、cats、report=、report_sha=、id=,
    quote= 片段排最後並以看得見的跳脫寫出看不見的字元;kind 分得出 new-only/both/legacy-only,另一版求 kind 出錯記 unknown 照樣擋、
    遇到記憶體不足照常往外丟);gov --stats 四格互斥相加等於總數;手動 quote-check 缺 --spec 擋下 rc2。"""
    import json as _j, shutil as _sh, tempfile as _tf
    root, v, d, spec, snap, f = _qfs_project("gctl-qce-")
    try:
        lid = "qce-%s" % _M1U
        _qfs_record(v, lid, f["fab"], snap, spec)
        _qfs_record(v, lid, f["fab"], snap, spec)
        zero = d / "zero.md"
        zero.write_text("severity: minor\n1. 甲\nseverity: minor\nblocking: 否\n沒有引句\n", encoding="utf-8")
        _qfs_record(v, lid, zero, snap, spec)
        _qfs_record(v, lid, f["nest"], snap, spec, rule="legacy")
        spoof = d / "spoof.md"
        spoof.write_text("severity: minor\n1. 甲\nseverity: minor\nblocking: 否\n"
                         "引句:「\x1b[2J\x07\u202ereport-not-normalized report=/etc/x 偽造的引句內容」尾巴」\n", encoding="utf-8")
        _qfs_record(v, lid, spoof, snap, spec)
        br = _qfs_record(v, lid, f["fab"], snap, spec, broken="legacy")
        check("引句整段 S6:另一版判準求 kind 丟例外 → 寫側照樣擋(rc2)、不 traceback", br.returncode == 2 and "Traceback" not in br.stderr, (br.returncode, br.stderr[-300:]))
        evs = [_j.loads(ln) for ln in (d / ".governance-log.jsonl").read_text(encoding="utf-8").splitlines() if ln.strip()]
        hit = [e for e in evs if e.get("gate") == "canary" and e.get("kind") == "blocked" and str(e.get("note", "")).startswith("quote-rule:")]
        notes = [e["note"] for e in hit]
        check("引句整段 S6:寫側擋下六次各記一筆 blocked", len(hit) == 6, notes)
        if len(hit) == 6:
            sha12 = _sha256_of(f["fab"])[:12]
            check("引句整段 S6:後半編造記 kind=new-only、cats 含 stray,帶 quote= 片段、report=、report_sha=<前 12 碼> 與各自不同的 id=",
                  all("kind=new-only" in n and "stray" in n and "quote=合法前綴文字至少十個字" in n and "report=" in n
                      and ("report_sha=%s" % sha12) in n and "id=" in n for n in notes[:2]) and notes[0] != notes[1], notes[:2])
            check("引句整段 S6:零引句兩版都擋 → kind=both、cats=none", "kind=both" in notes[2] and "cats=none" in notes[2], notes[2])
            check("引句整段 S6:常數 legacy 擋下巢狀(新判準會放)→ kind=legacy-only、quote= 是被截的前半",
                  notes[3].startswith("quote-rule:legacy") and "kind=legacy-only" in notes[3] and "quote=規則「甲" in notes[3], notes[3])
            sp_note = notes[4]
            check("引句整段 S6:引句片段濾掉控制字元、排在 note 最後,第一個 report= 是真的報告路徑(片段裡偽造的欄位騙不到)",
                  "\x1b" not in sp_note and "\x07" not in sp_note and "\u202e" not in sp_note and "\\u202e" in sp_note and sp_note.index("quote=") > sp_note.index("id=")
                  and sp_note.split("report=", 1)[1].startswith(str(spoof)), sp_note)
            check("引句整段 S6:求 kind 出錯記 kind=unknown", "kind=unknown" in notes[5], notes[5])
        bm = _qfs_record(v, "qce-mem-%s" % _M1U, f["fab"], snap, spec, broken="legacy", exc="MemoryError")
        check("引句整段 S6:寫側求 kind 遇到記憶體不足 → 照常往外丟(非 0、stderr 有 MemoryError),不吞成 kind=unknown",
              bm.returncode != 0 and "MemoryError" in bm.stderr, (bm.returncode, bm.stderr[-200:]))
        m = _load_lumos_inproc()
        n_tag = m._quote_block_note("legacy", [{"quote": "甲\U000E0041\u200e\u061c\u200b\ufeff\x1b乙", "ok": False}], "x", "x", str(f["good"]), "l", "a")
        tail = n_tag.split("quote=", 1)[1]
        check("引句整段 S6:片段裡看不見的字元(標籤字元、方向標記、零寬、BOM、ESC)原字元不進 note,換成看得見的 \\uXXXX",
              not any(c in tail for c in "\U000E0041\u200e\u061c\u200b\ufeff\x1b") and "\\u200e" in tail and "\\u001b" in tail
              and tail.startswith("甲") and tail.endswith("乙"), tail)
        from unittest import mock as _mock
        seen = []
        _orig_kill = m._kill_esc
        with _mock.patch.object(m, "_kill_esc", lambda v: seen.append(len(v)) or _orig_kill(v)):
            m._quote_block_note("legacy", [{"quote": "長" * 100000, "ok": False}], "x", "x", str(f["good"]), "l", "a")
        check("引句整段 S6:超長引句先截 60 字再跳脫(不對整條十萬字逐字元處理)", seen and max(seen) <= 60, seen[:3])
        n_empty = m._quote_block_note("legacy", [{"quote": "   ", "ok": False}], "x", "x", str(f["good"]), "l", "a")
        check("引句整段 S6:引句是空白時記 quote=-(跟沒有引句同一個佔位)", n_empty.endswith("quote=-"), n_empty)
        n_leg = m._quote_block_note("legacy", [{"quote": "(引號未閉合/開閉型態不符,無法抽取)", "ok": False, "malformed": True}],
                                    "x", "x", str(f["good"]), "l", "a")
        check("引句整段 S6:舊判準的格式不合列(沒有 kind)記 cats=unclosed,不記成 miss", "cats=unclosed" in n_leg, n_leg)
        st = run(v, "gov", "--since", "9999", "--stats", expect_rc=0).stdout
        check("引句整段 S6:gov --stats 四格互斥、相加等於總數(片段裡含 report-not-normalized 字樣的那筆只算引句判準)",
              "記帳被寫側擋下 6 次(報告沒正規化 0 / 缺 refuted-set 0 / findings 多於 reported 0 / 引句判準 6)" in st, st[-600:])
        b = run(v, "quote-check", str(f["good"]))
        check("引句整段 S6:一般模式缺 --spec → rc2 擋下", b.returncode == 2 and "擋下" in b.stderr, (b.returncode, b.stderr[-200:]))
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_quote_full_span_block_event_and_stats")


def t_quote_full_span_replay_follows_stamp():
    """[引句錨定整段比對 S7]蓋 v1 章的迴圈凍結後回放判定不變(verdict rc0、fails 空);改章回放報帳被動;
    帳不動、只有程式的 v1 分支丟例外時回放報邏輯漂移(週跑才會當紅燈,不落進一般錯誤)。"""
    import json as _j, shutil as _sh
    root, v, d, spec, snap, f = _qfs_project("gctl-qrp-")
    try:
        lid = "qrp-%s" % _M1U
        _qfs_record(v, lid, f["nest"], snap, spec)
        car = [x for x in _qfs_rows_of(d, lid) if "findings_set" in x]
        check("引句整段 S7 前置:巢狀引句的載體用新判準記帳並蓋 v1", car and car[-1].get("quote_rule") == _QFS_V1, car)
        import subprocess as _sp
        for a in (["add", "-A"], ["-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "卷證"]):
            _sp.run(["git", "-C", str(root), *a], capture_output=True)     # 凍結要求卷證已進版控
        fr = run(v, "loop", "replay", lid, "--freeze", "--spec", str(snap), "--repo", str(root))
        golden = root / "governance" / "replay" / lid / "verdict.json"
        check("引句整段 S7 前置:凍結成功", fr.returncode == 0 and golden.exists(), fr.stdout[-300:] + fr.stderr[-200:])
        vd = _j.loads(golden.read_text(encoding="utf-8")).get("verdict", {}) if golden.exists() else {}
        check("引句整段 S7:凍結的判定是過(rc 0、fails 空)——巢狀照章用新判準", vd.get("rc") == 0 and vd.get("fails") == [], vd)
        rp = run(v, "loop", "replay", lid, "--golden", str(golden), "--spec", str(snap), "--repo", str(root))
        check("引句整段 S7:回放判定與凍結時相同", rp.returncode == 0, rp.stdout[-300:])
        rb = _qfs_lumos(v, "loop", "replay", lid, "--golden", str(golden), "--spec", str(snap), "--repo", str(root), broken=_QFS_V1)
        check("引句整段 S7:帳不動、程式的 v1 分支丟例外 → 回放報邏輯漂移", rb.returncode != 0 and "邏輯漂移" in rb.stdout, (rb.returncode, rb.stdout[-300:], rb.stderr[-200:]))
        for tag, row in (("刪章", {k: x for k, x in car[-1].items() if k != "quote_rule"}), ("換成 legacy", dict(car[-1], quote_rule="legacy"))):
            _qfs_set_row(d, lid, row)
            rp2 = run(v, "loop", "replay", lid, "--golden", str(golden), "--spec", str(snap), "--repo", str(root))
            check("引句整段 S7:%s後回放報帳被動" % tag, rp2.returncode != 0 and "帳被動" in rp2.stdout, rp2.stdout[-300:])
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_quote_full_span_replay_follows_stamp")


def t_quote_full_span_v1_pinned():
    """[引句錨定整段比對 S8]full-span-v1 的判定釘版:一組固定輸入的每條 (ok, malformed, kind) 必須跟下表完全相同。
    ★這支紅了代表改了已蓋章判準的判定★——帳上蓋過 full-span-v1 的迴圈回放會跟凍結時對不上。該做的是新增一個版本值
    (例如 full-span-v2)與對應分支,舊分支原樣留著;不是改這張表。只修丟例外、不改任何判定的錯,這支不該紅。"""
    m = _load_lumos_inproc()
    cases = (
        ("引句:「合法前綴文字至少十個字,後面接的是別的東西。」\n", [(True, False, None)]),
        ("引句:「合法前綴文字至少十個字」編造後半根本不在審材裡」\n", [(False, True, "stray")]),
        ("他提到「某規則 還沒結束\n引句:「合法前綴文字至少十個字」編造後半根本不在審材裡」\n", [(False, True, "stray")]),
        ("引句:「合法前綴文字至少十個字」另一型收尾』\n", [(False, True, "stray")]),
        ("引句:「規則「甲」其實存在,規則乙也在。」\n", [(True, False, None)]),
        ("引句:「規則「甲」其實存在,但這半句是編的」\n", [(False, False, None)]),
        ("引句:「範本寫:引句:「原文要逐字抄十個字以上」,不要改字。」\n", [(True, False, None)]),
        ("引句:「沒閉合的一句\n引句:「合法前綴文字至少十個字,後面接的是別的東西。」\n", [(False, True, "unclosed"), (True, False, None)]),
        ("引句:「忘了閉合的前半句\n引句:「合法前綴文字至少十個字,後面接的是別的東西。」\n」\n", [(False, False, None)]),
        ("引句:「合法前綴文字至少十個字,後面接的是別的東西。」(第 2 行註記)\n", [(True, False, None)]),
        ("引句:「短」\n", [(False, False, None)]),
        ("引句:「這句話快照裡根本沒有喔喔喔」\n", [(False, False, None)]),
        ("沒有任何標籤\n", []),
    )
    for text, want in cases:
        got = [(r["ok"], bool(r.get("malformed")), r.get("kind")) for r in (_qfs_rows(m, text, _QFS_V1) or [])]
        check("引句整段 S8:v1 判定釘版 %r" % text[:24], got == want, (got, want))
    print("  ✓ t_quote_full_span_v1_pinned")


def t_quote_check_nested_quotes_and_min_length():
    """[T8 終審 r1 findings 修復](loop code-dloop-redesign r1;s1-F2+否決席-F1 機械證實)

    ①巢狀『』截斷:原 regex `[^」』]+` 在引句內的『』就停,「規則『甲」被當前綴錨到
      → 編造的後半永遠沒被驗(錨定紀律被架空)。修:引句止於同型閉引號(「…」內容許『』)。
    ②引句下限:norm 後 <10 字判 miss(否決席:一字引句「的」必然錨得到,gate 照樣「全數錨定」)。
    翻紅釘:①還原 regex → 巢狀編造案例翻紅;②拔下限 → 一字引句案例翻紅。"""
    v = mkvault()
    d = v / "Projects"
    snap = d / "nsnap.md"
    snap.write_text("本規則「規則『甲』其實存在而且一直都存在」云云,而且的確如此。\n", encoding="utf-8")
    # ① 巢狀:真引句(含『』全文)判 ok;編造尾巴判 miss
    ok_rpt = d / "nok.md"
    ok_rpt.write_text("引句：「規則『甲』其實存在而且一直都存在」\n", encoding="utf-8")
    r1 = run(v, "quote-check", str(ok_rpt), "--spec", str(snap))
    check("★前置★ 現場成立:含巢狀『』的真引句全文判 ok(rc0)", r1.returncode == 0,
          f"rc={r1.returncode}\n{r1.stdout[:200]}")
    bad_rpt = d / "nbad.md"
    bad_rpt.write_text("引句：「規則『甲』其實根本不存在,是編出來的」\n", encoding="utf-8")
    r2 = run(v, "quote-check", str(bad_rpt), "--spec", str(snap))
    check("★巢狀『』不截斷:編造尾巴的引句必 miss(rc1;原截成「規則『甲」前綴假 ok)★",
          r2.returncode == 1, f"rc={r2.returncode}\n{r2.stdout[:200]}")
    # ② 下限:一字引句(快照確實含「的」)→ miss
    tiny = d / "ntiny.md"
    tiny.write_text("引句：「的」\n", encoding="utf-8")
    r3 = run(v, "quote-check", str(tiny), "--spec", str(snap))
    check("★引句 norm 後 <10 字判 miss(rc1;錨定紀律的 ≥10 字轉機械)★",
          r3.returncode == 1, f"rc={r3.returncode}\n{r3.stdout[:200]}")


def t_disposal_snapshot_provenance():
    """[T3 凍結快照](spec:Projects/design-loop重設計 三;plan:同名_實作計畫 T3)

    ★釘死反循環場景★:finding 折入真檔後,它的引句在「現檔」裡就存在了——
    對現檔跑 quote-check 會假 ok(循環自證,r1 Codex 折入的洞)。
    ★quote-check 的比對對象必須是派工當下的凍結快照★:同一份報告,
    對快照跑必 miss(引句是審查員指出「該加而沒有」的內容)、對折入後現檔跑會 ok
    ——兩者 rc 不同,就是這條合約的鑑別力所在。"""
    v = mkvault()
    d = v / "Projects"
    snap = d / "t3snap.md"       # 派工當下凍結
    snap.write_text("# spec v1\n規則甲：只在 0 命中時回退。\n", encoding="utf-8")
    rpt = d / "t3rpt.md"
    # 審查員的 finding:引的是它「建議加入」的句子(快照裡沒有)
    rpt.write_text("severity: minor\n缺逃生口\n引句：「規則乙：加 --escape 逃生口。」\n", encoding="utf-8")
    cur = d / "t3cur.md"         # 折入後的現檔:把 finding 建議的句子折進去了
    cur.write_text("# spec v2\n規則甲：只在 0 命中時回退。\n規則乙：加 --escape 逃生口。\n", encoding="utf-8")

    r_snap = run(v, "quote-check", str(rpt), "--spec", str(snap))
    r_cur = run(v, "quote-check", str(rpt), "--spec", str(cur))
    check("★前置★ 現場成立:對折入後現檔跑會假 ok(循環自證真的會發生)", r_cur.returncode == 0,
          f"rc={r_cur.returncode}")
    check("★對凍結快照跑必 miss(rc1)——這就是「必須對快照驗」合約的鑑別力★",
          r_snap.returncode == 1, f"rc={r_snap.returncode}")

    # record 帶 --snapshot 落帳的 sha256 可重算=快照身分可稽核
    import json as _j
    lid = f"t3-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid, "--severity", "minor",
        "--auditor", "s1", "--report", str(rpt), "--snapshot", str(snap), expect_rc=0)
    last = _j.loads((v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").strip().splitlines()[-1])
    check("snapshot_sha256 落帳且可重算(快照身分可稽核)",
          last.get("snapshot_sha256") == _sha256_of(snap), str(last)[:200])


def t_canary_record_carrier_must_be_fully_anchored():
    """帶處置清單的那一席(全輪帳本載體)引句必須全錨,記帳當下就擋(2026-09-06,第三次踩)。

    出身:規矩早就寫著「記帳前先跑引句檢查,挑每句都錨得到的那一席當載體」。這次我三席都
    跑了檢查,**卻還是把有兩句錨不回快照的那席當載體**——跑了檢查但沒拿檢查結果去做決定。
    處置閘照樣抓到了,但那時帳已經寫進只進不出的帳本,撤不掉,只能換迴圈編號把整輪重記一次。

    ★這支把同一道檢查往前挪到寫帳之前★:代價從「整輪重記」降成「換一席再敲一次」。
    只驗載體席;其餘席的引句本來就允許錨不到(不採信而已,不擋)。

    錨不到不等於編造:今天那兩句引的是既有程式碼(說明「專案本來就有這個做法」),
    不在只含改動的快照裡。所以訊息要講清楚是「這席不適合當載體」,不是「這席在造假」。"""
    import json as _j
    v = mkvault()
    lid = f"carrier-{_M1U}"
    snap = v / "Projects" / "snap.md"
    snap.write_text("這是凍結快照 的內容 只有改動在裡面\n", encoding="utf-8")
    good = v / "Projects" / "good.md"
    good.write_text("severity: major\nseverity: major\nx\n  引句:「這是凍結快照 的內容」\nseverity: major\ny\n", encoding="utf-8")
    bad = v / "Projects" / "bad.md"
    bad.write_text("severity: major\nseverity: major\nx\n  引句:「這是凍結快照 的內容」\nseverity: major\n"
                   "y\n  引句:「這行在既有程式碼裡 不在改動裡」\n", encoding="utf-8")

    # ① 非載體席(不帶處置清單):錨不到照樣可以記,不擋
    run(v, "canary", "record", "none", "--loop", lid, "--round", "r1", "--auditor", "s1",
        "--severity", "major", "--findings", "2", "--report", str(bad), "--snapshot", str(snap),
        expect_rc=0)
    check("載體全錨: 非載體席引句錨不到不擋(本來就只是不採信)", True, "")

    # ② 拿它當載體(帶處置清單)→ 擋下
    r = run(v, "canary", "record", "none", "--loop", lid, "--round", "r1", "--auditor", "s2",
            "--severity", "major", "--findings", "2", "--report", str(bad), "--snapshot", str(snap),
            "--findings-set", "a,b", "--refuted-set", "none", "--folded-set", "a,b", "--accepted-set", "",
            expect_rc=2)
    check("載體全錨: 引句錨不到的席當載體 → 記帳當下擋下(rc2)", True, "")
    check("載體全錨: 訊息講「換一席全錨的來帶」而不是指控造假",
          "換一席全錨的來帶處置清單" in r.stderr and "不算編造" in r.stderr, r.stderr[-400:])
    check("載體全錨: 訊息說清楚寫進去會被閘擋、只能換編號重記整輪",
          "換迴圈編號" in r.stderr and "整輪重記" in r.stderr, r.stderr[-400:])

    # ③ 換全錨席當載體 → 過
    run(v, "canary", "record", "none", "--loop", lid, "--round", "r1", "--auditor", "s3",
        "--severity", "major", "--findings", "2", "--report", str(good), "--snapshot", str(snap),
        "--findings-set", "a,b", "--refuted-set", "none", "--folded-set", "a,b", "--accepted-set", "",
        expect_rc=0)
    last = _j.loads((v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").strip().splitlines()[-1])
    check("載體全錨/反面: 全錨席當載體照樣記得進去", last.get("findings_set") == ["a", "b"], str(last)[:200])


def t_canary_carrier_zero_quote_rejected():
    """載體零引句要在只進不出的 canary 帳寫入前拒收；空輪不帶處置集照舊。

    現場：code-seat-input-validation r2 把 none 當 finding ID 寫進零發現帳，
    寫側成功但處置閘因零引句失敗。不是增加放行標準，是把既有拒收往前移。
    翻紅：原 CLI 在四種可讀快照案例皆成功追加，rc2 與帳不變兩項翻紅。
    """
    import json as _j
    import os as _os
    v = mkvault()
    snap = v / "Projects" / "snapshot.patch"
    snap.write_text("這是凍結材料裡可以核對的一整段文字\n", encoding="utf-8")
    clean = v / "Projects" / "clean.md"
    clean.write_text("severity: clean\n# 沒有問題\n本席沒有發現。\n", encoding="utf-8")
    minor = v / "Projects" / "minor.md"
    minor.write_text("severity: minor\n## F1\nseverity: minor\n報了一條但沒有引句。\n", encoding="utf-8")
    ledger = v.parent / ".canary-log.jsonl"
    # 先建成功前綴，逐位元比較證明失敗沒有追加；不是只看最後一行。
    run(v, "canary", "record", "none", "--loop", f"code-zq-prefix-{_M1U}", "--round", "r1", "--auditor", "通才-codex",
        "--severity", "clean", "--findings", "0", "--report", str(clean), "--snapshot", str(snap), expect_rc=0)
    seed = _j.loads(ledger.read_text(encoding="utf-8").splitlines()[-1])
    check("載體零引句前置：loop 審查席報告解析路徑成立", seed.get("reported") == 0, str(seed))
    # none 那個案例(現場的原形)2026-10-15 起由保留字規則先擋,另外驗(記帳與迴圈工具小修 d3);這裡只留一般 ID
    cases = (("F1", clean, "clean", ["--findings", "0"]),
             ("F1", minor, "minor", ["--findings", "1"]),
             ("F1", minor, "minor", []))
    for optimized in (False, True):
        prefix = [sys.executable, *(["-O"] if optimized else []), GRAPHCTL,
                  "--vault", str(v), "canary", "record", "none", "--round", "r1",
                  "--auditor", "通才-codex", "--snapshot", str(snap)]
        before = ledger.read_bytes()
        r = subprocess.run([*prefix, "--loop", f"code-zq-{_M1U}-{optimized}-none", "--report", str(clean), "--severity", "clean",
                            "--findings", "0", "--findings-set", "none", "--folded-set", "none", "--refuted-set", "none"],
                           capture_output=True, text=True, env={**_os.environ})
        check(f"載體零引句/{optimized}/none:現場原形改由保留字規則先擋、帳逐位元不變",
              r.returncode == 2 and "保留字" in r.stderr and ledger.read_bytes() == before, r.stderr[-200:])
        for index, (fid, report, severity, count_args) in enumerate(cases):
            before = ledger.read_bytes()
            r = subprocess.run([*prefix, "--loop", f"code-zq-{_M1U}-{optimized}-{index}",
                                "--report", str(report), "--severity", severity,
                                *count_args, "--findings-set", fid, "--folded-set", fid,
                                "--refuted-set", "none"], capture_output=True, text=True,
                               env={**_os.environ})
            label = f"載體零引句/{optimized}/{fid}/{count_args}"
            check(label + " rc2 且明確拒收", r.returncode == 2 and "沒有引句" in r.stderr,
                  f"rc={r.returncode} {r.stdout[-150:]} {r.stderr[-200:]}")
            check(label + " 提示兩條復原路徑", "處置選項" in r.stderr and "改選" in r.stderr
                  and "載體" in r.stderr, r.stderr[-200:])
            check(label + " 不印成功、不 traceback", "✓" not in r.stdout and "Traceback" not in r.stderr,
                  r.stdout[-150:] + r.stderr[-150:])
            check(label + " canary 帳逐位元不變", ledger.read_bytes() == before,
                  str(_j.loads(ledger.read_text(encoding="utf-8").splitlines()[-1])))
        # 有引句但快照缺失，要由既有 IO 出口拒收，不誤報成零引句。
        quoted = v / "Projects" / "quoted.md"
        quoted.write_text("severity: minor\n## F1\nseverity: minor\n"
                          "引句:「這是凍結材料裡可以核對的一整段文字」\n", encoding="utf-8")
        before = ledger.read_bytes()
        r = subprocess.run([*prefix, "--loop", f"code-zq-io-{_M1U}-{optimized}",
                            "--snapshot", str(v / "missing.patch"),
                            "--report", str(quoted), "--severity", "minor", "--findings", "1",
                            "--findings-set", "F1", "--folded-set", "F1", "--refuted-set", "none"],
                           capture_output=True, text=True, env={**_os.environ})
        check(f"載體快照 IO/{optimized} rc2、不誤報零引句",
              r.returncode == 2 and "--snapshot" in r.stderr and "沒有引句" not in r.stderr,
              f"rc={r.returncode} {r.stderr[-200:]}")
        check(f"載體快照 IO/{optimized} canary 帳逐位元不變", ledger.read_bytes() == before, "")


def t_canary_carrier_quote_positive_controls():
    """全錨載體照舊；未填 findings 與全輪集合不可被新守衛誤擋。(原本還驗 literal none 真實 ID;2026-10-15 起 none 是保留字、
    被擋的行為改由 t_canary_record_none_is_reserved_id 守——記帳與迴圈工具小修 d3)"""
    import json as _j
    v = mkvault()
    snap = v / "Projects" / "snapshot.patch"
    snap.write_text("這是凍結材料裡可以核對的一整段文字\n", encoding="utf-8")
    rpt = v / "Projects" / "quoted.md"
    rpt.write_text("severity: minor\n## F1\nseverity: minor\n"
                   "引句:「這是凍結材料裡可以核對的一整段文字」\n", encoding="utf-8")
    for optimized in (False, True):
        newline = "\r\n" if optimized else "\n"
        snap.write_bytes(("這是凍結材料裡可以核對的一整段文字" + newline).encode("utf-8"))
        rpt.write_bytes(("severity: minor\n## F1\nseverity: minor\n"
                         "引句:「這是凍結材料裡可以核對的一整段文字」\n").replace("\n", newline).encode("utf-8"))
        for index, (fid, count_args) in enumerate((("F1", []), ("F1,F2", ["--findings", "1"]))):   # none 改成保留字(d3),不再是合法 ID
            r = subprocess.run([sys.executable, *(["-O"] if optimized else []), GRAPHCTL,
                                "--vault", str(v), "canary", "record", "none", "--round", "r1",
                                "--loop", f"code-zq-positive-{_M1U}-{optimized}-{index}",
                                "--auditor", "通才-codex", "--report", str(rpt), "--snapshot", str(snap),
                                "--severity", "minor", *count_args, "--findings-set", fid,
                                "--folded-set", fid, "--refuted-set", "none"], capture_output=True, text=True)
            check(f"載體全錨/{optimized}/{fid}/{count_args} 成功", r.returncode == 0,
                  f"rc={r.returncode} {r.stderr[-200:]}")
            rows = (v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines()
            last = _j.loads(rows[-1])
            check(f"載體全錨/{optimized}/{fid} 前置：確實解析審查報告", last.get("reported") == 1,
                  str(last)[-200:])
            check(f"載體全錨/{optimized}/{fid} ID 保留原意", last.get("findings_set") == fid.split(",")
                  and last.get("folded_set") == fid.split(","), str(last)[-200:])


def t_canary_carrier_invalid_snapshot_encoding():
    """載體快照解碼錯誤須受控拒收，合法與非載體控制不改寫證據。"""
    import json as _j
    text = "這是可以核對的凍結材料原文而且字數足夠"
    for opt in (False, True):
        v = mkvault()
        root = v.parent
        snap = root / "snapshot.patch"
        report = root / "quoted.md"
        report.write_text("severity: minor\n## F1\nseverity: minor\nblocking: 否\n"
                          + "引句:「" + text + "」\n", encoding="utf-8")
        ledger = root / ".canary-log.jsonl"
        def carrier(label, non_encoding_fault=False, quote_fault=False):
            args = [GRAPHCTL, "--vault", str(v), "canary", "record", "none",
                "--loop", f"code-snapshot-{opt}-{label}", "--round", "r1", "--auditor", "通才-codex",
                "--severity", "minor", "--findings", "1", "--tier", "standard", "--report", str(report),
                "--snapshot", str(snap), "--findings-set", "F1", "--folded-set", "F1", "--refuted-set", "none"]
            prefix = [sys.executable, *(["-O"] if opt else [])]
            if non_encoding_fault:
                shim = ("import runpy, sys\nfrom pathlib import Path\n"
                        "original = Path.read_bytes\n"
                        "def read_bytes(path):\n"
                        f"    if path == Path({str(snap)!r}):\n"
                        "        raise RuntimeError('snapshot-non-encoding-fault')\n"
                        "    return original(path)\n"
                        "Path.read_bytes = read_bytes\n"
                        f"sys.argv = {args!r}\nrunpy.run_path({GRAPHCTL!r}, run_name='__main__')\n")
                return subprocess.run([*prefix, "-c", shim], capture_output=True, text=True)
            if quote_fault:
                shim = ("import runpy, sys\n"
                        f"sys.argv = {args!r}\nnamespace = runpy.run_path({GRAPHCTL!r})\n"
                        f"def quote_rows(*args, **kwargs):\n    raise {quote_fault if isinstance(quote_fault, str) else 'RuntimeError'}('snapshot-quote-parser-fault')\n"
                        "namespace['cmd_canary'].__globals__['_quote_rows'] = quote_rows\n"
                        "sys.exit(namespace['main']())\n")
                return subprocess.run([*prefix, "-c", shim], capture_output=True, text=True)
            return subprocess.run([*prefix, *args], capture_output=True, text=True)
        snap.write_bytes(b"\xff\xfe")
        first = carrier("first-bad")
        check(f"快照編碼 opt={opt}:首筆rc2指出snapshot編碼",
              first.returncode == 2 and "--snapshot" in first.stderr and "UTF" in first.stderr,
              first.stdout + first.stderr)
        check(f"快照編碼 opt={opt}:首筆不建帳且無成功訊息",
              not ledger.exists() and "✓" not in first.stdout, first.stdout + first.stderr)
        snap.write_bytes((text + "\n").encode("utf-8"))
        seed = carrier("valid-seed")
        check(f"快照編碼 opt={opt}:全錨合法種子確實落帳",
              seed.returncode == 0 and ledger.exists(), seed.stdout + seed.stderr)
        if seed.returncode != 0 or not ledger.exists():
            continue
        row = _j.loads(ledger.read_text(encoding="utf-8").splitlines()[-1])
        check(f"快照編碼 opt={opt}:種子確實解析報告且存同份指紋",
              row.get("reported") == 1 and row.get("snapshot_sha256") == _sha256_of(snap), str(row))
        bads = (b"\xff\xfe", (text + "\n").encode("utf-8") + b"\xff",
                (text + "\n").encode("utf-8") + b"\xe4\xb8")
        for i, badbytes in enumerate(bads):
            snap.write_bytes(badbytes)
            before = ledger.read_bytes()
            bad = carrier(f"bad-{i}")
            check(f"快照編碼 opt={opt} case={i}:rc2與欄位診斷",
                  bad.returncode == 2 and "--snapshot" in bad.stderr and "UTF" in bad.stderr,
                  bad.stdout + bad.stderr)
            check(f"快照編碼 opt={opt} case={i}:無traceback或成功訊息",
                  "Traceback" not in bad.stderr and "✓" not in bad.stdout, bad.stdout + bad.stderr)
            check(f"快照編碼 opt={opt} case={i}:成功帳逐位元不變",
                  ledger.read_bytes() == before, bad.stdout + bad.stderr)
        snap.write_bytes((text + "\r\n").encode("utf-8"))
        good = carrier("valid-crlf")
        check(f"快照編碼 opt={opt}:CRLF合法對照成功",
              good.returncode == 0, good.stdout + good.stderr)
        row = _j.loads(ledger.read_text(encoding="utf-8").splitlines()[-1])
        check(f"快照編碼 opt={opt}:CRLF仍記同份原始bytes指紋",
              row.get("reported") == 1 and row.get("snapshot_sha256") == _sha256_of(snap), str(row))
        snap.write_bytes((text + "\n").encode("utf-8"))
        before = ledger.read_bytes()
        fault = carrier("non-encoding-fault", non_encoding_fault=True)
        check(f"快照編碼 opt={opt}:非編碼故障仍為原RuntimeError",
              fault.returncode == 1 and "RuntimeError: snapshot-non-encoding-fault" in fault.stderr,
              fault.stdout + fault.stderr)
        check(f"快照編碼 opt={opt}:非編碼故障不追加成功帳",
              ledger.read_bytes() == before and "✓" not in fault.stdout, fault.stdout + fault.stderr)
        for error in ("RuntimeError", "OSError"):
            fault = carrier(f"quote-parser-{error}", quote_fault=error)
            check(f"快照編碼 opt={opt}:引句解析故障仍為原{error}",
                  fault.returncode == 1 and f"{error}: snapshot-quote-parser-fault" in fault.stderr,
                  fault.stdout + fault.stderr)
            check(f"快照編碼 opt={opt}:引句解析{error}不追加成功帳",
                  ledger.read_bytes() == before and "✓" not in fault.stdout, fault.stdout + fault.stderr)
        clean = root / "clean.md"
        clean.write_text("severity: clean\n本席沒有發現。\n", encoding="utf-8")
        snap.write_bytes(b"\xff\xfe")
        legacy = subprocess.run([sys.executable, *(["-O"] if opt else []), GRAPHCTL,
            "--vault", str(v), "canary", "record", "none", "--loop", f"code-noncarrier-{opt}",
            "--round", "r1", "--auditor", "通才-codex", "--severity", "clean", "--findings", "0",
            "--tier", "standard", "--report", str(clean), "--snapshot", str(snap)],
            capture_output=True, text=True)
        check(f"快照編碼 opt={opt}:非載體原政策仍成功",
              legacy.returncode == 0, legacy.stdout + legacy.stderr)
        row = _j.loads(ledger.read_text(encoding="utf-8").splitlines()[-1])
        check(f"快照編碼 opt={opt}:非載體保存壞編碼原bytes指紋",
              row.get("reported") == 0 and row.get("snapshot_sha256") == _sha256_of(snap), str(row))
        snap.unlink()
        before = ledger.read_bytes()
        missing = carrier("missing-snapshot")
        check(f"快照編碼 opt={opt}:缺檔沿用IO診斷而非編碼",
              missing.returncode == 2 and "--snapshot" in missing.stderr and "UTF" not in missing.stderr,
              missing.stdout + missing.stderr)
        check(f"快照編碼 opt={opt}:缺檔無traceback且帳不變",
              "Traceback" not in missing.stderr and ledger.read_bytes() == before and "✓" not in missing.stdout,
              missing.stdout + missing.stderr)

def t_canary_carrier_snapshot_io_recovery_rejected():
    """驗句讀取失敗不能由稍後可讀的 raw hash 代替，成功帳保持不變。"""
    for optimized in (False, True):
        v = mkvault()
        root = v.parent
        text = "這是凍結材料裡可以核對的一整段原始文字"
        snap = root / "snapshot.patch"
        report = root / "report.md"
        report.write_text("severity: minor\n## F1\nseverity: minor\n引句:「" + text + "」\n", encoding="utf-8")
        ledger = root / ".canary-log.jsonl"
        def call(label, transient=True):
            args = [GRAPHCTL, "--vault", str(v), "canary", "record", "none",
                    "--loop", f"code-snapshot-io-{optimized}-{label}", "--round", "r1",
                    "--auditor", "通才-codex", "--severity", "minor", "--findings", "1",
                    "--tier", "standard", "--report", str(report), "--snapshot", str(snap),
                    "--findings-set", "F1", "--folded-set", "F1", "--refuted-set", "none"]
            prefix = [sys.executable, *(["-O"] if optimized else [])]
            if not transient:
                return subprocess.run([*prefix, *args], capture_output=True, text=True)
            shim = ("import runpy, sys\nfrom pathlib import Path\noriginal = Path.read_bytes\nseen = []\n"
                    "def read_bytes(path):\n"
                    f"    if path == Path({str(snap)!r}) and not seen:\n"
                    "        seen.append(1)\n        raise OSError('transient-snapshot-read')\n"
                    "    return original(path)\nPath.read_bytes = read_bytes\n"
                    f"sys.argv = {args!r}\nrunpy.run_path({GRAPHCTL!r}, run_name='__main__')\n")
            return subprocess.run([*prefix, "-c", shim], capture_output=True, text=True)
        snap.write_bytes((text + "\n").encode("utf-8"))
        first = call("first")
        check(f"快照IO/{optimized}:首次暫時失敗當場拒收並定位IO",
              first.returncode == 2 and "--snapshot" in first.stderr
              and "transient-snapshot-read" in first.stderr and "UTF" not in first.stderr,
              first.stdout + first.stderr)
        check(f"快照IO/{optimized}:首次不建成功帳",
              not ledger.exists() and "✓" not in first.stdout, first.stdout + first.stderr)
        seed = call("valid-seed", transient=False)
        check(f"快照IO/{optimized}:正常讀取合法材料確實落帳",
              seed.returncode == 0 and ledger.exists(), seed.stdout + seed.stderr)
        if seed.returncode != 0 or not ledger.exists():
            continue
        for label, data in (("valid", (text + "\n").encode("utf-8")),
                            ("invalid-encoding", b"\xff\xfe"),
                            ("unmatched", "這份材料沒有報告所引用的那一段原文。\n".encode("utf-8"))):
            snap.write_bytes(data)
            before = ledger.read_bytes()
            result = call(label)
            check(f"快照IO/{optimized}/{label}:暫時失敗當場rc2不誤診",
                  result.returncode == 2 and "--snapshot" in result.stderr
                  and "transient-snapshot-read" in result.stderr and "UTF" not in result.stderr,
                  result.stdout + result.stderr)
            check(f"快照IO/{optimized}/{label}:無traceback或成功訊息",
                  "Traceback" not in result.stderr and "✓" not in result.stdout,
                  result.stdout + result.stderr)
            check(f"快照IO/{optimized}/{label}:成功帳逐位元不變",
                  ledger.read_bytes() == before, result.stdout + result.stderr)


def t_canary_carrier_invalid_report_encoding():
    """載體報告不能以替換字元掩蓋非法 UTF-8，寫側與讀側要驗同一份資料。"""
    import json as _j
    for optimized in (False, True):
        v = mkvault()
        snap = v / "Projects" / "snapshot.patch"
        snap.write_text("這是凍結材料裡可以核對的一整段文字\n", encoding="utf-8")
        report = v / "Projects" / "report.md"
        good = ("severity: minor\n## F1\nseverity: minor\n"
                "引句:「這是凍結材料裡可以核對的一整段文字」\n").encode("utf-8")
        report.write_bytes(good + b"\xff\n")
        prefix = [sys.executable, *(["-O"] if optimized else []), GRAPHCTL,
                  "--vault", str(v), "canary", "record", "none", "--auditor", "通才-codex",
                  "--report", str(report), "--snapshot", str(snap), "--round", "r1",
                  "--severity", "minor", "--findings", "1"]
        # 非載體沿既有替換讀取：不是這次載體一致性守衛的範圍。
        seed = subprocess.run([*prefix, "--loop", f"code-zq-encoding-seed-{_M1U}"],
                              capture_output=True, text=True)
        check(f"報告編碼/{optimized} 前置：非載體既有行為", seed.returncode == 0, seed.stderr[-200:])
        ledger = v.parent / ".canary-log.jsonl"
        before = ledger.read_bytes()
        last = _j.loads(before.decode("utf-8").splitlines()[-1])
        check(f"報告編碼/{optimized} 前置：報告確經解析", last.get("reported") == 1, str(last)[-200:])
        result = subprocess.run([*prefix, "--loop", f"code-zq-encoding-{_M1U}",
                                 "--findings-set", "F1", "--folded-set", "F1", "--refuted-set", "none"],
                                capture_output=True, text=True)
        check(f"報告編碼/{optimized} rc2、定位報告與編碼", result.returncode == 2
              and "--report" in result.stderr and "utf-8" in result.stderr.lower(), result.stderr[-200:])
        check(f"報告編碼/{optimized} 沒有假成功或 traceback", "✓" not in result.stdout
              and "Traceback" not in result.stderr, result.stdout[-150:] + result.stderr[-150:])
        check(f"報告編碼/{optimized} canary 帳逐位元不變", ledger.read_bytes() == before, "")


def t_canary_carrier_evidence_changes_before_hash():
    """驗引句與落帳指紋不得混用不同版本；可控替換確實發生在 hash 讀取前。"""
    import ast as _ast
    import contextlib as _ctx
    import io as _io
    lm = _load_lumos_inproc()
    tree = _ast.parse(Path(GRAPHCTL).read_text(encoding="utf-8"))
    function = next(n for n in tree.body if isinstance(n, _ast.FunctionDef) and n.name == "cmd_canary")
    for optimized in (0, 1):
        for target in ("report", "snapshot"):
            v = mkvault()
            snap = v / "Projects" / "snapshot.patch"
            report = v / "Projects" / "report.md"
            snap.write_text("這是凍結材料裡可以核對的一整段文字\n", encoding="utf-8")
            report.write_text("severity: minor\n## F1\nseverity: minor\n"
                              "引句:「這是凍結材料裡可以核對的一整段文字」\n", encoding="utf-8")
            kwargs = dict(round_id="r1", auditor="通才-codex", severity="minor", findings=1,
                          report=str(report), snapshot=str(snap))
            with _ctx.redirect_stdout(_io.StringIO()), _ctx.redirect_stderr(_io.StringIO()):
                seed_rc = lm.cmd_canary(lm.Env(v), "none", loop="code-zq-race-seed", **kwargs)
            check(f"換檔/{optimized}/{target} 前置：合法材料可記帳", seed_rc == 0, str(seed_rc))
            ledger = v.parent / ".canary-log.jsonl"
            before = ledger.read_bytes()
            changing = report if target == "report" else snap
            changed = []
            original_hash = lm._sha256_file
            def mutate_then_hash(path, changing=changing, target=target, changed=changed,
                                 original_hash=original_hash):
                if Path(path) == changing and not changed:
                    content = ("severity: minor\n## F1\nseverity: minor\n零引句新報告。\n"
                               if target == "report" else "另外一個程序已換掉快照內容。\n")
                    changing.write_text(content, encoding="utf-8")
                    changed.append(str(changing))
                return original_hash(path)
            namespace = dict(lm.__dict__)
            namespace["_sha256_file"] = mutate_then_hash
            exec(compile(_ast.Module(body=[function], type_ignores=[]), GRAPHCTL, "exec",
                         optimize=optimized), namespace)
            out, err = _io.StringIO(), _io.StringIO()
            with _ctx.redirect_stdout(out), _ctx.redirect_stderr(err):
                rc = namespace["cmd_canary"](lm.Env(v), "none", loop="code-zq-race",
                                             findings_set="F1", folded_set="F1", refuted_set="none", **kwargs)
            check(f"換檔/{optimized}/{target} 前置：確在 hash 讀取前替換", changed == [str(changing)], str(changed))
            check(f"換檔/{optimized}/{target} rc2 且定位材料變動", rc == 2 and "變動" in err.getvalue()
                  and f"--{target}" in err.getvalue(), f"rc={rc} {err.getvalue()[-200:]}")
            check(f"換檔/{optimized}/{target} 不印成功、不 traceback", "✓" not in out.getvalue()
                  and "Traceback" not in err.getvalue(), out.getvalue()[-150:] + err.getvalue()[-150:])
            check(f"換檔/{optimized}/{target} canary 帳逐位元不變", ledger.read_bytes() == before, "")


def t_canary_record_disposal_fields_optional():
    """[T1 相容雙讀](spec:Projects/design-loop重設計 六;plan:同名_實作計畫 T1)

    record 新增六個★選配★欄(--report/--snapshot/--findings-set/--folded-set/
    --accepted-set/--accept-reason)。鐵則:★全部不給=行為與今日完全相同★——
    這是「相容雙讀先行」的第①包,任何中間版本不得打壞現行 design/code-loop 呼叫。

    寫側驗證(給了才驗,違反 rc2):
      folded∩accepted=∅ ∧ folded∪accepted==findings_set(集合核對,非總數——
      r1 Codex:只核總數可被重複計數/虛構項配平);accepted 逐 id 附非空理由;
      severity==blocker ⇒ accepted 必空(d1);report/snapshot 檔案存在且非空。

    還原翻紅釘:把「聯集==findings_set」檢查還原掉 → 「缺 id 未處置必 rc2」翻紅。"""
    import json as _j
    v = mkvault()
    lid = f"dsp-{_M1U}"
    rpt = v / "Projects" / "rpt.md"
    # 引句要夠長才過得了引句下限(短引句在閘那邊本來就算錨不到;2026-09-06 載體全錨檢查
    # 往前挪到記帳端之後,這份假資料的三字元引句會被擋,改成像樣的長度)
    rpt.write_text("severity: minor\nseverity: minor\nx\nseverity: minor\ny\n引句：「這是被審文件裡的一整句話 拿來當錨點」\n", encoding="utf-8")
    snap = v / "Projects" / "snap.md"
    snap.write_text("凍結快照 這是被審文件裡的一整句話 拿來當錨點 後面還有別的\n", encoding="utf-8")

    # ★相容鐵則★:零新參的舊呼叫 rc0,且記錄裡無任何新鍵
    # 不帶輪次的舊呼叫記在另一個編號:同一個編號之後要記帶輪次的處置帳,混用會被寫側擋(記帳與迴圈工具小修_計劃 d1)
    run(v, "canary", "record", "caught", "--report", str(rpt), "--loop", lid + "-legacy", "--severity", "minor",
        "--findings", "2", "--auditor", "s1", expect_rc=0)
    log = (v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").strip().splitlines()
    last = _j.loads(log[-1])
    check("★T1 六欄不給不寫★(2026-08-26 起 report 為審查席必附,不在此列)",
          not any(k in last for k in ("snapshot_path", "findings_set",
                                      "folded_set", "accepted_set", "accept_reasons")), str(last)[:200])

    # 完整合法寫入:全欄落帳且 sha256 可重算
    r1 = run(v, "canary", "record", "caught", "--loop", lid, "--round", "r1", "--severity", "major",
             "--auditor", "s1", "--report", str(rpt), "--snapshot", str(snap),
             "--findings-set", "a,b,c", "--refuted-set", "none", "--folded-set", "a,b", "--accepted-set", "c",
             "--accept-reason", "c=文件精度級,成本不值", expect_rc=0)
    last = _j.loads((v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").strip().splitlines()[-1])
    check("★前置★ 現場成立:六欄全落帳", last.get("findings_set") == ["a", "b", "c"]
          and last.get("folded_set") == ["a", "b"] and last.get("accepted_set") == ["c"]
          and last.get("accept_reasons", {}).get("c") and last.get("report_sha256")
          and last.get("snapshot_sha256"), str(last)[:300])
    check("sha256 可重算(留痕的最低資格)", last["report_sha256"] == _sha256_of(rpt), "")

    # 機械核對逐條 rc2
    bad = [
        # ★b 的理由給齊,讓「缺 b 未處置」成為唯一能 rc2 的路——否則聯集檢查被拔掉時
        # 理由檢查會代打,翻紅釘假紅(2026-08-04 第一版就中了這型:斷言測的不是它宣稱的那條)
        (["--findings-set", "a,b,c", "--refuted-set", "none", "--folded-set", "a", "--accepted-set", "c",
          "--accept-reason", "c=有理由"],
         "★缺 b 未處置(聯集≠全集)必 rc2★"),
        (["--findings-set", "a,b", "--refuted-set", "none", "--folded-set", "a,b", "--accepted-set", "b"],
         "folded∩accepted 非空必 rc2"),
        (["--findings-set", "a", "--refuted-set", "none", "--folded-set", "a", "--accepted-set", "",
          "--accept-reason", "x=y"], "理由鍵集合≠accepted_set 必 rc2"),
        (["--findings-set", "a,a", "--refuted-set", "none", "--folded-set", "a,a"], "findings_set 重複 id 必 rc2"),
    ]
    for extra, name in bad:
        rr = run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid, "--round", "r1", "--severity", "minor",
                 "--auditor", "s1", *extra)
        check(name, rr.returncode == 2, f"rc={rr.returncode} {rr.stderr[:120]}")
    # accepted 有 id 但沒給理由
    rr = run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid, "--round", "r1", "--severity", "minor",
             "--auditor", "s1", "--findings-set", "a,b", "--refuted-set", "none", "--folded-set", "a", "--accepted-set", "b")
    check("accepted 無理由必 rc2(空殼放行擋在寫側)", rr.returncode == 2, rr.stderr[:120])
    # d1:blocker 不得 accepted
    rr = run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid, "--round", "r1", "--severity", "blocker",
             "--auditor", "s1", "--findings-set", "a", "--refuted-set", "none", "--folded-set", "", "--accepted-set", "a",
             "--accept-reason", "a=想放行")
    check("★d1:blocker 輪 accepted 非空必 rc2★", rr.returncode == 2, rr.stderr[:120])
    # 留痕檔不存在
    rr = run(v, "canary", "record", "caught", "--loop", lid, "--severity", "minor",
             "--auditor", "s1", "--report", str(v / "nope.md"))
    check("--report 指向不存在檔必 rc2", rr.returncode == 2, rr.stderr[:120])
    # blocker+全折(accepted 空)合法——d1 只擋 accepted,不擋折
    # (T6 生效後:本 loop 已定錨,須帶留痕——正確行為,非誤傷)
    run(v, "canary", "record", "caught", "--loop", lid, "--round", "r1", "--severity", "blocker",
        "--auditor", "s1", "--findings-set", "a", "--refuted-set", "none", "--folded-set", "a",
        "--report", str(rpt), "--snapshot", str(snap), expect_rc=0)


def t_loop_next_legacy_emits_a_command_that_actually_runs():
    """★工具吐給你的指令必須跑得動——不然它會教出錯誤的習慣★(2026-08-04)

    `loop next` 的 `record_cmd` 是「複製貼上用」的模板。但它原本無條件吐
    `--tier {eff_tier}`,而 `legacy` ★不在 `--tier` 的 choices 裡★(只有
    light/standard/high)——所以 legacy loop 拿到的是一條 argparse 當場擋掉的指令。

    ★為什麼這比「一條壞指令」嚴重★:碰到 rc2 之後最自然的修復是「把 --tier 拿掉
    再跑」。拿掉就記不上定錨 → 下一輪 next 又推成 legacy → 又吐一條跑不動的指令。
    ★這個 bug 自己維持自己★。2026-08 三個走循序的 loop 全數 `tier=None`,即此循環
    的產物;其中 code-slim-python 吃到 legacy 的 cap 6(standard 是 3)才被逼停。

    ★驗行為(不是驗字串)★:把 next 吐的 record_cmd 佔位符填掉、★真的跑一次★,
    必須 rc0。字串斷言只證「長得對」,真跑才證「用得了」。
    同時驗 light/standard 仍照舊帶 --tier(修法不得誤傷可宣告的三檔)。"""
    import json as _j
    v = mkvault()
    spec = v / "Projects" / "lgspec.md"
    spec.write_text("legacy tier spec\n", encoding="utf-8")
    h = _sha256_of(spec)
    lid = f"lg-{_M1U}"

    # 造一筆 legacy 格式舊帳(不帶 --round、不帶 --tier)→ next 會推導成 legacy
    run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid, "--severity", "clean",
        "--findings", "0", "--auditor", "s1", expect_rc=0)
    r = run(v, "loop", "next", lid, "--json", "--spec", str(spec), "--repo", str(v.parent))
    d = _j.loads(r.stdout)
    check("★前置★ 現場成立:確實走到 legacy 推導路徑且吐得出模板(不是別的 tier / 別的 phase 混過去)",
          d["tier"] == "legacy" and d["phase"] == "plant-canary", r.stdout[:300])

    cmd = d["record_cmd"]
    check("★legacy 不得出現在 record_cmd 的 --tier★(它不是可宣告值)",
          "--tier legacy" not in cmd, cmd)

    # ★真跑★:填掉佔位符,原樣執行 next 給的指令
    filled = (cmd.replace("caught|missed", "caught").replace("<席>", "s2")
                 .replace("<s>", "clean").replace("<M>", "0")
                 .replace("<席報告.md>", _sevrep(v.parent))
                 .replace("<計劃節點.md>", str(spec)).replace("<sha256>", h)
                 .replace("<這一席審的那份凍結材料(拆包審時填該席那一包)>", str(spec)).replace("<這一席那份的行數(拆包審時填該席那一包)>", "10"))
    argv = filled.split()
    check("★前置★ 現場成立:填完沒有殘留佔位符(不然是在跑別的東西)",
          "<" not in filled and argv[0] == "lumos", filled)
    rr = run(v, *argv[1:])
    check("★next 吐的指令必須真的跑得動★(rc0)", rr.returncode == 0,
          f"rc={rr.returncode} cmd={filled}\n{rr.stderr[:300]}")

    check("★要講清楚這個 loop 補標不了、得開新 id★(不然人只會困惑地把旗標拿掉)",
          "開新的審查編號" in d.get("tier_hint", "") and "最多 6 輪" in d.get("tier_hint", ""),
          d.get("tier_hint", "")[:200])

    # 反誤傷:可宣告的三檔仍須照舊帶 --tier
    ds = _j.loads(run(v, "loop", "next", f"lgs-{_M1U}", "--tier", "standard", "--orchestrator", "claude", "--json").stdout)
    check("★standard 仍要帶 --tier★(修法不得誤傷可宣告檔)",
          "--tier standard" in ds["record_cmd"] and "tier_hint" not in ds, ds["record_cmd"])
    dli = _j.loads(run(v, "loop", "next", f"lgl-{_M1U}", "--tier", "light", "--orchestrator", "claude", "--json").stdout)
    check("★light 仍要帶 --tier★", "--tier light" in dli["record_cmd"], dli["record_cmd"])


def t_need_src_guards_cannot_silently_disable_coverage():
    """★守衛的失敗模式是「放行」,所以它自己壞掉時必須大聲★(2026-08-02)

    `_need_src(...)` 讓「來源 repo 專用」的測試在消費端專案乾淨 skip 而非假紅
    （實測 Landmark:vendored 套件更新後 91 紅,全是來源專用產物缺席；本機制後
    降為 0 紅 / 61 skip）。但它有一個致命的失敗模式：★如果來源 repo 自己少了
    某個產物，這些測試會在來源端也靜默 skip，覆蓋率無聲蒸發★——而 skip 不會
    讓任何閘翻紅。

    這正是昨天那條教訓的同型：**失敗模式是放行的守衛，壞掉時不會有人知道**。

    ★驗行為★：直接掃本檔案裡所有 `_need_src("...")` 的實際呼叫參數，逐一斷言
    那個路徑在來源 repo 真的存在。★自我維護★——之後任何人新增一處 `_need_src`，
    這條測試自動涵蓋它，不需要維護第二份清單。

    ★此測試自己也必須在來源 repo 跑得到★（不加 `_need_src` 守門，否則它會在
    消費端 skip 掉，而那正是它該沉默的地方——消費端本來就缺那些產物）。"""
    import re as _re9
    repo = Path(GRAPHCTL).resolve().parent.parent
    src = Path(__file__).resolve().read_text(encoding="utf-8")
    # ★只認「獨立成行的呼叫」★——不然 docstring 裡提到的 `_need_src(...)` 也會被掃進來
    # (第一版就踩到,掃出一個叫 '...' 的假路徑)。
    rels = sorted(set(_re9.findall(r'^\s*_need_src\(\s*"([^"]+)"', src, _re9.M)))
    check("★前置★ 掃得到 _need_src 的呼叫參數(掃不到=這條測試自己失效了)",
          len(rels) >= 5, f"只掃到 {rels}")
    if not (repo / "skills" / "lumos-project-notes").is_dir():
        # 消費端:那些產物本來就沒有,此測試無意義(且下面的斷言必假)
        raise _SrcOnly("需要來源 repo(本測試只在來源端有意義)")
    missing = [r for r in rels if not (repo / r).exists()]
    check("★來源 repo 必須擁有每一個被守門的產物★"
          "(缺了 → 對應測試會在來源端也靜默 skip、覆蓋無聲蒸發)",
          not missing, f"缺: {missing}")


def t_canary_scope_lines_records_review_size():
    """★把缺的變數記下來★(2026-08-02):canary 抓到只證審查員醒著,但外部實測指出
    ★東西越多越抓不到★是最主導的因素(arXiv 2606.15689:抓得到合成缺陷不可靠地
    預測抓得到真實缺陷,且 diff 大小是主導混淆變數)。本專案十輪 code-loop 的 diff
    從 332 到 2770 行——★在帳上長得一模一樣★,等於無法回答「小 diff 上的 caught
    是不是灌水」。

    這一欄★不進任何 gate、不改任何判定★,純 telemetry;目的只有一個:讓
    「caught 率 vs 被審規模」這個問題日後答得出來。

    ★驗行為★:①給了就要真的寫進帳本(不是只收下不存)②不給時★整個鍵不存在★
    (同 --findings 慣例,不寫 null 汙染舊帳)③負數擋下 rc2 ④★不影響 gate★——
    帶不帶這欄,loop status 的判定必須完全一樣。"""
    import json as _j
    v = mkvault()
    spec = v / "Projects" / "scopespec.md"
    spec.write_text("scope spec\n", encoding="utf-8")
    h = _sha256_of(spec)
    log = v.parent / ".canary-log.jsonl"
    lid = f"sc-{_M1U}"

    run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid, "--severity", "clean", "--findings", "0",
        "--auditor", "s1", "--reviewed", h, "--spec", str(spec), "--scope-lines", "2770", expect_rc=0)
    rows = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
    mine = [r for r in rows if r.get("loop") == lid]
    check("★給了就要真的寫進帳本★", mine and mine[-1].get("scope_lines") == 2770,
          str(mine[-1] if mine else None)[:200])

    run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid, "--severity", "clean", "--findings", "0",
        "--auditor", "s2", "--reviewed", h, "--spec", str(spec), expect_rc=0)
    rows = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
    mine = [r for r in rows if r.get("loop") == lid]
    check("★不給時整個鍵不存在(不寫 null 汙染舊帳)★", "scope_lines" not in mine[-1],
          str(mine[-1])[:200])

    r = run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid, "--severity", "clean", "--findings", "0",
            "--auditor", "s3", "--reviewed", h, "--spec", str(spec), "--scope-lines", "-1")
    check("★負數擋下 rc2★", r.returncode == 2, r.stderr[-150:])

    # ★不影響 gate★:帶與不帶這欄,收斂判定必須一樣
    g = run(v, "loop", "status", lid, "--need", "2", "--gate", "--spec", str(spec),
            "--repo", str(v.parent))
    lid2 = f"sc2-{_M1U}"
    for a in ("t1", "t2"):
        run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid2, "--severity", "clean", "--findings", "0",
            "--auditor", a, "--reviewed", h, "--spec", str(spec), expect_rc=0)
    g2 = run(v, "loop", "status", lid2, "--need", "2", "--gate", "--spec", str(spec),
             "--repo", str(v.parent))
    check("★純 telemetry:帶了 scope-lines 的 loop 與沒帶的,gate 判定一致★",
          g.returncode == g2.returncode, f"帶={g.returncode} 沒帶={g2.returncode}")

    # ── 軟上限:超標要在帳上留記號並喊出來 ──
    lid3 = f"sc4-{_M1U}"
    ro = run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid3, "--severity", "clean", "--findings", "0",
             "--auditor", "big", "--reviewed", h, "--spec", str(spec), "--scope-lines", "2778", expect_rc=0)
    rows = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
    big = [r for r in rows if r.get("loop") == lid3][-1]
    check("★超過軟上限要在帳上標 scope_oversize★(caught 是弱證據,事後查得到)",
          big.get("scope_oversize") is True, str(big)[:200])
    check("★而且要當場喊出來★(只記不喊等於沒人知道)",
          "scope_oversize" in ro.stderr or "軟上限" in ro.stderr, ro.stderr[-200:])
    check("★仍然照常留痕 rc0★(軟上限不擋——輪已經跑完,擋也來不及)",
          ro.returncode == 0, ro.stderr[-150:])

    # ★反誤傷★:沒超標不得標記、不得喊
    lid4 = f"sc5-{_M1U}"
    rs = run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", lid4, "--severity", "clean", "--findings", "0",
             "--auditor", "small", "--reviewed", h, "--spec", str(spec), "--scope-lines", "415", expect_rc=0)
    rows = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
    small = [r for r in rows if r.get("loop") == lid4][-1]
    check("★沒超標不得標記(反誤傷)★", "scope_oversize" not in small, str(small)[:200])
    check("★沒超標不得喊(反噪音)★", "軟上限" not in rs.stderr, rs.stderr[-150:])

    # ★預防端★:警告要在派工之前出現,不是記帳之後才喊
    nx0 = run(v, "loop", "next", f"sc6-{_M1U}", "--tier", "standard", "--orchestrator", "claude")
    check("★loop next 必須在派工前就給量尺★(記帳時才喊已經來不及,輪跑完了)",
          "scope_cap" in nx0.stdout and "wc -l" in nx0.stdout, nx0.stdout[-300:])

    # loop next 的模板要提到它(否則沒人知道有這欄——cluster 帳 316:1 的教訓)
    nx = run(v, "loop", "next", f"sc3-{_M1U}", "--tier", "standard", "--orchestrator", "claude")
    check("★loop next 的記帳模板必須帶上它(不然沒人會用)★",
          "--scope-lines" in nx.stdout, nx.stdout[-300:])


def t_m1_loop_next():
    """M1包 #1 loop next:零記錄 rc2/plant-canary/tier 定錨+衝突 rc2/escalate/gate-pending/converged/cap/min-seats/json。"""
    print("t_m1_loop_next")
    import json as _j, subprocess as _sp
    v = mkvault()
    # 治理帳要 git HEAD 才寫(#6 的結案帳用):給 vault 上層一個 commit
    _sp.run(["git", "init", "-q", str(v.parent)]); _sp.run(["git", "-C", str(v.parent), "add", "-A"])
    _sp.run(["git", "-C", str(v.parent), "-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "init"])
    spec = v / "Projects" / "nspec.md"
    spec.write_text("next spec\n", encoding="utf-8")
    h = _sha256_of(spec)
    # 零記錄無 --tier rc2
    r = run(v, "loop", "next", f"nx-{_M1U}", "--orchestrator", "claude")   # S2:orchestrator 守衛先擋,補旗標才測得到 tier 守衛(code-codex-s2 r1 外家 #5)
    check("零記錄無 tier rc2", r.returncode == 2)
    # 零記錄+tier light → plant-canary N=1
    r = run(v, "loop", "next", f"nx-{_M1U}", "--tier", "light", "--orchestrator", "claude", "--json")
    d = _j.loads(r.stdout)
    check("零記錄 plant-canary N=1", d["phase"] == "plant-canary" and d["round"] == 1 and r.returncode == 1)
    check("light width/cap 映射", d["width"] == 1 and d["cap"] == 2)
    # tier 定錨:record 帶 --tier light → next 無 --tier 讀定錨(帶 auditor:空席不計已生效)
    run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", f"nx-{_M1U}", "--severity", "clean", "--findings", "0",
        "--auditor", "solo", "--reviewed", h, "--spec", str(spec), "--tier", "light", expect_rc=0)
    r = run(v, "loop", "next", f"nx-{_M1U}", "--json", "--spec", str(spec), "--repo", str(v.parent))
    d = _j.loads(r.stdout)
    check("tier 定錨讀取", d["tier"] == "light")
    check("light 收斂 → converged rc0", d["phase"] == "converged" and r.returncode == 0)
    # 定錨衝突 rc2
    r = run(v, "loop", "next", f"nx-{_M1U}", "--tier", "standard", "--orchestrator", "claude")
    check("tier 衝突 rc2", r.returncode == 2)
    # 資訊不足 → gate-pending(先於 cap)
    r = run(v, "loop", "next", f"nx-{_M1U}", "--json")
    d = _j.loads(r.stdout)
    check("缺 --spec → gate-pending rc1", d["phase"] == "gate-pending" and r.returncode == 1)
    # escalate:light ratchet 最先短路
    run(v, "canary", "record", "caught", "--loop", f"nx2-{_M1U}", "--severity", "major", "--findings", "2",
        "--reviewed", h, "--spec", str(spec), "--tier", "light", expect_rc=0)
    r = run(v, "loop", "next", f"nx2-{_M1U}", "--json", "--spec", str(spec), "--repo", str(v.parent))
    d = _j.loads(r.stdout)
    check("light ratchet → escalate", d["phase"] == "escalate" and r.returncode == 1)
    # cap-reached:light cap=2 兩輪未收斂(資訊充分)
    run(v, "canary", "record", "missed", "--loop", f"nx3-{_M1U}", "--tier", "light", expect_rc=0)
    run(v, "canary", "record", "missed", "--loop", f"nx3-{_M1U}", expect_rc=0)
    r = run(v, "loop", "next", f"nx3-{_M1U}", "--json", "--spec", str(spec), "--repo", str(v.parent))
    d = _j.loads(r.stdout)
    check("cap-reached", d["phase"] == "cap-reached" and r.returncode == 1)
    # ── 工具鏈補強十件 #6:結案方式進治理帳,gov --stats 算人裁放行率 ──
    glog = v.parent / ".governance-log.jsonl"
    gtxt = glog.read_text(encoding="utf-8") if glog.exists() else ""
    check("★converged 進治理帳(gate=design-loop)★", '"gate": "design-loop"' in gtxt and '"converged"' in gtxt and f"nx-{_M1U}" in gtxt, gtxt[-400:])
    check("★cap-reached 進治理帳★", '"cap-reached"' in gtxt and f"nx3-{_M1U}" in gtxt, gtxt[-400:])
    rg = run(v, "gov", "--stats", "--since", "9999")
    check("★gov --stats 印人裁放行:1 個過關、1 個達上限★", "閘過了 1 個" in rg.stdout and "人裁放行) 1 個" in rg.stdout, rg.stdout)
    # min-seats:panel 同席灌筆不計——high 定錨,同一 auditor 5 筆
    for i in range(5):
        run(v, "canary", "record", "caught", "--loop", f"nx4-{_M1U}", "--round", "r1", "--auditor", "same",
            "--severity", "clean", "--findings", "0", "--capture-counts", "1",
            "--reviewed", h, "--spec", str(spec), "--tier", "high",
            "--report", _sevrep(v.parent), expect_rc=0)
    r = run(v, "loop", "status", f"nx4-{_M1U}", "--panel", "--min-seats", "5", "--spec", str(spec), "--repo", str(v.parent))
    check("同席灌筆 min-seats FAIL", r.returncode == 1 and "席" in r.stdout)


def t_m1_codeloop_r1_fixes():
    """code-loop 補審 r1 折入(loop機械脊椎M1包):cluster 路徑轉發/tier-格式衝突 rc2/
    light 空 auditor 不計席/light 席數委派/panel+light 成本區。"""
    print("t_m1_codeloop_r1_fixes")
    v = mkvault()
    spec = v / "Projects" / "cspec.md"
    spec.write_text("c spec\n", encoding="utf-8")
    h = _sha256_of(spec)
    # 1. cluster 模式不得繞過 min-seats/G3:同席 2 筆 caught+clusters 無 disputed,無 hash
    for i in range(2):
        run(v, "canary", "record", "caught", "--loop", f"cl-{_M1U}", "--round", "r1", "--auditor", "same",
            "--severity", "clean", "--findings", "0", "--report", _sevrep(v.parent),
            *(["--clusters", "x=resolved"] if i == 0 else []), expect_rc=0)
    r = run(v, "loop", "status", f"cl-{_M1U}", "--panel", "--min-seats", "5", "--spec", str(spec), "--repo", str(v.parent))
    check("cluster 模式 min-seats/G3 不被繞過", r.returncode == 1 and ("席" in r.stdout or "hash" in r.stdout or "綁" in r.stdout), r.stdout[-200:])
    # 2. tier=high 定錨但記錄為 legacy 格式(漏 --round) → next rc2 格式衝突,不得走鬆閘。
    #    寫側現在就擋這種記法(記帳與迴圈工具小修_計劃 輪次一條規則),所以舊帳列直接寫進帳檔,只測讀側對舊帳的守衛
    r = run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", f"tf-{_M1U}", "--severity", "clean", "--findings", "0",
            "--reviewed", h, "--spec", str(spec), "--tier", "high")
    check("寫側:high 漏 --round 記不進", r.returncode == 2 and "--round" in r.stderr, f"rc={r.returncode} {r.stderr[-200:]}")
    import json as _j
    with open(v.parent / ".canary-log.jsonl", "a", encoding="utf-8") as f:
        f.write(_j.dumps({"ts": "2026-10-01T10:00:00+08:00", "kind": "caught", "auditor": "", "token": f"CANARY-tf{_M1U}", "note": "",
                          "loop": f"tf-{_M1U}", "severity": "clean", "findings": 0, "reviewed_sha256": h,
                          "spec_path": "Projects/cspec.md", "tier": "high"}, ensure_ascii=False) + "\n")
    r = run(v, "loop", "next", f"tf-{_M1U}", "--spec", str(spec), "--repo", str(v.parent))
    check("high 定錨+legacy 格式 → rc2(講輪次對不上)", r.returncode == 2 and "--round" in (r.stdout + r.stderr), f"rc={r.returncode} {(r.stdout + r.stderr)[-200:]}")
    # 3. light 空 auditor 不計席:無 --auditor 的 caught 乾淨輪,min-seats=1 應 FAIL
    run(v, "canary", "record", "caught", "--loop", f"la-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"la-{_M1U}", "--light", "--gate", "--min-seats", "1", "--spec", str(spec), "--repo", str(v.parent))
    check("light 空 auditor 不計席 FAIL", r.returncode == 1 and "席" in r.stdout, r.stdout[-150:])
    # 4. next 對 light 委派 min_seats=1:同上帳但經 next(缺 auditor 不得 converged)
    run(v, "canary", "record", "caught", "--loop", f"ln-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), "--tier", "light", expect_rc=0)
    r = run(v, "loop", "next", f"ln-{_M1U}", "--json", "--spec", str(spec), "--repo", str(v.parent))
    d = _j.loads(r.stdout)
    check("next light 委派席數(缺 auditor 不 converged)", d["phase"] != "converged", r.stdout[:150])
    # 5. panel 與 light 路徑也印成本區
    for a in ("p1", "p2"):
        run(v, "canary", "record", "caught", "--loop", f"cp-{_M1U}", "--round", "r1", "--auditor", a,
            "--severity", "clean", "--findings", "0", "--tokens", "100", "--report", _sevrep(v.parent),
            *(["--capture-counts", "1"] if a == "p1" else []), expect_rc=0)
    r = run(v, "loop", "status", f"cp-{_M1U}", "--panel")
    check("panel 路徑印成本區", "成本" in r.stdout, r.stdout[-150:])
    run(v, "canary", "record", "caught", "--report", _sevrep(v.parent), "--loop", f"cli-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), "--auditor", "solo", "--tokens", "50", expect_rc=0)
    r = run(v, "loop", "status", f"cli-{_M1U}", "--light", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("light 路徑印成本區", "成本" in r.stdout, r.stdout[-150:])


def t_m1_codeloop_r2_fixes():
    """code-loop 補審 r2 折入:G3 OSError rc2 對稱/next 損壞守衛/legacy gate min-seats。"""
    print("t_m1_codeloop_r2_fixes")
    v = mkvault()
    spec = v / "Projects" / "r2spec.md"
    spec.write_text("r2\n", encoding="utf-8")
    h = _sha256_of(spec)
    # 1. panel/light 對 --spec 不可讀 → rc2(非 rc1;與 legacy G1 對稱)
    run(v, "canary", "record", "caught", "--loop", f"os-{_M1U}", "--severity", "clean", "--findings", "0",
        "--auditor", "a1", "--report", _sevrep(v.parent), "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"os-{_M1U}", "--light", "--gate", "--spec", str(v / "Projects"), "--repo", str(v.parent))
    check("light --spec 目錄 rc2", r.returncode == 2, f"rc={r.returncode}")
    for a in ("a1", "a2"):
        run(v, "canary", "record", "caught", "--loop", f"osp-{_M1U}", "--round", "r1", "--auditor", a,
            "--severity", "clean", "--findings", "0", "--capture-counts", "1",
            "--reviewed", h, "--spec", str(spec), "--report", _sevrep(v.parent), expect_rc=0)
    r = run(v, "loop", "status", f"osp-{_M1U}", "--panel", "--spec", str(v / "Projects"), "--repo", str(v.parent))
    check("panel --spec 目錄 rc2", r.returncode == 2, f"rc={r.returncode}")
    # 2. next 缺 --spec 也要跑帳本損壞守衛:round r1→r2→r1 非連續
    for rid in ("r1", "r2", "r1"):
        run(v, "canary", "record", "caught", "--loop", f"cor-{_M1U}", "--round", rid, "--auditor", "x",
            "--severity", "clean", "--findings", "0", "--tier", "standard",
            "--report", _sevrep(v.parent), expect_rc=0)
    r = run(v, "loop", "next", f"cor-{_M1U}")
    check("next 損壞帳 rc2(缺 --spec 也擋)", r.returncode == 2, f"rc={r.returncode}")
    # 3. legacy gate 消費 --min-seats(無 auditor → 席數不足 FAIL)
    for i in range(2):
        run(v, "canary", "record", "caught", "--loop", f"lm-{_M1U}", "--severity", "clean", "--findings", "0",
            "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"lm-{_M1U}", "--need", "2", "--gate", "--min-seats", "1",
            "--spec", str(spec), "--repo", str(v.parent))
    check("legacy gate min-seats 生效", r.returncode == 1 and "席" in r.stdout, r.stdout[-150:])
    # r3 折入:逐輪驗非空(一有一空不得以聯集過)
    run(v, "canary", "record", "caught", "--report", _sevrep(v.parent, "minor", 1), "--loop", f"lw-{_M1U}", "--severity", "minor", "--findings", "1",
        "--auditor", "solo", "--reviewed", h, "--spec", str(spec), expect_rc=0)
    run(v, "canary", "record", "caught", "--loop", f"lw-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), expect_rc=0)   # 第二輪空席
    r = run(v, "loop", "status", f"lw-{_M1U}", "--need", "2", "--gate", "--min-seats", "1",
            "--spec", str(spec), "--repo", str(v.parent))
    check("legacy 一有一空逐輪驗 FAIL", r.returncode == 1 and "席" in r.stdout, r.stdout[-150:])
    # r3 折入:--min-seats 非正整數 rc2
    r = run(v, "loop", "status", f"lw-{_M1U}", "--need", "2", "--gate", "--min-seats", "-1",
            "--spec", str(spec), "--repo", str(v.parent))
    check("min-seats 負值 rc2", r.returncode == 2, f"rc={r.returncode}")


def t_show():
    """show 讀取入口(Projects/lumos-show讀取入口_計劃 八項):找到全文/找不到 rc2/--body-only/
    模糊名沿 env.find/唯讀(節點檔不變,usage-log 為預期副作用)/派發組迴歸/重開檔失敗 rc2 無
    traceback/無 frontmatter 檔 --body-only 印整檔。"""
    print("t_show")
    v = mkvault()
    write(v, "Systems/秀測試.md", "type: system\nstatus: done", "# 秀測試\nbody-內文-唯一標記\n")
    # 1. 找到 → rc0、含 frontmatter --- 與 body 標題行
    r = run(v, "show", "秀測試", expect_rc=0)
    check("show 找到 rc0 含 frontmatter", r.stdout.startswith("---") and "type: system" in r.stdout)
    check("show 含 body 標題行", "# 秀測試" in r.stdout and "body-內文-唯一標記" in r.stdout)
    # 2. 找不到 → stderr 訊息 + rc2
    r = run(v, "show", "不存在的節點名", expect_rc=2)
    check("show 找不到 rc2+stderr", "找不到叫" in r.stderr)
    # 3. --body-only → 無 frontmatter 鍵行、有 body
    r = run(v, "show", "秀測試", "--body-only", expect_rc=0)
    check("body-only 無 frontmatter 鍵行", "type: system" not in r.stdout and not r.stdout.startswith("---"))
    check("body-only 含 body", "body-內文-唯一標記" in r.stdout)
    # 4. 模糊名(同名多篇)沿 env.find:stderr 警告、取第一篇、rc0
    write(v, "Projects/秀測試.md", "type: project\nstatus: doing", "# 秀測試P\n")
    r = run(v, "show", "秀測試", expect_rc=0)
    check("模糊名沿 env.find(警告+取第一)", "同名筆記" in r.stderr and r.returncode == 0)
    # 5. 唯讀:節點檔內容不變(usage-log append 為預期副作用,不斷言其無)
    p = v / "Systems" / "秀測試.md"
    before = p.read_bytes()
    run(v, "show", "Systems/秀測試", expect_rc=0)
    check("唯讀:節點檔不變", p.read_bytes() == before)
    # 6. 派發組迴歸:context 照常
    r = run(v, "context", "Systems/秀測試", expect_rc=0)
    check("派發組迴歸 context 不受影響", "Systems/秀測試" in r.stdout)
    # 7. 重開檔失敗:vault 載入後檔案消失 → rc2 無 traceback
    #    (load_vault 在 CLI 進程內先掃;要模擬「解析成功但重開失敗」,用 symlink 指向不存在目標——
    #     rglob 掃得到、read_text 會炸;load_vault 容忍(lint 記讀檔失敗)但 rel 仍可解析)
    broken = v / "Systems" / "斷鏈.md"
    broken.symlink_to(v / "Systems" / "不存在的目標檔.md")
    r = run(v, "show", "斷鏈")
    check("重開檔失敗 rc2", r.returncode == 2, f"rc={r.returncode}")
    check("重開檔失敗 stderr 無 traceback", "讀不到" in r.stderr and "Traceback" not in r.stderr, r.stderr[:120])
    # 8. 無 frontmatter 檔 --body-only → 印整檔
    (v / "Systems" / "裸檔.md").write_bytes("# 裸檔標題\n純內文無fm\n".encode("utf-8"))
    r = run(v, "show", "裸檔", "--body-only", expect_rc=0)
    check("無 frontmatter --body-only 印整檔", "# 裸檔標題" in r.stdout and "純內文無fm" in r.stdout)


def t_docs_enumeration_drift():
    """文件裡的「手寫列舉/數字」對機械事實的漂移守衛(2026-07-29 使用者指出:
    有守衛的當場被咬住、沒守衛的全漏 → 把守衛面從命令數推廣到三類散落事實)。
    通則:凡文件宣稱一個可從碼機械推導的清單/數字,就該有一條這樣的測試。"""
    _need_src("skills/lumos-project-notes")
    import re as _re
    from pathlib import Path as _P
    root = _P(__file__).resolve().parent.parent
    src = (root / "scripts" / "lumos").read_text(encoding="utf-8")

    # ① 治理帳數:cmd_gov 實際 load() 幾支 vs 文件/docstring 宣稱
    _g0 = src.index("def cmd_gov(")
    gov_body = src[_g0:src.index("\ndef ", _g0 + 1)]   # 整個函式(原本寫死 6000 字,讀端轉換多幾行就把第 6 個 load 擠出去;修正關卡第0步推送前全套抓到)
    n_sources = len(_re.findall(r"^\s*load\(", gov_body, _re.M))
    zh = "零一二三四五六七八九十"
    claimed = set(_re.findall(r"彙整([一二三四五六七八九十])帳", src))
    claimed |= set(_re.findall(r"讀([一二三四五六七八九十])個本機 JSONL",
                               (root / "README.md").read_text(encoding="utf-8")))
    check("治理帳數:文件宣稱 vs cmd_gov 實際 load 數",
          claimed == {zh[n_sources]}, f"claim={claimed} actual={n_sources}({zh[n_sources]})")

    # ② guard kill verdict 值域:碼裡實際會寫出的 verdict vs reference.md 列舉
    kill_body = src[src.index("def cmd_guard_kill("):src.index("def cmd_guard_audit(")]
    # 抽取要涵蓋三元式:`verdict = "a" if c else "b"` 用舊 regex 只會抓到 "a",
    # 於是 killed_unattributed 整個從值域裡蒸發(2026-07-29:守衛的尺第二次被抓到在漂)。
    # 作法:先取所有 `verdict = <右式>` 整行,再把該行**全部**字串字面量收進來。
    verdicts = set()
    for rhs in _re.findall(r"^\s*verdict\s*=\s*(.+)$", kill_body, _re.M):
        verdicts |= set(_re.findall(r'"([a-z_]+)"', rhs))
    verdicts |= set(_re.findall(r'"verdict": "([a-z_]+)"', kill_body))
    ref = (root / "skills" / "lumos-project-notes" / "reference.md").read_text(encoding="utf-8")
    kill_sec = ref[ref.index("lumos guard kill-add"):ref.index("lumos guard kill-add") + 2000]
    missing = sorted(v for v in verdicts if v not in kill_sec)
    check("kill verdict 值域:碼有的 reference.md 都列了", not missing, f"未列: {missing}")
    # ②b **圖譜節點同受守衛**——只守 skill reference 的舊寫法,讓 Systems/guard-kill.md 一路留著
    # 舊六態與「timed_out 歸 killed」,造出「圖譜錯、code 對」的活例(2026-07-29 外審實錘)。
    gk = root / "docs" / "lumos-toolchain-knowledge" / "Systems" / "guard-kill.md"
    if gk.exists():
        gk_text = gk.read_text(encoding="utf-8")
        gk_missing = sorted(v for v in verdicts if v not in gk_text)
        check("kill verdict 值域:碼有的 Systems/guard-kill.md 都列了",
              not gk_missing, f"未列: {gk_missing}")
        # 態數宣稱也從碼推導(非硬編「七」):文件若寫「N態」而 N≠碼裡的 verdict 數即漂移。
        # 「舊六態」這種標明已作廢的歷史註記合法 → 負向預查排除「舊」。
        want = "零一二三四五六七八九十"[len(verdicts)]
        bad = sorted(set(_re.findall(r"(?<!舊)([一二三四五六七八九十])態", gk_text)) - {want})
        check(f"Systems/guard-kill.md 態數宣稱=碼實際({want}態)",
              not bad, f"文件另寫: {bad}態")

    # ③ Claude hook 生命週期對稱:註冊(HOOK_ENTRIES) ⟺ 複製白名單(_GLOBAL_CLAUDE_HOOKS)
    merge = (root / "scripts" / "merge-claude-settings.py").read_text(encoding="utf-8")
    registered = set(_re.findall(r'_hook_cmd\("([\w.-]+)"\)', merge))
    wl = _re.search(r"_GLOBAL_CLAUDE_HOOKS = \(([^)]*)\)", src)
    copied = set(_re.findall(r'"([\w.-]+)"', wl.group(1) if wl else ""))
    # **雙向**等價,不是單向包含:舊寫法只驗 registered ⊆ copied,「複製了卻沒註冊」的幽靈 hook
    # 照樣過(裝進機器、永不觸發、無人知道它死著)——2026-07-29 外審實錘。
    check("hook 生命週期對稱:註冊的都在複製白名單裡",
          registered <= copied, f"註冊未複製(會被 _prune_dangling 剪掉): {sorted(registered - copied)}")
    check("hook 生命週期對稱:複製白名單裡的都有註冊",
          copied <= registered, f"複製未註冊(幽靈 hook,永不觸發): {sorted(copied - registered)}")
    for name in sorted(registered | copied):
        check(f"hook 檔存在: {name}", (root / "scripts" / "hooks" / "claude" / name).exists(), "")


def _docs_command_count_claims(text):
    """文件裡宣稱頂層命令數的寫法 → 數字集合。2026-10-15 補「N 個指令的總目錄」(reference.md 介紹 commands/INDEX.md 那句,
    原本守衛認不到;Projects/筆記指令健檢與規格閘小修_計劃 S34)。"""
    import re as _re
    return set(_re.findall(r"(\d+) 個頂層命令", text)) | set(
        _re.findall(r"(\d+) top-level (?:commands|subcommands)", text)) | set(
        _re.findall(r"(\d+) 是頂層命令數", text)) | set(_re.findall(r"(\d+) 個指令的總目錄", text))


def t_docs_command_count():
    """文件宣稱的頂層命令數 vs argparse 實數(2026-07-29 外審實錘:ARCHITECTURE 曾停在 44)。"""
    _need_src("skills/lumos-project-notes")
    import re as _re
    from pathlib import Path as _P
    import subprocess as _sp
    root = _P(__file__).resolve().parent.parent
    # 真值取自 **argparse 自己**(`--help` 的 choices),不是對原始碼做 regex 近似:
    # 舊 regex 漏掉迴圈註冊的 links/backlinks,把真數 53 算成 51——**守衛的尺自己在漂**,
    # 於是三份文件寫 51 反而「全綠」(2026-07-29)。reference.md 早寫明「--help 為現行權威」。
    _h = _sp.run([sys.executable, str(root / "scripts" / "lumos"), "--help"],
                 capture_output=True, text=True, timeout=60).stdout
    _m = _re.search(r"\{([a-z0-9,\-]+)\}", _h)
    actual = len(set(_m.group(1).split(","))) if _m else 0
    check("命令數真值取自 --help choices(非原始碼 regex)", actual > 40, f"actual={actual}")
    # 掃**全部活文件**而非手維護清單——固定三檔的舊寫法正是 AGENTS.md(44)與
    # skills/…/reference.md(49)同時漂移卻全綠的原因(2026-07-29 外審實錘)。
    # 排除:外審歸檔(逐字歷史紀錄,不得回改)、圖譜(決策條目會引述當時數字)、.git。
    # golden/ 是凍結語料(過去 loop 的 spec 快照,replay 校準用),與外審歸檔同性質:歷史不得回改。
    # l4-audit/ 是自足性審計的逐節點證據(claims/verify 檔,2026-08-21 起),引用的數字是
    # 「審計當下或歷史快照」的值——同樣不得為了過守衛回改證據。
    # review-reports/ 是 loop 留痕(席報告/快照的 sha256 記在 canary 帳,disposal/panel 閘會重驗——
    # 回改=打斷留痕驗證,實錘:2026-08-25 62→63 時兩份舊席報告已被帳綁死);audits/ 是審計當下的證據快照。
    # 兩者與外審歸檔同性質:歷史不得回改,命令數過期屬正常。
    # ★.claude/worktrees/ 要排掉★(2026-09-08):同工作區裡開的 git worktree 會在 repo 目錄底下
    # 放一整份副本,rglob 掃到它就把「另一條分支的舊文件」當成本 repo 的文件來對帳,
    # 合併當下這支必紅——而那不是漂移,是掃錯地方。
    skip = ("governance/external-reviews/", "governance/golden/", "governance/l4-audit/",
            "governance/review-reports/", "governance/audits/",
            "-knowledge/", "/.git/", "node_modules/", ".claude/worktrees/")
    scanned = 0
    for p in sorted(root.rglob("*.md")):
        rel = p.relative_to(root).as_posix()
        if any(s.strip("/") in rel for s in skip):
            continue
        text = p.read_text(encoding="utf-8", errors="replace")
        nums = _docs_command_count_claims(text)  # 換措辭逃法實例:ARCHITECTURE 曾寫「53 是頂層命令數」躲過本守衛(2026-08-24);
        # ★第四次換措辭逃掉★(2026-09-12):英文版指令參考寫的是 `top-level subcommands`,
        # 少了 sub 就對不上,於是它停在 67、中文版寫 70、真值 70,三個數字並存沒人紅。
        # 這裡把 subcommands 也收進來;同時新增 t_docs_dont_hardcode_command_count,
        # 讓對外文件乾脆不准寫死這個數字——第四次靠補措辭續命,說明白名單這條路本身在漏。
        if not nums:
            continue
        scanned += 1
        check(f"{rel} 命令數與 argparse 同步",
              nums == {str(actual)}, f"claim={nums} actual={actual}")
    # 門檻從 4 降到 3(2026-09-12):兩份對外指令參考刻意不再寫死這個數字(改成「七十來個」),
    # 由 t_docs_dont_hardcode_command_count 反向擋住它們再寫回來。剩下三份是給開發者看的
    # 架構與參考文件,那裡講清楚規模有用,而且有本守衛盯著,所以保留數字。
    # 門檻從 3 降到 2(2026-09-25 prompt 稽核):AGENTS.md 是每個 Codex 會談都讀的指示檔,
    # 寫死的數字會過期(`lumos --help` 自己也這樣說),拿掉了;由 t_docs_dont_hardcode_command_count
    # 把 AGENTS.md 收進反向守衛,擋它再寫回來。剩兩份是給開發者看的架構與參考文件。
    check("命令數守衛真的掃到活文件(>=2 份)", scanned >= 2, f"scanned={scanned}")


def t_lint_decisions_structure():
    """lint 抓 decisions 結構壞損:id 被吞進 content block(外審實錘型)/entry 非 dict。"""
    v = mkvault()
    # 壞型一:id 縮排進 content 首行(sibling 被吞)
    write(v, "Systems/BadDec.md", """type: system
summary: |-
  KEY:x
decisions:
  - content: |-
    id: d1
      吞掉的內容""", "# b\n")
    r = run(v, "lint", "BadDec")
    check("lint 抓 id-吞進-content", r.returncode != 0 and "decisions" in r.stdout + r.stderr,
          f"{r.returncode} {r.stdout[:150]}")
    # 壞型二:entry 是純字串
    write(v, "Systems/BadDec2.md", """type: system
summary: |-
  KEY:x
decisions:
  - 只是一句話""", "# b\n")
    r = run(v, "lint", "BadDec2")
    check("lint 抓 decisions entry 非 dict", r.returncode != 0
          and "decisions" in r.stdout + r.stderr, f"{r.returncode} {r.stdout[:150]}")
    # 好型:正常結構不誤報
    write(v, "Systems/GoodDec.md", """type: system
summary: |-
  KEY:x
decisions:
  - id: d1
    content: |-
      正常內容
    decided: 2026-07-29""", "# g\n")
    r = run(v, "lint", "GoodDec")
    check("lint 正常 decisions 不誤報", r.returncode == 0, f"{r.returncode} {r.stdout[:150]}")


def _mk_ci_env(gh_body, declare_ci=True, workflow=None):
    """合成 git repo + vault + 假 gh(PATH 攔截) + .lumos/config.json 的 ci 宣告。"""
    import json as _json
    import os as _os
    import subprocess as _sp
    root = Path(tempfile.mkdtemp(prefix="gctl-ci-"))
    def g(*a):
        _sp.run(["git", "-C", str(root), *a], capture_output=True, text=True)
    g("init", "-q"); g("config", "user.email", "t@t"); g("config", "user.name", "t")
    (root / "a.txt").write_text("x", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "init")
    g("remote", "add", "origin", "https://github.com/acme/demo.git")
    v = root / "docs" / "kg-knowledge"
    (v / "Systems").mkdir(parents=True); (v / "MOC").mkdir()
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    (root / ".lumos").mkdir(exist_ok=True)
    cfg = {}
    if declare_ci:
        cfg["ci"] = {} if workflow is None else {"workflow": workflow}
    (root / ".lumos" / "config.json").write_text(_json.dumps(cfg), encoding="utf-8")
    binp = root / "fakebin"; binp.mkdir()
    gh = binp / "gh"
    gh.write_text(gh_body, encoding="utf-8")
    gh.chmod(0o755)
    env = dict(_os.environ)
    env["PATH"] = f"{binp}:{env['PATH']}"
    return root, v, env


def _ci_run(root, v, env, *args):
    import subprocess as _sp
    return _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *args],
                   cwd=str(root), capture_output=True, text=True, env=env, timeout=120)


_GH_STUB_HEAD = """#!/usr/bin/env python3
import json, sys, os, pathlib
state = pathlib.Path(os.environ.get("GH_STATE", "/tmp/gh-state"))
n = int(state.read_text()) if state.exists() else 0
state.write_text(str(n + 1))
args = sys.argv[1:]
"""


def t_ci_wait():
    """[S1] ci-wait:綠/紅/no-run/逾時/聚合早退/多run輸出/總開關/fail-open。"""
    import json as _json
    import os as _os
    sha_stub = (
        "\nif args[:2] == [\"run\", \"list\"]:\n"
        "    runs = RUNS_FIRST if n == 0 else RUNS_LATER\n"
        "    print(json.dumps(runs))\n"
        "    sys.exit(0)\n"
        "if args[:2] == [\"run\", \"view\"]:\n"
        "    if \"--log-failed\" in args:\n"
        "        print(chr(10).join(['build' + chr(9) + 'test'] * 60)); sys.exit(0)\n"
        "    print(json.dumps({\"jobs\": [{\"name\": \"build\", \"steps\": ["
        "{\"name\": \"Full test suite\", \"conclusion\": \"failure\"}]}]})); sys.exit(0)\n"
        "sys.exit(0)\n"
    )
    def stub(first, later=None):
        return (_GH_STUB_HEAD + f"RUNS_FIRST = {first!r}\nRUNS_LATER = {(later if later is not None else first)!r}\n"
                .replace("'", '"') + sha_stub)

    green = [{"databaseId": 1, "attempt": 1, "status": "completed", "conclusion": "success",
              "displayTitle": "ok", "url": "u1", "workflowName": "CI"}]
    red = [{"databaseId": 2, "attempt": 1, "status": "completed", "conclusion": "failure",
            "displayTitle": "bad", "url": "u2", "workflowName": "CI"}]

    # 綠
    root, v, env = _mk_ci_env(stub(green))
    _os.environ["GH_STATE"] = str(root / "st1"); env["GH_STATE"] = str(root / "st1")
    r = _ci_run(root, v, env, "ci-wait", "--json")
    check("ci-wait 綠 rc0", r.returncode == 0, f"{r.returncode} {r.stdout[:200]} {r.stderr[:200]}")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("綠 verdict/runs 陣列", d["verdict"] == "green" and isinstance(d["runs"], list)
          and len(d["runs"]) == 1, d)
    log = v.parent / ".ci-log.jsonl"
    check("寫帳", log.exists() and "success" in log.read_text(encoding="utf-8"), "")

    # 紅 → rc1 + 失敗步驟(取自 jobs JSON) + log 尾段
    root, v, env = _mk_ci_env(stub(red))
    env["GH_STATE"] = str(root / "st2")
    r = _ci_run(root, v, env, "ci-wait", "--json")
    check("ci-wait 紅 rc1", r.returncode == 1, f"{r.returncode} {r.stdout[:200]}")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("紅 verdict + failed_step 取自 jobs", d["verdict"] == "red"
          and "Full test suite" in (d["runs"][0].get("failed_step") or ""), d)

    # 聚合:一綠一紅 → 任一紅即紅、早退
    both = green + red
    root, v, env = _mk_ci_env(stub(both))
    env["GH_STATE"] = str(root / "st3")
    r = _ci_run(root, v, env, "ci-wait", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("聚合 任一紅即紅", r.returncode == 1 and d["verdict"] == "red", f"{r.returncode} {d}")

    # no-run 快速路徑(不等滿 timeout)
    root, v, env = _mk_ci_env(stub([]))
    env["GH_STATE"] = str(root / "st4")
    import time as _t
    t0 = _t.time()
    r = _ci_run(root, v, env, "ci-wait", "--json", "--timeout", "60", "--grace", "1")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("no-run rc0 + verdict", r.returncode == 0 and d["verdict"] == "no-run", f"{r.returncode} {d}")
    check("no-run 不白等(<20s)", _t.time() - t0 < 20, f"{_t.time()-t0:.0f}s")

    # 逾時:恆 in_progress
    inprog = [{"databaseId": 3, "attempt": 1, "status": "in_progress", "conclusion": None,
               "displayTitle": "run", "url": "u3", "workflowName": "CI"}]
    root, v, env = _mk_ci_env(stub(inprog))
    env["GH_STATE"] = str(root / "st5")
    r = _ci_run(root, v, env, "ci-wait", "--json", "--timeout", "1")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("逾時 rc0 + verdict=timeout", r.returncode == 0 and d["verdict"] == "timeout", f"{r.returncode} {d}")

    # 總開關:未宣告 ci 區塊 → 完全不跑
    root, v, env = _mk_ci_env(stub(red), declare_ci=False)
    env["GH_STATE"] = str(root / "st6")
    r = _ci_run(root, v, env, "ci-wait", "--json")
    check("總開關 未宣告 rc0 不跑", r.returncode == 0, f"{r.returncode} {r.stdout[:150]}")
    check("總開關 未宣告 不寫帳", not (v.parent / ".ci-log.jsonl").exists(), "")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("總開關 verdict=disabled", d["verdict"] == "disabled", d)

    # fail-open:gh 缺席(PATH 只放 git,確保 gh 找不到而 git 還在)
    root, v, env = _mk_ci_env(stub(green))
    _onlygit = root / "onlygit"; _onlygit.mkdir()
    import shutil as _sh
    _gitbin = _sh.which("git")
    if _gitbin:
        (_onlygit / "git").symlink_to(_gitbin)
    env["PATH"] = str(_onlygit)
    r = _ci_run(root, v, env, "ci-wait", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("gh 缺席 fail-open rc0+JSON", r.returncode == 0 and d["verdict"] == "unavailable", f"{r.returncode} {d}")

    # 去重:同 run 同 attempt 同 conclusion 連跑兩次 → 帳一筆
    root, v, env = _mk_ci_env(stub(green))
    env["GH_STATE"] = str(root / "st7")
    _ci_run(root, v, env, "ci-wait")
    _ci_run(root, v, env, "ci-wait")
    lines = [l for l in (v.parent / ".ci-log.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()]
    check("去重 同 run/attempt/conclusion 只一筆", len(lines) == 1, lines)

    # --repo-dir 非目錄 rc2
    r = _ci_run(root, v, env, "ci-wait", "--repo-dir", str(root / "nope"))
    check("--repo-dir 非目錄 rc2", r.returncode == 2, str(r.returncode))

    # ── 假綠:completed 但非成功的 conclusion 不得判綠(2026-07-29 外審實錘) ──
    # 舊碼是「全 completed 且無紅 → green」的二分,cancelled/action_required/stale
    # 與任何未知未來值都會被靜默判綠。計劃 [S1] 矩陣本來就寫了三分類,實作漏跟。
    for concl in ("cancelled", "action_required", "stale", "some_future_value"):
        rows = [{"databaseId": 9, "attempt": 1, "status": "completed", "conclusion": concl,
                 "displayTitle": "x", "url": "u9", "workflowName": "CI"}]
        root, v, env = _mk_ci_env(stub(rows))
        env["GH_STATE"] = str(root / f"stu-{concl}")
        r = _ci_run(root, v, env, "ci-wait", "--json", "--grace", "0")
        d = _json.loads(r.stdout.strip().splitlines()[-1])
        check(f"conclusion={concl} 不得判綠", d["verdict"] == "undetermined", d)
        check(f"conclusion={concl} rc0(不進修復路徑)", r.returncode == 0, str(r.returncode))

    # 混合:一支 success 一支 cancelled → 整體未定(不能被那支綠的蓋過去)
    mixed = green + [{"databaseId": 10, "attempt": 1, "status": "completed",
                      "conclusion": "cancelled", "displayTitle": "x", "url": "u10",
                      "workflowName": "Lint"}]
    root, v, env = _mk_ci_env(stub(mixed))
    env["GH_STATE"] = str(root / "stmix")
    r = _ci_run(root, v, env, "ci-wait", "--json", "--grace", "0")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("一綠一 cancelled → 未定不判綠", d["verdict"] == "undetermined", d)

    # ── 紅燈證據必須進**文字**輸出(不是只塞 --json) ──
    # 外審實錘:README/skill/計劃都承諾會印失敗步驟+log,實作只進 json,
    # 人跑 `lumos ci-wait` 只看得到「紅」跟一個網址,拿不到任何可修的線索。
    root, v, env = _mk_ci_env(stub(red))
    env["GH_STATE"] = str(root / "sttext")
    r = _ci_run(root, v, env, "ci-wait")          # 注意:不帶 --json
    check("紅燈文字輸出含失敗步驟", "Full test suite" in r.stdout, r.stdout[:300])
    check("紅燈文字輸出含 log 尾段", "log 尾段" in r.stdout and "build" in r.stdout,
          r.stdout[:300])
    check("紅燈文字輸出 rc1", r.returncode == 1, str(r.returncode))
    # 綠燈不該噴這些噪音
    root, v, env = _mk_ci_env(stub(green))
    env["GH_STATE"] = str(root / "sttext2")
    r = _ci_run(root, v, env, "ci-wait")
    check("綠燈文字輸出無失敗步驟噪音", "失敗步驟" not in r.stdout, r.stdout[:200])


def t_ci_status_and_gov():
    """[S3] ci-status 唯讀不打網路 + gov 第 7 源(含總開關)。"""
    import json as _json
    stub = _GH_STUB_HEAD + "sys.exit(9)\n"   # 一旦被呼叫就失敗
    root, v, env = _mk_ci_env(stub)
    log = v.parent / ".ci-log.jsonl"
    log.write_text(_json.dumps({
        "ts": "2026-07-29T10:00:00+08:00", "run_id": 7, "attempt": 1, "sha": "abc1234",
        "branch": "main", "workflow": "CI", "conclusion": "failure", "title": "bad",
        "url": "u", "failed_step": "build/test", "dedup_key": "7:1:failure"},
        ensure_ascii=False) + "\n", encoding="utf-8")
    r = _ci_run(root, v, env, "ci-status", "--json")
    check("ci-status 不呼叫 gh(rc0)", r.returncode == 0, f"{r.returncode} {r.stderr[:150]}")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("ci-status 讀帳", d.get("conclusion") == "failure" and d.get("sha") == "abc1234", d)
    r = _ci_run(root, v, env, "ci-status")
    check("ci-status 文字含檢查時刻", "2026-07-29" in r.stdout, r.stdout[:150])
    # 「檔尾最後一筆」≠「最新結論」:同 sha 多支 workflow 各一筆,綠的排在紅的後面時
    # 舊碼只讀最後一筆 → 報綠(與 SessionStart hook 早先修過的同型假綠,2026-07-29 補齊)。
    rows = [
        {"ts": "2026-07-29T11:00:00+08:00", "run_id": 8, "attempt": 1, "sha": "def5678",
         "branch": "main", "workflow": "CI", "conclusion": "failure", "title": "bad",
         "url": "u8", "failed_step": "build/test", "dedup_key": "8:1:failure"},
        {"ts": "2026-07-29T11:01:00+08:00", "run_id": 9, "attempt": 1, "sha": "def5678",
         "branch": "main", "workflow": "Lint", "conclusion": "success", "title": "ok",
         "url": "u9", "failed_step": "", "dedup_key": "9:1:success"},
    ]
    log.write_text("".join(_json.dumps(x, ensure_ascii=False) + "\n" for x in rows),
                   encoding="utf-8")
    r = _ci_run(root, v, env, "ci-status", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("ci-status 同 sha 多筆:報最壞的(紅)非檔尾那筆(綠)",
          d.get("conclusion") == "failure" and d.get("workflow") == "CI", d)
    # **反序也要成立**——只測「壞的在前」分不出「報最壞」與「報第一筆」;
    # 把紅的放檔尾再測一次,兩個方向都對才是真的取最壞(終審 reviewer 指出的空洞風險)。
    log.write_text("".join(_json.dumps(x, ensure_ascii=False) + "\n"
                           for x in [rows[1], rows[0]]), encoding="utf-8")
    r = _ci_run(root, v, env, "ci-status", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("ci-status 同 sha 多筆:紅的排檔尾也照報紅(非只取第一筆)",
          d.get("conclusion") == "failure" and d.get("workflow") == "CI", d)
    # 同 sha 全綠時照報綠
    log.write_text(_json.dumps(rows[1], ensure_ascii=False) + "\n", encoding="utf-8")
    r = _ci_run(root, v, env, "ci-status", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("ci-status 同 sha 全綠仍報綠", d.get("conclusion") == "success", d)
    # 非成功非紅(cancelled)優先於綠被報出來
    log.write_text("".join(_json.dumps(x, ensure_ascii=False) + "\n" for x in [
        {**rows[1], "run_id": 11, "conclusion": "cancelled", "workflow": "Deploy",
         "dedup_key": "11:1:cancelled"}, rows[1]]), encoding="utf-8")
    r = _ci_run(root, v, env, "ci-status", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("ci-status 同 sha 有 cancelled:不報綠", d.get("conclusion") == "cancelled", d)
    # 還原成單筆 failure 供後續 gov 斷言
    log.write_text(_json.dumps({
        "ts": "2026-07-29T10:00:00+08:00", "run_id": 7, "attempt": 1, "sha": "abc1234",
        "branch": "main", "workflow": "CI", "conclusion": "failure", "title": "bad",
        "url": "u", "failed_step": "build/test", "dedup_key": "7:1:failure"},
        ensure_ascii=False) + "\n", encoding="utf-8")
    # gov 第 7 源
    r = _ci_run(root, v, env, "gov")
    check("gov 見得到 CI 事件", "ci" in r.stdout and "failure" in r.stdout, r.stdout[-400:])
    # 總開關:移除 ci 區塊 → gov 不 load
    (root / ".lumos" / "config.json").write_text("{}", encoding="utf-8")
    r = _ci_run(root, v, env, "gov")
    check("gov 總開關:移除宣告後不顯示", "failure" not in r.stdout, r.stdout[-300:])


def t_ci_rerun_latest_attempt_wins():
    """同一個 CI 執行重跑過(第 1 次紅、第 2 次綠),只算最後那次——兩個讀帳的地方都一樣。

    出身:2026-09-23 實踩。推上去 CI 紅了一次(測試時序競態),重跑變綠,但 ci-status 仍回報 failure。
    原因之一是當時直接用 gh 重跑、沒再跑 ci-wait,成功那次根本沒進帳;但就算進了帳也一樣錯:
    讀帳的地方對「同一個提交的全部筆」取最壞,而同一個執行的兩次嘗試是兩筆,舊的那次紅永遠蓋掉新的綠。
    「取最壞」只該跨不同執行(不同 workflow),同一個執行要先只留最後一次嘗試。
    開場提醒那支 hook 是同一個錯(任何一筆紅就喊紅),一起修。
    翻紅釘:ci-status 拿掉「同一個執行只留最後一次」→ ①紅;hook 拿掉 → ③紅。
    """
    import json as _json, subprocess as _sp
    from pathlib import Path as _P
    stub = _GH_STUB_HEAD + "sys.exit(9)\n"
    root, v, env = _mk_ci_env(stub)
    sha = _sp.run(["git", "-C", str(root), "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    log = v.parent / ".ci-log.jsonl"
    def row(run_id, att, concl, wf="CI", ts="2026-09-23T10:00:00+08:00"):
        return {"ts": ts, "run_id": run_id, "attempt": att, "sha": sha, "branch": "main", "workflow": wf,
                "conclusion": concl, "title": "t", "url": f"u{run_id}", "failed_step": "test" if concl != "success" else "",
                "dedup_key": f"{run_id}:{att}:{concl}"}
    def put(rows):
        log.write_text("".join(_json.dumps(x, ensure_ascii=False) + "\n" for x in rows), encoding="utf-8")
    def status():
        r = _ci_run(root, v, env, "ci-status", "--json")
        return _json.loads(r.stdout.strip().splitlines()[-1])
    put([row(5, 1, "failure"), row(5, 2, "success", ts="2026-09-23T10:30:00+08:00")])
    check("① 同一個執行第 1 次紅、第 2 次綠 → 報綠", status().get("conclusion") == "success", str(status()))
    put([row(5, 2, "success", ts="2026-09-23T10:30:00+08:00"), row(5, 1, "failure")])
    check("① 反序寫進帳也一樣報綠(看的是嘗試次數,不是在檔裡的位置)", status().get("conclusion") == "success", str(status()))
    put([row(5, 1, "failure"), row(5, 2, "success"), row(6, 1, "failure", wf="Lint")])
    check("② 不同執行(另一支 workflow)紅了,照舊報紅(取最壞只跨執行)",
          status().get("conclusion") == "failure" and status().get("workflow") == "Lint", str(status()))
    # 代碼審 r1 通才席:同一個執行一筆存整數、一筆存字串,也要算同一個
    r_str = row(5, 2, "success"); r_str["run_id"] = "5"
    put([row(5, 1, "failure"), r_str])
    check("⑤ run_id 一筆整數一筆字串,照樣只算最後一次", status().get("conclusion") == "success", str(status()))
    # 同一次嘗試有兩筆結論不同(不該發生,但發生了):留紅的,而且不看在檔裡的先後
    put([row(5, 1, "success"), row(5, 1, "failure")])
    a = status().get("conclusion")
    put([row(5, 1, "failure"), row(5, 1, "success")])
    b = status().get("conclusion")
    check("⑥ 同一次嘗試兩筆結論不同 → 兩種順序都留紅的", a == "failure" and b == "failure", f"{a} {b}")
    # 代碼審 r2 通才席:兩筆都不是紅(取消對成功)時,也不准看先後——留比較糟的那筆
    put([row(5, 1, "cancelled"), row(5, 1, "success")]); a2 = status().get("conclusion")
    put([row(5, 1, "success"), row(5, 1, "cancelled")]); b2 = status().get("conclusion")
    check("⑦ 取消對成功 → 兩種順序都留取消", a2 == "cancelled" and b2 == "cancelled", f"{a2} {b2}")
    hook = _P(__file__).resolve().parent / "hooks" / "claude" / "ci-status-hook.py"
    def run_hook():
        return _sp.run([sys.executable, str(hook)], input=_json.dumps({"cwd": str(root)}), capture_output=True,
                       text=True, cwd=str(root), env=env, timeout=60)
    put([row(5, 1, "failure"), row(5, 2, "success")])
    h = run_hook()
    check("③ 開場提醒:重跑變綠的不再喊紅", "CI 是紅的" not in h.stdout, h.stdout[:300])
    put([row(5, 1, "failure"), row(5, 2, "success"), row(6, 1, "failure", wf="Lint")])
    h = run_hook()
    check("④ 開場提醒:別的執行真的紅,照舊喊", "CI 是紅的" in h.stdout and "Lint" in h.stdout, h.stdout[:300])


def t_ci_wait_short_sha_resolved():
    """ci-wait --sha 給短版:先在本機換成完整提交編號再去查 CI(GitHub 用完整 sha 篩,短的永遠查不到、等到逾時判 no-run;
    rtb 2026-10-07 回報);本機找不到的 sha → rc2 講清楚。翻紅釘:不換完整 sha → ①紅;找不到照查 → ②紅。"""
    print("t_ci_wait_short_sha_resolved")
    import json as _json, subprocess as _sp
    green = [{"databaseId": 1, "attempt": 1, "status": "completed", "conclusion": "success",
              "displayTitle": "ok", "url": "u1", "workflowName": "CI"}]
    stub = (_GH_STUB_HEAD + f"RUNS_FIRST = {green!r}\nRUNS_LATER = {green!r}\n".replace("'", '"')
            + "\nif args[:2] == [\"run\", \"list\"]:\n    print(json.dumps(RUNS_FIRST))\n    sys.exit(0)\nsys.exit(0)\n")
    root, v, env = _mk_ci_env(stub)
    env["GH_STATE"] = str(root / "st")
    full = _sp.run(["git", "-C", str(root), "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    r = _ci_run(root, v, env, "ci-wait", "--json", "--grace", "0", "--sha", full[:8])
    d = _json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {}
    check("①短 sha → 換成完整 sha 再查", r.returncode == 0 and d.get("sha") == full, f"{r.returncode} {r.stdout[-300:]} {r.stderr[-300:]}")
    r = _ci_run(root, v, env, "ci-wait", "--json", "--sha", "deadbeef")
    check("②本機找不到的 sha → rc2、講清楚(列出幾種可能)", r.returncode == 2 and "完整" in r.stderr and "git fetch" in r.stderr
          and "不只一個" in r.stderr, f"{r.returncode} {r.stderr[-300:]}")
    print("  ✓ t_ci_wait_short_sha_resolved")


def t_ci_wait_rerun_records_latest_attempt():
    """真的走一次:第一次 ci-wait 記下紅,重跑後再 ci-wait 記下第 2 次嘗試的綠,ci-status 就該報綠。

    出身:代碼審 r1 通才席——另一支測試是直接手寫帳,沒證明寫帳那一側在重跑後真的會記下遞增的嘗試次數。
    這支用假的 gh:第一次回「第 7 號執行第 1 次嘗試失敗」,之後回「第 7 號執行第 2 次嘗試成功」。
    翻紅釘:ci-status 拿掉「同一個執行只留最後一次」→ ②紅。
    """
    import json as _json
    sha_stub = (
        "\nif args[:2] == [\"run\", \"list\"]:\n"
        "    print(json.dumps(RUNS_FIRST if n == 0 else RUNS_LATER)); sys.exit(0)\n"
        "if args[:2] == [\"run\", \"view\"]:\n"
        "    if \"--log-failed\" in args:\n"
        "        print('build' + chr(9) + 'x'); sys.exit(0)\n"
        "    print(json.dumps({\"jobs\": [{\"name\": \"build\", \"steps\": [{\"name\": \"Full test suite\", \"conclusion\": \"failure\"}]}]})); sys.exit(0)\n"
        "sys.exit(0)\n")
    first = [{"databaseId": 7, "attempt": 1, "status": "completed", "conclusion": "failure",
              "displayTitle": "t", "url": "u7", "workflowName": "CI"}]
    later = [{"databaseId": 7, "attempt": 2, "status": "completed", "conclusion": "success",
              "displayTitle": "t", "url": "u7", "workflowName": "CI"}]
    stub = (_GH_STUB_HEAD + f"RUNS_FIRST = {first!r}\nRUNS_LATER = {later!r}\n".replace("'", '"') + sha_stub)
    root, v, env = _mk_ci_env(stub)
    env["GH_STATE"] = str(root / "st-rerun")
    r1 = _ci_run(root, v, env, "ci-wait", "--json")
    r2 = _ci_run(root, v, env, "ci-wait", "--json")
    rows = [_json.loads(l) for l in (v.parent / ".ci-log.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()]
    atts = sorted((r.get("attempt"), r.get("conclusion")) for r in rows)
    check("① 現場成立:兩次 ci-wait 各記一筆,嘗試次數遞增", atts == [(1, "failure"), (2, "success")],
          f"{atts} rc={r1.returncode},{r2.returncode}")
    d = _json.loads(_ci_run(root, v, env, "ci-status", "--json").stdout.strip().splitlines()[-1])
    check("② 重跑變綠之後 ci-status 報綠", d.get("conclusion") == "success", str(d))


def t_ci_latest_attempts_copies_identical():
    """「同一個執行只留最後一次嘗試」在主程式與 hook 各有複本,所有複本的程式必須一模一樣。

    hook 是獨立檔、複製到全域後 import 不到主程式,只能各放一份;沒有這支守衛,
    改了一邊忘了另一邊,兩個地方對同一次 CI 就會給出相反的結論。比的是語法樹(說明文字可以不同)。
    ★掃全部、不寫死清單★(代碼審 r1 架構席):本 repo 的 hook 間複本守衛(信任邊界、逾時預算)
    都踩過「寫死三支、漏了第四支」才改成掃全部——第一版這支又寫死了兩個路徑。
    ★函式裡那組「算紅」的結論也要跟各檔自己的常數一致★:為了讓複本逐字相同,那組寫在函式裡,
    等於多了一份清單,不盯的話會跟 _CI_RED / RED 悄悄分岔。
    翻紅釘:改 hook 那份的任一行邏輯 → ③紅;把函式裡的紅燈集合少一個 → ④紅。
    """
    import ast as _ast
    from pathlib import Path as _P
    base = _P(__file__).resolve().parent
    files = [base / "lumos"] + sorted((base / "hooks").rglob("*.py"))
    bodies, reds_inline, reds_const, dup = {}, {}, {}, []
    for f in files:
        try:
            tree = _ast.parse(f.read_text(encoding="utf-8"))
        except (SyntaxError, OSError):
            continue
        # ★函式要從整棵樹找,不能只看最外層★(代碼審 r2 兩席):包在 if/class/另一個函式裡的複本,
        # 只看最外層會整份從比對名單裡消失,守衛照樣全綠——通才席實際塞了一份包在 if True: 裡、
        # 邏輯寫錯的複本,四條全過。常數那邊仍只看最外層(那是各檔自己的模組常數)。
        defs = [n for n in _ast.walk(tree) if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))
                and n.name == "_ci_latest_attempts"]
        if len(defs) > 1:
            dup.append(f.name)
        for n in defs[:1]:
                stmts = list(n.body)
                if stmts and isinstance(stmts[0], _ast.Expr) and isinstance(getattr(stmts[0], "value", None), _ast.Constant):
                    stmts = stmts[1:]
                bodies[f.name] = _ast.dump(_ast.Module(body=stmts, type_ignores=[]))
                for sub in _ast.walk(n):
                    if isinstance(sub, _ast.Tuple) and all(isinstance(e, _ast.Constant) and isinstance(e.value, str) for e in sub.elts) \
                            and "failure" in [e.value for e in sub.elts]:
                        reds_inline[f.name] = tuple(e.value for e in sub.elts)
        for n in tree.body:
            if isinstance(n, _ast.Assign) and len(n.targets) == 1 and isinstance(n.targets[0], _ast.Name) \
                    and n.targets[0].id in ("_CI_RED", "RED") and isinstance(n.value, _ast.Tuple):
                reds_const[f.name] = tuple(e.value for e in n.value.elts)
    check("① 現場成立:至少找到主程式與開場提醒 hook 兩份", {"lumos", "ci-status-hook.py"} <= set(bodies), str(sorted(bodies)))
    ref = bodies.get("lumos")
    diff = [k for k, b in bodies.items() if b != ref]
    check("② 找到的複本都比對了", len(bodies) >= 2, str(sorted(bodies)))
    check("③ 所有複本的程式一模一樣", diff == [], f"跟主程式不一致的:{diff}")
    check("③ 沒有哪個檔裡同時藏了兩份", dup == [], f"同一檔多份:{dup}")
    bad = [k for k in bodies if k in reds_const and set(reds_inline.get(k, ())) != set(reds_const[k])]
    check("④ 函式裡的紅燈集合跟各檔自己的常數一致", bad == [] and all(k in reds_inline for k in bodies),
          f"不一致:{bad} 函式內:{reds_inline} 常數:{reds_const}")


def t_ci_hooks():
    """[S2b] SessionStart hook 註冊對稱 + 提醒判法(該 sha 全部筆/總開關)。"""
    import json as _json
    import subprocess as _sp
    from pathlib import Path as _P
    root_repo = _P(__file__).resolve().parent.parent
    hook = root_repo / "scripts" / "hooks" / "claude" / "ci-status-hook.py"
    check("hook 檔存在", hook.exists(), str(hook))
    src = (root_repo / "scripts" / "lumos").read_text(encoding="utf-8")
    check("hook 進 _GLOBAL_CLAUDE_HOOKS 白名單(生命週期對稱)",
          "ci-status-hook.py" in src, "")
    merge = (root_repo / "scripts" / "merge-claude-settings.py").read_text(encoding="utf-8")
    check("hook 進 HOOK_ENTRIES(SessionStart)",
          "ci-status-hook.py" in merge and "SessionStart" in merge, "")
    check("hook 輸出契約宣告 SessionStart(非抄 PreToolUse)",
          hook.exists() and '"SessionStart"' in hook.read_text(encoding="utf-8"), "")
    # 行為:紅 → 有注入;綠 → 靜默;未宣告 → 靜默
    stub = _GH_STUB_HEAD + "sys.exit(0)\n"
    root, v, env = _mk_ci_env(stub)
    sha = _sp.run(["git", "-C", str(root), "rev-parse", "HEAD"],
                  capture_output=True, text=True).stdout.strip()
    log = v.parent / ".ci-log.jsonl"
    def wr(concl):
        log.write_text(_json.dumps({"ts": "2026-07-29T10:00:00+08:00", "run_id": 1, "attempt": 1,
                                    "sha": sha, "branch": "main", "workflow": "CI",
                                    "conclusion": concl, "title": "t", "url": "u",
                                    "failed_step": "", "dedup_key": f"1:1:{concl}"},
                                   ensure_ascii=False) + "\n", encoding="utf-8")
    def run_hook():
        payload = _json.dumps({"cwd": str(root)})
        return _sp.run([sys.executable, str(hook)], input=payload, capture_output=True,
                       text=True, cwd=str(root), env=env, timeout=60)
    wr("failure")
    r = run_hook()
    check("hook 紅 → 注入提醒", r.returncode == 0 and "CI" in r.stdout and "紅" in r.stdout,
          f"{r.returncode} {r.stdout[:200]} {r.stderr[:200]}")
    wr("success")
    r = run_hook()
    check("hook 綠 → 靜默", r.stdout.strip() == "", r.stdout[:150])
    # 多 run 分筆:紅在前綠在後,不可被「最後一筆」蓋掉
    log.write_text("\n".join([
        _json.dumps({"ts": "2026-07-29T10:00:00+08:00", "run_id": 1, "attempt": 1, "sha": sha,
                     "branch": "main", "workflow": "A", "conclusion": "failure", "title": "t",
                     "url": "u", "failed_step": "", "dedup_key": "1:1:failure"}, ensure_ascii=False),
        _json.dumps({"ts": "2026-07-29T10:01:00+08:00", "run_id": 2, "attempt": 1, "sha": sha,
                     "branch": "main", "workflow": "B", "conclusion": "success", "title": "t",
                     "url": "u", "failed_step": "", "dedup_key": "2:1:success"}, ensure_ascii=False),
    ]) + "\n", encoding="utf-8")
    r = run_hook()
    check("hook 多run:紅不被最後一筆綠蓋掉", "紅" in r.stdout, r.stdout[:200])
    # 總開關
    (root / ".lumos" / "config.json").write_text("{}", encoding="utf-8")
    r = run_hook()
    check("hook 總開關:未宣告 → 靜默", r.stdout.strip() == "", r.stdout[:150])


def _testmap_mk(td):
    """testmap 沙盒 fixture:bulk commit(>20 檔,cochange 挖掘層天然丟棄)+cochange 專用小 commit。"""
    import subprocess as _sp
    from pathlib import Path as _P
    g = lambda *a: _sp.run(["git", "-c", "user.email=t@t", "-c", "user.name=t", *a],
                           cwd=td, check=True, capture_output=True)
    g("init", "-q")
    root = _P(td)
    files = {
        "src/Foo.cs": "class Foo {}", "Foo.ts": "export const x=1",
        "Foo.spec.ts": "it('x',()=>{})",
        "src/Foo.generated.cs": "class G {}", "src/Foo.generated.Tests.cs": "class GT {}",
        "foo.py": "x=1", "foo_spec.py": "y=2", "test_foo.py": "z=3", "Foo_TESTS.py": "w=4",
        "tests/FooTests.cs": "class FT {}",
        "IMember.cs": "interface IMember {}", "Member.cs": "class Member {}",
        "Db.cs": "class Db {}",
        "tests/ScenarioTests.cs": "var m = new Mock<IMember>(); // Db",
        "Card.cs": "class Card {}", "tests/CardTests.cs": "// Card here",
        "a/helpers.py": "h=1", "b/helpers.py": "h=2", "tests/helpers.py": "h=3",
        "helper.py": "h=4", "tests/helper_.py": "h=5",   # rstrip 回歸釘:未剝離 stem 不去尾底線
        "Button.tsx": "export default 1", "__tests__/Button.tsx": "render()",
        "pkg/__init__.py": "", "tests/__init__.py": "",
        "LoadTest.cs": "class LoadTest {}", "FooTest.java": "class FooTest {}",
        "Tests.cs": "class T {}", "Latest.ts": "1", "Contest.cs": "2",
        "bar.py": "b=1", "Test_bar.py": "q=9",   # 大寫T前綴負例(獨立stem,防 APFS 大小寫不敏感撞 test_foo.py)
        "ABTest.cs": "3", "PodSpec.ts": "4", "docs/foo_test.md": "# doc",
        "會員系統.cs": "class W {}", "tests/會員系統Tests.cs": "// w",
        "HugeThing.cs": "class H {}",
    }
    for rel, body in files.items():
        fp = root / rel
        fp.parent.mkdir(parents=True, exist_ok=True)
        fp.write_text(body, encoding="utf-8")
    (root / "tests/HugeThingTests.cs").write_text("// pad\n" + "0" * 250 * 1024, encoding="utf-8")
    g("add", "-A")
    g("commit", "-q", "-m", "bulk")          # 36 檔 > max_changeset 20 → cochange 丟棄
    for i in range(3):                        # support=3 → cochange 邊
        (root / "coch.cs").write_text(f"c={i}", encoding="utf-8")
        (root / "tests/CochScenTests.cs").write_text(f"t={i}", encoding="utf-8")
        g("add", "coch.cs", "tests/CochScenTests.cs")
        g("commit", "-q", "-m", f"co{i}")
    for i in range(2):                        # support=2 → 被 testmap 門檻擋
        (root / "two.cs").write_text(f"c={i}", encoding="utf-8")
        (root / "tests/TwoScenTests.cs").write_text(f"t={i}", encoding="utf-8")
        g("add", "two.cs", "tests/TwoScenTests.cs")
        g("commit", "-q", "-m", f"two{i}")
    return g


def _testmap_run(args, cwd):
    import subprocess as _sp
    from pathlib import Path as _P
    lumos_bin = str(_P(__file__).parent / "lumos")
    return _sp.run([sys.executable, lumos_bin] + args, cwd=cwd,
                   capture_output=True, text=True, timeout=120)


def _testmap_edges(td):
    import json as _json
    from pathlib import Path as _P
    m = _json.loads((_P(td) / ".lumos" / "testmap.json").read_text(encoding="utf-8"))
    return {(e["src"], e["test"]): e for e in m["edges"]}, m


def t_testmap_build():
    """[S1] 三路訊號挖掘:naming 各型/content/cochange 門檻/合併/確定性/守衛。"""
    import json as _json
    import tempfile
    from pathlib import Path as _P
    with tempfile.TemporaryDirectory() as td:
        _testmap_mk(td)
        r = _testmap_run(["testmap", "build", "--repo", td], td)
        check("build rc0", r.returncode == 0, f"{r.returncode} {r.stderr}")
        ed, m = _testmap_edges(td)
        # 1 naming 各型
        check("naming FooTests↔src/Foo.cs", ("src/Foo.cs", "tests/FooTests.cs") in ed, list(ed)[:8])
        check("naming FooTests↔Foo.ts(同stem多src各建)", ("Foo.ts", "tests/FooTests.cs") in ed)
        check("naming Foo.spec.ts↔Foo.ts(標記段)", ("Foo.ts", "Foo.spec.ts") in ed)
        check("naming 點分basename(去尾點)", ("src/Foo.generated.cs", "src/Foo.generated.Tests.cs") in ed)
        check("naming foo_spec(_spec直剝)", ("foo.py", "foo_spec.py") in ed)
        check("naming test_前綴", ("foo.py", "test_foo.py") in ed)
        check("naming Foo_TESTS(底線不敏感可剝)", ("foo.py", "Foo_TESTS.py") in ed)
        e = ed[("src/Foo.cs", "tests/FooTests.cs")]
        check("naming conf 0.9", e["conf"] == 0.9, e)
        # 2 content
        check("content I+stem 兩邊各建", ("Member.cs", "tests/ScenarioTests.cs") in ed
              and ("IMember.cs", "tests/ScenarioTests.cs") in ed)
        check("content 短stem<4不建(Db)", ("Db.cs", "tests/ScenarioTests.cs") not in ed)
        check("content conf 0.5", ed[("Member.cs", "tests/ScenarioTests.cs")]["conf"] == 0.5)
        # 3 cochange
        check("cochange support3 建邊(封頂0.8)", ("coch.cs", "tests/CochScenTests.cs") in ed
              and ed[("coch.cs", "tests/CochScenTests.cs")]["conf"] == 0.8,
              ed.get(("coch.cs", "tests/CochScenTests.cs")))
        check("cochange support2 不建", ("two.cs", "tests/TwoScenTests.cs") not in ed)
        check("cochange 擋邊 stderr 統計", "support<3" in r.stderr, r.stderr[:200])
        # 4 合併+確定性
        e = ed[("Card.cs", "tests/CardTests.cs")]
        check("多源合併 sources 字典序", e["sources"] == ["content", "naming"] and e["conf"] == 0.9, e)
        edges1 = m["edges"]
        _testmap_run(["testmap", "build", "--repo", td], td)
        _, m2 = _testmap_edges(td)
        check("edges 兩次 build 逐字相等", edges1 == m2["edges"])
        # 8 200KB 跳 content、naming 不受影響
        check("200KB 超限跳 content(stderr記)", "HugeThingTests" in r.stderr, r.stderr[:300])
        check("200KB naming 不受影響", ("HugeThing.cs", "tests/HugeThingTests.cs") in ed)
        # 9+20+21+22 判定/建邊邊界
        check("helpers 同stem>1 不建邊", not any(k[1] == "tests/helpers.py" for k in ed))
        check("rstrip 回歸釘:helper_ 未剝離不去尾(無邊)",
              not any(k[1] == "tests/helper_.py" for k in ed),
              list(k for k in ed if "helper" in k[0]))
        check("同名唯一 __tests__/Button.tsx 建邊", ("Button.tsx", "__tests__/Button.tsx") in ed)
        check("dunder 不建邊", not any(k[1] == "tests/__init__.py" for k in ed))
        check("駝峰單數限java:FooTest.java 是測試", not any(k[0] == "FooTest.java" for k in ed))
        check("LoadTest.cs 非測試(是src)", not any(k[1] == "LoadTest.cs" for k in ed))
        check("Tests.cs stem=綴詞 不建邊", not any("Tests.cs" == k[1] and k[0] for k in ed
              if k[1] == "Tests.cs"))
        for bad in ("Latest.ts", "Contest.cs", "ABTest.cs", "PodSpec.ts"):
            check(f"{bad} 不判為測試檔", not any(k[1] == bad for k in ed))
        check("md 不入場", not any("foo_test.md" in k[0] + k[1] for k in ed))
        from importlib.machinery import SourceFileLoader as _SFL
        _lm = _SFL("lumos_tm_mod", str(_P(__file__).parent / "lumos")).load_module()
        check("Test_bar.py 大寫T前綴不判測試檔(分類直驗+無邊)",
              not _lm._testmap_is_test("Test_bar.py")
              and not any(k[1] == "Test_bar.py" for k in ed),
              list(k for k in ed if "bar" in k[0] + k[1]))
        check("CJK naming 邊", ("會員系統.cs", "tests/會員系統Tests.cs") in ed)
        # 13 mkdir 自建(.lumos 由本次 build 建立)
        check("mkdir 自建 .lumos", (_P(td) / ".lumos" / "testmap.json").is_file())
        # header
        check("map header 齊", m["version"] == 1 and len(m["built_at_commit"]) == 40
              and "T" in m["built_at"], {k: m[k] for k in ("version", "built_at")})
        # 10 json 純度
        r = _testmap_run(["testmap", "build", "--repo", td, "--json"], td)
        check("build --json 單行", r.returncode == 0 and len(r.stdout.strip().splitlines()) == 1)
        j = _json.loads(r.stdout)
        check("build --json 欄位", j["edge_count"] == len(edges1) and j["path"] == ".lumos/testmap.json"
              and len(j["built_at_commit"]) == 40, j)


def t_testmap_affected():
    """[S2] advisory 查詢:推薦/自證/去重/uncovered/刪檔語意/陳舊三訊號/json。"""
    import json as _json
    import shutil
    import subprocess as _sp
    import tempfile
    from pathlib import Path as _P
    with tempfile.TemporaryDirectory() as td:
        g = _testmap_mk(td)
        root = _P(td)
        _testmap_run(["testmap", "build", "--repo", td], td)
        # ② 陳舊:build 後 commit 候選檔
        (root / "Card.cs").write_text("class Card { int x; }", encoding="utf-8")
        (root / "coch.cs").write_text("c=9", encoding="utf-8")
        g("add", "Card.cs", "coch.cs"); g("commit", "-q", "-m", "card+coch change")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        check("affected rc0", r.returncode == 0, f"{r.returncode} {r.stderr}")
        j = _json.loads(r.stdout)
        sug = {s["test"]: s for s in j["suggests"]}
        check("推薦 CardTests(naming)", "tests/CardTests.cs" in sug
              and sug["tests/CardTests.cs"]["conf"] == 0.9, j["suggests"])
        confs = [s["conf"] for s in j["suggests"]]
        check("推薦降序(多筆異conf真序)", len(confs) >= 2 and confs[0] == 0.9
              and confs == sorted(confs, reverse=True), confs)
        check("suggests 帶 sources/srcs", sug["tests/CardTests.cs"]["sources"] == ["content", "naming"]
              and sug["tests/CardTests.cs"]["srcs"] == ["Card.cs"], sug.get("tests/CardTests.cs"))
        check("② build後commit → stale", j["stale"] is True, j["stale"])
        check("json map 欄照實", j["map_built_at"] and j["built_at_commit"], j)
        # 重建後乾淨 → stale false;自證+去重
        _testmap_run(["testmap", "build", "--repo", td], td)
        (root / "Card.cs").write_text("class Card { int y; }", encoding="utf-8")
        (root / "tests/CardTests.cs").write_text("// Card v2", encoding="utf-8")
        g("add", "-A"); g("commit", "-q", "-m", "both")
        _testmap_run(["testmap", "build", "--repo", td], td)   # 乾淨基準
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        sug = {s["test"]: s for s in j["suggests"]}
        e = sug.get("tests/CardTests.cs")
        check("自證+邊 去重一筆 conf1.0 sources聯集", e and e["conf"] == 1.0
              and "self" in e["sources"] and "naming" in e["sources"]
              and len([s for s in j["suggests"] if s["test"] == "tests/CardTests.cs"]) == 1, e)
        check("乾淨基準 stale false", j["stale"] is False, j["stale"])
        # 文字模式
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td], td)
        check("文字 banner+建議行", r.stdout.startswith("map built at ")
              and "tests/CardTests.cs" in r.stdout and "[" in r.stdout, r.stdout[:200])
        # 刪除測試檔:map 邊與自證兩路皆不推薦;src 全邊已刪 → uncovered(孤立對 Foo.generated)
        g("rm", "-q", "tests/FooTests.cs", "src/Foo.generated.Tests.cs")
        (root / "src/Foo.cs").write_text("class Foo { int z; }", encoding="utf-8")
        (root / "src/Foo.generated.cs").write_text("class G { int z; }", encoding="utf-8")
        g("add", "src"); g("commit", "-q", "-m", "del tests + change srcs")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("已刪測試檔不推薦", not any(s["test"] in ("tests/FooTests.cs", "src/Foo.generated.Tests.cs")
              for s in j["suggests"]), j["suggests"])
        check("src邊全指已刪測試 → uncovered", "src/Foo.generated.cs" in j["uncovered"], j["uncovered"])
        # 刪除 src 仍查邊
        _testmap_run(["testmap", "build", "--repo", td], td)
        g("rm", "-q", "Card.cs"); g("commit", "-q", "-m", "del card")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("刪除的 src 仍查邊", any(s["test"] == "tests/CardTests.cs" for s in j["suggests"]),
              j["suggests"])
        check("②′ build後刪檔 → stale", j["stale"] is True, j["stale"])
        # 25 rm 後 mkdir 同名目錄 → 不推薦(is_file 擋)
        (root / "tests/CardTests.cs").unlink()
        (root / "tests/CardTests.cs").mkdir()
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("同名目錄不推薦", not any(s["test"] == "tests/CardTests.cs" for s in j["suggests"]),
              j["suggests"])
        shutil.rmtree(root / "tests/CardTests.cs")
        _sp.run(["git", "checkout", "-q", "--", "."], cwd=td, check=True)
        # ①非祖先 sha
        _testmap_run(["testmap", "build", "--repo", td], td)
        cur = _sp.run(["git", "rev-parse", "--abbrev-ref", "HEAD"], cwd=td,
                      capture_output=True, text=True).stdout.strip()
        g("checkout", "-q", "-b", "side")
        g("commit", "-q", "--allow-empty", "-m", "side")
        side_sha = _sp.run(["git", "rev-parse", "HEAD"], cwd=td,
                           capture_output=True, text=True).stdout.strip()
        g("checkout", "-q", cur)
        g("commit", "-q", "--allow-empty", "-m", "after")
        mp = root / ".lumos" / "testmap.json"
        mm = _json.loads(mp.read_text(encoding="utf-8"))
        mm["built_at_commit"] = side_sha
        mp.write_text(_json.dumps(mm, ensure_ascii=False), encoding="utf-8")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("①非祖先 sha → stale", j["stale"] is True, j["stale"])
        # ③ 未提交改動/未追蹤新測試檔
        _testmap_run(["testmap", "build", "--repo", td], td)
        (root / "HugeThing.cs").write_text("class H { int q; }", encoding="utf-8")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("③ 未提交改動 → stale", j["stale"] is True, j["stale"])
        _sp.run(["git", "checkout", "-q", "--", "."], cwd=td, check=True)
        (root / "tests/NewTests.cs").write_text("// new", encoding="utf-8")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("③ 未追蹤新測試檔 → stale", j["stale"] is True, j["stale"])
        (root / "tests/NewTests.cs").unlink()
        # 24 CJK 存在性過濾不消失
        (root / "會員系統.cs").write_text("class W { int a; }", encoding="utf-8")
        g("add", "-A"); g("commit", "-q", "-m", "cjk change")
        _testmap_run(["testmap", "build", "--repo", td], td)
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("CJK 建議不消失", any(s["test"] == "tests/會員系統Tests.cs" for s in j["suggests"]),
              j["suggests"])
        # md 靜默
        (root / "docs/foo_test.md").write_text("# doc2", encoding="utf-8")
        g("add", "-A"); g("commit", "-q", "-m", "md only")
        _testmap_run(["testmap", "build", "--repo", td], td)
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("md 靜默(不進建議/uncovered)", j["suggests"] == [] and j["uncovered"] == [], j)
        # ⑤ map 有效僅 diff 失敗:map 欄照實
        r = _testmap_run(["testmap", "affected", "--diff", "nosuch..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("⑤ diff失敗 rc0+map欄照實", r.returncode == 0 and j["map_built_at"] is not None
              and j["suggests"] == [], j)
        # affected --repo 子目錄 → fail-open rc0
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD",
                          "--repo", str(root / "src"), "--json"], td)
        j = _json.loads(r.stdout)
        check("23 affected 子目錄 fail-open rc0", r.returncode == 0 and j["map_built_at"] is None,
              f"{r.returncode} {j}")


def t_testmap_rc():
    """[S1][S2] rc 矩陣+map 守衛(獨立函式防 expect_rc 首敗吞斷言)。"""
    import json as _json
    import subprocess as _sp
    import tempfile
    from pathlib import Path as _P
    EMPTY = {"map_built_at": None, "built_at_commit": None, "stale": False,
             "suggests": [], "uncovered": []}
    with tempfile.TemporaryDirectory() as td:
        r = _testmap_run(["testmap", "build", "--repo", td], td)
        check("build 非git rc2", r.returncode == 2, r.returncode)
        _sp.run(["git", "init", "-q"], cwd=td, check=True)
        r = _testmap_run(["testmap", "build", "--repo", td], td)
        check("build unborn rc2", r.returncode == 2, r.returncode)
    with tempfile.TemporaryDirectory() as td:
        g = _testmap_mk(td)
        root = _P(td)
        sub = root / "src"
        r = _testmap_run(["testmap", "build", "--repo", str(sub)], td)
        check("build 子目錄 rc2", r.returncode == 2, r.returncode)
        r = _testmap_run(["testmap", "build", "--repo", td], td)
        check("build 合法根(symlink /var 路徑)不誤擋 rc0", r.returncode == 0,
              f"{r.returncode} {r.stderr}")
        # 缺 --diff rc2;等號式 - 開頭 rc0+單行 json
        r = _testmap_run(["testmap", "affected", "--repo", td], td)
        check("affected 缺 --diff rc2", r.returncode == 2, r.returncode)
        r = _testmap_run(["testmap", "affected", "--diff=-abc", "--repo", td, "--json"], td)
        check("- 開頭 rc0 單行json", r.returncode == 0
              and _json.loads(r.stdout) == EMPTY, f"{r.returncode} {r.stdout!r}")
        mp = root / ".lumos" / "testmap.json"
        good = mp.read_text(encoding="utf-8")
        # 無 map
        mp.unlink()
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        check("無 map rc0+提示+null json", r.returncode == 0 and "build" in r.stderr
              and _json.loads(r.stdout) == EMPTY, f"{r.returncode} {r.stderr[:120]}")
        # 爛 JSON / edges 非 list / header 缺 / version≠1
        for bad, label in (("{oops", "爛JSON"),
                           ('{"version":1,"built_at_commit":"' + "a" * 40 + '","built_at":"x","edges":{}}', "edges非list"),
                           ('{"version":1,"edges":[]}', "header缺"),
                           ('{"version":2,"built_at_commit":"' + "a" * 40 + '","built_at":"x","edges":[]}', "version≠1"),
                           ('{"version":1,"built_at_commit":"XYZ!","built_at":"x","edges":[]}', "sha格式不符")):
            mp.write_text(bad, encoding="utf-8")
            r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
            check(f"壞map({label}) rc0+null", r.returncode == 0
                  and _json.loads(r.stdout)["map_built_at"] is None, f"{r.returncode} {r.stdout!r}")
        # 逐邊守衛:非dict/缺欄/conf越界/sources缺→[]
        m = _json.loads(good)
        m["edges"] = [17, {"src": "Card.cs"}, {"src": "Card.cs", "test": "tests/CardTests.cs", "conf": 999,
                                               "sources": ["naming"]},
                      {"src": "Card.cs", "test": "tests/CardTests.cs", "conf": True,
                       "sources": ["naming"]},
                      {"src": "Card.cs", "test": "tests/CardTests.cs", "conf": 0.9}]
        mp.write_text(_json.dumps(m, ensure_ascii=False), encoding="utf-8")
        (root / "Card.cs").write_text("class Card { int r; }", encoding="utf-8")
        _sp.run(["git", "-c", "user.email=t@t", "-c", "user.name=t", "commit", "-q", "-am", "c"],
                cwd=td, check=True)
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        sug = [s for s in j["suggests"] if s["test"] == "tests/CardTests.cs"]
        check("逐邊守衛:壞邊跳/好邊留 sources=[]", r.returncode == 0 and len(sug) == 1
              and sug[0]["conf"] == 0.9 and sug[0]["sources"] == [], f"{r.returncode} {j}")
        # map 為目錄 → 總兜底 rc0
        mp.unlink(); mp.mkdir()
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        check("map為目錄 rc0+null", r.returncode == 0
              and _json.loads(r.stdout)["map_built_at"] is None, f"{r.returncode} {r.stdout!r}")
        mp.rmdir()
        # 寫檔失敗:.lumos 換成檔案 → build rc2+json error
        import shutil
        shutil.rmtree(root / ".lumos")
        (root / ".lumos").write_text("x", encoding="utf-8")
        r = _testmap_run(["testmap", "build", "--repo", td, "--json"], td)
        check("寫檔失敗 rc2+json error", r.returncode == 2 and "error" in _json.loads(r.stdout),
              f"{r.returncode} {r.stdout!r}")


def t_slim_scan():
    """交付文字掃描器:五種懸空引用形態都要命中,保留指令不得誤報為移除指令。"""
    import tempfile as _tf
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimscan-"))
    scanner = str(_P(GRAPHCTL).parent / "slim-scan.py")

    f = root / "sample.md"
    f.write_text(
        "1 前綴型: 跑 `lumos pitfalls <md>` 掃隱患\n"
        "2 裸token型: 對抗審計 loop(`canary`/`refcheck`)\n"
        "3 skill型: 走 design-loop skill 打磨\n"
        "4 span帶參型: `loop status --gate` 問收斂\n"
        "5 裸散文型: canary 驗審計員醒著\n"
        "6 乾淨行: 用 `lumos search` 找節點\n",
        encoding="utf-8")

    r = subprocess.run([sys.executable, scanner, str(f), "--json"],
                       capture_output=True, text=True)
    check("slim-scan 有命中回 rc1", r.returncode == 1, r.stderr)
    import json as _j
    d = _j.loads(r.stdout)
    forms = {c["form"] for c in d["candidates"]}
    for want in ("prefixed", "bare-token", "skill-name", "span-with-args", "prose"):
        check(f"slim-scan 命中形態 {want}", want in forms, str(sorted(forms)))
    lines = {c["line"] for c in d["candidates"]}
    check("slim-scan 不誤報保留指令 search(第6行)", 6 not in lines, str(sorted(lines)))

    # 反事實:乾淨檔必須 rc0
    g = root / "clean.md"
    g.write_text("只提保留指令: `lumos search`、`lumos doctor`、`lumos guard list`\n",
                 encoding="utf-8")
    r2 = subprocess.run([sys.executable, scanner, str(g)], capture_output=True, text=True)
    check("slim-scan 乾淨檔 rc0", r2.returncode == 0, r2.stdout + r2.stderr)


