    txt = out.read_text(encoding="utf-8")
    check("迴圈註冊的 dropme 被砍出註冊清單", "'dropme'" not in txt and '"dropme"' not in txt, txt[:400])
    check("迴圈註冊的 keepme 仍在", "keepme" in txt, txt[:400])
