def _mk_eval_fixture():
    """標註刷新測試共用 fixture:tmp git repo+docs/kg-knowledge 小 vault+一支 code 檔。
    回 (root, goldset_dict)。goldset 手造三態:S01 Beta 已判1/Gamma 未標;
    E01 Alpha 已判0(不算未標)、其餘命中未標;E02 file-gone。"""
    root = Path(tempfile.mkdtemp(prefix="gctl-evalfx-")) / "repo"
    kg = root / "docs" / "kg-knowledge"
    for sub in ("Systems", "Projects"):
        (kg / sub).mkdir(parents=True)
    (root / "src").mkdir(parents=True)
    (root / "src" / "app.py").write_text("def zeb():\n    return 1\n", encoding="utf-8")
    (kg / "Systems" / "Alpha.md").write_text(
        "---\ntype: system\nstatus: done\n---\n# Alpha\n本模組實作在 `src/app.py`。\n", encoding="utf-8")
    (kg / "Systems" / "Beta.md").write_text(
        "---\ntype: system\nstatus: done\n---\n# Beta\nzebrafish 核心規則。\n", encoding="utf-8")
    (kg / "Projects" / "Gamma.md").write_text(
        "---\ntype: project\nstatus: doing\n---\n# Gamma\nzebrafish 排程計劃,關聯 `src/app.py`。\n", encoding="utf-8")
    import os
    env = {**os.environ, "GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@t.t",
           "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@t.t"}
    for cmd in (["git", "init", "-q"], ["git", "add", "-A"],
                ["git", "commit", "-qm", "init"]):
        subprocess.run(cmd, cwd=root, env=env, capture_output=True, text=True)
    gs = {"snapshot_commit": "deadbee", "split_salt": "x",
          "search": [{"id": "S01", "query": "zebrafish", "cat": "zh_short", "split": "held"}],
          "edit": [{"id": "E01", "file": "src/app.py", "delta": "(x)", "commit": "deadbee", "split": "held"},
                   {"id": "E02", "file": "src/gone.py", "delta": "(x)", "commit": "deadbee", "split": "held"}],
          "labels": {"S01": {"Systems/Beta.md": {"final": 1, "claude": 1, "codex": 1}},
                     "E01": {"Systems/Alpha.md": {"final": 0, "claude": 0, "codex": 0}}}}
    return root, gs


def _load_retrieval_eval(root):
    """以 fixture 為根載入 retrieval_eval 模組(獨立實例,不污染其他測試)。"""
    import importlib.util
    repo = Path(GRAPHCTL).resolve().parent.parent
    spec = importlib.util.spec_from_file_location(
        f"retrieval_eval_fx_{id(root)}", repo / "governance" / "eval" / "retrieval_eval.py")
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    m.ROOT = root
    m.VAULT = root / "docs" / "kg-knowledge"
    return m


def t_eval_universe_and_unjudged():
    """T2:共用原語——search_universe/edit_universe/collect_unjudged(三態判定唯一實作)。"""
    _need_src("governance/eval")
    root, gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    uni = m._touched_search(*m._search_arms("zebrafish"))
    check("計分觸及集含 Beta", "Systems/Beta.md" in uni, str(uni))
    check("計分觸及集含 Gamma", "Projects/Gamma.md" in uni, str(uni))
    e1 = m.edit_universe(gs["edit"][0])
    check("edit_universe 回結果列表且含 node 欄", isinstance(e1, list) and all("node" in x for x in e1), str(e1)[:200])
    check("edit_universe 命中 Alpha(inline-code 直連)", any(x["node"] == "Systems/Alpha.md" for x in e1), str(e1)[:300])
    check("edit_universe file-gone 回 None", m.edit_universe(gs["edit"][1]) is None, "")
    u = m.collect_unjudged(gs, "held")
    check("unjudged 回傳五鍵", set(u) >= {"per_case", "skipped", "denom", "count", "rate"}, str(u)[:200])
    check("S01:未標含 Gamma、不含已判 Beta",
          "Projects/Gamma.md" in u["per_case"].get("S01", []) and
          "Systems/Beta.md" not in u["per_case"].get("S01", []), str(u["per_case"]))
    check("E01:已判0 的 Alpha 不算未標", "Systems/Alpha.md" not in u["per_case"].get("E01", []), str(u["per_case"]))
    check("E02 file-gone 進 skipped", any(s.startswith("E02") for s in u["skipped"]), str(u["skipped"]))
    check("rate=count/denom 一致", u["denom"] > 0 and abs(u["rate"] - u["count"] / u["denom"]) < 1e-9, str(u))


def t_goldset_append():
    """★加題只加不碰既有★:append 新 edit 題,既有題目與 labels 必須一字不動。

    既有 labels 是累積數月的雙評審資產(build_goldset 裸跑防護就是為它立的)。
    加題如果動到既有,等於用一個「擴充」動作偷偷換尺。
    翻紅釘:把 append_edit_cases 改成重建 gs["edit"] → 第 1、2 條翻紅。"""
    _need_src("governance/eval")
    import importlib.util, json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    spec = importlib.util.spec_from_file_location(
        "build_goldset_fx2", repo / "governance" / "eval" / "build_goldset.py")
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)

    gs = {"edit": [{"id": "E01", "file": "a.py", "delta": "x", "split": "train"},
                   {"id": "E02", "file": "b.py", "delta": "y", "split": "held"}],
          "labels": {"E01": {"N1.md": {"final": 2}}, "E02": {"N2.md": {"final": 1}}},
          "search": [], "snapshot_commit": "abc"}
    before = _json.dumps(gs, sort_keys=True)

    new = [({"file": "c.py", "delta": "z", "commit": "s1"}, ["N3.md", "N4.md"]),
           ({"file": "a.py", "delta": "dup", "commit": "s2"}, ["N9.md"]),   # 已有 file → 該跳過
           ({"file": "d.py", "delta": "w", "commit": "s3"}, [])]            # 空池 → 該跳過
    out = m.append_edit_cases(gs, new)

    check("★既有兩題原封不動★", [e["id"] for e in out["edit"]][:2] == ["E01", "E02"],
          str(out["edit"])[:200])
    check("★既有 labels 一字不動★",
          out["labels"]["E01"] == {"N1.md": {"final": 2}} and out["labels"]["E02"] == {"N2.md": {"final": 1}},
          str(out["labels"])[:200])
    ids = [e["id"] for e in out["edit"]]
    check("新題接續編號 E03", "E03" in ids, str(ids))
    check("★重複 file 不重出題★", sum(1 for e in out["edit"] if e["file"] == "a.py") == 1, str(ids))
    check("★空池題不進卷★", not any(e["file"] == "d.py" for e in out["edit"]), str(ids))
    check("新題 labels 全是未標(等 delta 補)",
          all(v == {"final": None} for v in out["labels"]["E03"].values()), str(out["labels"].get("E03")))
    check("新題有分到 split", out["edit"][-1].get("split") in ("train", "held"), str(out["edit"][-1]))
    # 傳進來的 gs 不該被就地改壞(純函式紀律)
    check("★不就地竄改輸入★", _json.dumps(gs, sort_keys=True) == before, "輸入被改了")


def t_must_see_ratchet():
    """★must-see 棘輪★:必看項(標2)的個數不准比上一筆 PASS 少,少一個就紅。

    為什麼是棘輪不是門檻:定數字一定被問「為什麼 0.75 不是 0.8」,而且 held 不該反覆看。
    ★語意也對——標 2 的意思就是「必看」,掉一個就是缺陷,沒有「掉 20% 以內可接受」。★
    今天 21 個 must-see 只有 7 個坐固定席、14 個靠排序撐;棘輪正好守這個:
    排序一動把某個 must-see 擠出前 k,立刻紅。

    ★對照列要同 goldset_rev★:換尺(補標/加題→labels 變)那一刻舊個數不能拿來比,
    否則會拿舊尺的數字擋新尺,變成恆紅。
    翻紅釘:把 must_ratchet 改成恆回 (True, "") → 第 2 條翻紅。"""
    _need_src("governance/eval")
    import json as _json
    root, gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)

    rev = m.goldset_rev(gs)
    check("rev 是穩定短 hash", isinstance(rev, str) and 6 <= len(rev) <= 16, rev)
    gs2 = _json.loads(_json.dumps(gs)); gs2["labels"].setdefault("S01", {})["新節點.md"] = {"final": 2}
    check("★labels 一變 rev 就變(換尺看得出來)★", m.goldset_rev(gs2) != rev, f"{rev} vs {m.goldset_rev(gs2)}")

    hist = [{"pass": True, "goldset_rev": rev, "verdicts": {"train": {"must_in_out_count": 10}}}]
    ok, msg = m.must_ratchet(hist, rev, "train", 9)
    check("★退步一個就擋★", ok is False and "10" in msg and "9" in msg, f"ok={ok} msg={msg}")
    ok2, _ = m.must_ratchet(hist, rev, "train", 10)
    check("持平放行", ok2 is True)
    ok3, _ = m.must_ratchet(hist, rev, "train", 12)
    check("進步放行", ok3 is True)
    ok4, msg4 = m.must_ratchet(hist, "別的rev", "train", 1)
    check("★換尺後不拿舊數字比(否則恆紅)★", ok4 is True and ("基線" in msg4 or "首次" in msg4), msg4)
    ok5, msg5 = m.must_ratchet([], rev, "train", 1)
    check("★沒有歷史時放行並註明建立基線★", ok5 is True and msg5 != "", msg5)
    hist_fail = [{"pass": False, "goldset_rev": rev, "verdicts": {"train": {"must_in_out_count": 99}}}]
    ok6, _ = m.must_ratchet(hist_fail, rev, "train", 1)
    check("★只拿 PASS 的當基線(FAIL 輪的數字不算數)★", ok6 is True)


def t_build_goldset_junk_filter():
    """★出卷器不准撿垃圾★:dotfile / vendor 壓縮檔選進 edit 題 = 候選池空 = 廢題。

    2026-08-22 實測:既有 20 題裡 4 題是廢題(E01 .gitignore、E11 governance/.gitignore、
    E16 vendor/3d-force-graph.min.js、E17 vendor/marked.min.js),候選池全空、labels 無鍵、
    eval 直接跳過 → train 名義 8 實際 6、held 名義 12 實際 10。
    ★所謂「樣本太小」有一半是出卷器的 git-log 掃法撿到垃圾,不是題庫真的小。★
    翻紅釘:把 _is_junk_edit_file 改成恆回 False → 前兩條翻紅。"""
    _need_src("governance/eval")
    import importlib.util
    repo = Path(GRAPHCTL).resolve().parent.parent
    spec = importlib.util.spec_from_file_location(
        "build_goldset_fx", repo / "governance" / "eval" / "build_goldset.py")
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    j = m._is_junk_edit_file
    check("dotfile 排除(.gitignore)", j(".gitignore") is True)
    check("巢狀 dotfile 也排除", j("governance/.gitignore") is True)
    check("vendor 壓縮檔排除", j("scripts/vendor/marked.min.js") is True)
    check("任何 vendor/ 底下都排除", j("vendor/x.js") is True)
    check("★正常 code 檔不排除★", j("scripts/lumos") is False)
    check("★正常 py 不排除★", j("governance/eval/retrieval_eval.py") is False)
    check("★.min.js 但不在 vendor 也排除(壓縮檔沒有可讀 delta)★", j("web/app.min.js") is True)

    # ★裸跑防護不准被拿掉★:全量重建會清空累積數月的人工標註(2026-08-18 立)。
    # 這條釘死「沒帶 --force-full 就非 0 退出」,免得日後有人為了方便把它拔了。
    r = subprocess.run([sys.executable, str(repo / "governance" / "eval" / "build_goldset.py")],
                       capture_output=True, text=True, cwd=str(repo))
    check("★裸跑 build_goldset 必須擋(否則會清空既有標註)★", r.returncode != 0,
          f"rc={r.returncode} out={r.stdout[:150]}")
    check("擋下時要說得出替代路徑", "refresh_labels" in (r.stdout + r.stderr), (r.stdout + r.stderr)[:200])


def t_eval_ablation_gate():
    """★消融前置閘★:有未標候選就擋,免得「尺的偏見」被讀成「改動有害」。

    2026-08-22 真的踩過:一個檢索改動讓 edit train 未標從 4→9,多出的 5 個全計 0,
    分母才 48 → -5.4%,當時被讀成「改動有害」並據此撤回;實際是尺對「改善」有系統性
    偏見(改善→浮出新節點→沒標過→計 0→被罰)。
    ★本閘維持零容忍★——「不改尺」裁定 2026-08-26 已被翻(condensed 主尺上路,詳
    Projects/評測尺翻案_計劃),但本閘是 08-22 事故的根源修補,[S3c(反轉原裁)] 明裁
    不退場:condensed 不改變「消融結論要池完整才可下」。
    翻紅釘:把 ablation_blocked 改成恆回 False → 第 1、2 條翻紅。"""
    _need_src("governance/eval")
    root, gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)

    blocked, n, msg = m.ablation_blocked(gs, "held")
    check("有未標 → 擋", blocked is True and n > 0, f"blocked={blocked} n={n}")
    check("訊息講得出補標指令", "refresh_labels.py delta" in msg, msg[:200])
    check("★訊息要說清楚為什麼不能比★", "不是改動的效果" in msg or "尺的偏見" in msg, msg[:200])

    # 把該 split 觸及集全部標掉 → 應放行
    u = m.collect_unjudged(gs, "held")
    for cid, nodes in u["per_case"].items():
        gs["labels"].setdefault(cid, {})
        for nd in nodes:
            gs["labels"][cid][nd] = {"final": 0}
    blocked2, n2, _ = m.ablation_blocked(gs, "held")
    check("★補標後放行(閘會收斂,不是恆擋)★", blocked2 is False and n2 == 0, f"blocked={blocked2} n={n2}")


def t_eval_condensed_core():
    """評測尺翻案 [S1]/[S2]/[S3b]:condensed 於已判子列表計分、題級門檻、三方未標集合同源、
    pin_noise 三態語意不變。翻紅釘:把 _condense 的剔除改回「未標=0」→ 第 2 條翻紅。"""
    _need_src("governance/eval")
    root, gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    # search:窗內 [未標,未標,判2,判1](spec 驗證計劃修正後的例)
    gs["search"] = [{"id": "S01", "query": "zzz", "cat": "zh_short", "split": "held"}]
    # 10 節點窗、6 判(≥ceil(10/2)=5 過題級門檻):前兩名未標——spec 例的門檻合規版
    gs["labels"]["S01"] = {"Systems/B.md": {"final": 2}, "Systems/C.md": {"final": 1},
                           "Systems/D.md": {"final": 1}, "Systems/E.md": {"final": 0},
                           "Systems/F.md": {"final": 0}, "Systems/G.md": {"final": 0}}
    order = ["Systems/U1.md", "Systems/U2.md", "Systems/B.md", "Systems/C.md", "Systems/D.md",
             "Systems/E.md", "Systems/F.md", "Systems/G.md", "Systems/U3.md", "Systems/U4.md"]
    m._search_arms = lambda q: (list(order), list(order))
    rows = m.eval_search(gs, "held", k=2)
    r = rows[0]
    check("舊尺 nDCG@2:前兩名全未標→0.0(行為不變)", r["ranked_ndcg"] == 0.0, str(r))
    check("condensed nDCG@2=1.0(已判子列表 判2判1 領頭)", r["c_ranked_ndcg"] == 1.0, str(r))
    check("condensed MRR@10=1.0(第一個已判即相關)", r["c_ranked_mrr"] == 1.0, str(r))
    check("題級覆蓋率=6/10", r["ranked_cov"] == 0.6, str(r))
    # 三方集合同源([S1]①):condensed 剔除的=collect_unjudged 該題回報的
    unj = m.collect_unjudged(gs, "held")
    lab = m._labels_of(gs, "S01")
    dropped = {n for n in order if n not in lab}
    check("condensed 剔除集==collect_unjudged 未標集(同源斷言)",
          dropped == set(unj["per_case"].get("S01", [])), f"{dropped} vs {unj['per_case']}")
    # 題級門檻([S2]①):8 節點窗只判 1 個 < ceil(SEARCH_TOUCH/2)=5 → None 不進 macro(外家 1/8 抬分反例;門檻吃配置 k=10,r2 觀察修註)
    gs["labels"]["S01"] = {"Systems/B.md": {"final": 2}}
    big = [f"Systems/X{i}.md" for i in range(7)] + ["Systems/B.md"]
    m._search_arms = lambda q: (list(big), list(big))
    rows2 = m.eval_search(gs, "held", k=2)
    check("低覆蓋題(1/8)condensed 記 None", rows2[0]["c_ranked_ndcg"] is None, str(rows2[0]))
    check("低覆蓋題不進 macro(_macro 濾 None)", m._macro(rows2, "c_ranked_ndcg") is None, "")
    check("低覆蓋題舊尺照算(雙報期 gate 仍有值)", rows2[0]["ranked_ndcg"] is not None, str(rows2[0]))
    # s1-f3 釘:門檻用「配置窗寬 k」不是「窗實際長度」——候選只回 2 篇全已判,
    # 照 spec ceil(10/2)=5 仍不足 → None(len(window) 算法會誤判有效)
    gs["labels"]["S01"] = {"Systems/B.md": {"final": 2}, "Systems/C.md": {"final": 1}}
    m._search_arms = lambda q: (["Systems/B.md", "Systems/C.md"], ["Systems/B.md", "Systems/C.md"])
    rows3 = m.eval_search(gs, "held", k=2)
    check("短候選(2 篇全判<ceil(10/2))仍記 None(門檻吃配置 k 不吃窗長)",
          rows3[0]["c_ranked_ndcg"] is None, str(rows3[0]))
    # _labels_of 已判-only + 未標 pins 的 pin_noise([S1]④/[S3b]:fixture 強制含未標 pin)
    lab2 = m._labels_of(gs, "S01")
    check("_labels_of 不含未標鍵(已判-only)", "Systems/X0.md" not in lab2 and "Systems/B.md" in lab2, str(lab2))
    fake_pins = [{"node": "Systems/B.md"}, {"node": "Systems/未標席.md"}, {"node": "Systems/判零.md"}]
    lab3 = {"Systems/B.md": 2, "Systems/判零.md": 0}
    noise = sum(1 for x in fake_pins if x["node"] not in lab3 or lab3[x["node"]] == 0)
    check("pin_noise 三態:未標席+判0 席=2 條噪音(語意不隨 condensed 動)", noise == 2, str(noise))
    print("  ✓ t_eval_condensed_core")


def t_eval_condensed_switch():
    """評測尺翻案 [S3]:sticky metric_rev/恆等斷言/棘輪雙鍵+切換輪繼承。
    翻紅釘:_ratchet_base 拿掉 inherit 分支 → 第 4 條翻紅。"""
    _need_src("governance/eval")
    root, _gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    check("sticky:無 metric_rev 列→None", m._history_metric_rev([{"pass": True}]) is None, "")
    check("sticky:任一列帶→condensed-v1",
          m._history_metric_rev([{"metric_rev": "condensed-v1"}, {"pass": True}]) == "condensed-v1", "")
    hist = [{"pass": True, "goldset_rev": "aaa", "verdicts": {"all": {"must_in_out_count": 5, "pin_noise": 2}}}]
    ok, msg = m.must_ratchet(hist, "aaa", "all", 4, metric_rev="condensed-v1", inherit=True)
    check("切換輪繼承舊尺基線:5→4 被擋", ok is False and "繼承" in msg, f"{ok} {msg[:80]}")
    ok2, _ = m.must_ratchet(hist, "aaa", "all", 4, metric_rev="condensed-v1", inherit=False)
    check("非切換輪不繼承:無同鍵基線→放行建基線", ok2 is True, "")
    ok3, _ = m.pin_noise_ratchet(hist, "aaa", "all", 3, metric_rev="condensed-v1", inherit=True)
    check("噪音棘輪繼承:2→3 被擋", ok3 is False, "")
    # 恆等斷言:同值過/異值列差
    # ★2026-09-15 起恆等斷言吃限縮鍵 _*_eq(限縮到新尺也認可的題),不吃全題平均 _*_raw★
    # ——後者會讓兩組不同題目的平均互比,未標歸零也永遠不等(Issues/尺切換恆等斷言反覆不過 原因一)
    v = {"_rn_eq": 0.8, "_ln_eq": 0.4, "_fp_eq": 0.75, "_bp_eq": 0.5, "_gp_eq": 0.25,
         "condensed_search": {"ndcg": 0.8, "ndcg_legacy": 0.4},
         "condensed_edit": {"p": 0.75, "bm25_p": 0.5, "graph_p": 0.25}}
    eq, diffs = m._switch_equal(v)
    check("恆等斷言:全尺同值→過", eq is True and diffs == [], str(diffs))
    v["condensed_edit"]["p"] = 0.9
    eq2, diffs2 = m._switch_equal(v)
    check("恆等斷言:有差→列名不過(切換中止)", eq2 is False and any("fusion" in d for d in diffs2), str(diffs2))
    # code-r1 折修釘:beats 模組層可呼且 None 安全(s1-f1/f2);gate 門檻唯一實作+weak 語意(arch-f1)
    check("beats 模組層+None 安全(弱證據=判 False 不炸)",
          m.beats(None, 1, 1, 1) is False and m.beats(0.8, 0.8, 0.5, 0.5) is True, "")
    check("search gate helper:weak=不轉綠", m._search_gate_ok(20.0, 0.5, weak=True) is False
          and m._search_gate_ok(20.0, 0.5) is True, "")
    check("hook gate helper:None/weak=不轉綠", m._hook_gate_ok(None) is False
          and m._hook_gate_ok(0.75, weak=True) is False and m._hook_gate_ok(0.75) is True, "")
    print("  ✓ t_eval_condensed_switch")


def t_eval_switch_equal_same_question_set():
    """尺切換恆等斷言要比對「同一組題」(Issues/尺切換恆等斷言反覆不過 原因一)。

    症狀:新尺的題級門檻把候選不足的題整題丟出分母、舊尺照算,於是兩邊拿
    ★不同題目集算出來的平均★在比相不相等,永遠不等。2026-09-15 實跑重現:
    未標=0 但五組全不等;消融掉門檻後三組立刻相等。
    ★2026-09-15 收斂 r2 起改成從同一個交集算★:原本用一個 gate_key 逐鍵限縮,
    但顯示/閘門值改成取「各臂都有效」的交集之後,兩邊又變成不同批題;現在恆等鍵與
    被驗的新尺值一律從同一個子集算,同批題是結構保證。逐鍵限縮那支輔助函式已無人用、已刪。
    翻紅釘:把兩側同時無資料的分支改回 continue → 第 4 條翻紅。"""
    _need_src("governance/eval")
    root, _gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    # 三題:第三題被新尺判無效(c_* 是 None),舊尺照算
    rows = [{"ranked_ndcg": 0.9, "c_ranked_ndcg": 0.9},
            {"ranked_ndcg": 0.7, "c_ranked_ndcg": 0.7},
            {"ranked_ndcg": 0.1, "c_ranked_ndcg": None}]
    check("_macro 全算(含新尺丟掉的題)", m._macro(rows, "ranked_ndcg") == 0.5667,
          str(m._macro(rows, "ranked_ndcg")))
    _al = [r for r in rows if r.get("c_ranked_ndcg") is not None]
    check("★限縮到新尺也認可的題之後才是 0.8★", m._macro(_al, "ranked_ndcg") == 0.8,
          str(m._macro(_al, "ranked_ndcg")))
    check("★逐鍵限縮那支輔助函式已刪,不留死碼★", not hasattr(m, "_macro_on"),
          "還在=沒人用卻留著,而且它的測試會製造「有覆蓋」的假象")
    # 恆等斷言吃的是限縮後的值
    v = {"_rn_eq": 0.8, "_ln_eq": 0.4, "_fp_eq": 0.75, "_bp_eq": 0.5, "_gp_eq": 0.25,
         "condensed_search": {"ndcg": 0.8, "ndcg_legacy": 0.4},
         "condensed_edit": {"p": 0.75, "bm25_p": 0.5, "graph_p": 0.25}}
    eq, diffs = m._switch_equal(v)
    check("限縮後同值→恆等過", eq is True and diffs == [], str(diffs))
    v["condensed_edit"]["bm25_p"] = 0.9
    eq2, d2 = m._switch_equal(v)
    check("限縮後仍有差→照樣不過", eq2 is False and any("bm25" in x for x in d2), str(d2))
    check("★缺限縮鍵不得靜默當相等★", m._switch_equal({"condensed_search": {"ndcg": 0.8}})[0] is False, "")
    print("  ✓ t_eval_switch_equal_same_question_set")


def t_eval_touched_edit_covers_all_arms():
    """未標檢查要涵蓋三條排法各自的前 k(Issues/尺切換恆等斷言反覆不過 原因二)。

    症狀:edit 面用綜合/只比文字/只比圖三種排法各自截前 k 算分,但未標判定
    只看綜合那一條的前 k,另外兩條視窗裡的未標永遠不會被判定為未標、補標
    流程也碰不到 → 檢查說「未標=0」而那兩條其實有未標。
    翻紅釘:把 _touched_edit 改回只取 free[:k] → 第 2、3 條翻紅。"""
    _need_src("governance/eval")
    root, _gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    # 綜合分數高的在前;只比文字(L)與只比圖(in_deg)各有自己的贏家
    # 只比圖那條看的是 kind/hop(直接關聯=1.0,間接照 hop 衰減),不是入度
    res = [{"node": "A.md", "score": 0.9, "L": 0.1, "kind": "indirect", "hop": 3},
           {"node": "B.md", "score": 0.8, "L": 0.2, "kind": "indirect", "hop": 3},
           {"node": "C.md", "score": 0.1, "L": 0.9, "kind": "indirect", "hop": 3},   # 只比文字的第一名
           {"node": "D.md", "score": 0.05, "L": 0.0, "kind": "direct"}]              # 只比圖的第一名
    touched = m._touched_edit(res, k=2)
    check("綜合前 2 名在", "A.md" in touched and "B.md" in touched, str(touched))
    check("★只比文字的前 2 名也要在★", "C.md" in touched, str(touched))
    check("★只比圖的前 2 名也要在★", "D.md" in touched, str(touched))
    check("不重複", len(touched) == len(set(touched)), str(touched))
    # 固定席與參考道照舊全納入
    res2 = res + [{"node": "P.md", "score": 0.0, "pinned": True},
                  {"node": "L.md", "score": 0.0, "lane": "soft-guard"}]
    t2 = m._touched_edit(res2, k=1)
    check("固定席與參考道仍全納入", "P.md" in t2 and "L.md" in t2, str(t2))
    print("  ✓ t_eval_touched_edit_covers_all_arms")


def t_eval_edit_orders_single_source():
    """edit 面三條排法只有一份實作,未標判定與算分共用(code-r1 四席獨立命中)。

    出身:r1 外家/正確性/合約圖譜/架構對齊四席各自用不同反例命中同一件事——
    _touched_edit 把排序鍵複製了一份,而且複製當下就抄錯:綜合臂沿用上游順序
    (上游是 (-score, hop, node) 三鍵、rescued 又排在 free 之後),算分卻是
    (-score, node) 兩鍵,同分不同 hop 或被救回的候選會落在計分窗內卻不在觸及集。
    架構席另指出這違反本檔自己的「唯一實作」禁令。
    ★本測試釘的是「同一份輸入,兩邊算出的前 k 必須一致」——不是比對原始碼文字★。
    翻紅釘:讓 _touched_edit 的綜合臂改回沿用上游順序 → 第 2 條翻紅。"""
    _need_src("governance/eval")
    root, _gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    check("★排序鍵有單一來源 _edit_orders★", hasattr(m, "_edit_orders"), "兩邊各寫一份=會無聲漂移")
    # 同分不同 hop + rescued:四席反例的共同形狀
    res = [{"node": "B.md", "score": 0.7, "L": 0.1, "kind": "direct"},
           {"node": "A.md", "score": 0.7, "L": 0.2, "kind": "indirect", "hop": 1},
           {"node": "C.md", "score": 0.66, "L": 0.9, "kind": "indirect", "hop": 3}]
    for k in (1, 2, 3):
        touched = set(m._touched_edit(res, k=k))
        for name, order in m._edit_orders(res).items():
            top = {x["node"] for x in order[:k]}
            check(f"★k={k} {name} 的計分前 k 全在觸及集裡★", top <= touched,
                  f"漏掉 {sorted(top - touched)}(觸及集 {sorted(touched)})")
    # ★缺 score 要炸,不准靜默給 0★(2026-09-15 code-r3 正確性席折入):
    # 給預設值會把上游格式漂移變成靜默走樣,而這個排序決定的是驅動不可逆切換的視窗。
    # 翻紅釘:把 fusion 那條排序鍵改回 x.get("score", 0.0) → 這條翻紅。
    _bad = [{"node": "Z.md", "L": 0.1, "kind": "direct"}]   # 自由候選但沒有 score
    try:
        m._edit_orders(_bad)
        _raised = False
    except KeyError:
        _raised = True
    check("★自由候選缺 score 時排序要直接炸,不得靜默當 0★", _raised,
          "給了預設值=上游格式漂移會悄悄走樣,而這個視窗餵的是不可逆的尺切換判定")
    print("  ✓ t_eval_edit_orders_single_source")


def t_eval_switch_equal_no_data_is_not_equal():
    """兩側同時沒有可比資料時不得判恆等(code-r1 邊界席+正確性席獨立命中)。

    出身:限縮鍵與新尺值是對同一批列取平均,分母集合完全相同,所以沒有任何一題
    通過題級門檻時★兩邊必定同時變 None★;而恆等斷言對 (None, None) 是 continue,
    等於把「完全沒有可比資料」當成「經檢驗恆等」放行切換——★比舊寫法還寬鬆★
    (舊的全題平均幾乎必為非 None,同情境會被判有 vs 無而擋下)。
    翻紅釘:把 _switch_equal 對兩側皆 None 的處理改回 continue → 第 1、3、4 條翻紅(實測 3 條)。"""
    _need_src("governance/eval")
    root, _gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    v_none = {"_rn_eq": None, "_ln_eq": None, "_fp_eq": None, "_bp_eq": None, "_gp_eq": None,
              "condensed_search": {"ndcg": None, "ndcg_legacy": None},
              "condensed_edit": {"p": None, "bm25_p": None, "graph_p": None}}
    eq, diffs = m._switch_equal(v_none)
    check("★五個指標全無資料→不得判恆等★", eq is False and len(diffs) >= 1, f"{eq} {diffs}")
    # 訊息要講得出「不是數值不同,是根本沒得比」——驗語意不驗特定措辭
    check("差異訊息要區分得出「沒得比」與「值不同」",
          all("vs" not in d for d in diffs) and all("資料" in d for d in diffs), str(diffs))
    check("五個指標一條都不漏", len(diffs) == 5, str(diffs))
    # 部分無資料也不行
    v_part = dict(v_none); v_part.update({"_rn_eq": 0.8, "_ln_eq": 0.4, "_fp_eq": 0.75})
    v_part["condensed_search"] = {"ndcg": 0.8, "ndcg_legacy": 0.4}
    v_part["condensed_edit"] = {"p": 0.75, "bm25_p": None, "graph_p": None}
    eq2, d2 = m._switch_equal(v_part)
    check("★部分指標無資料也不得判恆等★", eq2 is False, str(d2))
    # 有資料且相等才算過(反向對照:證明上面不是靠改到永遠 False 換來的)
    v_ok = {"_rn_eq": 0.8, "_ln_eq": 0.4, "_fp_eq": 0.75, "_bp_eq": 0.5, "_gp_eq": 0.25,
            "condensed_search": {"ndcg": 0.8, "ndcg_legacy": 0.4},
            "condensed_edit": {"p": 0.75, "bm25_p": 0.5, "graph_p": 0.25}}
    check("反向對照:有資料且相等仍要判過", m._switch_equal(v_ok)[0] is True, "")
    print("  ✓ t_eval_switch_equal_no_data_is_not_equal")


def t_eval_eq_keys_are_wired_in():
    """限縮鍵有沒有真的被接上報告流程(code-r1 測試品質席 blocker)。

    出身:變異測試證明——把 report_goldset 裡五處賦值從限縮子集改回全題平均
    (函式本體不動),★82 支評測測試全綠★:本次修的缺陷若被撤回,沒有任何測試會發現。
    原因是舊測試只驗函式本身會不會算,不驗它有沒有被接上。
    ★本測試把受控的 rows 餵進真實的 report_goldset,驗它吐出來的 verdict★——
    改回全題平均時 _rn_eq 會從 0.8 變成 0.5667,直接翻紅。
    翻紅釘:把 report_goldset 裡五處恆等鍵改回 _macro(srows/erows) → 第 2、3、4 條翻紅
    (第 4 條也會紅:舊鍵與被改壞的限縮鍵變得相等;實測 3 條)。"""
    _need_src("governance/eval")
    root, _gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    # 第三題被新尺判無效(c_* 是 None):限縮=前兩題平均 0.8,全題=0.5667
    srows = [{"ranked_ndcg": 0.9, "c_ranked_ndcg": 0.9, "legacy_ndcg": 0.8, "c_legacy_ndcg": 0.8,
              "ranked_mrr": 1.0, "legacy_mrr": 1.0, "ranked_r10": 1.0, "legacy_r10": 1.0, "ranked_cov": 1.0},
             {"ranked_ndcg": 0.7, "c_ranked_ndcg": 0.7, "legacy_ndcg": 0.6, "c_legacy_ndcg": 0.6,
              "ranked_mrr": 1.0, "legacy_mrr": 1.0, "ranked_r10": 1.0, "legacy_r10": 1.0, "ranked_cov": 1.0},
             {"ranked_ndcg": 0.1, "c_ranked_ndcg": None, "legacy_ndcg": 0.1, "c_legacy_ndcg": None,
              "ranked_mrr": 0.0, "legacy_mrr": 0.0, "ranked_r10": 0.0, "legacy_r10": 0.0, "ranked_cov": 0.1}]
    _orig_s, _orig_e = m.eval_search, m.eval_edit
    try:
        m.eval_search = lambda gs, split=None, k=5: srows
        m.eval_edit = lambda gs, split=None, k=8: []
        _rep = m.report_goldset({"search": [], "edit": [], "labels": {}}, split=None)
    finally:
        m.eval_search, m.eval_edit = _orig_s, _orig_e
    v = _rep.get("verdict", _rep)   # 報告回外層包裝,判定在 verdict 鍵
    check("前置:報告流程有吐出限縮鍵", "_rn_eq" in v, str(sorted(v))[:200])
    check("★_rn_eq 是限縮值 0.8,不是全題平均 0.5667★", v.get("_rn_eq") == 0.8,
          f"拿到 {v.get('_rn_eq')}(全題平均會是 {m._macro(srows, 'ranked_ndcg')})")
    check("★_ln_eq 同理是 0.7 不是 0.5★", v.get("_ln_eq") == 0.7,
          f"拿到 {v.get('_ln_eq')}(全題平均會是 {m._macro(srows, 'legacy_ndcg')})")
    check("舊鍵仍是全題平均(兩者確實不同,證明這顆資料分得出來)",
          v.get("_rn_raw") == m._macro(srows, "ranked_ndcg") and v["_rn_raw"] != v["_rn_eq"], "")
    print("  ✓ t_eval_eq_keys_are_wired_in")

def t_eval_cross_arm_same_question_set():
    """★跨臂比較前要先對齊題目集★(2026-09-15 code-收斂 r1 正確性席 major)。

    出身:題級門檻用的是★配置的視窗寬度★(搜尋面固定 10)算出來的 5,不是那一題實際
    抓回幾個候選;而舊排序沒有數量上限、新排序明確只取前 10,同一題兩邊抓回的候選數
    天生不一樣。於是一題可能★在新排序那臂有效、在舊排序那臂無效★——就算整體未標=0。
    提升率原本拿兩個各自過濾的平均相除,等於★兩批不同題目在比★,實測可灌水一倍。
    切換之後 search 提升、held-out 不倒退、綜合勝只比文字、綜合勝只比圖,共四道閘
    直接吃這些值,而恆等斷言只管同一臂內新舊尺一致,完全攔不到這種跨臂落差。

    翻紅釘:把 search 或 edit 的 condensed 聚合改回各臂各自 _macro → 第 2 或第 4 條翻紅。"""
    _need_src("governance/eval")
    root, gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    # 造三題:①兩臂都有效 ②只有新排序有效(舊排序候選太少) ③只有舊排序有效
    srows = [
        {"id": "S1", "split": "held", "legacy_ndcg": 0.4, "ranked_ndcg": 0.6, "legacy_mrr": 0.4, "ranked_mrr": 0.6,
         "legacy_r10": 1, "ranked_r10": 1, "ranked_cov": 1.0,
         "c_legacy_ndcg": 0.4, "c_ranked_ndcg": 0.6, "c_ranked_mrr": 0.6, "c_ranked_r10": 1},
        {"id": "S2", "split": "held", "legacy_ndcg": 0.9, "ranked_ndcg": 0.9, "legacy_mrr": 0.9, "ranked_mrr": 0.9,
         "legacy_r10": 1, "ranked_r10": 1, "ranked_cov": 1.0,
         "c_legacy_ndcg": None, "c_ranked_ndcg": 0.9, "c_ranked_mrr": 0.9, "c_ranked_r10": 1},
        {"id": "S3", "split": "held", "legacy_ndcg": 0.8, "ranked_ndcg": 0.8, "legacy_mrr": 0.8, "ranked_mrr": 0.8,
         "legacy_r10": 1, "ranked_r10": 1, "ranked_cov": 1.0,
         "c_legacy_ndcg": 0.8, "c_ranked_ndcg": None, "c_ranked_mrr": None, "c_ranked_r10": None},
    ]
    def _e(fp, bp, gp, cfp, cbp, cgp):
        return {"id": "E", "split": "held", "n_free": 8, "n_pin": 0,
                "must_total": 1, "must_in_out": 1, "must_pinned": 1, "pin_noise": 0,
                "fusion_p": fp, "bm25_p": bp, "graph_p": gp, "out_top3_must": 1.0,
                "fusion_ndcg": fp, "bm25_ndcg": bp, "graph_ndcg": gp, "fusion_cov": 1.0,
                "c_fusion_p": cfp, "c_bm25_p": cbp, "c_graph_p": cgp,
                "c_fusion_ndcg": cfp, "c_bm25_ndcg": cbp, "c_graph_ndcg": cgp}
    erows = [_e(0.5, 0.4, 0.3, 0.5, 0.4, 0.3),      # 三臂都有效
             _e(0.9, 0.1, 0.1, 0.9, None, None),    # 只有綜合臂有效
             _e(0.2, 0.9, 0.9, None, 0.9, 0.9)]     # 綜合臂無效
    m.eval_search = lambda _gs, _sp=None, **kw: srows
    m.eval_edit = lambda _gs, _sp=None, **kw: erows
    import io, contextlib
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        rep = m.report_goldset(gs, None, k_edit=8)
    cs, ce = rep["verdict"]["condensed_search"], rep["verdict"]["condensed_edit"]
    check("★search:兩臂的提升率只能拿兩邊都有效的題來算★",
          cs["valid_n"] == 1 and abs(cs["lift_pct"] - 50.0) < 0.05,
          f"valid_n={cs['valid_n']} lift={cs['lift_pct']}——各自過濾會得到 2 題與 25.0%")
    check("search:兩臂的平均要出自同一題(舊 0.4 / 新 0.6)",
          cs["ndcg_legacy"] == 0.4 and cs["ndcg"] == 0.6,
          f"舊={cs['ndcg_legacy']} 新={cs['ndcg']}")
    check("★edit:三臂互比前要對齊到三臂都有效的題★",
          ce["valid_n"] == 1 and ce["p"] == 0.5 and ce["bm25_p"] == 0.4 and ce["graph_p"] == 0.3,
          f"valid_n={ce['valid_n']} 綜合={ce['p']} 只比文字={ce['bm25_p']} 只比圖={ce['graph_p']}")
    check("edit:對齊後綜合臂仍勝過另外兩臂(沒有因為對齊而翻盤)",
          rep["verdict"]["fusion_vs_bm25"] is not None, "")
    # ★恆等斷言用的那組值,要跟它要驗的那組值出自同一批題★
    # (2026-09-15 收斂 r2 資安席:r1 把顯示/閘門值改成取交集,卻沒同步改恆等鍵,
    #  於是兩邊拿不同批題目——方向偏保守(誤判不相等擋下切換),但仍是折入引進的反向錯)
    v = rep["verdict"]
    check("★search 恆等鍵與它要比的新尺值同批題★",
          v["_rn_eq"] == 0.6 and v["_ln_eq"] == 0.4,
          f"_rn_eq={v['_rn_eq']} _ln_eq={v['_ln_eq']}——單臂過濾會得到 0.75/0.6(兩題)")
    check("★edit 三條恆等鍵也同批題★",
          v["_fp_eq"] == 0.5 and v["_bp_eq"] == 0.4 and v["_gp_eq"] == 0.3,
          f"{v['_fp_eq']}/{v['_bp_eq']}/{v['_gp_eq']}——單臂過濾會混進只有該臂有效的題")
    check("恆等斷言拿這組值判定時不會因為分母不同而誤判不相等",
          m._switch_equal(v)[0] is True, f"差異:{m._switch_equal(v)[1]}")
    print("  ✓ t_eval_cross_arm_same_question_set")


def _src_of(mod, needle):
    """數 needle 在模組原始碼裡出現幾次,跳過檔頭說明段(那裡提到檔名是敘述不是路徑)。"""
    import inspect
    lines = inspect.getsource(mod).split("\n")
    body = lines[1:] if lines and lines[0].startswith('"""') else lines
    start = 0
    for i, l in enumerate(body[:40]):
        if l.strip().endswith('"""') and i > 0:
            start = i + 1
            break
    return sum(1 for l in body[start:] if needle in l)


def t_eval_unjudged_check_honours_cli_k():
    """★不可逆的尺切換閘,它的未標檢查必須跟計分用同一個視窗★(code-r3 delta 回歸席)。

    出身:計分走 report_goldset(gs, sp, k_edit=args.k),消融閘走 ablation_blocked(..., k=args.k),
    唯獨切換判定那處呼叫 collect_unjudged 時★沒把 args.k 傳下去★,永遠用預設 8。
    帶 -k 12 跑時,第 9-12 名裡的未標候選會算進分數、卻不在未標檢查的視野內,
    於是「未標=0」可能是假的,而切換★切了不回頭★——這正是本分支要堵的漏洞的鏡像版本。
    現況不會觸發(唯一的生產呼叫點不帶 -k),但那是運氣不是守衛。
    翻紅釘(條號為實測值,2026-09-15 收斂 r1 測試品質席逐條核對):
      ①把那兩處的 k=args.k 拿掉 → ★第 4 條★翻紅(觀察到的視窗出現 8);前三條照樣過
      ②把歷史帳導向拿掉 → 前置直接擋下,根本不會跑到 main。"""
    _need_src("governance/eval")
    import io, contextlib, os, json as _json
    root, gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    p = root / "gs-k.json"
    p.write_text(_json.dumps(gs), encoding="utf-8")
    seen = []
    _orig = m.collect_unjudged
    def _spy(g, split=None, k=8):
        seen.append(k)
        return _orig(g, split, k=k)
    m.collect_unjudged = _spy
    # ★main() 會往評測歷史帳 append,不導向 fixture 就會寫進正式那一份★
    # (2026-09-15 code-r3 正確性席 blocker:實測跑一次全套就多一筆假紀錄進受版控的檔)。
    # 這裡用 assert 硬擋而不是 check:導向沒生效就★不准跑到 main★,不然測試翻紅時
    # 正式帳已經被寫髒了,擋在事後沒有意義。
    _hist = root / "fixture-history.jsonl"
    _real_hist = Path(GRAPHCTL).resolve().parent.parent / "governance" / "eval" / "retrieval-eval-history.jsonl"
    _real_before = _real_hist.read_bytes() if _real_hist.exists() else None
    _env_old = os.environ.get("LUMOS_EVAL_HISTORY")
    _argv = sys.argv
    try:
        os.environ["LUMOS_EVAL_HISTORY"] = str(_hist)
        # ★前置要驗「模組真的會解析到 fixture」,不是驗「我剛設的值等於我剛設的值」★
        # (2026-09-15 code-收斂 r1 正確性席 minor:原本那道 assert 讀的是自己上一行剛
        #  寫進去的環境變數,套套邏輯——擋得住「測試忘了導向」,擋不住「模組改成不理會
        #  這個變數」那類回歸,而後者才是會寫髒正式帳的那種)。
        # ★用 if...raise 不用 assert★(2026-09-15 收斂 r1 資安席):Python 的最佳化模式
        # 會把 assert 整行拿掉,守衛就消失了;這道前置是擋「寫髒正式治理帳」的最後一關,
        # 不能有「某種跑法下它不存在」這種狀態。
        if m._history_path() != _hist:
            raise RuntimeError(
                f"拒跑:模組把歷史帳解析到 {m._history_path()},不是 fixture,跑下去會寫進正式帳")
        sys.argv = ["retrieval_eval", "--goldset", str(p), "-k", "12"]
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            m.main()
    finally:
        sys.argv = _argv
        if _env_old is None:
            os.environ.pop("LUMOS_EVAL_HISTORY", None)
        else:
            os.environ["LUMOS_EVAL_HISTORY"] = _env_old
    _real_after = _real_hist.read_bytes() if _real_hist.exists() else None
    check("★正式的評測歷史帳一個位元都沒被動到★", _real_after == _real_before,
          "這支測試呼叫了 main(),沒導向 fixture 就會往受版控的真帳 append 假紀錄")
    check("★歷史帳路徑只有一個解析點★(新增寫入點不得自己組路徑)",
          _src_of(m, "retrieval-eval-history.jsonl") == 1,
          "檔內不只一處自己組歷史帳路徑——曾經有一條 --auto 路徑沒吃環境變數,"
          "測試把帳導向 fixture 之後它照樣寫進正式帳")
    check("fixture 帳有被寫到(證明導向真的生效,不是 main 根本沒寫)", _hist.exists(),
          "導向了卻沒產生 fixture 帳=main 沒走到寫帳那一步,上一條斷言會變成空過")
    check("main 真的呼叫到未標判定(不然這支測試等於空過)", len(seen) >= 1, f"一次都沒呼叫到")
    check("★每一次未標判定拿到的視窗都是 CLI 給的 12,不是預設 8★",
          all(k == 12 for k in seen), f"觀察到的 k={seen}——有 8 就是沒把 args.k 傳下去")
    print("  ✓ t_eval_unjudged_check_honours_cli_k")


def t_symbol_vocab_single_source_and_reach():
    """摘要符號詞彙表:①單一來源(不得兩份寫死)②抓錯字的正則伸得到含連字號的前綴
    ③PRIOR-ART/REVISIT 收進詞彙表(兩者都是紀律文件明文要求寫的)。

    出身(2026-09-15,Projects/標籤系統精簡_計劃 S10):原本 SYMBOL_RE 與 SYMBOL_NAMES
    是★兩份各自寫死的九值★,只改一份會讓「已收編」只有一半是真的;而抓錯字的
    SYMBOLISH_RE 只認連續大寫,★含連字號的前綴從一開始就不會被比對到★——
    所以把 PRIOR-ART 加進白名單是無效動作,測試若只斷言「寫了不報錯」會永遠空過。
    翻紅釘(條號為實測值,2026-09-15 收斂 r1 測試品質席逐條核對):
      ①把 SYMBOL_NAMES 改回獨立字面集合 → 第 1 條翻紅
      ②把 SYMBOLISH_RE 改回 ^([A-Z]{2,}): → ★第 5、6 條★翻紅
        (原本寫第 3 條是錯的——那條只看詞彙表集合本身,跟這個正則無關)"""
    m = _load_lumos_inproc()
    # ① 單一來源——★驗實際辨識行為,不掃原始碼文字★(code-r1 測試品質席:文字掃描擋不住
    # 「文字上仍引用該集合、推導時偷偷排除一個值」的變異,實測那樣改 8 條斷言全綠而行為已壞)
    _missed = [n for n in m.SYMBOL_NAMES if not m.SYMBOL_RE.match(n + ":x")]
    check("★詞彙表每一個值,搜尋的符號正則都認得出來★", _missed == [],
          f"認不出來的:{sorted(_missed)}(兩份表已經漂移)")
    _extra = m.SYMBOL_RE.match("NOTASYMBOL:x")
    check("不在表裡的不得被認成符號", _extra is None or _extra.group(1) in m.SYMBOL_NAMES, "")
    check("② 詞彙表含 PRIOR-ART 與 REVISIT",
          {"PRIOR-ART", "REVISIT"} <= set(m.SYMBOL_NAMES), str(sorted(m.SYMBOL_NAMES)))
    check("② 既有九值一個都沒少",
          {"KEY", "FLOW", "DEP", "TEST", "AUTH", "FLAG", "DECISION", "VERIFY", "CORE"}
          <= set(m.SYMBOL_NAMES), str(sorted(m.SYMBOL_NAMES)))
    # 2026-09-21:紀律範本改定位後,寫筆記要用 WHY/RULE/PITFALL/FACT 分類「程式碼推不推得出來」。
    # 範本叫人寫,工具卻不認,那幾行會被 lint 唸成打錯字、也不會被當成摘要行——規範等於空轉。
    # 這是照範本實際寫一行 FACT: 時當場撞到的,不是推測。翻紅釘:從表裡拿掉任一個 → 這條紅。
    check("② 詞彙表含範本新定的四個分類前綴",
          {"WHY", "RULE", "PITFALL", "FACT"} <= set(m.SYMBOL_NAMES),
          str(sorted(m.SYMBOL_NAMES)))
    # ③ 抓錯字的正則要伸得到含連字號的前綴——★不准空過★:打錯字的變體仍要被抓
    R = m.SYMBOLISH_RE
    check("★正則伸得到含連字號的前綴★", R.match("PRIOR-ART:x") is not None, "比對不到=加白名單是無效動作")
    check("★不空過:打錯字的含連字號變體仍被抓到★",
          R.match("PRIOR-ARTT:x") is not None
          and R.match("PRIOR-ARTT:x").group(1) not in m.SYMBOL_NAMES, "")
    check("正常前綴照舊抓得到", R.match("KEYY:x") is not None
          and R.match("KEYY:x").group(1) not in m.SYMBOL_NAMES, "")
    check("合法前綴不被當錯字", R.match("KEY:x").group(1) in m.SYMBOL_NAMES
          and R.match("REVISIT:2026-12-01 x").group(1) in m.SYMBOL_NAMES, "")
    check("不是符號宣告的行不誤抓(小寫/中文開頭)",
          R.match("key:x") is None and R.match("這是中文:x") is None, "")
    print("  ✓ t_symbol_vocab_single_source_and_reach")


