def t_drift_ack_routed_tracked_state():
    """[照留表態 S4 補] 綁去處的照留:那篇開著 → drift scan 算已表態、doctor 不列;那篇收尾 → scan 列回要處理並講已收尾、
    doctor 列;那篇刪掉 → 講不在了(代碼審 r1 正確性席 F1:_drift_note_state 改成永遠回 None 原本測試照綠)。
    翻紅釘:_drift_note_state 永遠回 None → ①紅;_drift_route_open 一律 True → ②紅。"""
    print("t_drift_ack_routed_tracked_state")
    root, _b = _ra_repo()
    _rt_push(root, [_RA_PROBE], msg="probe")
    _ra_ack(root, _rt_line(root, _RA_PROBE), tracked="Issues/排程", reason="排進排程那篇")
    vault = root / "docs" / "kg-knowledge"

    def probe_acked():
        fs = _dr_scan(vault)
        mine = [f for f in fs if isinstance(f, dict) and f.get("kind") == "probe"] if isinstance(fs, list) else []
        return [f["acked"] for f in mine], fs

    got, fs = probe_acked()
    doc = (lambda r: r.stdout + r.stderr)(run(vault, "doctor"))
    check("①綁的 Issue 開著:scan 算已表態、doctor 不列", got == [True] and "照留已失效" not in doc, (str(fs)[-300:], doc[-300:]))
    _nh_node(root, "排程", typ="issue", folder="Issues", status="resolved", resp=None, summary="KEY:i")
    _nh_commit(root, "close")
    got, fs = probe_acked()
    txt = (lambda r: r.stdout + r.stderr)(run(vault, "drift", "scan"))
    doc = (lambda r: r.stdout + r.stderr)(run(vault, "doctor"))
    check("②綁的 Issue 收尾:scan 列回要處理、講已收尾與舊理由;doctor 列", got == [False] and "已收尾" in txt
          and "排進排程那篇" in txt and "照留已失效 1 筆" in doc, (txt[-600:], doc[-400:]))
    (vault / "Issues" / "排程.md").unlink()
    _nh_commit(root, "delete")
    txt = (lambda r: r.stdout + r.stderr)(run(vault, "drift", "scan"))
    check("③綁的 Issue 刪掉:講不在了", "不在了" in txt, txt[-600:])
    print("  ✓ t_drift_ack_routed_tracked_state")


# ── 改摘要單行的指令(Projects/改摘要單行的指令_計劃)─────────────────────────────────────────────
def _sl_vault(summary):
    """一篇 Systems/Pay,摘要給定 → (root, vault, 筆記路徑)。"""
    root = _nh_repo()
    p = _nh_node(root, "Pay", summary=summary)
    _nh_commit(root, "init")
    return root, root / "docs" / "kg-knowledge", p


def _sl_summary(p):
    lines = p.read_text(encoding="utf-8").split("\n")
    i = next(k for k, ln in enumerate(lines) if ln.startswith("summary:"))
    out = []
    for ln in lines[i + 1:]:
        if ln.startswith("  "):
            out.append(ln[2:])
        else:
            break
    return out


def _sl_today():
    import datetime as _dt
    return _dt.datetime.now(_dt.timezone.utc).astimezone().date().isoformat()


def t_summary_line_replace():
    """[改摘要單行 S1] 舊片段恰好出現一次 → 換成新片段、updated 改今天、印改前改後、其他行不動。
    翻紅釘:不改 updated → ②紅;換了第一個以外的行 → ①紅。"""
    print("t_summary_line_replace")
    _root, v, p = _sl_vault("WHY:用 A 方案 [出處:x] [因:y]\nKEY:第二條不動\nWHY:另一條 [出處:z] [因:w]")
    before = p.read_text(encoding="utf-8")
    r = run(v, "summary-line", "Systems/Pay", "用 A 方案", "改用 B 方案")
    s = _sl_summary(p)
    check("①換掉那一段、其他行不動", r.returncode == 0 and s == ["WHY:改用 B 方案 [出處:x] [因:y]", "KEY:第二條不動",
                                                          "WHY:另一條 [出處:z] [因:w]"], (r.stdout + r.stderr, s))
    check("②updated 改成今天", f"updated: {_sl_today()}" in p.read_text(encoding="utf-8"), p.read_text(encoding="utf-8")[:300])
    check("③印改前改後", "WHY:用 A 方案" in r.stdout and "WHY:改用 B 方案" in r.stdout, r.stdout)
    body_old = before.split("\n---\n", 1)[1]
    # ⑤新的那一行剛好跟另一行一模一樣:自驗照算對(代碼審 r1 正確性席 F4)
    _root2, v2, p2 = _sl_vault("KEY:甲\nKEY:乙")
    r2 = run(v2, "summary-line", "Systems/Pay", "乙", "甲")
    check("⑤新行跟另一行一樣:照改", r2.returncode == 0 and _sl_summary(p2) == ["KEY:甲", "KEY:甲"], (r2.stdout + r2.stderr, _sl_summary(p2)))
    check("④正文一字不動", p.read_text(encoding="utf-8").split("\n---\n", 1)[1] == body_old, "")
    print("  ✓ t_summary_line_replace")


def t_summary_line_ambiguous():
    """[改摘要單行 S2] 舊片段出現兩行以上或同一行兩次 → rc2 不寫、列候選行號與前 40 字;--nth 2 改第二個出現處。
    翻紅釘:對到多個時改第一個 → ①紅;--nth 數錯 → ③紅。"""
    print("t_summary_line_ambiguous")
    _root, v, p = _sl_vault("RULE:甲 [依據:人] [since:2026-01-01] [retire:人裁] [until:2027-01-01]\n"
                           "RULE:乙 [依據:人] [since:2026-01-01] [retire:人裁] [until:2027-01-01]")
    before = p.read_text(encoding="utf-8")
    r = run(v, "summary-line", "Systems/Pay", "[依據:人]", "[依據:外部]")
    out = r.stdout + r.stderr
    check("①對到兩行:rc2、檔不動、列出兩個候選", r.returncode == 2 and p.read_text(encoding="utf-8") == before
          and "RULE:甲" in out and "RULE:乙" in out and "--nth" in out, out)
    _root, v, p = _sl_vault("KEY:同一行 xx 兩次 xx")
    before = p.read_text(encoding="utf-8")
    r = run(v, "summary-line", "Systems/Pay", "xx", "yy")
    check("②同一行出現兩次:rc2、檔不動", r.returncode == 2 and p.read_text(encoding="utf-8") == before, r.stdout + r.stderr)
    r = run(v, "summary-line", "Systems/Pay", "xx", "yy", "--nth", "2")
    check("③--nth 2:換第二個出現處", r.returncode == 0 and _sl_summary(p) == ["KEY:同一行 xx 兩次 yy"], (r.stdout + r.stderr, _sl_summary(p)))
    r = run(v, "summary-line", "Systems/Pay", "yy", "zz", "--nth", "3")
    check("④--nth 超出範圍:rc2", r.returncode == 2, r.stdout + r.stderr)
    print("  ✓ t_summary_line_ambiguous")


def t_summary_line_rejects():
    """[改摘要單行 S3] 找不到、舊片段空或含換行、新片段含換行、節點不存在 → rc2 不寫。翻紅釘:不擋空的舊片段 → ①-④紅。"""
    print("t_summary_line_rejects")
    _root, v, p = _sl_vault("KEY:一條 [x]\nKEY:另一條")
    before = p.read_text(encoding="utf-8")
    for args, why, say in ((("找不到的字", "新"), "找不到", "摘要裡找不到"), (("", "新"), "舊片段空", "不能是空的"),
                           (("一條\nKEY", "新"), "舊片段含換行", "不能含換行"), (("一條", "新\n行"), "新片段含換行", "不能含換行")):
        r = run(v, "summary-line", "Systems/Pay", *args)
        check(f"①-④{why}:rc2、檔不動、講原因", r.returncode == 2 and p.read_text(encoding="utf-8") == before
              and say in r.stdout + r.stderr, r.stdout + r.stderr)
    r = run(v, "summary-line", "Systems/不存在", "a", "b")
    check("⑤節點不存在:rc2、講找不到那篇(共用的近名候選訊息)", r.returncode == 2
          and "找不到叫「Systems/不存在」的筆記" in r.stdout + r.stderr, r.stdout + r.stderr)
    for bad in ("\r", "\x85", "\u2028", "\x0b"):
        r = run(v, "summary-line", "Systems/Pay", "一條", f"新{bad}行")
        check(f"⑥新片段含換行類字元 {bad!r}:rc2、檔不動", r.returncode == 2 and p.read_text(encoding="utf-8") == before
              and "不能含換行" in r.stdout + r.stderr, r.stdout + r.stderr)
    r = run(v, "summary-line", "Systems/Pay", "一條", "一條")
    check("⑦新舊片段相同:rc2、講沒有要改的", r.returncode == 2 and p.read_text(encoding="utf-8") == before
          and "沒有要改的" in r.stdout + r.stderr, r.stdout + r.stderr)
    print("  ✓ t_summary_line_rejects")


def t_summary_line_continuation():
    """[改摘要單行 S5] 目標行屬於跨多個實體行的條目(第一行或續行)→ rc2、檔不動、講不支援續行。翻紅釘:不擋續行 → ①紅。"""
    print("t_summary_line_continuation")
    _root, v, p = _sl_vault("RULE:要人簽 [依據:人] [since:2026-09-01]\n  [retire:when-file:src/a.py]\nKEY:別條")
    before = p.read_text(encoding="utf-8")
    for frag in ("要人簽", "src/a.py"):
        r = run(v, "summary-line", "Systems/Pay", frag, "改")
        check(f"①續行條目({frag}):rc2、檔不動、講續行", r.returncode == 2 and p.read_text(encoding="utf-8") == before
              and "續行" in r.stdout + r.stderr, r.stdout + r.stderr)
    r = run(v, "summary-line", "Systems/Pay", "KEY:別條", "KEY:別條改過")
    check("②同一篇單行的條目照改", r.returncode == 0 and "KEY:別條改過" in _sl_summary(p), r.stdout + r.stderr)
    print("  ✓ t_summary_line_continuation")


def t_summary_line_delete():
    """[改摘要單行 S4] 換完只剩空白 → 拿掉那一行;摘要因此變空 → rc2 不寫。翻紅釘:留下空行 → ①紅。"""
    print("t_summary_line_delete")
    _root, v, p = _sl_vault("KEY:留著\nKEY:要刪的這一條")
    r = run(v, "summary-line", "Systems/Pay", "KEY:要刪的這一條", "")
    check("①整行刪光:拿掉那一行", r.returncode == 0 and _sl_summary(p) == ["KEY:留著"], (r.stdout + r.stderr, _sl_summary(p)))
    before = p.read_text(encoding="utf-8")
    r = run(v, "summary-line", "Systems/Pay", "KEY:留著", "")
    check("②刪完摘要會空:rc2、檔不動", r.returncode == 2 and p.read_text(encoding="utf-8") == before, r.stdout + r.stderr)
    print("  ✓ t_summary_line_delete")


def t_summary_line_verify():
    """[改摘要單行 S6] 寫入自驗失敗 → rc2、原檔不動;--dry-run 只印不寫;成功後提示 lint 那一篇。
    翻紅釘:不走 atomic_write_verify(直接寫)→ ①紅。"""
    print("t_summary_line_verify")
    import io, contextlib
    m = _load_lumos_inproc()
    _root, v, p = _sl_vault("KEY:正常的一條\nKEY:別條")
    before = p.read_text(encoding="utf-8")
    orig = m.atomic_write_verify

    def _boom(*a, **k):
        raise m.WriteBlocked("測試:自驗失敗")
    m.atomic_write_verify = _boom
    buf, old_argv = io.StringIO(), sys.argv
    sys.argv = ["lumos", "--vault", str(v), "summary-line", "Systems/Pay", "正常的一條", "改過的一條"]
    try:
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = m._cli()
    finally:
        m.atomic_write_verify, sys.argv = orig, old_argv
    check("①寫入自驗失敗:rc2、原檔不動", rc == 2 and p.read_text(encoding="utf-8") == before, buf.getvalue())
    r = run(v, "summary-line", "Systems/Pay", "正常的一條", "改過的一條", "--dry-run")
    check("②--dry-run:印改後、檔不動", r.returncode == 0 and "改過的一條" in r.stdout and p.read_text(encoding="utf-8") == before,
          r.stdout + r.stderr)
    r = run(v, "summary-line", "Systems/Pay", "正常的一條", "改過的一條")
    check("③成功後提示 lint 那一篇", r.returncode == 0 and "lumos lint Systems/Pay" in r.stdout, r.stdout)
    print("  ✓ t_summary_line_verify")


# ── 筆記 updated 落後:健檢列出加一鍵修(Projects/提交時自動更新筆記日期_計劃)────────────────────────
def _us_today():
    import datetime as _dt
    return _dt.datetime.now(_dt.timezone.utc).astimezone().date().isoformat()


def _us_repo():
    """兩篇筆記都寫 updated 2026-09-11、今天提交(→ 落後);一篇沒有 updated 欄。→ (root, vault)。"""
    root = _nh_repo()
    _nh_node(root, "Pay", summary="KEY:a")
    _nh_node(root, "Ship", summary="KEY:b")
    nou = root / "docs" / "kg-knowledge" / "Systems" / "NoDate.md"
    nou.write_text("---\ntype: system\nstatus: doing\nsummary: |-\n  KEY:c\n---\n# NoDate\n", encoding="utf-8")
    _nh_commit(root, "init")
    return root, root / "docs" / "kg-knowledge"


def _us_updated(vault, rel):
    import re as _re
    m = _re.search(r"^updated: (\S+)$", (vault / rel).read_text(encoding="utf-8"), _re.M)
    return m.group(1) if m else None


def t_doctor_updated_stale():
    """[updated 落後 S1] updated 早於 git 上最後一次提交日期 → doctor 印筆數與那幾篇、附 lumos updated-sync --stale;
    都沒落後 → 不印。翻紅釘:doctor 不接 _updated_stale_notes → ①紅。"""
    print("t_doctor_updated_stale")
    root, v = _us_repo()
    r = run(v, "doctor")
    out = r.stdout + r.stderr
    check("①兩篇落後:印筆數、例子、指令", "updated 落後" in out and "2 篇" in out and "Systems/Pay" in out
          and "lumos updated-sync --stale" in out, out[-1200:])
    for n in ("Pay", "Ship"):
        p = v / "Systems" / f"{n}.md"
        p.write_text(p.read_text(encoding="utf-8").replace("updated: 2026-09-11", f"updated: {_us_today()}"), encoding="utf-8")
    _nh_commit(root, "bump")
    r = run(v, "doctor")
    check("②都改成今天後:不印", "updated 落後" not in r.stdout + r.stderr, (r.stdout + r.stderr)[-800:])
    # ③淺複製(只有最近一個提交):日期表全變同一天、判不準 → 不印(代碼審 r1 正確性席 F1)
    import subprocess as _sp
    root, v = _us_repo()
    (root / "README.md").write_text("x\n")
    _nh_commit(root, "later")
    sh = Path(tempfile.mkdtemp(prefix="gctl-us-shallow-")) / "c"
    _sp.run(["git", "clone", "-q", "--depth", "1", f"file://{root}", str(sh)], capture_output=True)
    r = run(sh / "docs" / "kg-knowledge", "doctor")
    check("③淺複製:不印 updated 落後", "updated 落後" not in r.stdout + r.stderr, (r.stdout + r.stderr)[-600:])
    r = run(sh / "docs" / "kg-knowledge", "updated-sync", "--stale", "--dry-run")
    check("③淺複製:--stale 沒有要改的", "會改" not in r.stdout, r.stdout + r.stderr)
    # ④只落後一天(跨午夜才提交):不算(代碼審 r1 正確性席 F3)
    import datetime as _dt, os as _os
    root, v = _us_repo()
    y = (_dt.date.fromisoformat(_us_today()) - _dt.timedelta(days=1)).isoformat()
    for n in ("Pay", "Ship"):
        q = v / "Systems" / f"{n}.md"
        q.write_text(q.read_text(encoding="utf-8").replace("updated: 2026-09-11", f"updated: {y}"), encoding="utf-8")
    _nh_git(root, "add", "-A")
    _sp.run(["git", "-C", str(root), "commit", "-qm", "y"], capture_output=True, env=dict(_os.environ, GIT_COMMITTER_DATE=f"{_us_today()}T12:00:00"))
    r = run(v, "doctor")
    check("④updated 只比 git 日期早一天:不算落後", "updated 落後" not in r.stdout + r.stderr, (r.stdout + r.stderr)[-600:])
    print("  ✓ t_doctor_updated_stale")


def t_updated_sync_stale():
    """[updated 落後 S2] updated-sync --stale → 落後的每篇改成今天、其他欄位與正文不動;沒有 updated 欄的不加;已是今天的跳過。
    翻紅釘:改成 git 日期而非今天 → ①紅;沒有 updated 也加 → ③紅。"""
    print("t_updated_sync_stale")
    _root, v = _us_repo()
    before = (v / "Systems" / "Pay.md").read_text(encoding="utf-8")
    r = run(v, "updated-sync", "--stale")
    check("①兩篇改成今天", r.returncode == 0 and _us_updated(v, "Systems/Pay.md") == _us_today()
          and _us_updated(v, "Systems/Ship.md") == _us_today(), r.stdout + r.stderr)
    after = (v / "Systems" / "Pay.md").read_text(encoding="utf-8")
    check("②只動 updated 那一行", [ln for ln in before.split("\n") if not ln.startswith("updated:")]
          == [ln for ln in after.split("\n") if not ln.startswith("updated:")], after[:300])
    check("③沒有 updated 欄的不加(--stale 本來就不挑它)", _us_updated(v, "Systems/NoDate.md") is None,
          (v / "Systems" / "NoDate.md").read_text())
    r = run(v, "updated-sync", "Systems/NoDate")
    check("③b直接指定沒有 updated 欄的那篇:跳過、不加", r.returncode == 0 and "沒有 updated 欄或是空的" in r.stdout
          and _us_updated(v, "Systems/NoDate.md") is None, r.stdout + r.stderr)
    r = run(v, "updated-sync", "--stale")
    check("④再跑一次(都已是今天、但還沒提交):照樣改成今天、不報錯", r.returncode == 0, r.stdout + r.stderr)
    print("  ✓ t_updated_sync_stale")


def t_updated_sync_nodes():
    """[updated 落後 S3] 指定節點只改那一篇;找不到的走近名候選、rc 非 0、其他照改;--dry-run 只印不寫。
    翻紅釘:找不到就整批停 → ②紅;--dry-run 照寫 → ③紅。"""
    print("t_updated_sync_nodes")
    _root, v = _us_repo()
    r = run(v, "updated-sync", "Systems/Pay")
    check("①只改指定那篇", r.returncode == 0 and _us_updated(v, "Systems/Pay.md") == _us_today()
          and _us_updated(v, "Systems/Ship.md") == "2026-09-11", r.stdout + r.stderr)
    r = run(v, "updated-sync", "Systems/不存在", "Systems/Ship")
    check("②找不到的走近名候選、rc 非 0、其他照改", r.returncode != 0 and "找不到叫「Systems/不存在」的筆記" in r.stdout + r.stderr
          and _us_updated(v, "Systems/Ship.md") == _us_today(), r.stdout + r.stderr)
    _root, v = _us_repo()
    r = run(v, "updated-sync", "--stale", "--dry-run")
    check("③--dry-run:印會改哪幾篇、不寫", r.returncode == 0 and "Systems/Pay" in r.stdout
          and _us_updated(v, "Systems/Pay.md") == "2026-09-11", r.stdout + r.stderr)
    r = run(v, "updated-sync")
    check("④沒給節點也沒給 --stale:rc2", r.returncode == 2, r.stdout + r.stderr)
    # ⑤一篇寫入時丟例外:其他照改、rc 非 0(代碼審 r2 回歸席 F1)
    m = _load_lumos_inproc()
    import io, contextlib
    _root2, v2 = _us_repo()
    orig = m.cmd_set

    def _boom(env, rel, key, value):
        if rel.endswith("Pay.md"):
            raise RuntimeError("測試:寫入失敗")
        return orig(env, rel, key, value)
    m.cmd_set = _boom
    buf = io.StringIO()
    try:
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = m.cmd_updated_sync(m.Env(v2), ["Systems/Pay", "Systems/Ship"])
    finally:
        m.cmd_set = orig
    check("⑤一篇丟例外:其他照改、rc 非 0、講原因", rc != 0 and _us_updated(v2, "Systems/Ship.md") == _us_today()
          and "測試:寫入失敗" in buf.getvalue(), buf.getvalue())
    # ⑥updated 是不存在的日期:當成落後列出(代碼審 r2 回歸席 F2)
    _root3, v3 = _us_repo()
    q = v3 / "Systems" / "Pay.md"
    q.write_text(q.read_text(encoding="utf-8").replace("updated: 2026-09-11", "updated: 2026-02-30"), encoding="utf-8")
    _nh_commit(_root3, "bad date")
    r = run(v3, "updated-sync", "--stale", "--dry-run")
    check("⑥updated 是不存在的日期:列成要改", "會改 Systems/Pay" in r.stdout, r.stdout + r.stderr)
    print("  ✓ t_updated_sync_nodes")


def _rt_events(root):
    return [e for e in _ns_gov(root) if e.get("gate") == "drift-check" and e.get("check") == "retire"]


def _rt_inproc(m, root, base, tip, **patch):
    """行程內跑 cmd_drift_check,暫換模組常數 → (rc, 輸出)。"""
    import io, contextlib
    old = {k: getattr(m, k) for k in patch}
    for k, v in patch.items():
        setattr(m, k, v)
    buf = io.StringIO()
    try:
        with contextlib.redirect_stderr(buf), contextlib.redirect_stdout(buf):
            rc = m.cmd_drift_check(repo=str(root), diff_range=f"{base}..{tip}")
    finally:
        for k, v in old.items():
            setattr(m, k, v)
    return rc, buf.getvalue()


def t_slots_retire_followups():
    """撤除條件第 2 步代碼審 r1、r2 的修正:欄位寫在續行的 RULE 表態記整條(改續行條件舊表態失效、續行不同的兩條不互相放行);
    自己一個截止時間;沒寫 retire 照總開關;doctor 講比總開關鬆的設定;有事才記帳、放行不寫。
    翻紅釘:_drift_ack_text 只記實體行 → ①b①c紅;_retire_lines 給實體行 → ①紅;_drift_retire_config 預設寫死 block → ③③b紅;
    撤除條件改回吃核心剩下的時間 → ②b紅;_drift_gate_doctor_lines 不接 _drift_retire_doctor_lines → ④紅;
    記帳改成每次都記 → ⑤紅;rt_mode 不看 gate=off → ③c紅;推送不印 rt_warns → ③b紅;逾時訊息不分 kind → ②c紅。"""
    import json as _j
    m = _load_lumos_inproc()
    head = "RULE:要人簽 [依據:人] [since:2026-09-01]"
    ca, cb = "  [retire:when-file:src/a.py]", "  [retire:when-file:src/b.py]"
    # ①欄位寫在續行:擋 → 表態整條 → 放行
    root = _dr_repo()
    base = _rt_push(root, [head, ca], msg="rule")
    tip = _rt_push(root, [head, ca], files=("src/a.py",), msg="add file")
    rc, out = _dr(root, "check", "--diff", f"{base}..{tip}")
    check("①續行 RULE 先擋、帶表態段的指令", rc == 1 and head in out and "不改就留著並表態" in out
          and "lumos drift ack <節點> <行號> --kind retire" in out, out[-700:])
    arc, tip2 = _rt_ack(root, _rt_line(root, head))
    rc, out = _dr(root, "check", "--diff", f"{base}..{tip2}")
    check("①表態之後放行", arc == 0 and rc == 0 and "撤除條件成立" not in out, out[-500:])
    # ①b表態後把續行條件改成另一個已成立的:舊表態失效、照擋
    _nh_file(root, "src/c.py", "x = 1\n")
    tip3 = _rt_push(root, [head, "  [retire:when-file:src/c.py]"], msg="change cond")
    rc, out = _dr(root, "check", "--diff", f"{base}..{tip3}")
    check("①b改了續行條件,舊表態不算數", rc == 1 and "撤除條件成立" in out, out[-500:])
    # ①c第一行相同、續行條件不同的兩條:表態一條,另一條照擋
    root = _dr_repo()
    base = _rt_push(root, [head, ca, head, cb], msg="rules")
    tip = _rt_push(root, [head, ca, head, cb], files=("src/a.py", "src/b.py"), msg="add files")
    _arc, tip2 = _rt_ack(root, _rt_line(root, head, 1))
    rc, out = _dr(root, "check", "--diff", f"{base}..{tip2}")
    check("①c表態一條,第一行相同的另一條照擋", rc == 1 and out.count("[retire RULE") == 1, out[-600:])
    # ②預算用完:只列出不擋;②b核心用光時間,撤除條件照樣判得出(自己一個截止時間)
    rule = head + " [retire:when-file:src/new.py]"
    root = _dr_repo()
    base = _rt_push(root, [rule], msg="rule")
    tip = _rt_push(root, [rule], files=("src/new.py",), msg="add file")
    rc, out = _rt_inproc(m, root, base, tip, _DRIFT_RETIRE_BUDGET_SEC=-1)
    check("②預算用完只列出不擋", rc == 0 and "判不了(只列出,不擋)" in out and "撤除條件成立了" not in out, out[-600:])
    _rc, out = _rt_inproc(m, root, base, tip, _DRIFT_BUDGET_SEC=-1)
    check("②b核心用光時間,撤除條件照樣判出成立", "撤除條件成立了" in out, out[-600:])
    # ②c逾時訊息寫撤除條件、不寫回頭條件
    vr = "docs/kg-knowledge"
    tenv = m._drift_tree_env(root, tip, vr)
    _must, _l, unk = m._drift_probe_check(root, base, tip, vr, tenv, deadline=0, extract=m._retire_lines, kind="retire")
    check("②c逾時訊息寫 RULE 撤除條件", unk and all("RULE 撤除條件" in u and "回頭條件" not in u for u in unk), str(unk))
    # ③總開關 warn、retire 沒寫:跟著 warn;③b retire 寫壞:照總開關 warn、推送時印提醒;③c gate=off、retire=block:不跑
    for cfg, want_rc, want_hit, want_warn, tag in (
            ({"drift_check": {"gate": "warn"}}, 0, True, False, "③gate=warn、retire 沒寫:只提醒不擋"),
            ({"drift_check": {"gate": "warn", "retire": "nope"}}, 0, True, True, "③b retire 寫壞:照總開關 warn、印提醒"),
            ({"drift_check": {"gate": "off", "retire": "block"}}, 0, False, False, "③c gate=off:retire=block 也不跑")):
        root = _dr_repo(cfg=cfg)
        base = _rt_push(root, [rule], msg="rule")
        tip = _rt_push(root, [rule], files=("src/new.py",), msg="add file")
        rc, out = _dr(root, "check", "--diff", f"{base}..{tip}")
        check(tag, rc == want_rc and ("撤除條件成立" in out) == want_hit
              and (("提醒:drift_check.retire" in out) == want_warn), out[-500:])
    # ④doctor:比總開關鬆、寫錯值才講
    for cfg, want in (({"drift_check": {"retire": "off"}}, "是 off"), ({"drift_check": {"retire": "warn"}}, "是 warn"),
                      ({"drift_check": {"retire": "nope"}}, "沒讀懂"), ({"drift_check": {"gate": "warn", "retire": "warn"}}, None),
                      ({"drift_check": {"gate": "off", "retire": "off"}}, None), ({}, None)):
        d = Path(tempfile.mkdtemp(prefix="gctl-rt-doc-"))
        (d / ".lumos").mkdir()
        (d / ".lumos" / "config.json").write_text(_j.dumps(cfg))
        hit = [x for x in m._drift_gate_doctor_lines(d) if "RULE 撤除條件" in x]
        check(f"④doctor {cfg}:" + (f"講「{want}」" if want else "不講撤除條件"),
              (want is None and not hit) or (want is not None and any(want in x for x in hit)), str(hit))
    # ⑤放行不寫帳;成立時一筆、帶條數與頂端、起點
    root = _dr_repo()
    base = _rt_push(root, [rule], msg="rule")
    tip = _rt_push(root, [rule, "WHY:無關 [出處:a] [因:b]"], msg="same")
    rc, _out = _dr(root, "check", "--diff", f"{base}..{tip}")
    check("⑤沒成立、沒判不了:不寫帳", rc == 0 and not _rt_events(root), str(_rt_events(root))[-300:])
    tip = _rt_push(root, [rule], files=("src/new.py",), msg="add file")
    rc, _out = _dr(root, "check", "--diff", f"{base}..{tip}")
    ev = _rt_events(root)
    check("⑤成立:一筆 blocked、帶 handle/listed、頂端與起點", rc == 1 and len(ev) == 1 and ev[0].get("kind") == "blocked"
          and ev[0].get("handle") == 1 and ev[0].get("listed") == 0 and ev[0].get("head_sha") == tip
          and ev[0].get("base_sha") == base, str(ev)[-500:])
    print("  ✓ t_slots_retire_followups")


def t_slots_doctor_reminders():
    """[S13] doctor 的格子過期提醒:[被取代:] 一跳(S17)、度量(S18)、FACT 確認週期(S19)提醒且不計入問題數;已作廢的行不提醒;
    --ci 不跑一跳與度量;drift scan 列出撤除條件現在已成立、不列已作廢、已表態的不算要處理。
    翻紅釘:_slot_replacement_dead 不查決策 valid → ①紅;_doctor_metric_lines 拿掉暖機那道 → ③紅、拿掉閘 off 那道 → ③紅;
    _doctor_fact_recheck_lines 不跳過作廢 → ⑤紅;run_doctor 的 S17 不看 ci → ⑥紅;cmd_drift_scan 不跑 retire → ⑦紅。"""
    import json as _j, datetime as _dt
    m = _load_lumos_inproc()
    # ①[被取代:] 一跳
    v = mkvault()
    write(v, "Systems/Live.md", "type: system\nstatus: doing\ndecisions:\n  - id: d1\n    content: 現行\n    valid: true\n"
          "  - id: d2\n    content: 翻案了\n    valid: false\nsummary: |-\n  KEY:x", body="# L\n")
    write(v, "Systems/Old.md", "type: system\nstatus: superseded\nsummary: |-\n  KEY:x", body="# O\n")
    sup = " [status:superseded]"
    write(v, "Systems/R.md", "type: system\nstatus: doing\nsummary: |-\n"
          f"  WHY:甲指不存在 [出處:a] [因:b]{sup} [被取代:[[Systems/Nope]]]\n"
          f"  WHY:乙指作廢節點 [出處:a] [因:b]{sup} [被取代:[[Systems/Old]]]\n"
          f"  WHY:丙指沒有的決策 [出處:a] [因:b]{sup} [被取代:Systems/Live.md#d9]\n"
          f"  WHY:丁指翻案決策 [出處:a] [因:b]{sup} [被取代:Systems/Live#d2]\n"
          f"  WHY:戊指現行決策 [出處:a] [因:b]{sup} [被取代:Systems/Live.md#d1]\n"
          f"  WHY:己指現行節點 [出處:a] [因:b]{sup} [被取代:[[Systems/Live]]]\n"
          f"  WHY:庚無接手 [出處:a] [因:b]{sup} [被取代:無 限制自然消失]", body="# R\n")
    env = m.Env(v)
    lines = m._doctor_replacement_lines(env)
    txt = "\n".join(lines)
    check("①指不存在、作廢節點、沒有的決策、翻案決策各列一條", len(lines) == 4 and "Nope" in txt and "Old" in txt
          and "d9" in txt and "d2" in txt, txt)
    check("①指現行決策、現行節點、無接手的不列", all(x not in txt for x in ("#d1]", "[[Systems/Live]]", "無 限制")), txt)
    # ②S17 接進 doctor、不計入問題數;--ci 不跑
    r = run(v, "doctor", "--verbose")
    seg = r.stdout.split("[S17]")[1].split("\n[")[0] if "[S17]" in r.stdout else ""
    check("②doctor S17 列出", "4 處 [被取代:]" in seg, seg[-400:])
    v0 = mkvault()
    write(v0, "Systems/R.md", "type: system\nstatus: doing\nsummary: |-\n  WHY:x [出處:a] [因:b]", body="# R\n")
    r0 = run(v0, "doctor")
    check("②不計入問題數(rc 跟沒有這些行時一樣)", r.returncode == r0.returncode, f"{r.returncode} vs {r0.returncode}")
    rc = run(v, "doctor", "--ci")
    seg = rc.stdout.split("[S17]")[1].split("\n[")[0] if "[S17]" in rc.stdout else ""
    check("⑥--ci 不跑 S17", "--ci 不跑" in seg and "處 [被取代:]" not in seg, seg[-300:])
    # ③度量:成立才列;暖機、since 不滿、閘 off、作廢、不成立都不列
    now = _dt.datetime(2026, 10, 2, 12, 0, tzinfo=_dt.timezone.utc)

    def gl(vault, evs):
        (vault.parent / ".governance-log.jsonl").write_text(
            "".join(_j.dumps({"ts": t, "gate": g, "kind": k}) + "\n" for t, g, k in evs), encoding="utf-8")
    old = [("2026-07-01T00:00:00+00:00", "note-shape", "blocked"), ("2026-07-02T00:00:00+00:00", "doctor-run", "ran")]   # 暖機要兩筆舊紀錄
    recent = [(f"2026-09-{d:02d}T00:00:00+00:00", "note-shape", "blocked") for d in range(20, 26)]
    rules = ("  RULE:甲該撤 [依據:人] [since:2026-06-01] [retire:度量 note-shape.blocked >= 5 近4週]\n"
             "  RULE:乙沒到 [依據:人] [since:2026-06-01] [retire:度量 note-shape.blocked >= 50 近4週]\n"
             "  RULE:丙太新 [依據:人] [since:2026-09-25] [retire:度量 note-shape.blocked >= 5 近4週]\n"
             "  RULE:丁作廢 [依據:人] [since:2026-06-01] [retire:度量 note-shape.blocked >= 5 近4週] [status:superseded] [被取代:無 x]\n")
    v = mkvault()
    write(v, "Systems/M.md", "type: system\nstatus: doing\nsummary: |-\n" + rules, body="# M\n")
    gl(v, old + recent)
    got = m._doctor_metric_lines(m.Env(v), v.parent, now=now)
    check("③成立的列出(6 筆 >= 5),沒到、since 不滿 4 週、作廢的不列", len(got) == 1 and "甲該撤" in got[0] and "6 筆" in got[0],
          str(got))
    gl(v, recent)
    check("③暖機:帳裡最舊一筆不早於 4 週前,不判", m._doctor_metric_lines(m.Env(v), v.parent, now=now) == [], "")
    gl(v, old + recent)
    (v.parent / ".lumos").mkdir(exist_ok=True)
    (v.parent / ".lumos" / "config.json").write_text(_j.dumps({"note_shape": {"gate": "off"}}))
    check("③閘目前是 off,不判", m._doctor_metric_lines(m.Env(v), v.parent, now=now) == [], "")
    # ④⑤FACT 確認週期
    facts = ("  FACT:甲逾期 [來源:生產] [confirmed:2026-08-01] [recheck:30天]\n"
             "  FACT:乙照來源預設逾期 [來源:人工] [confirmed:2026-01-01]\n"
             "  FLOW:丙還在週期內 [來源:部署] [confirmed:2026-09-20]\n"
             "  FACT:丁沒寫確認 [來源:生產]\n"
             "  FACT:戊作廢 [來源:生產] [confirmed:2020-01-01] [status:superseded] [被取代:無 x]\n"
             "  DEP:己週期寫錯 [來源:外部] [confirmed:2026-09-30] [recheck:兩週]\n")
    v = mkvault()
    write(v, "Systems/F.md", "type: system\nstatus: doing\nsummary: |-\n" + facts, body="# F\n")
    got = m._doctor_fact_recheck_lines(m.Env(v), _dt.date(2026, 10, 2))
    txt = "\n".join(got)
    check("④逾期(recheck 與來源預設)列出、週期內與沒寫確認的不列", "甲逾期" in txt and "乙照來源預設逾期" in txt
          and "丙" not in txt and "丁" not in txt, txt)
    check("④週期寫錯提醒一次、照來源預設", "[recheck:兩週] 寫不成週期" in txt and "90 天" in txt, txt)
    check("⑤作廢的不判", "戊" not in txt, txt)
    r = run(v, "doctor", "--ci")
    check("④S19 在 --ci 也跑", "[S19]" in r.stdout and "條現況句超過確認週期" in r.stdout, r.stdout[-600:])
    # ⑦drift scan 列出撤除條件現在已成立;已作廢不列;已表態的不算要處理
    root = _dr_repo()
    rule = "RULE:要人簽 [依據:人] [since:2026-09-01] [retire:when-file:src/new.py]"
    rule2 = "RULE:另一條 [依據:人] [since:2026-09-01] [retire:when-file:src/new.py]"
    dead = rule.replace("要人簽", "已作廢") + " [status:superseded] [被取代:無 x]"
    _rt_push(root, [rule, rule2, dead], files=("src/new.py",), msg="rules")
    _arc, _tip = _rt_ack(root, _rt_line(root, rule2))
    vault = root / "docs" / "kg-knowledge"
    r = _dr_scan(vault)
    fs = [f for f in r if isinstance(f, dict) and f.get("kind") == "retire"] if isinstance(r, list) else []
    check("⑦scan 列出撤除條件已成立的 RULE,已作廢的不列", any("要人簽" in f["text"] and not f["acked"] for f in fs)
          and not any("已作廢" in f["text"] for f in fs), str(fs)[-500:])
    check("⑦已表態的標已表態", any("另一條" in f["text"] and f["acked"] for f in fs), str(fs)[-500:])
    print("  ✓ t_slots_doctor_reminders")


def t_slots_doctor_reminders_edges():
    """筆記格子第 3 步代碼審 r1 折入的邊角:S17 只看作廢行、[[X#dN]] 也查決策;S18 重驗寫法(超大週數、拼錯閘名列成提醒、不崩)、
    五種比較、naive 時間、出界時間只跳那一行、lint-new 關掉認得、--ci 不跑;S19 週與月;輸出清控制字元;檔尾截斷;S16 接回續行。
    翻紅釘:_doctor_replacement_lines 不看作廢 → ①紅;_doctor_metric_lines 不重驗 → ②紅(崩);_metric_gate_off 取 gate 鍵 → ④紅;
    _gov_metric_events 的 astimezone 拿出 try → ⑤紅;週改成 1 天 → ⑦紅;拿掉 _esc_clean → ⑧紅;_gov_tail_bytes 不丟頭一行 → ⑨紅;
    S16 不接續行 → ⑩紅。"""
    import json as _j, datetime as _dt
    m = _load_lumos_inproc()
    sup = " [status:superseded]"
    # ①S17 只看作廢行;[[X#dN]] 也查決策
    v = mkvault()
    write(v, "Systems/Live.md", "type: system\nstatus: doing\ndecisions:\n  - id: d1\n    content: 現行\n    valid: true\n"
          "  - id: d2\n    content: 翻案了\n    valid: false\nsummary: |-\n  KEY:x", body="# L\n")
    write(v, "Systems/R.md", "type: system\nstatus: doing\nsummary: |-\n"
          "  WHY:說明 [被取代:] 這個鍵怎麼用 [出處:a] [因:b]\n"
          "  WHY:舉例沒作廢 [被取代:[[Systems/Nope]]] 只是寫法示範 [出處:a] [因:b]\n"
          f"  WHY:連結帶翻案決策 [出處:a] [因:b]{sup} [被取代:[[Systems/Live#d2]]]\n"
          f"  WHY:連結帶現行決策 [出處:a] [因:b]{sup} [被取代:[[Systems/Live#d1|看這裡]]]", body="# R\n")
    lines = m._doctor_replacement_lines(m.Env(v))
    check("①沒標作廢的散文提到鍵名不列;[[X#d2]] 翻案列出、[[X#d1|別名]] 不列", len(lines) == 1 and "d2" in lines[0], str(lines))
    # ②S18 重驗寫法:超大週數與拼錯閘名列成提醒、不崩;③五種比較
    now = _dt.datetime(2026, 10, 2, 12, 0, tzinfo=_dt.timezone.utc)
    v = mkvault()
    rules = ("  RULE:甲超大 [依據:人] [since:2026-06-01] [retire:度量 note-shape.blocked < 1 近99999999999週]\n"
             "  RULE:乙拼錯 [依據:人] [since:2026-06-01] [retire:度量 nosuchgate.blocked == 0 近4週]\n"
             "  RULE:丙小於等於 [依據:人] [since:2026-06-01] [retire:度量 note-shape.blocked <= 6 近4週]\n"
             "  RULE:丁等於 [依據:人] [since:2026-06-01] [retire:度量 note-shape.blocked == 6 近4週]\n"
             "  RULE:戊大於 [依據:人] [since:2026-06-01] [retire:度量 note-shape.blocked > 6 近4週]\n"
             "  RULE:己小於 [依據:人] [since:2026-06-01] [retire:度量 note-shape.blocked < 6 近4週]\n")
    write(v, "Systems/M.md", "type: system\nstatus: doing\nsummary: |-\n" + rules, body="# M\n")
    evs = ["2026-07-01T00:00:00+00:00"] + [f"2026-09-{d:02d}T00:00:00" for d in range(20, 26)]   # 近 6 筆不帶時區
    bad = ['{"ts": "9999-12-31T23:59:59", "gate": "note-shape", "kind": "blocked"}', "not json",
           '{"ts": "2026-07-02T00:00:00+00:00", "gate": "doctor-run", "kind": "ran"}']   # 最後一筆:暖機要兩筆舊紀錄
    (v.parent / ".governance-log.jsonl").write_text(
        "".join(_j.dumps({"ts": t, "gate": "note-shape", "kind": "blocked"}) + "\n" for t in evs) + "\n".join(bad) + "\n",
        encoding="utf-8")
    got = m._doctor_metric_lines(m.Env(v), v.parent, now=now)
    txt = "\n".join(got)
    check("②超大週數、拼錯閘名列成寫法不合、不崩", "甲超大" not in txt.split("寫法不合")[0] and txt.count("寫法不合") == 2, txt)
    check("③<= 與 == 成立、> 與 < 不成立(6 筆)", "丙小於等於" in txt and "丁等於" in txt and "戊大於" not in txt
          and "己小於" not in txt, txt)
    check("⑤沒帶時區的照本機時間算進去、9999 年那筆只跳那一行", "6 筆" in txt, txt)
    r = run(v, "doctor", "--verbose")
    seg = r.stdout.split("[S18]")[1].split("\n[")[0] if "[S18]" in r.stdout else ""
    check("②doctor 跑完 S18 不崩、列出寫法不合", "寫法不合" in seg and "Traceback" not in r.stdout + r.stderr, seg[-400:])
    check("⑤帳增速那段遇到 9999 年那筆不整段跳過", "治理帳成長觀測跳過" not in r.stdout, r.stdout[-300:])
    rc = run(v, "doctor", "--ci")
    seg = rc.stdout.split("[S18]")[1].split("\n[")[0] if "[S18]" in rc.stdout else ""
    check("⑥--ci 不跑 S18", "--ci 不跑" in seg and "寫法不合" not in seg, seg[-300:])
    # ④lint-new 關掉認得
    root = Path(tempfile.mkdtemp(prefix="gctl-mg-"))
    (root / ".lumos").mkdir()
    (root / ".lumos" / "config.json").write_text(_j.dumps({"lint_new": {"gate": "off"}}))
    check("④lint-new 關掉時判得出 off", m._metric_gate_off(root, "lint-new", m._doctor_cfg_bytes(root)) is True, "")
    # ⑦S19 週與月
    facts = ("  FACT:甲兩週逾期 [來源:生產] [confirmed:2026-09-15] [recheck:2週]\n"
             "  FACT:乙一月未到 [來源:生產] [confirmed:2026-09-05] [recheck:1月]\n"
             "  FACT:丙一月逾期 [來源:生產] [confirmed:2026-08-31] [recheck:1月]\n"
             "  FACT:戊三週未到 [來源:生產] [confirmed:2026-09-15] [recheck:3週]\n"
             "  FACT:丁控制字元\x1b[2J [來源:生產] [confirmed:2020-01-01]\n")
    v = mkvault()
    write(v, "Systems/F.md", "type: system\nstatus: doing\nsummary: |-\n" + facts, body="# F\n")
    txt = "\n".join(m._doctor_fact_recheck_lines(m.Env(v), _dt.date(2026, 10, 2)))
    check("⑦週=7 天、月=30 天", "甲兩週逾期" in txt and "乙一月未到" not in txt and "丙一月逾期" in txt
          and "戊三週未到" not in txt, txt)
    check("⑧印出前清控制字元", "\x1b" not in txt and "丁控制字元" in txt, repr(txt[-200:]))
    # ⑨檔尾截斷丟掉切一半的頭一行
    gp = Path(tempfile.mkdtemp(prefix="gctl-tail-")) / "g.jsonl"
    gp.write_bytes(b'{"a": 1}\n{"b": 2}\n{"c": 3}\n')
    raw, start = m._gov_tail_bytes(gp, cap=12)
    check("⑨只讀檔尾、切一半的頭一行丟掉", start > 0 and raw == b'{"c": 3}\n', repr(raw))
    # ⑩S16 接回續行:[confirmed:] 寫在續行的不算沒寫
    notes = {"Systems/S.md": m._note_from_text("Systems/S.md", "---\ntype: system\nstatus: doing\nsummary: |-\n"
                                                "  RULE:甲 [依據:人] [since:2026-01-01] [retire:人裁] [until:2027-01-01]\n"
                                                "    [confirmed:2026-09-30]\n---\n# S\n", 0)}
    lines, _st = m._doctor_stale_rules(notes, _dt.date(2026, 10, 2))
    check("⑩S16 欄位寫在續行照讀到", lines == [], str(lines))
    print("  ✓ t_slots_doctor_reminders_edges")


def t_slots_doctor_reminders_r2():
    """筆記格子第 3 步代碼審 r2 折入:單行 summary 也判(S16、S19)、S17 與 S18 也清控制字元、[[X#d2|別名]] 照查決策、
    S18 算不出來 fail-open 不讓 doctor 中斷、讀設定檔捷徑不跟、lint-new 用已讀好的設定。
    翻紅釘:_note_summary_entries 不補單行 → ①紅;S17 拿掉 _esc_clean → ②紅;別名不切 → ③紅;S18 拿掉 try → ④紅(doctor 中斷);
    _doctor_cfg_bytes 拿掉捷徑檢查 → ⑤紅;_lint_new_config 不吃 text → ⑥紅。"""
    import io, contextlib, os as _o, json as _j, datetime as _dt
    m = _load_lumos_inproc()
    # ①單行 summary(含引號)
    notes = {"Systems/A.md": m._note_from_text("Systems/A.md", "---\ntype: system\nstatus: doing\n"
                                                "summary: RULE:甲單行 [依據:人] [since:2026-01-01] [retire:人裁] [until:2027-01-01]\n---\n# A\n", 0),
             "Systems/B.md": m._note_from_text("Systems/B.md", "---\ntype: system\nstatus: doing\n"
                                                'summary: "RULE:乙引號 [依據:人] [since:2026-01-01] [retire:人裁] [until:2027-01-01]"\n---\n# B\n', 0)}
    lines, _st = m._doctor_stale_rules(notes, _dt.date(2026, 10, 2))
    check("①S16 單行 summary 照判(含引號)", len(lines) == 2 and any("甲單行" in x for x in lines)
          and any("乙引號" in x for x in lines), str(lines))
    v = mkvault()
    write(v, "Systems/F.md", "type: system\nstatus: doing\nsummary: FACT:丙單行逾期 [來源:生產] [confirmed:2020-01-01]", body="# F\n")
    got = m._doctor_fact_recheck_lines(m.Env(v), _dt.date(2026, 10, 2))
    check("①S19 單行 summary 照判", len(got) == 1 and "丙單行逾期" in got[0] and ":4:" in got[0], str(got))
    # ②S17、S18 清控制字元;③[[X#d2|別名]] 照查決策
    v = mkvault()
    write(v, "Systems/Live.md", "type: system\nstatus: doing\ndecisions:\n  - id: d2\n    content: 翻案了\n    valid: false\n"
          "summary: |-\n  KEY:x", body="# L\n")
    write(v, "Systems/R.md", "type: system\nstatus: doing\nsummary: |-\n"
          "  WHY:甲 [出處:a] [因:b] [status:superseded] [被取代:[[Systems/No\x07pe]]]\n"
          "  WHY:乙 [出處:a] [因:b] [status:superseded] [被取代:[[Systems/Live#d2|別名]]]\n"
          "  RULE:丙\x1b]0;x\x07 [依據:人] [since:2026-01-01] [retire:度量 nosuch.blocked == 0 近4週]", body="# R\n")
    env = m.Env(v)
    l17 = m._doctor_replacement_lines(env)
    check("②S17 清控制字元", any("Systems/No" in x for x in l17) and not any("\x07" in x for x in l17), repr(l17))
    check("③[[X#d2|別名]] 照查決策、判翻案", any("d2" in x and "翻案" in x for x in l17), str(l17))
    l18 = m._doctor_metric_lines(env, v.parent)
    check("②S18 清控制字元", l18 and not any("\x1b" in x or "\x07" in x for x in l18), repr(l18))
    # ④S18 算不出來:fail-open,doctor 照跑完
    orig = m._doctor_metric_lines

    def boom(*a, **k):
        raise RuntimeError("壞了")
    m._doctor_metric_lines = boom
    buf = io.StringIO()
    try:
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(io.StringIO()):
            m.run_doctor(env, False, False)
    finally:
        m._doctor_metric_lines = orig
    out = buf.getvalue()
    check("④S18 算不出來只講一句、doctor 跑到 S19 之後", "度量式撤除條件觀測跳過" in out and "[S19]" in out, out[-400:])
    # ⑤讀設定檔:檔案或 .lumos 資料夾是捷徑都不跟
    root = Path(tempfile.mkdtemp(prefix="gctl-cfg-"))
    outside = Path(tempfile.mkdtemp(prefix="gctl-cfgout-")) / "c.json"
    outside.write_text(_j.dumps({"lint_new": {"gate": "off"}}))
    (root / ".lumos").mkdir()
    _o.symlink(outside, root / ".lumos" / "config.json")
    check("⑤config.json 是捷徑:不讀", m._doctor_cfg_bytes(root) is None, "")
    root2 = Path(tempfile.mkdtemp(prefix="gctl-cfg2-"))
    (outside.parent / "config.json").write_text(_j.dumps({"lint_new": {"gate": "off"}}))
    _o.symlink(outside.parent, root2 / ".lumos")
    check("⑤.lumos 資料夾是捷徑:不讀", m._doctor_cfg_bytes(root2) is None, "")
    # ⑥lint-new 用呼叫端讀好的設定(捷徑那份不讀,所以不算關)
    check("⑥lint-new 吃已讀好的設定:捷徑指到的 off 不算", m._metric_gate_off(root, "lint-new", m._doctor_cfg_bytes(root)) is False, "")
    check("⑥lint-new 吃已讀好的設定:給 off 就是 off",
          m._lint_new_config(root, text=b'{"lint_new": {"gate": "off"}}', from_snapshot=True)["mode"] == "off", "")
    print("  ✓ t_slots_doctor_reminders_r2")


def t_slots_retire_issue_followups():
    """撤除條件末輪遺留四項(Issues/撤除條件檢查末輪遺留四項):①續行行號下 --kind retire 擋下;②印出途中出錯不改判定、只記一筆;
    ③判定途中出錯記一筆沒判(條數 null、帶 error);④只判不了時記 warned、成立擋下時 hard 與 nodes、起點不是字串記空字串。
    翻紅釘:cmd_drift_ack 拿掉條目第一行檢查 → ①紅;_drift_retire_report 不包印出 → ②紅;兜底條數記 0 → ③紅。"""
    m = _load_lumos_inproc()
    head = "RULE:要人簽 [依據:人] [since:2026-09-01]"
    # ①續行行號
    root = _dr_repo()
    _rt_push(root, [head, "  [retire:when-file:src/a.py]"], files=("src/a.py",), msg="rule")
    import subprocess as sp
    r = sp.run([sys.executable, GRAPHCTL, "drift", "ack", "Systems/Pay", str(_rt_line(root, head) + 1), "--kind", "retire",
                "--reason", "這條還在用照留"], capture_output=True, text=True, cwd=str(root))
    check("①續行行號:擋下、講要用第一行", r.returncode == 2 and "不是摘要裡一條的第一行" in r.stderr, r.stderr[-300:])
    arc, _t = _rt_ack(root, _rt_line(root, head))
    check("①第一行照收", arc == 0, "")
    rule = head + " [retire:when-file:src/new.py]"
    # ②印出途中出錯:判定照舊(rc1)、只記一筆
    root = _dr_repo()
    base = _rt_push(root, [rule], msg="rule")
    tip = _rt_push(root, [rule], files=("src/new.py",), msg="add file")

    def boom(*a, **k):
        raise RuntimeError("x")
    rc, out = _rt_inproc(m, root, base, tip, _drift_print_findings=boom)
    ev = _rt_events(root)
    check("②印出出錯:照擋、講一句、只記一筆", rc == 1 and "印到一半出錯" in out and len(ev) == 1
          and ev[0].get("kind") == "blocked", str(ev)[-300:] + out[-300:])
    check("④成立擋下:hard、nodes、條數、起點", ev and ev[0].get("hard") is True and ev[0].get("nodes") == ["Systems/Pay"]
          and ev[0].get("handle") == 1 and ev[0].get("listed") == 0 and ev[0].get("base_sha") == base, str(ev)[-400:])
    # ②b記帳拋 OSError 以外的例外:不往外冒、判定照舊(代碼審 code-筆記格子第3步 r1 併發資源席)
    rc, out = _rt_inproc(m, root, base, tip, _drift_retire_ledger=boom)
    check("②b記帳出錯:照擋、講一句、不冒出去", rc == 1 and "這一筆帳沒寫進去" in out, out[-300:])
    # ③判定途中出錯:不擋、記一筆沒判
    root = _dr_repo()
    base = _rt_push(root, [rule], msg="rule")
    tip = _rt_push(root, [rule], files=("src/new.py",), msg="add file")
    orig = m._drift_probe_check

    def judge_boom(*a, **k):
        if k.get("kind") == "retire":
            raise RuntimeError("x")
        return orig(*a, **k)
    rc, out = _rt_inproc(m, root, base, tip, _drift_probe_check=judge_boom)
    ev = _rt_events(root)
    check("③判定出錯:不擋、記一筆條數 null 帶 error", rc == 0 and len(ev) == 1 and ev[0].get("handle") is None
          and ev[0].get("listed") is None and ev[0].get("error") == "RuntimeError", str(ev)[-300:])
    # ④只判不了:記 warned、不 hard
    root = _dr_repo()
    base = _rt_push(root, [rule], msg="rule")
    tip = _rt_push(root, [rule], files=("src/new.py",), msg="add file")
    rc, out = _rt_inproc(m, root, base, tip, _DRIFT_RETIRE_BUDGET_SEC=-1)
    ev = _rt_events(root)
    check("④只判不了:一筆 warned、handle 0、listed ≥1、不 hard", rc == 0 and len(ev) == 1 and ev[0].get("kind") == "warned"
          and ev[0].get("handle") == 0 and ev[0].get("listed", 0) >= 1 and ev[0].get("hard") is False, str(ev)[-300:])
    # ④起點不是字串記空字串
    import io, contextlib
    root = _dr_repo()
    with contextlib.redirect_stderr(io.StringIO()):
        m._drift_retire_ledger(root, "warned", "x", False, ("bad", "起點算不出來"), "abc", [], {"handle": 0, "listed": 1})
    ev = _rt_events(root)
    check("④起點不是字串記空字串", ev and ev[-1].get("base_sha") == "", str(ev)[-200:])
    print("  ✓ t_slots_retire_issue_followups")


def t_slots_doctor_bypass_scan():
    """doctor 事後掃描:格子上線後已推上遠端卻缺格子的新增行要列出(多半是 --no-verify 繞過)。
    翻紅釘:_note_shape_doctor_lines 的 sv 改成 [] → 紅(代碼審 code-筆記格子第1步 r1 通才席:原本拿掉沒測試會紅)。"""
    import subprocess as sp
    root, _g = _slot_golive_repo()
    _ns_note(root, summary="KEY:x\nWHY:繞過推上去的缺格子句")
    _nh_commit(root, "bypass")
    bare = Path(tempfile.mkdtemp(prefix="gctl-slot-doc-")) / "r.git"
    sp.run(["git", "init", "-q", "--bare", str(bare)], capture_output=True)
    _nh_git(root, "remote", "add", "origin", str(bare))
    br = _nh_git(root, "rev-parse", "--abbrev-ref", "HEAD").stdout.strip()
    _nh_git(root, "push", "-q", "--no-verify", "origin", br)
    _nh_git(root, "fetch", "-q", "origin")
    m = _load_lumos_inproc()
    lines = m._note_shape_doctor_lines(root, root / "docs" / "kg-knowledge", ci=False)
    check("已推上遠端卻有格子缺漏的新增行要列出", any("筆記格子缺漏的新增行" in x and "A.md" in x for x in lines), str(lines))
    print("  ✓ t_slots_doctor_bypass_scan")


