def t_slots_ledger_fields():
    """[S15] 擋下事件帶 slots_lines/slots_missing、路徑在 nodes;提交時單次跳過也帶;跳過前算格子出錯照樣放行、只記不帶格子欄位的跳過。
    翻紅釘:_note_shape_report 不帶 extra → ①紅;_ns_skip_slot_extra 拿掉例外防護 → ③替身炸出測試。"""
    rc, out, root = _slot_try("WHY:缺格子的一句")
    ev = _neg_events(root, "blocked")
    check("①擋下事件帶格子欄位(check=slots)", ev and ev[-1].get("check") == "slots" and ev[-1].get("slots_lines") == 1
          and ev[-1].get("slots_missing", {}).get("出處") == 1 and any("A" in n for n in ev[-1].get("nodes", [])), str(ev))
    check("①只因格子擋時不印筆記形狀擋的收尾句", "推得出來的一寫進去就會過期" not in out, out[-500:])
    rc, out, root = _slot_try("PITFALL:空清單靜默成功 [出處:a] [根因:b]")
    ev = _neg_events(root, "blocked")
    check("①三選一的缺漏也算進各格缺漏(結構化,不從字樣反推)",
          ev and ev[-1].get("slots_missing", {}).get("test/repro/防回歸") == 1, str(ev))
    root = _ns_repo()
    _ns_note(root, summary="KEY:x\nWHY:缺格子的一句")
    _ns_stage(root)
    rc, _out = _ns(root, "--staged", "--slots", env={"LUMOS_SKIP_NOTE_SHAPE": "1"})
    ev = _neg_events(root, "skipped-env")
    check("②單次跳過(提交時、帶 --slots)也帶格子欄位", rc == 0 and ev and ev[-1].get("slots_lines") == 1, str(ev))
    import os as _o
    root = _ns_repo()
    _ns_note(root, summary="KEY:x\nWHY:缺格子的一句")
    _ns_stage(root)
    _o.environ["LUMOS_SKIP_NOTE_SHAPE"] = "1"
    try:
        def _boom(*a, **k):
            raise RuntimeError("boom")
        m = _load_lumos_inproc()
        orig = m._ns_slots_violations
        m._ns_slots_violations = _boom
        import io, contextlib
        buf = io.StringIO()
        with contextlib.redirect_stderr(buf), contextlib.redirect_stdout(buf):
            rc = m.cmd_note_shape(repo=str(root), staged=True, slots_flag=True)
    finally:
        m._ns_slots_violations = orig
        _o.environ.pop("LUMOS_SKIP_NOTE_SHAPE", None)
    ev = _neg_events(root, "skipped-env")
    check("③跳過前算格子出錯:照樣放行、跳過事件不帶格子欄位", rc == 0 and ev and "slots_lines" not in ev[-1], str(ev))
    print("  ✓ t_slots_ledger_fields")


def t_refresh_delta():
    """T3:refresh_labels delta——已判不重出/未標全出/orphan 列出/file-gone skip/卷頭註記/rc 合約。"""
    _need_src("governance/eval")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    root, gs = _mk_eval_fixture()
    gs["labels"]["S01"]["Projects/Old.md"] = {"final": 1}   # orphan:標過但語料無此檔
    gpath = root / "goldset.json"
    gpath.write_text(_json.dumps(gs, ensure_ascii=False), encoding="utf-8")
    out = root / "delta"
    r = subprocess.run([sys.executable, str(repo / "governance" / "eval" / "refresh_labels.py"),
                        "delta", "--goldset", str(gpath), "--repo", str(root),
                        "--json", "--out", str(out)], capture_output=True, text=True)
    check("delta rc0", r.returncode == 0, r.stderr[-300:])
    d = _json.loads((Path(str(out) + ".json")).read_text(encoding="utf-8"))
    s01 = next((c["unjudged"] for c in d["cases"] if c["id"] == "S01"), [])
    check("未標全出(Gamma 在)", "Projects/Gamma.md" in s01, str(d["cases"]))
    check("已判不重出(Beta 不在)", "Systems/Beta.md" not in s01, str(s01))
    e01 = next((c["unjudged"] for c in d["cases"] if c["id"] == "E01"), [])
    check("已判0 不重出(Alpha 不在)", "Systems/Alpha.md" not in e01, str(e01))
    check("orphan 列出", any("Projects/Old.md" in o for o in d["orphans"]), str(d["orphans"]))
    check("file-gone 進 skipped", any(x.startswith("E02") for x in d["skipped"]), str(d["skipped"]))
    check("count/denom/rate 齊", all(k in d for k in ("count", "denom", "rate")), str(d)[:200])
    sheet = Path(str(out) + "-sheet.md").read_text(encoding="utf-8")
    check("卷頭註明 delta 片段", "delta 片段" in sheet and "不連號屬正常" in sheet, sheet[:200])
    check("sheet 僅未標列(Beta 不在)", "Systems/Beta.md" not in sheet, sheet[:400])
    r2 = subprocess.run([sys.executable, str(repo / "governance" / "eval" / "refresh_labels.py"),
                         "delta", "--goldset", str(root / "沒有.json"), "--repo", str(root)],
                        capture_output=True, text=True)
    check("goldset 缺=rc2", r2.returncode == 2, str(r2.returncode))


def t_delta_sheet_is_shuffled():
    """[S8] 未標清單端給標註者之前要洗牌(Projects/評測尺修復_計劃)。

    出身:建題庫那支腳本早就在洗(`rnd.shuffle(pool)` 兩處),但增量補標這支
    ★原樣沿用未標判定回傳的有序清單★——而那個順序就是現行排序的名次。
    把「系統認為誰該排前面」先告訴標註者,標出來的答案就不再獨立於被它驗證的排序,
    而那些答案正是不可逆尺切換的依據(2026-09-15 代碼審資安席獨立再撞到一次)。

    ★洗牌要可重現★:同一份題庫跑兩次順序必須一樣,否則標註結果回溯不到當初看的是什麼。

    翻紅釘(條號為實測值,2026-09-15 測試品質席逐條核對):把 cmd_delta 的洗牌整段拆光
    → ★第 1、4 條★翻紅(「順序不是名次序」與「上游被打亂時輸出仍一樣」);
    「同一份題庫跑兩次一樣」那條仍是綠的,因為不洗牌本來就穩定。
    ★原本寫第 1、2 條是錯的★——這種「憑推想寫翻紅釘」的錯,同一批工作已經犯第三次。"""
    _need_src("governance/eval")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    root, gs = _mk_eval_fixture()
    # 造一題有 12 個未標候選,名次序就是 N00..N11;候選夠多才看得出洗牌
    kg = root / "docs" / "kg-knowledge" / "Systems"
    names = [f"N{i:02d}.md" for i in range(12)]
    for n in names:
        (kg / n).write_text("---\ntype: system\nstatus: done\n---\n# " + n[:-3]
                            + "\nzebrafish 測試節點。\n", encoding="utf-8")
    gs["labels"].setdefault("S01", {})
    gpath = root / "goldset-shuffle.json"
    gpath.write_text(_json.dumps(gs, ensure_ascii=False), encoding="utf-8")
    _rlpath = repo / "governance" / "eval" / "refresh_labels.py"
    def _run(out):
        r = subprocess.run([sys.executable, str(_rlpath),
                            "delta", "--goldset", str(gpath), "--repo", str(root),
                            "--json", "--out", str(out)], capture_output=True, text=True)
        assert r.returncode == 0, f"delta 沒跑起來:{r.stderr[-300:]}"
        d = _json.loads((Path(str(out) + ".json")).read_text(encoding="utf-8"))
        return {c["id"]: c["unjudged"] for c in d["cases"]}
    first = _run(root / "d1")
    second = _run(root / "d2")
    # 找一個候選數 ≥4 的案例來比對(太少的話洗不洗都可能同序)
    cid = next((k for k, v in first.items() if len(v) >= 4), None)
    check("★前置★ 有候選數夠多的案例可驗(不然這支測試等於空過)", cid is not None,
          f"各案例候選數:{ {k: len(v) for k, v in first.items()} }")
    if cid is None:
        print("  ✓ t_delta_sheet_is_shuffled")
        return
    _m = _load_retrieval_eval(root)   # 本檔既有的共用夾具輔助,不自己重寫載入樣板
    ranked = _m.collect_unjudged(gs)["per_case"].get(cid, [])
    check("★端出去的順序不是名次序★(名次序=先告訴標註者系統認為誰該排前面)",
          list(first[cid]) != list(ranked) or len(ranked) < 4,
          f"洗過:{first[cid][:5]}\n名次:{list(ranked)[:5]}")
    check("★同一份題庫跑兩次順序一樣★(不可重現的話標註結果回溯不到當初看的是什麼)",
          first[cid] == second[cid], f"第一次:{first[cid][:5]}\n第二次:{second[cid][:5]}")
    check("洗牌不得增減候選(只換順序)", sorted(first[cid]) == sorted(ranked),
          f"洗過 {len(first[cid])} 個、名次 {len(ranked)} 個")
    # ★上游順序不穩定時也要洗得出同一個結果★(2026-09-15 真實資料上實測踩到:
    #  同一份題庫同一份語料連跑三次,有四題的候選順序跑出不同排法;直接洗不穩定的輸入
    #  等於同種子也洗不出同結果,「可重現」是假的)。夾具的順序是穩的,所以這條要
    #  ★自己把輸入打亂再餵★,不然測試會在夾具上空過、真實資料上才爆。
    # ★驗產品真的先正規化再洗,不是測試自己算一遍★(前一版就是這樣空過的:
    #  把產品端的 sorted 拿掉,測試照樣全綠)。做法=匯入那支腳本、換掉它拿未標清單的入口,
    #  讓上游回傳「同一批候選但順序被打亂」,再跑一次真的 delta,看吐出來的表一不一樣。
    import importlib.util as _iu, random as _rnd
    _spec = _iu.spec_from_file_location("_rl_probe", _rlpath)
    _rl = _iu.module_from_spec(_spec); _spec.loader.exec_module(_rl)
    _orig_load = _rl._load_re
    def _load_shuffled():
        _mm = _orig_load()
        _oc = _mm.collect_unjudged
        def _spy(_gs, split=None, k=8):
            _u = _oc(_gs, split, k=k)
            for _c in _u["per_case"]:
                _l = list(_u["per_case"][_c]); _rnd.Random(99).shuffle(_l)
                _u["per_case"][_c] = _l
            return _u
        _mm.collect_unjudged = _spy
        return _mm
    # ★為什麼一定要到這一層★(2026-09-15 架構對齊席指出這比既有白箱前例深一層):
    # 要驗的行為是「產品拿到★順序不穩定★的上游時,吐出來的表仍然一樣」,
    # 所以非得讓上游回傳打亂過的順序不可;而上游是子行程內部才載入的,
    # 走 CLI 注入不進去。既有前例(t_refresh_atomic_and_lock)同樣是匯入模組換掉裡面的東西,
    # 形狀一致——差別只在那支換的是私有小函式、這支換的是模組級輔助。
    # ★照前例補上 finally 還原★,不讓替身洩漏到同一行程的其他測試。
    _rl._load_re = _load_shuffled
    import types as _types   # 用本檔既有慣例造 args(參數解析包在 main 裡,沒有獨立入口可借)
    _args = _types.SimpleNamespace(goldset=str(gpath), repo=str(root), snapshot=None,
                                   split=None, json=True, out=str(root / "d3"))
    import io as _io, contextlib as _cl
    try:
        with _cl.redirect_stdout(_io.StringIO()), _cl.redirect_stderr(_io.StringIO()):
            _rc = _rl.cmd_delta(_args)
    finally:
        _rl._load_re = _orig_load
    check("★前置★ 上游被換掉之後 delta 仍跑得起來(跑不起來=下一條驗不到)", _rc == 0, f"rc={_rc}")
    _p3 = Path(str(root / "d3") + ".json")
    check("★前置★ 探針有產出檔", _p3.exists(), str(_p3))
    if _rc == 0 and _p3.exists():
        third = {c["id"]: c["unjudged"] for c in _json.loads(_p3.read_text(encoding="utf-8"))["cases"]}
        check("★上游順序被打亂時吐出來的表仍要一樣★(產品端要先正規化再洗,不是直接洗)",
              third.get(cid) == first[cid],
              f"原本:{first[cid][:3]}\n上游打亂後:{third.get(cid, [])[:3]}")
    print("  ✓ t_delta_sheet_is_shuffled")


def t_rater_material_has_no_labels():
    """[S13] 評審拿到的材料不得含既有答案(Projects/評測尺修復_計劃;實跑逃逸 2026-09-15)。

    出身:派工詞叫評審去讀題庫檔取查詢字串,★但那個檔裡同時就存著既有標註答案★——
    某席實跑時自陳「初讀題庫時意外顯示部分既有 labels」,治理帳已記一筆逃逸。
    這跟 [S8] 的名次洩漏是★兩條不同的錨定路徑★,補了一條不等於補了另一條。

    修法=產一份只含題目、不含任何標註的材料檔給評審讀。
    翻紅釘:讓材料檔改成直接複製整份題庫 → 第 2、3 條翻紅(答案跟著跑進去)。"""
    _need_src("governance/eval")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    root, gs = _mk_eval_fixture()
    # 夾具的答案要夠特別,才驗得出「有沒有漏進材料」
    gs["labels"]["S01"]["Systems/Beta.md"] = {"final": 2, "claude": 2, "codex": 1}
    gpath = root / "goldset-mat.json"
    gpath.write_text(_json.dumps(gs, ensure_ascii=False), encoding="utf-8")
    out = root / "material.md"
    r = subprocess.run([sys.executable, str(repo / "governance" / "eval" / "refresh_labels.py"),
                        "material", "--goldset", str(gpath), "--out", str(out)],
                       capture_output=True, text=True)
    check("material 子命令跑得起來", r.returncode == 0, r.stderr[-400:])
    if r.returncode != 0:
        print("  ✓ t_rater_material_has_no_labels")
        return
    txt = out.read_text(encoding="utf-8")
    check("★材料裡找不到任何標註欄位名★(final/claude/codex 都是答案欄)",
          not any(w in txt for w in ("final", '"claude"', '"codex"', "labels")),
          txt[:400])
    check("★材料裡找不到既有答案的節點路徑★(有答案的節點名本身就是提示)",
          "Systems/Beta.md" not in txt, txt[:400])
    check("題目本身要在(不然材料沒用)", "zebrafish" in txt and "S01" in txt, txt[:300])
    check("編輯題的檔名也要在", "src/app.py" in txt, txt[:400])
    # ★答案也可能從編輯題的「改動片段」流進來★(2026-09-15 外家席 blocker):
    # 那個欄位是★原封不動抄來的程式片段★,而這個 repo 的註解到處寫節點路徑;
    # 現況題庫剛好零命中,但那是運氣不是守衛——防線要擋在輸出端。
    gs2 = _json.loads(gpath.read_text(encoding="utf-8"))
    gs2["edit"][0]["delta"] = "# 見 Systems/Beta.md 的說明;另參 Projects/Gamma.md"
    gpath.write_text(_json.dumps(gs2, ensure_ascii=False), encoding="utf-8")
    out2 = root / "material2.md"
    r2 = subprocess.run([sys.executable, str(repo / "governance" / "eval" / "refresh_labels.py"),
                         "material", "--goldset", str(gpath), "--out", str(out2)],
                        capture_output=True, text=True)
    check("改動片段帶節點路徑時 material 仍跑得起來", r2.returncode == 0, r2.stderr[-300:])
    txt2 = out2.read_text(encoding="utf-8") if out2.exists() else ""
    check("★改動片段裡的節點路徑不得原樣印出★(有答案的節點名本身就是提示)",
          "Systems/Beta.md" not in txt2 and "Projects/Gamma.md" not in txt2, txt2[:400])
    check("擋掉路徑之後,那一題本身還在(不是整題消失)",
          "E01" in txt2, txt2[:300])
    print("  ✓ t_rater_material_has_no_labels")


def t_refresh_repin():
    """T4:repin 機械閘——未標>0 rc1 且 goldset 逐位元不變;全判後 rc0 僅 snapshot_commit 變;壞輸入 rc2。"""
    _need_src("governance/eval")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    script = repo / "governance" / "eval" / "refresh_labels.py"
    root, gs = _mk_eval_fixture()
    gpath = root / "goldset.json"
    gpath.write_text(_json.dumps(gs, ensure_ascii=False), encoding="utf-8")
    before = gpath.read_bytes()
    r = subprocess.run([sys.executable, str(script), "repin", "--goldset", str(gpath),
                        "--repo", str(root)], capture_output=True, text=True)
    check("未標>0 → rc1 硬擋", r.returncode == 1, f"rc={r.returncode}\n{r.stderr[-300:]}")
    # ★2026-09-15 翻掉這條舊斷言★(外家席指出這是第三條洩漏路徑):原本要求失敗訊息
    # ★逐筆印出候選★,而那順序就是現行排序的名次——只要標註者看得到這段診斷輸出,
    # 待標清單洗牌就前功盡棄。現在改成「給數量與去哪拿洗過的清單,但不列候選」。
    check("★rc1 不得逐筆印出候選★(那順序就是名次,等於繞過洗牌)",
          "Projects/Gamma.md" not in r.stderr, r.stderr[-400:])
    check("rc1 仍要講得出還差幾筆(不能只說失敗)", "未標" in r.stderr, r.stderr[-400:])
    check("rc1 要指路去拿洗過順序的清單", "delta" in r.stderr, r.stderr[-400:])
    check("rc1 時 goldset 逐位元不變", gpath.read_bytes() == before, "")
    # 補齊全部未標(用 delta --json 取清單,照單全判 0)
    out = root / "d2"
    subprocess.run([sys.executable, str(script), "delta", "--goldset", str(gpath),
                    "--repo", str(root), "--json", "--out", str(out)],
                   capture_output=True, text=True)
    d = _json.loads(Path(str(out) + ".json").read_text(encoding="utf-8"))
    gs2 = _json.loads(gpath.read_text(encoding="utf-8"))
    for c in d["cases"]:
        for n in c["unjudged"]:
            gs2["labels"].setdefault(c["id"], {})[n] = {"final": 0}
    gpath.write_text(_json.dumps(gs2, ensure_ascii=False), encoding="utf-8")
    head = subprocess.run(["git", "-C", str(root), "rev-parse", "--short", "HEAD"],
                          capture_output=True, text=True).stdout.strip()
    r2 = subprocess.run([sys.executable, str(script), "repin", "--goldset", str(gpath),
                         "--repo", str(root), "--target", head],
                        capture_output=True, text=True)
    check("全判後 rc0", r2.returncode == 0, r2.stderr[-300:] + r2.stdout[-200:])
    gs3 = _json.loads(gpath.read_text(encoding="utf-8"))
    check("snapshot_commit 更新為 target", gs3["snapshot_commit"] == head, gs3["snapshot_commit"])
    gs2["snapshot_commit"] = head
    check("其餘鍵零變動(labels 原樣)", gs3 == gs2, "")
    r3 = subprocess.run([sys.executable, str(script), "repin", "--goldset", str(root / "無.json"),
                         "--repo", str(root)], capture_output=True, text=True)
    check("壞輸入 rc2", r3.returncode == 2, str(r3.returncode))


def t_eval_history_record_fields():
    """T5:_history_record 純函式——goldset_snapshot/unjudged_count/unjudged_rate 三欄;
    --snapshot 覆寫 → mode=goldset-transition(mode 為既有欄位)。"""
    _need_src("governance/eval")
    import types
    root, gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    unj = {"count": 3, "denom": 30, "rate": 0.1, "per_case": {}, "skipped": []}
    args = types.SimpleNamespace(k=8, snapshot=None)
    rec = m._history_record(args, gates={"g": True}, ok=True,
                            reports=[{"split": "held", "verdict": {"v": 1}}],
                            unj=unj, pinned_sha="285d429")
    check("mode 預設 goldset", rec["mode"] == "goldset", str(rec))
    check("goldset_snapshot 欄=實際釘定 sha", rec["goldset_snapshot"] == "285d429", str(rec))
    check("unjudged 兩欄在", rec["unjudged_count"] == 3 and rec["unjudged_rate"] == 0.1, str(rec))
    check("condensed_preview 巢狀欄在(一輪一筆;評測尺翻案 [S3]②)",
          "condensed_preview" in rec and isinstance(rec["condensed_preview"], dict), str(list(rec.keys())))
    check("verdicts 不重複塞 condensed(留 preview 單一出口)",
          all(not k.startswith("condensed_") for v in rec["verdicts"].values() for k in (v or {})), "")
    check("既有欄位仍在(ts/gates/pass/verdicts)",
          all(k in rec for k in ("ts", "gates", "pass", "verdicts")), str(rec))
    args2 = types.SimpleNamespace(k=8, snapshot="ab91051")
    rec2 = m._history_record(args2, gates={}, ok=False, reports=[], unj=None, pinned_sha="ab91051")
    check("--snapshot 覆寫 → mode=goldset-transition", rec2["mode"] == "goldset-transition", str(rec2))
    check("unj=None 時兩欄為 None(欄位仍在)",
          "unjudged_count" in rec2 and rec2["unjudged_count"] is None, str(rec2))


def t_eval_output_top3_must():
    """★指標乙案(2026-08-24 Enzo 裁):輸出前 3 名必看命中率——量人打開 hook 先看到的三行,不限固定席★。
    甲案版(pin_top3_must,只量固定席)實測是死表:必看 15/69 坐固定席、事故恆最前,前 3 席組成幾乎不變。
    分母 min(3, 標 2 總數);沒標 2 → None 不進平均;接線照 fusion_p(row→_macro→verdict→history,不進 gate)。
    history 舊 key pin_top3_must 不追改(語意不同,新 key 免混讀)。
    翻紅釘:把母體改回只取 pinned → 「free 也算」那條翻紅。"""
    _need_src("governance/eval")
    root, gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    P = lambda n: {"node": n, "pinned": True, "score": 1.0}
    F = lambda n: {"node": n, "pinned": False, "score": 0.5}
    check("前 3(含 free)全必看 → 1.0", m.output_top3_must([P("a"), F("b"), F("c")], {"a": 2, "b": 2, "c": 2}) == 1.0, "")
    check("★free 排第 2 的必看也算(乙案核心:不限固定席)★", m.output_top3_must([P("x"), F("a")], {"a": 2, "x": 0}) == 1.0, "")
    check("2 必看只 1 個進前 3 → 0.5", m.output_top3_must([P("a"), P("x"), P("y"), F("b")], {"a": 2, "b": 2}) == 0.5, "")
    check("5 必看前 3 全中 → 1.0(分母 min(3,5))", m.output_top3_must([F(c) for c in "abcde"], {c: 2 for c in "abcde"}) == 1.0, "")
    check("沒標 2 → None", m.output_top3_must([P("a")], {"a": 1}) is None, "")
    check("第 4 名以後不算", m.output_top3_must([F("x"), F("y"), F("z"), F("a")], {"a": 2}) == 0.0, "")
    canned = [P("Systems/Alpha.md"), P("Systems/Hub.md"), F("Projects/Gamma.md")]
    gs["labels"]["E01"] = {"Systems/Alpha.md": {"final": 2, "claude": 2, "codex": 2}, "Systems/Hub.md": {"final": 1, "claude": 1, "codex": 1}}
    m.edit_universe = lambda case: canned
    rows = m.eval_edit(gs)
    check("eval_edit row 有 out_top3_must", rows and all("out_top3_must" in r for r in rows), str(rows)[:200])
    check("row 不再有舊 key pin_top3_must", all("pin_top3_must" not in r for r in rows), "")
    rep = m.report_goldset(gs)
    check("★verdict 有 out_top3_must(接到 history)★", "out_top3_must" in rep["verdict"], str(rep["verdict"])[:300])
    src = open(m.__file__, encoding="utf-8").read()
    gates_src = src[src.find("gates = {"):src.find("gates = {") + 600]
    check("不進 gates", "top3" not in gates_src, gates_src[:200])


def t_eval_lane_buckets():
    """★pin-denoise-a-v4 eval 側:split_buckets 唯一分流+lane 口徑四釘★——
    ⑨cap 內 lane 計入 must_in_out 但不計 P@8 ⑮output_top3_must 母體不含 lane
    ⑪rescued 仍在 P@8 母體(誠實計噪護欄回歸)⑭觸及集 lane 視同 pins。
    翻紅釘:split_buckets 把 lane 併回 free → ⑨⑮ 翻紅。"""
    _need_src("governance/eval")
    root, gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    P = lambda n: {"node": n, "pinned": True, "score": 1.0}
    F = lambda n, s=0.5: {"node": n, "pinned": False, "score": s}
    RS = lambda n: {"node": n, "pinned": False, "rescued": True, "score": 0.3}
    LN = lambda n: {"node": n, "pinned": False, "lane": "soft-guard", "kind": "indirect", "score": 0.4}
    res = [P("p1"), F("f1"), RS("r1"), LN("l1")]
    pins, free, lane = m.split_buckets(res)
    check("分桶:pins/free(含 rescued)/lane", [x["node"] for x in pins] == ["p1"] and [x["node"] for x in free] == ["f1", "r1"] and [x["node"] for x in lane] == ["l1"], str((pins, free, lane)))
    check("★⑪rescued 在 free=P@8 母體(勿排,護欄回歸)★", any(x.get("rescued") for x in free), "")
    check("★⑭觸及集:lane 視同 pins★", "l1" in m._touched_edit(res) , str(m._touched_edit(res)))
    check("★⑮output_top3_must 母體不含 lane★", m.output_top3_must([LN("a"), F("b"), F("c"), F("d")], {"a": 2, "b": 2}) == 0.5, str(m.output_top3_must([LN("a"), F("b"), F("c"), F("d")], {"a": 2, "b": 2})))
    # ⑨:lane 計入 must_in_out、不計 P@8——走 eval_edit 全鏈
    gs["labels"]["E01"] = {"Systems/Alpha.md": {"final": 2, "claude": 2, "codex": 2}, "Systems/Lane.md": {"final": 2, "claude": 2, "codex": 2}}
    m.edit_universe = lambda case: [P("Systems/Alpha.md"), F("Systems/Free.md"), LN("Systems/Lane.md")]
    rows = m.eval_edit(gs)
    row = rows[0]
    check("★⑨lane 計入 must_in_out★", row["must_in_out"] == 2, str(row))
    check("⑨lane 不計 free 母體(n_free 只算真 free)", row["n_free"] == 1, str(row))
    # edit_pool 含 lane(⑬)
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    import importlib.util
    spec = importlib.util.spec_from_file_location("bg", str(repo / "governance" / "eval" / "build_goldset.py"))
    bg = importlib.util.module_from_spec(spec); spec.loader.exec_module(bg)
    bg.lum_json = lambda *a, **kw: ({"results": [{"node": "A.md"}], "lane": [{"node": "L.md", "lane": "soft-guard"}]} if "--ranked" in a else {"direct": [], "indirect": []})
    pool = bg.edit_pool("src/x.py", "delta")
    check("★⑬edit_pool 含 lane 候選★", "L.md" in pool and "A.md" in pool, str(pool))


def t_pin_noise_ratchet():
    """★固定席噪音棘輪(v4 #4b)★:同 rev PASS 基線、只准降不准升;無基線建基線;換 rev 不比。
    翻紅釘:方向反了(count<base 才擋)→ 第 2 條翻紅。"""
    _need_src("governance/eval")
    root, gs = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    H = [{"pass": True, "goldset_rev": "aaa", "verdicts": {"held": {"pin_noise": 40}}}]
    ok, msg = m.pin_noise_ratchet(H, "aaa", "held", 39)
    check("降了 → 過", ok is True, msg)
    ok2, msg2 = m.pin_noise_ratchet(H, "aaa", "held", 41)
    check("★漲了 → 擋★", ok2 is False and "漲" in msg2, msg2)
    ok3, msg3 = m.pin_noise_ratchet(H, "bbb", "held", 99)
    check("換 rev → 建基線放行", ok3 is True and "基線" in msg3, msg3)
    ok4, _ = m.pin_noise_ratchet([{"pass": False, "goldset_rev": "aaa", "verdicts": {"held": {"pin_noise": 1}}}], "aaa", "held", 99)
    check("FAIL 輪不當基線", ok4 is True, "")


def t_refresh_merge_apply():
    """T6:merge(一致=同值/1v2 人裁/B 缺 degraded)+apply(人放行寫入;缺人裁 rc1 不寫;atomic;既有零變動)。"""
    _need_src("governance/eval")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    script = repo / "governance" / "eval" / "refresh_labels.py"
    root, gs = _mk_eval_fixture()
    gpath = root / "goldset.json"
    gpath.write_text(_json.dumps(gs, ensure_ascii=False), encoding="utf-8")
    a = {"S01": {"Projects/Gamma.md": 2, "Systems/Hub.md": 1}}
    b = {"S01": {"Projects/Gamma.md": 2, "Systems/Hub.md": 2}}
    (root / "a.json").write_text(_json.dumps(a), encoding="utf-8")
    (root / "b.json").write_text(_json.dumps(b), encoding="utf-8")
    r = subprocess.run([sys.executable, str(script), "merge", "--a", str(root / "a.json"),
                        "--b", str(root / "b.json"), "--out", str(root / "m.json"), "--json"],
                       capture_output=True, text=True)
    check("merge rc0", r.returncode == 0, r.stderr[-200:])
    m = _json.loads((root / "m.json").read_text(encoding="utf-8"))
    check("同值→agreed(Gamma=2)", m["agreed"].get("S01", {}).get("Projects/Gamma.md") == 2, str(m))
    check("1v2→disputed(Hub)", "Systems/Hub.md" in m["disputed"].get("S01", {}), str(m))
    check("非 degraded", m["degraded"] is False, str(m))
    r2 = subprocess.run([sys.executable, str(script), "merge", "--a", str(root / "a.json"),
                         "--b", str(root / "沒有.json"), "--out", str(root / "m2.json")],
                        capture_output=True, text=True)
    m2 = _json.loads((root / "m2.json").read_text(encoding="utf-8"))
    check("B 缺→degraded 且全 disputed", m2["degraded"] is True and not m2["agreed"]
          and "Projects/Gamma.md" in m2["disputed"].get("S01", {}), str(m2))
    # apply:缺人裁 → rc1 不寫
    before = gpath.read_bytes()
    r3 = subprocess.run([sys.executable, str(script), "apply", "--merge", str(root / "m.json"),
                         "--goldset", str(gpath)], capture_output=True, text=True)
    check("apply 缺人裁 rc1", r3.returncode == 1, str(r3.returncode) + r3.stderr[-200:])
    check("rc1 不寫(goldset 位元不變)", gpath.read_bytes() == before, "")
    adj = {"S01": {"Systems/Hub.md": {"final": 1, "by": "user", "why": "字面碰到而已"}}}
    (root / "adj.json").write_text(_json.dumps(adj, ensure_ascii=False), encoding="utf-8")
    r4 = subprocess.run([sys.executable, str(script), "apply", "--merge", str(root / "m.json"),
                         "--goldset", str(gpath), "--adjudication", str(root / "adj.json"),
                         "--note", "test 放行"], capture_output=True, text=True)
    check("apply 齊備 rc0", r4.returncode == 0, r4.stderr[-200:])
    gs2 = _json.loads(gpath.read_text(encoding="utf-8"))
    g = gs2["labels"]["S01"]["Projects/Gamma.md"]
    check("agreed 寫入 final/claude/gemini/labeled_at",
          g["final"] == 2 and g["claude"] == 2 and g["gemini"] == 2 and "labeled_at" in g, str(g))
    h = gs2["labels"]["S01"]["Systems/Hub.md"]
    check("disputed 寫入含 by/why 與兩席原值",
          h["final"] == 1 and h["by"] == "user" and h["why"] == "字面碰到而已"
          and h["claude"] == 1 and h["gemini"] == 2, str(h))
    check("既有已判鍵零變動(Beta 原樣)",
          gs2["labels"]["S01"]["Systems/Beta.md"] == {"final": 1, "claude": 1, "codex": 1}, str(gs2["labels"]["S01"]))


def t_refresh_signal():
    """T7:signal——讀 history 最後一筆考卷輪的 unjudged_rate;無欄=NA;超線 over=yes;恆 rc0。"""
    _need_src("governance/eval")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    script = repo / "governance" / "eval" / "refresh_labels.py"
    d = Path(tempfile.mkdtemp(prefix="gctl-signal-"))
    def _run(lines):
        h = d / f"h{len(lines)}.jsonl"
        h.write_text("\n".join(_json.dumps(x) for x in lines) + "\n", encoding="utf-8")
        return subprocess.run([sys.executable, str(script), "signal", "--history", str(h)],
                              capture_output=True, text=True)
    r1 = _run([{"mode": "goldset", "ts": "2026-08-01"}])
    check("無欄=NA 且 rc0", r1.returncode == 0 and "unjudged_rate=NA" in r1.stdout, r1.stdout)
    r2 = _run([{"mode": "goldset", "unjudged_rate": 0.04, "unjudged_count": 3},
               {"mode": "auto-cochange", "unjudged_rate": 0.99}])
    check("取最後一筆考卷輪(auto 列不算)、未超線 over=no",
          "unjudged_rate=0.04" in r2.stdout and "over=no" in r2.stdout, r2.stdout)
    r3 = _run([{"mode": "goldset", "unjudged_rate": 0.04},
               {"mode": "goldset-transition", "unjudged_rate": 0.12, "unjudged_count": 9}])
    check("transition 輪也算考卷輪、超線 over=yes",
          "unjudged_rate=0.12" in r3.stdout and "over=yes" in r3.stdout, r3.stdout)
    r4 = subprocess.run([sys.executable, str(script), "signal", "--history", str(d / "無.jsonl")],
                        capture_output=True, text=True)
    check("history 缺=rc2", r4.returncode == 2, str(r4.returncode))


def t_eval_touched_universe_bounds():
    """T8 落地後發現修正:評測母體=「計分觸及集」——search 兩臂各取前 10、
    edit=★三條排法各自前 k 的聯集★+全部 pins(2026-09-15 起;原本只有綜合那條)。
    全母體口徑實測連原快照都 54% 未標(金標只批過出卷小池)→ repin 永不可過,母體必須收斂到
    「未標了會實際影響分數」的位置。純函式直測邊界。"""
    _need_src("governance/eval")
    root, _ = _mk_eval_fixture()
    m = _load_retrieval_eval(root)
    legacy = [f"L{i}.md" for i in range(15)]
    ranked = [f"R{i}.md" for i in range(15)] + ["L3.md"]
    t = m._touched_search(legacy, ranked)
    check("search 觸及=兩臂各前10 去重", set(t) == set(legacy[:10]) | set(ranked[:10]), str(t))
    check("legacy 第11名起不入(L12 不在)", "L12.md" not in t, str(t))
    # ★2026-09-15 合約擴張(Issues/尺切換恆等斷言反覆不過 原因二)★:edit 面用三條排法
    # 各自截前 k 算分,而 bm25_p/graph_p 各自驅動一道 gate——那兩條窗裡的未標★會實際
    # 影響分數★,正是本測試 docstring 自己講的收斂判準所要求納入的。舊合約只含綜合窗,
    # 相對於它自己宣告的原則是★漏收★,不是本次改動把母體放寬。
    # ★候選數要遠超上界,上界斷言才分得出來★(code-r1:原本 12 個候選斷言 ≤24,恆真、
    # 對「改回單臂」或「改成五臂」都無鑑別力;實測把實作改回單臂,該測試 7 條全綠)
    res = ([{"node": f"F{i:02d}.md", "pinned": False, "score": 1.0 - i / 100,
             "L": i / 100, "kind": "indirect", "hop": 1 + i % 3} for i in range(40)]
           + [{"node": f"P{i}.md", "pinned": True} for i in range(20)])
    te = m._touched_edit(res, k=8)
    check("全部 pins 仍全入", {f"P{i}.md" for i in range(20)} <= set(te), str(te))
    check("不重複", len(te) == len(set(te)), str(te))
    _fcount = len([x for x in te if x.startswith("F")])
    check("★上界:free 側至多 3 條窗×k★", _fcount <= 3 * 8, f"{_fcount} 個")
    check("★下界:三臂各取前 8、彼此不同 → free 側必多於單臂的 8 個★", _fcount > 8,
          f"只有 {_fcount} 個,等於退化回單臂")
    # 三臂的前 k 全要在觸及集裡(與 _edit_orders 對帳,不靠固定案例猜)
    for name, order in m._edit_orders([x for x in res if not x.get("pinned")]).items():
        check(f"{name} 的前 8 全在觸及集", {x["node"] for x in order[:8]} <= set(te), name)


def _mk_eval_fixture2():
    """雙 commit fixture:c1=基礎三節點;c2=+Delta.md(也講 zebrafish)。回 (root, gs, c1, c2)。"""
    import os
    root, gs = _mk_eval_fixture()
    c1 = subprocess.run(["git", "rev-parse", "--short", "HEAD"], cwd=root,
                        capture_output=True, text=True).stdout.strip()
    (root / "docs" / "kg-knowledge" / "Systems" / "Delta.md").write_text(
        "---\ntype: system\nstatus: done\n---\n# Delta\nzebrafish 新規則,關聯 `src/app.py`。\n",
        encoding="utf-8")
    env = {**os.environ, "GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@t.t",
           "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@t.t"}
    subprocess.run(["git", "add", "-A"], cwd=root, env=env, capture_output=True)
