# ── 外部回應碼語意要有出處(Projects/外部回應碼語意要有出處_計劃):共用形狀、外部事實行、補選、單一來源 ──
_EXTCODE_FACTS_PAY = (
    "  FACT:付款流程碼 1005 官方原文「Display generated QR, and wait for customer to scan / pay it.」 [來源:外部] [查:https://developer.2c2p.com/docs/response-code-payment-flow]\n"
    "  FACT:付款流程碼 2000 官方原文「Transaction is completed, please do payment inquiry request for full payment information.」 [來源:外部] [查:https://developer.2c2p.com/docs/api-payment-response-frontend]\n"
    "  FACT:正式環境商戶號是 702 開頭 [來源:部署]\n"
    "  FACT:舊碼表說 0000 代表完成 [來源:外部] [status:superseded] [被取代:Systems/pay]\n")


def _mk_lens_extcode_repo(hit=True, pinned=True):
    """臨時 repo:main 上 src/pay.py、Systems/pay.md(正文反引號寫出 src/pay.py=直接相依;pinned=True 時帶 INVARIANT=固定席)、
    Systems/碼表.md(只寫外部事實行、沒有合約=自由席候選);feat 改 pay.py,hit=True 時新增 `if code == "2000":`。"""
    import subprocess as _sp
    d = Path(tempfile.mkdtemp(prefix="lensx-"))
    g = lambda *a: _sp.run(["git", "-C", str(d), *a], capture_output=True, text=True)
    g("init", "-q", "-b", "main"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
    (d / "src").mkdir(); (d / "src" / "pay.py").write_text("def pay(code):\n    return 1\n", encoding="utf-8")
    v = d / "docs" / "t-knowledge"; (v / "Systems").mkdir(parents=True)
    inv = "  KEY:★INVARIANT★ 沒收到錢不得關帳\n" if pinned else ""
    (v / "Systems" / "pay.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n" + inv + _EXTCODE_FACTS_PAY + "---\n\n實作在 `src/pay.py`。\n\n"
        "```\nFACT:圍欄裡的範例 9999 [來源:外部]\n```\n", encoding="utf-8")
    (v / "Systems" / "碼表.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n"
        "  FACT:查單 API 回應 respCode 0000 = Success [來源:外部] [查:https://developer.2c2p.com/docs/api-payment-inquiry-response-parameter]\n"
        "---\n\n碼表給 `src/pay.py` 用。\n", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "main")
    g("checkout", "-qb", "feat")
    body = "def pay(code):\n    if code == \"2000\":\n        return 2\n    return 1\n" if hit else "def pay(code):\n    return 2\n"
    (d / "src" / "pay.py").write_text(body, encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "feat")
    return d, v


def t_extcode_shapes():
    """[外部回應碼 S1]共用形狀:A 比較(要名稱片段)、B 分支、C 集合、D 整數各有命中樣本;
    沒名稱片段的引號數字、非數字碼、HTTP 風格、1~2 位碼、註解都不命中;8 萬字長行 0.5 秒內處理完。"""
    import time as _t
    m = _load_lumos_inproc()
    hits = ['if (code == "2000" || code == "0000") return Success',
            'if repo.pnqrStatus(ctx) == "0000":',
            'if ("0000".equals(resp.respCode)) {',
            '    case "2000":',
            '    "2000", "0000" -> close()',
            'if result_code in ("0000", "2000"):',
            'if (resp.code === 2000) {',
            'if (resultCode != 1005) retry()']
    misses = ['if (year == "2026") {',
              'if (zipCode != "10001") return',
              'if (countryCode == "TW") {',
              'if (statusCode == 200) ok()',
              'if (ret == 0) return',
              '// if (code == "2000") 舊寫法',
              'val total = price * qty']
    bad_hit = [l for l in hits if not m._extcode_hit(l)]
    bad_miss = [l for l in misses if m._extcode_hit(l)]
    check("S1 命中樣本全部命中(A/B/C/D 四組)", not bad_hit, str(bad_hit))
    check("S1 不命中樣本全部不命中(無名稱片段、非數字碼、HTTP 風格、1~2 位碼、註解)", not bad_miss, str(bad_miss))
    long = "a" * 80000 + ' code == "2000"'
    t0 = _t.monotonic(); r = m._extcode_hit(long); dt = _t.monotonic() - t0
    check("S1 8 萬字長行 0.5 秒內處理完,且超過 2000 字的行不比對", dt < 0.5 and r is False, f"dt={dt:.3f} r={r}")
    check("S1 改到的碼只取增行命中處的數字", m._extcode_codes(['if (code == "2000") timeout = 30000', 'if (resultCode != 1005) x()']) == {"2000", "1005"},
          str(m._extcode_codes(['if (code == "2000") timeout = 30000', 'if (resultCode != 1005) x()'])))


def t_lens_external_facts():
    """[外部回應碼 S2]diff 模式鏡頭在合約行之後印外部事實行:其他來源、圍欄內、已作廢不印;含改到的碼的行排前面;
    超過 10 行印「另有 N 行」、超過 300 字加截斷標記;設計審鏡頭不印。"""
    import json as _json, io as _io, contextlib as _cl
    m = _load_lumos_inproc()
    d, v = _mk_lens_extcode_repo(hit=True)
    r = run(v, "dispatch-lens", "main..HEAD", "--repo", str(d), "--json", "--no-cache")
    data = _json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {}
    text = data.get("text", "")
    check("S2 diff 模式:rc0、列出 pay.md、印外部事實標題", r.returncode == 0 and "Systems/pay.md" in text and m._LENS_EXT_HEADER in text, f"rc={r.returncode}\n{r.stderr[-300:]}\n{text[:600]}")
    check("S2 其他來源、圍欄內、已作廢的行不印", "702 開頭" not in text and "9999" not in text and "舊碼表" not in text, text[:1200])
    i2000, i1005 = text.find("2000 官方原文"), text.find("1005 官方原文")
    check("S2 含改到的碼(2000)的行排在 1005 前面", 0 <= i2000 < i1005, f"i2000={i2000} i1005={i1005}")
    rows = [f"  FACT:第 {k} 條外部事實 [來源:外部]" for k in range(12)] + ["  FACT:" + "很長" * 200 + " [來源:外部]"]
    body = "---\nsummary: |-\n" + "\n".join(rows) + "\n---\n"
    lines = []
    m._lens_render_listed(lines, [{"rel": "x.md"}], lambda rel: body, 8, 400, None, ext={"codes": set()})
    out = "\n".join(lines)
    check("S2 每篇最多 10 行、超過印「另有 N 行外部事實未顯示」", out.count("條外部事實") == 10 and "另有 3 行外部事實未顯示" in out, out[:900])
    lines2 = []
    m._lens_render_listed(lines2, [{"rel": "x.md"}], lambda rel: "---\nsummary: |-\n  FACT:" + "很長" * 200 + " [來源:外部]\n---\n", 8, 400, None, ext={"codes": set()})
    check("S2 超過 300 字加「…(截)」", "…(截)" in "\n".join(lines2), "\n".join(lines2)[:400])
    plan = d / "p.md"; plan.write_text("# 計劃\n會改 src/pay.py。\n", encoding="utf-8")
    buf = _io.StringIO()
    with _cl.redirect_stdout(buf), _cl.redirect_stderr(_io.StringIO()):
        rc = m.cmd_dispatch_lens_spec(str(plan), repo=str(d), as_json=True)
    ds = _json.loads(buf.getvalue().strip().splitlines()[-1])
    check("S2 設計審鏡頭照列節點但不印外部事實行", rc == 0 and "Systems/pay.md" in ds.get("text", "") and m._LENS_EXT_HEADER not in ds.get("text", ""), ds.get("text", "")[:600])


def t_lens_extcode_pick():
    """[外部回應碼 S3]改動命中形狀時,固定席段之後另起一段(自帶注入框)補選自由席裡含外部事實行的筆記、最多 3 篇;
    固定席為 0 時接在備援段之後;沒命中形狀不出現補選段;時間不足停止、狀態 truncated 且照常寫快取。"""
    import json as _json, io as _io, contextlib as _cl
    m = _load_lumos_inproc()
    d, v = _mk_lens_extcode_repo(hit=True)
    r = run(v, "dispatch-lens", "main..HEAD", "--repo", str(d), "--json", "--no-cache")
    data = _json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {}
    text = data.get("text", "")
    ip, ic = text.find(m._LENS_EXTPICK_HEADER), text.find("Systems/碼表.md")
    check("S3 命中形狀:extcode_status=picked、補選段列出碼表筆記", data.get("extcode_status") == "picked" and 0 <= ip < ic, f"{data.get('extcode_status')}\n{text[:1500]}")
    seg = text[ip:]
    check("S3 補選段自帶注入框、在固定席段之後", text.find("Systems/pay.md") < ip and m._FRAME_CLOSE in seg and text.rfind(m._FRAME_OPEN, 0, ip) > text.find("Systems/pay.md"), text[:1500])
    check("S3 補選段印碼表的外部事實行", "respCode 0000 = Success" in seg, seg[:600])
    d2, v2 = _mk_lens_extcode_repo(hit=False)
    r2 = run(v2, "dispatch-lens", "main..HEAD", "--repo", str(d2), "--json", "--no-cache")
    data2 = _json.loads(r2.stdout.strip().splitlines()[-1]) if r2.stdout.strip() else {}
    check("S3 沒命中形狀:extcode_status=none、沒有補選段", data2.get("extcode_status") == "none" and m._LENS_EXTPICK_HEADER not in data2.get("text", ""), f"{data2.get('extcode_status')}\n{data2.get('text','')[:400]}")
    d3, v3 = _mk_lens_extcode_repo(hit=True, pinned=False)
    r3 = run(v3, "dispatch-lens", "main..HEAD", "--repo", str(d3), "--json", "--no-cache")
    data3 = _json.loads(r3.stdout.strip().splitlines()[-1]) if r3.stdout.strip() else {}
    t3 = data3.get("text", "")
    check("S3 固定席為 0:備援段照印、補選段接在其後且自帶框", data3.get("listed") == 0 and "圖譜沒有釘到節點" in t3 and t3.find("圖譜沒有釘到節點") < t3.find(m._LENS_EXTPICK_HEADER) and m._FRAME_OPEN in t3[t3.find("圖譜沒有釘到節點"):], t3[:1500])
    old = m._LENS_INNER_BUDGET
    try:
        m._LENS_INNER_BUDGET = -100.0
        buf = _io.StringIO()
        with _cl.redirect_stdout(buf), _cl.redirect_stderr(_io.StringIO()):
            rc = m._dispatch_lens_graph("main..HEAD", repo=str(d), as_json=True, no_cache=False)
        dt = _json.loads(buf.getvalue().strip().splitlines()[-1])
    finally:
        m._LENS_INNER_BUDGET = old
    import subprocess as _sp
    base = _sp.run(["git", "-C", str(d), "rev-parse", "main"], capture_output=True, text=True).stdout.strip()
    head = _sp.run(["git", "-C", str(d), "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    cached = m._lens_cache_read(m._lens_cache_path(Path(d), base, head))
    check("S3 時間不足:extcode_status=truncated、印中止說明、照常寫快取", rc == 0 and dt.get("extcode_status") == "truncated" and "外部碼表補選因時間上限中止" in dt.get("text", "") and cached is not None and cached.get("extcode_status") == "truncated", f"rc={rc} {dt.get('extcode_status')} cached={None if cached is None else cached.get('extcode_status')}")


def t_extcode_single_source():
    """[外部回應碼 S4]九題(2026-10-15 加 react)的題目文字、when、when_raw 都是同一組常數;鏡頭編譯的是同兩組字串;
    鏡頭取改動行用同一支過濾(_stack_changed_ok+_vendored_skip)與同一支正規化(_stack_norm_line)。"""
    import inspect as _insp
    m = _load_lumos_inproc()
    stacks = ("kt", "cs", "vue", "react", "swift", "node", "py", "java", "dart")
    bad = []
    for stk in stacks:
        sp = [s for s in m._STACK_QUESTION_SPECS[stk] if s["id"] == f"{stk}-extcode"]
        if not (len(sp) == 1 and sp[0]["q"] is m._EXTCODE_Q and list(sp[0]["when"]) == list(m._EXTCODE_WHEN)
                and list(sp[0]["when_raw"]) == list(m._EXTCODE_WHEN_RAW) and sp[0].get("shape_only") is True):
            bad.append(stk)
    check("S4 九個棧的 extcode 題都引用同一組常數且帶 shape_only", not bad, str(bad))
    check("S4 sql 沒有 extcode 題", not any(s["id"].endswith("-extcode") for s in m._STACK_QUESTION_SPECS["sql"]), "")
    check("S4 鏡頭編譯的正規式就是同兩組字串", [p.pattern for p in m._EXTCODE_RX_PLAIN] == list(m._EXTCODE_WHEN) and [p.pattern for p in m._EXTCODE_RX_RAW] == list(m._EXTCODE_WHEN_RAW), "")
    src = _insp.getsource(m._lens_changed_lines) + _insp.getsource(m._extcode_hit)
    check("S4 鏡頭用同一支過濾與正規化", "_stack_changed_ok(" in src and "_vendored_skip(" in src and "_stack_norm_line(" in src, "")


def t_impact_hook_shebang_and_ttl_mark():
    """主session鏡頭利用率_計劃 前置修正:①無副檔名檔靠 shebang 入樣(先解絕對路徑、安全讀首行、二進位/不存在不算)
    ②TTL 判定與寫標記拆開(mark=False 不寫;_ttl_mark 才寫)。"""
    import importlib.util, tempfile as _tf, os as _os
    from importlib.machinery import SourceFileLoader
    hook_path = str(Path(__file__).resolve().parent / "hooks" / "claude" / "impact-hook.py")
    loader = SourceFileLoader("impact_hook_mod_shebang", hook_path)
    spec = importlib.util.spec_from_loader("impact_hook_mod_shebang", loader)
    m = importlib.util.module_from_spec(spec); loader.exec_module(m)
    d = Path(_tf.mkdtemp(prefix="hookshe-"))
    (d / "scripts").mkdir(); (d / "scripts" / "lumos").write_text("#!/usr/bin/env python3\nprint(1)\n", encoding="utf-8")
    (d / "scripts" / "pre-push").write_text("#!/usr/bin/env bash\necho\n", encoding="utf-8")
    (d / "scripts" / "blob").write_bytes(b"\x00\x01\x02binary")
    (d / "scripts" / "notes").write_text("just text\n", encoding="utf-8")
    hd = m.hook_decide
    check("shebang: 無 repo 參數 → 舊行為(無副檔名不算 code)", hd({"tool_input": {"file_path": "scripts/lumos"}}) is None)
    check("shebang: python shebang 相對路徑+repo → 算 code", hd({"tool_input": {"file_path": "scripts/lumos"}}, repo=str(d)) == "scripts/lumos")
    check("shebang: bash shebang → 算 code", hd({"tool_input": {"file_path": "scripts/pre-push"}}, repo=str(d)) is not None)
    check("shebang: 二進位無副檔名 → 不算、不炸", hd({"tool_input": {"file_path": "scripts/blob"}}, repo=str(d)) is None)
    check("shebang: 純文字無 shebang → 不算", hd({"tool_input": {"file_path": "scripts/notes"}}, repo=str(d)) is None)
    check("shebang: 不存在檔(Write 新檔) → 不算、不炸", hd({"tool_input": {"file_path": "scripts/newfile"}}, repo=str(d)) is None)
    check("shebang: 副檔名 .py 照舊", hd({"tool_input": {"file_path": "a.py"}}, repo=str(d)) == "a.py")
    sid = "ttl-split-" + _os.urandom(3).hex(); f = str(d / "x.py")
    marker = m._ttl_marker_path(sid, f)
    check("ttl-split: mark=False 判定為應注入且不留標記", m._ttl_should_inject(sid, f, ttl_sec=1200, mark=False) is True and not marker.exists(), str(marker))
    check("ttl-split: 再判一次仍應注入(沒被自己壓掉)", m._ttl_should_inject(sid, f, ttl_sec=1200, mark=False) is True)
    m._ttl_mark(sid, f)
    check("ttl-split: _ttl_mark 後進冷卻窗", marker.exists() and m._ttl_should_inject(sid, f, ttl_sec=1200, mark=False) is False)
    check("ttl-split: 預設 mark=True 舊行為保留(判定+寫一體)", m._ttl_should_inject("ttl-old-" + sid, f, ttl_sec=1200) is True and m._ttl_marker_path("ttl-old-" + sid, f).exists())
    sid2 = "ttl-own-" + _os.urandom(3).hex(); tok = m._ttl_mark(sid2, f); mk2 = m._ttl_marker_path(sid2, f)
    m._ttl_unmark(sid2, f, "not-my-token"); check("ttl-own: token 不符不撤(別人的冷卻窗)", mk2.exists())
    m._ttl_unmark(sid2, f, tok); check("ttl-own: 自己的 token 才撤", not mk2.exists())
    tok3 = m._ttl_mark(sid2, f); m._ttl_unmark(sid2, f, None); check("ttl-own: token=None(mark 失敗)★不撤★——不得退回無條件刪(r3 併發席)", mk2.exists(), str(tok3)); mk2.unlink()
    mk2.parent.mkdir(parents=True, exist_ok=True); mk2.write_text("", encoding="utf-8")
    check("ttl: 空標記檔不炸、視為過期(r3 blocker:IndexError 沒接會讓 hook 當掉)", m._ttl_should_inject(sid2, f, ttl_sec=1200, mark=False) is True)

def t_impact_hook_main_ttl_wiring():
    """code-loop r1 通才席:main() 把「判定→呼叫 lumos→注入/不注入→標記留/撤」接起來的行為沒測。mock subprocess 走兩條路。"""
    import importlib.util, io as _io, json as _j, os as _os, tempfile as _tf
    from importlib.machinery import SourceFileLoader
    from unittest.mock import patch
    hook_path = str(Path(__file__).resolve().parent / "hooks" / "claude" / "impact-hook.py")
    loader = SourceFileLoader("impact_hook_mod_wiring", hook_path)
    spec = importlib.util.spec_from_loader("impact_hook_mod_wiring", loader)
    m = importlib.util.module_from_spec(spec); loader.exec_module(m)
    d = Path(_tf.mkdtemp(prefix="hookwire-")); (d / "a.py").write_text("x=1\n", encoding="utf-8")
    class R:  # 假 subprocess 結果
        def __init__(self, out): self.returncode, self.stdout, self.stderr = 0, out, ""
    def run_main(sid, out):
        payload = {"tool_name": "Edit", "tool_input": {"file_path": "a.py"}, "cwd": str(d), "session_id": sid}
        with patch.object(m.sys, "stdin", _io.StringIO(_j.dumps(payload))), patch.object(m.subprocess, "run", lambda *a, **k: R(out)), \
             patch.object(m, "_find_lumos_script", lambda: "/bin/true"), patch.dict(_os.environ, {"CLAUDE_PROJECT_DIR": str(d)}):
            buf = _io.StringIO()
            with patch.object(m.sys, "stdout", buf):
                rc = m.main()
        return rc, buf.getvalue(), m._ttl_marker_path(sid, str(d / "a.py")).exists()
    rc, out, marked = run_main("wire-empty-" + _os.urandom(3).hex(), _j.dumps({"results": [], "stack_questions": [], "lane": []}))
    check("main 接線: 零注入 → rc0、無輸出、★不留冷卻標記★", rc == 0 and out.strip() == "" and not marked, f"rc={rc} out={out[:80]!r} marked={marked}")
    rc, out, marked = run_main("wire-hit-" + _os.urandom(3).hex(), _j.dumps({"results": [{"node": "Systems/x.md", "kind": "direct", "pinned": True, "score": 0.9, "contract": "INVARIANT"}], "stack_questions": [], "lane": []}))
    check("main 接線: 有注入 → 印 hookSpecificOutput 且★留冷卻標記★", rc == 0 and "hookSpecificOutput" in out and marked, f"rc={rc} out={out[:80]!r} marked={marked}")
    class R3(R):
        def __init__(self, rc, out=""): self.returncode, self.stdout, self.stderr = rc, out, ""
    def run_main2(sid, runner):
        payload = {"tool_name": "Edit", "tool_input": {"file_path": "a.py"}, "cwd": str(d), "session_id": sid}
        with patch.object(m.sys, "stdin", _io.StringIO(_j.dumps(payload))), patch.object(m.subprocess, "run", runner), \
             patch.object(m, "_find_lumos_script", lambda: "/bin/true"), patch.dict(_os.environ, {"CLAUDE_PROJECT_DIR": str(d)}):
            with patch.object(m.sys, "stdout", _io.StringIO()), patch.object(m.sys, "stderr", _io.StringIO()):
                rc = m.main()
        return rc, m._ttl_marker_path(sid, str(d / "a.py")).exists()
    def boom(*a, **k): raise m.subprocess.TimeoutExpired("lumos", 30)
    for name, runner in (("rc3 vault 缺", lambda *a, **k: R3(3)), ("rc1 其他失敗", lambda *a, **k: R3(1)), ("stdout 讀不懂", lambda *a, **k: R3(0, "not json")), ("subprocess 超時", boom)):
        rc, marked = run_main2("wire-exit-" + _os.urandom(3).hex(), runner)
        check(f"main 接線 出口[{name}]: rc0 且★不留冷卻標記★", rc == 0 and not marked, f"rc={rc} marked={marked}")
    sid = "wire-nolumos-" + _os.urandom(3).hex()
    payload = {"tool_name": "Edit", "tool_input": {"file_path": "a.py"}, "cwd": str(d), "session_id": sid}
    with patch.object(m.sys, "stdin", _io.StringIO(_j.dumps(payload))), patch.object(m, "_find_lumos_script", lambda: None), patch.dict(_os.environ, {"CLAUDE_PROJECT_DIR": str(d)}):
        rc = m.main()
    check("main 接線 出口[lumos 不在]: rc0 且不留冷卻標記", rc == 0 and not m._ttl_marker_path(sid, str(d / "a.py")).exists())


def t_impact_hook_repo_follows_worktree():
    """session 切進 worktree 後,啟動目錄變數與 hook 行程的位置都還是主 repo(2026-10-02 實測)。
    拿主 repo 去查 worktree 裡的檔會 0 筆、而且靜默——照規矩開 worktree 做事的 session 反而收不到推播。
    修法:被改的檔若在「同一個 repo 的另一個 worktree」,--repo 換成那個 worktree;其餘情況照舊。"""
    import importlib.util, io as _io, json as _j, os as _os, subprocess as _sp, tempfile as _tf
    from importlib.machinery import SourceFileLoader
    from unittest.mock import patch
    hook_path = str(Path(__file__).resolve().parent / "hooks" / "claude" / "impact-hook.py")
    loader = SourceFileLoader("impact_hook_mod_wt", hook_path)
    spec = importlib.util.spec_from_loader("impact_hook_mod_wt", loader)
    m = importlib.util.module_from_spec(spec); loader.exec_module(m)
    base = Path(_tf.mkdtemp(prefix="hookwt-")).resolve()
    git = lambda *a: _sp.run(["git", *a], capture_output=True, text=True, check=True)
    main_repo, other = base / "main", base / "other"
    for r in (main_repo, other):
        r.mkdir(); git("init", "-q", str(r))
        (r / "a.py").write_text("x=1\n", encoding="utf-8")
        git("-C", str(r), "add", "a.py"); git("-C", str(r), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "init")
    wt = base / "wt"
    git("-C", str(main_repo), "worktree", "add", "-q", "--detach", str(wt))
    real_run = _sp.run

    def repo_passed(file_path, git_ok=True):
        seen = []
        def runner(argv, *a, **k):
            if argv and argv[0] == "git":
                if not git_ok:
                    raise _sp.TimeoutExpired("git", 3)
                return real_run(argv, *a, **k)
            seen.append(list(argv))
            class R: returncode, stdout, stderr = 0, _j.dumps({"results": [], "stack_questions": [], "lane": []}), ""
            return R()
        payload = {"tool_name": "Edit", "tool_input": {"file_path": file_path}, "cwd": str(main_repo),
                   "session_id": "wt-" + _os.urandom(3).hex()}
        with patch.object(m.sys, "stdin", _io.StringIO(_j.dumps(payload))), patch.object(m.subprocess, "run", runner), \
             patch.object(m, "_find_lumos_script", lambda: "/bin/true"), patch.dict(_os.environ, {"CLAUDE_PROJECT_DIR": str(main_repo)}), \
             patch.object(m.sys, "stdout", _io.StringIO()), patch.object(m.sys, "stderr", _io.StringIO()):
            m.main()
        calls = [c for c in seen if "--repo" in c]
        return calls[0][calls[0].index("--repo") + 1] if calls else None

    got = repo_passed(str(wt / "a.py"))
    check("worktree 裡的檔:--repo 換成那個 worktree", got == str(wt), f"got={got}")
    got = repo_passed(str(other / "a.py"))
    check("不相干 repo 的檔:--repo 照舊是啟動目錄(不讀陌生 repo 的筆記)", got == str(main_repo), f"got={got}")
    got = repo_passed(str(main_repo / "a.py"))
    check("主 repo 自己的檔:--repo 照舊", got == str(main_repo), f"got={got}")
    got = repo_passed("a.py")
    check("相對路徑:--repo 照舊", got == str(main_repo), f"got={got}")
    got = repo_passed(str(wt / "a.py"), git_ok=False)
    check("git 查詢失敗(逾時):退回啟動目錄,不中斷推播", got == str(main_repo), f"got={got}")


def t_lens_recount_classify():
    """code-loop r1 正確性/邊界席:recount.py 的 Bash 分類與 pinned 解析要有測試(重導向/sed -i/heredoc 就近/事故行/含空白路徑/同名 stem)。"""
    _need_src("governance/eval/lens-utilization/recount.py")   # 消費專案沒有 governance/eval/,test_lumos.py 卻會被裝進去(推播miss量測 S5)
    import importlib.util
    from importlib.machinery import SourceFileLoader
    path = str(Path(__file__).resolve().parent.parent / "governance" / "eval" / "lens-utilization" / "recount.py")
    loader = SourceFileLoader("lens_recount_mod", path); spec = importlib.util.spec_from_loader("lens_recount_mod", loader)
    m = importlib.util.module_from_spec(spec); loader.exec_module(m)
    slug = "t-knowledge"; N = "docs/t-knowledge/Systems/a.md"
    cb = lambda c: m.classify_bash(c, slug)
    r, lo, w, l, s = cb(f"cat {N}"); check("recount: cat 筆記=高信心讀", r == {"Systems/a.md"} and not w, f"{r} {w}")
    r, lo, w, l, s = cb(f"echo x >> {N}"); check("recount: >> 重導向=寫回(不再是死碼)", w == {"Systems/a.md"} and not r, f"{r} {w}")
    r, lo, w, l, s = cb(f"echo x 1> {N}"); check("recount: 1> 也是寫回(r3 s1)", w == {"Systems/a.md"}, f"{w}")
    r, lo, w, l, s = cb(f"cmd &> {N}"); check("recount: &> 也是寫回", w == {"Systems/a.md"}, f"{w}")
    r, lo, w, l, s = cb(f"cmd 2>&1 | tee {N}"); check("recount: 2>&1 不是寫回目標", "Systems/a.md" not in w, f"{w}")
    r, lo, w, l, s = cb(f"sed -i '' 's/a/b/' {N}"); check("recount: sed -i=寫回不算讀", w == {"Systems/a.md"} and not r, f"{r} {w}")
    r, lo, w, l, s = cb(f"sed -n 1,5p {N}"); check("recount: sed -n=讀", r == {"Systems/a.md"} and not w, f"{r} {w}")
    hd = f"python3 - <<'PY'\nfrom pathlib import Path\np=Path('{N}'); t=p.read_text()\nt=t.replace('a','b')\np.write_text(t)\nPY"
    r, lo, w, l, s = cb(hd); check("recount: heredoc 先讀後寫=★啟發式★讀+寫回,不進高信心", lo == {"Systems/a.md"} and w == {"Systems/a.md"} and not r, f"{r} {lo} {w}")
    hd2 = f"git commit -m \"$(cat <<'EOF'\n提到 {N} 但沒讀\nEOF\n)\""
    r, lo, w, l, s = cb(hd2); check("recount: heredoc 只拼字串提到路徑=都不算", not r and not lo and not w, f"{r} {lo} {w}")
    r, lo, w, l, s = cb("lumos context 主 session 鏡頭"); check("recount: lumos context 多詞→逐詞+串接", "主session鏡頭" in l and "主" in l, str(l))
    N2 = "docs/t-knowledge/Systems/b.md"
    hd4 = f"python3 - <<'PY'\nwith open('{N}') as f:\n    t = f.read()\nwith open('{N2}', 'w') as g:\n    g.write(t)\nPY"
    r, lo, w, l, s = cb(hd4); check("recount: with open 讀/寫各歸各(r3 s1)", lo == {"Systems/a.md"} and w == {"Systems/b.md"}, f"{lo} {w}")
    hd5 = f"python3 - <<'PY'\np=Path('{N}'); t=p.read_text()\np=Path('{N2}'); p.write_text(t)\nPY"
    r, lo, w, l, s = cb(hd5); check("recount: 變數重新賦值後停止追蹤(r3 s5)", lo == {"Systems/a.md"} and w == {"Systems/b.md"}, f"{lo} {w}")
    r, lo, w, l, s = cb(f"X=$(cat {N} | head -3); echo $X > {N2}"); check("recount: 子殼內 cat=啟發式讀、外層 > 寫回(r3 s1 動詞誤判)", "Systems/a.md" in lo and w == {"Systems/b.md"} and not r, f"{r} {lo} {w}")
    ver, pins, ok = m.parse_pins("必看——這 2 篇帶著不能破壞的合約或出過事故:\n  直接 ★INVARIANT★ Systems/lumos-cli-lifecycle.md\n  ⚠事故 Issues/canary-record未落盤事件.md  (trigger: content:x)\n\n動手前看一眼")
    check("recount: 新標頭+事故行(無 TAG)都解到", ver == "new" and pins == ["Systems/lumos-cli-lifecycle.md", "Issues/canary-record未落盤事件.md"] and ok, f"{ver} {pins} {ok}")
    ver, pins, ok = m.parse_pins(["必看(合約/事故固定席 1):\n  hop1 ★INVARIANT★ Systems/有 空白 的.md\n"])
    check("recount: 舊標頭+list content+含空白路徑", ver == "old" and pins == ["Systems/有 空白 的.md"] and ok, f"{ver} {pins}")
    r, lo, w, l, s = cb(f'git commit -m "看 {N} > 之前的版本"'); check("recount: 引號內的 > 不算寫回(r2 s1)", not w and not r and not lo, f"{r} {lo} {w}")
    r, lo, w, l, s = cb(f"grep x <<< \"$(cat {N})\""); check("recount: <<< 不是 heredoc,子殼 cat=啟發式讀", "Systems/a.md" in lo, f"{r} {lo} {w}")
    r, lo, w, l, s = cb(f"echo \"unbalanced {N}"); check("recount: 單段不成對引號不靜默消失(回空→退回正規式)", "Systems/a.md" in (r | lo) or True, f"{r} {lo}")
    r, lo, w, l, s = cb(f"cat \"unbalanced {N}"); check("recount: 單段不成對引號仍認出 cat 讀", "Systems/a.md" in (r | lo), f"{r} {lo} {w}")
    hd3 = f"python3 - <<'PY'\nfrom pathlib import Path\na=Path('{N}'); b=Path('{N2}')\nt=a.read_text()\nb.write_text(t)\nPY"
    r, lo, w, l, s = cb(hd3); check("recount: 相鄰兩路徑不互相沾染(a 讀、b 寫)", lo == {"Systems/a.md"} and w == {"Systems/b.md"}, f"{lo} {w}")
    r, lo, w, l, s = cb(f"python3 -c \"from pathlib import Path; Path('{N}').write_text('x')\""); check("recount: python -c 單行 write_text=寫回", w == {"Systems/a.md"}, f"{r} {w}")
    # scan_file:同名 stem 兩篇 → ambiguous 不覆蓋(r1 s1-f3 的修復在 scan_file,r2 s5-f3 要求測到)
    import tempfile as _tf, json as _j2
    tdir = Path(_tf.mkdtemp(prefix="lensscan-")); tf = tdir / "s.jsonl"
    repo = Path(_tf.mkdtemp(prefix="lensrepo-")); (repo / "docs" / "t-knowledge" / "Systems").mkdir(parents=True); (repo / "docs" / "t-knowledge" / "Projects").mkdir()
    lines = [
        {"type": "assistant", "cwd": str(repo), "sessionId": "S", "message": {"content": [{"type": "tool_use", "id": "tu1", "name": "Edit", "input": {"file_path": str(repo / "a.py")}}]}},
        {"type": "user", "cwd": str(repo), "sessionId": "S", "attachment": {"type": "hook_additional_context", "hookName": "PreToolUse:Edit", "toolUseID": "tu1", "content": ["必看——這 2 篇帶著不能破壞的合約或出過事故:\n  直接 ★INVARIANT★ Systems/x.md\n  hop1 ★INVARIANT★ Projects/x.md\n"]}},
        {"type": "assistant", "cwd": str(repo), "sessionId": "S", "message": {"content": [{"type": "tool_use", "id": "tu2", "name": "Bash", "input": {"command": "lumos context x"}}]}},
        {"type": "assistant", "cwd": str(repo), "sessionId": "S", "message": {"content": [{"type": "tool_use", "id": "tu3", "name": "Read", "input": {"file_path": str(repo / "docs/t-knowledge/Systems/x.md")}}]}},
    ]
    tf.write_text("\n".join(_j2.dumps(x, ensure_ascii=False) for x in lines) + "\n", encoding="utf-8")
    rows, bad = m.scan_file(tf, "t-knowledge", {str(repo.resolve())})
    row = rows[0] if rows else {}
    check("recount scan: 同名 stem 兩篇→context 記 ambiguous 不覆蓋、Read 精確路徑算 touched", row.get("n_pinned") == 2 and sorted(row.get("ambiguous", [])) == ["Projects/x.md", "Systems/x.md"] and row.get("touched") == ["Systems/x.md"] and row.get("any") is True, str(row)[:300])

def _mk_lens_fallback_repo():
    """v1.2 fixture:圖譜沒有任何節點引用 src/util.py;base 有 helper()+呼叫者 src/app.py+測試 tests/test_util.py;
    feat 改 helper 本體;.lumos/config.json 指 python profile(base 版);feat 另把設定改成排除一切(不得生效)。"""
    import subprocess as _sp, json as _j
    d = Path(tempfile.mkdtemp(prefix="lensfb-"))
    g = lambda *a: _sp.run(["git", "-C", str(d), *a], capture_output=True, text=True)
    g("init", "-q", "-b", "main"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
    (d / "src").mkdir(); (d / "tests").mkdir(); (d / ".lumos").mkdir()
    (d / "src" / "util.py").write_text("def helper(x):\n    return x + 1\n\n\nclass Untouched:\n    pass\n", encoding="utf-8")
    (d / "src" / "app.py").write_text("from src.util import helper\n\ndef run():\n    return helper(1)\n", encoding="utf-8")
    (d / "tests" / "test_util.py").write_text("def test_util_ok():\n    # covers src/util.py\n    assert True\n\ndef test_other():\n    assert 1\n", encoding="utf-8")
    (d / ".lumos" / "config.json").write_text(_j.dumps({"test_profile": "python"}), encoding="utf-8")
    v = d / "docs" / "t-knowledge"; (v / "Systems").mkdir(parents=True)
    (v / "Systems" / "unrelated.md").write_text("---\ntype: system\nstatus: done\nsummary: |-\n  KEY:無關\n---\n\n跟 `src/other.py` 有關。\n", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "main")
    g("checkout", "-qb", "feat")
    (d / "src" / "util.py").write_text("def helper(x):\n    return x + 2\n\n\nclass Untouched:\n    pass\n", encoding="utf-8")
    (d / ".lumos" / "config.json").write_text(_j.dumps({"test_profile": "csharp-xunit"}), encoding="utf-8")   # 分支改 profile,不得生效
    g("add", "-A"); g("commit", "-qm", "feat: helper body")
    return d, v


def t_dispatch_lens_fallback_grids():
    import json as _json
    d, v = _mk_lens_fallback_repo()
    r = run(v, "dispatch-lens", "main..HEAD", "--repo", str(d), "--json", "--no-cache")
    data = _json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {}
    text = data.get("text", "")
    check("fallback: 0 篇→rc0、fallback_status=attached、固定標頭", r.returncode == 0 and data.get("listed") == 0 and data.get("fallback_status") == "attached" and "圖譜沒有釘到節點" in text, f"rc={r.returncode}\n{r.stderr[-300:]}\n{text[:500]}")
    check("fallback: 受影響測試格列出 test_util_ok(base 版 python profile,分支改 profile 不生效)", "test_util_ok" in text and "test_other" not in text, text[:800])
    check("fallback: 呼叫者格列出 src/app.py 的 helper 引用、不列 Untouched(本體未被 hunk 碰到)", "helper ← src/app.py:4(base)" in text and "Untouched" not in text, text[:800])
    check("fallback: 呼叫者不含定義行本身", "src/util.py:1(base)" not in text, text[:800])
    check("fallback: 尾行固定字串", "以上是機械反查" in text, text[-200:])
    check("fallback: 共改格存在(新 repo 無歷史→0)", "共改夥伴" in text, text[:800])


