    (root / "AGENTS.md").write_text("# A\n<!-- LUMOS:GRAPH-DISCIPLINE:START v0.9 — x -->\nb\n<!-- LUMOS:GRAPH-DISCIPLINE:END -->\n", encoding="utf-8")
    by4 = {r["layer"]: r["status"] for r in m.enforcement_status(root=root, home=home)}
