    with _cl.redirect_stdout(buf):
        rc = m.cmd_dispatch_lens_spec("docs/lumos-toolchain-knowledge/Projects/Codex行為精修_計劃.md", repo=str(repo), as_json=True)
    d = _j.loads(buf.getvalue().strip().splitlines()[-1])
