    buf = _io.StringIO()
    with _cl.redirect_stdout(buf), _cl.redirect_stderr(_io.StringIO()):
        rc3 = m.cmd_dispatch_lens_spec(str(tmp / "nope.md"), repo=str(tmp), as_json=True)
