    check("S1: 合法宣告無警告、三條都收", warns == [] and len(rules) == 3, str((rules, warns)))
    check("S1: 兩條都命中 web/App.vue → 取第一條 backend(宣告優先於 .vue 副檔名)",
          m._review_role_for("web/App.vue", "/nonexistent", rules) == "backend", "")
