    for label, kw in (("範圍算不出", {"body": {"lens_fail": "commit_missing"}, "prompt": "審查。\nLUMOS-IMPACT: main..HEAD\n"}),
                      ("計劃讀不到", {"body": {"lens_fail": "spec_missing", "spec_source": "worktree"}})):
        rc, o, _c, _m = _lr_hook_fire(hm, proj=bad, **kw)
