def t_hook_liveness_is_not_just_recently_ran():
    """★「近 7 天跑過」本身就是假綠來源,判準要三個條件同時成立★(2026-09-08 #19 S4)。

    r1 外家否決席判 blocker:hook 今天上午跑過、下午被移除,接下來七天照樣顯示有效
    ——那正是「以為防護還在、其實已經沒了」,是這支儀表板最不能有的方向。

    所以判準是:①現在有註冊 ②現在的檔案指紋對得上 ③最近有一筆**同 repo、同版本、
    成功完成**的事件。沒有近期成功要標 stale/unknown,★不標 inactive★
    ——那可能只是七天內沒被觸發。

    這一支逐個餵會造成假綠的輸入:別的 repo 的事件、未來時間戳、逾時、失敗、換過版本。
    """
    import json as _j, datetime as _dt, hashlib as _h, shutil as _sh, tempfile as _tf
    _need_src("scripts/lumos")
    lm = _load_lumos()
    root = Path(_tf.mkdtemp(prefix="gctl-hooklive-"))
    try:
        hookf = root / "h.py"; hookf.write_text("print(1)\n", encoding="utf-8")
        fp = _h.sha256(hookf.read_bytes()).hexdigest()[:16]
        d = root / "governance" / "runtime"; d.mkdir(parents=True)
        log = d / "hook-events.jsonl"

        def write(rows):
            log.write_text("".join(_j.dumps(r, ensure_ascii=False) + "\n" for r in rows),
                           encoding="utf-8")

        def ts(days=0, hours=0):
            return (_dt.datetime.now().astimezone()
                    - _dt.timedelta(days=days, hours=hours)).isoformat()

        base = {"hook": "H", "kind": "ok", "repo": str(root.resolve()), "fp": fp}

        check("★沒有事件檔 → unknown,不是 inactive★",
              lm._hook_recent_ok(root, "H", hookf)[0] == "unknown", "")

        write([dict(base, ts=ts(hours=2))])
        check("★兩小時前成功跑過 + 指紋對得上 → ok★",
              lm._hook_recent_ok(root, "H", hookf)[0] == "ok", log.read_text())

        write([dict(base, ts=ts(days=8))])
        check("★八天前那筆超出窗口 → stale★",
              lm._hook_recent_ok(root, "H", hookf)[0] == "stale", "")

        write([dict(base, ts=ts(hours=1), kind="timeout"), dict(base, ts=ts(hours=1), kind="error")])
        check("★逾時與失敗不算「跑過」★(在進入點記帳的實作會靠這種資料假綠)",
              lm._hook_recent_ok(root, "H", hookf)[0] == "stale", log.read_text())

        write([dict(base, ts=ts(hours=1), repo="/somewhere/else")])
        check("★別的 repo 的事件不算數★(共用檔會讓 A 專案的執行幫 B 專案假綠)",
              lm._hook_recent_ok(root, "H", hookf)[0] == "stale", log.read_text())

        write([dict(base, ts=(_dt.datetime.now().astimezone() + _dt.timedelta(hours=5)).isoformat())])
        check("★未來時間戳不採信★(時鐘被調過會長期假綠)",
              lm._hook_recent_ok(root, "H", hookf)[0] == "stale", log.read_text())

        write([dict(base, ts=ts(hours=1), fp="deadbeefdeadbeef")])
        check("★換過版本 → stale★(新版還沒跑過,不能拿舊版跑過當有效)",
              lm._hook_recent_ok(root, "H", hookf)[0] == "stale", log.read_text())

        write([dict(base, ts=ts(hours=1)), dict(base, ts=ts(days=9))])
        check("★新舊混在一起時看最新那筆★",
              lm._hook_recent_ok(root, "H", hookf)[0] == "ok", log.read_text())

        log.write_text("這不是 json\n" + _j.dumps(dict(base, ts=ts(hours=1))) + "\n", encoding="utf-8")
        check("★夾雜壞行不能整支炸掉★(fail-open 但仍要讀得到好的那筆)",
              lm._hook_recent_ok(root, "H", hookf)[0] == "ok", log.read_text())
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_hook_liveness_is_not_just_recently_ran")


def t_hook_event_trim_tmp_unique():
    """存活事件檔超過上限要修剪時,暫存檔用各自獨立的名字(代碼審 code-代理繞閘字樣問人 r1 併發資源席):
    固定叫 hook-events.jsonl.tmp 時,兩個會談同時修剪會寫同一個暫存檔;那個名字被別的東西佔住(這裡放一個資料夾)時,
    修剪永遠失敗、檔案無限長大。"""
    import tempfile as _tf, shutil as _sh
    m = _load_hook_mod("hookevent_trim", "_hookevent.py")
    root = Path(_tf.mkdtemp(prefix="gctl-hookevent-trim-"))
    try:
        rt = root / "governance" / "runtime"
        rt.mkdir(parents=True)
        f = rt / "hook-events.jsonl"
        f.write_text(("x" * 300 + "\n") * 4000, encoding="utf-8")
        (rt / "hook-events.jsonl.tmp").mkdir()
        ok = m.record(root, "pretooluse-bypass-ask-hook", "ok")
        lines = f.read_text(encoding="utf-8").splitlines()
        check("存活事件修剪:固定暫存檔名被佔住時照樣修剪(2000 行以內、大小在上限一半以內)、新事件在最後",
              ok and 0 < len(lines) <= 2000 and f.stat().st_size <= m.MAX_BYTES // 2 + 1024
              and "pretooluse-bypass-ask-hook" in lines[-1], (ok, len(lines), f.stat().st_size))
        left = [x.name for x in rt.iterdir() if x.name not in ("hook-events.jsonl", "hook-events.jsonl.tmp")]
        check("存活事件修剪:沒有留下殘餘暫存檔", left == [], left)
        # 權限照舊(r2 架構對齊席、併發資源席:mkstemp 會把 0644 換成 0600)
        import os as _os, stat as _st, time as _tm
        f.write_text(("x" * 300 + "\n") * 4000, encoding="utf-8")
        _os.chmod(f, 0o644)
        m.record(root, "pretooluse-bypass-ask-hook", "ok")
        check("存活事件修剪:修剪後權限照原檔(0644)", _st.S_IMODE(f.stat().st_mode) == 0o644, oct(_st.S_IMODE(f.stat().st_mode)))
        # 被砍在修剪中途留下的舊暫存檔,下次修剪會清掉(超過一分鐘的才清,不碰正在寫的)
        old_trim = rt / "hook-events.abc123.trim"
        old_trim.write_text("殘檔", encoding="utf-8")
        _os.utime(old_trim, (_tm.time() - 600, _tm.time() - 600))
        fresh_trim = rt / "hook-events.def456.trim"
        fresh_trim.write_text("寫到一半", encoding="utf-8")
        f.write_text(("x" * 300 + "\n") * 4000, encoding="utf-8")
        m.record(root, "pretooluse-bypass-ask-hook", "ok")
        check("存活事件修剪:超過一分鐘的殘留暫存檔被清掉、剛建的不碰", not old_trim.exists() and fresh_trim.exists(),
              (old_trim.exists(), fresh_trim.exists()))
        fresh_trim.unlink()
        # 長行:修剪後大小要落在上限以下,不能每次都再修一次(r2 正確性席)
        f.write_text(("y" * 600 + "\n") * 3000, encoding="utf-8")
        m.record(root, "pretooluse-bypass-ask-hook", "ok")
        check("存活事件修剪:長行時修剪後小於位元組上限", f.stat().st_size <= m.MAX_BYTES, f.stat().st_size)
        # 換入失敗時暫存檔要清掉(失敗清理分支)
        from unittest.mock import patch as _patch
        f.write_text(("x" * 300 + "\n") * 4000, encoding="utf-8")
        with _patch.object(m.os, "replace", side_effect=OSError("boom")):
            m.record(root, "pretooluse-bypass-ask-hook", "ok")
        left = [x.name for x in rt.iterdir() if x.name.endswith(".trim")]
        check("存活事件修剪:換入失敗時不留下暫存檔", left == [], left)
        # 檔案還小、不需要修剪時,舊殘檔也要清(r3 併發資源席:下一次修剪可能要很久才來)
        f.write_text("x\n", encoding="utf-8")
        stale = rt / "hook-events.zz9999.trim"
        stale.write_text("殘檔", encoding="utf-8")
        _os.utime(stale, (_tm.time() - 600, _tm.time() - 600))
        m.record(root, "pretooluse-bypass-ask-hook", "ok")
        check("存活事件修剪:不需要修剪時也清掉超過一分鐘的殘檔", not stale.exists(), stale.exists())
        # 目錄唯讀、檔案可寫:修剪失敗要印一行提示(r3 併發資源席:原本靜默、檔案一路長大)
        import io as _io, contextlib as _cl
        f.write_text(("x" * 300 + "\n") * 4000, encoding="utf-8")
        _os.chmod(rt, 0o555)
        err = _io.StringIO()
        try:
            with _cl.redirect_stderr(err):
                m.record(root, "pretooluse-bypass-ask-hook", "ok")
        finally:
            _os.chmod(rt, 0o755)
        check("存活事件修剪:目錄唯讀修剪失敗時印提示(帶 telemetry-write-failed 關鍵字,跟其他記帳失敗同一種)",
              "修剪失敗" in err.getvalue() and "telemetry-write-failed" in err.getvalue(), err.getvalue()[:200])
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_hook_event_trim_tmp_unique")


def t_hook_event_recorded_only_on_success():
    """★「跑過」只記在成功完成點,不記在進入點★(2026-09-08 #19 S4,r1 通才席)。

    如果實作圖省事把寫入放在 hook 進入點(常見寫法:先記一筆「開始」再做事),
    就會出現一種新的假綠——hook 每次都在起手式就當機,儀表板卻穩定顯示「近期跑過 N 次」。

    ★同型前例就在隔壁★:`Systems/hook逾時預算` 記的正是「寫在 except 分支裡的清理動作
    結構上永遠跑不到,而且沒人發現」,時間是 2026-09-07——前一天。
    """
    import json as _j, shutil as _sh, tempfile as _tf, subprocess as _sp
    _need_src("scripts/hooks/claude/_hookevent.py")
    src = Path(GRAPHCTL).resolve().parent / "hooks" / "claude" / "_hookevent.py"
    root = Path(_tf.mkdtemp(prefix="gctl-hookev-"))
    try:
        _sp.run(["git", "init", "-q", str(root)], check=True, capture_output=True)
        probe = root / "probe.py"
        probe.write_text(
            "import sys, pathlib\n"
            "sys.path.insert(0, %r)\n" % str(src.parent) +
            "from _hookevent import guard\n"
            "def main():\n"
            "    if len(sys.argv) > 1 and sys.argv[1] == 'boom':\n"
            "        raise RuntimeError('起手式就當機')\n"
            "    return 0\n"
            "sys.exit(guard('H', __file__, main, swallow=True))\n", encoding="utf-8")
        log = root / "governance" / "runtime" / "hook-events.jsonl"

        _sp.run([sys.executable, str(probe), "boom"], cwd=str(root), capture_output=True, timeout=60)
        rows = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
        check("★炸掉的那次不准記成 ok★", all(r["kind"] != "ok" for r in rows), str(rows))
        check("★但要記成 error(不是靜靜消失——那樣就看不出它一直在炸)★",
              any(r["kind"] == "error" for r in rows), str(rows))

        _sp.run([sys.executable, str(probe)], cwd=str(root), capture_output=True, timeout=60)
        rows = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
        check("★正常跑完那次才記 ok★", any(r["kind"] == "ok" for r in rows), str(rows))
        check("★事件要帶 repo 與指紋★(跨 repo 與換版都靠它們分辨)",
              all(r.get("repo") and "fp" in r for r in rows), str(rows))

        # 檔案位置:repo 樹內,不是家目錄(r1 三席都提,架構席判 blocker)
        check("★事件檔要落在 repo 樹內★", log.exists(), str(log))
        txt = src.read_text(encoding="utf-8")
        # ★只看碼,不看說明文字★:第一版直接對全檔比對,結果咬到 docstring 裡
        # 「原本寫 ~/.cache/lumos,為什麼搬走」那段說明,報了一個假的紅。
        # ★這是同一天第四次「斷言咬到註解」★——收束:凡是「碼裡不准出現 X」這類斷言,
        # 一律先把註解與 docstring 剝掉。
        import ast as _ast
        _tree = _ast.parse(txt)
        for _n in _ast.walk(_tree):
            if isinstance(_n, (_ast.Module, _ast.FunctionDef, _ast.ClassDef)):
                _d = _ast.get_docstring(_n, clean=False)
                if _d:
                    txt = txt.replace(_d, "")
        code = "\n".join(l for l in txt.splitlines() if not l.lstrip().startswith("#"))
        check("★前置★ 剝完註解還看得到碼", "def record(" in code, code[:200])
        check("★不准寫回家目錄★(這個 repo 的慣例是 repo 樹內 + gitignore)",
              "~/.cache" not in code and "expanduser" not in code, "碼裡還有家目錄的路徑")
        check("★要有容量上限★(append-only 的檔不能無限長)", "MAX_BYTES" in txt, "")
        check("★不記「注入 N 次」★(那是成效,派工鏡頭 d1 明令不量)",
              "inject" not in txt.lower(), "碼裡出現了 inject 相關欄位")
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_hook_event_recorded_only_on_success")


def t_skip_code_loop_never_skips_bound_tests():
    """★跳過「代碼審留痕」不得連帶跳掉合約測試閘★(2026-09-08 #19 S3;r1 通才席 blocker)。

    這是 r1 最鋒利的一條。計劃裡我把「代碼審留痕」列進可跳、把「合約測試閘」列進不可跳,
    ★而後者其實包在前者的同一次呼叫裡面★:合約測試閘是 `code-loop check` 內部的
    第 2.5 步(不分 tier、紅就擋),而 pre-push 自己那次獨立呼叫是 `--advisory` 加 `|| true`、
    **不擋**。所以照「hook 維持薄殼」最自然的實作(不呼叫那支),
    會把我自己寫明不可跳的那道一起跳掉。

    ★而 CI 那邊也關著它★:CI 設 `LUMOS_SKIP_BOUND_TESTS: "1"`,理由是「全套測試當後盾」
    ——但全套測試驗的是「現有測試會過」,**驗不出「這個合約根本沒綁測試」**。
    兩層疊起來,那個覆蓋率缺口在本機和 CI 都不會有人抓到。

    所以這個環境變數只能跳到「留痕要求」那一步為止。
    """
    import subprocess as _sp, json as _j, os as _os, shutil as _sh
    lumos_real = str(Path(__file__).resolve().parent / "lumos")

    def run(d, env=None):
        e = dict(_os.environ); e.pop("LUMOS_SKIP_BOUND_TESTS", None); e.update(env or {})
        return _sp.run([sys.executable, lumos_real, "code-loop", "check",
                        "--diff", "HEAD~1..HEAD", "--json", "--repo", str(d)],
                       capture_output=True, text=True, env=e)

    def gov(d, gate):
        pth = Path(d) / "docs" / ".governance-log.jsonl"
        if not pth.exists():
            return []
        return [_j.loads(l) for l in pth.read_text(encoding="utf-8").splitlines()
                if l.strip() and _j.loads(l).get("gate") == gate]

    d = _mk_bound_tests_repo(tempfile.mkdtemp(prefix="gctl-skipcl-"))
    try:
        (Path(d) / "tests" / "RED").write_text("", encoding="utf-8")   # 讓合約綁的測試翻紅
        r = run(d)
        v = _j.loads(r.stdout)
        check("★前置★ 現場成立:合約測試紅的時候本來就會擋",
              r.returncode == 1 and v["blocked"], r.stdout + r.stderr[-200:])

        r = run(d, env={"LUMOS_SKIP_CODE_LOOP": "1"})
        v = _j.loads(r.stdout)
        check("★跳過留痕要求之後,合約測試閘照樣擋★(這是 r1 blocker 的本體)",
              r.returncode == 1 and v["blocked"], r.stdout + r.stderr[-300:])
        check("★而且擋的理由要還是合約測試,不是留痕★",
              "t_pay_ok" in v.get("reason", "") or "Pay" in v.get("reason", ""), r.stdout)
    finally:
        _sh.rmtree(d, ignore_errors=True)

    # 合約測試是綠的、但 tier=high 沒留痕 → 這時候才輪得到那個環境變數放行,而且要留帳
    d = _mk_bound_tests_repo(tempfile.mkdtemp(prefix="gctl-skipcl2-"))
    try:
        # ★現場要真的長成 tier=high★:第一版直接用 fixture 的現場,結果 tier=standard,
        # 後半段整段被「前置不成立」跳過——★那等於這條路根本沒被測到★,
        # 而「跳過留痕」正是這一支要驗的東西。
        # 高風險的觸發條件實測出來是「新增的行裡有沒配 with 的 open(」,
        # 而且要動到合約點名的那個檔,合約測試閘才會被牽連進來。
        (Path(d) / "app" / "pay.py").write_text(
            "def charge(x):\n    f = open('/dev/null')\n    return abs(x)\n", encoding="utf-8")
        _sp.run(["git", "-C", str(d), "add", "-A"], capture_output=True)
        _sp.run(["git", "-C", str(d), "-c", "user.email=t@t", "-c", "user.name=t",
                 "commit", "-qm", "high", "--no-verify"], capture_output=True)
        r = run(d)
        base = _j.loads(r.stdout)
        check("★前置★ 現場成立:這一筆真的被判成高風險而且被擋",
              base.get("tier") == "high" and base["blocked"],
              "tier=%s blocked=%s" % (base.get("tier"), base.get("blocked")))
        if base.get("tier") == "high" and base["blocked"]:
            r2 = run(d, env={"LUMOS_SKIP_CODE_LOOP": "1"})
            v2 = _j.loads(r2.stdout)
            check("★留痕要求可以被跳(合約測試綠的前提下)★",
                  r2.returncode == 0 and not v2["blocked"], r2.stdout + r2.stderr[-200:])
            rows = [x for x in gov(d, "code-loop") if x.get("kind") == "skipped-env"]
            check("★被跳的閘一定要留一筆帳★(不然量不出哪一道最常被跳)",
                  len(rows) >= 1, str(gov(d, "code-loop")))
            if rows:
                check("★帳上要看得出原本會擋的理由★",
                      "留痕" in str(rows[-1].get("note", "")), str(rows[-1]))
            check("★而且要在 stderr 明講會留帳★(沒有人看的留痕等於沒有留痕)",
                  "留在治理帳" in r2.stderr, r2.stderr[-300:])
    finally:
        _sh.rmtree(d, ignore_errors=True)
    print("  ✓ t_skip_code_loop_never_skips_bound_tests")


def t_gate_blocked_writes_hard_ledger_row():
    """★閘擋下人的那一刻要落一筆 hard 帳★(2026-09-08 #19 S1)。

    修的病:治理帳 29,348 筆、`hard=true` **一筆都沒有**、`kind=blocked` 也是 0
    ——不是沒人寫那個欄位,是會寫它的那幾處從沒觸發過;真正的缺口是 hook 層的
    `exit 1`(pre-push 7 處、pre-commit 3 處)擋掉一次推送時,帳上完全看不出來。
    而 README 對外宣稱「每道關卡攔了誰、硬擋還是提醒」都在帳上。

    ★寫的人是「做判定的那一方」,不是 hook★(r1 架構對齊席):這個 repo 既有的模式
    就是子命令順便落帳,沒有「hook 呼叫記帳端點」的先例——而且 2026-09-07 真的有人
    寫過一個不存在的 `lumos gov-event`,當時的結論是「工具沒有給外部腳本寫治理帳的入口」。

    ★同一次推送的事件要串得起來★(#19 S6):pre-push 是逐 ref 迴圈、而錨點跑在迴圈外,
    所以整支層級的事件用 hook 產生的一次性識別碼,不是盲取 HEAD。
    """
    import subprocess as _sp, shutil as _sh, os as _os
    _need_src("scripts/lumos")
    lumos = Path(GRAPHCTL).resolve()
    root = _gate_ledger_sandbox()
    try:
        env = dict(_os.environ); env["LUMOS_PUSH_ATTEMPT"] = "TESTATTEMPT-1"
        r = _sp.run([sys.executable, str(lumos), "anchor", "verify", "--repo", str(root)],
                    capture_output=True, text=True, cwd=str(root), timeout=180, env=env)
        check("★前置★ 現場成立:錨點真的被擋了", r.returncode == 1, r.stdout + r.stderr)
        rows = _gate_rows(root)
        hard = [x for x in rows if x.get("hard") is True]
        check("★擋下時要留一筆 hard=true 的帳★", len(hard) == 1, str(rows))
        if hard:
            check("★kind 要是 blocked★(既有 29,348 筆裡一筆都沒有)",
                  hard[0].get("kind") == "blocked", str(hard[0]))
            check("★要講得出是哪一道閘★", hard[0].get("gate") == "anchor", str(hard[0]))
            check("★要講得出擋的是什麼★(不能只有一個空 note)",
                  "runner.py" in str(hard[0].get("note", "")), str(hard[0]))
            check("★同一次推送的識別碼要落進去★(整支層級的事件靠它串,不是靠 HEAD)",
                  hard[0].get("attempt_id") == "TESTATTEMPT-1", str(hard[0]))

        # 沒有那個環境變數時不准硬塞一個假的
        (root / "docs" / ".governance-log.jsonl").write_text("", encoding="utf-8")
        env2 = dict(_os.environ); env2.pop("LUMOS_PUSH_ATTEMPT", None)
        _sp.run([sys.executable, str(lumos), "anchor", "verify", "--repo", str(root)],
                capture_output=True, text=True, cwd=str(root), timeout=180, env=env2)
        rows = _gate_rows(root)
        check("★沒有識別碼時就不要那個欄位,不准編一個★",
              rows and "attempt_id" not in rows[-1], str(rows[-1:]))
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_gate_blocked_writes_hard_ledger_row")


def _break_for_write(path):
    """讓 path 寫不進去,root 身分也一樣:把檔換成同名資料夾。
    只改權限(chmod 0o444)在 root 下不生效——root 照寫不誤,「寫不進去」的現場根本造不出來,測試就假紅。
    開檔追加碰到資料夾一定丟 OSError(IsADirectoryError),跟磁碟滿、權限錯走同一條例外路。"""
    import os as _os
    p = Path(path)
    if p.exists() and not p.is_dir():
        _os.remove(p)
    p.mkdir(parents=True, exist_ok=True)


def t_gate_ledger_write_failure_does_not_change_verdict():
    """★記帳失敗不得改寫閘的判定★(2026-09-08 #19 S7,r1 外家否決席)。

    既有的治理帳寫入器是 `except OSError: pass`——I/O 錯誤靜靜吞掉。
    新的寫入如果照抄,「擋人時一定有帳」這個承諾在磁碟滿、權限錯、帳檔壞掉時就是空的。

    但反過來要求「寫成功才擋」更糟:那會讓**觀測系統故障變成放行**
    ——正是這一批要修的病的鏡像。所以規則是兩條:
    ①該擋還是擋 ②寫不進去要在 stderr 明講 `telemetry-write-failed`,不能靜靜吞掉。
    """
    import subprocess as _sp, shutil as _sh, os as _os
    _need_src("scripts/lumos")
    lumos = Path(GRAPHCTL).resolve()
    root = _gate_ledger_sandbox()
    try:
        log = root / "docs" / ".governance-log.jsonl"
        _break_for_write(log)          # 帳檔寫不進去
        r = _sp.run([sys.executable, str(lumos), "anchor", "verify", "--repo", str(root)],
                    capture_output=True, text=True, cwd=str(root), timeout=180)
        check("★帳寫不進去,該擋的還是要擋★(不能因為觀測壞了就放行)",
              r.returncode == 1, "rc=%s\n%s%s" % (r.returncode, r.stdout, r.stderr))
        check("★而且要在 stderr 明講寫不進去★(靜靜吞掉的話,承諾在最需要時是空的)",
              "telemetry-write-failed" in r.stderr, r.stderr[-400:])
        check("★訊息要講明判定不受影響★(免得人以為被擋是記帳造成的)",
              "判定不受影響" in r.stderr, r.stderr[-300:])
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_gate_ledger_write_failure_does_not_change_verdict")


def t_prepush_makes_one_attempt_id():
    """★推送閘要產生一次性識別碼,而且要 export 出去★(2026-09-08 #19 S6)。

    這支是逐 ref 迴圈,而錨點與健檢跑在迴圈**外面**——所以「當下的 commit」
    對整支層級的閘沒有唯一答案。同次推多個 ref、推的不是目前 checkout 的 ref、
    detached HEAD 或推 tag,盲取 HEAD 都會把事件歸到錯的 commit 上。
    """
    _need_src("scripts/hooks/pre-push", "scripts/lumos")
    root = Path(GRAPHCTL).resolve().parent.parent
    src = (root / "scripts" / "hooks" / "pre-push").read_text(encoding="utf-8")
    import re as _re
    m = _re.search(r"(?m)^export LUMOS_PUSH_ATTEMPT=(.+)$", src)
    check("★要 export(不 export 的話子行程讀不到)★", m is not None,
          "找不到 export LUMOS_PUSH_ATTEMPT=")
    if m:
        check("★識別碼要每次不同★(寫死的話串不出「同一次」)",
              ("$$" in m.group(1)) or ("RANDOM" in m.group(1)) or ("date" in m.group(1)),
              m.group(1))
        # ★比對真正的呼叫行,不是註解★:第一版用 `src.index("anchor verify")`,
        # 咬到的是檔頭那段說明文字裡的同一串字,位置在最前面,判斷當場反過來。
        # 這是同一天第三次「斷言咬到註解」。
        i_exp = src.index("export LUMOS_PUSH_ATTEMPT=")
        i_anchor = src.index('"$GRAPHCTL" anchor verify')
        check("★要在第一道閘之前就產生好★(不然前面的閘串不進去)", i_exp < i_anchor,
              "export 在 %d,第一道閘的呼叫在 %d" % (i_exp, i_anchor))
    lsrc = (root / "scripts" / "lumos").read_text(encoding="utf-8")
    check("★lumos 端要讀它★(只有 hook 產生、沒人讀,等於沒做)",
          'LUMOS_PUSH_ATTEMPT' in lsrc, "lumos 沒讀那個環境變數")
    print("  ✓ t_prepush_makes_one_attempt_id")


def t_hooks_path_forms_all_recognized():
    """★core.hooksPath 三種寫法都要判成同一件事,而且 hook 真的不在時要翻紅★(2026-09-08 #19 S5)。

    修的是一個**現在就在講錯話**的東西:`lumos enforcement` 把 git-pre-commit 與
    git-pre-push 都印成 inactive,而那兩道每次推送都在跑。根因是碼裡拿
    `core.hooksPath` 的值跟字面字串 `"scripts/hooks"` 比,而本機存的是絕對路徑。

    ★方向是「該說有卻說沒有」★——表面上是安全方向(不會假綠),實際後果更糟:
    那兩列長期是紅的,所以真的哪天 hook 掉了,那個紅沒有任何訊號價值。儀表板自己在喊狼來了。

    ★這支同時是反向對照★:只驗「三種寫法都說 active」會被一個「永遠回 True」的實作騙過去,
    所以最後一段把 hook 檔真的移走,要求它翻成 inactive。
    """
    import subprocess as _sp, tempfile as _tf, shutil as _sh, os as _os
    _need_src("scripts/lumos")
    lumos = Path(GRAPHCTL).resolve()
    root = Path(_tf.mkdtemp(prefix="gctl-hookspath-"))
    try:
        _sp.run(["git", "init", "-q", str(root)], check=True, capture_output=True)
        hooks = root / "scripts" / "hooks"; hooks.mkdir(parents=True)
        for fn in ("pre-commit", "pre-push"):
            f = hooks / fn; f.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8"); _os.chmod(f, 0o755)

        def _rows():
            r = _sp.run([sys.executable, str(lumos), "enforcement"],
                        capture_output=True, text=True, cwd=str(root), timeout=180)
            return r.stdout

        def _set(v):
            _sp.run(["git", "-C", str(root), "config", "core.hooksPath", v],
                    check=True, capture_output=True)

        # ① 相對 ② 絕對 ③ ~ 開頭(用 HOME 指到這個沙箱做出來)
        forms = [("相對", "scripts/hooks"), ("絕對", str(hooks))]
        home = root / "home"; home.mkdir()
        link = home / "hk"
        try:
            _os.symlink(str(hooks), str(link)); forms.append(("~ 開頭", "~/hk"))
        except OSError:
            pass

        env = dict(_os.environ); env["HOME"] = str(home)
        for name, val in forms:
            _set(val)
            r = _sp.run([sys.executable, str(lumos), "enforcement"],
                        capture_output=True, text=True, cwd=str(root), timeout=180, env=env)
            for layer in ("git-pre-commit", "git-pre-push"):
                line = [l for l in r.stdout.splitlines() if layer in l]
                check("★%s 寫法要判成 active(%s)★" % (name, layer),
                      bool(line) and "active" in line[0] and "inactive" not in line[0],
                      (line[0] if line else "沒有這一列") + " | 值=" + val)

        # ★反向對照★:設定還指著同一個地方,但 hook 檔不見了 → 必須翻紅
        _set(str(hooks))
        (hooks / "pre-push").unlink()
        r = _sp.run([sys.executable, str(lumos), "enforcement"],
                    capture_output=True, text=True, cwd=str(root), timeout=180)
        line = [l for l in r.stdout.splitlines() if "git-pre-push" in l]
        check("★hook 檔真的不在時要翻成 inactive★(只驗「它說 active」不算驗過)",
              bool(line) and "inactive" in line[0], line[0] if line else "沒有這一列")
        line = [l for l in r.stdout.splitlines() if "git-pre-commit" in l]
        check("★而且不能一起誤殺:另一支還在就還是 active★",
              bool(line) and "inactive" not in line[0], line[0] if line else "沒有這一列")

        # 指到別人的目錄 → 不是我們的,要判 inactive(既有 teardown 守衛的同一條語意)
        other = root / "githooks"; other.mkdir()
        _set(str(other))
        r = _sp.run([sys.executable, str(lumos), "enforcement"],
                    capture_output=True, text=True, cwd=str(root), timeout=180)
        line = [l for l in r.stdout.splitlines() if "git-pre-commit" in l]
        check("★指到別人自設的目錄 → 不算我們生效★",
              bool(line) and "inactive" in line[0], line[0] if line else "沒有這一列")
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_hooks_path_forms_all_recognized")


def t_hooks_path_sibling_worktree():
    """★附加工作樹裡,掛鉤路徑指向主工作目錄的 hooks 不算沒接上★(2026-10-13 實機確認)。

    core.hooksPath 存在共用的 .git/config,所有工作樹看到的都是主工作目錄那份 scripts/hooks;
    enforcement 只認「指向自己這個工作樹」,於是在每個附加工作樹裡都把每次推送都在跑的兩道 git 閘印成 inactive。
    ★但也不能直接說 active★:跑的是主工作目錄那份,工作樹裡改過的 hook 推送時不會跑——內容不同要講出來。
    反向對照:指向無關 repo 的 scripts/hooks 不准被當成自家;主工作目錄那份不在要翻紅。
    """
    import subprocess as _sp, tempfile as _tf, shutil as _sh, os as _os
    _need_src("scripts/lumos")
    lumos = Path(GRAPHCTL).resolve()
    base = Path(_tf.mkdtemp(prefix="gctl-wthooks-"))
    try:
        def _repo(p):
            _sp.run(["git", "init", "-q", str(p)], check=True, capture_output=True)
            h = p / "scripts" / "hooks"
            h.mkdir(parents=True)
            for fn in ("pre-commit", "pre-push"):
                f = h / fn
                f.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
                _os.chmod(f, 0o755)
            g = ["git", "-C", str(p), "-c", "user.name=t", "-c", "user.email=t@t", "-c", "core.hooksPath=/dev/null"]
            _sp.run([*g, "add", "-A"], check=True, capture_output=True)
            _sp.run([*g, "commit", "-q", "-m", "init"], check=True, capture_output=True)
            return h
        main = base / "main"
        mh = _repo(main)
        wt = base / "wt"
        _sp.run(["git", "-C", str(main), "worktree", "add", "-q", str(wt)], check=True, capture_output=True)
        _sp.run(["git", "-C", str(main), "config", "core.hooksPath", str(mh)], check=True, capture_output=True)

        def _line(layer):
            r = _sp.run([sys.executable, str(lumos), "enforcement"],
                        capture_output=True, text=True, cwd=str(wt), timeout=180)
            rows = [row for row in r.stdout.splitlines() if layer in row]
            return rows[0] if rows else "沒有這一列"

        for layer in ("git-pre-commit", "git-pre-push"):
            ln = _line(layer)
            check("★工作樹裡掛鉤指向主工作目錄、內容相同 → active(%s)★" % layer,
                  " active" in ln and "inactive" not in ln, ln)
            fn = layer.removeprefix("git-")
            check("★說明要講跑的是主工作目錄那份(%s)★" % layer, ("另一個工作目錄那份 %s" % (mh / fn)) in ln, ln)

        # 工作樹裡改了 pre-push:推送時跑的不是這份 → degraded,不是 active 也不是 inactive
        (wt / "scripts" / "hooks" / "pre-push").write_text("#!/bin/sh\necho changed\nexit 0\n", encoding="utf-8")
        ln = _line("git-pre-push")
        check("★工作樹的 hook 跟生效那份不同 → degraded★", "degraded" in ln, ln)
        ln = _line("git-pre-commit")
        check("★沒改的那支照樣 active★", " active" in ln and "inactive" not in ln, ln)

        # 工作樹裡根本沒有這支 hook:推送時本來就跑生效那份,不准說成「內容不同」而判 degraded(代碼審 r1 通才席)
        (wt / "scripts" / "hooks" / "pre-commit").unlink()
        ln = _line("git-pre-commit")
        check("★工作樹沒有同名 hook → 照樣 active,不是 degraded★", " active" in ln and "degraded" not in ln, ln)
        check("★而且說明講的是沒有,不是不同★", "不同" not in ln, ln)

        # 指向同 repo 裡某個子資料夾的 scripts/hooks:不是另一個工作目錄的根,不准當成工作樹那份(代碼審 r1 通才席)
        sub = main / "sub" / "scripts" / "hooks"
        sub.mkdir(parents=True)
        for fn in ("pre-commit", "pre-push"):
            f = sub / fn
            f.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
            _os.chmod(f, 0o755)
        _sp.run(["git", "-C", str(main), "config", "core.hooksPath", str(sub)], check=True, capture_output=True)
        ln = _line("git-pre-push")
        check("★指向 repo 內子資料夾的 scripts/hooks 不算另一個工作目錄★",
              "inactive" in ln and "另一個工作目錄" not in ln, ln)

        # 反向對照①:指向無關 repo 的 scripts/hooks → 不是自家
        oh = _repo(base / "other")
        _sp.run(["git", "-C", str(main), "config", "core.hooksPath", str(oh)], check=True, capture_output=True)
        ln = _line("git-pre-commit")
        check("★指向無關 repo 的 scripts/hooks 不准當自家★", "inactive" in ln, ln)

        _sp.run(["git", "-C", str(main), "config", "core.hooksPath", str(mh)], check=True, capture_output=True)
        # 生效那份在但不可執行 → inactive(代碼審 r2 通才席:拿掉可執行檢查原本照綠)
        _os.chmod(mh / "pre-push", 0o644)
        ln = _line("git-pre-push")
        check("★生效那份不可執行 → inactive★", "inactive" in ln, ln)
        _os.chmod(mh / "pre-push", 0o755)
        # 生效那份的回頭重讀沒帶 --gate → inactive,而且點名生效那份(代碼審 r2 通才席)
        keep = (mh / "pre-push").read_text(encoding="utf-8")
        (mh / "pre-push").write_text("#!/bin/sh\nlumos note-audit reread-check --range x\n", encoding="utf-8")
        ln = _line("git-pre-push")
        check("★生效那份沒接上關卡 → inactive 並點名它★", "inactive" in ln and str(mh / "pre-push") in ln, ln)
        (mh / "pre-push").write_text(keep, encoding="utf-8")
        # 工作樹那份讀不到:不准掉成 unknown 只剩錯誤碼,要列 degraded 並講讀不到哪支(代碼審 r2 通才席)
        wpc = wt / "scripts" / "hooks" / "pre-commit"
        wpc.write_text((mh / "pre-commit").read_text(encoding="utf-8"), encoding="utf-8")
        _os.chmod(wpc, 0o000)
        try:
            ln = _line("git-pre-commit")
        finally:
            _os.chmod(wpc, 0o644)
        if _os.access(wpc, _os.R_OK) and _os.geteuid() != 0:
            check("★工作樹那份讀不到 → degraded 並講讀不到★", "degraded" in ln and "讀不到" in ln, ln)

        # 反向對照②:指回主工作目錄,但那份 pre-commit 不在 → inactive
        (mh / "pre-commit").unlink()
        ln = _line("git-pre-commit")
        check("★主工作目錄那份不在 → inactive★", "inactive" in ln, ln)
    finally:
        _sh.rmtree(base, ignore_errors=True)
    print("  ✓ t_hooks_path_sibling_worktree")


def t_wrapper_log_path_agrees():
    """★第二個來源的路徑要兩邊都宣告,不能只有讀的那一側自己猜★(2026-09-08 架構對齊席 A1)。

    看門狗在健康檔不在時會去讀 wrapper 的 stdout 紀錄檔當第二個來源。
    原本只有看門狗這一側寫死一條路徑,而真正的權威是 launchd 那份 plist 的 StandardOutPath
    ——那份檔住在家目錄、不進版控。兩邊各自漂移不會有人知道,而漂移的後果是
    ★第二個來源靜靜地消失★,看門狗又退回只有一個來源的狀態。

    這條把它變成雙邊約定並機械比對。★誠實記:這擋不住有人去改 plist★——
    那份檔不在版控裡,這個 repo 看不到它;真的被改掉時看門狗會 fail-safe 退回舊判斷。
    """
    _need_src("governance/daily-governance.sh", "governance/wrapper-watchdog.sh")
    root = Path(GRAPHCTL).resolve().parent.parent
    import re as _re
    paths = {}
    for f in ("daily-governance.sh", "wrapper-watchdog.sh"):
        src = (root / "governance" / f).read_text(encoding="utf-8")
        m = _re.search(r'^\s*WRAPPER_LOG="([^"]+)"', src, _re.M)
        paths[f] = m.group(1) if m else None
        check("★%s 要宣告 stdout 紀錄檔的路徑★" % f, paths[f] is not None,
              "找不到 WRAPPER_LOG=,約定就只剩一邊知道")
    check("★兩邊宣告的路徑要一模一樣★",
          paths["daily-governance.sh"] == paths["wrapper-watchdog.sh"],
          "產出側 %r vs 讀取側 %r" % (paths["daily-governance.sh"], paths["wrapper-watchdog.sh"]))
    print("  ✓ t_wrapper_log_path_agrees")


def t_watchdog_time_math_is_one_scheme():
    """★同一個檔裡不要養兩套時間比較法★(2026-09-08 架構對齊席 A2,它的查證我複驗過)。

    這個工具鏈一路以來只用一種:`fromisoformat` 解析、拿 `datetime.now(timezone.utc)` 相減。
    我加第二個來源時用了 naive 的 `strptime` + 沒有時區的 `datetime.now()`
    ——**全 repo 唯一一處**。紀錄檔上的時間戳確實是本地字串,但 `astimezone()`
    就能接回既有那一套,不需要另開一條路。

    兩套並存的實際後果不只是難讀:naive 的比較在日光節約回撥的重複時段分不出來,
    人工調鐘也會差一小時,而這支的判斷門檻是以小時計的。
    """
    _need_src("governance/wrapper-watchdog.sh")
    root = Path(GRAPHCTL).resolve().parent.parent
    raw = (root / "governance" / "wrapper-watchdog.sh").read_text(encoding="utf-8")
    # ★只看碼,不看註解★:第一版忘了剝註解,結果咬到「這裡曾經用過 datetime.now()」
    # 那句說明文字,報了一個假的紅。這是「斷言沒咬到目標」的反面,同一族。
    src = "\n".join(ln for ln in raw.splitlines() if not ln.lstrip().startswith("#"))
    check("★前置★ 現場成立:剝完註解還看得到那段時間運算",
          "total_seconds()" in src, "剝過頭了,連碼都沒了")
    check("★不准出現沒有時區的 datetime.now()★",
          "datetime.now()" not in src.replace("datetime.now(datetime.timezone.utc)", ""),
          "有 naive 的 now(),那是第二套時間比較法")
    check("★strptime 解析完要接上 astimezone()★",
          ("strptime" not in src) or ("astimezone()" in src),
          "用了 strptime 卻沒轉成帶時區的,兩套時間法並存")
    print("  ✓ t_watchdog_time_math_is_one_scheme")


def t_watchdog_tests_never_notify_the_desktop():
    """★測試跑真的看門狗時,不准在使用者桌面彈通知★(2026-09-08,使用者回報「叫不停」)。

    真的發生了:三支看門狗測試會真的執行那支腳本,而沙箱裡沒有通知 app,
    `notify()` 就落到系統的 `osascript` ——**每一次都是一則真通知**。
    一輪全套約 20 則,而全套一天跑了好幾遍。★是我的測試在騷擾使用者,不是看門狗壞掉。★

    ★修在測試側不在產品側★:不新增「不要通知」的開關(那種開關會被拿來關真的告警)。
    這一支釘住:每一個「跑真看門狗」的呼叫點都必須帶 `_watchdog_quiet_env`。
    下次再加一支測試忘了帶,這裡會紅。
    """
    import re as _re
    src = Path(__file__).resolve().read_text(encoding="utf-8")
    bad = []
    for m in _re.finditer(r'_sp\.run\(\["bash", str\((wd|g / "wrapper-watchdog\.sh")\)\]', src):
        # ★窗口要前後都看★:設定安靜環境的那一行可能寫在呼叫的前面(env=… 先算好),
        # 第一版只往後看 400 字,漏掉那種寫法、報了一個假的紅。
        seg = src[max(0, m.start() - 400):m.start() + 400]
        if "_watchdog_quiet_env" not in seg:
            ln = src[:m.start()].count("\n") + 1
            bad.append("第 %d 行" % ln)
    check("★每個跑真看門狗的呼叫點都要帶安靜環境★", not bad,
          "沒帶的:" + "、".join(bad))
    # 反向對照:那支 helper 真的擋得住嗎
    import subprocess as _sp2, tempfile as _tf2, shutil as _sh2, os as _os2
    root = Path(_tf2.mkdtemp(prefix="gctl-quiet-"))
    try:
        env = _watchdog_quiet_env(root)
        hit = root / "hit"
        probe = root / "p.sh"
        probe.write_text('#!/bin/sh\nosascript -e x && echo ok\n', encoding="utf-8")
        _os2.chmod(probe, 0o755)
        r = _sp2.run(["bash", str(probe)], capture_output=True, text=True, env=env, timeout=60)
        check("★替身要真的蓋掉系統那支★(不然這條守衛是空的)",
              "ok" in r.stdout and not hit.exists(), r.stdout + r.stderr)
    finally:
        _sh2.rmtree(root, ignore_errors=True)
    print("  ✓ t_watchdog_tests_never_notify_the_desktop")


def _watchdog_quiet_env(root, base=None):
    """跑真的看門狗時,★把桌面通知那條路擋掉★(2026-09-08,使用者回報「叫不停」)。

    真的發生了:看門狗的測試會真的執行那支腳本,而沙箱裡沒有通知 app
    → `notify()` 落到系統的 `osascript` → **每一次都在使用者桌面彈一則真通知**。
    三支看門狗測試加起來一輪跑約 20 次,而全套一天跑了好幾遍。

    ★修在測試側,不在產品側★:不新增「不要通知」的環境變數——那種開關會被拿來
    關掉真的告警,而這支的存在理由就是「死了要有人知道」。
    改成在測試的 PATH 前面塞兩支無害替身(`osascript` / `open`),
    腳本照原樣跑、判斷照原樣走,只是話送不到桌面。
    """
    import os as _os
    b = Path(root) / "_quiet_bin"
    b.mkdir(exist_ok=True)
    for name in ("osascript", "open"):
        f = b / name
        f.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
        _os.chmod(f, 0o755)
    env = dict(base or _os.environ)
    env["PATH"] = str(b) + ":" + env.get("PATH", "")
    return env


def t_wrapper_watchdog_unknown_is_not_healthy():
    """★「問不出來」不准靜靜地變成「沒事」★(2026-09-08 code-batch20,三個現場都實跑重現過)。

    這支的存在理由是「死了要有人知道」,所以★該喊沒喊★比多喊一次嚴重得多。
    外家否決席挑出三個會讓它一聲不吭的洞,每一個我都自己造現場跑過:

    ① **健康檔的完成時間在未來**(手動調時、時鐘錯、檔被竄改):算出來的年齡是負數,
       既不算逾期也不算讀不動,五步全 0 就直接落進「沒事」——★整支完全沒有輸出★。
    ② **鎖齡量不出來**:鎖在、pid 活著、指令名對得上,但 python3 壞掉(launchd 那種
       精簡環境真的會遇到)。舊寫法把空值帶到 else 判「正在跑,不喊」——
       ★卡了 72 小時一聲不吭★。
    ③ **紀錄檔上的完成時間在未來**:不該被當成「剛剛才跑完」。
    """
    import shutil as _sh, subprocess as _sp, tempfile as _tf, datetime as _dt, os as _os, time as _time
    _need_src("governance/wrapper-watchdog.sh")
    repo = Path(GRAPHCTL).resolve().parent.parent
    src = (repo / "governance" / "wrapper-watchdog.sh").read_text(encoding="utf-8")

    def _mk():
        root = Path(_tf.mkdtemp(prefix="gctl-wdunk-"))
        g = root / "governance"; (g / "logs").mkdir(parents=True)
        (g / "wrapper-watchdog.sh").write_text(src, encoding="utf-8")
        return root, g

    def _run(g, env=None):
        (g / ".wrapper-watchdog-state").unlink(missing_ok=True)
        env = _watchdog_quiet_env(g.parent, env)          # ★別在使用者桌面彈真通知★
        r = _sp.run(["bash", str(g / "wrapper-watchdog.sh")], capture_output=True, timeout=300, env=env)
        return r.stdout.decode("utf-8", "replace").strip()

    # ① 健康檔的完成時間在未來
    root, g = _mk()
    try:
        fut = (_dt.datetime.now(_dt.timezone.utc) + _dt.timedelta(hours=5)).strftime("%Y-%m-%dT%H:%M:%SZ")
        (g / ".daily-governance-health.json").write_text(
            '{"finished_at":"%s","steps":{"governance":0},"total":0}' % fut, encoding="utf-8")
        out = _run(g)
        check("★健康檔的完成時間在未來 → 不准一聲不吭★", out != "", "整支沒有任何輸出")
        check("★而且要講成「這份檔不能用」,不是「沒事」★",
              ("不對" in out or "讀不動" in out or "矛盾" in out), out)
    finally:
        _sh.rmtree(root, ignore_errors=True)

    # ② 鎖齡量不出來(python3 壞掉),而 wrapper 其實卡了 72 小時
    root, g = _mk()
    proc = None
    try:
        b = root / "bin"; b.mkdir()
        (b / "python3").write_text("#!/bin/sh\nexit 1\n", encoding="utf-8"); _os.chmod(b / "python3", 0o755)
        h = g / "fake-daily-governance.sh"
        h.write_text("#!/bin/bash\nsleep 40\n", encoding="utf-8"); _os.chmod(h, 0o755)
        proc = _sp.Popen(["bash", str(h)], stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
        lk = g / ".daily-governance.lock"; lk.mkdir()
        (lk / "pid").write_text(str(proc.pid), encoding="utf-8")
        _os.utime(lk, (0, _time.time() - 72 * 3600))
        env = dict(_os.environ); env["PATH"] = str(b) + ":" + env["PATH"]
        out = _run(g, env)
        check("★算不出鎖齡 → 不准當成「正在跑、沒事」★", out != "", "整支沒有任何輸出")
        check("★要講明是「判不出來」不是「沒事」★", "判不出來" in out or "讀不到" in out, out)
    finally:
        if proc is not None:
            proc.kill(); proc.wait(timeout=10)
        _sh.rmtree(root, ignore_errors=True)

    # ③ 紀錄檔的完成時間在未來 + 「完成不了」不准被當成完成
    root, g = _mk()
    try:
        wlog = g / "logs" / "daily-wrapper.log"
        now = _dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        fut2 = (_dt.datetime.now() + _dt.timedelta(hours=3)).strftime("%Y-%m-%d %H:%M:%S")
        wlog.write_text("[%s] daily-governance wrapper 完成\n" % fut2, encoding="utf-8")
        check("★紀錄檔上未來的完成時間 → 不算「剛跑完」★",
              "從來沒跑完過" in _run(g), "被當成剛跑完了")
        wlog.write_text("[%s] ⚠ daily-governance wrapper 完成不了,要人來看\n" % now, encoding="utf-8")
        check("★「wrapper 完成不了」是錯誤訊息,不是完成事件★"
              "(舊寫法只找「這一行裡有沒有那四個字」,把真警報降級成沒事)",
              "從來沒跑完過" in _run(g), "被誤判成跑完了")
        wlog.write_text("[%s] daily-governance wrapper 完成\n" % now, encoding="utf-8")
        check("★反向對照:真正的完成行仍然要認得出來★(證明上面不是靠改過頭換來的)",
              "有在跑" in _run(g), "改過頭了,真的完成也認不出來")
    finally:
        _sh.rmtree(root, ignore_errors=True)

    # 結構:只讀尾端(無上限掃描沒有 fail-safe;實測 68MB 跑 0.9 秒,所以是防患不是救火)
    check("★讀紀錄檔要有上限,不能整份掃★",
          "TAIL" in src and "seek(size - TAIL)" in src,
          "找不到尾端讀取:檔案養大之後這支會跟著變慢,而且沒有任何上限")


def t_wrapper_watchdog_states():
    """★看門狗四種輸入各自要講對話★(2026-09-07 代碼審 r1 四席各自實測)。

    ① wrapper 正在跑(自主迴圈那段可跑三小時)→ 不准喊「超過 36 小時沒跑完」。
       第一版只看 finished_at 的年齡、完全不看鎖,會在它正常執行時發假警報,
       而那句話還會誘使人去 kill 一個其實正常的行程。
    ② finished_at 讀不動 + total=0 → 不准靜默判成正常。第一版時間解析失敗只讓
       age 變空字串,控制流直接掉到「比 total」,剛好是 0 就給綠燈。
    ③ 五步全 0、只有 total 壞掉 → 要說「這份檔自相矛盾」。第一版讀 total、健檢讀 steps,
       同一份檔兩邊講出相反結論(而碼裡還寫著「不會各說各話」)。
    ④ 它自己的狀態檔壞掉 → 要喊出來。第一版靜默吞掉,邊緣觸發失效、每小時重複喊同一件事。
    """
    import datetime as _dt
    import os as _os
    import shutil as _sh
    import subprocess as _sp
    import tempfile as _tf
    _need_src("governance/wrapper-watchdog.sh")
    repo = Path(GRAPHCTL).resolve().parent.parent
    root = Path(_tf.mkdtemp(prefix="gctl-wd-"))
    try:
        g = root / "governance"
        g.mkdir()
        wd = g / "wrapper-watchdog.sh"
        wd.write_text((repo / "governance" / "wrapper-watchdog.sh").read_text(encoding="utf-8"),
                      encoding="utf-8")
        hp = g / ".daily-governance-health.json"
        st = g / ".wrapper-watchdog-state"

        def _ago(h):
            return (_dt.datetime.now(_dt.timezone.utc)
                    - _dt.timedelta(hours=h)).strftime("%Y-%m-%dT%H:%M:%SZ")

        def _run():
            st.unlink(missing_ok=True)
            return _sp.run(["bash", str(wd)], capture_output=True, text=True, timeout=120,
                           env=_watchdog_quiet_env(root))   # ★別在使用者桌面彈真通知★

        # ① 逾期的健康檔 + 一支真的在跑的持鎖行程 → 不喊
        hp.write_text('{"finished_at":"%s","steps":{"governance":0},"total":0}' % _ago(37),
                      encoding="utf-8")
        holder = g / "fake-daily-governance.sh"
        holder.write_text("#!/bin/bash\nsleep 60\n", encoding="utf-8")
        _os.chmod(holder, 0o755)
        proc = _sp.Popen(["bash", str(holder)], stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
        lock = g / ".daily-governance.lock"
        try:
            lock.mkdir()
            (lock / "pid").write_text(str(proc.pid), encoding="utf-8")
            r = _run()
            check("★它正在跑的時候不准喊「超過 36 小時沒跑完」★",
                  "36 小時" not in r.stdout, r.stdout[-300:])
            check("正在跑要記成 running", st.read_text(encoding="utf-8").startswith("running|"),
                  st.read_text(encoding="utf-8"))
        finally:
            proc.kill()
            proc.wait(timeout=10)
            _sh.rmtree(lock, ignore_errors=True)

        # ② 時間讀不動 + total=0 → 不准判成正常
        hp.write_text('{"finished_at":"not-a-time","steps":{"governance":0},"total":0}',
                      encoding="utf-8")
        r = _run()
        check("★時間讀不動就是讀不動,不准掉進「沒事」★",
              st.read_text(encoding="utf-8").startswith("unreadable|"),
              st.read_text(encoding="utf-8") + r.stdout[-200:])

        # ③ 五步全 0、只有 total 壞掉 → 自相矛盾
        hp.write_text('{"finished_at":"%s","steps":{"governance":0,"doctor":0},"total":"oops"}'
                      % _ago(5), encoding="utf-8")
        r = _run()
        check("★total 跟 steps 對不上要單獨喊,不能跟健檢各說各話★",
              st.read_text(encoding="utf-8").startswith("inconsistent|"),
              st.read_text(encoding="utf-8") + r.stdout[-200:])

        # ④ 狀態檔壞掉(是個目錄)→ 要喊,而且錯誤不准漏到 stderr
        hp.write_text('{"finished_at":"%s","steps":{"doctor":9},"total":1}' % _ago(5),
                      encoding="utf-8")
        st.unlink(missing_ok=True)
        st.mkdir()
        r = _sp.run(["bash", str(wd)], capture_output=True, text=True, timeout=120,
                    env=_watchdog_quiet_env(root))       # ★別在使用者桌面彈真通知★
        check("★自己的狀態檔寫不進去要喊出來★(第一版靜默吞掉,邊緣觸發整個失效)",
              "狀態檔寫不進去" in r.stdout, r.stdout[-300:])
        check("★而且 bash 的重導向錯誤不准漏到 stderr★(2>/dev/null 對這種錯誤是無效的)",
              r.stderr.strip() == "", r.stderr[-300:])
        _sh.rmtree(st, ignore_errors=True)
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_wrapper_watchdog_states")


def t_doctor_wrapper_sections_behave():
    """★健檢那兩段軟提醒的行為本身要有測試★(2026-09-07 代碼審 r1 通才席指出:
    在這之前唯一覆蓋它們的是「不擋人」那道結構守衛,不是行為正確性——門檻、
    失敗步驟偵測、成長率公式全都沒有一條會在被改壞時翻紅)。

    順便釘住兩條實測抓到的行為:
    ① 治理帳裡有壞行,只能跳過那一行,不准整份統計作廢
       (第一版取日期的防呆數的是「到行尾」的引號、真正切的只有 40 個字元,
        兩邊範圍不一致 → IndexError → 被最外層 broad except 吃掉印成綠色「跳過」)。
    ② finished_at 型別不對(JSON 數字)要跟壞字串一樣走黃色警告,
       不准因為拋的是 AttributeError 就掉到綠色「跳過」。
    """
    import datetime as _dt
    import json as _j
    import shutil as _sh
    import subprocess as _sp
    import tempfile as _tf
    _need_src("governance/daily-governance.sh")
    root = Path(_tf.mkdtemp(prefix="gctl-dsec-"))
    try:
        # 圖譜目錄名要合規(docs/*-knowledge),且要有 .git——健檢找健康檔是從 vault 往上
        # 找 .git 當根,沒有 .git 會退到 docs/ 那一層、就找不到 governance/。
        (root / ".git").mkdir()
        vault = root / "docs" / "test-knowledge"
        vault.mkdir(parents=True)
        (vault / "README.md").write_text("---\nstatus: active\n---\n\n內容\n", encoding="utf-8")
        gov = root / "governance"
        gov.mkdir()
        led = root / "docs" / ".governance-log.jsonl"

        # ★醒來時間要隔開★(2026-09-11):健檢有「電腦剛從睡眠醒來兩小時內不喊看門狗」的豁免,
        # 讀的是 sysctl kern.waketime;測試沒隔開的話,這台 Mac 剛醒的兩小時內下面那條必紅(主線版一樣)。
        # 做法:在子程序的 PATH 最前面放一支假 sysctl,平常回報「很久以前就醒了」。
        import os as _os
        import time as _time
        fakebin = root / "fakebin"
        fakebin.mkdir()

        def _fake_waketime(sec):
            f = fakebin / "sysctl"
            f.write_text("#!/bin/sh\necho '{ sec = %d, usec = 0 } Thu Jan  1 00:00:00 1970'\n" % sec, encoding="utf-8")
            f.chmod(0o755)
        _fake_waketime(0)
        env = dict(_os.environ, PATH=str(fakebin) + _os.pathsep + _os.environ.get("PATH", ""))

        def _doctor():
            return _sp.run([sys.executable, GRAPHCTL, "doctor", "--ci"], cwd=str(root),
                           capture_output=True, text=True, timeout=180, env=env).stdout

        def _ago(h):
            return (_dt.datetime.now(_dt.timezone.utc)
                    - _dt.timedelta(hours=h)).strftime("%Y-%m-%dT%H:%M:%SZ")

        # A1:超過 36 小時沒跑完 → 要喊
        (gov / ".daily-governance-health.json").write_text(
            _j.dumps({"finished_at": _ago(40), "steps": {"governance": 0}, "total": 0}),
            encoding="utf-8")
        out = _doctor()
        check("★超過 36 小時沒跑完要喊★", "36 小時沒跑完" in out, out[-600:])

        # A1:有步驟失敗 → 要喊,而且要點名是哪一步
        (gov / ".daily-governance-health.json").write_text(
            _j.dumps({"finished_at": _ago(2), "steps": {"governance": 0, "testmap": 9}, "total": 1}),
            encoding="utf-8")
        out = _doctor()
        check("★有步驟失敗要點名是哪一步★", "testmap" in out and "有步驟失敗" in out, out[-600:])

        # A1:finished_at 型別不對 → 黃色警告,不准退化成綠色「跳過」
        (gov / ".daily-governance-health.json").write_text(
            _j.dumps({"finished_at": 1234567, "steps": {"governance": 0}, "total": 0}),
            encoding="utf-8")
        out = _doctor()
        check("★時間欄位型別不對也要走黃色警告★(第一版拋 AttributeError 被外層吃成綠勾)",
              "健康紀錄的時間讀不動" in out, out[-600:])
        check("不准退化成 fail-open 的那句「跳過」",
              "治理腳本健康觀測跳過" not in out, out[-600:])

        # A1:看門狗沒在跑 → 要喊
        (gov / ".daily-governance-health.json").write_text(
            _j.dumps({"finished_at": _ago(2), "steps": {"governance": 0}, "total": 0}),
            encoding="utf-8")
        out = _doctor()
        check("★有治理腳本但看門狗沒在跑,要喊★(不然看門狗自己死掉也沒人知道)",
              "看門狗沒在跑" in out, out[-600:])
        # 豁免本身也釘住:一分鐘前才醒 → 排程還沒輪到,不喊
        _fake_waketime(int(_time.time()) - 60)
        out = _doctor()
        check("剛從睡眠醒來兩小時內不喊看門狗(排程還沒輪到)", "看門狗沒在跑" not in out, out[-600:])
        _fake_waketime(0)
        (gov / ".wrapper-watchdog-state").write_text("ok|x", encoding="utf-8")
        out = _doctor()
        check("看門狗剛跑過就不喊", "看門狗沒在跑" not in out, out[-600:])

        # A2:治理帳裡有壞行 → 只跳那一行,統計照算
        def _line(day, i):
            return _j.dumps({"ts": "%sT10:00:%02d+08:00" % (day, i % 60), "gate": "x"},
                            ensure_ascii=False)
        today = _dt.date.today()
        rows = []
        for k in range(1, 8):
            rows += [_line((today - _dt.timedelta(days=k)).isoformat(), i) for i in range(40)]
        for k in range(8, 16):
            rows += [_line((today - _dt.timedelta(days=k)).isoformat(), i) for i in range(2)]
        led.write_text("\n".join(rows) + "\n", encoding="utf-8")
        out = _doctor()
        check("★近 7 日均值超過前 7 日兩倍要喊★", "長得比平常快" in out, out[-600:])
        led.write_text("\n".join(rows)
                       + '\n{"ts": 123456789012345678901234567890, "g": "x"}\n'
                       + "not json at all\n"
                       + '\n{"ts": "壞掉的時間", "g": "x"}\n', encoding="utf-8")
        out2 = _doctor()
        check("★帳裡有壞行,只跳那一行,不准整份統計作廢★"
              "(第一版取日期的防呆範圍跟切片範圍不一致 → 整份被 broad except 吃掉)",
              "長得比平常快" in out2 and "治理帳成長觀測跳過" not in out2, out2[-600:])
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_doctor_wrapper_sections_behave")


def t_watchdog_notifier_bundle():
    """★通知用的那支 app:改完 Info.plist 一定要重簽,而且 handler 不能吃 argv★
    (2026-09-07 代碼審 code-batch14 r1,通才席與實測)。

    兩個都是「壞掉時完全不出聲」的形態,所以非釘不可:

    ① `osacompile` 會幫 app 簽章,而★簽章的雜湊包含 Info.plist 的內容★。腳本簽完之後才用
       `plutil -replace` 改 bundle id,等於簽完名才改合約——章當場作廢。後果不是難看:
       章壞掉時 applet 裡的 `do shell script` 會被系統**靜默擋掉**,於是「我真的跑到了」
       那個回報永遠不會發生,退路邏輯就變成永遠不會觸發的死碼。
    ② applet 的 handler 寫成 `on run argv` 時,用 `open -a APP --args …` 啟動會讓它
       ★整個不執行★(連第一行都沒跑到),而 `open` 照樣回 0。所以只能寫 `on run`、
       訊息從檔案讀。

    結構這一半到哪都跑得動;行為那一半只有在有那幾支 macOS 工具的機器上才跑。
    """
    import re as _re
    import shutil as _sh
    import subprocess as _sp
    _need_src("governance/install-watchdog.sh")
    repo = Path(GRAPHCTL).resolve().parent.parent
    src = (repo / "governance" / "install-watchdog.sh").read_text(encoding="utf-8")

    # ── 結構:重簽必須排在兩行 plutil 之後 ──
    i_plutil = max(src.find("plutil -replace CFBundleIdentifier"),
                   src.find("plutil -replace CFBundleName"))
    i_sign = src.find("codesign -f -s -")
    check("★建 app 的流程要有重簽這一步★", i_sign > 0, "找不到 codesign -f -s -")
    check("★重簽要排在改 Info.plist 之後★(先簽後改 = 章作廢,而且是靜默的)",
          i_plutil > 0 and i_sign > i_plutil, "plutil 在 %d,codesign 在 %d" % (i_plutil, i_sign))
    check("★驗收也要驗簽章★(只查檔案在不在,驗不出章壞掉)",
          "codesign --verify" in src, "verify_notifier 沒有驗簽章")

    # ── 結構:applet 的 handler 不准吃 argv ──
    m = _re.search(r"^on run(?P<rest>.*)$", src, _re.M)
    check("★applet 的 handler 要寫 `on run`,不能吃 argv★(吃 argv 就整支不執行,而 open 照樣回 0)",
          m is not None and m.group("rest").strip() == "", m.group(0) if m else "找不到 on run")
    check("訊息要從檔案讀(因為參數傳不進去)", "message.txt" in src, "沒有用檔案傳訊息")
    check("applet 要留「我跑到了」的印子,退路才有辦法觸發", '"$NOTIFIER_DIR/.ran"' in src or "markFile" in src,
          "沒有印子機制")

    # ── 結構:兩支腳本對同一個 bundle 的判斷要一致 ──
    wd = (repo / "governance" / "wrapper-watchdog.sh").read_text(encoding="utf-8")
    check("★看門狗判斷 app 可不可用要看執行檔,不是只看目錄在不在★"
          "(半成品 bundle 的目錄也存在,會被當成可用)",
          "Contents/MacOS/applet" in wd, "還在用 [ -d ] 判斷")
    check("移除時要把建出來的 app 一起清掉", 'rm -rf "$NOTIFIER"' in src, "--uninstall 沒清 app")

    # ── 結構:換圖示的三件事缺一不可 ──
    # 2026-09-07 一步一步試出來的:只放 icns 沒有用;三件事漏任何一件,通知上還是預設的卷軸。
    check("★①要刪掉 osacompile 附的 Assets.car★"
          "(那份編譯過的圖示目錄裝著預設 applet 圖示,macOS 優先用它、不看我們放的 icns)",
          "Assets.car" in src, "沒刪 Assets.car,圖示會是預設的卷軸")
    i_car = src.find("rm -f \"$staged/Contents/Resources/Assets.car\"")
    check("★②重簽要排在刪 Assets.car 與改 Info.plist 之後★",
          i_car > 0 and i_sign > i_car, "Assets.car 在 %d,codesign 在 %d" % (i_car, i_sign))
    check("★③bundle 識別碼要帶版本尾巴★"
          "(通知中心會快取某個識別碼第一次註冊時的圖示,換識別碼是唯一逼它重讀的辦法)",
          _re.search(r'NOTIFIER_ID="[^"]*\.v\d+"', src) is not None,
          "識別碼沒有版本尾巴,改了圖示也吃不到")
    check("要明確叫 LaunchServices 重讀(只 touch 不夠可靠)", "lsregister" in src, "沒有 lsregister")

    # ── 行為:工具齊全才跑(CI 上多半沒有) ──
    if not all(_sh.which(c) for c in ("osacompile", "sips", "iconutil", "plutil", "codesign")):
        print("  ✓ t_watchdog_notifier_bundle(結構部分;這台機器沒有 macOS 那幾支工具,行為部分略過)")
        return
    root = Path(tempfile.mkdtemp(prefix="gctl-notif-"))
    try:
        app = root / "T.app"
        scpt = root / "s.applescript"
        scpt.write_text("on run\n\tdisplay notification \"x\" with title \"y\"\nend run\n", encoding="utf-8")
        _sp.run(["osacompile", "-o", str(app), str(scpt)], capture_output=True, timeout=60)
        r0 = _sp.run(["codesign", "--verify", "--deep", "--strict", str(app)],
                     capture_output=True, text=True, timeout=60)
        check("剛編出來的 app,章是好的(這是對照組)", r0.returncode == 0, r0.stderr[-200:])
        _sp.run(["plutil", "-replace", "CFBundleIdentifier", "-string", "com.example.probe",
                 str(app / "Contents" / "Info.plist")], capture_output=True, timeout=60)
        r1 = _sp.run(["codesign", "--verify", "--deep", "--strict", str(app)],
                     capture_output=True, text=True, timeout=60)
        check("★改完 Info.plist,章真的會壞★(這條就是本 finding 的現場成立前置)",
              r1.returncode != 0, "改完還是 valid,那前提不成立了:%s" % r1.stderr[-200:])
        _sp.run(["codesign", "-f", "-s", "-", str(app)], capture_output=True, timeout=60)
        r2 = _sp.run(["codesign", "--verify", "--deep", "--strict", str(app)],
                     capture_output=True, text=True, timeout=60)
        check("★重簽之後章又好了★", r2.returncode == 0, r2.stderr[-200:])
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_watchdog_notifier_bundle")


def t_prepush_autoloop_count_is_not_hardcoded():
    """★推送閘印的支數要從實際輸出讀,不准寫死★(2026-09-08)。

    寫死的數字會靜靜地漂:那行訊息印著「自主迴圈那 132 支也綠」,
    而那個檔當時實際有 144 支——閘其實跑整支、沒有少跑,但它報出來的數字錯了。
    這個 repo 對「宣稱 vs 實測」的既有立場是別讓數字靜靜地漂(doctor 的 [E] 段就在做這件事),
    訊息裡的數字同一個道理。

    這條驗兩件:①那段不含寫死的支數 ②真的有一支從輸出取數的函式。
    """
    _need_src("scripts/hooks/pre-push")
    root = Path(GRAPHCTL).resolve().parent.parent
    src = (root / "scripts" / "hooks" / "pre-push").read_text(encoding="utf-8")
    i = src.index("test_autonomous_loop.py")
    seg = src[max(0, i - 400): i + 1400]
    import re as _re
    hard = _re.findall(r"自主迴圈那\s*\d+\s*支", seg)
    check("★推送閘的訊息不准寫死自主迴圈的支數★", not hard,
          "找到寫死的支數 %s——測試檔增減時這個數字不會跟著動" % hard)
    check("★要有一支從實際輸出取支數的函式★", "_autoloop_count" in seg,
          "找不到 _autoloop_count:數字沒有來源就只能是寫死的")
    print("  ✓ t_prepush_autoloop_count_is_not_hardcoded")


def t_directly_invoked_scripts_keep_exec_bit():
    """★會被直接執行的腳本,在 git 索引裡必須帶執行位★(2026-09-08,看門狗真警報抓到的)。

    真的發生了:我用「寫暫存檔再 os.replace 換名」原子改寫 autonomous-loop.sh,
    ★換名會丟 +x★(記憶筆記 2026-09-07 就記過,今天又踩)。git 把 100644 記進索引,
    隔天 09:30 排程的 wrapper 直接呼叫它 → Permission denied → rc=126 →
    看門狗喊「autonomous 那步失敗」。測試沒抓到,因為測試都用 `bash <檔>` 跑、不需要 +x。

    這一支盯的是「誰會被別的腳本或 launchd 直接呼叫」那幾支——判準取自它們真的被怎麼呼叫,
    不是全 repo 所有 .sh 一律要 +x。
    """
    import subprocess as _sp
    _need_src("governance/daily-governance.sh")
    root = Path(GRAPHCTL).resolve().parent.parent
    # 被直接呼叫的:wrapper 本身(launchd 直呼)、它直呼的子腳本、看門狗(launchd 直呼)、安裝器
    must = ["governance/daily-governance.sh", "governance/autonomous-loop.sh",
            "governance/wrapper-watchdog.sh", "governance/install-watchdog.sh",
            "governance/ai-governance-research.sh", "scripts/hooks/pre-push", "scripts/hooks/pre-commit"]
    out = _sp.run(["git", "-C", str(root), "ls-files", "-s"] + must, capture_output=True, text=True).stdout
    modes = {}
    for ln in out.splitlines():
        parts = ln.split()
        if len(parts) >= 4:
            modes[parts[3]] = parts[0]
    for f in must:
        if not (root / f).exists():
            continue
        check("★%s 在索引裡要是 100755★(丟了 +x,launchd/wrapper 直呼會 Permission denied)" % f,
              modes.get(f) == "100755", "索引模式=%s" % modes.get(f))
    print("  ✓ t_directly_invoked_scripts_keep_exec_bit")


def t_daily_wrapper_lock_matches_source():
    """★抄過來的鎖要跟來源保持一致★(2026-09-07 全 repo 審視 #18,設計審 r1 架構席)。

    這個 repo 對「複製同一段邏輯」的既有立場是二選一:機械守衛防漂移,或至少留同源回指註解。
    本案兩個都做——這條是機械那半。

    盯的是這把鎖真正會改的四件事:建目錄取鎖、以「持鎖行程還活著嗎」為主要接管判準、
    pid 空時用鎖齡兜底、量不出鎖齡要讓行。
    ★不比對逐字★(兩支的變數名與訊息本來就不同),比對的是這四個行為都還在。
    """
    _need_src("governance/daily-governance.sh", "governance/autonomous-loop.sh")
    root = Path(GRAPHCTL).resolve().parent.parent
    dst = (root / "governance" / "daily-governance.sh").read_text(encoding="utf-8")
    srcf = (root / "governance" / "autonomous-loop.sh").read_text(encoding="utf-8")
    traits = {
        "建目錄取鎖": "mkdir \"$LOCKDIR\"",
        "看持鎖行程活著沒": "kill -0",
        "pid 空時用鎖齡兜底": "getmtime",
        "量不出鎖齡要讓行": "3600",
        # ★以下五項是 2026-09-07 code-batch19 補的★(架構對齊席 F3:
        # 原本四項只蓋到最基本的,而兩邊真正共用、最容易寫錯的是接管那一段)。
        "身分用啟動時刻不用名字": "lstart",
        "接管走接管權小鎖": ".steal",
        "破接管權也用 mv 不用 rm": "$steal.dead.",
        "接管把舊鎖原子搬走": "$LOCKDIR.dead.",
        "收尾先搬走再確認是不是自己的": "$LOCKDIR.rel.",
    }
    for name, needle in traits.items():
        check("來源那把鎖有「%s」" % name, needle in srcf, needle)
        check("★抄過來的也有「%s」★" % name, needle in dst, needle)
    # ★回指要雙向★(架構對齊席 F2):血緣是雙向的——#18 先在 daily 上修好,
    # code-batch19 再搬回 autonomous-loop.sh,而 batch19 的三席同時修了兩邊。
    # 只有一邊留註解的話,從另一邊進來的人不會知道要一起改。
    for label, text in (("抄過去那份", dst), ("來源那份", srcf)):
        check("★%s要留同源回指註解★" % label,
              ("autonomous-loop.sh" in text or "daily-governance.sh" in text) and "同源" in text,
              "找不到指向另一邊的註解——改了一邊的人不會知道另一邊也要改")
    print("  ✓ t_daily_wrapper_lock_matches_source")


def t_doctor_advisory_sections_do_not_block():
    """★標題寫「提醒,不擋」的段落,不准用會擋的那支★(2026-09-07 當場撞到才補)。

    健檢有兩支報訊息的函式:一支會讓 issue 計數增加(進而在嚴格模式回非零、擋住推送與 CI),
    一支完全不動計數。**[I] 段的標題寫著「提醒,不擋」,兩個分支卻都用了會擋的那支**,
    而其中一支的訊息自己寫著「未達裁決門檻」——說門檻沒到卻把人擋下來。
    當天它真的擋住了一次正常的推送,而且因為標題和意圖都是對的,查了五段才查到是它。

    ★這條驗的是「標題與行為一致」這個結構性質,不是某一段的內容★:
    掃所有標題含「不擋」的段落,底下不准出現會擋的那支。
    **例外要明寫**:[I] 段刻意保留一支會擋的——那是「轉硬擋條件已達」的升級路徑,
    是這個機制設計上就要擋的地方,不是誤用。
    """
    import re as _re
    root = Path(GRAPHCTL).resolve().parent.parent
    src = (root / "scripts" / "lumos").read_text(encoding="utf-8")
    # ★先把註解剝掉再數★:第一版直接掃原始碼,結果把下一段前言註解裡的
    # 「errs→warn(hard)計 issues」當成真的呼叫,對 [N] 段誤報一次。
    # 註解在講「哪一支會擋」是這個檔案的常態,不剝就一定假紅。
    src = "\n".join(_re.sub(r"#.*$", "", ln) for ln in src.split("\n"))
    secs = [(m.group(1), m.group(2), m.start()) for m in
            _re.finditer(r'section\("([^"]+)",\s*"([^"]*)"', src)]
    check("健檢的段落抓得到(≥15 段)", len(secs) >= 15, str(len(secs)))
    # 這一段刻意保留一支會擋的:缺席迴圈出過 blocker 時的升級路徑
    allowed_hard = {"I": "轉硬擋條件已達"}
    bad = []
    for i, (sid, title, pos) in enumerate(secs):
        if "不擋" not in title:
            continue
        end = secs[i + 1][2] if i + 1 < len(secs) else pos + 6000
        seg = src[pos:end]
        hard = len(_re.findall(r"(?<![_\w])warn\(", seg))
        if not hard:
            continue
        marker = allowed_hard.get(sid)
        if marker and marker in seg and hard == 1:
            continue          # 例外:只准一支,而且要帶那句明示升級的字樣
        bad.append("%s(%s):會擋的那支出現 %d 次" % (sid, title[:24], hard))
    check("★標題寫「不擋」的段落沒有在偷偷擋人★", not bad,
          "；".join(bad) + "  —— 用不擋的那支,或把標題改成誠實的")
    # 反面:例外那一支要真的還在(不能修過頭把該擋的也拿掉)
    i = src.find('section("I"')
    seg = src[i:i + 4600]   # 已剝註解
    j = seg.find('section("', 10)
    seg = seg[:j] if j > 0 else seg
    check("★[I] 段「轉硬擋條件已達」那支仍然會擋★",
          "轉硬擋條件已達" in seg and len(_re.findall(r"(?<![_\w])warn\(", seg)) == 1, seg[-400:])
    print("  ✓ t_doctor_advisory_sections_do_not_block")


def t_loop_close_kinds_classified():
    """★新增一種收工事件卻忘了歸類,這裡要翻紅★(2026-09-07 代碼審 r1,兩席獨立指出)。

    `loop list` 靠一張人工維護的「哪些事件算關門」表。原本沒有任何守衛:
    以後有人加一種新的收斂事件,那支只會**安靜地**繼續把它判成「沒關門」,
    清單長期有雜訊,最後被當成「這工具不準」而被忽略。

    同型前例就在隔壁:治理帳的閘名有一張 `_KNOWN_GATES` 表,而它**有**專門的漂移守衛。
    這條補上同一道:治理帳裡出現過的每一組 (閘, 種類),只要屬於審查迴圈那兩個閘,
    就必須在「算關門」或「明確不算關門」兩張表裡的其中一張。

    ★判準取自真實帳,不是寫死清單★——所以新增一種 kind、帳上一出現,這條就會紅。
    """
    import json as _j
    _need_src("docs/lumos-toolchain-knowledge")
    m = _load_lumos()
    repo = Path(GRAPHCTL).resolve().parent.parent
    path = repo / "docs" / ".governance-log.jsonl"
    if not path.exists():
        raise _SrcOnly("這個 repo 沒有治理帳,這段沒驗到")
    seen = set()
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            d = _j.loads(line)
        except ValueError:
            continue
        if not isinstance(d, dict):
            continue
        if d.get("gate") in ("design-loop", "code-loop"):
            seen.add((d.get("gate"), d.get("kind")))
    check("治理帳裡撈得到審查迴圈的事件種類", len(seen) >= 4, str(sorted(seen)))
    classified = (set(m.LOOP_CLOSE_EVENTS) | set(m.LOOP_CLOSE_EVENTS_BY_DETAIL)
                  | set(m.LOOP_NOT_CLOSE_EVENTS))
    unclassified = sorted(seen - classified)
    check("★每一種審查迴圈事件都被歸類過(算關門 / 明確不算)★", not unclassified,
          "沒歸類的: %s —— 新增了一種收工事件就要決定它算不算關門,"
          "放著不管的話 loop list 會安靜地把它當成沒關門" % unclassified)
    # 反面:表裡列的種類也不該是憑空想像的(全部都要在真實帳上出現過)
    listed = set(m.LOOP_CLOSE_EVENTS) | set(m.LOOP_CLOSE_EVENTS_BY_DETAIL)
    ghost = sorted(k for k in listed if k not in seen)
    check("表裡列的關門種類都真的在帳上出現過(不是憑空想的)", not ghost,
          "帳上從沒出現過: %s" % ghost)
    print("  ✓ t_loop_close_kinds_classified")


def t_loop_list_open_loops():
    """`lumos loop list`:列出帳面上還沒關門的審查迴圈(執行DAG_調研 排第一順位的缺口——
    loop next/status/verify-progress 全都強制要 loop_id,而沒有任何入口能先知道有哪些編號在飛,
    實務上只能 tail .canary-log.jsonl 或看 git 未追蹤檔)。

    關門訊號=治理帳 .governance-log.jsonl 的放行事件(design-loop converged/cap-reached/rewrite、
    code-loop passed/skipped),nodes 帶迴圈編號;開著=沒有關門事件、或關門後又記了新的審查輪次。
    ★誠實界線★:關門事件的慣例 2026-08-22 才開始,更早的迴圈天生沒有這筆——所以「沒關門」
    只等於「帳面沒看到關門事件」,不等於「沒做完」,輸出必須自己講明。唯讀恆 rc0(比照 canary-stats)。"""
    import json as _j
    import shutil
    root = Path(tempfile.mkdtemp(prefix="gctl-looplist-"))
    vault = root / "docs" / "kg"
    (vault / "MOC").mkdir(parents=True)
    (vault / "MOC" / "i.md").write_bytes("---\ntype: moc\n---\n# i\n".encode("utf-8"))
    can = root / "docs" / ".canary-log.jsonl"
    gov = root / "docs" / ".governance-log.jsonl"

    def rec(loop, ts, rnd="r1", sev="minor"):
        with open(can, "a", encoding="utf-8") as f:
            f.write(_j.dumps({"ts": ts, "kind": "caught", "token": "x", "loop": loop,
                              "round": rnd, "severity": sev, "auditor": "s1"}) + "\n")

    def close(loop, ts, gate="design-loop", kind="converged"):
        """設計審那組的關門事件:編號寫在 nodes 欄(跟真寫入端 _loop_gov_mark 同形)。"""
        with open(gov, "a", encoding="utf-8") as f:
            f.write(_j.dumps({"ts": ts, "commit": "abc", "gate": gate, "kind": kind,
                              "hard": False, "nodes": [loop], "note": "t"}) + "\n")

    def close_codeloop(loop, ts, kind="passed"):
        """★code-loop 那組:nodes 永遠是空的,編號只在自由文字 detail 裡★
        (2026-09-07 代碼審 r1,三席獨立抓到)。

        第一版的 fixture 對 code-loop 也塞 `nodes: [loop]`——**那個形狀現實中不存在**,
        真寫入端 `_codeloop_gov_log` 把 nodes 寫死成 []。於是測試綠、功能死:
        實測 23 個早就過閘的 code 迴圈被報成「空轉候選」。
        這裡照真寫入端的形狀寫,才驗得到那條路。"""
        with open(gov, "a", encoding="utf-8") as f:
            f.write(_j.dumps({"ts": ts, "commit": "abc", "gate": "code-loop", "kind": kind,
                              "hard": False, "nodes": [], "note": "",
                              "detail": "%s r1 收斂:5 findings 全折" % loop,
                              "branch": "main", "head_sha": "deadbeef"}) + "\n")

    try:
        # 空帳也要 rc0,不能因為沒東西就報錯
        r = run(vault, "loop", "list")
        check("空帳 rc0", r.returncode == 0, r.stderr)

        rec("still-open", "2026-09-06T10:00:00+08:00")
        rec("already-closed", "2026-09-05T10:00:00+08:00")
        close("already-closed", "2026-09-05T11:00:00+08:00")
        rec("reopened", "2026-09-04T10:00:00+08:00")
        close("reopened", "2026-09-04T11:00:00+08:00")
        rec("reopened", "2026-09-06T12:00:00+08:00", rnd="r2")      # 關門後又開新輪
        rec("long-idle", "2026-07-01T10:00:00+08:00")               # 沒關門但很久沒動
        close_codeloop("code-closed", "2026-09-05T11:00:00+08:00")
        rec("code-closed", "2026-09-05T10:00:00+08:00")
        # ★過閘之後才補記帳是常態,不算重開★(2026-09-07 代碼審 r1 折入時實測發現):
        # code-234 唯一那筆審查記錄比過閘晚 8 分鐘、code-kill 晚 14 分鐘,兩個都是同一次工作的
        # 收尾簿記,第一版卻判成「又開新輪」而永遠列在空轉候選裡。
        close_codeloop("code-late-bookkeeping", "2026-09-05T11:00:00+08:00")
        rec("code-late-bookkeeping", "2026-09-05T11:08:00+08:00")

        r = run(vault, "loop", "list", "--json", "--now", "2026-09-07")
        check("loop list rc0", r.returncode == 0, r.stderr)
        d = _j.loads(r.stdout)
        ids = [x["loop"] for x in d["open"]]
        check("列出還沒關門的", "still-open" in ids, r.stdout)
        check("已關門的不列", "already-closed" not in ids, r.stdout)
        check("★code-loop 的放行事件同樣算關門★", "code-closed" not in ids, r.stdout)
        check("★關門後隔天以上又記帳=重新算開著★", "reopened" in ids, r.stdout)
        check("★過閘後幾分鐘內的收尾簿記不算重開★", "code-late-bookkeeping" not in ids, r.stdout)
        check("久沒動的不進預設清單(進 stale)", "long-idle" not in ids
              and "long-idle" in [x["loop"] for x in d["stale"]], r.stdout)

        one = next(x for x in d["open"] if x["loop"] == "still-open")
        check("每筆帶最後活動日與距今天數", one["last_ts"][:10] == "2026-09-06" and one["idle_days"] == 1, r.stdout)
        check("每筆帶輪數", next(x for x in d["open"] if x["loop"] == "reopened")["rounds"] == 2, r.stdout)

        # --days 調門檻:放寬到 999 天,久沒動的要回到 open
        r = run(vault, "loop", "list", "--json", "--days", "999", "--now", "2026-09-07")
        check("--days 放寬後久沒動的回到 open",
              "long-idle" in [x["loop"] for x in _j.loads(r.stdout)["open"]], r.stdout)

        # 人讀輸出:必須自己講明「沒關門 ≠ 沒做完」,並給下一步指令
        r = run(vault, "loop", "list", "--now", "2026-09-07")
        check("★人讀輸出要講明誠實界線★", "不等於" in r.stdout and "2026-08-22" in r.stdout, r.stdout)
        check("下一步指令要印出來", "loop next" in r.stdout, r.stdout)

        # --exclude:通用前綴排除(自主迴圈每日場次天生不關門、一天長一個,會淹掉清單)
        rec("auto-2026-09-06", "2026-09-06T09:00:00+08:00")
        r = run(vault, "loop", "list", "--json", "--exclude", "auto-", "--now", "2026-09-07")
        d = _j.loads(r.stdout)
        check("--exclude 排掉指定前綴", "auto-2026-09-06" not in [x["loop"] for x in d["open"]]
              and "still-open" in [x["loop"] for x in d["open"]], r.stdout)

        # ★時區安全★:兩本帳今天都寫 +08:00,字串比對剛好會對;換一台機器寫 UTC 就會靜默判錯。
        # 這組把它釘死:關門事件是 03:00Z(=11:00+08:00,真實時間晚於審查那筆 10:00+08:00),
        # 但字串上 "…T03" < "…T10" —— 只比字串會誤判成「還開著」。
        rec("tz-mixed", "2026-09-06T10:00:00+08:00")
        close("tz-mixed", "2026-09-06T03:00:00+00:00")
        r = run(vault, "loop", "list", "--json", "--now", "2026-09-07")
        check("★跨時區的關門事件要判得出來(不能只比字串)★",
              "tz-mixed" not in [x["loop"] for x in _j.loads(r.stdout)["open"]], r.stdout)

        # --now 壞輸入:給人話,不要吐堆疊
        r = run(vault, "loop", "list", "--now", "上禮拜")
        check("--now 壞輸入 rc2", r.returncode == 2, str(r.returncode) + r.stderr)
        check("--now 壞輸入給人話不吐堆疊",
              "擋下" in r.stderr and "Traceback" not in r.stderr, r.stderr)

        # 壞行:跳過但要出聲,仍 rc0(唯讀查詢不 fail-closed,但不准靜默)
        with open(can, "a", encoding="utf-8") as f:
            f.write("{壞掉的行\n")
        r = run(vault, "loop", "list", "--now", "2026-09-07")
        check("壞行仍 rc0", r.returncode == 0, r.stderr)
        check("★壞行不得靜默★", "讀不動" in r.stderr or "跳過" in r.stderr, r.stderr)
    finally:
        shutil.rmtree(root, ignore_errors=True)


