_HOOK_PURE_PROBE = r'''
import importlib.util as u, sys, os, json, sysconfig
hook = os.path.realpath(sys.argv[1])
paths = sysconfig.get_paths()
# r3 外家 #7:只准標準庫本體(stdlib / platstdlib),不准 site-packages、不准整個 Python 安裝目錄;
# 路徑先 realpath 再用 commonpath 驗目錄邊界(startswith 會把 /lib/python3.14-foo 也放行)
std = set()
for s in (paths.get("stdlib"), paths.get("platstdlib")):
    if s:
        std.add(os.path.realpath(s))
def under_std(p):
    p = os.path.realpath(str(p))
    for s in std:
        try:
            if os.path.commonpath([p, s]) == s:
                return True
        except ValueError:
            pass
    return False
def is_write(mode, flags):
    # r3 外家 #6:os.open 走的是 (path, None, flags),mode 為 None、寫入意圖在 flags 裡;io.open 的 mode 是字串
    if mode is not None and any(c in str(mode) for c in "wax+"):
        return True
    try:
        f = int(flags)
    except (TypeError, ValueError):
        return mode is None   # 兩邊都看不懂=看不出是不是寫,保守算違規
    return (f & os.O_ACCMODE) != os.O_RDONLY or bool(f & (os.O_CREAT | os.O_TRUNC | os.O_APPEND))
DENY = ("subprocess.", "os.system", "os.exec", "os.spawn", "os.fork", "os.posix_spawn", "os.kill", "os.putenv", "os.unsetenv",
        "os.chdir", "os.remove", "os.unlink", "os.rename", "os.mkdir", "os.rmdir", "os.chmod", "os.chown", "os.link", "os.symlink",
        "os.truncate", "os.utime", "shutil.", "socket.", "http.", "urllib.", "ftplib.", "smtplib.", "poplib.", "imaplib.",
        "webbrowser.", "ctypes.", "tempfile.", "pty.", "signal.", "sys.setprofile", "sys.settrace", "glob.", "mmap.", "sqlite3.")
bad = []
_depth = [0]   # 檢查深度:稽核鉤子與 stat 包裝在做路徑判定時自己也會 lstat/realpath,深度>0 的呼叫一律放行不記
def audit(ev, args):
    _depth[0] += 1
    try:
        _audit_inner(ev, args)
    finally:
        _depth[0] -= 1
def _audit_inner(ev, args):
    if ev == "open":
        path = args[0] if len(args) > 0 else ""
        mode = args[1] if len(args) > 1 else None
        flags = args[2] if len(args) > 2 else 0
        if not isinstance(path, (str, bytes, os.PathLike)):   # 用 fd 開的看不出目標,保守算違規
            bad.append([ev, repr(path), repr(mode)]); return
        p = os.path.realpath(os.fsdecode(path))
        own_cache = os.path.join(os.path.dirname(hook), "__pycache__")   # Python 匯入系統讀 hook 自己的快取,不是 hook 的動作
        in_own_cache = os.path.commonpath([p, own_cache]) == own_cache if p.startswith(os.path.dirname(hook)) else False
        if is_write(mode, flags) or not (p == hook or in_own_cache or under_std(p)):
            bad.append([ev, p, repr(mode), int(flags) if isinstance(flags, int) else repr(flags)])
    elif ev in ("os.listdir", "os.scandir"):
        p = str(args[0]) if args and args[0] is not None else "."
        if not under_std(os.path.realpath(p)):
            bad.append([ev, p])
    elif ev.startswith(DENY):
        bad.append([ev, str(args)[:120]])
sys.addaudithook(audit)
# r4 外家 #8:stat 家族在 CPython 沒有稽核事件(os.stat("/etc/passwd") 零事件),匯入期間把它們包起來套同一套路徑政策。
# 只包 os 模組的名字:importlib 自己走 posix 模組的原函式,不受影響;hook 裡 os.stat / os.path.exists / pathlib 都會經過這裡。
def _wrap_pathfn(name):
    orig = getattr(os, name)
    def wrapped(path, *a, **kw):
        if _depth[0] == 0:   # 政策檢查裡的 realpath 自己會呼叫 os.lstat,深度>0 就放行,不然無限遞迴
            _depth[0] += 1
            try:
                if isinstance(path, (str, bytes, os.PathLike)):
                    p = os.path.realpath(os.fsdecode(path))
                    if not (p == hook or under_std(p)):
                        bad.append(["os." + name, p])
                else:
                    bad.append(["os." + name, repr(path)])
            finally:
                _depth[0] -= 1
        return orig(path, *a, **kw)
    setattr(os, name, wrapped)
for _n in ("stat", "lstat", "access", "readlink", "statvfs"):
    if hasattr(os, _n):
        _wrap_pathfn(_n)
s = u.spec_from_file_location("h", hook); m = u.module_from_spec(s); s.loader.exec_module(m)
assert callable(m.collect_turn_actions) and callable(m._is_real_user_input)
sys.stdout.write("AUDIT:" + json.dumps(bad, ensure_ascii=False))
'''


def t_handoff_hook_import_is_pure():
    """r1 外家 #5:`lumos handoff` 用 importlib 匯入收工 hook 檔,等於執行它的頂層碼——唯讀查詢不該有副作用。
    不搬 hook(範圍刀:不動 hook),改用這條鎖住「匯入不產生任何外部動作」。
    ★r2 外家:只看印字與 tmp 留檔鎖不住開程序 / 連網 / 讀別的檔 / 寫 tmp 外的路徑★ → 改用 Python 稽核鉤子
    (sys.addaudithook)全程監看匯入:open 只准讀 hook 自己的原始碼與標準庫本體(stdlib/platstdlib,realpath+commonpath 驗邊界;
    site-packages 與 Python 安裝目錄其他部分都不算——r3 外家 #7);寫入意圖同時看 mode 字串與 os.open 的數字 flags(r3 外家 #6);
    listdir/scandir 只准標準庫;stat/lstat/access/readlink/statvfs(沒有稽核事件,r4 外家 #8)在匯入期間包起來套同一套政策;
    子程序、socket、http/urllib、shutil、os 的改檔系統呼叫、ctypes、tempfile、signal、glob… 一律違規。
    另外 stdout/stderr 必須乾淨(hook 印字會污染 handoff 的 JSON 輸出)、tmp 不得留檔。
    PYTHONDONTWRITEBYTECODE=1 是關掉 Python 自己寫 __pycache__,那不是 hook 的動作。
    ★宣稱的精確範圍★:鎖的是「寫/建/刪/改權限任何檔、開子程序、開 socket、讀 hook 與標準庫以外的檔案內容 / 目錄清單 / 中繼資料」。
    ★明寫的殘餘面(不在鎖內)★:讀程序自身狀態(os.getcwd / os.environ / os.getpid / time)、經 posix 模組直呼原函式
    (posix.stat 不經 os 名字)、以及 CPython 其他沒有稽核事件又不經 os 模組名字的讀取原語。要縮這個面得改 hook 檔或
    換成不執行 hook,兩者都在範圍刀外;殘餘面是否可接受歸人裁(2026-09-07 r4 後攤給 Enzo)。
    翻紅釘:hook 頂層塞 print / subprocess.run / open 別的檔 / socket.socket / 寫檔 / listdir / os.open(O_WRONLY) 自己 /
    讀 sys.executable 各一種,這條都要紅。"""
    import json as _j
    import os as _os
    import shutil
    import subprocess as _sp
    tmp = Path(tempfile.mkdtemp(prefix="gctl-hookpure-"))
    hook = Path(GRAPHCTL).resolve().parent / "hooks" / "claude" / "check-graph-sync.py"
    try:
        r = _sp.run([sys.executable, "-c", _HOOK_PURE_PROBE, str(hook)], cwd=str(tmp),
                    env=dict(_os.environ, HOME=str(tmp), PYTHONDONTWRITEBYTECODE="1"),
                    capture_output=True, text=True)
        check("匯入 hook 不炸,且匯出接手視圖要用的兩個名字", r.returncode == 0, r.stderr[-400:])
        check("★匯入 hook 不印任何東西(stdout 只有探針自己的稽核結果、stderr 空)★",
              r.stdout.startswith("AUDIT:") and r.stderr == "", repr((r.stdout[:200], r.stderr[:200])))
        try:
            events = _j.loads(r.stdout[len("AUDIT:"):]) if r.stdout.startswith("AUDIT:") else ["(探針輸出被污染)"]
        except ValueError:
            events = ["(探針輸出不是 JSON)"]
        check("★匯入 hook 沒有鎖內的外部動作:不開程序、不連網、不改檔系統、不讀 hook 與標準庫以外的檔案內容 / 目錄清單 / 中繼資料★",
              events == [], str(events)[:400])
        leftover = [str(p.relative_to(tmp)) for p in tmp.rglob("*")]
        check("匯入 hook 不在 cwd / HOME 留任何檔", leftover == [], str(leftover))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


# ── 棧別提問表態閘(Projects/棧別提問表態閘_計劃,2026-09-09)────────────────────────────────
def _disp_repo(d, kt_body=None, config=None, with_issue=True):
    """建一個 main + feat 分支的 repo:feat 加一支 .kt(預設含 viewModelScope.launch → kt-coroutines 適用,
    註解裡的 GlobalScope 不算),tier standard(沒有 python 形狀的 regex 命中)。config=None → python profile + tests/。"""
    import json as _j, subprocess as _sp
    g = lambda *a: _sp.run(["git", *a], cwd=d, capture_output=True, text=True)
    g("init", "-q", "-b", "main"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
    P = Path(d)
    (P / "README.md").write_text("init\n", encoding="utf-8")
    (P / ".lumos").mkdir()
    cfg = config if config is not None else {"test_profile": "python", "test": {"method_regex": "(?m)^def (test_[A-Za-z0-9_]+)\\s*\\(", "run_cmd": "true"}}
    (P / ".lumos" / "config.json").write_text(_j.dumps(cfg), encoding="utf-8")
    (P / "tests").mkdir()
    (P / "tests" / "test_flow.py").write_text("def test_scope_cancel():\n    assert True\n", encoding="utf-8")
    (P / "docs" / "x-knowledge" / "Issues").mkdir(parents=True)
    if with_issue:
        (P / "docs" / "x-knowledge" / "Issues" / "待補協程scope.md").write_text(
            "---\ntype: issue\nstatus: open\ncreated: 2026-09-09\nsummary: |-\n  KEY:x\n---\n# 待補\n", encoding="utf-8")
        (P / "docs" / "x-knowledge" / "Issues" / "已結案.md").write_text(
            "---\ntype: issue\nstatus: resolved\ncreated: 2026-09-09\nsummary: |-\n  KEY:x\n---\n# 已結案\n", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "init")
    g("checkout", "-q", "-b", "feat/disp")
    (P / "app").mkdir()
    body = kt_body if kt_body is not None else (
        "class VM : ViewModel() {\n"
        "    // TODO remove GlobalScope later\n"
        "    fun load() { viewModelScope.launch { repo.fetch() } }\n"
        "}\n")
    (P / "app" / "Screen.kt").write_text(body, encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "kt change")
    return _sp.run(["git", "rev-parse", "HEAD"], cwd=d, capture_output=True, text=True).stdout.strip()


def _disp_run(args, cwd=None):
    import subprocess as _sp
    return _sp.run([sys.executable, GRAPHCTL, *args], capture_output=True, text=True, cwd=cwd)


def t_stack_questions_kotlin_spring_triggers():
    """[後端工程提問與證據擴充 S4] Kotlin 寫 Spring 後端時,交易/資料存取與外呼的寫法要觸發 kt 的後端題;
    只出現 Android 寫法(Room 的 @Entity/@Query("SELECT…")、Retrofit、Compose)不觸發新加的兩題。翻紅釘:拿掉這兩題 → ①② 翻紅。"""
    m = _load_lumos_inproc()
    def hits(lines):
        app, meta = m._stack_applicability({"kt": lines}, 300)
        return {x["id"] for x in meta.get("kt", []) if x["applicable"]}
    spring_data = ['@Transactional', 'fun place(cmd: PlaceOrder) {', 'interface OrderRepo : JpaRepository<Order, Long>',
                   'jdbcTemplate.update("update stock set qty = qty - 1 where id = ?", id)']
    check("① Spring 交易與資料存取寫法觸發 kt-springdata", "kt-springdata" in hits(spring_data), str(hits(spring_data)))
    spring_ext = ['val body = webClient.get().uri("/stock").retrieve()', 'private val rest = RestTemplate()']
    check("② Spring 外呼寫法觸發 kt-springhttp", "kt-springhttp" in hits(spring_ext), str(hits(spring_ext)))
    android = ['@Entity(tableName = "orders")', '@Query("SELECT * FROM orders")', 'val api = Retrofit.Builder().build()',
               '@Composable fun Screen() {}']
    h = hits(android)
    check("③ Android 寫法不觸發新加的兩題", "kt-springdata" not in h and "kt-springhttp" not in h, str(h))
    big = hits(["val x = 1"] * 400)
    check("④ 超過行數門檻也不因門檻而亮(shape_only)", "kt-springdata" not in big and "kt-springhttp" not in big and "kt-coroutines" in big, str(big))
    # 代碼審 r1 邊界席、通才席:Android 自訂類名與通用字誤觸發、Spring 的其他寫法漏觸發
    for line in ('class AppWebClient : WebViewClient() {', 'class RestClient(private val api: Api) {', 'val c = MyRestClient()',
                 'val webClient = MyWebViewClient()', 'val c: DatabaseClient = get()', '@Lock("x") fun f() {}'):
        h = hits([line])
        check(f"⑤ Android 自訂寫法不觸發:{line}", "kt-springdata" not in h and "kt-springhttp" not in h, str(h))
    for line, qid in (('@get:Transactional', "kt-springdata"), ('val rows = jdbcClient.sql("select 1").query()', "kt-springdata"),
                      ('private val jdbc: JdbcClient', "kt-springdata"), ('private val mongo: MongoTemplate', "kt-springdata"),
                      ('@Lock(LockModeType.PESSIMISTIC_WRITE)', "kt-springdata"), ('val db = DatabaseClient.create(factory)', "kt-springdata"),
                      ('val client = RestClient.builder().build()', "kt-springhttp"), ('@HttpExchange("/stock")', "kt-springhttp"),
                      ('private val webClient: WebClient', "kt-springhttp"), ('import org.springframework.web.client.RestClient', "kt-springhttp")):
        check(f"⑥ Spring 寫法要觸發 {qid}:{line}", qid in hits([line]), str(hits([line])))
    # 代碼審 r2 邊界席、正確性席:diff 常常只改呼叫行、宣告不在 diff 裡;小寫變數的 Spring 用戶端呼叫要亮(② 原本靠同一份裡的 RestTemplate() 才綠)
    for line, qid in (('val body = webClient.get().uri("/stock").retrieve()', "kt-springhttp"),
                      ('val r = restTemplate.exchange(url, HttpMethod.POST, entity, String::class.java)', "kt-springhttp"),
                      ('val res = restClient.get().uri("/x").retrieve().body<String>()', "kt-springhttp"),
                      ('restTemplate.getForObject(url, String::class.java)', "kt-springhttp"),
                      ('val rows = databaseClient.sql("select * from t").fetch().all()', "kt-springdata"),
                      # 代碼審 r3 通才席:變數名帶前綴、this. 開頭、安全呼叫、清單外的方法
                      ('val r = paymentWebClient.get().uri("/x").retrieve()', "kt-springhttp"),
                      ('stockRestTemplate.exchange(url, HttpMethod.GET, null, String::class.java)', "kt-springhttp"),
                      ('this.restTemplate.postForLocation(url, body)', "kt-springhttp"),
                      ('restTemplate?.exchange(url, HttpMethod.GET, null, String::class.java)', "kt-springhttp"),
                      ('orderDatabaseClient.sql("select 1").fetch().all()', "kt-springdata")):
        check(f"⑦ 只有呼叫行也要觸發 {qid}:{line}", qid in hits([line]), str(hits([line])))
    for line in ('webView.webViewClient = MyWebViewClient()', 'webClient.onPageFinished(view, url)', 'val webClient = AppWebClient()'):
        h = hits([line])
        check(f"⑧ Android WebView 寫法不觸發:{line}", "kt-springhttp" not in h, str(h))


def t_stack_question_triggers():
    """[表態閘 S2]每題有唯一 id 與非空 when、id 集合釘住(改 id=刻意動作,r3 正確性席 C1);
    比對對增行與刪行、剝字串、跳註解行;stack_questions 語意不變、另有 applicable/meta;依賴有 vue 的前端 .ts 歸 vue
    (只有 react 家族的歸 react,見 t_react_stack_key_from_package_json)。
    翻紅釘:拔掉 _stack_norm_line 的註解跳過 → ③翻紅;把 changed_lines 只收 + 行 → ⑥「純刪除 diff 也觸發」翻紅(r1 合約測試席 f5 訂正編號)。"""
    import json as _j
    m = _load_lumos_inproc()
    ids = [s["id"] for v in m._STACK_QUESTION_SPECS.values() for s in v]
    check("①每題 id 唯一且 when 非空(regex 已在載入時編譯)", len(ids) == len(set(ids)) and all(s["when"] for v in m._STACK_QUESTION_SPECS.values() for s in v), str(ids))
    check("①id 集合釘住(改 id 要來改這條測試——改語意才換 id 的紀律靠這裡逼)",
          set(ids) == {"kt-compose", "kt-coroutines", "kt-dispatchers", "kt-flow", "kt-collections", "kt-leaks", "kt-startup",
                       "kt-springdata", "kt-springhttp",   # 2026-10-12 Kotlin 寫 Spring 後端(後端工程提問與證據擴充 S4)
                       "cs-async", "cs-data", "cs-cache", "cs-linq", "cs-connection",
                       "vue-parallel", "vue-lcp", "vue-bundle", "vue-watch", "vue-reactive",
                       # 2026-10-15 React 補棧(Projects/前端框架從vue分出_計劃 d1)
                       "react-effect", "react-race", "react-render", "react-key", "react-strict", "react-bundle", "react-parallel",
                       "sql-nplus1", "sql-index", "sql-transaction", "sql-sargable",
                       "swift-main", "swift-swiftui", "swift-leaks", "swift-startup", "swift-concurrency", "swift-energy",
                       "node-eventloop", "node-parallel", "node-data", "node-external", "node-memory",
                       "py-eventloop", "py-parallel", "py-external", "py-memory", "py-hotpath",
                       "java-concurrency", "java-resources", "java-data", "java-external", "java-memory",
                       "java-collections", "java-android",
                       "dart-build", "dart-list", "dart-dispose", "dart-async", "dart-isolate", "dart-platform",
                       # 外部回應碼(2026-10-03 Projects/外部回應碼語意要有出處_計劃):sql 以外八棧各一題
                       "kt-extcode", "cs-extcode", "vue-extcode", "react-extcode", "swift-extcode", "node-extcode", "py-extcode",
                       "java-extcode", "dart-extcode",
                       # 本機基礎設施腳本(2026-10-15 Projects/前端知識與風險詞_計劃 做法 6)
                       "infra-shared", "infra-timeout", "infra-signal", "infra-pid", "infra-path", "infra-portable"}, str(sorted(ids)))
    # [外部回應碼 S5]命中樣本亮 extcode、不命中不亮;超過行數門檻不因門檻而亮;不進舊語意整組清單
    _xa, _xm = m._stack_applicability({"py": ['if resp_code == "2000":']}, 300)
    _xb, _xmb = m._stack_applicability({"py": ['if year == "2026":']}, 300)
    _xc, _xmc = m._stack_applicability({"kt": ["val x = 1"] * 400}, 300)
    _g = lambda mm, stk: {r["id"] for r in mm.get(stk, []) if r["applicable"]}
    check("S5 命中樣本亮 py-extcode、不命中樣本不亮", "py-extcode" in _g(_xm, "py") and "py-extcode" not in _g(_xmb, "py"), f"{_g(_xm,'py')} {_g(_xmb,'py')}")
    check("S5 超過行數門檻:其他題全表適用,kt-extcode 不因門檻而亮", "kt-extcode" not in _g(_xmc, "kt") and "kt-coroutines" in _g(_xmc, "kt"), str(_g(_xmc, "kt")))
    check("S5 extcode 不進舊語意整組清單(_STACK_PERF_QUESTIONS)", all(m._EXTCODE_Q not in v for v in m._STACK_PERF_QUESTIONS.values()), "")
    import re as _re
    check("①id 格式 ^[a-z]+-[a-z0-9]+$(r3 邊界席 B10)", all(_re.fullmatch(r"[a-z]+-[a-z0-9]+", i) for i in ids), str([i for i in ids if not _re.fullmatch(r"[a-z]+-[a-z0-9]+", i)]))
    app, meta = m._stack_applicability({"kt": ["    fun load() { viewModelScope.launch { repo.fetch() } }"]}, 300)
    got = {r["id"] for r in meta["kt"] if r["applicable"]}
    check("②命中樣本:viewModelScope.launch → kt-coroutines 適用、kt-compose 不適用", "kt-coroutines" in got and "kt-compose" not in got, str(got))
    app2, meta2 = m._stack_applicability({"kt": ["    // TODO remove GlobalScope later", "    val s = \"GlobalScope\""]}, 300)
    check("③註解行與字串字面裡的觸發詞不算", not app2, str(app2))
    app_ic, _ = m._stack_applicability({"kt": ["val n = 1 // TODO GlobalScope 之後拿掉", "val s = 2 /* viewModelScope.launch */"]}, 300)
    check("③行尾註解裡的觸發詞也不算(r1 外家備援席 f2)", not app_ic, str(app_ic))
    # 五棧各一題命中/不命中(r1 合約測試席 f4:原本只有 kt 有直接樣本)
    _samples = {"cs": ("cs-async", "var x = await svc.GetAsync(ct);", "var y = svc.Get();"),
                "sql": ("sql-index", "SELECT id FROM t WHERE a = 1", "INSERT INTO t VALUES (1)"),
                "swift": ("swift-swiftui", "struct V: View { var body: some View { Text(\"x\") } }", "let n = 3"),
                "node": ("node-parallel", "const r = await Promise.all(items.map(fetchOne))", "const r = items.map(f)"),
                "vue": ("vue-lcp", "<img src=\"a.png\" loading=\"lazy\">", "<div class=\"x\"></div>"),
                "py": ("py-parallel", "results = await asyncio.gather(*tasks)", "total = price * qty"),
                "java": ("java-concurrency", "CompletableFuture.allOf(a, b).join();", "int total = price * qty;"),
                "dart": ("dart-async", "final res = await http.get(uri);", "final total = price * qty;")}
    for _stk, (_qid, _hit, _miss) in _samples.items():
        _a1, _m1 = m._stack_applicability({_stk: [_hit]}, 300)
        _a2, _m2 = m._stack_applicability({_stk: [_miss]}, 300)
        _got1 = {r["id"] for r in _m1[_stk] if r["applicable"]}
        _got2 = {r["id"] for r in _m2[_stk] if r["applicable"]}
        check(f"③{_stk}:命中樣本觸發 {_qid}、不命中樣本零觸發", _qid in _got1 and not _got2, f"hit={_got1} miss={_got2}")
    # 反面詞(2026-09-09 Enzo:用爛的方法寫同一個功能要亮同一題,不能不亮):各棧舊法樣本亮的是「同一題」,乾淨舊法樣本零觸發
    _legacy = {
        "kt": [("kt-coroutines", "Thread { Thread.sleep(500) }.start()"), ("kt-compose", "val v = findViewById<TextView>(R.id.t)"), (None, "val n = list.size")],
        "cs": [("cs-async", "Thread.Sleep(1000);"), ("cs-data", 'using var cmd = new SqlCommand("SELECT * FROM t", conn);'), ("cs-connection", "conn.Open();"), (None, "var x = 1;")],
        "vue": [("vue-parallel", "this.$http.get('/api/list')"), ("vue-reactive", "data() { return { list: [] } }"), (None, "const a = 1")],
        "sql": [("sql-nplus1", "DECLARE c CURSOR FOR SELECT id FROM t"), ("sql-sargable", "WHERE YEAR(created_at) = 2026"), (None, "INSERT INTO t VALUES (1)")],
        "swift": [("swift-main", "DispatchQueue.global().async { load() }"), ("swift-swiftui", "func tableView(_ t: UITableView, cellForRowAt i: IndexPath) -> UITableViewCell {"), (None, "let n = 3")],
        "node": [("node-eventloop", "const cp = require('child_process')"), ("node-data", 'db.query("SELECT * FROM t", cb)'), (None, "const r = items.map(f)")],
        "py": [("py-eventloop", "time.sleep(1)"), ("py-external", "resp = urllib.request.urlopen(url)"),
               ("py-memory", "rows = cur.fetchall()"), ("py-hotpath", "for i in range(len(rows)):"),
               ("py-parallel", "t = threading.Thread(target=worker)"), (None, "total = price * qty")],
        # Dart(2026-09-13 補棧):舊法=不用 async/await 改寫成 .then 鏈、清單直接塞 children
        "dart": [("dart-async", "fetch().then((v) => cache = v);"),
                 ("dart-list", "ListView(children: items.map(row).toList())"),
                 ("dart-isolate", "final items = jsonDecode(body) as List;"),
                 (None, "final total = price * qty;")],
    }
    # 看字串只限 when_raw 那幾條(code-反面詞 r1 單席 f1):log/錯誤訊息裡的關鍵字不能變假命中;SQL 字串要長得像 SQL
    for _stk, _line, _bad in [("cs", 'logger.LogError("SELECT query failed, retrying");', "cs-data"),
                              ("node", 'console.log("remember to call JSON.parse on the config")', "node-eventloop"),
                              ("node", 'throw new Error("db.query failed, check createPool settings")', "node-data"),
                              ("swift", "override func viewDidLoad() { super.viewDidLoad() }", "swift-swiftui"),
                              ("cs", "response.Body.Open();", "cs-connection"),
                              ("sql", "SELECT dbo.fn_TotalTrim(name) FROM Users", "sql-sargable"),
                              ("py", 'log.error("time.sleep failed, requests.get timed out")', "py-eventloop"),
                              ("py", "raise ValueError('call fetchall() first')", "py-memory")]:
        _a, _m = m._stack_applicability({_stk: [_line]}, 300)
        _got = {r["id"] for r in _m[_stk] if r["applicable"]}
        check(f"③假命中不回來:{_line[:34]} 不亮 {_bad}", _bad not in _got, str(_got))
    for _stk, rows_ in _legacy.items():
        for _qid, _line in rows_:
            _a, _m = m._stack_applicability({_stk: [_line]}, 300)
            _got = {r["id"] for r in _m[_stk] if r["applicable"]}
            if _qid is None:
                check(f"③{_stk} 乾淨舊法樣本零觸發:{_line[:30]}", not _got, str(_got))
            else:
                check(f"③{_stk} 舊法樣本亮同一題 {_qid}:{_line[:30]}", _qid in _got, str(_got))
    app3, meta3 = m._stack_applicability({"kt": ["x"] * 301}, 300)
    check("④超過門檻全表適用且 triggered_by 註明", len(app3["kt"]) == 7 and meta3["kt"][0]["triggered_by"] == ["行數>300"], str(meta3["kt"][0]))
    with tempfile.TemporaryDirectory() as d:
        _disp_repo(d)
        r = _disp_run(["pitfalls", "--diff", "HEAD~1..HEAD", "--json", "--repo", d])
        data = _j.loads([l for l in r.stdout.splitlines() if l.startswith("{")][0])
        check("⑤stack_questions 語意不變(kt 整組 7 題;Spring 後端兩題是 shape_only 不進整組清單)", len(data["stack_questions"]["kt"]) == 7, str(data.get("stack_questions")))
        check("⑤applicable 只列命中題、meta 列全表", data["stack_questions_applicable"] == {"kt": [m._STACK_QUESTION_SPECS["kt"][1]["q"]]} and len(data["stack_questions_meta"]["kt"]) == 10, str(data.get("stack_questions_applicable")))   # meta 列全表:kt 七題+Spring 後端兩題+extcode
        # 刪行也算:拿掉 viewModelScope 那行 → kt-coroutines 仍適用
        P = Path(d); (P / "app" / "Screen.kt").write_text("class VM : ViewModel() {\n}\n", encoding="utf-8")
        import subprocess as _sp
        _sp.run(["git", "commit", "-qam", "remove launch"], cwd=d)
        r2 = _disp_run(["pitfalls", "--diff", "HEAD~1..HEAD", "--json", "--repo", d])
        data2 = _j.loads([l for l in r2.stdout.splitlines() if l.startswith("{")][0])
        check("⑥純刪除 diff 也觸發(拿掉 viewModelScope.launch → kt-coroutines 適用)", "kt" in data2["stack_questions_applicable"], str(data2.get("stack_questions_applicable")))
    with tempfile.TemporaryDirectory() as d:
        import subprocess as _sp
        g = lambda *a: _sp.run(["git", *a], cwd=d, capture_output=True, text=True)
        g("init", "-q", "-b", "main"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
        (Path(d) / "package.json").write_text('{"dependencies": {"vue": "^3"}}', encoding="utf-8")
        (Path(d) / "a.txt").write_text("x\n", encoding="utf-8"); g("add", "-A"); g("commit", "-qm", "init")
        (Path(d) / "store.ts").write_text("export const s = ref({}); watch(s, () => {})\n", encoding="utf-8"); g("add", "-A"); g("commit", "-qm", "ts")
        r3 = _disp_run(["pitfalls", "--diff", "HEAD~1..HEAD", "--json", "--repo", d])
        data3 = _j.loads([l for l in r3.stdout.splitlines() if l.startswith("{")][0])
        check("⑦前端 .ts 歸 vue 棧且 watch/ref 觸發", "vue" in data3["stack_questions_applicable"], str(data3.get("stack_questions_applicable")))


def t_dispositions_template():
    """[表態閘 S1]樣板:適用題留空、未觸發題自動 na(auto+觸發清單)、含 id 與原文;零命中與 gate=off 印 {};
    --carry 帶舊答案;門檻不合法用預設並印一行。翻紅釘:拔掉 auto 欄 → ②翻紅。"""
    import json as _j
    with tempfile.TemporaryDirectory() as d:
        _disp_repo(d)
        r = _disp_run(["pitfalls", "--diff", "HEAD~1..HEAD", "--dispositions-template", "--repo", d])
        tpl = _j.loads(r.stdout)
        check("①適用題 status 留空、帶原文", tpl["kt-coroutines"]["status"] == "" and tpl["kt-coroutines"]["question"], str(tpl.get("kt-coroutines")))
        check("②未觸發題自動 na 且 auto:true、reason 帶觸發清單", tpl["kt-compose"]["status"] == "na" and tpl["kt-compose"]["auto"] is True and tpl["kt-compose"]["reason"].startswith("未觸發:"), str(tpl.get("kt-compose")))
        check("③stderr 講要答幾題", "要答的題 1 題" in r.stderr, r.stderr[-200:])
        # 寫一份表態,再 --carry
        tpl["kt-coroutines"] = {"status": "na", "question": tpl["kt-coroutines"]["question"], "reason": "這段只是把既有呼叫搬進協程,沒有新的並行點"}
        f = Path(d) / "disp.json"; f.write_text(_j.dumps(tpl, ensure_ascii=False), encoding="utf-8")
        w = _disp_run(["code-loop", "dispositions", str(f), "--repo", d])
        check("④寫入 rc0", w.returncode == 0, w.stdout + w.stderr)
        r2 = _disp_run(["pitfalls", "--diff", "HEAD~1..HEAD", "--dispositions-template", "--carry", "--repo", d])
        tpl2 = _j.loads(r2.stdout)
        check("⑤--carry 帶回舊答案並標 carried", tpl2["kt-coroutines"]["status"] == "na" and tpl2["kt-coroutines"].get("carried") is True, str(tpl2.get("kt-coroutines")))
    with tempfile.TemporaryDirectory() as d:
        _disp_repo(d, kt_body="class VM : ViewModel() {\n}\n")   # 沒有觸發
        r = _disp_run(["pitfalls", "--diff", "HEAD~1..HEAD", "--dispositions-template", "--repo", d])
        check("⑥零命中印 {} 並在 stderr 講一句", r.stdout.strip() == "{}" and "沒有要答" in r.stderr, r.stdout + r.stderr)
    with tempfile.TemporaryDirectory() as d:
        _disp_repo(d, config={"stack_questions": {"gate": "off"}})
        r = _disp_run(["pitfalls", "--diff", "HEAD~1..HEAD", "--dispositions-template", "--repo", d])
        check("⑦gate=off 印 {}", r.stdout.strip() == "{}" and "off" in r.stderr, r.stdout + r.stderr)
    with tempfile.TemporaryDirectory() as d:
        _disp_repo(d, config={"stack_questions": {"ask_all_over_lines": "300", "gate": "sometimes"}})
        r = _disp_run(["pitfalls", "--diff", "HEAD~1..HEAD", "--json", "--repo", d])
        check("⑧門檻/gate 值不合法 → 用預設並印一行", "ask_all_over_lines" in r.stderr and "gate" in r.stderr and r.returncode == 0, r.stderr[-300:])


def t_codeloop_dispositions_write():
    """[表態閘 S4]形狀壞 rc2 不寫並講原因;好 → 先治理帳(帶 branch/head_sha/commit/ts)再原子寫 marker;沒 docs/ 明講。
    翻紅釘:把 _dispositions_validate 的 status 檢查拔掉 → ①翻紅。"""
    import json as _j
    with tempfile.TemporaryDirectory() as d:
        sha = _disp_repo(d)
        P = Path(d); f = P / "disp.json"
        q = "x"
        bad_cases = [
            ("status 大寫", {"kt-coroutines": {"status": "Satisfied", "question": q, "evidence": "app/Screen.kt:3"}}, "只認小寫"),
            ("satisfied 缺 evidence", {"kt-coroutines": {"status": "satisfied", "question": q}}, "evidence"),
            ("na 理由太短", {"kt-coroutines": {"status": "na", "question": q, "reason": "不需要。"}}, "太短"),
            ("英文短理由加句號繞不過", {"kt-coroutines": {"status": "na", "question": q, "reason": "not needed here。"}}, "太短"),
            ("todo 缺 issue", {"kt-coroutines": {"status": "todo", "question": q, "reason": "之後另開一題把 scope 生命週期補齊"}}, "issue"),
            ("未知 id", {"kt-nope": {"status": "na", "question": q, "reason": "這段只是把既有呼叫搬進協程沒有新並行"}}, "不是題目表裡的 id"),
            ("evidence 帶 ..", {"kt-coroutines": {"status": "satisfied", "question": q, "evidence": "../x.kt:1"}}, "切不開"),
            ("legacy 帶平台前綴", {"kt-coroutines": {"status": "satisfied", "question": q, "evidence": "test:app:test_scope_cancel"}}, "沒開多平台"),
        ]
        for label, doc, expect in bad_cases:
            f.write_text(_j.dumps(doc, ensure_ascii=False), encoding="utf-8")
            r = _disp_run(["code-loop", "dispositions", str(f), "--repo", d])
            check(f"①{label} → rc2 且講原因", r.returncode == 2 and expect in r.stderr, f"rc={r.returncode} {r.stderr[-300:]}")
        check("①壞形狀一個都沒寫 marker", not (P / "governance" / "code-loop").exists(), "")
        good = {"kt-coroutines": {"status": "satisfied", "question": q, "evidence": "test:test_scope_cancel"},
                "kt-compose": {"status": "na", "question": q, "auto": True, "reason": "未觸發:x"}}
        f.write_text(_j.dumps(good, ensure_ascii=False), encoding="utf-8")
        r = _disp_run(["code-loop", "dispositions", str(f), "--repo", d])
        check("②合法 → rc0", r.returncode == 0, r.stdout + r.stderr)
        mk = P / "governance" / "code-loop" / "feat__disp.dispositions.json"
        rec = _j.loads(mk.read_text(encoding="utf-8"))
        check("②marker 帶 head_sha/branch/ts", rec["head_sha"] == sha and rec["branch"] == "feat/disp" and rec["ts"], str(rec)[:200])
        lines = [_j.loads(l) for l in (P / "docs" / ".governance-log.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()]
        ev = [e for e in lines if e.get("kind") == "dispositions"]
        check("②治理帳事件帶 branch/head_sha/commit/dispositions", ev and ev[-1]["branch"] == "feat/disp" and ev[-1]["head_sha"] == sha and ev[-1]["commit"] == sha[:7] and "kt-coroutines" in ev[-1]["dispositions"], str(ev[-1:])[:300])
    with tempfile.TemporaryDirectory() as d:
        import shutil
        _disp_repo(d); shutil.rmtree(Path(d) / "docs")
        f = Path(d) / "disp.json"; f.write_text(_j.dumps({"kt-coroutines": {"status": "na", "question": "x", "reason": "這段只是把既有呼叫搬進協程沒有新並行"}}, ensure_ascii=False), encoding="utf-8")
        r = _disp_run(["code-loop", "dispositions", str(f), "--repo", d])
        check("③沒有 docs/ → rc2 明講治理帳寫不進去", r.returncode == 2 and "docs/" in r.stderr, r.stderr[-200:])


