        import subprocess as _sp2
        def fake_run(argv, *a, **kw):
            if len(argv) > 2 and argv[2] == "pitfalls":
                return _sp2.CompletedProcess(argv, 0, _j.dumps({"tier": "high", "stack_questions_applicable": {}, "stack_questions_meta": {}}), "")
