_HOME_AUDIT = str(Path(__file__).resolve().parent.parent / "governance" / "eval" / "home_audit.py")


def t_home_audit_sample_is_reproducible():
    """[S14] 抽查腳本:同一個種子抽出同一批(換種子會不一樣),每對附那篇的 KEY 行與那支檔開頭幾行。
    抽樣不可重現的話,「這次抽到的錯誤率」就沒辦法被別人覆核。"""
    print("t_home_audit_sample_is_reproducible")
    import json as _j, subprocess as _sp
    root = _nh_repo()
    for i in range(6):
        _nh_file(root, f"src/m{i}.py", f"# 模組 {i}\nx = {i}\n")
        _nh_node(root, f"模組{i}", about=[f"src/m{i}.py"], summary=f"KEY:模組 {i} 的規則",
                 body=f"實作在 `src/m{i}.py`。")
    def sample(seed, n=3):
        r = _sp.run([sys.executable, _HOME_AUDIT, "sample", "--vault", str(root / "docs" / "kg-knowledge"),
                     "--seed", str(seed), "--n", str(n), "--repo", str(root), "--lumos", GRAPHCTL],
                    capture_output=True, text=True)
        return _j.loads(r.stdout) if r.returncode == 0 else {"err": r.stderr}
    a, b, c = sample(7), sample(7), sample(99)
    check("①同一個種子抽出同一批", [x["file"] for x in a.get("pairs", [])] == [x["file"] for x in b.get("pairs", [])],
          str(a)[:200])
    check("②抽到的對數是 --n 給的", len(a.get("pairs", [])) == 3, str(len(a.get("pairs", []))))
    check("③總共幾對也說出來", a.get("total_pairs") == 6, str(a.get("total_pairs")))
    check("④換種子抽到不一樣的批(6 對抽 3 對,同批的機率 1/20)",
          [x["file"] for x in c.get("pairs", [])] != [x["file"] for x in a.get("pairs", [])], str(c)[:200])
    one = a.get("pairs", [{}])[0]
    check("⑤每對附那篇的 KEY 行", one.get("key", "").startswith("KEY:"), str(one)[:200])
    check("⑥每對附那支檔開頭", "模組" in one.get("head", ""), str(one.get("head"))[:120])
    check("⑦verdict 留白給審查員填", one.get("verdict") == "", str(one.get("verdict")))
    full = sample(7, n=0)
    check("⑧不給數量就是全部配對", len(full.get("pairs", [])) == 6, str(len(full.get("pairs", []))))


def t_home_audit_tally_counts():
    """[S14] 判定收回來要照「否、判不準、是」排(人從上往下看),給了人裁檔就算錯誤率——
    「超過一成先修家再上線」就是對這個數字。"""
    print("t_home_audit_tally_counts")
    import json as _j, subprocess as _sp
    d = Path(tempfile.mkdtemp(prefix="gctl-homeaudit-"))
    rows = [{"id": "p001", "file": "src/a.py", "node": "Systems/A.md", "key": "KEY:甲", "head": "", "verdict": "是"},
            {"id": "p002", "file": "src/b.py", "node": "Systems/B.md", "key": "KEY:乙", "head": "", "verdict": "否"},
            {"id": "p003", "file": "src/c.py", "node": "Systems/C.md", "key": "KEY:丙", "head": "", "verdict": "判不準"},
            {"id": "p004", "file": "src/d.py", "node": "Systems/D.md", "key": "KEY:丁", "head": "", "verdict": ""}]
    f = d / "verdicts.json"
    f.write_text(_j.dumps({"seed": 7, "pairs": rows}, ensure_ascii=False), encoding="utf-8")
    r = _sp.run([sys.executable, _HOME_AUDIT, "tally", str(f)], capture_output=True, text=True)
    lines = [l for l in r.stdout.splitlines() if l.startswith("  [")]
    check("①照 否 → 判不準 → 是 排",
          [l.split()[1] for l in lines][:3] == ["p002", "p003", "p001"], r.stdout)
    check("②沒填判定的排最後、而且點名", lines[-1].split()[1] == "p004" and "還有 1 對沒填判定" in r.stdout, r.stdout)
    check("③數出各判定幾對", "判「否」1 對" in r.stdout and "判「是」1 對" in r.stdout, r.stdout)
    check("④沒給人裁檔就不算錯誤率", "錯誤率" not in r.stdout, r.stdout)
    rul = d / "ruling.json"
    rul.write_text(_j.dumps({"wrong": ["p002"]}), encoding="utf-8")
    r2 = _sp.run([sys.executable, _HOME_AUDIT, "tally", str(f), "--ruling", str(rul)], capture_output=True, text=True)
    check("⑤錯誤率 = 人裁判錯的 ÷ 總對數", "1 對 ÷ 總共 4 對 = 25.0%" in r2.stdout, r2.stdout)
    check("⑥超過一成要講出來", "超過一成" in r2.stdout, r2.stdout)
    rul.write_text(_j.dumps({"wrong": []}), encoding="utf-8")
    r3 = _sp.run([sys.executable, _HOME_AUDIT, "tally", str(f), "--ruling", str(rul)], capture_output=True, text=True)
    check("⑦沒超過一成也講出來", "沒超過一成" in r3.stdout, r3.stdout)


def t_new_system_without_code_reminds():
    """[S13] 開新的 Systems 節點卻沒說它管哪幾支檔 → 印一句提醒(不擋)。
    不管任何程式檔的節點通常是「主題」不是「模組」;真要這樣,理由要寫在負責範圍裡。"""
