def _home_impact(root, rel, env_extra=None, ranked=True):
    import json as _j, subprocess as _sp, os as _os
    e = dict(_os.environ); e.update(env_extra or {})
    args = [sys.executable, GRAPHCTL, "impact", "--file", rel, "--repo", str(root), "--json"]
    if ranked:
        args.append("--ranked")
    r = _sp.run(args, capture_output=True, text=True, env=e)
    out = r.stdout.strip().splitlines()
    if not out:
        raise AssertionError(f"impact 沒有輸出(rc={r.returncode}):{r.stderr[-400:]}")
    return _j.loads(out[-1])


def t_impact_home_unconfirmed_not_pinned():
    """[S2] 分兩級:只有「確認過的家」保送。確認=那篇的摘要或正文寫出完整路徑,
    或反引號裡寫出在受版控檔裡唯一的裸檔名。光是把檔填進 about_code 不算——
    填錯的家大多就落在這一級,保送它等於把無關的筆記推到人眼前。"""
    print("t_impact_home_unconfirmed_not_pinned")
    root = _nh_repo()
    _nh_file(root, "src/pay.py")
    _nh_file(root, "legacy/pay.py")         # 同名檔:裸檔名不唯一,反引號寫 `pay.py` 不算確認
    _nh_node(root, "只填欄位", about=["src/pay.py"], body="這篇沒寫出那支檔。")
    _nh_node(root, "正文寫全路徑", about=["src/pay.py"], body="計價寫在 src/pay.py,這篇講為什麼。")
    _nh_node(root, "反引號寫裸檔名", about=["src/pay.py"], body="細節在 `pay.py`。")
    _nh_node(root, "欄位裡有但正文只有欄位", about=["src/pay.py"],
             summary="FLOW:x\nKEY:這篇管 src/pay.py [test:t_x]")
    _nh_git(root, "add", "-A")
    by = {x["node"]: x for x in _home_impact(root, "src/pay.py")["results"]}
    check("①只填欄位、正文沒提 → 不保送也不標家",
          not by.get("Systems/只填欄位.md", {}).get("home"), str(by.get("Systems/只填欄位.md")))
    check("②正文寫出完整路徑(沒反引號也算) → 確認,保送",
          by.get("Systems/正文寫全路徑.md", {}).get("home") and by["Systems/正文寫全路徑.md"]["pinned"],
          str(by.get("Systems/正文寫全路徑.md")))
    check("③反引號裡的裸檔名不唯一(兩支同名) → 不算確認",
          not by.get("Systems/反引號寫裸檔名.md", {}).get("home"), str(by.get("Systems/反引號寫裸檔名.md")))
    check("④摘要裡寫出完整路徑也算確認",
          by.get("Systems/欄位裡有但正文只有欄位.md", {}).get("home"), str(by.get("Systems/欄位裡有但正文只有欄位.md")))
    root2 = _nh_repo()
    _nh_file(root2, "src/only.py")
    _nh_node(root2, "唯一裸檔名", about=["src/only.py"], body="細節在 `only.py`。")
    _nh_git(root2, "add", "-A")
    by2 = {x["node"]: x for x in _home_impact(root2, "src/only.py")["results"]}
    check("⑤反引號裡的裸檔名在整個專案唯一 → 算確認",
          by2.get("Systems/唯一裸檔名.md", {}).get("home"), str(by2.get("Systems/唯一裸檔名.md")))


def t_impact_home_no_duplicate_node():
    """[S2] 同一篇既是家、又本來就因為反引號進了候選 → 只出現一次(原項加標記升級,不另外新增一項)。
    列兩次的話,派工鏡頭會把同一篇的內容貼兩遍,把別篇的位置吃掉。"""
    print("t_impact_home_no_duplicate_node")
    root = _nh_repo()
    _nh_file(root, "src/pay.py")
    _nh_node(root, "又是家又被提到", about=["src/pay.py"], body="計價在 `src/pay.py`。")
    _nh_git(root, "add", "-A")
    res = _home_impact(root, "src/pay.py")["results"]
    hits = [x for x in res if "又是家又被提到" in x["node"]]
    check("①只出現一次", len(hits) == 1, str([x["node"] for x in res]))
    check("②保留原本的種類與命中來源(不是憑空新增一項)",
          hits and hits[0]["kind"] == "direct" and hits[0].get("hit"), str(hits))
    check("③同時標了家、也升成必推", hits and hits[0].get("home") and hits[0]["pinned"], str(hits))


def t_impact_home_moves_out_of_lane():
    """[S2] 被分到「守衛面參考」那條道的節點,如果是這支檔確認過的家 → 搬進必推名單,
    而且從參考道拿掉(同一篇只出現在一個地方)。"""
    print("t_impact_home_moves_out_of_lane")
    root = _nh_repo()
    _nh_file(root, "src/pay.py"); _nh_file(root, "src/hub.py")
    # 樞紐直接命中 src/pay.py(反引號),它連到的 risk 節點就會落在查 src/pay.py 那次的參考道(hop1)
    _nh_node(root, "樞紐", about=["src/hub.py"],
             body="接線在 `src/hub.py`,也會碰到 `src/pay.py`;細節看 [[Systems/守衛面的家]]。")
    # ★正文不可以用反引號寫 src/pay.py★:那樣它查 src/pay.py 時會直接從「反引號命中」進候選,
    # 根本不會落在參考道,搬移那段程式碼就沒被執行到(代碼審 r1 測試席實測:把搬移那行拿掉照樣全綠)。
    # 要驗搬移,就得讓它「是 src/pay.py 的家、確認過(正文寫完整路徑但不用反引號)、而且在參考道裡」。
    _nh_node(root, "守衛面的家", about=["src/pay.py"], body="計價寫在 src/pay.py,這篇講守衛面。",
             summary="FLOW:x\nKEY:守衛面的規則")
    n = root / "docs" / "kg-knowledge" / "Systems" / "守衛面的家.md"
    n.write_text(n.read_text(encoding="utf-8").replace("  - status/doing", "  - status/doing\n  - risk/守衛面"),
                 encoding="utf-8")
    _nh_git(root, "add", "-A")
    d0 = _home_impact(root, "src/pay.py", {"LUMOS_IMPACT_HOME": "0"})
    check("①前提:旋鈕關掉時這篇確實落在參考道(不然②③等於沒驗)",
          any("守衛面的家" in x.get("node", "") for x in d0.get("lane", [])), str(d0.get("lane")))
    d = _home_impact(root, "src/pay.py")
    check("②是這支檔的家 → 進必推",
          any("守衛面的家" in x["node"] and x["pinned"] and x.get("home") for x in d["results"]),
          str(d["results"])[:300])
    check("③不會同時留在參考道",
          all("守衛面的家" not in x.get("node", "") for x in d.get("lane", [])), str(d.get("lane")))


def t_impact_pins_order_incident_home_rest():
    """[S3] 必推名單的順序:事故最前、其次家、其餘照原本;事故同時是家的算事故;
    家之間照分數高到低、同分照篇名。排錯的後果是實在的——派工鏡頭只把前幾篇貼內容,其餘只列名。"""
    print("t_impact_pins_order_incident_home_rest")
    root = _nh_repo()
    _nh_file(root, "src/pay.py")
    _nh_node(root, "B家", about=["src/pay.py"], body="計價在 `src/pay.py`。")
    _nh_node(root, "A家", about=["src/pay.py"], body="計價在 `src/pay.py`。")
    _nh_node(root, "事故又是家", typ="issue", folder="Issues", about=["src/pay.py"], resp=None,
             summary="FLAG:TECHNICAL\nKEY:出過事", body="出事的是 `src/pay.py`。")
    _nh_node(root, "帶合約的", about=[], resp=None,
             summary="FLOW:x\nKEY:\u2605INVARIANT\u2605 計價規則不准改 [test:t_x]",
             body="規則實作在 `src/pay.py`。")
    n = root / "docs" / "kg-knowledge" / "Issues" / "事故又是家.md"
    n.write_text(n.read_text(encoding="utf-8").replace("about_code:", "pitfall_when:\n  - glob:src/pay.py\nabout_code:"),
                 encoding="utf-8")
    _nh_git(root, "add", "-A")
    pins = [x for x in _home_impact(root, "src/pay.py")["results"] if x["pinned"]]
    names = [x["node"] for x in pins]
    check("①事故排最前(它同時是家,算事故)", names and names[0] == "Issues/事故又是家.md", str(names))
    check("②家排在其餘必推之前",
          names.index("Systems/A家.md") < names.index("Systems/帶合約的.md")
          and names.index("Systems/B家.md") < names.index("Systems/帶合約的.md"), str(names))
    check("③家之間同分照篇名排(A 在 B 前)",
          names.index("Systems/A家.md") < names.index("Systems/B家.md"), str(names))


def t_impact_home_is_additive_only():
    """[S5] 只加不降:事故、帶合約的直接節點、一跳硬合約間接節點照原本規則進必推,
    不因為「不是家」而被降;不是家、只被反引號提到的節點照原本規則留在可選名單。"""
    print("t_impact_home_is_additive_only")
    root = _nh_repo()
    _nh_file(root, "src/pay.py")
    _nh_node(root, "家", about=["src/pay.py"], body="計價在 `src/pay.py`。")
    _nh_node(root, "帶合約不是家", about=[], resp=None,
             summary="FLOW:x\nKEY:\u2605INVARIANT\u2605 計價規則不准改 [test:t_x]",
             body="規則實作在 `src/pay.py`。")
    _nh_node(root, "只被提到", about=[], body="改的時候順便看一下 `src/pay.py`。")
    _nh_git(root, "add", "-A")
    d = _home_impact(root, "src/pay.py")
    by = {x["node"]: x for x in d["results"]}
    check("①帶合約的直接節點照樣必推(不是家也不降)",
          by.get("Systems/帶合約不是家.md", {}).get("pinned"), str(by.get("Systems/帶合約不是家.md")))
    check("②只被反引號提到的照樣在候選裡",
          "Systems/只被提到.md" in by, str(list(by)))
    check("③它沒有被標成家", not by.get("Systems/只被提到.md", {}).get("home"), str(by.get("Systems/只被提到.md")))
    d0 = _home_impact(root, "src/pay.py", {"LUMOS_IMPACT_HOME": "0"})
    old = {x["node"] for x in d0["results"] if x["pinned"]}
    new = {x["node"] for x in d["results"] if x["pinned"]}
    check("④旋鈕開著之後,必推名單只多不少", old <= new, f"舊 {sorted(old)} / 新 {sorted(new)}")


def t_dispatch_lens_diff_includes_homes():
    """[S6] 派工鏡頭的推送前模式(--diff):家那一行要標成家,而且排在事故之後、其餘之前。"""
