def t_home_audit_refuses_paths_outside_repo():
    """代碼審 r2:抽查腳本會照筆記裡寫的路徑讀檔。筆記是 .md,手改就能寫成 ../ 或絕對路徑,
    讀到的內容還會原樣寫進常被提交進版控的輸出——越界的一律不讀。
    ★而且其餘合法配對照印★:第一版的警告把整份報告一起吃掉了。"""
    print("t_home_audit_refuses_paths_outside_repo")
    import json as _j, subprocess as _sp
    root = _nh_repo()
    secret = root.parent / f"SECRET_{root.name}.txt"
    secret.write_text("TOP-SECRET-LINE\n", encoding="utf-8")
    try:
        _nh_file(root, "src/good.py", "# 正常的檔\n")
        _nh_node(root, "正常的家", about=["src/good.py"], body="實作在 `src/good.py`。")
        _nh_node(root, "越界的家", about=[f"../{secret.name}"], body=f"看 `../{secret.name}`。")
        _nh_git(root, "add", "-A")
        r = _sp.run([sys.executable, _HOME_AUDIT, "sample", "--vault", str(root / "docs" / "kg-knowledge"),
                     "--seed", "1", "--repo", str(root), "--lumos", GRAPHCTL], capture_output=True, text=True)
        check("①專案外的檔一個字都沒讀出來", "TOP-SECRET-LINE" not in r.stdout + r.stderr,
              (r.stdout + r.stderr)[:400])
        check("②有講出是哪一對越界、怎麼改", "跑出專案外面" in r.stderr and "about_code" in r.stderr,
              r.stderr[:400])
        check("③其餘合法配對照印(警告不該把整份報告吃掉)",
              r.returncode == 0 and "src/good.py" in r.stdout, f"rc={r.returncode}\n" + r.stdout[:300])
        d = _j.loads(r.stdout)
        bad = next((x for x in d["pairs"] if "越界" in x["node"]), None)
        check("④越界那一對留在清單上、但內容換成說明(人才看得到要修哪一篇)",
              bad is not None and "跑出專案外面" in bad["head"], str(bad)[:200])
    finally:
        secret.unlink(missing_ok=True)


def t_home_audit_tally_rejects_stray_ids():
    """代碼審 r2:人裁檔拿錯輪的,編號對不上這批配對,錯誤率會算出超過 100% 卻不報錯——
    那個數字看起來還很正常。編號不在這批就擋下。"""
    print("t_home_audit_tally_rejects_stray_ids")
    import json as _j, subprocess as _sp
    d = Path(tempfile.mkdtemp(prefix="gctl-stray-"))
    rows = [{"id": "p001", "file": "src/a.py", "node": "Systems/A.md", "key": "K", "head": "", "verdict": "是"},
            {"id": "p002", "file": "src/b.py", "node": "Systems/B.md", "key": "K", "head": "", "verdict": "否"}]
    f = d / "verdicts.json"; f.write_text(_j.dumps({"pairs": rows}, ensure_ascii=False), encoding="utf-8")
    rul = d / "ruling.json"; rul.write_text(_j.dumps({"wrong": ["p001", "p998", "p999"]}), encoding="utf-8")
    r = _sp.run([sys.executable, _HOME_AUDIT, "tally", str(f), "--ruling", str(rul)], capture_output=True, text=True)
    check("①編號對不上就擋下", r.returncode == 2, f"rc={r.returncode}")
    check("②點名是哪幾個編號", "p998" in r.stderr and "p999" in r.stderr, r.stderr[:300])
    check("③講出最常見的原因(拿錯輪)", "同一輪" in r.stderr or "同一批" in r.stderr, r.stderr[:300])
    check("④不會印出超過 100% 的錯誤率", "150" not in r.stdout, r.stdout[:300])
    rul.write_text(_j.dumps({"wrong": ["p001"]}), encoding="utf-8")
    r2 = _sp.run([sys.executable, _HOME_AUDIT, "tally", str(f), "--ruling", str(rul)], capture_output=True, text=True)
    check("⑤編號都對得上就照算", r2.returncode == 0 and "50.0%" in r2.stdout, r2.stdout[-200:])


def t_impact_diff_keeps_homes():
    """[S6] 推送前的波及計算多檔聚合:家的標記取或、記下是哪幾支檔的家(分數高的那筆整項取代也不能沖掉);
    必推名單照 事故 → 家 → 其餘照分數 排。"""
    print("t_impact_diff_keeps_homes")
    import json as _j, subprocess as _sp
    root = _nh_repo()
    _nh_file(root, "src/a.py"); _nh_file(root, "src/b.py")
    _nh_node(root, "甲的窩", about=["src/a.py"], body="這篇講 `src/a.py`。")
    _nh_node(root, "合約那篇", typ="issue", folder="Issues", resp=None,
             summary="KEY:\u2605INVARIANT\u2605 兩支檔的計價規則不准改 [test:t_x]",
             body="規則落在 `src/a.py` 與 `src/b.py`。")
    _nh_git(root, "add", "-A"); _nh_git(root, "commit", "-qm", "base")
    _nh_file(root, "src/a.py", "x = 2\n"); _nh_file(root, "src/b.py", "y = 2\n")
    _nh_git(root, "add", "-A"); _nh_git(root, "commit", "-qm", "change")
    r = _sp.run([sys.executable, GRAPHCTL, "impact", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json"],
                capture_output=True, text=True)
    d = _j.loads(r.stdout.strip().splitlines()[-1])
    res = d.get("results", [])
    home = next((x for x in res if "甲的窩" in x["node"]), None)
    other = next((x for x in res if "合約那篇" in x["node"]), None)
    check("①多檔聚合後仍帶著家的標記", home is not None and home.get("home"), str(home))
    check("②記下它是哪幾支檔的家", home is not None and home.get("home_of") == ["src/a.py"], str(home))
    check("③家進必推名單", home is not None and home.get("pinned"), str(home))
    pins = [x for x in res if x.get("pinned")]
    check("④前提:另一篇必推的分數不低於家(不然⑤等於沒驗)",
          other is not None and other.get("pinned") and other["score"] >= home["score"],
          f"家 {home and home.get('score')} / 另一篇 {other and other.get('score')}")
    check("⑤家排在其餘必推之前(不照分數)",
          [x["node"] for x in pins][:2] == [home["node"], other["node"]] if (home and other) else False,
          str([x["node"] for x in pins]))


def t_dispatch_lens_spec_includes_homes():
    """[S6] 派工鏡頭的計劃模式走不帶排序的輸出:那個輸出要多一個頂層鍵列出家,鏡頭把家收進固定席、
    照 事故 → 家 → 其餘 排(不然家會排最後、被每檔上限截成只列名)。"""
    print("t_dispatch_lens_spec_includes_homes")
    import json as _j, subprocess as _sp
    root = _nh_repo()
    _nh_file(root, "src/pay.py")
    _nh_node(root, "計價規則", about=["src/pay.py"], body="計價在 `src/pay.py`。")
    _nh_git(root, "add", "-A"); _nh_git(root, "commit", "-qm", "base")
    r = _sp.run([sys.executable, GRAPHCTL, "impact", "--file", "src/pay.py", "--repo", str(root), "--json"],
                capture_output=True, text=True)
    d = _j.loads(r.stdout.strip().splitlines()[-1])
    check("①不帶排序的輸出多一個 homes 鍵",
          [x.get("node") for x in d.get("homes", [])] == ["Systems/計價規則.md"], str(d)[:240])
    check("②家不會同時又留在直接相依那袋(重複列兩次)",
          all("計價規則" not in x.get("node", "") for x in d.get("direct", [])), str(d.get("direct"))[:200])
    _nh_node(root, "某案_計劃", typ="project", folder="Projects", resp=None,
             summary="KEY:試", body="要改 `src/pay.py`。")
    _nh_git(root, "add", "-A"); _nh_git(root, "commit", "-qm", "plan")
    r2 = _sp.run([sys.executable, GRAPHCTL, "dispatch-lens", "--spec", "docs/kg-knowledge/Projects/某案_計劃.md",
                  "--repo", str(root)], capture_output=True, text=True)
    line = next((l for l in r2.stdout.splitlines() if "計價規則" in l), "")
    check("③計劃模式的鏡頭把家列出來,而且那行標成家", "家" in line, r2.stdout[:400] + r2.stderr[:200])


def t_impact_home_uses_nodehome_definition():
    """[S1] 家對照表只有一支算法:每支檔有家從提交快照餵、推筆記從已載入的圖譜餵,兩邊拿到同一張表。
    [S2] 確認過的家:全文寫出完整路徑,或反引號裡寫出在受版控檔裡唯一的裸檔名;裸檔名不在反引號裡不算
    (沒有副檔名的程式檔,檔名是普通詞——全庫 65 篇 Systems 有 62 篇正文出現裸字 lumos)。"""
    print("t_impact_home_uses_nodehome_definition")
    m = _load_lumos_inproc()
    root = _nh_repo()
    _nh_file(root, "src/pay.py"); _nh_file(root, "src/cart.py"); _nh_file(root, "tools/runner")
    _nh_node(root, "金流", about=["src/pay.py"], body="這篇講 `src/pay.py` 的計價。")
    _nh_node(root, "購物車", about=["src/cart.py"], body="購物車的狀態機;檔在 src/cart.py。")
    _nh_node(root, "跑測試", about=["tools/runner"], body="用 `runner` 跑一次就好(裸檔名在反引號裡)。")
    _nh_node(root, "隨手塞", about=["src/cart.py"], body="這篇完全沒提到那支檔。", summary="FLOW:無關")
    _nh_node(root, "計劃型", about=["src/pay.py"], typ="project", folder="Projects", status="doing")
    _nh_git(root, "add", "-A")
    side = m._nodehome_side(root, "index", "docs/kg-knowledge")
    homes_snap, _own = m._nodehome_homes(root, side)
    env = m.Env(root / "docs" / "kg-knowledge")
    homes_env, _o2 = m._impact_home_map(env)
    check("①兩邊餵同一支純函式,拿到同一張家對照表", homes_snap == homes_env, f"{homes_snap} vs {homes_env}")
    check("②只算 Systems 與 doing/done/stale(計劃型不算家)", homes_env.get("src/pay.py") == ["Systems/金流.md"], str(homes_env))
    top = m._nodehome_top_dirs([p for p in side.all_paths if "/" in p])
    def conf(node, path):
        text = (root / "docs" / "kg-knowledge" / "Systems" / f"{node}.md").read_text(encoding="utf-8")
        return m._home_confirmed(text, path, top, side.all_paths)
    check("③反引號裡寫完整路徑 → 確認", conf("金流", "src/pay.py"), "")
    check("④正文(沒有反引號)寫出完整路徑 → 確認", conf("購物車", "src/cart.py"), "")
    check("⑤反引號裡寫唯一的裸檔名 → 確認(沒有副檔名的檔也一樣)", conf("跑測試", "tools/runner"), "")
    check("⑥完全沒提到 → 不算確認", not conf("隨手塞", "src/cart.py"), "")
    plain = root / "docs" / "kg-knowledge" / "Systems" / "裸字.md"
    _nh_node(root, "裸字", about=["tools/runner"], body="這篇散文裡只寫了 runner 這個字,沒有反引號。")
    check("⑦裸檔名不在反引號裡不算確認(普通詞會誤判)",
          not m._home_confirmed(plain.read_text(encoding="utf-8"), "tools/runner", top, side.all_paths), "")


def t_nodehome_home_definition():
    """[S2] 家:狀態 doing/done/stale 的 Systems 節點 about_code 列了它;planned/deferred/rejected/superseded 不算;
    只看欄位值、不看預標指紋;Issues 不算。"""
    print("t_nodehome_home_definition")
    m = _load_lumos_inproc()
    root = _nh_repo()
    for i, st in enumerate(("doing", "done", "stale", "planned", "deferred", "rejected", "superseded")):
        _nh_file(root, f"src/f{i}.py")
        _nh_node(root, f"N{i}", about=[f"src/f{i}.py"], status=st)
    _nh_file(root, "src/x.py")
    _nh_node(root, "Stamped", about=["src/x.py"], extra="about_code_stamp: claude/2026-09-01/deadbeef")
    _nh_file(root, "src/i.py")
    _nh_node(root, "Inc", about=["src/i.py"], typ="issue", status="open", folder="Issues")
    _nh_git(root, "add", "-A")
    side = m._nodehome_side(root, "index", "docs/kg-knowledge")
    homes, _own = m._nodehome_homes(root, side)
    got = {f"src/f{i}.py": bool(homes.get(f"src/f{i}.py")) for i in range(7)}
    check("①doing/done/stale 算家", got["src/f0.py"] and got["src/f1.py"] and got["src/f2.py"], str(got))
    check("②planned/deferred/rejected/superseded 不算", not any(got[f"src/f{i}.py"] for i in (3, 4, 5, 6)), str(got))
    check("③預標指紋對不上照樣算家(只看欄位值)", bool(homes.get("src/x.py")), str(homes.get("src/x.py")))
    check("④Issues 的 about_code 不算家", not homes.get("src/i.py"), str(homes.get("src/i.py")))


def t_nodehome_check_blocks_new_homeless_file():
    """[S3] 新增的程式檔提交後沒家 → 擋;同一個提交順手建家 → 過;改名成新路徑、about_code 沒跟上 → 擋。"""
    print("t_nodehome_check_blocks_new_homeless_file")
    root = _nh_repo()
    _nh_base(root)
    _nh_file(root, "src/c.py")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("①新增 src/c.py 沒家 → rc1,訊息講出是哪一支", rc == 1 and "c.py" in out, out[-600:])
    _nh_node(root, "C", about=["src/c.py"])
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("②同一個提交順手建家 → rc0", rc == 0, out[-600:])
    _nh_git(root, "reset", "-q", "--hard")
    _nh_git(root, "clean", "-qfd")
    _nh_git(root, "mv", "src/a.py", "src/a2.py")
    rc, out = _nh_check(root)
    check("③改名成新路徑、about_code 沒跟上 → rc1(新路徑算新增)", rc == 1 and "a2.py" in out, out[-600:])
    _nh_git(root, "reset", "-q", "--hard")
    _nh_git(root, "config", "diff.renames", "copies")      # 使用者設了「偵測複製」也一樣:檢查自己帶 -M,複製照樣標成 A
    _nh_file(root, "src/a3.py", (root / "src" / "a.py").read_text(encoding="utf-8"))
    _nh_file(root, "src/a.py", "x = 1\ny = 2\n")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("④複製一支既有的檔(同時改原檔)→ 複製出來的那支算新增、沒家 rc1", rc == 1 and "a3.py" in out, out[-600:])


