def t_nodehome_route_content_change_definition():
    """[S12] 內容有變=摘要、決策、正文逐欄比對;只動簿記欄位不算。"""
    print("t_nodehome_route_content_change_definition")
    m = _load_lumos_inproc()
    base = m._nodehome_parse_note("---\ntype: system\nstatus: doing\nverified_by:\n  - \"[[Verification/x]]\"\nsummary: |-\n  FLOW:x\ndecisions:\n  - content: a\n    id: d1\n---\n# t\n正文\n")
    def sig(**kw):
        fm = {"vb": '  - "[[Verification/x]]"', "summary": "  FLOW:x", "dec": "  - content: a\n    id: d1", "body": "正文", "status": "doing"}
        fm.update(kw)
        t = f"---\ntype: system\nstatus: {fm['status']}\nverified_by:\n{fm['vb']}\nsummary: |-\n{fm['summary']}\ndecisions:\n{fm['dec']}\n---\n# t\n{fm['body']}\n"
        return m._nodehome_parse_note(t)["sig"]
    check("①只加驗證連結、改狀態 → 不算內容有變", sig(vb='  - "[[Verification/x]]"\n  - "[[Verification/y]]"', status="done") == base["sig"])
    check("②摘要變 → 算", sig(summary="  FLOW:y") != base["sig"])
    check("③決策變 → 算", sig(dec="  - content: b\n    id: d1") != base["sig"])
    check("④正文變 → 算", sig(body="正文改了") != base["sig"])
    src = Path(GRAPHCTL).read_text(encoding="utf-8")
    body = src.split("def _nodehome_parse_note", 1)[1].split("\ndef ", 1)[0]
    check("⑤不沿用只算正文的那支雜湊", "note_body_hash" not in body and "_body_hash_of_text" not in body)


