def _nh_hook_repo():
    """掛鉤測試用:真的 lumos 放進 scripts/lumos(提交前、推送前掛鉤從那裡叫)。"""
    import os as _os
    root = _nh_repo()
    (root / "scripts").mkdir(exist_ok=True)
    (root / "scripts" / "lumos").symlink_to(Path(GRAPHCTL).resolve())
    return root


def _nh_run_hook(root, hook, stdin=None):
    import subprocess as sp, os as _os
    env = dict(_os.environ, GIT_DIR=str(root / ".git"))
    r = sp.run(["bash", str(Path(GRAPHCTL).resolve().parent / "hooks" / hook)], cwd=str(root),
               input=stdin, capture_output=True, text=True, env=env, timeout=180)
    return r.returncode, r.stdout + r.stderr


def t_precommit_runs_home_check():
    """[S25] 提交前掛鉤在逐篇格式檢查之後、「改程式沒動圖譜」之前呼叫 home check --staged;擋下就不提交;合併提交跳過。"""
    print("t_precommit_runs_home_check")
    hook_txt = (Path(GRAPHCTL).resolve().parent / "hooks" / "pre-commit").read_text(encoding="utf-8")
    i_l, i_h, i_3 = hook_txt.find("# Gate L:"), hook_txt.find("home check --staged"), hook_txt.find("# Gate 3:")
    check("①位置:逐篇格式檢查之後、改程式沒動圖譜那道之前", 0 <= i_l < i_h < i_3, f"{i_l} {i_h} {i_3}")
    calls = [l for l in hook_txt.splitlines() if "--sync-only" in l and not l.lstrip().startswith("#")]
    check("②舊的反引號點名(impact --sync-only)不再被呼叫,改由 home check 照家算", not calls, str(calls))
    root = _nh_hook_repo()
    _nh_base(root)
    _nh_file(root, "src/c.py")
    (root / "docs" / "kg-knowledge" / "Verification" / "v.md").write_text(
        "---\ntype: verification\nstatus: pass\ndate: 2026-09-11\nvalid_under: x\nrevalidate_when: x\ntags:\n  - type/verification\n  - status/pass\n---\n# v\n", encoding="utf-8")
    _nh_git(root, "add", "-A")
    rc, out = _nh_run_hook(root, "pre-commit")
    check("③新增沒家的檔、同時有圖譜筆記加進索引 → 仍然擋(不會被改程式沒動圖譜那道提早放行)", rc == 1 and "c.py" in out, out[-600:])
    _nh_node(root, "C", about=["src/c.py"], body="`src/c.py`")
    _nh_git(root, "add", "-A")
    rc, out = _nh_run_hook(root, "pre-commit")
    check("④補了家 → 放行", rc == 0, out[-600:])
    _nh_git(root, "commit", "-qm", "c 有家", "--no-verify")
    _nh_git(root, "checkout", "-qb", "side")
    _nh_file(root, "src/d.py")
    (root / "docs" / "kg-knowledge" / "Verification" / "v2.md").write_text(
        "---\ntype: verification\nstatus: pass\ndate: 2026-09-11\nvalid_under: x\nrevalidate_when: x\ntags:\n  - type/verification\n  - status/pass\n---\n# v2\n", encoding="utf-8")
    _nh_commit(root, "side 加了沒家的檔(繞過)")
    _nh_git(root, "checkout", "-q", "-")
    _nh_file(root, "src/e.py", "e\n")
    _nh_node(root, "E", about=["src/e.py"], body="`src/e.py`")
    _nh_commit(root, "main 前進")
    _nh_git(root, "merge", "--no-ff", "--no-commit", "side")
    rc, out = _nh_run_hook(root, "pre-commit")
    check("⑤合併提交跳過(推送前整段比會接住)", rc == 0 and "合併提交跳過" in out, out[-600:])


def t_prepush_runs_home_check():
    """[S26] 推送前把這次要推的範圍整段查一次;新分支起點=不在任何遠端分支上的最早提交的上一個,不從頭掃。"""
    print("t_prepush_runs_home_check")
    import subprocess as sp, os as _os
    d = Path(tempfile.mkdtemp(prefix="gctl-nh-pp-"))
    sp.run(["git", "init", "-q", str(d)], capture_output=True)
    for k, v in (("user.email", "t@t"), ("user.name", "t")):
        sp.run(["git", "-C", str(d), "config", k, v], capture_output=True)
    log = d / "argv.log"
    sd = d / "scripts"
    sd.mkdir()
    (sd / "lumos").write_text(
        "#!/usr/bin/env python3\nimport sys, json, pathlib, os\n"
        f"pathlib.Path({str(log)!r}).open('a').write(' '.join(sys.argv[1:]) + '\\n')\n"
        "c = sys.argv[1] if len(sys.argv) > 1 else ''\n"
        "if c == 'python-path':\n    print(sys.executable); sys.exit(0)\n"   # 掛鉤先問 3.14 在哪(最低 Python 3.14)
        "if c == 'impact' and '--json' in sys.argv:\n"
        "    print(json.dumps({'range': 'x', 'files': [], 'results': [], 'sync': {'touched_nodes': [], 'missing': []}, 'meta': {}}))\n"
        "elif c == 'pitfalls' and '--json' in sys.argv:\n"
        "    print(json.dumps({'tier': 'standard'}))\n"
        "if c == 'home' and os.environ.get('FAKE_HOME_RC'):\n"
        "    sys.exit(int(os.environ['FAKE_HOME_RC']))\n"
        "sys.exit(0)\n", encoding="utf-8")
    _os.chmod(sd / "lumos", 0o755)
    def commit(msg):
        (d / f"{msg}.txt").write_text(msg, encoding="utf-8")
        sp.run(["git", "-C", str(d), "add", "-A"], capture_output=True)
        sp.run(["git", "-C", str(d), "commit", "-qm", msg, "--no-verify"], capture_output=True)
        return sp.run(["git", "-C", str(d), "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    def pp(stdin, **env):
        log.unlink(missing_ok=True)
        e = dict(_os.environ, GIT_DIR=str(d / ".git"), **env)
        r = sp.run(["bash", str(Path(GRAPHCTL).resolve().parent / "hooks" / "pre-push")], cwd=str(d),
                   input=stdin, capture_output=True, text=True, env=e, timeout=180)
        lines = log.read_text(encoding="utf-8").splitlines() if log.exists() else []
        return r.returncode, [l for l in lines if l.startswith("home check")], r.stdout + r.stderr
    z = "0" * 40
    c1 = commit("c1")
    rc, hl, out = pp(f"refs/heads/main {c1} refs/heads/main {z}\n")
    empty = sp.run(["git", "-C", str(d), "hash-object", "-t", "tree", "/dev/null"], capture_output=True, text=True).stdout.strip()
    check("①真的全新(最早的提交沒有上一個)→ 從空樹比", any(f"--diff {empty}..{c1}" in l for l in hl), "\n".join(hl) + out[-300:])
    sp.run(["git", "-C", str(d), "update-ref", "refs/remotes/origin/main", c1], capture_output=True)
    c2 = commit("c2")
    c3 = commit("c3")
    rc, hl, out = pp(f"refs/heads/main {c3} refs/heads/main {c1}\n")
    check("②一般更新 → 遠端舊值..本地新值", any(f"--diff {c1}..{c3}" in l for l in hl), "\n".join(hl))
    sp.run(["git", "-C", str(d), "checkout", "-qb", "feature"], capture_output=True)
    c4 = commit("c4")
    rc, hl, out = pp(f"refs/heads/feature {c4} refs/heads/feature {z}\n")
    check("③新分支 → 起點是不在遠端分支上的最早提交(c2)的上一個(c1),不從頭掃", any(f"--diff {c1}..{c4}" in l for l in hl), "\n".join(hl))
    rc, hl, out = pp(f"refs/heads/old {c1} refs/heads/old {z}\n")
    check("④要推的提交全都已在遠端 → 不查", not hl, "\n".join(hl))
    rc, hl, out = pp(f"refs/heads/main {c3} refs/heads/main {c1}\n", FAKE_HOME_RC="1")
    check("⑤home check 回 rc1 → 推送擋下,並講逃生路", rc == 1 and "node_home.gate" in out, out[-400:])
    rc, hl, out = pp(f"refs/heads/main {c3} refs/heads/main {c1}\n", FAKE_HOME_RC="3")
    check("⑥lumos 自己出錯(非 0/1)→ 放行", rc == 0, out[-400:])


def t_nodehome_check_gov_events_registered():
    """[S27] 擋下與放行都記進治理帳;閘名登記在已知閘名單與統計語意表;擋下事件帶(檔,節點)配對。"""
    print("t_nodehome_check_gov_events_registered")
