    m = _load_lumos_inproc()
    for g in ("nodehome-check", "check-s8", "check-s9", "check-s10"):
        check(f"①{g} 在已知閘名單", g in m._KNOWN_GATES)
    check("②統計語意表標明這個來源記的是檔案路徑", "nodehome-check" in m._STATS_NODE_SEMANTICS)
    root = _nh_repo()
    (root / "docs" / ".governance-log.jsonl").write_text("", encoding="utf-8")
