def t_new_system_with_code_and_responsibility():
    """[S19] lumos new system 可以帶 --code(可多支)與 --responsibility,一次建好;全部先驗完才建檔。"""
    print("t_new_system_with_code_and_responsibility")
    import subprocess as sp
    root = _nh_repo()
    _nh_file(root, "src/a.py")
    _nh_file(root, "src/b.py")
    _nh_commit(root, "init")
    kb = root / "docs" / "kg-knowledge"
    def new(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(kb), "new", *a], capture_output=True, text=True)
    r = new("system", "兩支", "--code", "src/a.py", "--code", "src/b.py", "--responsibility", "負責 a 與 b 的計算規則,不管畫面")
    txt = (kb / "Systems" / "兩支.md").read_text(encoding="utf-8") if (kb / "Systems" / "兩支.md").exists() else ""
    check("①建好了,about_code 兩支、負責範圍都寫進去", r.returncode == 0 and "  - src/a.py" in txt and "  - src/b.py" in txt
          and "responsibility: 負責 a 與 b 的計算規則" in txt, r.stdout[-300:] + r.stderr[-300:] + txt[:400])
    r = new("system", "壞路徑", "--code", "src/nope.py", "--responsibility", "負責 a 與 b 的計算規則,不管畫面")
    check("②路徑不存在 → rc2、不建檔", r.returncode == 2 and not (kb / "Systems" / "壞路徑.md").exists(), r.stderr[-300:])
    r = new("system", "太短", "--code", "src/a.py", "--responsibility", "管 a")
    check("③負責範圍太短 → rc2、不建檔", r.returncode == 2 and not (kb / "Systems" / "太短.md").exists(), r.stderr[-300:])
    r = new("project", "計劃", "--code", "src/a.py")
    check("④--code 用在計劃 → rc2", r.returncode == 2, r.stderr[-300:])
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("⑤用這個指令建出來的節點直接過每支檔有家的檢查", rc == 0, out[-400:])
    # 代碼審 r1 對答案席:條文說事故筆記也能用 --code,原本只驗了 system
    r = new("issue", "某事故", "--code", "src/b.py")
    txt = (kb / "Issues" / "某事故.md").read_text(encoding="utf-8") if (kb / "Issues" / "某事故.md").exists() else ""
    check("⑥事故筆記也能帶 --code,寫進 about_code", r.returncode == 0 and "  - src/b.py" in txt, r.stderr[-300:] + txt[:300])
    # 代碼審 r1 架構席:寫回被擋或逾時(丟例外)也要講「筆記建好了」、其餘項目照做完,跟下面回掛那兩段同一套
    import io, contextlib
    m = _load_lumos_inproc()
    real = m.cmd_append
    def boom(env, rel, key, value):
        if key == "about_code":
            raise RuntimeError("等了 60 秒還輪不到寫入")
        return real(env, rel, key, value)
    m.cmd_append = boom
    err = io.StringIO()
    try:
        with contextlib.redirect_stderr(err), contextlib.redirect_stdout(io.StringIO()):
            try:
                rc = m.cmd_new(m.Env(kb), "system", "逾時", "2026-09-11", code=["src/a.py"], responsibility="負責 a 的計算規則,不管畫面")
            except RuntimeError:
                rc = "穿出去了"
    finally:
        m.cmd_append = real
    txt = (kb / "Systems" / "逾時.md").read_text(encoding="utf-8") if (kb / "Systems" / "逾時.md").exists() else ""
    check("⑦--code 寫回逾時不穿出去、rc2、印「筆記建好了」", rc == 2 and "筆記建好了" in err.getvalue(), str(rc) + err.getvalue()[-300:])
    check("⑧其餘項目照做完(負責範圍照樣寫進去)", "responsibility: 負責 a 的計算規則" in txt, txt[:400])
    check("⑨同一次失敗只印一行提醒(代碼審 r2 正確性席、邊界席:原本例外那段印一次、外層又印一次)",
          err.getvalue().count("沒寫進 about_code") == 1, err.getvalue()[-400:])


def t_lands_in_field_format():
    """[S20] lands_in:清單欄位(lumos append 寫),每項 Systems/<名>——純字串、不帶 .md、不寫 [[連結]]、只收圖譜節點。"""
    print("t_lands_in_field_format")
    m = _load_lumos_inproc()
    check("①清單欄位白名單有 lands_in", "lands_in" in m.LIST_KEYS)
    check("②Systems/<名> 合格", m._lands_in_bad(["Systems/每支檔有家", "Systems/客人端 畫面"]) == [])
    bad = m._lands_in_bad(["[[Systems/A]]", "Systems/A.md", "Projects/B", "Systems/a/b", "", "A"])
    check("③連結寫法、帶 .md、非 Systems、多層、空的、沒前綴都算寫錯", len(bad) == 6, str(bad))
    v = mkvault()
    write(v, "Projects/P.md", "type: project\nstatus: doing", body="# P\n")
    r = run(v, "append", "P", "lands_in", "Systems/新篇")
    check("④lumos append 寫得進去", r.returncode == 0 and "Systems/新篇" in (v / "Projects" / "P.md").read_text(encoding="utf-8"), r.stderr[-300:])


def t_disposal_gate_requires_landing():
    """[S21] 處置閘多一步:設計審的計劃(Projects 底下、type: project)要有 lands_in、格式對;首筆帳在生效日之後才看、不回溯。"""
    print("t_disposal_gate_requires_landing")
    NEW = "2026-09-15T10:00:00+08:00"
    def _loop(v, lid, rel, fm, ts_override=NEW):
        spec = v / rel
        spec.parent.mkdir(parents=True, exist_ok=True)
        body = f"---\n{fm}\n---\n# spec\n規則甲：只在 0 命中時回退。\n"
        spec.write_text(body, encoding="utf-8")
        h = _sha256_of(spec)
        snap = v / f"{lid}-snap.md"; snap.write_text(body, encoding="utf-8")
        rpt = v / f"{lid}-rpt.md"; rpt.write_text("severity: minor\n甲\n引句：「規則甲：只在 0 命中時回退。」\n", encoding="utf-8")
        run(v, "canary", "record", "none", "--loop", lid, "--round", "r1", "--auditor", "s1-sonnet",
            "--severity", "minor", "--findings-set", "F1", "--refuted-set", "none", "--folded-set", "F1",
            "--report", str(rpt), "--snapshot", str(snap), "--spec", str(spec), "--reviewed", h, expect_rc=0)
        if ts_override:
            _ledger_patch_last(v.parent / ".canary-log.jsonl", lid, ts=ts_override)
        return run(v, "loop", "status", lid, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    v = mkvault()
    write(v, "Systems/A.md", "type: system\nstatus: doing\nsummary: |-\n  FLOW:x", body="# A\n")
    r = _loop(v, f"ld-a-{_M1U}", "Projects/a.md", "type: project\nstatus: doing")
    check("①沒寫 lands_in → FAIL 且理由含 落點", r.returncode == 1 and "落點: ✗" in r.stdout and "落點" in r.stdout.splitlines()[-1], r.stdout[-500:])
    r = _loop(v, f"ld-b-{_M1U}", "Projects/b.md", "type: project\nstatus: doing\nlands_in:\n  - Systems/A\n  - Systems/新篇")
    check("②寫了、格式對 → 那一步 ✓、整閘 PASS,新開的標出來", r.returncode == 0 and "落點: ✓" in r.stdout and "Systems/新篇(新開)" in r.stdout, r.stdout[-500:])
    r = _loop(v, f"ld-c-{_M1U}", "Projects/c.md", "type: project\nstatus: doing\nlands_in:\n  - \"[[Systems/A]]\"")
    check("③寫成連結 → FAIL 並點名那一項", r.returncode == 1 and "[[Systems/A]]" in r.stdout, r.stdout[-500:])
    r = _loop(v, f"ld-d-{_M1U}", "Projects/d.md", "type: project\nstatus: doing", ts_override="2026-09-11T10:00:00+08:00")
    check("④首筆帳早於生效日 → 不回溯", r.returncode == 0 and "落點: —" in r.stdout and "不回溯" in r.stdout, r.stdout[-500:])
    r = _loop(v, f"ld-e-{_M1U}", "Systems/e.md", "type: system\nstatus: doing")
    check("⑤審材不是 Projects 底下的計劃 → 不看", r.returncode == 0 and "不是這個圖譜 Projects 底下的計劃" in r.stdout, r.stdout[-500:])


def t_design_dispatch_shows_landing_sizes():
    """[S22] 設計審派工鏡頭附上落點每一篇的現況:存不存在、掛幾份計劃、幾行 KEY、幾條合約、管幾支檔、有沒有寫負責範圍。"""
    print("t_design_dispatch_shows_landing_sizes")
    import subprocess as sp
    root = _nh_repo()
    _nh_file(root, "src/a.py")
    _nh_node(root, "A", about=["src/a.py"],
             summary="FLOW:x\nKEY:★INVARIANT★ 金額不得為負 [test:t_x]\nKEY:第二行\nKEY:(2026-09-11 補)★CHECKPOINT★ 付款前先鎖單",
             extra='plan_refs:\n  - "[[Projects/舊一]]"\n  - "[[Projects/舊二]]"')
    import os as _os
    outside = Path(tempfile.mkdtemp(prefix="gctl-nh-outside-")) / "secret.md"
    outside.write_text('---\ntype: system\nplan_refs:\n  - "[[Projects/外一]]"\n  - "[[Projects/外二]]"\n  - "[[Projects/外三]]"\n---\n# 外面\n', encoding="utf-8")
    kb = root / "docs" / "kg-knowledge"
    _os.symlink(outside, kb / "Systems" / "捷徑.md")
    esc = _os.path.relpath(outside.with_suffix(""), kb)
    plan = kb / "Projects" / "新功能_計劃.md"
    plan.write_text("---\ntype: project\nstatus: doing\nlands_in:\n  - Systems/A\n  - Systems/新篇\n"
                    f"  - {esc}\n  - Systems/捷徑\n---\n# 新功能\n", encoding="utf-8")
    _nh_commit(root, "init")
    r = sp.run([sys.executable, GRAPHCTL, "dispatch-lens", "--spec", str(plan), "--repo", str(root)], capture_output=True, text=True)
    out = r.stdout + r.stderr
    check("①有落點現況段", "落點現況" in out, out[-600:])
    # 合約數用派工鏡頭既有的合約行判法(代碼審 r1 架構席:原本另寫一條正規式,KEY 後面帶括號說明的會漏算)
    check("②既有那篇:掛 2 份計劃、3 行 KEY、2 條合約(帶括號說明的也算)、管 1 支檔、有寫負責範圍",
          "‹Systems/A›:已存在;掛 2 份計劃、3 行 KEY、2 條合約、管 1 支檔、有寫負責範圍" in out, out[-600:])
    check("③還不存在的標要新開", "‹Systems/新篇›:還不存在(要新開)" in out, out[-600:])
    # 代碼審 r1 資安席:lands_in 沒驗寫法就拼路徑讀檔,能讀到圖譜外面的檔(印出它的統計)
    check("④寫法不對的(../ 跳出圖譜)不去讀、講明寫法看不懂", "寫法看不懂" in out and "掛 3 份計劃" not in out, out[-600:])
    check("⑤捷徑檔指到圖譜外面的不去讀", "‹Systems/捷徑›:指到圖譜外面" in out, out[-600:])


def t_nodehome_rules_in_hint_skill_and_discipline():
    """[S30] 每支檔有家的一句話版寫進:開新節點的提示、教寫節點的說明、節點還原 SOP(快查表與完整版)、
    注入每個專案的紀律區塊、設計審架構對齊派工範本——根因之一是規則只在私人記憶裡。"""
    print("t_nodehome_rules_in_hint_skill_and_discipline")
    import subprocess as sp
    repo = Path(GRAPHCTL).resolve().parent.parent
    places = {
        "教寫節點的說明": repo / "skills" / "lumos-project-notes" / "SKILL.md",
        "節點還原 SOP 快查表": repo / "skills" / "lumos-project-notes" / "commands" / "09-節點還原.md",
        "節點還原 SOP 完整版": repo / "skills" / "lumos-project-notes" / "reference.md",
        "紀律區塊範本": repo / "scripts" / "templates" / "graph-discipline.md",
        "架構對齊派工範本": repo / "skills" / "lumos-design-loop" / "templates.md",
    }
    if not all(p.exists() for p in places.values()):
        raise _SrcOnly("消費端沒有 skill 與範本(非來源 repo),這段沒驗到")
    for name, p in places.items():
        t = p.read_text(encoding="utf-8")
        check(f"①{name}提到每支檔有家", "每支檔有家" in t, str(p))
    for name in ("教寫節點的說明", "紀律區塊範本", "節點還原 SOP 快查表", "節點還原 SOP 完整版"):
        t = places[name].read_text(encoding="utf-8")
        check(f"②{name}給出建檔就帶 --code 與 --responsibility 的寫法", "--code" in t and "--responsibility" in t, name)
    tpl = places["架構對齊派工範本"].read_text(encoding="utf-8")
    sec = tpl.split("## 7.6", 1)[-1].split("\n## ", 1)[0]
    check("③架構對齊那一節有落點那一問", "落點合不合理" in sec, sec[:200])
    check("③b 那一節的計數字跟著改了(不再只寫三問)", "三問(設計審多第四問)" in sec and "三問(設計審四問)各一段" in sec, sec[:300])
    v = mkvault()
    r = run(v, "new", "system", "提示")
    check("④開新節點時印的提示講每支檔有家", "每支檔有家" in r.stdout and "responsibility" in r.stdout, r.stdout[-600:])


def t_nodehome_diff_shares_unchanged_notes():
    """[S38] 推送前:起點那一側只讀這段範圍裡有變動的節點,沒變的跟終點共用——不然每篇各 git show 一次,65 篇就超過 2 秒。"""
    print("t_nodehome_diff_shares_unchanged_notes")
    m = _load_lumos_inproc()
    root = _nh_repo()
    for i in range(20):
        _nh_file(root, f"src/f{i}.py")
        _nh_node(root, f"N{i}", about=[f"src/f{i}.py"], body=f"`src/f{i}.py`")
    _nh_commit(root, "base")
    base = _nh_git(root, "rev-parse", "HEAD").stdout.strip()
    _nh_file(root, "src/f3.py", "x = 9\n")
    _nh_node(root, "N3", about=["src/f3.py"], body="`src/f3.py` 改了")
    _nh_commit(root, "tip")
    tip = _nh_git(root, "rev-parse", "HEAD").stdout.strip()
    _nh_git(root, "checkout", "-qb", "other", base)
    _nh_file(root, "src/other.py")
    _nh_node(root, "Other", about=["src/other.py"], body="`src/other.py`")
    _nh_commit(root, "第三個提交")                 # 起點、終點都不是目前 checkout:兩側都得從 git 讀,才量得出有沒有共用
    calls = []
    real = m._lens_git
    def spy(repo_root, *args, **kw):
        if args and args[0] == "show":
            calls.append(args[1])
        return real(repo_root, *args, **kw)
    m._lens_git = spy
    try:
        import io, contextlib
        with contextlib.redirect_stderr(io.StringIO()), contextlib.redirect_stdout(io.StringIO()):
            rc = m.cmd_home_check(repo=str(root), diff_range=f"{base}..{tip}")
    finally:
        m._lens_git = real
    base_reads = [c for c in calls if c.startswith(base + ":docs/")]
    check("①起點那一側只讀有變動的節點(N3 一篇),其餘 19 篇跟終點共用", len(base_reads) <= 1, f"{len(base_reads)} {base_reads[:5]}")
    check("②判定照樣正確(沒有新違規)", rc == 0, str(rc))


def t_nodehome_config_and_vendored_from_snapshot():
    """[S38] 設定從被檢查的那個版本讀:工作目錄裡沒暫存的 gate=off 關不掉提交索引的檢查;推送前讀終點那個提交的設定。"""
    print("t_nodehome_config_and_vendored_from_snapshot")
    import json as _j
    root = _nh_repo({"node_home": {"gate": "on"}})
    _nh_base(root)
    _nh_file(root, "src/c.py")
    _nh_git(root, "add", "-A")
    (root / ".lumos" / "config.json").write_text(_j.dumps({"node_home": {"gate": "off"}}), encoding="utf-8")
    rc, out = _nh_check(root)
    check("①只在工作目錄把開關改成 off、沒暫存 → 照樣擋", rc == 1 and "c.py" in out, out[-400:])
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("②把 off 一起加進索引 → 才照設定跳過", rc == 0 and "關掉了" in out, out[-400:])
    _nh_git(root, "commit", "-qm", "c 沒家、開關關掉(被檢查的那個版本)", "--no-verify")
    (root / ".lumos" / "config.json").write_text(_j.dumps({"node_home": {"gate": "on"}}), encoding="utf-8")
    rc, out = _nh_check(root, "--diff", "HEAD~1..HEAD")
    check("③推送前讀終點那個提交的設定(off),不讀工作目錄(on)", rc == 0 and "關掉了" in out, out[-400:])


def t_nodehome_other_branch_rename_uses_commit_spelling():
    """[S2] 比對「家」用字面比對鍵、不讀磁碟:推送一個不是目前 checkout 的分支、裡面有大小寫改名時,不會因為磁碟拼法誤擋。"""
    print("t_nodehome_other_branch_rename_uses_commit_spelling")
    root = _nh_repo()
    _nh_file(root, "src/foo.py")
    _nh_node(root, "Foo", about=["src/foo.py"], body="`src/foo.py`")
    _nh_commit(root, "A")
    a = _nh_git(root, "rev-parse", "HEAD").stdout.strip()
    _nh_git(root, "checkout", "-qb", "feat")
    _nh_git(root, "mv", "src/foo.py", "src/tmp.py")
    _nh_git(root, "mv", "src/tmp.py", "src/Foo.py")
    _nh_node(root, "Foo", about=["src/Foo.py"], body="`src/Foo.py`")
    _nh_commit(root, "B:大小寫改名,同一個提交順手改 about_code")
    b = _nh_git(root, "rev-parse", "HEAD").stdout.strip()
    _nh_git(root, "checkout", "-q", a)
    rc, out = _nh_check(root, "--diff", f"{a}..{b}")
    check("①目前 checkout 在 A(磁碟是小寫 foo.py)推 B → 不誤擋", rc == 0, out[-500:])


def t_nodehome_new_file_awakens_foreign_ref():
    """[S9] 新增的檔喚醒沒改的節點裡原本就寫著的檔名:那篇從這次起就是別人檔的入口 → 擋。"""
    print("t_nodehome_new_file_awakens_foreign_ref")
    root = _nh_repo()
    _nh_base(root)
    _nh_node(root, "A", about=["src/a.py"], body="`src/a.py`,以後會有 `src/later.py`")
    _nh_commit(root, "A 先寫了一個還不存在的檔名")
    _nh_file(root, "src/later.py")
    _nh_node(root, "L", about=["src/later.py"], body="`src/later.py`")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("①新增 later.py(家是 L),A 沒改但從此是它的入口 → rc1、講明是被喚醒的", rc == 1 and "Systems/A" in out and "這篇沒改" in out, out[-600:])
    # 代碼審 r1 正確性席:那篇的反引號可能只是舉例、剛好同名;而且同一個提交裡改它會被寫回落點擋——訊息要指出能走的路
    check("②訊息指出要另開一個提交先改那篇,並分「原本就在講它」與「只是剛好同名」兩種改法",
          "另開一個提交" in out and "剛好同名" in out and "[[Systems/L]]" in out, out[-900:])
    _nh_node(root, "A", about=["src/a.py"], body="`src/a.py`,以後會有 later 那支檔")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("③同一個提交裡順手改 A → 還是擋(A 不是這次改動檔的家),所以才要另開提交", rc == 1 and "不是任何一支改動檔的家" in out, out[-600:])
    _nh_git(root, "reset", "-q", "--hard")
    _nh_git(root, "clean", "-qfd")
    _nh_node(root, "A", about=["src/a.py"], body="`src/a.py`,以後會有 later 那支檔")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("④照訊息先提交一個只改 A 的提交 → rc0(沒動程式的提交不查寫回落點)", rc == 0, out[-600:])
    _nh_commit(root, "先改 A")
    _nh_file(root, "src/later.py")
    _nh_node(root, "L", about=["src/later.py"], body="`src/later.py`")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("⑤再提交新檔與它的家 → rc0", rc == 0, out[-600:])
    _nh_commit(root, "later")
    rc, out = _nh_check(root, "--diff", "HEAD~2..HEAD")
    check("⑥推送前把兩個提交一起查 → rc0", rc == 0, out[-600:])


