def t_doctor_nodehome_bypass_split_all_sections():
    """[S39] 三段都分「守衛上線後才出現」與「上線前就在」;改名繞過的檔也算上線後。"""
    print("t_doctor_nodehome_bypass_split_all_sections")
    root = _nh_repo()
    _nh_base(root)
    _nh_node(root, "Old", about=["src/a.py"], body="`src/a.py` 舊帳寫了 `src/b.py`")
    for f in "cdef":
        _nh_file(root, f"lib/{f}.py")
    _nh_node(root, "BigOld", about=[f"lib/{f}.py" for f in "cdef"], resp=None, body="`lib/c.py`")
    _nh_file(root, "src/r.py", "r = '這支檔的內容獨一無二,改名偵測才不會配到別支同內容的新檔'\n")
    _nh_commit(root, "上線前的舊帳")
    (root / "scripts" / "hooks").mkdir(parents=True)
    (root / "scripts" / "hooks" / "pre-commit").write_text("#!/bin/bash\nlumos home check --staged\n", encoding="utf-8")
    _nh_commit(root, "裝上檢查")
    _nh_node(root, "New", about=["src/b.py"], body="`src/b.py` 繞過時寫進 `src/a.py`")
    for f in "ghij":
        _nh_file(root, f"lib2/{f}.py")
    _nh_node(root, "BigNew", about=[f"lib2/{f}.py" for f in "ghij"], resp=None, body="`lib2/g.py`")
    _nh_git(root, "mv", "src/r.py", "src/r2.py")
    _nh_commit(root, "繞過")
    rc, out = _nh_doctor(root)
    s8, s9, s10 = (out[out.find(a):out.find(b)] for a, b in (("[S8]", "[S9]"), ("[S9]", "[S10]"), ("[S10]", "[H]")))
    check("①S8:改名繞過的 r2.py 算上線後", "上線之後才新增" in s8 and "src/r2.py" in s8.split("上線前就在")[0], s8[:600])
    check("②S9:上線後才寫進的別人檔名單獨一群", "上線之後才寫進" in s9 and "Systems/New" in s9.split("舊帳")[0] and "Systems/Old" in s9.split("舊帳")[-1], s9[:600])
    check("③S10:上線後才變成管太多的單獨一群", "上線之後才變成" in s10 and "Systems/BigNew" in s10.split("(舊帳)")[0], s10[:600])


def t_doctor_nodehome_lists_non_utf8_names():
    """[S28] 檔名不是 UTF-8 的程式檔在健檢 S8 列出來(永遠當不了誰的家,建議改名或排除)。"""
    print("t_doctor_nodehome_lists_non_utf8_names")
    import subprocess as sp
    root = _nh_repo()
    _nh_base(root)
    name = b"src/\xa4\xa4\xa4\xe5.py"
    blob = sp.run(["git", "-C", str(root), "hash-object", "-w", "--stdin"], input=b"y = 1\n", capture_output=True).stdout.strip()
    sp.run([b"git", b"-C", str(root).encode(), b"update-index", b"--add", b"--cacheinfo", b"100644," + blob + b"," + name], capture_output=True)
    rc, out = _nh_doctor(root)
    s8 = out[out.find("[S8]"):out.find("[S9]")]
    check("①S8 講有檔名不是 UTF-8 的程式檔", "不是 UTF-8" in s8 and "Traceback" not in out, s8[:500])


def t_nodehome_newly_required_file_counts_as_new():
    """[S3] 這次才變成需要家的檔也算新增:捷徑檔換成真的程式檔(git 標 T)、沒副檔名的檔補上 #!——
    不能只因為路徑以前就在,就從「擋」降成「提醒」(代碼審 r1 正確性席)。"""
    print("t_nodehome_newly_required_file_counts_as_new")
    import os as _os
    root = _nh_repo()
    _nh_base(root)
    _os.symlink("a.py", root / "src" / "tool.py")
    _nh_file(root, "bin/run", "echo hi\n")
    _nh_commit(root, "捷徑檔與沒副檔名的檔,都還不需要家")
    (root / "src" / "tool.py").unlink()
    _nh_file(root, "src/tool.py", "import os\n")
    _nh_git(root, "add", "-A")
    st = _nh_git(root, "diff", "--cached", "--name-status").stdout
    rc, out = _nh_check(root)
    check("①捷徑檔換成真程式檔(git 標 T)、沒家 → rc1,當成新增", st.startswith("T") and rc == 1
          and "■ 這幾支程式檔沒有家" in out and "tool.py" in out, st + out[-600:])
    _nh_node(root, "Tool", about=["src/tool.py"])
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("②同一個提交順手建家 → rc0", rc == 0, out[-600:])
    _nh_git(root, "reset", "-q", "--hard")
    _nh_git(root, "clean", "-qfd")
    _nh_file(root, "bin/run", "#!/bin/sh\necho hi\n")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("③沒副檔名的舊檔補上 #! 變成程式、沒家 → rc1", rc == 1 and "■ 這幾支程式檔沒有家" in out and "run" in out, out[-600:])
    _nh_commit(root, "繞過提交前檢查")
    rc, out = _nh_check(root, "--diff", "HEAD~1..HEAD")
    check("④推送前也一樣擋", rc == 1 and "■ 這幾支程式檔沒有家" in out, out[-600:])


def t_nodehome_config_disk_read_skips_symlink():
    """[S37] 健檢開頭那一行直讀工作目錄的設定檔:是捷徑檔就不跟過去讀,用預設並留一句——
    跟提交前、推送前讀快照那條路一樣不認捷徑檔(代碼審 r1 資安席:設定檔被做成捷徑檔時會讀到本機任意檔)。"""
    print("t_nodehome_config_disk_read_skips_symlink")
    import os as _os
    m = _load_lumos_inproc()
    root = _nh_repo()
    outside = Path(tempfile.mkdtemp(prefix="gctl-nh-cfg-")) / "c.json"
    outside.write_text('{"node_home": {"gate": "off"}}', encoding="utf-8")
    (root / ".lumos").mkdir()
    _os.symlink(outside, root / ".lumos" / "config.json")
    cfg = m._nodehome_config(root)
    check("①設定檔是捷徑檔 → 不跟過去讀,用預設 on、留一句講明", cfg["mode"] == "on" and any("捷徑檔" in w for w in cfg["warnings"]), repr(cfg))
    (root / ".lumos" / "config.json").unlink()
    (root / ".lumos" / "config.json").write_text('{"node_home": {"gate": "off"}}', encoding="utf-8")
    check("②一般檔照讀", m._nodehome_config(root)["mode"] == "off", "")
    # 代碼審 r2 資安席、邊界席:只看 config.json 本身是不是捷徑,整個 .lumos 資料夾是捷徑時照樣讀到外面那支
    root2 = _nh_repo()
    (outside.parent / "config.json").write_text('{"node_home": {"gate": "off"}}', encoding="utf-8")
    _os.symlink(outside.parent, root2 / ".lumos")
    cfg2 = m._nodehome_config(root2)
    check("③.lumos 資料夾本身是捷徑 → 一樣不跟過去讀,用預設 on、留一句", cfg2["mode"] == "on" and any("捷徑" in w for w in cfg2["warnings"]), repr(cfg2))


def t_nodehome_cli_rejects_both_modes():
    """[S24] --staged 與 --diff 同給 → 用法錯誤 rc2,不靜默選邊。"""
    print("t_nodehome_cli_rejects_both_modes")
    import subprocess as sp
    root = _nh_repo()
    _nh_base(root)
    r = sp.run([sys.executable, GRAPHCTL, "home", "check", "--staged", "--diff", "HEAD..HEAD", "--repo", str(root)], capture_output=True, text=True)
    check("①同給 → rc2", r.returncode == 2, r.stderr[-300:])
    check("②訊息是白話中文、講明擇一(不是 argparse 的英文)", "不能一起用" in r.stderr and "not allowed" not in r.stderr, r.stderr[-300:])


def t_nodehome_planned_to_doing_requires_responsibility():
    """[S17] 這次才成為現況(planned/deferred 升成 doing/done/stale)也算出生,沒寫負責範圍 → 擋。"""
    print("t_nodehome_planned_to_doing_requires_responsibility")
    root = _nh_repo()
