    import time as _t
    ln = "xargs" + " " * 20000 + "x"
    t0 = _t.monotonic()
    _infra_hits([ln])
    dt = _t.monotonic() - t0
    check(f"① {dt:.2f}s < 1s", dt < 1.0, f"{dt:.2f}")


