    r = run(kg, "spec-gate", "Projects/乙_計劃", "--no-run")
    check("② 節內但類名不在四類的已排除行照掃 → 風險高", "風險高" in r.stdout and "DROP TABLE" in r.stdout, r.stdout[-600:])


