def _ppc_env(root, env):
    import os as _os
    tmp = root.with_name(root.name + "-tmp")
    tmp.mkdir(exist_ok=True)
    e = {k: v for k, v in _os.environ.items() if not k.startswith("FAKE_") and k not in (
        "LUMOS_SKIP_DRIFT_CHECK", "LUMOS_SKIP_REREAD_CHECK", "LUMOS_SKIP_CODE_LOOP", "LUMOS_PUSH_ATTEMPT", "GIT_DIR")}
    e.update(GIT_DIR=str(root / ".git"), LUMOS_TEST_SHARDS="1", TMPDIR=str(tmp))
    e.update(env)
    return e


_PPC_CAP_LINE = '# 新版的樣子:原始碼裡有 "--keep-going" 這個字樣(掛鉤讀檔找它判版本)\n'


def _ppc_set_new(root, new):
    """假 lumos 扮新版(FAKE_NEW=1)時原始碼裡要有 "--keep-going" 字樣——掛鉤讀檔找它,不執行 --help;扮舊版時拿掉。"""
    f = root / "scripts" / "lumos"
    t = f.read_text(encoding="utf-8").replace(_PPC_CAP_LINE, "")
    f.write_text(t + (_PPC_CAP_LINE if new else ""), encoding="utf-8")


def _ppc_sigint_default():
    """起掛鉤前把 SIGINT 裝回預設:掛鉤平常由前景的 git 叫起;測試若跑在背景(推送前閘的分片),繼承來的「忽略 SIGINT」
    會讓 bash 的 INT 陷阱裝不上(進場就忽略的訊號不能再接),測 Ctrl-C 的斷言在分片裡假紅(2026-10-14 分片實測)。"""
    import signal
    signal.signal(signal.SIGINT, signal.SIG_DFL)


def _ppc_run(root, stdin, hook=None, **env):
    """用 /bin/bash(macOS 上是 3.2)真的跑推送前掛鉤 → (rc, 假 lumos 的呼叫紀錄, 輸出)。"""
    import subprocess as sp
    hook = hook or Path(GRAPHCTL).resolve().parent / "hooks" / "pre-push"
    _ppc_set_new(root, env.get("FAKE_NEW") == "1")
    log = root / "argv.log"
    log.unlink(missing_ok=True)
    r = sp.run(["/bin/bash", str(hook)], cwd=str(root), input=stdin, capture_output=True, text=True,
               env=_ppc_env(root, env), timeout=300, preexec_fn=_ppc_sigint_default)
    lines = log.read_text(encoding="utf-8").splitlines() if log.exists() else []
    return r.returncode, lines, r.stdout + r.stderr


def _ppc_rows(out):
    """彙總段裡逐筆那幾行 → [(閘名, ref 或 ""), …];沒有彙總段回 None。"""
    import re
    i = out.rfind("這次推送共有")
    if i < 0:
        return None
    rows = []
    for ln in out[i:].splitlines()[1:]:
        mm = re.match(r"^\s+\d+\. (\S+?)(?: \[([^\]]*)\])?:", ln)
        if mm:
            rows.append((mm.group(1), mm.group(2) or ""))
    return rows


def _ppc_rows_full(out):
    """彙總段裡逐筆那幾行 → [(閘名, ref 或 "", 原因), …];沒有彙總段回 None。"""
    import re
    i = out.rfind("這次推送共有")
    if i < 0:
        return None
    rows = []
    for ln in out[i:].splitlines()[1:]:
        mm = re.match(r"^\s+\d+\. (\S+?)(?: \[([^\]]*)\])?:(.*)$", ln)
        if mm:
            rows.append((mm.group(1), mm.group(2) or "", mm.group(3)))
    return rows


def _ppc_header(out):
    import re
    mm = re.search(r"這次推送共有 (\d+) 筆擋下\((\d+) 道閘\)", out)
    return (int(mm.group(1)), int(mm.group(2))) if mm else None


def _ppc_cleanup(root):
    import shutil
    shutil.rmtree(root, ignore_errors=True)
    shutil.rmtree(root.with_name(root.name + "-tmp"), ignore_errors=True)


_PPC_GATES = (("anchor", {"FAKE_RCS": "anchor:1"}), ("anchor-baseline", None), ("doctor", {"FAKE_RCS": "doctor:1"}),
              ("home", {"FAKE_RCS": "home:1"}), ("note-shape", {"FAKE_RCS": "note-shape:1"}),
              ("spec-gate", {"FAKE_RCS": "spec-gate:1"}), ("code-loop", {"FAKE_RCS": "code-loop:1"}),
              ("drift", {"FAKE_RCS": "drift:1"}), ("reread", {"FAKE_RCS": "note-audit:1"}))


def t_prepush_each_gate_blocks_alone():
    """[S6] 全套之前的 9 道閘逐道各讓它單獨擋一次:掛鉤每次都回 1、全套沒被跑到、彙總列出那一道(1 筆、1 道閘),
    而且排在它後面的閘照樣被叫(收集,不是遇錯就停)。
    ①前置:沒有任何一道擋時,9 道都真的被叫到、跑到全套、rc0——不然「擋下時全套沒跑」可能只是假全套根本不會被叫。
    翻紅釘:任一道的 pp_record_block 拿掉(擋下變成什麼都不記)→ 那一道 rc0、全套照跑而紅;
    任一道改回 exit 1 → 那一道「後面的閘照樣被叫」紅;判斷點拿掉 → 全部「全套沒跑」紅。"""
    print("t_prepush_each_gate_blocks_alone")
    _need_src("scripts/hooks/pre-push")
    root, base, head = _ppc_repo()
    try:
        stdin = f"refs/heads/main {head} refs/heads/main {base}\n"
        rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1")
        called = {g: any(ln.startswith(p) for ln in lines) for g, p in (
            ("anchor", "anchor verify"), ("doctor", "doctor --ci"), ("home", "home check"), ("note-shape", "note-shape"),
            ("spec-gate", "spec-gate --push-check"), ("code-loop", "code-loop check --diff"), ("drift", "drift check"),
            ("reread", "note-audit reread-check"))}
        check("①前置:沒有一道擋 → 9 道(簽名檔那道是 git)都被叫到、跑到全套、rc0、不印彙總",
              rc == 0 and all(called.values()) and "SUITE" in lines and _ppc_header(out) is None,
              f"rc={rc} {called} {out[-400:]}")
        bl = root / "governance" / "anchor-baseline.json"
        for gate, env in _PPC_GATES:
            if env is None:
                bl.write_text("{}\n\n", encoding="utf-8")
                rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1")
                _nh_git(root, "checkout", "--", "governance/anchor-baseline.json")
            else:
                rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1", **env)
            rows = _ppc_rows(out)
            check(f"②{gate} 單獨擋:回 1、全套沒跑、彙總 1 筆 1 道閘、列出 {gate}",
                  rc == 1 and "SUITE" not in lines and _ppc_header(out) == (1, 1) and rows == [(gate, "")],
                  f"rc={rc} rows={rows} head={_ppc_header(out)} {out[-500:]}")
            check(f"③{gate} 擋下之後,排在最後的回頭重讀照樣被叫(收集)", any(ln.startswith("note-audit reread-check") for ln in lines),
                  str(lines[-4:]))
    finally:
        _ppc_cleanup(root)


