def t_push_summary_anchor_note_and_separators():
    """lumos push-summary 直接跑:①有 anchor 那筆時印「裁判檔沒簽名」提示句(逐字)、沒有時不印;
    ②暫存檔只照換行字元切:ref 名帶 U+2028、U+2029、U+0085 這類 Python splitlines 也會斷的字元時,那一筆不能被切掉
    (git 允許 ref 名帶這三種,git 2.39.2 的 check-ref-format 實測可過;掛鉤的簡版彙總照換行讀,兩邊要一致)。(代碼審 r1 合約席 1、邊界席 1)
    跳頁與 0x1c–0x1e 是控制字元,git 拒絕,推不出來,所以不測(代碼審 r2 合約席 1:原本那組測的是 git 推不出來的輸入)。
    翻紅釘:提示句改字 → ①紅;改回 splitlines → ②紅(筆數或閘數少、多出「沒寫進暫存檔」)。"""
    print("t_push_summary_anchor_note_and_separators")
    import subprocess as sp
    d = Path(tempfile.mkdtemp(prefix="gctl-pssum-"))
    try:
        bf = d / "blocks"
        bf.write_text("anchor\t-\t裁判檔沒簽名那筆\nhome\trefs/heads/x\t沒家\n", encoding="utf-8")
        r = sp.run([sys.executable, GRAPHCTL, "push-summary", "--blocks-file", str(bf), "--count", "2", "--refs", "1",
                    "--repo", str(d)], capture_output=True, text=True)
        check("①有 anchor 那筆 → 印提示句", r.returncode == 0 and _PPC_ANCHOR_NOTE in r.stderr, r.stderr[-400:])
        bf.write_text("home\trefs/heads/x\t沒家\n", encoding="utf-8")
        r = sp.run([sys.executable, GRAPHCTL, "push-summary", "--blocks-file", str(bf), "--count", "1", "--refs", "1",
                    "--repo", str(d)], capture_output=True, text=True)
        check("①沒有 anchor 那筆 → 不印提示句", r.returncode == 0 and "裁判檔沒簽名" not in r.stderr, r.stderr[-400:])
        # 行程內呼叫也回 0(不是 None):sys.exit(None) 也是 0,只看離開碼抓不到函式結尾的 return 被吃掉(推送與CI提速 代碼審 r1 通才席)
        rv = _load_lumos_module().cmd_push_summary(str(d), str(bf), 1, 1)
        check("①行程內呼叫 cmd_push_summary 回 0", rv == 0, repr(rv))
        for name, ch in (("U+2028", " "), ("U+2029", " "), ("U+0085", "\x85")):
            bf.write_bytes(f"home\trefs/heads/a{ch}b\t沒家\ndoctor\t-\t健檢\n".encode("utf-8"))
            r = sp.run([sys.executable, GRAPHCTL, "push-summary", "--blocks-file", str(bf), "--count", "2", "--refs", "2",
                        "--repo", str(d)], capture_output=True, text=True)
            # 只照 \n 切輸出(印出的 ref 名裡那個字元原樣留著,用 splitlines 讀輸出會把這一列自己切斷)
            import re as _re
            rows = [mm.group(1) for mm in (_re.match(r"^\s+\d+\. (\S+?)(?: \[|:)", ln) for ln in r.stderr.split("\n")) if mm]
            check(f"②ref 名帶 {name} → 2 筆 2 道閘、兩列都在、沒有「沒寫進暫存檔」",
                  r.returncode == 0 and _ppc_header(r.stderr) == (2, 2) and rows == ["home", "doctor"]
                  and "沒寫進暫存檔" not in r.stderr, f"{rows} {r.stderr[-400:]!r}")
    finally:
        import shutil as _sh
        _sh.rmtree(d, ignore_errors=True)


def t_push_summary_repo_root_like_push_range():
    """push-summary 找 repo 根的寫法跟 push-range 同一支(_note_audit_root):沒帶 --repo 時從子資料夾跑,帳寫進 repo 根的
    docs/.governance-log.jsonl;不在 git 專案裡又沒帶 --repo → rc2 講明(push-range 同樣)。(代碼審 r1 架構對齊席 2)
    翻紅釘:改回 Path(repo) if repo else Path.cwd() → ①紅(帳沒寫進 repo 根)、②紅(回 0)。"""
    print("t_push_summary_repo_root_like_push_range")
    import subprocess as sp, json as _j, os
    root = _clkg_repo()
    plain = Path(tempfile.mkdtemp(prefix="gctl-psnogit-"))
    try:
        sub = root / "sub"
        sub.mkdir()
        bf = plain / "blocks"
        bf.write_text("home\t-\t沒家\n", encoding="utf-8")
        led = root / "docs" / ".governance-log.jsonl"
        r = sp.run([sys.executable, GRAPHCTL, "push-summary", "--blocks-file", str(bf), "--count", "1", "--refs", "1"],
                   cwd=str(sub), capture_output=True, text=True)
        evs = [_j.loads(x) for x in (led.read_text(encoding="utf-8").splitlines() if led.exists() else []) if x.strip()]
        check("①子資料夾、沒帶 --repo → 帳寫進 repo 根(多一筆 prepush-summary)",
              r.returncode == 0 and [e.get("gate") for e in evs] == ["prepush-summary"], f"rc={r.returncode} {evs} {r.stderr[-300:]}")
        env = {k: v for k, v in os.environ.items() if k not in ("GIT_DIR", "GIT_WORK_TREE")}
        env["GIT_CEILING_DIRECTORIES"] = str(plain.parent)
        r = sp.run([sys.executable, GRAPHCTL, "push-summary", "--blocks-file", str(bf), "--count", "1", "--refs", "1"],
                   cwd=str(plain), capture_output=True, text=True, env=env)
        r2 = sp.run([sys.executable, GRAPHCTL, "push-range", "--diff", "a..b", "--push-remote", "", "--pushed-ref", ""],
                    cwd=str(plain), capture_output=True, text=True, env=env)
        check("②不在 git 專案、沒帶 --repo → rc2 講明,跟 push-range 一樣",
              r.returncode == 2 and r2.returncode == 2 and "不是 git 專案" in r.stderr and "不是 git 專案" in r2.stderr,
              f"rc={r.returncode}/{r2.returncode} {r.stderr[-200:]} {r2.stderr[-200:]}")
    finally:
        import shutil as _sh
        _sh.rmtree(root, ignore_errors=True)
        _sh.rmtree(plain, ignore_errors=True)


def t_prepush_escape_records_once():
    """收集模式下代碼審判定一次印出「受波及合約的測試沒過」與「tier=high 且…缺留痕」兩句時,逃逸自動記帳只記一筆
    (合約測試紅那筆,--stage push-gate);只有其中一句時照舊記那一句的那一筆。(代碼審 r1 通才席 2:原本遇錯就停時只印第一句)
    翻紅釘:兩句各記一筆(兩個獨立 if)→ ①紅;缺留痕那句優先 → ①紅;只有缺留痕那句時不記 → ③紅。"""
    print("t_prepush_escape_records_once")
    _need_src("scripts/hooks/pre-push")
    root, base, head = _ppc_repo()
    try:
        stdin = f"refs/heads/main {head} refs/heads/main {base}\n"
        bt = "擋下:受波及合約的測試沒過:t_fake_contract(1 支紅)(tier=high)"
        rv = "擋下:tier=high 且無留痕(尚未跑 code-loop pass/skip)"

        def esc(lines):
            return [ln.split("--stage ")[1].split()[0] for ln in lines if ln.startswith("loop escape --auto")]
        rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1", FAKE_RCS="code-loop:1", FAKE_CL_TEXT=bt + "\n" + rv,
                                  FAKE_CL_LINE="LUMOS-BLOCKS: bound_tests,review")
        check("①兩句都在 → 逃逸只記一筆、是合約測試紅那筆", rc == 1 and esc(lines) == ["push-gate"], f"rc={rc} {esc(lines)}")
        rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1", FAKE_RCS="code-loop:1", FAKE_CL_TEXT=bt,
                                  FAKE_CL_LINE="LUMOS-BLOCKS: bound_tests")
        check("②只有合約測試紅 → 記 push-gate 一筆", rc == 1 and esc(lines) == ["push-gate"], str(esc(lines)))
        rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1", FAKE_RCS="code-loop:1", FAKE_CL_TEXT=rv,
                                  FAKE_CL_LINE="LUMOS-BLOCKS: review")
        check("③只有缺留痕 → 記 push-gate-unreviewed 一筆", rc == 1 and esc(lines) == ["push-gate-unreviewed"], str(esc(lines)))
    finally:
        _ppc_cleanup(root)


def t_prepush_test_logs_inside_tmp():
    """全套測試與自主迴圈那支的 log 放在掛鉤的暫存資料夾裡(離開時整個清):全綠時 TMPDIR 底下不留任何 lumos-prepush 開頭的東西;
    紅的時候,訊息指給人看的那份先搬到暫存資料夾外、再印它的路徑——路徑指得到檔、檔裡有紅的那支。(代碼審 r1 併發席 2)
    翻紅釘:log 照舊在暫存資料夾外 mktemp → ①紅(全綠也留兩個檔);紅時印的是暫存資料夾裡那份 → ②③紅(印出的路徑已被刪)。"""
    print("t_prepush_test_logs_inside_tmp")
    import re
    _need_src("scripts/hooks/pre-push")
    root, base, head = _ppc_repo()
    tmp = root.with_name(root.name + "-tmp")
    try:
        (root / "scripts" / "test_autonomous_loop.py").write_text(_PPC_AUTOLOOP, encoding="utf-8")
        stdin = f"refs/heads/main {head} refs/heads/main {base}\n"

        def left():
            return sorted(p.name for p in tmp.glob("lumos-prepush*"))
        rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1")
        check("①全綠 → rc0、TMPDIR 底下不留 lumos-prepush 開頭的檔或資料夾", rc == 0 and "SUITE" in lines and left() == [],
              f"rc={rc} {left()} {out[-300:]}")
        for label, env, red in (("全套測試", {"FAKE_SUITE_RED": "1"}, "t_fake_red_case"),
                                ("自主迴圈那支", {"FAKE_AUTOLOOP_RED": "1"}, "t_fake_autoloop_case")):
            for p in tmp.glob("lumos-prepush*"):
                p.unlink()
            rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1", **env)
            mm = re.search(r"在這裡:\n\s+(\S+)", out)
            kept = Path(mm.group(1)) if mm else None
            check(f"②{label}紅 → 回 1、印出的 log 路徑在掛鉤結束後還在、裡面有紅的那支",
                  rc == 1 and kept is not None and kept.is_file() and red in kept.read_text(encoding="utf-8", errors="replace"),
                  f"rc={rc} kept={kept} {out[-500:]}")
            check(f"③{label}紅 → TMPDIR 底下只留那一份 log(暫存資料夾整個清掉)",
                  kept is not None and left() == [kept.name] and kept.parent == tmp, f"{left()} {kept}")
    finally:
        _ppc_cleanup(root)


def t_prepush_summary_records_event():
    """[S12] 有擋下時版控治理帳多一筆 prepush-summary(kind blocked、hard、帶這次推送的識別碼、extra 帶筆數、閘數、閘名清單、推送行數);
    push-summary 失敗時掛鉤仍回 1、改印簡版彙總。用真的 lumos 寫帳(假 lumos 把 push-summary 轉給真的)。
    翻紅釘:push-summary 不寫帳 → ①紅;_KNOWN_GATES 沒登記 prepush-summary → ①紅(寫入器拒寫);掛鉤看 push-summary 的回傳碼決定擋不擋 → ③紅。"""
    print("t_prepush_summary_records_event")
    import json as _j
    _need_src("scripts/hooks/pre-push")
    root, base, head = _ppc_repo()
    try:
        stdin = f"refs/heads/main {head} refs/heads/main {base}\nrefs/heads/main {head} refs/heads/feat {base}\n"
        led = root / "docs" / ".governance-log.jsonl"
        before = led.read_text(encoding="utf-8").splitlines() if led.exists() else []
        rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1", FAKE_RCS="home:1,drift:1")
        after = led.read_text(encoding="utf-8").splitlines() if led.exists() else []
        evs = [_j.loads(x) for x in after[len(before):] if x.strip()]
        ps = [e for e in evs if e.get("gate") == "prepush-summary"]
        e = ps[0] if len(ps) == 1 else {}
        check("①多一筆 prepush-summary:blocked、hard、帶推送識別碼", len(ps) == 1 and e.get("kind") == "blocked" and e.get("hard") is True
              and str(e.get("attempt_id", "")).count("-") >= 1, f"{ps} {out[-400:]}")
        check("②extra:4 筆、2 道閘、閘名清單、2 行推送", e.get("blocks") == 4 and e.get("gates_n") == 2
              and sorted(e.get("gates") or []) == ["drift", "home"] and e.get("refs") == 2, str(e))
        rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1", FAKE_RCS="home:1,push-summary:2")
        check("③push-summary 失敗 → 掛鉤仍回 1、印簡版彙總、全套沒跑", rc == 1 and "簡版彙總" in out and "SUITE" not in lines,
              f"rc={rc} {out[-400:]}")
    finally:
        _ppc_cleanup(root)


def t_prepush_interrupt_stops_every_gate():
    """[S10] 掛鉤註解區塊「中斷就停」列舉的每一支 lumos 呼叫被訊號殺掉(回傳碼 128 以上)→ 掛鉤以該回傳碼結束、印「<閘名>被中斷」、
    不再開始後面的閘(被殺掉的那支就是最後一次呼叫)、不跑全套;掛鉤自己收到 INT/TERM → 手上那支結束後就結束(130/143)、
    不再開始下一道;等全套測試時被砍(只對掛鉤送 TERM)、按 Ctrl-C(對整個行程群組送 SIGINT)或掛斷(只對掛鉤送 HUP)→ 立刻結束,
    ★全套測試的各片(掛鉤的孫行程)也要收掉★,不留下繼續跑的孤兒、TMPDIR 底下不留東西;裁判簽名與圖譜健檢回 2 照舊記成擋下。
    清單與程式要對得上:非註解的 pp_stop_if_signaled 呼叫行數 = 清單筆數。(併入原 t_prepush_gates_stop_on_signal。)
    對照組:把掛鉤裡的停下全拿掉,同一支被殺掉的呼叫就不會以那個回傳碼結束。
    翻紅釘(2026-10-14 逐條變異實測):拿掉任一支後面的 pp_stop_if_signaled → 那一支紅;門檻改成只認 130 → 全紅;
    陷阱裡不 exit(舊寫法)→ ④⑤⑥⑦紅;跑測試的子殼不收它起的各片(代碼審 r1 併發席 1)→ ⑥⑦⑨紅;裁判簽名改成只有 rc1 才擋 → ⑧紅;
    主殼或子殼不接 HUP(代碼審 r2 併發席 2)→ ⑨紅。⑥⑦⑨看那一片的 pid 有沒有消失,不靠計時窗口(代碼審 r2 邊界席:負載下會假綠)。
    ★片自己起的孫行程也要收★(代碼審 r3 併發席 2):各片各自一個行程群組、收的時候整組收;⑩看假全套起的那個 sleep 有沒有消失。
    ⑪只對跑測試的子殼送 HUP(代碼審 r3 邊界席 2、合約席 3:原本只有主殼收到訊號的情境,子殼的 HUP 陷阱拿掉照綠)。
    翻紅釘(2026-10-14 變異實測):拿掉子殼的 HUP 陷阱 → ⑪紅;_pp_kill_jobs 改回只送給本人 → ⑩⑪紅;起片時不換群組 → ⑩⑪紅。
    ⑪驗 rc == 1(代碼審 r4 合約席 2):子殼 exit 129、主殼把非零的子殼結束碼當成測試沒過,印「有紅」、回 1;這時「紅的是這幾支」是空的
    (沒有任何一支測試真的紅,是跑測試的子殼被掛斷)。翻紅釘:子殼結束碼 128 以上時掛鉤直接以那個碼結束 → ⑪紅(原本只驗非零,照綠)。
    ⑫整組送 TERM 時片正在 fork(代碼審 r4 併發席 1):假片收到 TERM 才生一個孫行程,只送一發時它一定變孤兒;
    翻紅釘:拿掉 _pp_kill_jobs 的第二發 → ⑫紅;第二發不短等直接送 → ⑫紅。
    啟動後毫秒級隨機送訊號的壓力實測跑一輪要幾分鐘,不放進這支,數字記在代碼審 r3-fix.json、r4-fix.json。"""
    print("t_prepush_interrupt_stops_every_gate")
    import re, subprocess as sp, time as _time
    _need_src("scripts/hooks/pre-push")
    hook = Path(GRAPHCTL).resolve().parent / "hooks" / "pre-push"
    txt = hook.read_text(encoding="utf-8")
    entries = re.findall(r"^# 中斷就停:([a-z-]+)\|([^|\n]+)\|(.+)$", txt, flags=re.M)
    calls = [ln for ln in txt.splitlines() if re.match(r"^\s*pp_stop_if_signaled \"", ln)]
    check("①清單在、而且跟程式裡的 pp_stop_if_signaled 呼叫行數一樣多", len(entries) >= 9 and len(entries) == len(calls),
          f"清單 {len(entries)} 筆、呼叫 {len(calls)} 行")
    check("①刻意不接的也列在同一個區塊、各附理由", len(re.findall(r"^# 中斷不停:[^|\n]+\|.{4,}$", txt, flags=re.M)) >= 4, "")
    root, base, head = _ppc_repo()
    old_hook = root.with_name(root.name + "-oldhook")
    try:
        z = "0" * 40
        normal = f"refs/heads/main {head} refs/heads/main {base}\n"
        newbr = f"refs/heads/main {head} refs/heads/feat {z}\n"
        old_hook.write_text(re.sub(r"^[ \t]*pp_stop_if_signaled \".*\n", "", txt, flags=re.M), encoding="utf-8")
        # 推 tag 才會叫安全證據那一支:假 lumos 補上新版旗標字樣(掛鉤讀檔找它),那一筆改推 tag
        fake = root / "scripts" / "lumos"
        fake.write_text(fake.read_text(encoding="utf-8") + '\n# 新版:"--security-only"\n', encoding="utf-8")
        tag = f"refs/tags/v1 {head} refs/tags/v1 {z}\n"
        for cmd, name, _what in entries:
            stdin = newbr if cmd == "push-range" else (tag if "security-only" in name else normal)
            rc, lines, out = _ppc_run(root, stdin, FAKE_NEW="1", FAKE_SIG_CMD=cmd)
            last = lines[-1] if lines else ""
            want = cmd + " "
            check(f"②{_what}被殺掉 → 以那個回傳碼結束、講明、被殺掉的是最後一次呼叫、全套沒跑",
                  rc >= 128 and f"{name}被中斷(rc={rc})" in out and last.startswith(want) and "SUITE" not in lines,
                  f"rc={rc} last={last!r} {out[-300:]}")
            rc, lines, out = _ppc_run(root, stdin, hook=old_hook, FAKE_NEW="1", FAKE_SIG_CMD=cmd)
            check(f"③對照:拿掉停下的掛鉤,{_what}被殺掉時不會以 128 以上結束", rc < 128, f"rc={rc}")
        for sig, want in (("SIGTERM", 143), ("SIGINT", 130)):
            rc, lines, out = _ppc_run(root, normal, FAKE_NEW="1", FAKE_HOOK_SIG_CMD="home", FAKE_HOOK_SIG=sig)
            check(f"④掛鉤自己收到 {sig}(每支檔有家跑到一半)→ 那支結束後掛鉤以 {want} 結束、不再開始筆記形狀擋、全套沒跑",
                  rc == want and lines and lines[-1].startswith("home check") and "SUITE" not in lines,
                  f"rc={rc} {lines[-3:]} {out[-300:]}")
        tmp = root.with_name(root.name + "-tmp")
        outf = tmp / "bg.out"
        linger = 30.0   # 假全套送出訊號後睡這麼久:沒被收掉就是孤兒,遠長於下面等它消失的時限
        _pids_seen = []

        def _alive(pid):
            import os as _os
            try:
                _os.kill(pid, 0)
            except ProcessLookupError:
                return False
            except PermissionError:
                return True
            return True

        def _suite_run(sig, new_session, late=False):
            """起掛鉤、讓假全套在跑的時候送訊號 → (rc, 起掛鉤到掛鉤結束的秒數, 輸出, 假全套那片的 pid 或 None, 那片在時限內消失沒,
            那片自己起的孫行程在時限內消失沒)。
            ★孤兒判準不靠計時窗口★(代碼審 r2 邊界席):直接看那一片的 pid——掛鉤結束後 10 秒內還在就是孤兒。
            原本靠「假全套睡 4 秒後記 SUITE-END、測試在起掛鉤後第 5 秒讀」,負載下餘裕只剩約 0.3 秒,拿掉收片陷阱也照綠。"""
            (root / "argv.log").unlink(missing_ok=True)
            kw = dict(start_new_session=True, preexec_fn=_ppc_sigint_default) if new_session else {}
            with open(outf, "w") as fh:
                t0 = _time.monotonic()
                p = sp.Popen(["/bin/bash", str(hook)], cwd=str(root), stdin=sp.PIPE, stdout=fh, stderr=fh, text=True,
                             env=_ppc_env(root, {"FAKE_NEW": "1", "FAKE_SUITE_SIG": sig, "FAKE_SUITE_LINGER": str(linger),
                                                 **({"FAKE_SUITE_LATE_KID": "1"} if late else {})}), **kw)
                p.communicate(normal, timeout=120)
                took = _time.monotonic() - t0
            log_txt = (root / "argv.log").read_text(encoding="utf-8") if (root / "argv.log").exists() else ""
            mm = re.search(r"^SUITE-PID (\d+)$", log_txt, flags=re.M)
            pid = int(mm.group(1)) if mm else None
            mk = re.search(r"^SUITE-KID (\d+)$", log_txt, flags=re.M)
            kid = int(mk.group(1)) if mk else None
            ml = re.search(r"^SUITE-LATE (\d+)$", log_txt, flags=re.M)
            if late:   # 收到 TERM 才生的那個孫行程:要它也消失(沒生出來就當成沒消失,不讓情境不成立時照綠)
                kid = int(ml.group(1)) if ml else None
            gone = kid_gone = False
            if pid is not None and kid is not None:
                _pids_seen.extend((pid, kid))
                dl = _time.monotonic() + 10.0
                while (_alive(pid) or _alive(kid)) and _time.monotonic() < dl:
                    _time.sleep(0.05)
                gone, kid_gone = not _alive(pid), not _alive(kid)
            return p.returncode, took, outf.read_text(encoding="utf-8", errors="replace"), pid, gone, kid_gone

        def _tmp_left():
            return sorted(x.name for x in tmp.glob("lumos-prepush*"))
        try:
            # took 的上限是相對量:掛鉤要是等那一片跑完才結束,至少要 linger 秒;取一半當界線,負載下前面幾道閘慢幾秒也不會假紅
            rc, took, bg, pid, gone, kid_gone = _suite_run("1", False)
            check("⑤等全套測試時收到 TERM → 掛鉤立刻以 143 結束(不等背景那支跑完、不印測試結果)",
                  rc == 143 and pid is not None and took < linger / 2 and "條斷言過" not in bg and "測試有紅" not in bg,
                  f"rc={rc} took={took:.1f}s pid={pid} {bg[-300:]}")
            check("⑥被砍(TERM)之後,全套測試那一片也被收掉(掛鉤結束後 10 秒內那個 pid 就不在了)、TMPDIR 底下沒留 lumos-prepush 開頭的東西",
                  pid is not None and gone and not _tmp_left(), f"pid={pid} gone={gone} {_tmp_left()}")
            check("⑩被砍(TERM)之後,那一片自己起的孫行程也跟著收掉(各片自成一個行程群組、整組收)", kid_gone, f"pid={pid} kid_gone={kid_gone}")
            # 整組送 TERM 的那一刻片正好在 fork:剛生出來的孫行程沒收到那一發(代碼審 r4 併發席 1)。假片在收到 TERM 時才生一個孫行程,
            # 只送一發的話它一定變孤兒;短等後再送第二發才收得到。
            rc, took, bg, pid, gone, kid_gone = _suite_run("1", False, late=True)
            check("⑫整組送 TERM 時片正在生孫行程(收到 TERM 才生)→ 短等後的第二發把那個孫行程也收掉、掛鉤以 143 結束",
                  rc == 143 and pid is not None and kid_gone, f"rc={rc} pid={pid} kid_gone={kid_gone} {bg[-300:]}")
            rc, took, bg, pid, gone, kid_gone = _suite_run("INT", True)
            check("⑦等全套測試時按 Ctrl-C(整個行程群組收到 SIGINT)→ 掛鉤以 130 結束,全套那一片也被收掉、TMPDIR 底下沒留東西",
                  rc == 130 and pid is not None and took < linger / 2 and gone and not _tmp_left(),
                  f"rc={rc} took={took:.1f}s pid={pid} gone={gone} {_tmp_left()} {bg[-300:]}")
            check("⑩按 Ctrl-C 之後,那一片自己起的孫行程也跟著收掉", kid_gone, f"pid={pid} kid_gone={kid_gone}")
            rc, took, bg, pid, gone, kid_gone = _suite_run("HUP", False)
            check("⑨等全套測試時只對掛鉤送 SIGHUP(ssh、編輯器掛斷)→ 掛鉤以 129 結束,全套那一片也被收掉、TMPDIR 底下沒留東西",
                  rc == 129 and pid is not None and took < linger / 2 and gone and not _tmp_left(),
                  f"rc={rc} took={took:.1f}s pid={pid} gone={gone} {_tmp_left()} {bg[-300:]}")
            check("⑩掛斷之後,那一片自己起的孫行程也跟著收掉", kid_gone, f"pid={pid} kid_gone={kid_gone}")
            # 只對跑測試的子殼送 HUP(代碼審 r3 邊界席 2、合約席 3):主殼沒收到訊號,只能靠子殼自己的 HUP 陷阱收片;
            # 子殼結束碼非零,掛鉤當成測試沒過擋下(不能放行;擋下時照設計把測試 log 複製一份到 TMPDIR 給人看,所以不驗 TMPDIR 乾淨)
            rc, took, bg, pid, gone, kid_gone = _suite_run("SUBHUP", False)
            check("⑪跑測試的子殼自己收到 SIGHUP → 那一片與它的孫行程都收掉、掛鉤回 1 擋下(子殼 exit 129 → 當成測試沒過)",
                  rc == 1 and pid is not None and took < linger / 2 and gone and kid_gone,
                  f"rc={rc} took={took:.1f}s pid={pid} gone={gone} kid_gone={kid_gone} {bg[-300:]}")
        finally:
            import os as _os, signal as _signal
            for _pid in _pids_seen:   # 沒被收掉的孤兒(紅的時候)由這裡砍掉,不留給機器
                if _alive(_pid):
                    try:
                        _os.kill(_pid, _signal.SIGKILL)
                    except OSError:
                        pass
        for gate, cmd in (("anchor", "anchor"), ("doctor", "doctor")):
            rc, lines, out = _ppc_run(root, normal, FAKE_NEW="1", FAKE_RCS=f"{cmd}:2")
            check(f"⑧{gate} 回 2 → 照舊記成擋下(非零就擋)", rc == 1 and _ppc_rows(out) == [(gate, "")], f"rc={rc} {out[-300:]}")
    finally:
        _ppc_cleanup(root)
        old_hook.unlink(missing_ok=True)


_PPL_FAKE = r'''import os, sys, pathlib
out = pathlib.Path(os.environ["PPL_OUT"])
out.write_text("START %s %d %d\n" % (__name__, os.getpid(), os.getpgid(0) if hasattr(os, "getpgid") else -1), encoding="utf-8")
with out.open("a", encoding="utf-8") as fh:
    fh.write("ARGV %r\n" % (sys.argv,))
    fh.write("END\n")
sys.exit(int(sys.argv[1]))
'''


def t_prepush_interrupt_launcher_without_setpgid():
    """全套測試每片的啟動器(掛鉤的 _PP_OWN_PGRP)在沒有 os.setpgid 的 Python(原生 Windows)上也要照常把測試檔跑完、
    離開碼照實傳出(代碼審 r4 正確性席 1、併發席 2、通才席 1):原本無條件 setpgid → AttributeError、每片 rc1,推送永遠被擋,
    「紅的是這幾支」又是空的;就算繞過 setpgid,Windows 的 os.execv 是起新行程後讓舊的立刻結束(外層回 0),測試還沒跑完就判綠。
    判準(人判,不是照啟動器算):假測試檔的離開碼 0/3/1 原樣傳出(3 = 每片都選中 0 支,掛鉤靠它判「沒選中」);
    假測試檔真的跑到最後(寫下 END)、以 __main__ 身分跑、參數原樣收到。
    模擬 Windows:包一層先 del os.setpgid,並把 os.execv 換成「立刻以 0 結束」(Windows 上 execv 的外層語意)。
    setpgid 丟 OSError(不准換群組的環境)也要照跑。POSIX 對照:有 setpgid 時片自成一個群組(組號 = 自己的 pid)。
    翻紅釘:拿掉 hasattr 判斷 → ②紅(AttributeError rc1);沒 setpgid 時改走 execv → ②紅(rc0、沒寫 END)。"""
    print("t_prepush_interrupt_launcher_without_setpgid")
    import os, re, subprocess as sp
    _need_src("scripts/hooks/pre-push")
    txt = (Path(GRAPHCTL).resolve().parent / "hooks" / "pre-push").read_text(encoding="utf-8")
    mm = re.search(r"^[ \t]*_PP_OWN_PGRP='([^']*)'", txt, flags=re.M)
    launcher = mm.group(1) if mm else ""
    calls = [ln for ln in txt.splitlines() if not ln.lstrip().startswith("#")
             and ln.rstrip().endswith(" &") and '"$REPO_ROOT/scripts/test_lumos.py"' in ln]
    check("①前置:啟動器抽得到,而且全套測試的每個起片處都經過它", bool(launcher) and len(calls) >= 2
          and all('"$PY" -c "$_PP_OWN_PGRP" "$PY" ' in ln for ln in calls), f"{launcher!r} {calls}")
    d = Path(tempfile.mkdtemp(prefix="gctl-pplaunch-"))
    try:
        fake = d / "fake suite.py"
        fake.write_text(_PPL_FAKE, encoding="utf-8")
        out = d / "out.txt"
        win = ("import os\nif hasattr(os, 'setpgid'):\n    del os.setpgid\nos.execv = lambda *a: os._exit(0)\n"
               "exec(compile(%r, '<launcher>', 'exec'))\n" % launcher)
        eperm = ("import os, errno\ndef _no(*a):\n    raise PermissionError(errno.EPERM, 'no')\nos.setpgid = _no\n"
                 "exec(compile(%r, '<launcher>', 'exec'))\n" % launcher)
        for label, prog in (("沒有 os.setpgid(模擬 Windows)", win), ("setpgid 丟 OSError", eperm), ("POSIX 照常", launcher)):
            for want in (0, 3, 1):
                out.unlink(missing_ok=True)
                r = sp.run([sys.executable, "-c", prog, sys.executable, str(fake), str(want), "--suite", "a b"],
                           capture_output=True, text=True, timeout=60, env={**os.environ, "PPL_OUT": str(out)})
                got = out.read_text(encoding="utf-8") if out.exists() else ""
                check(f"②{label}:假測試檔離開碼 {want} 原樣傳出、跑到最後、以 __main__ 身分跑、參數原樣",
                      r.returncode == want and got.startswith("START __main__ ") and got.rstrip().endswith("END")
                      and f"ARGV {[str(fake), str(want), '--suite', 'a b']!r}" in got,
                      f"rc={r.returncode} out={got!r} err={r.stderr[-300:]!r}")
                if label == "POSIX 照常" and want == 3 and hasattr(os, "setpgid"):
                    st = got.split()
                    check("③POSIX 對照:有 setpgid 時那一片自成一個行程群組(組號 = 自己的 pid)",
                          len(st) >= 4 and st[2] == st[3], got)
    finally:
        import shutil
        shutil.rmtree(d, ignore_errors=True)


def t_prepush_collects_all_blocks():
    """[S1][S2] 用真的 lumos 跑推送前掛鉤(搭法沿用 t_prepush_cheap_gates_run_before_expensive_suite)。
    S1:圖譜健檢有壞連結、而且簽名檔改過沒提交 → 回 1,兩道的完整說明都印、彙總裡兩道都列出,全套沒被跑到。
    S2:只有圖譜健檢擋 → 回 1,印它原本的完整說明加彙總(1 筆 1 道閘),全套沒跑;都沒擋 → 照舊跑到全套、不印彙總。
    翻紅釘:圖譜健檢擋下改回 exit 1 → ①只剩一道而紅;判斷點拿掉 → ①③全套跑了而紅;彙總不印 → ①③紅。"""
    print("t_prepush_collects_all_blocks")
    import subprocess as _sp, os as _os, shutil as _sh
    hook = Path(GRAPHCTL).resolve().parent / "hooks" / "pre-push"
    if not hook.is_file():
        raise _SrcOnly("消費端沒有 pre-push(非來源 repo),這段沒驗到")
    lumos_real = Path(GRAPHCTL).resolve()

    def mk(break_graph):
        d = Path(tempfile.mkdtemp(prefix="gctl-ppcollect-"))
        _sp.run(["git", "init", "-b", "main", str(d)], capture_output=True)
        _sp.run(["git", "-C", str(d), "config", "user.email", "t@t"], capture_output=True)
        _sp.run(["git", "-C", str(d), "config", "user.name", "t"], capture_output=True)
        (d / "scripts").mkdir()
        (d / "scripts" / "lumos").symlink_to(lumos_real)
        (d / "skills" / "lumos-project-notes").mkdir(parents=True)
        marker = d / "EXPENSIVE-SUITE-RAN"
        for name in ("test_lumos.py", "test_autonomous_loop.py"):
            (d / "scripts" / name).write_text(
                f"from pathlib import Path\nPath({str(marker)!r}).write_text('ran')\nprint('FAKE ok')\n", encoding="utf-8")
        kg = d / "docs" / "t-knowledge" / "Systems"
        kg.mkdir(parents=True)
        bad = '\n  - "[[Systems/根本不存在的節點]]"' if break_graph else ""
        (kg / "a.md").write_text(f"---\ntype: system\nstatus: done\nrelated:{bad or ' []'}\nsummary: |-\n  KEY:測試用\n---\n# a\n",
                                 encoding="utf-8")
        (d / "governance").mkdir()
        _sp.run([sys.executable, str(lumos_real), "anchor", "approve", "--note", "fixture"], cwd=str(d), capture_output=True)
        _sp.run(["git", "-C", str(d), "add", "-A"], capture_output=True)
        _sp.run(["git", "-C", str(d), "commit", "-qm", "init"], capture_output=True)
        return d, marker

    def run(d):
        env = {k: v for k, v in _os.environ.items() if k != "LUMOS_PUSH_ATTEMPT"}
        env["GIT_DIR"] = str(d / ".git")
        return _sp.run(["/bin/bash", str(hook)], cwd=str(d), input="refs/heads/main dummy refs/heads/main dummy\n",
                       capture_output=True, text=True, env=env, timeout=300)
    d1, m1 = mk(break_graph=True)
    d2, m2 = mk(break_graph=False)
    try:
        bl = d1 / "governance" / "anchor-baseline.json"
        check("前置:現場真的產出簽名檔了", bl.is_file(), str(bl))
        bl.write_text(bl.read_text(encoding="utf-8") + "\n", encoding="utf-8")
        r = run(d1)
        rows = _ppc_rows(r.stderr) or []
        gates = [g for g, _ in rows]
        check("①S1 兩道同時擋:回 1、兩道的說明都印、全套沒跑", r.returncode == 1 and not m1.exists()
              and "知識庫健康檢查發現問題" in r.stderr and "簽名檔改過了但沒提交" in r.stderr,
              f"rc={r.returncode} {r.stderr[-600:]}")
        check("②S1 彙總裡兩道都列出(筆數、閘數照實算)", "doctor" in gates and "anchor-baseline" in gates
              and _ppc_header(r.stderr) == (len(rows), len(set(gates))) and len(rows) >= 2, f"{rows} {r.stderr[-600:]}")
        _sp.run(["git", "-C", str(d1), "checkout", "--", "governance/anchor-baseline.json"], capture_output=True)
        r = run(d1)
        check("③S2 只有圖譜健檢擋:回 1、印它原本的完整說明加彙總(1 筆 1 道閘)、全套沒跑",
              r.returncode == 1 and not m1.exists() and "知識庫健康檢查發現問題" in r.stderr and "三條路選一條" in r.stderr
              and _ppc_header(r.stderr) == (1, 1) and _ppc_rows(r.stderr) == [("doctor", "")], f"rc={r.returncode} {r.stderr[-600:]}")
        r = run(d2)
        check("④S2 都沒擋:照舊跑到全套、不印彙總", m2.exists() and _ppc_header(r.stderr) is None, f"rc={r.returncode} {r.stderr[-400:]}")
    finally:
        _sh.rmtree(d1, ignore_errors=True)
        _sh.rmtree(d2, ignore_errors=True)


def t_prepush_stops_without_python():
    """[S3] 找不到 Python 3.14 時,推送前掛鉤立刻結束:回 1、只印找不到 3.14 的說明,不收集、不往下跑
    (後面的閘一道都沒印、沒有彙總)。守的是既有行為不被改壞,改動前就是綠的。
    現場刻意讓簽名檔改過沒提交:掛鉤要是沒停、往下收集,那一道一定會印「簽名檔改過了但沒提交」。
    翻紅釘:找不到 3.14 那裡的 exit 1 改成 pp_record_block → 後面的閘照跑、印出別道的擋下句與彙總而紅。"""
    print("t_prepush_stops_without_python")
    import os as _os, tempfile as _tf, subprocess as _sp, shutil as _sh
    if not hasattr(_os, "setsid"):
        raise _SrcOnly("非 POSIX,這段沒驗到")
    _need_src("scripts/hooks/pre-push")
    hook = Path(GRAPHCTL).resolve().parent / "hooks" / "pre-push"
    tmp = Path(_tf.mkdtemp(prefix="gctl-ppnopy-"))
    try:
        nopy = _py314_sysbin(tmp)
        root = _py314_hook_repo(tmp / "a")
        (root / "governance").mkdir()
        (root / "governance" / "anchor-baseline.json").write_text("{}\n", encoding="utf-8")
        _sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
        _sp.run(["git", "-C", str(root), "commit", "-qm", "b", "--no-verify"], capture_output=True)
        (root / "governance" / "anchor-baseline.json").write_text("{}\n\n", encoding="utf-8")
        base = {k: v for k, v in _os.environ.items() if k not in ("LUMOS_PYTHON", "LUMOS_REEXEC_PYTHON", "GIT_DIR")}
        base.update(HOME=str(tmp), LUMOS_PYTHON_SEARCH_DIRS=str(tmp / "nowhere"), PATH=str(nopy))
        r = _sp.run(["/bin/bash", str(hook)], cwd=str(root), capture_output=True, text=True, input="", env=base, timeout=120)
        check("①找不到 3.14 → 回 1、印說明", r.returncode == 1 and "要用 Python 3.14" in r.stderr, r.stderr[-400:])
        check("②立刻結束:後面的閘一道都沒跑(沒有簽名檔那道的擋下句)、沒有彙總",
              "簽名檔改過了但沒提交" not in r.stderr and "這次推送共有" not in r.stderr and "簡版彙總" not in r.stderr
              and "負責把關的檔案" not in r.stderr, r.stderr[-600:])
    finally:
        _sh.rmtree(tmp, ignore_errors=True)


_CLKG_GOLD_A = ("  受波及合約測試:受波及合約的測試全綠(1 支)\n",
                "擋下:這次改動有 2 題效能檢核適用,但表態不完整(2 處)——分支 feat,版本 <SHA8>。\n  - kt-fake-a:沒有表態\n  - kt-fake-b:沒有表態\n"
                "在意的原因:題目推到眼前不等於有人回答;推送前每一題要有機器讀得懂的交代(做到了附證據/不適用附理由/待辦連 Issue),這不是審查,跟 tier 無關。\n"
                "接下來(適用題算在 <SHA>..<SHA>,樣板用同一個範圍):\n"
                "    lumos pitfalls --diff <SHA>..<SHA> --dispositions-template --carry > /tmp/disp.json   # 填完:\n"
                "    lumos code-loop dispositions /tmp/disp.json\n")
_CLKG_GOLD_B = ("",
                "⚠ code-loop check: BLOCKED——這次高風險改動還不能推(分支 feat,版本 <SHA8>):受波及合約的測試沒過:t_fake_contract(1 支紅)\n"
                "  受波及合約測試:受波及合約的測試沒過:t_fake_contract(1 支紅)\n"
                "  真的跑不了(外部 DB 不在、環境缺)→ 留痕跳過:\n"
                "    lumos code-loop check --diff <範圍> --skip-bound-tests --note \"<為什麼>\"\n")


def _clkg_last_blocks(out):
    ln = [ln for ln in out.splitlines() if ln.startswith("LUMOS-BLOCKS:")]
    return ln[-1] if ln else None


def t_code_loop_check_keep_going():
    """[S4] code-loop check --keep-going:表態不完整且有新增告警 → 兩個原因都印、回 1;合約測試紅且 tier=high 又沒留痕 → 兩個原因都印;
    不帶 --keep-going → 只印第一個,stdout 與 stderr 跟改動前一字不差(_CLKG_GOLD_A/B 是改動前用同一個現場錄下來的輸出)。
    帶旗標時多印一行 LUMOS-BLOCKS:(給掛鉤讀);--json 多一個 blocks 清單、reason 放第一筆、tier 是算出來的分級;
    治理帳照舊一次判定一筆 code-loop blocked,extra 帶 blocks 的種類清單;合約測試只是低風險提醒時不記成擋下、照印「只提醒不擋」。
    現場在行程內跑:判定函式「問別人」的那幾支換成假的(合約測試、表態、新增告警、pitfalls、留痕),判定函式與印訊息那段照真的跑。
    翻紅釘:keep-going 模式第一個擋下就回傳 → ③④紅;不帶旗標時也跑完四道 → ①紅(lint 被叫)、②紅;合約測試狀態句照第一個原因或整體 blocked 選 → ⑤b紅。"""
    print("t_code_loop_check_keep_going")
    import json as _j, subprocess as _sp
    root = _clkg_repo()
    try:
        rc, o, e, c = _clkg_run(root, keep_going=False, disp=True, lint=True)
        check("①不帶:表態+新增告警都會擋 → 只印表態那一個,新增告警閘沒跑,輸出跟改動前一字不差",
              rc == 1 and (o, e) == _CLKG_GOLD_A and ("lint",) not in c, f"rc={rc}\n{o!r}\n{e!r}")
        rc, o, e, c = _clkg_run(root, keep_going=False, bt="red", tier="high")
        check("②不帶:合約測試紅+tier=high 沒留痕 → 只印合約測試那一個,一字不差", rc == 1 and (o, e) == _CLKG_GOLD_B,
              f"rc={rc}\n{o!r}\n{e!r}")
        led = root / "docs" / ".governance-log.jsonl"
        n0 = len(led.read_text(encoding="utf-8").splitlines()) if led.exists() else 0
        rc, o, e, c = _clkg_run(root, keep_going=True, disp=True, lint=True)
        check("③帶:表態與新增告警兩個原因都印(原本的擋下句)、回 1",
              rc == 1 and "表態不完整(2 處)——分支 feat" in e and "這次改動帶進了新的問題(1 條新增的告警)" in e
              and "lumos lint-waive fp1" in e, e[-800:])
        check("③機讀行列出兩種", _clkg_last_blocks(o) == "LUMOS-BLOCKS: dispositions,lint_new", o[-300:])
        evs = [_j.loads(x) for x in led.read_text(encoding="utf-8").splitlines()[n0:] if x.strip()]
        cl = [x for x in evs if x.get("gate") == "code-loop" and x.get("kind") == "blocked"]
        check("③治理帳照舊一筆 code-loop blocked,extra 帶種類清單", len(cl) == 1 and cl[0].get("blocks") == ["dispositions", "lint_new"],
              str(evs)[:600])
        rc, o, e, c = _clkg_run(root, keep_going=True, bt="red", tier="high")
        check("④帶:合約測試紅且 tier=high 沒留痕 → 兩個原因都印、回 1", rc == 1 and "受波及合約的測試沒過" in e
              and "tier=high 且無留痕" in e, e[-800:])
        check("④機讀行", _clkg_last_blocks(o) == "LUMOS-BLOCKS: bound_tests,review", o[-300:])
        check("④合約測試記成擋下 → 印跳過指令,不印「只提醒不擋」", "--skip-bound-tests" in e and "只提醒不擋" not in e, e[-800:])
        rc, o, e, c = _clkg_run(root, keep_going=True, bt="red", advisory=True, disp=True)
        check("⑤低風險合約紅只是提醒+表態擋 → 只記表態、照印「只提醒不擋」",
              rc == 1 and _clkg_last_blocks(o) == "LUMOS-BLOCKS: dispositions" and "只提醒不擋" in e, o[-200:] + e[-600:])
        rc, o, e, c = _clkg_run(root, keep_going=True, bt="red", advisory=True, lint=True)
        check("⑤b低風險合約紅只是提醒+新增告警擋(第一個原因不是表態)→ 照印「只提醒不擋」,不印合約測試的跳過指令",
              rc == 1 and _clkg_last_blocks(o) == "LUMOS-BLOCKS: lint_new" and "只提醒不擋" in e and "--skip-bound-tests" not in e,
              o[-200:] + e[-600:])
        rc, o, e, c = _clkg_run(root, keep_going=True, bt="red", tier="high", as_json=True)
        v = _j.loads(o.strip().splitlines()[-1]) if o.strip() else {}
        check("⑥--json:blocks 兩筆、reason 是第一筆、tier 是算出來的 high", v.get("blocked") is True
              and [b.get("reason_kind") for b in v.get("blocks") or []] == ["bound_tests", "review"]
              and v.get("reason") == (v.get("blocks") or [{}])[0].get("reason") and v.get("tier") == "high", str(v)[:500])
        check("⑥--json:blocks 每筆只有 reason_kind、reason 兩個鍵(輸出契約;沒人讀的欄位不放,代碼審 r2 通才席)",
              bool(v.get("blocks")) and all(sorted(b) == ["reason", "reason_kind"] for b in v.get("blocks") or []), str(v.get("blocks"))[:400])
        rc, o, e, c = _clkg_run(root, keep_going=True)
        check("⑦帶旗標、沒有一道擋 → 回 0、機讀行是空的", rc == 0 and _clkg_last_blocks(o) == "LUMOS-BLOCKS: ", o[-300:])
        r = _sp.run([sys.executable, GRAPHCTL, "code-loop", "check", "--help"], capture_output=True, text=True)
        check("⑧code-loop check --help 有 --keep-going", "--keep-going" in r.stdout, r.stdout[-300:])
        check("⑧scripts/lumos 原始碼裡有 \"--keep-going\" 字樣(掛鉤讀檔找它判版本,不執行 --help)",
              '"--keep-going"' in Path(GRAPHCTL).read_text(encoding="utf-8"), "")
    finally:
        import shutil as _sh
        _sh.rmtree(root, ignore_errors=True)


def t_code_loop_keep_going_pass_sites_keep_blocks():
    """[S13] code-loop check --keep-going 已記下一筆擋下之後,走到 8 個放行站點的每一個都仍回 1:pitfalls 失敗、pitfalls 沒有 JSON、
    pitfalls 例外、tier 不是 high、留痕有效、留痕過時但屬簿記豁免、留痕要求被環境變數跳過、合併側放行;pitfalls 失敗(三種)時新增告警閘照跑。
    每個站點先跑一次「沒有先前的擋下」當前置:同一個現場回 0,證明真的走到那個放行站點。
    另掃判定函式原始碼:每個 return 要嘛是 _fin(...),要嘛是「緊接在 `if <變數>:` 底下、回傳由 kg.hit(...) 指派的那個變數」
    (不帶旗標時 hit 回的就是 fin(v);帶旗標時回 None,所以回傳前一定要判非空)。
    翻紅釘:任一站點直接 return 放行(不經 _fin)→ 那一站紅、原始碼守衛也紅;pitfalls 失敗時不跑新增告警閘 → ③紅;
    把 `if _stop: return _stop` 改成無條件 return _stop → ⑤紅(代碼審 r2 合約席 2)。"""
    print("t_code_loop_keep_going_pass_sites_keep_blocks")
    import ast
    # 原始碼守衛先跑:行為那段若因判定函式回 None 而例外,這一段照樣給得出結論
    src = Path(GRAPHCTL).read_text(encoding="utf-8")
    tree = ast.parse(src)
    fn = next((n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "_codeloop_guard_verdict"), None)
    bad = []
    # 「這一道擋下」的結果(收集分流 kg.hit(...) 指派的變數)也算經過收尾:hit 不帶旗標時回的就是 fin(v),帶旗標時回 None 不回傳
    via_hit = set()
    if fn is not None:
        for x in ast.walk(fn):
            if isinstance(x, ast.Assign) and isinstance(x.value, ast.Call) and isinstance(x.value.func, ast.Attribute) \
                    and x.value.func.attr == "hit":
                via_hit.update(tg.id for tg in x.targets if isinstance(tg, ast.Name))
    kg_src = ast.get_source_segment(src, next((n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == "_CodeloopKg"),
                                              ast.Pass())) or ""
    check("⑤前置:收集分流 hit 不帶旗標時回的是 self.fin(v)", "return self.fin(v)" in kg_src, kg_src[:300])

    # 回傳 hit 指派的變數時,緊鄰的外層要是 `if <那個變數>:`、而且 return 是那個 if 本體的第一句(帶旗標時 hit 回 None,
    # 無條件 return 會讓整個判定函式回 None、下游 .get 崩;代碼審 r2 合約席 2)。guarded 記下這種 return 的行號。
    guarded = set()

    def walk(node):
        for ch in ast.iter_child_nodes(node):
            if isinstance(ch, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
                continue
            if isinstance(ch, ast.If) and isinstance(ch.test, ast.Name) and ch.body and isinstance(ch.body[0], ast.Return) \
                    and isinstance(ch.body[0].value, ast.Name) and ch.body[0].value.id == ch.test.id:
                guarded.add(ch.body[0].lineno)
            if isinstance(ch, ast.Return):
                v = ch.value
                if not ((isinstance(v, ast.Call) and isinstance(v.func, ast.Name) and v.func.id == "_fin")
                        or (isinstance(v, ast.Name) and v.id in via_hit and ch.lineno in guarded)):
                    bad.append(ch.lineno)
            walk(ch)
    if fn is not None:
        walk(fn)
    n_ret = len([1 for x in ast.walk(fn) if isinstance(x, ast.Return)]) if fn is not None else 0
    check("⑤判定函式的每個 return 要嘛是 _fin(...),要嘛是緊接在 `if <變數>:` 底下回傳 hit 指派的那個變數",
          fn is not None and not bad and n_ret >= 8 and guarded, f"不合的行:{bad} 總數 {n_ret} 有判非空的 {sorted(guarded)}")
    root = _clkg_repo()
    try:
        sites = (("pitfalls 失敗", dict(pf="fail"), dict(bt="red")),
                 ("pitfalls 沒有 JSON", dict(pf="nojson"), dict(bt="red")),
                 ("pitfalls 例外", dict(pf="exc"), dict(bt="red")),
                 ("tier 不是 high", dict(tier="standard"), dict(disp=True)),
                 ("留痕有效", dict(tier="high", marker="same"), dict(disp=True)),
                 ("留痕過時但屬簿記豁免", dict(tier="high", marker="stale", exempt=True), dict(disp=True)),
                 ("留痕要求被環境變數跳過", dict(tier="high", env_skip=True), dict(disp=True)),
                 ("合併側放行", dict(tier="high", merge_pass=True), dict(disp=True)))
        for name, site, prior in sites:
            rc0, _o0, e0, _c0 = _clkg_run(root, keep_going=True, **site)
            check(f"①前置({name}):沒有先前的擋下 → 回 0(真的走到這個放行站點)", rc0 == 0, f"rc={rc0} {e0[-300:]}")
            rc, o, e, c = _clkg_run(root, keep_going=True, **site, **prior)
            want = "bound_tests" if "bt" in prior else "dispositions"
            check(f"②{name}:先記下一筆擋下 → 仍回 1、機讀行留著那一筆", rc == 1 and _clkg_last_blocks(o) == f"LUMOS-BLOCKS: {want}",
                  f"rc={rc} {o[-200:]} {e[-300:]}")
            if site.get("pf"):
                check(f"③{name}:新增告警閘照跑", ("lint",) in c, str(c))
        rc, o, e, c = _clkg_run(root, keep_going=True, pf="fail", bt="red", lint=True)
        check("④pitfalls 失敗時新增告警閘照判:合約紅+新增告警 → 兩筆都記", rc == 1
              and _clkg_last_blocks(o) == "LUMOS-BLOCKS: bound_tests,lint_new", o[-200:])
    finally:
        import shutil as _sh
        _sh.rmtree(root, ignore_errors=True)


def t_code_loop_keep_going_pf_fail_stricter():
    """pitfalls 失敗(回非零、沒有 JSON、例外)而這次改動帶進新告警:不帶 --keep-going 照舊整個 fail-open 放行、新增告警閘不跑;
    帶 --keep-going(推送前掛鉤認得就一律帶)時新增告警閘照跑、擋下 → 掛鉤實際走的路比直接跑 CLI 嚴。計劃〈做法〉5 寫明這個差異,
    這支把兩邊釘住。(代碼審 r1 正確性席 1)
    翻紅釘:keep-going 下 pitfalls 失敗時不跑新增告警閘 → ②紅;不帶旗標時也跑 → ①紅。"""
    print("t_code_loop_keep_going_pf_fail_stricter")
    root = _clkg_repo()
    try:
        for pf in ("fail", "nojson", "exc"):
            rc, o, e, c = _clkg_run(root, keep_going=False, pf=pf, lint=True)
            check(f"①pitfalls {pf}、不帶旗標 → 回 0 放行、新增告警閘沒跑", rc == 0 and ("lint",) not in c, f"rc={rc} {c} {e[-300:]}")
            rc, o, e, c = _clkg_run(root, keep_going=True, pf=pf, lint=True)
            check(f"②pitfalls {pf}、帶 --keep-going → 新增告警閘照跑並擋下、回 1、機讀行只有 lint_new",
                  rc == 1 and ("lint",) in c and _clkg_last_blocks(o) == "LUMOS-BLOCKS: lint_new"
                  and "這次改動帶進了新的問題(1 條新增的告警)" in e, f"rc={rc} {o[-200:]} {e[-400:]}")
    finally:
        import shutil as _sh
        _sh.rmtree(root, ignore_errors=True)


# 種類由別的支(收集分流、收尾)轉手而不是自己產生的地方:值可以不是字面字串,但每支只准有這麼多處(多一處就是有人新開了轉手路)
_CL_REASON_KIND_CARRIERS = {"_CodeloopKg.hit": 1, "_codeloop_kg_finish": 1}


def _cl_reason_kind_sites(src):
    """掃 scripts/lumos 原始碼裡所有「設定 reason_kind」的地方(dict 字面的鍵、reason_kind= 關鍵字參數、x["reason_kind"] = 指派)
    → (字面種類的集合, 值不是字面字串的站點 [(所在函式, 行號)])。所在函式用「類別.方法」或函式名。"""
    import ast
    tree = ast.parse(src)
    kinds, nonlit = set(), []

    def val(owner, v):
        if isinstance(v, ast.Constant) and isinstance(v.value, str):
            kinds.add(v.value)
        else:
            nonlit.append((owner, v.lineno))

    def visit(node, owner):
        for ch in ast.iter_child_nodes(node):
            if isinstance(ch, ast.ClassDef):
                visit(ch, ch.name)
                continue
            if isinstance(ch, (ast.FunctionDef, ast.AsyncFunctionDef)):
                visit(ch, f"{owner}.{ch.name}" if owner and not owner.startswith("_fn:") else ch.name)
                continue
            if isinstance(ch, ast.Dict):
                for k, v in zip(ch.keys, ch.values):
                    if isinstance(k, ast.Constant) and k.value == "reason_kind":
                        val(owner, v)
            elif isinstance(ch, ast.keyword) and ch.arg == "reason_kind":
                val(owner, ch.value)
            elif isinstance(ch, ast.Assign):
                for tg in ch.targets:
                    if isinstance(tg, ast.Subscript) and isinstance(tg.slice, ast.Constant) and tg.slice.value == "reason_kind":
                        val(owner, ch.value)
            visit(ch, owner)
    visit(tree, "")
    return kinds, nonlit


# 查不到種類時的通用句:照計劃〈做法〉5 逐字寫在這裡(不從掛鉤讀)
_PPC_KIND_FALLBACK = "代碼審判定擋下(細節在上面)"


def t_prepush_cl_reason_table_matches_lumos():
    """漂移守衛(結構測試,行為另由 t_prepush_block_kinds_each_recorded 驗):scripts/lumos 會產生的 reason_kind 集合,
    跟掛鉤 pp_cl_reason 對照表的種類集合要一樣(雙向:掛鉤少一種,新種類的彙總會退成通用句;掛鉤多一種,是沒人產生的死條目);
    每種的句子與查不到時的通用句照 _PPC_KIND_SENTENCES / _PPC_KIND_FALLBACK 逐字(正本是計劃〈做法〉5「對照表五句的正本在這裡」那段,不從掛鉤讀)。
    ★設定 reason_kind 的值一律要是字面字串★(代碼審 r2 合約席 4):種類若經變數或組字串產生,上面抽集合的那步抽不到,守衛會照綠;
    只有收集分流與收尾兩處轉手(_CL_REASON_KIND_CARRIERS)可以不是字面,而且各只准一處。
    原本 scripts/lumos 也存一份句子表(_CODELOOP_BLOCK_KIND_REASONS)給 JSON 的 summary 欄位用,沒有任何程式讀它,r2 拿掉。
    翻紅釘:掛鉤加一種或刪一種 → ①紅;lumos 新增一種 reason_kind 沒補掛鉤 → ①紅;掛鉤改一句 → ②紅;
    產生種類改成變數傳入 → ③紅。"""
    print("t_prepush_cl_reason_table_matches_lumos")
    import re
    _need_src("scripts/hooks/pre-push")
    hook = (Path(GRAPHCTL).resolve().parent / "hooks" / "pre-push").read_text(encoding="utf-8")
    mm = re.search(r"^pp_cl_reason\(\) \{\n(.*?)^\}", hook, flags=re.M | re.S)
    body = mm.group(1) if mm else ""
    hk = dict(re.findall(r"^\s+([a-z_]+)\) echo \"([^\"]+)\" ;;$", body, flags=re.M))
    hf = re.findall(r"^\s+\*\) echo \"([^\"]+)\" ;;$", body, flags=re.M)
    emitted, nonlit = _cl_reason_kind_sites(Path(GRAPHCTL).read_text(encoding="utf-8"))
    check("①scripts/lumos 會產生的 reason_kind 跟掛鉤對照表的種類一樣(掛鉤沒少、也沒多)",
          bool(hk) and bool(emitted) and set(hk) == emitted, f"產生 {sorted(emitted)} 掛鉤 {sorted(hk)}")
    check("②掛鉤每種的句子與通用句跟計劃定稿逐字一致",
          hk == {k: _PPC_KIND_SENTENCES[k] for k in hk if k in _PPC_KIND_SENTENCES} and set(hk) <= set(_PPC_KIND_SENTENCES)
          and hf == [_PPC_KIND_FALLBACK], f"掛鉤 {hk} 通用句 {hf}")
    from collections import Counter
    per = Counter(owner for owner, _ln in nonlit)
    stray = [(o, ln) for o, ln in nonlit if o not in _CL_REASON_KIND_CARRIERS]
    over = {o: n for o, n in per.items() if o in _CL_REASON_KIND_CARRIERS and n > _CL_REASON_KIND_CARRIERS[o]}
    check("③設定 reason_kind 的值都是字面字串(只有收集分流與收尾各一處轉手例外)", not stray and not over,
          f"不是字面的:{stray} 轉手處超量:{over}")


