def t_lumos_parses_under_old_grammar():
    """[S7] scripts/lumos、merge-claude-settings.py、scripts/hooks/claude/*.py 仍要能被 3.9 語法解析:ruff(py39)查語法錯誤、
    先用一行 3.12 才合法的樣本證明 ruff 真的會報;找得到真的舊版直譯器就實際編譯;兩者都沒有就明說沒驗到。
    另外守版本檢查之前的 import 只用 3.9 就有的模組(翻紅釘:檔頭加 import tomllib → 最後一格紅)。"""
    print("t_lumos_parses_under_old_grammar")
    import shutil as _sh, subprocess as _sp, tempfile as _tf, glob as _g
    repo = Path(GRAPHCTL).resolve().parent.parent
    files = [str(repo / "scripts" / "lumos"), str(repo / "scripts" / "merge-claude-settings.py")] + \
        sorted(_g.glob(str(repo / "scripts" / "hooks" / "claude" / "*.py")))
    verified = False
    ruff = _sh.which("ruff")
    if ruff:
        tmp = Path(_tf.mkdtemp(prefix="gctl-s7-"))
        sample = tmp / "pep701.py"
        sample.write_text('d = {"a": 1}\nx = f"{d["a"]}"\n', encoding="utf-8")
        r0 = _sp.run([ruff, "check", "--isolated", "--target-version", "py39", "--select", "E9", str(sample)],
                     capture_output=True, text=True)
        check("ruff 對 3.12 才合法的 f-string 樣本真的會報(守衛不是空的)", r0.returncode != 0, r0.stdout[-200:])
        r = _sp.run([ruff, "check", "--isolated", "--target-version", "py39", "--select", "E9", *files],
                    capture_output=True, text=True)
        check("ruff(py39):三類檔沒有 3.9 解析不了的語法", r.returncode == 0, r.stdout[-400:])
        verified = True
    old = _py314_old_interpreter()
    if old:
        ver = _sp.run([old, "-c", "import sys;print(sys.version_info[:2] < (3, 12))"], capture_output=True, text=True).stdout.strip()
        r = _sp.run([old, "-c", "import sys\nfor f in sys.argv[1:]:\n    compile(open(f, encoding='utf-8').read(), f, 'exec')\nprint('OK')",
                     *files], capture_output=True, text=True)
        check("真的舊版直譯器編譯三類檔", r.returncode == 0 and "OK" in r.stdout, r.stderr[-400:])
        verified = verified or ver == "True"
    if not verified:
        print("  (沒驗到:這台機器沒有 ruff、也沒有 3.12 以前的直譯器,3.9 能不能解析這一格沒有真的查)")
    # 語法之外的另一半:版本檢查之前會執行到的 import 只准用 3.9 就有的標準庫模組。ruff 只查語法,
    # 在檔頭多 import 一個 3.11 才有的 tomllib,ruff 照綠、3.9 啟動卻在印出「需要 3.14」之前就炸(代碼審 r1)。
    # 要加新模組:確認 3.9 標準庫有它,再加進下面的清單。
    import ast as _ast
    ok39 = {"__future__", "argparse", "bisect", "collections", "glob", "json", "os", "pathlib", "re", "shlex", "shutil", "subprocess",
            "sys", "time", "unicodedata", "uuid"}
    for rel, end in (("scripts/lumos", "# ── python-floor gate end ──"), ("scripts/merge-claude-settings.py", "    _py_floor_gate()")):
        text = (repo / rel).read_text(encoding="utf-8")
        head = text[:text.index(end) + len(end)] if end in text else None
        mods = set()
        if head is not None:
            for n in _ast.walk(_ast.parse(head)):
                if isinstance(n, _ast.Import):
                    mods |= {a.name.split(".")[0] for a in n.names}
                elif isinstance(n, _ast.ImportFrom):
                    mods.add((n.module or "").split(".")[0])
        check(f"{rel}:版本檢查之前只 import 3.9 就有的標準庫模組", head is not None and mods <= ok39,
              f"找不到版本檢查的位置" if head is None else f"清單外:{sorted(mods - ok39)}")


def t_doctor_flags_stale_hook_python():
    """[S10] Claude/Codex 設定裡註冊的直譯器不存在或低於 3.14 → doctor 印軟提醒(不計 issues、--ci 不跑)叫人重跑安裝;
    enforcement 的 python 列列出註冊的直譯器與結果(Projects/最低Python版本改3.14_計劃 做法第 9 點)。
    只看 lumos 自己註冊的那幾條:別的工具的掛鉤不列、不執行(代碼審 r1:第一版把任何含 hooks/ 的命令都拿去跑 -c 探針)。
    翻紅釘:Q 段拿掉 → ②紅;計進 issues → ③紅;enforcement 不讀註冊 → ⑤紅;不篩自家掛鉤 → ⑥紅;
    正規式不收結尾 t 或不看目錄 → ⑦⑧紅;enforcement 多一個名單外的檔名 → ⑨紅;
    Codex 那一家的目錄判斷拿掉、或合併程式改了命令形狀 → ⑩紅。"""
    print("t_doctor_flags_stale_hook_python")
    import os as _os, json as _j, tempfile as _tf, subprocess as _sp
    m = _load_lumos_inproc()
    tmp = Path(_tf.mkdtemp(prefix="gctl-s10-"))
    old = tmp / "python3.9"
    old.write_text("#!/bin/sh\necho 'OLD 3.9.6'\nexit 1\n", encoding="utf-8")
    old.chmod(0o755)

    def settings(home, exes):
        d = home / ".claude"
        d.mkdir(parents=True, exist_ok=True)
        names = ("lumos-entry-hook.py", "impact-hook.py", "ci-status-hook.py")
        hooks = {"SessionStart": [{"hooks": [{"type": "command", "command": f'{e} "${{HOME}}/.claude/hooks/{names[i]}"'}
                                             for i, e in enumerate(exes)]}]}
        (d / "settings.json").write_text(_j.dumps({"hooks": hooks}), encoding="utf-8")
    bad = tmp / "bad"
    settings(bad, ["/nonexistent/python3.14", str(old)])
    fine = tmp / "fine"
    settings(fine, [sys.executable])
    seen, probs = m._hook_python_problems(bad)
    check("①不存在的路徑與舊版都列成問題", len(probs) == 2 and any("不存在" in p for p in probs) and any("3.9.6" in p for p in probs),
          str(probs))
    check("①註冊的是 3.14 時沒有問題", m._hook_python_problems(fine)[1] == [], str(m._hook_python_problems(fine)))
    v = mkvault()
    base = {k: val for k, val in _os.environ.items() if k not in ("CODEX_HOME",)}
    r_bad = _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "doctor"], capture_output=True, text=True,
                    env=dict(base, HOME=str(bad)))
    r_fine = _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "doctor"], capture_output=True, text=True,
                     env=dict(base, HOME=str(fine)))
    out = r_bad.stdout + r_bad.stderr
    check("②doctor 印軟提醒叫人重跑安裝", "掛鉤註冊的直譯器不見了或低於 3.14" in out and "lumos install" in out, out[-500:])
    import re as _re

    def n_issues(r):
        mm = _re.search(r"發現 (\d+) 個 issue|— (\d+) issues", r.stdout)
        return int(mm.group(1) or mm.group(2)) if mm else None
    check("③軟提醒不計 issues(收尾那行的問題數跟沒問題時一樣;doctor 不加 --strict 時回傳碼恆為 0,比回傳碼驗不到)",
          n_issues(r_bad) is not None and n_issues(r_bad) == n_issues(r_fine), f"bad={n_issues(r_bad)} fine={n_issues(r_fine)}")
    r_ci = _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "doctor", "--ci"], capture_output=True, text=True,
                   env=dict(base, HOME=str(bad)))
    check("④doctor --ci 不跑這段", "掛鉤註冊的直譯器不見了" not in r_ci.stdout + r_ci.stderr, "")
    rows = m.enforcement_status(root=tmp, home=bad)
    py = [x for x in rows if x["layer"] == "python"]
    check("⑤enforcement 的 python 列列出註冊的直譯器與問題(狀態維持 active,不動既有的分母;提醒交給 doctor Q 段)",
          py and py[0]["status"] == "active" and "/nonexistent/python3.14" in py[0]["detail"] and "重跑 lumos install" in py[0]["detail"],
          str(py))
    other = tmp / "other"
    (other / ".claude" / "hooks").mkdir(parents=True)
    side = tmp / "side-effect.log"
    notify = other / ".claude" / "hooks" / "notify.sh"
    notify.write_text(f'#!/bin/sh\necho "RAN $1" >> "{side}"\n', encoding="utf-8")
    notify.chmod(0o755)
    third = [str(notify), f'bash "{notify}"', 'if [ -f "$HOME/.orca/agent-hooks/x.sh" ]; then bash x; fi',
             f'{notify} "${{HOME}}/.claude/hooks/lumos-entry-hook.py"']
    (other / ".claude" / "settings.json").write_text(_j.dumps({"hooks": {"Stop": [{"hooks": [
        {"type": "command", "command": c} for c in third]}]}}), encoding="utf-8")
    seen, probs = m._hook_python_problems(other)
    check("⑥別的工具的掛鉤(直接寫腳本、bash 包一層、shell 條件式、第一段不是 python)不列、不執行",
          seen == [] and probs == [] and not side.exists(), f"{seen} {probs} side={side.exists()}")
    mix = tmp / "mix"
    (mix / ".claude").mkdir(parents=True)
    (mix / ".claude" / "settings.json").write_text(_j.dumps({"hooks": {"Stop": [{"hooks": [
        {"type": "command", "command": '/nonexistent/python3.14t "${HOME}/.claude/hooks/impact-hook.py"'},
        {"type": "command", "command": '/nonexistent/python3.13 /opt/other/lumos-entry-hook.py'},
        {"type": "command", "command": '/nonexistent/python3.12 /tmp/foreign/.claude/hooks/ci-status-hook.py'}]}]}}), encoding="utf-8")
    seen, probs = m._hook_python_problems(mix)
    check("⑦free-threaded 的 python3.14t 註冊也認得;⑧別的目錄(含別人家目錄底下的 .claude/hooks)裡同名的檔不算自家掛鉤",
          [e for _f, e, _w in seen] == ["/nonexistent/python3.14t"], str(seen))
    import re as _re2
    src = Path(GRAPHCTL).read_text(encoding="utf-8")
    body = src[src.index("def enforcement_status("):]
    body = body[:body.index("\ndef ", 10)]
    needles = set(_re2.findall(r'\("[\w-]+", "([\w.-]+\.py)"\)', body))
    check("⑨enforcement 各列找的掛鉤檔名都在自家掛鉤名單裡(名單只有一份)",
          len(needles) >= 5 and needles <= m._own_hook_scripts(), f"{sorted(needles)} vs {sorted(m._own_hook_scripts())}")
    merge = Path(GRAPHCTL).resolve().parent / "merge-claude-settings.py"
    real = tmp / "real"
    real.mkdir()
    menv = dict(base, HOME=str(real), CODEX_HOME=str(real / ".codex"))
    menv.pop("LUMOS_PYTHON", None)
    rc = [_sp.run([sys.executable, str(merge), *t], capture_output=True, text=True, env=menv).returncode
          for t in ([], ["--target", "codex"])]
    saved_ch = _os.environ.pop("CODEX_HOME", None)
    try:
        seen, probs = m._hook_python_problems(real)
    finally:
        if saved_ch is not None:
            _os.environ["CODEX_HOME"] = saved_ch
    fams = {f for f, _e, _w in seen}
    check("⑩拿合併程式真的寫出的兩家設定來餵:Claude 與 Codex 的註冊都認得、都判合格(安裝端改了命令形狀就會紅)",
          rc == [0, 0] and fams == {"claude", "codex"} and probs == [] and all(w == "合格" for _f, _e, w in seen),
          f"rc={rc} seen={seen} probs={probs}")


def t_update_prints_python314_notice_and_slim_strips_floor():
    """[S9] 新版 lumos 執行 update、消費專案的 pre-commit 還是舊的(沒有 python-path)→ 印一段升級注意,之後再更新不印;
    CI 裡找不到 3.14 時,說明多一行 setup-python 怎麼設;精簡版生成器的產物不含開頭那三行版本檢查
    (Projects/最低Python版本改3.14_計劃 做法第 8、10 點)。
    ★前提講明★:①② 直接呼叫新版的 _vendor_toolchain,等於「執行 update 的已經是新程式」——同一台機器第二個專案起才是這樣。
    第一個專案的 update 由拉新之前就載進記憶體的舊程式執行,印不出升級注意(代碼審 r1);那一段靠 ④:失敗現場自己講清楚。
    翻紅釘:升級注意拿掉 → ①紅;不看舊 pre-commit 一律印 → ②紅;生成器不剝 → ③紅;CI 那行拿掉 → ④紅。"""
    print("t_update_prints_python314_notice_and_slim_strips_floor")
    import os as _os, io as _io, contextlib as _cl, tempfile as _tf, subprocess as _sp
    tmp = Path(_tf.mkdtemp(prefix="gctl-s9-"))
    src = tmp / "src"
    (src / "scripts" / "hooks").mkdir(parents=True)
    (src / "scripts" / "install-graph-toolchain.sh").write_text("#!/bin/sh\n", encoding="utf-8")
    (src / "scripts" / "hooks" / "pre-commit").write_text("#!/bin/bash\n# 新版:問 lumos python-path\n", encoding="utf-8")
    (src / "scripts" / "templates").mkdir()
    (src / "scripts" / "templates" / "graph-discipline.md").write_text("紀律:{{KG}}", encoding="utf-8")
    _sp.run(["git", "-C", str(src), "init", "-q"], capture_output=True)
    root = tmp / "consumer"
    (root / "scripts" / "hooks").mkdir(parents=True)
    (root / "scripts" / "hooks" / "pre-commit").write_text("#!/bin/bash\nCC_PY=\"$(command -v python3)\"\n", encoding="utf-8")
    _sp.run(["git", "-C", str(root), "init", "-q"], capture_output=True)
    saved = {k: _os.environ.get(k) for k in ("HOME", "LUMOS_HOME", "CODEX_HOME")}
    outs = []
    try:
        _os.environ.update(HOME=str(tmp / "home"), LUMOS_HOME=str(src), CODEX_HOME=str(tmp / "home" / ".codex"))
        (tmp / "home").mkdir()
        for _ in range(2):
            mod = _load_lumos_mod("lumos_s9")
            buf = _io.StringIO()
            with _cl.redirect_stdout(buf), _cl.redirect_stderr(_io.StringIO()):
                mod._vendor_toolchain(src, root, "consumer", no_pull=True)
            outs.append(buf.getvalue())
    finally:
        for k, v in saved.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v
    check("①從舊版更新上來:印升級注意(要 3.14、CI、LUMOS_PYTHON、重跑 install)", "升級注意" in outs[0] and "3.14" in outs[0]
          and "LUMOS_PYTHON" in outs[0] and "lumos install" in outs[0], outs[0][-500:])
    check("②已經是新版再更新:不印", "升級注意" not in outs[1], outs[1][-300:])
    repo = Path(GRAPHCTL).resolve().parent.parent
    dist = tmp / "dist-lumos"
    r = _sp.run([sys.executable, str(repo / "scripts" / "slim-gen.py"), "--outfile", str(dist)], capture_output=True, text=True)
    body = dist.read_text(encoding="utf-8") if dist.exists() else ""
    check("③精簡版產物不含開頭版本檢查的呼叫", r.returncode == 0 and bool(body)
          and 'if __name__ == "__main__":\n    _py_floor_gate()' not in body, r.stderr[-300:])
    m = _load_lumos_inproc()
    saved = {k: _os.environ.get(k) for k in ("CI", "GITHUB_ACTIONS")}
    try:
        for k in saved:
            _os.environ.pop(k, None)
        local = m._py_floor_message([("python3", "版本 3.9.6,低於 3.14")])
        _os.environ["GITHUB_ACTIONS"] = "true"
        ci = m._py_floor_message([("python3", "版本 3.9.6,低於 3.14")])
    finally:
        for k, v in saved.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v
    check("④CI 裡找不到 3.14:說明多一行 setup-python 設 3.14;本機不印這行", "setup-python" in ci and '"3.14"' in ci
          and "setup-python" not in local, ci[-300:])


# ═══ 存量漂移守衛 乙:條件式回頭條件 ═══

def t_drift_when_gone_evaluates():
    """[S1] when-gone 在指定提交的樹上判:檔在不成立、刪掉成立;資料夾、連結檔、子模組算在;帶字串時字串在不成立、拿掉或刪檔
    成立;帶字串而路徑是資料夾、含 NUL、LFS 指標、不是 UTF-8(Big5)、讀不出都判不了,原因記下來、點名時講出來。"""
    print("t_drift_when_gone_evaluates")
    m = _load_lumos_inproc()
    root = _nh_repo()
    _nh_file(root, "src/a.py", "import time\nnow = time.time()\n")
    _nh_file(root, "src/lib/x.py", "x = 1\n")
    (root / "src" / "bin.dat").write_bytes(b"abc\0def time.time()")
    (root / "src" / "lfs.bin").write_bytes(b"version https://git-lfs.github.com/spec/v1\noid sha256:abc\nsize 3\n")
    (root / "src" / "big5.txt").write_bytes("時間到了 time.time()".encode("big5"))
    import os as _os
    _os.symlink("a.py", root / "src" / "link.py")
    _nh_commit(root, "tree")
    tip = _na_head(root)
    tr = m._drift_probe_tree(root, tip)
    cases = [("src/a.py", False), ("src/none.py", True), ("src/lib", False), ("src/link.py", False),
             ("src/a.py::time.time()", False), ("src/a.py::datetime.now()", True), ("src/none.py::time.time()", True)]
    bad = [(v, tr.one("gone", v)) for v, want in cases if tr.one("gone", v) is not want]
    check("①在/消失、資料夾與連結檔算在、字串在不在", not bad, bad)
    unknown = ["src/lib::x", "src/bin.dat::time.time()", "src/lfs.bin::oid", "src/big5.txt::time.time()", "src/link.py::time"]
    got = {v: tr.one("gone", v) for v in unknown}
    check("②帶字串讀不準的一律判不了", all(x is None for x in got.values()), got)
    whys = {v: tr.gone_why.get(v, "") for v in unknown}
    check("②判不了的原因記下來", "一般檔" in whys["src/lib::x"] and "NUL" in whys["src/bin.dat::time.time()"]
          and "LFS" in whys["src/lfs.bin::oid"] and "UTF-8" in whys["src/big5.txt::time.time()"], whys)
    note = m._drift_bad_note(m._drift_row_unread((("gone", "src/big5.txt::time.time()"),), (), (tr,)))
    check("③點名講出那支檔與原因", "src/big5.txt(不是 UTF-8)" in note, note)
    sub = m._DriftProbeTree(root, tip, set(), m._nodehome_layout([]), entries=["vendor/sub"])
    check("④子模組(樹上的條目、不是一般檔)算在", sub.gone("vendor/sub") is False and sub.gone("vendor/other") is True, "")
    _nh_git(root, "rm", "-q", "src/a.py")
    _nh_commit(root, "rm")
    tr2 = m._drift_probe_tree(root, _na_head(root))
    check("⑤刪掉檔:只帶路徑與帶字串的都成立", tr2.one("gone", "src/a.py") is True and tr2.one("gone", "src/a.py::time.time()") is True, "")


def t_drift_when_gone_push():
    """[S2] 推送刪掉 when-gone 指的字串或檔:點名「這次推送讓條件成立了」、不附打錯字提示;推送沒動那支檔不列;
    新寫一條而字串本來就不在檔裡:點名已經成立;新寫一條而路徑在終點就找不到:多附「路徑在這一版就找不到」。"""
    print("t_drift_when_gone_push")
    root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
    _nh_file(root, "src/a.py", "now = time.time()\n")
    _nh_file(root, "src/other.py", "x = 1\n")
    _nh_node(root, "Pay", summary="FLOW:a", body="REVISIT:[when-gone:src/a.py::time.time()][by:2099-12-31] 不再讀系統時間就拿掉警告")
    _nh_commit(root, "base")
    b0 = _na_head(root)
    _nh_file(root, "src/other.py", "x = 2\n")
    _nh_commit(root, "無關")
    rc, out = _dr(root, "check", "--diff", f"{b0}..HEAD")
    check("①推送沒動那支檔:不列", rc == 0 and "probe" not in out, out[-400:])
    b1 = _na_head(root)
    _nh_file(root, "src/a.py", "now = clock()\n")
    _nh_commit(root, "拿掉 time.time()")
    rc, out = _dr(root, "check", "--diff", f"{b1}..HEAD")
    check("②推送刪掉那段字:點名、不附打錯字提示", rc == 1 and "這次推送讓條件成立了" in out and "找不到" not in out, out[-500:])
    root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
    _nh_file(root, "src/a.py", "x = 1\n")
    _nh_node(root, "Pay", summary="FLOW:a", body="REVISIT:[when-gone:src/a.py][by:2099-12-31] 檔不見就收尾")
    _nh_commit(root, "base")
    b0 = _na_head(root)
    _nh_git(root, "rm", "-q", "src/a.py")
    _nh_commit(root, "刪檔")
    rc, out = _dr(root, "check", "--diff", f"{b0}..HEAD")
    check("③推送刪掉檔:點名、不附打錯字提示", rc == 1 and "這次推送讓條件成立了" in out and "找不到" not in out, out[-500:])
    b1 = _na_head(root)
    _nh_file(root, "src/b.py", "y = 1\n")
    _nh_node(root, "Pay", summary="FLOW:a", body="REVISIT:[when-gone:src/a.py][by:2099-12-31] 檔不見就收尾\n"
             "REVISIT:[when-gone:src/b.py::not_there][by:2099-12-31] 字串本來就不在\n"
             "REVISIT:[when-gone:src/typo.py][by:2099-12-31] 打錯字的路徑")
    _nh_commit(root, "新寫兩條")
    rc, out = _dr(root, "check", "--diff", f"{b1}..HEAD")
    check("④新寫而字串本來就不在:點名已經成立", rc == 1 and "src/b.py::not_there" in out and "條件已經成立" in out, out[-700:])
    typo = [ln for ln in out.split("\n") if "typo.py" in ln]
    check("⑤新寫而路徑在終點就找不到:多附提示", typo and any("這一版就找不到" in ln for ln in out.split("\n")), out[-700:])
    # ⑥不是程式檔(沒有程式形狀改變):刪掉資料夾裡的素材也要當候選——一般條件的候選篩選只看程式檔,when-gone 看路徑本身
    #   與以它為前綴的資料夾
    for label, target, rm in (("素材檔", "assets/old.txt", ["assets/old.txt"]), ("素材資料夾", "assets/icons", ["-r", "assets/icons"])):
        root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
        _nh_file(root, "assets/old.txt", "舊素材\n")
        _nh_file(root, "assets/icons/a.txt", "icon\n")
        _nh_node(root, "Pay", summary="FLOW:a", body=f"REVISIT:[when-gone:{target}][by:2099-12-31] 舊素材拿掉就收尾")
        _nh_commit(root, "base")
        b0 = _na_head(root)
        _nh_git(root, "rm", "-q", *rm)
        _nh_commit(root, "刪素材")
        rc, out = _dr(root, "check", "--diff", f"{b0}..HEAD")
        check(f"⑥刪掉{label}(不是程式檔):點名", rc == 1 and "這次推送讓條件成立了" in out, (label, out[-500:]))


def t_drift_when_gone_grammar():
    """[S3][S5] when-gone 的寫法:路徑 / 開頭、含 ..(含反斜線寫法)、字串空、標記內反引號都報條件寫錯;合格不擋;字串從第一個
    :: 切、反斜線原樣、兩端空白去掉。列舉條件鍵的訊息與文件都提到每個鍵,本 repo 的紀律區塊跟範本一致。"""
    print("t_drift_when_gone_grammar")
    import inspect
    m = _load_lumos_inproc()
    for label, ln in [("/ 開頭", "REVISIT:[when-gone:/a.py][by:2099-01-01] x"),
                      ("..", "REVISIT:[when-gone:../a.py][by:2099-01-01] x"),
                      ("反斜線 ..", "REVISIT:[when-gone:a\\..\\x.py][by:2099-01-01] x"),
                      ("字串空", "REVISIT:[when-gone:a.py::][by:2099-01-01] x"),
                      ("反引號", "REVISIT:[when-gone:a.py::`t()` x][by:2099-01-01] x")]:
        v = m._ns_revisit_violations(ln, "body", True)
        check(f"①{label}:報條件寫錯", [r for r, _f, _x in v] == ["條件寫錯"], (label, v))
    check("②合格:不報", m._ns_revisit_violations("REVISIT:[when-gone:src/a.py::time.time()][by:2099-01-01] x", "body", True) == [], "")
    pr = m._probe_parse("[when-gone:src\\a.py::  Foo::bar\\n  ][by:2099-01-01] x")
    check("③從第一個 :: 切、路徑反斜線轉斜線、字串反斜線原樣、兩端空白去掉", pr["conds"] == [("gone", "src/a.py::Foo::bar\\n")]
          and m._drift_cond_split(pr["conds"][0][1], "gone") == ("src/a.py", "Foo::bar\\n"), pr)
    msgs = [m._probe_value_err("bogus", "x"), m._slot_retire_err("亂寫")]     # 兩句訊息各自要列全
    hint = inspect.getsource(m)  # 提示那段在筆記形狀擋的否定現況句提醒裡
    i = hint.index("條件怎麼選:")
    hint = hint[i:i + 600]
    root = _repo_root_for_discipline()
    docs = [(root / "skills" / "lumos-project-notes" / "commands" / "03-寫回圖譜.md").read_text(encoding="utf-8"),
            (root / "skills" / "lumos-project-notes" / "reference.md").read_text(encoding="utf-8"),
            (root / "scripts" / "templates" / "graph-discipline.md").read_text(encoding="utf-8")]
    targets = [("值驗證訊息", msgs[0].replace("、", " when-")), ("撤除條件訊息", msgs[1]), ("提醒", hint), ("03", docs[0]),
               ("reference", docs[1]), ("範本", docs[2])]
    miss = [(k, n) for k in m._PROBE_KEYS for n, t in targets if f"when-{k}" not in t and f"只有 {k}" not in t]
    check("④列舉條件鍵的訊息、提醒、文件都提到每個鍵", not miss, miss)
    claude = (root / "CLAUDE.md").read_text(encoding="utf-8")
    check("⑤本 repo 紀律區塊跟範本一致(帶 when-gone)", "when-gone:路徑[::字串]" in claude
          and "when-gone:路徑[::字串]" in (root / "AGENTS.md").read_text(encoding="utf-8"), "")


def t_drift_when_gone_retire():
    """[S4] RULE 撤除條件 [retire:when-gone:src/a.py]:只有路徑合格;推送刪掉那支檔點名撤除條件成立;撤除條件的 when-gone
    寫 ..\\x 或標記內有反引號照 REVISIT 那條路報錯。"""
    print("t_drift_when_gone_retire")
    m = _load_lumos_inproc()
    check("①只有路徑:合格", m._slot_retire_err("when-gone:src/a.py") is None, "")
    check("②..\\x:報錯", m._slot_retire_err("when-gone:..\\x.py") is not None
          and m._slot_retire_err("when-gone:a\\..\\x.py") is not None, "")
    check("③標記內反引號:報錯", "反引號" in (m._slot_retire_err("when-gone:a.py::`t()`") or ""), "")
    rule = "RULE:要人簽 [依據:人] [since:2026-09-01] [retire:when-gone:src/old.py]"
    root = _dr_repo()
    base = _rt_push(root, [rule], files=("src/old.py",), msg="rule")
    _nh_git(root, "rm", "-q", "src/old.py")
    _nh_commit(root, "刪檔")
    rc, out = _dr(root, "check", "--diff", f"{base}..{_na_head(root)}")
    check("④推送刪掉那支檔:點名撤除條件成立", rc == 1 and "撤除條件成立" in out, out[-500:])


def t_drift_when_gone_review_r1():
    """代碼審 r1:反引號檢查只看真正的 [when-gone: 標記(說明文字提到 when-gone: 後面有行內程式碼不算);字串含 [ 報錯(會被
    第一個 ] 截斷);帶字串的大檔不整份讀進記憶體(git 與工作目錄兩種模式);讀不出判不了;工作目錄模式照樣判;預算用完判不了。"""
    print("t_drift_when_gone_review_r1")
    import time as _time
    m = _load_lumos_inproc()
    ok = "REVISIT:[when-file:src/a.py][by:2099-01-01] 寫法見 when-gone: 用 `[when-gone:路徑]` 那種"
    check("①說明文字提到 when-gone: 後面有行內程式碼:不報", m._ns_revisit_violations(ok, "body", True) == [], m._ns_revisit_violations(ok, "body", True))
    check("①前提:真正的標記內有反引號照報", m._ns_revisit_violations("REVISIT:[when-gone:a.py::`t`][by:2099-01-01] x", "body", True) != [], "")
    check("②字串含 [ 報錯(REVISIT 與撤除條件)", m._probe_check_value("gone", "a.py::x[1")[1] is not None
          and m._slot_retire_err("when-gone:a.py::x[1") is not None, "")
    root = _nh_repo()
    big = b"time.time()\n" + b"x" * (3 * 1048576)
    (root / "src").mkdir(parents=True, exist_ok=True)
    (root / "src" / "big.py").write_bytes(big)
    _nh_file(root, "src/a.py", "now = time.time()\n")
    _nh_commit(root, "big")
    tip = _na_head(root)
    for where in (tip, "disk"):
        tr = m._drift_probe_tree(root, where)
        got = tr.one("gone", "src/big.py::time.time()")
        held = tr._raw.get("src/big.py")
        check(f"③大檔({where[:6]}):判不了、沒整份讀進記憶體", got is None and not (isinstance(held, bytes) and len(held) > 2 * 1048576)
              and "MB" in tr.gone_why.get("src/big.py::time.time()", ""), (where, got, type(held), tr.gone_why))
    tr = m._drift_probe_tree(root, "disk")
    check("④工作目錄模式照樣判", tr.one("gone", "src/a.py::time.time()") is False and tr.one("gone", "src/a.py::nope") is True, "")
    tr = m._drift_probe_tree(root, tip)
    real = m._nodehome_cat_blobs_capped
    m._nodehome_cat_blobs_capped = lambda *a, **k: [None] * len(a[1])
    try:
        got = tr.one("gone", "src/a.py::time.time()")
    finally:
        m._nodehome_cat_blobs_capped = real
    check("⑤讀不出:判不了、記原因", got is None and "讀不出" in tr.gone_why.get("src/a.py::time.time()", ""), (got, tr.gone_why))
    tr = m._drift_probe_tree(root, "disk")
    tr.deadline = _time.monotonic() - 1
    check("⑥預算用完(工作目錄模式):判不了", tr.one("gone", "src/a.py::time.time()") is None, "")
    # ⑦when-file 指到資料夾的提示改用 is_dir(跟 when-gone 的「在」共用)後照舊:既有提示原本沒有測試守
    tr = m._drift_probe_tree(root, tip)
    pr = m._probe_parse("[when-file:src][by:2099-01-01] x")
    probs = m._drift_probe_row_problems(pr, m._drift_tree_env(root, tip, "docs/kg-knowledge"), tr)
    pr2 = m._probe_parse("[when-file:src/a.py][by:2099-01-01] x")
    probs2 = m._drift_probe_row_problems(pr2, m._drift_tree_env(root, tip, "docs/kg-knowledge"), tr)
    check("⑦when-file 指到資料夾照提示、指到檔不提示", any("指到資料夾" in x for x in probs) and not any("資料夾" in x for x in probs2), (probs, probs2))


def t_drift_when_gone_review_r2():
    """代碼審 r2:路徑含方括號(Next.js 的 app/[id]/page.tsx)在第一個 ] 被截斷、會對還在的檔誤判——四種帶路徑的鍵與撤除條件都報錯;
    反引號檢查跳過行內程式碼裡提到的 [when-gone:;工作目錄模式讀到一半預算用完就停;git 模式讀不出與超過上限分開講。"""
    print("t_drift_when_gone_review_r2")
    m = _load_lumos_inproc()
    for k, v in (("gone", "app/[id"), ("file", "app/[id"), ("symbol", "app/[id::f"), ("test", "app/[id::t")):
        check(f"①路徑含方括號報錯:{k}", m._probe_check_value(k, v)[1] is not None and "方括號" in (m._probe_check_value(k, v)[1] or ""),
              m._probe_check_value(k, v))
    check("①撤除條件也報", m._slot_retire_err("when-gone:app/[id") is not None and m._slot_retire_err("when-file:app/[id") is not None, "")
    v = m._ns_revisit_violations("REVISIT:[when-gone:app/[id]/page.tsx][by:2099-01-01] x", "body", True)
    check("①回頭條件行:報條件寫錯", [r for r, _f, _x in v] == ["條件寫錯"], v)
    ok = "REVISIT:[when-file:src/a.py][by:2099-01-01] 寫法是 `[when-gone:路徑` 開頭,見 [[Projects/X]]"
    check("②行內程式碼裡提到的 [when-gone: 不算標記", m._ns_revisit_violations(ok, "body", True) == [], m._ns_revisit_violations(ok, "body", True))
    check("②前提:真標記照擋", m._probe_gone_backtick_err("REVISIT:[when-gone:a.py::`t`][by:2099-01-01] x") is not None, "")
    root = _nh_repo()
    _nh_file(root, "src/a.py", "now = time.time()\n")
    _nh_file(root, "src/b.py", "x = 1\n")
    big = b"time.time()\n" + b"x" * (3 * 1048576)
    (root / "src" / "big.py").write_bytes(big)
    _nh_commit(root, "files")
    tr = m._drift_probe_tree(root, "disk")
    calls = [False, False, True]
    tr._over = lambda: calls.pop(0) if calls else True
    check("③工作目錄模式讀到一半預算用完:回 False、沒讀到的不記", tr._read_raw(["src/a.py", "src/b.py"]) is False
          and "src/b.py" not in tr._raw, tr._raw.keys())
    tr = m._drift_probe_tree(root, _na_head(root))
    tr.one("gone", "src/big.py::time.time()")
    real = m._nodehome_cat_blobs_capped
    m._nodehome_cat_blobs_capped = lambda *a, **k: [None] * len(a[1])
    try:
        tr2 = m._drift_probe_tree(root, _na_head(root))
        tr2.one("gone", "src/a.py::time.time()")
    finally:
        m._nodehome_cat_blobs_capped = real
    check("④git 模式:超過上限與讀不出分開講", "超過" in tr.gone_why.get("src/big.py::time.time()", "") and "讀不出" not in tr.gone_why.get("src/big.py::time.time()", "")
          and tr2.gone_why.get("src/a.py::time.time()", "") == "讀不出", (tr.gone_why, tr2.gone_why))


def _born_scan(root, *extra):
    """drift scan --json → ({(路徑, 原文裡的條件片段): born}, 文字輸出);born 沒有就是 None。"""
    import json as _j, subprocess as sp
    r = sp.run([sys.executable, GRAPHCTL, "drift", "scan", "--json", *extra], capture_output=True, text=True, cwd=str(root))
    try:
        fs = _j.loads(r.stdout)["findings"]
    except (ValueError, KeyError):
        return {("錯", "", r.stdout + r.stderr): None}, ""
    got = {}
    for f in fs:
        if f["kind"] in ("probe", "retire"):
            got[(f["path"], f["kind"], f["text"])] = f.get("born")
    t = sp.run([sys.executable, GRAPHCTL, "drift", "scan", *extra], capture_output=True, text=True, cwd=str(root))
    return got, t.stdout + t.stderr


def _born_of(got, path, needle, kind="probe"):
    for (p, k, t), b in got.items():
        if p == path and k == kind and needle in t:
            return b
    return "沒找到"


def t_drift_born_true_scan():
    """[S1] 寫下那一版條件就已成立的回頭條件:scan 文字在那一條底下印「寫下時就已成立」與寫下那一版的短編號、--json 的
    born.state=true、born.commit=寫下那一版;已表態的照印;寫下時不成立後來才成立的是 false、不印;RULE 撤除條件照同一套標。

    翻紅釘:在終點判(不往回找)→ 後來才成立的那條也變 true;已表態的不印 → ④紅。"""
    print("t_drift_born_true_scan")
    root = _dr_repo()
    _nh_file(root, "src/other.py", "x = 1\n")
    _nh_commit(root, "程式")
    _nh_node(root, "Pay", summary="FLOW:a\nRULE:要人簽 [依據:人] [since:2026-09-01] [retire:when-file:src/other.py]",
             body="REVISIT:[when-file:src/other.py][by:2099-12-31] 生來就成立的\n"
                  "REVISIT:[when-file:src/runner.py][by:2099-12-31] 後來才成立的")
    _nh_commit(root, "寫下")
    w1 = _na_head(root)
    _nh_file(root, "src/runner.py", "def main():\n    pass\n")
    _nh_commit(root, "加啟動程式")
    got, txt = _born_scan(root)
    b = _born_of(got, "Systems/Pay.md", "生來就成立")
    check("①生來就成立:state=true、commit=寫下那一版", isinstance(b, dict) and b.get("state") == "true"
          and b.get("commit") == w1 and b.get("date"), (b, got))
    b2 = _born_of(got, "Systems/Pay.md", "後來才成立")
    check("②後來才成立:state=false", isinstance(b2, dict) and b2.get("state") == "false", (b2, got))
    br = _born_of(got, "Systems/Pay.md", "要人簽", kind="retire")
    check("③RULE 撤除條件照同一套標", isinstance(br, dict) and br.get("state") == "true" and br.get("commit") == w1, (br, got))
    check("①文字輸出印「寫下時就已成立」與短編號,只印兩條(回頭條件、撤除條件)",
          txt.count("寫下時就已成立") == 2 and w1[:7] in txt, txt[-1500:])
    check("①訊息只講查到的:從那一版起連續出現,不講「第一次出現」(代碼審 r1 正確性席 F2)",
          f"{w1[:7]}" in txt and "起連續出現在這篇" in txt and "第一次出現" not in txt, txt[-1500:])
    import subprocess as sp
    line = next(i for i, ln in enumerate((root / "docs/kg-knowledge/Systems/Pay.md").read_text(encoding="utf-8").split("\n"), 1)
                if "生來就成立" in ln)
    r = sp.run([sys.executable, GRAPHCTL, "drift", "ack", "Systems/Pay", str(line), "--kind", "probe", "--reason", "照留觀察中"],
               capture_output=True, text=True, cwd=str(root))
    _nh_commit(root, "表態")
    got, txt = _born_scan(root)
    seg = txt[txt.find("生來就成立"):]
    check("④已表態的照印那一行", r.returncode == 0 and "(已表態)" in seg.split("\n")[0]
          and "寫下時就已成立" in "\n".join(seg.split("\n")[1:3]), (r.stdout + r.stderr, txt[-1500:]))
    check("④前提:JSON 照標 true", (_born_of(got, "Systems/Pay.md", "生來就成立") or {}).get("state") == "true", got)


def t_drift_born_identity():
    """[S2] 同一條的認法:只改待辦文字、搬位置、筆記改名仍追到最早那一版;改了條件從改的那一版算;刪掉再寫回從寫回那一版算;
    側分支寫、合併進主線以合併那一版算。

    翻紅釘:用整行文字認同一條 → ①紅;不加 --first-parent → ④拿到側分支的提交。"""
    print("t_drift_born_identity")
    root = _dr_repo()
    _nh_file(root, "src/a.py", "x = 1\n")
    _nh_file(root, "src/b.py", "x = 1\n")
    _nh_commit(root, "程式")
    _nh_node(root, "Pay", summary="FLOW:a", body="REVISIT:[when-file:src/a.py][by:2099-12-31] 原本的待辦")
    _nh_node(root, "Q", summary="FLOW:q", body="REVISIT:[when-file:src/a.py][by:2099-12-31] q 的待辦")
    _nh_node(root, "R", summary="FLOW:r", body="REVISIT:[when-file:src/b.py][by:2099-12-31] r 的待辦")
    _nh_commit(root, "寫下")
    w1 = _na_head(root)
    _nh_node(root, "Pay", summary="FLOW:a", body="新加的段落\n\n另一段\nREVISIT:[when-file:src/a.py][by:2099-12-31] 改過的待辦文字")
    _nh_node(root, "Q", summary="FLOW:q", body="REVISIT:[when-file:src/b.py][by:2099-12-31] q 的待辦")
    _nh_node(root, "R", summary="FLOW:r", body="r 刪掉了")
    _nh_commit(root, "改文字、改條件、刪掉")
    w2 = _na_head(root)
    _nh_git(root, "mv", "docs/kg-knowledge/Systems/Pay.md", "docs/kg-knowledge/Systems/Pay2.md")
    _nh_node(root, "R", summary="FLOW:r", body="REVISIT:[when-file:src/b.py][by:2099-12-31] r 寫回來")
    _nh_commit(root, "改名、寫回")
    w3 = _na_head(root)
    _nh_git(root, "checkout", "-q", "-b", "side")
    _nh_node(root, "S", summary="FLOW:s", body="REVISIT:[when-file:src/a.py][by:2099-12-31] 側分支寫的")
    _nh_commit(root, "側分支")
    side = _na_head(root)
    _nh_git(root, "checkout", "-q", "-")
    _nh_file(root, "src/c.py", "y = 2\n")
    _nh_commit(root, "主線另一個改動")
    _nh_git(root, "merge", "-q", "--no-ff", "--no-edit", "side")
    mg = _na_head(root)
    src = (root / "docs/kg-knowledge/Systems/Pay2.md").read_text(encoding="utf-8")
    (root / "docs/kg-knowledge/Systems/T.md").write_text(src.replace("# Pay", "# T"), encoding="utf-8")
    _nh_commit(root, "複製一篇")
    cp = _na_head(root)
    check("⑤前提:git 把 T 認成從 Pay2 複製來的", "C" in _nh_git(root, "log", "--follow", "--format=", "--name-status", "-1", "--",
          "docs/kg-knowledge/Systems/T.md").stdout[:2], "")
    got, _txt = _born_scan(root)
    b = _born_of(got, "Systems/Pay2.md", "改過的待辦文字")
    check("①只改待辦文字、搬位置、改名:追到最早那一版", isinstance(b, dict) and b.get("commit") == w1, (b, w1, got))
    b = _born_of(got, "Systems/Q.md", "q 的待辦")
    check("②改了條件:從改的那一版算", isinstance(b, dict) and b.get("commit") == w2, (b, w2))
    b = _born_of(got, "Systems/R.md", "r 寫回來")
    check("③刪掉再寫回:從寫回那一版算", isinstance(b, dict) and b.get("commit") == w3, (b, w3))
    b = _born_of(got, "Systems/S.md", "側分支寫的")
    check("④側分支寫、合併進主線:以合併那一版算", isinstance(b, dict) and b.get("commit") == mg and mg != side, (b, mg, side))
    b = _born_of(got, "Systems/T.md", "改過的待辦文字")
    check("⑤從別篇複製來的:以複製那一版算、不追進來源那篇", isinstance(b, dict) and b.get("commit") == cp, (b, cp, w1))
    # ⑥ 改壞(解析不到)再修好:這一世從修好那一版算(代碼審 r1 正確性席 F2;訊息只講「從那一版起連續出現」)
    _nh_node(root, "G", summary="FLOW:g", body="REVISIT:[when-file:src/z.py][by:2099-12-31] 中間壞過")
    _nh_commit(root, "寫下(z.py 不在)")
    _nh_node(root, "G", summary="FLOW:g", body="REVISIT [when-file:src/z.py][by:2099-12-31] 中間壞過")
    _nh_file(root, "src/z.py", "z = 1\n")
    _nh_commit(root, "改壞、加 z.py")
    _nh_node(root, "G", summary="FLOW:g", body="REVISIT:[when-file:src/z.py][by:2099-12-31] 中間壞過")
    _nh_commit(root, "修好")
    fix = _na_head(root)
    got, _txt = _born_scan(root)
    b = _born_of(got, "Systems/G.md", "中間壞過")
    check("⑥改壞再修好:這一世從修好那一版算", isinstance(b, dict) and b.get("commit") == fix and b.get("state") == "true", (b, fix))


def t_note_versions_stop_at_copy():
    """[S5] 共用的版本清單停在複製:git log --follow 也跟複製(關不掉),新開一篇跟舊篇很像的筆記原本會一路追進舊篇的歷史——
    狀態序列混進舊篇的狀態翻轉(doing→done 被當成新篇在範圍裡收尾)。改名照跟。

    翻紅釘:_note_versions 不停在 C → ①②紅。"""
    print("t_note_versions_stop_at_copy")
    m = _load_lumos_inproc()
    root = _nh_repo()
    _nh_node(root, "A_計劃", typ="project", folder="Projects", resp=None, status="doing", summary="KEY:一樣的摘要",
             body="很長的一樣內容\n" * 20)
    _nh_commit(root, "A doing")
    c1 = _na_head(root)
    _nh_node(root, "A_計劃", typ="project", folder="Projects", resp=None, status="done", summary="KEY:一樣的摘要",
             body="很長的一樣內容\n" * 20)
    _nh_commit(root, "A done")
    src = (root / "docs/kg-knowledge/Projects/A_計劃.md").read_text(encoding="utf-8")
    (root / "docs/kg-knowledge/Projects/B_計劃.md").write_text(src.replace("# A_計劃", "# B_計劃"), encoding="utf-8")
    _nh_commit(root, "複製成 B")
    cp = _na_head(root)
    bp = "docs/kg-knowledge/Projects/B_計劃.md"
    pre = _nh_git(root, "log", "--follow", "--format=", "--name-status", "-1", "--", bp).stdout.strip()
    check("前提:git 把 B 認成從 A 複製來(不然①②③走不到停在複製那一段)", pre.startswith("C"), pre)
    vs = m._note_versions(root, "HEAD", bp)
    check("①版本清單停在複製那一版", [s_ for s_, _q in vs] == [cp], vs)
    seq = m._note_status_seq(root, c1, "HEAD", "docs/kg-knowledge", bp, strict=True)
    check("②狀態序列不混進來源那篇的翻轉", seq == [None, "done"], seq)
    _nh_git(root, "mv", bp, "docs/kg-knowledge/Projects/C_計劃.md")
    _nh_commit(root, "改名成 C")
    vs = m._note_versions(root, "HEAD", "docs/kg-knowledge/Projects/C_計劃.md")
    check("③改名照跟、跟到複製那一版為止", [s_ for s_, _q in vs][1:] == [cp] and len(vs) == 2, vs)
    ha, hb = "a" * 40, "b" * 40
    raw = (ha + "\0\n" + hb + "\0\nR087\0old.md\0new.md\0").encode()
    check("④沒有檔案列的提交(合併提交)跳過、不把下一個提交編號當路徑;改名取新路徑",
          m._git_log_sha_status_paths(raw) == [(hb, "new.md", "R")], m._git_log_sha_status_paths(raw))
    # 代碼審 r2 正確性席 F1:本機設 log.showSignature=true 時,簽章提交的編號前面會夾 gpg 訊息。原本跳過對不上的片段、
    # 沿用上一個提交編號,簽章提交的檔案列被記到別人名下,寫下那一版追錯
    raw = (ha + "\0\nM\0a.md\0" + "gpg: Signature made\n" + hb + "\0\nM\0a.md\0").encode()
    check("⑤認不得的片段整份判不了,不沿用上一個提交編號", m._git_log_sha_status_paths(raw) is None,
          m._git_log_sha_status_paths(raw))
    seen = []
    orig_ns, orig_lens = m._ns_git, m._lens_git
    m._ns_git = lambda r_, *a: (seen.append(a), orig_ns(r_, *a))[1]
    m._lens_git = lambda r_, *a, **k: (seen.append(a), orig_lens(r_, *a, **k))[1]
    try:
        _nh_git(root, "config", "log.showSignature", "true")
        m._note_versions(root, "HEAD", "docs/kg-knowledge/Projects/C_計劃.md")
        d = m._git_commit_date(root, cp)
    finally:
        m._ns_git, m._lens_git = orig_ns, orig_lens
    logs = [a for a in seen if a and a[0] in ("log", "show")]
    check("⑥版本清單與取日期的 git 呼叫都關掉簽章顯示", {a[0] for a in logs} == {"log", "show"} and all("--no-show-signature" in a for a in logs), logs)
    import re as _re
    check("⑦取日期只回 YYYY-MM-DD", isinstance(d, str) and _re.fullmatch(r"\d{4}-\d{2}-\d{2}", d) is not None, d)
    m._lens_git = lambda *_a, **_k: subprocess.CompletedProcess([], 0, stdout="gpg: Signature made\n2026-10-03\n", stderr="")
    try:
        d = m._git_commit_date(root, cp)
    finally:
        m._lens_git = orig_lens
    check("⑧輸出夾了別的東西就不給日期", d is None, d)


def t_drift_born_unknown():
    """[S3] 判不了一律 state=unknown、why 講原因、文字只印一行彙總:同篇兩行同條件、走到的某一版不是 UTF-8、淺層 clone、
    partial clone、工作目錄裡還沒提交的行、超過 6 個不同提交;不是 git 專案照樣判不了、scan 照常列其他發現。"""
    print("t_drift_born_unknown")
    import subprocess as sp, shutil
    root = _dr_repo()
    _nh_file(root, "src/a.py", "x = 1\n")
    _nh_commit(root, "程式")
    _nh_node(root, "Dup", summary="FLOW:d", body="REVISIT:[when-file:src/a.py][by:2099-12-31] 一\n"
                                                 "REVISIT:[when-file:src/a.py][by:2099-12-31] 二")
    p = root / "docs/kg-knowledge/Systems/Bad.md"
    _nh_node(root, "Bad", summary="FLOW:b", body="REVISIT:[when-file:src/a.py][by:2099-12-31] 壞版本\n")
    p.write_bytes(p.read_bytes() + b"\xff\xfe big5 \xa7\xda\n")
    _nh_commit(root, "寫下(Bad 那一版不是 UTF-8)")
    _nh_node(root, "Bad", summary="FLOW:b", body="REVISIT:[when-file:src/a.py][by:2099-12-31] 壞版本\n修好編碼")
    _nh_commit(root, "修好編碼")
    _nh_node(root, "New", summary="FLOW:n", body="REVISIT:[when-file:src/a.py][by:2099-12-31] 還沒提交")
    got, txt = _born_scan(root)
    for path, needle, word in (("Systems/Dup.md", "一", "不只一行"), ("Systems/Bad.md", "壞版本", "UTF-8"),
                               ("Systems/New.md", "還沒提交", "還沒提交")):
        b = _born_of(got, path, needle)
        check(f"①判不了:{path} why 講出「{word}」", isinstance(b, dict) and b.get("state") == "unknown"
              and word in (b.get("why") or ""), (b, got))
    check("①文字輸出只印一行彙總、不逐條印", txt.count("查不出寫下時成不成立") == 1 and "寫下時就已成立" not in txt, txt[-1500:])
    (root / "docs/kg-knowledge/Systems/New.md").unlink()
    # 代碼審 r1 正確性席 F1:已提交一行、工作目錄加同條件第二行(未提交)——原本兩行都被標成寫下時就已成立
    _nh_node(root, "W", summary="FLOW:w", body="REVISIT:[when-file:src/a.py][by:2099-12-31] 已提交的")
    _nh_commit(root, "W 寫下")
    _nh_node(root, "W", summary="FLOW:w", body="REVISIT:[when-file:src/a.py][by:2099-12-31] 已提交的\n"
             "REVISIT:[when-file:src/a.py][by:2099-12-31] 工作目錄多一行")
    got, _txt = _born_scan(root)
    bs = [_born_of(got, "Systems/W.md", w) for w in ("已提交的", "工作目錄多一行")]
    check("①工作目錄裡同組條件兩行:兩行都判不了「不只一行」", all(isinstance(b, dict) and b.get("state") == "unknown"
          and "不只一行" in (b.get("why") or "") for b in bs), bs)
    _nh_git(root, "checkout", "--", "docs/kg-knowledge/Systems/W.md")
    sh = Path(tempfile.mkdtemp(prefix="gctl-born-shallow-")) / "c"
    sp.run(["git", "clone", "-q", "--depth", "1", f"file://{root}", str(sh)], capture_output=True)
    got, txt = _born_scan(sh)
    b = _born_of(got, "Systems/Bad.md", "壞版本")
    check("②淺層 clone:判不了、講原因", isinstance(b, dict) and b.get("state") == "unknown" and "淺層" in (b.get("why") or ""), (b, got))
    _nh_git(root, "config", "extensions.partialClone", "origin")
    got, _txt = _born_scan(root)
    b = _born_of(got, "Systems/Bad.md", "壞版本")
    check("③partial clone:判不了、講原因", isinstance(b, dict) and b.get("state") == "unknown" and "partial" in (b.get("why") or ""), (b, got))
    _nh_git(root, "config", "--unset", "extensions.partialClone")
    for i in range(7):
        _nh_node(root, f"N{i}", summary="FLOW:n", body=f"REVISIT:[when-file:src/a.py][by:2099-12-31] 第 {i} 條")
        _nh_commit(root, f"第 {i} 條")
    got, _txt = _born_scan(root)
    bs = [_born_of(got, f"Systems/N{i}.md", f"第 {i} 條") for i in range(7)]
    over = [b for b in bs if isinstance(b, dict) and b.get("state") == "unknown" and "上限" in (b.get("why") or "")]
    check("④超過 6 個不同提交:多的判不了「超過上限」", len(over) >= 1 and all(isinstance(b, dict) for b in bs), bs)
    ng = Path(tempfile.mkdtemp(prefix="gctl-born-nogit-"))
    shutil.copytree(root / "docs", ng / "docs")
    _nh_node(ng, "St", summary="FLOW:s", body="REVISIT:[when-status:Projects/退款_計劃=doing][by:2099-12-31] 不是 git 專案")
    got, txt = _born_scan(ng)
    b = _born_of(got, "Systems/St.md", "不是 git 專案")
    check("⑤不是 git 專案:判不了、scan 照常列", isinstance(b, dict) and b.get("state") == "unknown", (b, got, txt[-600:]))


_CT_PY = (
    "from enum import Enum, auto\n"
    "STATES = (\"a\", \"b\", \"c\")\n"
    "KINDS = [\"x\", \"y\"]\n"
    "SETS = {\"p\", \"q\", \"p\"}\n"
    "D = {\"k1\": 1, \"k2\": 2}\n"
    "FS = frozenset({\"a\", \"b\", \"c\", \"d\"})\n"
    "class Color(Enum):\n"
    "    RED = auto()\n"
    "    GREEN = auto()\n"
    "    BLUE = auto()\n"
)


def _ct_repo(body, files=None, summary="KEY:x"):
    """數量標記的測試專案:_dr_repo + src/st.py(各種具名集合)+ 一篇 Cnt 筆記;回 (root, vault)。"""
    root = _dr_repo()
    _nh_file(root, "src/st.py", _CT_PY)
    for rel, txt in (files or {}).items():
        _nh_file(root, rel, txt)
    _nh_node(root, "Cnt", body=body, summary=summary)
    _nh_commit(root, "count")
    return root, root / "docs" / "kg-knowledge"


def _ct_scan(vault, *extra):
    import json as _j
    r = run(vault, "drift", "scan", "--json", *extra)
    try:
        d = _j.loads(r.stdout)
    except ValueError:
        return None, r.stdout + r.stderr
    return d, None


def _ct_line(vault, needle):
    """Cnt 筆記裡含 needle 那一行的行號(1 起算)。"""
    lines = (vault / "Systems" / "Cnt.md").read_text(encoding="utf-8").split("\n")
    return next(i for i, ln in enumerate(lines, 1) if needle in ln)


def t_count_tag_scan():
    """[S1] [count:路徑::名稱=N] 指到元組、清單、集合、字典、frozenset(…)、列舉類別:數字對不上 drift scan 列 kind=count
    (帶 claimed/actual),吻合的不列;工作目錄與 --at 都判得出。

    翻紅釘:scan 不跑數量標記 → ①紅;集合不去重 → ①紅(SETS 會變成 3≠2);列舉數成 0 → ①紅。"""
    print("t_count_tag_scan")
    body = ("有 3 種狀態 [count:src/st.py::STATES=3]\n"
            "有 5 種類型 [count:src/st.py::KINDS=5]\n"
            "集合 2 個 [count:src/st.py::SETS=2]\n"
            "字典 3 個鍵 [count:src/st.py::D=3]\n"
            "凍結 4 個 [count:src/st.py::FS=4]\n"
            "顏色 2 種 [count:src/st.py::Color=2]\n")
    root, vault = _ct_repo(body)
    for extra in ((), ("--at", "HEAD")):
        d, err = _ct_scan(vault, *extra)
        got = sorted((f["text"].split(" [")[0], f["count"]["claimed"], f["count"]["actual"])
                     for f in (d or {}).get("findings", []) if f["kind"] == "count")
        want = [("字典 3 個鍵", 3, 2), ("有 5 種類型", 5, 2), ("顏色 2 種", 2, 3)]
        check(f"①對不上的列成 count、吻合的不列({'工作目錄' if not extra else '--at'})", got == want, str(got) + str(err or ""))
    t = run(vault, "drift", "scan").stdout
    check("②文字輸出有 [count] 那一段與寫幾、現在幾", "[count]" in t and "寫 5、現在是 2" in t, t[-1200:])


def t_count_tag_unknown():
    """[S2] 判不了的一律列成問題、講原因,不列成對不上:名稱找不到、指派不只一次、不是字面值集合、含展開、非常數成員、
    列舉別名、不是 Python、檔不在、檔案解不開、沒帶路徑、數字寫錯。

    翻紅釘:找不到名稱當成 0 → 列成對不上,①紅。"""
    print("t_count_tag_unknown")
    u = ("from enum import Enum\n"
         "X = (1,)\nX = (1, 2)\n"
         "Y = make()\n"
         "Z = (*STATES, 3)\n"
         "W = {a, b}\n"
         "class E(Enum):\n    A = 1\n    B = 1\n"
         "from enum import Flag\n"
         "class F(Flag):\n    A = 1\n    B = 2\n    C = 3\n"
         "class P(Enum):\n    _priv = 1\n    X = 2\n"
         "class G(Enum):\n    _ignore_ = ['tmp']\n    tmp = 5\n    Q = 1\n"
         "M = {'a'}\nM |= {'b'}\n"
         "L = ['a']\nL.append('b')\n"
         "import enum\n"
         "class MA(enum.Enum):\n    A = B = 1\n"
         "class TA(enum.Enum):\n    A, B = 1, 2\n"
         "class IB(enum.Enum):\n    A = 1\n    if True:\n        B = 2\n"
         "class AD(enum.IntEnum):\n    A = enum.auto()\n    B = 1\n"
         "R1 = (1, 2, 3)\ntry:\n    import nonexistent\nexcept ImportError:\n    R1 = (1,)\n"
         "R2 = (1, 2, 3)\ndef reload():\n    global R2\n    R2 = (1,)\n"
         "R3 = (1, 2, 3)\nR3, R9 = (1,), 2\n"
         "R4 = (1, 2, 3)\ndel R4\n"
         "R5 = [1, 2, 3]\nR5.__iadd__([4])\n"
         "V1 = (1, 2, 3)\ndef fv(a=(V1 := (1,))):\n    pass\n"
         "V2 = (1, 2, 3)\nclass CV((V2 := object)):\n    pass\n"
         "V3 = (1, 2, 3)\nmatch (7,):\n    case [V3]:\n        pass\n"
         "V4 = (1, 2, 3)\ntry:\n    raise ValueError\nexcept ValueError as V4:\n    pass\n")
    cases = [("[count:src/u.py::NOPE=1]", "找不到"), ("[count:src/u.py::X=2]", "不只一次"),
             ("[count:src/u.py::Y=1]", "不是字面值"), ("[count:src/u.py::Z=3]", "展開"),
             ("[count:src/u.py::W=2]", "不是常數"), ("[count:src/u.py::E=2]", "別名"),
             ("[count:src/a.js::K=1]", "Python"), ("[count:src/missing.py::K=1]", "不在"),
             ("[count:src/bad.py::K=1]", "解不開"), ("[count:K=1]", "路徑"), ("[count:src/u.py::X=abc]", "整數"),
             # 代碼審 code-數量標記檢查 r1 正確性席 F1、F4、F5:Flag 組合值、底線開頭的成員、_ignore_、定義後又被改過、數字太長
             ("[count:src/u.py::F=2]", "Flag"), ("[count:src/u.py::P=2]", "底線"), ("[count:src/u.py::G=1]", "_ignore_"),
             ("[count:src/u.py::M=2]", "改過"), ("[count:src/u.py::L=2]", "改過"),
             ("[count:src/u.py::X=" + "9" * 5000 + "]", "整數"),
             # 代碼審 code-數量標記檢查-2 r2 正確性席 F1–F3:列舉本體看不懂的語句、auto() 與明寫值混用、名稱在別處被重新綁定
             ("[count:src/u.py::MA=1]", "看不懂"), ("[count:src/u.py::TA=2]", "看不懂"), ("[count:src/u.py::IB=2]", "看不懂"),
             ("[count:src/u.py::AD=1]", "auto"), ("[count:src/u.py::R1=1]", "改過"), ("[count:src/u.py::R2=1]", "改過"),
             ("[count:src/u.py::R3=1]", "改過"), ("[count:src/u.py::R4=3]", "改過"), ("[count:src/u.py::R5=4]", "改過"),
             # 代碼審 code-數量標記檢查-2 r3 正確性席 F2、F3:函式預設值與類別基底裡的海象、match 捕捉、except as 也會重新綁定
             ("[count:src/u.py::V1=1]", "改過"), ("[count:src/u.py::V2=3]", "改過"), ("[count:src/u.py::V3=3]", "改過"),
             ("[count:src/u.py::V4=3]", "改過"),
             # code-數量標記檢查-3 r1 正確性席 F2:星號 import 可能蓋掉名稱,名稱卻不出現
             ("[count:src/s.py::S=2]", "改過")]
    body = "".join(f"第{i}條 {tag}\n" for i, (tag, _w) in enumerate(cases))
    root, vault = _ct_repo(body, files={"src/u.py": u, "src/a.js": "const K = [1];\n", "src/bad.py": "def (:\n",
                                        "src/s.py": "S = (1, 2)\nfrom os import *\n"})
    d, err = _ct_scan(vault)
    found = [f for f in (d or {}).get("findings", []) if f["kind"] == "count"]
    check("①判不了的一條都不列成對不上", d is not None and not found, str(found) + str(err or ""))
    probs = (d or {}).get("problems", [])
    for i, (tag, word) in enumerate(cases):
        hit = [p["why"] for p in probs if p["text"].startswith(f"第{i}條 ")]
        check(f"②{tag} 列成問題、原因講「{word}」", len(hit) == 1 and word in hit[0], str(hit))


def t_inline_visible_single_source():
    """_strip_inline_markup 重構後跟舊公式逐字一樣(含原文本來就有的 NUL),位置不動版本拿掉被遮的字後也一樣
    (代碼審 code-數量標記檢查-2 r3 架構對齊席 Z1 抽出唯一本體;code-數量標記檢查-3 r1 正確性席 F1:原本用 NUL 當遮罩,
    原文的 NUL 也被刪)。

    翻紅釘:改回用 NUL 遮罩再整串刪 NUL → ②紅;兩邊任一支自己算 → ①或③紅。"""
    print("t_inline_visible_single_source")
    import random
    m = _load_lumos_inproc()

    def old(line):
        t = m.INLINE_CODE_RE.sub("", m._DOUBLE_BACKTICK_RE.sub("", line))
        return (t.split("`", 1)[0], True) if "`" in t else (t, False)
    rnd = random.Random(20261004)
    alpha = ["`", "``", "```", "a", "5", " ", "[count:x.py::K=5]", "\n", "\0"]
    bad, dbl, unclosed = [], 0, 0
    for _ in range(20000):
        ln = "".join(rnd.choice(alpha) for _ in range(rnd.randint(0, 12)))
        dbl += "``" in ln
        unclosed += old(ln)[1]
        mask = m._inline_visible_mask(ln)
        if m._strip_inline_markup(ln) != old(ln) or len(mask) != len(ln):
            bad.append(ln)
    check("前提:隨機樣本裡雙反引號與未閉合反引號都夠多", dbl > 1000 and unclosed > 1000, (dbl, unclosed))
    check("①重構後跟舊公式逐字一樣、遮罩版長度不變", not bad, [repr(b) for b in bad[:3]])
    check("②原文本來就有的 NUL 照留", m._strip_inline_markup("[test:a\0b]") == ("[test:a\0b]", False))
    check("③遮罩版只遮行內程式碼", m._inline_visible_mask("a `b` c") == "a \0\0\0 c")


def t_count_tag_places():
    """[S3] 圍欄與行內程式碼裡的標籤不評估;表格行照評估;已標 [status:superseded] 的摘要行不評估。

    翻紅釘:不剝行內程式碼 → 多一筆,①紅;跳過表格行 → 少一筆,①紅。"""
    print("t_count_tag_places")
    body = ("```\n範例 [count:src/st.py::KINDS=9]\n```\n"
            "行內 `[count:src/st.py::KINDS=9]` 不算\n"
            "| 欄 | 表格裡 [count:src/st.py::KINDS=9] |\n")
    summary = "KEY:舊的 [count:src/st.py::KINDS=9] [status:superseded] [被取代:無 測試]"
    root, vault = _ct_repo(body, summary=summary)
    d, err = _ct_scan(vault)
    got = [f["text"] for f in (d or {}).get("findings", []) if f["kind"] == "count"]
    check("①只有表格行那一筆", len(got) == 1 and got[0].startswith("| 欄 |"), str(got) + str(err or ""))


def t_count_tag_doctor():
    """[S4] doctor 存量漂移段列數量標記總數與寫錯的處數;不評估數字、不影響結束碼。

    翻紅釘:Z 段不數標籤 → ①紅;doctor 去評估數字 → ③紅(會印「對不上」)。"""
    print("t_count_tag_doctor")
    root, vault = _ct_repo("無標籤\n")
    rc0 = run(vault, "doctor").returncode
    (vault / "Systems" / "Cnt.md").write_text(
        (vault / "Systems" / "Cnt.md").read_text(encoding="utf-8")
        + "有 5 種 [count:src/st.py::KINDS=5]\n寫錯 [count:K=1]\n", encoding="utf-8")
    rd = run(vault, "doctor")
    check("①Z 段列數量標記總數與寫錯的", "數量標記 2 處" in rd.stdout and "寫錯的 1 處" in rd.stdout, rd.stdout[-1500:])
    check("②不影響結束碼", rd.returncode == rc0, (rc0, rd.returncode))
    check("③doctor 不評估數字", "寫 5、現在是 2" not in rd.stdout, rd.stdout[-600:])


def t_count_tag_fix():
    """[S5] drift fix --kind count 把標籤與句子裡恰好一個的舊數字改成現值、記修復帳;句子裡的舊數字找不到或不只一個擋下不寫;
    已吻合回報不用改;drift ack --kind count 讓那一筆列在已表態。

    翻紅釘:只改標籤不改句子 → ①紅;句子有兩個舊數字也照改 → ③紅。"""
    print("t_count_tag_fix")
    body = ("有 5 種類型 [count:src/st.py::KINDS=5]\n"
            "共 5 項另有 5 個 [count:src/st.py::STATES=5]\n"
            "沒有數字的句子 [count:src/st.py::D=5]\n"
            "已經對 3 種 [count:src/st.py::FS=4]\n"
            "對的 4 個 [count:src/st.py::FS=4]\n"
            "空白版 5 種 [count:src/st.py::KINDS = 5]\n"
            "前導零 5 種 [count:src/st.py::KINDS=05]\n"
            "見 F5 說明有5種 [count:src/st.py::KINDS=5] 範例 `[count:src/st.py::KINDS=5]`\n"
            "2026-10-04 起共十種 [count:src/st.py::STATES=10]\n"
            "共 ``5`` 種 [count:src/st.py::FS=5]\n"
            "夾程式碼 5 種 [count:src/st.py::KINDS``x``=5]\n")
    root, vault = _ct_repo(body)
    p = vault / "Systems" / "Cnt.md"
    rc, out = _df_fix(vault, "Systems/Cnt", str(_ct_line(vault, "有 5 種類型")), "--kind", "count")
    txt = p.read_text(encoding="utf-8")
    check("①標籤與句子裡的數字一起改成現值", rc == 0 and "有 2 種類型 [count:src/st.py::KINDS=2]" in txt, out + txt[-400:])
    rows = _df_rows(root)
    check("②記修復帳 kind=count", rows and rows[-1].get("kind") == "count", str(rows[-1:]))
    before = p.read_bytes()
    rc, out = _df_fix(vault, "Systems/Cnt", str(_ct_line(vault, "共 5 項")), "--kind", "count")
    check("③句子裡舊數字不只一個 → 擋下不寫", rc == 2 and p.read_bytes() == before and "不只一個" in out, out)
    rc, out = _df_fix(vault, "Systems/Cnt", str(_ct_line(vault, "沒有數字的句子")), "--kind", "count")
    check("④句子裡找不到舊數字 → 擋下不寫", rc == 2 and p.read_bytes() == before and "找不到" in out, out)
    rc, out = _df_fix(vault, "Systems/Cnt", str(_ct_line(vault, "對的 4 個")), "--kind", "count")
    check("⑤已吻合 → 回報不用改、不寫", rc != 0 and p.read_bytes() == before and "不用改" in out, out)
    ln = _ct_line(vault, "共 5 項")
    r = run(vault, "drift", "ack", "Systems/Cnt", str(ln), "--kind", "count", "--reason", "這句講的是另一件事")
    d, err = _ct_scan(vault)
    acked = [f for f in (d or {}).get("findings", []) if f["kind"] == "count" and f["line"] == ln]
    check("⑥表態後那一筆列在已表態", r.returncode == 0 and acked and acked[0]["acked"] is True, r.stdout + r.stderr + str(acked))
    # 代碼審 code-數量標記檢查 r1 正確性席 F2:標籤寫成 = 5、=05 時原本只改了句子、標籤沒動,寫進去才在驗證時擋下
    for needle, want in (("空白版", "空白版 2 種 [count:src/st.py::KINDS=2]"), ("前導零", "前導零 2 種 [count:src/st.py::KINDS=2]")):
        rc, out = _df_fix(vault, "Systems/Cnt", str(_ct_line(vault, needle)), "--kind", "count")
        check(f"⑦{needle}的標籤照樣改到、整行一致", rc == 0 and want in p.read_text(encoding="utf-8"), out)
    # F3:句子裡的 F5 是識別碼不是數量;行內程式碼裡的範例標籤不能跟著改
    rc, out = _df_fix(vault, "Systems/Cnt", str(_ct_line(vault, "見 F5")), "--kind", "count")
    line = p.read_text(encoding="utf-8").split("\n")[_ct_line(vault, "見 F5") - 1]
    check("⑧識別碼 F5 與行內程式碼裡的範例不動", rc == 0 and line == "見 F5 說明有2種 [count:src/st.py::KINDS=2] 範例 `[count:src/st.py::KINDS=5]`", out + line)
    # 代碼審 code-數量標記檢查-2 r2 正確性席 F4、F5:日期裡的數字、雙反引號裡看不見的數字都不是句子數字 → 找不到、擋下不寫
    for needle in ("2026-10-04 起", "共 ``5`` 種"):
        before = p.read_bytes()
        rc, out = _df_fix(vault, "Systems/Cnt", str(_ct_line(vault, needle)), "--kind", "count")
        check(f"⑨{needle}:句子裡沒有看得見的舊數字 → 擋下不寫", rc == 2 and p.read_bytes() == before and "找不到" in out, out)
    # r3 正確性席 F1:標籤裡夾行內程式碼,原本把遮罩字元寫進筆記
    before = p.read_bytes()
    rc, out = _df_fix(vault, "Systems/Cnt", str(_ct_line(vault, "夾程式碼")), "--kind", "count")
    check("⑩標籤裡夾行內程式碼 → 擋下不寫、不寫進遮罩字元", rc == 2 and p.read_bytes() == before and b"\x00" not in p.read_bytes(), out)


def t_drift_born_reads_stop_at_boundary():
    """[S4] 一篇筆記歷史很長、這一世只在最近幾版:版本讀取碰到邊界就停,不讀完整段歷史(一次 32 版)。

    翻紅釘:一次讀完全部版本 → 讀到的版本數 = 歷史長度(80 以上)。"""
    print("t_drift_born_reads_stop_at_boundary")
    m = _load_lumos_inproc()
    root = _dr_repo()
    _nh_file(root, "src/a.py", "x = 1\n")
    for i in range(80):
        _nh_node(root, "Pay", summary="FLOW:a", body=f"第 {i} 版")
        _nh_commit(root, f"v{i}")
    _nh_node(root, "Pay", summary="FLOW:a", body="第 80 版\nREVISIT:[when-file:src/a.py][by:2099-12-31] 最近才寫")
    _nh_commit(root, "寫下")
    w = _na_head(root)
    _nh_node(root, "Pay", summary="FLOW:a", body="第 81 版\nREVISIT:[when-file:src/a.py][by:2099-12-31] 最近才寫")
    _nh_commit(root, "再改")
    head = _na_head(root)
    tenv = m._drift_tree_env(root, head, "docs/kg-knowledge")
    line = next(no for no, _t, _pr in m._probe_lines(m.env_text(tenv, "Systems/Pay.md"))[0])
    f = {"kind": "probe", "path": "Systems/Pay.md", "line": line, "text": "REVISIT:[when-file:src/a.py][by:2099-12-31] 最近才寫",
         "related": [], "why": "x"}
    real, seen = m._nodehome_cat_blobs, []

    def spy(repo_root, specs, timeout=60):
        seen.extend(s for s in specs if s.endswith(":docs/kg-knowledge/Systems/Pay.md"))
        return real(repo_root, specs, timeout=timeout)
    m._nodehome_cat_blobs = spy
    try:
        m._drift_born_annotate(root, head, "docs/kg-knowledge", tenv, [f])
    finally:
        m._nodehome_cat_blobs = real
    check("①找對寫下那一版", (f.get("born") or {}).get("commit") == w, f.get("born"))
    check("①讀到的版本數不超過一段(32)", 0 < len(seen) <= 32, len(seen))
    check("②上限跟列樹快取連動:留兩格給終點(代碼審 r1 架構對齊席 Z4)",
          m._DRIFT_BORN_MAX_COMMITS == m._DRIFT_LS_CACHE_MAX - 2, getattr(m, "_DRIFT_LS_CACHE_MAX", None))


def t_drift_when_probes_evaluate_and_trigger():
    """[S9] 條件標記照文法解析、只認正文與摘要的可見行,四種鍵在指定提交的樹上判對(含路徑限定、status 任一值、
    筆記不存在算不成立、Python 帶型別的模組層指定),一行全部成立才算成立;check 以行為篩選單位,終點成立而起點沒有同一條
    或同一條還不成立的算要處理(只改待辦文字仍是同一條、新寫而已成立的也擋),起點早就成立的不列、跟條件無關的推送不擋。

    翻紅釘:check 不看起點(每次都擋成立的)→ ⑦紅;「同一條」改成比整行文字 → ⑧紅;status 不拆 | → ③紅。
    """
    print("t_drift_when_probes_evaluate_and_trigger")
    import pathlib
    m = _load_lumos_inproc()
    # ① 文法與可見行
    txt = ("---\ntype: project\nstatus: doing\nvalid_under: 前提 [when-file:a.py]\nsummary: |-\n"
           "  REVISIT:[when-file:src/a.py][by:2099-01-01] 摘要裡的\n---\n# X\n"
           "- REVISIT:[when-symbol:src/a.py::Foo][when-status:Projects/P=doing|done][by:2099-01-01] 正文列表裡的\n"
           "`REVISIT:[when-file:x.py][by:2099-01-01]` 行內程式碼裡的\n"
           "| REVISIT:[when-file:t.py][by:2099-01-01] | 表格裡的 |\n"
           "```\nREVISIT:[when-file:f.py][by:2099-01-01] 圍欄裡的\n```\n"
           "REVISIT:[when-bogus:x][by:2099-01-01] 鍵寫錯\n"
           "REVISIT:[when-file:ok.py] 沒帶期限\n")
    rows, dead = m._probe_lines(txt)
    got = [(no, pr["conds"], bool(pr["errs"]), pr["by"]) for no, _t, pr in rows]
    check("①摘要與正文列表的條件式認得;行內程式碼、表格、圍欄裡的不算",
          [g[0] for g in got] == [6, 9, 15, 16], str(got))
    check("①解析出鍵與值、期限", got[1][1] == [("symbol", "src/a.py::Foo"), ("status", "Projects/P=doing|done")]
          and got[1][3] == "2099-01-01", str(got[1]))
    check("①不認得的鍵算寫錯;沒帶期限另外看得到", got[2][2] is True and got[3][3] is None, str(got[2:]))
    check("①開頭欄位其他欄、表格行裡的條件標記列成不評估", sorted(d[0] for d in dead) == [4, 11], str(dead))
    # ② ③ 四種鍵的判定
    root = _nh_repo()
    _nh_file(root, "src/a.py", "MAX: int = 3\nclass Foo:\n    async def bar(self):\n        pass\n")
    _nh_file(root, "src/b.kt", "val quota = 1 // Quota\n")
    _nh_file(root, "tests/test_a.py", "def test_ok():\n    assert True\n")
    _nh_node(root, "P_計劃", typ="project", folder="Projects", resp=None, status="doing", summary="KEY:p")
    _nh_commit(root, "tree")
    tip = _na_head(root)
    tenv = m._drift_tree_env(root, tip, "docs/kg-knowledge")
    tr = m._drift_probe_tree(root, tip)
    cases = [(("file", "src/a.py"), True), (("file", "src/none.py"), False),
             (("symbol", "MAX"), True), (("symbol", "Foo"), True), (("symbol", "bar"), True),
             (("symbol", "src/b.kt::quota"), True), (("symbol", "src/a.py::quota"), False), (("symbol", "Nope"), False),
             (("test", "test_ok"), True), (("test", "tests/test_a.py::test_ok"), True), (("test", "MAX"), False),
             (("status", "Projects/P_計劃=done|doing"), True), (("status", "P_計劃=done"), False),
             (("status", "Projects/不存在=doing"), False)]
    bad = [(c, m._drift_probe_one(tr, tenv, *c)) for c, want in cases if m._drift_probe_one(tr, tenv, *c) is not want]
    check("②③四種鍵判對(路徑限定、Python 帶型別指定與方法、status 任一值、筆記不存在)", not bad, str(bad))
    check("②一行多個條件全部成立才算成立", m._drift_probe_line(tr, tenv, (("file", "src/a.py"), ("symbol", "Nope"))) is False
          and m._drift_probe_line(tr, tenv, (("file", "src/a.py"), ("symbol", "MAX"))) is True, "")
    # ④–⑨ 推送判定
    root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
    _nh_file(root, "src/other.py", "x = 1\n")
    _nh_node(root, "Pay", summary="FLOW:a", body="REVISIT:[when-file:src/runner.py][by:2099-12-31] 有啟動程式了要補測試")
    _nh_commit(root, "base")
    b0 = _na_head(root)
    _nh_file(root, "src/other.py", "x = 2\n")
    _nh_commit(root, "無關的改動")
    rc, out = _dr(root, "check", "--diff", f"{b0}..HEAD")
    check("④跟條件無關的推送:不擋", rc == 0 and "probe" not in out, out)
    b1 = _na_head(root)
    _nh_file(root, "src/runner.py", "def main():\n    pass\n")
    _nh_commit(root, "加啟動程式")
    rc, out = _dr(root, "check", "--diff", f"{b1}..HEAD")
    check("⑤這次推送讓條件成立:擋、指到那一行", rc == 1 and "[probe" in out and "Systems/Pay.md" in out, out)
    b2 = _na_head(root)
    _nh_file(root, "src/runner.py", "def main():\n    return 1\n")
    _nh_commit(root, "改啟動程式")
    rc, out = _dr(root, "check", "--diff", f"{b2}..HEAD")
    check("⑦起點早就成立:不列", rc == 0, out)
    _nh_node(root, "Pay", summary="FLOW:a", body="REVISIT:[when-file:src/runner.py][by:2099-12-31] 換個說法的待辦")
    _nh_commit(root, "只改待辦文字")
    rc, out = _dr(root, "check", "--diff", f"{b2}..HEAD")
    check("⑧只改待辦文字仍是同一條、起點早就成立:不列", rc == 0, out)
    b3 = _na_head(root)
    _nh_node(root, "Pay", summary="FLOW:a", body="REVISIT:[when-file:src/runner.py][by:2099-12-31] 換個說法的待辦\n"
             "REVISIT:[when-file:src/other.py][by:2099-12-31] 新寫一條已經成立的")
    _nh_commit(root, "新寫一條已成立的")
    rc, out = _dr(root, "check", "--diff", f"{b3}..HEAD")
    check("⑨新寫一條終點已經成立的條件式:擋", rc == 1 and "src/other.py" in out, out)


def _rv_stage_shape(root):
    """暫存全部、跑一次提交前的筆記形狀擋 → (rc, 輸出)。"""
    import subprocess as sp
    _nh_git(root, "add", "-A")
    r = sp.run([sys.executable, GRAPHCTL, "note-shape", "--staged", "--repo", str(root)], capture_output=True, text=True)
    return r.returncode, r.stdout + r.stderr


def t_revisit_misplaced_blocks_new():
    """[S1][S2][S4] 新寫的句中 REVISIT(句子後面、KEY: 前綴、星號、刪除線、核取方塊、表格列、開頭欄位欄名在前、
    行首已是合法 REVISIT 後面再一條)提交時擋、報「回頭條件寫在句中」;獨立一行、開頭欄位清單項的行首形狀不報;
    表格裡帶條件標記已報「條件寫在不評估的地方」的不重報;舊行尾補括號照報(整行層級不扣)。"""
    print("t_revisit_misplaced_blocks_new")
    root = _nh_repo()
    _nh_node(root, "A", body="開頭")
    _nh_commit(root, "base")
    _nh_node(root, "A", body="開頭\nREVISIT:2026-10-05 獨立一行的")
    rc, out = _rv_stage_shape(root)
    check("①前提:獨立一行不擋", rc == 0 and "回頭條件寫在句中" not in out, out[-400:])
    _nh_git(root, "reset", "-q")
    cases = [("句子後面", "這裡承認風險。REVISIT:2026-10-05 回頭看", "body"),
             ("星號", "★REVISIT:[when-file:a.py][by:2026-12-31] 回頭看★", "body"),
             ("刪除線", "~~REVISIT:2026-10-05 不用了~~", "body"),
             ("核取方塊", "- [ ] REVISIT:2026-10-05 回頭看", "body"),
             ("表格列", "| 甲 | REVISIT:2026-10-05 回頭看 |", "body"),
             ("一行兩條", "REVISIT:2026-10-05 先做 A;REVISIT:[when-file:a.py][by:2026-12-31] 再做 B", "body"),
             ("KEY 前綴", "KEY:REVISIT:2026-10-05 回頭看", "summary"),
             ("開頭欄位欄名在前", "why: 已知 REVISIT:2026-10-05 回頭看", "extra")]
    for label, ln, where in cases:
        kw = {"body": "開頭\n" + ln} if where == "body" else ({"summary": ln} if where == "summary" else {"extra": ln, "body": "開頭"})
        _nh_node(root, "A", **kw)
        rc, out = _rv_stage_shape(root)
        check(f"②{label}:擋、報回頭條件寫在句中", rc == 1 and "回頭條件寫在句中" in out, (label, out[-500:]))
        _nh_git(root, "reset", "-q")
    _nh_node(root, "A", extra="followups:\n  - REVISIT:2026-10-05 x", body="開頭")
    rc, out = _rv_stage_shape(root)
    check("③開頭欄位清單項的行首形狀:不報句中", "回頭條件寫在句中" not in out, out[-500:])
    _nh_git(root, "reset", "-q")
    _nh_node(root, "A", body="開頭\n| REVISIT:[when-file:t.py][by:2099-01-01] | 表格 |")
    rc, out = _rv_stage_shape(root)
    check("④表格裡帶條件標記:只報條件寫在不評估的地方、不重報", out.count("條件寫在不評估的地方") == 1
          and "回頭條件寫在句中" not in out, out[-500:])
    _nh_git(root, "reset", "-q")
    # S4:舊行就是句中 REVISIT,只在句尾補括號
    old = "這裡承認風險 `src/a.py:3`。REVISIT:2026-10-05 回頭看"
    root2 = _nh_repo()
    _nh_node(root2, "B", body=old)
    _nh_commit(root2, "old")
    _nh_node(root2, "B", body=old + "(更正:2026-10-03 已改 [來源:人工])")
    rc, out = _rv_stage_shape(root2)
    check("⑤舊行尾補括號:行號引用照片段扣掉(配對成立)、句中 REVISIT 照報", rc == 1 and "回頭條件寫在句中" in out
          and "程式行號引用" not in out, out[-500:])


def t_revisit_misplaced_ignores_mentions():
    """[S3] 只是提到這個字、行內程式碼裡、圍欄裡、在一對引號裡面的,不報。"""
    print("t_revisit_misplaced_ignores_mentions")
