def t_reread_fp_tip_names_deadline():
    """[S28] 判「分支自己的紀錄」那次列分岔點的紀錄檔名(ls-tree)也吃截止時間:剩 1.5 秒時那次 git 的逾時不超過 1.5 秒
    (原本走 20 秒的預設,會把留給後面的預算吃掉)。2026-10-14 代碼審 r4 併發 2 起吃的是呼叫端傳的整體截止時間、不是指紋這一步的
    (指紋這一步逾時,已算出的篇照常認;見 t_reread_fp_timeout_keeps_computed),所以這裡把 1.5 秒當整體截止時間傳、指紋這一步的設成已過。
    判準來源:代碼審 r1 併發席 2。翻紅釘:ls-tree 不帶截止時間 → ①紅。"""
    print("t_reread_fp_tip_names_deadline")
    import time as _t
    m = _load_lumos_inproc()
    root, base = _rfp_repo()
    g = m._note_reread_own_fps.__globals__
    real, seen = g["_lens_git"], []

    def spy(repo_root, *args, **kw):
        if "ls-tree" in args:
            seen.append(kw.get("timeout", 20))
        return real(repo_root, *args, **kw)
    scan = {"root": root, "tip": base, "fpbase": {"bp": base, "dl": _t.monotonic() - 1}}
    try:
        g["_lens_git"] = spy
        m._note_reread_own_fps(root, scan, [], {"0" * 16}, _t.monotonic() + 1.5)
    finally:
        g["_lens_git"] = real
    check("①ls-tree 的逾時夾進剩下的 1.5 秒", seen and all(t <= 1.5 for t in seen), str(seen))


def t_reread_fp_fallback_reasons():
    """[S29] 單檔與整篇退回 v1 的三種原因各走一次,事件記對原因:任一邊超過大小上限(太大)、一般檔變成符號連結(型別變更)、
    about_code 有一項拼錯或是資料夾(樹裡找不到)。對照組:同樣的分支不觸發時是 v2。
    判準來源:代碼審 r1 邊界席 2(拿掉對應判斷不會紅)。變異驗證:各拿掉那一道判斷 → 對應那條紅。"""
    print("t_reread_fp_fallback_reasons")
    import os as _os
    m = _load_lumos_inproc()
    root, base = _rfp_repo()
    _rfp_line(root, "src/a.py", 15, "a15 = 150")
    _rr_touch(root, _rr_note("A"), "A 追加")
    _nh_commit(root, "feat")
    rc, o, ev = _rfp_inproc(m, m.cmd_note_audit_reread_check, root, f"{base}..HEAD")
    check("①對照組:v2", _rfp_why(ev)[0] == 1, str(_rfp_ev(ev)))
    rc, o, ev = _rfp_inproc(m, m.cmd_note_audit_reread_check, root, f"{base}..HEAD", {"_NOTE_REREAD_FP_MAX": 10})
    v2n, why = _rfp_why(ev)
    check("②任一邊超過大小上限 → v1、記「太大」", v2n == 0 and why.get("太大") == 1, str(_rfp_ev(ev)))
    r2, b2 = _rfp_repo()
    (r2 / "src" / "a.py").unlink()
    _os.symlink("b.py", r2 / "src" / "a.py")
    _rr_touch(r2, _rr_note("A"), "A 追加")
    _nh_commit(r2, "a.py 變成符號連結")
    rc, o, ev = _rfp_check(r2, f"{b2}..HEAD")
    v2n, why = _rfp_why(ev)
    check("③一般檔變成符號連結 → v1、記「型別變更」", v2n == 0 and why.get("型別變更") == 1, str(_rfp_ev(ev)))
    for label, extra in (("拼錯", "src/nope.py"), ("資料夾", "src")):
        r3, b3 = _rfp_repo(lambda r, e=extra: _nh_node(r, "A", about=["src/a.py", e], body="A 的第一行"))
        _rfp_line(r3, "src/a.py", 15, "a15 = 150")
        _rr_touch(r3, _rr_note("A"), "A 追加")
        _nh_commit(r3, "feat")
        rc, o, ev = _rfp_check(r3, f"{b3}..HEAD")
        v2n, why = _rfp_why(ev)
        check(f"④about_code 有一項{label}({extra})→ v1、記「樹裡找不到」", v2n == 0 and why.get("樹裡找不到") == 1,
              str(_rfp_ev(ev)))


def t_reread_fp_literal_pathspec_names():
    """[S29] 檔名帶 [x]、* 這類萬用字元時,逐檔 diff 只拿那一支檔(--literal-pathspecs):A 管 src/[x].py、B 管 src/*.py;
    一條分支同時改了 src/x.py、src/a.py,另一條只改 [x].py 與 *.py(改法相同)→ 兩篇的 v2 指紋都跟另一條相同(別支檔的改動沒混進來)。
    判準來源:代碼審 r1 邊界席 2。變異驗證:拿掉 --literal-pathspecs → ②紅。"""
    print("t_reread_fp_literal_pathspec_names")
    m = _load_lumos_inproc()

    def setup(r):
        for f in ("src/[x].py", "src/*.py", "src/x.py"):
            _nh_file(r, f, "".join(f"k{i} = {i}\n" for i in range(1, 11)))
        _nh_node(r, "A", about=["src/[x].py"], body="A 的第一行")
        _nh_node(r, "B", about=["src/*.py"], body="B 的第一行")
    root, base = _rfp_repo(setup)

    def branch(name, files):
        _nh_git(root, "checkout", "-q", "-b", name, base)
        for f in files:
            _rfp_line(root, f, 5, "k5 = 50")
        _rr_touch(root, _rr_note("A"), "A 追加")
        _rr_touch(root, _rr_note("B"), "B 追加")
        _nh_commit(root, name)
        fps, _f, out = _rfp_items(root, f"{base}..HEAD")
        return fps, out
    wide, out = branch("wide", ["src/[x].py", "src/*.py", "src/x.py", "src/a.py"])
    narrow, _o = branch("narrow", ["src/[x].py", "src/*.py"])
    va = _rfp_v1(m, root, _rr_note("A"), ["src/[x].py"])
    check("①前置:兩篇都用 v2", wide.get(_rr_note("A")) not in (None, va) and wide.get(_rr_note("B")), f"{wide}\n{out[-400:]}")
    check("②只算各自那一支檔:另一條分支多改的 x.py、a.py 不影響指紋",
          wide.get(_rr_note("A")) == narrow.get(_rr_note("A")) and wide.get(_rr_note("B")) == narrow.get(_rr_note("B")),
          f"{wide}\n{narrow}")


def t_reread_fp_symlink_submodule_kinds():
    """[S29] 符號連結改目標、子模組指標改版:兩種都照樣算 v2,改成兩種不同的目標/版本時指紋不同。
    子模組用 update-index --cacheinfo 160000 造(指的提交不在本 repo,照實際情形)。
    判準來源:代碼審 r1 邊界席 2。變異驗證:大小查詢不跳過子模組 → ①紅(查不到大小、退回 v1);符號連結只記 mode 不記目標 → ②紅。"""
    print("t_reread_fp_symlink_submodule_kinds")
    import os as _os
    m = _load_lumos_inproc()
    about = ["src/a.py", "src/l", "sub"]

    def setup(r):
        _os.symlink("a.py", r / "src" / "l")
        _nh_node(r, "A", about=about, body="A 的第一行")
    root, base = _rfp_repo(setup)
    _nh_git(root, "checkout", "-q", "main")
    _nh_git(root, "update-index", "--add", "--cacheinfo", f"160000,{'1' * 40},sub")
    _nh_git(root, "commit", "-qm", "sub", "--no-verify")
    base = _na_head(root)
    _nh_git(root, "update-ref", "refs/remotes/origin/main", base)

    def branch(name, sub_sha, target):
        _nh_git(root, "checkout", "-q", "-B", name, base)
        _nh_git(root, "update-index", "--cacheinfo", f"160000,{sub_sha},sub")
        (root / "src" / "l").unlink()
        _os.symlink(target, root / "src" / "l")
        _rr_touch(root, _rr_note("A"), "A 追加")
        _rr_commit_index(root, name, "src/l", _rr_note("A"))
        fps, _f, out = _rfp_items(root, f"{base}..HEAD")
        return fps.get(_rr_note("A")), _rfp_v1(m, root, _rr_note("A"), about), out
    s1, v1a, out = branch("s1", "2" * 40, "b.py")
    s2, v1b, _o = branch("s2", "3" * 40, "b.py")
    check("①子模組指標改版:兩次都用 v2、指紋不同", s1 not in (None, v1a) and s2 not in (None, v1b) and s1 != s2,
          f"{s1} {v1a} {s2} {v1b}\n{out[-400:]}")
    s3, v1c, _o = branch("s3", "2" * 40, "c.py")
    check("②符號連結改成不同目標:用 v2、指紋不同", s3 not in (None, v1c) and s3 != s1, f"{s1} {s3}")


def t_reread_fp_added_deleted_files():
    """[S29] 新增檔與刪檔:A 管 src/a.py 與 src/n.py(分岔點沒有 n.py),兩條分支新增內容不同的 n.py → 都用 v2、指紋不同;
    B 管 src/b.py,一條刪掉、一條改掉 → 都用 v2、指紋不同。
    判準來源:代碼審 r1 邊界席 2。變異驗證:大小查詢不跳過全零物件編號 → ①②紅(查不到大小、退回 v1)。"""
    print("t_reread_fp_added_deleted_files")
    m = _load_lumos_inproc()
    root, base = _rfp_repo(lambda r: _nh_node(r, "A", about=["src/a.py", "src/n.py"], body="A 的第一行"))

    def branch(name, edit):
        _nh_git(root, "checkout", "-q", "-B", name, base)
        edit(root)
        _rr_touch(root, _rr_note("A"), "A 追加")
        _rr_touch(root, _rr_note("B"), "B 追加")
        _nh_commit(root, name)
        fps, _f, out = _rfp_items(root, f"{base}..HEAD")
        return fps, {n: _rfp_v1(m, root, _rr_note(n), [f"src/{f}.py" for f in fs]) for n, fs in (("A", "an"), ("B", "b"))}, out

    def n1(r):
        _nh_file(r, "src/n.py", "n = 1\n")
        (r / "src" / "b.py").unlink()

    def n2(r):
        _nh_file(r, "src/n.py", "n = 2\n")
        _rfp_line(r, "src/b.py", 3, "b3 = 30")
    one, v1s, out = branch("n1", n1)
    two, v2s, _o = branch("n2", n2)
    a1, a2, b1, b2 = (one.get(_rr_note("A")), two.get(_rr_note("A")), one.get(_rr_note("B")), two.get(_rr_note("B")))
    check("①新增檔:兩條都用 v2、內容不同指紋不同", a1 not in (None, v1s["A"]) and a2 not in (None, v2s["A"]) and a1 != a2,
          f"{one}\n{two}\n{out[-400:]}")
    check("②刪檔對改檔:兩條都用 v2、指紋不同", b1 not in (None, v1s["B"]) and b2 not in (None, v2s["B"]) and b1 != b2,
          f"{one}\n{two}")


def t_reread_fp_forged_record_no_more_than_v1():
    """[S30] 範圍終點在本機找不到的紀錄算分支自己的(rebase 前的舊頂端被 gc 時要用到),所以手寫一份這樣的 v2 紀錄就能命中——
    釘住它的效力最多等同手寫一份 v1 紀錄:兩種都只替檔名那一個指紋背書;作者自己的改動一變,兩種都不再命中;來源核對沒過的
    兩種都不算。判準來源:代碼審 r1 資安席 2(判定是不多給權力,寫進計劃〈實務隱患〉)。"""
    print("t_reread_fp_forged_record_no_more_than_v1")
    import json as _j
    m = _load_lumos_inproc()
    root, base = _rfp_repo()
    _rfp_line(root, "src/a.py", 15, "a15 = 150")
    _rr_touch(root, _rr_note("A"), "A 追加")
    _nh_commit(root, "feat")
    fps, _f, _o = _rfp_items(root, f"{base}..HEAD")
    v2, v1 = fps.get(_rr_note("A")), _rfp_v1(m, root, _rr_note("A"), ["src/a.py"])
    d = root / "governance" / "reread-verdicts"
    d.mkdir(parents=True, exist_ok=True)

    def forge(fp, ok=True):
        for p in d.glob("*.json"):
            p.unlink()
        doc = {"version": 1, "provenance_ok": ok, "note": _rr_note("A"), "contrast_fp": fp, "tip": "f" * 40, "rows": []}
        (d / f"{fp}-20991231T000000Z-{'e' * 32}.json").write_text(_j.dumps(doc), encoding="utf-8")
        _nh_commit(root, "forge")
        rc, o, ev = _rfp_check(root, f"{base}..HEAD")
        return _rfp_ev(ev).get("covered_by"), o
    check("①前置:v2 與 v1 不同", v2 and v2 != v1, f"{v2} {v1}")
    cv2, o = forge(v2)
    cv1, o1 = forge(v1)
    check("②手寫的 v2 紀錄(範圍終點找不到)命中,手寫的 v1 紀錄也命中——效力相同",
          cv2 == {"v1": 0, "v2": 1} and cv1 == {"v1": 1, "v2": 0}, f"{cv2} {cv1}")
    bad2, _o = forge(v2, ok=False)
    bad1, _o = forge(v1, ok=False)
    check("③來源核對沒過的兩種都不算", bad2 == {"v1": 0, "v2": 0} and bad1 == {"v1": 0, "v2": 0}, f"{bad2} {bad1}")
    forge(v2)
    _rfp_line(root, "src/a.py", 15, "a15 = 151")
    _nh_commit(root, "作者的改動變了")
    rc, o, ev = _rfp_check(root, f"{base}..HEAD")
    check("④作者自己的改動一變,手寫的 v2 紀錄不再命中(只替檔名那一個指紋背書)",
          _rfp_ev(ev).get("covered_by") == {"v1": 0, "v2": 0} and "Systems/A.md" in o, f"{o[-400:]}\n{_rfp_ev(ev)}")


# ── 代碼審 code-回頭重讀指紋 r3 修正(2026-10-14):收尾符號行、逾時照擋、替身物件、偽造遠端追蹤 ref、兩份縮排算法 ─────────────
def t_reread_fp_chain_skips_punct_lines():
    """[S21] 縮排鏈(與起點)跳過「沒有任何字母或數字的行」(只有括號、標點、空白,例如 `{`、`}`、`):`、`];`),跟空行一樣:
    black 風格的多行簽名、Allman 大括號、C 函式另起一行的大括號,鏈都落在函式那一行,不是收尾符號。期望值照規則逐行手算。
    判準來源:代碼審 r3 正確性 1、邊界 1(實測 Allman 的 C# 兩個方法鏈都是 ('{', '{')、black 風格兩個函式都是 ('):',))。
    應抓到的錯:不跳過標點行 → ①②③④⑤紅;起點不跳過標點行 → ④紅;有字的頂格行(#endif)也跳過 → ⑥紅(那是另一條規則);
    純標點的改動照舊當成無限深(代碼審 r4 邊界 2:鏈多一層,鄰近的參數行被主線改就要多重讀一次)→ ⑦⑧紅;空行也套縮排 → ⑨紅。"""
    print("t_reread_fp_chain_skips_punct_lines")
    m = _load_lumos_inproc()
    py_lines = [
        "def f(",          # 1
        "    a,",          # 2
        "    b,",          # 3
        "):",              # 4
        "    x1 = 1",      # 5
        "",                # 6
        "def g(",          # 7
        "    a,",          # 8
        "):",              # 9
        "    x1 = 1",      # 10
    ]
    cs_lines = [
        "class A",         # 1
        "{",               # 2
        "    void F()",    # 3
        "    {",           # 4
        "        a();",    # 5
        "    }",           # 6
        "    void G()",    # 7
        "    {",           # 8
        "        a();",    # 9
        "    });",         # 10 只有標點
        "}",               # 11
    ]
    c_lines = [
        "int pub(struct user *u)",   # 1
        "{",                         # 2
        "    a();",                  # 3
        "#endif",                    # 4 有字的頂格行照舊截斷
        "    b();",                  # 5
        "}",                         # 6
    ]
    py, cs, c = ("\n".join(x).encode("utf-8") for x in (py_lines, cs_lines, c_lines))
    cases = [
        ("①black 風格:f 的本體 → def f(", py, (5, 1), ["def f("]),
        ("②black 風格:g 的本體 → def g(", py, (10, 1), ["def g("]),
        ("③Allman:F 的本體 → class A、void F()", cs, (5, 1), ["class A", "void F()"]),
        ("④Allman:範圍從 `    {` 起 → 起點是下一行 a();、鏈是 class A、void G()", cs, (8, 2), ["class A", "void G()"]),
        ("⑤C 另起一行的大括號 → int pub(...)", c, (3, 1), ["int pub(struct user *u)"]),
        ("⑥有字的頂格行(#endif)照舊算一層", c, (5, 1), ["#endif"]),
        ("⑦範圍只有標點行 → 從那一行自己的縮排(4)往外推,只收縮排比它淺的行", cs, (10, 1), ["class A"]),
        ("⑧邊界席的例子:只改 `)`(縮排 8)→ 鏈是 def f():、if a:(不含同層的 x( 與更深的 1,)",
         b"def f():\n    if a:\n        x(\n            1,\n        )\n", (5, 1), ["def f():", "if a:"]),
        ("⑨範圍只有空行 → 照舊當成無限深,從上面最近有字的行起整條鏈", cs + b"\n\n", (12, 1), ["class A", "void G()", "a();"]),
    ]
    for label, data, span, want in cases:
        got = list(m._note_reread_hunk_chains(data, [span])[0])
        check(label, got == want, f"{got!r} != {want!r}")


# 每種寫法兩個結構相同的函式,收尾符號行在整個檔裡到處重複(代碼審 r3 正確性 1、邊界 1、邊界 2)
_RFP_LANGS_R3 = {
    ("P1", "src/black.py"): (["def pub(", "    u,", "    v,", "):"] + _rfp_body("    ") + ["", "", "def adm(", "    u,",
                             "    v,", "):"] + _rfp_body("    ")),
    ("P2", "src/Svc.cs"): (["class Svc", "{", "    void Pub(User u)", "    {"] + _rfp_body("        ", ";")
                           + ["    }", "", "    void Adm(User u)", "    {"] + _rfp_body("        ", ";") + ["    }", "}"]),
    ("P3", "src/brace.c"): (["int pub(struct user *u)", "{"] + _rfp_body("    ", ";") + ["}", "", "int adm(struct user *u)", "{"]
                            + _rfp_body("    ", ";") + ["}"]),
    ("P4", "src/Allman.java"): (["public class Svc", "{", "    public void pub(User u)", "    {"] + _rfp_body("        ", ";")
                                + ["    }", "", "    public void adm(User u)", "    {"] + _rfp_body("        ", ";")
                                + ["    }", "}"]),
}


def t_reread_fp_moved_past_punct_lines():
    """[S20] 同一段改動搬到同檔另一個結構相同的函式、前後三行逐字相同 → v2 指紋不同,收尾符號行到處重複的寫法:black 風格的多行
    簽名(`):`)、Allman 的 C# 與 Java(`{` 另起一行)、C 函式另起一行的大括號。兩條分支都先確認用 v2。
    判準來源:代碼審 r3 正確性 1(實測)。應抓到的錯:鏈不跳過標點行 → 四種寫法全紅(兩個函式的鏈都是收尾符號)。"""
    print("t_reread_fp_moved_past_punct_lines")
    _rfp_moved_check(_load_lumos_inproc(), _RFP_LANGS_R3)


def t_reread_fp_outer_line_changes_fp():
    """[S22] 代價:縮排鏈含外層那一行的原文,主線改了作者那段所在函式的簽名(Allman 的 C# 方法那一行、black 風格的 def 那一行),
    作者 rebase 上去 → 指紋會變(多要求一次重讀,方向是多擋);主線只改了另一個函式的簽名 → 指紋不變。改動都離作者那段超過三行。
    判準來源:代碼審 r3 邊界 2(原本只測了一行寫完的 Python def)。應抓到的錯:鏈不含外層那一行(只看收尾符號或只看改動本身)→ ③紅;
    鏈含整個檔的頂格行 → ②紅。"""
    print("t_reread_fp_outer_line_changes_fp")
    m = _load_lumos_inproc()
    cs = _RFP_LANGS_R3[("P2", "src/Svc.cs")]
    py = _RFP_LANGS_R3[("P1", "src/black.py")]

    def setup(r):
        _nh_file(r, "src/Svc.cs", "\n".join(cs) + "\n")
        _nh_file(r, "src/black.py", "\n".join(py) + "\n")
        _nh_node(r, "A", about=["src/Svc.cs", "src/black.py"], body="A 的第一行")
    root, base = _rfp_repo(setup)
    for rel, lines in (("src/Svc.cs", cs), ("src/black.py", py)):
        idx = [i for i, t in enumerate(lines) if "check(u)" in t][1]
        _rfp_line(root, rel, idx + 1, lines[idx].replace("check(u)", "allow(u)"))
    _rr_touch(root, _rr_note("A"), "A 追加")
    _nh_commit(root, "feat")
    fp0 = _rfp_items(root, f"{base}..HEAD")[0].get(_rr_note("A"))
    check("①前置:用 v2", fp0 and fp0 != _rfp_v1(m, root, _rr_note("A"), ["src/Svc.cs", "src/black.py"]), str(fp0))

    def sub(rel, old, new):
        def edit(r):
            p = r / rel
            p.write_text(p.read_text(encoding="utf-8").replace(old, new, 1), encoding="utf-8")
        return edit
    rb = _rfp_main_advance(root, sub("src/Svc.cs", "void Pub(User u)", "void Pub(User u, int n)"))
    fp1 = _rfp_items(root, f"{_RFP_ZERO}..HEAD", *_rfp_push())[0].get(_rr_note("A"))
    check("②主線只改另一個方法 Pub 的簽名 → 指紋不變", rb.returncode == 0 and fp1 == fp0, f"{rb.stderr}\n{fp1} {fp0}")
    rb = _rfp_main_advance(root, sub("src/Svc.cs", "void Adm(User u)", "void Adm(User u, int n)"))
    fp2 = _rfp_items(root, f"{_RFP_ZERO}..HEAD", *_rfp_push())[0].get(_rr_note("A"))
    rb2 = _rfp_main_advance(root, sub("src/black.py", "def adm(", "def adm2("))
    fp3 = _rfp_items(root, f"{_RFP_ZERO}..HEAD", *_rfp_push())[0].get(_rr_note("A"))
    v1 = _rfp_v1(m, root, _rr_note("A"), ["src/Svc.cs", "src/black.py"])
    check("③主線改了作者那段所在方法 Adm 的簽名、再改所在函式 def adm( → 指紋各變一次(仍是 v2)",
          rb.returncode == 0 and rb2.returncode == 0 and fp2 not in (None, fp0) and fp3 not in (None, fp0, fp2) and fp3 != v1,
          f"{rb.stderr}{rb2.stderr}\n{fp0} {fp2} {fp3}")


def t_reread_fp_indent_inline_same():
    """縮排算法有兩份:獨立的 _note_reread_indent(挑起點用)與 _note_reread_hunk_nodes 熱迴圈裡內聯的那份。同一批輸入兩邊要一樣:
    內聯那份的縮排從外面量——那一行下面放一行縮排 j 的探針、起點設在探針,那一行進鏈 ⇔ 它不被跳過而且縮排 < j,所以「最小的 j」減 1
    就是內聯那份算出的縮排;從來不進鏈就是被跳過(None)。另有幾個手算的期望值(tab 8 欄、空白加 tab、標點行與空白行跳過、頂格 0)。
    判準來源:代碼審 r3 架構對齊 1(兩份各改一邊會漂移)。應抓到的錯:只改一邊的 tab 欄寬或跳過規則 → 對應那幾行紅。"""
    print("t_reread_fp_indent_inline_same")
    m = _load_lumos_inproc()
    want = {b"x": 0, b"    x": 4, b"\tx": 8, b"  \tx": 8, b"\t  x": 10, b"   ": None, b"": None, b"\t": None, b"}": None,
            b"    ):": None, b"  ];": None, b"#endif": 0, b"  \xe4\xb8\xad": 2, b"\x0cx": 0, b"x\r": 0, b"  }\r": None,
            b" \t \x0b": None, b"        y = 2": 8}
    for ln, exp in want.items():
        alone = m._note_reread_indent(ln)
        inline = None
        for j in range(1, 40):
            chain = m._note_reread_hunk_chains(ln + b"\n" + b" " * j + b"p", [(2, 1)])[0]
            if chain:
                inline = j - 1
                break
        check(f"{ln!r}:獨立函式 {alone!r}、內聯 {inline!r}、手算 {exp!r} 三者相同", alone == inline == exp, f"{alone} {inline} {exp}")


def t_reread_fp_timeout_blocks():
    """[S27] check 因逾時沒算出新版指紋的篇照舊版判、照擋(代碼審 r3 資安 1:堆三千個垃圾檔撐到逾時,原本整篇放行、rc0)。
    縮小規模重現資安席的情境:A 的 about_code 列了 40 支這條分支新增的垃圾檔,真的算指紋、算到第 6 支時截止時間到(替身
    把指紋這一步的截止時間改成已過,模擬 27 秒用完,後面走真的逾時路徑);block 加 --gate → ①擋下(rc1、blocked、late=1),那篇講明
    「這篇因為逾時沒算出新版指紋,照舊版判」、給跳過的環境變數、照實講「機器忙時重推可能就會過」與跳過的帳記在哪
    (代碼審 r4 通才 2、資安 4:原本寫「重跑也一樣」「跳過會留帳」,都說得比實際強;r5 合約 1:r4 改成「只留在本機帳」又說錯,
    skipped-env 不在本機帳白名單、寫進有進版控的 docs/.governance-log.jsonl),而且不出現「這次不擋」;①b 照訊息真的單次跳過一次,
    看事件落在哪一本;②warn 加 --gate → rc0、
    只提醒、不印跳過那句也不印「擋下」;③對照組:預算夠、真的算出指紋 → 擋下但不提逾時。
    判準來源:代碼審 r3 資安 1、正確性 2、併發 3、通才 1(擋下與不擋同時出現)、合約 2。
    應抓到的錯:逾時的篇照舊排除在擋之外 → ①紅;訊息照舊說這次不擋 → ①紅;warn 也擋 → ②紅。"""
    print("t_reread_fp_timeout_blocks")
    import time as _t
    m = _load_lumos_inproc()
    junk = [f"junk/f{i}.txt" for i in range(40)]
    root, base = _rfp_repo(lambda r: _nh_node(r, "A", about=["src/a.py", *junk], body="A 的第一行"))
    for rel in junk:
        _nh_file(root, rel, f"junk {rel}\n")
    _rfp_line(root, "src/a.py", 15, "a15 = 150")
    _rr_touch(root, _rr_note("A"), "A 追加")
    _nh_commit(root, "feat")
    rng, chk = f"{base}..HEAD", m.cmd_note_audit_reread_check
    real, calls = m._note_reread_fp_file, []

    def late(scan, fbase, ent):    # 算到第 6 支檔時把指紋這一步的截止時間改成已過,後面照真的逾時路徑走
        calls.append(ent["path"])
        if len(calls) >= 6:
            fbase["dl"] = _t.monotonic() - 1
        return real(scan, fbase, ent)
    rc, o, ev = _rfp_inproc(m, chk, root, rng, {"_note_reread_fp_file": late}, gate=True)
    e = _rfp_ev(ev)
    check("①逾時沒算出新版指紋 → 照舊版判、擋下(rc1、blocked、late=1)、講明原因與跳過指令、不說這次不擋",
          rc == 1 and e.get("kind") == "blocked" and e.get("late") == 1 and _rfp_why(ev)[1].get("逾時") == 1
          and "這篇因為逾時沒算出新版指紋,照舊版判" in o and "LUMOS_SKIP_REREAD_CHECK=1" in o
          and "跳過記進 docs/.governance-log.jsonl(有進版控,跟著帳本提交送出)" in o and "本機帳" not in o
          and "機器忙時重推可能就會過" in o and "重跑也一樣" not in o
          and "不擋" not in o, f"rc={rc}\n{o[-1200:]}\n{e}")
    import json as _j
    docs = root / "docs"
    n_log, n_local = (len(p.read_text(encoding="utf-8").splitlines()) if p.is_file() else 0
                      for p in (docs / ".governance-log.jsonl", docs / ".governance-local.jsonl"))
    rc_s, _o, _e = _rr(root, "reread-check", "--gate", "--diff", rng, env={"LUMOS_SKIP_REREAD_CHECK": "1"})
    new_log = (docs / ".governance-log.jsonl").read_text(encoding="utf-8").splitlines()[n_log:]
    new_local = (docs / ".governance-local.jsonl").read_text(encoding="utf-8").splitlines()[n_local:] \
        if (docs / ".governance-local.jsonl").is_file() else []
    check("①b照訊息說的單次跳過 → rc0、印的帳位置照實、skipped-env 記進 docs/.governance-log.jsonl(不是本機帳)",
          rc_s == 0 and "已記進 docs/.governance-log.jsonl" in _o and "本機" not in _o
          and any((_j.loads(x).get("gate"), _j.loads(x).get("kind")) == ("note-reread", "skipped-env") for x in new_log)
          and not any('"note-reread"' in x for x in new_local), f"rc={rc_s}\n{_o}\n{new_log}\n{new_local}")
    _nh_file(root, ".lumos/config.json", '{"note_reread": {"gate": "warn"}}\n')
    _nh_commit(root, "warn")
    calls.clear()
    rc, o, ev = _rfp_inproc(m, chk, root, f"{base}..HEAD", {"_note_reread_fp_file": late}, gate=True)
    check("②warn 模式 → rc0、只提醒(講明照舊版判)、不印擋下也不印跳過指令",
          rc == 0 and "擋下" not in o and "照舊版判" in o and "LUMOS_SKIP_REREAD_CHECK=1" not in o and _rfp_ev(ev).get("late") == 1,
          f"rc={rc}\n{o[-900:]}")
    _nh_git(root, "reset", "-q", "--hard", "HEAD~1")
    rc, o, ev = _rfp_inproc(m, chk, root, rng, gate=True)
    check("③對照組:預算夠 → 擋下、late=0、不提逾時", rc == 1 and _rfp_ev(ev).get("late") == 0 and "逾時" not in o,
          f"rc={rc}\n{o[-600:]}")


def t_reread_fp_prefetch_walk_order():
    """[S26] 批次讀照算指紋實際走的順序讀:候選照筆記路徑排序走、每篇裡照 about_code 鍵排序走。八篇筆記 N0..N7 各管一支檔,
    N_i 管 src/f{7-i}.py(走的順序是 f7、f6…f0,剛好跟檔名排序相反);每支檔約 1500 位元組、總量上限 4500(一批裝兩支)→
    批次讀應是 ceil(8/2)=4 次,指紋跟不設上限時相同。判準來源:代碼審 r3 併發 1(實測反序 120 支 1 MB 的檔讀了 120 批、7.5 秒,
    照順序 2 批)。應抓到的錯:批次讀照全部 about_code 鍵的排序讀 → 8 次(每支都缺、從它起往後讀到底只剩它與它後面已讀過的)。"""
    print("t_reread_fp_prefetch_walk_order")
    m = _load_lumos_inproc()
    n = 8

    def setup(r):
        for i in range(n):
            rel = f"src/f{n - 1 - i}.py"
            _nh_file(r, rel, "".join(f"v{j} = {j}  # f{n - 1 - i}\n" for j in range(100)))
            _nh_node(r, f"N{i}", about=[rel], body=f"N{i} 的第一行")
    root, base = _rfp_repo(setup)
    for i in range(n):
        _rfp_line(root, f"src/f{i}.py", 50, f"v49 = {i}")
        _rr_touch(root, _rr_note(f"N{i}"), "追加")
    _nh_commit(root, "feat")
    size = len((root / "src" / "f0.py").read_bytes())
    rng, chk = f"{base}..HEAD", m.cmd_note_audit_reread_check
    _rc, _o, ev = _rfp_inproc(m, chk, root, rng)
    ref = {x["path"]: x["fp"] for x in (_rfp_ev(ev).get("layer1_fps") or [])}
    real, seen = m._nodehome_cat_blobs, []

    def spy(repo_root, specs, *a, **k):
        got = real(repo_root, specs, *a, **k)
        if specs and all(":" not in s for s in specs):
            seen.append(len(specs))
        return got
    _rc, _o, ev = _rfp_inproc(m, chk, root, rng, {"_nodehome_cat_blobs": spy, "_NOTE_REREAD_FP_PREFETCH_TOTAL": 2 * size + 500})
    got = {x["path"]: x["fp"] for x in (_rfp_ev(ev).get("layer1_fps") or [])}
    check("前置:八篇都用 v2、每支檔約 1500 位元組", _rfp_why(ev)[0] == n and 1000 < size < 2500, f"{_rfp_why(ev)} {size}")
    check("①反序的候選:批次讀 4 次(一批兩支)", len(seen) == 4, str(seen))
    check("②指紋跟不設上限時相同", got == ref and len(got) == n, f"{got} {ref}")


def t_reread_fp_chain_deadline():
    """[S28] 縮排鏈的計算看截止時間(代碼審 r3 併發 2:32 MB 的檔掃到檔尾要幾秒,原本完全不看截止時間):①直接呼叫,截止時間已過
    → 不算(回 None);同一份輸入不給截止時間 → 算得出;②截止時間在算鏈的時候到(替身只在 _note_reread_hunk_nodes 裡回 True)→ 那支檔
    退回舊版、原因記「逾時」、block 加 --gate 照擋。應抓到的錯:鏈的計算不看截止時間 → ①②紅。"""
    print("t_reread_fp_chain_deadline")
    import sys as _s
    import time as _t
    m = _load_lumos_inproc()
    data = b"def f():\n" + b"    x = 1\n" * 50000
    check("①截止時間已過 → 不算(None);不給截止時間 → 算得出",
          m._note_reread_hunk_tags(data, [(50000, 1)], deadline=_t.monotonic() - 1) is None
          and m._note_reread_hunk_tags(data, [(50000, 1)]) not in (None, [""]), "")
    root, base = _rfp_repo()
    _rfp_line(root, "src/a.py", 15, "a15 = 150")
    _rr_touch(root, _rr_note("A"), "A 追加")
    _nh_commit(root, "feat")
    real = m._note_reread_fp_expired

    def in_chain(dl):
        return True if _s._getframe(1).f_code.co_name == "_note_reread_hunk_nodes" else real(dl)
    rc, o, ev = _rfp_inproc(m, m.cmd_note_audit_reread_check, root, f"{base}..HEAD", {"_note_reread_fp_expired": in_chain},
                            gate=True)
    check("②截止時間在算鏈時到 → 退回舊版、原因「逾時」、照擋", rc == 1 and _rfp_why(ev) == (0, {"逾時": 1}), f"rc={rc}\n{o[-600:]}")


def _rfp_two_branches(root, base, extra=None):
    """從 base 開兩條分支,都把 src/a.py 第 15 行改成 a15 = 150、A 追加一行;attack 那條先多一個改第 5 行的提交(extra 給了就用它)。
    回 (honest 頂端, attack 那個多出來的提交, attack 頂端)。"""
    _nh_git(root, "checkout", "-q", "-b", "honest", base)
    _rfp_line(root, "src/a.py", 15, "a15 = 150")
    _rr_touch(root, _rr_note("A"), "A 追加")
    _nh_commit(root, "honest")
    honest = _na_head(root)
    _nh_git(root, "checkout", "-q", "-b", "attack", base)
    _rfp_line(root, "src/a.py", 5, extra or "a5 = 'evil'")
    _nh_commit(root, "evil")
    evil = _na_head(root)
    _rfp_line(root, "src/a.py", 15, "a15 = 150")
    _rr_touch(root, _rr_note("A"), "A 追加")
    _nh_commit(root, "honest again")
    return honest, evil, _na_head(root)


def t_reread_fp_ignores_replace_refs():
    """git replace 的替身物件不影響指紋(代碼審 r3 資安 3):attack 分支多藏一個改第 5 行的提交,再 `git replace <attack 頂端> <honest 頂端>`,
    git 讀 attack 頂端時讀到的是 honest 那個提交(推出去的卻是真的 attack 提交)。reread-prepare(走 lumos 主程式入口)算出的 attack 指紋
    應跟 honest 的不同、跟沒設替身時一樣。判準來源:資安席實測(替身讓指紋與 honest 相同);統一規則在主程式入口設
    GIT_NO_REPLACE_OBJECTS=1。lumos 子行程的環境拿掉入口會設的變數(外層殼帶著時防護也只能來自入口)。應抓到的錯:入口不設 → ③紅。"""
    print("t_reread_fp_ignores_replace_refs")
    root, base = _rfp_repo()
    honest, _evil, attack = _rfp_two_branches(root, base)
    fh = _rfp_items_attack(root, f"{base}..{honest}")[0].get(_rr_note("A"))
    fa = _rfp_items_attack(root, f"{base}..{attack}")[0].get(_rr_note("A"))
    check("①前置:沒設替身時 attack 與 honest 的指紋不同", fh and fa and fh != fa, f"{fh} {fa}")
    r = _nh_git(root, "replace", attack, honest)
    seen = _rfp_git_raw(root, "rev-parse", f"{attack}^{{tree}}").stdout.strip()
    check("②前置:一般 git(不帶入口的環境變數)讀 attack 頂端讀到的是 honest 的樹",
          r.returncode == 0 and seen == _rfp_git_raw(root, "rev-parse", f"{honest}^{{tree}}").stdout.strip(), f"{r.stderr} {seen}")
    fr = _rfp_items_attack(root, f"{base}..{attack}")[0].get(_rr_note("A"))
    check("③設了替身 → attack 的指紋照舊是真提交的那個、不等於 honest", fr == fa and fr != fh, f"{fr} {fa} {fh}")


def t_reread_fp_forged_tracking_ref_blocks():
    """推主線時,分岔點直接用 pre-push 給的遠端舊值算(代碼審 r3 資安 2、r4 資安 1 換形狀):本機把 refs/remotes/origin/main 指到 attack
    分支上藏了改動的那個提交,照它算的分岔點會落在藏了改動的提交上、指紋看不到那段;記了紀錄(prepare 不帶推送參數,分岔點照本機
    追蹤 ref)之後 reread-check --gate 推 refs/heads/main(遠端舊值是真的主線 base)→ ①分岔點改用遠端舊值算、指紋含藏起來的改動、
    跟紀錄對不上 → 擋下、A 列在沒有紀錄底下;②對照組:origin/main 沒被動過、同一套流程 → 照常放行;③對照組:功能分支 rebase 到前進了的
    主線後強推(遠端舊值是 rebase 前的頂端)→ 不擋(功能分支照舊用本機主線候選);④同上、主線改的是 a.py 別處 → 照樣靠 v2 命中。
    判準來源:資安席實測(偽造之後指紋與 honest 相同、紀錄照樣命中)。應抓到的錯:推主線仍用本機追蹤 ref 算分岔點 → ①紅;
    功能分支也改用遠端舊值 → ④紅(分岔點變成 rebase 前那條分支跟新頂端的共同祖先,主線帶進來的 a.py 改動被算成自己的)。"""
    print("t_reread_fp_forged_tracking_ref_blocks")
    tmp = Path(tempfile.mkdtemp(prefix="gctl-rfp-"))
    root, base = _rfp_forged(tmp)
    rc, o, e = _rr(root, "reread-check", "--gate", "--diff", f"{base}..HEAD", "--push-remote", "origin",
                   "--pushed-ref", "refs/heads/main")
    check("①偽造的遠端追蹤 ref、推主線 → 分岔點用遠端舊值算、對不上紀錄 → 擋下、列出 A", rc == 1 and "擋下" in e
          and "Systems/A.md" in e and "沒有紀錄" in e, f"rc={rc}\n{o[-400:]}\n{e[-800:]}")
    root2, base2 = _rfp_repo()
    _rfp_line(root2, "src/a.py", 15, "a15 = 150")
    _rr_touch(root2, _rr_note("A"), "A 追加")
    _nh_commit(root2, "honest")
    _rfp_record(root2, f"{base2}..HEAD", tmp)
    rc, o, e = _rr(root2, "reread-check", "--gate", "--diff", f"{base2}..HEAD", "--push-remote", "origin",
                   "--pushed-ref", "refs/heads/main")
    check("②對照組:沒偽造、推主線 → 放行", rc == 0 and "擋下" not in e and "都對照過" in o, f"rc={rc}\n{o[-400:]}\n{e[-400:]}")
    old = _na_head(root2)
    rb = _rfp_main_advance(root2, lambda r: _rfp_line(r, "src/b.py", 3, "b3 = 30"))
    rc, o, e = _rr(root2, "reread-check", "--gate", "--diff", f"{old}..HEAD", *_rfp_push())
    check("③對照組:功能分支 rebase 後強推 → 不擋(紀錄照樣命中)", rb.returncode == 0 and rc == 0 and "擋下" not in e,
          f"rc={rc}\n{o[-400:]}\n{e[-400:]}")
    old = _na_head(root2)
    rb = _rfp_main_advance(root2, lambda r: _rfp_line(r, "src/a.py", 2, "a2 = 20"))
    rc, o, e = _rr(root2, "reread-check", "--gate", "--diff", f"{old}..HEAD", *_rfp_push())
    check("④對照組:主線改了 a.py 別處、功能分支 rebase 後強推 → 照本機主線候選算、靠 v2 命中不擋",
          rb.returncode == 0 and rc == 0 and "擋下" not in e and "都對照過" in o, f"rc={rc}\n{o[-400:]}\n{e[-400:]}")


# lumos 主程式入口會設或清的 git 環境變數(main() 開頭那一段);攻擊測試的前置檢查要用不帶它們的 git,確認攻擊在一般 git 底下真的生效——
# 測試行程可能帶著它們(外層殼設的,或行程內呼叫過 main())
_RFP_GIT_ENV = ("GIT_NO_REPLACE_OBJECTS", "GIT_GRAFT_FILE", "GIT_DIFF_OPTS", "GIT_EXTERNAL_DIFF")


def _rfp_git_raw(root, *a, env=None):
    """不帶 _RFP_GIT_ENV 跑 git(再加 env)→ CompletedProcess。"""
    import os as _os
    import subprocess as sp
    e = {k: v for k, v in _os.environ.items() if k not in _RFP_GIT_ENV}
    e.update(env or {})
    return sp.run(["git", "-C", str(root), *a], capture_output=True, text=True, errors="replace", env=e, check=False)


def _rfp_items_attack(root, rng, env=None):
    """reread-prepare --all,lumos 子行程的環境拿掉 _RFP_GIT_ENV(防護只能來自 lumos 入口自己,外層殼帶著也不算)、再加 env
    → ({筆記路徑: 對照指紋}, 輸出)。"""
    import os as _os
    import re as _re
    import subprocess as sp
    e = {k: v for k, v in _os.environ.items() if k not in _RFP_GIT_ENV + ("LUMOS_SKIP_REREAD_CHECK", "CI", "GITHUB_ACTIONS")}
    e.update(env or {})
    r = sp.run([sys.executable, GRAPHCTL, "note-audit", "reread-prepare", "--diff", rng, "--orchestrator", "claude", "--all",
                "--repo", str(root)], capture_output=True, text=True, env=e, check=False)
    files = [Path(f) for f in _re.findall(r"項目檔:(\S+\.md)$", r.stdout, _re.MULTILINE)]
    return {_rr_meta(f)["筆記路徑"]: _rr_meta(f)["對照指紋"] for f in files}, r.stdout + r.stderr


def _rfp_forged(tmp):
    """偽造遠端追蹤 ref 的夾具:honest、attack 兩條分支(_rfp_two_branches)、refs/remotes/origin/main 指到 attack 上藏了改動的那個提交,
    在 attack 上照偽造的分岔點記好紀錄(prepare 不帶推送參數)。回 (根, 真的主線 base)。"""
    root, base = _rfp_repo()
    _honest, evil, _attack = _rfp_two_branches(root, base)
    _nh_git(root, "update-ref", "refs/remotes/origin/main", evil)
    _rfp_record(root, f"{evil}..HEAD", tmp)
    return root, base


def t_reread_fp_mainline_alias_remote_blocks():
    """推主線的判定看被推的 ref 名、不看遠端名(代碼審 r4 資安 1):偽造 origin/main 之後,另加一個指向同一網址的別名遠端 o2 推 main、
    或直接推網址,遠端舊值照樣是真的主線 base → 分岔點用它算、對不上照偽造分岔點記的紀錄 → 擋下。
    判準來源:資安席實測(別名遠端與網址都 rc0)。應抓到的錯:推主線的判定綁在 refs/remotes/<遠端名>/<分支> 是不是主線候選 → ①②紅。"""
    print("t_reread_fp_mainline_alias_remote_blocks")
    tmp = Path(tempfile.mkdtemp(prefix="gctl-rfp-"))
    root, base = _rfp_forged(tmp)
    url = str(root / "nowhere")
    _nh_git(root, "remote", "add", "o2", url)
    for label, remote in (("①別名遠端 o2", "o2"), ("②直接推網址", url)):
        rc, o, e = _rr(root, "reread-check", "--gate", "--diff", f"{base}..HEAD", "--push-remote", remote,
                       "--pushed-ref", "refs/heads/main")
        check(f"{label} 推 main、本機 origin/main 被偽造 → 擋下、列出 A", rc == 1 and "Systems/A.md" in e and "沒有紀錄" in e,
              f"rc={rc}\n{o[-400:]}\n{e[-600:]}")


def t_reread_fp_fork_remote_main_uses_old():
    """推到別的遠端(fork)的 main:分岔點用 pre-push 給的 fork 遠端舊值算,本機 origin/main 偽造無效(代碼審 r4 正確性 1)。
    ①check 印的 A 指紋 = 帶同一組推送參數的 prepare 算的(用遠端舊值)、≠ 照偽造分岔點記的紀錄 → 擋下;②前置:帶推送參數的 prepare
    跟不帶的指紋不同(證明真的換了分岔點)。判準來源:正確性席的情境(推 fork 的 main、分岔點取自 origin/main)。
    應抓到的錯:推到非 origin 的遠端時不改用遠端舊值 → ①紅。"""
    print("t_reread_fp_fork_remote_main_uses_old")
    tmp = Path(tempfile.mkdtemp(prefix="gctl-rfp-"))
    root, base = _rfp_forged(tmp)
    _nh_git(root, "remote", "add", "fork", str(root / "fork"))
    _nh_git(root, "update-ref", "refs/remotes/fork/main", base)
    push = ("--push-remote", "fork", "--pushed-ref", "refs/heads/main")
    with_old = _rfp_items(root, f"{base}..HEAD", *push)[0].get(_rr_note("A"))
    local = _rfp_items(root, f"{base}..HEAD")[0].get(_rr_note("A"))
    check("②前置:帶推送參數的 prepare(用遠端舊值)與不帶的(用偽造的 origin/main)指紋不同", with_old and local and with_old != local,
          f"{with_old} {local}")
    n0 = _ns_gov(root)
    rc, _o, e = _rr(root, "reread-check", "--gate", "--diff", f"{base}..HEAD", *push)
    ev = [x for x in _gov_since(_ns_gov(root), n0) if x.get("gate") == "note-reread"]
    got = {x["path"]: x["fp"] for x in (_rfp_ev(ev).get("layer1_fps") or [])}
    check("①推 fork 的 main → 用 fork 遠端舊值算的指紋、擋下", rc == 1 and "Systems/A.md" in e
          and got.get(_rr_note("A")) == with_old, f"rc={rc}\n{got}\n{with_old}\n{e[-600:]}")


def t_reread_fp_fork_workflow_no_false_block():
    """fork 工作流不誤擋(代碼審 r4 通才 1):origin 是 fork(origin/main 停在 base)、本機 main 追蹤正本 upstream/main(比 base 新一個提交),
    分支把正本快轉進來再加自己的改動,照 check 印的指令(帶同一組推送參數)prepare、記紀錄,再 `push origin main` → 放行、靠 v2 命中。
    前置:不帶推送參數時的分岔點是正本 upstream/main 的頂端(候選含 main@{upstream}),不是 fork 的舊值——情境真的是通才席說的那種。
    應抓到的錯:推主線時分岔點仍取本機候選、再核對它是不是遠端舊值的祖先 → ②紅(誤擋、叫人 fetch 也修不好)。"""
    print("t_reread_fp_fork_workflow_no_false_block")
    m = _load_lumos_inproc()
    tmp = Path(tempfile.mkdtemp(prefix="gctl-rfp-"))
    root, base = _rfp_repo()
    _nh_git(root, "remote", "add", "upstream", str(root / "canon"))
    _nh_git(root, "checkout", "-q", "main")
    _rfp_line(root, "src/b.py", 3, "b3 = 30")
    _nh_commit(root, "正本前進")
    up = _na_head(root)
    _nh_git(root, "update-ref", "refs/remotes/upstream/main", up)
    _nh_git(root, "config", "branch.main.remote", "upstream")
    _nh_git(root, "config", "branch.main.merge", "refs/heads/main")
    _nh_git(root, "checkout", "-q", "feat")
    _nh_git(root, "merge", "-q", "--ff-only", "main")
    _rfp_line(root, "src/a.py", 15, "a15 = 150")
    _rr_touch(root, _rr_note("A"), "A 追加")
    _nh_commit(root, "feat")
    tip = _na_head(root)
    check("①前置:不帶推送參數的分岔點是正本頂端、不是 fork 的舊值",
          m._lens_default_base(root, tip=tip, include_local=False) == up != base, up)
    push = ("--push-remote", "origin", "--pushed-ref", "refs/heads/main")
    _rfp_record(root, f"{base}..HEAD", tmp, *push)
    n0 = _ns_gov(root)
    rc, o, e = _rr(root, "reread-check", "--gate", "--diff", f"{base}..HEAD", *push)
    ev = [x for x in _gov_since(_ns_gov(root), n0) if x.get("gate") == "note-reread"]
    check("②fork 工作流照 check 印的指令對照過、push origin main → 放行、靠 v2 命中",
          rc == 0 and "擋下" not in e and "都對照過" in o and _rfp_ev(ev).get("covered_by") == {"v1": 0, "v2": 1},
          f"rc={rc}\n{o[-400:]}\n{e[-600:]}\n{_rfp_ev(ev)}")


def t_reread_fp_feature_push_lookup_fail_no_block():
    """推功能分支時查主線候選失敗,只影響功能分支自己的分岔點、不因推主線那條判定而擋(代碼審 r4 邊界 1):替身讓「範圍起點與分岔點
    以外」的 _push_mainlines 呼叫回 git 失敗(偶發失敗);功能分支自己的分岔點照常算得出、紀錄是 v2 → 放行(rc0、v2 命中)。
    前置:替身真的觸發過。應抓到的錯:查候選失敗時整批退回舊版 → rc1(v2 紀錄比不到)。"""
    print("t_reread_fp_feature_push_lookup_fail_no_block")
    import sys as _s
    m = _load_lumos_inproc()
    tmp = Path(tempfile.mkdtemp(prefix="gctl-rfp-"))
    root, base = _rfp_repo()
    _rfp_line(root, "src/a.py", 15, "a15 = 150")
    _rr_touch(root, _rr_note("A"), "A 追加")
    _nh_commit(root, "feat")
    _rfp_record(root, f"{base}..HEAD", tmp)
    real, hit = m._push_mainlines, []

    def flaky(*a, **k):
        if _s._getframe(1).f_code.co_name not in ("_lens_default_base", "_push_range_start"):
            hit.append(1)
            return [], "查主線候選 refs/remotes/origin/HEAD 時 git 失敗或逾時"
        return real(*a, **k)
    rc, o, ev = _rfp_inproc(m, m.cmd_note_audit_reread_check, root, f"{base}..HEAD", {"_push_mainlines": flaky}, gate=True,
                            push_remote="origin", pushed_ref="refs/heads/feat")
    check("前置:替身觸發過", bool(hit), "")
    check("推功能分支、查主線候選偶發失敗 → 照常用 v2 命中、放行", rc == 0 and _rfp_ev(ev).get("covered_by") == {"v1": 0, "v2": 1},
          f"rc={rc}\n{o[-600:]}\n{_rfp_ev(ev)}")


def t_reread_fp_mainline_old_missing_blocks():
    """推主線、遠端舊值本機找不到(沒 fetch)→ 算不出這次的分岔點,擋下、請先 git fetch <遠端>(代碼審 r4 正確性 1):①check 帶 --gate → rc1、
    訊息有 `git fetch origin`;②照它印的指令貼的 prepare → rc2、同樣的話,不產項目檔。對照:紀錄是照真的分岔點記好的(遠端舊值找得到時會放行,
    見 t_reread_fp_forged_tracking_ref_blocks ②)。應抓到的錯:找不到就靜默改用本機追蹤 ref → ①紅(rc0)。"""
    print("t_reread_fp_mainline_old_missing_blocks")
    tmp = Path(tempfile.mkdtemp(prefix="gctl-rfp-"))
    root, base = _rfp_repo()
    _rfp_line(root, "src/a.py", 15, "a15 = 150")
    _rr_touch(root, _rr_note("A"), "A 追加")
    _nh_commit(root, "honest")
    # 紀錄併進同一個提交:遠端舊值找不到時範圍只查最後一個提交(_push_range_start),改動與紀錄都要在那個提交裡,這篇才是候選
    _fps, files, _out = _rfp_items(root, f"{base}..HEAD")
    for f in files:
        _rr(root, "reread-record", "--prepared", str(f), "--report", str(_rr_report(tmp / f"{f.stem}.md", f, [])))
    _nh_git(root, "add", "-A")
    _nh_git(root, "commit", "-q", "--amend", "--no-edit", "--no-verify")
    fake = "1234567890abcdef1234567890abcdef12345678"
    push = ("--push-remote", "origin", "--pushed-ref", "refs/heads/main")
    rc, o, e = _rr(root, "reread-check", "--gate", "--diff", f"{base}..HEAD", *push)
    check("前置:遠端舊值找得到時同一份紀錄命中、放行", rc == 0 and "都對照過" in o, f"rc={rc}\n{o[-400:]}\n{e[-400:]}")
    rc, o, e = _rr(root, "reread-check", "--gate", "--diff", f"{fake}..HEAD", *push)
    check("①推主線、遠端舊值本機找不到 → 擋下、請先 git fetch origin", rc == 1 and "擋下" in e and "git fetch origin" in e,
          f"rc={rc}\n{o[-400:]}\n{e[-600:]}")
    rc, out, files = _rr_prepare(root, f"{fake}..HEAD", *push)
    check("②同一組參數的 prepare → rc2、請先 fetch、不產項目檔", rc == 2 and "git fetch origin" in out and not files, f"rc={rc}\n{out[-600:]}")


def t_reread_fp_ignores_grafts():
    """.git/info/grafts 不影響指紋(代碼審 r4 資安 2):遠端主線 M(主線往前一個提交、origin/main 跟上),attack 分支從 base 開、多藏一個改第 5 行
    的提交 evil;grafts 寫「M 的父提交是 base 與 evil」,一般 git 算 attack 頂端跟 M 的分岔點就變成 evil、evil 的改動不在分岔點..頂端裡,
    指紋跟 honest 相同。reread-prepare(走 lumos 主程式入口,子行程不帶任何入口會設的變數)算出的 attack 指紋應跟沒寫 grafts 時一樣、
    不等於 honest。判準來源:資安席實測(git 2.39 在 GIT_NO_REPLACE_OBJECTS=1 下照讀 grafts)。
    應抓到的錯:入口不把 GIT_GRAFT_FILE 指到不存在的路徑 → ③紅。"""
    print("t_reread_fp_ignores_grafts")
    root, base = _rfp_repo()
    honest, evil, attack = _rfp_two_branches(root, base)
    _nh_git(root, "checkout", "-q", "main")
    _rfp_line(root, "src/b.py", 3, "b3 = 30")
    _nh_commit(root, "main advance")
    mtip = _na_head(root)
    _nh_git(root, "update-ref", "refs/remotes/origin/main", mtip)
    a = _rr_note("A")
    fh = _rfp_items_attack(root, f"{base}..{honest}")[0].get(a)
    fa = _rfp_items_attack(root, f"{base}..{attack}")[0].get(a)
    check("①前置:沒寫 grafts 時 attack 與 honest 的指紋不同", fh and fa and fh != fa, f"{fh} {fa}")
    gd = Path(_nh_git(root, "rev-parse", "--absolute-git-dir").stdout.strip())
    (gd / "info").mkdir(exist_ok=True)
    (gd / "info" / "grafts").write_text(f"{mtip} {base} {evil}\n", encoding="utf-8")
    mb = _rfp_git_raw(root, "merge-base", attack, mtip).stdout.strip()
    check("②前置:一般 git 讀了 grafts、attack 跟主線的分岔點變成 evil", mb == evil, f"{mb} {evil}")
    fg = _rfp_items_attack(root, f"{base}..{attack}")[0].get(a)
    check("③寫了 grafts → attack 的指紋照真的歷史算、不等於 honest", fg == fa and fg != fh, f"{fg} {fa} {fh}")


def _rfp_insert(root, rel, n, text):
    """rel 第 n 行(從 1 起)之前插一行 text。"""
    p = root / rel
    ls = p.read_text(encoding="utf-8").split("\n")
    ls.insert(n - 1, text)
    p.write_text("\n".join(ls), encoding="utf-8")


def t_reread_fp_ignores_diff_opts():
    """GIT_DIFF_OPTS 不影響指紋(代碼審 r4 資安 3):同一行 payload() 插在 src/a.py 第 15 行或第 5 行(都在頂層、縮排鏈都是空的)兩條分支,
    指紋靠前後三行分得開;GIT_DIFF_OPTS=-u0 會蓋掉指紋指令明寫的 -U3、前後文沒了、兩個位置的指紋相同。reread-prepare 帶
    GIT_DIFF_OPTS=-u0 跑(lumos 子行程不帶任何入口會設的變數)時,兩個位置的指紋應不同、各自跟不帶時一樣。
    判準來源:資安席實測(-u0 下兩個位置指紋相同)。應抓到的錯:入口不清 GIT_DIFF_OPTS → ③紅。"""
    print("t_reread_fp_ignores_diff_opts")
    root, base = _rfp_repo()
    tips = {}
    for n in (15, 5):
        _nh_git(root, "checkout", "-q", "-b", f"p{n}", base)
        _rfp_insert(root, "src/a.py", n, "payload()")
        _rr_touch(root, _rr_note("A"), "A 追加")
        _nh_commit(root, f"insert@{n}")
        tips[n] = _na_head(root)
    plain = _rfp_git_raw(root, "diff", "-U3", base, tips[15], "--", "src/a.py").stdout
    u0 = _rfp_git_raw(root, "diff", "-U3", base, tips[15], "--", "src/a.py", env={"GIT_DIFF_OPTS": "-u0"}).stdout
    check("①前置:一般 git 在 GIT_DIFF_OPTS=-u0 下蓋掉 -U3(前後文行沒了)",
          "\n a13 = 13" in plain and "\n a13 = 13" not in u0 and "+payload()" in u0, f"{plain}\n---\n{u0}")
    a = _rr_note("A")
    ref = {n: _rfp_items_attack(root, f"{base}..{tips[n]}")[0].get(a) for n in tips}
    check("②前置:不帶環境變數時兩個位置的指紋不同", ref[15] and ref[5] and ref[15] != ref[5], str(ref))
    got = {n: _rfp_items_attack(root, f"{base}..{tips[n]}", env={"GIT_DIFF_OPTS": "-u0"})[0].get(a) for n in tips}
    check("③帶 GIT_DIFF_OPTS=-u0 → 兩個位置照樣不同、各自跟不帶時一樣", got == ref, f"{got} {ref}")


def t_reread_fp_line_blocks_same():
    """縮排鏈一塊一塊切行(_note_reread_line_blocks,代碼審 r4 併發 3:原本一次切成整個串列、記憶體約檔案的 30 倍):①各種塊大小接起來
    跟整個照換行 split 逐行相同(期望值是 Python 自己的 bytes.split,結尾有沒有換行、空檔、連續換行、CRLF、只有一行);②塊壓到 3 位元組時
    算出的縮排鏈跟預設塊大小相同。應抓到的錯:塊邊界吃掉或重複一行 → ①紅;塊邊界讓行號錯位 → ②紅。"""
    print("t_reread_fp_line_blocks_same")
    m = _load_lumos_inproc()
    datas = [b"", b"a", b"a\n", b"a\nb", b"a\nb\n", b"\n\n\n", b"x\r\ny\r\n", b"long line " * 50 + b"\nz", b"ab\n" * 1000]
    bad = [(d[:20], b) for d in datas for b in (1, 2, 3, 7, 64, 1 << 20)
           if [ln for blk in m._note_reread_line_blocks(d, b) for ln in blk] != d.split(b"\n")]
    check("①各種塊大小接起來跟整個 split 相同", not bad, str(bad[:5]))
    data = b"class A\n{\n    void F()\n    {\n        a();\n    }\n    void G()\n    {\n        a();\n    });\n}\n"
    spans = [(5, 1), (9, 1), (10, 1), (8, 2), (12, 1)]
    ref = m._note_reread_hunk_chains(data, spans)
    real = m._note_reread_line_blocks
    g = m._note_reread_hunk_nodes.__globals__
    try:
        g["_note_reread_line_blocks"] = lambda d, block=3: real(d, 3)
        small = m._note_reread_hunk_chains(data, spans)
    finally:
        g["_note_reread_line_blocks"] = real
    check("②塊壓到 3 位元組 → 縮排鏈跟預設相同", small == ref and ref[0] == ("class A", "void F()"), f"{small} {ref}")


def t_reread_fp_ignores_external_diff():
    """GIT_EXTERNAL_DIFF 不影響指紋(代碼審 r4 資安 3 同族):帶一支會改輸出的外部差異工具(小 shell 腳本,不管輸入一律印同一行)跑
    reread-prepare(lumos 子行程不帶任何入口會設的變數),兩條改動不同的分支指紋照樣不同、各自跟不帶時一樣。前置:一般 git 帶這支工具時
    `git diff` 的輸出真的變成那一行。兩道防線:入口拿掉 GIT_EXTERNAL_DIFF、指紋的 diff 明寫 --no-ext-diff;應抓到的錯:兩道都拿掉 → ③紅
    (只拿掉其中一道照綠,另一道擋得住)。"""
    print("t_reread_fp_ignores_external_diff")
    root, base = _rfp_repo()
    honest, _evil, attack = _rfp_two_branches(root, base)
    tool = Path(tempfile.mkdtemp(prefix="gctl-rfp-extdiff-")) / "extdiff.sh"
    tool.write_text("#!/bin/sh\necho 'EXTERNAL-DIFF-SAME-FOR-ALL'\n", encoding="utf-8")
    tool.chmod(0o755)
    env = {"GIT_EXTERNAL_DIFF": str(tool)}
    out = _rfp_git_raw(root, "diff", base, honest, "--", "src/a.py", env=env).stdout
    check("①前置:一般 git 帶這支工具時 git diff 的輸出變成那一行", "EXTERNAL-DIFF-SAME-FOR-ALL" in out and "+a15 = 150" not in out, out)
    a = _rr_note("A")
    ref = {n: _rfp_items_attack(root, f"{base}..{t}")[0].get(a) for n, t in (("honest", honest), ("attack", attack))}
    check("②前置:不帶工具時兩條分支指紋不同", ref["honest"] and ref["attack"] and ref["honest"] != ref["attack"], str(ref))
    got = {n: _rfp_items_attack(root, f"{base}..{t}", env=env)[0].get(a) for n, t in (("honest", honest), ("attack", attack))}
    check("③帶外部差異工具 → 兩條照樣不同、各自跟不帶時一樣", got == ref, f"{got} {ref}")


def t_reread_fp_timeout_keeps_computed():
    """一篇逾時,其他已算出新版指紋的篇照常給認可(代碼審 r4 併發 2):A、B 兩篇都記好 v2 紀錄,替身在算到 B 那支檔時把指紋這一步的
    截止時間改成已過(模擬機器忙、B 沒算完)→ A 靠 v2 命中、不列出;B 照舊版判、照擋(rc1、late=1)、講明逾時。
    應抓到的錯:指紋這一步的截止時間一過、分支自己的紀錄就整個不認(回空集合)→ A 也被列成沒對照、covered_by v2=0。"""
    print("t_reread_fp_timeout_keeps_computed")
    import time as _t
    m = _load_lumos_inproc()
    tmp = Path(tempfile.mkdtemp(prefix="gctl-rfp-"))
    root, base = _rfp_repo()
    _rfp_line(root, "src/a.py", 15, "a15 = 150")
    _rfp_line(root, "src/b.py", 15, "b15 = 150")
    _rr_touch(root, _rr_note("A"), "A 追加")
    _rr_touch(root, _rr_note("B"), "B 追加")
    _nh_commit(root, "feat")
    _rfp_record(root, f"{base}..HEAD", tmp)
    real = m._note_reread_fp_file

    def late(scan, fbase, ent):
        if ent["path"] == "src/b.py":
            fbase["dl"] = _t.monotonic() - 1
        return real(scan, fbase, ent)
    rc, o, ev = _rfp_inproc(m, m.cmd_note_audit_reread_check, root, f"{base}..HEAD", {"_note_reread_fp_file": late}, gate=True)
    e = _rfp_ev(ev)
    check("B 逾時、A 已算出 → A 靠 v2 命中不列出,B 照舊版判、擋下",
          rc == 1 and e.get("late") == 1 and e.get("covered_by") == {"v1": 0, "v2": 1} and "Systems/B.md" in o
          and "Systems/A.md" not in o and "這篇因為逾時沒算出新版指紋" in o, f"rc={rc}\n{o[-900:]}\n{e}")


def t_reread_fp_one_diff_for_all_files():
    """指紋這一步一次 git diff 帶全部路徑、照 diff --git 檔頭切開(代碼審 r4 併發 1:原本每支檔各開一次,約一千支檔就撞 30 秒上限):
    一篇筆記管 30 支改過的檔(含帶空白與中文的檔名)→ ①問 git 要逐檔改動的 diff 只有 1 次;②把每批的大小上限壓到 1 位元組(每批一支、
    等於舊的逐支做法)算出的指紋相同;③改其中一支檔的改動,指紋跟著變(切開沒有把別支的改動算到這支、也沒漏)。
    應抓到的錯:照舊逐支開 → ①紅;切錯檔(例如檔名有空白時對不上)→ ②紅或退回舊版。"""
    print("t_reread_fp_one_diff_for_all_files")
    m = _load_lumos_inproc()
    rels = [f"src/m{i}.py" for i in range(28)] + ["src/有 空白.py", "src/中文檔.py"]

    def setup(r):
        for rel in rels:
            _nh_file(r, rel, "".join(f"v{j} = {j}\n" for j in range(20)))
        _nh_node(r, "M", about=rels, body="M 的第一行")
    root, base = _rfp_repo(setup)
    for i, rel in enumerate(rels):
        _rfp_line(root, rel, 10, f"v9 = {i + 100}")
    _rr_touch(root, _rr_note("M"), "追加")
    _nh_commit(root, "feat")
    rng, chk = f"{base}..HEAD", m.cmd_note_audit_reread_check
    real, calls = m._note_reread_git, []

    def spy(r, *a, **k):
        if "diff" in a and "-U3" in a:
            calls.append(a)
        return real(r, *a, **k)
    _rc, _o, ev = _rfp_inproc(m, chk, root, rng, {"_note_reread_git": spy})
    fp1 = {x["path"]: x["fp"] for x in (_rfp_ev(ev).get("layer1_fps") or [])}
    check("前置:那篇用 v2", _rfp_why(ev)[0] == 1, f"{_rfp_why(ev)}")
    check("①30 支檔、問 git 要逐檔 diff 1 次", len(calls) == 1, str(len(calls)))
    calls.clear()
    _rc, _o, ev = _rfp_inproc(m, chk, root, rng, {"_note_reread_git": spy, "_NOTE_REREAD_FP_DIFF_BATCH": 1})
    fp2 = {x["path"]: x["fp"] for x in (_rfp_ev(ev).get("layer1_fps") or [])}
    check("②每批一支(舊做法)算出的指紋相同", fp1 == fp2 and len(calls) == len(rels), f"{fp1} {fp2} {len(calls)}")
    _rfp_line(root, "src/有 空白.py", 10, "v9 = 'changed'")
    _nh_commit(root, "改其中一支")
    _rc, _o, ev = _rfp_inproc(m, chk, root, rng)
    fp3 = {x["path"]: x["fp"] for x in (_rfp_ev(ev).get("layer1_fps") or [])}
    check("③改其中一支(檔名有空白)的改動 → 指紋變了、仍是 v2", fp3 != fp1 and _rfp_why(ev)[0] == 1, f"{fp3} {fp1} {_rfp_why(ev)}")


# ── 代碼審 code-回頭重讀指紋 r5 修正(2026-10-14):批次 diff 不帶太大的檔、不重算;切檔頭的邊界;子行程看不到外部差異工具 ──────────
def _rfp_diff_spy(m):
    """攔指紋那次逐檔 diff(帶 -U3 的 git diff)→ (給 _rfp_inproc 的 patch, 每次呼叫的路徑參數清單)。"""
    real, calls = m._note_reread_git, []

    def spy(r, *a, **k):
        if "diff" in a and "-U3" in a and "--" in a:
            calls.append(list(a[a.index("--") + 1:]))
        return real(r, *a, **k)
    return {"_note_reread_git": spy}, calls


def t_reread_fp_batch_skips_oversize():
    """批次 diff 不帶太大的檔(代碼審 r5 併發 1):三篇筆記各管「小檔、超過上限的新增文字檔、小檔」,上限壓到 4 KB、新增檔約 20 KB
    → ①前置:三篇都因「太大」退回舊版(情境成立:大檔真的會被判太大、不會被要求 diff);②問 git 要逐檔 diff 的每一次,路徑參數裡都沒有
    那三支大檔。判準來源:〈做法〉5(任一邊超過上限就退回 v1、不碰 git diff;r4 以前逐支問時就是這樣)。
    應抓到的錯:建批次時不看大小,把之後才判「太大」的檔一起 diff(單側新增只算一側成本,塞得進批次上限)→ ②紅。"""
    print("t_reread_fp_batch_skips_oversize")
    m = _load_lumos_inproc()
    names = [f"G{i}" for i in range(3)]

    def setup(r):
        for n in names:
            for s in ("a", "c"):
                _nh_file(r, f"src/{n}_{s}.py", "".join(f"v{j} = {j}\n" for j in range(20)))
            _nh_node(r, n, about=[f"src/{n}_a.py", f"src/{n}_big.txt", f"src/{n}_c.py"], body=f"{n} 的第一行")
    root, base = _rfp_repo(setup)
    for n in names:
        _rfp_line(root, f"src/{n}_a.py", 10, "v9 = 900")
        _rfp_line(root, f"src/{n}_c.py", 10, "v9 = 900")
        _nh_file(root, f"src/{n}_big.txt", "".join(f"line {j}\n" for j in range(2500)))
        _rr_touch(root, _rr_note(n), "追加")
    _nh_commit(root, "feat")
    patch, calls = _rfp_diff_spy(m)
    patch["_NOTE_REREAD_FP_MAX"] = 4096
    _rc, o, ev = _rfp_inproc(m, m.cmd_note_audit_reread_check, root, f"{base}..HEAD", patch)
    check("①前置:三篇都因「太大」退回舊版", _rfp_why(ev) == (0, {"太大": 3}), f"{_rfp_why(ev)}\n{o[-400:]}")
    big = {f"src/{n}_big.txt" for n in names}
    check("②逐檔 diff 的路徑參數裡沒有太大的檔", not any(big & set(c) for c in calls), str(calls))


def t_reread_fp_batch_no_rediff():
    """已算過的檔不再進下一批 diff(代碼審 r5 併發 2):Q0 管「一支太大的新增檔(排第一、Q0 在它就退回)、f1..f5」,Q1..Q5 各管 f5..f1 一支
    → 實際要求的順序跟批次順序(f1..f5)相反;路徑參數上限壓到剛好兩支。①前置:Q1..Q5 都用新版指紋;②每支檔只出現在一次逐檔 diff 裡。
    判準來源:批次只是把逐支問 git 併起來,一支檔在同一次檢查裡只要 diff 一次。應抓到的錯:批次從被要求的那支往後收、不看後面的
    已經算過 → f5、f4… 每次都被重 diff,②紅(反序三千支時是二次方)。"""
    print("t_reread_fp_batch_no_rediff")
    m = _load_lumos_inproc()
    fs = [f"src/f{i}.py" for i in range(1, 6)]

    def setup(r):
        for rel in fs:
            _nh_file(r, rel, "".join(f"v{j} = {j}\n" for j in range(20)))
        _nh_node(r, "Q0", about=["src/0big.txt", *fs], body="Q0 的第一行")
        for i, rel in enumerate(reversed(fs), 1):
            _nh_node(r, f"Q{i}", about=[rel], body=f"Q{i} 的第一行")
    root, base = _rfp_repo(setup)
    for rel in fs:
        _rfp_line(root, rel, 10, "v9 = 900")
    _nh_file(root, "src/0big.txt", "".join(f"line {j}\n" for j in range(2500)))
    for i in range(6):
        _rr_touch(root, _rr_note(f"Q{i}"), "追加")
    _nh_commit(root, "feat")
    patch, calls = _rfp_diff_spy(m)
    patch.update({"_NOTE_REREAD_FP_MAX": 4096, "_NOTE_REREAD_FP_DIFF_ARGLEN": 2 * (len("src/f1.py") + 1)})
    _rc, o, ev = _rfp_inproc(m, m.cmd_note_audit_reread_check, root, f"{base}..HEAD", patch)
    check("①前置:Q1..Q5 用新版、Q0 因太大退回", _rfp_why(ev) == (5, {"太大": 1}), f"{_rfp_why(ev)}\n{o[-400:]}")
    seen = [p for c in calls for p in c]
    check("②每支檔只 diff 一次", sorted(seen) == sorted(fs), str(calls))


def t_reread_fp_entry_hides_external_diff_from_children():
    """lumos 起的子行程看不到 GIT_EXTERNAL_DIFF、GIT_DIFF_OPTS(代碼審 r5 合約 3):環境帶這兩個變數跑 code-loop check,bound-tests 真跑
    使用者專案的測試執行器,執行器把它看到的兩個值寫進檔案 → 都是 None。前置:執行器真的跑了。
    判準來源:〈做法〉9 的 WHY(入口統一清,lumos 自己與所有子行程的 git 都繼承;lumos 自己的指紋 diff 另帶 --no-ext-diff,所以入口
    那行獨立管的就是子行程)。應抓到的錯:入口拿掉 `GIT_EXTERNAL_DIFF` 那行 → 紅(t_reread_fp_ignores_external_diff 那支要兩道都拿掉才紅)。"""
    print("t_reread_fp_entry_hides_external_diff_from_children")
    import os as _os
    import subprocess as sp
    bt = Path(_mk_bound_tests_repo(tempfile.mkdtemp(prefix="gctl-rfp-bt-")))
    run_py = bt / "tests" / "run.py"
    run_py.write_text("import os\nopen(os.path.join(os.path.dirname(__file__), 'SEEN'), 'w').write("
                      "repr((os.environ.get('GIT_EXTERNAL_DIFF'), os.environ.get('GIT_DIFF_OPTS'))))\n"
                      + run_py.read_text(encoding="utf-8"), encoding="utf-8")
    e = {k: v for k, v in _os.environ.items() if k not in _RFP_GIT_ENV + ("LUMOS_SKIP_BOUND_TESTS",)}
    e.update({"GIT_EXTERNAL_DIFF": "/nonexistent/extdiff.sh", "GIT_DIFF_OPTS": "-u0"})
    r = sp.run([sys.executable, GRAPHCTL, "code-loop", "check", "--diff", "HEAD~1..HEAD", "--json", "--repo", str(bt)],
               capture_output=True, text=True, env=e, check=False)
    seen = bt / "tests" / "SEEN"
    check("前置:bound-tests 真的跑了使用者專案的測試執行器", seen.is_file(), r.stdout[-300:] + r.stderr[-300:])
    check("子行程看到的 GIT_EXTERNAL_DIFF、GIT_DIFF_OPTS 都是空的",
          seen.is_file() and seen.read_text(encoding="utf-8") == "(None, None)",
          seen.read_text(encoding="utf-8") if seen.is_file() else "")


def t_reread_fp_mainline_name_edges():
    """推主線判定的邊界(代碼審 r5 邊界 2):偽造 origin/main 之後,被推的 ref 是 `refs/heads/master` → 跟 main 一樣用遠端舊值、擋下;
    `refs/heads/main2`、`refs/heads/feat/main`、`refs/tags/main`、`refs/notes/main` → 不算推主線,照功能分支用本機追蹤 ref(記好的紀錄命中、放行)。
    判準來源:〈做法〉3(只有 refs/heads/<主線分支名> 算推主線,主線分支名固定含 main、master)。應抓到的錯:固定名拿掉 master → ①紅;
    拿掉 refs/heads/ 前綴檢查 → refs/notes/main(前綴一樣 11 字)算成推主線 → ②紅;分支名改取最後一段 → refs/heads/feat/main 紅。"""
    print("t_reread_fp_mainline_name_edges")
    tmp = Path(tempfile.mkdtemp(prefix="gctl-rfp-"))
    root, base = _rfp_forged(tmp)
    rc, o, e = _rr(root, "reread-check", "--gate", "--diff", f"{base}..HEAD", "--push-remote", "origin",
                   "--pushed-ref", "refs/heads/master")
    check("①推 refs/heads/master → 算推主線、擋下", rc == 1 and "Systems/A.md" in e and "沒有紀錄" in e, f"rc={rc}\n{e[-600:]}")
    for ref in ("refs/heads/main2", "refs/heads/feat/main", "refs/tags/main", "refs/notes/main"):
        rc, o, e = _rr(root, "reread-check", "--gate", "--diff", f"{base}..HEAD", "--push-remote", "origin", "--pushed-ref", ref)
        check(f"②推 {ref} → 不算推主線、照功能分支放行", rc == 0 and "都對照過" in o, f"rc={rc}\n{o[-300:]}\n{e[-400:]}")


def t_patch_fingerprint_b_in_path_name():
    """逐檔改動指紋的檔名:沒有 `---`/`+++` 的段(只改權限、二進位)從 `diff --git a/X b/X` 兩半相同取名(代碼審 r5 正確性 1、邊界 1;
    資安席的凍結 patch 與回頭重讀共用 _patch_file_changes,一條規則管全部呼叫端)。手寫的 patch:`x b/y2` 只改權限、`opt b/z.bin`
    二進位、引號包起來的 `"q b/\\344\\270\\255"` 只改權限 → 檔名各是 `x b/y2`、`opt b/z.bin`、`q b/中`。
    應抓到的錯:取最後一個「 b/」之後 → 得到 `y2`、`z.bin`、`中`。"""
    print("t_patch_fingerprint_b_in_path_name")
    m = _load_lumos_inproc()
    text = ("diff --git a/x b/y2 b/x b/y2\nold mode 100644\nnew mode 100755\n"
            "diff --git a/opt b/z.bin b/opt b/z.bin\nindex 1111111..2222222 100644\nBinary files a/opt b/z.bin and b/opt b/z.bin differ\n"
            'diff --git "a/q b/\\344\\270\\255" "b/q b/\\344\\270\\255"\nold mode 100644\nnew mode 100755\n')
    got = sorted(m._patch_file_changes(text, headers=False, lf_only=True))
    check("三支檔名都照兩半相同還原", got == sorted(["x b/y2", "opt b/z.bin", "q b/中"]), str(got))


def _rfp_fp_both(m, root, rng, note):
    """同一個範圍跑兩次 check:預設批次、每批一支(_NOTE_REREAD_FP_DIFF_BATCH=1,單支問 git)→ ((v2 篇數, 退回原因, 那篇指紋) × 2)。"""
    out = []
    for patch in (None, {"_NOTE_REREAD_FP_DIFF_BATCH": 1}):
        _rc, _o, ev = _rfp_inproc(m, m.cmd_note_audit_reread_check, root, rng, patch)
        fps = {x["path"]: x["fp"] for x in (_rfp_ev(ev).get("layer1_fps") or [])}
        out.append((*_rfp_why(ev), fps.get(_rr_note(note))))
    return out


def t_reread_fp_split_b_in_path_mode_only():
    """路徑含「 b/」、只改權限的檔(沒有 +++ 行)切段後照樣認得(代碼審 r5 邊界 1):`src/x b/y2` chmod +x、同篇另一支檔改一行
    → ①預設批次與每批一支兩種問法,那篇都用新版指紋、指紋相同;②預設批次問 git 一次就切得出;③檔名還原那道拿掉(替身)時,
    只問這一支就整段給它,指紋照樣跟①相同。判準來源:這支檔有改動(權限變了),新版指紋算得出;r4 以前逐支問 git、整段輸出直接用,
    這情形是 v2。應抓到的錯:檔名從 `diff --git` 行取最後一個「 b/」之後(得到 `y2`)、依名字查不到就當 diff 空 → ①紅;
    不從兩半相同還原 → ②紅(多一次單支再問);只問一支時仍依名字查 → ③紅。"""
    print("t_reread_fp_split_b_in_path_mode_only")
    import os as _os
    m = _load_lumos_inproc()
    rels = ["src/x b/y2", "src/k.py"]

    def setup(r):
        for rel in rels:
            _nh_file(r, rel, "".join(f"v{j} = {j}\n" for j in range(20)))
        _nh_node(r, "X", about=rels, body="X 的第一行")
    root, base = _rfp_repo(setup)
    _os.chmod(root / rels[0], 0o755)
    _rfp_line(root, rels[1], 10, "v9 = 900")
    _rr_touch(root, _rr_note("X"), "追加")
    _nh_commit(root, "feat")
    raw = _nh_git(root, "diff", "--name-status", base, "HEAD").stdout
    check("前置:那支檔只改了權限(在清單裡、是 M)", "M\tsrc/x b/y2" in raw, raw)
    rng = f"{base}..HEAD"
    both = _rfp_fp_both(m, root, rng, "X")
    check("①預設批次與每批一支都用新版指紋、指紋相同", all(b[0] == 1 for b in both) and both[0][2] == both[1][2] and both[0][2],
          str(both))
    patch, calls = _rfp_diff_spy(m)
    _rfp_inproc(m, m.cmd_note_audit_reread_check, root, rng, patch)
    check("②預設批次問 git 一次就切得出(檔名從 diff --git 那行兩半相同還原,不必單支再問)", len(calls) == 1, str(calls))
    g = m._note_reread_split_diff.__globals__
    real = g["_diff_git_same_name"]
    try:
        g["_diff_git_same_name"] = lambda line: None     # 模擬檔頭還原不出檔名:只剩「只問這一支就整段給它」那道
        blind = _rfp_fp_both(m, root, rng, "X")
    finally:
        g["_diff_git_same_name"] = real
    check("③檔名還原不出來時,只問這一支 → 整段給它,指紋跟①相同", [b[2] for b in blind] == [both[0][2]] * 2
          and all(b[0] == 1 for b in blind), f"{blind} {both}")


def t_reread_fp_split_b_in_path_binary():
    """路徑含「 b/」的二進位檔(沒有 +++ 行)切段後照樣認得(代碼審 r5 正確性 1):`opt b/z.bin` 換成另一份二進位內容
    → ①預設批次與每批一支兩種問法都用新版指紋、指紋相同;②再換一次內容 → 指紋跟著變、仍是新版(切出來的是這支檔自己的那段,不是空的)。
    判準來源:二進位檔的指紋記改後那一邊的物件編號(〈做法〉1),內容換了指紋就要變。應抓到的錯:檔名取成 `z.bin` 對不上
    → 退回舊版(「diff 空」),①紅。"""
    print("t_reread_fp_split_b_in_path_binary")
    m = _load_lumos_inproc()
    rel = "opt b/z.bin"

    def setup(r):
        (r / "opt b").mkdir()
        (r / rel).write_bytes(b"\x00\x01\x02 old\x00")
        _nh_file(r, "src/k.py", "".join(f"v{j} = {j}\n" for j in range(20)))
        _nh_node(r, "Z", about=[rel, "src/k.py"], body="Z 的第一行")
    root, base = _rfp_repo(setup)
    (root / rel).write_bytes(b"\x00\x01\x02 new\x00")
    _rfp_line(root, "src/k.py", 10, "v9 = 900")
    _rr_touch(root, _rr_note("Z"), "追加")
    _nh_commit(root, "feat")
    both = _rfp_fp_both(m, root, f"{base}..HEAD", "Z")
    check("①預設批次與每批一支都用新版指紋、指紋相同", all(b[0] == 1 for b in both) and both[0][2] == both[1][2] and both[0][2],
          str(both))
    (root / rel).write_bytes(b"\x00\x01\x02 newer\x00")
    _nh_commit(root, "再換一次")
    again = _rfp_fp_both(m, root, f"{base}..HEAD", "Z")
    check("②內容再換一次 → 指紋變了、仍是新版", all(b[0] == 1 for b in again) and again[0][2] != both[0][2], f"{again} {both}")


def t_reread_fp_file_replaced_by_dir():
    """檔案換成同名資料夾(代碼審 r5 通才 1):`src/d` 刪掉、新增 `src/d/e`,那篇的 about_code 只列 `src/d` → ①預設批次與每批一支
    指紋相同;②只改 `src/d/e` 的內容 → 那篇指紋不變(`git diff -- src/d` 會連 `src/d/e` 一起印,但那不是這篇管的檔)。
    判準來源:指紋只算那篇 about_code 列到的檔的改動(〈做法〉1);r4 以前逐支問、整段輸出直接用,會把 `src/d/e` 併進來,
    新做法較精確。應抓到的錯:只問一支時不分段、整段輸出直接用 → ①②紅(每批一支那次把 `src/d/e` 算進來)。"""
    print("t_reread_fp_file_replaced_by_dir")
    m = _load_lumos_inproc()

    def setup(r):
        _nh_file(r, "src/d", "".join(f"v{j} = {j}\n" for j in range(20)))
        _nh_file(r, "src/k.py", "".join(f"v{j} = {j}\n" for j in range(20)))
        _nh_node(r, "D", about=["src/d", "src/k.py"], body="D 的第一行")
    root, base = _rfp_repo(setup)
    (root / "src" / "d").unlink()
    _nh_file(root, "src/d/e", "e = 1\n")
    _rfp_line(root, "src/k.py", 10, "v9 = 900")
    _rr_touch(root, _rr_note("D"), "追加")
    _nh_commit(root, "feat")
    out = _rfp_git_raw(root, "--literal-pathspecs", "diff", base, "HEAD", "--", "src/d").stdout
    check("前置:git diff -- src/d 連 src/d/e 一起印", out.count("diff --git ") == 2 and "b/src/d/e" in out, out)
    both = _rfp_fp_both(m, root, f"{base}..HEAD", "D")
    check("①預設批次與每批一支都用新版指紋、指紋相同", all(b[0] == 1 for b in both) and both[0][2] == both[1][2] and both[0][2],
          str(both))
    _nh_file(root, "src/d/e", "e = 2\n")
    _nh_commit(root, "只改資料夾裡的檔")
    again = _rfp_fp_both(m, root, f"{base}..HEAD", "D")
    check("②只改 src/d/e → 那篇指紋不變", [b[2] for b in again] == [both[0][2]] * 2, f"{again} {both}")


def t_drift_ack_reread_kind():
    """[S20][S21][S22] drift ack --kind reread:非規則類、沒有判定點出、不是條目開頭 → rc2 不寫帳;
    有判定點出的規則類條目開頭 → 記 kind、path、整條 text、reason、verdicts;drift scan 種類計數不出現 reread。

    翻紅釘:不驗工作目錄有判定點出 → ②紅;不看紀錄的 note 欄 → ②b 紅;text 記實體行不記整條 → ④紅。"""
    print("t_drift_ack_reread_kind")
    import json as _j, subprocess as sp
    tmp = Path(tempfile.mkdtemp(prefix="gctl-rrb4-"))
    summ = "\n".join([_RRB_RULE, "WHY:之所以這樣選是因為比較快 [出處:討論] [因:速度]",
                      "RULE:沒有被點出的另一條規則 [依據:人] [since:2026-10-01]\n  接續行在這裡 [retire:人裁] [until:2026-12-01]"])
    root, base = _rrb_repo(summ)
    l_rule, l_why = _rrb_line(root, "推送前一定要先跑全套測試"), _rrb_line(root, "之所以這樣選")
    l_other, l_cont = _rrb_line(root, "沒有被點出的另一條規則"), _rrb_line(root, "接續行在這裡")
    name, fp = _rrb_judge(root, f"{base}..HEAD", [{"line": l_rule, "quote": "推送前一定要先跑全套測試"},
                                                   {"line": l_why, "quote": "之所以這樣選是因為比較快"},
                                                   {"line": l_cont, "quote": "接續行在這裡"}], tmp)
    acks = root / "governance" / "drift-acks.jsonl"

    def ack(line):
        r = sp.run([sys.executable, GRAPHCTL, "drift", "ack", "Systems/A", str(line), "--kind", "reread", "--reason", "照留理由寫在這"],
                   capture_output=True, text=True, cwd=str(root))
        return r.returncode, r.stdout + r.stderr

    def rows():
        return [_j.loads(x) for x in acks.read_text(encoding="utf-8").splitlines() if x.strip()] if acks.is_file() else []
    for label, line, word in (("非規則類條目(WHY:)", l_why, "非規則類"),
                              ("不是條目開頭(接續行)", l_cont, f"開頭在第 {l_other} 行")):
        rc, out = ack(line)
        check(f"①[S20]{label} → rc2、講原因、不寫帳", rc == 2 and word in out and rows() == [], out)
    root2, b2 = _rrb_repo(summ)
    _rrb_judge(root2, f"{b2}..HEAD", [{"line": _rrb_line(root2, "推送前一定要先跑全套測試"), "quote": "推送前一定要先跑全套測試"}], tmp, tag="x")
    r = sp.run([sys.executable, GRAPHCTL, "drift", "ack", "Systems/A", str(_rrb_line(root2, "沒有被點出的另一條規則")), "--kind",
                "reread", "--reason", "照留理由寫在這"], capture_output=True, text=True, cwd=str(root2))
    check("②[S20]沒有任何判定紀錄點出的規則類條目 → rc2、講沒有判定點出、不寫帳",
          r.returncode == 2 and "沒有判定" in r.stdout + r.stderr and not (root2 / "governance" / "drift-acks.jsonl").is_file(),
          r.stdout + r.stderr)
    # 紀錄的 note 欄要等於這篇:點出同一句原文、但 note 欄是別篇的紀錄,不能拿來表態這篇
    rec = _rr_records(root2)[0]
    doc = _j.loads(rec.read_text(encoding="utf-8"))
    rec.write_text(_j.dumps(dict(doc, note=_rr_note("B")), ensure_ascii=False), encoding="utf-8")
    r = sp.run([sys.executable, GRAPHCTL, "drift", "ack", "Systems/A", str(_rrb_line(root2, "推送前一定要先跑全套測試")), "--kind",
                "reread", "--reason", "照留理由寫在這"], capture_output=True, text=True, cwd=str(root2))
    check("②b[S20]點出這一條的紀錄 note 欄是別篇 → rc2、講沒有判定點出、不寫帳",
          doc.get("note") == _rr_note("A") and r.returncode == 2 and "沒有判定" in r.stdout + r.stderr
          and not (root2 / "governance" / "drift-acks.jsonl").is_file(), r.stdout + r.stderr)
    rc, out = ack(l_rule)
    got = rows()
    check("③[S21]有判定點出的規則類條目開頭 → rc0、印成功訊息", rc == 0 and "表態記下了" in out and len(got) == 1, out)
    g = got[0] if got else {}
    check("④[S21]表態含 kind=reread、path、整條 text、reason、verdicts(點出它的紀錄指紋)",
          g.get("kind") == "reread" and g.get("path") == _rr_note("A") and g.get("text") == _RRB_RULE
          and g.get("reason") == "照留理由寫在這" and g.get("verdicts") == [fp], str(g))
    rc, out = ack(l_other)
    check("⑤[S21]接續行被點出的那一條:以開頭行號表態、記整條(接續行併回)",
          rc == 0 and rows()[-1].get("text") == "RULE:沒有被點出的另一條規則 [依據:人] [since:2026-10-01] 接續行在這裡 [retire:人裁] [until:2026-12-01]",
          out + str(rows()[-1:]))
    r = run(root / _NA_VAULT, "drift", "scan")
    head = next((ln for ln in r.stdout.splitlines() if ln.startswith("存量漂移健檢")), "")
    check("⑥[S22]drift scan 讀到 kind=reread 的表態,種類計數不出現 reread", head and "reread" not in head, r.stdout[:600])


def t_reread_block_hook_and_ci_wiring():
    """[S23][S24][S25] 掛鉤 reread-check 段帶 --gate、rc1 擋下印逃生段、128 以上交中斷處理、其他非零講一句放行;CI 那步照舊不帶 --gate;
    reread-record 收尾不再說不需要表態、git add 列具體檔名、來源核對沒過講這份不算對照;舊掛鉤搭新工具印一句、enforcement 查得到。

    翻紅釘:掛鉤拿掉 --gate → ①紅;enforcement 不讀生效的 pre-push → ⑨紅;帳的來源欄寫死 ci 或 hook → ⑨b 紅。"""
    print("t_reread_block_hook_and_ci_wiring")
    import re as _re
    _need_src("scripts/hooks/pre-push", ".github/workflows/ci.yml")
    repo = Path(GRAPHCTL).resolve().parent.parent
    hook = (repo / "scripts" / "hooks" / "pre-push").read_text(encoding="utf-8").replace("\\\n", " ")
    ci = (repo / ".github" / "workflows" / "ci.yml").read_text(encoding="utf-8")
    calls = [ln for ln in hook.split("\n") if "note-audit reread-check" in ln and not ln.lstrip().startswith("#")]
    check("①[S23]掛鉤的 reread-check 呼叫帶 --gate、標準錯誤不丟", len(calls) == 1 and "--gate" in calls[0] and "2>/dev/null" not in calls[0],
          str(calls))
    steps = _re.split(r"(?m)^      - name: ", ci)
    rr = next((s for s in steps if "note-audit reread-check" in s), "")
    check("②[S23]CI 的 reread-check 那一步照舊不帶 --gate", rr and "--gate" not in rr and "continue-on-error: true" in rr, rr[:600])
    root = _dr_repo()
    base = _na_head(root)
    _nh_node(root, "Pay", summary="FLOW:b")
    _nh_commit(root, "c")
    head = _na_head(root)
    _dr_hook_fakes(root)
    stdin = f"refs/heads/main {head} refs/heads/main {base}\n"
    rc, argv, out = _dr_hook_run(root, stdin, args=("origin",))
    i_r = next((i for i, ln in enumerate(argv) if ln.startswith("note-audit reread-check")), None)
    check("③[S23]實跑:reread-check 帶 --gate、整支放行", rc == 0 and i_r is not None and "--gate" in argv[i_r] and "SUITE" in argv,
          f"rc={rc} {argv} {out[-300:]}")
    rc, argv, out = _dr_hook_run(root, stdin, FAKE_RC_CMD="note-audit:1")
    check("④[S23]reread-check 回 1 → 擋下、印逃生段(單次略過、note_reread.gate 改 warn)、不跑全套",
          rc == 1 and "SUITE" not in argv and "LUMOS_SKIP_REREAD_CHECK=1 git push" in out and "note_reread.gate" in out,
          f"rc={rc} {argv} {out[-500:]}")
    rc, argv, out = _dr_hook_run(root, stdin, FAKE_SIG_CMD="note-audit")
    check("⑤[S23]reread-check 被 SIGTERM 砍掉(143)→ 交給中斷處理、整支停下、不跑全套",
          rc == 143 and "SUITE" not in argv and "被中斷(rc=143)" in out, f"rc={rc} {argv} {out[-300:]}")
    rc, argv, out = _dr_hook_run(root, stdin, FAKE_RC_CMD="note-audit:2")
    check("⑥[S23]其他非零(例如舊版工具不認得 --gate 回 2)→ 講一句這次沒檢查、放行、照跑全套",
          rc == 0 and "SUITE" in argv and "這次沒檢查" in out, f"rc={rc} {argv} {out[-300:]}")
    # [S24]
    r2, b2 = _rr_repo()
    _rr_touch(r2, "src/a.py")
    _rr_touch(r2, _rr_note("A"), "A 追加")
    _nh_commit(r2, "r")
    rc, o, files = _rr_prepare(r2, f"{b2}..HEAD")
    tmp = Path(tempfile.mkdtemp(prefix="gctl-rrb5-"))
    rc, o, e = _rr(r2, "reread-record", "--prepared", str(files[0]), "--report", str(_rr_report(tmp / "a.md", files[0], [])))
    name = _rr_records(r2)[0].name if _rr_records(r2) else "?"
    check("⑦[S24]record 收尾不再出現「不需要表態」、git add 列這次寫的具體檔名",
          rc == 0 and "不需要表態" not in o + e and f"git add governance/reread-verdicts/{name} && git commit" in o
          and "drift ack" in o, o + e)
    rc, o, e = _rr(r2, "reread-record", "--prepared", str(files[0]),
                   "--report", str(_rr_report(tmp / "b.md", files[0], [], provider="codex")))
    check("⑧[S24]來源核對沒過 → 講這份不算對照、請重派", rc == 0 and "這份不算對照,請重派" in o + e, o + e)
    # [S25]
    rc, o, e = _rr(r2, "reread-check", "--diff", f"{b2}..HEAD", "--push-remote", "origin", "--pushed-ref", "refs/heads/x")
    check("⑨[S25]帶 --push-remote、不帶 --gate、設定是 block、不在 CI → 多印一句掛鉤沒帶 --gate、這次不擋",
          rc == 0 and "掛鉤沒帶 --gate" in o, o + e)
    for label, env, extra in (("CI 設了", {"CI": "true"}, ()), ("GITHUB_ACTIONS 設了", {"GITHUB_ACTIONS": "true"}, ()),
                              ("帶了 --gate", None, ("--gate",))):
        n0 = _ns_gov(r2)
        rc, o, e = _rr(r2, "reread-check", *extra, "--diff", f"{b2}..HEAD", "--push-remote", "origin", "--pushed-ref", "refs/heads/x",
                       env=env)
        check(f"⑨對照組:{label} → 不印那一句", "掛鉤沒帶 --gate" not in o + e, o + e)
        # 同一支指令判「是不是 CI」只有一個條件:只設 GITHUB_ACTIONS 時帳的來源也記 ci(原本帳只看 CI、提示看兩個);
        # 兩個都沒設(_rr 會清掉外面的)記 hook——兩邊都驗,來源欄寫死哪一邊都紅
        got = [x for x in _gov_since(_ns_gov(r2), n0) if x.get("gate") == "note-reread"]
        src = "ci" if env else "hook"
        check(f"⑨b {label} → 帳的來源記 {src}", got and got[-1].get("note", "").endswith(f"來源 {src}"), str(got)[:400])
    rc, o, e = _rr(r2, "reread-check", "--diff", f"{b2}..HEAD")
    check("⑨對照組:沒帶 --push-remote(手動跑)→ 不印那一句", "掛鉤沒帶 --gate" not in o + e, o + e)
    m = _load_lumos_inproc()
    eroot, home = _enforcement_fixture(all_active=True)
    pp = eroot / "scripts" / "hooks" / "pre-push"
    pp.write_text('#!/bin/sh\n# lumos note-audit reread-check\n"$PY" "$GRAPHCTL" note-audit reread-check --diff "$r" \\\n'
                  '  --repo "$REPO_ROOT" || rr_rc=$?\nexit 0\n')
    by = {r["layer"]: r for r in m.enforcement_status(root=eroot, home=home)}
    check("⑩[S25]enforcement:生效的 pre-push 的 reread-check 沒有 --gate → 列為沒接上(inactive),說明講 --gate",
          by.get("git-pre-push", {}).get("status") == "inactive" and "--gate" in by.get("git-pre-push", {}).get("detail", ""),
          str(by.get("git-pre-push")))
    pp.write_text('#!/bin/sh\n"$PY" "$GRAPHCTL" note-audit reread-check --gate --diff "$r" \\\n  --repo "$REPO_ROOT" || rr_rc=$?\nexit 0\n')
    by = {r["layer"]: r for r in m.enforcement_status(root=eroot, home=home)}
    check("⑩對照組:帶 --gate → active", by.get("git-pre-push", {}).get("status") == "active", str(by.get("git-pre-push")))


def t_nodehome_side_deadline_reread_base_side():
    """代碼審 r2 通才席 F2:reread-check 的截止時間也傳給起點那一側的 _nodehome_side(起點那側只讀範圍裡有變動的筆記,
    變動的篇數一多照樣會慢)。起點每篇讀 0.2 秒、範圍裡改了 16 篇;上限=先實測「走到起點那側第一次讀」花的時間 + 0.5 秒
    (原本寫死 0.5 秒,假設頂端那側幾乎不花時間;2026-10-02 這台機器光走到起點就要 1 秒,起點一篇都沒讀到、每次紅,
    見 [[Issues/起點時限測試寫死半秒隨機器快慢紅]])。

    翻紅釘:起點那行拿掉 deadline → 起點 16 篇全讀完才逾時 → 紅。"""
    print("t_nodehome_side_deadline_reread_base_side")
    import contextlib, io, time as _t
    m = _load_lumos_inproc()
    root, _b0 = _rr_repo()
    for i in range(15):
        _nh_node(root, f"N{i}", about=[f"src/n{i}.py"], body="x")
        _nh_file(root, f"src/n{i}.py", f"n = {i}\n")
    _nh_commit(root, "many homes")
    base = _na_head(root)
    _rr_touch(root, "src/a.py")
    _rr_touch(root, _rr_note("A"), "追加")
    for i in range(15):
        _rr_touch(root, _rr_note(f"N{i}"), "範圍裡改了")
    _nh_commit(root, "touch many notes")
    tip = _na_head(root)
    g = m.cmd_note_audit_reread_check.__globals__
    real = g["_nodehome_reader"]
    reads = []
    first = []

    def probe_reader(r, where):
        inner = real(r, where)

        def rd(p):
            if where == base and "/Systems/" in p and not first:
                first.append(_t.monotonic() - t0)
            return inner(p)
        return rd
    saved = {k: g[k] for k in ("_nodehome_reader", "_NOTE_REREAD_BUDGET_SEC")}
    try:        # 先量這台機器走到起點那側第一次讀要多久(不慢讀、上限放寬)
        g.update({"_nodehome_reader": probe_reader, "_NOTE_REREAD_BUDGET_SEC": 60})
        t0 = _t.monotonic()
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            m.cmd_note_audit_reread_check(repo=str(root), diff_range=f"{base}..{tip}")
    finally:
        g.update(saved)
    budget = (first[0] if first else 0.0) + 0.5

    def slow_reader(r, where):
        inner = real(r, where)

        def rd(p):
            if where == base and "/Systems/" in p:
                reads.append(p)
                _t.sleep(0.2)
            return inner(p)
        return rd
    saved = {k: g[k] for k in ("_nodehome_reader", "_NOTE_REREAD_BUDGET_SEC")}
    so = io.StringIO()
    try:
        g.update({"_nodehome_reader": slow_reader, "_NOTE_REREAD_BUDGET_SEC": budget})
        t0 = _t.monotonic()
        with contextlib.redirect_stdout(so), contextlib.redirect_stderr(io.StringIO()):
            rc = m.cmd_note_audit_reread_check(repo=str(root), diff_range=f"{base}..{tip}")
        spent = _t.monotonic() - t0
    finally:
        g.update(saved)
    check("起點那側每篇讀 0.2 秒、上限=走到起點的實測時間+0.5 秒:印逾時、回 0,起點讀到上限就停(沒把 16 篇讀完)",
          rc == 0 and "逾時" in so.getvalue() and 0 < len(reads) < 10 and spent < budget + 2.0,
          f"rc={rc} 起點讀了 {len(reads)} 篇、花 {spent:.1f} 秒、上限 {budget:.1f} 秒\n{so.getvalue()}")


def t_discipline_block_stamp_matches_version():
    """代碼審 r1 合約圖譜席 F1:本 repo 自己的 CLAUDE.md、AGENTS.md 紀律區塊戳記要等於 LUMOS_VERSION
    (升版的同一個提交要重注入;不然工具鏈自己的健檢在自家 repo 上帶一條「落後、跑 lumos update」)。只在來源 repo 跑。"""
    print("t_discipline_block_stamp_matches_version")
    import re as _re
    _need_src("skills/lumos-project-notes/SKILL.md", "CLAUDE.md", "AGENTS.md")
    m = _load_lumos_inproc()
    repo = Path(GRAPHCTL).resolve().parent.parent
    for t in ("CLAUDE.md", "AGENTS.md"):
        mm = _re.search(r"LUMOS:GRAPH-DISCIPLINE:START (v[0-9.]+)", (repo / t).read_text(encoding="utf-8"))
        check(f"{t} 紀律區塊戳記 = LUMOS_VERSION", mm is not None and mm.group(1) == m.LUMOS_VERSION,
              f"{mm.group(1) if mm else None} vs {m.LUMOS_VERSION}")


def t_set_plan_closed_lists_satisfied_status_probes():
    """[S15] lumos set 把計劃收尾時,另列 [when-status:<這份計劃>=…] 的 status 條件因此成立的回頭條件(只做文字比對);
    同一行還有別的條件時註明另有條件。

    翻紅釘:拿掉 _drift_plan_followups 的第③項 → ①紅。
    """
    print("t_set_plan_closed_lists_satisfied_status_probes")
    v = mkvault()
    (v / "Issues").mkdir()
    write(v, "Projects/P_計劃.md", "type: project\nstatus: doing", body="# P\n")
    write(v, "Issues/I.md", "type: issue\nstatus: open",
          body="# I\nREVISIT:[when-status:Projects/P_計劃=done|superseded][by:2099-01-01] P 收尾了把這篇結案\n"
               "REVISIT:[when-status:Projects/P_計劃=done][when-file:x.py][by:2099-01-01] 另有條件的\n"
               "REVISIT:[when-status:Projects/P_計劃=superseded][by:2099-01-01] 只在翻案時\n")
    r = run(v, "set", "Projects/P_計劃", "status", "done")
    out = r.stdout
    check("①status 條件因收尾成立的回頭條件列出", "第 6 行的 status 條件因這次收尾成立" in out, out)
    check("②同一行另有條件:註明", "第 7 行" in out and "另有條件" in out, out)
    check("③值不含新狀態的不列", "第 8 行" not in out, out)


def t_drift_probe_scan_and_doctor():
    """[S2][S14](乙的部分)scan 列出條件已成立的行、寫錯的條件、沒帶期限、指不到的筆記、寫在不評估的地方;
    doctor Z 段印條件式的條數、沒帶期限與寫錯的條數,不跑條件評估。

    翻紅釘:scan 不列 probe 發現 → ①紅;Z 段不算條件式 → ③紅。
    """
    print("t_drift_probe_scan_and_doctor")
    import json as _j
    root = _nh_repo()
    _nh_file(root, "src/a.py", "x = 1\n")
    _nh_node(root, "A", body="REVISIT:[when-file:src/a.py][by:2099-01-01] 已成立的\n"
                             "REVISIT:[when-file:src/none.py][by:2099-01-01] 還沒成立的\n"
                             "REVISIT:[when-status:Projects/不存在=done][by:2099-01-01] 指不到\n"
                             "REVISIT:[when-file:src/b.py] 沒帶期限\n")
    _nh_commit(root, "c")
    vault = root / "docs" / "kg-knowledge"
    r = run(vault, "drift", "scan", "--json")
    d = _j.loads(r.stdout)
    probe = [f for f in d["findings"] if f["kind"] == "probe"]
    check("①成立的列成發現、沒成立的不列", [f["text"].split("] ", 1)[-1] for f in probe] == ["已成立的"], str(probe) + str(d.get("problems")))
    whys = " ".join(x["why"] for x in d["problems"])
    check("②指不到的筆記與沒帶期限列成問題", "找不到" in whys and "沒帶期限" in whys, whys)
    rd = run(vault, "doctor")
    check("③doctor Z 段印條件式條數與沒帶期限", "條件式回頭條件 4 條" in rd.stdout and "沒帶期限 1 條" in rd.stdout, rd.stdout[-800:])


def t_drift_exam_probe_mode():
    """[S13](乙的部分)probe 題照改寫檔把那一行在起點與終點兩版換掉,對 event_commit 跑 check,在要處理算擋到;
    改寫檔沒有那一題記成略過。

    翻紅釘:只換終點不換起點 → ①照樣擋到(起點沒有同一條也算新寫)——所以另釘 ②:event_commit 換成跟條件無關的提交要漏。
    """
    print("t_drift_exam_probe_mode")
    import json as _j, subprocess as sp
    root = _dr_repo()
    _nh_node(root, "Pay", summary="FLOW:a", body="REVISIT:2099-12-31 有啟動程式時補測試")
    _nh_commit(root, "base")
    _nh_file(root, "src/other.py", "x = 1\n")
    _nh_commit(root, "無關")
    unrelated = _na_head(root)
    _nh_file(root, "src/runner.py", "def main():\n    pass\n")
    _nh_commit(root, "加啟動程式")
    ev = _na_head(root)
    exam = [{"id": "B", "exam_event": "probe", "note": "Systems/Pay.md", "line": 18, "text": "REVISIT:2099-12-31 有啟動程式時補測試"},
            {"id": "N", "exam_event": "probe", "note": "Systems/Pay.md", "line": 18, "text": "REVISIT:2099-12-31 有啟動程式時補測試"},
            {"id": "X", "exam_event": "probe", "note": "Systems/Pay.md", "line": 18, "text": "x"}]
    rw = "REVISIT:[when-file:src/runner.py][by:2099-12-31] 有啟動程式了補測試"
    probes = [{"id": "B", "rewrite": rw, "event_commit": ev}, {"id": "N", "rewrite": rw, "event_commit": unrelated}]
    (root / "exam.json").write_text(_j.dumps(exam, ensure_ascii=False), encoding="utf-8")
    (root / "probes.json").write_text(_j.dumps(probes, ensure_ascii=False), encoding="utf-8")
    r = sp.run([sys.executable, GRAPHCTL, "drift", "exam", str(root / "exam.json"), "--repo", str(root),
                "--probes", str(root / "probes.json"), "--json"], capture_output=True, text=True)
    try:
        res = {x["id"]: x["result"] for x in _j.loads(r.stdout)["rows"]}
    except (ValueError, KeyError):
        res = {}
    check("①事件提交讓條件成立:擋到", res.get("B") == "擋到", r.stdout + r.stderr)
    check("②跟條件無關的提交:漏(不是每次都擋)", res.get("N") == "漏", str(res))
    check("③改寫檔沒有這一題:略過", str(res.get("X", "")).startswith("略過"), str(res))


def t_drift_code_review_yi_r1_regressions():
    """乙代碼審 r1 折入的回歸釘(存量漂移防線,條件式回頭條件)。每條 check 名後面括號是對應的發現。

    翻紅釘:corpus 只收有副檔名的 → A1、C1 紅;Python 定義改回逐行正則 → A3 紅;parse 不正規化路徑 → A4、C4 紅;
    status 不看讀不讀得出 → A5 紅;帶路徑仍讀整批 → A6 紅;工作目錄模式改回讀 index → B1 紅;
    status 放在列樹之後 → B3 紅;diff 不帶 --text → C2 紅;scan 的樹清單不記住 → C6 紅;
    code_shape 不排 governance/ → C7 紅;set 第③項不看舊狀態 → D1 紅;E5 改回只剝單反引號 → D2 紅;
    other 區不對淨差異 → D3 紅;改寫檔不驗文法 → D4 紅。
    """
    print("t_drift_code_review_yi_r1_regressions")
    import contextlib, io, json as _j, time as _time, unicodedata as _ud, subprocess as sp
    m = _load_lumos_inproc()
    V = "docs/kg-knowledge"
    by = "[by:2099-12-31]"
    # ── A 在某一版上判條件 ──
    root = _nh_repo()
    _nh_file(root, "scripts/tool", "#!/usr/bin/env python3\ndef cmd_old():\n    pass\n")
    _nh_file(root, "src/doc.py", 'DOC = """\ndef launch():\n    pass\n"""\n\n\ndef helper():\n'
                                 '    """範例:\n    def ghost():\n        pass\n    """\n')
    _nh_file(root, "src/café.py", "x = 1\n")
    _nh_file(root, "src/plain.py", "def only_here():\n    pass\n")
    _nh_file(root, "tests/test_a.py", "def test_ok():\n    pass\n")
    _nh_file(root, "tests/test_b.py", "def test_other():\n    pass\n")
    _nh_node(root, "P_計劃", typ="project", folder="Projects", resp=None, status="doing", summary="KEY:p")
    _nh_commit(root, "tree")
    tip = _na_head(root)
    tenv = m._drift_tree_env(root, tip, V)
    tr = m._drift_probe_tree(root, tip)

    def one(k, v, t=tr, env=tenv):
        return m._drift_probe_one(t, env, k, v)
    got = (one("symbol", "scripts/tool::cmd_old"), one("symbol", "cmd_old"))
    check("A1 沒副檔名、#! 開頭的 Python 檔:帶路徑與不帶路徑的 symbol 都找得到(正確性 F1)", got == (True, True), str(got))
    got = (one("test", "src/plain.py::only_here"), one("symbol", "tests/test_a.py::test_ok"))
    check("A2 帶路徑就讀那支檔,不看它算不算測試檔(正確性 F1 第 4 點)", got == (True, True), str(got))
    got = (one("symbol", "launch"), one("symbol", "ghost"), one("symbol", "helper"), one("symbol", "DOC"))
    check("A3 字串與 docstring 裡的 def 不算定義,真的定義照認(外家 F1、架構 F5)", got == (False, False, True, True), str(got))
    conds = [m._probe_parse(f"[when-file:{p}]{by}")["conds"][0] for p in ("./src/plain.py", _ud.normalize("NFD", "src/café.py"))]
    got = [one(k, v) for k, v in conds]
    check("A4 ./ 開頭與 NFD 寫法的路徑解析時就正規化、照認(外家 F3、邊界 F1、正確性 F7)",
          conds[0] == ("file", "src/plain.py") and got == [True, True], str(conds) + str(got))
    uenv = m.Env.from_texts(root / V, {}, unreadable=["Projects/Q.md"])
    check("A5 status 指到讀不出的筆記:判不了,不是不成立(外家 F2)", one("status", "Projects/Q=done", env=uenv) is None, "")
    sizes, orig_cat = [], m._nodehome_cat_blobs
    m._nodehome_cat_blobs = lambda r, specs, **k: (sizes.append(len(specs)), orig_cat(r, specs, **k))[1]
    try:
        r6 = m._drift_probe_one(m._drift_probe_tree(root, tip), tenv, "test", "tests/test_a.py::test_ok")
    finally:
        m._nodehome_cat_blobs = orig_cat
    check("A6 帶路徑的條件只讀那一支檔(併發 F2)", r6 is True and sizes == [1], str(sizes))
    check("A7 預算用完就不列樹、判不了(併發 F1)", m._drift_probe_tree(root, tip, deadline=_time.monotonic() - 1) is None, "")
    # ── B scan ──
    _nh_file(root, "src/untracked.py", "y = 1\n")
    (root / "src/plain.py").unlink()
    try:
        td = m._drift_probe_tree(root, "disk")
        got = (m._drift_probe_one(td, None, "file", "src/untracked.py"), m._drift_probe_one(td, None, "file", "src/plain.py"))
    finally:
        _nh_git(root, "checkout", "--", "src/plain.py")
        (root / "src/untracked.py").unlink()
    check("B1 工作目錄模式看磁碟:沒追蹤的檔算在、刪掉還沒 stage 的算不在(外家 F5)", got == (True, False), str(got))
    vault = root / V
    _nh_node(root, "Q", body=f"REVISIT:[when-symbol:Config::load]{by} 型別::方法寫法\n"
                             f"REVISIT:[when-file:src/zzz.py]{by} 還沒成立")
    r = run(vault, "drift", "scan", "--json", "--budget", "5")
    try:
        d = _j.loads(r.stdout)
    except ValueError:
        d = {"problems": [], "findings": []}
    check("B2 scan 收 --budget(外家 F6)", r.returncode == 0, r.stdout + r.stderr)
    whys = " ".join(x["why"] for x in d["problems"])
    check("B4 symbol 路徑那段不像檔案路徑(型別::方法)列成問題(正確性 F7)", "Config" in whys and "不像" in whys, whys)
    pr_tx = m.env_text(m.Env(vault), "Systems/Q.md")
    _f, probs = m._drift_probe_scan(m.Env.from_texts(vault, {"Systems/Q.md": pr_tx}), None,
                                    deadline=_time.monotonic() - 1)
    check("B5 scan 預算用完:條件列成判不了(超過預算)(外家 F6)", any("預算" in p[3] for p in probs), str(probs))
    v = mkvault()
    (v / "Issues").mkdir()
    write(v, "Projects/P_計劃.md", "type: project\nstatus: doing", body="# P\n")
    write(v, "Issues/I.md", "type: issue\nstatus: open", body=f"# I\nREVISIT:[when-status:Projects/P_計劃=doing|done]{by} 開工了\n")
    r = run(v, "drift", "scan", "--json")
    try:
        d = _j.loads(r.stdout)
    except ValueError:
        d = {"problems": [], "findings": []}
    got = ([f["kind"] for f in d["findings"]], [x["why"] for x in d["problems"]])
    check("B3 不是 git 專案:純 status 條件照判、不列判不了(正確性 F5)", got == (["probe"], []), str(got))
    # ── C check ──
    root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
    _nh_file(root, "scripts/tool", "#!/usr/bin/env python3\ndef cmd_old():\n    pass\n")
    _nh_file(root, ".gitattributes", "src/gen.py -diff\n")
    _nh_file(root, "src/gen.py", "x = 1\n")
    _nh_node(root, "Pay", summary="FLOW:a",
             body=f"REVISIT:[when-symbol:scripts/tool::cmd_new]{by} 帶路徑的\nREVISIT:[when-symbol:cmd_extra]{by} 不帶路徑的\n"
                  f"REVISIT:[when-file:./src/runner.py]{by} 點斜線開頭的\nREVISIT:[when-symbol:Bar]{by} 標了負差異的")
    _nh_commit(root, "base")
    b0 = _na_head(root)
    _nh_file(root, "scripts/tool", "#!/usr/bin/env python3\ndef cmd_old():\n    pass\n\n\ndef cmd_new():\n    pass\n\n\n"
                                   "def cmd_extra():\n    pass\n")
    _nh_file(root, "src/runner.py", "def main():\n    pass\n")
    _nh_commit(root, "事件")
    rc, out = _dr(root, "check", "--diff", f"{b0}..HEAD")
    check("C1 沒副檔名的 Python 檔新增定義:帶路徑與不帶路徑的都擋(正確性 F1)",
          rc == 1 and "帶路徑的" in out and "不帶路徑的" in out and "標了負差異的" not in out, out)
    check("C3 條件式的要處理不印預告句的修法,給 --kind probe 的表態指令(正確性 F3)",
          "預告句" not in out and "--kind probe" in out, out)
    check("C4 ./ 開頭的路徑:候選與判定都對得上、擋(外家 F3)", "點斜線開頭的" in out, out)
    tip = _na_head(root)
    # 只改標了 -diff 的那支檔(沒有檔被新增或刪除,候選只能靠新增行裡找得到名稱)
    _nh_file(root, "src/gen.py", "x = 1\n\n\nclass Bar:\n    pass\n")
    _nh_commit(root, "只改負差異檔")
    rc, out = _dr(root, "check", "--diff", f"{tip}..HEAD")
    check("C2 程式檔標了 -diff 屬性:照樣看得到新增行、擋(正確性 F2)", rc == 1 and "標了負差異的" in out, out)
    calls, orig_git, orig_ns = [], m._nodehome_git, m._ns_git
    m._nodehome_git = lambda r, *a, **k: (calls.append(a), orig_git(r, *a, **k))[1]
    m._ns_git = lambda r, *a, **k: (calls.append(a), orig_ns(r, *a, **k))[1]
    try:
        tenv = m._drift_tree_env(root, tip, V)
        calls.clear()
        m._drift_probe_check(root, b0, tip, V, tenv, deadline=_time.monotonic() + 60)
        probe_calls = list(calls)
        calls.clear()
        m._drift_check_core(root, b0, tip, V, deadline=_time.monotonic() + 60)
        core_calls = list(calls)
    finally:
        m._nodehome_git, m._ns_git = orig_git, orig_ns
    ns = [a for a in probe_calls if "--name-status" in a]
    check("C5 乙的範圍改動只算一次 name-status(改名對照不另起 git)(圖譜一致 F1、架構 F4)", len(ns) == 1, str(ns))
    lt = [a[-1] for a in core_calls if a and a[0] == "ls-tree"]
    check("C6 一次 check 裡同一棵樹只列一次(併發 F1)", len(lt) == len(set(lt)), str(lt))
    b1 = _na_head(root)
    _nh_file(root, "governance/eval/x.py", "def z():\n    pass\n")
    _nh_commit(root, "治理資料夾的工具")
    ch = m._drift_probe_changes(root, b1, _na_head(root))
    check("C7 governance/ 底下新增程式檔不算程式檔形狀改變(圖譜一致 F4)", ch is not None and ch["code_shape"] is False, str(ch))
    # ── D 其他 ──
    v = mkvault()
    (v / "Issues").mkdir()
    write(v, "Projects/P_計劃.md", "type: project\nstatus: doing", body="# P\n")
    write(v, "Issues/I.md", "type: issue\nstatus: open", body=f"# I\nREVISIT:[when-status:Projects/P_計劃=doing|done]{by} 開工了\n")
    r = run(v, "set", "Projects/P_計劃", "status", "done")
    check("D1 收尾前條件就已成立:不說成「因這次收尾成立」(正確性 F4、外家 F9)", "因這次收尾成立" not in r.stdout, r.stdout)
    v = mkvault()
    write(v, "Systems/A.md", "type: system\nstatus: doing",
          body="# A\n``REVISIT:[when-file:x.py][by:2020-01-01] 雙反引號範例``\n")
    r = run(v, "doctor")
    check("D2 E5 跟另外兩層一樣把雙反引號當範例(正確性 F6、外家 F8)", "雙反引號範例" not in r.stdout, r.stdout[-600:])
    root = _nh_repo()
    ln = f"REVISIT:[when-file:x.py]{by} 同一句"
    _nh_node(root, "A", extra="valid_under: |-\n  " + ln)
    _nh_commit(root, "base")
    base = _na_head(root)
    _nh_node(root, "A", extra="valid_under: |-\n  " + ln, body=ln)
    _nh_commit(root, "正文新寫同一句")
    tip = _na_head(root)
    res = m._notelines_new(root, False, base, tip, V, reader=m._nodehome_reader(root, tip), mark="x", keep_other=True)
    regs = [reg for _p, _t, rows in (res[0] if res else []) for _n, _l, reg in rows]
    check("D3 推送範圍:開頭欄位裡同一句的舊行不算新行(外家 F4)", "other" not in regs and "body" in regs, str(regs))
    root = _dr_repo()
    (root / "p.json").write_text(_j.dumps([{"id": "A", "rewrite": "REVISIT:[when-file:a.py] 沒期限", "event_commit": "HEAD"}]),
                                 encoding="utf-8")
    (root / "e.json").write_text(_j.dumps([{"id": "A", "exam_event": "probe", "note": "Systems/Pay.md", "line": 1, "text": "x"}]),
                                 encoding="utf-8")
    r = sp.run([sys.executable, GRAPHCTL, "drift", "exam", str(root / "e.json"), "--repo", str(root),
                "--probes", str(root / "p.json")], capture_output=True, text=True)
    check("D4 改寫檔的條件式不合文法(沒帶期限):擋下 rc2(外家 F7、正確性 F8)",
          r.returncode == 2 and "期限" in r.stderr, r.stdout + r.stderr)
    real = m._drift_exam_load_probes(str(Path(GRAPHCTL).resolve().parent.parent / "governance/eval/drift-exam/rtb-2026-09-28-probes.json"))
    check("D5 正式改寫檔每一題都合文法(外家 F7)", isinstance(real, dict) and len(real) == 5, str(real)[:200])


def t_drift_code_review_yi_r2_regressions():
    """乙代碼審 r2 折入的回歸釘(存量漂移防線,條件式回頭條件修正差異)。每條 check 名後面括號是對應的發現。

    翻紅釘:ast 只接 SyntaxError/ValueError → A1 紅;候選改回只看新增行 → B1、B2 紅;單一檔讀不到當成不成立 → C1 紅;
    筆記讀不到當不存在 → C2 紅;不換 NFD 重讀 → C3 紅;反斜線不驗 → D1 紅;讀檔不去 BOM → E1、E2 紅;
    工作目錄讀檔不看預算 → F1 紅;帶路徑的條件逐支讀 → F2 紅;提示把種類接成 c1|probe → G1 紅;
    重放拿改完的圖譜算第③項 → G2 紅;--budget 收 inf → G3 紅;淨差異一律先算 → G4 紅;v1.2 當成檔案路徑 → G5 紅。
    """
    print("t_drift_code_review_yi_r2_regressions")
    import contextlib, io, json as _j, time as _time, unicodedata as _ud, subprocess as sp
    m = _load_lumos_inproc()
    V = "docs/kg-knowledge"
    by = "[by:2099-12-31]"
    bom = "﻿"
    # ── A 解析不了的大檔不讓整支當掉 ──
    deep = "# cmd_new 只在註解\n" + "-" * 200000 + "1\n"
    try:
        got = m._drift_py_names(deep)
        ok = True
    except (MemoryError, RecursionError) as ex:       # noqa: F841
        ok, got = False, repr(ex)
    check("A1 巢狀太深解析不了:退回逐行比對,不丟例外(邊界 F1)", ok and got is None, str(got)[:80])
    # ── B 判定放寬之後,候選篩選要跟上 ──
    root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
    _nh_file(root, "src/api.py", "X = 1\n'''\ndef new_api():\n    return 1\n'''\n")
    _nh_file(root, "bin/tool", "def max_x():\n    pass\n")
    _nh_node(root, "Pay", summary="FLOW:a",
             body=f"REVISIT:[when-symbol:new_api]{by} 刪掉三引號才出現的\nREVISIT:[when-symbol:max_x]{by} 加了井號驚嘆號才算的")
    _nh_commit(root, "base")
    b0 = _na_head(root)
    _nh_file(root, "src/api.py", "X = 1\ndef new_api():\n    return 1\n")
    _nh_commit(root, "只刪三引號")
    rc, out = _dr(root, "check", "--diff", f"{b0}..HEAD")
    check("B1 只刪掉包住定義的三引號:條件翻成立,擋(正確性 F1)", rc == 1 and "刪掉三引號才出現的" in out, out)
    b1 = _na_head(root)
    _nh_file(root, "bin/tool", "#!/usr/bin/env python3\ndef max_x():\n    pass\n")
    _nh_commit(root, "只加井號驚嘆號")
    rc, out = _dr(root, "check", "--diff", f"{b1}..HEAD")
    check("B2 沒副檔名的檔只加上 #!:條件翻成立,擋(正確性 F1)", rc == 1 and "加了井號驚嘆號才算的" in out, out)
    # ── C 讀不到的算判不了 ──
    tip = _na_head(root)
    tr = m._drift_probe_tree(root, tip)
    orig_cat = m._nodehome_cat_blobs
    m._nodehome_cat_blobs = lambda r, specs, **k: [None] * len(specs)
    try:
        c1 = m._drift_probe_one(tr, None, "symbol", "src/api.py::new_api")
        tenv_bad = m._drift_tree_env(root, tip, V)
    finally:
        m._nodehome_cat_blobs = orig_cat
    check("C1 樹上有這支檔、讀出來卻是空的:判不了,不是不成立(外家 F1)", c1 is None, repr(c1))
    n = tenv_bad.notes.get("Systems/Pay.md") if tenv_bad is not None else None
    check("C2 筆記讀出來是空的:建成讀不出的筆記,不當成不存在(外家 F1 第 2 點)",
          n is not None and m._note_unreadable(n), str(tenv_bad and sorted(tenv_bad.notes))[:200])
    nfd = _ud.normalize("NFD", "src/café.py")
    r = sp.run(["git", "-C", str(root), "hash-object", "-w", "--stdin"], input="def cafe_fn():\n    pass\n",
               capture_output=True, text=True)
    blob = r.stdout.strip()
    sp.run(["git", "-C", str(root), "-c", "core.precomposeunicode=false", "update-index", "--add", "--cacheinfo",
            f"100644,{blob},{nfd}"], capture_output=True)
    sp.run(["git", "-C", str(root), "-c", "core.precomposeunicode=false", "commit", "-qm", "NFD 檔名", "--no-verify"],
           capture_output=True)
    ls = _nh_git(root, "ls-tree", "-r", "--name-only", "-z", "HEAD").stdout
    stored_nfd = nfd in ls.split("\0")
    tr = m._drift_probe_tree(root, _na_head(root))
    c3 = m._drift_probe_one(tr, None, "symbol", "src/café.py::cafe_fn")
    check("C3 以 NFD 存進 git 的檔名:換寫法重讀、判得到(外家 F1 第 2 點)", stored_nfd and c3 is True,
          f"stored_nfd={stored_nfd} got={c3!r}")
    # ── D 反斜線 ..
    errs = [m._probe_parse(f"[when-{v}]{by}")["errs"] for v in ("file:..\\x.py", "symbol:..\\a.py::f", "file:a/..")]
    check("D1 反斜線寫的 ..、收成 . 的路徑:算寫錯(正確性 F2、邊界 F3)", all(errs), str(errs))
    # ── E BOM ──
    root = _nh_repo()
    _nh_file(root, "src/b.py", bom + 'def real_b():\n    """範例:\n    def ghost_b():\n        pass\n    """\n')
    (root / "scripts").mkdir(exist_ok=True)
    (root / "scripts/runner").write_bytes((bom + "#!/usr/bin/env python3\ndef cmd_bom():\n    pass\n").encode("utf-8"))
    _nh_commit(root, "bom")
    tip = _na_head(root)
    tr = m._drift_probe_tree(root, tip)
    got = (m._drift_probe_one(tr, None, "symbol", "real_b"), m._drift_probe_one(tr, None, "symbol", "ghost_b"))
    check("E1 帶 BOM 的 Python 檔照 ast 判:docstring 範例不算(正確性 F4)", got == (True, False), str(got))
    check("E2 帶 BOM 的 #! 腳本進語料:不帶路徑照找得到(邊界 F2)",
          m._drift_probe_one(tr, None, "symbol", "cmd_bom") is True, "")
    # ── F 預算與讀檔次數 ──
    td = m._drift_probe_tree(root, "disk", deadline=_time.monotonic() + 60)
    td.deadline = _time.monotonic() - 1
    check("F1 工作目錄模式讀檔也看預算:用完就判不了(併發 F1)", m._drift_probe_one(td, None, "symbol", "real_b") is None, "")
    for i in range(4):
        _nh_file(root, f"src/f{i}.py", f"def s{i}():\n    pass\n")
    _nh_node(root, "Q", body="\n".join(f"REVISIT:[when-symbol:src/f{i}.py::s{i}]{by} 第 {i} 支" for i in range(4)))
    _nh_commit(root, "四支")
    tip = _na_head(root)
    tenv = m._drift_tree_env(root, tip, V)
    calls = []
    m._nodehome_cat_blobs = lambda r, specs, **k: (calls.append(len(specs)), orig_cat(r, specs, **k))[1]
    try:
        found, _pr = m._drift_probe_scan(tenv, m._drift_probe_tree(root, tip))
    finally:
        m._nodehome_cat_blobs = orig_cat
    check("F2 帶路徑的條件一批讀完,不是一支檔開一次 git(併發 F2)",
          len([f for f in found if f["path"] == "Systems/Q.md"]) == 4 and calls == [4], str(calls))
    # ── G 其他 ──
    err = io.StringIO()
    orig_ev = m._gate_event_or_warn
    m._gate_event_or_warn = lambda *a, **k: None
    try:
        with contextlib.redirect_stderr(err):
            m._drift_report_must(root, "warn", [{"kind": "c1", "path": "Verification/G.md", "line": 3, "text": "x", "why": "y"},
                                               {"kind": "probe", "path": "Systems/Q.md", "line": 5, "text": "z", "why": "w"}], [], [])
    finally:
        m._gate_event_or_warn = orig_ev
    e = err.getvalue()
    check("G1 兩種發現都有:表態指令一種一行,不印成 c1|probe(正確性 F5、圖譜一致 F1、外家 F3)",
          "c1|probe" not in e and "--kind c1 " in e and "--kind probe " in e, e)
    root = _nh_repo()
    _nh_node(root, "P", typ="project", folder="Projects", resp=None, status="doing", summary="KEY:p")
    _nh_node(root, "N", typ="issue", folder="Issues", resp=None, status="open", summary="KEY:n",
             body=f"REVISIT:[when-status:Projects/P=done]{by} P 收尾了就結案")
    _nh_commit(root, "c")
    fu = m._drift_exam_replay(root, _na_head(root), V, ["Projects/P"])
    check("G2 考試重放跟 lumos set 一樣列第③項(正確性 F3)", isinstance(fu, set) and "Issues/N.md" in fu, str(fu))
    vault = root / V
    rcs = [run(vault, "drift", "scan", "--budget", b).returncode for b in ("inf", "nan")]
    check("G3 --budget 收到 inf、nan:擋下 rc2,不丟例外(外家 F2)", rcs == [2, 2], str(rcs))
    base = _na_head(root)
    _nh_node(root, "N", typ="issue", folder="Issues", resp=None, status="open", summary="KEY:n",
             body=f"REVISIT:[when-status:Projects/P=done]{by} P 收尾了就結案\n新的一句")
    _nh_commit(root, "只改正文")
    _nh_node(root, "N", typ="issue", folder="Issues", resp=None, status="open", summary="KEY:n",
             body=f"REVISIT:[when-status:Projects/P=done]{by} P 收尾了就結案\n新的一句\n再一句")
    _nh_commit(root, "再改正文")      # 兩個提交:逐提交那幾次 diff 的參數才不會跟淨差異撞在一起
    tip = _na_head(root)
    net_calls, orig_diff = [], m._ns_diff
    m._ns_diff = lambda r, *a, **k: (net_calls.append(a) if a[:2] == (base, tip) else None, orig_diff(r, *a, **k))[1]
    try:
        m._notelines_new(root, False, base, tip, V, reader=m._nodehome_reader(root, tip), mark="x", keep_other=True)
    finally:
        m._ns_diff = orig_diff
    check("G4 開頭欄位其他欄沒有新行時,不多算一次淨差異(併發 F3)", net_calls == [], str(net_calls))
    fake = type("T", (), {"files": set()})()
    got = (m._drift_probe_path_warn("symbol", "v1.2::x", fake), m._drift_probe_path_warn("symbol", "src/new.py::main", fake),
           m._drift_probe_path_warn("symbol", "Makefile::build", fake) or "")
    check("G5 v1.2::x 列成不像檔案路徑、還沒建的 src/new.py 不列、Makefile 提示可能是還沒建的根目錄檔(邊界 F4)",
          got[0] is not None and got[1] is None and "還沒建" in got[2], str(got))


def t_drift_code_review_yi_r3_regressions():
    """乙代碼審 r3 折入的回歸釘(存量漂移防線,條件式回頭條件第二次修正差異)。每條 check 名後面括號是對應的發現。

    翻紅釘:讀檔改回「版本:路徑」→ A1、A2、A3 紅;判不了不點名檔 → A4 紅;候選迴圈不看預算 → B1 紅;
    名稱改回對全文跑正則 → B2 紅;候選遇到判不了就停 → B3 紅;拿掉接 MemoryError/RecursionError → C1 紅(3.12 以前的事先量測
    已隨工具最低版本改 3.14 刪掉,C1 改驗 3.14 上的極端輸入);
    版面改變不算形狀改變 → D1 紅;反斜線不先轉斜線 → D2 紅;check 拿存下的值重驗 → D3 紅;--budget 不設上限 → E1 紅;
    副檔名規則改回字母數字 → E2 紅;候選判不了不記 → F1 紅;語料有讀不出的檔當成不成立 → F2 紅。
    """
    print("t_drift_code_review_yi_r3_regressions")
    import subprocess as sp, time as _time
    m = _load_lumos_inproc()
    V = "docs/kg-knowledge"
    by = "[by:2099-12-31]"

    def _add_raw(root, raw_path, content):
        """用 git 原樣路徑存一支檔(不經檔案系統,檔名寫法不被改)。"""
        blob = sp.run(["git", "-C", str(root), "hash-object", "-w", "--stdin"], input=content,
                      capture_output=True, text=True).stdout.strip()
        sp.run(["git", "-C", str(root), "-c", "core.precomposeunicode=false", "update-index", "--add", "--cacheinfo",
                f"100644,{blob},{raw_path}"], capture_output=True)

    # ── A 用內容編號讀:檔名寫法怪的照讀得到 ──
    root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
    compat = "src/豈文.py"                                   # 相容表意字,NFC 與 NFD 都會把它換掉
    mixed = "café/café.py"                             # 資料夾組合字、檔名分解字
    _add_raw(root, compat, "def compat_fn():\n    pass\n")
    _add_raw(root, mixed, "def mixed_fn():\n    pass\n")
    _add_raw(root, "src/a\nb.py", "def nl_fn():\n    pass\n")
    sp.run(["git", "-C", str(root), "commit", "-qm", "怪檔名", "--no-verify"], capture_output=True)
    b0 = _na_head(root)
    tr = m._drift_probe_tree(root, b0)
    got = (tr.one("symbol", "compat_fn"), tr.one("symbol", m.nfc(mixed) + "::mixed_fn"), tr.one("symbol", "nl_fn"),
           tr.one("symbol", "not_yet_written"))
    check("A1 相容表意字檔名的檔:讀得到,不帶路徑的條件照判(正確性 F1)", got[0] is True and got[3] is False, str(got))
    check("A2 資料夾與檔名寫法混用:帶路徑的條件讀得到(正確性 F1)", got[1] is True, str(got))
    check("A3 檔名含換行的檔:不讓整批讀取失敗(邊界 F2)", got[2] is True, str(got))
    _nh_node(root, "Pay", summary="FLOW:a", body=f"REVISIT:[when-symbol:not_yet_written]{by} 等它出現")
    _nh_commit(root, "新寫一條還沒成立的")
    rc, out = _dr(root, "check", "--diff", f"{b0}..HEAD")
    check("A1 有怪檔名的專案:新寫還沒成立的條件不擋(正確性 F1)", rc == 0 and "判不了" not in out, out)
    tb = m._drift_probe_tree(root, b0)
    tb._text["src/壞.py"] = None
    note = m._drift_bad_note(m._drift_row_unread([("symbol", "anything")], (), (tb,)))
    check("A4 判不了時點名讀不出的檔(正確性 F1 第 4 點)", "src/壞.py" in note, note)
    # ── B 候選迴圈 ──
    pr = m._probe_parse(f"[when-symbol:foo]{by}")
    lines = [("Systems/Pay.md", i, "x", pr) for i in range(1, 6)]
    ch = {"renames": {}, "touched": set(), "code_shape": False, "code_touched": ["a.py"]}
    todo, unk = m._drift_probe_candidates(lines, ch, V + "/", None, None, None, lambda: True)
    check("B1 預算用完:每一行都記成超過預算,不再往下篩(併發 F1)",
          todo == [] and len(unk) == 5 and all("超過預算" in u for u in unk), str(unk))
    names = m._DriftNames(["x_1 " * 1500000])
    t0 = _time.monotonic()
    hits = [m._drift_probe_cond_candidate("symbol", f"missing_{i}", ch, V + "/", None, lambda _t: names) for i in range(300)]
    el = _time.monotonic() - t0
    check("B2 名稱查識別字集合:300 條不在 6MB 全文裡的名稱 1 秒內判完(併發 F1)", el < 1 and not any(hits), f"{el:.2f}s")
    E = type("E", (), {"resolve": lambda s, x: "Projects/P.md"})
    ch2 = {"touched": {"x.txt"}, "code_shape": False, "code_touched": ["bad.py"]}
    got = m._drift_probe_is_candidate([("symbol", "foo"), ("file", "x.txt")], ch2, V + "/", E(), lambda _t: None)
    check("B3 一條判不了、另一條確定受影響:算候選(外家 F2)", got is True, repr(got))
    # ── C 極深的程式:3.14 的解析器丟接得住的例外,退回正則(工具最低版本改 3.14 後,原本 3.9 會 SIGSEGV 的事先量測已刪)──
    deep = "# foo\n" + "-" * 300000 + "1\n"
    elifs = "if a:\n    pass\n" + "elif a:\n    pass\n" * 170000
    flat = "".join(f"def f{i}():\n    return {i}\n" for i in range(12000))
    c1 = (m._drift_py_names(deep), m._drift_py_names(elifs))
    got = m._drift_py_names(flat)
    check("C1 極長的一行、極長的 elif 鏈:不崩潰、回 None 退回正則;一般大檔照解析(外家 F1、r4 正確性 F1)",
          c1 == (None, None) and got is not None and "f11999" in got[0], f"{c1} {None if got is None else len(got[0])}")
    # ── D 版面、路徑 ──
    root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
    _nh_file(root, "Foo/Main.SWIFT", "x\n")
    _nh_file(root, "FooTests/Helper.swift", "func makeFixture() {}\n")
    _nh_node(root, "Pay", summary="FLOW:a", body=f"REVISIT:[when-symbol:makeFixture]{by} 輔助函式變成正式程式")
    _nh_commit(root, "base")
    b1 = _na_head(root)
    _nh_git(root, "rm", "-q", "Foo/Main.SWIFT")
    _nh_commit(root, "只刪一支不算程式檔的檔")
    rc, out = _dr(root, "check", "--diff", f"{b1}..HEAD")
    check("D1 刪一支檔讓別的檔從測試檔變程式檔:條件翻成立,擋(正確性 F2)", rc == 1 and "輔助函式變成正式程式" in out, out)
    got = [m._probe_parse(f"[when-{v}]{by}") for v in ("file:a\\..\\x.py", "file:..\\x.py", "file:a/../x.py", "file:src\\a.py")]
    check("D2 反斜線寫的 .. 段一律算寫錯,正常的反斜線路徑照收(正確性 F3)",
          [g["bad"] for g in got] == [True, True, True, False] and got[3]["conds"] == [("file", "src/a.py")], str(got))
    b2 = _na_head(root)
    _add_raw(root, "a\\..\\x.py", "x\n")                    # 樹上真的有一支檔就叫 a\..\x.py
    sp.run(["git", "-C", str(root), "commit", "-qm", "反斜線檔名", "--no-verify"], capture_output=True)
    bad_pr = m._probe_parse(f"[when-file:a\\..\\x.py]{by}")
    tenv = type("T", (), {})()
    tenv.notes = {"Systems/Pay.md": None}
    orig = m.env_text, m._probe_lines
    m.env_text = lambda e, p: "tip" if e is tenv else "base"
    m._probe_lines = lambda t: ([(3, "REVISIT", bad_pr)], []) if t == "tip" else ([], [])
    try:
        res = m._drift_probe_check(root, b2, _na_head(root), V, tenv)
    finally:
        m.env_text, m._probe_lines = orig
    check("D3 寫錯的條件不評估:check 看解析的旗標,不拿存下的原文重驗(正確性 F3)",
          bad_pr["bad"] and res == ([], [], []), str(res))
    # ── E 參數與提示 ──
    vault = root / V
    r = run(vault, "drift", "scan", "--at", "HEAD", "--budget", "1e10")
    check("E1 --budget 超過一天:擋下 rc2,不溢位(邊界 F1)", r.returncode == 2, (r.stdout + r.stderr)[-200:])
    fake = type("T", (), {"files": set()})()
    got = {v: m._drift_probe_path_warn("symbol", v, fake) is not None
           for v in ("app.Config::load", "plugin.c++::load", "script.R::f", "v1.2::x", "src/new.py::main")}
    check("E2 像不像檔名:app.Config、v1.2 列;.c++、.R、還沒建的 src/new.py 不列(邊界 F3、外家 F4)",
          got == {"app.Config::load": True, "plugin.c++::load": False, "script.R::f": False, "v1.2::x": True,
                  "src/new.py::main": False}, str(got))
    # ── F 兩條判不了的路有測試守著 ──
    stub = type("S", (), {"names_in": lambda s, paths, test: None, "bad_paths": lambda s: ["src/壞.py"],
                          "unread_for": lambda s, k, v: ["src/壞.py"]})()
    orig_old = m._drift_probe_old
    m._drift_probe_old = lambda *a, **k: True
    try:
        todo, unk = m._drift_probe_candidates([("Systems/Pay.md", 7, "x", m._probe_parse(f"[when-symbol:foo]{by}"))],
                                             ch, V + "/", None, None, stub, lambda: False)
    finally:
        m._drift_probe_old = orig_old
    check("F1 候選判不了:記成判不了並點名那支檔,不當成不是候選(圖譜一致 F1)",
          todo == [] and len(unk) == 1 and "src/壞.py" in unk[0], str(unk))
    root = _nh_repo()
    _nh_file(root, "src/a.py", "def here():\n    pass\n")
    _nh_file(root, "src/b.py", "x = 1\n")
    _nh_commit(root, "c")
    tr = m._drift_probe_tree(root, _na_head(root))
    orig_cat = m._nodehome_cat_blobs
    m._nodehome_cat_blobs = lambda r, specs, **k: [None if i == 1 else orig_cat(r, [s], **k)[0] for i, s in enumerate(specs)]
    try:
        got = (tr.one("symbol", "here"), tr.one("symbol", "nothere"))
    finally:
        m._nodehome_cat_blobs = orig_cat
    check("F2 語料有一支讀不出:找到定義照成立,找不到算判不了(圖譜一致 F1)", got == (True, None), str(got))


def t_drift_code_review_yi_r4_regressions():
    """乙代碼審 r4(上限後的破例輪)查出的洞:SHA-256 repo 記不到內容編號、一支讀不出就把另一支的確定命中降成判不了、
    判不了時點名無關的檔、點名的檔名沒跳脫控制字元。3.9 崩潰那幾條隨最低版本改 3.14 整段拿掉(見 r3 回歸測試 C1)。
    翻紅釘:只認 40 碼 → A1 紅;有一支讀不出就回 None → B1 紅;點名整棵樹 → C1 紅;不跳脫 → D1 紅。"""
    print("t_drift_code_review_yi_r4_regressions")
    import subprocess as sp, tempfile as _tf, unicodedata as _ud
    m = _load_lumos_inproc()
    # ── A SHA-256 物件格式的 repo:用內容編號讀 NFD 檔名的程式檔 ──
    tmp = Path(_tf.mkdtemp(prefix="gctl-yi-r4-"))
    root = tmp / "r256"
    ok = sp.run(["git", "init", "-q", "--object-format=sha256", str(root)], capture_output=True).returncode == 0
    if ok:
        for kv in (("user.email", "t@t"), ("user.name", "t"), ("core.precomposeunicode", "false")):
            sp.run(["git", "-C", str(root), "config", *kv], capture_output=True)
        blob = sp.run(["git", "-C", str(root), "hash-object", "-w", "--stdin"], input=b"def cafe_fn():\n    pass\n",
                      capture_output=True).stdout.decode().strip()
        nfd = _ud.normalize("NFD", "src/café.py")
        sp.run(["git", "-C", str(root), "update-index", "--add", "--cacheinfo", f"100644,{blob},{nfd}"], capture_output=True)
        sp.run(["git", "-C", str(root), "commit", "-qm", "c"], capture_output=True)
        head = sp.run(["git", "-C", str(root), "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
        m._DRIFT_LS_CACHE.clear()
        m._DRIFT_OID_CACHE.clear()
        t = m._drift_probe_tree(str(root), head, None)
        got = (t.one("symbol", "cafe_fn"), t.one("symbol", "src/café.py::cafe_fn")) if t else None
        check("A1 SHA-256 repo(64 碼提交編號)、git 裡存 NFD 檔名:帶路徑與不帶路徑的條件都判得出成立",
              len(head) == 64 and got == (True, True), f"{len(head)} {got}")
    else:
        print("  (沒驗到 A1:這台機器的 git 不支援 --object-format=sha256)")
    # ── B 一支讀不出、另一支確定命中 ──
    t = m._DriftProbeTree(".", "tip", {"good.py", "bad.py"}, ({}, {}))
    t._text = {"good.py": "def target():\n    pass\n", "bad.py": None}
    ch = {"touched": {"good.py", "bad.py"}, "renames": {}, "code_shape": False, "code_touched": ["good.py", "bad.py"]}
    names = lambda test: t.names_in(ch["code_touched"], test)  # noqa: E731
    hit = m._drift_probe_is_candidate([("symbol", "target")], ch, "docs/kg-knowledge/", None, names)
    miss = m._drift_probe_is_candidate([("symbol", "elsewhere")], ch, "docs/kg-knowledge/", None, names)
    check("B1 讀得出的那支找到名稱:算候選;找不到而有檔讀不出:判不了(不是不成立)", hit is True and miss is None,
          f"hit={hit} miss={miss}")
    # ── C 判不了只點名這一行碰到的 ──
    E = type("E", (), {"notes": {}, "resolve": lambda s, x: "Projects/壞.md"})
    env = E()
    env.notes = {"Projects/壞.md": object()}
    real = m._note_unreadable
    m._note_unreadable = lambda n: True
    try:
        st = m._drift_row_unread([("status", "[[Projects/壞]]=done")], (env,), (t,))
    finally:
        m._note_unreadable = real
    sym = m._drift_row_unread([("symbol", "other.py::f")], (), (t,))
    check("C1 status 判不了點名指到的那篇筆記、不點名無關的程式檔;帶路徑的只點名那一支",
          st == ["Projects/壞.md"] and sym == [], f"st={st} sym={sym}")
    # ── D 檔名裡的控制字元 ──
    note = m._drift_bad_note(["src/a\x1b[2Kb.py"])
    check("D1 點名的檔名先把控制字元換成空格才印", "\x1b" not in note and "src/a" in note, repr(note))


def t_drift_code_review_yi_r5_regressions():
    """乙代碼審 r5(上限後第二次破例輪)查出的洞:程式檔與測試檔的讀不出混在一起、帶標點的名稱每條掃全文耗光預算、
    SHA-256 repo 的空樹、印到終端的筆記路徑與原文沒跳脫。
    翻紅釘:names_in 不分類 → A1 紅;點名不分類 → A2 紅;帶標點的名稱不先查字詞 → B1 紅;空樹寫死 SHA-1 → C1 紅;
    印出不消毒 → D1 紅。"""
    print("t_drift_code_review_yi_r5_regressions")
    import io as _io, pathlib as _pl, subprocess as sp, tempfile as _tf, time as _time, types as _types
    m = _load_lumos_inproc()
    # ── A 程式檔與測試檔分開算 ──
    f = {"src/good.py", "tests/test_bad.py"}
    t = m._DriftProbeTree(".", "tip", f, m._nodehome_layout(sorted(f)))
    t._text = {"src/good.py": "def target(): pass\n", "tests/test_bad.py": None}
    ch = {"touched": set(f), "renames": {}, "code_shape": False, "code_touched": sorted(f)}
    cand = m._drift_probe_is_candidate([("symbol", "elsewhere")], ch, "docs/kg-knowledge/", None,
                                       lambda test: t.names_in(ch["code_touched"], test))
    check("A1 讀不出的是測試檔:symbol 條件的候選判定照常(不成立),跟正式判定一致(正確性 F1)",
          cand is False and t.one("symbol", "elsewhere") is False, f"cand={cand}")
    files = {"zz/a.py", *[f"tests/t{i}.py" for i in range(6)]}
    tree = m._DriftProbeTree(".", "tip", files, m._nodehome_layout(sorted(files)))
    tree._read = _types.MethodType(lambda self, paths: self._text.update({p: None for p in paths}) is None, tree)

    def note(cond):
        return "---\ntype: system\nstatus: doing\nsummary: x\n---\n" f"REVISIT:{cond}[by:2099-12-31] x\n"
    env = m.Env.from_texts(_pl.Path("/unused"), {"Systems/A.md": note("[when-test:missing]"),
                                                  "Systems/B.md": note("[when-symbol:missing]")})
    _found, probs = m._drift_probe_scan(env, tree)
    by = {p: w for p, _n, _t, w in probs}
    check("A2 前一行讀過的測試檔不混進這一行的點名:symbol 那行只點名讀不出的程式檔(外家 F3)",
          "zz/a.py" in by.get("Systems/B.md", "") and "tests/" not in by.get("Systems/B.md", "")
          and "tests/t0.py" in by.get("Systems/A.md", ""), str(by))
    # ── B 帶標點的名稱 ──
    names = m._DriftNames(["x_1 " * 1500000])
    t0 = _time.monotonic()
    hits = [names.has(f"missing-{i}") for i in range(850)]
    el = _time.monotonic() - t0
    check("B1 帶標點的名稱先查字詞:850 條不在 6MB 全文裡的名稱 1 秒內判完(外家 F2)", el < 1 and not any(hits), f"{el:.2f}s")
    check("B1 字詞都在時照樣對全文確認(整字)", m._DriftNames(["call foo-bar(x)"]).has("foo-bar")
          and not m._DriftNames(["foo bar"]).has("foo-bar"), "")
    # ── C SHA-256 repo 的空樹 ──
    root = Path(_tf.mkdtemp(prefix="gctl-yi-r5-")) / "r"
    if sp.run(["git", "init", "-q", "--object-format=sha256", str(root)], capture_output=True).returncode == 0:
        (root / "a.py").write_text("x = 1\n", encoding="utf-8")
        sp.run(["git", "-C", str(root), "add", "a.py"], capture_output=True)
        sp.run(["git", "-C", str(root), "-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "c"], capture_output=True)
        head = sp.run(["git", "-C", str(root), "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
        m._DRIFT_EMPTY_TREE.clear()
        et = m._drift_empty_tree(str(root))
        chg = m._drift_probe_changes(str(root), None, head)
        check("C1 SHA-256 repo 沒有起點(首推):用這個 repo 的空樹算改動,不是 SHA-1 那個(外家 F1、正確性 F4)",
              len(et) == 64 and chg is not None and "a.py" in chg["touched"], f"{et} {chg}")
    else:
        print("  (沒驗到 C1:這台機器的 git 不支援 --object-format=sha256)")
    # ── D 印出消毒 ──
    buf = _io.StringIO()
    m._drift_print_findings([{"kind": "probe", "path": "Systems/a\x1b[2K.md", "line": 3, "text": "REVISIT:\x1b]0;x\x07",
                              "why": "因為\x1b[31m"}], buf)
    check("D1 筆記路徑、原文、說明印到終端前換掉控制字元(資安 F1)", "\x1b" not in buf.getvalue() and "\x07" not in buf.getvalue(),
          repr(buf.getvalue()))


# ═══ 存量漂移改法(Projects/存量漂移改法_計劃):drift fix、settle 對 pass、E5 標記、結案列回頭條件、表態綁關係 ═══

_DF_PAY = ("KEY:★INVARIANT★ 大額退費要人工核可 [test:t_refund]\nKEY:★INVARIANT★ 合約乙 [test:t_b]\n"
           "KEY:★INVARIANT★ 合約丙 [test:t_c]\nKEY:★INVARIANT★ 合約丁 [test:t_d]\nKEY:★INVARIANT★ 合約戊 [test:t_e]\n"
           "KEY:★INVARIANT★ 合約己 [test:t_f]\nKEY:★INVARIANT★ 合約庚 [test:t_g]")


def _df_commit(root, msg="c", date=None):
    """提交(可指定作者與提交者日期,c1 推轉正日期用)。"""
    import subprocess as sp, os as _os
    e = dict(_os.environ)
    if date:
        e["GIT_AUTHOR_DATE"] = e["GIT_COMMITTER_DATE"] = date + "T12:00:00"
    sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True, env=e)
    sp.run(["git", "-C", str(root), "commit", "-qm", msg, "--no-verify"], capture_output=True, env=e)


def _df_fix(vault, *args, env=None):
    import subprocess as sp, os as _os
    e = dict(_os.environ)
    e.pop("LUMOS_DRIFT_FIX_FAULT", None)
    if env:
        e.update(env)
    r = sp.run([sys.executable, GRAPHCTL, "--vault", str(vault), "drift", "fix", *args], capture_output=True, text=True, env=e)
    return r.returncode, r.stdout + r.stderr


def _df_rows(root, name="drift-fixes.jsonl"):
    import json as _j
    p = root / "governance" / name
    return [_j.loads(x) for x in p.read_text(encoding="utf-8").splitlines() if x.strip()] if p.is_file() else []


def _df_find(vault, kind, path):
    fs = _dr_scan(vault)
    return [f for f in fs if f["kind"] == kind and f["path"] == path] if isinstance(fs, list) else fs


def _df_repo():
    """存量漂移改法的測試專案:_dr_repo + 家筆記 Pay 有好幾條綁了測試的正式合約行 + 已收尾的計劃 Done_計劃。"""
    root = _dr_repo()
    _nh_node(root, "Pay", summary=_DF_PAY)
    _nh_node(root, "Done_計劃", typ="project", folder="Projects", resp=None, status="done", summary="KEY:d")
    _df_commit(root, "df base", "2026-08-01")
    return root


def t_drift_fix_refuses_wrong_kind():
    """[S1] drift fix 指定的行不是那一種、參數與種類不合、--kind 不是 c1–c5、同名好幾篇、沒被追蹤、有不是工具留下的改動、
    帶 BOM 或 CRLF → 回 2、不寫任何檔;drift fix 走自己的分派,不被當成 ack。

    翻紅釘:_drift_fix_load 拿掉 _drift_current_finding 的判定 → ②紅(c3 的改法會套上去);_drift_fix_args_err 拿掉
    「不收」那段 → ③紅;_drift_fix_target 改回 env.find → ⑤紅(取第一篇);乾淨檢查拿掉 → ⑥⑦紅;
    main 的 drift 分派改回「不是 scan 就當 ack」→ ⑨紅(寫出表態檔)。
    """
    print("t_drift_fix_refuses_wrong_kind")
    root = _df_repo()
    v = root / _DR_VAULT
    _nh_file(root, f"{_DR_VAULT}/Issues/I.md", "---\ntype: issue\nstatus: open\n---\n# I\n[[Projects/Done_計劃]]\n")
    (v / "Verification" / "G.md").write_text(_dr_guard_text("pass"), encoding="utf-8")
    _nh_file(root, f"{_DR_VAULT}/Systems/Dup.md", "---\ntype: issue\nstatus: open\n---\n# D\n[[Projects/Done_計劃]]\n")
    _nh_file(root, f"{_DR_VAULT}/Issues/Dup.md", "---\ntype: issue\nstatus: open\n---\n# D\n[[Projects/Done_計劃]]\n")
    (v / "Issues" / "Bom.md").write_bytes(b"\xef\xbb\xbf---\ntype: issue\nstatus: open\n---\n# B\n[[Projects/Done_\xe8\xa8\x88\xe5\x8a\x83]]\n")
    (v / "Issues" / "Crlf.md").write_bytes("---\r\ntype: issue\r\nstatus: open\r\n---\r\n# C\r\n[[Projects/Done_計劃]]\r\n".encode("utf-8"))
    _df_commit(root, "cases")
    fs = _dr_scan(v)
    check("①前置:I 第 3 行是 c2、G 有 c1、BOM 與 CRLF 那兩篇也被列成 c2", isinstance(fs, list)
          and ("Issues/I.md", 3) in [(f["path"], f["line"]) for f in fs if f["kind"] == "c2"]
          and any(f["kind"] == "c1" and f["path"] == "Verification/G.md" for f in fs)
          and {"Issues/Bom.md", "Issues/Crlf.md"} <= {f["path"] for f in fs if f["kind"] == "c2"}, str(fs)[:500])
    before = _nh_git(root, "status", "--porcelain").stdout
    rc, out = _df_fix(v, "Issues/I", "3", "--kind", "c3", "--status", "pass")
    check("②那一行不是這一種(c2 那行指定 c3):回 2、說明現在不是", rc == 2 and "現在不是 c3" in out, out)
    rc, out = _df_fix(v, "Verification/G", "20", "--kind", "c1", "--status", "pass")
    check("③參數與種類不合(c1 帶 --status):回 2", rc == 2 and "不收 --status" in out, out)
    rc, out = _df_fix(v, "Issues/I", "3", "--kind", "probe")
    check("④--kind probe:回 2、指到把待辦做掉或 drift ack", rc == 2 and "drift ack" in out and "沒有工具改法" in out, out)
    rc, out = _df_fix(v, "Issues/I", "3", "--kind", "c9")
    check("④--kind 不是 c1–c5:回 2", rc == 2 and "c1/c2/c3/c4/c5" in out, out)
    rc, out = _df_fix(v, "Dup", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "已經修好了")
    check("⑤節點同名好幾篇:回 2、要完整路徑(不猜第一篇)", rc == 2 and "同名筆記有 2 篇" in out, out)
    _nh_file(root, f"{_DR_VAULT}/Issues/New.md", "---\ntype: issue\nstatus: open\n---\n# N\n[[Projects/Done_計劃]]\n")
    check("⑥前置:New 沒被追蹤、但確實是 c2", "Issues/New.md" in _nh_git(root, "status", "--porcelain", "-uall").stdout
          and _df_find(v, "c2", "Issues/New.md"), "")
    rc, out = _df_fix(v, "Issues/New", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "已經修好了")
    check("⑥沒被追蹤:回 2(改壞了退不回來)", rc == 2 and "沒被 git 追蹤" in out, out)
    (v / "Issues" / "New.md").unlink()
    ip = v / "Issues" / "I.md"
    ip.write_text(ip.read_text(encoding="utf-8") + "\n別人寫到一半\n", encoding="utf-8")
    check("⑦前置:I 有別人的未提交改動", " M " in _nh_git(root, "status", "--porcelain").stdout, "")
    rc, out = _df_fix(v, "Issues/I", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "已經修好了")
    check("⑦有不是工具自己留下的未提交改動:回 2、別人的改動還在", rc == 2 and "未提交的改動" in out
          and "別人寫到一半" in ip.read_text(encoding="utf-8"), out)
    _nh_git(root, "checkout", "--", f"{_DR_VAULT}/Issues/I.md")
    for name in ("Bom", "Crlf"):
        raw = (v / "Issues" / f"{name}.md").read_bytes()
        rc, out = _df_fix(v, f"Issues/{name}", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "已經修好了")
        check(f"⑧{name}:回 2、講明原因、檔案一個位元組都沒動", rc == 2 and {"Bom": "BOM", "Crlf": "CRLF"}[name] in out
              and (v / "Issues" / f"{name}.md").read_bytes() == raw, out)
        rc, out = _df_fix(v, f"Issues/{name}", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "已經修好了",
                          "--dry-run")
        check(f"⑧{name}:--dry-run 也回 2(預覽跟實寫一致)", rc == 2, out)
    check("②–⑧全部擋下後:工作目錄跟擋之前一樣、沒寫表態檔與修復帳",
          _nh_git(root, "status", "--porcelain").stdout == before
          and not (root / "governance" / "drift-acks.jsonl").exists() and not (root / "governance" / "drift-fixes.jsonl").exists(),
          _nh_git(root, "status", "--porcelain").stdout)
    rc, out = _df_fix(v, "Issues/I", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "已經修好了", "--dry-run")
    check("⑨drift fix 走自己的分派:dry-run 印預覽、不寫表態檔", rc == 0 and "預覽" in out
          and not (root / "governance" / "drift-acks.jsonl").exists(), out)


def t_drift_fix_c1_rewrites_with_commit_date():
    """[S2] c1 修已 pass 的守衛紀錄:改寫四種預告句,日期依序取 --date、那篇已寫的轉正日期、守衛紀錄第一次變成 pass 的提交
    日期(那一筆若也是檔案第一次出現就不算);推不出、shallow、已寫的兩個日期不同時擋下、不用今天;家節點沒有綁測試的正式行擋下;
    下一個非空行是手補的「已轉正」時刪掉 settle 句那一行、不疊。

    翻紅釘:_guard_pass_commit_date 改成拿今天 → ②紅;拿掉「那一筆也是第一次出現」→ ⑦紅;_guard_settled_date 先查 git 再看
    已寫日期 → ⑤紅;拿掉兩處日期不同的檢查 → ⑥紅;_guard_pass_home 拿掉 → ⑧紅(家節點沒有正式行也改);
    _guard_settle_rewrite 的 settle-del 拿掉 → ⑨紅(疊出兩行已轉正);shallow 檢查拿掉 → ⑩紅。
    """
    print("t_drift_fix_c1_rewrites_with_commit_date")
    import hashlib, subprocess as sp, tempfile as _tf, datetime
    today = datetime.date.today().isoformat()
    root = _df_repo()
    v = root / _DR_VAULT
    V = v / "Verification"
    specs = {"G": "大額退費要人工核可", "G2": "合約乙", "G3": "合約丙", "G4": "合約丁", "G6": "沒轉正的合約", "G7": "合約己"}
    for name, claim in specs.items():
        (V / f"{name}.md").write_text(_dr_guard_text("pending", claim=claim), encoding="utf-8")
    _df_commit(root, "plan", "2026-09-01")
    for name in specs:
        t = (V / f"{name}.md").read_text(encoding="utf-8").replace("status: pending", "status: pass").replace(
            "status/pending", "status/pass")
        if name == "G3":
            t = t.replace("還沒定案\n  TEST", "還沒定案(2026-09-15 已轉正)\n  TEST")
        if name == "G4":
            t = t.replace("還沒定案\n  TEST", "還沒定案(2026-09-15 已轉正)\n  TEST").replace(
                "不要手改狀態。\n", "不要手改狀態。\n\n2026-09-16 已轉正:手補的\n")
        if name == "G7":
            t = t.replace("不要手改狀態。\n", "不要手改狀態。\n\n2026-09-18 已轉正:人手補的說明\n")
        (V / f"{name}.md").write_text(t, encoding="utf-8")
    _df_commit(root, "舊版 settle 轉正", "2026-09-20")
    (V / "G5.md").write_text(_dr_guard_text("pass", claim="合約戊"), encoding="utf-8")
    _df_commit(root, "整批匯入", "2026-09-22")
    fs = _dr_scan(v)
    g1 = sorted(f["line"] for f in fs if f["kind"] == "c1" and f["path"] == "Verification/G.md")
    check("①前置:G 有四筆 c1、轉正那次提交的日期是 2026-09-20", len(g1) == 4 and "2026-09-20" in _nh_git(
        root, "log", "--format=%as", "--", f"{_DR_VAULT}/Verification/G.md").stdout, str(g1))
    rc, out = _df_fix(v, "Verification/G", str(g1[0]), "--kind", "c1")
    t = (V / "G.md").read_text(encoding="utf-8")
    check("②沒給日期:用守衛紀錄第一次變成 pass 的提交日期(不是今天)", rc == 0
          and "TEST:[2026-09-20] 預告已轉正,合約改由 [[Systems/Pay]] 的正式合約行守" in t
          and "還沒定案(2026-09-20 已轉正)" in t and "\n預告當時為什麼還不做:" in t and "\n(2026-09-20 已轉正)\n" in t
          and (today == "2026-09-20" or today not in t), out + t)
    check("②c1 整篇消失", not _df_find(v, "c1", "Verification/G.md"), "")
    rows = _df_rows(root)
    check("③修復帳一筆:種類、路徑、改後指紋等於磁碟", len(rows) == 1 and rows[0]["kind"] == "c1"
          and rows[0]["path"] == f"{_DR_VAULT}/Verification/G.md"
          and rows[0]["after_sha256"] == hashlib.sha256((V / "G.md").read_bytes()).hexdigest() and rows[0]["changed"], str(rows))
    ln = lambda n: str(min(f["line"] for f in _df_find(v, "c1", f"Verification/{n}.md")))
    rc, out = _df_fix(v, "Verification/G2", ln("G2"), "--kind", "c1", "--date", "2026-09-05")
    check("④--date 優先", rc == 0 and "TEST:[2026-09-05]" in (V / "G2.md").read_text(encoding="utf-8"), out)
    rc, out = _df_fix(v, "Verification/G3", ln("G3"), "--kind", "c1")
    check("⑤那篇已寫的轉正日期(WHY 行尾)優先於提交日期", rc == 0 and "TEST:[2026-09-15]" in (V / "G3.md").read_text(encoding="utf-8"),
          out)
    raw4 = (V / "G4.md").read_bytes()
    rc, out = _df_fix(v, "Verification/G4", ln("G4"), "--kind", "c1")
    check("⑥已寫的兩個日期不同:回 2、不寫", rc == 2 and "不一致" in out and (V / "G4.md").read_bytes() == raw4, out)
    raw5 = (V / "G5.md").read_bytes()
    rc, out = _df_fix(v, "Verification/G5", ln("G5"), "--kind", "c1")
    check("⑦第一次是 pass 的那筆也是檔案第一次出現(匯入):回 2、要 --date", rc == 2 and "第一次出現" in out
          and (V / "G5.md").read_bytes() == raw5, out)
    rc, out = _df_fix(v, "Verification/G5", ln("G5"), "--kind", "c1", "--date", "2026-09-10")
    check("⑦給了 --date 就改", rc == 0 and "TEST:[2026-09-10]" in (V / "G5.md").read_text(encoding="utf-8"), out)
    raw6 = (V / "G6.md").read_bytes()
    rc, out = _df_fix(v, "Verification/G6", ln("G6"), "--kind", "c1", "--date", "2026-09-10")
    check("⑧家節點沒有綁測試的正式行:回 2、講兩條出路", rc == 2 and "pending" in out and "drift ack" in out
          and (V / "G6.md").read_bytes() == raw6, out)
    rc, out = _df_fix(v, "Verification/G7", ln("G7"), "--kind", "c1")
    t7 = (V / "G7.md").read_text(encoding="utf-8")
    check("⑨下一個非空行是手補的已轉正:刪掉 settle 句、不疊一行,日期取手補那天", rc == 0 and "做完之後跑" not in t7
          and t7.count("已轉正:人手補的說明") == 1 and "\n(2026-09-18 已轉正)\n" not in t7 and "TEST:[2026-09-18]" in t7
          and "預告當時為什麼還不做:下游介面還沒定案\n\n2026-09-18 已轉正" in t7, out + t7)
    # ⑩ shallow:淺複製的 repo 查不到完整歷史
    (V / "G8.md").write_text(_dr_guard_text("pending", claim="合約庚"), encoding="utf-8")
    _df_commit(root, "g8 plan", "2026-09-01")
    t8 = (V / "G8.md").read_text(encoding="utf-8").replace("status: pending", "status: pass").replace("status/pending", "status/pass")
    (V / "G8.md").write_text(t8, encoding="utf-8")
    _df_commit(root, "g8 pass", "2026-09-21")
    sh = Path(_tf.mkdtemp(prefix="gctl-shallow-")) / "r"
    sp.run(["git", "clone", "-q", "--depth", "1", "file://" + str(root), str(sh)], capture_output=True)
    sv = sh / _DR_VAULT
    check("⑩前置:淺複製成功、G8 有 c1", (sh / ".git" / "shallow").exists() and _df_find(sv, "c1", "Verification/G8.md"), "")
    rc, out = _df_fix(sv, "Verification/G8", str(min(f["line"] for f in _df_find(sv, "c1", "Verification/G8.md"))), "--kind", "c1")
    check("⑩shallow:回 2、要 --date", rc == 2 and "shallow" in out and "--date" in out, out)


def t_guard_settle_pass_completes_prose():
    """[S3] guard settle 遇到 pass 但還留著預告句:用 guard 區段同一支補改、不需要 --test、接受 --date;沒有預告句照舊回 0 印已轉正;
    前提不符回 2;pending 沒給 --test 或給了 --date 擋下。pending 轉正遇到手補的已轉正段也刪 settle 句(同一支)。

    翻紅釘:_guard_settle_pass 改回一律「已轉正,不用再做」→ ①紅;--test 改回必填 → ①紅(argparse 擋);
    pending 分支拿掉 --date 檢查 → ④紅;_guard_pass_home 拿掉 → ③紅;pending 轉正的 _guard_settle_rewrite 拿掉 settle-del → ⑥紅。
    """
    print("t_guard_settle_pass_completes_prose")
    import datetime
    today = datetime.date.today().isoformat()
    root = _df_repo()
    v = root / _DR_VAULT
    V = v / "Verification"
    (V / "P1.md").write_text(_dr_guard_text("pass"), encoding="utf-8")
    (V / "P2.md").write_text(_dr_guard_text("pass", prose=False), encoding="utf-8")
    (V / "P3.md").write_text(_dr_guard_text("pass", claim="沒轉正的合約"), encoding="utf-8")
    (V / "P5.md").write_text(_dr_guard_text("pending", claim="合約乙"), encoding="utf-8")
    _df_commit(root, "plan", "2026-09-01")
    t5 = (V / "P5.md").read_text(encoding="utf-8").replace("status: pending", "status: pass").replace("status/pending", "status/pass")
    (V / "P5.md").write_text(t5, encoding="utf-8")
    _df_commit(root, "old settle", "2026-09-19")
    check("①前置:P1 是 pass 而且有 c1", _df_find(v, "c1", "Verification/P1.md"), "")
    r = run(v, "guard", "settle", "Verification/P1", "--date", "2026-09-12")
    t1 = (V / "P1.md").read_text(encoding="utf-8")
    check("①pass 還有預告句:不用 --test、照 --date 補改、成功訊息不印 [test:]", r.returncode == 0
          and "TEST:[2026-09-12]" in t1 and "做完之後跑" not in t1 and "[test:" not in r.stdout, r.stdout + r.stderr + t1)
    check("①補改後 c1 消失", not _df_find(v, "c1", "Verification/P1.md"), "")
    r = run(v, "guard", "settle", "Verification/P2")
    check("②pass 沒有預告句:照舊回 0 印已轉正", r.returncode == 0 and "已轉正,不用再做" in r.stdout, r.stdout + r.stderr)
    raw3 = (V / "P3.md").read_bytes()
    r = run(v, "guard", "settle", "Verification/P3", "--date", "2026-09-12")
    check("③前提不符(家節點沒有正式行):回 2、講兩條出路、不寫", r.returncode == 2 and "pending" in r.stderr
          and "drift ack" in r.stderr and (V / "P3.md").read_bytes() == raw3, r.stdout + r.stderr)
    _gp(v, "guard", "plan", "Systems/Pay", "新預告的合約", "--plan", "Projects/退款_計劃", "--phase", "P1", "--due", "2099-12-31",
        "--why", "還沒定", "--owner", "enzo", "--name", "新預告")
    g4 = [x for x in V.glob("*.md") if "新預告" in x.stem][0]
    raw4 = g4.read_bytes()
    r = run(v, "guard", "settle", "Verification/" + g4.stem)
    check("④pending 沒給 --test:回 2", r.returncode == 2 and "--test" in r.stderr and g4.read_bytes() == raw4, r.stdout + r.stderr)
    r = run(v, "guard", "settle", "Verification/" + g4.stem, "--test", "t_new", "--date", "2026-09-12")
    check("④pending 給了 --date:回 2", r.returncode == 2 and "--date" in r.stderr and g4.read_bytes() == raw4, r.stdout + r.stderr)
    r = run(v, "guard", "settle", "Verification/P5")
    check("⑤沒給 --date:推出守衛紀錄變成 pass 那次提交的日期", r.returncode == 0
          and "TEST:[2026-09-19]" in (V / "P5.md").read_text(encoding="utf-8"), r.stdout + r.stderr)
    g4.write_text(g4.read_text(encoding="utf-8").replace("不要手改狀態。\n", "不要手改狀態。\n\n2026-09-18 已轉正:人手補的\n"),
                  encoding="utf-8")
    check("⑥前置:pending 那篇 settle 句後面有手補段", "2026-09-18 已轉正:人手補的" in g4.read_text(encoding="utf-8")
          and "做完之後跑" in g4.read_text(encoding="utf-8"), "")
    r = run(v, "guard", "settle", "Verification/" + g4.stem, "--test", "t_new")
    t4 = g4.read_text(encoding="utf-8")
    check("⑥pending 轉正也走同一支:刪掉 settle 句、不疊一行「(今天 已轉正)」", r.returncode == 0 and "做完之後跑" not in t4
          and f"\n({today} 已轉正)\n" not in t4 and t4.count("已轉正:人手補的") == 1, r.stdout + r.stderr + t4)


def t_drift_fix_c3_sets_status_and_note():
    """[S4] c3:只收驗證紀錄扣掉 pending 的合法值;改 status 並同步標籤、正文最後加一行依狀態措辭的說明;--by 找不到或猜不準擋下,
    寫進去的是完整路徑的連結;正文最後停在沒閉合的圍欄擋下;原本的正文不改。

    翻紅釘:_DRIFT_C3_STATUSES 放進 pending → ②紅;_drift_fix_by 改成取第一篇 → ③紅;措辭不分狀態 → ⑥紅;
    _drift_append_note 拿掉圍欄檢查 → ⑦紅;加行位置改成直接接在檔尾 → ④「隔一個空行、原正文不動」紅。
    """
    print("t_drift_fix_c3_sets_status_and_note")
    import datetime
    today = datetime.date.today().isoformat()
    root = _df_repo()
    v = root / _DR_VAULT
    V = v / "Verification"
    ref = 'plan_refs:\n  - "[[Projects/Done_計劃]]"\ntags:\n  - type/verification\n  - status/pending'
    body = "# V\n\n原本的正文第一段。\n\n原本的第二段。\n\n\n"
    write(v, "Verification/V.md", "type: verification\nstatus: pending\n" + ref, body=body)
    write(v, "Verification/V2.md", "type: verification\nstatus: pending\n" + ref, body="# V2\n內容\n")
    write(v, "Verification/V3.md", "type: verification\nstatus: pending\n" + ref, body="# V3\n```\n沒關的圍欄\n")
    write(v, "Verification/V4.md", "type: verification\nstatus: pending\n" + ref, body="")
    _nh_file(root, f"{_DR_VAULT}/Systems/Dup.md", "---\ntype: system\n---\n# D\n")
    _nh_file(root, f"{_DR_VAULT}/Issues/Dup.md", "---\ntype: issue\nstatus: open\n---\n# D\n")
    _df_commit(root, "c3 cases")
    check("①前置:V 第 3 行是 c3", [f["line"] for f in _df_find(v, "c3", "Verification/V.md")] == [3], "")
    raw = (V / "V.md").read_bytes()
    for bad in ("pending", "done"):
        rc, out = _df_fix(v, "Verification/V", "3", "--kind", "c3", "--status", bad)
        check(f"②--status {bad} 不合法:回 2、列出合法值", rc == 2 and "abandoned/pass/stale/superseded" in out, out)
    for by, why in (("Dup", "同名好幾篇"), ("不存在的", "找不到")):
        rc, out = _df_fix(v, "Verification/V", "3", "--kind", "c3", "--status", "pass", "--by", by)
        check(f"③--by {by}:{why} → 回 2", rc == 2 and why in out, out)
    check("②③擋下都沒動檔", (V / "V.md").read_bytes() == raw, "")
    rc, out = _df_fix(v, "Verification/V", "3", "--kind", "c3", "--status", "pass", "--by", "Done_計劃")
    t = (V / "V.md").read_text(encoding="utf-8")
    want = f"{today} 狀態改為 pass(存量漂移 c3),由 [[Projects/Done_計劃]] 解決"
    check("④status、標籤改成 pass;短名解成完整路徑的連結(不加反引號)", rc == 0 and "status: pass" in t and "status/pass" in t
          and "status/pending" not in t and f"[[Projects/Done_計劃]]" in t and "`[[" not in t, out + t)
    check("④加在正文最後一個非空行之後、隔一個空行,檔尾一個換行;原本的正文一字不動",
          t.endswith("原本的第二段。\n\n" + want + "\n") and "# V\n\n原本的正文第一段。\n\n原本的第二段。\n" in t, repr(t[-200:]))
    check("④c3 消失", not _df_find(v, "c3", "Verification/V.md"), "")
    rc, out = _df_fix(v, "Verification/V2", "3", "--kind", "c3", "--status", "stale", "--by", "Systems/Pay")
    t2 = (V / "V2.md").read_text(encoding="utf-8")
    check("⑥stale 的措辭是「參考」", rc == 0 and f"{today} 狀態改為 stale(存量漂移 c3),參考 [[Systems/Pay]]" in t2, out + t2)
    raw3 = (V / "V3.md").read_bytes()
    rc, out = _df_fix(v, "Verification/V3", "3", "--kind", "c3", "--status", "abandoned")
    check("⑦正文最後停在沒閉合的圍欄:回 2、不寫", rc == 2 and "圍欄" in out and (V / "V3.md").read_bytes() == raw3, out)
    rc, out = _df_fix(v, "Verification/V4", "3", "--kind", "c3", "--status", "superseded")
    t4 = (V / "V4.md").read_text(encoding="utf-8")
    check("⑧正文是空的:放在開頭欄位結束那行之後", rc == 0 and t4.endswith(f"---\n{today} 狀態改為 superseded(存量漂移 c3)\n"),
          out + repr(t4[-120:]))


def t_drift_fix_c4_evidence_then_replace():
    """[S5] c4 只列證據、範本與一條預填好的 lumos set 整欄指令,不寫檔、不做乾淨檢查、不寫修復帳;不收 --old/--new。
    ★c4 不自己寫開頭欄位★(Enzo 2026-09-30 裁,代碼審四輪:自己寫原始文字每輪都漏一種 YAML 形狀):改用既有的 lumos set 整欄重寫;
    指令裡要改的那項放佔位字,原封不動照貼會被 set 擋下;填好整句照貼就改好、c4 消失。
    漂移修法補強(2026-09-30)後:範本句的卷證一律是 <卷證>(不自動填),卷證目錄列在清單裡、標來源(細節見
    t_drift_c4_reports_from_first_commit)。

    翻紅釘:證據頁不標要改的那項或指令各項跟讀到的不一致 → ②紅;c4 也做乾淨檢查 → ③紅;set 拿掉佔位字檢查 → ④紅;
    範本改回自動填卷證目錄 → ②範本紅。
    """
    print("t_drift_fix_c4_evidence_then_replace")
    import shlex as _shlex
    root = _df_repo()
    v = root / _DR_VAULT
    E = v / "Verification" / "E.md"
    (root / "governance" / "review-reports" / "code-done").mkdir(parents=True)
    (root / "governance" / "review-reports" / "code-done" / "r1.md").write_text("x\n", encoding="utf-8")
    E.write_text("---\ntype: verification\nstatus: pass\nvalid_under:\n  - 本工作樹(未提交、未過代碼審);全套測試\n"
                 "  - 另一項 還沒提交 的前提\n  - 釘在提交 abc 的乾淨工作樹\nplan_refs:\n  - \"[[Projects/Done_計劃]]\"\n---\n# E\n",
                 encoding="utf-8")
    _df_commit(root, "c4 cases")
    first = _nh_git(root, "log", "--diff-filter=A", "--format=%H", "--", f"{_DR_VAULT}/Verification/E.md").stdout.split()[-1]
    fs = _df_find(v, "c4", "Verification/E.md")
    check("①前置:E 的 c4 指到第 5 行", [f["line"] for f in fs] == [5], str(fs))
    raw = E.read_bytes()
    rc, out = _df_fix(v, "Verification/E", "5", "--kind", "c4")
    tpl = f"提交 {first[:12]};代碼審見 <卷證>"
    cmd = [ln.strip() for ln in out.splitlines() if ln.strip().startswith("lumos set ")]
    check("②列第一次提交、卷證目錄(標來源)、範本(卷證放佔位字),回 0、不寫檔不寫帳", rc == 0 and first[:12] in out
          and "governance/review-reports/code-done(兩者)" in out and tpl in out and E.read_bytes() == raw and not _df_rows(root), out)
    check("②列出各項、標出要改的兩項", out.count("← 要改的這項") == 2 and "釘在提交 abc 的乾淨工作樹" in out, out)
    check("②預填的 lumos set 指令:要改的兩項放佔位字、其他照抄", cmd and _shlex.split(cmd[0]) == [
        "lumos", "set", "Verification/E", "valid_under", "<整項新內容>", "<整項新內容>", "釘在提交 abc 的乾淨工作樹"], str(cmd))
    rc, out = _df_fix(v, "Verification/E", "5", "--kind", "c4", "--old", "未提交", "--new", "x")
    check("②不收 --old/--new", rc == 2 and E.read_bytes() == raw, out)
    E.write_text(E.read_text(encoding="utf-8") + "未提交的一行\n", encoding="utf-8")
    rc, out = _df_fix(v, "Verification/E", "5", "--kind", "c4")
    check("③筆記有未提交改動也照列(只看不寫,不做乾淨檢查)", rc == 0 and "只列出、不寫檔" in out, out)
    E.write_bytes(raw)
    a = _shlex.split(cmd[0])
    r = run(v, *a[1:])
    check("④原封不動照貼:set 擋下佔位字、沒動檔", r.returncode == 2 and "<整項新內容>" in r.stderr and E.read_bytes() == raw,
          r.stdout + r.stderr)
    filled = tpl.replace("<卷證>", "governance/review-reports/code-done") + ";全套測試"
    r = run(v, "set", "Verification/E", "valid_under", filled, "已在 main 的前提", "釘在提交 abc 的乾淨工作樹")
    check("⑤填好整句照貼:改好、c4 消失", r.returncode == 0 and not _df_find(v, "c4", "Verification/E.md")
          and filled in E.read_text(encoding="utf-8"), r.stdout + r.stderr)


# ═══ 漂移修法補強(Projects/漂移修法補強_計劃):c4 卷證目錄兩種來源、set 擋範本佔位字、c1/settle 訊息、c3 理由、刪除守衛跳過工具自裝檔 ═══


def t_drift_c4_reports_from_first_commit():
    """[S1] c4 證據頁列卷證目錄:這篇第一次被提交的那個提交加進來(含改名進來)的 governance/review-reports/<目錄>,
    跟計劃名比對到的都列出、標來源(兩者/同提交/計劃名),排序兩者 → code- 開頭 → 其他、同級照字母;只列現在還在的目錄;
    同提交超過 3 個時先印「可能含別的計劃的卷證」;中文目錄名照原樣;範本句的卷證一律是 <卷證>;git 查不到時寫明。

    翻紅釘:--diff-filter=AR 改成 A → ②moved-in 紅;拿掉「只留還存在的」→ ③gone 紅;範本改回自動填目錄 → ④紅;
    排序改成只照字母 → ②順序紅;查不到時不寫明 → ⑤紅。
    """
    print("t_drift_c4_reports_from_first_commit")
    root = _df_repo()
    v = root / _DR_VAULT
    RR = "governance/review-reports"
    _nh_file(root, f"{RR}/done-old-plan/r1.md", "舊的\n")                  # 早一個提交就在:只有計劃名對得上
    _nh_file(root, "tmp/moved.md", "要改名進卷證目錄的內容\n")
    _df_commit(root, "earlier")
    E = v / "Verification" / "E.md"
    E.write_text("---\ntype: verification\nstatus: pass\nvalid_under:\n  - 本工作樹(未提交);全套測試\nplan_refs:\n"
                 "  - \"[[Projects/Done_計劃]]\"\n---\n# E\n", encoding="utf-8")
    for d in ("code-done", "code-xyz", "zeta", "審查卷證甲", "gone", "aaa", "zz-done"):
        _nh_file(root, f"{RR}/{d}/r1.md", f"{d} 的報告\n")
    (root / RR / "moved-in").mkdir(parents=True)
    _nh_git(root, "mv", "tmp/moved.md", f"{RR}/moved-in/r1.md")
    _df_commit(root, "feature with reports")
    first = _nh_git(root, "log", "--diff-filter=A", "--format=%H", "--", f"{_DR_VAULT}/Verification/E.md").stdout.split()[-1]
    shown = _nh_git(root, "-c", "core.quotePath=false", "show", "--name-status", "--format=", first).stdout
    check("①前置:E 第一次提交就是加卷證那一個;moved-in 是改名進來(R)、中文目錄同提交加進來",
          f"{RR}/審查卷證甲/r1.md" in shown and any(ln.startswith("R") and f"{RR}/moved-in/r1.md" in ln for ln in shown.splitlines())
          and [f["line"] for f in _df_find(v, "c4", "Verification/E.md")] == [5], shown)
    import shutil as _sh
    _sh.rmtree(root / RR / "gone")          # 同一個提交加進來、後來刪掉的目錄不列
    rc, out = _df_fix(v, "Verification/E", "5", "--kind", "c4")
    rows = [ln.strip() for ln in out.splitlines() if ln.strip().startswith(f"{RR}/")]
    want = [f"{RR}/code-done(兩者)", f"{RR}/zz-done(兩者)", f"{RR}/code-xyz(同提交)", f"{RR}/aaa(同提交)",
            f"{RR}/done-old-plan(計劃名)", f"{RR}/moved-in(同提交)", f"{RR}/zeta(同提交)", f"{RR}/審查卷證甲(同提交)"]
    check("②兩種來源都列、標來源、排序兩者 → code- → 其他(同級照字母),改名進來的也算,中文目錄照原樣", rc == 0 and rows == want,
          out)
    check("③已經刪掉的目錄不列", "gone" not in out, out)
    check("④範本句的卷證一律是 <卷證>(不自動填),提交照填", f"③範本句:提交 {first[:12]};代碼審見 <卷證>" in out, out)
    check("④同提交超過 3 個:先印可能含別的計劃的卷證", "可能含別的計劃的卷證(整批匯入或壓成一個的提交)" in out
          and out.index("可能含別的計劃的卷證") < out.index(want[0]), out)
    check("④最後提醒先提交再跑別的 drift fix", "用 lumos set 改完先提交" in out.splitlines()[-1], out)
    # ⑤git 查不到(這篇還沒提交):寫明查不到,計劃名那一份照列,範本的提交也放佔位字
    E2 = v / "Verification" / "E2.md"
    E2.write_text(E.read_text(encoding="utf-8"), encoding="utf-8")
    check("⑤前置:E2 還沒提交、也是 c4", "E2.md" in _nh_git(root, "status", "--porcelain", "-uall").stdout
          and [f["line"] for f in _df_find(v, "c4", "Verification/E2.md")] == [5], "")
    rc, out = _df_fix(v, "Verification/E2", "5", "--kind", "c4")
    rows = [ln.strip() for ln in out.splitlines() if ln.strip().startswith(f"{RR}/")]
    check("⑤git 查不到:寫明「同提交:查不到」,計劃名的照列,範本是 <sha> 與 <卷證>", rc == 0
          and "同提交:查不到(git 失敗或沒有)" in out
          and rows == [f"{RR}/code-done(計劃名)", f"{RR}/done-old-plan(計劃名)", f"{RR}/zz-done(計劃名)"]
          and "③範本句:提交 <sha>;代碼審見 <卷證>" in out, out)


def t_drift_c4_code_review_r1():
    """[S1] 代碼審 r1(2026-09-30)折入:
    - 同提交清單照目錄去重(一個卷證目錄通常有好幾支檔);剛好 3 個不印「可能含別的計劃的卷證」,超過才印(正確性 F1、spec 對照 F3)。
    - 「code- 開頭排在其他前面」對計劃名來源也適用(spec 對照 F3)。
    - ★NFC 只當比對鍵,印的是原名★:NFD 寫法的目錄照原樣印(外家否決 F2、正確性 F2、邊界 F2);第二輪起印的一律是磁碟上現存的名字
      (t_drift_c4_code_review_r2)。
    - 證據頁範本的佔位字(_SET_COND_SLOTS 後兩個)跟 --reason 那側的 _DRIFT_PLACEHOLDER_RE 認得的一致(架構對齊 F1)。
    - drift fix 的一行說明寫現況:c3 可帶 --reason、c4 只列證據不寫檔(合約圖譜 F1)。

    翻紅釘:拿掉去重 → ②紅;門檻 > 3 改 >= 3 或 > 0 → ②紅;code- 只算同提交來源 → ③紅;印 NFC 名 → ④紅;
    同提交改回印 git 裡的名字 → ⑤紅;_DRIFT_PLACEHOLDER_RE 少認一個 → ⑥紅;說明改回舊句 → ⑦紅。
    """
    print("t_drift_c4_code_review_r1")
    import os as _os, unicodedata as _ud
    root = _df_repo()
    v = root / _DR_VAULT
    RR = "governance/review-reports"
    nfd = "done-Café"
    _nh_file(root, f"{RR}/code-old-done/r1.md", "舊的\n")      # 早一個提交:只有計劃名對得上、code- 開頭
    _nh_file(root, f"{RR}/{nfd}/r1.md", "舊的\n")              # 早一個提交:只有計劃名對得上、NFD 寫法
    _nh_file(root, f"{RR}/zz-other/r1.md", "無關\n")
    _df_commit(root, "earlier")
    E = v / "Verification" / "E.md"
    E.write_text("---\ntype: verification\nstatus: pass\nvalid_under:\n  - 本工作樹(未提交);全套測試\nplan_refs:\n"
                 "  - \"[[Projects/Done_計劃]]\"\n---\n# E\n", encoding="utf-8")
    for d in ("aaa", "bbb", "ccc"):
        for f in ("r1.md", "r2.md", "snapshot.patch"):
            _nh_file(root, f"{RR}/{d}/{f}", f"{d} {f}\n")
    _df_commit(root, "feature with reports")
    first = _nh_git(root, "log", "--diff-filter=A", "--format=%H", "--", f"{_DR_VAULT}/Verification/E.md").stdout.split()[-1]
    shown = _nh_git(root, "show", "--name-only", "--format=", first).stdout
    check("①前置:E 第一次提交加了 3 個卷證目錄、每個 3 支檔(9 支);NFD 目錄在磁碟上照 NFD 存著",
          sum(1 for ln in shown.splitlines() if ln.startswith(f"{RR}/")) == 9
          and nfd in _os.listdir(root / RR) and not _ud.is_normalized("NFC", nfd), shown)
    rc, out = _df_fix(v, "Verification/E", "5", "--kind", "c4")
    rows = [ln.strip() for ln in out.splitlines() if ln.strip().startswith(f"{RR}/")]
    check("②同提交照目錄去重、剛好 3 個不印「可能含別的計劃的卷證」", rc == 0 and "可能含別的計劃的卷證" not in out
          and sum(1 for r in rows if r.endswith("(同提交)")) == 3, out)
    want = [f"{RR}/code-old-done(計劃名)", f"{RR}/aaa(同提交)", f"{RR}/bbb(同提交)", f"{RR}/ccc(同提交)", f"{RR}/{nfd}(計劃名)"]
    check("③code- 開頭對計劃名來源也排在其他前面", rows == want, "\n".join(map(ascii, rows)))
    check("④NFD 寫法的目錄照原名印(不換成 NFC)", f"{RR}/{nfd}(計劃名)" in rows
          and f"{RR}/{_ud.normalize('NFC', nfd)}(計劃名)" not in rows, "\n".join(map(ascii, rows)))
    m = _load_lumos_inproc()
    a, b = "code-Café", "code-Café"
    fake = "".join(f"{RR}/{x}/{f}\0" for x, f in ((a, "r1.md"), (b, "r1.md"), (b, "r2.md"), ("gone", "r1.md"))).encode()
    orig = m._nodehome_git
    m._nodehome_git = lambda _root, *_a: fake
    try:
        got = m._drift_c4_same_commit(str(root), "abc123", {b})
    finally:
        m._nodehome_git = orig
    check("⑤同提交:git 回兩種 NFC 等價的名字、磁碟上只有一個 → 只列磁碟上那一個(代碼審第二輪改裁,見 t_drift_c4_code_review_r2);不在的不列",
          got == [b], ascii(got))
    check("⑥證據頁範本的佔位字(<卷證>、<sha>)--reason 那側也認得", all(m._drift_placeholder_err(s, "x")
                                                                    for s in m._SET_COND_SLOTS[1:]), str(m._SET_COND_SLOTS))
    h = m.HELP_WHEN["drift fix"]
    check("⑦drift fix 的一行說明是現況:c3 可帶 --reason、c4 只列證據不寫檔", "--reason" in h and "c4 只列證據" in h
          and "不寫檔" in h and "換掉還沒提交的前提" not in h, h)


def t_drift_c4_code_review_r2():
    """[S1] 代碼審第二輪折入:c4 證據頁印的一律是現在真的存在的那個目錄名(磁碟上的實際名字);git 裡的名字只拿 NFC 鍵
    去對應現存目錄。一個現存目錄一行,兩種來源都有就標「兩者」;NFC 鍵對到多個現存目錄才每個都列(正確性 F2、外家否決 F3、
    邊界 F1)。目錄名裡的 Unicode 格式字元(方向控制、零寬)換成看得見的 \\uXXXX(資安 F3,只在這一處)。

    翻紅釘:同提交印 git 裡的名字 → ②⑤紅;兩種來源照原名對、不照現存目錄合併 → ②紅(macOS)、⑤紅;
    格式字元不換 → ③紅;NFC 鍵只取一個現存目錄 → ⑥紅。
    """
    print("t_drift_c4_code_review_r2")
    import os as _os, unicodedata as _ud
    root = _df_repo()
    v = root / _DR_VAULT
    RR = "governance/review-reports"
    nfd = "done-Café"
    cf = "done-\u202egnp​x"
    E = v / "Verification" / "E.md"
    E.write_text("---\ntype: verification\nstatus: pass\nvalid_under:\n  - 本工作樹(未提交);全套測試\nplan_refs:\n"
                 "  - \"[[Projects/Done_計劃]]\"\n---\n# E\n", encoding="utf-8")
    for d in (nfd, cf, "zzz"):
        _nh_file(root, f"{RR}/{d}/r1.md", "報告\n")
    _df_commit(root, "feature with reports")
    first = _nh_git(root, "log", "--diff-filter=A", "--format=%H", "--", f"{_DR_VAULT}/Verification/E.md").stdout.split()[-1]
    check("①前置:NFD 目錄與含格式字元的目錄在磁碟上照原樣存著、跟 E 同一個提交加進來", nfd in _os.listdir(root / RR)
          and cf in _os.listdir(root / RR) and not _ud.is_normalized("NFC", nfd)
          and _nh_git(root, "show", "--name-only", "--format=", first).stdout.count(f"{RR}/") >= 3, "")
    rc, out = _df_fix(v, "Verification/E", "5", "--kind", "c4")
    rows = [ln.strip() for ln in out.splitlines() if ln.strip().startswith(f"{RR}/")]
    names = [r[len(RR) + 1:r.rindex("(")] for r in rows]
    shown_cf = "done-\\u202egnp\\u200bx"
    check("②一個現存目錄一行:NFD 目錄兩種來源都有 → 一行「兩者」,印磁碟上的名字;每一條印出的路徑都精確存在(格式字元那條除外)",
          rc == 0 and rows.count(f"{RR}/{nfd}(兩者)") == 1 and len(rows) == 3
          and all(n in _os.listdir(root / RR) for n in names if n != shown_cf), "\n".join(map(ascii, rows)))
    check("③目錄名裡的方向控制、零寬字元換成看得見的 \\uXXXX,原字元不進終端", f"{RR}/{shown_cf}(兩者)" in rows
          and "\u202e" not in out and "​" not in out, "\n".join(map(ascii, rows)))
    m = _load_lumos_inproc()
    a, b = "code-Café", "code-Café"
    orig = m._nodehome_git
    try:
        m._nodehome_git = lambda _root, *_a: "".join(f"{RR}/{x}/{f}\0" for x, f in
                                                     ((a, "r1.md"), (b, "r1.md"), (b, "r2.md"), ("gone", "r1.md"))).encode()
        got = m._drift_c4_same_commit(str(root), "abc123", {b})
        m._nodehome_git = lambda _root, *_a: f"{RR}/{a}/r1.md\0".encode()
        got2 = m._drift_c4_same_commit(str(root), "abc123", {a, b, "other"})
    finally:
        m._nodehome_git = orig
    check("⑤git 裡是 NFC、磁碟上只有 NFD:列的是磁碟上那一個、只列一次;不在的不列", got == [b], ascii(got))
    check("⑥NFC 鍵對到兩個現存目錄(分正規化的檔案系統):兩個都列", sorted(got2) == sorted([a, b]), ascii(got2))


def t_drift_fix_c1_missing_tail_once():
    """[S3] 代碼審 r1(spec 對照 F2)折入:c1 一次找不到好幾種預告句時,名稱用「、」接,說明尾巴只印一次;
    settle 照舊逐句提醒(兩處仍走同一支 _guard_settle_missing_say)。

    翻紅釘:c1 改回每個名稱各接一整句 → ②紅;合併句的字樣跟單句不同 → ①紅。
    """
    print("t_drift_fix_c1_missing_tail_once")
    m = _load_lumos_inproc()
    tail = "——可能已經是轉正後的說法(不用改),或被手改過(看一下)"
    one = m._guard_settle_missing_say("X.md", ["test", "why"], say=False, one=True)
    check("①合併成一句:名稱照 _GUARD_PROSE_NAMES 用「、」接、尾巴一次;只缺一種時跟 settle 那句一字不差",
          one == [f"找不到摘要的 TEST 預告句、摘要的 WHY 預告句{tail}"]
          and m._guard_settle_missing_say("X.md", ["test"], say=False, one=True)
          == m._guard_settle_missing_say("X.md", ["test"], say=False)
          and m._guard_settle_missing_say("X.md", [], say=False, one=True) == [], str(one))
    root = _df_repo()
    v = root / _DR_VAULT
    V = v / "Verification"
    (V / "C.md").write_text(_dr_guard_text("pass", claim="大額退費要人工核可")
                            .replace("TEST:還沒有測試在守這條", "TEST:[2026-09-15] 預告已轉正,自己先改好的")
                            .replace("WHY:[2026-09-01]預告這條合約但還沒做:", "WHY:[2026-09-15]已轉正,原因是:"), encoding="utf-8")
    _df_commit(root, "cases", "2026-09-20")
    c1 = _df_find(v, "c1", "Verification/C.md")
    t = (V / "C.md").read_text(encoding="utf-8")
    check("②前置:C 是 c1、TEST 與 WHY 預告句都已經不在", c1 and "TEST:還沒有測試" not in t and "預告這條合約但還沒做" not in t, str(c1))
    rc, out = _df_fix(v, "Verification/C", str(min(f["line"] for f in c1)), "--kind", "c1", "--date", "2026-09-15")
    check("②c1:兩種都找不到時,結果訊息只接一次說明尾巴、兩個名稱都點到", rc == 0 and out.count(tail) == 1
          and "摘要的 TEST 預告句" in out and "摘要的 WHY 預告句" in out, out)


def t_set_conditions_blocks_placeholder_variants():
    """[S2] 代碼審 r1(邊界 F1)折入、第二輪改裁:lumos set 整欄改 valid_under/revalidate_when 時,佔位字的打錯變體也擋——
    只擋兩邊都有角括號的:全形角括號(＜卷證＞)、括號內多空白(< 卷證 >)、sha 大小寫(<SHA>)。少一邊角括號的
    (<卷證、卷證>20個、git-sha>)第二輪起不擋(外家否決 F2、正確性 F4、邊界 F4、資安 F2:正常內容被誤擋);
    佔位字後面還接別的字的(<卷證 目錄>、<sha 1>、<git-sha>)、一般角括號文字(Map<K,V>、<SHA-1>、List<sha256>)照收。

    翻紅釘:拿掉變體檢查 → ②紅;變體不要求閉括號 → ③紅;sha 不分大小寫拿掉 → ②<SHA> 紅;加回只剩閉括號那一支 → ③紅。
    """
    print("t_set_conditions_blocks_placeholder_variants")
    v = mkvault()
    write(v, "Verification/V.md", "type: verification\nstatus: pass\nvalid_under: 原本的前提\nrevalidate_when: 原本的回頭條件")
    p = v / "Verification" / "V.md"
    raw = p.read_bytes()
    bad = (("代碼審見 ＜卷證＞", "<卷證>"), ("代碼審見 < 卷證 >", "<卷證>"), ("代碼審見 <卷證＞", "<卷證>"),
           ("代碼審見 <\u3000卷證\u3000>", "<卷證>"), ("提交 <SHA>;代碼審見 x", "<sha>"), ("提交 <Sha >;x", "<sha>"),
           ("提交 ＜sha＞", "<sha>"), ("改成 ＜整項新內容>", "<整項新內容>"), ("改成 < 整項新內容 >", "<整項新內容>"))
    r0 = run(v, "set", "Verification/V", "valid_under", "好的一條")
    check("①前置:同一篇正常的值寫得進去(擋下不是因為別的原因)", r0.returncode == 0, r0.stdout + r0.stderr)
    write(v, "Verification/V.md", "type: verification\nstatus: pass\nvalid_under: 原本的前提\nrevalidate_when: 原本的回頭條件")
    raw = p.read_bytes()
    for key in ("valid_under", "revalidate_when"):
        for val, slot in bad:
            r = run(v, "set", "Verification/V", key, "好的一條", val)
            check(f"②{key} 值 {val!r}:佔位字的變體 → 回 2、點名是哪個佔位字、檔案不動", r.returncode == 2
                  and slot in r.stderr and "佔位字" in r.stderr and p.read_bytes() == raw, r.stdout + r.stderr)
            p.write_bytes(raw)   # 沒擋住時還原,免得一條紅牽連後面每一條
    ok = ("Map<K,V> 與 <src/lib> 照收;提交 <SHA-1> 與 List<sha256>、<shape>、<卷證目錄> 都不是佔位字;a < b 且 c > d;"
          "代碼審見 governance/review-reports/code-x 的卷證;sha 值 > 3;commitsha> 這種黏在英文字後面的;"
          "若卷證>20個就重驗;輸出 git-sha> 時重驗;提交 <git-sha> 之後;<卷證 目錄> 與 <sha 1>;a < sha;見 <卷證 那一段;<整項新內容")
    r = run(v, "set", "Verification/V", "valid_under", ok)
    check("③正文裡合法的角括號字樣照樣寫得進去", r.returncode == 0 and ok in p.read_text(encoding="utf-8"), r.stdout + r.stderr)


def t_drift_c4_lists_all_dirs():
    """[S1] 代碼審第三輪撤回第一輪加的「超過 20 個只列前 20 個 + 補充指令」:三輪長出四個新缺陷(指令少列加引號的目錄名、
    沒照現存名稱與格式字元處理、數量說法對不上、散檔那條測不到);長清單罕見,證據頁是人主動叫出來看的——回到全部列出。

    翻紅釘:加回上限 → ②紅;加回「另有 N 個」或補充指令 → ②紅。
    """
    print("t_drift_c4_lists_all_dirs")
    root = _df_repo()
    v = root / _DR_VAULT
    RR = "governance/review-reports"
    E = v / "Verification" / "E.md"
    E.write_text("---\ntype: verification\nstatus: pass\nvalid_under:\n  - 本工作樹(未提交);全套測試\nplan_refs:\n"
                 "  - \"[[Projects/Done_計劃]]\"\n---\n# E\n", encoding="utf-8")
    names = [f"bulk-{i:02d}" for i in range(23)]
    for d in names:
        _nh_file(root, f"{RR}/{d}/r1.md", f"{d}\n")
    _df_commit(root, "bulk import")
    check("①前置:E 第一次提交一起加了 23 個卷證目錄", len([d for d in (root / RR).iterdir() if d.is_dir()]) == 23
          and [f["line"] for f in _df_find(v, "c4", "Verification/E.md")] == [5], "")
    rc, out = _df_fix(v, "Verification/E", "5", "--kind", "c4")
    rows = [ln.strip() for ln in out.splitlines() if ln.strip().startswith(f"{RR}/")]
    check("②23 個全部列出(照原本的排序)、沒有「另有 N 個」也沒有補充指令", rc == 0
          and rows == [f"{RR}/{d}(同提交)" for d in names] and "另有" not in out and "git --literal-pathspecs" not in out, out)


def t_drift_c4_code_review_r3():
    """[S1] 代碼審第三輪折入:
    - git 裡的目錄名對現存目錄的比對鍵是 NFC 再 casefold:不分大小寫的檔案系統上磁碟名只差大小寫也對得上,印磁碟上的名字;
      鍵對到好幾個現存目錄(分大小寫的檔案系統)就都列(外家否決 F1、邊界 F2)。
    - 補分支測試(spec 對照 F4):有提交但 git 讀不到 → 回 None、證據頁印「同提交:查不到(git 失敗或沒有)」;
      git 成功但那個提交沒加卷證目錄 → 回空清單、不印那句。

    翻紅釘:比對鍵拿掉 casefold → ①②紅;git 失敗改回空清單 → ③紅;空清單也印查不到 → ④紅。
    """
    print("t_drift_c4_code_review_r3")
    import io, contextlib
    m = _load_lumos_inproc()
    RR = "governance/review-reports"
    orig = m._nodehome_git
    try:
        m._nodehome_git = lambda _root, *_a: f"{RR}/Code-Review/r1.md\0".encode()
        got = m._drift_c4_same_commit(".", "abc123", {"code-review", "other"})
        m._nodehome_git = lambda _root, *_a: f"{RR}/CODE-FOO/r1.md\0".encode()
        got2 = m._drift_c4_same_commit(".", "abc123", {"Code-Foo", "code-foo", "bar"})
        m._nodehome_git = lambda _root, *_a: None
        got3 = m._drift_c4_same_commit(".", "abc123", {"code-review"})
        m._nodehome_git = lambda _root, *_a: b"src/x.py\0"
        got4 = m._drift_c4_same_commit(".", "abc123", {"code-review"})
    finally:
        m._nodehome_git = orig
    check("①git 裡是 Code-Review、磁碟上是 code-review:對得上,印磁碟上的名字", got == ["code-review"], str(got))
    check("②鍵對到兩個現存目錄(分大小寫的檔案系統):兩個都列", sorted(got2) == ["Code-Foo", "code-foo"], str(got2))
    outs = []
    for same in (got3, got4):
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            m._drift_c4_print_dirs({"reports": [], "same": same})
        outs.append(buf.getvalue())
    check("③有提交但 git 讀不到:回 None、證據頁寫「同提交:查不到(git 失敗或沒有)」", got3 is None
          and "同提交:查不到(git 失敗或沒有)" in outs[0], str(got3) + outs[0])
    check("④git 成功但那個提交沒加卷證目錄:回空清單、不印「同提交:查不到」", got4 == [] and "同提交:查不到" not in outs[1],
          str(got4) + outs[1])


def t_set_conditions_blocks_drift_placeholders():
    """[S2] lumos set 整欄改 valid_under/revalidate_when,值裡有 <整項新內容>、<卷證> 或 <sha> 任一個 → 擋下、點名是哪一個、
    檔案不動;其他輸入(空值、多行、合法的角括號字樣)的行為與訊息跟改前一樣。

    翻紅釘:_SET_COND_SLOTS 改回只有 <整項新內容> → ②<卷證>、<sha> 紅;訊息不點名 → ②紅;<整項新內容> 的訊息改了 → ③紅。
    """
    print("t_set_conditions_blocks_drift_placeholders")
    v = mkvault()
    write(v, "Verification/V.md", "type: verification\nstatus: pass\nvalid_under: 原本的前提\nrevalidate_when: 原本的回頭條件")
    p = v / "Verification" / "V.md"
    raw = p.read_bytes()
    m = _load_lumos_inproc()
    check("①前置:三個佔位字都在同一份常數、預填指令用的是第一個", tuple(m._SET_COND_SLOTS) == ("<整項新內容>", "<卷證>", "<sha>")
          and m._SET_COND_SLOT == "<整項新內容>", str(getattr(m, "_SET_COND_SLOTS", None)))
    for key in ("valid_under", "revalidate_when"):
        for slot in ("<整項新內容>", "<卷證>", "<sha>"):
            r = run(v, "set", "Verification/V", key, "好的一條", f"提交 abc;代碼審見 {slot}")
            check(f"②{key} 值裡留著 {slot}:回 2、點名、檔案不動", r.returncode == 2 and f"還留著 {slot}(" in r.stderr
                  and p.read_bytes() == raw, r.stdout + r.stderr)
    r = run(v, "set", "Verification/V", "valid_under", "<整項新內容>")
    check("③<整項新內容> 的訊息跟改前一字不差", r.returncode == 2 and r.stderr.strip()
          == "擋下:值裡還留著 <整項新內容>(drift fix 證據頁的佔位字)——換成那一項改寫後的整句,檔案沒動", r.stderr)
    r = run(v, "set", "Verification/V", "valid_under", "提交 <sha>;代碼審見 <卷證>")
    check("③兩個一起留著:兩個都點名", r.returncode == 2 and "還留著 <卷證>、<sha>(" in r.stderr and p.read_bytes() == raw, r.stderr)
    r = run(v, "set", "Verification/V", "valid_under", "")
    check("④空值:照舊擋、訊息不變", r.returncode == 2 and "的每一條都不能是空的" in r.stderr and p.read_bytes() == raw, r.stderr)
    r = run(v, "set", "Verification/V", "valid_under", "第一行\n第二行")
    check("④多行:照舊擋、訊息不變", r.returncode == 2 and "一條條件只能一行" in r.stderr and p.read_bytes() == raw, r.stderr)
    r = run(v, "set", "Verification/V", "valid_under", "Map<K,V> 與 <src/lib> 照收;提交 <SHA-1> 大寫不是佔位字")
    check("⑤合法的角括號字樣照收", r.returncode == 0 and "Map<K,V> 與 <src/lib>" in p.read_text(encoding="utf-8"),
          r.stdout + r.stderr)


def t_drift_fix_c1_missing_message():
    """[S3] c1 與 guard settle 找不到某種預告句時,訊息講明「可能已經是轉正後的說法(不用改),或被手改過」;
    兩處走同一支 _guard_settle_missing_say、字樣相同、名稱不疊字。

    翻紅釘:c1 改回自己的「找不到…,沒改」→ ③紅;settle 改回舊提醒 → ②紅;字樣裡再疊一次「預告句」→ ①紅。
    """
    print("t_drift_fix_c1_missing_message")
    m = _load_lumos_inproc()
    tail = "——可能已經是轉正後的說法(不用改),或被手改過(看一下)"
    say = m._guard_settle_missing_say("X.md", list(m._GUARD_PROSE_NAMES), say=False)
    check("①每一種名稱:找不到<名稱>+同一句說明,名稱照 _GUARD_PROSE_NAMES、不疊字",
          say == [f"找不到{n}{tail}" for n in m._GUARD_PROSE_NAMES.values()]
          and not any("預告句預告句" in x or "預告句」預告句" in x for x in say), str(say))
    want = f"找不到摘要的 TEST 預告句{tail}"
    # ② settle:pending 轉正時 TEST 句被改過
    root = _df_repo()
    v = root / _DR_VAULT
    V = v / "Verification"
    (V / "S.md").write_text(_dr_guard_text("pending", claim="合約乙").replace(
        "TEST:還沒有測試在守這條", "TEST:[2026-09-15] 預告已轉正,自己先改好的"), encoding="utf-8")
    # ③ c1:已 pass、TEST 句早就是轉正後的說法,其他三句還在
    (V / "C.md").write_text(_dr_guard_text("pass", claim="大額退費要人工核可").replace(
        "TEST:還沒有測試在守這條", "TEST:[2026-09-15] 預告已轉正,自己先改好的"), encoding="utf-8")
    _df_commit(root, "cases", "2026-09-20")
    c1 = _df_find(v, "c1", "Verification/C.md")
    check("②③前置:S 沒有 TEST 預告句、C 是 c1", "TEST:還沒有測試" not in (V / "S.md").read_text(encoding="utf-8") and c1, str(c1))
    r = run(v, "guard", "settle", "Verification/S", "--test", "t_b")
    check("②settle:提醒用同一句", r.returncode == 0 and f"提醒:Verification/S.md 裡{want}" in r.stdout, r.stdout + r.stderr)
    rc, out = _df_fix(v, "Verification/C", str(min(f["line"] for f in c1)), "--kind", "c1", "--date", "2026-09-15")
    check("③c1:結果訊息接同一句(不再是「找不到…,沒改」)", rc == 0 and f";{want}" in out and "沒改" not in out, out)


def t_drift_fix_c3_reason():
    """[S4] drift fix --kind c3 帶 --reason:補的那一行最後接「;理由:<去頭尾空白的理由>」,三種寫法(pass+--by、其他+--by、
    沒 --by)都一樣;沒給照舊。理由的長度、單行、佔位字規則跟 c2 相同;改法提示帶 [--reason "…"]。

    翻紅釘:_DRIFT_FIX_ALLOWED["c3"] 拿掉 reason → ②紅(不收 --reason);理由長度上限拿掉 → ③超過 200 字紅;_drift_fix_c3_args 拿掉佔位字檢查 → ③佔位字紅;
    理由不去空白 → ②紅;只在其中一種寫法接 → ②另兩種紅。
    """
    print("t_drift_fix_c3_reason")
    import datetime
    today = datetime.date.today().isoformat()
    root = _df_repo()
    v = root / _DR_VAULT
    V = v / "Verification"
    ref = 'plan_refs:\n  - "[[Projects/Done_計劃]]"\ntags:\n  - type/verification\n  - status/pending'
    for n in ("A", "B", "C", "D"):
        write(v, f"Verification/{n}.md", "type: verification\nstatus: pending\n" + ref, body=f"# {n}\n內容\n")
    _df_commit(root, "c3 reason cases")
    check("①前置:四篇第 3 行都是 c3", all([f["line"] for f in _df_find(v, "c3", f"Verification/{n}.md")] == [3]
                                       for n in "ABCD"), "")
    raw = (V / "A.md").read_bytes()
    for bad, why in (("abc", "4 到 200"), ("第一行\n第二行", "4 到 200"), ("<為什麼算解決,附提交或測試>", "佔位字"),
                     ("見 <卷證> 那份", "佔位字"), ("長" * 201, "4 到 200")):
        rc, out = _df_fix(v, "Verification/A", "3", "--kind", "c3", "--status", "pass", "--reason", bad)
        check(f"③理由 {bad!r} 不合規:回 2({why})、不寫", rc == 2 and why in out and (V / "A.md").read_bytes() == raw, out)
    cases = (("A", ["--status", "pass", "--by", "Done_計劃"], "pass", ",由 [[Projects/Done_計劃]] 解決"),
             ("B", ["--status", "stale", "--by", "Systems/Pay"], "stale", ",參考 [[Systems/Pay]]"),
             ("C", ["--status", "abandoned"], "abandoned", ""))
    for n, args, st, mid in cases:
        rc, out = _df_fix(v, f"Verification/{n}", "3", "--kind", "c3", *args, "--reason", "  主線上已驗過,見 [[不存在的筆記]]  ")
        t = (V / f"{n}.md").read_text(encoding="utf-8")
        check(f"②{n}({st}):行尾接「;理由:<去空白的理由>」、理由裡的連結不驗", rc == 0
              and t.endswith(f"{today} 狀態改為 {st}(存量漂移 c3){mid};理由:主線上已驗過,見 [[不存在的筆記]]\n"), out + repr(t[-160:]))
    rc, out = _df_fix(v, "Verification/D", "3", "--kind", "c3", "--status", "superseded")
    check("④沒給理由照舊", rc == 0 and (V / "D.md").read_text(encoding="utf-8").endswith(
        f"{today} 狀態改為 superseded(存量漂移 c3)\n"), out)
    m = _load_lumos_inproc()
    check("⑤改法提示帶 [--reason \"…\"]", m._drift_fix_hint("c3", "Verification/V.md", 3)[0].endswith('[--reason "…"]'),
          m._drift_fix_hint("c3", "Verification/V.md", 3)[0])


def t_delguard_scans_vendored_files_in_consumer():
    """漂移修法補強 第 5 節已撤(代碼審第三輪,同一類第三次整類拿掉):刪除守衛不再跳過任何工具自裝檔——消費專案提交時
    scripts/lumos 刪掉的名稱照抽,治理事件 note 不帶 vendored-skip=。原因與可能的正確判法見
    Issues/刪除守衛在消費專案把工具更新刪掉的名稱當成專案的。

    翻紅釘:cmd_delguard_check 又傳跳過集合(不管哪一種判法)→ ②紅;note 又帶 vendored-skip= → ③紅。
    """
    print("t_delguard_scans_vendored_files_in_consumer")
    import subprocess as _sp, tempfile as _tf, json as _j
    m = _load_lumos_inproc()
    root = Path(_tf.mkdtemp(prefix="gctl-dgvend-"))
    (root / "docs" / "x-knowledge" / "Systems").mkdir(parents=True)
    (root / "docs" / "x-knowledge" / "Systems" / "a.md").write_text("---\nname: a\n---\n# a\n呼叫 zzVendoredOnlyFn。\n",
                                                                   encoding="utf-8")
    body = "def zzVendoredOnlyFn():\n    return 1\n"
    _nh_file(root, "scripts/lumos", body)
    _nh_file(root, ".lumos/vendored.json", _j.dumps({"version": 1, "files": {"scripts/lumos": m._vendored_digest(body.encode())}}))
    _nh_git(root, "init", "-q")
    _nh_git(root, "add", "-A")
    _nh_git(root, "-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "i")
    _nh_file(root, "scripts/lumos", "x = 1\n")                   # 像 lumos update:工具檔與安裝清單一起換成新版
    _nh_file(root, ".lumos/vendored.json", _j.dumps({"version": 1, "files": {"scripts/lumos": m._vendored_digest(b"x = 1\n")}}))
    _nh_git(root, "add", "-A")
    diff = _nh_git(root, "diff", "--cached").stdout
    check("①前置:消費專案(不是工具鏈本身)、這次提交從原封不動的 scripts/lumos 刪掉 zzVendoredOnlyFn",
          "-def zzVendoredOnlyFn" in diff and not m._is_toolchain_repo(str(root)) and "scripts/lumos" in m._VENDORED_ALL, diff[:300])
    r = _sp.run([sys.executable, GRAPHCTL, "delguard", "--staged", "--json"], cwd=str(root), capture_output=True, text=True,
                timeout=120)
    try:
        out = _j.loads(r.stdout.strip().splitlines()[-1])
    except Exception:
        out = {}
    toks = {t for h in out.get("hits", []) for t in h["tokens"]}
    check("②工具檔刪掉的名稱照抽(不跳過工具自裝檔)", "zzVendoredOnlyFn" in toks, r.stdout + r.stderr)
    rows = [x for x in _gov_events_all(root / "docs") if x.get("gate") == "delguard"]   # ok 寫本機帳
    check("③治理事件 note 不帶 vendored-skip=", rows and "vendored-skip" not in rows[-1].get("note", ""), str(rows))


def t_doctor_revisit_marks_closed_issues():
    """[S6] doctor E5 列出到期回頭條件時,來源是狀態為 Issue 結案值的 Issue,那一行標「這篇 Issue 已結案」,照樣列、照樣計數;
    其他類型、Issue 用了非結案值時不標;E5 與結案列出用同一支判定(_revisit_lines)。

    翻紅釘:拿掉 E5 的 _closed5 → ①紅;_closed5 不看類型 → ②計劃那行紅;改成看 QUERY_CLOSED_STATUSES 以外的字 → ②紅;
    E5 改回自己的逐行迴圈、不走 _revisit_lines → ③紅。
    """
    print("t_doctor_revisit_marks_closed_issues")
    import contextlib, io
    v = mkvault()
    (v / "Issues").mkdir()
    write(v, "Issues/已結案甲.md", "type: issue\nstatus: done", body="# 甲\nREVISIT:2020-01-01 最老的一條\n")
    write(v, "Issues/還開著乙.md", "type: issue\nstatus: open", body="# 乙\nREVISIT:2020-01-02 開著的\n")
    write(v, "Projects/收尾丙_計劃.md", "type: project\nstatus: done", body="# 丙\nREVISIT:2020-01-03 計劃留的撤除條件\n")
    write(v, "Issues/怪值丁.md", "type: issue\nstatus: fixed", body="# 丁\nREVISIT:2020-01-04 非結案值\n")
    r = run(v, "doctor", "--verbose")
    e5 = r.stdout.split("[E5]")[1].split("\n[")[0] if "[E5]" in r.stdout else ""
    row = lambda s: next((x for x in e5.split("\n") if s in x), "")
    check("①已結案的 Issue:那一行標「這篇 Issue 已結案」,照樣列", "(這篇 Issue 已結案)" in row("最老的一條"), e5)
    check("②開著的 Issue、已收尾的計劃、非結案值的 Issue 不標", row("開著的") and "已結案" not in row("開著的")
          and row("計劃留的撤除條件") and "已結案" not in row("計劃留的撤除條件")
          and row("非結案值") and "已結案" not in row("非結案值"), e5)
    check("②照樣計數(四件都算)", "4 件回訪到期" in r.stdout, e5)
    m = _load_lumos_inproc()
    seen = []
    orig = m._revisit_lines

    def spy(text):
        seen.append(text)
        return orig(text)
    m._revisit_lines = spy
    try:
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            m.run_doctor(m.Env(v), False, False)
        n_doc = len(seen)
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            m._closing_revisits(m.Env(v), "Issues/已結案甲.md", "done")
    finally:
        m._revisit_lines = orig
    check("③E5 與結案列出用同一支判定(_revisit_lines)", n_doc >= 4 and len(seen) == n_doc + 1 and "最老的一條" in buf.getvalue(),
          f"{n_doc} {len(seen)} {buf.getvalue()}")


def _rvb_vault(src_body):
    v = mkvault()
    write(v, "Verification/X.md", "type: verification\nstatus: pass\nrevalidate_when: 產圖腳本改變時", body="# X\n")
    write(v, "Projects/P.md", "type: project\nstatus: doing", body="# P\n" + src_body + "\n")
    write(v, "Projects/Q.md", "type: project\nstatus: doing", body="# Q\n無關\n")
    return v


def t_set_revalidate_when_lists_backrefs():
    """[B5 S1] lumos set 改了某篇的 revalidate_when:列出連到它、同一句講到 revalidate_when 的句子
    (來源篇、行號、原句)與改完之後的事件清單;沒有這種句子不多印;不擋、不改別篇(rtb 第三次比對回傳第 10 項)。
    翻紅釘:拿掉 main 裡 set 之後的呼叫 → ①紅;印改之前的值 → ②紅。append/remove 本來就不收 revalidate_when(只能 set 整欄換)。"""
    print("t_set_revalidate_when_lists_backrefs")
    src = "Phase 12 頁面上主線時由 [[Verification/X]] 的 revalidate_when 觸發重驗。"
    v = _rvb_vault(src)
    before = (v / "Projects" / "P.md").read_text(encoding="utf-8")
    r = run(v, "set", "Verification/X", "revalidate_when", "字型改變時")
    lines = before.split("\n")
    no = next(i + 1 for i, ln in enumerate(lines) if "觸發重驗" in ln)
    check("①set 之後列出引用它的句子(來源篇與行號、原句)", r.returncode == 0 and f"Projects/P.md:{no}" in r.stdout and "觸發重驗" in r.stdout, r.stdout + r.stderr)
    check("②印出改完之後的事件清單", "字型改變時" in r.stdout and r.stdout.find("字型改變時") >= 0, r.stdout)
    check("①不改別篇", (v / "Projects" / "P.md").read_text(encoding="utf-8") == before, "")
    r = run(v, "set", "Verification/X", "revalidate_when", "README 文案改變時", "字型改變時")
    check("③整欄換成多個值也列,並印出多個事件", r.returncode == 0 and "Projects/P.md:" in r.stdout and "README 文案改變時" in r.stdout, r.stdout + r.stderr)
    # 代碼審 r1 正確性席 F1:同一行兩句都指向同一篇,兩句都要列(原本每行取到一句就停)
    v3 = _rvb_vault("甲 [[Verification/X]] 的 revalidate_when 第一;乙 [[Verification/X]] 的 revalidate_when 第二。")
    r = run(v3, "set", "Verification/X", "revalidate_when", "字型改變時")
    check("⑥同一行兩句指向同一篇:兩句都列", r.returncode == 0 and "第一" in r.stdout and "第二" in r.stdout and "有 2 句" in r.stdout, r.stdout)
    # 代碼審 r2 正確性席 F1:同一句裡兩組完整配對,這一句只列一次(r1 拿掉取到就停之後會列兩次、把句數灌水)
    v5 = _rvb_vault("[[Verification/X]] 的 revalidate_when 與 [[Verification/X]] 的 revalidate_when 同一句。")
    r = run(v5, "set", "Verification/X", "revalidate_when", "字型改變時")
    check("⑨同一句兩組配對:只列一次", r.returncode == 0 and r.stdout.count("Projects/P.md:") == 1 and "有 1 句" in r.stdout, r.stdout)
    # 代碼審 r1 架構對齊席 A1:同 _drift_print_backrefs 最多列 20 句,其餘說還有幾句
    v4 = _rvb_vault("\n".join(f"第{i}行由 [[Verification/X]] 的 revalidate_when 觸發。" for i in range(25)))
    r = run(v4, "set", "Verification/X", "revalidate_when", "字型改變時")
    check("⑦超過 20 句只列 20 句,其餘說還有 5 句", r.returncode == 0 and r.stdout.count("Projects/P.md:") == 20 and "還有 5 句" in r.stdout, r.stdout[-300:])
    # 代碼審 r1 架構對齊席 A2:列出出錯不改回傳碼,stderr 說寫入照樣完成(同 _drift_print_backrefs 的 fail-open)
    m = _load_lumos_inproc()
    import io as _io2
    from unittest.mock import patch as _patch2
    err = _io2.StringIO()
    with _patch2.object(m, "_revalidate_backref_lines", side_effect=ValueError("壞掉")), _patch2.object(m.sys, "stderr", err):
        raised = None
        try:
            m._print_revalidate_backrefs(None, "Verification/X.md")
        except Exception as e:     # noqa: BLE001 — 要的就是「不丟例外」
            raised = e
    check("⑧列出出錯不丟例外,stderr 說寫入照樣完成", raised is None and "寫入照樣完成" in err.getvalue(), repr(raised) + err.getvalue())
    v2 = _rvb_vault("沒有引用")
    r = run(v2, "set", "Verification/X", "revalidate_when", "字型改變時")
    check("⑤沒有引用句:不多印", r.returncode == 0 and "句連到這篇" not in r.stdout, r.stdout)


def t_set_revalidate_when_backrefs_excluded():
    """[B5 S2] 不列的情形:連結包在行內程式碼裡、整句在程式碼區裡、連到別篇、revalidate_when 跟連結隔著句尾、改的是別的欄位。
    每一格都在同一篇另放一句對照句(沒有排除情形),對照句要列——證明「不列」不是因為根本什麼都沒印。"""
    print("t_set_revalidate_when_backrefs_excluded")
    ctl = "\n對照:由 [[Verification/X]] 的 revalidate_when 觸發。"
    for desc, body in (("①連結在行內程式碼裡", "例如 `[[Verification/X]]` 的 revalidate_when 觸發。"),
                       ("②整句在程式碼區裡", "```\n由 [[Verification/X]] 的 revalidate_when 觸發\n```"),
                       ("③連到別篇", "由 [[Projects/Q]] 的 revalidate_when 觸發。"),
                       ("④隔著句尾", "見 [[Verification/X]]。另外 revalidate_when 要寫清楚。")):
        v = _rvb_vault(body + ctl)
        lines = (v / "Projects" / "P.md").read_text(encoding="utf-8").split("\n")
        bad = [i + 1 for i, ln in enumerate(lines) if "對照" not in ln and ("revalidate_when" in ln or "[[" in ln)]
        ok_no = next(i + 1 for i, ln in enumerate(lines) if "對照" in ln)
        r = run(v, "set", "Verification/X", "revalidate_when", "字型改變時")
        check(f"{desc}:不列,對照句照列", r.returncode == 0 and f"Projects/P.md:{ok_no}" in r.stdout
              and not any(f"Projects/P.md:{n} " in r.stdout or f"Projects/P.md:{n}\n" in r.stdout for n in bad), r.stdout)
    v = _rvb_vault("由 [[Verification/X]] 的 revalidate_when 觸發。")
    r = run(v, "set", "Verification/X", "status", "pass")
    check("⑤改的是別的欄位:不列", r.returncode == 0 and "Projects/P.md:" not in r.stdout, r.stdout)


def t_set_issue_closed_lists_revisits():
    """[S7] lumos set 或 drift fix --kind c2 --close 把 Issue 改成結案值:列出它全部的回頭條件行(程式碼區與行內程式碼裡的不算),
    不擋不改;行號用寫完之後的內容算。

    翻紅釘:拿掉 main 裡 set 之後的 _closing_revisits → ①紅;只列到期的 → ①未來那條紅;不剝程式碼區 → ②紅;
    不看類型 → ③紅;c2 --close 不呼叫 → ④紅;行號用改之前的內容算 → ④行號紅。
    """
    print("t_set_issue_closed_lists_revisits")
    v = mkvault()
    (v / "Issues").mkdir()
    body = ("# I\nREVISIT:2099-01-01 未來的\n- REVISIT:2020-01-01 過期的\n```\nREVISIT:2020-01-01 碼區裡的\n```\n"
            "`REVISIT:2020-01-01 行內程式碼`\nREVISIT:[when-file:src/x.py][by:2099-01-01] 條件式\n")
    write(v, "Issues/I.md", "type: issue\nstatus: open", body=body)
    write(v, "Projects/P.md", "type: project\nstatus: doing", body="# P\nREVISIT:2099-01-01 計劃的\n")
    raw = (v / "Issues" / "I.md").read_text(encoding="utf-8")
    r = run(v, "set", "Issues/I", "status", "doing")
    check("①前置:改成非結案值不列", r.returncode == 0 and "回頭條件" not in r.stdout, r.stdout)
    r = run(v, "set", "Issues/I", "status", "done")
    lines = (v / "Issues" / "I.md").read_text(encoding="utf-8").split("\n")
    want = [i + 1 for i, l in enumerate(lines) if ("未來的" in l or "過期的" in l or "條件式" in l)]
    check("①改成結案值:列出全部回頭條件(含未到期、條件式),行號對", r.returncode == 0 and "還留著 3 行回頭條件" in r.stdout
          and all(f"Issues/I.md:{n}" in r.stdout for n in want), r.stdout)
    check("②程式碼區與行內程式碼裡的不算", "碼區裡的" not in r.stdout and "行內程式碼" not in r.stdout, r.stdout)
    check("①不擋不改:除了 status 其他一字不動", (v / "Issues" / "I.md").read_text(encoding="utf-8")
          == raw.replace("status: open", "status: done"), "")
    r = run(v, "set", "Projects/P", "status", "done")
    check("③不是 Issue 不列", r.returncode == 0 and "還留著" not in r.stdout, r.stdout)
    root = _df_repo()
    dv = root / _DR_VAULT
    _nh_file(root, f"{_DR_VAULT}/Issues/C.md", "---\ntype: issue\nstatus: open\n---\n# C\n第一段 [[Projects/Done_計劃]]\n"
             "REVISIT:2099-01-01 結案後要改的\n")
    _df_commit(root, "c")
    rc, out = _df_fix(dv, "Issues/C", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "修好了,提交 abc",
                      "--keep-revisits", "結案後還要回頭確認一次")
    cl = (dv / "Issues" / "C.md").read_text(encoding="utf-8").split("\n")
    n = next(i + 1 for i, l in enumerate(cl) if "結案後要改的" in l)
    check("④drift fix c2 --close 也列,行號是加了橫幅之後的", rc == 0 and f"Issues/C.md:{n}" in out and n == 10, out)


def _c6_ln(path, marker):
    """那篇裡第一個含 marker 的行號(1 起算);找不到回 0。"""
    for i, l in enumerate(path.read_text(encoding="utf-8").split("\n"), 1):
        if marker in l:
            return i
    return 0


def t_drift_c6_detects_pending_clause_to_settled_note():
    """[S1] 未收尾的筆記有一行在同一子句裡寫了待定詞、又連到已收尾的筆記 → c6(related 是那篇);
    被 。或 —— 隔開、已有「(已裁定:」、在程式碼圍欄裡、來源本身已收尾、只寫「待辦」、連到未收尾的 → 不列。

    翻紅釘:不切子句 → 乙丙紅;詞表收「待辦」→ 戊紅;不剝程式碼圍欄 → 庚紅;不看來源狀態 → Old 紅;
    剝行內程式碼 → 辛([todo] 在行內程式碼裡)紅;不看 summary → 摘要那行紅;切點漏全形分號 → 子紅(代碼審 r1 正確性席);
    單行 summary 略過 → ④紅;doctor 漂移段不列 c6 → ⑤紅;全形引號裡只是在提這個詞也算 → 丑紅(上線自用時抓到的誤報)。
    """
    print("t_drift_c6_detects_pending_clause_to_settled_note")
    root = _df_repo()
    v = root / _DR_VAULT
    _nh_file(root, f"{_DR_VAULT}/Issues/Res.md", "---\ntype: issue\nstatus: resolved\n---\n# Res\n已修\n")
    _nh_file(root, f"{_DR_VAULT}/Projects/Open_計劃.md", "---\ntype: project\nstatus: doing\n---\n# Open\nx\n")
    live = _nh_file(root, f"{_DR_VAULT}/Projects/Live_計劃.md",
                    "---\ntype: project\nstatus: doing\nsummary: |-\n  KEY:摘要那行,等 [[Projects/Done_計劃]] 待裁定\n---\n# Live\n"
                    "甲 排隊中,等 [[Projects/Done_計劃]] 落地後才執行\n"
                    "乙 [[Projects/Done_計劃]] 已上線。這邊還沒做\n"
                    "丙 等 [[Projects/Done_計劃]]——之後再排隊中\n"
                    "丁 待裁定 [[Projects/Done_計劃]](已裁定:2026-10-01 好,見 [[Projects/Done_計劃]])\n"
                    "戊 連鎖待辦單 [[Projects/Done_計劃]]\n"
                    "己 還沒修 [[Issues/Res]]\n"
                    "壬 待裁定 [[Projects/Open_計劃]]\n"
                    "```\n庚 待裁定 [[Projects/Done_計劃]]\n```\n"
                    "- [[Projects/Done_計劃]] `[todo]` — 辛 等評測尺\n"
                    "子 [[Projects/Done_計劃]] 已上線；這邊還沒做\n"
                    "丑 這個檢查認「待裁定」『排隊中』這類詞,見 [[Projects/Done_計劃]]\n")
    _nh_file(root, f"{_DR_VAULT}/Projects/Old_計劃.md", "---\ntype: project\nstatus: done\n---\n# Old\n待裁定 [[Projects/Done_計劃]]\n")
    one = _nh_file(root, f"{_DR_VAULT}/Projects/One_計劃.md", "---\ntype: project\nstatus: doing\n"
                   "summary: KEY:單行摘要,等 [[Projects/Done_計劃]] 待裁定\n---\n# One\nx\n")
    _nh_file(root, f"{_DR_VAULT}/Projects/Cm_計劃.md", "---\ntype: project\nstatus: doing\n"
             "summary: # 只是註解 待裁定 [[Projects/Done_計劃]]\n---\n# Cm\nx\n")
    _df_commit(root, "c6 cases")
    fs = _df_find(v, "c6", "Projects/Live_計劃.md")
    got = sorted(f["line"] for f in fs) if isinstance(fs, list) else fs
    want = sorted(_c6_ln(live, m) for m in ("摘要那行", "甲 ", "己 ", "辛 "))
    check("①同一子句有待定詞+連到已收尾的:摘要、甲、己、辛列出,乙丙丁戊庚壬子丑不列(子是全形分號隔開、丑是引號裡在提這個詞)", got == want,
          f"got={got} want={want}")
    check("④summary 只有註解那一行不算", _df_find(v, "c6", "Projects/Cm_計劃.md") == [], str(_df_find(v, "c6", "Projects/Cm_計劃.md")))
    check("④summary 寫成單行值:那一行也看", [f["line"] for f in _df_find(v, "c6", "Projects/One_計劃.md")] == [_c6_ln(one, "單行摘要")],
          str(_df_find(v, "c6", "Projects/One_計劃.md")))
    r = run(v, "doctor", "--verbose")
    check("⑤doctor 的漂移段列 c6", "[c6]" in r.stdout, r.stdout[-1500:])
    rel = {f["line"]: f.get("related") for f in fs} if isinstance(fs, list) else {}
    check("②related 是那一行命中的已收尾目標", rel.get(_c6_ln(live, "己 ")) == ["Issues/Res.md"]
          and rel.get(_c6_ln(live, "甲 ")) == ["Projects/Done_計劃.md"], str(rel))
    check("③來源本身已收尾的不列", _df_find(v, "c6", "Projects/Old_計劃.md") == [], "")


def t_drift_c6_ignores_link_title_words():
    """[c6 不看連結標題 S1] 連到標題含待定詞(「還沒做」)的已收尾筆記、連結外沒寫待定詞 → 不列;連結外寫了 → 照列;
    別名裡的待定詞也不算(2026-10-06 rtb 盤點 1-1 的兩條誤報)。翻紅釘:判待定詞不遮連結 → ①③紅。"""
    print("t_drift_c6_ignores_link_title_words")
    root = _df_repo()
    v = root / _DR_VAULT
    _nh_file(root, f"{_DR_VAULT}/Issues/收據還沒做.md", "---\ntype: issue\nstatus: resolved\n---\n# 收據還沒做\n不做了\n")
    live = _nh_file(root, f"{_DR_VAULT}/Projects/Moc_計劃.md",
                    "---\ntype: project\nstatus: doing\n---\n# Moc\n"
                    "寅 收據不做、已結案,見 [[Issues/收據還沒做]]\n"
                    "卯 收據這邊還沒做,見 [[Issues/收據還沒做]]\n"
                    "辰 見 [[Issues/收據還沒做|那件還沒做的事]]\n")
    _df_commit(root, "c6 link title")
    fs = _df_find(v, "c6", "Projects/Moc_計劃.md")
    got = sorted(f["line"] for f in fs) if isinstance(fs, list) else fs
    check("①連結標題裡的「還沒做」不算:寅不列", isinstance(got, list) and _c6_ln(live, "寅 ") not in got, str(fs))
    check("②連結外真的寫了「還沒做」:卯照列", isinstance(got, list) and _c6_ln(live, "卯 ") in got, str(fs))
    check("③別名裡的「還沒做」也不算:辰不列", isinstance(got, list) and _c6_ln(live, "辰 ") not in got, str(fs))


def t_drift_fix_c6_appends_settled_bracket():
    """[S2] drift fix --kind c6 --settled:待定子句結尾補「(已裁定:日期 結論,見 [[目標]])」、那行不再被列、修復帳 kind=c6;
    兩個連結沒給 --by 回 2;表格行、沒有待定子句的行回 2;擋下都不寫檔。

    翻紅釘:不要求 --by → ②紅;不擋表格行 → ③紅;括號沒帶連結 → ①紅;不寫修復帳 → ①帳那格紅;一律補在行尾 → ⑤紅;
    已裁定括號整行算處理 → ⑥紅;切點漏全形分號 → ⑦紅(代碼審 r1 正確性席);括號內容參與子句判斷 → ⑧紅;
    同目標兩個子句照補 → ⑨卡在「沒處理到」;不驗結論括號配對 → ⑩紅;單行 summary 照補 → ⑪紅(代碼審 r2 正確性席);
    補進行內程式碼中間不擋 → ⑫紅(代碼審 r3 正確性席;⑩原本對已補過的行下指令,拿掉配對檢查也綠,改成對一行還是 c6 的)。
    """
    print("t_drift_fix_c6_appends_settled_bracket")
    import datetime
    today = datetime.date.today().isoformat()
    root = _df_repo()
    v = root / _DR_VAULT
    _nh_file(root, f"{_DR_VAULT}/Issues/Res.md", "---\ntype: issue\nstatus: resolved\n---\n# Res\n已修\n")
    p = _nh_file(root, f"{_DR_VAULT}/Projects/Live_計劃.md",
                 "---\ntype: project\nstatus: doing\n---\n# Live\n"
                 "甲 排隊中,等 [[Projects/Done_計劃]] 落地\n"
                 "乙 待裁定 [[Projects/Done_計劃]] 與 [[Issues/Res]]\n"
                 "| 丙 待裁定 | [[Projects/Done_計劃]] |\n"
                 "丁 普通的一行 [[Projects/Done_計劃]]\n"
                 "戊 排隊中,等 [[Projects/Done_計劃]] 落地後才執行(之前裁的)——後面還有很長的說明\n"
                 "己 待裁定 [[Projects/Done_計劃]];還沒做 [[Issues/Res]]\n"
                 "庚 排隊中,等 [[Projects/Done_計劃]] 落地；後面是別的事\n"
                 "辛 待裁定 [[Projects/Done_計劃]] 落地;還沒做 [[Issues/Res]]\n"
                 "壬 待裁定 [[Projects/Done_計劃]];還沒做 [[Projects/Done_計劃]] 的另一半\n"
                 "癸 待裁定 [[Projects/Done_計劃]] 見 `a；b` 後\n"
                 "子 待裁定 [[Projects/Done_計劃]]\n")
    one = _nh_file(root, f"{_DR_VAULT}/Projects/One_計劃.md", "---\ntype: project\nstatus: doing\n"
                   "summary: \"KEY:單行 待裁定 [[Projects/Done_計劃]]\"\n---\n# One\nx\n")
    _df_commit(root, "c6 fix cases")
    la, lb, lc, ld, le, lf, lg, lh, li, lj, lk = (_c6_ln(p, m) for m in ("甲 ", "乙 ", "丙 ", "丁 ", "戊 ", "己 ", "庚 ", "辛 ", "壬 ",
                                                                         "癸 ", "子 "))
    raw = p.read_bytes()
    rc, out = _df_fix(v, "Projects/Live_計劃", str(lb), "--kind", "c6", "--settled", "兩邊都做完了")
    check("②兩個連結沒給 --by:回 2、列出候選、不寫檔", rc == 2 and "--by" in out and p.read_bytes() == raw, out)
    rc, out = _df_fix(v, "Projects/Live_計劃", str(lc), "--kind", "c6", "--settled", "這邊已經做完了")
    check("③表格行:回 2、不寫檔", rc == 2 and "表格" in out and p.read_bytes() == raw, out)
    rc, out = _df_fix(v, "Projects/Live_計劃", str(ld), "--kind", "c6", "--settled", "這邊已經做完了")
    check("③沒有待定子句的行:回 2、不寫檔", rc == 2 and "不是 c6" in out and p.read_bytes() == raw, out)
    rc, out = _df_fix(v, "Projects/Live_計劃", str(la), "--kind", "c6", "--settled", "已落地,開始執行")
    line = p.read_text(encoding="utf-8").split("\n")[la - 1]
    check("①待定子句在行尾:括號補在行尾(帶連結)", rc == 0 and line == f"甲 排隊中,等 [[Projects/Done_計劃]] 落地"
          f"(已裁定:{today} 已落地,開始執行,見 [[Projects/Done_計劃]])", out + line)
    check("①那一行不再被列成 c6", la not in [f["line"] for f in _df_find(v, "c6", "Projects/Live_計劃.md")], "")
    rows = _df_rows(root)
    check("①修復帳多一行 kind=c6", rows and rows[-1]["kind"] == "c6" and rows[-1]["path"].endswith("Projects/Live_計劃.md"), str(rows[-1:]))
    rc, out = _df_fix(v, "Projects/Live_計劃", str(lb), "--kind", "c6", "--settled", "上游已經修好", "--by", "Issues/Res",
                      "--date", "2026-10-01")
    line = p.read_text(encoding="utf-8").split("\n")[lb - 1]
    check("④給了 --by 與 --date:括號用那篇與那天", rc == 0 and line.endswith("(已裁定:2026-10-01 上游已經修好,見 [[Issues/Res]])"), out + line)
    rc, out = _df_fix(v, "Projects/Live_計劃", str(le), "--kind", "c6", "--settled", "已經落地了", "--date", "2026-10-02")
    line = p.read_text(encoding="utf-8").split("\n")[le - 1]
    check("⑤待定子句後面還有 —— 接的說明:括號補在 —— 之前,不跑到行尾", rc == 0 and line == "戊 排隊中,等 [[Projects/Done_計劃]] 落地後才執行(之前裁的)"
          "(已裁定:2026-10-02 已經落地了,見 [[Projects/Done_計劃]])——後面還有很長的說明", out + line)
    rc, out = _df_fix(v, "Projects/Live_計劃", str(lf), "--kind", "c6", "--settled", "已經決定好了", "--by", "Projects/Done_計劃")
    left = [f for f in _df_find(v, "c6", "Projects/Live_計劃.md") if f["line"] == lf]
    check("⑥同一行兩個待定子句:補了一個,另一個(連到 Res)照樣列", rc == 0 and len(left) == 1
          and left[0].get("related") == ["Issues/Res.md"], out + str(left))
    rc, out = _df_fix(v, "Projects/Live_計劃", str(lg), "--kind", "c6", "--settled", "已經落地了", "--date", "2026-10-03")
    line = p.read_text(encoding="utf-8").split("\n")[lg - 1]
    check("⑦全形分號也是子句切點:括號補在「；」之前", rc == 0 and line == "庚 排隊中,等 [[Projects/Done_計劃]] 落地"
          "(已裁定:2026-10-03 已經落地了,見 [[Projects/Done_計劃]])；後面是別的事", out + line)
    rc, out = _df_fix(v, "Projects/Live_計劃", str(lh), "--kind", "c6", "--settled", "先做A(該案裁定 d2)——其餘；還沒做",
                      "--by", "Projects/Done_計劃")
    left = [f for f in _df_find(v, "c6", "Projects/Live_計劃.md") if f["line"] == lh]
    check("⑧結論裡有分號、——、待定詞與巢狀括號:括號整塊不參與判斷,修法成功、後面那個待定子句照列",
          rc == 0 and len(left) == 1 and left[0].get("related") == ["Issues/Res.md"], out + str(left))
    raw = p.read_bytes()
    rc, out = _df_fix(v, "Projects/Live_計劃", str(li), "--kind", "c6", "--settled", "兩半都做完了")
    check("⑨同一行兩個待定子句連到同一篇:回 2、不寫檔,請人手改", rc == 2 and "手動改" in out and p.read_bytes() == raw, out)
    rc, out = _df_fix(v, "Projects/Live_計劃", str(lk), "--kind", "c6", "--settled", "括號(沒有收尾")
    check("⑩結論括號沒配對(那一行本身是 c6):回 2、講要成對", rc == 2 and "要成對" in out and p.read_bytes() == raw, out)
    rc, out = _df_fix(v, "Projects/Live_計劃", str(lj), "--kind", "c6", "--settled", "已經決定好了")
    check("⑫補的位置落在行內程式碼裡:回 2、不寫檔,請人手改", rc == 2 and "行內程式碼" in out and p.read_bytes() == raw, out)
    oraw = one.read_bytes()
    rc, out = _df_fix(v, "Projects/One_計劃", str(_c6_ln(one, "單行")), "--kind", "c6", "--settled", "已經好了呢")
    check("⑪單行 summary(可能有引號):回 2、不寫檔,請人手改", rc == 2 and "手動改" in out and one.read_bytes() == oraw, out)


def t_drift_check_lists_c6_and_ack_binds_related():
    """[S3] 推送讓 c6 的連結目標收尾 → drift check 只列出、不因 c6 擋;表態後又有另一個目標收尾 → 重新列出。

    翻紅釘:c6 進 must → ①rc 紅;c6 不在綁清單的種類 → ③紅(舊表態永久豁免)。
    """
    print("t_drift_check_lists_c6_and_ack_binds_related")
    root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
    v = root / _DR_VAULT
    _nh_node(root, "Other_計劃", typ="project", folder="Projects", resp=None, summary="KEY:o")
    live = _nh_file(root, f"{_DR_VAULT}/Projects/Live_計劃.md", "---\ntype: project\nstatus: doing\n---\n# Live\n"
                    "待裁定 [[Projects/退款_計劃]] 與 [[Projects/Other_計劃]]\n")
    _nh_commit(root, "base")
    base = _na_head(root)
    for name in ("退款_計劃",):
        q = v / "Projects" / f"{name}.md"
        q.write_text(q.read_text(encoding="utf-8").replace("status: doing", "status: done").replace("status/doing", "status/done"),
                     encoding="utf-8")
    _nh_commit(root, "收尾退款")
    rc, out = _dr(root, "check", "--diff", f"{base}..HEAD")
    check("①c6 只列出、不擋", rc == 0 and "只列出" in out and "Projects/Live_計劃.md" in out and "c6" in out, out)
    ln = _c6_ln(live, "待裁定")
    r = run(v, "drift", "ack", "Projects/Live_計劃", str(ln), "--kind", "c6", "--reason", "這句是當時的紀錄,照留")
    _nh_commit(root, "ack")
    left = [f for f in _df_find(v, "c6", "Projects/Live_計劃.md") if not f.get("acked")]
    check("②表態之後 scan 不再列成要處理", r.returncode == 0 and left == [], r.stdout + r.stderr + str(left))
    q = v / "Projects" / "Other_計劃.md"
    q.write_text(q.read_text(encoding="utf-8").replace("status: doing", "status: done").replace("status/doing", "status/done"),
                 encoding="utf-8")
    _nh_commit(root, "收尾 Other")
    fs = [f for f in _df_find(v, "c6", "Projects/Live_計劃.md") if not f.get("acked")]
    check("③又有一個目標收尾:重新列出,related 兩篇", len(fs) == 1
          and fs[0].get("related") == ["Projects/Other_計劃.md", "Projects/退款_計劃.md"], str(fs))


def t_settle_backrefs_listed_after_close_and_decisions():
    """[S4] set 收尾、drift fix c2 --close、decision-add、decision-supersede 成功後,列出連到那篇、同一子句有待定詞的行
    與 c6 修法範本;回傳碼照舊、不改其他檔。

    翻紅釘:main 拿掉 set 之後的列出 → ①紅;fix close 不呼叫 → ②紅;decision-add / supersede 不呼叫 → ③④紅;
    列出時要求目標已收尾 → ③④紅(加決策不改狀態)。
    """
    print("t_settle_backrefs_listed_after_close_and_decisions")
    root = _df_repo()
    v = root / _DR_VAULT
    _nh_node(root, "P_計劃", typ="project", folder="Projects", resp=None, summary="KEY:p")
    _nh_file(root, f"{_DR_VAULT}/Issues/C.md", "---\ntype: issue\nstatus: open\n---\n# C\n第一段 [[Projects/Done_計劃]]\n")
    ref = _nh_file(root, f"{_DR_VAULT}/Projects/Ref_計劃.md", "---\ntype: project\nstatus: doing\n---\n# Ref\n"
                   "甲 待裁定 [[Projects/P_計劃]]\n乙 還沒做 [[Issues/C]]\n丙 未裁定 [[Systems/Pay]]\n")
    _df_commit(root, "backref cases")
    raw = ref.read_bytes()
    r = run(v, "set", "Projects/P_計劃", "status", "done")
    check("①set 收尾:列出 Ref 甲那行與 c6 修法範本", r.returncode == 0 and f"Projects/Ref_計劃.md:{_c6_ln(ref, '甲 ')}" in r.stdout
          and "--kind c6" in r.stdout, r.stdout)
    _df_commit(root, "P done")
    rc, out = _df_fix(v, "Issues/C", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "修好了,提交 abc")
    check("②drift fix c2 --close:列出 Ref 乙那行", rc == 0 and f"Projects/Ref_計劃.md:{_c6_ln(ref, '乙 ')}" in out, out)
    _df_commit(root, "C closed")
    r = run(v, "decision-add", "Systems/Pay", "改用新做法", "--decided", "2026-10-05")
    check("③decision-add:列出 Ref 丙那行(Pay 沒收尾也列)", r.returncode == 0
          and f"Projects/Ref_計劃.md:{_c6_ln(ref, '丙 ')}" in r.stdout, r.stdout + r.stderr)
    r = run(v, "decision-supersede", "Systems/Pay", "改用新做法", "--by", "再換一個")
    check("④decision-supersede:列出 Ref 丙那行", r.returncode == 0
          and f"Projects/Ref_計劃.md:{_c6_ln(ref, '丙 ')}" in r.stdout, r.stdout + r.stderr)
    check("⑤只列出:Ref 一個位元組都沒動", ref.read_bytes() == raw, "")


def t_drift_close_requires_decision_for_pending_line():
    """[S5] c2 --close:摘要有含待定詞的 DECISION: 行又沒給 --decision → 回 2 不寫;給了就換成「DECISION:[今天] 新句」;
    兩行以上待定、或沒有待定行卻給了 --decision → 回 2 不寫。

    翻紅釘:不檢查 DECISION 行 → ①紅;--decision 不加日期 → ④紅;多行時換第一行 → ②紅;沒待定行也收 → ③紅。
    """
    print("t_drift_close_requires_decision_for_pending_line")
    import datetime
    today = datetime.date.today().isoformat()
    root = _df_repo()
    v = root / _DR_VAULT
    def issue(name, decisions):
        s = "".join(f"  DECISION:{d}\n" for d in decisions)
        return _nh_file(root, f"{_DR_VAULT}/Issues/{name}.md", f"---\ntype: issue\nstatus: open\nsummary: |-\n  FLAG:TECHNICAL\n{s}---\n"
                        f"# {name}\n第一段 [[Projects/Done_計劃]]\n")
    i = issue("I", ["(未裁)要不要修另開計劃"])
    j = issue("J", ["未裁——方向一", "還沒修,等上游"])
    k = issue("K", ["[2026-09-01] 已決定照做"])
    _df_commit(root, "decision cases")
    args = ("--kind", "c2", "--close", "--status", "resolved", "--reason", "修好了,提交 abc")
    raw = i.read_bytes()
    rc, out = _df_fix(v, "Issues/I", "3", *args)
    check("①待定決策行沒給 --decision:回 2、列出那行、不寫檔", rc == 2 and "(未裁)要不要修" in out and "--decision" in out
          and i.read_bytes() == raw, out)
    jraw = j.read_bytes()
    rc, out = _df_fix(v, "Issues/J", "3", *args, "--decision", "決定不修了")
    check("②兩行待定:回 2、不寫檔", rc == 2 and "一次只換一行" in out and j.read_bytes() == jraw, out)
    kraw = k.read_bytes()
    rc, out = _df_fix(v, "Issues/K", "3", *args, "--decision", "多給的一句結論")
    check("③沒有待定行卻給了 --decision:回 2、不寫檔", rc == 2 and "不用 --decision" in out and k.read_bytes() == kraw, out)
    rc, out = _df_fix(v, "Issues/I", "3", *args, "--decision", "還沒做,另開計劃")
    check("⑤換上的新句還寫待定:回 2、不寫檔(代碼審 r1 正確性席)", rc == 2 and "待定" in out and i.read_bytes() == raw, out)
    rc, out = _df_fix(v, "Issues/I", "3", *args, "--decision", "不修,改走設計審")
    t = i.read_text(encoding="utf-8")
    check("④給了 --decision:那一行換成帶今天日期的新句、照常結案", rc == 0 and f"  DECISION:[{today}] 不修,改走設計審\n" in t
          and "(未裁)" not in t and "status: resolved" in t, out + t)


def t_drift_close_blocks_live_revisits():
    """[S6] c2 --close:還有沒結案的回頭條件又沒給 --keep-revisits → 回 2、列出每行、不寫;合格 [closed:] 的不算;
    給了 --keep-revisits 照常結案、修復帳記理由與行號;沒有活的卻給了 → 回 2。

    翻紅釘:不檢查回頭條件 → ①紅;[closed:] 的也算 → ②紅;不記理由 → ④帳那格紅;沒有活的也收 → ③紅。
    """
    print("t_drift_close_blocks_live_revisits")
    root = _df_repo()
    v = root / _DR_VAULT
    def issue(name, extra):
        return _nh_file(root, f"{_DR_VAULT}/Issues/{name}.md", f"---\ntype: issue\nstatus: open\n---\n# {name}\n"
                        f"第一段 [[Projects/Done_計劃]]\n{extra}")
    r_ = issue("R", "REVISIT:2099-01-01 未來的\nREVISIT:2020-01-01 已處理的 [closed:2026-09-01 早就處理完了]\n")
    s_ = issue("S", "REVISIT:2020-01-01 已處理的 [closed:2026-09-01 早就處理完了]\n")
    t_ = issue("T", "")
    _df_commit(root, "revisit cases")
    args = ("--kind", "c2", "--close", "--status", "done", "--reason", "修好了,提交 abc")
    raw = r_.read_bytes()
    rc, out = _df_fix(v, "Issues/R", "3", *args)
    check("①有活的回頭條件沒給 --keep-revisits:回 2、列出那行、不寫檔", rc == 2 and "未來的" in out and "--keep-revisits" in out
          and r_.read_bytes() == raw, out)
    check("②已寫合格 [closed:] 的不列", "已處理的" not in out, out)
    rc, out = _df_fix(v, "Issues/S", "3", *args)
    check("②只有已結案的回頭條件:照常結案", rc == 0 and "status: done" in s_.read_text(encoding="utf-8"), out)
    traw = t_.read_bytes()
    rc, out = _df_fix(v, "Issues/T", "3", *args, "--keep-revisits", "上線後要回頭量")
    check("③沒有活的卻給了 --keep-revisits:回 2、不寫檔", rc == 2 and "不用 --keep-revisits" in out and t_.read_bytes() == traw, out)
    rc, out = _df_fix(v, "Issues/R", "3", *args, "--keep-revisits", "上線後要回頭量")
    n = _c6_ln(r_, "未來的")
    row = (_df_rows(root) or [{}])[-1]
    check("④給了 --keep-revisits:照常結案、修復帳記理由與留下的行號", rc == 0 and "status: done" in r_.read_text(encoding="utf-8")
          and row.get("keep_revisits") == {"reason": "上線後要回頭量", "lines": [n]}, out + str(row))


def t_superseded_note_revisits_listed_and_marked():
    """[S7] set 把任何類型改成 superseded → 列出全部沒結案的回頭條件;doctor E5 在作廢筆記那行標「(這篇已作廢)」;
    計劃改成 done 不列不標。

    翻紅釘:_closing_revisits 只認 Issue → ①紅;E5 不標作廢 → ③紅;done 計劃也列 → ②紅。
    """
    print("t_superseded_note_revisits_listed_and_marked")
    v = mkvault()
    sp = write(v, "Projects/S.md", "type: project\nstatus: doing", body="# S\nREVISIT:2020-01-01 過期的作廢\nREVISIT:2099-01-01 未來的作廢\n")
    write(v, "Projects/D.md", "type: project\nstatus: doing", body="# D\nREVISIT:2020-01-02 過期的收尾\n")
    yp = write(v, "Systems/Y.md", "type: system\nstatus: doing", body="# Y\nREVISIT:2099-01-01 系統未來的\n")
    r = run(v, "set", "Projects/S", "status", "superseded")
    check("①計劃改成 superseded:列出兩行", r.returncode == 0 and "作廢" in r.stdout
          and f"Projects/S.md:{_c6_ln(sp, '過期的作廢')}" in r.stdout and f"Projects/S.md:{_c6_ln(sp, '未來的作廢')}" in r.stdout, r.stdout)
    r = run(v, "set", "Systems/Y", "status", "superseded")
    check("①系統筆記改成 superseded 也列", r.returncode == 0 and f"Systems/Y.md:{_c6_ln(yp, '系統未來的')}" in r.stdout, r.stdout)
    r = run(v, "set", "Projects/D", "status", "done")
    check("②計劃改成 done:不列", r.returncode == 0 and "還留著" not in r.stdout, r.stdout)
    r = run(v, "doctor")
    out = r.stdout + r.stderr
    sl = [l for l in out.split("\n") if "過期的作廢" in l]
    dl = [l for l in out.split("\n") if "過期的收尾" in l]
    check("③E5:作廢筆記那行標「(這篇已作廢)」、done 計劃那行不標", sl and all("(這篇已作廢)" in l for l in sl)
          and dl and not any("已作廢" in l for l in dl), "\n".join(sl + dl) or out[-1500:])


def t_set_issue_close_lists_pending_decision():
    """[S8] set 把 Issue 改成結案值、摘要還有含待定詞的 DECISION: 行 → 列出那幾行,回 0、不改那幾行。

    翻紅釘:_closing_revisits 不列待定決策行 → ①紅;列的時候改了檔 → ②紅。
    """
    print("t_set_issue_close_lists_pending_decision")
    v = mkvault()
    p = write(v, "Issues/I.md", "type: issue\nstatus: open\nsummary: |-\n  FLAG:TECHNICAL\n  DECISION:(未裁)要不要修另開計劃",
              body="# I\n第一段\n")
    raw = p.read_text(encoding="utf-8")
    r = run(v, "set", "Issues/I", "status", "resolved")
    check("①列出待定決策行", r.returncode == 0 and "(未裁)要不要修" in r.stdout and "DECISION" in r.stdout, r.stdout)
    check("②只列出:除了 status 一字不動", p.read_text(encoding="utf-8") == raw.replace("status: open", "status: resolved"), "")


def t_drift_ack_binds_related_plans():
    """[S8] c2/c3 表態確認那一行當下是那一種發現,記當時的已收尾計劃清單與遞增序號;比對只看記了清單的、取序號最大的那幾筆,
    全部涵蓋現在的清單才算;沒記清單的舊表態不再算數;同一篇行號移位不影響。

    翻紅釘:cmd_drift_ack 拿掉 c2/c3 的 _drift_current_finding → ①紅;_drift_split_acked 對 c2 改回任一筆對得上 → ③⑤紅;
    同號改成任一筆涵蓋就算 → ⑥紅;不檢查 related 是字串清單 → ⑦「清單裡混了數字」紅(nfc 對數字丟例外,scan 整支倒);
    比對綁行號 → ⑧紅;seq 不是正整數的也算數 → ⑪紅。
    (⑦ 原本只有 related 是一整個字串那格:拿掉檢查後字串被拆成單字集合、照樣「沒涵蓋」,那格走不到被測分支——代碼審 r1 正確性席。)
    """
    print("t_drift_ack_binds_related_plans")
    import json as _j
    root = _df_repo()
    v = root / _DR_VAULT
    _nh_node(root, "Two_計劃", typ="project", folder="Projects", resp=None, status="doing", summary="KEY:t")
    _nh_file(root, f"{_DR_VAULT}/Issues/I.md", "---\ntype: issue\nstatus: open\n---\n# I\n[[Projects/Done_計劃]] [[Projects/Two_計劃]]\n")
    for n in ("I2", "I3", "I4", "I5", "I6"):
        _nh_file(root, f"{_DR_VAULT}/Issues/{n}.md", f"---\ntype: issue\nstatus: open\n---\n# {n}\n[[Projects/Done_計劃]]\n")
    write(v, "Verification/V.md", 'type: verification\nstatus: pending\nplan_refs:\n  - "[[Projects/Done_計劃]]"', body="# V\n")
    _df_commit(root, "c")
    acks = root / "governance" / "drift-acks.jsonl"
    r = run(v, "drift", "ack", "Issues/I", "1", "--kind", "c2", "--reason", "還在排查中照留")
    check("①那一行當下不是 c2:回 2、不寫", r.returncode == 2 and "現在不是 c2" in r.stderr and not acks.exists(), r.stdout + r.stderr)
    r = run(v, "drift", "ack", "Issues/I", "3", "--kind", "c2", "--reason", "還在排查中照留")
    rows = _df_rows(root, "drift-acks.jsonl")
    check("②記下當時的已收尾計劃與序號", r.returncode == 0 and rows[-1]["related"] == ["Projects/Done_計劃.md"]
          and rows[-1]["seq"] == 1, str(rows))
    ack = lambda p, k="c2": [f["acked"] for f in (_j.loads(run(v, "drift", "scan", "--json").stdout)["findings"])
                             if f["path"] == p and f["kind"] == k]
    check("②scan 算已表態", ack("Issues/I.md") == [True], "")
    two = v / "Projects" / "Two_計劃.md"
    two.write_text(two.read_text(encoding="utf-8").replace("status: doing", "status: done"), encoding="utf-8")
    check("③多了新的收尾計劃:重新列出", ack("Issues/I.md") == [False], "")
    r = run(v, "drift", "scan")
    check("③說明以前表態過、現在多了哪篇、最近一次理由", "這篇以前表態過" in r.stdout and "現在多了 Projects/Two_計劃" in r.stdout
          and "還在排查中照留" in r.stdout, r.stdout)
    run(v, "drift", "ack", "Issues/I", "3", "--kind", "c2", "--reason", "兩份都收尾了照留")
    rows = _df_rows(root, "drift-acks.jsonl")
    check("④重新表態:序號遞增、清單兩篇、算已表態", rows[-1]["seq"] == 2 and len(rows[-1]["related"]) == 2
          and ack("Issues/I.md") == [True], str(rows[-1]))
    base = {"path": f"{_DR_VAULT}/Issues/I2.md", "text": "status: open", "kind": "c2", "reason": "舊版表態"}
    with open(acks, "a", encoding="utf-8") as fh:
        fh.write(_j.dumps(dict(base, id="DACK-old1"), ensure_ascii=False) + "\n")
        fh.write(_j.dumps(dict(base, id="DACK-s1", path=f"{_DR_VAULT}/Issues/I3.md", seq=9,
                               related=["Projects/Done_計劃.md"]), ensure_ascii=False) + "\n")
        fh.write(_j.dumps(dict(base, id="DACK-s2", path=f"{_DR_VAULT}/Issues/I3.md", seq=9, related=[]), ensure_ascii=False) + "\n")
        fh.write(_j.dumps(dict(base, id="DACK-b1", path=f"{_DR_VAULT}/Issues/I4.md", seq=1,
                               related=["Projects/Done_計劃.md"]), ensure_ascii=False) + "\n")
        fh.write(_j.dumps(dict(base, id="DACK-b2", path=f"{_DR_VAULT}/Issues/I4.md", seq=10,
                               related="Projects/Done_計劃.md"), ensure_ascii=False) + "\n")
        fh.write(_j.dumps(dict(base, id="DACK-m1", path=f"{_DR_VAULT}/Issues/I5.md", seq=3,
                               related=["Projects/Done_計劃.md", 1]), ensure_ascii=False) + "\n")
        fh.write(_j.dumps(dict(base, id="DACK-q1", path=f"{_DR_VAULT}/Issues/I6.md", seq="壞掉",
                               related=["Projects/Done_計劃.md"]), ensure_ascii=False) + "\n")
    check("⑤沒記清單的舊表態不再算數", ack("Issues/I2.md") == [False], "")
    check("⑥同號兩筆、有一筆沒涵蓋:保守,重新列出", ack("Issues/I3.md") == [False], "")
    check("⑦序號最大那筆的 related 不是字串清單:當成沒涵蓋", ack("Issues/I4.md") == [False], "")
    r7 = run(v, "drift", "scan", "--json")
    check("⑦清單裡混了數字:scan 照跑、當成沒涵蓋", r7.returncode in (0, 1) and ack("Issues/I5.md") == [False], r7.stderr[-400:])
    check("⑪seq 不是正整數的綁定表態不算數", ack("Issues/I6.md") == [False], "")
    ip = v / "Issues" / "I.md"
    ip.write_text(ip.read_text(encoding="utf-8").replace("---\ntype: issue\n", "---\ntype: issue\naliases: []\nowner: enzo\n"),
                  encoding="utf-8")
    fs = [f for f in _j.loads(run(v, "drift", "scan", "--json").stdout)["findings"] if f["path"] == "Issues/I.md"]
    check("⑧同一篇上面插兩行:發現的行號變了、表態照樣對得上", [f["line"] for f in fs] == [5] and [f["acked"] for f in fs] == [True],
          str(fs))
    r = run(v, "drift", "ack", "Verification/V", "3", "--kind", "c3", "--reason", "驗證還沒做照留")
    rows = _df_rows(root, "drift-acks.jsonl")
    check("⑨c3 表態也記清單", r.returncode == 0 and rows[-1]["kind"] == "c3" and rows[-1]["related"] == ["Projects/Done_計劃.md"]
          and ack("Verification/V.md", "c3") == [True], str(rows[-1]))
    (v / "Verification" / "G.md").write_text(_dr_guard_text("pass"), encoding="utf-8")
    ln = min(f["line"] for f in _df_find(v, "c1", "Verification/G.md"))
    r = run(v, "drift", "ack", "Verification/G", str(ln), "--kind", "c1", "--reason", "歷史紀錄照留")
    rows = _df_rows(root, "drift-acks.jsonl")
    check("⑩其他種類照舊(不記清單)、也記序號", r.returncode == 0 and "related" not in rows[-1]
          and rows[-1]["seq"] == max(x["seq"] for x in rows[:-1] if type(x.get("seq")) is int) + 1, str(rows[-1]))


def t_drift_fix_dry_run_lock_and_ledger():
    """[S9] fix 在鎖內比指紋才寫、寫完確認磁碟內容等於算出的內容且已處理才寫修復帳;驗證失敗或帳寫不進去回 2 指到 git、不自動還原;
    --dry-run 不拿鎖、不寫檔不寫帳但做完判定;修復帳在簿記檔名單、帳檔或 repo 內上層目錄是符號連結時擋下;自由文字過不了形狀擋時擋下。

    翻紅釘:_drift_fix_write 拿掉指紋比對 → ③紅(蓋掉別人的改動);atomic_write_verify 移到鎖外 → ②紅;
    驗證失敗時自動還原 → ④「筆記留著改動」紅;dry-run 也拿鎖 → ①紅;_BOOKKEEPING_FILES 拿掉帳檔 → ⑦紅;
    _drift_ledger_path_err 拿掉逐層連結檢查 → ⑧紅;拿掉 _drift_fix_shape_err → ⑨紅。
    """
    print("t_drift_fix_dry_run_lock_and_ledger")
    import contextlib, io, hashlib, os as _os, tempfile as _tf
    root = _df_repo()
    v = root / _DR_VAULT
    ref = 'plan_refs:\n  - "[[Projects/Done_計劃]]"'
    for n in ("V", "W", "X"):
        write(v, f"Verification/{n}.md", "type: verification\nstatus: pending\n" + ref, body=f"# {n}\n")
    _nh_file(root, "scripts/app.py", "".join(f"x{i} = {i}\n" for i in range(30)))
    _nh_file(root, f"{_DR_VAULT}/Issues/I.md", "---\ntype: issue\nstatus: open\n---\n# I\n[[Projects/Done_計劃]]\n")
    _df_commit(root, "c")
    m = _load_lumos_inproc()
    O = lambda **k: dict({"dry_run": False, "date": None, "close": False, "keep": False, "status": None, "reason": None,
                          "by": None, "old": None, "new": None}, **k)
    V = v / "Verification" / "V.md"
    raw = V.read_bytes()
    locks = []
    orig_lock = m._vault_write_lock
    m._vault_write_lock = lambda vault: (locks.append(1), orig_lock(vault))[1]
    try:
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(out):
            rc = m.cmd_drift_fix(m.Env(v), "Verification/V", 3, "c3", O(dry_run=True, status="pass"))
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            rc_bad = m.cmd_drift_fix(m.Env(v), "Verification/V", 1, "c3", O(dry_run=True, status="pass"))
    finally:
        m._vault_write_lock = orig_lock
    check("①--dry-run:印改前改後、回 0、不拿鎖、不寫檔不寫帳", rc == 0 and "- 第 3 行:status: pending" in out.getvalue()
          and "狀態改為 pass" in out.getvalue() and not locks and V.read_bytes() == raw and not _df_rows(root), out.getvalue())
    check("①--dry-run 也做判定(那一行不是 c3 回 2)", rc_bad == 2, "")
    held = []
    orig_w = m.atomic_write_verify

    def spy_w(path, *a, **k):
        held.append(bool(m._VAULT_LOCK_HELD))
        return orig_w(path, *a, **k)
    m.atomic_write_verify = spy_w
    try:
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            rc = m.cmd_drift_fix(m.Env(v), "Verification/V", 3, "c3", O(status="pass"))
    finally:
        m.atomic_write_verify = orig_w
    check("②寫入時拿著鎖", rc == 0 and held == [True], f"{rc} {held}")
    rows = _df_rows(root)
    check("②修復帳一筆:DFIX- 編號、序號、repo 相對路徑、改前行號、插入行記 null、改後指紋等於磁碟",
          len(rows) == 1 and rows[0]["id"].startswith("DFIX-") and rows[0]["seq"] == 1
          and rows[0]["path"] == f"{_DR_VAULT}/Verification/V.md" and rows[0]["line"] == 3
          and {"line": 3, "before": "status: pending", "after": "status: pass"} in rows[0]["changed"]
          and any(c["line"] is None and c["before"] is None and "狀態改為 pass" in (c["after"] or "") for c in rows[0]["changed"])
          and rows[0]["after_sha256"] == hashlib.sha256(V.read_bytes()).hexdigest(), str(rows))
    W = v / "Verification" / "W.md"
    orig_sh = m._drift_fix_shape_err

    def meddle(root_, texts):
        W.write_text(W.read_text(encoding="utf-8") + "別的會談剛寫的\n", encoding="utf-8")
        return orig_sh(root_, texts)
    m._drift_fix_shape_err = meddle
    err = io.StringIO()
    try:
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
            rc = m.cmd_drift_fix(m.Env(v), "Verification/W", 3, "c3", O(status="pass"))
    finally:
        m._drift_fix_shape_err = orig_sh
    check("③判定之後那一篇被改過:鎖內比指紋不符、回 2、不蓋掉對方", rc == 2 and "被改過" in err.getvalue()
          and "別的會談剛寫的" in W.read_text(encoding="utf-8") and "status: pending" in W.read_text(encoding="utf-8"), err.getvalue())
    _nh_git(root, "checkout", "--", f"{_DR_VAULT}/Verification/W.md")
    rc, out = _df_fix(v, "Verification/W", "3", "--kind", "c3", "--status", "pass", env={"LUMOS_DRIFT_FIX_FAULT": "verify"})
    check("④驗證失敗:回 2、指到 git checkout、不自動還原、不寫帳", rc == 2 and "checkout --" in out
          and "status: pass" in W.read_text(encoding="utf-8") and len(_df_rows(root)) == 1, out)
    rc, out = _df_fix(v, "Verification/W", "3", "--kind", "c3", "--status", "pass")
    check("④照指示還原前:工具不在不乾淨的筆記上動手", rc == 2 and "未提交" in out, out)
    _nh_git(root, "checkout", "--", f"{_DR_VAULT}/Verification/W.md")
    rc, out = _df_fix(v, "Verification/W", "3", "--kind", "c3", "--status", "pass", env={"LUMOS_DRIFT_FIX_FAULT": "ledger"})
    check("⑤帳寫不進去:回 2、筆記已改好、帳沒多", rc == 2 and "修復帳沒記到" in out and "status: pass" in W.read_text(encoding="utf-8")
          and len(_df_rows(root)) == 1, out)
    _nh_git(root, "checkout", "--", f"{_DR_VAULT}/Verification/W.md")
    rc, out = _df_fix(v, "Verification/W", "3", "--kind", "c3", "--status", "pass", env={"LUMOS_DRIFT_FIX_FAULT": "bogus"})
    check("⑥故障注入只認 verify|ledger:其他值照常成功、提示跟筆記一起提交", rc == 0 and len(_df_rows(root)) == 2
          and "add governance/drift-fixes.jsonl" in out, out)
    check("⑦修復帳在簿記檔名單裡", "governance/drift-fixes.jsonl" in m._BOOKKEEPING_FILES, "")
    fx = root / "governance" / "drift-fixes.jsonl"
    outside = Path(_tf.mkdtemp(prefix="gctl-outside-")) / "x.jsonl"
    outside.write_text("", encoding="utf-8")
    keep = fx.read_bytes()
    fx.unlink()
    _os.symlink(outside, fx)
    rc, out = _df_fix(v, "Verification/X", "3", "--kind", "c3", "--status", "pass")
    check("⑧帳檔是符號連結:回 2、外面的檔沒被寫", rc == 2 and "符號連結" in out and outside.read_text(encoding="utf-8") == "", out)
    fx.unlink()
    fx.write_bytes(keep)
    real = Path(_tf.mkdtemp(prefix="gctl-realdir-"))
    _os.symlink(real, root / "govlink")
    check("⑧repo 內上層目錄是符號連結也擋", "符號連結" in (m._drift_ledger_path_err(root, "govlink/a.jsonl") or ""), "")
    _os.link(fx, root / "hard.jsonl")
    check("⑧帳檔有別的硬連結也擋", "硬連結" in (m._drift_ledger_path_err(root, "governance/drift-fixes.jsonl") or ""), "")
    (root / "hard.jsonl").unlink()
    (root / "govlink").unlink()
    _nh_git(root, "checkout", "--", f"{_DR_VAULT}/Verification/X.md")
    ip = v / "Issues" / "I.md"
    iraw = ip.read_bytes()
    rc, out = _df_fix(v, "Issues/I", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "修好了,見 scripts/app.py:12")
    check("⑨自由文字過不了筆記形狀擋(程式行號引用):回 2、不寫", rc == 2 and "筆記形狀擋" in out and ip.read_bytes() == iraw, out)


def t_drift_hints_point_to_fix():
    """[S10] drift check 擋下與只列出、drift scan、doctor Z 段、計劃收尾列出 c1–c5 時,訊息由同一支函式產生、指到 lumos drift fix
    (c1 每篇一條),不再教人手改。

    翻紅釘:check 擋下改回「把預告句手改」→ ①紅;scan 不印改法 → ②紅;Z 段、計劃收尾的連帶待辦不呼叫 _drift_fix_hint →
    ③④紅;任一處自己寫死指令文字 → ⑤同一支那格紅。
    """
    print("t_drift_hints_point_to_fix")
    import contextlib, io
    root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
    v = root / _DR_VAULT
    _nh_node(root, "Pay", summary=_DF_PAY)
    (v / "Verification" / "G.md").write_text(_dr_guard_text("pending"), encoding="utf-8")
    _nh_file(root, f"{_DR_VAULT}/Issues/I.md", "---\ntype: issue\nstatus: open\n---\n# I\n[[Projects/退款_計劃]]\n")
    write(v, "Verification/V.md", 'type: verification\nstatus: pending\nplan_refs:\n  - "[[Projects/退款_計劃]]"', body="# V\n")
    _nh_commit(root, "base")
    base = _na_head(root)
    g = v / "Verification" / "G.md"
    g.write_text(g.read_text(encoding="utf-8").replace("status: pending", "status: pass").replace("status/pending", "status/pass"),
                 encoding="utf-8")
    r = run(v, "set", "Projects/退款_計劃", "status", "done")
    check("④計劃收尾的連帶待辦:c3 那一項給 drift fix 指令", "lumos drift fix Verification/V 3 --kind c3 --status <" in r.stdout,
          r.stdout)
    _nh_commit(root, "轉正、收尾")
    rc, out = _dr(root, "check", "--diff", f"{base}..HEAD")
    check("①check 擋下:c1 一篇一條 drift fix 指令、不再教人手改", rc == 1
          and out.count("lumos drift fix Verification/G ") == 1 and "--kind c1" in out and "把預告句手改" not in out, out)
    check("①check 只列出的那條路也指到 drift fix(c2 兩條)", "lumos drift fix Issues/I 3 --kind c2 --close" in out
          and "lumos drift fix Issues/I 3 --kind c2 --keep" in out, out)
    r = run(v, "drift", "scan")
    check("②scan:每篇印一次、c3 帶 --status 佔位、c2 印兩條", r.stdout.count("lumos drift fix Verification/G ") == 1
          and "lumos drift fix Verification/V 3 --kind c3 --status <" in r.stdout
          and "--kind c2 --close" in r.stdout and "--kind c2 --keep" in r.stdout, r.stdout)
    rd = run(v, "doctor")
    z = rd.stdout.split("[Z]")[1] if "[Z]" in rd.stdout else ""
    check("③doctor Z 段指到 drift fix", "lumos drift fix" in z, z[:600])
    m = _load_lumos_inproc()
    orig = m._drift_fix_hint
    m._drift_fix_hint = lambda k, p, ln, names=None: [f"HINT-{k}"]
    try:
        so, se = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(so), contextlib.redirect_stderr(se):
            m.cmd_drift_scan(m.Env(v))
            zl = m._drift_doctor_lines(m.Env(v))
            m.cmd_drift_check(repo=str(root), diff_range=f"{base}..HEAD")
            p = v / "Projects" / "退款_計劃.md"
            p.write_text(p.read_text(encoding="utf-8").replace("status: done", "status: doing"), encoding="utf-8")
            m._drift_print_followups(m.Env(v), "Projects/退款_計劃.md", "done")
    finally:
        m._drift_fix_hint = orig
    check("⑤同一支函式產生:scan、Z 段、check、計劃收尾都用 _drift_fix_hint", "HINT-c1" in so.getvalue()
          and any("HINT-c1" in x for x in zl) and "HINT-c1" in se.getvalue() and "HINT-c2" in se.getvalue()
          and so.getvalue().count("HINT-c3") >= 2, so.getvalue()[-800:] + se.getvalue()[-400:] + str(zl))


def t_drift_fix_c2_close_or_keep():
    """[S11] c2 --close 只收 Issue 的結案值、改 status、正文標題之後加結案橫幅(已有就不加)並列回頭條件;--keep 等同帶清單的 c2 表態;
    兩者都沒給或都給、--reason 超過一行或不在 4 到 200 字時擋下。

    翻紅釘:結案值改用 QUERY_CLOSED_STATUSES → ①「pass」那格紅;_drift_close_banner 改成加在檔尾 → ②位置紅;
    拿掉「已有橫幅不加」→ ③紅;--keep 改成也做乾淨檢查 → ④有改動時紅;--keep 不記 related → ④紅。
    """
    print("t_drift_fix_c2_close_or_keep")
    import datetime
    today = datetime.date.today().isoformat()
    root = _df_repo()
    v = root / _DR_VAULT
    I = v / "Issues" / "I.md"
    _nh_file(root, f"{_DR_VAULT}/Issues/I.md", "---\ntype: issue\nstatus: open\ntags:\n  - type/issue\n  - status/open\n---\n"
             "# I\n第一段排查紀錄 [[Projects/Done_計劃]]\n")
    _nh_file(root, f"{_DR_VAULT}/Issues/B.md", "---\ntype: issue\nstatus: doing\n---\n# B\n\n> 已結案(2026-09-01,done):舊的橫幅。\n\n"
             "[[Projects/Done_計劃]]\n")
    _nh_file(root, f"{_DR_VAULT}/Issues/K.md", "---\ntype: issue\nstatus: open\n---\n# K\n[[Projects/Done_計劃]]\n")
    _df_commit(root, "c2 cases")
    check("①前置:I 第 3 行是 c2", [f["line"] for f in _df_find(v, "c2", "Issues/I.md")] == [3], "")
    raw = I.read_bytes()
    bad = [((), "二擇一"), (("--close", "--keep", "--status", "done", "--reason", "修好了喔"), "二擇一"),
           (("--close", "--reason", "修好了喔"), "結案值"), (("--close", "--status", "open", "--reason", "修好了喔"), "結案值"),
           (("--close", "--status", "pass", "--reason", "修好了喔"), "結案值"), (("--close", "--status", "done", "--reason", "短"), "4 到 200"),
           (("--close", "--status", "done", "--reason", "字" * 201), "4 到 200"),
           (("--close", "--status", "done", "--reason", "第一行\n第二行"), "一行"), (("--keep", "--reason", "還沒好喔", "--status", "done"), "不收")]
    for args, why in bad:
        rc, out = _df_fix(v, "Issues/I", "3", "--kind", "c2", *args)
        check(f"①{args[:3]}…:回 2({why})", rc == 2 and why in out, out)
    check("①擋下都沒動檔", I.read_bytes() == raw, "")
    rc, out = _df_fix(v, "Issues/I", "3", "--kind", "c2", "--close", "--status", "resolved", "--reason", "修好了,提交 abc123 的測試 t_x")
    t = I.read_text(encoding="utf-8")
    check("②status 改成 resolved、標籤同步", rc == 0 and "status: resolved" in t and "status/resolved" in t and "status/open" not in t,
          out + t)
    check("②結案橫幅在標題之後、第一段之前", f"# I\n\n> 已結案({today},resolved):修好了,提交 abc123 的測試 t_x。"
          "以下是當時的排查紀錄,不是現況。\n\n第一段排查紀錄" in t, t)
    check("②c2 消失", not _df_find(v, "c2", "Issues/I.md"), "")
    braw = (v / "Issues" / "B.md").read_text(encoding="utf-8")
    rc, out = _df_fix(v, "Issues/B", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "這次真的修好了")
    tb = (v / "Issues" / "B.md").read_text(encoding="utf-8")
    check("③第一段已經是已結案橫幅:不再加、訊息講出來", rc == 0 and tb.count("已結案(") == 1 and "沒再加" in out
          and tb == braw.replace("status: doing", "status: done"), out + tb)
    K = v / "Issues" / "K.md"
    K.write_text(K.read_text(encoding="utf-8") + "未提交的筆記\n", encoding="utf-8")
    kraw = K.read_bytes()
    rc, out = _df_fix(v, "Issues/K", "3", "--kind", "c2", "--keep", "--reason", "還沒解決,等上游")
    rows = _df_rows(root, "drift-acks.jsonl")
    check("④--keep 等同帶清單的 c2 表態:不做乾淨檢查、不改筆記、不寫修復帳", rc == 0 and K.read_bytes() == kraw
          and rows and rows[-1]["kind"] == "c2" and rows[-1]["related"] == ["Projects/Done_計劃.md"]
          and not any(x["path"].endswith("Issues/K.md") for x in _df_rows(root)), out + str(rows))


def t_drift_fix_review_r1_edges():
    """代碼審 r1 折入的邊角(存量漂移改法):--keep --dry-run 只預覽;提示的佔位字照抄進來擋下;印給人照貼的指令參數加引號;
    c4 換完在標準 YAML 讀得一樣;結案橫幅只認橫幅形狀、標題不在圍欄裡找;帳檔只在 \\n 切行;帳檔路徑壞掉時寫筆記之前就擋;
    被修的筆記是符號連結擋下;驗證之後、記帳之前被改就不記帳;c4 只列證據不做乾淨檢查;家節點有正式行但沒綁測試擋下。

    翻紅釘:--keep 不看 dry_run → ①紅;拿掉 _drift_placeholder_err → ②紅;_drift_sh 改成原樣 → ③紅;
    橫幅判定改回「開頭是已結案」→ ⑤假橫幅紅;標題不看圍欄 → ⑤圍欄紅;_drift_jsonl_parse 改回 splitlines → ⑥紅;
    帳檔路徑檢查移回寫筆記之後 → ⑦「筆記沒動」紅;拿掉筆記連結檢查 → ⑧紅;記帳前不再比磁碟 → ⑨紅;
    c4 只列證據也做乾淨檢查 → ⑩紅;_guard_pass_home 不要求綁測試 → ⑪紅;--reason 只擋 \\n → ⑫紅;鎖內不比家節點 → ⑬紅;_phys_path 拿掉逐層找 → ⑭紅(只在分 NFC/NFD 的檔案系統上跑得到,例如 Linux CI;macOS 上前置斷言不成立就跳過並印出來)。
    """
    print("t_drift_fix_review_r1_edges")
    import os as _os
    m = _load_lumos_module()
    root = _df_repo()
    v = root / _DR_VAULT
    _nh_file(root, f"{_DR_VAULT}/Issues/K.md", "---\ntype: issue\nstatus: open\n---\n# K\n[[Projects/Done_計劃]]\n")
    _nh_file(root, f"{_DR_VAULT}/Issues/F.md", "---\ntype: issue\nstatus: open\n---\n已結案通知功能仍會重複寄信\n\n"
             "[[Projects/Done_計劃]]\n")
    _nh_file(root, f"{_DR_VAULT}/Issues/C.md", "---\ntype: issue\nstatus: open\n---\n```\n# comment\n```\n\n"
             "[[Projects/Done_計劃]]\n")
    V = v / "Verification"
    (V / "Q.md").write_text("---\ntype: verification\nstatus: pass\nvalid_under:\n  - \"本工作樹(未提交)\"\n  - 甲(未提交)\n"
                            "  - 乙(未提交)\n---\n# Q\n", encoding="utf-8")
    write(v, "Verification/W.md", 'type: verification\nstatus: pending\nplan_refs:\n  - "[[Projects/Done_計劃]]"', body="# W\n")
    write(v, "Verification/X.md", 'type: verification\nstatus: pending\nplan_refs:\n  - "[[Projects/Done_計劃]]"', body="# X\n")
    _df_commit(root, "r1 edges")
    acks = root / "governance" / "drift-acks.jsonl"
    K = v / "Issues" / "K.md"
    kraw = K.read_bytes()
    rc, out = _df_fix(v, "Issues/K", "3", "--kind", "c2", "--keep", "--reason", "還沒解決等上游", "--dry-run")
    check("①--keep --dry-run:回 0、印預覽、不寫表態檔", rc == 0 and "預覽(沒寫)" in out and not acks.exists()
          and K.read_bytes() == kraw, out)
    for args in (("--close", "--status", "done", "--reason", "<為什麼算解決,附提交或測試>"),
                 ("--keep", "--reason", "<為什麼還沒解決>")):
        rc, out = _df_fix(v, "Issues/K", "3", "--kind", "c2", *args)
        check(f"②{args[0]} 照抄提示的佔位字:回 2", rc == 2 and "佔位字" in out and K.read_bytes() == kraw and not acks.exists(), out)
    r = run(v, "drift", "ack", "Issues/K", "3", "--kind", "c2", "--reason", "<為什麼照留>")
    check("②drift ack 照抄佔位字:回 2", r.returncode == 2 and "佔位字" in r.stderr and not acks.exists(), r.stdout + r.stderr)
    h = m._drift_fix_hint("c2", "Issues/a$(touch pwned).md", 3)[0]
    h2 = m._drift_fix_hint("c3", "Issues/有 空白.md", 3)[0]
    h3 = m._drift_fix_hint("c2", "Issues/linter-gap實務隱患.md", 3)[0]
    import shlex as _shlex
    check("③檔名帶 $(…)、空白:印出的指令照貼切得回同一個節點", _shlex.split(h)[3] == "Issues/a$(touch pwned)"
          and _shlex.split(h2)[3] == "Issues/有 空白", h + " | " + h2)
    check("③一般中文檔名不加引號", h3.startswith("lumos drift fix Issues/linter-gap實務隱患 3 "), h3)
    rc, out = _df_fix(v, "Issues/F", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "這次真的修好了")
    tf = (v / "Issues" / "F.md").read_text(encoding="utf-8")
    check("⑤正文開頭是「已結案…」的一般句子:照樣加橫幅", rc == 0 and "> 已結案(" in tf
          and tf.index("> 已結案(") < tf.index("已結案通知功能"), out + tf)
    rc, out = _df_fix(v, "Issues/C", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "這次真的修好了")
    tc = (v / "Issues" / "C.md").read_text(encoding="utf-8")
    check("⑤沒有標題、圍欄裡有 # comment:橫幅不插進圍欄", rc == 0 and "```\n# comment\n```" in tc
          and tc.index("> 已結案(") < tc.index("```"), out + tc)
    rows = m._drift_jsonl_parse('{"a": "x\u2028y"}\n{"b": 1}\n壞行\n'.encode("utf-8"))
    check("⑥帳檔一筆含 U+2028:讀得回來", len(rows) == 2 and rows[0]["a"] == "x\u2028y", str(rows))
    gov = root / "governance"
    gov.mkdir(exist_ok=True)
    real = root.parent / (root.name + "-gov-real")
    real.mkdir()
    (real / "drift-fixes.jsonl").write_text("", encoding="utf-8")
    fx = gov / "drift-fixes.jsonl"
    if fx.exists():
        fx.unlink()
    _os.symlink(real / "drift-fixes.jsonl", fx)
    W = V / "W.md"
    wraw = W.read_bytes()
    rc, out = _df_fix(v, "Verification/W", "3", "--kind", "c3", "--status", "pass")
    check("⑦修復帳是符號連結:寫筆記之前就擋、筆記沒動", rc == 2 and "符號連結" in out and W.read_bytes() == wraw, out)
    fx.unlink()
    (v / "Issues" / "Real.md").write_text("---\ntype: issue\nstatus: open\n---\n# R\n[[Projects/Done_計劃]]\n", encoding="utf-8")
    _os.symlink("Real.md", v / "Issues" / "Lnk.md")
    _df_commit(root, "link")
    rc, out = _df_fix(v, "Issues/Lnk", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "已經修好了喔")
    check("⑧被修的筆記是符號連結:回 2、連結還在", rc == 2 and "符號連結" in out and (v / "Issues" / "Lnk.md").is_symlink(), out)
    rc, out = _df_fix(v, "Verification/W", "3", "--kind", "c3", "--status", "pass", env={"LUMOS_DRIFT_FIX_FAULT": "moved"})
    check("⑨驗證之後、記帳之前被改:回 2、不記帳", rc == 2 and "又被別人改了" in out
          and not any(x["path"].endswith("Verification/W.md") for x in _df_rows(root)), out)
    _df_commit(root, "after moved")
    (V / "Q.md").write_text((V / "Q.md").read_text(encoding="utf-8") + "未提交的一行\n", encoding="utf-8")
    rc, out = _df_fix(v, "Verification/Q", "5", "--kind", "c4")
    check("⑩c4 只列證據:筆記有未提交改動也照列、回 0", rc == 0 and "只列出、不寫檔" in out, out)
    r2 = _dr_repo()
    _nh_node(r2, "Pay", summary=_DF_PAY + "\nKEY:★INVARIANT★ 合約辛沒綁測試")
    _nh_node(r2, "Done_計劃", typ="project", folder="Projects", resp=None, status="done", summary="KEY:d")
    v2 = r2 / _DR_VAULT
    (v2 / "Verification" / "G8.md").write_text(_dr_guard_text("pass", claim="合約辛沒綁測試"), encoding="utf-8")
    _df_commit(r2, "g8", "2026-09-20")
    g8 = [f["line"] for f in _df_find(v2, "c1", "Verification/G8.md")]
    graw = (v2 / "Verification" / "G8.md").read_bytes()
    rc, out = _df_fix(v2, "Verification/G8", str(min(g8)), "--kind", "c1", "--date", "2026-09-10")
    check("⑪家節點有這條合約的正式行、但沒綁測試:回 2、不寫", g8 and rc == 2 and "綁了測試的正式行" in out
          and (v2 / "Verification" / "G8.md").read_bytes() == graw, out)
    rc, out = _df_fix(v, "Issues/K", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "修好了\u2028提交 abc")
    check("⑫fix --reason 含 U+2028:回 2、不寫", rc == 2 and K.read_bytes() == kraw, out)
    r = run(v, "drift", "ack", "Issues/K", "3", "--kind", "c2", "--reason", "還沒解決\u2028等上游")
    check("⑫drift ack --reason 含 U+2028:回 2", r.returncode == 2 and not acks.exists(), r.stdout + r.stderr)
    import types as _ty, tempfile as _tf
    td = Path(_tf.mkdtemp())
    A, B = td / "A.md", td / "B.md"
    A.write_text("---\nstatus: pending\n---\n", encoding="utf-8")
    B.write_text("家節點改過了\n", encoding="utf-8")
    cx = {"path": A, "raw": A.read_bytes()}
    res = {"new": ["---", "status: pass", "---", ""], "key": "status", "check": lambda f: True, "deps": [(B, "判定當時\n".encode())]}
    err = m._drift_fix_write(_ty.SimpleNamespace(vault=td), cx, res)
    check("⑬判定依賴的家節點在寫入前被改過:不寫", err and "被改過" in err and "status: pending" in A.read_text(encoding="utf-8"), str(err))
    import unicodedata as _ud
    (td / "Issues").mkdir()
    nfd = _ud.normalize("NFD", "café.md")
    (td / "Issues" / nfd).write_text("內容\n", encoding="utf-8")
    nfc_rel = "Issues/" + _ud.normalize("NFC", "café.md")
    if (td / nfc_rel).exists():
        print("  ⚠ ⑭跳過:這個檔案系統不分 NFC/NFD(macOS),逐層找的那段走不到;Linux CI 上才驗得到")
    else:
        got = m._phys_path(td, nfc_rel)
        check("⑭索引鍵是 NFC、磁碟上是 NFD:找得到實際的檔", got.read_text(encoding="utf-8") == "內容\n", str(got))
    rc, out = _df_fix(v, "Verification/X", "3", "--kind", "c3", "--status", "pass", env={"LUMOS_DRIFT_FIX_FAULT": "verify"})
    check("⑮驗證失敗:回 2,講明 git checkout 會連同這篇之前沒提交的工具修改一起退掉", rc == 2 and "一起退掉" in out
          and "checkout --" in out, out)


def t_drift_fix_review_r2_edges():
    """代碼審 r2 折入(存量漂移改法):c4 只看換完的結果——--old 連引號一起框、行內清單、換完成了 YAML 標記都擋;
    計劃收尾「看:」那行也加引號;認得本專案真實的結案橫幅寫法;佔位字只認提示真的印過的那幾種;c1、c5 把家節點放進寫入前的比對;
    - 開頭的節點提示印成 ./ 開頭而且 drift fix 認得;git 指令用 git 裡的原樣路徑。

    翻紅釘:「看:」那行拿掉 _drift_sh → ②紅;橫幅正則改回只認 > 與 ** → ③紅;
    佔位字正則改回任意 <…> → ④紅;_drift_fix_c1 或 _drift_fix_c5 的 deps 改成空的 → ⑤紅;_drift_sh 拿掉 node 的 ./ → ⑥紅;
    _drift_fix_target 不認 ./ → ⑥fix 那格紅;_drift_git_cmd 改回索引鍵 → ⑦紅。
    """
    print("t_drift_fix_review_r2_edges")
    import shlex as _shlex, contextlib, io
    root = _df_repo()
    v = root / _DR_VAULT
    V = v / "Verification"
    (V / "Q2.md").write_text('---\ntype: verification\nstatus: pass\nvalid_under:\n  - "本工作樹(未提交)"\n  - 甲(未提交)\n---\n# Q2\n',
                             encoding="utf-8")
    (V / "Q3.md").write_text("---\ntype: verification\nstatus: pass\nvalid_under:\n  - '本工作樹(未提交)'\n---\n# Q3\n", encoding="utf-8")
    (V / "Q4.md").write_text("---\ntype: verification\nstatus: pass\nvalid_under: [本工作樹(未提交), 乙]\n---\n# Q4\n", encoding="utf-8")
    for n, first in (("B1", "> ## ✅ 已結案(2026-08-22)— 舊橫幅"), ("B2", "> ✅ **已結案(2026-09-21)**:舊橫幅"),
                     ("B3", "**★已結案(2026-09-01)★** 舊橫幅")):
        _nh_file(root, f"{_DR_VAULT}/Issues/{n}.md", f"---\ntype: issue\nstatus: open\n---\n# {n}\n\n{first}\n\n[[Projects/Done_計劃]]\n")
    _nh_file(root, f"{_DR_VAULT}/Issues/K.md", "---\ntype: issue\nstatus: open\n---\n# K\n[[Projects/Done_計劃]]\n")
    _nh_file(root, f"{_DR_VAULT}/-x.md", "---\ntype: issue\nstatus: open\n---\n# X\n[[Projects/Done_計劃]]\n")
    _nh_node(root, "Open_計劃", typ="project", folder="Projects", resp=None, status="doing", summary="KEY:o")
    _nh_file(root, f"{_DR_VAULT}/Issues/a$(touch PWNED).md", "---\ntype: issue\nstatus: open\n---\n# A\n[[Projects/Open_計劃]]\n")
    (V / "G.md").write_text(_dr_guard_text("pass"), encoding="utf-8")
    _df_commit(root, "r2 edges", "2026-09-20")
    r = run(v, "set", "Projects/Open_計劃", "status", "done")
    look = [ln.split("看:", 1)[1] for ln in r.stdout.splitlines() if "看:" in ln and "touch PWNED" in ln]
    check("②計劃收尾「看:」那行加了引號:照貼切得回同一個節點", look and _shlex.split(look[0])[2] == "Issues/a$(touch PWNED)",
          r.stdout[-600:])
    for n in ("B1", "B2", "B3"):
        rc, out = _df_fix(v, f"Issues/{n}", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "這次真的修好了")
        t = (v / "Issues" / f"{n}.md").read_text(encoding="utf-8")
        check(f"③{n} 已有本專案寫法的結案橫幅:不再疊一個", rc == 0 and t.count("已結案") == 1 and "沒再加" in out, out + t)
    r = run(v, "drift", "ack", "Issues/K", "3", "--kind", "c2", "--reason", "等 Map<K,V> 泛型那支修好再結案")
    check("④理由裡有 Map<K,V> 這種真的角括號:照收", r.returncode == 0, r.stdout + r.stderr)
    m = _load_lumos_inproc()
    seen = []
    orig = m._drift_fix_write
    m._drift_fix_write = lambda env, cx, res: (seen.append([p.name for p, _b in res.get("deps", [])]), orig(env, cx, res))[1]
    try:
        buf = io.StringIO()
        ln = min(f["line"] for f in _df_find(v, "c1", "Verification/G.md"))
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = m.cmd_drift_fix(m.Env(v), "Verification/G", ln, "c1",
                                 {"dry_run": False, "date": "2026-09-10", "close": False, "keep": False, "status": None,
                                  "reason": None, "by": None, "old": None, "new": None})
    finally:
        m._drift_fix_write = orig
    check("⑤c1 寫入前的比對含家節點 Pay", rc == 0 and seen and "Pay.md" in seen[0], buf.getvalue() + str(seen))
    h = m._drift_fix_hint("c2", "-x.md", 3)[0]
    check("⑥- 開頭的節點:提示印成 ./-x", _shlex.split(h)[3] == "./-x", h)
    rc, out = _df_fix(v, "./-x", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "這次真的修好了")
    check("⑥drift fix 認得 ./-x", rc == 0 and "status: done" in (v / "-x.md").read_text(encoding="utf-8"), out)
    orig_g = m._git_paths_nfc
    m._git_paths_nfc = lambda r, p: ["docs/x/Issues/cafe\u0301.md"]
    try:
        g = m._drift_git_cmd({"root": str(root), "repo_rel": "docs/x/Issues/caf\u00e9.md"}, "checkout --")
    finally:
        m._git_paths_nfc = orig_g
    check("⑦git 指令用 git 裡的原樣拼法(NFD)", _shlex.split(g)[-1] == "docs/x/Issues/cafe\u0301.md", repr(g))


def t_drift_fix_review_r3_edges():
    """代碼審 r3 折入(存量漂移改法):c4 整項換掉的邊界(帶行尾註解、值跨行、冒號後沒空白的單行值);git 指令不截斷、
    加 --literal-pathspecs、路徑含控制字元不印可照貼的指令、三處印指令的接線都走原樣路徑;同名兩種 Unicode 拼法並存不動手;
    ./ 開頭一律當明確路徑、一般查找也認得;計劃收尾「看:」對 - 開頭補 ./;<src/lib> 這種真理由照收。

    翻紅釘:_drift_git_cmd 截斷或拿掉 --literal-pathspecs → ②紅;
    成功訊息改回用索引鍵 → ②接線那格紅;拿掉控制字元判斷 → ②控制字元那格紅;拿掉兩種拼法的檢查 → ③紅;
    _drift_fix_target 的 ./ 改回用檔名猜 → ④紅;Env.find 不剝 ./ → ④ context 那格紅;「看:」不帶 node=True → ⑤紅;
    佔位字正則加回「小寫/小寫」→ ⑥紅。
    """
    print("t_drift_fix_review_r3_edges")
    import shlex as _shlex, contextlib, io
    root = _df_repo()
    v = root / _DR_VAULT
    V = v / "Verification"
    (V / "C1.md").write_text('---\ntype: verification\nstatus: pass\nvalid_under:\n  - "本工作樹(未提交)" # 註解\n---\n# C1\n',
                             encoding="utf-8")
    (V / "C2.md").write_text("---\ntype: verification\nstatus: pass\nvalid_under:\n  - 本工作樹(未提交)\n    接續的一行\n---\n# C2\n",
                             encoding="utf-8")
    (V / "C3.md").write_text("---\ntype: verification\nstatus: pass\nvalid_under: a 本工作樹(未提交)\n---\n# C3\n", encoding="utf-8")
    write(v, "Verification/W2.md", 'type: verification\nstatus: pending\nplan_refs:\n  - "[[Projects/Done_計劃]]"', body="# W2\n")
    for p in ("-x.md", "Issues/-x.md"):
        _nh_file(root, f"{_DR_VAULT}/{p}", "---\ntype: issue\nstatus: open\n---\n# X\n[[Projects/Done_計劃]]\n")
    _nh_node(root, "Open_計劃", typ="project", folder="Projects", resp=None, status="doing", summary="KEY:o")
    _nh_file(root, f"{_DR_VAULT}/-y.md", "---\ntype: issue\nstatus: open\n---\n# Y\n[[Projects/Open_計劃]]\n")
    _nh_file(root, f"{_DR_VAULT}/Issues/K.md", "---\ntype: issue\nstatus: open\n---\n# K\n[[Projects/Done_計劃]]\n")
    for p in ("-d/z.md", "Issues/z.md"):
        _nh_file(root, f"{_DR_VAULT}/{p}", f"---\ntype: issue\nstatus: open\n---\n# {p}\n")
    _df_commit(root, "r3 edges")
    m = _load_lumos_inproc()
    long = "docs/" + "a" * 145 + "/" + "b" * 145 + " x.md"
    orig_p = m._git_paths_nfc
    try:
        m._git_paths_nfc = lambda r, p: [long]
        g = m._drift_git_cmd({"root": str(root), "repo_rel": "x"}, "checkout --")
        check("②長路徑不截斷、加 --literal-pathspecs", _shlex.split(g) == ["git", "--literal-pathspecs", "checkout", "--", long], g)
        m._git_paths_nfc = lambda r, p: ["docs/a\x1bb.md"]
        check("②路徑含控制字元:不印可照貼的指令", m._drift_git_cmd({"root": str(root), "repo_rel": "x"}, "checkout --") is None
              and "控制字元" in m._drift_git_hint({"root": str(root), "repo_rel": "x"}, "checkout --"), "")
        m._git_paths_nfc = lambda r, p: [f"{_DR_VAULT}/Verification/W2\u0301.md"]
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = m.cmd_drift_fix(m.Env(v), "Verification/W2", 3, "c3",
                                 {"dry_run": False, "date": None, "close": False, "keep": False, "status": "pass",
                                  "reason": None, "by": None, "old": None, "new": None})
        check("②成功訊息的 git add 走 git 原樣路徑", rc == 0 and "W2\u0301.md" in buf.getvalue()
              and "git --literal-pathspecs add governance/drift-fixes.jsonl" in buf.getvalue(), buf.getvalue())
        m._git_paths_nfc = lambda r, p: ["docs/k/Issues/caf\u00e9.md", "docs/k/Issues/cafe\u0301.md"]
        err = m._drift_fix_clean_err(str(root), "docs/k/Issues/caf\u00e9.md", b"x")
        check("③同名兩種 Unicode 拼法並存:乾淨檢查擋下", err and "Unicode 拼法" in err, str(err))
    finally:
        m._git_paths_nfc = orig_p
    rc, out = _df_fix(v, "./-x", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "這次真的修好了")
    check("④./-x 就是根目錄那篇,不因為 Issues/-x 同名被擋", rc == 0 and "status: done" in (v / "-x.md").read_text(encoding="utf-8")
          and "status: open" in (v / "Issues" / "-x.md").read_text(encoding="utf-8"), out)
    r = run(v, "context", "./-d/z", "--brief")
    check("④一般查找也認得 ./ 開頭:./-d/z 就是那一篇,不退回用檔名猜(沒有同名警告)", r.returncode == 0
          and "同名筆記" not in r.stderr and "-d/z" in r.stdout, r.stdout[-300:] + r.stderr[-300:])
    r = run(v, "set", "Projects/Open_計劃", "status", "done")
    look = [ln.split("看:", 1)[1] for ln in r.stdout.splitlines() if "看:" in ln and "-y" in ln]
    check("⑤計劃收尾「看:」對 - 開頭的節點補 ./", look and _shlex.split(look[0])[2] == "./-y", r.stdout[-600:])
    r = run(v, "drift", "ack", "Issues/K", "3", "--kind", "c2", "--reason", "改用 <src/lib> 的新寫法,見提交 abc123")
    check("⑥理由裡有 <src/lib> 這種路徑:照收", r.returncode == 0, r.stdout + r.stderr)


def t_drift_fix_review_r4_edges():
    """代碼審 r4 折入(存量漂移改法):./ 開頭在一般查找找不到就是找不到、不退回用檔名猜(不會寫到別篇);乾淨檢查的 git diff
    不把檔名當萬用字元;合併衝突中 git ls-files 同一路徑列好幾次算一筆;列 git 原樣路徑收成一支(guard 與 drift 共用)。

    翻紅釘:Env.find 的 explicit 找不到改回退用檔名猜 → ①紅;乾淨檢查拿掉 --literal-pathspecs → ②紅;_git_paths_nfc 不去重 → ③紅;
    _guard_raw_git_path 改回自己掃 → ④紅。
    """
    print("t_drift_fix_review_r4_edges")
    root = _df_repo()
    v = root / _DR_VAULT
    _nh_file(root, f"{_DR_VAULT}/A/z.md", "---\ntype: issue\nstatus: open\n---\n# z\n")
    _nh_file(root, f"{_DR_VAULT}/Issues/q*.md", "---\ntype: issue\nstatus: open\n---\n# Q\n[[Projects/Done_計劃]]\n")
    _nh_file(root, f"{_DR_VAULT}/Issues/qz.md", "---\ntype: issue\nstatus: open\n---\n# QZ\n")
    _df_commit(root, "r4 edges")
    az = (v / "A" / "z.md").read_bytes()
    r = run(v, "set", "./z", "status", "done")
    check("①./z 在根目錄不存在:不退回用檔名猜、A/z 沒被改", r.returncode != 0 and (v / "A" / "z.md").read_bytes() == az,
          r.stdout + r.stderr)
    qz = v / "Issues" / "qz.md"
    qz.write_text(qz.read_text(encoding="utf-8") + "別篇沒提交的改動\n", encoding="utf-8")
    rc, out = _df_fix(v, "Issues/q*", "3", "--kind", "c2", "--close", "--status", "done", "--reason", "這次真的修好了")
    check("②檔名帶 *:乾淨檢查只看這一篇,別篇沒提交的改動不會害它被擋", rc == 0
          and "status: done" in (v / "Issues" / "q*.md").read_text(encoding="utf-8"), out)
    m = _load_lumos_inproc()
    orig = m._nodehome_git
    try:
        m._nodehome_git = lambda r, *a: b"docs/k/Issues/a.md\0docs/k/Issues/a.md\0docs/k/Issues/a.md\0"
        check("③合併衝突中同一路徑列三次:算一筆", m._git_paths_nfc("x", "docs/k/Issues/a.md") == ["docs/k/Issues/a.md"], "")
        check("④guard 那支走同一個共用函式", m._guard_raw_git_path("x", "docs/k/Issues/a.md") == "docs/k/Issues/a.md", "")
        seen = []
        orig_p = m._git_paths_nfc
        m._git_paths_nfc = lambda r, p: (seen.append(p), ["docs/k/x.md"])[1]
        m._guard_raw_git_path("x", "docs/k/x.md")
        check("④_guard_raw_git_path 呼叫 _git_paths_nfc", seen == ["docs/k/x.md"], str(seen))
        m._git_paths_nfc = orig_p
    finally:
        m._nodehome_git = orig


def t_drift_fix_c5_completes_settle():
    """[S12] c5:從家節點正式行讀出測試名、只改守衛紀錄轉成 pass(跟 settle 第二步同一支算內容),不需要人給 --test;
    家節點還留著重複預告行時擋下。

    翻紅釘:c5 不走 _guard_settle_record_lines → ④紅;測試名改成要人給 → ②「取第一支」紅;拿掉家節點預告行的檢查 → ③紅;
    c5 順手改了家節點 → ②「家節點沒動」紅;_drift_fix_c5 的 deps 改成空的 → ②「比對含家節點」紅。
    """
    print("t_drift_fix_c5_completes_settle")
    import datetime
    today = datetime.date.today().isoformat()
    root = _df_repo()
    v = root / _DR_VAULT
    V = v / "Verification"
    _nh_node(root, "Pay", summary="KEY:★INVARIANT★ 大額退費要人工核可 [test:t_refund,t_extra]\n"
             "KEY:★INVARIANT★ 合約乙 [test:t_b]\nKEY:★INVARIANT-PLANNED★ 合約乙 [watch:Verification/G2] [due:2099-12-31]")
    (V / "G.md").write_text(_dr_guard_text("pending"), encoding="utf-8")
    (V / "G2.md").write_text(_dr_guard_text("pending", claim="合約乙"), encoding="utf-8")
    _df_commit(root, "c5 cases")
    pay = (v / "Systems" / "Pay.md").read_bytes()
    fs = _df_find(v, "c5", "Verification/G.md")
    check("①前置:G 是 c5(家節點已是正式行、守衛紀錄還 pending)", len(fs) == 1, str(fs))
    rc, out = _df_fix(v, "Verification/G", str(fs[0]["line"]), "--kind", "c5", "--status", "pass")
    check("①c5 不收參數", rc == 2 and "不收" in out, out)
    m = _load_lumos_inproc()
    calls, deps = [], []
    orig = m._guard_settle_record_lines
    m._guard_settle_record_lines = lambda *a, **k: (calls.append(a), orig(*a, **k))[1]
    orig_w = m._drift_fix_write
    m._drift_fix_write = lambda env, cx, res: (deps.append([p.name for p, _b in res.get("deps", [])]), orig_w(env, cx, res))[1]
    try:
        import contextlib, io
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = m.cmd_drift_fix(m.Env(v), "Verification/G", fs[0]["line"], "c5",
                                 {"dry_run": False, "date": None, "close": False, "keep": False, "status": None,
                                  "reason": None, "by": None, "old": None, "new": None})
    finally:
        m._guard_settle_record_lines = orig
        m._drift_fix_write = orig_w
    check("②寫入前的比對含家節點 Pay(代碼審 r2:原本拿掉這條接線測試照樣綠)", deps and "Pay.md" in deps[0], str(deps))
    t = (V / "G.md").read_text(encoding="utf-8")
    check("②轉成 pass、標籤同步、預告句改成歷史說法(日期今天)", rc == 0 and "status: pass" in t and "status/pass" in t
          and f"TEST:[{today}] 預告已轉正" in t and "做完之後跑" not in t, buf.getvalue() + t)
    check("②測試名從家節點正式行讀、好幾支取第一支並寫出來;家節點沒動", "t_refund" in buf.getvalue() and "取第一支" in buf.getvalue()
          and (v / "Systems" / "Pay.md").read_bytes() == pay, buf.getvalue())
    rows = _df_rows(root)
    check("②修復帳記下用了哪一支測試", rows and rows[-1]["kind"] == "c5" and rows[-1]["test"] == "t_refund", str(rows))
    check("②c5、c1 都消失", not _df_find(v, "c5", "Verification/G.md") and not _df_find(v, "c1", "Verification/G.md"), "")
    fs2 = _df_find(v, "c5", "Verification/G2.md")
    raw2 = (V / "G2.md").read_bytes()
    rc, out = _df_fix(v, "Verification/G2", str(fs2[0]["line"]) if fs2 else "3", "--kind", "c5")
    check("③家節點同時有預告行與正式行:回 2、說先手動刪預告行", fs2 and rc == 2 and "先手動刪掉預告行" in out
          and (V / "G2.md").read_bytes() == raw2 and (v / "Systems" / "Pay.md").read_bytes() == pay, out)
    check("④跟 settle 第二步同一支算內容(_guard_settle_record_lines)", len(calls) == 1, str(len(calls)))


# ═══ 舊句檢查 m1(Projects/舊句檢查_計劃;條款 [S1] 到 [S18] 一條一支)═══

_M1_VAULT = "docs/kg-knowledge"


class _M1Home:
    """把 HOME 換成一個乾淨的暫存目錄(定義快取與漏記痕跡都在 ~/.cache/lumos 底下,測試不碰真的家目錄)。"""

    def __init__(self, home=None):
        self.home = Path(home) if home else Path(tempfile.mkdtemp(prefix="gctl-m1home-"))

    def __enter__(self):
        import os as _o
        self.old = _o.environ.get("HOME")
        _o.environ["HOME"] = str(self.home)
        return self.home

    def __exit__(self, *a):
        import os as _o
        if self.old is None:
            _o.environ.pop("HOME", None)
        else:
            _o.environ["HOME"] = self.old


def _m1_note(root, rel, body, about=(), summary=None, typ="system", raw=None):
    """直接寫一篇筆記(圖譜內路徑 rel);raw 給了就整篇照寫(位元組或文字)。"""
    p = root / _M1_VAULT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    if raw is not None:
        (p.write_bytes if isinstance(raw, bytes) else lambda t: p.write_text(t, encoding="utf-8"))(raw)
        return p
    fm = [f"type: {typ}", "status: doing"]
    if about:
        fm += ["about_code:"] + [f"  - {a}" for a in about]
    if summary is not None:
        fm += ["summary: |-"] + ["  " + x for x in summary.split("\n")]
    p.write_text("---\n" + "\n".join(fm) + "\n---\n" + body + "\n", encoding="utf-8")
    return p


def _m1_lno(root, rel, needle):
    lines = (root / _M1_VAULT / rel).read_text(encoding="utf-8-sig").split("\n")
    return next(i + 1 for i, ln in enumerate(lines) if needle in ln)


def _m1_commit(root, msg="c"):
    _nh_commit(root, msg)
    return _na_head(root)


def _m1_check(root, base, tip, home=None, now=None, deadline=None):
    """在行程內跑判定本體(HOME 換掉;列檔的行程內記憶清掉,每次都像新的推送)。"""
    import time as _t
    m = _load_lumos_inproc()
    m._DRIFT_LS_CACHE.clear()
    m._DRIFT_OID_CACHE.clear()
    kw = {} if now is None else {"now": now}
    with _M1Home(home):
        return m._drift_old_sentence_check(Path(root), base, tip, _M1_VAULT,
                                           deadline if deadline is not None else _t.monotonic() + 600, **kw)


def _m1_hits(res):
    return {(f["path"], f["line"], f["layer"], tuple(f["names"])) for f in res["handle"] + res["listed"]}


def _m1_run(root, rng, home=None, env=None):
    e = {"HOME": str(home or tempfile.mkdtemp(prefix="gctl-m1home-"))}
    e.update(env or {})
    return _dr(root, "check", "--diff", rng, env=e)


def _gov_events_all(docs_dir):
    """版控帳與本機帳(例行觀察,治理帳例行紀錄分流_計劃)合起來、依時間排序的事件——
    驗「這筆有沒有記下來」用;驗「記在哪一本」的是 t_gov_split_* 那幾支。排序照 lumos 的 _gov_ledger_rows_by_time。"""
    return _load_lumos()._gov_ledger_rows_by_time(Path(docs_dir))


def _gov_since(after, before):
    """after 比 before 多出來的事件(多重集合差,保留 after 的順序)。兩本帳依時間合併後,同一秒寫進不同本的事件
    先後不固定,不能用「先數筆數、再取第 N 筆以後」抓新事件。"""
    import json as _j
    left = {}
    for e in before:
        k = _j.dumps(e, sort_keys=True, ensure_ascii=False)
        left[k] = left.get(k, 0) + 1
    out = []
    for e in after:
        k = _j.dumps(e, sort_keys=True, ensure_ascii=False)
        if left.get(k):
            left[k] -= 1
        else:
            out.append(e)
    return out


def _m1_events(root):
    return [d for d in _gov_events_all(root / "docs") if d.get("check") == "old-sentence"]


def _m1_res(state="done", cand=3, handle=(), listed=(), **kw):
    r = {"state": state, "handle": list(handle), "listed": list(listed), "unparsable": [], "text_defs": [],
         "bad_notes": 0, "bad_touched": 0, "code_files": 2, "other_files": 0, "candidates": cand, "too_long": 0,
         "parsed": 0, "cache_hits": 0, "gone": {}, "long_lines": 0, "error": None}
    r.update(kw)
    return r


def _m1_f(path, line, names, layer="handle", text=None):
    return {"kind": "m1", "path": path, "line": line, "text": text or ("呼叫 " + " 與 ".join(names)),
            "why": "消失的名稱:" + "、".join(f"`{n}`(原本在 src/a.py)" for n in names), "names": list(names), "layer": layer}


def _m1_report(res, mode, root=None, base="a" * 40, tip="b" * 40):
    """行程內跑 _drift_m1_report,回 (rc, stderr)。root 不給就用一個沒有 docs/ 的暫存目錄(不寫帳)。"""
    import contextlib, io
    m = _load_lumos_inproc()
    buf = io.StringIO()
    with contextlib.redirect_stderr(buf), _M1Home():
        rc = m._drift_m1_report(Path(root or tempfile.mkdtemp(prefix="gctl-m1rep-")), mode, base, tip, _M1_VAULT, res)
    return rc, buf.getvalue()


def t_drift_m1_disappeared_names():
    """[S1] 起點有、終點語料(排除清單照參考實作、含測試檔)的所有 Python 檔都沒定義 → 消失。
    搬到別支檔、搬進 tests/ 都不算;只剩 governance/ 或 build/ 還定義著算;只改 governance/ 底下的檔不抽候選。

    翻紅釘:終點語料拿掉 tests/(照 probe 的只看產品碼)→ ③紅;不查終點語料(只比同一支檔)→ ②紅;
    governance/ 算進語料 → ④紅。
    """
    print("t_drift_m1_disappeared_names")
    root = _nh_repo()
    names = ["foo_bar", "moved_to_test", "only_in_gov", "only_in_build", "truly_gone_x"]
    _nh_file(root, "src/a.py", "".join(f"def {n}():\n    pass\n\n" for n in names))
    _nh_file(root, "src/b.py", "x = 1\n")
    _nh_file(root, "tests/test_x.py", "def t_ok():\n    pass\n")
    _nh_file(root, "governance/eval/x.py", "def gov_only_def():\n    pass\n")
    _m1_note(root, "Systems/A.md", "# A\n" + "\n".join(f"用 {n} 做事" for n in [*names, "gov_only_def"]))
    base = _m1_commit(root, "base")
    _nh_file(root, "src/a.py", "y = 2\n")
    _nh_file(root, "src/b.py", "def foo_bar():\n    pass\n")
    _nh_file(root, "tests/test_x.py", "def t_ok():\n    pass\n\ndef moved_to_test():\n    pass\n")
    _nh_file(root, "governance/eval/x.py", "def gov_only_def():\n    pass\n\ndef only_in_gov():\n    pass\n")
    _nh_file(root, "build/x.py", "def only_in_build():\n    pass\n")
    tip = _m1_commit(root, "move")
    res = _m1_check(root, base, tip)
    check("①前置:判完、改到的程式檔算到 3 支(build/、governance/ 不算)", res["state"] == "done" and res["code_files"] == 3,
          str(res))
    gone = set(res["gone"])
    check("②搬到 b.py 不算消失", "foo_bar" not in gone, str(gone))
    check("③搬進 tests/test_x.py 定義也不算(終點語料含測試檔)", "moved_to_test" not in gone, str(gone))
    check("④只剩 governance/eval/x.py 或 build/x.py 還定義著 → 算消失", {"only_in_gov", "only_in_build", "truly_gone_x"} <= gone,
          str(gone))
    listed = {n for f in res["handle"] + res["listed"] for n in f["names"]}
    check("④筆記提到的消失名稱都列出、沒消失的不列", listed == {"only_in_gov", "only_in_build", "truly_gone_x"}, str(listed))
    _nh_file(root, "governance/eval/x.py", "def only_in_gov():\n    pass\n")
    tip2 = _m1_commit(root, "gov only")
    res2 = _m1_check(root, tip, tip2)
    check("⑤改到的只有 governance/ 底下的檔:不抽候選、不印不記(state 是 None)", res2["state"] is None
          and res2["candidates"] is None and not res2["gone"], str(res2))


def t_drift_m1_history_filters():
    """[S2] 撤除節(①節開頭撤除行;②節內 > 開頭、同一行含撤除字樣與範圍宣告字)與名稱所在那一句的 54 個歷史字眼 → 不列。

    翻紅釘:②不要求範圍宣告字(P4r2)→ ③golden 那節紅;拿掉 NOT_YET → ④紅;括號外不先遮括號對 → ⑤第一句紅;
    英文句點也切 → ⑥紅;字眼表少一個 → ⑨紅。
    """
    print("t_drift_m1_history_filters")
    m = _load_lumos_inproc()
    root = _nh_repo()
    gone = ["gone_alpha", "gone_beta", "gone_gamma", "gone_delta", "gone_eps", "gone_zeta", "gone_eta", "gone_theta",
            "gone_iota", "gone_kappa", "gone_lambda", "gone_mu"]
    _nh_file(root, "src/a.py", "".join(f"def {n}():\n    pass\n" for n in gone))
    body = "\n".join([
        "# A", "", "## 寫檔版", "說明", "> 下面凡是講 --restore 的段落都是寫檔版的歷史紀錄", "呼叫 gone_alpha 做事", "",
        "## golden", "說明", "> golden 已凍結,別改它", "呼叫 gone_beta 做事", "",
        "## 還沒", "說明", "> 尚未撤除,下面照舊", "呼叫 gone_gamma 做事", "",
        "## 開頭撤除", "(本節已作廢)", "呼叫 gone_delta 做事", "",
        "## 句子", "現況:gone_eps 還在用(含 (內) 曾改過)", "gone_zeta 還在用。原本叫 x", "現況(原本叫 x。gone_eta 還在用)",
        "(說明 gone_theta 還在 (x", "Removed in v2: gone_iota", "呼叫 gone_kappa 算錢", "old style removed. gone_lambda is used now",
        "gone_mu 還在"])
    _m1_note(root, "Systems/A.md", body)
    base = _m1_commit(root, "base")
    _nh_file(root, "src/a.py", "z = 1\n")
    tip = _m1_commit(root, "del")
    res = _m1_check(root, base, tip)
    got = {n for f in res["handle"] + res["listed"] for n in f["names"]}
    check("①前置:判完、12 個名稱都是候選", res["state"] == "done" and res["candidates"] == 12, str(res))
    check("②> 下面…歷史紀錄 之後的行不列", "gone_alpha" not in got, str(got))
    check("③> golden 已凍結(沒有範圍宣告字)之後照列", "gone_beta" in got, str(got))
    check("④> 尚未撤除 不算撤除行", "gone_gamma" in got, str(got))
    check("④節開頭的撤除行(括號)整節不看", "gone_delta" not in got, str(got))
    check("⑤外層括號的「曾」跟名稱同一段 → 不列", "gone_eps" not in got, str(got))
    check("⑤句號切開 → 照列;括號裡也照句號切 → 照列", {"gone_zeta", "gone_eta"} <= got, str(got))
    check("⑤沒關上的 ( 在名稱後面 → 當括號外、照列", "gone_theta" in got, str(got))
    check("⑥ASCII 字眼大小寫敏感(Removed)→ 照列;英文句點不切(removed 同一句)→ 不列", "gone_iota" in got
          and "gone_lambda" not in got, str(got))
    check("⑦含「呼叫」的句子不因此被放過", "gone_kappa" in got and "gone_mu" in got, str(got))
    want = ("零命中", "已移除", "不存在", "查無", "已刪", "從未", "已退役", "移除", "無此", "原記", "舊名", "改名", "已改", "棄用",
            "不使用", "廢棄", "停用", "未使用", "dead", "removed", "deleted", "no longer", "renamed", "deprecated", "unused",
            "obsolete", "撤除", "撤掉", "拿掉", "原寫", "原本", "原先", "不再", "舊版", "舊的", "刪除", "刪掉", "取代", "搬到",
            "搬去", "改為", "改叫", "改成", "曾", "前身", "撤", "刪", "拔掉", "去掉", "不帶", "沒有", "當時叫", "擴成", "改名為")
    check("⑧字眼表逐字 54 個,不引用 NEG_LEXICONS", m._DRIFT_M1_HIST_WORDS == want and len(set(want)) == 54, "")
    bad = [w for w in want if not m._drift_m1_clause_hist(f"x {w} gone_q", len(f"x {w} "))]
    check("⑨54 個字眼逐項:跟名稱同一句就不列", not bad, str(bad))
    check("⑨「呼叫」「叫」不是字眼", not m._drift_m1_clause_hist("呼叫 gone_q", 3) and not m._drift_m1_clause_hist("叫 gone_q", 2),
          "")
    # 代碼審 r1 spec 對照席 F5:六個範圍宣告字各一節;②從那行到節尾含子節;①節開頭撤除行含子節
    r2 = _nh_repo()
    words = ["下面", "以下", "本節", "這一節", "整篇", "之後"]
    nm = [f"scope_{i}_x" for i in range(6)] + ["sub_two_x", "after_two_x", "sub_one_x", "after_one_x"]
    _nh_file(r2, "src/a.py", "".join(f"def {n}():\n    pass\n" for n in nm))
    parts = ["# A"]
    for i, w in enumerate(words):
        parts += [f"## 節{i}", "說明", f"> {w}都是歷史紀錄", f"呼叫 scope_{i}_x"]
    parts += ["## 二", "說明", "> 以下是歷史紀錄", "### 子節", "呼叫 sub_two_x", "## 三", "呼叫 after_two_x",
              "## 四", "(本節已作廢)", "### 子節", "呼叫 sub_one_x", "## 五", "呼叫 after_one_x"]
    _m1_note(r2, "Systems/A.md", "\n".join(parts))
    b2 = _m1_commit(r2, "base")
    _nh_file(r2, "src/a.py", "z = 1\n")
    t2 = _m1_commit(r2, "del")
    res2 = _m1_check(r2, b2, t2)
    got2 = {n for f in res2["handle"] + res2["listed"] for n in f["names"]}
    check("⑩前置:10 個名稱都是候選", res2["state"] == "done" and res2["candidates"] == 10, str(res2["candidates"]))
    check("⑩六個範圍宣告字都觸發②;②與①都含子節、到同層標題為止", got2 == {"after_two_x", "after_one_x"}, str(got2))


def t_drift_m1_layers_and_mode():
    """[S3] 家筆記(起點或終點 about_code 列了改到的檔)或摘要 → 要處理,其他只列出;rc_m1 只看 old_sentence,
    整支回 max(既有那段, rc_m1);兩個開關各自解析。

    翻紅釘:rc_m1 看 gate → ②④紅;回傳改成只看 rc_core → ③紅;摘要行不進要處理 → ①紅;old_sentence 在 gate 壞值時一起退回 → ⑥紅。
    """
    print("t_drift_m1_layers_and_mode")
    import json as _j
    m = _load_lumos_inproc()
    root = _dr_repo(cfg={"drift_check": {"gate": "block"}})
    vault = root / _DR_VAULT
    _nh_file(root, "src/pay.py", "def refund_amount_x():\n    pass\n\ndef second_name_y():\n    pass\n")
    _nh_node(root, "Pay", about=["src/pay.py"], summary="FLOW:a", body="呼叫 refund_amount_x 與 second_name_y。")
    _m1_note(root, "Systems/Other.md", "# O\n也呼叫 refund_amount_x。", summary="KEY:用 refund_amount_x")
    (vault / "Verification" / "G.md").write_text(_dr_guard_text("pending"), encoding="utf-8")
    base = _m1_commit(root, "base")
    g = vault / "Verification" / "G.md"
    g.write_text(g.read_text(encoding="utf-8").replace("status: pending", "status: pass").replace("status/pending", "status/pass"),
                 encoding="utf-8")
    _nh_file(root, "src/pay.py", "def second_name_y():\n    pass\n")
    x = _m1_commit(root, "flip + remove")
    res = _m1_check(root, base, x)
    lay = {(f["path"], f["layer"]) for f in res["handle"] + res["listed"]}
    check("①家筆記 → 要處理;別篇正文 → 只列出;別篇摘要 → 要處理", ("Systems/Pay.md", "handle") in lay
          and ("Systems/Other.md", "list") in lay and ("Systems/Other.md", "handle") in lay, str(lay))

    def cfg(gate, osm):
        dc = {"gate": gate}
        if osm is not None:
            dc["old_sentence"] = osm
        (root / ".lumos" / "config.json").write_text(_j.dumps({"drift_check": dc}), encoding="utf-8")
        _m1_commit(root, f"cfg {gate} {osm}")
        return _m1_run(root, f"{base}..HEAD")
    rc, out = cfg("block", "warn")
    check("②前置:c1 要處理、m1 要處理都在(gate=block、old_sentence=warn)", "[c1 " in out and "[m1 " in out, out[-1500:])
    check("②gate=block、old_sentence=warn → 1(來自 c1),m1 只提醒", rc == 1 and "提醒:舊句檢查" in out, out[-800:])
    rc, out = cfg("off", "warn")
    check("③gate=off、old_sentence=warn → 0,m1 照跑", rc == 0 and "舊句檢查" in out and "[c1 " not in out, out[-800:])
    rc, out = cfg("off", "block")
    check("④gate=off、old_sentence=block → 1(來自 m1)", rc == 1 and "擋下:舊句檢查" in out, out[-800:])
    rc, out = cfg("block", "off")
    check("⑤gate=block、old_sentence=off → 1 而且 m1 沒跑", rc == 1 and "舊句檢查" not in out and "[c1 " in out, out[-800:])
    (root / ".lumos" / "config.json").write_text(_j.dumps({"drift_check": {"gate": "block", "old_sentence": "block"}}),
                                                 encoding="utf-8")
    y0 = _m1_commit(root, "cfg both block")
    _nh_file(root, "src/pay.py", "z = 1\n")
    _m1_commit(root, "remove second")
    rc, out = _m1_run(root, f"{y0}..HEAD")
    check("⑥c1 到 c5 乾淨、m1 要處理 1 筆、old_sentence=block → 1", rc == 1 and "[c1 " not in out
          and "擋下:舊句檢查" in out and "second_name_y" in out, out[-800:])
    got = [m._drift_config(t) for t in (b'{"drift_check": {"old_sentence": "block"}}',
                                        b'{"drift_check": {"gate": "blcok", "old_sentence": "block"}}',
                                        b'{"drift_check": {"old_sentence": "on"}}', None, b"{bad")]
    check("⑦只寫 old_sentence=block → gate 照它的預設 block、old_sentence block", got[0][0] == "block" and got[0][3] == "block", str(got[0]))
    check("⑦gate 寫壞、old_sentence=block → gate 照預設加提醒,old_sentence 照樣 block", got[1][0] == "block"
          and any("blcok" in w for w in got[1][1]) and got[1][3] == "block", str(got[1]))
    check("⑦old_sentence 寫壞值 → 照總開關(這裡沒寫 gate 是 block)並提醒", got[2][3] == "block"
          and any("drift_check.old_sentence 只能是 block/warn/off,你寫的是 'on',照總開關 block" == w for w in got[2][1]), str(got[2]))
    check("⑦沒設定檔、設定檔壞掉 → block(預設照總開關/照預設)", got[3][3] == "block" and got[4][3] == "block", str(got[3:]))
    check("⑦設定檔壞掉:gate 與 old_sentence 都照預設 block,兩句各講各的", got[4][0] == "block"
          and any("讀不成 JSON" in w for w in got[4][1])
          and any("舊句檢查(drift_check.old_sentence)照預設 block" in w for w in got[4][1]),
          str(got[4]))
    # 代碼審 r1 spec 對照席 F1:同一個提交刪名稱、也把家筆記 about_code 裡那支檔拿掉 → 起點樹還列著,仍是家
    r3 = _nh_repo()
    _nh_file(r3, "src/two.py", "def gone_two_x():\n    pass\n")
    _m1_note(r3, "Systems/Two.md", "# T\n呼叫 gone_two_x。", about=["src/two.py"])
    b3 = _m1_commit(r3, "b")
    _nh_file(r3, "src/two.py", "z = 1\n")
    _m1_note(r3, "Systems/Two.md", "# T\n呼叫 gone_two_x。")
    t3 = _m1_commit(r3, "t")
    res3 = _m1_check(r3, b3, t3)
    check("⑧前置:終點樹的 Two 已經沒列 src/two.py", "src/two.py" not in (r3 / _M1_VAULT / "Systems" / "Two.md").read_text(encoding="utf-8"),
          "")
    check("⑧只在起點樹當家也算家 → 要處理", [(f["path"], f["layer"]) for f in res3["handle"] + res3["listed"]]
          == [("Systems/Two.md", "handle")], str(res3["handle"] + res3["listed"]))


def t_drift_m1_ack_binds_name():
    """[S4] drift ack --kind m1 --name=… 記名稱清單;同路徑同原文所有 m1 表態的名稱聯集涵蓋一筆發現的名稱集合才算已表態;
    沒 --name、空白、別種類帶 --name 回 2;照貼提示(名稱 --restore)換掉佔位字 rc 0,原樣帶佔位字 rc 2。

    翻紅釘:只看最新一筆表態(照 c2/c3)→ ③紅;不寫 names → ②③紅;提示寫成 --name --restore → ⑦紅。
    """
    print("t_drift_m1_ack_binds_name")
    import json as _j, shlex
    m = _load_lumos_inproc()
    root = _nh_repo(cfg={"drift_check": {"old_sentence": "block"}})
    vault = root / _M1_VAULT
    _nh_file(root, "src/x.py", "import argparse\np = argparse.ArgumentParser()\np.add_argument('--restore')\n"
             "def alpha_name_a():\n    pass\n\ndef beta_name_b():\n    pass\n\ndef gamma_name_c():\n    pass\n")
    _m1_note(root, "Systems/N.md", "# N\n呼叫 alpha_name_a 與 beta_name_b 與 gamma_name_c。\n用 --restore 還原。", about=["src/x.py"])
    b0 = _m1_commit(root, "b0")
    lno = _m1_lno(root, "Systems/N.md", "alpha_name_a")
    _nh_file(root, "src/x.py", "def gamma_name_c():\n    pass\n\nimport argparse\np = argparse.ArgumentParser()\np.add_argument('--restore')\n")
    _m1_commit(root, "b1")
    rc, out = _m1_run(root, f"{b0}..HEAD")
    check("①前置:那一行列在要處理,名稱 {alpha, beta}", rc == 1 and f"Systems/N.md:{lno}" in out and "alpha_name_a" in out, out[-800:])
    for n in ("alpha_name_a", "beta_name_b"):
        r = run(vault, "drift", "ack", "Systems/N", str(lno), "--kind", "m1", f"--name={n}", "--reason", "歷史說法照留給讀者")
    acks = [_j.loads(ln) for ln in (root / "governance" / "drift-acks.jsonl").read_text(encoding="utf-8").splitlines() if ln.strip()]
    check("②表態記路徑、原文、種類與名稱清單", r.returncode == 0 and [a.get("names") for a in acks] == [["alpha_name_a"], ["beta_name_b"]]
          and acks[0]["kind"] == "m1" and acks[0]["path"] == f"{_M1_VAULT}/Systems/N.md", str(acks))
    _m1_commit(root, "acks")
    rc, out = _m1_run(root, f"{b0}..HEAD")
    check("③分兩次表態 A、B → {A,B} 已表態,不再列", rc == 0 and f"Systems/N.md:{lno}" not in out, out[-800:])
    _nh_file(root, "src/x.py", "import argparse\np = argparse.ArgumentParser()\np.add_argument('--restore')\n")
    _m1_commit(root, "remove c")
    rc, out = _m1_run(root, f"{b0}..HEAD")
    check("④新名稱 C 觸發同一行 → {A,B,C} 不是子集,照列", rc == 1 and f"Systems/N.md:{lno}" in out and "gamma_name_c" in out,
          out[-800:])
    f = _m1_f("Systems/N.md", lno, ["alpha_name_a"], text="呼叫 alpha_name_a 與 beta_name_b 與 gamma_name_c。")
    old = [{"path": f"{_M1_VAULT}/Systems/N.md", "text": f["text"], "kind": "m1", "reason": "舊的"},
           {"path": f"{_M1_VAULT}/Systems/N.md", "text": f["text"], "kind": "m1", "reason": "空", "names": []}]
    left, _done = m._drift_split_acked([f], old, _M1_VAULT)
    check("⑤沒有 names 欄或空清單的 m1 表態不涵蓋任何名稱", left == [f], str(left))
    for label, extra in (("不帶 --name", []), ("--name= 空白", ["--name=   "]), ("--name 超過 200 字", ["--name=" + "a" * 201])):
        r = run(vault, "drift", "ack", "Systems/N", str(lno), "--kind", "m1", *extra, "--reason", "歷史說法照留給讀者")
        check(f"⑥{label} → rc 2", r.returncode == 2, r.stdout + r.stderr)
    r = run(vault, "drift", "ack", "Systems/N", str(lno), "--kind", "c1", "--name=x_y", "--reason", "歷史說法照留給讀者")
    check("⑥別的種類帶 --name → rc 2", r.returncode == 2 and "--name" in r.stderr, r.stdout + r.stderr)
    _nh_file(root, "src/x.py", "x = 1\n")
    _m1_commit(root, "remove flag")
    rc, out = _m1_run(root, f"{b0}..HEAD")
    hint = next((ln.split("確定照留就 ", 1)[1] for ln in out.splitlines() if "--name=--restore" in ln), None)
    check("⑦前置:提示印 --name=--restore(等號寫法)", hint is not None and "--kind m1" in hint, out[-1200:])
    if hint:
        args = shlex.split(hint)
        r = run(vault, *args[1:])
        check("⑦原樣照貼(帶佔位字)→ 被佔位字檢查擋成 rc 2", r.returncode == 2 and "佔位字" in r.stderr, r.stdout + r.stderr)
        r = run(vault, *shlex.split(hint.replace("<為什麼照留>", "這句在講舊旗標的由來,照留"))[1:])
        check("⑦換成實際理由後照貼 → rc 0", r.returncode == 0, r.stdout + r.stderr)
    # 代碼審 r1 spec 對照席 F3:只列出層也走表態;表態檔的名稱排序去重
    _m1_note(root, "Systems/Other.md", "# O\n也呼叫 beta_name_b 與 alpha_name_a。")
    _m1_commit(root, "other")
    rc, out = _m1_run(root, f"{b0}..HEAD")
    olno = _m1_lno(root, "Systems/Other.md", "beta_name_b")
    check("⑧前置:Other 那行在只列出層", f"Systems/Other.md:{olno}" in out and "只列出(舊句檢查" in out, out[-800:])
    r = run(vault, "drift", "ack", "Systems/Other", str(olno), "--kind", "m1", "--name=beta_name_b", "--name=alpha_name_a",
            "--name=beta_name_b", "--reason", "這篇是對照說明,照留")
    last = _j.loads((root / "governance" / "drift-acks.jsonl").read_text(encoding="utf-8").splitlines()[-1])
    check("⑧表態檔的名稱排序去重", r.returncode == 0 and last.get("names") == ["alpha_name_a", "beta_name_b"], str(last))
    _m1_commit(root, "ack other")
    rc, out = _m1_run(root, f"{b0}..HEAD")
    check("⑧只列出層的已表態也不再列", f"Systems/Other.md:{olno}" not in out, out[-800:])


def _m1_cache_repo(n=30, extra=None):
    """定義快取測試的專案:沒有沒副檔名的檔;src/m<k>.py 各定義兩個名稱,筆記提到其中一個。"""
    root = _nh_repo()
    for k in range(n):
        _nh_file(root, f"src/m{k}.py", f"def fn_{k}_x():\n    pass\n\nname_{k}_x = 1\n")
    for rel, txt in (extra or {}).items():
        _nh_file(root, rel, txt)
    _m1_note(root, "Systems/A.md", "# A\n" + "\n".join(f"用 fn_{k}_x" for k in range(n)))
    return root, _m1_commit(root, "base")


def _m1_cache_invalidation(m, root, base, c3, c30, h3):
    """t_drift_m1_defs_cache 的 ⑦ 到 ⑪:剖不動不寫、時間到之前剖好的留著、不可信與壞掉的快取、保鮮期清舊檔。"""
    import os as _o, time as _t
    _nh_file(root, "src/bad.py", "def ok_one_x():\n    pass\n")
    c_ok = _m1_commit(root, "bad ok")
    _nh_file(root, "src/bad.py", "def (\n")
    c_bad = _m1_commit(root, "bad broken")
    hb = Path(tempfile.mkdtemp())
    r = _m1_check(root, c_ok, c_bad, home=hb)
    d = hb / ".cache" / "lumos" / "drift-defs"
    bad_oid = _nh_git(root, "rev-parse", f"{c_bad}:src/bad.py").stdout.strip()
    ok_oid = _nh_git(root, "rev-parse", f"{c_ok}:src/bad.py").stdout.strip()
    with _M1Home(hb):
        check("⑦前置:剖不動那支記在 unparsable", r["unparsable"] == ["src/bad.py"], str(r))
        check("⑦剖不動的不寫快取,剖得動的那一版有寫", not m._drift_m1_cache_path(d, bad_oid).exists()
              and m._drift_m1_cache_path(d, ok_oid).exists(), str(sorted(x.name for x in d.iterdir())))
    ht = Path(tempfile.mkdtemp())
    orig_names = m._drift_py_names
    n_parse = [0]

    def counting(txt, m1=False):
        n_parse[0] += 1
        return orig_names(txt, m1)
    m._drift_py_names = counting
    try:
        r = _m1_check(root, base, c30, home=ht, now=lambda: 0 if n_parse[0] < 8 else 10 ** 9, deadline=100)
    finally:
        m._drift_py_names = orig_names
    dt = ht / ".cache" / "lumos" / "drift-defs"
    check("⑧時間到(假時鐘,剖到第 8 支)→ state timeout,之前剖好的已寫進快取", r["state"] == "timeout"
          and len(list(dt.glob("*.json"))) >= 7, f"{r['state']} {len(list(dt.glob('*.json')))}")
    d3 = h3 / ".cache" / "lumos" / "drift-defs"
    _o.chmod(d3, 0o777)
    try:
        r = _m1_check(root, base, c3, home=h3)
    finally:
        _o.chmod(d3, 0o700)
    check("⑨快取目錄不可信 → cache_hits 是 null,照常判完", r["state"] == "done" and r["cache_hits"] is None and r["parsed"] > 0, str(r))
    oid0 = _nh_git(root, "rev-parse", f"{base}:src/m0.py").stdout.strip()
    with _M1Home(h3):
        p0 = m._drift_m1_cache_path(d3, oid0)
    check("⑩前置:m0 起點版有快取檔", p0.is_file(), str(p0))
    _o.chmod(p0, 0o666)
    r = _m1_check(root, base, c3, home=h3)
    check("⑩快取檔 group/other 可寫 → 當沒命中、重剖", r["parsed"] >= 1 and r["state"] == "done", str(r))
    p0.write_text("{壞掉", encoding="utf-8")
    r = _m1_check(root, base, c3, home=h3)
    check("⑩快取檔壞掉 → 當沒命中、照剖", r["parsed"] >= 1 and r["state"] == "done", str(r))
    old = d3 / "old.json"
    old.write_text("{}", encoding="utf-8")
    past = _t.time() - m._DRIFT_M1_DEFS_TTL - 3600
    _o.utime(old, (past, past))
    _m1_check(root, base, c3, home=h3)
    check("⑪超過保鮮期的檔開跑前刪掉", not old.exists(), "")
    old.write_text("{}", encoding="utf-8")
    _o.utime(old, (past, past))
    _o.chmod(d3, 0o777)
    try:
        _m1_check(root, base, c3, home=h3)
    finally:
        _o.chmod(d3, 0o700)
    check("⑪目錄不可信時一支都不刪", old.exists(), "")


def _m1_cache_concurrency_and_pin(m):
    """t_drift_m1_defs_cache 的 ⑫⑬:兩個執行緒同寫同鍵;抽法輸出雜湊釘住。"""
    import hashlib, json as _j, threading
    hc = Path(tempfile.mkdtemp())
    oks = []
    with _M1Home(hc):
        dc = m._drift_m1_cache_dir()
        pc = m._drift_m1_cache_path(dc, "c" * 40)
        payload = {k: [f"n{i}" for i in range(300)] for k in "fcagt"}

        def writer():
            for _i in range(150):
                oks.append(m._home_cache_write("drift-defs", pc, payload))
        ths = [threading.Thread(target=writer) for _ in range(2)]
        for th in ths:
            th.start()
        for th in ths:
            th.join()
        back = _j.loads(pc.read_text(encoding="utf-8"))
    check("⑫兩個執行緒同寫同鍵:每次都寫成、讀回的是完整 JSON、沒有殘留暫存檔", all(oks) and len(oks) == 300 and back == payload
          and not list(dc.glob("*.tmp")), f"{sum(1 for x in oks if not x)} {list(dc.glob('*.tmp'))[:3]}")
    fixed = ("A_ONE, B_TWO = 1, 2\ntry:\n    MAX_RETRY = 3\nexcept ValueError:\n    MAX_RETRY = 4\n"
             "first_x, *rest_y = f()\nclass K:\n    field_x: int\n    def meth_x(self):\n        local_q = 1\n"
             "import argparse\np = argparse.ArgumentParser()\np.add_argument('--foo', dest='x')\nadd_argument('--bar')\n")
    got = m._drift_py_names(fixed, m1=True)
    digest = hashlib.sha256(_j.dumps([sorted(s) for s in got]).encode()).hexdigest()[:16]
    check("⑬抽法輸出雜湊釘住——這個雜湊變了就把 _DRIFT_M1_DEFS_SCHEMA 加一", digest == "ef2e1f3e18464d23", digest)


def t_drift_m1_defs_cache():
    """[S5] 定義快取 ~/.cache/lumos/drift-defs/:同一個 blob 第二次不重剖也不讀內容;schema、Python 版本換了不命中;
    剖不動的不寫;時間到之前剖好的留著;不可信的目錄、檔、壞檔當沒有快取;超過保鮮期的開跑前刪;git 呼叫次數不隨檔數長;
    兩個執行緒同寫同鍵不壞、不留暫存檔;抽法輸出雜湊釘住。

    翻紅釘:不查快取 → ④紅;鍵不帶 schema → ⑤紅;剖不動也寫 → ⑦紅;逐檔讀內容 → ②紅;
    _home_cache_write 的 mkstemp 換成固定檔名 → ⑫紅;抽法改了 → ⑬紅(同時把 _DRIFT_M1_DEFS_SCHEMA 加一)。
    """
    print("t_drift_m1_defs_cache")
    import subprocess as _sp
    m = _load_lumos_inproc()
    root, base = _m1_cache_repo(40)      # 另 10 支兩個範圍都沒改:兩次都要讀終點語料
    for k in range(3):
        _nh_file(root, f"src/m{k}.py", f"name_{k}_x = 1\n")
    c3 = _m1_commit(root, "3 files")
    for k in range(3, 30):
        _nh_file(root, f"src/m{k}.py", f"name_{k}_x = 1\n")
    c30 = _m1_commit(root, "30 files")
    orig_run, orig_cat = _sp.run, m._drift_m1_cat
    calls = {"git": 0, "cat": 0}

    def cnt_run(*a, **k):
        calls["git"] += 1
        return orig_run(*a, **k)

    def cnt_cat(*a, **k):
        calls["cat"] += 1
        return orig_cat(*a, **k)

    def measured(b, t, home):
        calls.update(git=0, cat=0)
        _sp.run, m._drift_m1_cat = cnt_run, cnt_cat
        try:
            return _m1_check(root, b, t, home=home), dict(calls)
        finally:
            _sp.run, m._drift_m1_cat = orig_run, orig_cat
    h3, h30 = Path(tempfile.mkdtemp()), Path(tempfile.mkdtemp())
    r3, n3 = measured(base, c3, h3)
    r30, n30 = measured(base, c30, h30)
    check("①前置:兩次都從冷快取、判完、有剖檔", r3["state"] == r30["state"] == "done" and r3["parsed"] > 0 and r30["parsed"] > 0
          and r3["cache_hits"] == 0 and r30["cache_hits"] == 0, f"{r3} {r30}")
    check("②改到 3 支與 30 支 .py:git 呼叫次數一樣", n3["git"] == n30["git"], f"{n3} {n30}")
    check("③程式檔批次讀最多 2 次", n3["cat"] <= 2 and n30["cat"] <= 2, f"{n3} {n30}")
    r3b, n3b = measured(base, c3, h3)
    check("④同一個範圍第二次跑:不重剖、全命中、程式檔批次讀 0 次", r3b["parsed"] == 0 and r3b["cache_hits"] > 0
          and n3b["cat"] == 0 and _m1_hits(r3b) == _m1_hits(r3), f"{r3b} {n3b}")
    orig_schema = m._DRIFT_M1_DEFS_SCHEMA
    m._DRIFT_M1_DEFS_SCHEMA = orig_schema + 1
    try:
        r = _m1_check(root, base, c3, home=h3)
    finally:
        m._DRIFT_M1_DEFS_SCHEMA = orig_schema
    check("⑤schema 常數改了 → 不命中、重剖", r["parsed"] > 0 and r["cache_hits"] == 0, str(r))
    orig_ver = m._drift_m1_pyver
    m._drift_m1_pyver = lambda: (3, 99)
    try:
        r = _m1_check(root, base, c3, home=h3)
    finally:
        m._drift_m1_pyver = orig_ver
    check("⑥Python 主次版本不同 → 不命中", r["parsed"] > 0 and r["cache_hits"] == 0, str(r))
    _m1_cache_invalidation(m, root, base, c3, c30, h3)
    _m1_cache_concurrency_and_pin(m)


def t_drift_m1_events_and_budget():
    """[S6] 範圍裡有改到的程式檔(或列不出)而 old_sentence 不是 off → 一定印一行結論、記一筆帳,欄位攤平在事件最外層;
    純文件推送不印不記;時間到、git 失敗、形狀過不了、rows 上限與 4 KB、帳寫不進去的留痕、空樹起點。

    翻紅釘:時間到落成 done/沒有候選 → ②紅;批次讀回 None 一律 git-failed → ③紅;rows 不設上限 → ⑤紅;
    量長度不含 _gate_event 補的欄位 → ⑥紅;帳寫不進去不留痕 → ⑦紅;空樹起點照判 → ⑧紅。
    """
    print("t_drift_m1_events_and_budget")
    import json as _j
    m = _load_lumos_inproc()
    root = _nh_repo(cfg={"drift_check": {"old_sentence": "block"}})
    _nh_file(root, "src/a.py", "def old_name_x():\n    pass\n\ndef resolve():\n    pass\n")
    _nh_file(root, "src/b.py", "def keep_b_x():\n    pass\n")
    _nh_file(root, "src/c.py", "def keep_c_x():\n    pass\n")
    _m1_note(root, "Systems/A.md", "# A\n呼叫 old_name_x。", about=["src/a.py"])
    base = _m1_commit(root, "base")
    _nh_file(root, "src/a.py", "def resolve():\n    pass\n")
    tip = _m1_commit(root, "del")
    rc, out = _m1_run(root, f"{base}..{tip}")
    ev = _m1_events(root)
    check("①前置:block、要處理 1 筆 → rc 1、記一筆", rc == 1 and len(ev) == 1, out[-600:])
    e = ev[-1] if ev else {}
    want = {"gate": "drift-check", "kind": "blocked", "hard": True, "head_sha": tip, "check": "old-sentence", "state": "done",
            "base_sha": base, "code_files": 1, "candidates": 1, "handle": 1, "listed": 0, "unparsable": 0, "text_defs": 0,
            "too_long": 0, "rows_truncated": False, "nodes": ["Systems/A"]}
    check("①欄位在事件最外層、值對", all(e.get(k) == v for k, v in want.items()) and "extra" not in e
          and isinstance(e.get("parsed"), int) and isinstance(e.get("cache_hits"), int)
          and e.get("rows") == [{"path": "Systems/A.md", "line": _m1_lno(root, "Systems/A.md", "old_name_x"), "layer": "handle",
                                 "names": ["old_name_x"], "text": "呼叫 old_name_x。"}], str(e))
    _nh_file(root, "src/a.py", "x = 1\n")
    tip2 = _m1_commit(root, "del resolve")
    rc, out = _m1_run(root, f"{tip}..{tip2}")
    e = _m1_events(root)[-1]
    check("④只刪了全小寫的 resolve(過不了形狀)→ done、candidates 0、passed、有帳", rc == 0 and e["state"] == "done"
          and e["candidates"] == 0 and e["kind"] == "passed" and e["head_sha"] == tip2, str(e))
    _m1_note(root, "Systems/Doc.md", "# D\n純文件")
    tip3 = _m1_commit(root, "docs only")
    n0 = len(_m1_events(root))
    rc, out = _m1_run(root, f"{tip2}..{tip3}")
    check("④純文件推送:不印不記", rc == 0 and "舊句檢查" not in out and len(_m1_events(root)) == n0, out[-400:])
    # ②時間到(冷快取剖終點語料到一半;候選還沒算出來)
    orig_names = m._drift_py_names
    n_parse = [0]

    def counting(txt, m1=False):
        n_parse[0] += 1
        return orig_names(txt, m1)
    m._drift_py_names = counting
    try:
        res = _m1_check(root, base, tip, now=lambda: 0 if n_parse[0] < 3 else 10 ** 9, deadline=100)
    finally:
        m._drift_py_names = orig_names
    check("②前置:冷快取剖到第 3 支時間到", res["state"] == "timeout" and res["candidates"] is None, str(res))
    rc, out = _m1_report(res, "block", root=root, base=base, tip=tip)
    e = _m1_events(root)[-1]
    check("②時間到 → block 回 1、帳 state timeout、candidates/handle/listed 是 null、沒有 rows", rc == 1 and e["state"] == "timeout"
          and e["candidates"] is None and e["handle"] is None and e["listed"] is None and "rows" not in e
          and e["kind"] == "blocked", str(e))
    flag = [0]
    orig_cat = m._drift_m1_cat
    m._drift_m1_cat = lambda *a, **k: (flag.__setitem__(0, 1), None)[1]
    try:
        r_over = _m1_check(root, base, tip, now=lambda: 10 ** 9 if flag[0] else 0, deadline=100)
        flag[0] = -1
        r_git = _m1_check(root, base, tip, now=lambda: 0, deadline=100)
    finally:
        m._drift_m1_cat = orig_cat
    check("③批次讀回 None 而已過截止時間 → timeout;還沒過 → git-failed", r_over["state"] == "timeout"
          and r_git["state"] == "git-failed", f"{r_over['state']} {r_git['state']}")
    # ⑤rows 上限
    many_h = [_m1_f(f"Systems/H{i}.md", 3, ["old_name_x"]) for i in range(12)]
    many_l = [_m1_f(f"Systems/L{i}.md", 3, ["old_name_x"], layer="list") for i in range(5)]
    m._drift_m1_ledger(root, "warn", base, tip, _m1_res(handle=many_h, listed=many_l), (many_h, many_l), "note")
    e = _m1_events(root)[-1]
    check("⑤要處理 12、只列出 5 → rows 各記 10、3", sum(1 for x in e["rows"] if x["layer"] == "handle") == 10
          and sum(1 for x in e["rows"] if x["layer"] == "list") == 3 and e["kind"] == "warned", str(e)[:400])
    # ⑥4 KB:長路徑讓 rows 撐過 4096 → 先丟 rows;nodes 多又長 → 丟光 rows 再截 nodes 到 20
    lp = "Systems/" + "長名" * 10
    lt = "呼叫 old_name_x " + "很長的句子" * 30
    big_h = [_m1_f(f"{lp}{i}.md", 3, ["old_name_x"], text=lt) for i in range(10)]
    big_l = [_m1_f(f"{lp}L{i}.md", 3, ["old_name_x"], layer="list", text=lt) for i in range(3)]
    ev0 = m._gate_event_build(root, "drift-check", "warned", "n", head_sha=tip, nodes=[f["path"][:-3] for f in big_h],
                              extra={"rows": m._drift_m1_rows(big_h, 10) + m._drift_m1_rows(big_l, 3)})
    check("⑥前置:不截的話一行超過 4096 位元組", len((_j.dumps(ev0, ensure_ascii=False) + "\n").encode()) > 4096, "")
    m._drift_m1_ledger(root, "warn", base, tip, _m1_res(handle=big_h, listed=big_l), (big_h, big_l), "note")
    last = (root / "docs" / ".governance-log.jsonl").read_text(encoding="utf-8").splitlines()[-1]
    e = _j.loads(last)
    check("⑥先從只列出丟 rows,整行壓在 4096 內、記 rows_truncated", len((last + "\n").encode()) <= 4096 and e["rows_truncated"]
          and not any(x["layer"] == "list" for x in e["rows"]) and len(e["nodes"]) == 10, f"{len(last)} {e.get('rows_truncated')}")
    huge = [_m1_f("Systems/" + "很長的筆記名稱" * 20 + f"{i}.md", 3, ["old_name_x"]) for i in range(50)]
    m._drift_m1_ledger(root, "warn", base, tip, _m1_res(handle=huge), (huge, []), "note")
    e = _m1_events(root)[-1]
    check("⑥rows 丟光還超過 → nodes 截到 20、rows_truncated true", e["rows"] == [] and len(e["nodes"]) == 20 and e["rows_truncated"],
          f"{len(e['nodes'])} {len(e['rows'])}")
    # ⑦帳寫不進去的留痕
    h = Path(tempfile.mkdtemp())
    orig_ge = m._gate_event
    m._gate_event = lambda *a, **k: False
    try:
        with _M1Home(h):
            import contextlib, io
            with contextlib.redirect_stderr(io.StringIO()):
                m._drift_m1_ledger(root, "warn", base, tip, _m1_res(), ([], []), "note")
    finally:
        m._gate_event = orig_ge
    miss = h / ".cache" / "lumos" / "drift-m1" / "ledger-miss.jsonl"
    rows = [_j.loads(ln) for ln in miss.read_text(encoding="utf-8").splitlines()] if miss.is_file() else []
    check("⑦_gate_event 回 False → ledger-miss.jsonl 多一行帶 repo、head_sha、state", len(rows) == 1
          and rows[0]["repo"] == str(Path(root).resolve()) and rows[0]["head_sha"] == tip and rows[0]["state"] == "done", str(rows))
    # ⑧空樹起點
    r_docs = _nh_repo()
    _m1_note(r_docs, "Systems/A.md", "# A")
    t_docs = _m1_commit(r_docs, "docs")
    rd = _m1_check(r_docs, None, t_docs)
    check("⑧空樹起點、終點沒有程式檔 → 不印不記", rd["state"] is None, str(rd))
    rn = _m1_check(root, None, tip)
    rc, out = _m1_report(rn, "block", root=root, base=None, tip=tip)
    e = _m1_events(root)[-1]
    check("⑧空樹起點、有程式檔 → no-base、印那一行、rc 0、帳 range-unavailable、base_sha 空字串、candidates null",
          rn["state"] == "no-base" and rc == 0 and "舊句檢查:這次沒有起點版可比,不判" in out
          and e["kind"] == "range-unavailable" and e["state"] == "no-base"
          and e["base_sha"] == "" and e["candidates"] is None, f"{rn} {e}")
    # 代碼審 r1 spec 對照席 F2:終點不是 HEAD(--diff A..B,B 後面還有提交)→ head_sha 是 B
    _nh_file(root, "src/b.py", "y = 2\n")
    xb = _m1_commit(root, "x")
    _nh_file(root, "src/c.py", "w = 3\n")
    head = _m1_commit(root, "after x")
    check("⑨前置:終點不是 HEAD", xb != head, "")
    _m1_run(root, f"{tip3}..{xb}")
    e = _m1_events(root)[-1]
    check("⑨帳的 head_sha 是被推送的終點,不是 HEAD", e["head_sha"] == xb and e["commit"] == xb[:7], str(e))


def t_drift_m1_hint_paste_safe():
    """[S7] m1 的改法:每個名稱寫成過了 _drift_sh 的 --name=<名稱>,去重鍵帶名稱集合,不截在 300 字,超過 4000 字改印
    「名稱太多,先改寫這一行」;名稱含分號、空白、$() 時照貼不會切參數或執行。

    翻紅釘:名稱不過 _drift_sh → ②紅;去重鍵不帶名稱 → ③紅;截在 300 字 → ④紅。
    """
    print("t_drift_m1_hint_paste_safe")
    import io, shlex, subprocess as _sp
    m = _load_lumos_inproc()
    work = Path(tempfile.mkdtemp(prefix="gctl-m1sh-"))
    names = ["src/x;y.py", "a b.py", "$(touch PWNED).py", "--restore"]
    h = m._drift_fix_hint("m1", "Systems/A.md", 7, names=names)[0]
    cmd = h.split("確定照留就 ", 1)[1].replace("<為什麼照留>", "理由")
    check("①提示帶改法說明與表態指令", h.startswith("改成歷史說法(例:「原本叫 <名稱>,已移除」)或刪掉這句;確定照留就 lumos drift ack"), h)
    r = _sp.run(["bash", "-c", 'lumos(){ printf "%s\\n" "$@"; }; ' + cmd], cwd=work, capture_output=True, text=True)
    args = r.stdout.split("\n")[:-1]
    check("②照貼進 shell:每個名稱一整段 --name=<名稱>、沒有切開也沒有執行", r.returncode == 0
          and [a for a in args if a.startswith("--name=")] == ["--name=" + n for n in names]
          and not (work / "PWNED").exists() and not (work / "PWNED).py").exists(), r.stdout + r.stderr)
    check("②shlex 切出來一樣", [a for a in shlex.split(cmd) if a.startswith("--name=")] == ["--name=" + n for n in names], cmd)
    rows = [_m1_f("Systems/A.md", 7, ["aa_x"]), _m1_f("Systems/A.md", 7, ["bb_x"]), _m1_f("Systems/A.md", 7, ["aa_x"])]
    buf = io.StringIO()
    m._drift_print_hints(rows, buf)
    check("③去重鍵帶名稱集合:同一行不同名稱兩條、相同的一條", buf.getvalue().count("--kind m1") == 2, buf.getvalue())
    long_names = [f"very_long_name_{i:02d}_" + "x" * 40 for i in range(12)]
    buf = io.StringIO()
    m._drift_print_hints([_m1_f("Systems/A.md", 7, long_names)], buf)
    check("④不截在 300 字", len(buf.getvalue()) > 700 and long_names[-1] in buf.getvalue() and "…" not in buf.getvalue(),
          buf.getvalue()[-200:])
    huge = [f"n_{i:03d}_" + "y" * 60 for i in range(80)]
    h2 = m._drift_fix_hint("m1", "Systems/A.md", 7, names=huge)[0]
    check("⑤超過 4000 字改印「名稱太多,先改寫這一行」", h2.startswith("名稱太多,先改寫這一行") and len(h2) < 200, h2[:200])


def t_drift_m1_extract_defs():
    """[S8] _drift_py_names(txt, m1=True) → 函式、類別、指派、旗標四個集合(指派與旗標照參考實作);m1=False 回傳跟改之前逐字相同。

    翻紅釘:拆包收巢狀 → ②紅;try 的 except/finally 不遞迴 → ③紅;收函式裡的區域指派 → ⑤紅;收 except* → ⑥紅。
    """
    print("t_drift_m1_extract_defs")
    m = _load_lumos_inproc()
    src = "\n".join([
        "A_ONE, B_TWO = 1, 2", "C_X, (D_NEST, E_NEST) = 1, (2, 3)", "first_x, *rest_y = f()",
        "if cond:", "    IF_BODY = 1", "else:", "    IF_ELSE = 2",
        "try:", "    MAX_RETRY = 3", "except ValueError:", "    EXC_VAL = 4", "else:", "    TRY_ELSE = 5", "finally:", "    FIN_VAL = 6",
        "try:", "    pass", "except* OSError:", "    STAR_VAL = 7",
        "type AliasT = int", "AUG_X = 0", "AUG_X += 1", "ann_no_value: int", "ann_val: int = 3",
        "class Outer:", "    field_x: int", "    cls_val = 1", "    class Inner:", "        inner_val = 2",
        "    def meth_x(self):", "        local_q = 1", "        return local_q",
        "async def co_fn():", "    pass",
        "def top_fn():", "    in_fn = 1", "    def nested_fn():", "        pass",
        "import argparse", "p = argparse.ArgumentParser()", "p.add_argument('--foo', dest='x')", "p.add_argument('-s', '--long-s')",
        "add_argument('--bare')", "p.add_argument(NAME)", "p.add_argument('pos')", "other('--nope')", ""])
    got = m._drift_py_names(src, m1=True)
    check("①回四個集合", isinstance(got, tuple) and len(got) == 4, str(got)[:200])
    if not (isinstance(got, tuple) and len(got) == 4):
        return
    f, c, a, g = got
    check("①函式、類別任何層(含 async、方法、巢狀)", {"co_fn", "top_fn", "nested_fn", "meth_x"} <= f and {"Outer", "Inner"} == c, str((f, c)))
    check("②拆包只收一層、只收直接是名稱的元素", {"A_ONE", "B_TWO", "C_X", "first_x"} <= a
          and not {"D_NEST", "E_NEST", "rest_y"} & a, str(a))
    check("③模組層 if/try(含 else、except、finally)遞迴收", {"IF_BODY", "IF_ELSE", "MAX_RETRY", "EXC_VAL", "TRY_ELSE", "FIN_VAL"} <= a,
          str(a))
    check("④型別標註有沒有值都算;類別層與巢狀類別層收", {"ann_no_value", "ann_val", "field_x", "cls_val", "inner_val", "AUG_X"} <= a,
          str(a))
    check("⑤函式裡的區域指派不收", not {"local_q", "in_fn"} & a, str(a))
    check("⑥except*、type X = …、X += 1 不額外收", "STAR_VAL" not in a and "AliasT" not in a, str(a))
    check("⑦旗標:add_argument 位置參數裡以 -- 開頭的字串常數", g == {"--foo", "--long-s", "--bare"}, str(g))
    probe = "def a_fn():\n    pass\nclass B_cls:\n    pass\nMOD_X = 1\nann_y: int = 2\nann_z: int\nq, r = 1, 2\n"
    check("⑧m1=False 回傳跟改之前逐字相同(三個集合,指定只算模組層、帶型別的要有值、不拆包)",
          m._drift_py_names(probe) == ({"a_fn"}, {"B_cls"}, {"MOD_X", "ann_y"}) and m._drift_py_names("def (") is None,
          str(m._drift_py_names(probe)))


def t_drift_m1_paths_and_shape():
    """[S9] 被刪的程式檔(含 --no-renames 下的改名)舊路徑算消失,檔名只在終點樹任何位置都沒有同名檔才算;候選過形狀過濾。

    翻紅釘:檔名不查終點樹 → ②紅;改名配對(-M)→ ④紅;拿掉形狀過濾 → ⑤紅。
    """
    print("t_drift_m1_paths_and_shape")
    m = _load_lumos_inproc()
    root = _nh_repo()
    _nh_file(root, "pkg_a/util.py", "x = 1\n")
    _nh_file(root, "pkg_b/util.py", "y = 1\n")
    _nh_file(root, "tools/run_all.sh", "#!/bin/bash\necho hi\n")
    _nh_file(root, "tools/old_mover.py", "z = 1\n")
    _m1_note(root, "Systems/A.md", "# A\n跑 pkg_a/util.py\n跑 tools/run_all.sh")
    base = _m1_commit(root, "base")
    for p in ("pkg_a/util.py", "tools/run_all.sh"):
        (root / p).unlink()
    (root / "tools" / "old_mover.py").rename(root / "tools" / "new_mover.py")
    tip = _m1_commit(root, "del")
    res = _m1_check(root, base, tip)
    gone = set(res["gone"])
    check("①前置:判完、改到 4 支程式檔(改名拆成一刪一加)", res["state"] == "done" and res["code_files"] == 4, str(res))
    check("②刪 pkg_a/util.py、終點還有 pkg_b/util.py → 路徑算、檔名不算", "pkg_a/util.py" in gone and "util.py" not in gone, str(gone))
    check("③刪 tools/run_all.sh、沒有別的同名檔 → 兩個都算", {"tools/run_all.sh", "run_all.sh"} <= gone, str(gone))
    check("④改名在 --no-renames 下也算刪", {"tools/old_mover.py", "old_mover.py"} <= gone, str(gone))
    ok = ["Result", "getUser", "old_name", "--restore", "a/b"]
    no = ["main", "FOO", "lumos", "pre-push", "resolve"]
    check("⑤形狀過濾(照參考實作 _shape_ok)", all(m._drift_m1_shape_ok(x) for x in ok) and not any(m._drift_m1_shape_ok(x) for x in no),
          str([(x, m._drift_m1_shape_ok(x)) for x in ok + no]))


def t_drift_m1_whole_word():
    """[S10] 整字比對照參考實作 _mk_rx(ASCII 識別字邊界,中文緊貼算提到);名稱先篩不改結果;每一行都看時間(代碼審 r1 起;原本每 200 行)。

    翻紅釘:邊界改成 \\b(含中文)→ ①「改了foo_bar函式」紅;先篩切詞含中文 → ③紅;逐篇才看時間 → ④紅。
    """
    print("t_drift_m1_whole_word")
    m = _load_lumos_inproc()
    rx = m._drift_m1_name_rx(["foo_bar", "--restore", "tools/匯出報表.py", "計算_總額", "get_user", "foo.py", "--dry-run",
                              "run_all", "run_all.sh"])
    def f(s):
        return [x.group(0) for x in rx.finditer(s)]
    check("①中文緊貼算提到", f("改了foo_bar函式") == ["foo_bar"] and f("加了--restore旗標") == ["--restore"]
          and f("見tools/匯出報表.py") == ["tools/匯出報表.py"] and f("呼叫 計算_總額 算錢") == ["計算_總額"], "")
    check("②整字:get_user_id 不算 get_user、other/foo.py 不算 foo.py、--dry-run-x 不算 --dry-run", f("get_user_id") == []
          and f("other/foo.py") == [] and f("--dry-run-x") == [], "")
    check("②同一個位置 run_all 先吃掉 run_all.sh", f("執行 run_all.sh") == ["run_all"], str(f("執行 run_all.sh")))
    root = _nh_repo()
    names = [f"cand_{i:03d}_x" for i in range(250)]
    _nh_file(root, "src/a.py", "".join(f"def {n}():\n    pass\n" for n in names) + "def 計算_總額():\n    pass\n")
    _nh_file(root, "tools/匯出報表.py", "x = 1\n")
    _m1_note(root, "Systems/A.md", "# A\n改了cand_001_x函式\n呼叫 計算_總額 算錢\n見 tools/匯出報表.py\n" + "\n".join(
        f"第 {i} 行 cand_{i:03d}_xyz 不算" for i in range(5)))
    base = _m1_commit(root, "base")
    _nh_file(root, "src/a.py", "z = 1\n")
    (root / "tools" / "匯出報表.py").unlink()
    tip = _m1_commit(root, "del")
    orig = m._DRIFT_M1_PREFILTER_MIN
    try:
        m._DRIFT_M1_PREFILTER_MIN = 0
        r0 = _m1_check(root, base, tip)
        m._DRIFT_M1_PREFILTER_MIN = 10 ** 9
        r1 = _m1_check(root, base, tip)
    finally:
        m._DRIFT_M1_PREFILTER_MIN = orig
    got = {n for f_ in r0["handle"] + r0["listed"] for n in f_["names"]}
    check("③前置:候選超過 200 個、中文函式名與中文路徑都列", r0["candidates"] > 200 and {"cand_001_x", "計算_總額", "tools/匯出報表.py"} <= got,
          str(got))
    check("③先篩開與不開,輸出逐字相同", r0["handle"] == r1["handle"] and r0["listed"] == r1["listed"], "")
    _m1_note(root, "Systems/Long.md", "# L\n" + "\n".join("cand_002_x 在這" if i == 10 else f"第 {i} 行" for i in range(1000)))
    tip2 = _m1_commit(root, "long")
    calls = [0]
    orig_ret = m._drift_m1_retired
    started = [False]

    def ret(lines, *a):
        started[0] = started[0] or len(lines) >= 1000      # 從那篇 1000 行的筆記開始數
        return orig_ret(lines, *a)

    def now():
        if started[0]:
            calls[0] += 1
        return 10 ** 9 if calls[0] > 500 else 0
    m._drift_m1_retired = ret
    try:
        r = _m1_check(root, base, tip2, now=now, deadline=100)
    finally:
        m._drift_m1_retired = orig_ret
    check("④每一行都看時間:1000 行那篇掃到第 500 行時間到 → timeout,那篇前面已找到的留著", r["state"] == "timeout"
          and calls[0] == 501 and any(f_["path"] == "Systems/Long.md" for f_ in r["handle"] + r["listed"]), f"{r['state']} {calls[0]}")


def t_drift_m1_no_base_and_unreadable():
    """[S11] 起點空樹 → 不判、印一行、rc_m1 0、帳 range-unavailable/no-base(代碼審 r1 起不記 skipped);範圍改到的筆記讀不出 → unreadable、block 回 1;
    沒改到的讀不出 → 只印「K 篇筆記讀不出沒掃」;開頭帶 BOM 的筆記照樣切得出開頭欄位(摘要行照算要處理)。

    翻紅釘:空樹照判 → ①紅;沒改到的讀不出也算判不了 → ③紅;讀筆記不去 BOM → ④紅。
    """
    print("t_drift_m1_no_base_and_unreadable")
    root = _nh_repo()
    _nh_file(root, "src/a.py", "def gone_one_x():\n    pass\n\ndef gone_two_x():\n    pass\n")
    _m1_note(root, "Systems/Plain.md", "# P\n呼叫 gone_one_x。")
    _m1_note(root, "Systems/Old.md", "", raw=b"---\ntype: system\n---\n# \xff\xfe bad\n")
    _m1_note(root, "Systems/Bom.md", "", raw="\ufeff---\ntype: system\nsummary: |-\n  KEY:用 gone_two_x\n---\n# B\n")
    base = _m1_commit(root, "base")
    rn = _m1_check(root, None, base)
    rc, out = _m1_report(rn, "block", root=root, base=None, tip=base)
    check("①空樹起點、有程式檔 → no-base、印那一行、rc_m1 0", rn["state"] == "no-base" and rc == 0
          and "舊句檢查:這次沒有起點版可比,不判" in out, f"{rn} {out}")
    e = _m1_events(root)[-1]
    check("①帳記 kind range-unavailable(不是 skipped,gov 不算成被跳過)、state no-base",
          e["kind"] == "range-unavailable" and e["state"] == "no-base", str(e))
    _nh_file(root, "src/a.py", "x = 1\n")
    t1 = _m1_commit(root, "del")
    r = _m1_check(root, base, t1)
    rc, out = _m1_report(r, "block", root=root, base=base, tip=t1)
    lay = {(f["path"], f["layer"]) for f in r["handle"] + r["listed"]}
    check("③前置:判完、Plain 只列出", r["state"] == "done" and ("Systems/Plain.md", "list") in lay, str(r))
    check("③沒改到的讀不出 → 只印「1 篇筆記讀不出沒掃」、不影響 rc", r["bad_notes"] == 1 and "1 篇筆記讀不出沒掃" in out, out)
    check("④開頭帶 BOM 的筆記照樣切得出開頭欄位:摘要行算要處理", ("Systems/Bom.md", "handle") in lay, str(lay))
    check("④(rc 來自 BOM 那篇的要處理)", rc == 1, out)
    _m1_note(root, "Systems/Touched.md", "", raw=b"---\ntype: system\n---\n# \xff new bad\n")
    _nh_file(root, "src/b.py", "def later_gone_x():\n    pass\n")
    t2 = _m1_commit(root, "add")
    _nh_file(root, "src/b.py", "y = 1\n")
    (root / _M1_VAULT / "Systems" / "Touched.md").write_bytes(b"---\ntype: system\n---\n# \xff changed bad\n")
    t3 = _m1_commit(root, "touch bad")
    r = _m1_check(root, t2, t3)
    rc, out = _m1_report(r, "block", root=root, base=t2, tip=t3)
    check("②範圍改到的筆記讀不出 → unreadable、判不了、block 回 1", r["state"] == "unreadable" and r["bad_touched"] == 1 and rc == 1
          and "擋下:舊句檢查:這次改到的筆記有 1 篇讀不出,這次沒判完" in out, f"{r} {out}")


def t_drift_m1_unparsable_files():
    """[S16] 改到的檔任一版剖不動 → 不抽候選、印「N 支剖不動」;超過 4194304 位元組 → 兩版文字抽定義、照樣判;
    終點語料剖不動或太大 → 文字抽,抽到的算還在;文字抽跟 _drift_py_def_re 判斷一致;latin-1 舊檔照剖;
    只改一支剖不動的檔 → 照樣印結論與「1 支剖不動」、記 done/candidates 0。

    翻紅釘:剖不動當全部消失 → ①紅;太大照樣 ast(或略過)→ ②紅;終點語料剖不動直接略過(參考實作)→ ③紅。
    """
    print("t_drift_m1_unparsable_files")
    import time as _t
    m = _load_lumos_inproc()
    root = _nh_repo(cfg={"drift_check": {"old_sentence": "block"}})
    big_base = "def old_helper_x():\n    pass\n" + "".join(f"def f_{i}(): pass\n" for i in range(240000))
    check("②前置:造出來的檔超過 4194304 位元組", len(big_base.encode()) > m._DRIFT_M1_PARSE_MAX_BYTES, str(len(big_base)))
    _nh_file(root, "src/big.py", big_base)
    _nh_file(root, "src/c.py", "import argparse\np = argparse.ArgumentParser()\np.add_argument('--foo')\n"
             "def old_name():\n    pass\n\ndef really_gone_x():\n    pass\n")
    _nh_file(root, "src/broken.py", "from typing import Callable\nold_name: Callable = h\np.add_argument('--foo')\ndef (\n")
    _nh_file(root, "src/half.py", "def half_gone_x():\n    pass\n")
    (root / "src" / "lat.py").write_bytes(b"# \xe9t\xe9\ndef lat_name_x():\n    pass\n")
    _nh_file(root, "src/only_bad.py", "def (\n")
    _m1_note(root, "Systems/A.md", "# A\n用 old_helper_x\n用 old_name\n用 --foo\n用 really_gone_x\n用 half_gone_x\n用 lat_name_x")
    base = _m1_commit(root, "base")
    _nh_file(root, "src/big.py", big_base.replace("def old_helper_x():\n    pass\n", ""))
    _nh_file(root, "src/c.py", "x = 1\n")
    _nh_file(root, "src/half.py", "def (\n")
    (root / "src" / "lat.py").write_bytes(b"# \xe9t\xe9\ny = 1\n")
    tip = _m1_commit(root, "change")
    t0 = _t.perf_counter()
    r = _m1_check(root, base, tip)
    got = {n for f in r["handle"] + r["listed"] for n in f["names"]}
    check("①前置:判完", r["state"] == "done", str({k: v for k, v in r.items() if k not in ("handle", "listed")}))
    check("①改到的檔一版剖不動 → 那支不抽候選、記剖不動", "half_gone_x" not in r["gone"] and r["unparsable"] == ["src/half.py"], str(r["gone"]))
    check("②超過 4 MB → 兩版文字抽定義、照樣判消失並列出", "old_helper_x" in got and "src/big.py" in r["text_defs"], str(got))
    check("③終點語料剖不動的檔用文字抽:old_name: Callable = h 與 add_argument('--foo') 算還在", "old_name" not in r["gone"]
          and "--foo" not in r["gone"] and "really_gone_x" in got, str(r["gone"]))
    check("⑤latin-1 位元組的舊檔照剖、不當掉", "lat_name_x" in got, str(got))
    rc, out = _m1_report(r, "warn", root=root, base=base, tip=tip)
    check("②④印「N 支剖不動、M 支用文字比對:路徑」、帳 text_defs", "1 支剖不動、" in out and "支用文字比對:src/half.py、src/big.py" in out
          and _m1_events(root)[-1]["text_defs"] == len(r["text_defs"]) and "src/big.py" in _m1_events(root)[-1]["text_defs_paths"],
          out + str(_t.perf_counter() - t0))
    txt = "def alpha_a():\n    pass\n  def ind_b(x):\nclass Cc_c(Base):\nmod_d = 1\nmod_e: int = 2\nmod_f: int\nmod_g == 3\n" \
          "    ind_h = 4\nasync def as_i():\n# def cm_j\nx.attr_k = 5\n"
    batch = ["alpha_a", "ind_b", "Cc_c", "mod_d", "mod_e", "mod_f", "mod_g", "ind_h", "as_i", "cm_j", "attr_k", "alpha", "mod"]
    td = m._drift_m1_text_defs(txt)
    diff = [n for n in batch if (n in td) != bool(m._drift_py_def_re(n, False).search(txt))]
    check("④_drift_m1_text_defs 對一批名稱的判斷跟 _drift_py_def_re 逐一相同", not diff, str(diff))
    _nh_file(root, "src/only_bad.py", "def ( changed\n")
    t2 = _m1_commit(root, "only bad")
    r2 = _m1_check(root, tip, t2)
    rc, out = _m1_report(r2, "block", root=root, base=tip, tip=t2)
    e = _m1_events(root)[-1]
    check("⑥只改一支剖不動的 .py → 結論行、「1 支剖不動」、帳 done/candidates 0", r2["state"] == "done" and r2["candidates"] == 0
          and "舊句檢查:這次改到 1 支程式檔,沒有名稱消失" in out and "1 支剖不動" in out and e["state"] == "done"
          and e["candidates"] == 0 and rc == 0, out + str(e))


def t_drift_m1_not_in_scan():
    """[S12] drift scan、doctor、drift exam 不跑 m1(scan 的計數與標頭沒有 m1);drift fix --kind m1 回 2 並列出能用的種類。

    翻紅釘:scan 改回用 _DRIFT_KINDS → ②紅;判定放進 _drift_check_core → ④紅。
    """
    print("t_drift_m1_not_in_scan")
    import inspect, json as _j
    m = _load_lumos_inproc()
    root = _nh_repo()
    vault = root / _M1_VAULT
    _nh_file(root, "src/a.py", "def gone_name_x():\n    pass\n")
    _m1_note(root, "Systems/A.md", "# A\n呼叫 gone_name_x。", about=["src/a.py"])
    base = _m1_commit(root, "base")
    _nh_file(root, "src/a.py", "x = 1\n")
    _m1_commit(root, "del")
    _rc, out = _m1_run(root, f"{base}..HEAD")
    check("①前置:drift check 列出 m1", "[m1 " in out, out[-400:])
    r = run(vault, "drift", "scan")
    head = r.stdout.split("\n")[0] if r.stdout else ""
    check("②scan 的標頭與計數沒有 m1、輸出不含 m1", r.returncode == 0 and "存量漂移健檢" in head and "m1" not in r.stdout
          and "舊東西" not in r.stdout, r.stdout[:400])
    r = run(vault, "drift", "scan", "--json")
    check("②scan --json 沒有 m1", r.returncode == 0 and not any(f["kind"] == "m1" for f in _j.loads(r.stdout)["findings"]), r.stdout[:300])
    r = run(vault, "doctor")
    check("③doctor 不含 m1 的發現", "[m1" not in r.stdout + r.stderr and "舊東西" not in r.stdout + r.stderr, "")
    r = run(vault, "drift", "fix", "Systems/A", "7", "--kind", "m1")
    check("③drift fix --kind m1 → rc 2 並列出能用的種類", r.returncode == 2 and "c1/c2/c3/c4/c5" in r.stderr, r.stdout + r.stderr)
    srcs = [inspect.getsource(getattr(m, n)) for n in ("_drift_check_core", "cmd_drift_exam", "_drift_exam_one",
                                                        "_drift_exam_history", "_drift_exam_replay", "cmd_drift_scan",
                                                        "_drift_doctor_lines")]
    check("④check core、考試(含 --history)、scan、doctor 都不呼叫舊句判定", not any("_drift_old_sentence_check" in s for s in srcs), "")


def t_drift_m1_output_text():
    """[S13] 有要處理或只列出時照〈做法〉3 的字樣印到 stderr:warn「提醒:…(drift_check.old_sentence=warn,不擋)」、block「擋下:…」;
    先要處理段、再只列出段;超過 20 筆那句不提 drift scan;不印借來的舊表態理由;要處理 0、只列出 2 沒有開頭詞、rc 0。

    翻紅釘:只列出段排在前面 → ②紅;超過 20 筆沿用「lumos drift scan 看全部」→ ④紅;m1 借 _drift_old_reason → ⑤紅。
    """
    print("t_drift_m1_output_text")
    h = [_m1_f("Systems/A.md", 7, ["foo_bar"])]
    l_ = [_m1_f("Systems/B.md", 9, ["baz_qux"], layer="list")]
    rc, out = _m1_report(_m1_res(handle=h, listed=l_), "warn")
    check("①warn 的結論行", rc == 0 and "提醒:舊句檢查:這次推送消失了 3 個名稱,筆記裡還在講的——要處理 1 筆、只列出 1 筆"
          "(drift_check.old_sentence=warn,不擋)" in out, out)
    rc, out = _m1_report(_m1_res(handle=h, listed=l_), "block")
    check("①block 的結論行、rc 1", rc == 1 and "擋下:舊句檢查:這次推送消失了 3 個名稱,筆記裡還在講的——要處理 1 筆、只列出 1 筆\n" in out, out)
    check("②先要處理段、再只列出段", 0 < out.index("Systems/A.md:7") < out.index("Systems/B.md:9"), out)
    check("③每筆一行 [m1 …] 路徑:行  原文,下一行消失的名稱與起點路徑;改法帶改成歷史說法",
          "  [m1 程式改了、筆記還在講舊東西] Systems/A.md:7  呼叫 foo_bar\n      消失的名稱:`foo_bar`(原本在 src/a.py)" in out
          and "改成歷史說法(例:「原本叫 <名稱>,已移除」)或刪掉這句" in out, out)
    many = [_m1_f(f"Systems/M{i}.md", 3, ["foo_bar"]) for i in range(25)]
    rc, out = _m1_report(_m1_res(handle=many), "warn")
    check("④超過 20 筆:「其餘 5 筆這裡沒印;改完這些再推會再列」、不提 drift scan",
          out.count("其餘 5 筆這裡沒印;改完這些再推會再列") == 2 and "drift scan" not in out, out[-600:])
    root = _nh_repo()
    _nh_file(root, "src/a.py", "def foo_bar_x():\n    pass\n")
    _m1_note(root, "Systems/A.md", "# A\n呼叫 foo_bar_x。")
    (root / "governance").mkdir(exist_ok=True)
    (root / "governance" / "drift-acks.jsonl").write_text(
        '{"id": "DACK-1", "path": "docs/kg-knowledge/Systems/Gone.md", "text": "呼叫 foo_bar_x。", "kind": "m1", '
        '"reason": "借來的理由XYZ", "names": ["zzz_q"], "seq": 1}\n', encoding="utf-8")
    base = _m1_commit(root, "base")
    _nh_file(root, "src/a.py", "x = 1\n")
    tip = _m1_commit(root, "del")
    rc, out = _m1_run(root, f"{base}..{tip}")
    check("⑤前置:那一行照列(舊表態名稱不涵蓋)", "Systems/A.md" in out and "foo_bar_x" in out, out)
    check("⑤不印借來的舊表態理由", "借來的理由XYZ" not in out and "舊理由" not in out, out)
    two = [_m1_f("Systems/B.md", 9, ["baz_qux"], layer="list"), _m1_f("Systems/C.md", 9, ["baz_qux"], layer="list")]
    for mode in ("warn", "block"):
        rc, out = _m1_report(_m1_res(listed=two), mode)
        first = out.split("\n")[0]
        check(f"⑥要處理 0、只列出 2({mode}):沒有開頭詞、rc 0", rc == 0
              and first == "舊句檢查:這次推送消失了 3 個名稱,筆記裡還在講的——要處理 0 筆、只列出 2 筆", out)


def t_drift_m1_gate_off_wording():
    """[S14] gate=off 而 old_sentence 明寫不是 off → 印「c1 到 c5(原文是 en dash)與回頭條件關掉了…舊句檢查另有明寫的開關…」,不印「關掉了…跳過」;兩個都 off 照原來那句。

    翻紅釘:gate=off 照舊直接回 → ①紅(m1 沒跑、原句還在)。
    """
    print("t_drift_m1_gate_off_wording")
    for osm, want, not_want in (
            ("warn", "存量漂移檢查:c1\u2013c5 與回頭條件關掉了(drift_check.gate=off);舊句檢查另有明寫的開關 drift_check.old_sentence,有改到程式檔時照跑",
             "這道檢查關掉了"),
            ("off", "存量漂移檢查:這個專案把這道檢查關掉了(drift_check.gate=off),跳過", "舊句檢查另有")):
        root = _nh_repo(cfg={"drift_check": {"gate": "off", "old_sentence": osm}})
        _nh_file(root, "src/a.py", "def gone_name_x():\n    pass\n")
        _m1_note(root, "Systems/A.md", "# A\n呼叫 gone_name_x。")
        base = _m1_commit(root, "base")
        _nh_file(root, "src/a.py", "x = 1\n")
        _m1_commit(root, "del")
        rc, out = _m1_run(root, f"{base}..HEAD")
        check(f"①old_sentence={osm}:那一句逐字", rc == 0 and want in out and not_want not in out, out)
        check(f"①old_sentence={osm}:m1 {'照跑' if osm != 'off' else '不跑'}", ("舊句檢查:" in out.replace(want, "")) == (osm != "off"), out)


def t_old_sentence_default_follows_gate():
    """[S1][S2][S3][S4][S26] drift_check.old_sentence 沒寫(含 null、值看不懂)→ 照總開關 drift_check.gate(總開關沒寫是 block;
    總開關 off 時沒寫的 m1 不跑);設定檔讀不成 JSON、drift_check 不是物件、整份設定不是物件 → block 並各講一句「照預設 block」;
    明寫的 warn/block/off 照原義、不受總開關影響(舊行為 gate=off 加 old_sentence=block 照跑照擋)。
    Projects/舊句兩道轉擋_計劃〈設計〉開關。

    翻紅釘:預設改回固定 warn → ①②紅;沒寫時不看總開關(只看 block)→ ③紅;gate=off 仍跑沒寫的 m1 → ⑤紅;
    明寫值也被總開關蓋掉 → ④⑥紅;壞設定仍照 warn → ⑦紅;掛鉤逃生句還說「改 gate 沒用」→ ⑨紅。
    """
    print("t_old_sentence_default_follows_gate")
    import json as _j
    m = _load_lumos_inproc()

    def run_case(cfg_text, label):
        root = _nh_repo()
        if cfg_text is not None:
            (root / ".lumos").mkdir(exist_ok=True)
            (root / ".lumos" / "config.json").write_text(cfg_text, encoding="utf-8")
        _nh_file(root, "src/a.py", "def gone_name_x():\n    pass\n")
        _m1_note(root, "Systems/A.md", "# A\n呼叫 gone_name_x。", about=("src/a.py",))
        base = _m1_commit(root, f"base {label}")
        _nh_file(root, "src/a.py", "x = 1\n")
        _m1_commit(root, f"del {label}")
        return _m1_run(root, f"{base}..HEAD")

    def dc(**kw):
        return _j.dumps({"drift_check": kw})
    # S1:什麼都沒寫(沒設定檔、設定檔沒有 drift_check、drift_check 空物件、old_sentence 寫 null)→ 預設 block
    for label, txt in (("沒設定檔", None), ("設定檔沒 drift_check", '{"other": 1}'), ("drift_check 空物件", dc()),
                       ("old_sentence null", dc(old_sentence=None)), ("old_sentence 寫壞值 gate 沒寫", dc(old_sentence="on"))):
        rc, out = run_case(txt, label)
        check(f"①S1 {label}:rc1 並印舊句清單", rc == 1 and "擋下:舊句檢查" in out and "gone_name_x" in out, out[-700:])
    # S2:gate=warn、old_sentence 沒寫 → 照 warn:只印清單、rc0
    for label, txt in (("沒寫", dc(gate="warn")), ("null", dc(gate="warn", old_sentence=None)),
                       ("壞值", dc(gate="warn", old_sentence="on"))):
        rc, out = run_case(txt, "gw " + label)
        check(f"②S2 gate=warn、old_sentence {label}:rc0 只提醒、清單還在", rc == 0 and "提醒:舊句檢查" in out
              and "擋下:舊句檢查" not in out and "gone_name_x" in out, out[-700:])
    rc, out = run_case(dc(gate="warn", old_sentence="on"), "gw bad")
    check("②壞值那句照講,並說照總開關 warn", "drift_check.old_sentence 只能是 block/warn/off,你寫的是 'on',照總開關 warn" in out, out[-700:])
    # gate 寫 block 明著寫、old_sentence 沒寫 → block
    rc, out = run_case(dc(gate="block"), "gb")
    check("③gate=block、old_sentence 沒寫:rc1", rc == 1 and "擋下:舊句檢查" in out, out[-700:])
    # S3 與明寫不受總開關影響
    rc, out = run_case(dc(gate="off", old_sentence="block"), "off+block")
    check("④S3 gate=off、old_sentence=block:rc1", rc == 1 and "擋下:舊句檢查" in out and "gone_name_x" in out, out[-700:])
    rc, out = run_case(dc(gate="warn", old_sentence="block"), "warn+block")
    check("④gate=warn、old_sentence=block:rc1(明寫照原義)", rc == 1 and "擋下:舊句檢查" in out, out[-700:])
    rc, out = run_case(dc(gate="block", old_sentence="warn"), "block+warn")
    check("⑥gate=block、old_sentence=warn:rc0 只提醒(明寫 warn 不被總開關蓋成擋)", rc == 0 and "提醒:舊句檢查" in out
          and "擋下:舊句檢查" not in out, out[-700:])
    rc, out = run_case(dc(gate="block", old_sentence="off"), "block+off")
    check("⑥gate=block、old_sentence=off:m1 不跑", rc == 0 and "舊句檢查" not in out and "gone_name_x" not in out, out[-700:])
    # S26:gate=off、old_sentence 沒寫 → m1 不跑
    for label, txt in (("沒寫", dc(gate="off")), ("null", dc(gate="off", old_sentence=None)), ("壞值", dc(gate="off", old_sentence="on"))):
        rc, out = run_case(txt, "goff " + label)
        check(f"⑤S26 gate=off、old_sentence {label}:rc0、m1 沒跑", rc == 0 and "舊句檢查:" not in out and "gone_name_x" not in out
              and "擋下" not in out, out[-700:])
    rc, out = run_case(dc(gate="off"), "goff wording")
    check("⑤gate=off 又沒寫 old_sentence:印的是整道關掉那句,不說舊句檢查照跑",
          "存量漂移檢查:這個專案把這道檢查關掉了(drift_check.gate=off),跳過" in out and "舊句檢查另有" not in out
          and "照跑" not in out, out[-700:])
    rc, out = run_case(dc(gate="off", old_sentence="warn"), "goff warn")
    check("⑤gate=off、old_sentence=warn 明寫:整句改成「明寫的舊句檢查照跑」", rc == 0 and "舊句檢查另有明寫的開關 drift_check.old_sentence" in out
          and "提醒:舊句檢查" in out, out[-700:])
    # S4:壞設定 → block 並講一句照預設 block
    for label, txt, hint in (("讀不成 JSON", "{bad", "讀不成 JSON,舊句檢查(drift_check.old_sentence)照預設 block"),
                             ("drift_check 是字串", '{"drift_check": "off"}', "drift_check 不是物件,舊句檢查(drift_check.old_sentence)照預設 block"),
                             ("drift_check 是 null", '{"drift_check": null}', "drift_check 不是物件,舊句檢查(drift_check.old_sentence)照預設 block"),
                             ("drift_check 是陣列", '{"drift_check": ["warn"]}', "drift_check 不是物件,舊句檢查(drift_check.old_sentence)照預設 block"),
                             ("整份設定是陣列", '["x"]', "舊句檢查(drift_check.old_sentence)照預設 block"),
                             ("整份設定是字串", '"x"', "舊句檢查(drift_check.old_sentence)照預設 block")):
        rc, out = run_case(txt, label)
        check(f"⑦S4 {label}:rc1、清單、另講一句照預設 block", rc == 1 and "擋下:舊句檢查" in out and "gone_name_x" in out and hint in out,
              out[-900:])
    # 解析本體(不經 git):回傳值與提醒
    f = m._drift_old_sentence_config
    check("⑧沒寫 → 照 gate(三種)", [f({"drift_check": {}}, False, g)[0] for g in ("block", "warn", "off")] == ["block", "warn", "off"], "")
    check("⑧null → 照 gate", f({"drift_check": {"old_sentence": None}}, False, "warn") == ("warn", []), "")
    check("⑧壞值 → 照 gate 並講一句", f({"drift_check": {"old_sentence": "on"}}, False, "off")
          == ("off", ["drift_check.old_sentence 只能是 block/warn/off,你寫的是 'on',照總開關 off"]), str(f({"drift_check": {"old_sentence": "on"}}, False, "off")))
    check("⑧明寫三值不看 gate", all(f({"drift_check": {"old_sentence": v}}, False, g)[0] == v
                                    for v in ("block", "warn", "off") for g in ("block", "warn", "off")), "")
    check("⑧壞設定一律 block(不管傳進來的 gate)", f(None, True, "off")[0] == "block" and f({"drift_check": 3}, False, "off")[0] == "block"
          and f([1], False, "off")[0] == "block" and f("x", False, "off")[0] == "block", "")
    check("⑧壞設定各講一句照預設 block", "照預設 block" in f(None, True)[1][0] and "照預設 block" in f({"drift_check": 3})[1][0]
          and "照預設 block" in f([1])[1][0], "")
    check("⑧沒設定檔(cfg 是 None、bad 假)→ 照 gate、不講話", f(None, False, "block") == ("block", []) and f(None, False, "off") == ("off", []), "")
    got = [m._drift_config(t) for t in (b'{"drift_check": {"gate": "warn"}}', b'{"drift_check": {"gate": "off"}}', None, b"{bad")]
    check("⑧_drift_config 第四個回傳值照 gate:warn→warn、off→off、沒設定→block、壞掉→block",
          [g[3] for g in got] == ["warn", "off", "block", "block"], str(got))
    # 掛鉤逃生句與 --help
    hook = (Path(__file__).parent / "hooks" / "pre-push").read_text(encoding="utf-8")
    check("⑨掛鉤 drift 那段不再說「改 gate 沒用」", "改 gate 沒用" not in hook and "drift_check.old_sentence" in hook, "")
    r = subprocess.run([sys.executable, str(GRAPHCTL), "drift", "check", "--help"], capture_output=True, text=True)
    r2 = subprocess.run([sys.executable, str(GRAPHCTL), "drift", "--help"], capture_output=True, text=True)
    check("⑨drift check 的 --help 與命令表不再說舊句檢查沒寫是 warn",
          "沒寫是 warn" not in r.stdout + r2.stdout and "drift_check.old_sentence" in r.stdout, r.stdout[-600:])


def t_drift_m1_code_path_scope():
    """[S15] _drift_m1_code_path 對不是 .md 的路徑跟參考實作 not _excluded(p) 逐一相同;_drift_m1_code_kind 用既有程式檔清單
    (刻意差異第 1 條:src/OldPanel.tsx 是 other、config.json 與 legacy.PY 不是程式檔、#! python 的 scripts/lumos 是 py)。

    翻紅釘:不排除 governance/ → ①紅;改抄參考實作的 TEXT_EXTS → ②紅。
    """
    print("t_drift_m1_code_path_scope")
    m = _load_lumos_inproc()
    paths = ["docs/x.py", "governance/eval/x.py", "a/node_modules/x.py", "build/x.py", "x/package-lock.json", "src/a.py", "scripts/lumos"]
    got = [m._drift_m1_code_path(p) for p in paths]
    check("①前五個 False、後兩個 True", got == [False] * 5 + [True] * 2, str(got))
    ref = Path(GRAPHCTL).resolve().parent.parent / "governance" / "eval" / "drift-exam" / "old-sentence" / "old_sentence_exp.py"
    if ref.is_file():
        import importlib.machinery, importlib.util
        ld = importlib.machinery.SourceFileLoader("_m1_ref_exp", str(ref))
        spec = importlib.util.spec_from_loader("_m1_ref_exp", ld)
        mod = importlib.util.module_from_spec(spec)
        ld.exec_module(mod)
        check("①跟參考實作的 not _excluded(p) 逐一相同", got == [not mod._excluded(p) for p in paths], "")
    else:
        print("  (消費端沒有參考實作,跳過逐一比對)")
    check("②src/OldPanel.tsx → other;config.json、legacy.PY → None;#! python 的 scripts/lumos → py",
          m._drift_m1_code_kind("src/OldPanel.tsx", "") == "other" and m._drift_m1_code_kind("config.json", "{") is None
          and m._drift_m1_code_kind("legacy.PY", "") is None
          and m._drift_m1_code_kind("scripts/lumos", "#!/usr/bin/env python3") == "py"
          and m._drift_m1_code_kind("tools/run", "#!/bin/bash") == "other" and m._drift_m1_code_kind("Makefile", "all:") is None,
          "")


def t_drift_m1_conclusion_lines():
    """[S17] 沒有發現或判不了時逐字印〈做法〉3 那一句;判不了的三種 block 時「擋下:」並接 LUMOS_SKIP_DRIFT_CHECK=1 git push,
    warn 時「提醒:」加句尾。

    翻紅釘:要處理 0、只列出 2 印成「沒有還在講的」→ ③紅;判不了在 warn 也接略過指令 → ⑦紅。
    """
    print("t_drift_m1_conclusion_lines")
    lst2 = [_m1_f("Systems/B.md", 9, ["baz_qux"], layer="list"), _m1_f("Systems/C.md", 9, ["baz_qux"], layer="list")]
    cases = [("①done 候選 0", _m1_res(cand=0), "舊句檢查:這次改到 2 支程式檔,沒有名稱消失"),
             ("②done 候選 3、兩層都 0", _m1_res(cand=3), "舊句檢查:這次消失 3 個名稱,筆記裡沒有還在講的"),
             ("③done 候選 3、要處理 0、只列出 2", _m1_res(cand=3, listed=lst2),
              "舊句檢查:這次推送消失了 3 個名稱,筆記裡還在講的——要處理 0 筆、只列出 2 筆"),
             ("⑤no-base", _m1_res(state="no-base", cand=None), "舊句檢查:這次沒有起點版可比,不判")]
    for label, res, want in cases:
        for mode in ("warn", "block"):
            rc, out = _m1_report(res, mode)
            check(f"{label}({mode}):沒有開頭詞、rc 0", rc == 0 and out.split("\n")[0] == want, out)
    rc, out = _m1_report(_m1_res(cand=0, text_defs=["src/big.py"], too_long=1), "warn")
    check("④另印「0 支剖不動、1 支用文字比對:<路徑>」與「1 個名稱太長或帶控制字元、頭尾空白,沒列」",
          "0 支剖不動、1 支用文字比對:src/big.py" in out and "1 個名稱太長或帶控制字元、頭尾空白,沒列" in out, out)
    unk = [("timeout", _m1_res(state="timeout", cand=None), "舊句檢查:這次沒跑完(時間到,30 秒)"),
           ("git-failed", _m1_res(state="git-failed", cand=None), "舊句檢查:git 讀不出這次推送的範圍或內容,這次沒判"),
           ("unreadable", _m1_res(state="unreadable", bad_touched=1), "舊句檢查:這次改到的筆記有 1 篇讀不出,這次沒判完")]
    for st, res, want in unk:
        rc, out = _m1_report(res, "block")
        check(f"⑥{st}(block):擋下、接略過指令、rc 1", rc == 1 and out.split("\n")[0] == "擋下:" + want
              and "LUMOS_SKIP_DRIFT_CHECK=1 git push" in out, out)
        rc, out = _m1_report(res, "warn")
        check(f"⑦{st}(warn):提醒、句尾不擋、不接略過指令、rc 0", rc == 0
              and out.split("\n")[0] == "提醒:" + want + "(drift_check.old_sentence=warn,不擋)" and "LUMOS_SKIP" not in out, out)


def t_drift_m1_long_names():
    """[S18] 候選名稱超過 200 字或帶控制字元 → 不列、印「N 個名稱太長或帶控制字元、頭尾空白,沒列」、帳 too_long;
    200 字照列、照提示表態 rc 0。

    翻紅釘:拿掉長度上限 → ①紅;上限改成 199 → ②紅。
    """
    print("t_drift_m1_long_names")
    import shlex
    root = _nh_repo()
    vault = root / _M1_VAULT
    n200 = "a_" + "b" * 198
    n201 = "c_" + "d" * 199
    _nh_file(root, "src/a.py", f"def {n200}():\n    pass\n\ndef {n201}():\n    pass\n\ndef short_ok_x():\n    pass\n")
    tabp = "src/tab\there.py"
    _nh_file(root, tabp, "x = 1\n")
    _m1_note(root, "Systems/A.md", f"# A\n呼叫 {n201} 與 short_ok_x\n呼叫 {n200}")
    base = _m1_commit(root, "base")
    _nh_file(root, "src/a.py", "y = 1\n")
    (root / tabp).unlink()
    tip = _m1_commit(root, "del")
    r = _m1_check(root, base, tip)
    rows = {f["line"]: f["names"] for f in r["handle"] + r["listed"]}
    l1, l2 = _m1_lno(root, "Systems/A.md", n201), _m1_lno(root, "Systems/A.md", "呼叫 " + n200)
    check("①前置:201 字的與帶 tab 的路徑都是消失的候選", n201 in r["gone"] and tabp in r["gone"], str(list(r["gone"])[:6]))
    check("①201 字與帶控制字元的(路徑與檔名)不列、too_long 記 3", r["too_long"] == 3 and all(n201 not in v and tabp not in v for v in rows.values()),
          str(r["too_long"]))
    check("②同一行另有合格名稱時只列合格的", rows.get(l1) == ["short_ok_x"], str(rows))
    check("②200 字的照列", rows.get(l2) == [n200], str(rows))
    _rc, out = _m1_report(r, "warn", root=root, base=base, tip=tip)
    check("③結論行下面印「3 個名稱太長或帶控制字元、頭尾空白,沒列」、帳 too_long 3",
          "3 個名稱太長或帶控制字元、頭尾空白,沒列" in out and _m1_events(root)[-1]["too_long"] == 3, out)
    hint = next((x.split("確定照留就 ", 1)[1] for x in out.splitlines() if f"--name={n200}" in x), None)
    check("④前置:200 字名稱的表態提示有印", hint is not None, out[-600:])
    if hint:
        r2 = run(vault, *shlex.split(hint.replace("<為什麼照留>", "兩百字的名稱照留"))[1:])
        check("④照提示表態 rc 0", r2.returncode == 0, r2.stdout + r2.stderr)


# ═══ 舊句檢查 m1 代碼審 r1 折入(每支對一組發現;家 Systems/存量漂移守衛)═══

def _m1_git_b(root, *args, stdin=None):
    """git 呼叫,參數可以是位元組(造非 UTF-8 檔名用)。"""
    import subprocess as sp
    return sp.run([b"git", b"-C", str(root).encode(), *[a if isinstance(a, bytes) else a.encode() for a in args]],
                  input=stdin, capture_output=True)


def _m1_index_add(root, path_bytes, content_bytes):
    """不經磁碟,直接把一支檔(檔名是任意位元組)放進索引。"""
    oid = _m1_git_b(root, "hash-object", "-w", "--stdin", stdin=content_bytes).stdout.decode().strip()
    _m1_git_b(root, "update-index", "--add", "--cacheinfo", b"100644," + oid.encode() + b"," + path_bytes)


def t_drift_m1_review_r1_non_utf8_and_guard():
    """代碼審 r1 正確性-F1:檔名不是 UTF-8 時寫帳與印出照 _nodehome_show 轉義、不丟例外(warn 回 0);
    m1 裡任何沒預料到的例外兜底成判不了(state error):warn 回 0、block 回 1;連印出記帳都出錯時也只印一行。

    翻紅釘:帳的路徑不轉義 → ①紅(UnicodeEncodeError、rc 1);拿掉兜底 → ③紅(例外丟出去)。
    """
    print("t_drift_m1_review_r1_non_utf8_and_guard")
    import contextlib, io
    m = _load_lumos_inproc()
    root = _nh_repo()
    _nh_file(root, "src/a.py", "def old_func_x():\n    pass\n")
    _m1_note(root, "Systems/A.md", "# A\n只是說明")
    _nh_git(root, "add", "-A")
    _m1_index_add(root, b"legacy/se\xf1or.py", b"print 'py2 syntax'\n")
    _m1_index_add(root, b"docs/kg-knowledge/Systems/se\xf1or.md",
                  "---\ntype: system\n---\n# N\n呼叫 old_func_x。\n".encode())
    _nh_git(root, "commit", "-qm", "base", "--no-verify")
    base = _na_head(root)
    _nh_file(root, "src/a.py", "x = 1\n")
    _nh_git(root, "add", "src/a.py")
    _nh_git(root, "commit", "-qm", "del", "--no-verify")
    tip = _na_head(root)
    ls = _m1_git_b(root, "ls-tree", "-r", "--name-only", "-z", tip).stdout
    check("①前置:樹上真的有非 UTF-8 檔名的程式檔與筆記", b"se\xf1or.py" in ls and b"se\xf1or.md" in ls, str(ls[:300]))
    rc, out = _m1_run(root, f"{base}..{tip}")
    ev = _m1_events(root)
    e = ev[-1] if ev else {}
    check("①warn:不當掉、rc 0、記一筆帳", rc == 0 and "Traceback" not in out and len(ev) == 1 and e.get("state") == "done", out[-800:])
    check("①帳裡非 UTF-8 的路徑照 _nodehome_show 換成替代字元(剖不動的終點檔、只列出那一行的筆記)",
          "legacy/se�or.py" in (e.get("text_defs_paths") or [])
          and any(r["path"] == "Systems/se�or.md" for r in (e.get("rows") or [])), str(e)[:600])
    vault_rel = _M1_VAULT

    def guarded(mode):
        buf = io.StringIO()
        with contextlib.redirect_stderr(buf), _M1Home():
            rc_ = m._drift_m1_guarded(Path(root), mode, base, tip, vault_rel)
        return rc_, buf.getvalue()
    orig = m._drift_old_sentence_check
    m._drift_old_sentence_check = lambda *a, **k: (_ for _ in ()).throw(RuntimeError("boom-x"))
    try:
        ev0 = _m1_events(root)
        rc_w, out_w = guarded("warn")
        new_w = _gov_since(_m1_events(root), ev0)     # 同一秒寫進兩本的事件合讀後先後不固定,不取 [-1]
        e_w = new_w[-1] if new_w else {}
        rc_b, out_b = guarded("block")
    finally:
        m._drift_old_sentence_check = orig
    check("②判定丟例外:warn 印判不了、rc 0、帳 state error", rc_w == 0 and "工具內部出錯" in out_w and "boom-x" in out_w
          and len(new_w) == 1 and len(_gov_since(_m1_events(root), ev0)) == 2
          and e_w.get("state") == "error" and e_w.get("kind") == "warned", out_w + str(e_w))
    check("②block 照判不了的規矩擋、接略過指令", rc_b == 1 and "擋下:舊句檢查:工具內部出錯" in out_b
          and "LUMOS_SKIP_DRIFT_CHECK=1 git push" in out_b, out_b)
    orig_rep = m._drift_m1_report
    m._drift_m1_report = lambda *a, **k: (_ for _ in ()).throw(ValueError("rep-x"))
    try:
        rc_w, out_w = guarded("warn")
        rc_b, out_b = guarded("block")
    finally:
        m._drift_m1_report = orig_rep
    check("③連印出記帳都出錯:只印一行,warn 0、block 1", rc_w == 0 and rc_b == 1 and "帳也沒記" in out_w, out_w)


def t_drift_m1_review_r1_scan_budget():
    """代碼審 r1 資安-F1、邊界-F1:3 萬個名稱加超長行、同一行大量命中,都在 m1 的時間上限內結束;超過單行上限的行不掃、
    計數進結論行與帳;逐行只拿可能命中的名稱跑比對,結果跟整條正則相同;句內字眼的預先計算跟原本逐次算的相同。

    翻紅釘:拿掉單行上限 → ①紅(時間爆掉或沒計數);逐行候選漏掉某類名稱 → ②紅;預先計算的切句位置偏一格 → ③紅。
    """
    print("t_drift_m1_review_r1_scan_budget")
    import random, time as _t
    m = _load_lumos_inproc()
    root = _nh_repo()
    names = [f"gen_func_{i:06d}" for i in range(30000)]
    _nh_file(root, "src/gen.py", "".join(f"def {n}(): pass\n" for n in names))
    _m1_note(root, "Systems/A.md", "# A", about=["src/gen.py"])
    base = _m1_commit(root, "base")
    (root / "src" / "gen.py").unlink()
    dense = "現況 " + " ".join(names[i % 900] for i in range(1150))          # 單行 1 萬 9 千多字、同一行 1150 次命中
    body = ["# A", "(已移除 " + " ".join(names) + ")", " ".join(f"abc{i}" for i in range(30000)), dense]
    body += [f"呼叫 {n}" for n in names[:2000]]
    _m1_note(root, "Systems/A.md", "\n".join(body), about=["src/gen.py"])
    tip = _m1_commit(root, "del")
    check("①前置:dense 那行在上限內、另兩行超過", len(dense) <= m._DRIFT_M1_LINE_MAX < len(body[1]), str(len(dense)))
    t0 = _t.monotonic()
    _rc, out = _m1_run(root, f"{base}..{tip}")
    dt = _t.monotonic() - t0
    e = (_m1_events(root) or [{}])[-1]
    check("①3 萬個名稱加超長行:在 m1 的時間上限內結束、判完", dt < m._DRIFT_M1_BUDGET_SEC and e.get("state") == "done"
          and e.get("candidates") == 30002, f"{dt:.1f}s {str(e)[:300]}")
    check("①超過單行上限的行不掃、計數進結論行與帳(代碼審 r3 起分兩種:含消失名稱的 1 行算判不了,無關的 1 行只計數)",
          e.get("long_lines") == 1 and e.get("long_lines_other") == 1
          and f"有 1 行太長沒看(超過 {m._DRIFT_M1_LINE_MAX} 字)" in out.split("\n")[0], out[:600])
    check("①同一行大量命中照判(dense 那行列出、2000 行各一筆)", e.get("handle") == 2001, str(e.get("handle")))
    rnd = random.Random(11)
    pool = ["foo_bar", "foo_bar_x", "計算_總額", "tools/匯出報表.py", "run_all", "run_all.sh", "--restore", "--dry-run",
            "Tool_x-v2", "a/b", "中文名", "x.py"]
    toks = [*pool, "呼叫", " ", "(", ")", "。", "曾", "_", "-", "/", ".", "zz", "原本"]
    bad = []
    for _i in range(3000):
        sub = rnd.sample(pool, rnd.randint(1, len(pool)))
        ln = "".join(rnd.choice(toks) for _j in range(rnd.randint(1, 30)))
        rx = m._drift_m1_name_rx(sub)
        full = sorted({x.group(0) for x in rx.finditer(ln) if not m._drift_m1_clause_hist(ln, x.start())})
        if m._drift_m1_line_hits(m._drift_m1_name_index(sub), ln) != full:
            bad.append((sub, ln))
    check("②逐行只拿可能命中的名稱:結果跟整條正則加逐次句內判定逐字相同(3000 組隨機)", not bad, str(bad[:3]))
    alpha = [*"()（）。;；!?！？ab 曾x", "原本", "removed", "Removed"]
    bad = []
    for _i in range(3000):
        ln = "".join(rnd.choice(alpha) for _j in range(rnd.randint(0, 40)))
        cl = m._DriftM1Clauses(ln)
        bad += [(ln, p) for p in range(len(ln) + 1) if cl.hist(p) != m._drift_m1_clause_hist(ln, p)]
    check("③句內字眼的預先計算跟原本逐次算的逐位置相同", not bad, str(bad[:3]))


def t_drift_m1_review_r1_shebang_either_side():
    """代碼審 r1 外家否決-F1、外家 finder-F1、spec 對照-F4:沒副檔名的 Python 腳本拿掉 #! 或改成 shell,起點版的定義照樣抽;
    起點版或終點版任一邊是 Python 就算 Python 檔;沒副檔名的 Python 檔端到端照判。

    翻紅釘:分類只看終點首行 → ①②紅;不是 Python 的那一版照剖 → ③紅(shell 版剖不動、整支不抽)。
    """
    print("t_drift_m1_review_r1_shebang_either_side")
    root = _nh_repo()
    py = "#!/usr/bin/env python3\ndef {0}():\n    pass\n\ndef keep_{1}():\n    pass\n"
    _nh_file(root, "scripts/tool", py.format("old_helper_x", "a"))
    _nh_file(root, "scripts/tool2", py.format("old_helper_y", "b"))
    _nh_file(root, "scripts/tool3", py.format("old_helper_z", "c"))
    _m1_note(root, "Systems/A.md", "# A\n呼叫 old_helper_x\n呼叫 old_helper_y\n呼叫 old_helper_z\n呼叫 keep_c")
    base = _m1_commit(root, "base")
    _nh_file(root, "scripts/tool", "#!/bin/bash\necho old\n")
    _nh_file(root, "scripts/tool2", "just some text now\n")
    _nh_file(root, "scripts/tool3", "#!/usr/bin/env python3\ndef keep_c():\n    pass\n")
    tip = _m1_commit(root, "reformat")
    res = _m1_check(root, base, tip)
    got = {n for f in res["handle"] + res["listed"] for n in f["names"]}
    check("①前置:判完、三支沒副檔名的檔都算改到的程式檔", res["state"] == "done" and res["code_files"] == 3, str(res))
    check("①Python 腳本改成 shell:起點版的定義照樣抽、消失的列出", "old_helper_x" in got, str(got))
    check("②Python 腳本拿掉 #! 變成純文字:照樣抽、列出", "old_helper_y" in got, str(got))
    check("③兩邊都是 Python 的沒副檔名檔端到端照判;還定義著的不列", "old_helper_z" in got and "keep_c" not in got
          and not res["unparsable"], str(res["unparsable"]))


def t_drift_m1_review_r1_name_canon():
    """代碼審 r1 外家否決-F2、外家 finder-F2、邊界-F2、資安-F2:候選名稱與 --name 用同一支正規化;頭尾空白、U+2028/2029、
    方向覆寫、非 UTF-8 的名稱不列(計入 too_long)也不收表態;照貼提示印的指令一定表態得掉那一行。

    翻紅釘:候選端改回只擋控制字元 → ①②紅;表態端寫入前去空白 → ④紅。
    """
    print("t_drift_m1_review_r1_name_canon")
    import shlex
    m = _load_lumos_inproc()
    bad_names = ["--trail ", " lead_x", "a\u2028b_x", "a\u2029b_x", "x\u202eb_y", "se\udcf1or.py", "", "a" * 201, "a\tb_x"]
    check("①這些名稱正規化後不能用", all(m._drift_m1_name_canon(x) is None for x in bad_names),
          str([x for x in bad_names if m._drift_m1_name_canon(x) is not None]))
    check("①表態端用同一支:每個都 rc 2 那種錯誤、合格的收", all(m._drift_ack_names_err("m1", [x]) for x in bad_names)
          and m._drift_ack_names_err("m1", ["ok_name_x", "--restore"]) is None, "")
    root = _nh_repo(cfg={"drift_check": {"old_sentence": "block"}})
    vault = root / _M1_VAULT
    _nh_file(root, "src/x.py", "import argparse\np = argparse.ArgumentParser()\np.add_argument('--trail ')\n"
             "p.add_argument('--old-flag')\n")
    _nh_file(root, "src/line\u2028break.py", "z = 1\n")
    _m1_note(root, "Systems/N.md", "# N\n用 --trail  與 --old-flag", about=["src/x.py"])
    base = _m1_commit(root, "base")
    _nh_file(root, "src/x.py", "x = 1\n")
    (root / "src" / "line\u2028break.py").unlink()
    _m1_commit(root, "del")
    rc, out = _m1_run(root, f"{base}..HEAD")
    e = _m1_events(root)[-1]
    lno = _m1_lno(root, "Systems/N.md", "--old-flag")
    check("②頭尾空白的旗標、帶 U+2028 的路徑與檔名不列、計入 too_long", e["too_long"] == 3 and "'--name=--trail '" not in out
          and f"Systems/N.md:{lno}" in out and rc == 1, out[-1000:])
    hint = next((x.split("確定照留就 ", 1)[1] for x in out.splitlines() if f"N {lno} --kind m1" in x), None)
    check("③前置:提示只帶合格名稱", hint is not None and "--name=--old-flag" in hint and "trail" not in hint, str(hint))
    if hint:
        r = run(vault, *shlex.split(hint.replace("<為什麼照留>", "舊旗標的說明照留"))[1:])
        _m1_commit(root, "ack")
        rc, out = _m1_run(root, f"{base}..HEAD")
        check("④照貼提示表態後,那一行不再列、block 放行", r.returncode == 0 and f"Systems/N.md:{lno}" not in out and rc == 0,
              r.stderr + out[-600:])


