    _ns_stage(root)
    rc, out = _ns(root)
    check("⑦改名同時結案 → 照樣提醒", "摘要沒跟著改" in out and "Issues/Other2" in out, out[-800:])
    gov = [e for e in _ns_gov(root) if e.get("kind") == "hinted" and (e.get("extra") or e).get("check") == "close-summary"]
