def t_loop_next_lens_scope_root_kind():
    """[鏡頭範圍 S13;代碼審 r2 資安 1、通才 3、邊界 2] loop next 講明判別用的是哪一個根:--json 多一欄 lens_scope_root,
    帶 --repo 是 "--repo"、沒帶是 "ledger"(帳本所在 repo);人讀那一行開頭跟著寫「--repo 指的 repo」或「帳本所在 repo」。
    沒帶 --repo 的那一半在同一行程內做(vault 上層放 SKILL.md 就是帳本所在 repo 是工具鏈)。消費專案也有這一欄(常駐)。
    期望值照計劃字面手寫。應抓到的錯:帶 --repo 仍說「帳本所在 repo」、JSON 沒有根的種類。"""
    import contextlib as _ctx
    import io as _io
    import json as _j
    vault = mkvault()
    tc, cons = _mk_lens_dirs()
    _rc, lt, jt = _lens_next(vault, "code-rk", "--tier", "high", "--repo", str(tc))
    check("①帶 --repo、工具鏈:lens_scope_root=--repo、那一行開頭是「--repo 指的 repo」",
          jt.get("lens_scope_root") == "--repo" and _LENS_SCOPE_LINE_REPO in lt and _LENS_SCOPE_LINE not in lt, str(jt.get("lens_scope_root")))
    _rc, lc, jc = _lens_next(vault, "code-rk", "--tier", "high", "--repo", str(cons))
    check("②帶 --repo、消費專案:lens_scope_root=--repo(常駐)、不印那一行", jc.get("lens_scope_root") == "--repo" and not any("鏡頭範圍" in x for x in lc),
          str(jc.get("lens_scope_root")))
    m = _load_lumos_inproc()
    v2 = mkvault()
    env = m.Env(v2)
    skill = v2.parent / "skills" / "lumos-project-notes" / "SKILL.md"
    skill.parent.mkdir(parents=True)
    skill.write_text("# s\n", encoding="utf-8")
    outs = {}
    for as_json in (False, True):
        buf = _io.StringIO()
        with _ctx.redirect_stdout(buf), _ctx.redirect_stderr(_io.StringIO()):
            m.cmd_loop_next(env, "code-rk", tier="high", as_json=as_json, orchestrator="claude")
        outs[as_json] = buf.getvalue()
    j = _j.loads(outs[True].strip().splitlines()[-1])
    check("③沒帶 --repo、帳本所在 repo 是工具鏈:lens_scope_root=ledger、那一行開頭是「帳本所在 repo」",
          j.get("lens_scope_root") == "ledger" and j.get("lens_scope") == "toolchain" and _LENS_SCOPE_LINE in outs[False].splitlines()
          and _LENS_SCOPE_LINE_REPO not in outs[False].splitlines(), str((j.get("lens_scope_root"), j.get("lens_scope"))))


def t_loop_next_lens_scope_fail_open():
    """[鏡頭範圍 S3]同一行程內把取 repo 根那一步換成丟例外的版本:不印鏡頭範圍、lens_scope=default,
    退出碼與其他輸出跟沒丟例外的消費專案相同(文字與 JSON 兩種模式)。"""
    import contextlib as _ctx
    import io as _io
    import json as _j
    m = _load_lumos_inproc()
    vault = mkvault()
    env = m.Env(vault)
    skill = vault.parent / "skills" / "lumos-project-notes" / "SKILL.md"

    def go(as_json):
        buf = _io.StringIO()
        with _ctx.redirect_stdout(buf), _ctx.redirect_stderr(_io.StringIO()):
            rc = m.cmd_loop_next(env, "code-lensfo", tier="high", as_json=as_json, orchestrator="claude")
        if as_json:
            d = _j.loads(buf.getvalue().strip().splitlines()[-1])
            d.pop("canary_type", None)
            return rc, d
        return rc, [ln for ln in buf.getvalue().splitlines() if not ln.startswith("  canary_type:")]
    base_t, base_j = go(False), go(True)   # 消費專案(vault 上層沒有 SKILL.md)
    skill.parent.mkdir(parents=True)
    skill.write_text("# s\n", encoding="utf-8")
    ok_t, ok_j = go(False), go(True)
    check("★前置★ 不丟例外時,vault 上層是工具鏈本 repo → 印鏡頭範圍、toolchain",
          _LENS_SCOPE_LINE in ok_t[1] and ok_j[1].get("lens_scope") == "toolchain", str(ok_j[1].get("lens_scope")))

    def boom(*_a, **_k):
        raise RuntimeError("注錯:取 repo 根炸掉")
    keep = m._vault_repo_root
    m._vault_repo_root = boom
    try:
        bad_t, bad_j = go(False), go(True)
    finally:
        m._vault_repo_root = keep
    check("①丟例外:文字輸出與退出碼跟消費專案相同(不印鏡頭範圍、無 traceback)", bad_t == base_t, f"{bad_t[0]}/{base_t[0]}")
    check("②丟例外:JSON 與退出碼跟消費專案相同(lens_scope=default)", bad_j == base_j and bad_j[1].get("lens_scope") == "default",
          str(bad_j[1].get("lens_scope")))


def _tpl_text():
    _need_src("skills/lumos-design-loop/templates.md")
    return (Path(GRAPHCTL).resolve().parent.parent / "skills" / "lumos-design-loop" / "templates.md").read_text(encoding="utf-8")


def _sub_block(sec, head):
    """§7.8 圍欄之後的 ### 小節本文(到下一個 ### 或節尾)。"""
    if f"### {head}" not in sec:
        return ""
    return sec.split(f"### {head}", 1)[1].split("\n### ", 1)[0]


def t_templates_frontend_lens_supplement():
    """[前端知識與風險詞 S13] templates.md §7.7〈前端補充〉:在三條硬性配套之後、### C 之前;寫明看要改的檔決定、加問不取代、語意規格每輪改述;
    五個設計審鏡頭各一列;§1 審查要求第 5 點有指到它的填空。"""
    t = _tpl_text()
    sec = t.split("## 7.7 ", 1)[-1].split("\n## ", 1)[0]
    i_pact, i_fe, i_c = sec.find("三條硬性配套"), sec.find("### 前端補充"), sec.find("### C ")
    check("① 位置:配套之後、### C 之前", 0 <= i_pact < i_fe < i_c, f"{i_pact} {i_fe} {i_c}")
    body = sec[i_fe:i_c]
    check("② 寫明看要改的檔決定、加問不取代、語意規格", all(x in body for x in ("要改的檔", "加問、不取代", "語意規格")), body[:300])
    rows = [ln.split("|")[1].strip() for ln in body.splitlines() if ln.startswith("| ") and not ln.startswith("| 鏡頭")]
    check("③ 五個設計審鏡頭各一列", rows == ["正確性/邏輯", "邊界可執行", "整合/知識同步", "資源併發", "回滾"], str(rows))
    s1 = t.split("## 1. ", 1)[-1].split("\n## ", 1)[0]
    check("④ §1 有指到〈前端補充〉的填空", "{這份計劃要改前端檔時:" in s1 and "§7.7〈前端補充〉" in s1, "")


def t_templates_security_web_frontend_class():
    """[前端知識與風險詞 S14] §7.8〈消費專案六類〉逐字不動;其後有〈網頁前端類〉列八項,在〈工具鏈三類〉之前。"""
    t = _tpl_text()
    sec = t.split("## 7.8 ", 1)[-1].split("\n## ", 1)[0]
    six = _sub_block(sec, "消費專案六類")
    check("① 六類那節仍含原文", _SEC_SIX_CLASSES_ORIG in six, six[:200])
    web = _sub_block(sec, "網頁前端類")
    check("② 網頁前端類八項都在", all(x in web for x in ("XSS", "CSRF", "開放式轉址", "CSP", "localStorage", "postMessage", "第三方腳本", "開發代理")), web[:300])
    check("③ 順序:六類 → 網頁前端類 → 工具鏈三類", 0 <= sec.find("### 消費專案六類") < sec.find("### 網頁前端類") < sec.find("### 工具鏈三類"), "")


def t_templates_security_fill_line_mentions_web_class():
    """[前端知識與風險詞 S15] §7.8 圍欄的逐類清單填空行與圍欄後的填法說明段,都寫明含網頁前端檔時再接著貼〈網頁前端類〉;圍欄有 infra- 選配行。"""
