    check("① 網頁前端節三條都在", all(x in sec for x in ("advanceTimers: vi.advanceTimersByTime", "fetch 替身", "同輪連點", "fireEvent.click")), sec[:200])
    w = (root / "03-寫回圖譜.md").read_text(encoding="utf-8")
