        check("S34 前置:第一輪審查席", _rf_rec(v, "code-rf34", rpt, snap, "--tier", "standard", "--orchestrator", "claude", rnd="r1").returncode == 0)
        _append_outcome(root / "docs" / ".canary-log.jsonl", "code-rf34")
