    (d / "web" / "package.json").write_text('{"dependencies": {"react": "19"}}', encoding="utf-8")
    (d / "api").mkdir()
    (d / "api" / "package.json").write_text('{"dependencies": {"fastify": "5"}}', encoding="utf-8")
