def t_seclist_r2_error_cap():
    """R4:錯誤清單每個節點最多 50 筆,超出併成一筆「另有 M 筆」;畸形圍欄同理。輸出大小與時間都要有界。"""
    import json as _j, time as _t
    v = _seclist_vault()
    n = 200_000
    (v / "Systems" / "SlEmpties.md").write_text("---\ntype: system\n---\n```lumos-security-v1\n"
                                                + _j.dumps({"schema_version": 1, "controls": [{}] * n}) + "\n```\n", encoding="utf-8")
    m = 20_000
    (v / "Systems" / "SlFences.md").write_text("---\ntype: system\n---\n" + "> ```lumos-security-v1\n" * m, encoding="utf-8")
    t0 = _t.monotonic()
    r = subprocess.run([sys.executable, GRAPHCTL, "--vault", str(v), "security", "list", "--json"], capture_output=True, text=True)
    dt = _t.monotonic() - t0
    doc = _j.loads(r.stdout) if r.stdout.strip() else {}
    per = {}
    for e in doc.get("errors", []):
        per[e.get("node")] = per.get(e.get("node"), 0) + 1
    check(f"R4 每個節點最多 51 筆(50 筆加一筆彙總;實測 {per.get('Systems/SlEmpties.md')}、{per.get('Systems/SlFences.md')})",
          r.returncode == 2 and per.get("Systems/SlEmpties.md", 0) <= 51 and per.get("Systems/SlFences.md", 0) <= 51, str(per)[:300])
    summ = [e for e in doc.get("errors", []) if e.get("kind") == "errors_truncated"]
    om = {e.get("node"): e.get("omitted") for e in summ}
    check("R4 彙總寫明另有幾筆", om.get("Systems/SlFences.md") == m - 50 and (om.get("Systems/SlEmpties.md") or 0) >= n - 50, str(om))
    check(f"R4 輸出有界(實測 {len(r.stdout)} 字)與時間有界(實測 {dt:.1f}s)", len(r.stdout) < 500_000 and dt < 40, f"{len(r.stdout)} {dt:.1f}")
    rt = run(v, "security", "list")
    check("R4 文字模式同樣有界", len(rt.stdout) < 500_000, str(len(rt.stdout)))


def t_seclist_r2_inventory_dup_scale():
    """R4:inventory 的 assets/surfaces 重複檢查不是二次方:5.5 萬個 asset 在 8 秒內。"""
