    write(v, "Systems/SlDecs.md", "type: system\nstatus: done\ndecisions:\n" + decs.rstrip("\n"))
    ctrls = [_seclist_ctrl(f"D{i}", evidence_refs=[], source={"kind": "requirement", "claim": f"要求 {i}",
                                                               "decision_ref": f"Systems/SlDecs#d{i % 3000 + 1}"}) for i in range(3000)]
    for part in range(3):
        write(v, f"Systems/SlDecRefs{part}.md", "type: system\nstatus: done", body="# r\n" + _seclist_block(ctrls[part::3]))
    t0 = _t.monotonic()
