def t_seclist_r3_tag_formats():
    """T1:tags 寫成行內清單、頂格清單、項目帶行尾註解時,工具解析不到標籤:要列 tag_format_unrecognized 並把那篇算進
    unregistered_nodes(不能靜默漏列);正常的縮排清單照舊列、不報格式錯誤。"""
    v = _seclist_vault()
    write(v, "Systems/TagInline.md", "type: system\nstatus: done\ntags: [flag/security-relevant]")
    write(v, "Systems/TagTop.md", "type: system\nstatus: done\ntags:\n- flag/security-relevant")
    write(v, "Systems/TagComment.md", "type: system\nstatus: done\ntags:\n  - flag/security-relevant # sec")
    write(v, "Systems/TagOk.md", "type: system\nstatus: done\ntags:\n  - flag/security-relevant")
    write(v, "Systems/TagMention.md", "type: system\nstatus: done\nsummary: |-\n  WHY:提到 flag/security-relevant 這個字但不是標籤")
    r, doc = _seclist_json(v)
    un = (doc or {}).get("unregistered_nodes", [])
    bad = {e.get("node") for e in _seclist_err(doc, "tag_format_unrecognized")}
    for node in ("Systems/TagInline.md", "Systems/TagTop.md", "Systems/TagComment.md"):
        check(f"T1 {node}:列 tag_format_unrecognized 並算未登記", node in un and node in bad, f"{un} {bad}")
    check("T1 正常寫法照列未登記、不報格式錯誤", "Systems/TagOk.md" in un and "Systems/TagOk.md" not in bad)
    check("T1 摘要裡提到這個字不算標籤", "Systems/TagMention.md" not in un and "Systems/TagMention.md" not in bad, f"{un} {bad}")
    check("T1 格式錯誤退出 2、讀取完整性照算", r.returncode == 2 and (doc or {}).get("read_complete") is True)


def t_seclist_r3_global_error_cap():
    """T2:除了每篇 50 筆,全庫錯誤總量也有上限(2000 筆),超出併成一筆全庫 errors_truncated 帶各種類計數;
    6000 篇各 60 個空物件(36 萬筆錯誤)的 JSON 與文字輸出都要小於 1MB、各在 60 秒內。"""
    import json as _j, time as _t
    v = mkvault()
    blk = "---\ntype: system\n---\n```lumos-security-v1\n" + _j.dumps({"schema_version": 1, "controls": [{}] * 60}) + "\n```\n"
    for i in range(6000):
        (v / "Systems" / f"N{i:04d}.md").write_text(blk, encoding="utf-8")
    t0 = _t.monotonic()
    r = subprocess.run([sys.executable, GRAPHCTL, "--vault", str(v), "security", "list", "--json"], capture_output=True, text=True)
    dj = _t.monotonic() - t0
    doc = _j.loads(r.stdout) if r.stdout.strip() else {}
    errs = doc.get("errors", [])
    glob = [e for e in errs if e.get("kind") == "errors_truncated" and e.get("node") is None]
    listed = sum(1 for e in errs if e.get("kind") == "invalid_record")
    omitted = sum(e.get("omitted_by_kind", {}).get("invalid_record", 0) for e in errs if e.get("kind") == "errors_truncated")
    check(f"T2 全庫錯誤筆數有上限(實測 {len(errs)} 筆)", len(errs) <= 2001, str(len(errs)))
    check("T2 全庫彙總一筆、各種類計數加起來對得上 36 萬筆", len(glob) == 1 and listed + omitted == 360000,
          f"{len(glob)} {listed} {omitted}")
    check(f"T2 JSON 輸出小於 1MB、60 秒內(實測 {len(r.stdout)} 字、{dj:.1f}s)", r.returncode == 2 and len(r.stdout) < 1_000_000 and dj < 60)
    t1 = _t.monotonic()
    rt = run(v, "security", "list")
    dt = _t.monotonic() - t1
    check(f"T2 文字輸出小於 1MB、60 秒內(實測 {len(rt.stdout)} 字、{dt:.1f}s)", len(rt.stdout) < 1_000_000 and dt < 60)


def t_seclist_r3_duplicate_not_mapped():
    """T3:重複 ID、同一來源被兩個 ID 登記的控制項不得算入口映射;入口照列缺口,另列在 invalid_registration_control_ids。"""
    v = _seclist_vault()
    write(v, "Systems/DupA.md", "type: system\nstatus: done", body="# a\n" + _seclist_block([_seclist_ctrl("SAME-ID", surfaces=["S-refund"]),
                                                                                            _seclist_ctrl("SOLO-1", surfaces=["S-pay"])]))
    write(v, "Systems/DupB.md", "type: system\nstatus: done", body="# b\n" + _seclist_block([
        _seclist_ctrl("SAME-ID", surfaces=["S-refund"], source={"kind": "requirement", "claim": "另一句", "decision_ref": "Systems/SlPay#d1"})]))
    r, doc = _seclist_json(v)
    surf = {s.get("surface_id"): s for s in (doc or {}).get("coverage", {}).get("surfaces", [])}
    check("T3 重複 ID:入口仍 unmapped、兩條都另列", r.returncode == 2 and "S-refund" in (doc or {}).get("coverage", {}).get("unmapped", [])
          and surf.get("S-refund", {}).get("invalid_registration_control_ids") == ["SAME-ID", "SAME-ID"], str(surf.get("S-refund")))
    v2 = _seclist_vault()
    same = {"kind": "requirement", "claim": "同一句要求", "decision_ref": "Systems/SlPay#d1"}
    write(v2, "Systems/Src.md", "type: system\nstatus: done", body="# s\n" + _seclist_block([
        _seclist_ctrl("SRC-A", surfaces=["S-refund"], source=same), _seclist_ctrl("SRC-B", surfaces=["S-refund"], source=same)]))
    _r2, d2 = _seclist_json(v2)
    s2 = {s.get("surface_id"): s for s in (d2 or {}).get("coverage", {}).get("surfaces", [])}
    check("T3 同來源兩個 ID:入口仍 unmapped", "S-refund" in (d2 or {}).get("coverage", {}).get("unmapped", [])
          and sorted(s2.get("S-refund", {}).get("invalid_registration_control_ids", [])) == ["SRC-A", "SRC-B"], str(s2.get("S-refund")))
    check("T3 每條另有 registration_valid=false", _seclist_rec(d2, "SRC-A").get("registration_valid") is False
          and _seclist_rec(doc, "SOLO-1").get("registration_valid") is True)


